--
-- Name: CLAIMANT_EXECUTANT_QUERY(integer[], integer[], character varying[], integer[], integer[], integer[], integer[], character varying[]); Type: PROCEDURE; Schema: kaveri; Owner: csgadmin
--

CREATE PROCEDURE kaveri."CLAIMANT_EXECUTANT_QUERY"(IN "_Hoblicode" integer[], IN "_CurrentPropertyTypeID" integer[], IN "_CurrentNumber" character varying[], IN "_VillageCode" integer[], IN "_PINPartyTypeID" integer[], IN "_PIN2PartyTypeID" integer[], IN "_OldPropertyTypeID" integer[], IN "_OldNumber" character varying[])
    LANGUAGE plpgsql
    AS $$
begin 
SELECT PND.PropertyID,
      PIN.DocumentId,
	  A.PropertyTypeName,
      PND.SROCode,
      CurrentPropertyTypeID,
      CurrentNumber,
      OldPropertyTypeID,
      OldNumber,
      PS.Description,
      Survey_No,
      Surnoc, 
      PIN.FirstName || ' ' || PIN.MiddleName || ' ' || PIN.LastName as "Executant Name",
	  PIN.PartyTypeID,
	  PIN2.FirstName || ' ' || PIN2.MiddleName || ' ' || PIN2.LastName as "Claimant Name",
	  PIN2.PartyTypeID,
      Hissa_No, 
      PM.TotalArea, 
      PM.NorthBoundary, 
      PM.SouthBoundary, 
      PM.EastBoundary, 
      PM.WestBoundary, 
	  H.Hoblinamee,
	  V.villagenameE IndexIIVillage
	 -- areaname,
	 -- measurementEtoW,
	 -- measurementNtoS
  FROM
   kaveri.PropertyNumberDetails PND, 
   kaveri.PropertyMaster PM,
   kaveri.MAS_VAL_PropertyTypeMaster A,
   kaveri.PropertyNoTypeMaster B,
   kaveri.PropertySchedules PS , 
   kaveri.PartyInfo PIN,
   kaveri.PartyInfo PIN2,
   kaveri.hoblimaster H,
kaveri.talukmaster T,
kaveri.villagemaster V
  where PND.propertyID=PM.PropertyID
 and A.PropertyTypeID = B.PropertyTypeID 
 and PND.PropertyID=PS.PropertyID
 and B.PropertyTypeID = PND.CurrentPropertyTypeID /* Added on 21-09-2021 */
 and B.PropertyTypeID = PND.OldPropertyTypeID     /* Added on 21-09-2021 */
 and PM.DocumentID=PIN.DocumentID 
 and PM.SROCode=PIN.SROCode
 and PM.DocumentID=PIN2.DocumentID 
 and PM.SROCode=PIN2.SROCode
 and PND.SROCode=PM.SROCode
 and PND.SROCode = PS.SROCode         /* As this is the composite key which need to be mapped with the SROCode of PropertySchedules */
 and H.talukcode = T.talukcode and
PM.villagecode = V.villagecode and
T.talukcode = V.talukcode and
H.hoblicode=_Hoblicode
 and PND.CurrentPropertyTypeID=_CurrentPropertyTypeID
 and PND.CurrentNumber=_CurrentNumber 
 and PM.VillageCode=_VillageCode 
 and PIN.PartyTypeID=_PINPartyTypeID
 and PIN2.PartyTypeID=_PIN2PartyTypeID
 union
 SELECT PND.PropertyID,
      PIN.DocumentId,
	  A.PropertyTypeName,
      PND.SROCode,
      CurrentPropertyTypeID,
      CurrentNumber,
      OldPropertyTypeID,
      OldNumber,
      PS.Description,
      Survey_No,
      Surnoc, 
      PIN.FirstName || ' ' || PIN.MiddleName || ' ' || PIN.LastName as "Executant Name",
	  PIN.PartyTypeID,
	  PIN2.FirstName || ' ' || PIN2.MiddleName || ' ' || PIN2.LastName as "Claimant Name",
	  PIN2.PartyTypeID,
      Hissa_No, 
      PM.TotalArea, 
      PM.NorthBoundary, 
      PM.SouthBoundary, 
      PM.EastBoundary, 
      PM.WestBoundary, 
	  H.Hoblinamee,
	  V.villagenameE IndexIIVillage
	 -- areaname,
	 -- measurementEtoW,
	 -- measurementNtoS
  FROM
   kaveri.PropertyNumberDetails PND, 
   kaveri.PropertyMaster PM,
   kaveri.MAS_VAL_PropertyTypeMaster A,
   kaveri.PropertyNoTypeMaster B,
   kaveri.PropertySchedules PS , 
   kaveri.PartyInfo PIN,
   kaveri.PartyInfo PIN2,
   kaveri.hoblimaster H,
kaveri.talukmaster T,
kaveri.villagemaster V
  where PND.propertyID=PM.PropertyID
 and A.PropertyTypeID = B.PropertyTypeID 
 and PND.PropertyID=PS.PropertyID
 and B.PropertyTypeID = PND.CurrentPropertyTypeID /* Added on 21-09-2021 */
 and B.PropertyTypeID = PND.OldPropertyTypeID     /* Added on 21-09-2021 */
 and PM.DocumentID=PIN.DocumentID 
 and PM.SROCode=PIN.SROCode
 and PM.DocumentID=PIN2.DocumentID 
 and PM.SROCode=PIN2.SROCode
 and PND.SROCode=PM.SROCode
 and PND.SROCode = PS.SROCode         /* As this is the composite key which need to be mapped with the SROCode of PropertySchedules */
 and H.talukcode = T.talukcode and
PM.villagecode = V.villagecode and
T.talukcode = V.talukcode and
H.hoblicode = _Hoblicode
  and PM.VillageCode=_VillageCode 
 and PIN.PartyTypeID=_PINPartyTypeID
 and PIN2.PartyTypeID=_PIN2PartyTypeID
 and PND.oldPropertyTypeID=_OldPropertyTypeID 
 and PND.oldNumber=_OldNumber;
 end;
$$;


ALTER PROCEDURE kaveri."CLAIMANT_EXECUTANT_QUERY"(IN "_Hoblicode" integer[], IN "_CurrentPropertyTypeID" integer[], IN "_CurrentNumber" character varying[], IN "_VillageCode" integer[], IN "_PINPartyTypeID" integer[], IN "_PIN2PartyTypeID" integer[], IN "_OldPropertyTypeID" integer[], IN "_OldNumber" character varying[]) OWNER TO csgadmin;

--
-- Name: PARTY_INFO(integer); Type: PROCEDURE; Schema: kaveri; Owner: csgadmin
--

CREATE PROCEDURE kaveri."PARTY_INFO"(IN v_party_id integer DEFAULT 0)
    LANGUAGE plpgsql
    AS $$
begin
SELECT a.partyid,a.documentid,a.partytypeid,a.firstname,
   a.middlename,a.lastname,a.address,a.age,a.sex,a.profession,
   a.poapresentation,a.poaadmission,a.isexecutor,a.ispresenter,
   a.admissiondate,a.dateofdeath,a.photopath,a.thumbpath,
   a.section88exemption,a.primaryseller,a.partypoa,a.thumbminutiae,
   a.photo,a.thumb,a.aliasname,a.correctedname,a.restriction,
   a.restrictiontype,a.restrictiondescription,a.landcode,a.category,
   a.relationship,a.relativename,a.ownerno,a.mainownerno,a.bincom,
   a.epic,a.pan,a.ispartofrtc,a.phonenumber,a.transactextacre,
   a.transactextgunta,a.transactextfgunta,a.availableextgunta,
   a.availableextfgunta,a.totalextacre,a.totalextgunta,a.totalextfgunta,
   a.hasgpa,a.fingerid,a.fingerverificationstatusid,
   a.thumbmatchfailedreasonid,
   a.isaua,a.importedpartyparentid,a.salutationid,a.srocode,
   B.srocode,B.uid,B.email,B.uporownerno,b.isonline from
   kaveri.PARTYINFO A,
   kaveri.additionalpartyinfo B
   where a.partyid = b.partyid
   and b.partyid = V_PARTY_ID;
   END;
$$;


ALTER PROCEDURE kaveri."PARTY_INFO"(IN v_party_id integer) OWNER TO csgadmin;

