--
-- Name: SP_COURT_ORDERS(integer, integer, character varying[], integer, character varying[]); Type: PROCEDURE; Schema: kaveri; Owner: csgadmin
--

CREATE PROCEDURE kaveri."SP_COURT_ORDERS"(IN "V_SROCode" integer, IN "V_CurrentPropertyTypeID" integer, IN "V_CurrentNumber" character varying[], IN "V_OldPropertyTypeID" integer, IN "V_OldNumber" character varying[])
    LANGUAGE plpgsql
    AS $$
BEGIN
SELECT  ID
      ,BPN.SROCode SRO,BPN.PropertyID,
 BPN.injuction_or_stay_flag,
      BPN.OrderID,CurrentPropertyTypeID
      ,CurrentNumber,OldPropertyTypeID
      ,OldNumber,BPN.Description Description1
      ,Survey_No,Surnoc
      ,Hissa_No,BP.PropertyDescription
 ,BP.IsAgriculturalProperty,BP.EastBoundary EastBoundary
 ,BP.NorthBoundary NorthBoundary,BP.WestBoundary WestBoundary
 ,BP.SouthBoundary SouthBoundary,BP.Area Area
 ,BP.MeasurementUnit,MUM.DescriptionEnglish
 ,CO.OrderNumber COURT_ORDER_NUMBER,CO.Description Description
 ,CO.OrderEntryDateTime,CO.IsCancelled
 ,CO.ReasonOfCancellation
  FROM kaveri.BannedPropertyNumbers BPN inner join kaveri.BannedProperties BP
  on
  BPN.PropertyID=BP.PropertyID and BPN.SROCode=BP.SROCode
  inner join kaveri.CourtOrders CO
  on
  BP.SROCode=CO.SROCode and BP.OrderID=CO.OrderID
  inner join kaveri.MeasUnitMaster MUM
  on MUM.UnitID=BP.MeasurementUnit
  where BPN.SROCode=V_SROCode and CurrentPropertyTypeID=V_CurrentPropertyTypeID and CurrentNumber=V_CurrentNumber
   or BPN.SROCode=V_SROCode and OldPropertyTypeID=V_OldPropertyTypeID and OldNumber=V_OldNumber;
   END;
$$;


