--
-- Name: SP_PARTY_INFO(integer); Type: PROCEDURE; Schema: kaveri; Owner: csgadmin
--

CREATE PROCEDURE kaveri."SP_PARTY_INFO"(IN "V_PARTY_ID" integer DEFAULT 0)
    LANGUAGE plpgsql
    AS $_$
begin
SELECT a.partyid,a.documentid,a.partytypeid,a.firstname,
   a.middlename,a.lastname,a.address,a.age,a.sex,a.profession,
   a.poapresentation,a.poaadmission,a.isexecutor,a.ispresenter,
   a.admissiondate,a.dateofdeath,a.photopath,a.thumbpath,
   a.section88exemption,a.primaryseller,a.partypoa,a.thumbminutiae,
   a.photo,a.thumb,a.aliasname,a.correctedname,a.restriction,
   a.restrictiontype,a.restrictiondescription,a.landcode,a.category,
   a.relationship,a.relativename,a.ownerno,a.mainownerno,a.bincom,
   a.epic,a.pan,a.ispartofrtc,a.phonenumber,a.transactextacre,
   a.transactextgunta,a.transactextfgunta,a.availableextgunta,
   a.availableextfgunta,a.totalextacre,a.totalextgunta,a.totalextfgunta,
   a.hasgpa,a.fingerid,a.fingerverificationstatusid,
   a.thumbmatchfailedreasonid,
   a.isaua,a.importedpartyparentid,a.salutationid,a.srocode,
   B.srocode,B.uid,B.email,B.uporownerno,b.isonline,a.applicationnumber from
   kaveri.PARTYINFO A,
   kaveri.additionalpartyinfo B
   where a.partyid = b.partyid
   and b.partyid like '$V_PARTY_ID';
   END;
$_$;


ALTER PROCEDURE kaveri."SP_PARTY_INFO"(IN "V_PARTY_ID" integer) OWNER TO csgadmin;

--
-- Name: analyticsinsert(); Type: PROCEDURE; Schema: kaveri; Owner: postgres
--

CREATE PROCEDURE kaveri.analyticsinsert()
    LANGUAGE plpgsql
    AS $$   
declare
v_month date;
v_record record;
v_currentdate date;
v_months record;
begin

select to_timestamp('2023-01','YYYY-MM')::date into v_month;
SELECT to_timestamp(to_char(current_date ,'YYYY-MM'),'YYYY-MM')::date into v_currentdate;

raise notice 'mm %',v_month;

	if (v_month < v_currentdate)
		then
		
		for v_record in (select srocode,sronamee from kaveri.sromaster where srocode <>0 order by srocode limit 1) 
		loop

		insert into  kaveri_analytics.ec_sla_monthwise (srocode,sronamee,month_year)
		values(v_record.srocode,v_record.sronamee,v_month);

		end loop;
	SELECT to_char((v_month + interval '1 month')::date,'YYYY-MM-DD')::date into v_month;
	else 
	select null into v_month;
 end if;	
end;
$$;


ALTER PROCEDURE kaveri.analyticsinsert() OWNER TO postgres;

--
-- Name: applicationnumber(character varying, character varying, text); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.applicationnumber(_bookname character varying, _finalregistrationno character varying, _presentyear text) RETURNS TABLE(application_number character varying)
    LANGUAGE plpgsql
    AS $$
begin 
	return query
	select d.applicationnumber as Application_Number  from kaveri.documentmaster d 
	left join kaveri.booktypemaster b on d.bookid = b.bookid 
	left join kaveri.scannedfileuploaddetails s on d.documentid = s.documentid 
	where b.booknameenglish=_bookname and d.finalregistrationnumber=_finalregistrationno and extract(year from d.presentdatetime)::varchar=_presentyear;
	
end;
$$;


ALTER FUNCTION kaveri.applicationnumber(_bookname character varying, _finalregistrationno character varying, _presentyear text) OWNER TO csgadmin;

--
-- Name: dashboardinfoinsert(); Type: PROCEDURE; Schema: kaveri; Owner: csgadmin
--

CREATE PROCEDURE kaveri.dashboardinfoinsert()
    LANGUAGE plpgsql
    AS $$

begin
	
	truncate table kaveri.feedashboarddetails;
	
	insert into kaveri.feedashboarddetails(feesname,feerulecode,feesamount,lastrefreshdate)
	 select feesname, feerulecode, feesamount,current_timestamp as lastrefreshdate from kaveri.vw_fees_landingpage;
	
	truncate table kaveri.applicantdashboarddetails;
	
	insert into kaveri.applicantdashboarddetails(applicationtypeid, applicationtypename, bookid, bookname, cnt_totalapplication)
	Select applicationtypeid, applicationtypename, bookid, bookname, cnt_totalapplication from kaveri.vw_cnt_totalapplication; 
	
	 update kaveri.citizenloginloginfo set isactive=false,ismultilogin=false where isactive=true or ismultilogin=true and logindatetime::time> interval '0 hours 30 minutes';--'00:30:00'--limit 10
	
	update kaveri.departmentloginloginfo set isactive=false,ismultilogin=false where isactive=true or ismultilogin=true and logindatetime::time> interval '0 hours 30 minutes';--'00:30:00'--limit 10
	--update kaveri.citizeotpdetails set otp =0, otpcount=0 where otpcount>=5;
	update kaveri.citizeotpdetails set otpcount=0, otptime= now()::timestamp  where otpcount>=5; 
	update kaveri.citizenmaster set forgotpasswordcount = 0 where forgotpasswordcount >=1;
	
end;
$$;


ALTER PROCEDURE kaveri.dashboardinfoinsert() OWNER TO csgadmin;

--
-- Name: dashboardinfoinsert_new(); Type: PROCEDURE; Schema: kaveri; Owner: csgadmin
--

CREATE PROCEDURE kaveri.dashboardinfoinsert_new()
    LANGUAGE plpgsql
    AS $$

begin
	
	truncate table kaveri.feedashboarddetails_new;
	
	insert into kaveri.feedashboarddetails_new(feesname,srocode,feerulecode,feesamount)
	 select Distinct feesname,srocode, feerulecode, feesamount from kaveri.vw_fees_landingpage_new;
	
end;
$$;


ALTER PROCEDURE kaveri.dashboardinfoinsert_new() OWNER TO csgadmin;

--
-- Name: deps_restore_dependencies(name, name); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.deps_restore_dependencies(p_view_schema name, p_view_name name) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  v_curr record;
begin
for v_curr in 
(
  select deps_ddl_to_run 
  from kaveri.deps_saved_ddl
  where deps_view_schema = p_view_schema and deps_view_name = p_view_name
  order by deps_id desc
) loop
  execute v_curr.deps_ddl_to_run;
end loop;

delete from kaveri.deps_saved_ddl
where deps_view_schema = p_view_schema and deps_view_name = p_view_name;
end;
$$;


ALTER FUNCTION kaveri.deps_restore_dependencies(p_view_schema name, p_view_name name) OWNER TO csgadmin;

--
-- Name: deps_save_and_drop_dependencies(name, name); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.deps_save_and_drop_dependencies(p_view_schema name, p_view_name name) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  v_curr record;
begin
for v_curr in 
(
  select obj_schema, obj_name, obj_type from
  (
  with recursive recursive_deps(obj_schema, obj_name, obj_type, depth) as 
  (
    select p_view_schema, p_view_name, null::char, 0
    union
    select dep_schema::name, dep_name::name, dep_type::char, recursive_deps.depth + 1 from 
    (
      select ref_nsp.nspname ref_schema, ref_cl.relname ref_name, 
	  rwr_cl.relkind dep_type,
      rwr_nsp.nspname dep_schema,
      rwr_cl.relname dep_name
      from pg_depend dep
      join pg_class ref_cl on dep.refobjid = ref_cl.oid
      join pg_namespace ref_nsp on ref_cl.relnamespace = ref_nsp.oid
      join pg_rewrite rwr on dep.objid = rwr.oid
      join pg_class rwr_cl on rwr.ev_class = rwr_cl.oid
      join pg_namespace rwr_nsp on rwr_cl.relnamespace = rwr_nsp.oid
      where dep.deptype = 'n'
      and dep.classid = 'pg_rewrite'::regclass
    ) deps
    join recursive_deps on deps.ref_schema = recursive_deps.obj_schema and deps.ref_name = recursive_deps.obj_name
    where (deps.ref_schema != deps.dep_schema or deps.ref_name != deps.dep_name)
  )
  select obj_schema, obj_name, obj_type, depth
  from recursive_deps 
  where depth > 0
  ) t
  group by obj_schema, obj_name, obj_type
  order by max(depth) desc
) loop

  insert into kaveri.deps_saved_ddl(deps_view_schema, deps_view_name, deps_ddl_to_run)
  select distinct p_view_schema, p_view_name, indexdef
  from pg_indexes
  where schemaname = v_curr.obj_schema
  and tablename = v_curr.obj_name;

  insert into kaveri.deps_saved_ddl(deps_view_schema, deps_view_name, deps_ddl_to_run)
  select distinct tablename, rulename, definition
  from pg_rules
  where schemaname = v_curr.obj_schema
  and tablename = v_curr.obj_name;

  insert into kaveri.deps_saved_ddl(deps_view_schema, deps_view_name, deps_ddl_to_run)
  select p_view_schema, p_view_name, 'COMMENT ON ' ||
  case
  when c.relkind = 'v' then 'VIEW'
  when c.relkind = 'm' then 'MATERIALIZED VIEW'
  else ''
  end
  || ' ' || n.nspname || '.' || c.relname || ' IS ''' || replace(d.description, '''', '''''') || ''';'
  from pg_class c
  join pg_namespace n on n.oid = c.relnamespace
  join pg_description d on d.objoid = c.oid and d.objsubid = 0
  where n.nspname = v_curr.obj_schema and c.relname = v_curr.obj_name and d.description is not null;

  insert into kaveri.deps_saved_ddl(deps_view_schema, deps_view_name, deps_ddl_to_run)
  select p_view_schema, p_view_name, 'COMMENT ON COLUMN ' || n.nspname || '.' || c.relname || '.' || a.attname || ' IS ''' || replace(d.description, '''', '''''') || ''';'
  from pg_class c
  join pg_attribute a on c.oid = a.attrelid
  join pg_namespace n on n.oid = c.relnamespace
  join pg_description d on d.objoid = c.oid and d.objsubid = a.attnum
  where n.nspname = v_curr.obj_schema and c.relname = v_curr.obj_name and d.description is not null;
  
  insert into kaveri.deps_saved_ddl(deps_view_schema, deps_view_name, deps_ddl_to_run)
  select p_view_schema, p_view_name, 'GRANT ' || privilege_type || ' ON ' || table_schema || '.' || quote_ident(table_name) || ' TO ' || grantee
  from information_schema.role_table_grants
  where table_schema = v_curr.obj_schema and table_name = v_curr.obj_name;
  
  
  insert into kaveri.deps_saved_ddl(deps_view_schema, deps_view_name, deps_ddl_to_run)
	select distinct p_view_schema, p_view_name, indexdef
	FROM pg_indexes
	WHERE schemaname = v_curr.obj_schema
	AND tablename = v_curr.obj_name;


	insert into kaveri.deps_saved_ddl(deps_view_schema, deps_view_name, deps_ddl_to_run)
	select distinct tablename, rulename, definition
	FROM pg_rules
	WHERE schemaname = v_curr.obj_schema
	AND tablename = v_curr.obj_name;



  if v_curr.obj_type = 'v' then
    insert into kaveri.deps_saved_ddl(deps_view_schema, deps_view_name, deps_ddl_to_run)
    select p_view_schema, p_view_name, 'CREATE VIEW ' || v_curr.obj_schema || '.' || quote_ident(v_curr.obj_name) || ' AS ' || view_definition
    from information_schema.views
    where table_schema = v_curr.obj_schema and table_name = v_curr.obj_name;
  elsif v_curr.obj_type = 'm' then
    insert into kaveri.deps_saved_ddl(deps_view_schema, deps_view_name, deps_ddl_to_run)
    select p_view_schema, p_view_name, 'CREATE MATERIALIZED VIEW ' || v_curr.obj_schema || '.' || quote_ident(v_curr.obj_name) || ' AS ' || definition
    from pg_matviews
    where schemaname = v_curr.obj_schema and matviewname = v_curr.obj_name;
  end if;
  
  execute 'DROP ' ||
  case 
    when v_curr.obj_type = 'v' then 'VIEW'
    when v_curr.obj_type = 'm' then 'MATERIALIZED VIEW'
  end
  || ' ' || v_curr.obj_schema || '.' || quote_ident(v_curr.obj_name);
  
end loop;
end;
$$;


ALTER FUNCTION kaveri.deps_save_and_drop_dependencies(p_view_schema name, p_view_name name) OWNER TO csgadmin;

--
-- Name: estamp_summary(text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.estamp_summary(appnumber text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    result_data jsonb;
begin
select row_to_json(ss) into result_data from (
select  
(select row_to_json(ss) from (
select regarticlecode as natureofdocument from kaveri.documentmaster dm
where dm.applicationnumber = d.applicationnumber
) as ss) as documentdetails,
(select jsonb_agg(row_to_json(s2))  from (
select distinct pm.stampruleid,pm.stamparticlecode,s.districtcode,v.talukcode,v.hoblicode,v.villagecode
,pm.ismovableproperty ,pm.consideration,pm.marketvalue,pm.propertytypeid,'propertyaddress' as propertyaddress,1 as constructiontype,
(select jsonb_agg(row_to_json(s0)) from (
select ps.easttowest ,ps.northtosouth ,ps.totalarea,ps.scheduletype,ps.eastboundary,ps.westboundary,ps.northboundary,ps.southboundary,description,pss.partyid
,'1Acre 2Gunta 3FGunta' as agriarea
from kaveri.propertyschedules ps
left join kaveri.partyschedules pss on pss.scheduleid=ps.scheduleid
where ps.applicationnumber=pm.applicationnumber) s0) as propertyschedules
,(select jsonb_agg(row_to_json(s5)) from (select distinct currentpropertytypeid,currentnumber from kaveri.propertynumberdetails pnd where pnd.propertyid=pm.propertyid) s5) as propertynodetalis
from kaveri.propertymaster pm
join kaveri.villagemaster v on pm.villagecode=v.villagecode
join kaveri.sromaster s on s.srocode=v.srocode
where pm.applicationnumber=d.applicationnumber) as s2) as propertydetails,
(
select jsonb_agg(row_to_json(s9)) from (select p.relationship,p.relativename,p.pin,p.profession, p.partyid,p.linkpartyid,concat(p.firstname,' ',p.middlename,' ',p.lastname) as name,
phonenumber,age,sex,address,partytypeid,idprooftypeid,pan,
(select jsonb_agg(row_to_json(ss)) from (select masked_aadhar,aadharhash from kaveri.aadhar_authentication_log aal  where aal.partyid=p.partyid) as ss) as ekycdetails
from
kaveri.partyinfo p where applicationnumber=d.applicationnumber) s9)  as parties,
(select jsonb_agg(row_to_json(s8)) from (select w.feerulecode,w.amountrequired from kaveri.feesrequired w  where w.applicationnumber=d.applicationnumber
and amountrequired<>0 ) as s8) as feesinfo
,
(select jsonb_agg(row_to_json(ss)) from (select name,address,phoneno,age,sex from kaveri.witnessinfo w  where w.applicationnumber=d.applicationnumber) as ss) as witnessinfo
,
(select jsonb_agg(row_to_json(s66)) from (
select distinct a.deptreferencecode,a.remittername,mak.ddocode,are2.transactiontimestamp,are2.amount,(select jsonb_agg(row_to_json(ss))
 from (select dd.feerulecode,dd.totalamount
from kaveri.ams_reg_epaymenttransdetails dd where dd.applicationnumber=a.applicationnumber )as ss) as paymentbreakup
from kaveri.ams_reg_epaymenttransdetails a
join kaveri.mas_ams_khajaneddocodemapping mak on a.officeid =mak.srocode
join kaveri.ams_reg_epaymentbankackdetails are2 on a.deptreferencecode =are2.deptreferencecode
where applicationnumber=appnumber and isdelete =false) as s66) as paymentinfo
from kaveri.documentmaster d
join kaveri.registrationarticles r on d.regarticlecode =r.regarticlecode
where d.applicationnumber =appnumber
group by d.applicationnumber) as ss;
--
-- INSERT INTO kaveri.estampsummary (applicationnumber, summaryjson) VALUES (appnumber, result_data)
--    ON CONFLICT (applicationnumber) DO UPDATE SET summaryjson = result_data;
return result_data::text;
END;
$$;


ALTER FUNCTION kaveri.estamp_summary(appnumber text) OWNER TO postgres;

