update kaveri.citizenmaster set 
	--loginname=v_loginname,
--	firstname=_firstname,     --  
--	middlename=_middlename,   --  
--	lastname=_lastname,       --  
--	gender=_gender, 
	email=lower(_email),
	phone=_phone,
	--password=_password,
	--secquestion=_secquestion,
	--secanswer=_secanswer,
	--isloggedin=_isloggedin,
	--lstupdusr=_lstupdusr,
	permanentaddress=_permanentaddress,
	pin=_pin 
--	pan = _pan    --- 
	where 
	---citizenid = _citizenid; --and 
	lower(loginname) = lower(_loginname) ;
	
	end if;
	
--end if;
select loginname into v_loginname from kaveri.citizenmaster where  lower(email) = lower(_email) and phone=_phone;
if v_loginname is not null then
null;
end if;

select citizenid into v_citizenid from kaveri.citizenmaster where lower(loginname) = lower(_loginname);
return v_citizenid;

exception
WHEN unique_violation then
raise notice 'duplicate user';
   end;
$$;


