--
-- Name: f_citizen_master(text, text, text, text, integer, text, bigint, text, integer, text, character, text, timestamp without time zone, boolean, character varying, character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.f_citizen_master(_loginname text, _firstname text, _middlename text, _lastname text, _gender integer, _email text, _phone bigint, _password text, _secquestion integer, _secanswer text, _isloggedin character, _lstupdusr text, _lstupddt timestamp without time zone, _isinstitution boolean, _bankid character varying, _branchid character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$


DECLARE
id_val bigint;
x bigint;
y bigint;
_citizenid bigint;
z bigint = -1;
begin
select count(1) into x from kaveri.citizenmaster where lower(loginname) = lower(_loginname);
select count(1) into y from kaveri.citizenmaster where lower(email) = lower(_email) and phone=_phone;
if (x = 1 ) then
_citizenid=0;
return _citizenid;
elseif (y = 1 ) then
_citizenid=0;
return _citizenid;
elsif (_isinstitution is false) then
 _bankid=null;
 _branchid=null;

INSERT INTO kaveri.citizenmaster(loginname,firstname,middlename,lastname,gender,email,phone,password,secquestion,secanswer,isloggedin,
                                  lstupdusr,lstupddt,isinstitution ,bankid,branchid)
   VALUES
 	(lower(_loginname),_firstname,_middlename,_lastname,_gender,lower(_email),_phone,_password,_secquestion,_secanswer,_isloggedin,
             _lstupdusr,_lstupddt,_isinstitution,_bankid,_branchid);
    select citizenid into _citizenid from kaveri.citizenmaster where loginname = _loginname;
	return _citizenid;
	
ELSE

	INSERT INTO kaveri.citizenmaster(loginname,firstname,middlename,lastname,gender,email,phone,password,secquestion,secanswer,isloggedin,
                                  lstupdusr,lstupddt,isinstitution ,bankid,branchid)
   VALUES
 	(lower(_loginname),_firstname,_middlename,_lastname,_gender,lower(_email),_phone,_password,_secquestion,_secanswer,_isloggedin,
             _lstupdusr,_lstupddt,_isinstitution,_bankid,_branchid);
    select citizenid into _citizenid from kaveri.citizenmaster where loginname = _loginname;
	return _citizenid;
	
	end if;
exception
 WHEN unique_violation then
 raise notice 'duplicate user';
   end
$$;


