CREATE FUNCTION kaveri.f_citizen_master_chk(_citizenid bigint, _loginname text, _firstname text, _middlename text, _lastname text, _gender integer, _email text, _phone bigint, _password text, _secquestion integer, _secanswer text, _isloggedin character, _lstupdusr text, _permanentaddress character varying, _pin integer, _pan character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
id_val bigint;
x bigint;
y bigint;
z bigint = -1;
v_cnt bigint;
begin
select count(1) into x from kaveri.citizenmaster where loginname = _loginname;
select count(1) into y from kaveri.citizenmaster where email = _email and phone=_phone;
/*if (x = 1 ) then
_citizenid=0;
return _citizenid;
elseif (y = 1 ) then
_citizenid=0;
return _citizenid;
end if;*/
if (x = 0) and (y = 0) then
INSERT INTO kaveri.citizenmaster(loginname,firstname,middlename,lastname,gender,email,phone,password,secquestion,secanswer,isloggedin,
                                  lstupdusr,permanentaddress,pin,pan)
   VALUES
 	(_loginname,_firstname,_middlename,_lastname,_gender,_email,_phone,_password,_secquestion,_secanswer,_isloggedin,
             _lstupdusr,_permanentaddress,_pin,_pan);
elseif (x = 1) and (y = 1) then
update kaveri.citizenmaster set 
	--loginname=_loginname,
	firstname=_firstname,
	middlename=_middlename,
	lastname=_lastname,
	gender=_gender,
	email=_email,
	phone=_phone,
	--password=_password,
	--secquestion=_secquestion,
	--secanswer=_secanswer,
	--isloggedin=_isloggedin,
	--lstupdusr=_lstupdusr,
	permanentaddress=_permanentaddress,
	pin=_pin,
	pan=_pan where citizenid = _citizenid and loginname = _loginname;
	end if;
--end if;
select citizenid into _citizenid from kaveri.citizenmaster where loginname = _loginname;
return _citizenid;
exception
WHEN unique_violation then
raise notice 'duplicate user';
   end;
$$;


