--
-- Name: fn_accept_anywhere_reg(bigint, integer, bigint, character varying, character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_accept_anywhere_reg(_srocode bigint, _bookid integer, _propertyid bigint, _oldapplicationnumber character varying, _newapplicationnumber character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
regDetail record;
prty record;
prpty record;
v_documentid bigint;
BEGIN	
	--Insert to DocumentMaster
	for regDetail in (select * from kaveri.documentmaster d where d.applicationnumber = _oldApplicationNumber) loop
		insert into kaveri.documentmaster (
			documentid,
			srocode, 
	 		bookid,
			regarticlecode,
	 		presentdatetime, 
			executiondatetime, 
			applicationnumber, 
			verified, 
			issroapproved
		) values (
			nextval('kaveri.document_seq'),
			_srocode, 
			5,
			regDetail.regarticlecode,
			current_timestamp, 
			regDetail.executiondatetime, 
			_newApplicationNumber, 
			true, 
			'E'
		 ) returning documentid into v_documentid;
	end loop;
	
	--Insert To PartyInfo
	for prty in (select * from kaveri.partyinfo p where p.applicationnumber=_oldApplicationNumber) loop
		insert into kaveri.partyinfo(			
			srocode,
			documentid,
			partytypeid,
			firstname,
			middlename,
			lastname,
			address,
			age,
			sex,
			isexecutor,
			ispresenter,
			relationship,
			relativename,
			epic,
			pan,
			phonenumber,
			availableextacre,
			availableextgunta,
			availableextfgunta,
			bincom,
			category,
			dateofdeath,
			fingerid,
			fingerverificationstatusid,
			landcode,
			mainownerno,
			ownerno,
			partypoa,
			photopath,
			poapresentation,
			profession,
			section88exemption,
			thumbpath,
			totalextacre,
			totalextgunta,
			totalextfgunta,
			transactextacre,
			transactextgunta,
			transactextfgunta,
			salutationid,
			isorganization,
			organizationid,
			applicationnumber,
			verified,
			issroapproved,
			districtcode,
			talukcode,
			hoblicode,
			villagecode, 
			tanno,
			housenumber,
			propertyid, 
			propertynumber, 
			idprooftypeid,
			isconsentwitness,
			isprivateattendance 
		) values (
			_srocode,
			v_documentid,
			prty.partytypeid,
			prty.firstname,
			prty.middlename,
			prty.lastname,
			prty.address,
			prty.age,
			prty.sex,
			prty.isexecutor,
			prty.ispresenter,
			prty.relationship,
			prty.relativename,
			prty.epic,
			prty.pan,
			prty.phonenumber,
			prty.availableextacre,
			prty.availableextgunta,
			prty.availableextfgunta,
			prty.bincom,
			prty.category,
			prty.dateofdeath,
			prty.fingerid,
			prty.fingerverificationstatusid,
			prty.landcode,
			prty.mainownerno,
			prty.ownerno,
			prty.partypoa,
			prty.photopath,
			prty.poapresentation,
			prty.profession,
			prty.section88exemption,
			prty.thumbpath,
			prty.totalextacre,
			prty.totalextgunta,
			prty.totalextfgunta,
			prty.transactextacre,
			prty.transactextgunta,
			prty.transactextfgunta,
			prty.salutationid,
			prty.isorganization,
			prty.organizationid,
			_newApplicationNumber,
			prty.verified,
			prty.issroapproved,
			prty.districtcode,
			prty.talukcode,
			prty.hoblicode,
			prty.villagecode, 
			prty.tanno,
			prty.housenumber,
			prty.propertyid, 
			prty.propertynumber, 
			prty.idprooftypeid,
			prty.isconsentwitness,
			prty.isprivateattendance 
		);
	end loop;
	
	--Insert To PropertyMaster
	for prpty in (select * from kaveri.propertymaster p where p.applicationnumber = _oldApplicationNumber) loop 
		insert into kaveri.propertymaster (
			propertyid, 
			documentid, 
			villagecode,
			regsrocode,
			srocode,
			totalarea,
			unitid,
			northboundary,
			southboundary,
			eastboundary,
			westboundary,
			landmark,
			marketvalue,
			assessment,
			stampduty,
			consideration,
			additionalduty, 
			cessduty,
			govtduty,
			isexempted,
			exemptiondescription,
			ismovableproperty,
			applicationnumber,
			verified,
			issroapproved,
			stamparticlecode,
			stampruleid,
			regarticlecode,
			propertytypeid,
			noofscanpages,
			roadcode,
			sfdastamparticlecode,
			sfdastampruleid,
			sfdanoofscanpages,
			srostamparticlecode,
			srostampruleid,
			sronoofscanpages,
			sfdamarketvalue,
			sromarketvalue,
			ownedarea,
			sfdanatureofdocument,
			sronatureofdocument,
			transferliabilities
		) values (
			nextval('kaveri.propertymastersequence_seq'),
			v_documentid, 
			prpty.villagecode,
			_srocode,
			_srocode,
			prpty.totalarea,
			prpty.unitid,
			prpty.northboundary,
			prpty.southboundary,
			prpty.eastboundary,
			prpty.westboundary,
			prpty.landmark,
			prpty.marketvalue,
			prpty.assessment,
			prpty.stampduty,
			prpty.consideration,
			prpty.additionalduty, 
			prpty.cessduty,
			prpty.govtduty,
			prpty.isexempted,
			prpty.exemptiondescription,
			prpty.ismovableproperty,
			_newApplicationNumber,
			prpty.verified,
			prpty.issroapproved,
			prpty.stamparticlecode,
			prpty.stampruleid,
			prpty.regarticlecode,
			prpty.propertytypeid,
			prpty.noofscanpages,
			prpty.roadcode,
			prpty.sfdastamparticlecode,
			prpty.sfdastampruleid,
			prpty.sfdanoofscanpages,
			prpty.srostamparticlecode,
			prpty.srostampruleid,
			prpty.sronoofscanpages,
			prpty.sfdamarketvalue,
			prpty.sromarketvalue,
			prpty.ownedarea,
			prpty.sfdanatureofdocument,
			prpty.sronatureofdocument,
			prpty.transferliabilities
		); 
	end loop;
	
	update kaveri.anywhere_reg_log set 
		isjurisdictionsroaccepted = true, memoaccepteddatetime = current_timestamp, newapplicationnumber = _newapplicationnumber
	where propertyid=_propertyid;
	
return v_documentid;
END;
$$;


ALTER FUNCTION kaveri.fn_accept_anywhere_reg(_srocode bigint, _bookid integer, _propertyid bigint, _oldapplicationnumber character varying, _newapplicationnumber character varying) OWNER TO csgadmin;

--
-- Name: fn_accept_anywhere_reg_doc(bigint, integer, bigint, character varying, character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_accept_anywhere_reg_doc(_srocode bigint, _bookid integer, _propertyid bigint, _oldapplicationnumber character varying, _newapplicationnumber character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
regDetail record;
prty record;
prpty record;
v_documentid bigint;
BEGIN	
	--Insert to DocumentMaster
	for regDetail in (select * from kaveri.documentmaster d where d.applicationnumber = _oldApplicationNumber) loop
		insert into kaveri.documentmaster (
			documentid,
			srocode, 
	 		bookid,
			regarticlecode,
	 		presentdatetime, 
			executiondatetime, 
			applicationnumber, 
			verified, 
			issroapproved
		) values (
			nextval('kaveri.document_seq'),
			_srocode, 
			5,
			regDetail.regarticlecode,
			current_timestamp, 
			regDetail.executiondatetime, 
			_newApplicationNumber, 
			true, 
			'E'
		 ) returning documentid into v_documentid;
	end loop;
	
	
	update kaveri.anywhere_reg_log set 
		isjurisdictionsroaccepted = true, memoaccepteddatetime = current_timestamp, newapplicationnumber = _newapplicationnumber
	where propertyid=_propertyid;
	
return v_documentid;
END;
$$;


ALTER FUNCTION kaveri.fn_accept_anywhere_reg_doc(_srocode bigint, _bookid integer, _propertyid bigint, _oldapplicationnumber character varying, _newapplicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_accept_anywhere_reg_party(bigint, bigint, character varying, character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_accept_anywhere_reg_party(_srocode bigint, _documentid bigint, _oldapplicationnumber character varying, _newapplicationnumber character varying) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $$
DECLARE
regDetail record;
prty record;
prptysch record;
v_partyid bigint;
v_partyids bigint[];
v_desc text;
v_scheduleid bigint;
v_propertyid bigint;
BEGIN
--	Insert To PartyInfo
	for prty in (select * from kaveri.partyinfo p where p.applicationnumber=_oldapplicationnumber) 
	loop
		insert into kaveri.partyinfo(			
			srocode,
			documentid,
			partytypeid,
			firstname,
			middlename,
			lastname,
			address,
			age,
			sex,
			isexecutor,
			ispresenter,
			relationship,
			relativename,
			epic,
			pan,
			phonenumber,
			availableextacre,
			availableextgunta,
			availableextfgunta,
			bincom,
			category,
			dateofdeath,
			fingerid,
			fingerverificationstatusid,
			landcode,
			mainownerno,
			ownerno,
			partypoa,
			photopath,
			poapresentation,
			profession,
			section88exemption,
			thumbpath,
			totalextacre,
			totalextgunta,
			totalextfgunta,
			transactextacre,
			transactextgunta,
			transactextfgunta,
			salutationid,
			isorganization,
			organizationid,
			applicationnumber,
			verified,
			issroapproved,
			districtcode,
			talukcode,
			hoblicode,
			villagecode, 
			tanno,
			housenumber,
			propertyid, 
			propertynumber, 
			idprooftypeid,
			isconsentwitness,
			isprivateattendance 
		) values (
			_srocode,
			_documentid,
			prty.partytypeid,
			prty.firstname,
			prty.middlename,
			prty.lastname,
			prty.address,
			prty.age,
			prty.sex,
			prty.isexecutor,
			prty.ispresenter,
			prty.relationship,
			prty.relativename,
			prty.epic,
			prty.pan,
			prty.phonenumber,
			prty.availableextacre,
			prty.availableextgunta,
			prty.availableextfgunta,
			prty.bincom,
			prty.category,
			prty.dateofdeath,
			prty.fingerid,
			prty.fingerverificationstatusid,
			prty.landcode,
			prty.mainownerno,
			prty.ownerno,
			prty.partypoa,
			prty.photopath,
			prty.poapresentation,
			prty.profession,
			prty.section88exemption,
			prty.thumbpath,
			prty.totalextacre,
			prty.totalextgunta,
			prty.totalextfgunta,
			prty.transactextacre,
			prty.transactextgunta,
			prty.transactextfgunta,
			prty.salutationid,
			prty.isorganization,
			prty.organizationid,
			_newApplicationNumber,
			prty.verified,
			prty.issroapproved,
			prty.districtcode,
			prty.talukcode,
			prty.hoblicode,
			prty.villagecode, 
			prty.tanno,
			prty.housenumber,
			prty.propertyid, 
			prty.propertynumber, 
			prty.idprooftypeid,
			prty.isconsentwitness,
			prty.isprivateattendance 
		)
	returning partyid into v_partyid;

end loop;

---get the schedule allocation from the partyschedules using party.propertyid (this is the old propertyid)
---this will give us partyid(a) to whom allocation has been made
---now compare (a) with the current old partyid prty.partyid(b)
---if a=b then it should in partyschdules
---get propertyid based on newapplicationnumber 

for prptysch in (select p3.propertyid as oldpropertyid ,p.partyid as newpartyid 
				from kaveri.partyinfo p 
				join kaveri.partyinfo p2 on p.firstname=p2.firstname and p.partytypeid=p2.partytypeid and p2.applicationnumber=_oldapplicationnumber --oldappno
				join kaveri.partyschedules p3 on p2.applicationnumber =p3.applicationnumber and p2.partyid =p3.partyid 
				where p.applicationnumber =_newapplicationnumber ) 
	loop
		--select p.description into v_desc from kaveri.propertyschedules p 
		--where p.scheduleid=prptysch.scheduleid;
		
		
		select scheduleid,propertyid into v_scheduleid,v_propertyid 
		from kaveri.propertyschedules ps 
		where applicationnumber =_newapplicationnumber and ps.description in (select p.description  from kaveri.propertyschedules p 
		where p.propertyid=prptysch.oldpropertyid and p.applicationnumber=_oldapplicationnumber); 
		
	if (v_scheduleid is not null)
	then 
	INSERT INTO kaveri.partyschedules (partyid
	, scheduleid
	, propertyid
	, applicationnumber
--	, isdelete
	, inserteddatetime
	, k1k2_flag) 
	VALUES(prptysch.newpartyid,v_scheduleid,v_propertyid
	, _newapplicationnumber, current_timestamp, 2);
	end if;
end loop;
v_partyids:=array(select partyid from kaveri.partyinfo where applicationnumber=_newapplicationnumber); 


return v_partyids;
END;
$$;


ALTER FUNCTION kaveri.fn_accept_anywhere_reg_party(_srocode bigint, _documentid bigint, _oldapplicationnumber character varying, _newapplicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_accept_anywhere_reg_prpty(bigint, bigint, character varying, character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_accept_anywhere_reg_prpty(_srocode bigint, _documentid bigint, _oldapplicationnumber character varying, _newapplicationnumber character varying) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $$
DECLARE
regDetail record;
prptyno record;
prpty record;
prptysch record;
v_propertyid bigint[];
v_prop bigint;
v_mx bigint;
BEGIN	
--	Insert To PropertyMaster
	
	
	for prpty in (select * from kaveri.propertymaster p where p.applicationnumber = _oldApplicationNumber and p.srocode=_srocode) loop 
		insert into kaveri.propertymaster (
			propertyid, 
			documentid, 
			villagecode,
			regsrocode,
			srocode,
			totalarea,
			unitid,
			northboundary,
			southboundary,
			eastboundary,
			westboundary,
			landmark,
			marketvalue,
			assessment,
			stampduty,
			consideration,
			additionalduty, 
			cessduty,
			govtduty,
			isexempted,
			exemptiondescription,
			ismovableproperty,
			applicationnumber,
			verified,
			issroapproved,
			stamparticlecode,
			stampruleid,
			regarticlecode,
			propertytypeid,
			noofscanpages,
			roadcode,
			sfdastamparticlecode,
			sfdastampruleid,
			sfdanoofscanpages,
			srostamparticlecode,
			srostampruleid,
			sronoofscanpages,
			sfdamarketvalue,
			sromarketvalue,
			ownedarea,
			sfdanatureofdocument,
			sronatureofdocument,
			transferliabilities
		) values (
			nextval('kaveri.propertymastersequence_seq'),
			_documentid, 
			prpty.villagecode,
			_srocode,
			_srocode,
			prpty.totalarea,
			prpty.unitid,
			prpty.northboundary,
			prpty.southboundary,
			prpty.eastboundary,
			prpty.westboundary,
			prpty.landmark,
			prpty.marketvalue,
			prpty.assessment,
			prpty.stampduty,
			prpty.consideration,
			prpty.additionalduty, 
			prpty.cessduty,
			prpty.govtduty,
			prpty.isexempted,
			prpty.exemptiondescription,
			prpty.ismovableproperty,
			_newApplicationNumber,
			prpty.verified,
			prpty.issroapproved,
			prpty.stamparticlecode,
			prpty.stampruleid,
			prpty.regarticlecode,
			prpty.propertytypeid,
			prpty.noofscanpages,
			prpty.roadcode,
			prpty.sfdastamparticlecode,
			prpty.sfdastampruleid,
			prpty.sfdanoofscanpages,
			prpty.srostamparticlecode,
			prpty.srostampruleid,
			prpty.sronoofscanpages,
			prpty.sfdamarketvalue,
			prpty.sromarketvalue,
			prpty.ownedarea,
			prpty.sfdanatureofdocument,
			prpty.sronatureofdocument,
			prpty.transferliabilities
		)
		returning propertyid into v_prop;
		
		
	for prptysch in (select * from kaveri.propertyschedules p where propertyid=prpty.propertyid and srocode=prpty.srocode ) 
				loop 
				insert into kaveri.propertyschedules(
				scheduleid,
				propertyid,
				srocode,
				partyid,
				scheduletype,
				totalarea,
				unitid,
				description,
				partyids,
				aileniatedauthorityid,
				alieniatedorder,
				bhoomisellerpartyids,
				govtrestricorder,
				govtrestrictionid,
				landcode,
				propertygroup,
				giftshare,
				giftsharedetails,
				easttowest,
				northtosouth,
				blockchainpropertyid,
				assignedblockchainpid,
				applicationnumber,
				verified,
				issroapproved,
				eastboundary,
				westboundary,
				northboundary,
				southboundary,
				inserteddatetime,
				k1k2_flag,
				electriccompid,
				waterboardid,
				electriccomp,
				waterboard)
				values (
				nextval('kaveri.propertyschedules_scheduleid_seq'),
				v_prop,
				prptysch.srocode,
				prptysch.partyid,
				prptysch.scheduletype,
				prptysch.totalarea,
				prptysch.unitid,
				prptysch.description,
				prptysch.partyids,
				prptysch.aileniatedauthorityid,
				prptysch.alieniatedorder,
				prptysch.bhoomisellerpartyids,
				prptysch.govtrestricorder,
				prptysch.govtrestrictionid,
				prptysch.landcode,
				prptysch.propertygroup,
				prptysch.giftshare,
				prptysch.giftsharedetails,
				prptysch.easttowest,
				prptysch.northtosouth,
				prptysch.blockchainpropertyid,
				prptysch.assignedblockchainpid,
				_newapplicationnumber,
				prptysch.verified,
				prptysch.issroapproved,
				prptysch.eastboundary,
				prptysch.westboundary,
				prptysch.northboundary,
				prptysch.southboundary,
				prptysch.inserteddatetime,
				prptysch.k1k2_flag,
				prptysch.electriccompid,
				prptysch.waterboardid,
				prptysch.electriccomp,
				prptysch.waterboard);
				end loop;
			
	for prptyno in (select * from kaveri.propertynumberdetails p where propertyid=prpty.propertyid 
						and srocode=prpty.srocode ) 
			loop 
			

			insert into kaveri.propertynumberdetails(
			propertyid,
			srocode,
			currentpropertytypeid,
			currentnumber,
			oldpropertytypeid,
			oldnumber,
			description,
			survey_no,
			surnoc,
			hissa_no
			)
			values (
			v_prop,
			prptyno.srocode,
			prptyno.currentpropertytypeid,
			prptyno.currentnumber,
			prptyno.oldpropertytypeid,
			prptyno.oldnumber,
			prptyno.description,
			prptyno.survey_no,
			prptyno.surnoc,
			prptyno.hissa_no
			);
		
			
			end loop;
		
			end loop;
		v_propertyid:=array(select propertyid  from 
	kaveri.propertymaster p where p.applicationnumber = _newapplicationnumber);
	
return v_propertyid;
END;
$$;


ALTER FUNCTION kaveri.fn_accept_anywhere_reg_prpty(_srocode bigint, _documentid bigint, _oldapplicationnumber character varying, _newapplicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_add_dept_user(integer, text, integer, integer, integer, integer, text, text, text, bigint, integer, text, text, text, text, text, text, boolean, integer, text, text, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_add_dept_user(_employeetypeid integer, _officialemailid text, _officeid integer, _districtcode integer, _srocode integer, _rollid integer, _firstname text, _middlename text, _lastname text, _phoneno bigint, _identityprooftype integer, _idproofnumber text, _idproofpath text, _panno text, _leftthumbpath text, _rightthumbpath text, _photopath text, _isactive boolean, _createdby integer, _password text DEFAULT NULL::text, _kgid text DEFAULT NULL::text, _doj timestamp without time zone DEFAULT NULL::timestamp without time zone, _serviceexpdate timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS bigint
    LANGUAGE plpgsql
    AS $$




DECLARE
v_userid bigint;
v_count integer;
v_srocode integer;
v_officetypeid integer;
BEGIN 

	 select officetypeid into v_officetypeid from kaveri.mas_officemaster mo where officeid=_officeid;
	if v_officetypeid<3 then 
	select srocode into _srocode from (select srocode from kaveri.sromaster where districtcode=_districtcode limit 1)temp;
	
	end if;
	select count(*) into v_count from kaveri.departmentusers where emailid=_officialemailid or  mobileno=_phoneno;
if v_count=0 then 
   insert into kaveri.departmentusers(userid,employeetypeid,emailid,officeid,districtcode,srocode,designationid,firstname,
   middlename,lastname,mobileno,serviceflag,passwd,kgid,doj,serviceexpdate,loginname,createdby,status)
   values(nextval('kaveri.deptuserid_seq'::regclass),_employeetypeid,_officialemailid,_officeid,_districtcode,
   _srocode,_rollid,_firstname,_middlename,_lastname,
   _phoneno,_isactive,_password,_kgid,_doj,_serviceexpdate,_officialemailid,_createdby,1)
   returning userid into v_userid;
   
   insert into kaveri.departmentusers_biometrics(userid,uploadphoto,pan,status,uploadthumbleft,uploadthumbright,identityprooftype,idproofnumber,idproofpath,createdby)
   values (v_userid,_photopath,_panno,_isactive,_leftthumbpath,_rightthumbpath,_identityprooftype,_idproofnumber,_idproofpath,_createdby);
 
 end if;
   
   													

 
return v_userid;
END;

$$;


ALTER FUNCTION kaveri.fn_add_dept_user(_employeetypeid integer, _officialemailid text, _officeid integer, _districtcode integer, _srocode integer, _rollid integer, _firstname text, _middlename text, _lastname text, _phoneno bigint, _identityprooftype integer, _idproofnumber text, _idproofpath text, _panno text, _leftthumbpath text, _rightthumbpath text, _photopath text, _isactive boolean, _createdby integer, _password text, _kgid text, _doj timestamp without time zone, _serviceexpdate timestamp without time zone) OWNER TO csgadmin;

--
-- Name: fn_add_designation_role(integer, character varying, text, boolean); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_add_designation_role(_createdby integer, _designame character varying, _desigdescription text, _isactive boolean DEFAULT false) RETURNS integer
    LANGUAGE plpgsql
    AS $$

DECLARE

v_designationid integer;
v_count integer;

BEGIN 

select count(*) into v_count from  kaveri.desigmaster where designame=_desigdescription;
	
	if v_count>0 then 
	  
		v_designationid=0;
	ELSE
	
	 insert into kaveri.desigmaster(designationid,designame,desigdescription,isactive,createdby)
	 values(nextval('kaveri.designationid_seq'::regclass),_designame,_desigdescription,_isactive,_createdby)
	 returning designationid into v_designationid;
	 
	 end if;
	 
	 return v_designationid;

END;

$$;


ALTER FUNCTION kaveri.fn_add_designation_role(_createdby integer, _designame character varying, _desigdescription text, _isactive boolean) OWNER TO csgadmin;

--
-- Name: fn_add_function_usermangt(text, integer, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_add_function_usermangt(_functionname text, _moduleid integer, _submoduleid integer, _createdby integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$

DECLARE

v_functionid  integer;


BEGIN 


 insert into kaveri.functionmaster(functionname,moduleid,submoduleid,createdby)
  values (_functionname,_moduleid,_submoduleid,_createdby)
  returning functionid into v_functionid;
 
 
 

return v_functionid;

END;

$$;


ALTER FUNCTION kaveri.fn_add_function_usermangt(_functionname text, _moduleid integer, _submoduleid integer, _createdby integer) OWNER TO csgadmin;

