CREATE FUNCTION kaveri.fn_add_module(_modulename text, _createdby integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$

DECLARE

v_moduleid integer;
v_count integer;

BEGIN 


 insert into kaveri.modulemaster(modulename,createdby)
