ALTER FUNCTION kaveri.fn_add_module(_modulename text, _createdby integer) OWNER TO csgadmin;

--
-- Name: fn_add_office(integer, integer, text, text, text, text, integer, integer, text, text, integer, text, character varying, integer, boolean, integer, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_add_office(_createdby integer, _officetypeid integer, _officename text, _officenamer text, _shortname text, _shortnamer text, _districtid integer, _kavericode integer, _officeaddress text, _landline text, _pincode integer, _govt_order_filepath text, _ddocode character varying, _parentofficeid integer DEFAULT NULL::integer, _isactive boolean DEFAULT true, _anywhereregenabled integer DEFAULT 0, _bhoomicensuscode integer DEFAULT NULL::integer, _onlinebookingenabled integer DEFAULT 1) RETURNS integer
    LANGUAGE plpgsql
    AS $$

DECLARE

v_officeid integer;
v_kavericode integer;
v_count integer;
v_anywhereregenabled  boolean;

BEGIN 

	if _anywhereregenabled=0 then 
	v_anywhereregenabled=false;
	else 
	v_anywhereregenabled=true;
end if;
	
	  
select nextval('kaveri.officeid_seq'::regclass) into v_officeid;

 if  _officetypeid=1 then
    select count(*) into v_count from kaveri.mas_officemaster where officetypeid=1;
     if v_count>0 then 
     
       return 0;
     end if;
    _parentofficeid=v_officeid;
    _kavericode=1;
end if;

if  _officetypeid=2 then
	select count(*) into v_count from kaveri.mas_officemaster where officetypeid=2 and districtid=_districtid;
     if v_count>0 then 
     
       return 0;
     end if;
    _parentofficeid=1;
    _kavericode=_districtid;
end if;

if _officetypeid=3 then 

	select count(*) into v_count from kaveri.mas_officemaster where officetypeid=3 and officename =_officename;
     if v_count>0 then 
     
       return 0;
     end if;
    
    if v_count=0 then 
    INSERT INTO kaveri.sromaster
	(districtcode, sronamek, sronamee, shortnamek, shortnamee, enableanywherereg, getbhoomidata,islive)
	VALUES(_districtid,_officenamer,_officename,_shortnamer,_shortname,v_anywhereregenabled, false,true)
	returning srocode into _kavericode;
   end if;

    
 end if;




 
 insert into kaveri.mas_officemaster(createdby,officeid,officetypeid,officename,officenamer,shortname,shortnamer,districtid,parentofficeid,kavericode,bhoomicensuscode,anywhereregenabled,officeaddress,landline,onlinebookingenabled,pincode,govt_order_filepath,ddocode,isactive)
VALUES
(_createdby,v_officeid,_officetypeid,_officename,_officenamer,_shortname,_shortnamer,_districtid,_parentofficeid,_kavericode,_bhoomicensuscode,_anywhereregenabled,_officeaddress,_landline,_onlinebookingenabled,_pincode,_govt_order_filepath,_ddocode,_isactive);
 
	-- if Any sro under DR is anywhere enabled then ,All sr under that dr will be anywhere enabled	 
if(_officetypeid=3 and _anywhereregenabled=1 ) then
   update kaveri.mas_officemaster set anywhereregenabled=1 where parentofficeid=_parentofficeid;
end if;
	

return v_officeid;

END;

$$;


ALTER FUNCTION kaveri.fn_add_office(_createdby integer, _officetypeid integer, _officename text, _officenamer text, _shortname text, _shortnamer text, _districtid integer, _kavericode integer, _officeaddress text, _landline text, _pincode integer, _govt_order_filepath text, _ddocode character varying, _parentofficeid integer, _isactive boolean, _anywhereregenabled integer, _bhoomicensuscode integer, _onlinebookingenabled integer) OWNER TO csgadmin;

--
-- Name: fn_add_role_module_function_mapping(integer, integer, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_add_role_module_function_mapping(_rollid integer, _functionid integer, _moduleid integer, _submoduleid integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$

DECLARE

v_success  integer;
v_count integer;

BEGIN 

select count(*)  into  v_count  from kaveri.role_module_function_mapping   where
rollid=_rollid  and moduleid=_moduleid and submoduleid=_submoduleid and functionid=_functionid;
if(v_count=0) THEN
 insert into kaveri.role_module_function_mapping(rollid,functionid,moduleid,submoduleid)
  values (_rollid,_functionid,_moduleid,_submoduleid)
  returning 1 into v_success;
 ELSE
 v_success=0;
 end if;
 
 

return v_success;

END;

$$;


