--
-- Name: fn_add_usergroup(text, text, boolean, integer, integer[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_add_usergroup(_groupname text, _groupdesc text, _isactive boolean, _createdby integer, _rollarray integer[] DEFAULT NULL::integer[]) RETURNS integer
    LANGUAGE plpgsql
    AS $$



DECLARE
v_groupid integer;
v_count integer;
v_roleid integer;
BEGIN 
	v_groupid:=0;
       select count(*) into v_count from kaveri.deptmentusergroup where groupname=_groupname;
	   if v_count=0 then 
	   
		INSERT into kaveri.deptmentusergroup(groupname,groupdesc,isactive,createdby)
		values(_groupname,_groupdesc,_isactive,_createdby) 
		returning groupid into v_groupid;
		
		if(_rollarray is not null and array_length(_rollarray,1)>0 ) then
			for v_roleid in (select * from unnest(_rollarray)a) 
		 LOOP
		 
			insert into kaveri.group_roll_mapping(groupid,rollid) values(v_groupid,v_roleid);
		 end loop;
		 end if;
	end if;
		
		
		return v_groupid;
		 
END;

$$;


