--
-- Name: fn_all_delete_duplicate_properties_fruits(); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_all_delete_duplicate_properties_fruits() RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    rec RECORD;
    v_result jsonb := '[]'::jsonb;
    v_delete_result jsonb;
    v_doc_status boolean := FALSE;
BEGIN
    FOR rec IN
        SELECT DISTINCT a.applicationnumber
        FROM kaveri.fruits_issue_20260731 f
        JOIN kaveri.applicantapplicationdetails a
          ON f.applicationnumber = a.applicationnumber
        WHERE a.currentstatus in('CD110')
    LOOP
        -- Get delete result
        v_delete_result := kaveri.fn_delete_duplicate_properties(rec.applicationnumber);

        -- Get document summary status
         v_doc_status := kaveri.fn_insert_documentsummary(rec.applicationnumber);

        -- Add document summary status to the returned JSON
        v_result := v_result ||
        (
            SELECT jsonb_agg(
                elem || jsonb_build_object(
                    'fn_insert_documentsummary', v_doc_status
                )
            )
            FROM jsonb_array_elements(v_delete_result) AS elem
        );
    END LOOP;

    RETURN v_result;
END;
$$;


ALTER FUNCTION kaveri.fn_all_delete_duplicate_properties_fruits() OWNER TO postgres;

--
-- Name: fn_application_upd_delete(character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_application_upd_delete(_applicationnumber character varying) RETURNS character varying
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$
declare
v_cnt integer;
--y integer;
v_appno varchar;
BEGIN	 
select count(*) into v_cnt from kaveri.applicantapplicationdetails 
where applicationnumber =_applicationnumber;

if (v_cnt>0)
then
update kaveri.applicantapplicationdetails set isdeleted =true 
where applicationnumber =_applicationnumber;
v_appno:=_applicationnumber;
else 
v_appno:='application does not exists';

end if;

return v_appno;
END;
$$;


ALTER FUNCTION kaveri.fn_application_upd_delete(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_applicationlimit_check(bigint, character varying, character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_applicationlimit_check(_citizenid bigint, _aplicationnumber character varying, _tablename character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $$

declare
v_cnt int;
v_appcount int;
v_propertycount int;
v_partycount int;
v_maxparty int;
v_maxproperty int ;
v_return bool;
begin
v_maxparty:=100;
v_maxproperty:=100;

if (_citizenid in (1317,215388)) ---1317-Fruits, 215388-memo
then
return true;
end if;
select count(*) into v_cnt from kaveri.applicationlimitdetails where applicationnumber = _aplicationnumber ;

v_return:=true;
if(v_cnt>0)
		then
	select maxparty ,maxproperty into v_maxparty,v_maxproperty
		from kaveri.applicationlimitdetails where citizenid = citizenid and applicationnumber = _aplicationnumber;	
--	select  maxproperty into v_maxproperty
--		from kaveri.applicationlimitdetails where citizenid = citizenid and applicationnumber = _aplicationnumber;	

end if;
if(_tablename = 'applicantapplicationdetails')
	then 
	select Count(distinct applicationnumber) into v_appcount from kaveri.applicantapplicationdetails 
		where (inserteddatetime > now() - interval '24 hours') and citizenid = _citizenid;
		if (v_appcount>=20) then 
			v_return:=false; 
		else
			insert into kaveri.applicationlimitdetails (citizenid,applicationnumber,maxproperty,maxparty)
			values(_citizenid,_aplicationnumber,v_maxproperty,v_maxparty);
		end if;
	elsif(_tablename = 'propertymaster')
		then 
		select Count(distinct propertyid) into v_propertycount from kaveri.propertymaster where applicationnumber = _aplicationnumber;
		if(v_propertycount >= v_maxproperty) then 
			v_return:=false; 
		end if;
	elseif(_tablename = 'partyinfo')
		then 
		select Count(distinct partyid) into v_partycount from kaveri.partyinfo where applicationnumber = _aplicationnumber;
		if(v_partycount >= v_maxparty) then
		v_return:=false ;
		end if;
end if;	
return v_return;
end;
$$;


ALTER FUNCTION kaveri.fn_applicationlimit_check(_citizenid bigint, _aplicationnumber character varying, _tablename character varying) OWNER TO postgres;

