--

CREATE FUNCTION kaveri.fn_autofile_fruits_doc(_applicationnumber character varying, _docpath character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_referenceno varchar;
BEGIN  

update kaveri.fruits_data_recv_details 
	set applicationstatus = 1, isformiiisrsigned = true, formiiipath = _docpath
where applicationnumber = _applicationnumber returning referenceno into v_referenceno;
	
update kaveri.documentmaster 
	set uploaddocdeedpath = _docpath,ackdatetime=current_timestamp ,isdigitalsigned=true
where applicationnumber = _applicationnumber;

update kaveri.applicantapplicationdetails 
	set currentstatus = 'CD120'
where applicationnumber = _applicationnumber;
return v_referenceno;
END;
$$;


