--
-- Name: fn_cc_fetch_application_deo(text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_cc_fetch_application_deo(p_deoid text) RETURNS TABLE(applicationnum character varying, srocode integer, applicationtypeid integer, servicename character varying, currentstatus character varying, wrkflowstatusnamee text, isregistrationcompleted boolean, ispaymentdone boolean, applicationdate timestamp without time zone, sfdaid bigint, deocode bigint, username text)
    LANGUAGE plpgsql
    AS $$
BEGIN
   RETURN QUERY
  SELECT
    ad.applicationnumber AS applicationnum,
    ad.srocode,
    ad.applicationtypeid,
    sm.servicename,
    ad.currentstatus,
    wm.wrkflowstatusnamee,   
    false as isregistrationcompleted,   
    CASE
        WHEN fk.applicationnumber IS NOT NULL THEN true
        ELSE false
    END AS ispaymentdone,
    ad.applicationstartdate,
    ad.sfdaid,
    ad.deoid,
    '' as username
FROM
    kaveri.ApplicantApplicationdetails ad
JOIN
    kaveri.cc_applicationdetails cc ON ad.applicationnumber = cc.applicationnumber 
JOIN
    kaveri.Wrkflowmaster wm ON wm.wrkflowstatusid = ad.currentstatus
JOIN
    Kaveri.servicesmaster sm ON ad.applicationtypeid = sm.serviceid
LEFT JOIN
    (SELECT DISTINCT applicationnumber FROM kaveri.feesrequired_paymentchk) fk ON ad.applicationnumber = fk.applicationnumber
where ad.deoid::text = p_deoid and (ad.currentstatus in ('CC110')) and
 cc.isprior2003 =true;
END;
$$;


ALTER FUNCTION kaveri.fn_cc_fetch_application_deo(p_deoid text) OWNER TO postgres;

