select count(*) into y from kaveri.otherreceiptdetails where lower(ddchallannumber)=lower(_challan);
select count(*) into z from kaveri.AMS_BankInstrumentNumberDetails where instrumentnumber=_challan;
if (x > 0) or (y > 0) or (z > 0) then
