--
-- Name: fn_create_appointment_and_update_status(integer, integer, integer, text, timestamp without time zone, interval, interval, integer, text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_create_appointment_and_update_status(p_appointmenttypeid integer, p_srocode integer, p_deoperator integer, p_applicationnumber text, p_appointmentdate timestamp without time zone, p_starttime interval, p_endtime interval, p_noofapplicants integer, p_status text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result TEXT;
BEGIN

    INSERT INTO kaveri.appointmentmaster
    (
        appointmenttypeid,
        srocode,
        deoperator,
        applicationnumber,
        appointmentdate,
        starttime,
        endtime,
        noofapplicants,
        status
    )
    VALUES
    (
        p_appointmenttypeid,
        p_srocode,
        p_deoperator,
        p_applicationnumber,
        p_appointmentdate,
        p_starttime,
        p_endtime,
        p_noofapplicants,
        p_status
    );

    update kaveri.applicantapplicationdetails
	set currentstatus = 'CD108',lastupdatedby = 'AppointmentScheduler' 
	where applicationnumber = p_applicationnumber returning applicationnumber into v_result;
	
    IF v_result <> p_applicationnumber THEN
        RAISE EXCEPTION 'Application status update failed';
    END IF;

    RETURN v_result;

END;
$$;


ALTER FUNCTION kaveri.fn_create_appointment_and_update_status(p_appointmenttypeid integer, p_srocode integer, p_deoperator integer, p_applicationnumber text, p_appointmentdate timestamp without time zone, p_starttime interval, p_endtime interval, p_noofapplicants integer, p_status text) OWNER TO postgres;

