    LANGUAGE plpgsql
    AS $$

DECLARE

v_officetypeid int2;
v_count  int2;

BEGIN 
  
 select count(officetype) into v_count   from kaveri.mas_officetypes mo   where officetype=upper(_officetype);
 if v_count=0 then 
    
   INSERT INTO kaveri.mas_officetypes(
	officetype,officetypedesc, officetypedescr, shortname, shortnamer,createdby)
	VALUES (upper(_officetype), _officetypedesc,_officetypedescr,_shortname,_shortnamer,_createdby)
	returning officetypeid into v_officetypeid;
 else
    v_officetypeid=0;
 end if;
	
	
	return v_officetypeid;

END;

$$;


