CREATE FUNCTION kaveri.fn_delete_data_by_application(_applicationnumber character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$


declare 
v_cnt int;
v_docid character varying;
begin 
	
	
	delete from kaveri.partyinfo p1 where applicationnumber =_applicationnumber;

	delete from kaveri.k1pendingregistrationdata where applicationnumber =_applicationnumber;
	
	delete from kaveri.documentmaster d where applicationnumber=_applicationnumber;

	delete from kaveri.propertynumberdetails p3 where propertyid in (select propertyid from kaveri.propertymaster where applicationnumber=_applicationnumber);

	delete from kaveri.propertymaster p where applicationnumber=_applicationnumber;

	
	delete from kaveri.propertyschedules p2 where applicationnumber =_applicationnumber;

	delete from kaveri.minutebook_data m where applicationnumber =_applicationnumber;



v_docid:=_applicationnumber;

return v_docid;
	
end;
$$;


