--
-- Name: fn_delete_duplicate_properties(character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_delete_duplicate_properties(p_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_partial_count   INTEGER := 0;
    v_duplicate_count INTEGER := 0;
	v_partial_properties json := null;
	v_duplicate_properties json := null;
	v_json json;
BEGIN
 
    ------------------------------------------------------------------
    -- Temporary table for PropertyIds to delete
    ------------------------------------------------------------------
	drop table if exists tmp_delete_properties;
	
    CREATE TEMP TABLE tmp_delete_properties
    (
        propertyid BIGINT PRIMARY KEY
    ) ON COMMIT DROP;
 
    ------------------------------------------------------------------
    -- STEP 1 : Delete Partial Records
    ------------------------------------------------------------------
 
    INSERT INTO tmp_delete_properties(propertyid)
    select propertyid from kaveri.fruits_issue_20260731 where applicationnumber = p_applicationnumber
	and (partyschedules = 'NO' or propertynumberdetails = 'NO' or propertyschedules = 'NO');

	select json_agg(propertyid) into v_partial_properties from tmp_delete_properties;
 
    GET DIAGNOSTICS v_partial_count = ROW_COUNT;
 
    ------------------------------------------------------------------
    -- Delete partial records
    ------------------------------------------------------------------
 
    DELETE FROM kaveri.partyschedules WHERE propertyid IN (SELECT propertyid FROM tmp_delete_properties) and applicationnumber = p_applicationnumber;
 
    DELETE FROM kaveri.partyinfo WHERE propertyid IN (SELECT propertyid FROM tmp_delete_properties) and applicationnumber = p_applicationnumber;
 
    DELETE FROM kaveri.propertyschedules WHERE propertyid IN (SELECT propertyid FROM tmp_delete_properties) and applicationnumber = p_applicationnumber;
 
    DELETE FROM kaveri.propertymaster WHERE propertyid IN (SELECT propertyid FROM tmp_delete_properties) and applicationnumber = p_applicationnumber;
 
 
    ------------------------------------------------------------------
    -- STEP 2 : Delete True Duplicate Records
    ------------------------------------------------------------------
 
    TRUNCATE TABLE tmp_delete_properties;
 
    INSERT INTO tmp_delete_properties(propertyid)
	WITH ValidProperties AS
	(
	    SELECT DISTINCT
	           applicationnumber,
	           propertyid
	    FROM kaveri.fruits_issue_20260731
	    WHERE propertyschedules = 'YES'
	      AND partyinfo        = 'YES'
	      AND partyschedules   = 'YES'
	),
	 
	DuplicateRows AS
	(
	    SELECT
	        b.applicationnumber,
	        b.propertyid,
	 
	        MIN(b.propertyid) OVER
	        (
	            PARTITION BY
	                b.villagecode,
	                b.regsrocode,
	                b.srocode,
	                b.totalarea,
	                b.unitid,
	                b.northboundary,
	                b.southboundary,
	                b.eastboundary,
	                b.westboundary,
	                b.landmark,
	                b.marketvalue,
	                b.assessment,
	                b.sdcalculationstring,
	                b.stampduty,
	                b.transferliabilities,
	                b.consideration,
	                b.additionalduty,
	                b.cessduty,
	                b.govtduty,
	                b.isexempted,
	                b.exemptiondescription,
	                b.ismovableproperty,
	                b.sdrefund,
	                b.docmarketvalue,
	                b.valid1,
	                b.isimdemnified,
	                b.restriction,
	                b.restrictiontype,
	                b.restrictiondescription,
	                b.enumber,
	                b.claimingblocknumber,
	                b.retainingblocknumber,
	                b.valuationreport,
	                b.loanpurposeid,
	                b.applicationnumber,
	                b.verified,
	                b.issroapproved,
	                b.stamparticlecode,
	                b.stampruleid,
	                b.regarticlecode,
	                b.propertytypeid,
	                b.noofscanpages,
	                b.movablepropertydesc,
	                b.roadcode,
	                b.wardid,
	                b.pidno,
	                b.udeptid,
	                b.sfdastamparticlecode,
	                b.sfdastampruleid,
	                b.sfdanoofscanpages,
	                b.srostamparticlecode,
	                b.srostampruleid,
	                b.sronoofscanpages,
	                b.sfdamarketvalue,
	                b.sromarketvalue,
	                b.ownedarea,
	                b.sfdanatureofdocument,
	                b.sronatureofdocument,
	                b.denodescription,
	                b.estampdescription,
	                b.adjudescription,
	                b.sroconsideration,
	                b.sfdaconsideration,
	                b.referencepropertyid,
	                b.isbefore2004,
	                b.sfdastampduty,
	                b.srostampduty,
	                b.sfdacessduty,
	                b.srocessduty,
	                b.surcharge,
	                b.sfdasurcharge,
	                b.srosurcharge,
	                b.valuationtypeid,
	                b.zoneid,
	                b.subpropertytypeid,
	                b.k1k2_flag,
	                b.sroroadcode,
	                b.sfdaroadcode,
	                b.upormutationfee,
	                b.uporprcardfee,
	                b.uportotalarea,
	                b.uporpartarea,
	                b.isuporpartextent
	        ) AS keep_propertyid,
	 
	        ROW_NUMBER() OVER
	        (
	            PARTITION BY
	                b.villagecode,
	                b.regsrocode,
	                b.srocode,
	                b.totalarea,
	                b.unitid,
	                b.northboundary,
	                b.southboundary,
	                b.eastboundary,
	                b.westboundary,
	                b.landmark,
	                b.marketvalue,
	                b.assessment,
	                b.sdcalculationstring,
	                b.stampduty,
	                b.transferliabilities,
	                b.consideration,
	                b.additionalduty,
	                b.cessduty,
	                b.govtduty,
	                b.isexempted,
	                b.exemptiondescription,
	                b.ismovableproperty,
	                b.sdrefund,
	                b.docmarketvalue,
	                b.valid1,
	                b.isimdemnified,
	                b.restriction,
	                b.restrictiontype,
	                b.restrictiondescription,
	                b.enumber,
	                b.claimingblocknumber,
	                b.retainingblocknumber,
	                b.valuationreport,
	                b.loanpurposeid,
	                b.applicationnumber,
	                b.verified,
	                b.issroapproved,
	                b.stamparticlecode,
	                b.stampruleid,
	                b.regarticlecode,
	                b.propertytypeid,
	                b.noofscanpages,
	                b.movablepropertydesc,
	                b.roadcode,
	                b.wardid,
	                b.pidno,
	                b.udeptid,
	                b.sfdastamparticlecode,
	                b.sfdastampruleid,
	                b.sfdanoofscanpages,
	                b.srostamparticlecode,
	                b.srostampruleid,
	                b.sronoofscanpages,
	                b.sfdamarketvalue,
	                b.sromarketvalue,
	                b.ownedarea,
	                b.sfdanatureofdocument,
	                b.sronatureofdocument,
	                b.denodescription,
	                b.estampdescription,
	                b.adjudescription,
	                b.sroconsideration,
	                b.sfdaconsideration,
	                b.referencepropertyid,
	                b.isbefore2004,
	                b.sfdastampduty,
	                b.srostampduty,
	                b.sfdacessduty,
	                b.srocessduty,
	                b.surcharge,
	                b.sfdasurcharge,
	                b.srosurcharge,
	                b.valuationtypeid,
	                b.zoneid,
	                b.subpropertytypeid,
	                b.k1k2_flag,
	                b.sroroadcode,
	                b.sfdaroadcode,
	                b.upormutationfee,
	                b.uporprcardfee,
	                b.uportotalarea,
	                b.uporpartarea,
	                b.isuporpartextent
	            ORDER BY b.propertyid
	        ) AS rn
	 
	    FROM kaveri.propertymaster b
	    INNER JOIN ValidProperties vp
	        ON vp.applicationnumber = b.applicationnumber
	       AND vp.propertyid        = b.propertyid
	 
	    -- Optional filter
	    WHERE b.applicationnumber = p_applicationnumber
	)
	 
	SELECT
--	    applicationnumber,
--	    keep_propertyid,
	    propertyid AS delete_propertyid
--	    rn
	FROM DuplicateRows
	WHERE rn > 1
	ORDER BY
	    applicationnumber,
	    keep_propertyid,
	    delete_propertyid;
	
	GET DIAGNOSTICS v_duplicate_count = ROW_COUNT;

	select json_agg(propertyid) into v_duplicate_properties from tmp_delete_properties;
 
 
    ------------------------------------------------------------------
    -- Delete duplicate records
    ------------------------------------------------------------------
 
    DELETE FROM kaveri.partyschedules WHERE propertyid IN (SELECT propertyid FROM tmp_delete_properties) and applicationnumber = p_applicationnumber;
 
    DELETE FROM kaveri.partyinfo WHERE propertyid IN (SELECT propertyid FROM tmp_delete_properties) and applicationnumber = p_applicationnumber;
 
    DELETE FROM kaveri.propertyschedules WHERE propertyid IN (SELECT propertyid FROM tmp_delete_properties) and applicationnumber = p_applicationnumber;
 
    DELETE FROM kaveri.propertymaster WHERE propertyid IN (SELECT propertyid FROM tmp_delete_properties) and applicationnumber = p_applicationnumber;
 
 
    ------------------------------------------------------------------
    select json_agg(ss) into v_json from (SELECT
		p_applicationnumber,
		v_partial_properties,
		v_duplicate_properties)ss;
	
    RETURN v_json;
 
END;
$$;


ALTER FUNCTION kaveri.fn_delete_duplicate_properties(p_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_delete_duplicate_properties_check(character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_delete_duplicate_properties_check(p_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_partial_count   INTEGER := 0;
    v_duplicate_count INTEGER := 0;
	v_partial_properties json := null;
	v_duplicate_properties json := null;
	v_json json;
BEGIN
 
    ------------------------------------------------------------------
    -- Temporary table for PropertyIds to delete
    ------------------------------------------------------------------
	DROP TABLE IF EXISTS tmp_delete_properties;
	
    CREATE TEMP TABLE tmp_delete_properties
    (
        propertyid BIGINT PRIMARY KEY
    ) ON COMMIT DROP;
 
    ------------------------------------------------------------------
    -- STEP 1 : Delete Partial Records
    ------------------------------------------------------------------
 
    INSERT INTO tmp_delete_properties(propertyid)
    select propertyid from kaveri.fruits_issue_20260728 where applicationnumber = p_applicationnumber
	and (partyschedules = 'NO' or propertynumberdetails = 'NO' or propertyschedules = 'NO');

	select json_agg(propertyid) into v_partial_properties from tmp_delete_properties;
 
    GET DIAGNOSTICS v_partial_count = ROW_COUNT;
 
    ------------------------------------------------------------------
    -- Delete partial records
    ------------------------------------------------------------------
 
    -- DELETE FROM kaveri.partyschedules
    -- WHERE propertyid IN (SELECT propertyid FROM tmp_delete_properties) and applicationnumber = p_applicationnumber;
 
    -- DELETE FROM kaveri.partyinfo
    -- WHERE propertyid IN (SELECT propertyid FROM tmp_delete_properties) and applicationnumber = p_applicationnumber;
 
    -- DELETE FROM kaveri.propertyschedules
    -- WHERE propertyid IN (SELECT propertyid FROM tmp_delete_properties) and applicationnumber = p_applicationnumber;
 
    -- DELETE FROM kaveri.propertymaster
    -- WHERE propertyid IN (SELECT propertyid FROM tmp_delete_properties) and applicationnumber = p_applicationnumber;
 
 
    ------------------------------------------------------------------
    -- STEP 2 : Delete True Duplicate Records
    ------------------------------------------------------------------
 
    TRUNCATE TABLE tmp_delete_properties;
 
    INSERT INTO tmp_delete_properties(propertyid)
	WITH ValidProperties AS
	(
	    SELECT DISTINCT
	           applicationnumber,
	           propertyid
	    FROM kaveri.fruits_issue_20260728
	    WHERE propertyschedules = 'YES'
	      AND partyinfo        = 'YES'
	      AND partyschedules   = 'YES'
	),
	 
	DuplicateRows AS
	(
	    SELECT
	        b.applicationnumber,
	        b.propertyid,
	 
	        MIN(b.propertyid) OVER
	        (
	            PARTITION BY
	                b.villagecode,
	                b.regsrocode,
	                b.srocode,
	                b.totalarea,
	                b.unitid,
	                b.northboundary,
	                b.southboundary,
	                b.eastboundary,
	                b.westboundary,
	                b.landmark,
	                b.marketvalue,
	                b.assessment,
	                b.sdcalculationstring,
	                b.stampduty,
	                b.transferliabilities,
	                b.consideration,
	                b.additionalduty,
	                b.cessduty,
	                b.govtduty,
	                b.isexempted,
	                b.exemptiondescription,
	                b.ismovableproperty,
	                b.sdrefund,
	                b.docmarketvalue,
	                b.valid1,
	                b.isimdemnified,
	                b.restriction,
	                b.restrictiontype,
	                b.restrictiondescription,
	                b.enumber,
	                b.claimingblocknumber,
	                b.retainingblocknumber,
	                b.valuationreport,
	                b.loanpurposeid,
	                b.applicationnumber,
	                b.verified,
	                b.issroapproved,
	                b.stamparticlecode,
	                b.stampruleid,
	                b.regarticlecode,
	                b.propertytypeid,
	                b.noofscanpages,
	                b.movablepropertydesc,
	                b.roadcode,
	                b.wardid,
	                b.pidno,
	                b.udeptid,
	                b.sfdastamparticlecode,
	                b.sfdastampruleid,
	                b.sfdanoofscanpages,
	                b.srostamparticlecode,
	                b.srostampruleid,
	                b.sronoofscanpages,
	                b.sfdamarketvalue,
	                b.sromarketvalue,
	                b.ownedarea,
	                b.sfdanatureofdocument,
	                b.sronatureofdocument,
	                b.denodescription,
	                b.estampdescription,
	                b.adjudescription,
	                b.sroconsideration,
	                b.sfdaconsideration,
	                b.referencepropertyid,
	                b.isbefore2004,
	                b.sfdastampduty,
	                b.srostampduty,
	                b.sfdacessduty,
	                b.srocessduty,
	                b.surcharge,
	                b.sfdasurcharge,
	                b.srosurcharge,
	                b.valuationtypeid,
	                b.zoneid,
	                b.subpropertytypeid,
	                b.k1k2_flag,
	                b.sroroadcode,
	                b.sfdaroadcode,
	                b.upormutationfee,
	                b.uporprcardfee,
	                b.uportotalarea,
	                b.uporpartarea,
	                b.isuporpartextent
	        ) AS keep_propertyid,
	 
	        ROW_NUMBER() OVER
	        (
	            PARTITION BY
	                b.villagecode,
	                b.regsrocode,
	                b.srocode,
	                b.totalarea,
	                b.unitid,
	                b.northboundary,
	                b.southboundary,
	                b.eastboundary,
	                b.westboundary,
	                b.landmark,
	                b.marketvalue,
	                b.assessment,
	                b.sdcalculationstring,
	                b.stampduty,
	                b.transferliabilities,
	                b.consideration,
	                b.additionalduty,
	                b.cessduty,
	                b.govtduty,
	                b.isexempted,
	                b.exemptiondescription,
	                b.ismovableproperty,
	                b.sdrefund,
	                b.docmarketvalue,
	                b.valid1,
	                b.isimdemnified,
	                b.restriction,
	                b.restrictiontype,
	                b.restrictiondescription,
	                b.enumber,
	                b.claimingblocknumber,
	                b.retainingblocknumber,
	                b.valuationreport,
	                b.loanpurposeid,
	                b.applicationnumber,
	                b.verified,
	                b.issroapproved,
	                b.stamparticlecode,
	                b.stampruleid,
	                b.regarticlecode,
	                b.propertytypeid,
	                b.noofscanpages,
	                b.movablepropertydesc,
	                b.roadcode,
	                b.wardid,
	                b.pidno,
	                b.udeptid,
	                b.sfdastamparticlecode,
	                b.sfdastampruleid,
	                b.sfdanoofscanpages,
	                b.srostamparticlecode,
	                b.srostampruleid,
	                b.sronoofscanpages,
	                b.sfdamarketvalue,
	                b.sromarketvalue,
	                b.ownedarea,
	                b.sfdanatureofdocument,
	                b.sronatureofdocument,
	                b.denodescription,
	                b.estampdescription,
	                b.adjudescription,
	                b.sroconsideration,
	                b.sfdaconsideration,
	                b.referencepropertyid,
	                b.isbefore2004,
	                b.sfdastampduty,
	                b.srostampduty,
	                b.sfdacessduty,
	                b.srocessduty,
	                b.surcharge,
	                b.sfdasurcharge,
	                b.srosurcharge,
	                b.valuationtypeid,
	                b.zoneid,
	                b.subpropertytypeid,
	                b.k1k2_flag,
	                b.sroroadcode,
	                b.sfdaroadcode,
	                b.upormutationfee,
	                b.uporprcardfee,
	                b.uportotalarea,
	                b.uporpartarea,
	                b.isuporpartextent
	            ORDER BY b.propertyid
	        ) AS rn
	 
	    FROM kaveri.propertymaster b
	    INNER JOIN ValidProperties vp
	        ON vp.applicationnumber = b.applicationnumber
	       AND vp.propertyid        = b.propertyid
	 
	    -- Optional filter
	    WHERE b.applicationnumber = p_applicationnumber
	)
	 
	SELECT
--	    applicationnumber,
--	    keep_propertyid,
	    propertyid AS delete_propertyid
--	    rn
	FROM DuplicateRows
	WHERE rn > 1
	ORDER BY
	    applicationnumber,
	    keep_propertyid,
	    delete_propertyid;
	
	GET DIAGNOSTICS v_duplicate_count = ROW_COUNT;

	select json_agg(propertyid) into v_duplicate_properties from tmp_delete_properties;
 
 
    ------------------------------------------------------------------
    -- Delete duplicate records
    ------------------------------------------------------------------
 
    -- DELETE FROM kaveri.partyschedules
    -- WHERE propertyid IN (SELECT propertyid FROM tmp_delete_properties) and applicationnumber = p_applicationnumber;
 
    -- DELETE FROM kaveri.partyinfo
    -- WHERE propertyid IN (SELECT propertyid FROM tmp_delete_properties) and applicationnumber = p_applicationnumber;
 
    -- DELETE FROM kaveri.propertyschedules
    -- WHERE propertyid IN (SELECT propertyid FROM tmp_delete_properties) and applicationnumber = p_applicationnumber;
 
    -- DELETE FROM kaveri.propertymaster
    -- WHERE propertyid IN (SELECT propertyid FROM tmp_delete_properties) and applicationnumber = p_applicationnumber;
 
 
    ------------------------------------------------------------------
	select json_agg(ss) into v_json from (SELECT
		p_applicationnumber,
		v_partial_properties,
		v_duplicate_properties)ss;
	
    RETURN v_json;
	
 
END;
$$;


ALTER FUNCTION kaveri.fn_delete_duplicate_properties_check(p_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_delete_ecpropertysearchkeyvalues(kaveri.type_ecpropertysearchkeyvalues_request[]); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_delete_ecpropertysearchkeyvalues(kaveri.type_ecpropertysearchkeyvalues_request[] DEFAULT NULL::kaveri.type_ecpropertysearchkeyvalues_request[]) RETURNS bigint
    LANGUAGE plpgsql
    AS $_$

declare
v_propertyid bigint;

begin

delete from kaveri.ecpropertysearchkeyvalues e  where (e.propertyid,e.villagecode,e.documentid,e.currentnumber,e.currentpropertytypeid) in 
(select ss._propertyid,ss._villagecode,ss._documentid,ss._currentnumber,ss._currentpropertytypeid from unnest($1) ss);

select distinct a._propertyid into v_propertyid  from unnest($1) a;
return v_propertyid; 
end;
$_$;


