--
-- Name: fn_delete_officetype(integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_delete_officetype(_officetypeid integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$




DECLARE
v_success integer;
v_count integer;
BEGIN 
	v_success=0;
		select count(*) into v_count from kaveri.departmentusers where officeid in 
		(select officeid  from kaveri.mas_officemaster mo where mo.officetypeid=_officetypeid);
		if v_count=0 then
		
		 select count(*)  into v_count from kaveri.mas_officemaster mo where mo.officetypeid=_officetypeid;
		
		 if v_count=0 then 
		
		  delete from kaveri.mas_officetypes mo  where officetypeid=_officetypeid;
		  v_success=1;
		ELSE
		
		  v_success=0;
		end if;
	   end if;
	    
		
		return v_success;

END;

$$;


ALTER FUNCTION kaveri.fn_delete_officetype(_officetypeid integer) OWNER TO csgadmin;

