--

CREATE FUNCTION kaveri.fn_fetch_1d_arrayofarray(anyarray) RETURNS SETOF anyarray
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE
	   cit_id TEXT;
BEGIN
     FOR cit_id IN ( select unnest($1) )
	  LOOP
        RETURN NEXT ARRAY[cit_id];
    END LOOP;
    RETURN;	   
END;
$_$;


