--
-- Name: fn_fetch_address_taluk_lgd(bigint); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_address_taluk_lgd(_talukcode bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$
declare 
v_address text;
BEGIN		

select t.taluknamee||', '||d.districtnamee||', '|| s.statenamee
into v_address 
from
kaveri.lgd_statemaster s
inner join kaveri.lgd_districtmaster d on (s.statecode = d.lgdstatecode)  
INNER JOIN kaveri.lgd_talukmaster T ON (t.lgd_districtcode = d.districtcode) 
where t.talukcode =  _talukcode;

return v_address;

END;
$$;


ALTER FUNCTION kaveri.fn_fetch_address_taluk_lgd(_talukcode bigint) OWNER TO csgadmin;

--
-- Name: fn_fetch_address_village(bigint); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_address_village(_villagecode bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$
declare 
v_address text;
BEGIN		

select v.taluknamee||', '||T.districtnamee||', '||d.statenamee
into v_address from kaveri.lgd_talukmaster v 
INNER JOIN kaveri.lgd_districtmaster T ON (v.lgd_districtcode = t.districtcode)
inner join kaveri.lgd_statemaster d on (t.lgdstatecode = d.statecode) 
where v.talukcode = _villagecode;

return v_address;

END;
$$;


