--
-- Name: fn_fetch_allocate_applications_sro(integer, text); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_allocate_applications_sro(p_srocode integer, p_status text) RETURNS TABLE(applicationnum character varying, applicationdate date, srocode integer, applicationtypeid integer, servicename character varying, currentstatus character varying, wrkflowstatusnamee text, deoid integer, deoname text)
    LANGUAGE plpgsql
    AS $$
BEGIN
IF(p_status = 'CD108') THEN
   RETURN QUERY
  select ad.applicationnumber applicationnum,aa.crtdt::date as applicationdate,ad.srocode,ad.applicationtypeid,sm.servicename,
ad.currentstatus,wm.wrkflowstatusnamee,0,null
from kaveri.ApplicantApplicationdetails ad
inner join (select au.applicationnumber,crtdt,au.wrkflowstatusid from Kaveri.ApplicationAudit au
	where au.wrkflowstatusid = p_status and activityorder = (select max(activityorder) 
				from Kaveri.ApplicationAudit aau 
						   where aau.applicationnumber = au.applicationnumber 
						   and aau.wrkflowstatusid = au.wrkflowstatusid)) aa 
						   on aa.applicationnumber= ad.applicationnumber
left outer join kaveri.Wrkflowmaster wm on wm.wrkflowstatusid = ad.currentstatus 
left join Kaveri.servicesmaster sm on ad.applicationtypeid = sm.serviceid 
where ad.srocode = p_srocode and 
ad.currentstatus in (p_status)
order by aa.crtdt;
ELSIF(P_STATUS = 'CD109') then
RETURN QUERY
  select ad.applicationnumber applicationnum,aa.crtdt::date as applicationdate,ad.srocode,ad.applicationtypeid,sm.servicename,
ad.currentstatus,wm.wrkflowstatusnamee,du.userid as deoid, du.firstname||' '||du.lastname
from kaveri.ApplicantApplicationdetails ad
inner join (select au.applicationnumber,crtdt,au.wrkflowstatusid from Kaveri.ApplicationAudit au
	where au.wrkflowstatusid = p_status and activityorder = (select max(activityorder) 
				from Kaveri.ApplicationAudit aau 
						   where aau.applicationnumber = au.applicationnumber 
						   and aau.wrkflowstatusid = au.wrkflowstatusid)) aa 
						   on aa.applicationnumber= ad.applicationnumber
						   inner join kaveri.departmentusers du 
						   on (ad.assignedto=du.userid::text)
						   inner join kaveri.desigmaster dm on (dm.designationid =4 and dm.designationid=du.designationid)
left outer join kaveri.Wrkflowmaster wm on wm.wrkflowstatusid = ad.currentstatus 
left join Kaveri.servicesmaster sm on ad.applicationtypeid = sm.serviceid 
where ad.srocode = p_srocode and 
ad.currentstatus in (p_status) AND ad.deoid is not null
order by aa.crtdt;
END IF;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_allocate_applications_sro(p_srocode integer, p_status text) OWNER TO csgadmin;

--
-- Name: fn_fetch_allocate_applications_sro_marriage(integer, text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_allocate_applications_sro_marriage(p_srocode integer, p_status text) RETURNS TABLE(applicationnum character varying, applicationdate date, srocode integer, applicationtypeid integer, servicename character varying, currentstatus character varying, wrkflowstatusnamee text, deoid integer, deoname text)
    LANGUAGE plpgsql
    AS $$

BEGIN
IF(p_status = 'MR106') THEN
   RETURN QUERY
  select ad.applicationnumber applicationnum,aa.crtdt::date as applicationdate,ad.srocode,ad.applicationtypeid,sm.servicename,
ad.currentstatus,wm.wrkflowstatusnamee,0,null
from kaveri.ApplicantApplicationdetails ad
inner join (select au.applicationnumber,crtdt,au.wrkflowstatusid from Kaveri.ApplicationAudit au
	where au.wrkflowstatusid = p_status and activityorder = (select max(activityorder) 
				from Kaveri.ApplicationAudit aau 
						   where aau.applicationnumber = au.applicationnumber 
						   and aau.wrkflowstatusid = au.wrkflowstatusid)) aa 
						   on aa.applicationnumber= ad.applicationnumber
left outer join kaveri.Wrkflowmaster wm on wm.wrkflowstatusid = ad.currentstatus 
left join Kaveri.servicesmaster sm on ad.applicationtypeid = sm.serviceid 
where ad.srocode = p_srocode and 
ad.currentstatus in (p_status)
order by aa.crtdt;
ELSIF(P_STATUS = 'MR115') then
RETURN QUERY
  select ad.applicationnumber applicationnum,aa.crtdt::date as applicationdate,ad.srocode,ad.applicationtypeid,sm.servicename,
ad.currentstatus,wm.wrkflowstatusnamee,du.userid as deoid, du.firstname||' '||du.lastname
from kaveri.ApplicantApplicationdetails ad
inner join (select au.applicationnumber,crtdt,au.wrkflowstatusid from Kaveri.ApplicationAudit au
	where au.wrkflowstatusid = p_status and activityorder = (select max(activityorder) 
				from Kaveri.ApplicationAudit aau 
						   where aau.applicationnumber = au.applicationnumber 
						   and aau.wrkflowstatusid = au.wrkflowstatusid)) aa 
						   on aa.applicationnumber= ad.applicationnumber
						   inner join kaveri.departmentusers du 
						   on (ad.assignedto=du.userid::text)
						   inner join kaveri.desigmaster dm on (dm.designationid =4 and dm.designationid=du.designationid)
left outer join kaveri.Wrkflowmaster wm on wm.wrkflowstatusid = ad.currentstatus 
left join Kaveri.servicesmaster sm on ad.applicationtypeid = sm.serviceid 
where ad.srocode = p_srocode and 
ad.currentstatus in (p_status) AND ad.deoid is not null
order by aa.crtdt;
END IF;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_allocate_applications_sro_marriage(p_srocode integer, p_status text) OWNER TO postgres;

--
-- Name: fn_fetch_anywhere_reg(bigint, character varying, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_anywhere_reg(_srocode bigint, _sr character varying, pagenumber integer, pagesize integer) RETURNS TABLE(finalregistrationnumber character varying, applicationnumber character varying, regsrocode integer, regsroname character varying, srocode integer, sroname character varying, propertyid bigint, propertydescription character varying, northboundary character varying, eastboundary character varying, westboundary character varying, southboundary character varying, executiondatetime date, presentdatetime date, registrationdatetime date, pagecount integer, executants text, claimants text, docpath text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
v_srapplicationnumber character varying[];
v_rspplicationnumber character varying[];
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
if(_sr = 'rsr') then

select array_agg(arl.applicationnumber) into v_rspplicationnumber from kaveri.anywhere_reg_log arl
	where arl.regsrocode=_srocode and arl.ismemosent = false ;

	return query 
	with cte as (select distinct 
		dm.finalregistrationnumber, 
		dm.applicationnumber, 
		pm.regsrocode::integer, 
--		(select sronamee from kaveri.sromaster s where s.srocode=arl.regsrocode),
		rs.sronamee,
		pm.srocode::integer,
--		(select sronamee from kaveri.sromaster s where s.srocode=arl.srocode),
		js.sronamee,
		pm.propertyid,
		ps.description,
		pm.northboundary,
		pm.eastboundary,
		pm.westboundary,
		pm.southboundary,
		dm.executiondatetime::date,
		dm.presentdatetime::date,
		dm.registrationdatetime::date,
		dm.pagecount,
		prt_ex.executants,
		prt_cl.claimants,
		dm.uploaddocdeedpath
	from kaveri.anywhere_reg_log arl
	 join kaveri.documentmaster dm on arl.applicationnumber = dm.applicationnumber
	 join kaveri.propertymaster pm on arl.propertyid = pm.propertyid  
	 join kaveri.propertyschedules ps on pm.propertyid = ps.propertyid 
	 join kaveri.sromaster js on arl.srocode =js.srocode 
	 join kaveri.sromaster rs on arl.regsrocode=rs.srocode
	 JOIN ( SELECT vw.applicationnumber,
			string_agg((coalesce (vw.firstname,'')::text||' '::text||coalesce (vw.middlename,'')::text||' '::text||coalesce (vw.lastname,'')::text|| ' '::text) || coalesce (vw.address,'')::text ,', '::text) as claimants
			FROM kaveri.partyinfo vw
			WHERE  vw.applicationnumber = any(v_rspplicationnumber) and vw.srocode=_srocode and vw.partytypeid = 1 
			GROUP BY vw.applicationnumber) prt_cl ON prt_cl.applicationnumber::text = dm.applicationnumber::text
	 JOIN ( SELECT vw.applicationnumber,
			string_agg((coalesce (vw.firstname,'')::text||' '::text||coalesce (vw.middlename,'')::text||' '::text||coalesce (vw.lastname,'')::text|| ' '::text) || coalesce (vw.address,'')::text ,', '::text) as executants
			FROM kaveri.partyinfo vw
			WHERE  vw.applicationnumber = any(v_rspplicationnumber) and vw.srocode=_srocode and vw.partytypeid = 2 
			GROUP BY vw.applicationnumber) prt_ex ON prt_ex.applicationnumber::text = dm.applicationnumber::text
	where arl.regsrocode=_srocode and arl.ismemosent = false and pm.srocode<>0),cte_count as (select count(*) as total_rows from cte)
   select * from cte
   right join (select total_rows from cte_count) total_row on true
   where total_row.total_rows<>0
	OFFSET PageOffset
	FETCH NEXT pagesize ROWS ONLY;
elsif (_sr = 'jsr') then

select array_agg(arl.applicationnumber) into v_srapplicationnumber  from kaveri.anywhere_reg_log arl
	 	 where arl.srocode=_srocode and arl.isjurisdictionsroaccepted = false ;

return query 
	with cte as (select distinct 
		dm.finalregistrationnumber, 
		dm.applicationnumber, 
		pm.regsrocode::integer,
--		(select sronamee from kaveri.sromaster s where s.srocode=arl.regsrocode),
		rs.sronamee,
		pm.srocode::integer,
--		(select sronamee from kaveri.sromaster s where s.srocode=arl.srocode),
		js.sronamee,
		pm.propertyid,
		ps.description,
		pm.northboundary,
		pm.eastboundary,
		pm.westboundary,
		pm.southboundary,
		dm.executiondatetime::date,
		dm.presentdatetime::date,
		dm.registrationdatetime::date,
		dm.pagecount,
		prt_ex.executants,
		prt_cl.claimants,
		dm.uploaddocdeedpath
	from kaveri.anywhere_reg_log arl
	 join kaveri.documentmaster dm on arl.applicationnumber = dm.applicationnumber
	 join kaveri.propertymaster pm on arl.propertyid = pm.propertyid  
	 join kaveri.propertyschedules ps on pm.propertyid = ps.propertyid 
	join kaveri.sromaster js on arl.srocode =js.srocode 
	 join kaveri.sromaster rs on arl.regsrocode=rs.srocode
	 JOIN ( SELECT vw.applicationnumber,
			string_agg((coalesce (vw.firstname,'')::text||' '::text||coalesce (vw.middlename,'')::text||' '::text||coalesce (vw.lastname,'')::text|| ' '::text) || coalesce (vw.address,'')::text ,', '::text) as claimants
			FROM kaveri.partyinfo vw
			join kaveri.propertymaster pm2 on vw.applicationnumber=pm2.applicationnumber 
			WHERE  vw.applicationnumber = any(v_srapplicationnumber)  and pm2.srocode=_srocode and vw.partytypeid = 1
			GROUP BY vw.applicationnumber) prt_cl ON prt_cl.applicationnumber::text = dm.applicationnumber::text
	 JOIN ( SELECT vw.applicationnumber,
			string_agg((coalesce (vw.firstname,'')::text||' '::text||coalesce (vw.middlename,'')::text||' '::text||coalesce (vw.lastname,'')::text|| ' '::text) || coalesce (vw.address,'')::text ,', '::text) as executants
			FROM kaveri.partyinfo vw
			join kaveri.propertymaster pm2 on vw.applicationnumber=pm2.applicationnumber 
			WHERE  vw.applicationnumber = any(v_srapplicationnumber)  and pm2.srocode=_srocode  and vw.partytypeid = 2
			GROUP BY vw.applicationnumber) prt_ex ON prt_ex.applicationnumber::text = dm.applicationnumber::text
	where arl.srocode=_srocode and arl.isjurisdictionsroaccepted = false and pm.regsrocode<>0)
	,cte_count as (select count(*) as total_rows from cte)
   select * from cte
   right join (select total_rows from cte_count) total_row on true
   where total_row.total_rows<>0
	OFFSET PageOffset
	FETCH NEXT pagesize ROWS ONLY;
end if;

END;
$$;


ALTER FUNCTION kaveri.fn_fetch_anywhere_reg(_srocode bigint, _sr character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_applicaion_finalized(integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_applicaion_finalized(p_srocode integer) RETURNS TABLE(applicationnum character varying, applicationdate date, srocode integer, applicationtypeid integer, servicename character varying, currentstatus character varying, wrkflowstatusnamee text)
    LANGUAGE plpgsql
    AS $$
BEGIN
   RETURN QUERY
  select ad.applicationnumber applicationnum,aa.crtdt::date as applicationdate,ad.srocode,ad.applicationtypeid,sm.servicename,
ad.currentstatus,wm.wrkflowstatusnamee
from kaveri.ApplicantApplicationdetails ad
inner join (select au.applicationnumber,crtdt,au.wrkflowstatusid from Kaveri.ApplicationAudit au
	where au.wrkflowstatusid in ('CD103','CD110') and activityorder = (select max(activityorder) 
				from Kaveri.ApplicationAudit aau 
						   where aau.applicationnumber = au.applicationnumber 
						   and aau.wrkflowstatusid = au.wrkflowstatusid)) aa 
						   on aa.applicationnumber= ad.applicationnumber
left outer join kaveri.Wrkflowmaster wm on wm.wrkflowstatusid = ad.currentstatus 
left join Kaveri.servicesmaster sm on ad.applicationtypeid = sm.serviceid 
where ad.srocode = p_srocode and ad.sfdaid is not null and 
ad.currentstatus in ('CD105','CD110')
order by aa.crtdt;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_applicaion_finalized(p_srocode integer) OWNER TO csgadmin;

