--
-- Name: fn_fetch_application_deo(text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_application_deo(p_deoid text) RETURNS TABLE(applicationnum character varying, applicationdate date, applicationtime text, srocode integer, applicationtypeid integer, servicename character varying, currentstatus character varying, wrkflowstatusnamee text, isverified boolean, isuploaddocuments boolean, presentdate date, executedate date, pendingdocumentnumber character varying, finalregistrationnumber character varying, documentid bigint, isprintsummary boolean, isprintendorsement boolean, isdigitalsigned boolean, isregistrationcompleted boolean, sakalanumber character varying, uploadsummarydocpath text, remarks text, isundervaluation boolean, articlenamee character varying, isphotothumbtransmitted boolean, ispaymentdone boolean, registrationdatetime timestamp without time zone, issignpageappended boolean, isregistrationaccepted boolean, isdigitallyexecuted boolean, isfruits boolean, uploaddocdeedpath text, uploadthumbregisterpath character varying, ispaperless boolean, reasonid bigint)
    LANGUAGE plpgsql
    AS $_$


BEGIN
   RETURN QUERY
 select distinct ad.applicationnumber applicationnum,
  am.appointmentdate::date as applicationdate,
  am.starttime||'-'||am.endtime::text as applicationtime
  ,ad.srocode,ad.applicationtypeid,sm.servicename,
ad.currentstatus,wm.wrkflowstatusnamee,coalesce(dm.ispaymentdetails,'false') as isverified,
coalesce(dm.isuploaddocuments,'false') isuploaddocuments,dm.presentdatetime::date presentdate,
dm.executiondatetime::date as executedate,
regexp_replace(dm.pendingdocumentnumber, '^([^-]*-[^-]*)-.*$', '\1')::character varying,
dm.finalregistrationnumber,dm.documentid,
dm.isprintsummary,dm.isprintendorsement,
	dm.isdigitalsigned,dm.isregistrationcompleted,dm.gscno as sakalanumber,dm.uploadsummarydocpath
	,ad.remarks,dm.isundervaluation,rg.articlenamee,dm.isphotothumbtransmitted
	,CASE
            WHEN fk.applicationnumber is not null THEN true
            ELSE false
        END AS ispaymentdone,
dm.registrationdatetime,
-- paperless change
dm.issignpageappended,
dm.isregistrationaccepted,
dm.isdigitallyexecuted,
ad.isfruits,
dm.uploaddocdeedpath,
dm.uploadthumbregisterpath,
ad.ispaperless,
mb.reasonid
from kaveri.ApplicantApplicationdetails ad
inner join kaveri.documentmaster dm on (dm.applicationnumber = ad.applicationnumber)
left join kaveri.appointmentmaster am on am.applicationnumber =ad.applicationnumber and am.status in ('1','Pending')
join kaveri.Wrkflowmaster wm on wm.wrkflowstatusid = ad.currentstatus
left join kaveri.registrationarticles rg on ad.regarticlecode=rg.regarticlecode
join Kaveri.servicesmaster sm on ad.applicationtypeid = sm.serviceid
left join kaveri.feesrequired_paymentchk fk on ad.applicationnumber=fk.applicationnumber
left join kaveri.minutebook_data mb on mb.applicationnumber = ad.applicationnumber
where ad.deoid::text = p_deoid and
(ad.currentstatus in ('CD110','CD112','CD119','CD115', 'CD136'))
;

END;
$_$;


ALTER FUNCTION kaveri.fn_fetch_application_deo(p_deoid text) OWNER TO postgres;

--
-- Name: fn_fetch_application_deo_appnum_filing(integer, character varying, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_application_deo_appnum_filing(_deocode integer, _currentstatus character varying, _bookid integer, _applicationtypeid integer) RETURNS TABLE(applicationnum character varying, applicationdate timestamp without time zone, applicationtime text, regsrocode integer, srocode integer, applicationtypeid integer, currentstatus character varying, wrkflowstatusnamee text, deoid bigint, ordernumber character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (_currentstatus IN ('BK101', 'BK110', 'BK111', 'BK105', 'BK106', 'BK114')) THEN
        RETURN QUERY
        SELECT DISTINCT
            ad.applicationnumber AS applicationnum,
            ad.applicationstartdate AS applicationdate,
            TO_CHAR(ad.applicationstartdate, 'HH12:MI:SS AM') AS applicationtime,
			ad.regsrocode,
            ad.srocode,
            ad.applicationtypeid,
            ad.currentstatus,
            wm.wrkflowstatusnamee,
			ad.deoid,
			CASE WHEN _bookid = 14 THEN fb.order_number ELSE NULL END AS ordernumber
        FROM kaveri.applicantapplicationdetails ad
        JOIN kaveri.wrkflowmaster wm ON wm.wrkflowstatusid = ad.currentstatus
		LEFT JOIN kaveri.filing_book1 fb ON (_bookid = 14 AND ad.applicationnumber = fb.applicationnumber)
        WHERE ad.deoid = _deocode
            AND ad.bookid = _bookid
            AND ad.applicationtypeid = _applicationtypeid
            AND ad.isdeleted = FALSE
            AND ad.currentstatus = _currentstatus
        ORDER BY ad.applicationstartdate;
    END IF;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_application_deo_appnum_filing(_deocode integer, _currentstatus character varying, _bookid integer, _applicationtypeid integer) OWNER TO postgres;

--
-- Name: fn_fetch_application_fda_appnum_filing(integer, character varying, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_application_fda_appnum_filing(_fdacode integer, _currentstatus character varying, _bookid integer, _applicationtypeid integer) RETURNS TABLE(applicationnum character varying, applicationdate timestamp without time zone, applicationtime text, regsrocode integer, srocode integer, applicationtypeid integer, currentstatus character varying, wrkflowstatusnamee text, deoid bigint, ordernumber character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (_currentstatus IN ('BK103', 'BK112')) THEN
        RETURN QUERY
        SELECT DISTINCT
            ad.applicationnumber AS applicationnum,
            ad.applicationstartdate AS applicationdate,
            TO_CHAR(ad.applicationstartdate, 'HH12:MI:SS AM') AS applicationtime,
			ad.regsrocode,
            ad.srocode,
            ad.applicationtypeid,
            ad.currentstatus, 
            wm.wrkflowstatusnamee,
			ad.deoid,
			CASE WHEN _bookid = 14 THEN fb.order_number ELSE NULL END AS ordernumber
        FROM kaveri.applicantapplicationdetails ad
        JOIN kaveri.wrkflowmaster wm ON wm.wrkflowstatusid = ad.currentstatus
		LEFT JOIN kaveri.filing_book1 fb ON (_bookid = 14 AND ad.applicationnumber = fb.applicationnumber)
        WHERE ad.sfdaid = _fdacode
            AND ad.bookid = _bookid
            AND ad.applicationtypeid = _applicationtypeid
            AND ad.isdeleted = FALSE
            AND ad.currentstatus = _currentstatus
        ORDER BY ad.applicationstartdate;
    END IF;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_application_fda_appnum_filing(_fdacode integer, _currentstatus character varying, _bookid integer, _applicationtypeid integer) OWNER TO postgres;

--
-- Name: fn_fetch_application_json_data(text, bigint); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_application_json_data(_applicationnumber text, _srocode bigint) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
BEGIN
		
select row_to_json(app_json) into v_data_json
from (
  select ad.applicationnumber,dm.executiondatetime::date executedate,
dm.pendingdocumentnumber, dm.pagecount ,sa.articlenamee as stamparticlename,
ra.articlenamee as regarticalename, 
     (
      select array_to_json(array_agg(row_to_json(prpty)))
      from (SELECT pm.applicationnumber,
 	pm.propertyid,
    pm.documentid,
    d.villagenamee,
	pm.propertytypeid,
	ptm.propertytypename as propertytype,
    c.sronamee sroname,
    pm.northboundary,
    pm.southboundary,
    pm.eastboundary,
    pm.westboundary,
    pm.landmark,
	pm.consideration,
    pm.marketvalue,
	pm.cessduty,
    pm.govtduty,
	pm.additionalduty,
	pm.stampduty,
    pm.valuationreport,
	( select array_to_json(array_agg(row_to_json(schd)))
      from (select ps.scheduletype,ps.totalarea,ps.description as scheduledescription,
			ps.partyids as scheduleparties from kaveri.propertyschedules ps 
		   where ps.propertyid = pm.propertyid)schd ) as propertyschedules,
	  ( select array_to_json(array_agg(row_to_json(prptyno)))
      from (select pnd.propertyid,pnd.currentpropertytypeid,
			pntm.typenameenglish as propertynumbertype,
			pnd.currentnumber,pnd.hissa_no,pnd.survey_no 
			from kaveri.propertynumberdetails pnd 
		   left join kaveri.propertynotypemaster pntm			
			on (pntm.propertytypeid = pnd.currentpropertytypeid) 
		   where pnd.propertyid = pm.propertyid )prptyno ) 
			as propertynumberdetails
   FROM kaveri.propertymaster pm 
   left join kaveri.propertytypemaster ptm on (ptm.propertytypeid = pm.propertytypeid) 
   left join  kaveri.sromaster c on (pm.srocode = c.srocode)
   left join kaveri.villagemaster d on (pm.villagecode = d.villagecode)
   where pm.applicationnumber=ad.applicationnumber) prpty
    ) as propertyinfo,	
	 (
      select array_to_json(array_agg(row_to_json(prty)))
      from (select applicationnumber,partyid,name as partyname,age, address ,profession,
phonenumber,epic,partytypeid,partytypename,isexecutor,ispresenter,admissiondate,
section88exemption,fingerid,thumbpath,photopath
from kaveri.vw_fetch_party vw_party 
			where vw_party.applicationnumber = ad.applicationnumber) prty
    ) as partyinfo,
	(  select array_to_json(array_agg(row_to_json(witness)))
      from (select name,address,age,profession from kaveri.witnessinfo wi
where wi.applicationnumber = ad.applicationnumber) witness
	) as witnessinfo
  from kaveri.applicantapplicationdetails ad
inner join kaveri.documentmaster dm on (ad.applicationnumber=dm.applicationnumber)
left join kaveri.booktypemaster bm on (bm.bookid=dm.bookid)
left join kaveri.stamparticles sa on (sa.stamparticlecode=dm.stamparticlecode)
left join kaveri.registrationarticles ra on (ra.regarticlecode=dm.regarticlecode)
  where ad.applicationnumber = _applicationnumber and ad.srocode=_srocode
) app_json ;

return v_data_json;

END;
$$;


ALTER FUNCTION kaveri.fn_fetch_application_json_data(_applicationnumber text, _srocode bigint) OWNER TO csgadmin;

--
-- Name: fn_fetch_application_status_track(bigint, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_application_status_track(_srocode bigint, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
PageOffset INTEGER := 0;
v_offcnt int;
begin
	
	
PageOffset := ((pagenumber - 1) * pagesize);	

select count(*) into v_offcnt from kaveri.appointmentmaster am
join kaveri.applicantapplicationdetails a on a.applicationnumber =am.applicationnumber 
where appointmentdate::date=current_date and a.srocode =_srocode
and a.currentstatus in ('CD108','CD109','CD110','CD111',
	'CD112','CD115','CD116');	

if (v_offcnt<PageOffset)
then
PageOffset := 0;
end if;
if(pagenumber<>-1 and pagesize<>-1) then
	
	select row_to_json(data_json) into v_data_json 
	from (select dsm.districtnamee ,s.sronamee,
		(select array_to_json(array_agg((row_to_json(application_data))))
	  	from(select a.applicationnumber,a.currentstatus, 
		coalesce(p.firstname,' ') || coalesce(p.middlename,' ') || coalesce(p.lastname,' ')  as presentername,
		d2.userid,d3.designame || '-'||d2.slno as deoid
	  	from kaveri.applicantapplicationdetails a
	  		join kaveri.appointmentmaster am on am.applicationnumber =a.applicationnumber
		   left join kaveri.documentmaster d on a.applicationnumber=d.applicationnumber 
		   left join (select row_number() over (partition by designationid,srocode order by designationid)as slno,* from 
kaveri.departmentusers) d2 on a.assignedto=d2.userid::text 
		   left join kaveri.desigmaster d3 on d2.designationid=d3.designationid 
		   left join kaveri.partyinfo p on d.applicationnumber=p.applicationnumber and p.ispresenter=true
		   where d.srocode=_srocode  and a.currentstatus in ('CD108','CD109','CD110','CD111',
	'CD112','CD115','CD116') and am.appointmentdate::Date=current_date order by a.inserteddatetime
	OFFSET PageOffset
	FETCH NEXT pagesize ROWS ONLY)application_data) as application_data
	from kaveri.districtmaster dsm 
	join kaveri.sromaster s on dsm.districtcode=s.districtcode and s.srocode=_srocode)data_json;

elsif (pagenumber=-1 or  pagesize=-1) then
--	PageOffset := ((pagenumber - 1) * pagesize);
	select row_to_json(data_json) into v_data_json 
	from (select dsm.districtnamee ,s.sronamee,
		(select array_to_json(array_agg((row_to_json(application_data))))
	  	from(select a.applicationnumber,a.currentstatus, 
		coalesce(p.firstname,' ') || coalesce(p.middlename,' ') || coalesce(p.lastname,' ')  as presentername,
		d2.userid,d2.userid,d3.designame || '-'||d2.slno as deoid
	  	from kaveri.applicantapplicationdetails a
	  		join kaveri.appointmentmaster am on a.applicationnumber=am.applicationnumber 
		   left join kaveri.documentmaster d on a.applicationnumber=d.applicationnumber 
		  left join (select row_number() over (partition by designationid,srocode order by designationid)as slno,* from 
kaveri.departmentusers) d2 on a.assignedto=d2.userid::text   
		   left join kaveri.desigmaster d3 on d2.designationid=d3.designationid 
		   left join kaveri.partyinfo p on d.applicationnumber=p.applicationnumber and p.ispresenter=true
		   where d.srocode=_srocode and a.currentstatus in ('CD108','CD109','CD110','CD111',
	'CD112','CD115','CD116') and am.appointmentdate::Date=current_date order by a.inserteddatetime )application_data) as application_data
	from kaveri.districtmaster dsm 
	join kaveri.sromaster s on dsm.districtcode=s.districtcode and s.srocode=_srocode)data_json;
end if;

return v_data_json;

END;
$$;


ALTER FUNCTION kaveri.fn_fetch_application_status_track(_srocode bigint, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_applicationdetails(integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_applicationdetails(_valrateheaderid integer) RETURNS TABLE(valrateheaderid bigint, circularinfo text, circularpath text, effectivedate timestamp without time zone, roadcode bigint, roadname character varying, roadnamek character varying, srocode bigint, villagecode bigint, villagename character varying, villagenamek character varying, hoblicode integer, hobliname character varying, sfdaid bigint, masval json)
    LANGUAGE plpgsql
    AS $$

BEGIN 

return query
SELECT mh.valrateheaderid,
    mh.circularinfo,
    mh.circularpath,
    mh.effectivedate,
    mval.roadcode,
    rm.roadnamee AS roadname,
    rm.roadnamek,
    mval.srocode,
    vm.villagecode,
    vm.villagenamee AS villagename,
    vm.villagenamek,
    h.hoblicode,
    h.hoblinamee AS hobliname,
    mh.sfdaid,
    ( SELECT array_to_json(array_agg(row_to_json(val.*))) AS array_to_json
           FROM ( SELECT 'Agriculture'::text AS propertytype,
                    ra.rate,
                    ra.agrilandtypedesc AS typedesc,
                    ra.rate_val
                   FROM ( SELECT m.roadcode,
                            r.agrilandtypeid,
                            r.measurementcode,
                            r.rate,
                            r.effectivedate,
                            agri_ty.description AS agrilandtypedesc,
                            m.rate AS rate_val
                           FROM kaveri.mas_valratedetail m
                             JOIN kaveri.mas_val_agrilandtypes agri_ty ON m.agrilandtypeid = agri_ty.agrilandtypeid
                             LEFT JOIN ( SELECT ad.roadcode,
                                    ad.agrilandtypeid,
                                    ad.villagecode,
                                    ad.measurementcode,
                                    ad.rate,
                                    ad.effectivedate,
                                    COALESCE(lead(ad.effectivedate, 1) OVER (PARTITION BY ad.roadcode, ad.agrilandtypeid ORDER BY ad.effectivedate),
                                    CURRENT_DATE::timestamp without time zone) AS effectivetodate
                                   FROM kaveri.rateagriculturaldetail ad) r ON r.roadcode = m.roadcode AND m.agrilandtypeid = r.agrilandtypeid AND m.propertytypeid = 17 AND CURRENT_DATE >= r.effectivedate AND CURRENT_DATE <= r.effectivetodate
                          WHERE mh.valrateheaderid = m.valrateheaderid AND mval.roadcode = m.roadcode AND mval.sfdaid = m.sfdaid AND m.propertytypeid = 17) ra
                  WHERE mval.roadcode = ra.roadcode
                  UNION ALL
                 SELECT 'Vacant Land/Building'::text AS propertytype,
                    ra.rate,
                    ra.propertytypename AS typedesc,
                    ra.rate_val
                   FROM ( SELECT m.roadcode,
                            r.propertytypeid,
                            r.measurementcode,
                            r.rate,
                            r.effectivedate,
                            ptm.propertytypename,
                            m.rate AS rate_val
                           FROM kaveri.mas_valratedetail m
                             JOIN kaveri.propertytypemaster ptm ON ptm.propertytypeid = m.propertytypeid
                             LEFT JOIN ( SELECT br.roadcode,
                                    br.propertytypeid,
                                    br.rate,
                                    br.measurementcode,
                                    br.effectivedate,
                                    COALESCE(lead(br.effectivedate, 1) OVER (PARTITION BY br.roadcode, br.propertytypeid ORDER BY br.effectivedate), CURRENT_DATE::timestamp without time zone) AS effectivetodate
                                   FROM kaveri.openbuiltratedetail br) r ON r.roadcode = m.roadcode AND m.propertytypeid <> 17 AND m.agrilandtypeid IS NULL AND m.propertytypeid = r.propertytypeid AND CURRENT_DATE >= r.effectivedate AND CURRENT_DATE <= r.effectivetodate
                          WHERE mh.valrateheaderid = m.valrateheaderid AND mval.roadcode = m.roadcode AND mval.sfdaid = m.sfdaid AND m.agrilandtypeid IS NULL AND m.amenitiesid IS NULL) ra
                  WHERE mval.roadcode = ra.roadcode 
                   UNION ALL
                 SELECT 'Apartment/Flat'::text AS propertytype,
                    ra.rate,
                    ra.namewithamenities AS typedesc,
                    ra.rate_val
                   FROM ( SELECT m.roadcode,
                            r.propertytypeid,
                            r.measurementcode,
                            r.rate,
                            r.effectivedate,
                            ptm.propertytypename,
                            m.amenitiesid,
                            m.floorid,
                            amn.namewithamenities,
                            m.rate AS rate_val
                           FROM kaveri.mas_valratedetail m
                             JOIN kaveri.mas_val_apartmentsamenities amn ON amn.amenitiesid = m.amenitiesid
                             JOIN kaveri.propertytypemaster ptm ON ptm.propertytypeid = m.propertytypeid
                             LEFT JOIN ( SELECT op.roadid AS roadcode,
                                    op.propertytypeid,
                                    op.amenitiesid,
                                    op.floorid,
                                    op.unitid AS measurementcode,
                                    op.rate,
                                    op.effectivedate,
                                    COALESCE(lead(op.effectivedate, 1) OVER (PARTITION BY op.roadid, op.propertytypeid, op.amenitiesid, op.floorid ORDER BY op.effectivedate), CURRENT_DATE::timestamp without time zone) AS effectivetodate
                                   FROM kaveri.mas_val_flatrates op
                                  WHERE op.amenitiesid IS NOT NULL) r ON r.roadcode = m.roadcode AND m.propertytypeid <> 17 AND m.agrilandtypeid IS NULL AND m.propertytypeid = r.propertytypeid AND m.amenitiesid = r.amenitiesid AND m.floorid = r.floorid AND CURRENT_DATE >= r.effectivedate AND CURRENT_DATE <= r.effectivetodate
                          WHERE mh.valrateheaderid = m.valrateheaderid AND mval.roadcode = m.roadcode AND mval.sfdaid = m.sfdaid AND m.amenitiesid IS NOT NULL AND m.agrilandtypeid IS NULL) ra
                  WHERE ra.roadcode = mval.roadcode
                  ) val) AS masval
      FROM kaveri.mas_valrateheader mh
      join kaveri.mas_valratedetail mval ON mh.valrateheaderid = mval.valrateheaderid
      --     JOIN ( SELECT DISTINCT mas_valratedetail.sfdaid,
--            mas_valratedetail.srocode,
--            mas_valratedetail.roadcode,
--            mas_valratedetail.valrateheaderid
--           FROM kaveri.mas_valratedetail
--          WHERE mas_valratedetail.valrateheaderid IS NOT NULL) mval ON mh.valrateheaderid = mval.valrateheaderid
     JOIN kaveri.roadmaster rm ON rm.roadcode = mval.roadcode
     JOIN kaveri.villagemaster vm ON vm.villagecode = rm.villagecode
     JOIN kaveri.hoblimaster h ON vm.hoblicode = h.hoblicode
     where mh.valrateheaderid =_valrateheaderid;
end;
$$;


ALTER FUNCTION kaveri.fn_fetch_applicationdetails(_valrateheaderid integer) OWNER TO postgres;

--
-- Name: fn_fetch_applicationdetails(character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_applicationdetails(_applicationnumber character varying) RETURNS TABLE(appointmenttypeid integer, appointmenttype character varying, serviceid integer, servicename character varying, srocode integer, sroname character varying, firstname character varying, iswillpvtattendance boolean)
    LANGUAGE plpgsql
    AS $$


declare
v_typeid int;

BEGIN 
	
select applicationtypeid into v_typeid from kaveri.applicantapplicationdetails a where applicationnumber =_applicationnumber;

if(v_typeid=1)
then
return query
with party as (select count(partyid) as countofparty,isprivateattendance,partyid,applicationnumber from kaveri.partyinfo group by isprivateattendance,partyid,applicationnumber )
select distinct
1 as appointmenttypeid,
'Regular'::varchar as appointmenttype,
e.serviceid
,e.servicename
,p.srocode
,s.sronamee  sroname
, p.firstname::varchar
,case when party.countofparty = 1 and party.isprivateattendance = true then true else false END as iswillpvtattendance
from kaveri.applicantapplicationdetails a 
join kaveri.servicesmaster e on a.applicationtypeid  =e.serviceid
join kaveri.partyinfo p on a.applicationnumber =p.applicationnumber 
--join kaveri.documentmaster c on c.applicationnumber =p.applicationnumber 
join kaveri.sromaster s on p.srocode =s.srocode 
join party on party.applicationnumber = a.applicationnumber
where a.applicationnumber=_applicationnumber and p.ispresenter = case 
when party.countofparty=1 and party.isprivateattendance = true then  false 
else  true end;

elsif(v_typeid=4)
then
return query
select
1 as appointmenttypeid,
'Regular'::varchar as appointmenttype,
e.serviceid
,e.servicename
,a.srocode
,s.sronamee  sroname
, c.firstname::varchar,
false as iswillpvtattendance
from kaveri.applicantapplicationdetails a 
join kaveri.citizenmaster c on a.citizenid=c.citizenid
join kaveri.servicesmaster e on a.applicationtypeid  =e.serviceid
--join kaveri.partyinfo p on a.applicationnumber =p.applicationnumber 
--join kaveri.documentmaster d on d.applicationnumber =a.applicationnumber 
join kaveri.sromaster s on a.srocode =s.srocode 
where a.applicationnumber=_applicationnumber;
end if;


end;
$$;


ALTER FUNCTION kaveri.fn_fetch_applicationdetails(_applicationnumber character varying) OWNER TO csgadmin;

