CREATE FUNCTION kaveri.fn_fetch_applicationnumber(_bookid bigint, _financial_year character varying, _documentnumber bigint, _srocode bigint) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_applicationno character varying ;
v_array json;
v_reg character varying;
begin 
--	if _bookname = 'Marriage' then
--	select * from kaveri.fn_fetch_applicationnumber_marriage(_bookname, _financial_year, _documentnumber , _srocode)
--    into v_array;
--	else
 SELECT row_to_json(w) AS Jsonfun from (select
	  d.applicationnumber,d.finalregistrationnumber,a.currentstatus,sr.sronamee,sr.sronamek
	from kaveri.documentmaster d
	left join kaveri.sromaster sr on d.srocode = sr.srocode 
	left join kaveri.applicantapplicationdetails a on a.applicationnumber = d.applicationnumber
	left join kaveri.booktypemaster b on d.bookid = b.bookid 
	left join kaveri.scannedfileuploaddetails s on d.documentid = s.documentid 
	where b.bookid =_bookid and right(d.finalregistrationnumber,7)::varchar=_financial_Year --and extract(year from d.presentdatetime)::varchar=_presentyear
	and d.documentnumber=_documentnumber and d.srocode=_srocode)  w into v_array;
--v_reg:=array[v_applicationno,v_applicationno];
--end if;
return (v_array) ;
end;
$$;


