--
-- Name: fn_fetch_applications_citizen_dashboard(bigint, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_applications_citizen_dashboard(_citizenid bigint, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(applicationnumber text, applicationstartdate timestamp without time zone, applicationtype text, ispendingdocument boolean, wrkflowstatusnamee text, wrkflowstatusid text, remarks text, sroname text, sronamek text, isduecorrection boolean, deptreferencecode text, reasonid integer)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
		PageOffset := ((pagenumber - 1) * pagesize);
			

				return query 
				/*select 
				vw.applicationnumber::text, 
				vw.applicationstartdate, 
				vw.servicename::text as applicationtype,
				--a.ispendingdocument,
				vw.currentstatusname as wrkflowstatusnamee,
				vw.currentstatus::text as wrkflowstatusid,
				vw.remarks,
				vw.sroname::text,
				vw.sronamek::text,vw.isduecorrection,vw.deptreferencecode::text,a.reasonid
				from kaveri.vw_citizen_dashbaord vw 
				left join kaveri.minutebook_data a on a.applicationnumber = vw.applicationnumber
				where  vw.citizenid = _citizenid
				order by vw.applicationstartdate desc  */
				
				select 
				app.applicationnumber::text, 
				app.applicationstartdate, 
				ser.servicename::text as applicationtype,
				a.ispendingdocument,
				wrk.wrkflowstatusnamee as wrkflowstatusnamee,
				app.currentstatus::text as wrkflowstatusid,
				app.remarks,
				sr.sronamee::text as sroname,
				sr.sronamek::text,
				app.isduecorrection,
					( SELECT ams_reg_epaymenttransdetails.deptreferencecode::text
					FROM kaveri.ams_reg_epaymenttransdetails
					WHERE ams_reg_epaymenttransdetails.applicationnumber::text = app.applicationnumber::text AND 
					ams_reg_epaymenttransdetails.isdelete IS NULL
					ORDER BY ams_reg_epaymenttransdetails.inserteddatetime DESC
					LIMIT 1) AS deptreferencecode,
				a.reasonid
		--kaveri.vw_citizen_dashbaord vw 
  FROM kaveri.applicantapplicationdetails app
     JOIN kaveri.servicesmaster ser ON app.applicationtypeid = ser.serviceid
     JOIN kaveri.wrkflowmaster wrk ON app.currentstatus::text = wrk.wrkflowstatusid::text
     LEFT JOIN kaveri.sromaster sr ON sr.srocode = COALESCE(app.regsrocode, app.srocode)
	 left join kaveri.minutebook_data a on a.applicationnumber = app.applicationnumber
				where  app.citizenid = _citizenid
			order by app.applicationstartdate desc
				
				OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
				

END;
$$;


ALTER FUNCTION kaveri.fn_fetch_applications_citizen_dashboard(_citizenid bigint, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_fetch_applications_citizen_dashboard_bkup_020523(bigint, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_applications_citizen_dashboard_bkup_020523(_citizenid bigint, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(applicationnumber text, applicationstartdate timestamp without time zone, applicationtype text, wrkflowstatusnamee text, wrkflowstatusid text, remarks text, sroname text, sronamek text, isduecorrection boolean, deptreferencecode text, reasonid integer)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
		PageOffset := ((pagenumber - 1) * pagesize);
			

				return query 
				select 

				vw.applicationnumber::text, 
				vw.applicationstartdate, 
				vw.servicename::text as applicationtype,
				--a.ispendingdocument,
				vw.currentstatusname as wrkflowstatusnamee,
				vw.currentstatus::text as wrkflowstatusid,
				vw.remarks,
				vw.sroname::text,
				vw.sronamek::text,vw.isduecorrection,vw.deptreferencecode::text,a.reasonid
				from kaveri.vw_citizen_dashbaord vw 
				left join kaveri.minutebook_data a on a.applicationnumber = vw.applicationnumber
				where  vw.citizenid = _citizenid
				order by vw.applicationstartdate desc
				
				OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
		
		

END;
$$;


ALTER FUNCTION kaveri.fn_fetch_applications_citizen_dashboard_bkup_020523(_citizenid bigint, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_applications_citizen_dashboard_json(bigint, integer, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_applications_citizen_dashboard_json(_citizenid bigint, _applicationtypeid integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
 
DECLARE
PageOffset INTEGER := 0;
v_count integer;
v_data_json json;
BEGIN
 
  select count(*) into v_count from  kaveri.vw_citizen_dashbaord vw
  left join kaveri.minutebook_data a on a.applicationnumber = vw.applicationnumber
  where  vw.citizenid = _citizenid and vw.applicationtypeid =_applicationtypeid;
  PageOffset := ((pagenumber - 1) * pagesize);
   
 
    select row_to_json(app_data) into v_data_json from (select array_to_json(array_agg(row_to_json(temp))) as applications,v_count as Total from (select
 
    vw.applicationnumber::text,
    vw.applicationstartdate,
    vw.servicename::text as applicationtype,
    a.ispendingdocument,
    vw.currentstatusname as wrkflowstatusnamee,
    vw.currentstatus::text as wrkflowstatusid,
    vw.remarks,
    vw.srocode,
    vw.sroname::text,
    vw.sronamek::text,vw.isduecorrection,vw.deptreferencecode::text,a.reasonid,
    a.isbefore2003,
    vw.applicationtypeid,
    vw.wasfrozen,
    vw.uploaddocdeedpath,
    case when k1.applicationnumber is not null and aap.currentstatus='CD101' then true else false end as isk1pending,
    vw.submitteddate,
	aap.regarticlecode,
	vw.isdigitallyexecuted,
	vw.issignpageappended,
	aap.ispaperless,
	vw.ispanverified,
	vw.ispanmandatory
    from kaveri.vw_citizen_dashbaord vw
    left join kaveri.minutebook_data a on a.applicationnumber = vw.applicationnumber
    left join kaveri.k1pendingregistrationdata k1 on k1.applicationnumber = vw.applicationnumber
    left join kaveri.applicantapplicationdetails aap on aap.applicationnumber = vw.applicationnumber
    where  vw.citizenid = _citizenid and vw.applicationtypeid = _applicationtypeid
    order by vw.applicationstartdate desc
    
    OFFSET PageOffset
    FETCH NEXT pagesize ROWS ONLY )temp)app_data;
  
  
return  v_data_json;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_applications_citizen_dashboard_json(_citizenid bigint, _applicationtypeid integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_applications_citizen_dashboard_json_1(bigint, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_applications_citizen_dashboard_json_1(_citizenid bigint, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$





DECLARE
PageOffset INTEGER := 0;
v_count integer;
v_data_json json;
BEGIN	

		select count(*) into v_count from  kaveri.vw_citizen_dashbaord vw 
		left join kaveri.minutebook_data a on a.applicationnumber = vw.applicationnumber
		where  vw.citizenid = _citizenid;
		PageOffset := ((pagenumber - 1) * pagesize);
			

				select row_to_json(app_data) into v_data_json from (select array_to_json(array_agg(row_to_json(temp))) as applications,v_count as Total from (select 

				vw.applicationnumber::text, 
				vw.applicationstartdate, 
				vw.servicename::text as applicationtype,
				a.ispendingdocument,
				vw.currentstatusname as wrkflowstatusnamee,
				vw.currentstatus::text as wrkflowstatusid,
				vw.remarks,
				vw.srocode,
				vw.sroname::text,
				vw.sronamek::text,vw.isduecorrection,vw.deptreferencecode::text,a.reasonid,
				vw.wasfrozen
				from kaveri.vw_citizen_dashbaord vw 
				left join kaveri.minutebook_data a on a.applicationnumber = vw.applicationnumber
				where  vw.citizenid = _citizenid
				order by vw.applicationstartdate desc
				
				OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY	)temp)app_data;
		
		
return  v_data_json;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_applications_citizen_dashboard_json_1(_citizenid bigint, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_fetch_applications_citizen_dashboard_json_form17_indx(bigint, integer, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_applications_citizen_dashboard_json_form17_indx(_citizenid bigint, _applicationtypeid integer, pagenumber integer DEFAULT 1, pagesize integer DEFAULT 10) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare
    PageOffset INTEGER := 0;
    v_count INTEGER;
    v_data_json JSON;
begin

    PageOffset := ((pagenumber - 1) * pagesize);

    select COUNT(*) into v_count from kaveri.applicantapplicationdetails aap where aap.citizenid = _citizenid and aap.applicationtypeid = _applicationtypeid;

    select row_to_json(app_data) into v_data_json from (select  array_to_json(array_agg(row_to_json(temp))) as applications, v_count as Total
        from (select
                al.applicationnumber::text,
                aap.applicationstartdate,
                s.servicename::text AS applicationtype,
                wrk.wrkflowstatusnamee,
                wrk.wrkflowstatusid,
                aap.applicationtypeid,
                al.filepath,
				ams.deptreferencecode 
            from kaveri.applicantapplicationdetails aap 
			join kaveri.tbl_index2_audit_log al on aap.applicationnumber = al.applicationnumber
			left join kaveri.ams_reg_epaymenttransdetails ams on ams.applicationnumber = aap.applicationnumber and ams.isdelete =false
            join kaveri.servicesmaster s on s.serviceid = aap.applicationtypeid 
			join kaveri.wrkflowmaster wrk on wrk.wrkflowstatusid = aap.currentstatus
            where aap.citizenid = _citizenid and aap.applicationtypeid = _applicationtypeid
            order by aap.applicationstartdate desc
            offset PageOffset
            limit pagesize
        ) temp
    ) app_data;

    return v_data_json;

end;
$$;


ALTER FUNCTION kaveri.fn_fetch_applications_citizen_dashboard_json_form17_indx(_citizenid bigint, _applicationtypeid integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_book1_part3_property_details_json(text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_book1_part3_property_details_json(_applicationnumber text) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_data_json JSON;
BEGIN
    -- Prepare the JSON data for each property
    SELECT json_agg(data_json) INTO v_data_json
    FROM (
        WITH property_details AS (
            SELECT 
                pm.propertyid AS property_id,
                pm.regsrocode AS reg_sro_code,
                pm.propertytypeid AS property_type_id,
				dm.districtcode AS district_code,
				tm.talukcode AS taluk_code,
				hm.hoblicode AS hobli_code,
                pm.villagecode AS village_code,
                pm.totalarea AS total_area,
                pm.unitid AS unit_id,
                pm.northboundary AS north_boundary,
                pm.southboundary AS south_boundary,
                pm.eastboundary AS east_boundary,
                pm.westboundary AS west_boundary,
                COALESCE(bpc.amount_paid, '0') AS stamp_duty,
				bpc.challan_number AS challan_number,
				CASE 
				WHEN bpc.payment_type_id = '0' THEN 'No'
				WHEN bpc.payment_type_id = '1' THEN 'Received'
            	WHEN bpc.payment_type_id = '2' THEN 'E-Stamp'
            	WHEN bpc.payment_type_id = '3' THEN 'K2-Challan'
            			ELSE ''
        				END AS payment_type,
                pm.documentid AS doc_id,
                pm.srocode AS sro_code,
                pm.ismovableproperty AS is_movable,
                ps.description AS schedule_desc,
                -- Combining current_property_type_ids and current_number as an object
                json_agg(
                   DISTINCT jsonb_build_object(
                        'currentPropertyTypeId', pnd.currentpropertytypeid,
                        'currentNumber', pnd.currentnumber
                    )
                ) AS current_property_details,
                COALESCE(
            jsonb_agg(
                DISTINCT jsonb_build_object(
                    'partyid', pi.partyid,
                    'salutationid', COALESCE(pi.salutationid, 0),
                    'firstname', pi.firstname,
                    'middlename', pi.middlename,
                    'lastname', pi.lastname,
                    'address', pi.address,
                    'isexecutor', pi.isexecutor,
                    'ispresenter', pi.ispresenter,
                    'partytypeid', pi.partytypeid,
                    'age', pi.age
                )
            ) FILTER (WHERE pi.partytypeid = 1 and pi.applicationnumber = _applicationnumber), '[]'::jsonb
        ) AS party_details
            FROM kaveri.propertymaster pm
            LEFT JOIN kaveri.propertyschedules ps ON pm.propertyid = ps.propertyid
            LEFT JOIN kaveri.propertynumberdetails pnd ON pm.propertyid = pnd.propertyid
            LEFT JOIN kaveri.partyinfo pi ON pm.applicationnumber = pi.applicationnumber
			LEFT JOIN kaveri.villagemaster vm ON pm.villagecode = vm.villagecode
			LEFT JOIN kaveri.hoblimaster hm ON vm.hoblicode = hm.hoblicode
			LEFT JOIN kaveri.talukmaster tm ON hm.talukcode = tm.talukcode
			LEFT JOIN kaveri.districtmaster dm ON tm.districtcode = dm.districtcode
			LEFT join kaveri.book1_part3_court bpc ON pm.applicationnumber = bpc.applicationnumber
            WHERE pm.applicationnumber = _applicationnumber
            GROUP BY 
                pm.propertyid, ps.description, pm.regsrocode, pm.propertytypeid, dm.districtcode, tm.talukcode, hm.hoblicode,
                pm.villagecode, pm.totalarea, pm.unitid, pm.northboundary, pm.southboundary,
                pm.eastboundary, pm.westboundary, bpc.amount_paid, bpc.challan_number, bpc.payment_type_id, pm.documentid, pm.srocode, pm.ismovableproperty
        )
        SELECT 
            property_id, 
            reg_sro_code, 
            property_type_id,
			district_code,
			taluk_code,
			hobli_code, 
            village_code, 
            total_area, 
            unit_id, 
            north_boundary, 
            south_boundary, 
            east_boundary, 
            west_boundary, 
            stamp_duty,
			challan_number,
			payment_type,
            doc_id, 
            sro_code, 
            is_movable, 
            schedule_desc, 
            current_property_details, 
            party_details
        FROM property_details
    ) data_json;

    -- Return the JSON result
    RETURN v_data_json;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_book1_part3_property_details_json(_applicationnumber text) OWNER TO postgres;

--
-- Name: fn_fetch_book1_part3_summary_json(text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_book1_part3_summary_json(_applicationnumber text) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_data_json JSON;
BEGIN
    SELECT json_agg(data_json) INTO v_data_json
    FROM (
        SELECT
            -- Property Details
            pm.propertyid AS property_id,
            di.districtnamee AS district,
            ta.taluknamee AS taluk,
            ho.hoblinamee AS hobli,
            vi.villagenamee AS index_ii_village,
            pt.propertytypename AS property_type,
            ps.eastboundary AS east,
            ps.westboundary AS west,
            ps.northboundary AS north,
            ps.southboundary AS south,
			--pnd.currentnumber AS present_property_no,

            -- Schedule Description Details
            COALESCE((SELECT array_to_json(array_agg(row_to_json(schedule_data)))
             FROM (
                SELECT
                    'Schedule: ' || ps.scheduletype AS schedule_type,
                    --'Survey Number: ' || pnd.survey_no AS property_details,
					COALESCE(
					    (SELECT string_agg(pnm.typenameenglish || ': ' || pnd.currentnumber, ', ')
					     FROM kaveri.propertynumberdetails pnd
					     JOIN kaveri.propertynotypemaster pnm 
					         ON pnd.currentpropertytypeid = pnm.propertytypeid
					     WHERE pnd.propertyid = pm.propertyid
					    ),
					    'No details available'
					) AS property_details,

                    pm.totalarea AS area,
                    mm.measurementnamee AS unit,
                    ps.description AS description,

                    -- Executants (partytypeid = 2)
                    (SELECT array_to_json(array_agg(row_to_json(party_data)))
                     FROM (
                        SELECT pi.firstname AS name
                        FROM kaveri.partyinfo pi
                        WHERE pi.applicationnumber = _applicationnumber AND pi.partytypeid = 2
						AND pi.propertyid = pm.propertyid
                        GROUP BY pi.firstname
                     ) party_data) AS executants,

				-- Claimants (partytypeid = 1) filtered by propertyId
				(SELECT array_to_json(array_agg(row_to_json(party_data)))
 				FROM (
    				SELECT pi.firstname AS name
    				FROM kaveri.partyinfo pi
    				INNER JOIN kaveri.partyschedules ps 
        				ON pi.partyid = ps.partyid 
        				--AND pi.propertyid = ps.propertyid
    				WHERE ps.applicationnumber = _applicationnumber 
      				AND ps.isdelete = false
      				AND pi.partytypeid = 1
      				AND ps.propertyid = ps.propertyid
    				GROUP BY pi.firstname
 				) party_data) AS claimants



                FROM kaveri.propertyschedules ps
                LEFT JOIN kaveri.measurementmaster mm ON ps.unitid = mm.measurementcode
                LEFT JOIN kaveri.propertynumberdetails pnd ON ps.propertyid = pnd.propertyid
                WHERE ps.propertyid = pm.propertyid
                GROUP BY ps.scheduletype, pnd.survey_no, pm.totalarea, mm.measurementnamee, ps.description
             ) schedule_data
			), '[]') AS schedule_description_details,

		--Stamp Duty Details
		(SELECT array_to_json(array_agg(row_to_json(challan_data)))
             FROM (
			SELECT bc.challan_number AS challan_number,
			COALESCE(bc.amount_paid, '0') AS amount_paid,
			CASE 
				WHEN bc.payment_type_id = '0' THEN 'No'
				WHEN bc.payment_type_id = '1' THEN 'Received'
            	WHEN bc.payment_type_id = '2' THEN 'E-Stamp'
            	WHEN bc.payment_type_id = '3' THEN 'K2-Challan'
            ELSE ''
        	END AS payment_type
			FROM kaveri.book1_part3_court bc WHERE bc.applicationnumber = _applicationnumber --AND bc.is_stamp_duty_paid = true
			GROUP BY bc.challan_number, bc.amount_paid, bc.payment_type_id ) challan_data) AS stamp_duty_details

        FROM kaveri.propertymaster pm
        LEFT JOIN kaveri.villagemaster vi ON pm.villagecode = vi.villagecode
        LEFT JOIN kaveri.hoblimaster ho ON vi.hoblicode = ho.hoblicode
        LEFT JOIN kaveri.talukmaster ta ON vi.talukcode = ta.talukcode
        LEFT JOIN kaveri.districtmaster di ON ta.districtcode = di.districtcode
        LEFT JOIN kaveri.propertytypemaster pt ON pm.propertytypeid = pt.propertytypeid
        LEFT JOIN kaveri.propertyschedules ps ON pm.propertyid = ps.propertyid
		LEFT JOIN kaveri.propertynumberdetails pnd ON pm.propertyid = pnd.propertyid
        WHERE pm.applicationnumber = _applicationnumber
        GROUP BY pm.propertyid, di.districtnamee, ta.taluknamee, ho.hoblinamee, vi.villagenamee, pt.propertytypename,
                 ps.eastboundary, ps.westboundary, ps.northboundary, ps.southboundary, pm.totalarea
    ) data_json;

    RETURN v_data_json;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_book1_part3_summary_json(_applicationnumber text) OWNER TO postgres;

--
-- Name: fn_fetch_cc(character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_cc(finalregistrationumber character varying) RETURNS TABLE(documentid bigint, regarticlecode integer, uploaddocdeedpath text, isrescanned boolean, referencetext character varying)
    LANGUAGE plpgsql
    AS $$
declare 
v_finalreg int;
BEGIN	

select count(finalregistrationnumber) into  v_finalreg 
from kaveri.dec_drordermaster d where d.finalregistrationnumber=finalregistrationumber and d.statuscode=4 and d.documentrescan = true;	
	
if(v_finalreg>0)
	then
	
	return query
	select 
	dd.documentid ,
	null::int as  regarticlecode ,
 	dd.rescandocument::text as uploaddocdeedpath,
	 true as isrescanned,
	null::varchar as referencetext
	from 
	kaveri.dec_drordermaster dd where dd.finalregistrationnumber=finalregistrationumber and dd.statuscode=4 and dd.documentrescan = true
	order by dd.insertdatetime desc limit 1;
	
else 
	
	return query 
	SELECT 
	dm.documentid,
    dm.regarticlecode,
    dm.uploaddocdeedpath::text,
	false AS isrescanned,
    r.referencetext
   FROM kaveri.documentmaster dm
     LEFT JOIN kaveri.referencemaster r ON r.documentid = dm.documentid
  	where dm.isdigitalsigned = true and dm.finalregistrationnumber=finalregistrationumber
  	order by dm.inserteddatetime desc limit 1;
 end if;
 end ;
$$;


ALTER FUNCTION kaveri.fn_fetch_cc(finalregistrationumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_cc_details_json_check(text); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_cc_details_json_check(_applicationnumber text) RETURNS json
    LANGUAGE plpgsql
    AS $$

/* 22-08-22 - Added phone column (Drupad)   */
declare 
v_data_json json;
BEGIN
select row_to_json(app_json) into v_data_json
from (
select b.ccid,
b.applicationnumber,
aad.currentstatus , 
c.documenttypedesc as applicationtype,
a.firstname,
a.middlename,
a.lastname,
a.pan as Adhaarnumber,
a.phone,
--b.ccnumber,
--b.ccdate,
--b.userid,
--b.documenttype,
b.documenttype as documenttypeid,
b.marriagetypeid,
g.documenttypedesc as documenttype,
--c.documenttypedesc as documenttype,
b.kaveridrocode ,
e.districtcode,
e.districtnamee as district,
b.kaverisrocode,
d.sronamee as subregistraroffice,
b.documentnumber,
b.booktype as booktypeid,
f.booknameenglish as booktype,
b.yearofregistration,
a.citizenid,
b.isprior2003,
b.finalregistrationnumber,
b.isquicksearch,
b.reason,
b.isappliedbydept,
/*b.pagecount,
b.totalamount,
b.isappliedforsignedcopy,
b.documentstatusid,
b.submittedby,
b.submitteddatetime,
b.preparedby,
b.prepareddatetime,
b.signedby,
b.signeddatetime,
b.appliedsignedcopy,
b.comparedby,
b.compareddatetime,
b.certificatenumber,
b.accepteddatetime,
b.marriagetypeid,
b.firmtypeid,*/
	( select array_to_json(array_agg(row_to_json(feesrequired)))
      from (
	   select c.serviceid,
c.ispaid,
c.requiredfeeid,
c.feeruleid,
c.payableamount,
c.feedescription from kaveri.cc_requiredfees c where c.ccid = b.ccid
	  )feesrequired) as feesrequired
	from kaveri.citizenmaster a  
    inner join kaveri.cc_applicationdetails b on  a.citizenid = b.userid
	inner join kaveri.documenttypemaster c on cast(b.documenttype as bigint) = c.documenttypeid
	inner join kaveri.sromaster d on b.kaverisrocode = d.srocode
	inner join kaveri.districtmaster e on b.kaveridrocode = e.districtcode
	inner join kaveri.booktypemaster f on cast(b.booktype as integer) = f.bookid
	inner join kaveri.documenttypemaster g on b.documenttype = g.documenttypeid
	inner join kaveri.applicantapplicationdetails aad on aad.applicationnumber  = b.applicationnumber
	
	--right JOIN kaveri.partyinfo p on p.applicationnumber::text = a.applicationnumber::text
where b.applicationnumber = _applicationnumber
) app_json ;
return v_data_json;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_cc_details_json_check(_applicationnumber text) OWNER TO csgadmin;

--
-- Name: fn_fetch_cc_receiptnumber_details_json(text); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_cc_receiptnumber_details_json(_applicationnumber text) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
begin
	select row_to_json(data_json) into v_data_json 
      from (
	         select  b.ccid,b.ccdate::date,b.applicationnumber,sum(f.payableamount)::text as Fees,c.firstname as name,c.permanentaddress as address,
        b.certificatenumber,s.sronamee as place,r.receiptnumber 
      from kaveri.citizenmaster c 
         inner join kaveri.cc_applicationdetails b  on b.userid=c.citizenid
         inner join kaveri.cc_requiredfees f on f.ccid =b.ccid 
        left join kaveri.receiptmaster r on r.applicationnumber =b.applicationnumber 
        inner join kaveri.sromaster s on s.srocode =b.kaverisrocode
         where b.applicationnumber =_applicationnumber
         --'CCA-07032023-21664'
        group by b.ccid,b.ccdate,c.firstname,c.permanentaddress,b.certificatenumber,r.receiptnumber,s.sronamee
) data_json ;
return v_data_json;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_cc_receiptnumber_details_json(_applicationnumber text) OWNER TO csgadmin;

--
-- Name: fn_fetch_challan_details(character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_challan_details(_applicationnumber character varying) RETURNS TABLE(deptreferencecode character varying, chlnrefnum character varying, amountpaid numeric, inserteddatetime timestamp without time zone, receiptid bigint)
    LANGUAGE plpgsql
    AS $$
declare 
v_address text;
BEGIN		

return query
select distinct epd.deptreferencecode,epd.chlnrefnum, Sum(epd.totalamount) as amountpaid
, epd.inserteddatetime , epd.receiptid
from kaveri.ams_reg_epaymenttransdetails epd 
left join kaveri.ams_reg_epaymentbankackdetails epa 
on epa.deptreferencecode=epd.deptreferencecode 
where applicationnumber=_applicationnumber  and epd.feerulecode in (36,58,59) 
and epa.paymentstatuscode in ('10700066','10700072') 
group by epd.deptreferencecode,epd.chlnrefnum,epd.inserteddatetime, epd.receiptid 
union
select distinct epd.deptreferencecode,epd.chlnrefnum, Sum(epd.totalamount) as amountpaid
, epd.inserteddatetime, epd.receiptid
from kaveri.ams_reg_epaymenttransdetails epd 
left join kaveri.ams_reg_epaymentbankackdetails epa 
on epa.deptreferencecode=epd.deptreferencecode 
where applicationnumber=_applicationnumber and epd.feerulecode in (110,109) 
and epa.paymentstatuscode in ('10700066','10700072') 
group by epd.deptreferencecode,epd.chlnrefnum,epd.inserteddatetime, epd.receiptid; 

end;
$$;


ALTER FUNCTION kaveri.fn_fetch_challan_details(_applicationnumber character varying) OWNER TO postgres;

