--

CREATE FUNCTION kaveri.fn_fetch_childpartydata_auth(_partyid bigint) RETURNS TABLE(partyid bigint, srocode integer, documentid bigint, partytypeid integer, firstname character varying, middlename character varying, lastname character varying, address character varying, age character varying, sex smallint, isexecutor boolean, ispresenter boolean, isorganization boolean, admissiondate timestamp without time zone, relationship character varying, relativename character varying, pan character varying, phonenumber character varying, nameasperaadhar character varying)
