ALTER FUNCTION kaveri.fn_fetch_childpartydata_auth(_partyid bigint) OWNER TO postgres;

--
-- Name: fn_fetch_citizen_dashboard(integer, timestamp without time zone, timestamp without time zone, integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_citizen_dashboard(_applicationtypeid integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _propertytypeid integer DEFAULT NULL::integer) RETURNS TABLE(applicationsreceived bigint, applicationsapproved bigint, averagetime text, mediantime text, mintime text, maxtime text)
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$


DECLARE

BEGIN	

if _applicationtypeid=1 THEN --All document registration
	return query
	select 
	count(distinct a.applicationnumber) as ApplicationsReceived,
	count(distinct case when a.currentstatus='CD120'  then a.applicationnumber end ) as ApplicationsApproved,
	CASE
  WHEN EXTRACT(month FROM justify_interval((AVG(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
    EXTRACT(month FROM justify_interval((AVG(d.registrationdatetime - d.presentdatetime))::interval)) || ' Month(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(day FROM justify_interval((AVG(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
    EXTRACT(day FROM justify_interval((AVG(d.registrationdatetime - d.presentdatetime))::interval)) || ' Day(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(hour FROM justify_interval((AVG(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
    EXTRACT(hour FROM justify_interval((AVG(d.registrationdatetime - d.presentdatetime))::interval)) || ' Hour(s) '
  ELSE ''
END ||
EXTRACT(minute FROM justify_interval((AVG(d.registrationdatetime - d.presentdatetime))::interval)) || ' Minute(s) ' as AverageTime,
CASE
  WHEN EXTRACT(month FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY d.registrationdatetime - d.presentdatetime))) > 0 THEN
    EXTRACT(month FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY d.registrationdatetime - d.presentdatetime))) || ' Month(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(day FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY d.registrationdatetime - d.presentdatetime))) > 0 THEN
    EXTRACT(day FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY d.registrationdatetime - d.presentdatetime))) || ' Day(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(hour FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY d.registrationdatetime - d.presentdatetime))) > 0 THEN
    EXTRACT(hour FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY d.registrationdatetime - d.presentdatetime))) || ' Hour(s) '
  ELSE ''
END ||
EXTRACT(minute FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY d.registrationdatetime - d.presentdatetime))) || ' Minute(s) ' as MedianTime,
CASE
  WHEN EXTRACT(month FROM justify_interval((MIN(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
    EXTRACT(month FROM justify_interval((MIN(d.registrationdatetime - d.presentdatetime))::interval)) || ' Month(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(day FROM justify_interval((MIN(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
    EXTRACT(day FROM justify_interval((MIN(d.registrationdatetime - d.presentdatetime))::interval)) || ' Day(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(hour FROM justify_interval((MIN(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
    EXTRACT(hour FROM justify_interval((MIN(d.registrationdatetime - d.presentdatetime))::interval)) || ' Hour(s) '
  ELSE ''
END ||
EXTRACT(minute FROM justify_interval((MIN(d.registrationdatetime - d.presentdatetime))::interval)) || ' Minute(s) ' as MinTime,
CASE
  WHEN EXTRACT(month FROM justify_interval((MAX(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
    EXTRACT(month FROM justify_interval((MAX(d.registrationdatetime - d.presentdatetime))::interval)) || ' Month(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(day FROM justify_interval((MAX(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
    EXTRACT(day FROM justify_interval((MAX(d.registrationdatetime - d.presentdatetime))::interval)) || ' Day(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(hour FROM justify_interval((MAX(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
    EXTRACT(hour FROM justify_interval((MAX(d.registrationdatetime - d.presentdatetime))::interval)) || ' Hour(s) '
  ELSE ''
END ||
EXTRACT(minute FROM justify_interval((MAX(d.registrationdatetime - d.presentdatetime))::interval)) || ' Minute(s) ' as max_duration
	FROM kaveri.applicantapplicationdetails a
	join Kaveri.propertymaster p on p.applicationnumber = a.applicationnumber
	join Kaveri.documentmaster d on d.applicationnumber = a.applicationnumber
	where p.propertytypeid =_propertytypeid and d.presentdatetime::date >=_fromdate 
	and d.registrationdatetime::date <=_todate and a.applicationtypeid=_applicationtypeid
 and  d.registrationdatetime is not null;
       
elsif _applicationtypeid=12 then --All CC registration
	return query
	select 
	count(distinct a.applicationnumber) as ApplicationsReceived,
	count(distinct case when a.currentstatus='CC109'  then a.applicationnumber end ) as ApplicationsApproved,
		CASE
  WHEN EXTRACT(month FROM justify_interval((AVG(a.applicationenddate - a.applicationstartdate))::interval)) > 0 THEN
    EXTRACT(month FROM justify_interval((AVG(a.applicationenddate - a.applicationstartdate))::interval)) || ' Month(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(day FROM justify_interval((AVG(a.applicationenddate - a.applicationstartdate))::interval)) > 0 THEN
    EXTRACT(day FROM justify_interval((AVG(a.applicationenddate - a.applicationstartdate))::interval)) || ' Day(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(hour FROM justify_interval((AVG(a.applicationenddate - a.applicationstartdate))::interval)) > 0 THEN
    EXTRACT(hour FROM justify_interval((AVG(a.applicationenddate - a.applicationstartdate))::interval)) || ' Hour(s) '
  ELSE ''
END ||
EXTRACT(minute FROM justify_interval((AVG(a.applicationenddate - a.applicationstartdate))::interval)) || ' Minute(s) ' as AverageTime,
CASE
  WHEN EXTRACT(month FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.applicationenddate - a.applicationstartdate))) > 0 THEN
    EXTRACT(month FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.applicationenddate - a.applicationstartdate))) || ' Month(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(day FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.applicationenddate - a.applicationstartdate))) > 0 THEN
    EXTRACT(day FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.applicationenddate - a.applicationstartdate))) || ' Day(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(hour FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.applicationenddate - a.applicationstartdate))) > 0 THEN
    EXTRACT(hour FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.applicationenddate - a.applicationstartdate))) || ' Hour(s) '
  ELSE ''
END ||
EXTRACT(minute FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.applicationenddate - a.applicationstartdate))) || ' Minute(s) ' as MedianTime,
CASE
  WHEN EXTRACT(month FROM justify_interval((MIN(a.applicationenddate - a.applicationstartdate))::interval)) > 0 THEN
    EXTRACT(month FROM justify_interval((MIN(a.applicationenddate - a.applicationstartdate))::interval)) || ' Month(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(day FROM justify_interval((MIN(a.applicationenddate - a.applicationstartdate))::interval)) > 0 THEN
    EXTRACT(day FROM justify_interval((MIN(a.applicationenddate - a.applicationstartdate))::interval)) || ' Day(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(hour FROM justify_interval((MIN(a.applicationenddate - a.applicationstartdate))::interval)) > 0 THEN
    EXTRACT(hour FROM justify_interval((MIN(a.applicationenddate - a.applicationstartdate))::interval)) || ' Hour(s) '
  ELSE ''
END ||
EXTRACT(minute FROM justify_interval((MIN(a.applicationenddate - a.applicationstartdate))::interval)) || ' Minute(s) ' as MinTime,
CASE
  WHEN EXTRACT(month FROM justify_interval((MAX(a.applicationenddate - a.applicationstartdate))::interval)) > 0 THEN
    EXTRACT(month FROM justify_interval((MAX(a.applicationenddate - a.applicationstartdate))::interval)) || ' Month(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(day FROM justify_interval((MAX(a.applicationenddate - a.applicationstartdate))::interval)) > 0 THEN
    EXTRACT(day FROM justify_interval((MAX(a.applicationenddate - a.applicationstartdate))::interval)) || ' Day(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(hour FROM justify_interval((MAX(a.applicationenddate - a.applicationstartdate))::interval)) > 0 THEN
    EXTRACT(hour FROM justify_interval((MAX(a.applicationenddate - a.applicationstartdate))::interval)) || ' Hour(s) '
  ELSE ''
END ||
EXTRACT(minute FROM justify_interval((MAX(a.applicationenddate - a.applicationstartdate))::interval)) || ' Minute(s) ' as max_duration
		FROM kaveri.applicantapplicationdetails a
--	join kaveri.documentmaster d on d.applicationnumber = a.applicationnumber
		join kaveri.cc_applicationdetails d on a.applicationnumber =d.applicationnumber 
	where a.applicationstartdate ::date >=_fromdate and a.applicationenddate ::date <=_todate and a.applicationtypeid=_applicationtypeid
 and  a.applicationstartdate is not null;	

	
elsif _applicationtypeid=13 then --All EC registration
return query
select 
	count(distinct a.applicationnumber) as ApplicationsReceived,
	count(distinct case when a.currentstatus='CE110'  then a.applicationnumber end ) as ApplicationsApproved,
		CASE
  WHEN EXTRACT(month FROM justify_interval((AVG(a.applicationenddate - a.applicationstartdate))::interval)) > 0 THEN
    EXTRACT(month FROM justify_interval((AVG(a.applicationenddate - a.applicationstartdate))::interval)) || ' Month(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(day FROM justify_interval((AVG(a.applicationenddate - a.applicationstartdate))::interval)) > 0 THEN
    EXTRACT(day FROM justify_interval((AVG(a.applicationenddate - a.applicationstartdate))::interval)) || ' Day(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(hour FROM justify_interval((AVG(a.applicationenddate - a.applicationstartdate))::interval)) > 0 THEN
    EXTRACT(hour FROM justify_interval((AVG(a.applicationenddate - a.applicationstartdate))::interval)) || ' Hour(s) '
  ELSE ''
END ||
EXTRACT(minute FROM justify_interval((AVG(a.applicationenddate - a.applicationstartdate))::interval)) || ' Minute(s) ' as AverageTime,
CASE
  WHEN EXTRACT(month FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.applicationenddate - a.applicationstartdate))) > 0 THEN
    EXTRACT(month FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.applicationenddate - a.applicationstartdate))) || ' Month(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(day FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.applicationenddate - a.applicationstartdate))) > 0 THEN
    EXTRACT(day FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.applicationenddate - a.applicationstartdate))) || ' Day(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(hour FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.applicationenddate - a.applicationstartdate))) > 0 THEN
    EXTRACT(hour FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.applicationenddate - a.applicationstartdate))) || ' Hour(s) '
  ELSE ''
END ||
EXTRACT(minute FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.applicationenddate - a.applicationstartdate))) || ' Minute(s) ' as MedianTime,
CASE
  WHEN EXTRACT(month FROM justify_interval((MIN(a.applicationenddate - a.applicationstartdate))::interval)) > 0 THEN
