		join kaveri.ec_applicationdetails d on a.applicationnumber =d.applicationnumber 
	where a.applicationstartdate ::date >=_fromdate and a.applicationenddate ::date <=_todate and a.applicationtypeid=_applicationtypeid
 and  a.applicationstartdate is not null;		
	
elsif _applicationtypeid=4 then --All marriage registration
	return query
