--EXTRACT(minute FROM justify_interval((AVG(a.applicationenddate - a.applicationstartdate))::interval)) || ' Minute(s) ' as AverageTime,

AVG(a.applicationenddate - a.applicationstartdate)::time as AverageTime,


--CASE
--  WHEN EXTRACT(month FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.applicationenddate - a.applicationstartdate))) > 0 THEN
--    EXTRACT(month FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.applicationenddate - a.applicationstartdate))) || ' Month(s) '
--  ELSE ''
--END ||
--CASE
--  WHEN EXTRACT(day FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.applicationenddate - a.applicationstartdate))) > 0 THEN
--    EXTRACT(day FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.applicationenddate - a.applicationstartdate))) || ' Day(s) '
--  ELSE ''
--END ||
--CASE
--  WHEN EXTRACT(hour FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.applicationenddate - a.applicationstartdate))) > 0 THEN
--    EXTRACT(hour FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.applicationenddate - a.applicationstartdate))) || ' Hour(s) '
--  ELSE ''
--END ||
--EXTRACT(minute FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.applicationenddate - a.applicationstartdate))) || ' Minute(s) ' as MedianTime,
--

percentile_cont(0.5) WITHIN GROUP (ORDER BY a.applicationenddate - a.applicationstartdate)::text as MedianTime,

--CASE
--  WHEN EXTRACT(month FROM justify_interval((MIN(a.applicationenddate - a.applicationstartdate))::interval)) > 0 THEN
--    EXTRACT(month FROM justify_interval((MIN(a.applicationenddate - a.applicationstartdate))::interval)) || ' Month(s) '
--  ELSE ''
--END ||
--CASE
--  WHEN EXTRACT(day FROM justify_interval((MIN(a.applicationenddate - a.applicationstartdate))::interval)) > 0 THEN
--    EXTRACT(day FROM justify_interval((MIN(a.applicationenddate - a.applicationstartdate))::interval)) || ' Day(s) '
--  ELSE ''
--END ||
--CASE
--  WHEN EXTRACT(hour FROM justify_interval((MIN(a.applicationenddate - a.applicationstartdate))::interval)) > 0 THEN
--    EXTRACT(hour FROM justify_interval((MIN(a.applicationenddate - a.applicationstartdate))::interval)) || ' Hour(s) '
--  ELSE ''
--END ||
--EXTRACT(minute FROM justify_interval((MIN(a.applicationenddate - a.applicationstartdate))::interval)) || ' Minute(s) ' as MinTime,
--

MIN(a.applicationenddate - a.applicationstartdate)::time as MinTime,

--CASE
--  WHEN EXTRACT(month FROM justify_interval((MAX(a.applicationenddate - a.applicationstartdate))::interval)) > 0 THEN
--    EXTRACT(month FROM justify_interval((MAX(a.applicationenddate - a.applicationstartdate))::interval)) || ' Month(s) '
--  ELSE ''
--END ||
--CASE
--  WHEN EXTRACT(day FROM justify_interval((MAX(a.applicationenddate - a.applicationstartdate))::interval)) > 0 THEN
--    EXTRACT(day FROM justify_interval((MAX(a.applicationenddate - a.applicationstartdate))::interval)) || ' Day(s) '
--  ELSE ''
--END ||
--CASE
--  WHEN EXTRACT(hour FROM justify_interval((MAX(a.applicationenddate - a.applicationstartdate))::interval)) > 0 THEN
--    EXTRACT(hour FROM justify_interval((MAX(a.applicationenddate - a.applicationstartdate))::interval)) || ' Hour(s) '
--  ELSE ''
--END || --applicationenddate , applicationstartdate
--EXTRACT(minute FROM justify_interval((MAX(a.applicationenddate - a.applicationstartdate))::interval)) || ' Minute(s) ' as max_duration

MAX(a.applicationenddate - a.applicationstartdate)::time as max_duration
,a.srocode		
FROM kaveri.applicantapplicationdetails a
--	join kaveri.documentmaster d on d.applicationnumber = a.applicationnumber
		join kaveri.ec_applicationdetails d on a.applicationnumber =d.applicationnumber 
	where a.applicationstartdate ::date >=_fromdate and a.applicationenddate ::date <=_todate 
	and a.applicationtypeid=_applicationtypeid
 and  a.applicationstartdate is not null and a.srocode=_srocode
group by a.srocode;		
	
elsif _applicationtypeid=4 then --All marriage registration
	return query
	select 
	count(distinct a.applicationnumber) as ApplicationsReceived,
	count(distinct case when a.currentstatus='MR115'  then a.applicationnumber end ) as ApplicationsApproved,
--		CASE
--  WHEN EXTRACT(month FROM justify_interval((AVG(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
--    EXTRACT(month FROM justify_interval((AVG(d.registrationdatetime - d.presentdatetime))::interval)) || ' Month(s) '
--  ELSE ''
--END ||
--CASE
--  WHEN EXTRACT(day FROM justify_interval((AVG(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
--    EXTRACT(day FROM justify_interval((AVG(d.registrationdatetime - d.presentdatetime))::interval)) || ' Day(s) '
--  ELSE ''
--END ||
--CASE
--  WHEN EXTRACT(hour FROM justify_interval((AVG(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
--    EXTRACT(hour FROM justify_interval((AVG(d.registrationdatetime - d.presentdatetime))::interval)) || ' Hour(s) '
--  ELSE ''
--END ||
--EXTRACT(minute FROM justify_interval((AVG(d.registrationdatetime - d.presentdatetime))::interval)) || ' Minute(s) ' as AverageTime,
--

AVG(d.registrationdatetime - d.presentdatetime)::time as AverageTime,

--CASE
--  WHEN EXTRACT(month FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY d.registrationdatetime - d.presentdatetime))) > 0 THEN
--    EXTRACT(month FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY d.registrationdatetime - d.presentdatetime))) || ' Month(s) '
--  ELSE ''
--END ||
--CASE
--  WHEN EXTRACT(day FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY d.registrationdatetime - d.presentdatetime))) > 0 THEN
--    EXTRACT(day FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY d.registrationdatetime - d.presentdatetime))) || ' Day(s) '
--  ELSE ''
--END ||
--CASE
--  WHEN EXTRACT(hour FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY d.registrationdatetime - d.presentdatetime))) > 0 THEN
--    EXTRACT(hour FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY d.registrationdatetime - d.presentdatetime))) || ' Hour(s) '
--  ELSE ''
--END ||
--EXTRACT(minute FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY d.registrationdatetime - d.presentdatetime))) || ' Minute(s) ' as MedianTime,
--

percentile_cont(0.5) WITHIN GROUP (ORDER BY d.registrationdatetime - d.presentdatetime)::text as MedianTime,

--CASE
--  WHEN EXTRACT(month FROM justify_interval((MIN(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
--    EXTRACT(month FROM justify_interval((MIN(d.registrationdatetime - d.presentdatetime))::interval)) || ' Month(s) '
--  ELSE ''
--END ||
--CASE
--  WHEN EXTRACT(day FROM justify_interval((MIN(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
--    EXTRACT(day FROM justify_interval((MIN(d.registrationdatetime - d.presentdatetime))::interval)) || ' Day(s) '
--  ELSE ''
--END ||
--CASE
--  WHEN EXTRACT(hour FROM justify_interval((MIN(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
--    EXTRACT(hour FROM justify_interval((MIN(d.registrationdatetime - d.presentdatetime))::interval)) || ' Hour(s) '
--  ELSE ''
--END ||
--EXTRACT(minute FROM justify_interval((MIN(d.registrationdatetime - d.presentdatetime))::interval)) || ' Minute(s) ' as MinTime,
--

MIN(d.registrationdatetime - d.presentdatetime)::time as MinTime,


--CASE
--  WHEN EXTRACT(month FROM justify_interval((MAX(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
--    EXTRACT(month FROM justify_interval((MAX(d.registrationdatetime - d.presentdatetime))::interval)) || ' Month(s) '
--  ELSE ''
--END ||
--CASE
--  WHEN EXTRACT(day FROM justify_interval((MAX(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
--    EXTRACT(day FROM justify_interval((MAX(d.registrationdatetime - d.presentdatetime))::interval)) || ' Day(s) '
--  ELSE ''
--END ||
--CASE
--  WHEN EXTRACT(hour FROM justify_interval((MAX(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
--    EXTRACT(hour FROM justify_interval((MAX(d.registrationdatetime - d.presentdatetime))::interval)) || ' Hour(s) '
--  ELSE ''
--END ||
--EXTRACT(minute FROM justify_interval((MAX(d.registrationdatetime - d.presentdatetime))::interval)) || ' Minute(s) ' as max_duration

MAX(d.registrationdatetime - d.presentdatetime)::time as max_duration


,a.srocode


FROM kaveri.applicantapplicationdetails a
	join kaveri.documentmaster d on d.applicationnumber = a.applicationnumber
	where d.presentdatetime::date >=_fromdate and d.registrationdatetime::date <=_todate and a.applicationtypeid=_applicationtypeid
  and  d.registrationdatetime is not null and a.srocode=_srocode
 group by a.srocode;			
	   
End if;
END;

$$;


ALTER FUNCTION kaveri.fn_fetch_citizen_dashboard_new(_applicationtypeid integer, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _propertytypeid integer) OWNER TO postgres;

--
-- Name: fn_fetch_citizenaccesslog(bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_citizenaccesslog(_citizenid bigint) RETURNS TABLE(accesscount integer, citizenexists boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
v_cnt int;
v_ccsearchnumber int;
v_bool bool;
 begin
 
 select count(*) into v_cnt from kaveri.citizenmaster where citizenid=_citizenid;
 if(v_cnt>0)
	then

	select count(d.citizenid) as ccsearchnumber into v_ccsearchnumber from kaveri.documentacceslog d
	where d.citizenid::bigint=_citizenid and d.inserteddatetime::date=current_date;

	v_bool=true;
	return query
	select v_ccsearchnumber,v_bool;
else
	v_bool=False;
	return query
	select coalesce(v_ccsearchnumber,0),v_bool;
end if;


end;
$$;


ALTER FUNCTION kaveri.fn_fetch_citizenaccesslog(_citizenid bigint) OWNER TO postgres;

--
-- Name: fn_fetch_citizenloginloginfo_new(character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_citizenloginloginfo_new(_loginname character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $$

DECLARE
	v_citizenid bigint;
	v_isactive bool;
BEGIN
	select citizenid into v_citizenid from kaveri.citizenmaster where loginname = lower(_loginname);
	select isactive into v_isactive from kaveri.citizenloginloginfo_new where citizenid = v_citizenid and isactive = true;
	
	return v_isactive;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_citizenloginloginfo_new(_loginname character varying) OWNER TO postgres;

--
-- Name: fn_fetch_closing_remarks(character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_closing_remarks(_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare
v_array character varying[];
v_stampduty numeric;
v_registrationfees numeric;
v_reasonid integer;
v_markrtvalue bigint;
v_drorderno character varying;
v_minutedate text;
v_deptreferencecode character varying;
v_transdate text;
v_endorsementtext character varying;
v_districtname character varying;
v_delaycondonefees numeric;
v_endorsementKtext character varying;
v_delaydays integer;
v_regdate text;
BEGIN	
--Get the deficit stamp duty--
select sum(b.amountpaid) into v_stampduty
from kaveri.feesrequired b where applicationnumber=_applicationnumber and b.feerulecode in (35,99,100);

--SRO market value 
select sum(p.sromarketvalue) into v_markrtvalue from kaveri.propertymaster p where p.applicationnumber =_applicationnumber; 

--Get the deficit registration fees--
select b.amountpaid into v_registrationfees
from kaveri.feesrequired b where applicationnumber=_applicationnumber and b.feerulecode = 31;

--Get the DR Order details
select a.reasonid, a.dr_order_number, to_char(a.minutedate,'dd-MM-yyyy') into v_reasonid, v_drorderno, v_minutedate 
from kaveri.minutebook_data a where a.applicationnumber = _applicationnumber;

--Get Challan Payment Details
select distinct b.deptreferencecode, to_char(ab.transactiontimestamp,'dd-MM-yyyy') transdate 
into v_deptreferencecode, v_transdate
from kaveri.ams_reg_epaymentamtpaiddetails b 
join kaveri.ams_reg_epaymentbankackdetails ab on b.deptreferencecode=ab.deptreferencecode
right outer join kaveri.feesrequired c 
on b.applicationnumber=c.applicationnumber where b.applicationnumber = _applicationnumber 
and c.feerulecode in (35,99,100,31) and b.amountpaid=c.amountpaid;

--Get the district registrar office name--
select districtnamee into v_districtname from kaveri.sromaster sm left outer join kaveri.districtmaster dm on
sm.districtcode=dm.districtcode left outer join kaveri.documentmaster docm on docm.srocode=sm.srocode
where docm.applicationnumber=_applicationnumber;

--Get Registrationdate---

select to_char(d.registrationdatetime ,'dd-MM-yyyy') into v_regdate from kaveri.documentmaster d where applicationnumber =_applicationnumber;

--Now create text based on reason id

if (v_reasonid=1) then --If Under Valuation
v_endorsementtext:=concat('As per the district registrar order No. ',v_drorderno,' dated ',v_minutedate,' the market value of rs.',v_markrtvalue,' ','the property is decided. For the difference in market value the stamp duty of Rs. ',v_stampduty,' and Reg fee of Rs. ',v_registrationfees,' Is paid vide challan No. ',v_deptreferencecode,' Date ',v_transdate,'. Hence the document is ordered for registration on',' ',v_regdate);
v_endorsementKtext:=concat('ಮಾನ್ಯ ಜಿಲ್ಲಾ ನೋಂದಣಾಧಿಕಾರಿಗಳ ಆದೇಶ ಸಂಖ್ಯೆ.',v_drorderno,'ದಿನಾಂಕ',v_minutedate,'ರಂತೆ ಸ್ವತ್ತಿಗೆ',' ',v_markrtvalue,' ','ರೂಗಳ ಮಾರುಕಟ್ಟೆ ಮೌಲ್ಯವನ್ನು ನಿಗದಿಪಡಿಸಿರುತ್ತಾರೆ. ಮಾನ್ಯ ಜಿಲ್ಲಾ ನೋಂದಣಾಧಿಕಾರಿಗಳು  ಆದೇಶದಂತೆ ವೆತ್ಯಾಸದ ಮಾರುಕಟ್ಟೆ ಮೌಲ್ಯಕ್ಕೆ ಕ್ರಮವಾಗಿ ರೂ',v_stampduty,'ಮುದ್ರಾಂಕ ಶುಲ್ಕ ಮತ್ತು  ರೂ',v_registrationfees,'ಗಳ ನೋಂದಣಿ ಶುಲ್ಕವನ್ನು ಚಲನ್ ಸಂಖ್ಯೆ',v_deptreferencecode,' ರಂತೆ ದಿನಾಂಕ',v_transdate,'  ರಂದು ಪಾವತಿಸಿ',' ',v_regdate,' ','ದಿನಾಂಕದಂದು ಉಪ ನೋಂದಣಿ ಕಛೇರಿಗೆ ಹಾಜರುಪಡಿಸಲಾಗಿದ್ದು ದಸ್ತಾವೇಜನ್ನು ನೋಂದಣಿಗೆ ಆದೇಶಿಸಿದೆ.');
elsif (v_reasonid=2) then --If Impound
v_endorsementtext:=concat('As per the district registrar order No. ',v_drorderno,' dated ',v_minutedate,' the difference of stamp duty of Rs. ',v_stampduty,' and Reg fee of Rs. ',v_registrationfees,' Is paid vide challan No. ',v_deptreferencecode,' Date ',v_transdate,'. Hence the document is ordered for registration.');
v_endorsementKtext:=concat('ಮಾನ್ಯ ಜಿಲ್ಲಾ ನೋಂದಣಾಧಿಕಾರಿಗಳ ಆದೇಶ ಸಂಖ್ಯೆಯೆ.',v_drorderno,'ದಿನಾಂಕ',v_minutedate,'ರಂತೆ  ದಸ್ತಾವೇಜನ್ನು ಪರಿಬದ್ದಗೊಳಿಸಿ ಆದೇಶಿಸಲಾಗಿದೆ .ಮಾನ್ಯ ಜಿಲ್ಲಾ ನೋಂದಣಾಧಿಕಾರಿಗಳು  ಆದೇಶದಂತೆ ವೆತ್ಯಾಸದ ರೂ',v_stampduty,',',v_registrationfees,'ಗಳ ನೋಂದಣಿ ಶುಲ್ಕವನ್ನು ಚಲನ್ ಸಂಖ್ಯೆ',v_deptreferencecode,'ರಂತೆ ದಿನಾಂಕ',v_transdate,'ರಂದು ಪಾವತಿಸಿ',v_regdate,'','. ದಿನಾಂಕದಂದು ಉಪ ನೋಂದಣಿ ಕಛೇರಿಗೆ ಹಾಜರುಪಡಿಸಲಾಗಿದ್ದು ದಸ್ತಾವೇಜನ್ನು ನೋಂದಣಿಗೆ ಆದೇಶಿಸಿದೆ.');
elsif (v_reasonid=3) then --If Delay Condonation
--Get the delay condonation fees--
select b.amountpaid into v_delaycondonefees
from kaveri.feesrequired b where applicationnumber=_applicationnumber and b.feerulecode = 28;

--Get the delayed days--
select date_part('day', presentdatetime - executiondatetime) - 122 into v_delaydays from kaveri.documentmaster where applicationnumber = _applicationnumber;

v_endorsementtext:=concat('Acceptance for registration/admission to registration was directed by the District Registrar of ',v_districtname,' in his order No. ',v_drorderno,' dated ',v_minutedate,' on payment of the fine Rs. ',v_delaycondonefees,' for a delay of ',v_delaydays,' days under Section 25/ Section 34 of the Registration Act 1908. ');
v_endorsementKtext:=concat('ನೋಂದಣಿ ಸ್ವೀಕಾರ / ಅಂಗೀಕಾರ ನೋಂದಣಿ ಕಾಯ್ದೆ 1908ರ ಪ್ರಕರಣ 25 / ಪ್ರಕರಣ 34ರ ಕೆಳಗೆ',v_delaydays,'ವಿಳಂಬಕ್ಕೆ ಶುಲ್ಕ ಮತ್ತು ದಂಡ ಒಟ್ಟು ರೂ.',v_delaycondonefees,'ಪಾವತಿಯಾದ ನಂತರ ಜಿಲ್ಲಾ ನೋಂದಣಾಧಿಕಾರಿಗಳು',v_districtname,' ರವರ ಆದೇಶ ಸಂಖ್ಯೆ',v_drorderno,'ದಿನಾಂಕ',v_minutedate,'ರಂತೆ ನೋಂದಣಿಗೆ ಸ್ವೀಕರಿಸಿದೆ /ಒಪ್ಪಿದೆ.');
elsif (v_reasonid=4) then --If Party Appearance
v_endorsementtext:='On completion of all the party appearance and admission of execution document is ordered for registration.';
v_endorsementKtext:='ಎಲ್ಲಾ ಪಕ್ಷಗಾರರು ಹಾಜರಾಗಿ ದಸ್ತಾವೇಜನ್ನು ಬರೆದು  ಕೊಟ್ಟಿದಾಗಿ ಒಪ್ಪಿಕೊಳ್ಳುತ್ತಾರೆ';
elsif (v_reasonid=5) then --If Private Attendance
v_endorsementtext:='After private appearance, the document is ordered for registration.';
v_endorsementKtext:='ಖಾಸಗಿ ಹಾಜರಾತಿಯ ನಂತರ, ದಸ್ತಾವೇಜನ್ನು ನೋಂದಣಿಗೆ ಆದೇಶಿಸಿದೆ';
end if;
v_array:=array[v_endorsementtext,v_endorsementKtext];
return array_to_json(v_array);
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_closing_remarks(_applicationnumber character varying) OWNER TO csgadmin;

--
-- Name: fn_fetch_closing_remarks_1(character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_closing_remarks_1(_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare
v_array character varying[];
v_stampduty numeric;
v_registrationfees numeric;
v_reasonid integer;
v_markrtvalue bigint;
v_drorderno character varying;
v_minutedate text;
v_deptreferencecode character varying;
v_transdate text;
v_endorsementtext character varying;
v_districtname character varying;
v_delaycondonefees numeric;
v_endorsementKtext character varying;
v_delaydays integer;
v_regdate text;
BEGIN	
--Get the deficit stamp duty--
select sum(b.amountpaid) into v_stampduty
from kaveri.feesrequired b where applicationnumber=_applicationnumber and b.feerulecode in (35,99,100);

--SRO market value 
select sum(p.sromarketvalue) into v_markrtvalue from kaveri.propertymaster p where p.applicationnumber =_applicationnumber; 

--Get the deficit registration fees--
select b.amountpaid into v_registrationfees
from kaveri.feesrequired b where applicationnumber=_applicationnumber and b.feerulecode = 31;

--Get the DR Order details
select a.reasonid, a.dr_order_number, to_char(a.minutedate,'dd-MM-yyyy') into v_reasonid, v_drorderno, v_minutedate 
from kaveri.minutebook_data a where a.applicationnumber = _applicationnumber;

--Get Challan Payment Details
select distinct b.deptreferencecode, to_char(b.inserteddatetime,'dd-MM-yyyy') transdate 
into v_deptreferencecode, v_transdate
from kaveri.ams_reg_epaymentamtpaiddetails b right outer join kaveri.feesrequired c 
on b.applicationnumber=c.applicationnumber where b.applicationnumber = _applicationnumber 
and c.feerulecode in (35,99,100,31) and b.amountpaid=c.amountpaid;

--Get the district registrar office name--
select districtnamee into v_districtname from kaveri.sromaster sm left outer join kaveri.districtmaster dm on
sm.districtcode=dm.districtcode left outer join kaveri.documentmaster docm on docm.srocode=sm.srocode
where docm.applicationnumber=_applicationnumber;

--Get Registrationdate---

select to_char(d.registrationdatetime ,'dd-MM-yyyy') into v_regdate from kaveri.documentmaster d where applicationnumber =_applicationnumber;

--Now create text based on reason id

if (v_reasonid=1) then --If Under Valuation
raise notice 'deptrefcode %',v_deptreferencecode;
v_endorsementtext:=concat('As per the district registrar order No. ',v_drorderno,' dated ',v_minutedate,' the market value of rs.',v_markrtvalue,' ','the property is decided. For the difference in market value the stamp duty of Rs. ',v_stampduty,' and Reg fee of Rs. ',v_registrationfees,' Is paid vide challan No. ',v_deptreferencecode,' Date ',v_transdate,'. Hence the document is ordered for registration on',' ',v_regdate);
v_endorsementKtext:=concat('ಮಾನ್ಯ ಜಿಲ್ಲಾ ನೋಂದಣಾಧಿಕಾರಿಗಳ ಆದೇಶ ಸಂಖ್ಯೆ.',v_drorderno,'ದಿನಾಂಕ',v_minutedate,'ರಂತೆ ಸ್ವತ್ತಿಗೆ',' ',v_markrtvalue,' ','ರೂಗಳ ಮಾರುಕಟ್ಟೆ ಮೌಲ್ಯವನ್ನು ನಿಗದಿಪಡಿಸಿರುತ್ತಾರೆ. ಮಾನ್ಯ ಜಿಲ್ಲಾ ನೋಂದಣಾಧಿಕಾರಿಗಳು  ಆದೇಶದಂತೆ ವೆತ್ಯಾಸದ ಮಾರುಕಟ್ಟೆ ಮೌಲ್ಯಕ್ಕೆ ಕ್ರಮವಾಗಿ ರೂ',v_stampduty,'ಮುದ್ರಾಂಕ ಶುಲ್ಕ ಮತ್ತು  ರೂ',v_registrationfees,'ಗಳ ನೋಂದಣಿ ಶುಲ್ಕವನ್ನು ಚಲನ್ ಸಂಖ್ಯೆ',v_deptreferencecode,' ರಂತೆ ದಿನಾಂಕ',v_transdate,'  ರಂದು ಪಾವತಿಸಿ',' ',v_regdate,' ','ದಿನಾಂಕದಂದು ಉಪ ನೋಂದಣಿ ಕಛೇರಿಗೆ ಹಾಜರುಪಡಿಸಲಾಗಿದ್ದು ದಸ್ತಾವೇಜನ್ನು ನೋಂದಣಿಗೆ ಆದೇಶಿಸಿದೆ.');
elsif (v_reasonid=2) then --If Impound
v_endorsementtext:=concat('As per the district registrar order No. ',v_drorderno,' dated ',v_minutedate,' the difference of stamp duty of Rs. ',v_stampduty,' and Reg fee of Rs. ',v_registrationfees,' Is paid vide challan No. ',v_deptreferencecode,' Date ',v_transdate,'. Hence the document is ordered for registration.');
v_endorsementKtext:=concat('ಮಾನ್ಯ ಜಿಲ್ಲಾ ನೋಂದಣಾಧಿಕಾರಿಗಳ ಆದೇಶ ಸಂಖ್ಯೆಯೆ.',v_drorderno,'ದಿನಾಂಕ',v_minutedate,'ರಂತೆ  ದಸ್ತಾವೇಜನ್ನು ಪರಿಬದ್ದಗೊಳಿಸಿ ಆದೇಶಿಸಲಾಗಿದೆ .ಮಾನ್ಯ ಜಿಲ್ಲಾ ನೋಂದಣಾಧಿಕಾರಿಗಳು  ಆದೇಶದಂತೆ ವೆತ್ಯಾಸದ ರೂ',v_stampduty,',',v_registrationfees,'ಗಳ ನೋಂದಣಿ ಶುಲ್ಕವನ್ನು ಚಲನ್ ಸಂಖ್ಯೆ',v_deptreferencecode,'ರಂತೆ ದಿನಾಂಕ',v_transdate,'ರಂದು ಪಾವತಿಸಿ',v_regdate,'','. ದಿನಾಂಕದಂದು ಉಪ ನೋಂದಣಿ ಕಛೇರಿಗೆ ಹಾಜರುಪಡಿಸಲಾಗಿದ್ದು ದಸ್ತಾವೇಜನ್ನು ನೋಂದಣಿಗೆ ಆದೇಶಿಸಿದೆ.');
elsif (v_reasonid=3) then --If Delay Condonation
--Get the delay condonation fees--
select b.amountpaid into v_delaycondonefees
from kaveri.feesrequired b where applicationnumber=_applicationnumber and b.feerulecode = 28;

--Get the delayed days--
select date_part('day', presentdatetime - executiondatetime) - 122 into v_delaydays from kaveri.documentmaster where applicationnumber = _applicationnumber;

v_endorsementtext:=concat('Acceptance for registration/admission to registration was directed by the District Registrar of ',v_districtname,' in his order No. ',v_drorderno,' dated ',v_minutedate,' on payment of the fine Rs. ',v_delaycondonefees,' for a delay of ',v_delaydays,' days under Section 25/ Section 34 of the Registration Act 1908. ');
v_endorsementKtext:=concat('ನೋಂದಣಿ ಸ್ವೀಕಾರ / ಅಂಗೀಕಾರ ನೋಂದಣಿ ಕಾಯ್ದೆ 1908ರ ಪ್ರಕರಣ 25 / ಪ್ರಕರಣ 34ರ ಕೆಳಗೆ',v_delaydays,'ವಿಳಂಬಕ್ಕೆ ಶುಲ್ಕ ಮತ್ತು ದಂಡ ಒಟ್ಟು ರೂ.',v_delaycondonefees,'ಪಾವತಿಯಾದ ನಂತರ ಜಿಲ್ಲಾ ನೋಂದಣಾಧಿಕಾರಿಗಳು',v_districtname,' ರವರ ಆದೇಶ ಸಂಖ್ಯೆ',v_drorderno,'ದಿನಾಂಕ',v_minutedate,'ರಂತೆ ನೋಂದಣಿಗೆ ಸ್ವೀಕರಿಸಿದೆ /ಒಪ್ಪಿದೆ.');
elsif (v_reasonid=4) then --If Party Appearance
v_endorsementtext:='On completion of all the party appearance and admission of execution document is ordered for registration.';
v_endorsementKtext:='ಎಲ್ಲಾ ಪಕ್ಷಗಾರರು ಹಾಜರಾಗಿ ದಸ್ತಾವೇಜನ್ನು ಬರೆದು  ಕೊಟ್ಟಿದಾಗಿ ಒಪ್ಪಿಕೊಳ್ಳುತ್ತಾರೆ';
elsif (v_reasonid=5) then --If Private Attendance
v_endorsementtext:='After private appearance, the document is ordered for registration.';
v_endorsementKtext:='ಖಾಸಗಿ ಹಾಜರಾತಿಯ ನಂತರ, ದಸ್ತಾವೇಜನ್ನು ನೋಂದಣಿಗೆ ಆದೇಶಿಸಿದೆ';
end if;
v_array:=array[v_endorsementtext,v_endorsementKtext];
return array_to_json(v_array);
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_closing_remarks_1(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_courtorder_details(integer, integer, integer, character varying, integer, character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_courtorder_details(_srocode integer, _villagecode integer, _propertytypeid integer, _propertytynumber character varying, _surveyno integer DEFAULT NULL::integer, _hissano character varying DEFAULT NULL::character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$


declare 
v_data_json json;
--v_surveyhisno json;

--v_courtdetalsh json ;

begin
--	select row_to_json(app_json_d) into v_surveyhisno from (
--	select e.survey_no,e.hissa_no from kaveri.bannedpropertynumbers e 
--	join kaveri.bannedproperties b on e.propertyid=b.propertyid 
--	where e.survey_no =_surveyno and e.hissa_no=_hissano and b.villagecode=_villagecode
--	)app_json_d;

if(_surveyno is  null or _hissano is null or _propertytypeid<>1 )  then
	
--RETURN QUERY
select array_to_json(array_agg(row_to_json(courtorder)))
from (
	
	select distinct co.ordernumber as "ordernumber", co.issuingauthority, 
co.issueddate, concat(co.description,'; Area:', bp.area) as "description", '' as "casetype" 
FROM kaveri.courtorders co
JOIN kaveri.bannedpropertynumbers bpn ON co.courtorderid = bpn.orderid AND co.srocode = bpn.srocode
JOIN kaveri.bannedproperties bp ON bpn.orderid = bp.orderid  
where bp.villagecode=_villagecode and bpn.currentnumber=_propertytynumber
and bpn.currentpropertytypeid=_propertytypeid and co.isinforce = true AND co.iscancelled = false
	
	/*select c.ordernumber, c.issuingauthority, c.issueddate, c.description, c.casetype 
	  from kaveri.courtorders c join kaveri.bannedpropertynumbers a on c.courtorderid=a.orderid and c.srocode=a.srocode
join
kaveri.bannedproperties b on a.orderid =b.orderid and b.srocode=a.srocode and b.courtpropertyid=a.propertyid
where a.srocode=_srocode and a.currentpropertytypeid=_propertytypeid and a.currentnumber=_propertytynumber 
and b.villagecode=_villagecode and c.isinforce=true and c.iscancelled=False*/
) courtorder into v_data_json;
	  

elseif(_surveyno is not null or _hissano is not null or _propertytypeid=1) 
then

select array_to_json(array_agg(row_to_json(courtorder)))
from (
	
/*	select c.ordernumber, c.issuingauthority, c.issueddate, c.description, c.casetype from kaveri.courtorders c join
kaveri.bannedpropertynumbers a on c.courtorderid=a.orderid and c.srocode=a.srocode
join
kaveri.bannedproperties b on a.orderid =b.orderid and b.srocode=a.srocode and b.courtpropertyid=a.propertyid 
where a.srocode=_srocode and a.survey_no =_surveyno and a.hissa_no=_hissano 
and b.villagecode=_villagecode and c.isinforce=true and c.iscancelled=False
*/
	
select distinct co.ordernumber as "ordernumber", co.issuingauthority, 
co.issueddate, concat(co.description,'; Area:', bp.area) as "description", '' as "casetype" 
FROM kaveri.courtorders co
JOIN kaveri.bannedpropertynumbers bpn ON co.courtorderid = bpn.orderid AND co.srocode = bpn.srocode
JOIN kaveri.bannedproperties bp ON bpn.orderid = bp.orderid  
where bp.villagecode=_villagecode and (bpn.survey_no=_surveyno
										or bpn.currentnumber=cast(_surveyno as character varying))
and bpn.currentpropertytypeid=_propertytypeid and co.isinforce = true AND co.iscancelled = false
) courtorder into v_data_json;

end if;

return v_data_json;
end
$$;


ALTER FUNCTION kaveri.fn_fetch_courtorder_details(_srocode integer, _villagecode integer, _propertytypeid integer, _propertytynumber character varying, _surveyno integer, _hissano character varying) OWNER TO csgadmin;

--
-- Name: fn_fetch_courtorder_propertytype_json(text); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_courtorder_propertytype_json(p_applicationnumber text) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
v_propertytypeid integer;
v_applicationnumber text;
BEGIN
--select propertytypeid into v_propertytypeid from kaveri.propertytypemaster where propertytypeid = p_propertytypeid;
--if (v_propertytypeid = 20) and (v_applicationnumber = p_applicationnumber) then
select row_to_json(app_json) into v_data_json
from (
	   select array_to_json(array_agg(row_to_json(agri)))
      from (SELECT applicationnumber,
    propertyid,
    sro,
    court_order_number,
    injuction_or_stay_flag,
    survey_no,
    currentnumber,
    oldnumber,
    eastboundary,
    westboundary,
    northboundary,
    southboundary,
    area,
    description AS court_order_details,
    currentpropertytypeid,
    oldpropertytypeid,
    hissa_no,
    propertytypename, 
	--end if;
--if (v_propertytypeid = 28) and (v_applicationnumber = p_applicationnumber) then
	 ( select array_to_json(array_agg(row_to_json(Non_Agriculture)))
      from (select applicationnumber,
    propertyid,
    sro,
    court_order_number,
    injuction_or_stay_flag,
    survey_no,
    currentnumber,
    oldnumber,
    eastboundary,
    westboundary,
    northboundary,
    southboundary,
    area,
    description AS court_order_details,
    currentpropertytypeid,
    oldpropertytypeid,
    hissa_no--,
    --propertytypename 
			from kaveri.vw_court_order_non_agri where 
			currentpropertytypeid = 20 and applicationnumber = p_applicationnumber
) Non_Agriculture) as nonagri
from kaveri.vw_fetch_court_order_details
where currentpropertytypeid = 17 and applicationnumber = p_applicationnumber)agri
)app_json;
--end if;
return v_data_json;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_courtorder_propertytype_json(p_applicationnumber text) OWNER TO csgadmin;

--
-- Name: fn_fetch_ctzen_dshbrd_new(integer, timestamp without time zone, timestamp without time zone, integer, bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_ctzen_dshbrd_new(_applicationtypeid integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _propertytypeid integer DEFAULT NULL::integer, _srocode bigint DEFAULT NULL::bigint) RETURNS TABLE(applicationsreceived numeric, applicationsapproved numeric, applicationspending numeric, averagetime interval, mediantime interval, mintime interval, maxtime interval, male numeric, female numeric, other numeric)
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$


DECLARE
v_datediff int;

BEGIN	
	
--v_datediff:=(_todate::date-_fromdate::date);

if(_srocode is not null)	
then	
return query
select coalesce(sum(c.applicationsreceived),0) as applicationsreceived
,coalesce(sum(c.applicationsapproved),0) as applicationsapproved
,coalesce(sum(c.applicationspending),0) as  applicationspending
,avg(c.averagetime) as averagetime 
,percentile_cont(0.5) WITHIN GROUP (ORDER BY c.mediantime) as mediantime
,min(c.mintime) as mintime
,max(c.maxtime) as maxtime
,coalesce(sum(c.male),0) as male
,coalesce(sum(c.female),0) as female
,coalesce(sum(c.transgender),0) as other
from kaveri.citizendashboard c 
where applicationtypeid =_applicationtypeid and fromdate>=_fromdate
	and todate<=_todate and propertytypeid=coalesce(_propertytypeid,0)
	and srocode=_srocode;
else
return query
select coalesce(sum(c.applicationsreceived),0) as applicationsreceived
,coalesce(sum(c.applicationsapproved),0) as applicationsapproved
,coalesce(sum(c.applicationspending),0) as  applicationspending
,avg(c.averagetime) as averagetime 
,percentile_cont(0.5) WITHIN GROUP (ORDER BY c.mediantime) as mediantime
,min(c.mintime) as mintime
,max(c.maxtime) as maxtime
,coalesce(sum(c.male),0) as male
,coalesce(sum(c.female),0) as female
,coalesce(sum(c.transgender),0) as other
from kaveri.citizendashboard c 
where applicationtypeid =_applicationtypeid and fromdate>=_fromdate
	and todate<=_todate and propertytypeid=coalesce(_propertytypeid,0);
	
end if;
END;

$$;


