-- Name: fn_fetch_cvc_reports(character varying, bigint, bigint, bigint, bigint, bigint, bigint, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_cvc_reports(_status character varying, _srocode bigint DEFAULT NULL::bigint, _roadcode bigint DEFAULT NULL::bigint, _villagecode bigint DEFAULT NULL::bigint, _hoblicode bigint DEFAULT NULL::bigint, _talukcode bigint DEFAULT NULL::bigint, _districtcode bigint DEFAULT NULL::bigint, _from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _to_date timestamp without time zone DEFAULT NULL::timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(srocode integer, sronamee character varying, districtcode integer, districtnamee character varying, talukcode integer, taluknamee character varying, hoblicode integer, hoblinamee character varying, villagecode bigint, villagenamee character varying, roadcode bigint, roadnamee character varying, roadnamek character varying, propertytypeid integer, propertytypename character varying, agrilandtypenamee character varying, oldrate numeric, newrate numeric, measurementcode integer, measurementnamee character varying, effectivedate text, circularyear integer, circularinfo text, roadaddedby text, roadrejby text, remarks text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	

if (pagenumber<>-1 and pagesize<>-1) then
PageOffset := ((pagenumber - 1) * pagesize);
return query
with cte as (select 
		distinct 
		s.srocode,
		s.sronamee,
		d.districtcode,
		d.districtnamee,
		t.talukcode,
		t.taluknamee,
		h.hoblicode,
		h.hoblinamee,
		v.villagecode,
		v.villagenamee,
		mvd.roadcode,
		r.roadnamee,
		r.roadnamek,
		mvd.propertytypeid,
		p.propertytypename,
		a.agrilandtypenamee,
		case when mvd.roadcode in (select r3.roadcode from kaveri.rateagriculturaldetail r3 ) and mvd.agrilandtypeid = r2.agrilandtypeid then r2.rate
        	 when mvd.roadcode in (select o.roadcode from kaveri.openbuiltratedetail o ) and mvd.propertytypeid = o.propertytypeid then o.rate
        	 when mvd.roadcode in (select mvf2.roadid from kaveri.mas_val_flatrates mvf2 ) and mvd.propertytypeid = mvf.propertytypeid then mvf.rate
        end as oldrate,
        case when mvd.roadcode in (select r3.roadcode from kaveri.rateagriculturaldetail r3) and mvd.agrilandtypeid = r2.agrilandtypeid then mvd.rate
        	 when mvd.roadcode in (select o.roadcode from kaveri.openbuiltratedetail o) and mvd.propertytypeid = o.propertytypeid then mvd.rate
        	 when mvd.roadcode in (select mvf2.roadid from kaveri.mas_val_flatrates mvf2) and mvd.propertytypeid = mvf.propertytypeid then mvd.rate   
        end as newrate,
        m.measurementcode,
		m.measurementnamee,
		to_char(mv.effectivedate, 'dd-mm-yyyy') as effectivedate,
		mv.circularyear,
		mv.circularinfo,
		d1.firstname as roadaddedby,
		d2.firstname as roadapprorejby,
		mvd.remarks	
from kaveri.mas_valratedetail mvd
join kaveri.mas_valrateheader mv on mv.valrateheaderid = mvd.valrateheaderid 
inner join kaveri.measurementmaster m on m.measurementcode = mvd.unitid
left join kaveri.rateagriculturaldetail r2 on mvd.roadcode = r2.roadcode and mvd.agrilandtypeid = r2.agrilandtypeid
left join kaveri.openbuiltratedetail o on mvd.roadcode = o.roadcode and mvd.propertytypeid = o.propertytypeid
left join kaveri.mas_val_flatrates mvf on mvf.roadid = mvd.roadcode and mvd.propertytypeid = mvf.propertytypeid
join kaveri.propertytypemaster p on p.propertytypeid = mvd.propertytypeid
join kaveri.roadmaster r on mvd.roadcode = r.roadcode
inner join kaveri.villagemaster v on r.villagecode = v.villagecode
left join kaveri.agrilandtypemaster a on a.agrilandtypeid = mvd.agrilandtypeid 
join kaveri.sromaster s on s.srocode = v.srocode and mvd.srocode = s.srocode
join kaveri.hoblimaster h on h.hoblicode = v.hoblicode 
join kaveri.talukmaster t on t.talukcode = v.talukcode 
join kaveri.districtmaster d on t.districtcode = d.districtcode
left join kaveri.departmentusers d1 on d1.userid = mv.sfdaid
left join kaveri.departmentusers d2 on mv.updatedby::bigint = d2.userid
where

(CASE when _from_date is not null and _to_date is not null then mv.effectivedate between _from_date and(_to_date + interval '1 day')
else true end)
and 
(CASE WHEN _status is not null THEN mvd.isapproved = _status::boolean   
ELSE mvd.isapproved is null END )
and 
(CASE WHEN _srocode is not null THEN mvd.srocode = _srocode ELSE true END)
and 
(CASE WHEN _roadcode is not null THEN mvd.roadcode = _roadcode ELSE true END)
and
(CASE WHEN _villagecode is not null THEN r.villagecode = _villagecode ELSE true END)
and 
(case WHEN _hoblicode is not null THEN h.hoblicode = _hoblicode ELSE true END)
and 
(case WHEN _talukcode is not null THEN t.talukcode = _talukcode ELSE true END)
and
(CASE WHEN _districtcode is not null THEN  d.districtcode = _districtcode ELSE true END)
),cte_count as (select count(*) as total_rows from cte)
   select * from cte
   right join (select total_rows from cte_count) total_row on true
   where total_row.total_rows<>0  OFFSET PageOffset 
				FETCH NEXT pagesize ROWS ONLY;

elsif (pagenumber=-1 or  pagesize=-1) then 

return query
with cte as (select 
		distinct 
		s.srocode,
		s.sronamee,
		d.districtcode,
		d.districtnamee,
		t.talukcode,
		t.taluknamee,
		h.hoblicode,
		h.hoblinamee,
		v.villagecode,
		v.villagenamee,
		mvd.roadcode,
		r.roadnamee,
		r.roadnamek,
		mvd.propertytypeid,
		p.propertytypename,
		a.agrilandtypenamee,
		case when mvd.roadcode in (select r3.roadcode from kaveri.rateagriculturaldetail r3 ) and mvd.agrilandtypeid = r2.agrilandtypeid then r2.rate
        	 when mvd.roadcode in (select o.roadcode from kaveri.openbuiltratedetail o ) and mvd.propertytypeid = o.propertytypeid then o.rate
        	 when mvd.roadcode in (select mvf2.roadid from kaveri.mas_val_flatrates mvf2 ) and mvd.propertytypeid = mvf.propertytypeid then mvf.rate
        end as oldrate,
        case when mvd.roadcode in (select r3.roadcode from kaveri.rateagriculturaldetail r3) and mvd.agrilandtypeid = r2.agrilandtypeid then mvd.rate
        	 when mvd.roadcode in (select o.roadcode from kaveri.openbuiltratedetail o) and mvd.propertytypeid = o.propertytypeid then mvd.rate
        	 when mvd.roadcode in (select mvf2.roadid from kaveri.mas_val_flatrates mvf2) and mvd.propertytypeid = mvf.propertytypeid then mvd.rate   
        end as newrate,
        m.measurementcode,
		m.measurementnamee,
		to_char(mv.effectivedate, 'dd-mm-yyyy') as effectivedate,
		mv.circularyear,
		mv.circularinfo,
		d1.firstname as roadaddedby,
		d2.firstname as roadapprorejby,
		mvd.remarks	
from kaveri.mas_valratedetail mvd
join kaveri.mas_valrateheader mv on mv.valrateheaderid = mvd.valrateheaderid 
inner join kaveri.measurementmaster m on m.measurementcode = mvd.unitid
left join kaveri.rateagriculturaldetail r2 on mvd.roadcode = r2.roadcode and mvd.agrilandtypeid = r2.agrilandtypeid
left join kaveri.openbuiltratedetail o on mvd.roadcode = o.roadcode and mvd.propertytypeid = o.propertytypeid
left join kaveri.mas_val_flatrates mvf on mvf.roadid = mvd.roadcode and mvd.propertytypeid = mvf.propertytypeid
join kaveri.propertytypemaster p on p.propertytypeid = mvd.propertytypeid
join kaveri.roadmaster r on mvd.roadcode = r.roadcode
inner join kaveri.villagemaster v on r.villagecode = v.villagecode
left join kaveri.agrilandtypemaster a on a.agrilandtypeid = mvd.agrilandtypeid 
join kaveri.sromaster s on s.srocode = v.srocode and mvd.srocode = s.srocode
join kaveri.hoblimaster h on h.hoblicode = v.hoblicode 
join kaveri.talukmaster t on t.talukcode = v.talukcode 
join kaveri.districtmaster d on t.districtcode = d.districtcode
left join kaveri.departmentusers d1 on d1.userid = mv.sfdaid
left join kaveri.departmentusers d2 on mv.updatedby::bigint = d2.userid
where

(CASE when _from_date is not null and _to_date is not null then mv.effectivedate between _from_date and(_to_date + interval '1 day')
else true end)
and 
(CASE WHEN _status is not null THEN mvd.isapproved = _status::boolean ELSE true END)
and 
(CASE WHEN _srocode is not null THEN mvd.srocode = _srocode ELSE true END)
and 
(CASE WHEN _roadcode is not null THEN mvd.roadcode = _roadcode ELSE true END)
and 
(CASE WHEN _villagecode is not null THEN r.villagecode = _villagecode ELSE true  END )  
and 
(case WHEN _hoblicode is not null THEN h.hoblicode = _hoblicode ELSE true END)
and
(case WHEN _talukcode is not null THEN t.talukcode = _talukcode ELSE true END)  
and 
(CASE WHEN _districtcode is not null THEN d.districtcode = _districtcode ELSE true END)
)
select cte.*,null::bigint as totalcount from cte;

end if;
end;
$$;


ALTER FUNCTION kaveri.fn_fetch_cvc_reports(_status character varying, _srocode bigint, _roadcode bigint, _villagecode bigint, _hoblicode bigint, _talukcode bigint, _districtcode bigint, _from_date timestamp without time zone, _to_date timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO postgres;

