CREATE FUNCTION kaveri.fn_fetch_cvc_reports_18102023(_status character varying, _srocode bigint DEFAULT NULL::bigint, _roadcode bigint DEFAULT NULL::bigint, _villagecode bigint DEFAULT NULL::bigint, _hoblicode bigint DEFAULT NULL::bigint, _talukcode bigint DEFAULT NULL::bigint, _districtcode bigint DEFAULT NULL::bigint, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(roadcode bigint, roadnamee character varying, roadnamek character varying, srocode integer, sronamee character varying, villagecode bigint, villagenamee character varying, hoblicode integer, hoblinamee character varying, talukcode integer, taluknamee character varying, districtcode integer, districtnamee character varying, roadaddedby text, roadrejby text, remarks text, newrate numeric, oldrate numeric, propertytypeid integer, propertytypename character varying, effectivedate timestamp without time zone, circularinfo text, circularyear integer, measurementcode integer, measurementnamee character varying)
    LANGUAGE plpgsql
    AS $$


DECLARE
PageOffset INTEGER := 0;
BEGIN   
PageOffset := ((pagenumber - 1) * pagesize);

    if( _status = 'true' and _srocode is not null) then
return query
select distinct mvd.roadcode,
        r.roadnamee,
        r.roadnamek,
        s.srocode,
        s.sronamee,
        v.villagecode,
        v.villagenamee,
        h.hoblicode,
        h.hoblinamee,
        t.talukcode,
        t.taluknamee,
        d.districtcode,
        d.districtnamee,
        d1.firstname as roadaddedby,
        d2.firstname as roadapprorejby,
        mvd.remarks,
--        mvd.rate as newrate,
        case when mvd.agrilandtypeid = r2.agrilandtypeid then mvd.rate 
             when mvd.propertytypeid = o.propertytypeid then mvd.rate
             when mvd.propertytypeid = mvf.propertytypeid then mvd.rate
             end as newrate,
        case when mvd.agrilandtypeid = r2.agrilandtypeid then r2.rate 
             when mvd.propertytypeid = o.propertytypeid then o.rate
             when mvd.propertytypeid = mvf.propertytypeid then mvf.rate
             end as oldrate,
        mvd.propertytypeid,
        p.propertytypename,
        mv.effectivedate,
        mv.circularinfo,
        mv.circularyear,
        m.measurementcode,
        m.measurementnamee
from kaveri.mas_valratedetail mvd
left join kaveri.mas_valrateheader mv on mv.valrateheaderid = mvd.valrateheaderid 
inner join kaveri.measurementmaster m on m.measurementcode = mvd.unitid
left join kaveri.rateagriculturaldetail r2 on mvd.roadcode = r2.roadcode
left join kaveri.openbuiltratedetail o on mvd.roadcode = o.roadcode 
left join kaveri.mas_val_flatrates mvf on mvf.roadid = mvd.roadcode
inner join kaveri.propertytypemaster p on p.propertytypeid = mvd.propertytypeid
left join kaveri.roadmaster r on mvd.roadcode = r.roadcode
inner join kaveri.villagemaster v on r.villagecode = v.villagecode
left join kaveri.sromaster s on s.srocode = v.srocode and mvd.srocode = s.srocode
left join kaveri.hoblimaster h on h.hoblicode = v.hoblicode 
left join kaveri.talukmaster t on t.talukcode = v.talukcode 
left join kaveri.districtmaster d on t.districtcode = d.districtcode
left join kaveri.departmentusers d1 on d1.userid = mvd.sfdaid
left join kaveri.departmentusers d2 on mvd.updatedby::bigint = d2.userid
where mvd.isapproved = _status::boolean
and mvd.srocode = _srocode
--and mvd.roadcode = _roadcode;
--and v.villagecode = _villagecode; 
--and h.hoblicode = _hoblicode;
--and t.talukcode = _talukcode;
--and d.districtcode = _districtcode;
OFFSET PageOffset   
FETCH NEXT pagesize ROWS ONLY;

elseif ( _status = 'false' and _srocode is not null) then
return query
select distinct mvd.roadcode,
        r.roadnamee,
        r.roadnamek,
