        	 when mvd.roadcode in (select o.roadcode from kaveri.openbuiltratedetail o) and mvd.propertytypeid = o.propertytypeid then mvd.rate
        	 when mvd.roadcode in (select mvf2.roadid from kaveri.mas_val_flatrates mvf2) and mvd.propertytypeid = mvf.propertytypeid then mvd.rate   
        end as newrate,
        case when mvd.roadcode in (select r3.roadcode from kaveri.rateagriculturaldetail r3) and mvd.agrilandtypeid = r2.agrilandtypeid then r2.rate
        	 when mvd.roadcode in (select o.roadcode from kaveri.openbuiltratedetail o) and mvd.propertytypeid = o.propertytypeid then o.rate
        	 when mvd.roadcode in (select mvf2.roadid from kaveri.mas_val_flatrates mvf2) and mvd.propertytypeid = mvf.propertytypeid then mvf.rate
        end as oldrate,     
        mvd.propertytypeid,
        p.propertytypename,
        mv.effectivedate,
        mv.circularinfo,
        mv.circularyear,
        m.measurementcode,
        m.measurementnamee,
        r3.regionname,
        a.agrilandtypenamee,
        case when r.roadcode in (select r5.roadcode from kaveri.rateagriculturaldetail r5 union 
        						 select o5.roadcode from kaveri.openbuiltratedetail o5 union 
        						 select mvf5.roadid from kaveri.mas_val_flatrates mvf5) then 'Yes'::character varying
        else 'No'::character varying end as Newroad_YN,
        mvd.updateddate
from kaveri.mas_valratedetail mvd
left join kaveri.mas_valrateheader mv on mv.valrateheaderid = mvd.valrateheaderid 
inner join kaveri.measurementmaster m on m.measurementcode = mvd.unitid
left join kaveri.rateagriculturaldetail r2 on mvd.roadcode = r2.roadcode and mvd.agrilandtypeid = r2.agrilandtypeid 
left join kaveri.openbuiltratedetail o on mvd.roadcode = o.roadcode and mvd.propertytypeid = o.propertytypeid 
left join kaveri.mas_val_flatrates mvf on mvf.roadid = mvd.roadcode and mvd.propertytypeid = mvf.propertytypeid 
left join kaveri.propertytypemaster p on p.propertytypeid = mvd.propertytypeid
left join kaveri.agrilandtypemaster a on a.agrilandtypeid = r2.agrilandtypeid
left join kaveri.roadmaster r on mvd.roadcode = r.roadcode
left join kaveri.regionmaster r3 on r3.regionid = r.regionid 
left join kaveri.villagemaster v on r.villagecode = v.villagecode
left join kaveri.sromaster s on s.srocode = v.srocode and mvd.srocode = s.srocode
left join kaveri.hoblimaster h on h.hoblicode = v.hoblicode 
left join kaveri.talukmaster t on t.talukcode = v.talukcode 
left join kaveri.districtmaster d on t.districtcode = d.districtcode
left join kaveri.departmentusers d1 on d1.userid = mvd.sfdaid
left join kaveri.departmentusers d2 on mvd.updatedby::bigint = d2.userid
where  case when (_status = 'true' and _srocode is not null) then mvd.isapproved = _status::boolean and mvd.srocode = _srocode 
	    when (_status = 'false' and _srocode is not null) then mvd.isapproved = _status::boolean and mvd.srocode = _srocode 
	    when (_status is null and _srocode is not null) then mvd.isapproved is null and mvd.srocode = _srocode 
	    when (_status = 'true' and _roadcode is not null) then mvd.isapproved = _status::boolean and mvd.roadcode = _roadcode 
	    when (_status = 'false' and _roadcode is not null) then mvd.isapproved = _status::boolean and mvd.roadcode = _roadcode 
	    when (_status is null and _roadcode is not null) then mvd.isapproved is null and mvd.roadcode = _roadcode 
	    when (_status = 'true' and _villagecode is not null) then mvd.isapproved = _status::boolean and r.villagecode = _villagecode 
	    when (_status = 'false' and _villagecode is not null) then mvd.isapproved = _status::boolean and r.villagecode = _villagecode 
	    when (_status is null and _villagecode is not null) then mvd.isapproved is null and r.villagecode = _villagecode 
	    when (_status = 'true' and _hoblicode is not null) then mvd.isapproved = _status::boolean and h.hoblicode = _hoblicode 
	    when (_status = 'false' and _hoblicode is not null) then mvd.isapproved = _status::boolean and h.hoblicode = _hoblicode 
	    when (_status is null and _hoblicode is not null) then mvd.isapproved is null and h.hoblicode = _hoblicode 
	    when (_status = 'true' and _talukcode is not null) then mvd.isapproved = _status::boolean and t.talukcode = _talukcode 
	    when (_status = 'false' and _talukcode is not null) then mvd.isapproved = _status::boolean and t.talukcode = _talukcode 
	    when (_status is null and _talukcode is not null) then mvd.isapproved is null and t.talukcode = _talukcode 
	    when (_status = 'true' and _districtcode is not null) then mvd.isapproved = _status::boolean and d.districtcode = _districtcode 
	    when (_status = 'false' and _districtcode is not null) then mvd.isapproved = _status::boolean and d.districtcode = _districtcode 
	    when (_status is null and _districtcode is not null) then mvd.isapproved is null and d.districtcode = _districtcode end)
	   ,cte_count as (select count(*) as total_rows from cte)
select * from cte
right join (select total_rows from cte_count) total_row on true 
OFFSET PageOffset
FETCH NEXT pagesize ROWS ONLY;

elsif (pagenumber=-1 or  pagesize=-1) then
return query
with cte as (select distinct mvd.roadcode,
        r.roadnamee,
        r.roadnamek,
        s.srocode,
        s.sronamee,
        v.villagecode,
        v.villagenamee,
        h.hoblicode,
        h.hoblinamee,
        t.talukcode,
        t.taluknamee,
        d.districtcode,
        d.districtnamee,
        d1.firstname as roadaddedby,
        d2.firstname as roadapprorejby,
        mvd.remarks,
        case when mvd.roadcode in (select r3.roadcode from kaveri.rateagriculturaldetail r3) and mvd.agrilandtypeid = r2.agrilandtypeid then mvd.rate
        	 when mvd.roadcode in (select o.roadcode from kaveri.openbuiltratedetail o) and mvd.propertytypeid = o.propertytypeid then mvd.rate
        	 when mvd.roadcode in (select mvf2.roadid from kaveri.mas_val_flatrates mvf2) and mvd.propertytypeid = mvf.propertytypeid then mvd.rate   
        end as newrate,
        case when mvd.roadcode in (select r3.roadcode from kaveri.rateagriculturaldetail r3) and mvd.agrilandtypeid = r2.agrilandtypeid then r2.rate
        	 when mvd.roadcode in (select o.roadcode from kaveri.openbuiltratedetail o) and mvd.propertytypeid = o.propertytypeid then o.rate
        	 when mvd.roadcode in (select mvf2.roadid from kaveri.mas_val_flatrates mvf2) and mvd.propertytypeid = mvf.propertytypeid then mvf.rate
        end as oldrate,     
        mvd.propertytypeid,
        p.propertytypename,
        mv.effectivedate,
        mv.circularinfo,
        mv.circularyear,
        m.measurementcode,
        m.measurementnamee,
        r3.regionname,
        a.agrilandtypenamee,
        case when r.roadcode in (select r5.roadcode from kaveri.rateagriculturaldetail r5 union 
        						 select o5.roadcode from kaveri.openbuiltratedetail o5 union 
        						 select mvf5.roadid from kaveri.mas_val_flatrates mvf5) then 'Yes'::character varying
        else 'No'::character varying end as Newroad_YN,
        mvd.updateddate
from kaveri.mas_valratedetail mvd
left join kaveri.mas_valrateheader mv on mv.valrateheaderid = mvd.valrateheaderid 
inner join kaveri.measurementmaster m on m.measurementcode = mvd.unitid
left join kaveri.rateagriculturaldetail r2 on mvd.roadcode = r2.roadcode and mvd.agrilandtypeid = r2.agrilandtypeid 
left join kaveri.openbuiltratedetail o on mvd.roadcode = o.roadcode and mvd.propertytypeid = o.propertytypeid 
left join kaveri.mas_val_flatrates mvf on mvf.roadid = mvd.roadcode and mvd.propertytypeid = mvf.propertytypeid 
left join kaveri.propertytypemaster p on p.propertytypeid = mvd.propertytypeid
left join kaveri.agrilandtypemaster a on a.agrilandtypeid = r2.agrilandtypeid
left join kaveri.roadmaster r on mvd.roadcode = r.roadcode
left join kaveri.regionmaster r3 on r3.regionid = r.regionid 
left join kaveri.villagemaster v on r.villagecode = v.villagecode
left join kaveri.sromaster s on s.srocode = v.srocode and mvd.srocode = s.srocode
left join kaveri.hoblimaster h on h.hoblicode = v.hoblicode 
left join kaveri.talukmaster t on t.talukcode = v.talukcode 
left join kaveri.districtmaster d on t.districtcode = d.districtcode
left join kaveri.departmentusers d1 on d1.userid = mvd.sfdaid
left join kaveri.departmentusers d2 on mvd.updatedby::bigint = d2.userid
where  case when (_status = 'true' and _srocode is not null) then mvd.isapproved = _status::boolean and mvd.srocode = _srocode 
	    when (_status = 'false' and _srocode is not null) then mvd.isapproved = _status::boolean and mvd.srocode = _srocode 
	    when (_status is null and _srocode is not null) then mvd.isapproved is null and mvd.srocode = _srocode 
	    when (_status = 'true' and _roadcode is not null) then mvd.isapproved = _status::boolean and mvd.roadcode = _roadcode 
	    when (_status = 'false' and _roadcode is not null) then mvd.isapproved = _status::boolean and mvd.roadcode = _roadcode 
	    when (_status is null and _roadcode is not null) then mvd.isapproved is null and mvd.roadcode = _roadcode 
	    when (_status = 'true' and _villagecode is not null) then mvd.isapproved = _status::boolean and r.villagecode = _villagecode 
	    when (_status = 'false' and _villagecode is not null) then mvd.isapproved = _status::boolean and r.villagecode = _villagecode 
	    when (_status is null and _villagecode is not null) then mvd.isapproved is null and r.villagecode = _villagecode 
	    when (_status = 'true' and _hoblicode is not null) then mvd.isapproved = _status::boolean and h.hoblicode = _hoblicode 
	    when (_status = 'false' and _hoblicode is not null) then mvd.isapproved = _status::boolean and h.hoblicode = _hoblicode 
	    when (_status is null and _hoblicode is not null) then mvd.isapproved is null and h.hoblicode = _hoblicode 
	    when (_status = 'true' and _talukcode is not null) then mvd.isapproved = _status::boolean and t.talukcode = _talukcode 
	    when (_status = 'false' and _talukcode is not null) then mvd.isapproved = _status::boolean and t.talukcode = _talukcode 
	    when (_status is null and _talukcode is not null) then mvd.isapproved is null and t.talukcode = _talukcode 
	    when (_status = 'true' and _districtcode is not null) then mvd.isapproved = _status::boolean and d.districtcode = _districtcode 
	    when (_status = 'false' and _districtcode is not null) then mvd.isapproved = _status::boolean and d.districtcode = _districtcode 
	    when (_status is null and _districtcode is not null) then mvd.isapproved is null and d.districtcode = _districtcode end)
select cte.*,null::bigint as totalcount from cte;
--select * from cte
--right join (select total_rows from cte_count) total_row on true;
end if;

end;
$$;


