--
-- Name: fn_fetch_cvcopeningclosing(bigint, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_cvcopeningclosing(_srocode bigint DEFAULT NULL::bigint, _from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _to_date timestamp without time zone DEFAULT NULL::timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(id bigint, sronamee character varying, opendate date, closedate date, extendedcloserdate date, remark character varying, isenabled boolean, entrydoneby bigint, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
begin

if (pagenumber<>-1 and pagesize<>-1) then
PageOffset := ((pagenumber - 1) * pagesize);
return query
with cte as (select c.id, s.sronamee ,c.opendate::date,c.closedate::date, c.extendedcloserdate::date, c.remark ,c.isenabled , c.entrydoneby from kaveri.cvcopeningclosing c 
join kaveri.sromaster s on s.srocode = c.srocode
where c.srocode = _srocode and  (c.opendate >= _from_date or c.closedate >= _from_date or c.extendedcloserdate >= _from_date) and 
((c.opendate <= _to_date or c.closedate <= _to_date or c.extendedcloserdate <= _to_date))),
cte_count as (select count(*) as total_rows from cte)
select * from cte
right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
FETCH NEXT pagesize ROWS ONLY;

elsif (pagenumber=-1 or  pagesize=-1) then
PageOffset := ((pagenumber - 1) * pagesize);
return query
with cte as (select c.id, s.sronamee ,c.opendate::date,c.closedate::date, c.extendedcloserdate::date, c.remark ,c.isenabled , c.entrydoneby from kaveri.cvcopeningclosing c 
join kaveri.sromaster s on s.srocode = c.srocode
where c.srocode = _srocode and  (c.opendate >= _from_date or c.closedate >= _from_date or c.extendedcloserdate >= _from_date) and 
((c.opendate <= _to_date or c.closedate <= _to_date or c.extendedcloserdate <= _to_date)))
select cte.*,null::bigint as totalcount from cte;

end if;

end;
$$;


ALTER FUNCTION kaveri.fn_fetch_cvcopeningclosing(_srocode bigint, _from_date timestamp without time zone, _to_date timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_cvcopeningclosing_lasteditedby_lastediteddate(timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_cvcopeningclosing_lasteditedby_lastediteddate(_from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _to_date timestamp without time zone DEFAULT NULL::timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(id bigint, sronamee character varying, opendate date, closedate date, remark character varying, extendedcloserdate date, isenabled boolean, entrydoneby bigint, entrydate date, lasteditedby bigint, lastediteddate date, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
begin

if (pagenumber<>-1 and pagesize<>-1) then
PageOffset := ((pagenumber - 1) * pagesize);
return query
with cte as (select c.id, s.sronamee ,c.opendate::date,c.closedate::date, c.remark , c.extendedcloserdate::date,c.isenabled , c.entrydoneby,c.entrydate::date,
			 c.lasteditedby,c.lastediteddate::date from kaveri.cvcopeningclosing c 
join kaveri.sromaster s on s.srocode = c.srocode
where inserteddatetime::date >= _from_date and inserteddatetime:: date <=_to_date),
cte_count as (select count(*) as total_rows from cte)
select * from cte
right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
FETCH NEXT pagesize ROWS ONLY;

elsif (pagenumber=-1 or  pagesize=-1) then
PageOffset := ((pagenumber - 1) * pagesize);
return query
with cte as (select c.id, s.sronamee ,c.opendate::date,c.closedate::date,c.remark , c.extendedcloserdate::date, c.isenabled , c.entrydoneby,c.entrydate::date
			 ,c.lasteditedby,c.lastediteddate::date from kaveri.cvcopeningclosing c 
join kaveri.sromaster s on s.srocode = c.srocode
where inserteddatetime::date >= _from_date and inserteddatetime:: date <=_to_date)
select cte.*,null::bigint as totalcount from cte;

end if;

end;
$$;


