--
-- Name: fn_fetch_digilockerdoctype(character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_digilockerdoctype(_finalregistrationnumber character varying) RETURNS TABLE(digilockid integer, doctype character varying)
    LANGUAGE plpgsql
    AS $$
begin
	
	return query
	select dg.id as digilockid,dg.doctype from kaveri.documentmaster d
	join kaveri.propertymaster p on d.applicationnumber = p.applicationnumber 
	join kaveri.stampdigilockrelation st on st.stamparticlecode = p.stamparticlecode 
	join kaveri.digilockerdoctypemaster dg on st.digilocker_id = dg.id
	where d.finalregistrationnumber = _finalregistrationnumber limit 1;
end;
$$;


ALTER FUNCTION kaveri.fn_fetch_digilockerdoctype(_finalregistrationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_district_taluk_hob_village_name(bigint, bigint, bigint, bigint); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_district_taluk_hob_village_name(_districtcode bigint, _talukcode bigint, _hoblicode bigint, _villagecode bigint) RETURNS TABLE(kaveridistrictnamee character varying, kaveritaluknamee character varying, kaverihobliname character varying, kaverivillagename character varying, bhoomidistrictnamee character varying, bhoomitaluknamee character varying, bhoomihobliname character varying, bhoomivillagename character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN   

 
-- select 
--dsm.districtnamee as kaveridistrictname,
--tm.taluknamee as kaveritalukname,
--hm.hoblinamee as kaverihobliname,
--v.villagenamee as kaverivillagename,
--b.districtnamee as bhoomidistrictname,
--btk.talukaname as bhoomitalukname,
--btm.villagename as bhoomivillagename,
--btm.hobliname as bhoomihobliname
--from 
--kaveri.villagemaster v 
--join kaveri.talukmaster tm on tm.talukcode = v.talukcode
--join kaveri.hoblimaster hm on hm.hoblicode = v.hoblicode
--join kaveri.districtmaster dsm on dsm.districtcode = tm.districtcode
--join kaveri.bhoomimappingdetails b on  b.kaverivillagecode=v.villagecode
--join kaveri.bhoomitalukamapping btm on  btm.villagecode = v.villagecode
--join kaveri.bhoomitaluk btk on btk.talukacode=btm.talukacode
 return query	
 select 
dsm.districtnamee as kaveridistrictname,
tm.taluknamee as kaveritalukname,
hm.hoblinamee as kaverihobliname,
v.villagenamee as kaverivillagename,
