--
-- Name: fn_fetch_doc_ec_cc_dashboard_stats(); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_doc_ec_cc_dashboard_stats() RETURNS json
    LANGUAGE plpgsql
    AS $$

 

DECLARE 
v_data_json json;


BEGIN	 

	 
select row_to_json(data_json) into v_data_json from (

select array_to_json(array_agg(row_to_json(dashboard)))  

from (

--select
--	distinct a.district_code,
--	a.district_name,
--	sum(a.document_regs) as document_regs_dist ,
--	sum(a.document_revenue) as document_revenue_dist ,
--	sum(a.ec_apps) as ec_apps_dist ,
--	sum(a.ec_revenue) as ec_revenue_dist ,
--	sum(a.cc_apps) as cc_apps_dist ,
--	sum(a.cc_revenue) as cc_revenue_dist ,
--	jsonb_agg(distinct  jsonb_build_object('sro_code',
--	a.sro_code,
--	'sro_name',
--	a.sro_name,
--	'document_regs',
--	document_regs,
--	'document_revenue',
--	document_revenue,
--	'ec_apps',
--	ec_apps,
--	'ec_revenue',
--	ec_revenue,
--	'cc_apps',
--	cc_apps,
--	'cc_revenue',
--	cc_revenue )) as sro_details
--from
--	kaveri.daily_dashboard_apps_revenue_details a
--group by
--	a.district_code,
--	a.district_name



WITH aggregated_data AS (
    SELECT
        district_code,
        sro_code,
        sum(document_regs) AS document_regs_dist,
        sum(document_revenue) AS document_revenue_dist,
        sum(ec_apps) AS ec_apps_dist,
        sum(ec_revenue) AS ec_revenue_dist,
        sum(cc_apps) AS cc_apps_dist,
        sum(cc_revenue) AS cc_revenue_dist
    FROM
        kaveri.daily_dashboard_apps_revenue_details
    GROUP BY
        district_code,
        sro_code
)
SELECT
    DISTINCT a.district_code,
    a.district_name,
    sum(document_regs) AS document_regs_dist,
        sum(document_revenue) AS document_revenue_dist,
        sum(ec_apps) AS ec_apps_dist,
        sum(ec_revenue) AS ec_revenue_dist,
        sum(cc_apps) AS cc_apps_dist,
        sum(cc_revenue) AS cc_revenue_dist,
    jsonb_agg(
        DISTINCT jsonb_build_object(
        
        		'sro_code', a.sro_code,
                'sro_name', a.sro_name,
                'document_regs', agg_data.document_regs_dist,
                'document_revenue', agg_data.document_revenue_dist,
                'ec_apps', agg_data.ec_apps_dist,
                'ec_revenue', agg_data.ec_revenue_dist,
                'cc_apps', agg_data.cc_apps_dist,
                'cc_revenue', agg_data.cc_revenue_dist
        )
    ) as sro_details
FROM
    kaveri.daily_dashboard_apps_revenue_details a
JOIN
    aggregated_data agg_data ON a.district_code = agg_data.district_code AND a.sro_code = agg_data.sro_code
GROUP BY
    a.district_code,
    a.district_name



) dashboard

) data_json;
return v_data_json;
	END;
$$;


ALTER FUNCTION kaveri.fn_fetch_doc_ec_cc_dashboard_stats() OWNER TO postgres;

