--
-- Name: fn_fetch_doc_path_bucket_ref(text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_doc_path_bucket_ref(_doc_path text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_cnt int;
	v_bucketname varchar;
begin

	select count(*) into v_cnt from kaveri.doc_path_bucket_ref where doc_path = _doc_path;
	if v_cnt>0 then
	select bucketname into v_bucketname from kaveri.doc_path_bucket_ref where doc_path = _doc_path;
	else 
	v_bucketname :='';
--	insert into kaveri.doc_path_bucket_ref(doc_path,bucketname) values(_doc_path,_bucketname) 
--	returning bucketname into v_bucketname;
	end if;
Return v_bucketname;
end;
$$;


ALTER FUNCTION kaveri.fn_fetch_doc_path_bucket_ref(_doc_path text) OWNER TO postgres;

--
-- Name: fn_fetch_document_party_details(text, bigint); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_document_party_details(_applicationnumber text, _srocode bigint) RETURNS TABLE(applicationtypeid integer, finalregistrationnumber character varying, executiondatetime timestamp without time zone, pendingdocumentnumber character varying, book character varying, registrationdatetime timestamp without time zone, noofscanpages integer, applicationtype character varying, sroname character varying, partyinfo json)
    LANGUAGE plpgsql
    AS $$

declare 

BEGIN
return query
select ad.applicationtypeid,dm.finalregistrationnumber,
dm.executiondatetime executiondatetime,
dm.pendingdocumentnumber,bm.printablename as book,
dm.registrationdatetime registrationdatetime,
pm.sronoofscanpages as noofscnpages,svm.servicename as applicationtype,
sm.sronamee as sroname,
(
      select array_to_json(array_agg(row_to_json(prty)))
      from (

select 
applicationnumber,partyid,name as partyname,age, address ,profession,
phonenumber,epic,partytypeid,partytypename,isexecutor,ispresenter,admissiondate,
section88exemption,fingerid,thumbpath,photopath,idprooftypedesc,idproofnumber,
relationship,relativename,
isEndorsePrinted,gender as sex,
isprivateattendance,
vw_party.coveringletterno,thumbremarks 
from kaveri.vw_fetch_party vw_party 
			where vw_party.applicationnumber = ad.applicationnumber and
			vw_party.partytypeid in (1,2) order by partytypeid) prty
    ) as partyinfo

from kaveri.documentmaster dm 
inner join kaveri.sromaster sm on sm.srocode = dm.srocode 
inner join kaveri.applicantapplicationdetails ad ON ad.srocode = sm.srocode
inner join kaveri.partyinfo pi on pi.srocode = sm.srocode
inner join kaveri.propertymaster pm on pm.propertyid = pi.propertyid
inner join kaveri.servicesmaster svm on svm.serviceid = ad.applicationtypeid
left join kaveri.booktypemaster bm on (bm.bookid=dm.bookid) 
where  ad.applicationnumber = _applicationnumber and ad.srocode=_srocode;

END;
$$;


ALTER FUNCTION kaveri.fn_fetch_document_party_details(_applicationnumber text, _srocode bigint) OWNER TO csgadmin;

--
-- Name: fn_fetch_document_registration_dashboard_count(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_document_registration_dashboard_count(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$

 

DECLARE 
PageOffset INTEGER := 0;
v_data_json json;
v_fromdate date;
v_todate date;

BEGIN	 
--PageOffset := ((pagenumber - 1) * pagesize);
PageOffset := (pagesize*pagenumber) - pagesize;
v_fromdate :=_fromdate;
v_todate :=_todate;
	 
select array_to_json(array_agg(row_to_json(dashboard)))   into v_data_json 

from (select distinct  to_char(current_date,'DD-MM-YYYY') as current_date, s.sronamee, s.srocode,
concat(to_char(v_fromdate,'DD-MM-YYYY'),' - ',to_char(v_todate,'DD-MM-YYYY'))as date_range, d.districtcode,d.districtnamee,  

count(distinct case when a.currentstatus in ('CD102') then a.applicationnumber else null end) as Received_from_Citizen,  

count(distinct case when a.currentstatus in ('CD103') then a.applicationnumber else null end) as Allocated_to_SDA_FDA,  

count(distinct case when a.currentstatus in ('CD104') then a.applicationnumber else null end) as Received_from_SDA_FDA,  

count(distinct case when a.currentstatus in ('CD106') then a.applicationnumber else null end) as Sent_to_citizen_for_confirmation,  

count(distinct case when a.currentstatus in ('CD108') then a.applicationnumber else null end) as Received_from_citizen_after_confirmation,  

count(distinct case when a.currentstatus in ('CD110') then a.applicationnumber else null end) as Allocated_to_DEO_for_Biometric,  

count(distinct case when a.currentstatus in ('CD111') then a.applicationnumber else null end) as Received_from_DEO_after_Biometric_with_Summary,  

count(distinct case when a.currentstatus in ('CD112') then a.applicationnumber else null end) as Allocated_to_DEO_for_Printing_with_scanning,  

--count(distinct case when a.currentstatus in ('CD112') then a.applicationnumber else null end) as Allocated_to_DEO_for_Printing_with_scanning,	  

count(distinct case when a.currentstatus in ('CD115') then a.applicationnumber else null end) as Received_for_digi_sign,  

count(distinct case when a.currentstatus in ('CD116') then a.applicationnumber else null end) as Sent_to_FDA_SDA_for_Acknowledgement  

from kaveri.applicantapplicationdetails a  

join kaveri.sromaster s on s.srocode = a.srocode  -- and s.districtcode =_districtcode

join kaveri.districtmaster d on d.districtcode = s.districtcode  

where a.applicationtypeid in (1,2) 

--and a.applicationstartdate::date >=_fromdate and a.applicationstartdate::date <=_todate

and (case when _fromdate is not null and _todate is not null then a.applicationstartdate::date between _fromdate

             and _todate

                     else true 

             end)



and 
 (case when _districtcode <> 0 then s.districtcode = _districtcode
					else
						true
				end)
				
and (case when _srocode<>0 then s.srocode =_srocode
					else 
						true
				end)
				

group by  d.districtcode,d.districtnamee, s.sronamee, s.srocode --, a.applicationnumber
order by d.districtnamee asc)as dashboard


limit pagesize offset PageOffset;

return v_data_json; 

END; 

$$;


ALTER FUNCTION kaveri.fn_fetch_document_registration_dashboard_count(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_documentsummary(text); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_documentsummary(_applicationnumber text) RETURNS json
    LANGUAGE plpgsql
    AS $_$



declare 
v_data_json1 json;
BEGIN

select row_to_json(app_json) into v_data_json1
from (

  select ad.applicationnumber,dm.executiondatetime::date executedate,
  dm.presentdatetime as presentdate,
regexp_replace(dm.pendingdocumentnumber, '^([^-]*-[^-]*)-.*$', '\1') as pendingdocumentnumber ,
	dm.finalregistrationnumber,dm.registrationdatetime,dm.isPrintEndorsement,
	dm.pagecount ,sa.articlenamee as stamparticlename,ad.annexurepath,dm.partypaymentdetails,
ra.articlenamee as Naturedeed, bm.printablename as book,sm.servicename as applicationtype,
	ad.remarks,
	ad.remarksk,
	ss.sronamee as sroname ,--- To fetch the Kannada text added on 28-11-2022
	ss.sronamek as sronamek,
	ad.currentstatus,dm.isscancompleted,ad.applicationtypeid,md.remark_comment,md.reasonid,md.private_remark,ad.refuseremarks, 
	string_agg(bh.acknowledgeno,',') as Ysavednumber,
	string_agg(ee.acknowledgeno,',') as acknowledgeno,md.isbefore2003,  
     (
      select array_to_json(array_agg(row_to_json(prpty)))
      from (SELECT pm.applicationnumber,	  
			pm.propertyid,
			pm.documentid,
			stm.articlenamee as stamparticle,
			pm.ismovableproperty,
			d.villagenamee,
			pm.propertytypeid,
			ptm.propertytypename as propertytype,
			c.sronamee sroname,
			pm.northboundary,
			pm.denodescription ,
			pm.estampdescription,
			pm.adjudescription ,
			pm.southboundary,
			pm.eastboundary,
			pm.westboundary,
			pm.landmark,
			pm.consideration,
			pm.marketvalue,
			pm.sroconsideration,
			case when pm.sromarketvalue is null then 0 else pm.sromarketvalue end sromarketvalue,
			pm.cessduty,
			pm.govtduty,
			pm.additionalduty,
			pm.stampduty,
			pm.valid1 as duplicatecopies,
			calc.duplicatefee,
			calc.duplicatestampduty,
			calc.duplicateregistrationfee,
			calc.privateattendancefee,
			--calc.stampduty, 		
			pm.valuationreport,
			pm.sronoofscanpages, /* added a new column on 07/10/2022 to fetch number of scan pages in document summary page */
			sr.ismarketvaluationdone, /* added a new column on 06/11/2022 */
			h.hoblinamee as hobli, /* added a new column on 06/11/2022 */
			srf.ispartytopropertyschd, /* added a new column on 07/11/2022 */
			zn.departmentname as zonenamee,
			( select array_to_json(array_agg(row_to_json(schd)))
			  from (
			/*  select ps.propertyid as propertyschedulespropertyid,ps.scheduletype,ps.totalarea,
			  ps.description as scheduledescription,
					case when pm.propertytypeid=17 then
					string_agg(pi.name,',') else null end as bhoomisellerparty ,

					pi.name, pi.ispresenter, pi.isexecutor			

					from kaveri.propertyschedules ps 
					left join kaveri.vw_fetch_party pi on (pi.propertyid = ps.propertyid 
					and pi.applicationnumber=ps.applicationnumber
						)
				   where ps.propertyid = pm.propertyid 
					group by ps.propertyid ,ps.scheduletype,ps.totalarea,ps.description,			
				  pi.name, pi.ispresenter, pi.isexecutor	*/

				  select distinct ps.propertyid as propertyschedulespropertyid, 
						ps.scheduletype, 
						ps.totalarea,
					string_agg(pi.name,',') as bhoomisellername
					, pnam.firstname as name
					, ps.description as scheduledescription,
					case when pm.propertytypeid=17 then string_agg(pi.name,',') else null end as bhoomisellerparty,
					ps.eastboundary, ps.westboundary, ps.northboundary, ps.southboundary
				  from kaveri.propertyschedules ps 
				  left join kaveri.vw_fetch_party pi on ps.applicationnumber=pi.applicationnumber and pi.propertyid = ps.propertyid
				  left join (select ps1.scheduleid, array_to_string(array_agg(distinct pi2.name),',') AS firstname from kaveri.partyschedules ps1
					left join (select name,partyid from kaveri.vw_fetch_party vf where vf.applicationnumber = _applicationnumber ) as pi2 on pi2.partyid = ps1.partyid
						where ps1.applicationnumber =_applicationnumber
							group by ps1.scheduleid)
				  as pnam on ps.scheduleid = pnam.scheduleid
				  where  ps.propertyid = pm.propertyid 
				  group by ps.propertyid, ps.scheduletype, ps.totalarea, pnam.firstname, ps.description, ps.eastboundary,
				  ps.westboundary, ps.northboundary, ps.southboundary)schd ) as propertyschedules,			
			  ( select array_to_json(array_agg(row_to_json(prptyno)))
			   from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,
					 pntm.typenameenglish as propertynumbertype, pnd.currentnumber, coalesce(pnd.hissa_no,'') as hissa_no,
					 coalesce(pnd.survey_no,0) as survey_no, pnd.description as propertynumberdescription
					from kaveri.propertynumberdetails pnd 
					 left join kaveri.propertynotypemaster pntm on (pntm.propertytypeid = pnd.currentpropertytypeid) 
					 where pnd.propertyid = pm.propertyid )prptyno ) as propertynumberdetails
		   FROM kaveri.propertymaster pm 
		   left join kaveri.propertytypemaster ptm on (ptm.propertytypeid = pm.propertytypeid) 
			left join kaveri.stamparticles stm on (stm.stamparticlecode=pm.stamparticlecode)
			left join kaveri.integrationdepartment zn on (pm.zoneid=zn.udeptid)
			left join kaveri.stamprules sr on pm.stampruleid = sr.stampruleid
			left join kaveri.stamprulesflag srf ON sr.stampruleid = srf.stampruleid
		   left join  kaveri.sromaster c on (pm.srocode = c.srocode)
		   left join kaveri.villagemaster d on (pm.villagecode = d.villagecode)
			left join kaveri.hoblimaster h on d.hoblicode = h.hoblicode
		   left join kaveri.vw_fee_calculation_details_chk_v2 calc on (pm.applicationnumber = calc.applicationnumber)
		   where pm.applicationnumber=ad.applicationnumber) prpty
    ) as propertyinfo,	
	 (
      select array_to_json(array_agg(row_to_json(prty)))
      from (
		select 
		vw_party.applicationnumber,vw_party.partyid,case when (vw_party.aliasname='' or vw_party.aliasname is null)  then  vw_party.name else CONCAT(vw_party.name,', alias:',vw_party.aliasname) end  as partyname,vw_party.age, vw_party.address ,vw_party.profession,
		vw_party.phonenumber,vw_party.epic,vw_party.partytypeid,vw_party.partytypename,vw_party.isexecutor,vw_party.ispresenter,vw_party.admissiondate,
		vw_party.section88exemption,vw_party.fingerid,vw_party.thumbpath,vw_party.photopath,vw_party.idprooftypedesc,vw_party.idproofnumber,
		vw_party.relationship,vw_party.relativename,string_agg(wi.name||' '||wi.middlename||' '||wi.lastname,',') as witness_name ,
		/*isorganization, tanno, organizationid, yearofincorp, linkpartyid, auname, auaddress,
		 aualiasname, 
		auage, ausex, auidprooftypeid, auidprooftypedesc, auidproofnumber, auprofession,
		 poaisorganization,
		poaname, poaaddress, poaage, poasex, poaidproofnumber, poatan, poaprofession,
		 poarelationship, 
		poarelativename,poaidprooftypedesc, poapartytypename, poayearofincorp, 
		orgpoaauthsignfname, orgpoaauthsignmname, orgpoaauthsignlname, minorguardianname,
		 minorguardianage,
		minorguardianrelationship, minorguardianrelativename,*/
		vw_party.isEndorsePrinted,vw_party.gender as sex, vw_party.isorganization, vw_party.tanno, vw_party.minorguardianname, vw_party.poaname,
		vw_party.auname, vw_party.auaddress, vw_party.isprivateattendance, vw_party.coveringletterno, vw_party.thumbremarks,vw_party.ispartyrefused,
		sl.descriptione,vw_party.islateapperance,vw_party.isbiometricrefused,vw_party.iscitizennotappeared,
		(select row_to_json(aadhar)
		from (select aal.partyid,aal.nameasperaadhar,
		case when aal.partyid is not null 
			then
				case when aal.responsestatus = 'Y' then true 
				 	when aal.responsestatus = 'N' then false
			when aal.partyid is null then null end
		end as aadharverified
		,aal.errormessage from kaveri.aadhar_authentication_log aal
		where aal.partyid = vw_party.partyid 
		order by aal.id desc limit 1)aadhar)as aadharinfo
		from kaveri.vw_fetch_party vw_party 
		left join kaveri.partywitness pw on pw.partyid in (select partyid from kaveri.partyinfo where applicationnumber =_applicationnumber)
		left join  kaveri.salutationmaster sl on vw_party.salutationid=sl.salutationid
		left join kaveri.witnessinfo wi on pw.witnessid = wi.witnessid 
			where vw_party.applicationnumber = ad.applicationnumber
			group by vw_party.applicationnumber,vw_party.applicationnumber,vw_party.partyid,vw_party.name ,vw_party.age, vw_party.address ,vw_party.profession,
		vw_party.phonenumber,vw_party.epic,vw_party.partytypeid,vw_party.partytypename,vw_party.isexecutor,vw_party.ispresenter,vw_party.admissiondate,
		vw_party.section88exemption,vw_party.fingerid,vw_party.thumbpath,vw_party.photopath,vw_party.idprooftypedesc,vw_party.idproofnumber,
		vw_party.relationship,vw_party.relativename,vw_party.isEndorsePrinted,vw_party.gender, vw_party.isorganization, vw_party.tanno, vw_party.minorguardianname, vw_party.poaname,
		vw_party.auname, vw_party.auaddress, vw_party.isprivateattendance, vw_party.coveringletterno, vw_party.thumbremarks,vw_party.ispartyrefused
		,vw_party.aliasname,sl.descriptione,vw_party.islateapperance,vw_party.isbiometricrefused,vw_party.iscitizennotappeared
			order by partytypeid) prty
    ) as partyinfo,
	(  select array_to_json(array_agg(row_to_json(witness)))
      from (select wi.witnessid, wi.name, wi.houseno, concat(wi.address,' ',d.districtnamee,' ',g.taluknamee,' ',s.statenamee) as address,
			wi.age,wi.applicationnumber,wi."name",r.relatione as relation,wi.relativename,
			/* added a columns houseno, address, pincode and necessary joins for the same, on 07/11/2022 */
			/* Removed above changes, on 07/11/2022 */
			/*(wi.address::text || ', '::text) || (tal.taluknamee::text || ', '::text) || (dis.districtnamee::text || ', '::text) || (st.statenamee::text) || ' '::text AS address,*/
			wi.pincode, wi.age, wi.profession, wi.isEndorsePrinted, wi.sex 
			from kaveri.witnessinfo wi
			left join kaveri.relationshipmasters r on wi.relation::int =r.id 
			JOIN kaveri.lgd_districtmaster d ON d.districtcode = wi.districtcode
    		 JOIN kaveri.lgd_statemaster s ON d.lgdstatecode = s.statecode
     		JOIN kaveri.lgd_talukmaster g ON g.talukcode = wi.talukcode
			/*left join kaveri.lgd_districtmaster dis ON dis.districtcode = wi.districtcode
			left join kaveri.lgd_statemaster st ON st.statecode  = wi.statecode
			left join kaveri.lgd_talukmaster tal ON tal.talukcode = wi.talukcode*/
			where wi.applicationnumber = ad.applicationnumber) witness
	) as witnessinfo,
	md.ispendingdocument  as ispendingdocument,
	(case when fds.valuatiotypeid=1 then true else false end) as isundervaluation,
	(case when fds.valuatiotypeid=3 then true else false end) as isimpound,
	(case when dm.executiondatetime::date<(now()- interval '4 months')::date then true else false end) as isdelaycondonation 
  from kaveri.applicantapplicationdetails ad
inner join kaveri.documentmaster dm on (ad.applicationnumber=dm.applicationnumber)
left join kaveri.minutebook_data md on (md.applicationnumber=ad.applicationnumber)
left join (select distinct applicationnumber,valuatiotypeid from kaveri.feesrequired fd where fd.applicationnumber=_applicationnumber) as fds on fds.applicationnumber=ad.applicationnumber 
 join kaveri.servicesmaster sm on (sm.serviceid = ad.applicationtypeid)
 join kaveri.booktypemaster bm on (bm.bookid=dm.bookid)
left join kaveri.stamparticles sa on (sa.stamparticlecode=dm.stamparticlecode)
left join kaveri.registrationarticles ra on (ra.regarticlecode=dm.regarticlecode)
left join kaveri.bhoomifileuploaddetails bh on (dm.finalregistrationnumber = bh.finalregistrationnumber)
left join kaveri.easthi_eswathu_fileuploaddetails ee on (dm.finalregistrationnumber =ee.finalregistrationnumber )
inner join kaveri.sromaster ss on ss.srocode=ad.srocode
  where ad.applicationnumber = _applicationnumber 
  group by ad.applicationnumber,dm.executiondatetime,
  dm.presentdatetime ,
	dm.finalregistrationnumber,dm.registrationdatetime,dm.isPrintEndorsement,
	dm.pagecount ,sa.articlenamee ,ad.annexurepath,dm.partypaymentdetails,
ra.articlenamee , bm.printablename ,sm.servicename ,
	ad.remarks,fds.valuatiotypeid,dm.executiondatetime,
	ad.remarksk,ss.sronamee,ss.sronamek, --- To fetch the Kannada text added on 28-11-2022
	ad.currentstatus,dm.isscancompleted,ad.applicationtypeid,md.remark_comment,md.reasonid ,md.private_remark,ad.refuseremarks,dm.pendingdocumentnumber,md.ispendingdocument,md.isbefore2003
) app_json ;

return v_data_json1;

END;
$_$;


ALTER FUNCTION kaveri.fn_fetch_documentsummary(_applicationnumber text) OWNER TO csgadmin;

--
-- Name: fn_fetch_documentsummary_json(text, bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_documentsummary_json(_applicationnumber text, _srocode bigint) RETURNS json
    LANGUAGE plpgsql
    AS $_$



declare 
v_data_json1 json;
BEGIN

select row_to_json(app_json) into v_data_json1
from (

  select ad.applicationnumber,dm.executiondatetime::date executedate,
  dm.presentdatetime as presentdate,
regexp_replace(dm.pendingdocumentnumber, '^([^-]*-[^-]*)-.*$', '\1') as pendingdocumentnumber ,
 dm.finalregistrationnumber,dm.registrationdatetime,dm.isPrintEndorsement,
 dm.pagecount ,sa.articlenamee as stamparticlename,dm.regarticlecode,ad.annexurepath,dm.partypaymentdetails,
ra.articlenamee as Naturedeed, bm.printablename as book,sm.servicename as applicationtype,
 ad.remarks,
 ad.remarksk,
 ss.sronamee as sroname ,--- To fetch the Kannada text added on 28-11-2022
 ss.sronamek as sronamek,
 -- paperless change
 d.districtnamee,
 d.districtnamek,
 dp.firstname||'('||substring(dp.loginname,1,4)||')' as deoname,
 ad.currentstatus,dm.isscancompleted,ad.applicationtypeid,md.remark_comment,md.reasonid,md.private_remark,ad.refuseremarks, 
 string_agg(bh.acknowledgeno,',') as Ysavednumber,
 string_agg(ee.acknowledgeno,',') as acknowledgeno,md.isbefore2003,
 -- paperless change
 dm.isdigitalsigned,
     (
      select array_to_json(array_agg(row_to_json(prpty)))
      from (SELECT pm.applicationnumber,   
   pm.propertyid,
   pm.documentid,
   stm.articlenamee as stamparticle,
   sr.descriptione as subarticle,
   pm.ismovableproperty,
   d.villagenamee,
   pm.propertytypeid,
   ptm.propertytypename as propertytype,
   c.sronamee sroname,
   pm.northboundary,
   pm.denodescription ,
   pm.estampdescription,
   pm.adjudescription ,
   pm.southboundary,
   pm.eastboundary,
   pm.westboundary,
   pm.landmark,
   pm.consideration,
   pm.marketvalue,
   pm.sroconsideration,
   case when pm.sromarketvalue is null then 0 else pm.sromarketvalue end sromarketvalue,
   pm.cessduty,
   pm.govtduty,
   pm.additionalduty,
   pm.stampduty,
   pm.valid1 as duplicatecopies,
   calc.duplicatefee,
   calc.duplicatestampduty,
   calc.duplicateregistrationfee,
   calc.privateattendancefee,
   --calc.stampduty,   
   pm.valuationreport,
   pm.sronoofscanpages, /* added a new column on 07/10/2022 to fetch number of scan pages in document summary page */
   sr.ismarketvaluationdone, /* added a new column on 06/11/2022 */
   h.hoblinamee as hobli, /* added a new column on 06/11/2022 */
   srf.ispartytopropertyschd, /* added a new column on 07/11/2022 */
   ( select array_to_json(array_agg(row_to_json(schd)))
     from (
   /*  select ps.propertyid as propertyschedulespropertyid,ps.scheduletype,ps.totalarea,
     ps.description as scheduledescription,
     case when pm.propertytypeid=17 then
     string_agg(pi.name,',') else null end as bhoomisellerparty ,

     pi.name, pi.ispresenter, pi.isexecutor   

     from kaveri.propertyschedules ps 
     left join kaveri.vw_fetch_party pi on (pi.propertyid = ps.propertyid 
     and pi.applicationnumber=ps.applicationnumber
      )
       where ps.propertyid = pm.propertyid 
     group by ps.propertyid ,ps.scheduletype,ps.totalarea,ps.description,   
      pi.name, pi.ispresenter, pi.isexecutor */

      select distinct ps.propertyid as propertyschedulespropertyid, 
      ps.scheduletype, 
      ps.totalarea,
     string_agg(pi.name,',') as bhoomisellername, pnam.firstname as name, ps.description as scheduledescription,
     case when pm.propertytypeid=17 then string_agg(pi.name,',') else null end as bhoomisellerparty,
     ps.eastboundary, ps.westboundary, ps.northboundary, ps.southboundary
      from kaveri.propertyschedules ps 
      left join kaveri.vw_fetch_party pi on ps.applicationnumber=pi.applicationnumber and  pi.propertyid = ps.propertyid
      left join (select ps1.scheduleid, array_to_string(array_agg(pi2.name),',') 
        AS firstname from kaveri.partyschedules ps1
   left join 
      (select name,partyid from kaveri.vw_fetch_party vf where vf.applicationnumber = _applicationnumber ) as pi2 
        on pi2.partyid = ps1.partyid
       where ps1.applicationnumber =_applicationnumber 
       group by ps1.scheduleid)
      as pnam on ps.scheduleid = pnam.scheduleid
      where  ps.propertyid = pm.propertyid 
      group by ps.propertyid, ps.scheduletype, ps.totalarea, pnam.firstname, ps.description, ps.eastboundary,
      ps.westboundary, ps.northboundary, ps.southboundary)schd ) as propertyschedules,   
     ( select array_to_json(array_agg(row_to_json(prptyno)))
      from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,
      pntm.typenameenglish as propertynumbertype, pnd.currentnumber, coalesce(pnd.hissa_no,'') as hissa_no,
      coalesce(pnd.survey_no,0) as survey_no, pnd.description as propertynumberdescription
     from kaveri.propertynumberdetails pnd 
      left join kaveri.propertynotypemaster pntm on (pntm.propertytypeid = pnd.currentpropertytypeid) 
      where pnd.propertyid = pm.propertyid )prptyno ) as propertynumberdetails
     FROM kaveri.propertymaster pm 
     left join kaveri.propertytypemaster ptm on (ptm.propertytypeid = pm.propertytypeid) 
   left join kaveri.stamparticles stm on (stm.stamparticlecode=pm.stamparticlecode)
   left join kaveri.stamprules sr on pm.stampruleid = sr.stampruleid
   left join kaveri.stamprulesflag srf ON sr.stampruleid = srf.stampruleid
     left join  kaveri.sromaster c on (pm.srocode = c.srocode)
     left join kaveri.villagemaster d on (pm.villagecode = d.villagecode)
   left join kaveri.hoblimaster h on d.hoblicode = h.hoblicode
     left join kaveri.vw_fee_calculation_details_chk_v2 calc on (pm.applicationnumber = calc.applicationnumber)
     where pm.applicationnumber=ad.applicationnumber) prpty
    ) as propertyinfo, 
  (
      select array_to_json(array_agg(row_to_json(prty)))
      from (
  select 
  vw_party.applicationnumber,vw_party.partyid,case when (vw_party.aliasname='' or vw_party.aliasname is null)  then  vw_party.name else CONCAT(vw_party.name,', alias:',vw_party.aliasname) end  as partyname,coalesce(vw_party.age,0) as age, vw_party.address ,vw_party.profession,
  vw_party.phonenumber,vw_party.epic,vw_party.partytypeid,vw_party.partytypename,vw_party.isexecutor,vw_party.ispresenter,vw_party.admissiondate,
  vw_party.section88exemption,vw_party.fingerid,vw_party.thumbpath,vw_party.photopath,vw_party.idprooftypedesc,vw_party.idproofnumber,
  vw_party.relationship,vw_party.relativename,string_agg(wi.name||' '||wi.middlename||' '||wi.lastname,',') as witness_name ,
  /*isorganization, tanno, organizationid, yearofincorp, linkpartyid, auname, auaddress,
   aualiasname, 
  auage, ausex, auidprooftypeid, auidprooftypedesc, auidproofnumber, auprofession,
   poaisorganization,
  poaname, poaaddress, poaage, poasex, poaidproofnumber, poatan, poaprofession,
   poarelationship, 
  poarelativename,poaidprooftypedesc, poapartytypename, poayearofincorp, 
  orgpoaauthsignfname, orgpoaauthsignmname, orgpoaauthsignlname, minorguardianname,
   minorguardianage,
  minorguardianrelationship, minorguardianrelativename,*/
  vw_party.isEndorsePrinted,vw_party.gender as sex, vw_party.isorganization, vw_party.tanno, vw_party.minorguardianname, vw_party.poaname,
  vw_party.auname, vw_party.auaddress, vw_party.isprivateattendance, vw_party.coveringletterno, vw_party.thumbremarks,vw_party.ispartyrefused,
  sl.descriptione,vw_party.islateapperance,vw_party.isbiometricrefused,vw_party.iscitizennotappeared,
  -- paperless change
  vw_party.isendorsementsigned, vw_party.isthumbregistersigned,vw_party.isdocumentexecuted,vw_party.duplicatepartyid,vw_party.isduplicate,
  vw_party.idprooftypeid,vw_party.namematchpercentage,vw_party.propertyid, --added 13-01-2026--

  (select row_to_json(aadhar)
  from (select aal.partyid,aal.nameasperaadhar,
  case when aal.partyid is not null 
   then
    case when aal.responsestatus = 'Y' then true 
      when aal.responsestatus = 'N' then false
   when aal.partyid is null then null end
  end as aadharverified
  ,aal.errormessage from kaveri.aadhar_authentication_log aal
  where aal.partyid = vw_party.partyid or aal.partyid = vw_party.duplicatepartyid
  order by aal.id desc limit 1)aadhar)as aadharinfo
  from kaveri.vw_fetch_party vw_party 
  left join kaveri.partywitness pw on pw.partyid in (select partyid from kaveri.partyinfo where applicationnumber =_applicationnumber)
  left join  kaveri.salutationmaster sl on vw_party.salutationid=sl.salutationid
  left join kaveri.witnessinfo wi on pw.witnessid = wi.witnessid 
   where vw_party.applicationnumber = ad.applicationnumber 
   group by vw_party.applicationnumber,vw_party.applicationnumber,vw_party.partyid,vw_party.name ,vw_party.age, vw_party.address ,vw_party.profession,
  vw_party.phonenumber,vw_party.epic,vw_party.partytypeid,vw_party.partytypename,vw_party.isexecutor,vw_party.ispresenter,vw_party.admissiondate,
  vw_party.section88exemption,vw_party.fingerid,vw_party.thumbpath,vw_party.photopath,vw_party.idprooftypedesc,vw_party.idproofnumber,
  vw_party.relationship,vw_party.relativename,vw_party.isEndorsePrinted,vw_party.gender, vw_party.isorganization, vw_party.tanno, vw_party.minorguardianname, vw_party.poaname,
  vw_party.auname, vw_party.auaddress, vw_party.isprivateattendance, vw_party.coveringletterno, vw_party.thumbremarks,vw_party.ispartyrefused
  ,vw_party.aliasname,sl.descriptione,vw_party.islateapperance,vw_party.isbiometricrefused,vw_party.iscitizennotappeared,
  -- paperless change
  vw_party.isendorsementsigned, vw_party.isthumbregistersigned,vw_party.isdocumentexecuted,vw_party.duplicatepartyid,vw_party.isduplicate,
  vw_party.idprooftypeid,vw_party.namematchpercentage,vw_party.propertyid
   order by partytypeid) prty
    ) as partyinfo,
 (  select array_to_json(array_agg(row_to_json(witness)))
      from (select wi.witnessid, wi.name, wi.houseno, concat(wi.address,' ',d.districtnamee,' ',g.taluknamee,' ',s.statenamee) as address,
   wi.age,wi.applicationnumber,wi."name",r.relatione as relation,wi.relativename,
   /* added a columns houseno, address, pincode and necessary joins for the same, on 07/11/2022 */
   /* Removed above changes, on 07/11/2022 */
   /*(wi.address::text || ', '::text) || (tal.taluknamee::text || ', '::text) || (dis.districtnamee::text || ', '::text) || (st.statenamee::text) || ' '::text AS address,*/
   wi.pincode, wi.age, wi.profession, wi.isEndorsePrinted, wi.sex 
   from kaveri.witnessinfo wi
   left join kaveri.relationshipmasters r on wi.relation::int =r.id 
   left JOIN kaveri.lgd_districtmaster d ON d.districtcode = wi.districtcode
       left JOIN kaveri.lgd_statemaster s ON d.lgdstatecode = s.statecode
       left JOIN kaveri.lgd_talukmaster g ON g.talukcode = wi.talukcode
   /*left join kaveri.lgd_districtmaster dis ON dis.districtcode = wi.districtcode
   left join kaveri.lgd_statemaster st ON st.statecode  = wi.statecode
   left join kaveri.lgd_talukmaster tal ON tal.talukcode = wi.talukcode*/
   where wi.applicationnumber = ad.applicationnumber) witness
 ) as witnessinfo,
 md.ispendingdocument  as ispendingdocument,
 (case when fds.valuatiotypeid=1 then true else false end) as isimpound,
 (case when fds.valuatiotypeid=3 then true else false end) as isundervaluation,
 (case when dm.executiondatetime::date<(now()- interval '4 months')::date then true else false end) as isdelaycondonation
 -- paperless change
 ,dm.isdigitallyexecuted,  /* added a new column on 09/02/2026 */
 dm.issignpageappended,   /* added a new column on 09/02/2026 */
 dm.isthumbregisterdocsigned  /* added a new column on 17/02/2026 */
  from kaveri.applicantapplicationdetails ad
inner join kaveri.documentmaster dm on (ad.applicationnumber=dm.applicationnumber)
left join kaveri.minutebook_data md on (md.applicationnumber=ad.applicationnumber)
left join (select distinct applicationnumber,valuatiotypeid from kaveri.feesrequired fd where fd.applicationnumber=_applicationnumber) as fds on fds.applicationnumber=ad.applicationnumber 
 join kaveri.servicesmaster sm on (sm.serviceid = ad.applicationtypeid)
 join kaveri.booktypemaster bm on (bm.bookid=dm.bookid)
left join kaveri.stamparticles sa on (sa.stamparticlecode=dm.stamparticlecode)
left join kaveri.registrationarticles ra on (ra.regarticlecode=dm.regarticlecode)
left join kaveri.bhoomifileuploaddetails bh on (dm.finalregistrationnumber = bh.finalregistrationnumber)
left join kaveri.easthi_eswathu_fileuploaddetails ee on (dm.finalregistrationnumber =ee.finalregistrationnumber )
inner join kaveri.sromaster ss on ss.srocode=ad.srocode
-- paperless change
inner join kaveri.districtmaster d on d.districtcode = ss.districtcode
left join kaveri.departmentusers dp on dp.userid = ad.deoid
  where ad.applicationnumber = _applicationnumber and ad.srocode=_srocode
  group by ad.applicationnumber,dm.executiondatetime,
  dm.presentdatetime ,
 dm.finalregistrationnumber,dm.registrationdatetime,dm.isPrintEndorsement,
 dm.pagecount ,sa.articlenamee ,ad.annexurepath,dm.partypaymentdetails,
ra.articlenamee , bm.printablename ,sm.servicename ,
 ad.remarks,fds.valuatiotypeid,dm.executiondatetime,
 ad.remarksk,ss.sronamee,ss.sronamek, --- To fetch the Kannada text added on 28-11-2022
 ad.currentstatus,dm.isscancompleted,ad.applicationtypeid,md.remark_comment,md.reasonid ,md.private_remark,ad.refuseremarks,dm.pendingdocumentnumber,md.ispendingdocument,md.isbefore2003,dm.regarticlecode,
 -- paperless change
 ss.sronamek,
 d.districtnamee,
 d.districtnamek,
 dp.firstname,dp.loginname,
 -- paperless change
 dm.isdigitalsigned,dm.isdigitallyexecuted,dm.issignpageappended,dm.isthumbregisterdocsigned
) app_json ;

return v_data_json1;

END;
$_$;


ALTER FUNCTION kaveri.fn_fetch_documentsummary_json(_applicationnumber text, _srocode bigint) OWNER TO postgres;

--
-- Name: fn_fetch_documentsummary_json2(text, bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_documentsummary_json2(_applicationnumber text, _srocode bigint) RETURNS json
    LANGUAGE plpgsql
    AS $_$



declare 
v_data_json1 json;
BEGIN

select row_to_json(app_json) into v_data_json1
from (

  select ad.applicationnumber,dm.executiondatetime::date executedate,
  dm.presentdatetime as presentdate,
regexp_replace(dm.pendingdocumentnumber, '^([^-]*-[^-]*)-.*$', '\1') as pendingdocumentnumber ,
	dm.finalregistrationnumber,dm.registrationdatetime,dm.isPrintEndorsement,
	dm.pagecount ,sa.articlenamee as stamparticlename,dm.regarticlecode,ad.annexurepath,dm.partypaymentdetails,
ra.articlenamee as Naturedeed, bm.printablename as book,sm.servicename as applicationtype,
	ad.remarks,
	ad.remarksk,
	ss.sronamee as sroname ,--- To fetch the Kannada text added on 28-11-2022
	ad.currentstatus,dm.isscancompleted,ad.applicationtypeid,md.remark_comment,md.reasonid,md.private_remark,ad.refuseremarks, 
	string_agg(bh.acknowledgeno,',') as Ysavednumber,
	string_agg(ee.acknowledgeno,',') as acknowledgeno,md.isbefore2003,  
     (
      select array_to_json(array_agg(row_to_json(prpty)))
      from (SELECT pm.applicationnumber,	  
			pm.propertyid,
			pm.documentid,
			stm.articlenamee as stamparticle,
			pm.ismovableproperty,
			d.villagenamee,
			pm.propertytypeid,
			ptm.propertytypename as propertytype,
			c.sronamee sroname,
			pm.northboundary,
			pm.denodescription ,
			pm.estampdescription,
			pm.adjudescription ,
			pm.southboundary,
			pm.eastboundary,
			pm.westboundary,
			pm.landmark,
			pm.consideration,
			pm.marketvalue,
			pm.sroconsideration,
			case when pm.sromarketvalue is null then 0 else pm.sromarketvalue end sromarketvalue,
			pm.cessduty,
			pm.govtduty,
			pm.additionalduty,
			pm.stampduty,
			pm.valid1 as duplicatecopies,
			calc.duplicatefee,
			calc.duplicatestampduty,
			calc.duplicateregistrationfee,
			calc.privateattendancefee,
			--calc.stampduty, 		
			pm.valuationreport,
			pm.sronoofscanpages, /* added a new column on 07/10/2022 to fetch number of scan pages in document summary page */
			sr.ismarketvaluationdone, /* added a new column on 06/11/2022 */
			h.hoblinamee as hobli, /* added a new column on 06/11/2022 */
			srf.ispartytopropertyschd, /* added a new column on 07/11/2022 */
			( select array_to_json(array_agg(row_to_json(schd)))
			  from (
			/*  select ps.propertyid as propertyschedulespropertyid,ps.scheduletype,ps.totalarea,
			  ps.description as scheduledescription,
					case when pm.propertytypeid=17 then
					string_agg(pi.name,',') else null end as bhoomisellerparty ,

					pi.name, pi.ispresenter, pi.isexecutor			

					from kaveri.propertyschedules ps 
					left join kaveri.vw_fetch_party pi on (pi.propertyid = ps.propertyid 
					and pi.applicationnumber=ps.applicationnumber
						)
				   where ps.propertyid = pm.propertyid 
					group by ps.propertyid ,ps.scheduletype,ps.totalarea,ps.description,			
				  pi.name, pi.ispresenter, pi.isexecutor	*/

				  select distinct ps.propertyid as propertyschedulespropertyid, 
						ps.scheduletype, 
						ps.totalarea,
					string_agg(pi.name,',') as bhoomisellername, pnam.firstname as name, ps.description as scheduledescription,
					case when pm.propertytypeid=17 then string_agg(pi.name,',') else null end as bhoomisellerparty,
					ps.eastboundary, ps.westboundary, ps.northboundary, ps.southboundary
				  from kaveri.propertyschedules ps 
				  left join kaveri.vw_fetch_party pi on ps.applicationnumber=pi.applicationnumber and  pi.propertyid = ps.propertyid
				  left join (select ps1.scheduleid, array_to_string(array_agg(distinct pi2.name),',') 
								AS firstname from kaveri.partyschedules ps1
			left join 
						(select name,partyid from kaveri.vw_fetch_party vf where vf.applicationnumber = _applicationnumber ) as pi2 
							 on pi2.partyid = ps1.partyid
							where ps1.applicationnumber =_applicationnumber 
							group by ps1.scheduleid)
				  as pnam on ps.scheduleid = pnam.scheduleid
				  where  ps.propertyid = pm.propertyid 
				  group by ps.propertyid, ps.scheduletype, ps.totalarea, pnam.firstname, ps.description, ps.eastboundary,
				  ps.westboundary, ps.northboundary, ps.southboundary)schd ) as propertyschedules,			
			  ( select array_to_json(array_agg(row_to_json(prptyno)))
			   from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,
					 pntm.typenameenglish as propertynumbertype, pnd.currentnumber, coalesce(pnd.hissa_no,'') as hissa_no,
					 coalesce(pnd.survey_no,0) as survey_no, pnd.description as propertynumberdescription
					from kaveri.propertynumberdetails pnd 
					 left join kaveri.propertynotypemaster pntm on (pntm.propertytypeid = pnd.currentpropertytypeid) 
					 where pnd.propertyid = pm.propertyid )prptyno ) as propertynumberdetails
		   FROM kaveri.propertymaster pm 
		   left join kaveri.propertytypemaster ptm on (ptm.propertytypeid = pm.propertytypeid) 
			left join kaveri.stamparticles stm on (stm.stamparticlecode=pm.stamparticlecode)
			left join kaveri.stamprules sr on pm.stampruleid = sr.stampruleid
			left join kaveri.stamprulesflag srf ON sr.stampruleid = srf.stampruleid
		   left join  kaveri.sromaster c on (pm.srocode = c.srocode)
		   left join kaveri.villagemaster d on (pm.villagecode = d.villagecode)
			left join kaveri.hoblimaster h on d.hoblicode = h.hoblicode
		   left join kaveri.vw_fee_calculation_details_chk_v2 calc on (pm.applicationnumber = calc.applicationnumber)
		   where pm.applicationnumber=ad.applicationnumber) prpty
    ) as propertyinfo,	
	 (
      select array_to_json(array_agg(row_to_json(prty)))
      from (
		select 
		vw_party.applicationnumber,vw_party.partyid,case when (vw_party.aliasname='' or vw_party.aliasname is null)  then  vw_party.name else CONCAT(vw_party.name,', alias:',vw_party.aliasname) end  as partyname,vw_party.age, vw_party.address ,vw_party.profession,
		vw_party.phonenumber,vw_party.epic,vw_party.partytypeid,vw_party.partytypename,vw_party.isexecutor,vw_party.ispresenter,vw_party.admissiondate,
		vw_party.section88exemption,vw_party.fingerid,vw_party.thumbpath,vw_party.photopath,vw_party.idprooftypedesc,vw_party.idproofnumber,
		vw_party.relationship,vw_party.relativename,string_agg(wi.name||' '||wi.middlename||' '||wi.lastname,',') as witness_name ,
		/*isorganization, tanno, organizationid, yearofincorp, linkpartyid, auname, auaddress,
		 aualiasname, 
		auage, ausex, auidprooftypeid, auidprooftypedesc, auidproofnumber, auprofession,
		 poaisorganization,
		poaname, poaaddress, poaage, poasex, poaidproofnumber, poatan, poaprofession,
		 poarelationship, 
		poarelativename,poaidprooftypedesc, poapartytypename, poayearofincorp, 
		orgpoaauthsignfname, orgpoaauthsignmname, orgpoaauthsignlname, minorguardianname,
		 minorguardianage,
		minorguardianrelationship, minorguardianrelativename,*/
		vw_party.isEndorsePrinted,vw_party.gender as sex, vw_party.isorganization, vw_party.tanno, vw_party.minorguardianname, vw_party.poaname,
		vw_party.auname, vw_party.auaddress, vw_party.isprivateattendance, vw_party.coveringletterno, vw_party.thumbremarks,vw_party.ispartyrefused,
		sl.descriptione,vw_party.islateapperance,vw_party.isbiometricrefused,vw_party.iscitizennotappeared	,
		(select row_to_json(aadhar)
		from (select aal.partyid,aal.nameasperaadhar,
		case when aal.partyid is not null 
			then
				case when aal.responsestatus = 'Y' then true 
				 	when aal.responsestatus = 'N' then false
			when aal.partyid is null then null end
		end as aadharverified
		,aal.errormessage from kaveri.aadhar_authentication_log aal
		where aal.partyid = vw_party.partyid 
		order by aal.id desc limit 1)aadhar)as aadharinfo
		from kaveri.vw_fetch_party vw_party 
		left join kaveri.partywitness pw on pw.partyid in (select partyid from kaveri.partyinfo where applicationnumber =_applicationnumber)
		left join  kaveri.salutationmaster sl on vw_party.salutationid=sl.salutationid
		left join kaveri.witnessinfo wi on pw.witnessid = wi.witnessid 
			where vw_party.applicationnumber = ad.applicationnumber 
			group by vw_party.applicationnumber,vw_party.applicationnumber,vw_party.partyid,vw_party.name ,vw_party.age, vw_party.address ,vw_party.profession,
		vw_party.phonenumber,vw_party.epic,vw_party.partytypeid,vw_party.partytypename,vw_party.isexecutor,vw_party.ispresenter,vw_party.admissiondate,
		vw_party.section88exemption,vw_party.fingerid,vw_party.thumbpath,vw_party.photopath,vw_party.idprooftypedesc,vw_party.idproofnumber,
		vw_party.relationship,vw_party.relativename,vw_party.isEndorsePrinted,vw_party.gender, vw_party.isorganization, vw_party.tanno, vw_party.minorguardianname, vw_party.poaname,
		vw_party.auname, vw_party.auaddress, vw_party.isprivateattendance, vw_party.coveringletterno, vw_party.thumbremarks,vw_party.ispartyrefused
		,vw_party.aliasname,sl.descriptione,vw_party.islateapperance,vw_party.isbiometricrefused,vw_party.iscitizennotappeared
			order by partytypeid) prty
    ) as partyinfo,
	(  select array_to_json(array_agg(row_to_json(witness)))
      from (select wi.witnessid, wi.name, wi.houseno, concat(wi.address,' ',d.districtnamee,' ',g.taluknamee,' ',s.statenamee) as address,
			wi.age,wi.applicationnumber,wi."name",r.relatione as relation,wi.relativename,
			/* added a columns houseno, address, pincode and necessary joins for the same, on 07/11/2022 */
			/* Removed above changes, on 07/11/2022 */
			/*(wi.address::text || ', '::text) || (tal.taluknamee::text || ', '::text) || (dis.districtnamee::text || ', '::text) || (st.statenamee::text) || ' '::text AS address,*/
			wi.pincode, wi.age, wi.profession, wi.isEndorsePrinted, wi.sex 
			from kaveri.witnessinfo wi
			left join kaveri.relationshipmasters r on wi.relation::int =r.id 
			JOIN kaveri.lgd_districtmaster d ON d.districtcode = wi.districtcode
    		 JOIN kaveri.lgd_statemaster s ON d.lgdstatecode = s.statecode
     		JOIN kaveri.lgd_talukmaster g ON g.talukcode = wi.talukcode
			/*left join kaveri.lgd_districtmaster dis ON dis.districtcode = wi.districtcode
			left join kaveri.lgd_statemaster st ON st.statecode  = wi.statecode
			left join kaveri.lgd_talukmaster tal ON tal.talukcode = wi.talukcode*/
			where wi.applicationnumber = ad.applicationnumber) witness
	) as witnessinfo,
	md.ispendingdocument  as ispendingdocument,
	(case when fds.valuatiotypeid=1 then true else false end) as isundervaluation,
	(case when fds.valuatiotypeid=3 then true else false end) as isimpound,
	(case when dm.executiondatetime::date<(now()- interval '4 months')::date then true else false end) as isdelaycondonation 
  from kaveri.applicantapplicationdetails ad
inner join kaveri.documentmaster dm on (ad.applicationnumber=dm.applicationnumber)
left join kaveri.minutebook_data md on (md.applicationnumber=ad.applicationnumber)
left join (select distinct applicationnumber,valuatiotypeid from kaveri.feesrequired fd where fd.applicationnumber=_applicationnumber) as fds on fds.applicationnumber=ad.applicationnumber 
 join kaveri.servicesmaster sm on (sm.serviceid = ad.applicationtypeid)
 join kaveri.booktypemaster bm on (bm.bookid=dm.bookid)
left join kaveri.stamparticles sa on (sa.stamparticlecode=dm.stamparticlecode)
left join kaveri.registrationarticles ra on (ra.regarticlecode=dm.regarticlecode)
left join kaveri.bhoomifileuploaddetails bh on (dm.finalregistrationnumber = bh.finalregistrationnumber)
left join kaveri.easthi_eswathu_fileuploaddetails ee on (dm.finalregistrationnumber =ee.finalregistrationnumber )
inner join kaveri.sromaster ss on ss.srocode=ad.srocode
  where ad.applicationnumber = _applicationnumber and ad.srocode=_srocode
  group by ad.applicationnumber,dm.executiondatetime,
  dm.presentdatetime ,
	dm.finalregistrationnumber,dm.registrationdatetime,dm.isPrintEndorsement,
	dm.pagecount ,sa.articlenamee ,ad.annexurepath,dm.partypaymentdetails,
ra.articlenamee , bm.printablename ,sm.servicename ,
	ad.remarks,fds.valuatiotypeid,dm.executiondatetime,
	ad.remarksk,ss.sronamee, --- To fetch the Kannada text added on 28-11-2022
	ad.currentstatus,dm.isscancompleted,ad.applicationtypeid,md.remark_comment,md.reasonid ,md.private_remark,ad.refuseremarks,dm.pendingdocumentnumber,md.ispendingdocument,md.isbefore2003,dm.regarticlecode
) app_json ;

return v_data_json1;

END;
$_$;


ALTER FUNCTION kaveri.fn_fetch_documentsummary_json2(_applicationnumber text, _srocode bigint) OWNER TO postgres;

--
-- Name: fn_fetch_documentsummary_json_2(text, bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_documentsummary_json_2(_applicationnumber text, _srocode bigint) RETURNS json
    LANGUAGE plpgsql
    AS $_$



declare 
v_data_json1 json;
BEGIN

select row_to_json(app_json) into v_data_json1
from (

  select ad.applicationnumber,dm.executiondatetime::date executedate,
  dm.presentdatetime as presentdate,
regexp_replace(dm.pendingdocumentnumber, '^([^-]*-[^-]*)-.*$', '\1') as pendingdocumentnumber ,
	dm.finalregistrationnumber,dm.registrationdatetime,dm.isPrintEndorsement,
	dm.pagecount ,sa.articlenamee as stamparticlename,dm.regarticlecode,ad.annexurepath,dm.partypaymentdetails,
ra.articlenamee as Naturedeed, bm.printablename as book,sm.servicename as applicationtype,
	ad.remarks,
	ad.remarksk,
	ss.sronamee as sroname ,--- To fetch the Kannada text added on 28-11-2022
	ad.currentstatus,dm.isscancompleted,ad.applicationtypeid,md.remark_comment,md.reasonid,md.private_remark,ad.refuseremarks, 
	string_agg(bh.acknowledgeno,',') as Ysavednumber,
	string_agg(ee.acknowledgeno,',') as acknowledgeno,md.isbefore2003,  
     (
      select array_to_json(array_agg(row_to_json(prpty)))
      from (SELECT pm.applicationnumber,	  
			pm.propertyid,
			pm.documentid,
			stm.articlenamee as stamparticle,
			pm.ismovableproperty,
			d.villagenamee,
			pm.propertytypeid,
			ptm.propertytypename as propertytype,
			c.sronamee sroname,
			pm.northboundary,
			pm.denodescription ,
			pm.estampdescription,
			pm.adjudescription ,
			pm.southboundary,
			pm.eastboundary,
			pm.westboundary,
			pm.landmark,
			pm.consideration,
			pm.marketvalue,
			pm.sroconsideration,
			case when pm.sromarketvalue is null then 0 else pm.sromarketvalue end sromarketvalue,
			pm.cessduty,
			pm.govtduty,
			pm.additionalduty,
			pm.stampduty,
			pm.valid1 as duplicatecopies,
			calc.duplicatefee,
			calc.duplicatestampduty,
			calc.duplicateregistrationfee,
			calc.privateattendancefee,
			--calc.stampduty, 		
			pm.valuationreport,
			pm.sronoofscanpages, /* added a new column on 07/10/2022 to fetch number of scan pages in document summary page */
			sr.ismarketvaluationdone, /* added a new column on 06/11/2022 */
			h.hoblinamee as hobli, /* added a new column on 06/11/2022 */
			srf.ispartytopropertyschd, /* added a new column on 07/11/2022 */
			( select array_to_json(array_agg(row_to_json(schd)))
			from (
			/*  select ps.propertyid as propertyschedulespropertyid,ps.scheduletype,ps.totalarea,
			  ps.description as scheduledescription,
					case when pm.propertytypeid=17 then
					string_agg(pi.name,',') else null end as bhoomisellerparty ,

					pi.name, pi.ispresenter, pi.isexecutor			

					from kaveri.propertyschedules ps 
					left join kaveri.vw_fetch_party pi on (pi.propertyid = ps.propertyid 
					and pi.applicationnumber=ps.applicationnumber
						)
				   where ps.propertyid = pm.propertyid 
					group by ps.propertyid ,ps.scheduletype,ps.totalarea,ps.description,			
				  pi.name, pi.ispresenter, pi.isexecutor	*/

			select distinct ps.propertyid as propertyschedulespropertyid, 
				ps.scheduletype, 
						ps.totalarea,
					string_agg(pi.name,',') as bhoomisellername, pnam.firstname as name, ps.description as scheduledescription,
				case when pm.propertytypeid=17 then string_agg(pi.name,',') else null end as bhoomisellerparty,
					ps.eastboundary, ps.westboundary, ps.northboundary, ps.southboundary
				 from kaveri.propertyschedules ps 
				  left join kaveri.vw_fetch_party pi on pi.propertyid = ps.propertyid
			 left join (select ps1.scheduleid, array_to_string(array_agg(distinct pi2.name),',') 
					AS firstname from kaveri.partyschedules ps1
			left join 
				(select name,partyid from kaveri.vw_fetch_party vf where vf.applicationnumber = _applicationnumber ) as pi2 
					on pi2.partyid = ps1.partyid 
							group by ps1.scheduleid)
				  as pnam on ps.scheduleid = pnam.scheduleid
				  where  ps.propertyid = pm.propertyid 
				  group by ps.propertyid, ps.scheduletype, ps.totalarea, pnam.firstname, ps.description, ps.eastboundary,
				  ps.westboundary, ps.northboundary, ps.southboundary)schd ) as propertyschedules,			
			  ( select array_to_json(array_agg(row_to_json(prptyno)))
			   from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,
					 pntm.typenameenglish as propertynumbertype, pnd.currentnumber, coalesce(pnd.hissa_no,'') as hissa_no,
					 coalesce(pnd.survey_no,0) as survey_no, pnd.description as propertynumberdescription
					from kaveri.propertynumberdetails pnd 
					 left join kaveri.propertynotypemaster pntm on (pntm.propertytypeid = pnd.currentpropertytypeid) 
					 where pnd.propertyid = pm.propertyid )prptyno ) as propertynumberdetails
		   FROM kaveri.propertymaster pm 
		   left join kaveri.propertytypemaster ptm on (ptm.propertytypeid = pm.propertytypeid) 
			left join kaveri.stamparticles stm on (stm.stamparticlecode=pm.stamparticlecode)
			left join kaveri.stamprules sr on pm.stampruleid = sr.stampruleid
			left join kaveri.stamprulesflag srf ON sr.stampruleid = srf.stampruleid
		   left join  kaveri.sromaster c on (pm.srocode = c.srocode)
		   left join kaveri.villagemaster d on (pm.villagecode = d.villagecode)
			left join kaveri.hoblimaster h on d.hoblicode = h.hoblicode
		   left join kaveri.vw_fee_calculation_details_chk_v2 calc on (pm.applicationnumber = calc.applicationnumber)
		   where pm.applicationnumber=ad.applicationnumber) prpty
    ) as propertyinfo,	
	  (
       select array_to_json(array_agg(row_to_json(prty)))
       from (
	 	select 
	 	vw_party.applicationnumber,vw_party.partyid,case when (vw_party.aliasname='' or vw_party.aliasname is null)  then  vw_party.name else CONCAT(vw_party.name,', alias:',vw_party.aliasname) end  as partyname,vw_party.age, vw_party.address ,vw_party.profession,
	 	vw_party.phonenumber,vw_party.epic,vw_party.partytypeid,vw_party.partytypename,vw_party.isexecutor,vw_party.ispresenter,vw_party.admissiondate,
	 	vw_party.section88exemption,vw_party.fingerid,vw_party.thumbpath,vw_party.photopath,vw_party.idprooftypedesc,vw_party.idproofnumber,
	 	vw_party.relationship,vw_party.relativename,string_agg(wi.name||' '||wi.middlename||' '||wi.lastname,',') as witness_name ,
	 	/*isorganization, tanno, organizationid, yearofincorp, linkpartyid, auname, auaddress,
	 	 aualiasname, 
	 	auage, ausex, auidprooftypeid, auidprooftypedesc, auidproofnumber, auprofession,
	 	 poaisorganization,
	 	poaname, poaaddress, poaage, poasex, poaidproofnumber, poatan, poaprofession,
	 	 poarelationship, 
	 	poarelativename,poaidprooftypedesc, poapartytypename, poayearofincorp, 
	 	orgpoaauthsignfname, orgpoaauthsignmname, orgpoaauthsignlname, minorguardianname,
	 	 minorguardianage,
	 	minorguardianrelationship, minorguardianrelativename,*/
	 	vw_party.isEndorsePrinted,vw_party.gender as sex, vw_party.isorganization, vw_party.tanno, vw_party.minorguardianname, vw_party.poaname,
	 	vw_party.auname, vw_party.auaddress, vw_party.isprivateattendance, vw_party.coveringletterno, vw_party.thumbremarks,vw_party.ispartyrefused,
	 	sl.descriptione,vw_party.islateapperance,vw_party.isbiometricrefused,vw_party.iscitizennotappeared	,
	 	(select row_to_json(aadhar)
	 	from (select aal.partyid,aal.nameasperaadhar,
	 	case when aal.partyid is not null 
	 		then
	 			case when aal.responsestatus = 'Y' then true 
	 			 	when aal.responsestatus = 'N' then false
	 		when aal.partyid is null then null end
	 	end as aadharverified
	 	,aal.errormessage from kaveri.aadhar_authentication_log aal
	 	where aal.partyid = vw_party.partyid 
	 	order by aal.id desc limit 1)aadhar)as aadharinfo
	 	from kaveri.vw_fetch_party vw_party 
	 	left join kaveri.partywitness pw on vw_party.partyid=pw.partyid and pw.partyid in (select partyid from kaveri.partyinfo where applicationnumber =_applicationnumber)
	 	left join  kaveri.salutationmaster sl on vw_party.salutationid=sl.salutationid
	 	left join kaveri.witnessinfo wi on pw.witnessid = wi.witnessid 
	 		where vw_party.applicationnumber = ad.applicationnumber 
	 		group by vw_party.applicationnumber,vw_party.applicationnumber,vw_party.partyid,vw_party.name ,vw_party.age, vw_party.address ,vw_party.profession,
	 	vw_party.phonenumber,vw_party.epic,vw_party.partytypeid,vw_party.partytypename,vw_party.isexecutor,vw_party.ispresenter,vw_party.admissiondate,
	 	vw_party.section88exemption,vw_party.fingerid,vw_party.thumbpath,vw_party.photopath,vw_party.idprooftypedesc,vw_party.idproofnumber,
	 	vw_party.relationship,vw_party.relativename,vw_party.isEndorsePrinted,vw_party.gender, vw_party.isorganization, vw_party.tanno, vw_party.minorguardianname, vw_party.poaname,
	 	vw_party.auname, vw_party.auaddress, vw_party.isprivateattendance, vw_party.coveringletterno, vw_party.thumbremarks,vw_party.ispartyrefused
	 	,vw_party.aliasname,sl.descriptione,vw_party.islateapperance,vw_party.isbiometricrefused,vw_party.iscitizennotappeared
	 		order by partytypeid) prty
     ) as partyinfo,
	(  select array_to_json(array_agg(row_to_json(witness)))
      from (select wi.witnessid, wi.name, wi.houseno, concat(wi.address,' ',d.districtnamee,' ',g.taluknamee,' ',s.statenamee) as address,
			wi.age,wi.applicationnumber,wi."name",r.relatione as relation,wi.relativename,
			/* added a columns houseno, address, pincode and necessary joins for the same, on 07/11/2022 */
			/* Removed above changes, on 07/11/2022 */
			/*(wi.address::text || ', '::text) || (tal.taluknamee::text || ', '::text) || (dis.districtnamee::text || ', '::text) || (st.statenamee::text) || ' '::text AS address,*/
			wi.pincode, wi.age, wi.profession, wi.isEndorsePrinted, wi.sex 
			from kaveri.witnessinfo wi
			left join kaveri.relationshipmasters r on wi.relation::int =r.id 
			JOIN kaveri.lgd_districtmaster d ON d.districtcode = wi.districtcode
    		 JOIN kaveri.lgd_statemaster s ON d.lgdstatecode = s.statecode
     		JOIN kaveri.lgd_talukmaster g ON g.talukcode = wi.talukcode
			/*left join kaveri.lgd_districtmaster dis ON dis.districtcode = wi.districtcode
			left join kaveri.lgd_statemaster st ON st.statecode  = wi.statecode
			left join kaveri.lgd_talukmaster tal ON tal.talukcode = wi.talukcode*/
			where wi.applicationnumber = ad.applicationnumber) witness
	) as witnessinfo,
	md.ispendingdocument  as ispendingdocument,
	(case when fds.valuatiotypeid=1 then true else false end) as isundervaluation,
	(case when fds.valuatiotypeid=3 then true else false end) as isimpound,
	(case when dm.executiondatetime::date<(now()- interval '4 months')::date then true else false end) as isdelaycondonation 
  from kaveri.applicantapplicationdetails ad
inner join kaveri.documentmaster dm on (ad.applicationnumber=dm.applicationnumber)
left join kaveri.minutebook_data md on (md.applicationnumber=ad.applicationnumber)
left join (select distinct applicationnumber,valuatiotypeid from kaveri.feesrequired fd where fd.applicationnumber=_applicationnumber) as fds on fds.applicationnumber=ad.applicationnumber 
 join kaveri.servicesmaster sm on (sm.serviceid = ad.applicationtypeid)
 join kaveri.booktypemaster bm on (bm.bookid=dm.bookid)
left join kaveri.stamparticles sa on (sa.stamparticlecode=dm.stamparticlecode)
left join kaveri.registrationarticles ra on (ra.regarticlecode=dm.regarticlecode)
left join kaveri.bhoomifileuploaddetails bh on (dm.finalregistrationnumber = bh.finalregistrationnumber)
left join kaveri.easthi_eswathu_fileuploaddetails ee on (dm.finalregistrationnumber =ee.finalregistrationnumber )
inner join kaveri.sromaster ss on ss.srocode=ad.srocode
  where ad.applicationnumber = _applicationnumber and ad.srocode=_srocode
  group by ad.applicationnumber,dm.executiondatetime,
  dm.presentdatetime ,
	dm.finalregistrationnumber,dm.registrationdatetime,dm.isPrintEndorsement,
	dm.pagecount ,sa.articlenamee ,ad.annexurepath,dm.partypaymentdetails,
ra.articlenamee , bm.printablename ,sm.servicename ,
	ad.remarks,fds.valuatiotypeid,dm.executiondatetime,
	ad.remarksk,ss.sronamee, --- To fetch the Kannada text added on 28-11-2022
	ad.currentstatus,dm.isscancompleted,ad.applicationtypeid,md.remark_comment,md.reasonid ,md.private_remark,ad.refuseremarks,dm.pendingdocumentnumber,md.ispendingdocument,md.isbefore2003,dm.regarticlecode
) app_json ;

return v_data_json1;

END;
$_$;


ALTER FUNCTION kaveri.fn_fetch_documentsummary_json_2(_applicationnumber text, _srocode bigint) OWNER TO postgres;

--
-- Name: fn_fetch_documentsummary_json_new(text, bigint); Type: FUNCTION; Schema: kaveri; Owner: raghavendrap
--

CREATE FUNCTION kaveri.fn_fetch_documentsummary_json_new(_applicationnumber text, _srocode bigint) RETURNS json
    LANGUAGE plpgsql
    AS $_$



declare 
v_data_json1 json;
BEGIN

select row_to_json(app_json) into v_data_json1
from (

  select ad.applicationnumber,dm.executiondatetime::date executedate,
  dm.presentdatetime as presentdate,
regexp_replace(dm.pendingdocumentnumber, '^([^-]*-[^-]*)-.*$', '\1') as pendingdocumentnumber ,
	dm.finalregistrationnumber,dm.registrationdatetime,dm.isPrintEndorsement,
	dm.pagecount ,sa.articlenamee as stamparticlename,dm.regarticlecode,ad.annexurepath,dm.partypaymentdetails,
ra.articlenamee as Naturedeed, bm.printablename as book,sm.servicename as applicationtype,
	ad.remarks,
	ad.remarksk,
	ss.sronamee as sroname ,--- To fetch the Kannada text added on 28-11-2022
	ad.currentstatus,dm.isscancompleted,ad.applicationtypeid,md.remark_comment,md.reasonid,md.private_remark,ad.refuseremarks, 
	string_agg(bh.acknowledgeno,',') as Ysavednumber,
	string_agg(ee.acknowledgeno,',') as acknowledgeno,md.isbefore2003, 
	dp.firstname||'('||substring(dp.loginname,1,4)||')' as deoname,
     (
      select array_to_json(array_agg(row_to_json(prpty)))
      from (SELECT pm.applicationnumber,	  
			pm.propertyid,
			pm.documentid,
			stm.articlenamee as stamparticle,
			pm.ismovableproperty,
			d.villagenamee,
			pm.propertytypeid,
			ptm.propertytypename as propertytype,
			c.sronamee sroname,
			pm.northboundary,
			pm.denodescription ,
			pm.estampdescription,
			pm.adjudescription ,
			pm.southboundary,
			pm.eastboundary,
			pm.westboundary,
			pm.landmark,
			pm.consideration,
			pm.marketvalue,
			pm.sroconsideration,
			case when pm.sromarketvalue is null then 0 else pm.sromarketvalue end sromarketvalue,
			pm.cessduty,
			pm.govtduty,
			pm.additionalduty,
			pm.stampduty,
			pm.valid1 as duplicatecopies,
			calc.duplicatefee,
			calc.duplicatestampduty,
			calc.duplicateregistrationfee,
			calc.privateattendancefee,
			--calc.stampduty, 		
			pm.valuationreport,
			pm.sronoofscanpages, /* added a new column on 07/10/2022 to fetch number of scan pages in document summary page */
			sr.ismarketvaluationdone, /* added a new column on 06/11/2022 */
			h.hoblinamee as hobli, /* added a new column on 06/11/2022 */
			srf.ispartytopropertyschd, /* added a new column on 07/11/2022 */
			( select array_to_json(array_agg(row_to_json(schd)))
			  from (
			/*  select ps.propertyid as propertyschedulespropertyid,ps.scheduletype,ps.totalarea,
			  ps.description as scheduledescription,
					case when pm.propertytypeid=17 then
					string_agg(pi.name,',') else null end as bhoomisellerparty ,

					pi.name, pi.ispresenter, pi.isexecutor			

					from kaveri.propertyschedules ps 
					left join kaveri.vw_fetch_party pi on (pi.propertyid = ps.propertyid 
					and pi.applicationnumber=ps.applicationnumber
						)
				   where ps.propertyid = pm.propertyid 
					group by ps.propertyid ,ps.scheduletype,ps.totalarea,ps.description,			
				  pi.name, pi.ispresenter, pi.isexecutor	*/

				  select distinct ps.propertyid as propertyschedulespropertyid, 
						ps.scheduletype, 
						ps.totalarea,
					string_agg(pi.name,',') as bhoomisellername, pnam.firstname as name, ps.description as scheduledescription,
					case when pm.propertytypeid=17 then string_agg(pi.name,',') else null end as bhoomisellerparty,
					ps.eastboundary, ps.westboundary, ps.northboundary, ps.southboundary
				  from kaveri.propertyschedules ps 
				  left join kaveri.vw_fetch_party pi on ps.applicationnumber=pi.applicationnumber and  pi.propertyid = ps.propertyid
				  left join (select ps1.scheduleid, array_to_string(array_agg(pi2.name),',') 
								AS firstname from kaveri.partyschedules ps1
			left join 
						(select name,partyid from kaveri.vw_fetch_party vf where vf.applicationnumber = _applicationnumber ) as pi2 
							 on pi2.partyid = ps1.partyid
							where ps1.applicationnumber =_applicationnumber 
							group by ps1.scheduleid)
				  as pnam on ps.scheduleid = pnam.scheduleid
				  where  ps.propertyid = pm.propertyid 
				  group by ps.propertyid, ps.scheduletype, ps.totalarea, pnam.firstname, ps.description, ps.eastboundary,
				  ps.westboundary, ps.northboundary, ps.southboundary)schd ) as propertyschedules,			
			  ( select array_to_json(array_agg(row_to_json(prptyno)))
			   from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,
					 pntm.typenameenglish as propertynumbertype, pnd.currentnumber, coalesce(pnd.hissa_no,'') as hissa_no,
					 coalesce(pnd.survey_no,0) as survey_no, pnd.description as propertynumberdescription
					from kaveri.propertynumberdetails pnd 
					 left join kaveri.propertynotypemaster pntm on (pntm.propertytypeid = pnd.currentpropertytypeid) 
					 where pnd.propertyid = pm.propertyid )prptyno ) as propertynumberdetails
		   FROM kaveri.propertymaster pm 
		   left join kaveri.propertytypemaster ptm on (ptm.propertytypeid = pm.propertytypeid) 
			left join kaveri.stamparticles stm on (stm.stamparticlecode=pm.stamparticlecode)
			left join kaveri.stamprules sr on pm.stampruleid = sr.stampruleid
			left join kaveri.stamprulesflag srf ON sr.stampruleid = srf.stampruleid
		   left join  kaveri.sromaster c on (pm.srocode = c.srocode)
		   left join kaveri.villagemaster d on (pm.villagecode = d.villagecode)
			left join kaveri.hoblimaster h on d.hoblicode = h.hoblicode
		   left join kaveri.vw_fee_calculation_details_chk_v2 calc on (pm.applicationnumber = calc.applicationnumber)
		   where pm.applicationnumber=ad.applicationnumber) prpty
    ) as propertyinfo,	
	 (
      select array_to_json(array_agg(row_to_json(prty)))
      from (
		select 
		vw_party.applicationnumber,vw_party.partyid,case when (vw_party.aliasname='' or vw_party.aliasname is null)  then  vw_party.name else CONCAT(vw_party.name,', alias:',vw_party.aliasname) end  as partyname,vw_party.age, vw_party.address ,vw_party.profession,
		vw_party.phonenumber,vw_party.epic,vw_party.partytypeid,vw_party.partytypename,vw_party.isexecutor,vw_party.ispresenter,vw_party.admissiondate,
		vw_party.section88exemption,vw_party.fingerid,vw_party.thumbpath,vw_party.photopath,vw_party.idprooftypedesc,vw_party.idproofnumber,
		vw_party.relationship,vw_party.relativename,string_agg(wi.name||' '||wi.middlename||' '||wi.lastname,',') as witness_name ,
		/*isorganization, tanno, organizationid, yearofincorp, linkpartyid, auname, auaddress,
		 aualiasname, 
		auage, ausex, auidprooftypeid, auidprooftypedesc, auidproofnumber, auprofession,
		 poaisorganization,
		poaname, poaaddress, poaage, poasex, poaidproofnumber, poatan, poaprofession,
		 poarelationship, 
		poarelativename,poaidprooftypedesc, poapartytypename, poayearofincorp, 
		orgpoaauthsignfname, orgpoaauthsignmname, orgpoaauthsignlname, minorguardianname,
		 minorguardianage,
		minorguardianrelationship, minorguardianrelativename,*/
		vw_party.isEndorsePrinted,vw_party.gender as sex, vw_party.isorganization, vw_party.tanno, vw_party.minorguardianname, vw_party.poaname,
		vw_party.auname, vw_party.auaddress, vw_party.isprivateattendance, vw_party.coveringletterno, vw_party.thumbremarks,vw_party.ispartyrefused,
		sl.descriptione,vw_party.islateapperance,vw_party.isbiometricrefused,vw_party.iscitizennotappeared	,
		(select row_to_json(aadhar)
		from (select aal.partyid,aal.nameasperaadhar,
		case when aal.partyid is not null 
			then
				case when aal.responsestatus = 'Y' then true 
				 	when aal.responsestatus = 'N' then false
			when aal.partyid is null then null end
		end as aadharverified
		,aal.errormessage from kaveri.aadhar_authentication_log aal
		where aal.partyid = vw_party.partyid 
		order by aal.id desc limit 1)aadhar)as aadharinfo
		from kaveri.vw_fetch_party vw_party 
		left join kaveri.partywitness pw on pw.partyid in (select partyid from kaveri.partyinfo where applicationnumber =_applicationnumber)
		left join  kaveri.salutationmaster sl on vw_party.salutationid=sl.salutationid
		left join kaveri.witnessinfo wi on pw.witnessid = wi.witnessid 
			where vw_party.applicationnumber = ad.applicationnumber 
			group by vw_party.applicationnumber,vw_party.applicationnumber,vw_party.partyid,vw_party.name ,vw_party.age, vw_party.address ,vw_party.profession,
		vw_party.phonenumber,vw_party.epic,vw_party.partytypeid,vw_party.partytypename,vw_party.isexecutor,vw_party.ispresenter,vw_party.admissiondate,
		vw_party.section88exemption,vw_party.fingerid,vw_party.thumbpath,vw_party.photopath,vw_party.idprooftypedesc,vw_party.idproofnumber,
		vw_party.relationship,vw_party.relativename,vw_party.isEndorsePrinted,vw_party.gender, vw_party.isorganization, vw_party.tanno, vw_party.minorguardianname, vw_party.poaname,
		vw_party.auname, vw_party.auaddress, vw_party.isprivateattendance, vw_party.coveringletterno, vw_party.thumbremarks,vw_party.ispartyrefused
		,vw_party.aliasname,sl.descriptione,vw_party.islateapperance,vw_party.isbiometricrefused,vw_party.iscitizennotappeared
			order by partytypeid) prty
    ) as partyinfo,
	(  select array_to_json(array_agg(row_to_json(witness)))
      from (select wi.witnessid, wi.name, wi.houseno, concat(wi.address,' ',d.districtnamee,' ',g.taluknamee,' ',s.statenamee) as address,
			wi.age,wi.applicationnumber,wi."name",r.relatione as relation,wi.relativename,
			/* added a columns houseno, address, pincode and necessary joins for the same, on 07/11/2022 */
			/* Removed above changes, on 07/11/2022 */
			/*(wi.address::text || ', '::text) || (tal.taluknamee::text || ', '::text) || (dis.districtnamee::text || ', '::text) || (st.statenamee::text) || ' '::text AS address,*/
			wi.pincode, wi.age, wi.profession, wi.isEndorsePrinted, wi.sex 
			from kaveri.witnessinfo wi
			left join kaveri.relationshipmasters r on wi.relation::int =r.id 
			JOIN kaveri.lgd_districtmaster d ON d.districtcode = wi.districtcode
    		 JOIN kaveri.lgd_statemaster s ON d.lgdstatecode = s.statecode
     		JOIN kaveri.lgd_talukmaster g ON g.talukcode = wi.talukcode
			/*left join kaveri.lgd_districtmaster dis ON dis.districtcode = wi.districtcode
			left join kaveri.lgd_statemaster st ON st.statecode  = wi.statecode
			left join kaveri.lgd_talukmaster tal ON tal.talukcode = wi.talukcode*/
			where wi.applicationnumber = ad.applicationnumber) witness
	) as witnessinfo,
	md.ispendingdocument  as ispendingdocument,
	(case when fds.valuatiotypeid=1 then true else false end) as isundervaluation,
	(case when fds.valuatiotypeid=3 then true else false end) as isimpound,
	(case when dm.executiondatetime::date<(now()- interval '4 months')::date then true else false end) as isdelaycondonation 
  from kaveri.applicantapplicationdetails ad
inner join kaveri.documentmaster dm on (ad.applicationnumber=dm.applicationnumber)
left join kaveri.minutebook_data md on (md.applicationnumber=ad.applicationnumber)
left join (select distinct applicationnumber,valuatiotypeid from kaveri.feesrequired fd where fd.applicationnumber=_applicationnumber) as fds on fds.applicationnumber=ad.applicationnumber 
 join kaveri.servicesmaster sm on (sm.serviceid = ad.applicationtypeid)
 join kaveri.booktypemaster bm on (bm.bookid=dm.bookid)
left join kaveri.stamparticles sa on (sa.stamparticlecode=dm.stamparticlecode)
left join kaveri.registrationarticles ra on (ra.regarticlecode=dm.regarticlecode)
left join kaveri.bhoomifileuploaddetails bh on (dm.finalregistrationnumber = bh.finalregistrationnumber)
left join kaveri.easthi_eswathu_fileuploaddetails ee on (dm.finalregistrationnumber =ee.finalregistrationnumber )
inner join kaveri.sromaster ss on ss.srocode=ad.srocode
left join kaveri.departmentusers dp on dp.userid = ad.deoid
  where ad.applicationnumber = _applicationnumber and ad.srocode=_srocode
  group by ad.applicationnumber,dm.executiondatetime,
  dm.presentdatetime ,
	dm.finalregistrationnumber,dm.registrationdatetime,dm.isPrintEndorsement,
	dm.pagecount ,sa.articlenamee ,ad.annexurepath,dm.partypaymentdetails,
ra.articlenamee , bm.printablename ,sm.servicename ,
	ad.remarks,fds.valuatiotypeid,dm.executiondatetime,
	ad.remarksk,ss.sronamee, --- To fetch the Kannada text added on 28-11-2022
	ad.currentstatus,dm.isscancompleted,ad.applicationtypeid,md.remark_comment,md.reasonid ,md.private_remark,ad.refuseremarks,dm.pendingdocumentnumber,md.ispendingdocument,md.isbefore2003,dm.regarticlecode,dp.firstname,dp.loginname
) app_json ;

return v_data_json1;

END;
$_$;


ALTER FUNCTION kaveri.fn_fetch_documentsummary_json_new(_applicationnumber text, _srocode bigint) OWNER TO raghavendrap;

--
-- Name: fn_fetch_documentsummary_json_org_20260717(text, bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_documentsummary_json_org_20260717(_applicationnumber text, _srocode bigint) RETURNS json
    LANGUAGE plpgsql
    AS $_$



declare 
v_data_json1 json;
BEGIN

select row_to_json(app_json) into v_data_json1
from (

  select ad.applicationnumber,dm.executiondatetime::date executedate,
  dm.presentdatetime as presentdate,
regexp_replace(dm.pendingdocumentnumber, '^([^-]*-[^-]*)-.*$', '\1') as pendingdocumentnumber ,
	dm.finalregistrationnumber,dm.registrationdatetime,dm.isPrintEndorsement,
	dm.pagecount ,sa.articlenamee as stamparticlename,dm.regarticlecode,ad.annexurepath,dm.partypaymentdetails,
ra.articlenamee as Naturedeed, bm.printablename as book,sm.servicename as applicationtype,
	ad.remarks,
	ad.remarksk,
	ss.sronamee as sroname ,--- To fetch the Kannada text added on 28-11-2022
	ss.sronamek as sronamek,
	-- paperless change
	d.districtnamee,
	d.districtnamek,
	dp.firstname||'('||substring(dp.loginname,1,4)||')' as deoname,
	ad.currentstatus,dm.isscancompleted,ad.applicationtypeid,md.remark_comment,md.reasonid,md.private_remark,ad.refuseremarks, 
	string_agg(bh.acknowledgeno,',') as Ysavednumber,
	string_agg(ee.acknowledgeno,',') as acknowledgeno,md.isbefore2003,
	-- paperless change
	dm.isdigitalsigned,
     (
      select array_to_json(array_agg(row_to_json(prpty)))
      from (SELECT pm.applicationnumber,	  
			pm.propertyid,
			pm.documentid,
			stm.articlenamee as stamparticle,
			sr.descriptione as subarticle,
			pm.ismovableproperty,
			d.villagenamee,
			pm.propertytypeid,
			ptm.propertytypename as propertytype,
			c.sronamee sroname,
			pm.northboundary,
			pm.denodescription ,
			pm.estampdescription,
			pm.adjudescription ,
			pm.southboundary,
			pm.eastboundary,
			pm.westboundary,
			pm.landmark,
			pm.consideration,
			pm.marketvalue,
			pm.sroconsideration,
			case when pm.sromarketvalue is null then 0 else pm.sromarketvalue end sromarketvalue,
			pm.cessduty,
			pm.govtduty,
			pm.additionalduty,
			pm.stampduty,
			pm.valid1 as duplicatecopies,
			calc.duplicatefee,
			calc.duplicatestampduty,
			calc.duplicateregistrationfee,
			calc.privateattendancefee,
			--calc.stampduty, 		
			pm.valuationreport,
			pm.sronoofscanpages, /* added a new column on 07/10/2022 to fetch number of scan pages in document summary page */
			sr.ismarketvaluationdone, /* added a new column on 06/11/2022 */
			h.hoblinamee as hobli, /* added a new column on 06/11/2022 */
			srf.ispartytopropertyschd, /* added a new column on 07/11/2022 */
			( select array_to_json(array_agg(row_to_json(schd)))
			  from (
			/*  select ps.propertyid as propertyschedulespropertyid,ps.scheduletype,ps.totalarea,
			  ps.description as scheduledescription,
					case when pm.propertytypeid=17 then
					string_agg(pi.name,',') else null end as bhoomisellerparty ,

					pi.name, pi.ispresenter, pi.isexecutor			

					from kaveri.propertyschedules ps 
					left join kaveri.vw_fetch_party pi on (pi.propertyid = ps.propertyid 
					and pi.applicationnumber=ps.applicationnumber
						)
				   where ps.propertyid = pm.propertyid 
					group by ps.propertyid ,ps.scheduletype,ps.totalarea,ps.description,			
				  pi.name, pi.ispresenter, pi.isexecutor	*/

				  select distinct ps.propertyid as propertyschedulespropertyid, 
						ps.scheduletype, 
						ps.totalarea,
					string_agg(pi.name,',') as bhoomisellername, pnam.firstname as name, ps.description as scheduledescription,
					case when pm.propertytypeid=17 then string_agg(pi.name,',') else null end as bhoomisellerparty,
					ps.eastboundary, ps.westboundary, ps.northboundary, ps.southboundary
				  from kaveri.propertyschedules ps 
				  left join kaveri.vw_fetch_party pi on ps.applicationnumber=pi.applicationnumber and  pi.propertyid = ps.propertyid
				  left join (select ps1.scheduleid, array_to_string(array_agg(pi2.name),',') 
								AS firstname from kaveri.partyschedules ps1
			left join 
						(select name,partyid from kaveri.vw_fetch_party vf where vf.applicationnumber = _applicationnumber ) as pi2 
							 on pi2.partyid = ps1.partyid
							where ps1.applicationnumber =_applicationnumber 
							group by ps1.scheduleid)
				  as pnam on ps.scheduleid = pnam.scheduleid
				  where  ps.propertyid = pm.propertyid 
				  group by ps.propertyid, ps.scheduletype, ps.totalarea, pnam.firstname, ps.description, ps.eastboundary,
				  ps.westboundary, ps.northboundary, ps.southboundary)schd ) as propertyschedules,			
			  ( select array_to_json(array_agg(row_to_json(prptyno)))
			   from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,
					 pntm.typenameenglish as propertynumbertype, pnd.currentnumber, coalesce(pnd.hissa_no,'') as hissa_no,
					 coalesce(pnd.survey_no,0) as survey_no, pnd.description as propertynumberdescription
					from kaveri.propertynumberdetails pnd 
					 left join kaveri.propertynotypemaster pntm on (pntm.propertytypeid = pnd.currentpropertytypeid) 
					 where pnd.propertyid = pm.propertyid )prptyno ) as propertynumberdetails
		   FROM kaveri.propertymaster pm 
		   left join kaveri.propertytypemaster ptm on (ptm.propertytypeid = pm.propertytypeid) 
			left join kaveri.stamparticles stm on (stm.stamparticlecode=pm.stamparticlecode)
			left join kaveri.stamprules sr on pm.stampruleid = sr.stampruleid
			left join kaveri.stamprulesflag srf ON sr.stampruleid = srf.stampruleid
		   left join  kaveri.sromaster c on (pm.srocode = c.srocode)
		   left join kaveri.villagemaster d on (pm.villagecode = d.villagecode)
			left join kaveri.hoblimaster h on d.hoblicode = h.hoblicode
		   left join kaveri.vw_fee_calculation_details_chk_v2 calc on (pm.applicationnumber = calc.applicationnumber)
		   where pm.applicationnumber=ad.applicationnumber) prpty
    ) as propertyinfo,	
	 (
      select array_to_json(array_agg(row_to_json(prty)))
      from (
		select 
		vw_party.applicationnumber,vw_party.partyid,case when (vw_party.aliasname='' or vw_party.aliasname is null)  then  vw_party.name else CONCAT(vw_party.name,', alias:',vw_party.aliasname) end  as partyname,coalesce(vw_party.age,0) as age, vw_party.address ,vw_party.profession,
		vw_party.phonenumber,vw_party.epic,vw_party.partytypeid,vw_party.partytypename,vw_party.isexecutor,vw_party.ispresenter,vw_party.admissiondate,
		vw_party.section88exemption,vw_party.fingerid,vw_party.thumbpath,vw_party.photopath,vw_party.idprooftypedesc,vw_party.idproofnumber,
		vw_party.relationship,vw_party.relativename,string_agg(wi.name||' '||wi.middlename||' '||wi.lastname,',') as witness_name ,
		/*isorganization, tanno, organizationid, yearofincorp, linkpartyid, auname, auaddress,
		 aualiasname, 
		auage, ausex, auidprooftypeid, auidprooftypedesc, auidproofnumber, auprofession,
		 poaisorganization,
		poaname, poaaddress, poaage, poasex, poaidproofnumber, poatan, poaprofession,
		 poarelationship, 
		poarelativename,poaidprooftypedesc, poapartytypename, poayearofincorp, 
		orgpoaauthsignfname, orgpoaauthsignmname, orgpoaauthsignlname, minorguardianname,
		 minorguardianage,
		minorguardianrelationship, minorguardianrelativename,*/
		vw_party.isEndorsePrinted,vw_party.gender as sex, vw_party.isorganization, vw_party.tanno, vw_party.minorguardianname, vw_party.poaname,
		vw_party.auname, vw_party.auaddress, vw_party.isprivateattendance, vw_party.coveringletterno, vw_party.thumbremarks,vw_party.ispartyrefused,
		sl.descriptione,vw_party.islateapperance,vw_party.isbiometricrefused,vw_party.iscitizennotappeared,
		-- paperless change
		vw_party.isendorsementsigned, vw_party.isthumbregistersigned,vw_party.isdocumentexecuted,vw_party.duplicatepartyid,vw_party.isduplicate,
		vw_party.idprooftypeid,vw_party.namematchpercentage,vw_party.propertyid, --added 13-01-2026--

		(select row_to_json(aadhar)
		from (select aal.partyid,aal.nameasperaadhar,
		case when aal.partyid is not null 
			then
				case when aal.responsestatus = 'Y' then true 
				 	when aal.responsestatus = 'N' then false
			when aal.partyid is null then null end
		end as aadharverified
		,aal.errormessage from kaveri.aadhar_authentication_log aal
		where aal.partyid = vw_party.partyid or aal.partyid = vw_party.duplicatepartyid
		order by aal.id desc limit 1)aadhar)as aadharinfo
		from kaveri.vw_fetch_party vw_party 
		left join kaveri.partywitness pw on pw.partyid in (select partyid from kaveri.partyinfo where applicationnumber =_applicationnumber)
		left join  kaveri.salutationmaster sl on vw_party.salutationid=sl.salutationid
		left join kaveri.witnessinfo wi on pw.witnessid = wi.witnessid 
			where vw_party.applicationnumber = ad.applicationnumber 
			group by vw_party.applicationnumber,vw_party.applicationnumber,vw_party.partyid,vw_party.name ,vw_party.age, vw_party.address ,vw_party.profession,
		vw_party.phonenumber,vw_party.epic,vw_party.partytypeid,vw_party.partytypename,vw_party.isexecutor,vw_party.ispresenter,vw_party.admissiondate,
		vw_party.section88exemption,vw_party.fingerid,vw_party.thumbpath,vw_party.photopath,vw_party.idprooftypedesc,vw_party.idproofnumber,
		vw_party.relationship,vw_party.relativename,vw_party.isEndorsePrinted,vw_party.gender, vw_party.isorganization, vw_party.tanno, vw_party.minorguardianname, vw_party.poaname,
		vw_party.auname, vw_party.auaddress, vw_party.isprivateattendance, vw_party.coveringletterno, vw_party.thumbremarks,vw_party.ispartyrefused
		,vw_party.aliasname,sl.descriptione,vw_party.islateapperance,vw_party.isbiometricrefused,vw_party.iscitizennotappeared,
		-- paperless change
		vw_party.isendorsementsigned, vw_party.isthumbregistersigned,vw_party.isdocumentexecuted,vw_party.duplicatepartyid,vw_party.isduplicate,
		vw_party.idprooftypeid,vw_party.namematchpercentage,vw_party.propertyid
			order by partytypeid) prty
    ) as partyinfo,
	(  select array_to_json(array_agg(row_to_json(witness)))
      from (select wi.witnessid, wi.name, wi.houseno, concat(wi.address,' ',d.districtnamee,' ',g.taluknamee,' ',s.statenamee) as address,
			wi.age,wi.applicationnumber,wi."name",r.relatione as relation,wi.relativename,
			/* added a columns houseno, address, pincode and necessary joins for the same, on 07/11/2022 */
			/* Removed above changes, on 07/11/2022 */
			/*(wi.address::text || ', '::text) || (tal.taluknamee::text || ', '::text) || (dis.districtnamee::text || ', '::text) || (st.statenamee::text) || ' '::text AS address,*/
			wi.pincode, wi.age, wi.profession, wi.isEndorsePrinted, wi.sex 
			from kaveri.witnessinfo wi
			left join kaveri.relationshipmasters r on wi.relation::int =r.id 
			JOIN kaveri.lgd_districtmaster d ON d.districtcode = wi.districtcode
    		 JOIN kaveri.lgd_statemaster s ON d.lgdstatecode = s.statecode
     		JOIN kaveri.lgd_talukmaster g ON g.talukcode = wi.talukcode
			/*left join kaveri.lgd_districtmaster dis ON dis.districtcode = wi.districtcode
			left join kaveri.lgd_statemaster st ON st.statecode  = wi.statecode
			left join kaveri.lgd_talukmaster tal ON tal.talukcode = wi.talukcode*/
			where wi.applicationnumber = ad.applicationnumber) witness
	) as witnessinfo,
	md.ispendingdocument  as ispendingdocument,
	(case when fds.valuatiotypeid=1 then true else false end) as isimpound,
	(case when fds.valuatiotypeid=3 then true else false end) as isundervaluation,
	(case when dm.executiondatetime::date<(now()- interval '4 months')::date then true else false end) as isdelaycondonation
	-- paperless change
	,dm.isdigitallyexecuted,		/* added a new column on 09/02/2026 */
	dm.issignpageappended, 		/* added a new column on 09/02/2026 */
	dm.isthumbregisterdocsigned 	/* added a new column on 17/02/2026 */
  from kaveri.applicantapplicationdetails ad
inner join kaveri.documentmaster dm on (ad.applicationnumber=dm.applicationnumber)
left join kaveri.minutebook_data md on (md.applicationnumber=ad.applicationnumber)
left join (select distinct applicationnumber,valuatiotypeid from kaveri.feesrequired fd where fd.applicationnumber=_applicationnumber) as fds on fds.applicationnumber=ad.applicationnumber 
 join kaveri.servicesmaster sm on (sm.serviceid = ad.applicationtypeid)
 join kaveri.booktypemaster bm on (bm.bookid=dm.bookid)
left join kaveri.stamparticles sa on (sa.stamparticlecode=dm.stamparticlecode)
left join kaveri.registrationarticles ra on (ra.regarticlecode=dm.regarticlecode)
left join kaveri.bhoomifileuploaddetails bh on (dm.finalregistrationnumber = bh.finalregistrationnumber)
left join kaveri.easthi_eswathu_fileuploaddetails ee on (dm.finalregistrationnumber =ee.finalregistrationnumber )
inner join kaveri.sromaster ss on ss.srocode=ad.srocode
-- paperless change
inner join kaveri.districtmaster d on d.districtcode = ss.districtcode
left join kaveri.departmentusers dp on dp.userid = ad.deoid
  where ad.applicationnumber = _applicationnumber and ad.srocode=_srocode
  group by ad.applicationnumber,dm.executiondatetime,
  dm.presentdatetime ,
	dm.finalregistrationnumber,dm.registrationdatetime,dm.isPrintEndorsement,
	dm.pagecount ,sa.articlenamee ,ad.annexurepath,dm.partypaymentdetails,
ra.articlenamee , bm.printablename ,sm.servicename ,
	ad.remarks,fds.valuatiotypeid,dm.executiondatetime,
	ad.remarksk,ss.sronamee,ss.sronamek, --- To fetch the Kannada text added on 28-11-2022
	ad.currentstatus,dm.isscancompleted,ad.applicationtypeid,md.remark_comment,md.reasonid ,md.private_remark,ad.refuseremarks,dm.pendingdocumentnumber,md.ispendingdocument,md.isbefore2003,dm.regarticlecode,
	-- paperless change
	ss.sronamek,
	d.districtnamee,
	d.districtnamek,
	dp.firstname,dp.loginname,
	-- paperless change
	dm.isdigitalsigned,dm.isdigitallyexecuted,dm.issignpageappended,dm.isthumbregisterdocsigned
) app_json ;

return v_data_json1;

END;
$_$;


ALTER FUNCTION kaveri.fn_fetch_documentsummary_json_org_20260717(_applicationnumber text, _srocode bigint) OWNER TO postgres;

--
-- Name: fn_fetch_documentsummary_json_orgbck(text, bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_documentsummary_json_orgbck(_applicationnumber text, _srocode bigint) RETURNS json
    LANGUAGE plpgsql
    AS $_$



declare 
v_data_json1 json;
BEGIN

select row_to_json(app_json) into v_data_json1
from (

  select ad.applicationnumber,dm.executiondatetime::date executedate,
  dm.presentdatetime as presentdate,
regexp_replace(dm.pendingdocumentnumber, '^([^-]*-[^-]*)-.*$', '\1') as pendingdocumentnumber ,
	dm.finalregistrationnumber,dm.registrationdatetime,dm.isPrintEndorsement,
	dm.pagecount ,sa.articlenamee as stamparticlename,dm.regarticlecode,ad.annexurepath,dm.partypaymentdetails,
ra.articlenamee as Naturedeed, bm.printablename as book,sm.servicename as applicationtype,
	ad.remarks,
	ad.remarksk,
	ss.sronamee as sroname ,--- To fetch the Kannada text added on 28-11-2022
	ad.currentstatus,dm.isscancompleted,ad.applicationtypeid,md.remark_comment,md.reasonid,md.private_remark,ad.refuseremarks, 
	string_agg(bh.acknowledgeno,',') as Ysavednumber,
	string_agg(ee.acknowledgeno,',') as acknowledgeno,md.isbefore2003,  
     (
      select array_to_json(array_agg(row_to_json(prpty)))
      from (SELECT pm.applicationnumber,	  
			pm.propertyid,
			pm.documentid,
			stm.articlenamee as stamparticle,
			pm.ismovableproperty,
			d.villagenamee,
			pm.propertytypeid,
			ptm.propertytypename as propertytype,
			c.sronamee sroname,
			pm.northboundary,
			pm.denodescription ,
			pm.estampdescription,
			pm.adjudescription ,
			pm.southboundary,
			pm.eastboundary,
			pm.westboundary,
			pm.landmark,
			pm.consideration,
			pm.marketvalue,
			pm.sroconsideration,
			case when pm.sromarketvalue is null then 0 else pm.sromarketvalue end sromarketvalue,
			pm.cessduty,
			pm.govtduty,
			pm.additionalduty,
			pm.stampduty,
			pm.valid1 as duplicatecopies,
			calc.duplicatefee,
			calc.duplicatestampduty,
			calc.duplicateregistrationfee,
			calc.privateattendancefee,
			--calc.stampduty, 		
			pm.valuationreport,
			pm.sronoofscanpages, /* added a new column on 07/10/2022 to fetch number of scan pages in document summary page */
			sr.ismarketvaluationdone, /* added a new column on 06/11/2022 */
			h.hoblinamee as hobli, /* added a new column on 06/11/2022 */
			srf.ispartytopropertyschd, /* added a new column on 07/11/2022 */
			( select array_to_json(array_agg(row_to_json(schd)))
			  from (
			/*  select ps.propertyid as propertyschedulespropertyid,ps.scheduletype,ps.totalarea,
			  ps.description as scheduledescription,
					case when pm.propertytypeid=17 then
					string_agg(pi.name,',') else null end as bhoomisellerparty ,

					pi.name, pi.ispresenter, pi.isexecutor			

					from kaveri.propertyschedules ps 
					left join kaveri.vw_fetch_party pi on (pi.propertyid = ps.propertyid 
					and pi.applicationnumber=ps.applicationnumber
						)
				   where ps.propertyid = pm.propertyid 
					group by ps.propertyid ,ps.scheduletype,ps.totalarea,ps.description,			
				  pi.name, pi.ispresenter, pi.isexecutor	*/

				  select distinct ps.propertyid as propertyschedulespropertyid, 
						ps.scheduletype, 
						ps.totalarea,
					string_agg(pi.name,',') as bhoomisellername, pnam.firstname as name, ps.description as scheduledescription,
					case when pm.propertytypeid=17 then string_agg(pi.name,',') else null end as bhoomisellerparty,
					ps.eastboundary, ps.westboundary, ps.northboundary, ps.southboundary
				  from kaveri.propertyschedules ps 
				  left join kaveri.vw_fetch_party pi on pi.propertyid = ps.propertyid
				  left join (select ps1.scheduleid, array_to_string(array_agg(distinct pi2.name),',') 
								AS firstname from kaveri.partyschedules ps1
			left join 
						(select name,partyid from kaveri.vw_fetch_party vf where vf.applicationnumber = _applicationnumber ) as pi2 
							 on pi2.partyid = ps1.partyid 
							group by ps1.scheduleid)
				  as pnam on ps.scheduleid = pnam.scheduleid
				  where  ps.propertyid = pm.propertyid 
				  group by ps.propertyid, ps.scheduletype, ps.totalarea, pnam.firstname, ps.description, ps.eastboundary,
				  ps.westboundary, ps.northboundary, ps.southboundary)schd ) as propertyschedules,			
			  ( select array_to_json(array_agg(row_to_json(prptyno)))
			   from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,
					 pntm.typenameenglish as propertynumbertype, pnd.currentnumber, coalesce(pnd.hissa_no,'') as hissa_no,
					 coalesce(pnd.survey_no,0) as survey_no, pnd.description as propertynumberdescription
					from kaveri.propertynumberdetails pnd 
					 left join kaveri.propertynotypemaster pntm on (pntm.propertytypeid = pnd.currentpropertytypeid) 
					 where pnd.propertyid = pm.propertyid )prptyno ) as propertynumberdetails
		   FROM kaveri.propertymaster pm 
		   left join kaveri.propertytypemaster ptm on (ptm.propertytypeid = pm.propertytypeid) 
			left join kaveri.stamparticles stm on (stm.stamparticlecode=pm.stamparticlecode)
			left join kaveri.stamprules sr on pm.stampruleid = sr.stampruleid
			left join kaveri.stamprulesflag srf ON sr.stampruleid = srf.stampruleid
		   left join  kaveri.sromaster c on (pm.srocode = c.srocode)
		   left join kaveri.villagemaster d on (pm.villagecode = d.villagecode)
			left join kaveri.hoblimaster h on d.hoblicode = h.hoblicode
		   left join kaveri.vw_fee_calculation_details_chk_v2 calc on (pm.applicationnumber = calc.applicationnumber)
		   where pm.applicationnumber=ad.applicationnumber) prpty
    ) as propertyinfo,	
	 (
      select array_to_json(array_agg(row_to_json(prty)))
      from (
		select 
		vw_party.applicationnumber,vw_party.partyid,case when (vw_party.aliasname='' or vw_party.aliasname is null)  then  vw_party.name else CONCAT(vw_party.name,', alias:',vw_party.aliasname) end  as partyname,vw_party.age, vw_party.address ,vw_party.profession,
		vw_party.phonenumber,vw_party.epic,vw_party.partytypeid,vw_party.partytypename,vw_party.isexecutor,vw_party.ispresenter,vw_party.admissiondate,
		vw_party.section88exemption,vw_party.fingerid,vw_party.thumbpath,vw_party.photopath,vw_party.idprooftypedesc,vw_party.idproofnumber,
		vw_party.relationship,vw_party.relativename,string_agg(wi.name||' '||wi.middlename||' '||wi.lastname,',') as witness_name ,
		/*isorganization, tanno, organizationid, yearofincorp, linkpartyid, auname, auaddress,
		 aualiasname, 
		auage, ausex, auidprooftypeid, auidprooftypedesc, auidproofnumber, auprofession,
		 poaisorganization,
		poaname, poaaddress, poaage, poasex, poaidproofnumber, poatan, poaprofession,
		 poarelationship, 
		poarelativename,poaidprooftypedesc, poapartytypename, poayearofincorp, 
		orgpoaauthsignfname, orgpoaauthsignmname, orgpoaauthsignlname, minorguardianname,
		 minorguardianage,
		minorguardianrelationship, minorguardianrelativename,*/
		vw_party.isEndorsePrinted,vw_party.gender as sex, vw_party.isorganization, vw_party.tanno, vw_party.minorguardianname, vw_party.poaname,
		vw_party.auname, vw_party.auaddress, vw_party.isprivateattendance, vw_party.coveringletterno, vw_party.thumbremarks,vw_party.ispartyrefused,
		sl.descriptione,vw_party.islateapperance,vw_party.isbiometricrefused,vw_party.iscitizennotappeared	,
		(select row_to_json(aadhar)
		from (select aal.partyid,aal.nameasperaadhar,
		case when aal.partyid is not null 
			then
				case when aal.responsestatus = 'Y' then true 
				 	when aal.responsestatus = 'N' then false
			when aal.partyid is null then null end
		end as aadharverified
		,aal.errormessage from kaveri.aadhar_authentication_log aal
		where aal.partyid = vw_party.partyid 
		order by aal.id desc limit 1)aadhar)as aadharinfo
		from kaveri.vw_fetch_party vw_party 
		left join kaveri.partywitness pw on pw.partyid in (select partyid from kaveri.partyinfo where applicationnumber =_applicationnumber)
		left join  kaveri.salutationmaster sl on vw_party.salutationid=sl.salutationid
		left join kaveri.witnessinfo wi on pw.witnessid = wi.witnessid 
			where vw_party.applicationnumber = ad.applicationnumber 
			group by vw_party.applicationnumber,vw_party.applicationnumber,vw_party.partyid,vw_party.name ,vw_party.age, vw_party.address ,vw_party.profession,
		vw_party.phonenumber,vw_party.epic,vw_party.partytypeid,vw_party.partytypename,vw_party.isexecutor,vw_party.ispresenter,vw_party.admissiondate,
		vw_party.section88exemption,vw_party.fingerid,vw_party.thumbpath,vw_party.photopath,vw_party.idprooftypedesc,vw_party.idproofnumber,
		vw_party.relationship,vw_party.relativename,vw_party.isEndorsePrinted,vw_party.gender, vw_party.isorganization, vw_party.tanno, vw_party.minorguardianname, vw_party.poaname,
		vw_party.auname, vw_party.auaddress, vw_party.isprivateattendance, vw_party.coveringletterno, vw_party.thumbremarks,vw_party.ispartyrefused
		,vw_party.aliasname,sl.descriptione,vw_party.islateapperance,vw_party.isbiometricrefused,vw_party.iscitizennotappeared
			order by partytypeid) prty
    ) as partyinfo,
	(  select array_to_json(array_agg(row_to_json(witness)))
      from (select wi.witnessid, wi.name, wi.houseno, concat(wi.address,' ',d.districtnamee,' ',g.taluknamee,' ',s.statenamee) as address,
			wi.age,wi.applicationnumber,wi."name",r.relatione as relation,wi.relativename,
			/* added a columns houseno, address, pincode and necessary joins for the same, on 07/11/2022 */
			/* Removed above changes, on 07/11/2022 */
			/*(wi.address::text || ', '::text) || (tal.taluknamee::text || ', '::text) || (dis.districtnamee::text || ', '::text) || (st.statenamee::text) || ' '::text AS address,*/
			wi.pincode, wi.age, wi.profession, wi.isEndorsePrinted, wi.sex 
			from kaveri.witnessinfo wi
			left join kaveri.relationshipmasters r on wi.relation::int =r.id 
			JOIN kaveri.lgd_districtmaster d ON d.districtcode = wi.districtcode
    		 JOIN kaveri.lgd_statemaster s ON d.lgdstatecode = s.statecode
     		JOIN kaveri.lgd_talukmaster g ON g.talukcode = wi.talukcode
			/*left join kaveri.lgd_districtmaster dis ON dis.districtcode = wi.districtcode
			left join kaveri.lgd_statemaster st ON st.statecode  = wi.statecode
			left join kaveri.lgd_talukmaster tal ON tal.talukcode = wi.talukcode*/
			where wi.applicationnumber = ad.applicationnumber) witness
	) as witnessinfo,
	md.ispendingdocument  as ispendingdocument,
	(case when fds.valuatiotypeid=1 then true else false end) as isundervaluation,
	(case when fds.valuatiotypeid=3 then true else false end) as isimpound,
	(case when dm.executiondatetime::date<(now()- interval '4 months')::date then true else false end) as isdelaycondonation 
  from kaveri.applicantapplicationdetails ad
inner join kaveri.documentmaster dm on (ad.applicationnumber=dm.applicationnumber)
left join kaveri.minutebook_data md on (md.applicationnumber=ad.applicationnumber)
left join (select distinct applicationnumber,valuatiotypeid from kaveri.feesrequired fd where fd.applicationnumber=_applicationnumber) as fds on fds.applicationnumber=ad.applicationnumber 
 join kaveri.servicesmaster sm on (sm.serviceid = ad.applicationtypeid)
 join kaveri.booktypemaster bm on (bm.bookid=dm.bookid)
left join kaveri.stamparticles sa on (sa.stamparticlecode=dm.stamparticlecode)
left join kaveri.registrationarticles ra on (ra.regarticlecode=dm.regarticlecode)
left join kaveri.bhoomifileuploaddetails bh on (dm.finalregistrationnumber = bh.finalregistrationnumber)
left join kaveri.easthi_eswathu_fileuploaddetails ee on (dm.finalregistrationnumber =ee.finalregistrationnumber )
inner join kaveri.sromaster ss on ss.srocode=ad.srocode
  where ad.applicationnumber = _applicationnumber and ad.srocode=_srocode
  group by ad.applicationnumber,dm.executiondatetime,
  dm.presentdatetime ,
	dm.finalregistrationnumber,dm.registrationdatetime,dm.isPrintEndorsement,
	dm.pagecount ,sa.articlenamee ,ad.annexurepath,dm.partypaymentdetails,
ra.articlenamee , bm.printablename ,sm.servicename ,
	ad.remarks,fds.valuatiotypeid,dm.executiondatetime,
	ad.remarksk,ss.sronamee, --- To fetch the Kannada text added on 28-11-2022
	ad.currentstatus,dm.isscancompleted,ad.applicationtypeid,md.remark_comment,md.reasonid ,md.private_remark,ad.refuseremarks,dm.pendingdocumentnumber,md.ispendingdocument,md.isbefore2003,dm.regarticlecode
) app_json ;

return v_data_json1;

END;
$_$;


ALTER FUNCTION kaveri.fn_fetch_documentsummary_json_orgbck(_applicationnumber text, _srocode bigint) OWNER TO postgres;

--
-- Name: fn_fetch_dro_for_sro_json_check(json[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_dro_for_sro_json_check(json_in json[]) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
 item text;
BEGIN
   for item in select * from json_array_elements_text(json_in ) loop
select row_to_json(dro) into v_data_json
from (
select array_to_json(array_agg(row_to_json(drodetails))) as SRO_identify_concerned_DRO from (
    /*  select a.srocode,a.sronamee,a.districtcode,b.districtnamee from
  kaveri.sromaster a inner join kaveri.districtmaster b
  on  a.districtcode = b.districtcode
  where srocode in ( select srocode from kaveri.villagemaster where villagecode in (json_in))*/  -- input parameters
  --union
  select a.srocode,a.sronamee,a.districtcode,b.districtnamee from
  kaveri.sromaster a inner join kaveri.districtmaster b
  on  a.districtcode = b.districtcode --and a.districtcode in (34,35,36,33,1)
  where a.districtcode in (select a.districtcode from
  kaveri.sromaster a inner join kaveri.districtmaster b
  on  a.districtcode = b.districtcode
  where srocode in ( select srocode from kaveri.villagemaster where villagecode in (json_in)))
  order by srocode,districtcode
		   )
			as drodetails
	) dro;
end loop;
return v_data_json;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_dro_for_sro_json_check(json_in json[]) OWNER TO csgadmin;

--
-- Name: fn_fetch_dro_for_sro_json_check(json); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_dro_for_sro_json_check(json_in json) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
BEGIN
select row_to_json(dro) into v_data_json
from (
select array_to_json(array_agg(row_to_json(drodetails))) as SRO_identify_concerned_DRO from (
      select a.srocode,a.sronamee,a.districtcode,b.districtnamee from
  kaveri.sromaster a inner join kaveri.districtmaster b
  on  a.districtcode = b.districtcode
  where srocode in ( select srocode from kaveri.villagemaster where villagecode in (json_in))  -- input parameters
  union
  select a.srocode,a.sronamee,a.districtcode,b.districtnamee from
  kaveri.sromaster a inner join kaveri.districtmaster b
  on  a.districtcode = b.districtcode and a.districtcode in (34,35,36,33,1)
  where a.districtcode in (select a.districtcode from
  kaveri.sromaster a inner join kaveri.districtmaster b
  on  a.districtcode = b.districtcode
  where srocode in ( select srocode from kaveri.villagemaster where villagecode in (json_in)))
  order by srocode,districtcode
		   )
			as drodetails
	) dro;

return v_data_json;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_dro_for_sro_json_check(json_in json) OWNER TO csgadmin;

--
-- Name: fn_fetch_ec_details_json_check(text); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_ec_details_json_check(_applicationnumber text) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json; 
v_ispropertysearch boolean;      
v_isnamesearch boolean; 
v_isappliedbydept boolean;
BEGIN 

select 
	ispropertysearch, 
	isnamesearch,
	isappliedbydept
	into v_ispropertysearch, v_isnamesearch,v_isappliedbydept		
from kaveri.ec_applicationdetails where applicationnumber = _applicationnumber;
--like 'TMPEC-00027'

if v_isappliedbydept = true
then

		if v_ispropertysearch = true 
		then
		
		select row_to_json(app_json) into v_data_json
		from (
		select
			a.ecid,
		    a.kaverivillagecode,
		    b.villagenamee,
		    a.kaverihoblicode,
		    c.hoblinamee,
		    e.districtcode,
		    d.districtnamee,
		    c.talukcode,
		    f.taluknamee,
		    a.eastboundary AS east,
		    a.westboundary AS west,
		    a.northboundary AS north,
		    a.southboundary AS south,
		    a.easttowest,
		    a.northtosouth,
		    a.measurementunitid,
		    g.descriptionenglish AS units,
		    a.propertydescription AS descriptionofproperty,
		    a.searchfromdate AS fromdate,
		    a.searchtodate AS todate,
			a.ispropertysearch, -- 
			a.isnamesearch,  -- 
			--l.firstname,
		    --l.middlename,
		    --l.lastname,
			--l.phone,
			--l.email,
			a.applicationnumber,
			--l.permanentaddress as  address,
			a.kaverisrocode,
			e.sronamee,
			a.area,
			a.hectare,
			a.acre,
			a.gunta,
			a.cents,
			a.easttowestmeasurement,
		    a.northtosouthmeasurement,
			a.propertytypeid,
			p.propertytypename as propertytype,
			--l.pin as pincode ,
			a.partyname ,
			a.isappliedbydept,
			a.reason,
			a.isbefore2004,
			( select array_to_json(array_agg(row_to_json(propertynodetails)))
		      from (
			  select  i.propertynotypeid,
		    h.typenameenglish AS propertynumbertype,
			i.newpropertynumber AS propdetails,
			presentpropertydetails
				  from kaveri.ec_propertynumberdetails i
				  inner join kaveri.propertynotypemaster h on i.ecid = a.ecid and
				  h.propertytypeid = i.propertynotypeid  
			  )propertynodetails) as propnumberdetails,
			  
			
			( select array_to_json(array_agg(row_to_json(feesinfo)))
		      from (select  k.requiredfeeid,
		    k.feeruleid,
		    k.payableamount,
		    k.ispaid,
		    k.serviceid,
		    k.feedescription from
				kaveri.ec_requiredfees k 
		     JOIN kaveri.feesrulemaster m ON k.ecid = a.ecid and m.feerulecode = k.feeruleid
				   )feesinfo ) as feesdetails
				   
			FROM kaveri.ec_applicationdetails a
		     JOIN kaveri.villagemaster b ON a.kaverivillagecode = b.villagecode
		     JOIN kaveri.hoblimaster c ON b.hoblicode = c.hoblicode
		     JOIN kaveri.talukmaster f ON f.talukcode = c.talukcode
		     JOIN kaveri.sromaster e ON e.srocode = a.kaverisrocode
		     JOIN kaveri.districtmaster d ON d.districtcode = e.districtcode
		     JOIN kaveri.measunitmaster g ON g.unitid = a.measurementunitid::integer
			--JOIN kaveri.citizenmaster l ON l.citizenid = a.userid
			JOIN kaveri.propertytypemaster p on p.propertytypeid = a.propertytypeid
			--JOIN kaveri.partyinfo pi on pi.applicationnumber::text = a.applicationnumber::text
		and a.applicationnumber = _applicationnumber
		) app_json ;
		
		
		else 
		
		select row_to_json(app_json) into v_data_json
		from (
		select
			a.ecid,
		    a.kaverivillagecode,
		    b.villagenamee,
		    a.kaverihoblicode,
		    c.hoblinamee,
		    e.districtcode,
		    d.districtnamee,
		    c.talukcode,
		    f.taluknamee,
		    a.eastboundary AS east,
		    a.westboundary AS west,
		    a.northboundary AS north,
		    a.southboundary AS south,
		    a.easttowest,
		    a.northtosouth,
		    a.measurementunitid,
		   --  g.descriptionenglish AS units,
		    null AS units,
		    a.propertydescription AS descriptionofproperty,
		    a.searchfromdate AS fromdate,
		    a.searchtodate AS todate,
			a.ispropertysearch, -- 
			a.isnamesearch,  -- 
			--l.firstname,
		    --l.middlename,
		    --l.lastname,
			--l.phone,
			--l.email,
			a.applicationnumber,
			--l.permanentaddress as  address,
			a.kaverisrocode,
			e.sronamee,
			a.area,
			a.hectare,
			a.acre,
			a.gunta,
			a.cents,
			a.easttowestmeasurement,
		    a.northtosouthmeasurement,
			a.propertytypeid,
			--p.propertytypename as propertytype,
			--l.pin as pincode ,
			
			a.partyname , 
			a.isappliedbydept,
			a.reason,
			a.isbefore2004,
			( select array_to_json(array_agg(row_to_json(propertynodetails)))
		      from (
			  select  i.propertynotypeid,
		    h.typenameenglish AS propertynumbertype,
			i.newpropertynumber AS propdetails,
			presentpropertydetails
				  from kaveri.ec_propertynumberdetails i
				  inner join kaveri.propertynotypemaster h on i.ecid = a.ecid and
				  h.propertytypeid = i.propertynotypeid  
			  )propertynodetails) as propnumberdetails,  
			( select array_to_json(array_agg(row_to_json(feesinfo)))
		      from (select  k.requiredfeeid,
		    k.feeruleid,
		    k.payableamount,
		    k.ispaid,
		    k.serviceid,
		    k.feedescription from
				kaveri.ec_requiredfees k 
		     JOIN kaveri.feesrulemaster m ON k.ecid = a.ecid and m.feerulecode = k.feeruleid
				   )feesinfo ) as feesdetails
			FROM kaveri.ec_applicationdetails a
		     JOIN kaveri.villagemaster b ON a.kaverivillagecode = b.villagecode
		     JOIN kaveri.hoblimaster c ON b.hoblicode = c.hoblicode
		     JOIN kaveri.talukmaster f ON f.talukcode = c.talukcode
		     JOIN kaveri.sromaster e ON e.srocode = a.kaverisrocode
		     JOIN kaveri.districtmaster d ON d.districtcode = e.districtcode
		     --JOIN kaveri.measunitmaster g ON g.unitid = a.measurementunitid::integer
			--JOIN kaveri.citizenmaster l ON l.citizenid = a.userid
			--JOIN kaveri.propertytypemaster p on p.propertytypeid = a.propertytypeid
			--JOIN kaveri.partyinfo pi on pi.applicationnumber::text = a.applicationnumber::text
		and a.applicationnumber = _applicationnumber
		) app_json ;
	end if;
	
else
		if v_ispropertysearch = true
		then
		select row_to_json(app_json) into v_data_json
		from (
		select
			a.ecid,
		    a.kaverivillagecode,
		    b.villagenamee,
		    a.kaverihoblicode,
		    c.hoblinamee,
		    e.districtcode,
		    d.districtnamee,
		    c.talukcode,
		    f.taluknamee,
		    a.eastboundary AS east,
		    a.westboundary AS west,
		    a.northboundary AS north,
		    a.southboundary AS south,
		    a.easttowest,
		    a.northtosouth,
		    a.measurementunitid,
		    g.descriptionenglish AS units,
		    a.propertydescription AS descriptionofproperty,
		    a.searchfromdate AS fromdate,
		    a.searchtodate AS todate,
			a.ispropertysearch, -- 
			a.isnamesearch,  -- 
			l.firstname,
		    l.middlename,
		    l.lastname,
			l.phone,
			l.email,
			a.applicationnumber,
			l.permanentaddress as  address,
			a.kaverisrocode,
			e.sronamee,
			a.area,
			a.hectare,
			a.acre,
			a.gunta,
			a.cents,
			a.easttowestmeasurement,
		    a.northtosouthmeasurement,
			a.propertytypeid,
			p.propertytypename as propertytype,
			--l.pin as pincode ,
			a.partyname ,
			a.isappliedbydept,
			a.reason,
			a.isbefore2004,
			( select array_to_json(array_agg(row_to_json(propertynodetails)))
		      from (
			  select  i.propertynotypeid,
		    h.typenameenglish AS propertynumbertype,
			i.newpropertynumber AS propdetails,
			presentpropertydetails
				  from kaveri.ec_propertynumberdetails i
				  inner join kaveri.propertynotypemaster h on i.ecid = a.ecid and
				  h.propertytypeid = i.propertynotypeid  
			  )propertynodetails) as propnumberdetails,
			  
			
			( select array_to_json(array_agg(row_to_json(feesinfo)))
		      from (select  k.requiredfeeid,
		    k.feeruleid,
		    k.payableamount,
		    k.ispaid,
		    k.serviceid,
		    k.feedescription from
				kaveri.ec_requiredfees k 
		     JOIN kaveri.feesrulemaster m ON k.ecid = a.ecid and m.feerulecode = k.feeruleid
				   )feesinfo ) as feesdetails
				   
			FROM kaveri.ec_applicationdetails a
		     JOIN kaveri.villagemaster b ON a.kaverivillagecode = b.villagecode
		     JOIN kaveri.hoblimaster c ON b.hoblicode = c.hoblicode
		     JOIN kaveri.talukmaster f ON f.talukcode = c.talukcode
		     JOIN kaveri.sromaster e ON e.srocode = a.kaverisrocode
		     JOIN kaveri.districtmaster d ON d.districtcode = e.districtcode
		     JOIN kaveri.measunitmaster g ON g.unitid = a.measurementunitid::integer
			JOIN kaveri.citizenmaster l ON l.citizenid = a.userid
			JOIN kaveri.propertytypemaster p on p.propertytypeid = a.propertytypeid
			--JOIN kaveri.partyinfo pi on pi.applicationnumber::text = a.applicationnumber::text
		and a.applicationnumber = _applicationnumber
		) app_json ;
		
		
		else 
		
		select row_to_json(app_json) into v_data_json
		from (
		select
			a.ecid,
		    a.kaverivillagecode,
		    b.villagenamee,
		    a.kaverihoblicode,
		    c.hoblinamee,
		    e.districtcode,
		    d.districtnamee,
		    c.talukcode,
		    f.taluknamee,
		    a.eastboundary AS east,
		    a.westboundary AS west,
		    a.northboundary AS north,
		    a.southboundary AS south,
		    a.easttowest,
		    a.northtosouth,
		    a.measurementunitid,
		   --  g.descriptionenglish AS units,
		    null AS units,
		    a.propertydescription AS descriptionofproperty,
		    a.searchfromdate AS fromdate,
		    a.searchtodate AS todate,
			a.ispropertysearch, -- 
			a.isnamesearch,  -- 
			l.firstname,
		    l.middlename,
		    l.lastname,
			l.phone,
			l.email,
			a.applicationnumber,
			l.permanentaddress as  address,
			a.kaverisrocode,
			e.sronamee,
			a.area,
			a.hectare,
			a.acre,
			a.gunta,
			a.cents,
			a.easttowestmeasurement,
		    a.northtosouthmeasurement,
			a.propertytypeid,
			--p.propertytypename as propertytype,
			l.pin as pincode ,
			
			a.partyname , 
			a.isappliedbydept,
			a.reason,
			a.isbefore2004,
			( select array_to_json(array_agg(row_to_json(propertynodetails)))
		      from (
			  select  i.propertynotypeid,
		    h.typenameenglish AS propertynumbertype,
			i.newpropertynumber AS propdetails,
			presentpropertydetails
				  from kaveri.ec_propertynumberdetails i
				  inner join kaveri.propertynotypemaster h on i.ecid = a.ecid and
				  h.propertytypeid = i.propertynotypeid  
			  )propertynodetails) as propnumberdetails,
			  
			
			( select array_to_json(array_agg(row_to_json(feesinfo)))
		      from (select  k.requiredfeeid,
		    k.feeruleid,
		    k.payableamount,
		    k.ispaid,
		    k.serviceid,
		    k.feedescription from
				kaveri.ec_requiredfees k 
		     JOIN kaveri.feesrulemaster m ON k.ecid = a.ecid and m.feerulecode = k.feeruleid
				   )feesinfo ) as feesdetails
				   
			FROM kaveri.ec_applicationdetails a
		     JOIN kaveri.villagemaster b ON a.kaverivillagecode = b.villagecode
		     JOIN kaveri.hoblimaster c ON b.hoblicode = c.hoblicode
		     JOIN kaveri.talukmaster f ON f.talukcode = c.talukcode
		     JOIN kaveri.sromaster e ON e.srocode = a.kaverisrocode
		     JOIN kaveri.districtmaster d ON d.districtcode = e.districtcode
		     --JOIN kaveri.measunitmaster g ON g.unitid = a.measurementunitid::integer
			JOIN kaveri.citizenmaster l ON l.citizenid = a.userid
			--JOIN kaveri.propertytypemaster p on p.propertytypeid = a.propertytypeid
			--JOIN kaveri.partyinfo pi on pi.applicationnumber::text = a.applicationnumber::text
		and a.applicationnumber = _applicationnumber
		) app_json ;

end if ;
end if;

return v_data_json;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_ec_details_json_check(_applicationnumber text) OWNER TO csgadmin;

--
-- Name: fn_fetch_ec_json_check(integer, kaveri.ec_srch_property[], timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_ec_json_check(_villagecode integer, p_srch_property kaveri.ec_srch_property[], _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS json
    LANGUAGE plpgsql
    AS $$
 
 
declare 

v_data_json json;

begin

select row_to_json(data_json)::json into v_data_json from ( 

select array_to_json(array_agg(row_to_json(app_json)))

--select row_to_json(app_json) into v_data_json

from ( select 

pm.applicationnumber,

pm.propertyid,

pm.marketvalue,

pm.sroconsideration as consideration,

ra.articlenamee,

pm.eastboundary AS east,

pm.westboundary AS west,

pm.northboundary AS north,

pm.southboundary AS south,

pm.totalarea AS area,

pm.villagecode,

v.villagenamee,

v.hoblicode,

h.hoblinamee,

--r.referencetext,

(select referencetext from kaveri.referencemaster where documentid=dm.documentid order by lstupddate desc limit 1),

( select array_to_json(array_agg(row_to_json(propertynodetails)))

      from ( select 

pn.currentpropertytypeid,

pn.currentnumber

-- pn.currentnumber AS aptno_new,

-- pn.oldnumber AS oldno

from  kaveri.propertynumberdetails pn WHERE

			pm.propertyid = pn.propertyid  

			and (pn.currentpropertytypeid, pn.currentnumber) in (select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a )

  )propertynodetails) as propnumberdetails,

( select array_to_json(array_agg(row_to_json(propertyschedules)))

      from ( 

--Code Begins for Property Schedules

-- Left Join is required at partyschedules and partyinfo to fetch propertyschedules where partyid is null

select 

ps.easttowest,

ps.northtosouth,

case when pas.propertyid is not null 

then

case when  ps.description is not null and  ps.description<>'' then  

concat(ps.description, ' Allotted to: ', string_agg(pin.firstname || pin.middlename || pin.lastname,' & '),' ',zn.zonenamee,' zonename')

else concat('District: ', d.districtnamee,', ' , 'Taluk: ', tm.taluknamee,', ' , 'Village: ',v2.villagenamee,', ', '', 'Survey No: ',p.survey_no,', ', 'Hissa No: ', p.hissa_no,', ', 'BoundaryDetails: [North: ',ps.northboundary,', '

, 'East: ',ps.eastboundary,', '

, 'West: ', ps.westboundary,', ', 'South: ', ps.southboundary,', ','] measuring ',ps.totalarea,' acre',zn.zonenamee,' zonename') end 

else

ps.description end as

description

from kaveri.propertyschedules ps 

join kaveri.propertynumberdetails p on ps.propertyid=p.propertyid 

join kaveri.propertymaster pp on ps.propertyid=pp.propertyid 

left join kaveri.zonemaster zn on zn.zoneid=pp.zoneid

left join kaveri.partyschedules pas on ps.propertyid=pas.propertyid 

left join kaveri.partyinfo pin on pas.partyid=pin.partyid 

join kaveri.villagemaster v2 on pp.villagecode=v2.villagecode 

join kaveri.talukmaster tm on v2.talukcode =tm.talukcode --, p.currentnumber) 

join kaveri.districtmaster d on tm.districtcode =d.districtcode 

where ps.propertyid = pm.propertyid and (p.currentpropertytypeid, p.currentnumber) in (select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a )

		   group by ps.easttowest, ps.northtosouth,ps.description,pas.propertyid,d.districtnamee,tm.taluknamee,v2.villagenamee,p.survey_no,p.hissa_no,ps.northboundary

		   ,ps.eastboundary,ps.westboundary,ps.southboundary,ps.totalarea,zn.zonenamee

--Code Ends for Property Schedules	  

)propertyschedules)as propertyschedules,

( select array_to_json(array_agg(row_to_json(partydetails)))

      from ( select distinct p.partyid,

-- (

--        CASE

--            WHEN pi.partytypeid = 1 THEN concat(pi.firstname, pi.middlename, pi.lastname)

--            ELSE NULL::text

--        END::text) AS claimant,

          CASE

	            when p1.partytypeid = 4 AND p2.firstname IS NOT NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is rep. by minor guardian ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ', whose POA is ', s2.descriptione, p2.firstname, ' ', p2.middlename, ' ', p2.lastname)

	            WHEN p1.partytypeid = 4 AND p2.firstname IS NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is rep. by minor guardian ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)

	            WHEN p1.partytypeid = 5 AND p.isorganization = true THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' POA by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ' is Rep. by ', p1.orgpoaauthsignfname, ' ', p1.orgpoaauthsignlname)

	            WHEN p1.partytypeid = 5 AND p.isorganization = false THEN concat(s1.descriptione, p1.firstname, ' is POA of ', s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)

	            WHEN p1.partytypeid = 9 AND p.isorganization = true AND p2.firstname IS NOT NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is Rep. by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ', whose POA is ', s2.descriptione, p2.firstname, ' ', p2.middlename, ' ', p2.lastname)

	            WHEN p1.partytypeid = 9  AND p.isorganization = true AND p2.firstname IS NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is Rep. by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)

	            WHEN p1.partytypeid IS NULL AND p.partytypeid = 1 THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)

	            WHEN p1.partytypeid IS NULL AND p.partytypeid = 2 THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)

	            ELSE NULL::text

	        END AS partyname,

        p.partytypeid ,

-- (

--        CASE

--            WHEN pi.partytypeid = 2 THEN concat(pi.firstname, pi.middlename, pi.lastname)

--            ELSE NULL::text

--        END::text) AS executant,

        --# left join is necessary because in partyschedules table we are not capturing claimaint details

		     p.address from kaveri.partyinfo p

			left JOIN kaveri.partyinfo p1 ON p.partyid = p1.linkpartyid AND (p1.partytypeid = ANY (ARRAY[9, 4, 5]))

			left JOIN kaveri.partyinfo p2 ON p2.linkpartyid = p1.partyid AND (p2.partytypeid = ANY (ARRAY[5]))

			left JOIN kaveri.salutationmaster s ON p.salutationid = s.salutationid

			left JOIN kaveri.salutationmaster s1 ON p1.salutationid = s1.salutationid

			left JOIN kaveri.salutationmaster s2 ON p2.salutationid = s2.salutationid

		--	left  join kaveri.partyschedules ps on pi.partyid=ps.partyid 

			where p.documentid = dm.documentid

--group by pi.partyid,pi.address,ps.propertyid

)partydetails) as partydetails,

( select array_to_json(array_agg(row_to_json(documentdetails)))

   from (select dm.documentid,

    dm.srocode,

    dm.registrationdatetime AS executiondate,

    dm.cdnumber,

    dm.pagecount,

    dm.finalregistrationnumber AS documentreference)documentdetails)as documentdetails, 
	--(select note_enteredpart from kaveri.dec_drpndnote where propertyid=pm.propertyid order by insertdatetime desc limit 1) as correctionnote,--Commented on 02-01-24 by Shubham
 
	(select note_enteredpart from kaveri.dec_drpndnote where orderid in (select orderid from kaveri.dec_drordermaster d where statuscode = 4 and d.documentid = dm.documentid order by d.insertdatetime desc limit 1)
order by insertdatetime desc limit 1) as correctionnote,--Added on 02-01-24 by Shubham, to fetch correction note based on document and not property.

	(select string_agg(concat('1. Liability Details: Order Number: ', ld.ordernumber, ', Issue Date: ', TO_CHAR(ld.issuedate ::date, 'dd/mm/yyyy'), 

	 	',Liability Note: ', ld.liabilitynote, '<br>2.  Additional Note: ', ld.liabilityadditionalnote),';<br> ') 

		from kaveri.liabilityonpropertydetails lop

		 join kaveri.liabilitydetails ld on lop.liabilityid = ld.liabilityid 

		--left join kaveri.liabilitynoteadditionaldetails lnad on lnad.liabilityid=ld.liabilityid 

	 where lop.propertyid = pm.propertyid) as liabilitynote

from kaveri.propertymaster pm inner join kaveri.villagemaster v on pm.villagecode = v.villagecode

--inner join kaveri.propertynumberdetails pn_src  on pm.propertyid = pn_src.propertyid and (pn_src.currentpropertytypeid, pn_src.currentnumber) in (select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a )  --and pn_src.srocode = v.srocode

join (select distinct propertyid from kaveri.propertynumberdetails p where(p.currentpropertytypeid, p.currentnumber) 

in (select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a ) ) as pn_src on pn_src.propertyid=pm.propertyid

inner JOIN kaveri.hoblimaster h ON v.hoblicode = h.hoblicode

JOIN kaveri.documentmaster dm ON pm.documentid = dm.documentid  and dm.finalregistrationnumber is not null and Isregistrationcompleted=true

JOIN kaveri.registrationarticles ra ON ra.regarticlecode = dm.regarticlecode

where  v.villagecode = _villagecode and dm.bookid not in (3, 4) and pm.ismovableproperty = false

and dm.registrationdatetime::date >= _fromdate and dm.registrationdatetime::date <= _todate 

)  app_json ) data_json;

return v_data_json;

END;

$$;


ALTER FUNCTION kaveri.fn_fetch_ec_json_check(_villagecode integer, p_srch_property kaveri.ec_srch_property[], _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO csgadmin;

--
-- Name: fn_fetch_ec_json_check_1(integer, kaveri.ec_srch_property[], timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_ec_json_check_1(_villagecode integer, p_srch_property kaveri.ec_srch_property[], _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
begin
	
	
select row_to_json(data_json)::json into v_data_json from ( 
select array_to_json(array_agg(row_to_json(app_json)))
	
--select row_to_json(app_json) into v_data_json
from ( select 
 pm.applicationnumber,
 pm.propertyid,
 pm.marketvalue,
 pm.sroconsideration as consideration,
 ra.articlenamee,
 pm.eastboundary AS east,
 pm.westboundary AS west,
 pm.northboundary AS north,
 pm.southboundary AS south,
 pm.totalarea AS area,
 pm.villagecode,
 v.villagenamee,
 v.hoblicode,
 h.hoblinamee,
 --r.referencetext,
 (select referencetext from kaveri.referencemaster where documentid=dm.documentid order by lstupddate desc limit 1),
( select array_to_json(array_agg(row_to_json(propertynodetails)))
      from ( select 
pn.currentpropertytypeid,
 pn.currentnumber
-- pn.currentnumber AS aptno_new,
-- pn.oldnumber AS oldno
from  kaveri.propertynumberdetails pn WHERE
			pm.propertyid = pn.propertyid  
			and (pn.currentpropertytypeid, pn.currentnumber) in (select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a )
  )propertynodetails) as propnumberdetails,
( select array_to_json(array_agg(row_to_json(propertyschedules)))
      from ( 
--Code Begins for Property Schedules
-- Left Join is required at partyschedules and partyinfo to fetch propertyschedules where partyid is null
select 
ps.easttowest,
 ps.northtosouth,
 case when pas.propertyid is not null 
 then
 case when  ps.description is not null and  ps.description<>'' then  
 concat(ps.description, ' Allotted to: ', string_agg(pin.firstname || pin.middlename || pin.lastname,' & '))
 else concat('District: ', d.districtnamee,', ' , 'Taluk: ', tm.taluknamee,', ' , 'Village: ',v2.villagenamee,', ', '', 'Survey No: ',p.survey_no,', ', 'Hissa No: ', p.hissa_no,', ', 'BoundaryDetails: [North: ',ps.northboundary,', '
 , 'East: ',ps.eastboundary,', '
 , 'West: ', ps.westboundary,', ', 'South: ', ps.southboundary,', ','] measuring ',ps.totalarea,' acre') end 
else
ps.description end as
 description
from kaveri.propertyschedules ps 
join kaveri.propertynumberdetails p on ps.propertyid=p.propertyid 
join kaveri.propertymaster pp on ps.propertyid=pp.propertyid 
left join kaveri.partyschedules pas on ps.propertyid=pas.propertyid 
left join kaveri.partyinfo pin on pas.partyid=pin.partyid 
join kaveri.villagemaster v2 on pp.villagecode=v2.villagecode 
join kaveri.talukmaster tm on v2.talukcode =tm.talukcode --, p.currentnumber) 
join kaveri.districtmaster d on tm.districtcode =d.districtcode 
where ps.propertyid = pm.propertyid and (p.currentpropertytypeid, p.currentnumber) in (select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a )
		   group by ps.easttowest, ps.northtosouth,ps.description,pas.propertyid,d.districtnamee,tm.taluknamee,v2.villagenamee,p.survey_no,p.hissa_no,ps.northboundary
		   ,ps.eastboundary,ps.westboundary,ps.southboundary,ps.totalarea
--Code Ends for Property Schedules	  
)propertyschedules)as propertyschedules,
( select array_to_json(array_agg(row_to_json(partydetails)))
      from ( select distinct pi.partyid,
-- (
--        CASE
--            WHEN pi.partytypeid = 1 THEN concat(pi.firstname, pi.middlename, pi.lastname)
--            ELSE NULL::text
--        END::text) AS claimant,
        concat(pi.firstname, pi.middlename, pi.lastname) as partyname,
        pi.partytypeid,
-- (
--        CASE
--            WHEN pi.partytypeid = 2 THEN concat(pi.firstname, pi.middlename, pi.lastname)
--            ELSE NULL::text
--        END::text) AS executant,
        --# left join is necessary because in partyschedules table we are not capturing claimaint details
		     pi.address from kaveri.partyinfo pi 
			left  join kaveri.partyschedules ps on pi.partyid=ps.partyid 
			where pi.documentid = dm.documentid
--group by pi.partyid,pi.address,ps.propertyid
)partydetails) as partydetails,
( select array_to_json(array_agg(row_to_json(documentdetails)))
   from (select dm.documentid,
    dm.srocode,
    dm.registrationdatetime AS executiondate,
    dm.cdnumber,
    dm.pagecount,
    dm.finalregistrationnumber AS documentreference)documentdetails)as documentdetails, 
	(select note_enteredpart from kaveri.dec_drpndnote where propertyid=pm.propertyid order by insertdatetime desc limit 1) as correctionnote,
	(select string_agg(concat('1. Liability Details: Order Number: ', ld.ordernumber, ', Issue Date: ', TO_CHAR(ld.issuedate ::date, 'dd/mm/yyyy'), 
	 	',Liability Note: ', ld.liabilitynote, '<br>2.  Additional Note: ', ld.liabilityadditionalnote),';<br> ') 
		from kaveri.liabilityonpropertydetails lop
		 join kaveri.liabilitydetails ld on lop.liabilityid = ld.liabilityid 
		--left join kaveri.liabilitynoteadditionaldetails lnad on lnad.liabilityid=ld.liabilityid 
	 where lop.propertyid = pm.propertyid) as liabilitynote
from kaveri.propertymaster pm inner join kaveri.villagemaster v on pm.villagecode = v.villagecode
--inner join kaveri.propertynumberdetails pn_src  on pm.propertyid = pn_src.propertyid and (pn_src.currentpropertytypeid, pn_src.currentnumber) in (select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a )  --and pn_src.srocode = v.srocode
join (select distinct propertyid from kaveri.propertynumberdetails p where(p.currentpropertytypeid, p.currentnumber) 
in (select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a ) ) as pn_src on pn_src.propertyid=pm.propertyid
inner JOIN kaveri.hoblimaster h ON v.hoblicode = h.hoblicode
JOIN kaveri.documentmaster dm ON pm.documentid = dm.documentid  and dm.finalregistrationnumber is not null and Isregistrationcompleted=true
JOIN kaveri.registrationarticles ra ON ra.regarticlecode = dm.regarticlecode
where  v.villagecode = _villagecode and dm.bookid not in (3, 4) and pm.ismovableproperty = false
and dm.registrationdatetime::date >= _fromdate and dm.registrationdatetime::date <= _todate 
)  app_json ) data_json;
return v_data_json;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_ec_json_check_1(_villagecode integer, p_srch_property kaveri.ec_srch_property[], _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_fetch_ec_json_check_appno(integer, kaveri.ec_srch_property[], timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_ec_json_check_appno(_villagecode integer, p_srch_property kaveri.ec_srch_property[], _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS json
    LANGUAGE plpgsql
    AS $_$
 
 
declare 

v_data_json json;

begin
select row_to_json(data_json)::json into v_data_json from ( 
select array_to_json(array_agg(row_to_json(propertynodetails))) --into v_data_json
from ( select distinct pm.applicationnumber,pm.propertyid,
CASE
    WHEN arl.newapplicationnumber is not null THEN
     not (arl.ismemosent and arl.isjurisdictionsroaccepted)
    ELSE false
end as isremove
from  kaveri.propertynumberdetails pn
join  kaveri.propertymaster pm on pn.propertyid=pm.propertyid
left join kaveri.anywhere_reg_log arl on pm.applicationnumber = arl.newapplicationnumber
join kaveri.documentmaster dm  on dm.applicationnumber =pm.applicationnumber
WHERE
(pn.currentpropertytypeid, REGEXP_REPLACE(pn.currentnumber, '^[\s\u00A0]+|[\s\u00A0]+$', '', 'g')) 
in (select a._currentproperttypeid
,a._currentnumber from unnest (p_srch_property) a )
and pm.villagecode=_villagecode
and dm.registrationdatetime between _fromdate and _todate
and Isregistrationcompleted=true --dm.finalregistrationnumber is not null and 
and dm.bookid not in (3, 4)
and pm.ismovableproperty = false
--) in 
--(select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a )
)propertynodetails) data_json;

return v_data_json;

END;

$_$;


ALTER FUNCTION kaveri.fn_fetch_ec_json_check_appno(_villagecode integer, p_srch_property kaveri.ec_srch_property[], _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_fetch_ec_json_check_appno_1(integer, kaveri.ec_srch_property[], timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_ec_json_check_appno_1(_villagecode integer, p_srch_property kaveri.ec_srch_property[], _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS json
    LANGUAGE plpgsql
    AS $$
 
 
declare 

v_data_json json;

begin
select row_to_json(data_json)::json into v_data_json from ( 
select array_to_json(array_agg(row_to_json(propertynodetails))) --into v_data_json
from ( select 
distinct pm.applicationnumber,pm.propertyid
from  kaveri.propertynumberdetails pn
join  (select distinct propertyid,documentid,applicationnumber,villagecode,ismovableproperty 
from  kaveri.propertymaster) pm  on pn.propertyid=pm.propertyid 
join kaveri.documentmaster dm  on pm.applicationnumber =pm.applicationnumber 
WHERE
(pn.currentpropertytypeid, pn.currentnumber) in (select a._currentproperttypeid
,a._currentnumber from unnest (p_srch_property) a )
and pm.villagecode=_villagecode
and dm.registrationdatetime>=_fromdate
and dm.registrationdatetime<=_todate
and dm.finalregistrationnumber is not null and Isregistrationcompleted=true and dm.bookid not in (3, 4)
and pm.ismovableproperty = false
--) in 
--(select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a )
)propertynodetails) data_json;

return v_data_json;

END;

$$;


ALTER FUNCTION kaveri.fn_fetch_ec_json_check_appno_1(_villagecode integer, p_srch_property kaveri.ec_srch_property[], _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_fetch_ec_json_check_docdetails(character varying, bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_ec_json_check_docdetails(_applicationnumber character varying, _propertyid bigint) RETURNS json
    LANGUAGE plpgsql
    AS $$
 
 
declare 

v_data_json json;

begin
select row_to_json(data_json)::json into v_data_json from ( 
select array_to_json(array_agg(row_to_json(app_json)))

--select row_to_json(app_json) into v_data_json

from ( select 

pm.applicationnumber,

pm.propertyid,

pm.sromarketvalue as marketvalue,

pm.sroconsideration as consideration,

ra.articlenamee,

s.descriptione as subarticlenamee,

pm.eastboundary AS east,

pm.westboundary AS west,

pm.northboundary AS north,

pm.southboundary AS south,

pm.totalarea AS area,

pm.villagecode,

v.villagenamee,

v.hoblicode,

h.hoblinamee,
(select referencetext from kaveri.referencemaster where documentid=dm.documentid order by lstupddate desc limit 1),
(select array_to_json(array_agg(row_to_json(documentdetails)))

   from (select dm.documentid,

    dm.srocode,

    dm.executiondatetime AS executiondate,

    dm.cdnumber,

    dm.pagecount,

    dm.finalregistrationnumber AS documentreference)documentdetails)as documentdetails, 
	(select note_enteredpart from kaveri.dec_drpndnote where orderid in (select orderid from kaveri.dec_drordermaster d where statuscode = 4 and d.documentid = dm.documentid order by d.insertdatetime desc limit 1)
	order by insertdatetime desc limit 1) as correctionnote,--Added on 02-01-24 by Shubham, to fetch correction note based on document and not property.
	(select string_agg(concat('1. Liability Details: Order Number: ', ld.ordernumber, ', Issue Date: ', TO_CHAR(ld.issuedate ::date, 'dd/mm/yyyy'), 
	',Liability Note: ', ld.liabilitynote, '<br>2.  Additional Note: ', ld.liabilityadditionalnote),';<br> ') 
	from kaveri.liabilityonpropertydetails lop
	join kaveri.liabilitydetails ld on lop.liabilityid = ld.liabilityid 
	where lop.propertyid = pm.propertyid) as liabilitynote
	
	from kaveri.propertymaster pm inner join kaveri.villagemaster v on pm.villagecode = v.villagecode
	join kaveri.stamprules s on s.stampruleid = pm.stampruleid
	inner JOIN kaveri.hoblimaster h ON v.hoblicode = h.hoblicode
	JOIN kaveri.documentmaster dm ON pm.documentid = dm.documentid  and dm.finalregistrationnumber is not null and Isregistrationcompleted=true
	JOIN kaveri.registrationarticles ra ON ra.regarticlecode = dm.regarticlecode
	where dm.applicationnumber =_applicationnumber and pm.propertyid=_propertyid
	and dm.finalregistrationnumber is not null and Isregistrationcompleted=true and dm.bookid not in (3, 4)
	and pm.ismovableproperty = false
	)  app_json ) data_json;
return v_data_json;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_ec_json_check_docdetails(_applicationnumber character varying, _propertyid bigint) OWNER TO postgres;

--
-- Name: fn_fetch_ec_json_check_docdetails(character varying, bigint, integer, kaveri.ec_srch_property[]); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_ec_json_check_docdetails(_applicationnumber character varying, _propertyid bigint, _villagecode integer, p_srch_property kaveri.ec_srch_property[]) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare
 
v_data_json json;
 
begin
select row_to_json(data_json)::json into v_data_json from (
select array_to_json(array_agg(row_to_json(app_json)))
 
--select row_to_json(app_json) into v_data_json
 
from ( select
 
pm.applicationnumber,
 
pm.propertyid,
 
pm.sromarketvalue as marketvalue,
 
pm.sroconsideration as consideration,
 
ra.articlenamee,
 
s.descriptione as subarticlenamee,
 
pm.eastboundary AS east,
 
pm.westboundary AS west,
 
pm.northboundary AS north,
 
pm.southboundary AS south,
 
pm.totalarea AS area,
 
pm.villagecode,
 
v.villagenamee,
 
v.hoblicode,
 
h.hoblinamee,
(select referencetext from kaveri.referencemaster where documentid=dm.documentid order by lstupddate desc limit 1),
(select array_to_json(array_agg(row_to_json(documentdetails)))
 
   from (select dm.documentid,
 
    dm.srocode,
 
    dm.executiondatetime AS executiondate,
 
    dm.cdnumber,
 
    dm.pagecount,
 
    dm.finalregistrationnumber AS documentreference)documentdetails)as documentdetails,
	
--(select dd.note_enteredpart || ', as per the order number '::text || tab2.ordernumber::text || ' dated '::text ||
--	to_char(tab2.orderdate, 'dd-mm-yyyy'::text)  from kaveri.dec_drpndnote dd join
--	(select d.orderid,e.propertyid,d.ordernumber,d.orderdate from kaveri.dec_drordermaster d join
--	kaveri.ecpropertysearchkeyvalues e on d.orderid=e.orderid
--	where statuscode = 4 and d.documentid = dm.documentid
--	and e.propertyid=_propertyid and e.villagecode=_villagecode
--	order by d.insertdatetime desc limit 1) tab2 on dd.orderid=tab2.orderid and dd.propertyid=tab2.propertyid order by insertdatetime desc limit 1) as correctionnote,--Added on 02-01-24 by Shubham, to fetch correction note based on document and not property.
	
(select dd.note_enteredpart || ', as per the order number '::text || d.ordernumber::text || ' dated '::text ||
	to_char(d.orderdate, 'dd-mm-yyyy'::text) 
	from kaveri.dec_drpndnote dd 
	join kaveri.dec_drordermaster d on dd.orderid=d.orderid 
	where dd.propertyid=_propertyid and d.documentid = dm.documentid and d.statuscode = 4  
	order by d.insertdatetime desc limit 1) as correctionnote,

	(select array_agg('Liability Details: Order Number: '|| ld.ordernumber || ', Issue Date: ' || TO_CHAR(ld.orderdate ::date, 'dd/mm/yyyy') ||
	',Liability Note: ' || ld.liabilitynote || case when ld.liabilityamount is not null then ',Liability Amount: ' || ld.liabilityamount else '' end || CASE WHEN ld.iscleared = true THEN ',#Cleared with note: ' || COALESCE(ld.clearnote, '') ELSE '' END)
	from kaveri.liabilitydetails_new ld
	where ld.propertyid = pm.propertyid group by ld.propertyid) as liabilitydetails
 
	from kaveri.propertymaster pm
	inner join kaveri.villagemaster v on pm.villagecode = v.villagecode
	join kaveri.stamprules s on s.stampruleid = pm.stampruleid
	inner JOIN kaveri.hoblimaster h ON v.hoblicode = h.hoblicode
	JOIN kaveri.documentmaster dm ON pm.documentid = dm.documentid  and dm.finalregistrationnumber is not null and Isregistrationcompleted=true
	JOIN kaveri.registrationarticles ra ON ra.regarticlecode = dm.regarticlecode
	where dm.applicationnumber =_applicationnumber and pm.propertyid=_propertyid
	and dm.finalregistrationnumber is not null and Isregistrationcompleted=true and dm.bookid not in (3, 4)
	and pm.ismovableproperty = false
	)  app_json ) data_json;
return v_data_json;
END;
$$;


