ALTER FUNCTION kaveri.fn_fetch_ec_json_check_partyschedules_n(_scheduleid bigint) OWNER TO postgres;

--
-- Name: fn_fetch_ec_json_check_propertyschedules_n(bigint, character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_ec_json_check_propertyschedules_n(_propertyid bigint, _applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
 
 
declare 

v_data_json json;

begin
select row_to_json(data_json)::json into v_data_json from ( 
select array_to_json(array_agg(row_to_json(propertyschedules)))
from ( 
select 
ps.scheduleid,
ps.easttowest,
ps.northtosouth,
case when pas.propertyid is not null 
then
case when  ps.description is not null and  ps.description<>'' then  
concat('[BoundaryDetails] : North: ',ps.northboundary,', '
, 'East: ',ps.eastboundary,', '
, 'West: ', ps.westboundary,', ', 'South: ', ps.southboundary,' [Schedule details] : ',ps.description)
else concat('District: ', d.districtnamee,', ' , 'Taluk: ', tm.taluknamee,', ' , 'Village: ',v2.villagenamee,', ', '', 'Survey No: ',p.survey_no
,', ', 'Hissa No: ', COALESCE(NULLIF(p.hissa_no, ''), null),', '
, 'BoundaryDetails: [North: ',ps.northboundary,', '
, 'East: ',ps.eastboundary,', '
, 'West: ', ps.westboundary,', ', 'South: ', ps.southboundary,', ','] measuring '
,ps.totalarea,' acre') end 
else
concat('[BoundaryDetails] : North: ',ps.northboundary,', '
, 'East: ',ps.eastboundary,', '
, 'West: ', ps.westboundary,', ', 'South: ', ps.southboundary,' [Schedule details] : ',ps.description) end as
description
from kaveri.propertymaster pp 
join kaveri.propertynumberdetails p on pp.propertyid=p.propertyid 
join kaveri.propertyschedules ps on ps.propertyid=pp.propertyid and pp.applicationnumber=ps.applicationnumber
--left join kaveri.zonemaster zn on zn.zoneid=pp.zoneid
left join kaveri.partyschedules pas on ps.scheduleid=pas.scheduleid 
left join kaveri.partyinfo pin on pas.partyid=pin.partyid 
join kaveri.villagemaster v2 on pp.villagecode=v2.villagecode 
join kaveri.talukmaster tm on v2.talukcode =tm.talukcode --, p.currentnumber) 
join kaveri.districtmaster d on tm.districtcode =d.districtcode 
where pp.propertyid = _propertyid and pp.applicationnumber=_applicationnumber 
group by ps.easttowest, ps.northtosouth,ps.description,pas.propertyid
,d.districtnamee,tm.taluknamee,v2.villagenamee,p.survey_no,COALESCE(NULLIF(p.hissa_no, ''), null),ps.northboundary
,ps.eastboundary,ps.westboundary,ps.southboundary,ps.totalarea,ps.scheduleid
)propertyschedules) data_json;
return v_data_json;
END;
$$;


