--
-- Name: fn_fetch_ec_json_ecnamesearchkeyvalues(integer, character varying, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_ec_json_ecnamesearchkeyvalues(_villagecode integer, _firstname character varying, _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS TABLE(applicationnumber character varying)
    LANGUAGE plpgsql
    AS $$

begin
return query
	select d.applicationnumber from kaveri.ecnamesearchkeyvalues ec
	join kaveri.documentmaster d on ec.documentid = d.documentid
	join kaveri.propertymaster p on d.applicationnumber=p.applicationnumber
	where lower(ec.firstname) ~ lower(_firstname) = true --firstname like _firstname 
	and d.registrationdatetime::date between _fromdate and _todate
	and villagecode=_villagecode;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_ec_json_ecnamesearchkeyvalues(_villagecode integer, _firstname character varying, _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_fetch_ec_json_ecnamesearchkeyvalues(integer, character varying, character varying, character varying, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_ec_json_ecnamesearchkeyvalues(_villagecode integer, _firstname character varying, _middlename character varying, _lastname character varying, _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS TABLE(applicationnumber character varying)
    LANGUAGE plpgsql
    AS $$
declare 
v_appno character varying;
begin
--return query
	select distinct d.applicationnumber into v_appno from kaveri.ecnamesearchkeyvalues ec
	join kaveri.documentmaster d on ec.documentid = d.documentid
	join kaveri.propertymaster p on d.applicationnumber=p.applicationnumber
	join kaveri.ecpropertysearchkeyvalues ep on ep.documentid = ec.documentid
	where lower(ec.firstname) ilike '%'||lower(_firstname)||'%'
			and lower(coalesce(ec.middlename,'')) ilike '%'||lower(_middlename)||'%'
			and lower(coalesce(ec.lastname,'')) ilike '%'||lower(_lastname)||'%'
			and d.registrationdatetime::date between _fromdate and _todate
	and case when ep.villagecode is not null then ep.villagecode = _villagecode else p.villagecode=_villagecode end;
	
if (v_appno is null)
then 

select distinct d.applicationnumber into v_appno
from kaveri.ecpropertysearchkeyvalues  ec
join kaveri.documentmaster d on ec.documentid = d.documentid
join kaveri.propertymaster p on d.applicationnumber=p.applicationnumber
join kaveri.partyinfo p2 on p2.documentid =ec.documentid 
where lower(p2.firstname) ilike '%'||lower(_firstname)||'%'
and  lower(p2.middlename) ilike '%'||lower(_middlename)||'%'
and lower(p2.lastname) ilike '%'||lower(_lastname)||'%'
and d.registrationdatetime::date between _fromdate and _todate
and case when ec.villagecode is not null then ec.villagecode = _villagecode else p.villagecode=_villagecode end;

end if;

return query
select v_appno;


END;
$$;


ALTER FUNCTION kaveri.fn_fetch_ec_json_ecnamesearchkeyvalues(_villagecode integer, _firstname character varying, _middlename character varying, _lastname character varying, _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_fetch_ec_json_ecnamesearchkeyvalues_20022024(integer, character varying, character varying, character varying, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_ec_json_ecnamesearchkeyvalues_20022024(_villagecode integer, _firstname character varying, _middlename character varying, _lastname character varying, _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS TABLE(applicationnumber character varying)
    LANGUAGE plpgsql
    AS $$

begin
return query
	select d.applicationnumber from kaveri.ecnamesearchkeyvalues ec
	join kaveri.documentmaster d on ec.documentid = d.documentid
	join kaveri.propertymaster p on d.applicationnumber=p.applicationnumber
	where lower(ec.firstname) ~ lower(_firstname) = true
	and lower(coalesce(ec.middlename,'')) ~ lower(_middlename) = true
			and lower(coalesce(ec.lastname,'')) ~ lower(_lastname) = true--firstname like _firstname 
	and d.registrationdatetime::date between _fromdate and _todate
	and villagecode=_villagecode;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_ec_json_ecnamesearchkeyvalues_20022024(_villagecode integer, _firstname character varying, _middlename character varying, _lastname character varying, _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_fetch_ec_json_ecnamesearchkeyvalues_namesearch(character varying, character varying, character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_ec_json_ecnamesearchkeyvalues_namesearch(_firstname character varying, _middlename character varying, _lastname character varying) RETURNS TABLE(finalregistrationnumber character varying, partyid bigint)
    LANGUAGE plpgsql
    AS $$
begin
return query

select d.finalregistrationnumber,ec.partyid 
from kaveri.dec_drordermaster d
join kaveri.ecnamesearchkeyvalues ec on ec.orderid = d.orderid 
where statuscode = 4 and ec.documentid = 0 and lower(ec.firstname) ilike '%'||_firstname||'%'
and case when _middlename <> '' then lower(coalesce(ec.middlename,'')) ilike '%'||_middlename||'%' else true end
and case when _lastname <> '' then lower(coalesce(ec.lastname,'')) ilike '%'||_lastname||'%' else true end;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_ec_json_ecnamesearchkeyvalues_namesearch(_firstname character varying, _middlename character varying, _lastname character varying) OWNER TO postgres;

--
-- Name: fn_fetch_ec_json_party_details_check(integer, character varying, character varying, character varying, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_ec_json_party_details_check(_villagecode integer, _firstname character varying, _middlename character varying, _lastname character varying, _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
begin
select row_to_json(data_json) into v_data_json from (
select array_to_json(array_agg(row_to_json(app_json)))
--select row_to_json(data_json) into v_data_json from (
--select array_to_json(array_agg(row_to_json(data_json)))
--into v_data_json 
from (
 select 
pm.propertyid,
pm.marketvalue,
pm.consideration,
ra.articlenamee,
pm.eastboundary AS east,
pm.westboundary AS west,
pm.northboundary AS north,
pm.southboundary AS south,
pm.totalarea AS area,
pm.villagecode,
v.villagenamee,
v.hoblicode,
h.hoblinamee,
(select referencetext from kaveri.referencemaster where documentid=dm.documentid order by lstupddate desc limit 1),
v.srocode,
s.sronamee,
( select array_to_json(array_agg(row_to_json(propertyschedules)))
from ( 
	--Code Begins for Property Schedules
select 
ps.easttowest,
 ps.northtosouth,
 case when pas.propertyid is not null then
 concat(ps.description, ' Allotted to: ', string_agg(pin.firstname || pin.middlename || pin.lastname,' & ')) 
else
ps.description end as
 description
from kaveri.propertyschedules ps left outer join kaveri.partyschedules pas
on ps.propertyid=pas.propertyid left outer join kaveri.partyinfo pin on 
pas.partyid=pin.partyid where  ps.propertyid = pm.propertyid
		   group by ps.easttowest, ps.northtosouth,ps.description,pas.propertyid
--Code Ends for Property Schedules	 
)propertyschedules)as propertyschedules,
( select array_to_json(array_agg(row_to_json(prty)))
from ( select distinct pi.partyid,
 (
        CASE
            WHEN pi.partytypeid = 1 or (ps.propertyid = pm.propertyid) THEN concat(pi.firstname, pi.middlename, pi.lastname)
            ELSE NULL::text
        END::text) AS claimant,
 (
        CASE
            WHEN pi.partytypeid = 2 THEN concat(pi.firstname, pi.middlename, pi.lastname)
            ELSE NULL::text
        END::text) AS executant,
		     pi.address from kaveri.partyinfo pi 
			left outer join kaveri.partyschedules ps on pi.partyid=ps.partyid
			where pi.documentid = dm.documentid
		    --order by pi.partytypeid,pi.partyid	 	  	
)prty ) as partydetails,
( select array_to_json(array_agg(row_to_json(documentdetails)))
from (select dm.documentid,
dm.registrationdatetime AS executiondate,
dm.cdnumber,
dm.pagecount,
dm.finalregistrationnumber AS documentreference)documentdetails)as documentdetails,
(select note_enteredpart from kaveri.dec_drpndnote where propertyid=pm.propertyid order by insertdatetime desc limit 1) as correctionnote,
(select string_agg(concat('1. Liability Details: Order Number: ', ld.ordernumber, ', Issue Date: ', TO_CHAR(ld.issuedate ::date, 'dd/mm/yyyy'), 
	 	', Liability Note: ', ld.liabilitynote, '<br>2. Additional Note: ', ld.liabilityadditionalnote),';<br> ') 
		from kaveri.liabilityonpropertydetails lop
		left join kaveri.liabilitydetails ld on lop.liabilityid = ld.liabilityid 
		--left join kaveri.liabilitynoteadditionaldetails lnad on lnad.liabilityid=ld.liabilityid 
	 where lop.propertyid = pm.propertyid) as liabilitynote
from  kaveri.propertymaster pm
left join  kaveri.propertyschedules ps on  ps.propertyid = pm.propertyid
left JOIN kaveri.documentmaster dm ON pm.documentid = dm.documentid
left join kaveri.villagemaster v on pm.villagecode = v.villagecode
left JOIN kaveri.hoblimaster h ON v.hoblicode = h.hoblicode
left JOIN kaveri.registrationarticles ra ON ra.regarticlecode = dm.regarticlecode
left join kaveri.sromaster s on s.srocode = v.srocode
--left join  kaveri.partyinfo pi  on (pi.documentid = pm.documentid )
where pm.villagecode = _villagecode and  dm.bookid not in (3, 4) and pm.ismovableproperty = false and
	exists  (select 1 from kaveri.partyinfo p where p.documentid=pm.documentid
							and  p.applicationnumber is not null and
			lower(firstname) ~ lower(_firstname) = true
			and lower(coalesce(middlename,'')) ~ lower(_middlename) = true
			and lower(coalesce(lastname,'')) ~ lower(_lastname) = true
		   )
	--pi.applicationnumber in (
	--select applicationnumber from kaveri.partyinfo where
--firstname = _firstname and 
--coalesce(middlename,'') = _middlename and
--coalesce(lastname,'') = _lastname )
 and 
	dm.registrationdatetime::date >= _fromdate and dm.registrationdatetime::date <= _todate

--)  data_json ;
) app_json )  data_json ;
return v_data_json;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_ec_json_party_details_check(_villagecode integer, _firstname character varying, _middlename character varying, _lastname character varying, _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

