--

CREATE FUNCTION kaveri.fn_fetch_ec_json_party_details_check_documentdetail_application(_villagecode integer, _applicationnumber character varying) RETURNS TABLE(propertyid bigint, marketvalue numeric, consideration numeric, articlenamee character varying, east character varying, west character varying, north character varying, south character varying, area numeric, villagecode bigint, villagenamee character varying, hoblicode integer, hoblinamee character varying, referencetext character varying, srocode integer, sronamee character varying, correctionnote character varying, liabilitynote text, documentid bigint, executiondate timestamp without time zone, cdnumber character varying, pagecount integer, documentreference character varying)
    LANGUAGE plpgsql
    AS $$

declare 
v_app_json json;
begin
return query
--select row_to_json(app_json) into v_app_json from (
select 
distinct 
pm.propertyid,
--pm.marketvalue,
pm.sromarketvalue::numeric as marketvalue,
pm.consideration,
ra.articlenamee,
pm.eastboundary AS east,
pm.westboundary AS west,
pm.northboundary AS north,
pm.southboundary AS south,
pm.totalarea AS area,
pm.villagecode,
v.villagenamee,
v.hoblicode,
h.hoblinamee,
(select rm.referencetext from kaveri.referencemaster rm where rm.documentid=dm.documentid order by lstupddate desc limit 1),
v.srocode,
s.sronamee,
dr.note_enteredpart,
(select string_agg(concat('1. Liability Details: Order Number: ', ld.ordernumber, ', Issue Date: ', TO_CHAR(ld.issuedate ::date, 'dd/mm/yyyy'), 
	 	', Liability Note: ', ld.liabilitynote, '<br>2. Additional Note: ', ld.liabilityadditionalnote),';<br> ') 
		from kaveri.liabilityonpropertydetails lop
		left join kaveri.liabilitydetails ld on lop.liabilityid = ld.liabilityid 
	 where lop.propertyid = pm.propertyid) as liabilitynote,
dm.documentid,
--dm.registrationdatetime AS executiondate,
dm.executiondatetime as executiondate,
dm.cdnumber,
dm.pagecount,
dm.finalregistrationnumber AS documentreference
--(select distinct array_to_json(array_agg(row_to_json(prop)))
-- 	from (select distinct pmd.currentpropertytypeid::text, pmd.currentnumber::text  from kaveri.propertynumberdetails pmd
-- where pmd.propertyid=pm.propertyid) as prop) as propertynodetails 
from kaveri.propertymaster pm
left join kaveri.propertyschedules ps on  ps.propertyid = pm.propertyid
--left join kaveri.dec_drpndnote dr on dr.propertyid = pm.propertyid 
--left JOIN kaveri.documentmaster dm ON pm.documentid = dm.documentid
left JOIN kaveri.documentmaster dm ON pm.documentid = dm.documentid
left join kaveri.dec_drordermaster dd on dd.documentid = dm.documentid
left join kaveri.dec_drpndnote dr on dr.orderid = dd.orderid
left join kaveri.villagemaster v on pm.villagecode = v.villagecode
left JOIN kaveri.hoblimaster h ON v.hoblicode = h.hoblicode
left JOIN kaveri.registrationarticles ra ON ra.regarticlecode = dm.regarticlecode
left join kaveri.sromaster s on s.srocode = v.srocode
left join kaveri.zonemaster zn on zn.zoneid =pm.zoneid
where pm.applicationnumber = _applicationnumber and pm.villagecode = _villagecode;
END;
$$;


