    LANGUAGE plpgsql
    AS $$

declare 
v_app_json json;
begin
return query
--select row_to_json(app_json) into v_app_json from (
select 
pm.propertyid,
pm.marketvalue,
pm.consideration,
ra.articlenamee,
pm.eastboundary AS east,
pm.westboundary AS west,
pm.northboundary AS north,
pm.southboundary AS south,
pm.totalarea AS area,
pm.villagecode,
v.villagenamee,
v.hoblicode,
h.hoblinamee,
(select rm.referencetext from kaveri.referencemaster rm where rm.documentid=dm.documentid order by lstupddate desc limit 1),
v.srocode,
s.sronamee,
dr.note_enteredpart,
--(select string_agg(concat('1. Liability Details: Order Number: ', ld.ordernumber, ', Issue Date: ', TO_CHAR(ld.issuedate ::date, 'dd/mm/yyyy'), ', Liability Note: ', ld.liabilitynote, '<br>2. Additional Note: ', ld.liabilityadditionalnote),';<br> ')) as liabilitynote 
--(select dd.note_enteredpart from kaveri.dec_drpndnote dd where dd.propertyid=pm.propertyid order by insertdatetime desc limit 1) as correctionnote,
(select string_agg(concat('1. Liability Details: Order Number: ', ld.ordernumber, ', Issue Date: ', TO_CHAR(ld.issuedate ::date, 'dd/mm/yyyy'), 
	 	', Liability Note: ', ld.liabilitynote, '<br>2. Additional Note: ', ld.liabilityadditionalnote),';<br> ') 
		from kaveri.liabilityonpropertydetails lop
		left join kaveri.liabilitydetails ld on lop.liabilityid = ld.liabilityid 
	 where lop.propertyid = pm.propertyid) as liabilitynote,
dm.documentid,
dm.registrationdatetime AS executiondate,
dm.cdnumber,
dm.pagecount,
dm.finalregistrationnumber AS documentreference
from kaveri.propertymaster pm
left join kaveri.propertyschedules ps on ps.propertyid = pm.propertyid
left join kaveri.dec_drpndnote dr on dr.propertyid = pm.propertyid 
left JOIN kaveri.documentmaster dm ON pm.documentid = dm.documentid
--left join kaveri.referencemaster rm on rm.documentid=dm.documentid
inner join kaveri.villagemaster v on pm.villagecode = v.villagecode
inner JOIN kaveri.hoblimaster h ON v.hoblicode = h.hoblicode
inner JOIN kaveri.registrationarticles ra ON ra.regarticlecode = dm.regarticlecode
inner join kaveri.sromaster s on s.srocode = v.srocode
--left join kaveri.zonemaster zn on zn.zoneid =pm.zoneid
--left join kaveri.liabilityonpropertydetails lop on lop.propertyid = pm.propertyid
--left join kaveri.liabilitydetails ld on lop.liabilityid = ld.liabilityid 
where pm.villagecode = _villagecode and  dm.bookid not in (3, 4) and pm.ismovableproperty = false and
	exists  (select 1 from kaveri.partyinfo p where p.documentid=pm.documentid
							and  p.applicationnumber is not null and
			lower(firstname) ~ lower(_firstname) = true
			and lower(coalesce(middlename,'')) ~ lower(_middlename) = true
			and lower(coalesce(lastname,'')) ~ lower(_lastname) = true
		   )
 and 
	dm.registrationdatetime::date >= _fromdate and dm.registrationdatetime::date <= _todate;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_ec_json_party_details_check_documentdetails(_villagecode integer, _firstname character varying, _middlename character varying, _lastname character varying, _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_fetch_ec_json_party_details_check_ecnamesearchkeyvalues(integer, character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_ec_json_party_details_check_ecnamesearchkeyvalues(_villagecode integer, _applicationnumber character varying) RETURNS TABLE(partyid bigint, partyname text, partytypeid integer, address character varying)
    LANGUAGE plpgsql
    AS $$
begin
return query
select ec.partyid, 
	concat(ec.firstname,' ',ec.middlename,' ',ec.lastname) as partyname,
	ec.partytypeid,
	p.address
from kaveri.ecnamesearchkeyvalues ec
join kaveri.documentmaster d on d.documentid = ec.documentid
join kaveri.propertymaster pm on pm.documentid = ec.documentid
join kaveri.partyinfo p on p.partyid = ec.partyid
where ec.partytypeid in (1,2) and p.applicationnumber = _applicationnumber and pm.villagecode = _villagecode;
END;
$$;


