    LANGUAGE plpgsql
    AS $$
begin
return query
--select distinct p.applicationnumber
--			from kaveri.partyinfo p 
--			left JOIN kaveri.documentmaster dm ON p.documentid = dm.documentid
--			left join kaveri.propertymaster pm on pm.documentid = dm.documentid
--where pm.villagecode = _villagecode 
--and dm.bookid not in (3, 4) 
--and pm.ismovableproperty = false and
--exists (select 1 from kaveri.partyinfo p where p.documentid=pm.documentid
--and p.applicationnumber is not null 
--			and
--			case when _firstname <> '' or _middlename <> '' or _lastname <> '' then
--			lower(p.firstname) ~ lower(_firstname) = true
--			and lower(coalesce(p.middlename,'')) ~ lower(_middlename) = true
--			and lower(coalesce(p.lastname,'')) ~ lower(_lastname) = true
--			end
--			)and dm.registrationdatetime::date >= _fromdate and dm.registrationdatetime::date <= _todate;

select distinct p.applicationnumber from kaveri.partyinfo p 
join kaveri.propertymaster p2 on p.applicationnumber = p2.applicationnumber 
join kaveri.documentmaster d on p2.applicationnumber  = d.applicationnumber 
where lower(p.firstname) ilike '%'||_firstname||'%'
			and case when _middlename <> '' then lower(coalesce(p.middlename,'')) ilike '%'||_middlename||'%' else true end
			and case when _lastname <> '' then lower(coalesce(p.lastname,'')) ilike '%'||_lastname||'%' else true end
and p2.villagecode = _villagecode
