ALTER FUNCTION kaveri.fn_fetch_ec_json_party_details_check_fetch_application_20022024(_villagecode integer, _firstname character varying, _middlename character varying, _lastname character varying, _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_fetch_ec_json_party_details_check_partydetails(character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_ec_json_party_details_check_partydetails(_applicationnumber character varying) RETURNS TABLE(partyid bigint, partyname text, partytypeid integer, address character varying)
    LANGUAGE plpgsql
    AS $$
begin
return query
select p.partyid,
				case
	            when p1.partytypeid = 4 AND p2.firstname IS NOT NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is rep. by minor guardian ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ', whose POA is ', s2.descriptione, p2.firstname, ' ', p2.middlename, ' ', p2.lastname)
	            WHEN p1.partytypeid = 4 AND p2.firstname IS NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is rep. by minor guardian ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)
	            WHEN p1.partytypeid = 5 AND p.isorganization = true THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' POA by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ' is Rep. by ', p1.orgpoaauthsignfname, ' ', p1.orgpoaauthsignlname)
	            WHEN p1.partytypeid = 5 AND p.isorganization = false THEN concat(s1.descriptione, p1.firstname, ' is POA of ', s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
	            WHEN p1.partytypeid = 9 AND p.isorganization = true AND p2.firstname IS NOT NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is Rep. by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ', whose POA is ', s2.descriptione, p2.firstname, ' ', p2.middlename, ' ', p2.lastname)
	            WHEN p1.partytypeid = 9  AND p.isorganization = true AND p2.firstname IS NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is Rep. by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)
	            WHEN p1.partytypeid IS NULL AND p.partytypeid = 1 THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
	            WHEN p1.partytypeid IS NULL AND p.partytypeid = 2 THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
	            ELSE NULL::text
	        END AS partyname,
        		p.partytypeid,
 			p.address from kaveri.partyinfo p
			left JOIN kaveri.partyinfo p1 ON p.partyid = p1.linkpartyid AND p1.partytypeid in (9, 4, 5) --ANY (ARRAY[9, 4, 5]))
			left JOIN kaveri.partyinfo p2 ON p2.linkpartyid = p1.partyid AND p2.partytypeid = 5 --= ANY (ARRAY[5]))
			left JOIN kaveri.salutationmaster s ON p.salutationid = s.salutationid
			left JOIN kaveri.salutationmaster s1 ON p1.salutationid = s1.salutationid
			left JOIN kaveri.salutationmaster s2 ON p2.salutationid = s2.salutationid 
			left JOIN kaveri.documentmaster dm ON p.documentid = dm.documentid 
			inner join kaveri.propertymaster pm on pm.documentid = dm.documentid
			where p.applicationnumber = _applicationnumber;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_ec_json_party_details_check_partydetails(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_ec_json_party_details_check_partydetails(integer, character varying, character varying, character varying, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaveri; Owner: raghavendrap
--

CREATE FUNCTION kaveri.fn_fetch_ec_json_party_details_check_partydetails(_villagecode integer, _firstname character varying, _middlename character varying, _lastname character varying, _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS TABLE(partyid bigint, partyname text, partytypeid integer, address character varying)
    LANGUAGE plpgsql
    AS $$
begin
return query
select p.partyid,
				CASE
	            when p1.partytypeid = 4 AND p2.firstname IS NOT NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is rep. by minor guardian ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ', whose POA is ', s2.descriptione, p2.firstname, ' ', p2.middlename, ' ', p2.lastname)
	            WHEN p1.partytypeid = 4 AND p2.firstname IS NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is rep. by minor guardian ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)
	            WHEN p1.partytypeid = 5 AND p.isorganization = true THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' POA by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ' is Rep. by ', p1.orgpoaauthsignfname, ' ', p1.orgpoaauthsignlname)
	            WHEN p1.partytypeid = 5 AND p.isorganization = false THEN concat(s1.descriptione, p1.firstname, ' is POA of ', s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
	            WHEN p1.partytypeid = 9 AND p.isorganization = true AND p2.firstname IS NOT NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is Rep. by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ', whose POA is ', s2.descriptione, p2.firstname, ' ', p2.middlename, ' ', p2.lastname)
	            WHEN p1.partytypeid = 9  AND p.isorganization = true AND p2.firstname IS NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is Rep. by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)
	            WHEN p1.partytypeid IS NULL AND p.partytypeid = 1 THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
	            WHEN p1.partytypeid IS NULL AND p.partytypeid = 2 THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
	            ELSE NULL::text
	        END AS partyname,
        		p.partytypeid ,
 		p.address from kaveri.partyinfo p
			left JOIN kaveri.partyinfo p1 ON p.partyid = p1.linkpartyid AND (p1.partytypeid = ANY (ARRAY[9, 4, 5]))
			left JOIN kaveri.partyinfo p2 ON p2.linkpartyid = p1.partyid AND (p2.partytypeid = ANY (ARRAY[5]))
			left JOIN kaveri.salutationmaster s ON p.salutationid = s.salutationid
			left JOIN kaveri.salutationmaster s1 ON p1.salutationid = s1.salutationid
			left JOIN kaveri.salutationmaster s2 ON p2.salutationid = s2.salutationid 
			left JOIN kaveri.documentmaster dm ON p.documentid = dm.documentid 
--			and
--			lower(p.firstname) ~ lower(_firstname) = true
--			and lower(coalesce(p.middlename,'')) ~ lower(_middlename) = true
--			and lower(coalesce(p.lastname,'')) ~ lower(_lastname) = true
			left join kaveri.propertymaster pm on pm.documentid = dm.documentid
where pm.villagecode = _villagecode 
and dm.bookid not in (3, 4) 
and pm.ismovableproperty = false and 
exists (select 1 from kaveri.partyinfo p where p.documentid=pm.documentid
and p.applicationnumber is not null and
			lower(p.firstname) ~ lower(_firstname) = true
			and lower(coalesce(p.middlename,'')) ~ lower(_middlename) = true
			and lower(coalesce(p.lastname,'')) ~ lower(_lastname) = true)
			and
		dm.registrationdatetime::date >= _fromdate and dm.registrationdatetime::date <= _todate;
END;
$$;


