    LANGUAGE plpgsql
    AS $$

begin
	return query
select
ps.scheduleid,
pm.propertyid,
ps.easttowest,
ps.northtosouth,
case when pas.propertyid is not null then
concat(ps.description, ' Allotted to: ', string_agg(pin.firstname || pin.middlename || pin.lastname,' & '),' ',zn.zonenamee) 
else
ps.description end as
 description
from kaveri.propertyschedules ps 
