where pm.applicationnumber = _applicationnumber and pm.villagecode = _villagecode --and pm.propertyid = _propertyid
	group by ps.scheduleid,pm.propertyid, ps.easttowest, ps.northtosouth,ps.description,pas.propertyid,zn.zonenamee;
	--,pmd.currentpropertytypeid,
 --pmd.currentnumber;
END;
$$;


