CREATE FUNCTION kaveri.fn_fetch_ec_json_party_details_check_propertydetails(_villagecode integer, _firstname character varying, _middlename character varying, _lastname character varying, _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS TABLE(easttowest character varying, northtosouth character varying, description character varying)
    LANGUAGE plpgsql
    AS $$
begin
	return query
select 
ps.easttowest,
ps.northtosouth,
case when pas.propertyid is not null then
concat(ps.description, ' Allotted to: ', string_agg(pin.firstname || pin.middlename || pin.lastname,' & '),' ',zn.zonenamee)
else
ps.description end as
 description
from kaveri.propertyschedules ps 
left join kaveri.partyschedules pas on ps.propertyid=pas.propertyid
left join kaveri.propertymaster pm on ps.propertyid = pm.propertyid
left JOIN kaveri.documentmaster dm ON pm.documentid = dm.documentid
left join kaveri.zonemaster zn on pm.zoneid = zn.zoneid
left join kaveri.partyinfo pin on  pas.partyid=pin.partyid
where pm.villagecode = _villagecode and  dm.bookid not in (3, 4) and pm.ismovableproperty = false and
	exists  (select 1 from kaveri.partyinfo p where p.documentid=pm.documentid
							and  p.applicationnumber is not null and
			lower(firstname) ~ lower(_firstname) = true
			and lower(coalesce(middlename,'')) ~ lower(_middlename) = true
			and lower(coalesce(lastname,'')) ~ lower(_lastname) = true
		   )and 
	dm.registrationdatetime::date >= _fromdate and dm.registrationdatetime::date <= _todate
	group by ps.easttowest, ps.northtosouth,ps.description,pas.propertyid,zn.zonenamee;
END;
