--
-- Name: fn_fetch_ecjson_prtydtlschk_fth_appln(integer, character varying, character varying, character varying, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_ecjson_prtydtlschk_fth_appln(_villagecode integer, _firstname character varying, _middlename character varying, _lastname character varying, _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS TABLE(applicationnumber character varying)
    LANGUAGE plpgsql
    AS $$
declare 
v_appno character varying;

begin
	


select distinct d.applicationnumber into v_appno
from kaveri.ecpropertysearchkeyvalues  ec
join kaveri.documentmaster d on ec.documentid = d.documentid
join kaveri.propertymaster p on d.applicationnumber=p.applicationnumber
join kaveri.partyinfo p2 on p2.documentid =ec.documentid 
where lower(p2.firstname) ilike '%'||lower(_firstname)||'%'
and  lower(p2.middlename) ilike '%'||lower(_middlename)||'%'
and lower(p2.lastname) ilike '%'||lower(_lastname)||'%'
and d.registrationdatetime::date between _fromdate and _todate
and d.bookid not in (3, 4)
and case when ec.villagecode is not null then ec.villagecode = _villagecode else p.villagecode=_villagecode end;

if(v_appno is null)
then
--partyinfo p

select distinct p.applicationnumber into v_appno
from 
kaveri.ecpropertysearchkeyvalues ec 
join kaveri.partyinfo p on ec.documentid=p.documentid
join kaveri.propertymaster p2 on p.applicationnumber = p2.applicationnumber 
join kaveri.documentmaster d on p2.applicationnumber  = d.applicationnumber 
where lower(p.firstname) ilike '%'||lower(_firstname)||'%'
			and lower(coalesce(p.middlename,'')) ilike '%'||lower(_middlename)||'%'
			and lower(coalesce(p.lastname,'')) ilike '%'||lower(_lastname)||'%'
--and p2.villagecode = _villagecode
and p2.ismovableproperty = false
and d.bookid not in (3, 4) and d.isregistrationcompleted = true and
--d.registrationdatetime::date >= _fromdate and d.registrationdatetime::date <= _todate;
d.registrationdatetime::date between _fromdate and _todate
and case when ec.villagecode is not null then ec.villagecode =_villagecode else p2.villagecode=_villagecode end;


end if;

return query
select v_appno;

END;
$$;


ALTER FUNCTION kaveri.fn_fetch_ecjson_prtydtlschk_fth_appln(_villagecode integer, _firstname character varying, _middlename character varying, _lastname character varying, _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_fetch_ecjsonprty_dtlchk_dmntdtl_application(character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_ecjsonprty_dtlchk_dmntdtl_application(_applicationnumber character varying) RETURNS TABLE(propertyid bigint, marketvalue numeric, consideration numeric, articlenamee character varying, east character varying, west character varying, north character varying, south character varying, area numeric, villagecode bigint, villagenamee character varying, hoblicode integer, hoblinamee character varying, referencetext character varying, srocode integer, sronamee character varying, correctionnote character varying, liabilitynote text, documentid bigint, executiondate timestamp without time zone, cdnumber character varying, pagecount integer, documentreference character varying)
    LANGUAGE plpgsql
    AS $$

declare 
v_app_json json;
begin
return query
--select row_to_json(app_json) into v_app_json from (
select 
distinct 
pm.propertyid,
pm.marketvalue,
pm.consideration,
ra.articlenamee,
pm.eastboundary AS east,
pm.westboundary AS west,
pm.northboundary AS north,
pm.southboundary AS south,
pm.totalarea AS area,
pm.villagecode,
v.villagenamee,
v.hoblicode,
h.hoblinamee,
(select rm.referencetext from kaveri.referencemaster rm where rm.documentid=dm.documentid order by lstupddate desc limit 1),
v.srocode,
s.sronamee,
dr.note_enteredpart,
(select string_agg(concat('1. Liability Details: Order Number: ', ld.ordernumber, ', Issue Date: ', TO_CHAR(ld.issuedate ::date, 'dd/mm/yyyy'), 
	 	', Liability Note: ', ld.liabilitynote, '<br>2. Additional Note: ', ld.liabilityadditionalnote),';<br> ') 
		from kaveri.liabilityonpropertydetails lop
		left join kaveri.liabilitydetails ld on lop.liabilityid = ld.liabilityid 
	 where lop.propertyid = pm.propertyid) as liabilitynote,
dm.documentid,
dm.registrationdatetime AS executiondate,
dm.cdnumber,
dm.pagecount,
dm.finalregistrationnumber AS documentreference
--(select distinct array_to_json(array_agg(row_to_json(prop)))
-- 	from (select distinct pmd.currentpropertytypeid::text, pmd.currentnumber::text  from kaveri.propertynumberdetails pmd
-- where pmd.propertyid=pm.propertyid) as prop) as propertynodetails 
from kaveri.propertymaster pm
left join kaveri.propertyschedules ps on  ps.propertyid = pm.propertyid
--left join kaveri.dec_drpndnote dr on dr.propertyid = pm.propertyid 
--left JOIN kaveri.documentmaster dm ON pm.documentid = dm.documentid
left JOIN kaveri.documentmaster dm ON pm.documentid = dm.documentid
left join kaveri.dec_drordermaster dd on dd.documentid = dm.documentid
left join kaveri.dec_drpndnote dr on dr.orderid = dd.orderid
left join kaveri.villagemaster v on pm.villagecode = v.villagecode
left JOIN kaveri.hoblimaster h ON v.hoblicode = h.hoblicode
left JOIN kaveri.registrationarticles ra ON ra.regarticlecode = dm.regarticlecode
left join kaveri.sromaster s on s.srocode = v.srocode
left join kaveri.zonemaster zn on zn.zoneid =pm.zoneid
where pm.applicationnumber = _applicationnumber ;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_ecjsonprty_dtlchk_dmntdtl_application(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_ecnamechange_status(bigint, text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_ecnamechange_status(_partyid bigint, _partyname text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$


DECLARE


v_cnt bigint;
v_cnt2 bigint;

BEGIN 
	 
	 select count(partyid) into v_cnt from kaveri.ecnamesearchkeyvalues e 
	 where e.partyid=_partyid;
	if v_cnt=0 then 
	   
	    return true;
	else 
	   
	    select count(partyid) into v_cnt2  from kaveri.ecnamesearchkeyvalues e
	    where e.partyid=_partyid and  e.firstname  ilike _partyname;
	    if v_cnt2>0 then 
	       return true;
	    else 
	      return false;
	    end if;
	
		
	end if;
	  


 



END;

$$;


ALTER FUNCTION kaveri.fn_fetch_ecnamechange_status(_partyid bigint, _partyname text) OWNER TO postgres;

--
-- Name: fn_fetch_employee(integer, integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_employee(_officetype integer, _officeid integer) RETURNS TABLE(userid bigint, employeename text, employeepost text, useremail text)
    LANGUAGE plpgsql
    AS $$



DECLARE

BEGIN 

	if _officetype=0 then 
	    
		  if _officeid=0 then --All office of All type

			  return query
				select  du.userid,concat_ws(' '::text, du.firstname,du.middlename, du.lastname) AS EmployeeName,
				concat_ws(' '::text, mo2.officetypedesc,mo.officename ,d.designame) as post,
				du.emailid as username
				from kaveri.departmentusers du 
				join  kaveri.mas_officemaster mo on du.officeid=mo.officeid 
				--and mo.officeid=_officeid
				join kaveri.mas_officetypes mo2 on mo2.officetypeid=mo.officetypeid 
				--and mo2.officetypeid=_officetype
				join kaveri.desigmaster d on d.designationid=du.designationid 
				where du.serviceflag is true;
			
			ELSE  --perticular office of any type
			
				return query
				select  du.userid,concat_ws(' '::text, du.firstname,du.middlename, du.lastname) AS EmployeeName,
				concat_ws(' '::text, mo2.officetypedesc,mo.officename ,d.designame) as post,
				du.emailid as username
				from kaveri.departmentusers du 
				join  kaveri.mas_officemaster mo on du.officeid=mo.officeid 
				and mo.officeid=_officeid
				join kaveri.mas_officetypes mo2 on mo2.officetypeid=mo.officetypeid 
				--and mo2.officetypeid=_officetype
				join kaveri.desigmaster d on d.designationid=du.designationid 
				where du.serviceflag is true;
		end if;
		
	 ELSE
			if _officeid=0 then  --All office of perticular type
			return query
				select  du.userid,concat_ws(' '::text, du.firstname,du.middlename, du.lastname) AS EmployeeName,
				concat_ws(' '::text, mo2.officetypedesc,mo.officename ,d.designame) as post,
				du.emailid as username
				from kaveri.departmentusers du 
				join  kaveri.mas_officemaster mo on du.officeid=mo.officeid 
				--and mo.officeid=_officeid
				join kaveri.mas_officetypes mo2 on mo2.officetypeid=mo.officetypeid 
				and mo2.officetypeid=_officetype
				join kaveri.desigmaster d on d.designationid=du.designationid 
				where du.serviceflag is true;
				
			ELSE  --perticular office of a perticular type
			
				return query
				select  du.userid,concat_ws(' '::text, du.firstname,du.middlename, du.lastname) AS EmployeeName,
				concat_ws(' '::text, mo2.officetypedesc,mo.officename ,d.designame) as post,
				du.emailid as username
				from kaveri.departmentusers du 
				join  kaveri.mas_officemaster mo on du.officeid=mo.officeid   and mo.officeid=_officeid
				join kaveri.mas_officetypes mo2 on mo2.officetypeid=mo.officetypeid 
				and mo2.officetypeid=_officetype
				join kaveri.desigmaster d on d.designationid=du.designationid 
				where du.serviceflag is true;
			end if;
			
				
	end if; 
			

 

END;

$$;


ALTER FUNCTION kaveri.fn_fetch_employee(_officetype integer, _officeid integer) OWNER TO csgadmin;

--
-- Name: fn_fetch_employee_by_officeid(integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_employee_by_officeid(_officeid integer) RETURNS TABLE(userid bigint, employeename text, employeepost text, useremail text)
    LANGUAGE plpgsql
    AS $$


DECLARE



BEGIN 

  return query
	select  du.userid,concat_ws(' '::text, du.firstname,du.middlename, du.lastname) AS EmployeeName,
	concat_ws(' '::text, mo2.officetypedesc,mo.officename ,d.designame) as post,
	du.emailid as username
	from kaveri.departmentusers du 
	join  kaveri.mas_officemaster mo on du.officeid=mo.officeid 
	join kaveri.mas_officetypes mo2 on mo2.officetypeid=mo.officetypeid 
	join kaveri.desigmaster d on d.designationid=du.designationid  where du.officeid=_officeid;

 

END;

$$;


ALTER FUNCTION kaveri.fn_fetch_employee_by_officeid(_officeid integer) OWNER TO csgadmin;

--
-- Name: fn_fetch_employee_by_userid(integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_employee_by_userid(_userid integer) RETURNS TABLE(userid bigint, kgid text, employeename text, roll text, usertype text, officeid text, officename text, jurisdictionid text, post text, joiningdate text, officialemailid text, mobileno bigint, isactive boolean, roleinfo json)
    LANGUAGE plpgsql
    AS $$


DECLARE

BEGIN 

  return query
	
select  du.userid,
	du.kgid,concat_ws(' '::text, du.firstname,du.middlename, du.lastname) AS empname,
	d.designame::text as role,
	e.employeetypedesc  as usertype,
	mo2.officetypedesc||mo.officeid as officeid,
	mo2.officetypedesc||' '||mo.officename as officename,
	mo2.officetypedesc||' '||joff.officeid as jurisdictionid,
	concat_ws(' '::text,trim(d.designame),mo2.officetypedesc,mo.officename ) as post,
	to_char(du.doj,'dd/mm/yyyy') as joiningdate,
	du.emailid as officialemailid,du.mobileno,du.serviceflag,
	(select  fn_fetch_roleinfo_byuseid  from kaveri.fn_fetch_roleinfo_ByUseId(_userid))as rolesinfo
	from kaveri.departmentusers du 
	join  kaveri.mas_officemaster mo on du.officeid=mo.officeid 
	join kaveri.mas_officetypes mo2 on mo2.officetypeid=mo.officetypeid 
	join kaveri.desigmaster d on d.designationid=du.designationid 
	join kaveri.mas_officemaster joff on mo.parentofficeid=joff.officeid
	join kaveri.mas_officetypes mo3 on mo3.officetypeid=joff.officetypeid 
	join kaveri.employeetypemaster e on e.employeetypeid=du.employeetypeid 
	where du.userid=_userid;

 

END;

$$;


ALTER FUNCTION kaveri.fn_fetch_employee_by_userid(_userid integer) OWNER TO csgadmin;

