	e.employeetypedesc  as usertype,
	mo2.officetypedesc||mo.officeid as officeid,
	mo2.officetypedesc||' '||mo.officename as officename,
	mo2.officetypedesc||' '||joff.officeid as jurisdictionid,
	concat_ws(' '::text,trim(d.designame),mo2.officetypedesc,mo.officename ) as post,
	to_char(du.doj,'dd/mm/yyyy') as joiningdate,
	du.emailid as officialemailid,du.mobileno,du.serviceflag,
	(select  fn_fetch_roleinfo_byuseid  from kaveri.fn_fetch_roleinfo_ByUseId(_userid))as rolesinfo
	from kaveri.departmentusers du 
	join  kaveri.mas_officemaster mo on du.officeid=mo.officeid 
	join kaveri.mas_officetypes mo2 on mo2.officetypeid=mo.officetypeid 
	join kaveri.desigmaster d on d.designationid=du.designationid 
	join kaveri.mas_officemaster joff on mo.parentofficeid=joff.officeid
	join kaveri.mas_officetypes mo3 on mo3.officetypeid=joff.officetypeid 
	join kaveri.employeetypemaster e on e.employeetypeid=du.employeetypeid 
	where du.userid=_userid;

 

END;

$$;


