left join kaveri.documentmaster dc on (dc.regarticlecode = pm.regarticlecode and dc.documentid=pm.documentid)
left join kaveri.stamparticles sp on (sp.stamparticlecode = pm.stamparticlecode)
left join kaveri.stamprules sr on (sr.stampruleid = pm.stampruleid)
left join kaveri.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
left join kaveri.booktypemaster bt on (bt.bookid = sr.bookid)
left join kaveri.sromaster se on (se.srocode = pm.srocode)
left join kaveri.propertytypemaster pt on pt.propertytypeid = pm.propertytypeid
left join kaveri.villagewardmapping vw on vw.villagecode = pm.villagecode and vw.wardid = pm.wardid and pm.ismovableproperty=false
left join kaveri.warddetails w on w.wardid = pm.wardid
left join kaveri.measunitmaster me on me.unitid = pm.unitid
left join kaveri.integrationdepartment zone on pm.zoneid = zone.udeptid
left join kaveri.roadmaster rd on (pm.roadcode=rd.roadcode)
where pm.applicationnumber = _applicationnumber
group by pm.propertyid,pm.villagecode,vi.villagenamee,vi.hoblicode,ho.hoblinamee,vi.talukcode,ta.taluknamee,sm.districtcode,di.districtnamee
,pm.stamparticlecode,sp.articlenamee,pm.stampruleid,sr.descriptione,pm.regarticlecode,ra.articlenamee,sr.bookid,bt.booknameenglish
,pm.srocode,se.sronamee,
pm.propertytypeid,
pt.propertytypename,
pm.noofscanpages,
pm.ismovableproperty,
pm.movablepropertydesc,
w.wardid,
pm.totalarea,
me.descriptionenglish,
w.wardnumber,
pm.landmark,
pm.zoneid,
zone.departmentname,
subpropertytypeid,pm.applicationnumber,pm.assessment,pm.ownedarea,pm.roadcode,rd.roadnamee,ta.unit,pt.isagri, pm.valuationreport 
offset pageoffset
fetch next pagesize rows only
 
)app_json) 

from kaveri.vw_document_for_approval_rule17 rr where rr.applicationnumber = _applicationnumber

) data_json;


return v_data_json;
	END;
$$;


ALTER FUNCTION kaveri.fn_fetch_endorsement_summary_rule_17_bck(_applicationnumber text, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_endorsementdetails(character varying, bigint); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_endorsementdetails(_applicationnumber character varying, srocode bigint) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_array json;
v_pid json;
v_presenter boolean;
v_privateattendence boolean;
V_linkparty bigint;
V_section88exemption boolean;
--v_rearray bigint[];
begin
	
for v_presenter,v_privateattendence,V_linkparty,V_section88exemption   in (select p.ispresenter,p.isprivateattendance,p.linkpartyid,p.section88exemption  
	from kaveri.partyinfo p where applicationnumber = _applicationnumber)
	loop
	
	
		
		
	if(v_presenter=true)
	then 
		
		
	-----At private attandance------
	
		if(v_privateattendence=true)
		then 
		

		 select array_to_json(array_agg(row_to_json(party)))
      	from (
		select Distinct e.endorsementdescriptione,e.endorsmentsubname from kaveri.partyinfo p 
		 join kaveri.EndorsementFlowMaster e on e.endorsmentname  = case when p.ispresenter='true' then 'Presentation' else null end
		 where e.endorsmentsubname='At private attandance' and p.isprivateattendance = true) as  party into v_array ;
		
	------With Power of attorney----
		
		elseif(V_linkparty is not null)
		then 
		select array_to_json(array_agg(row_to_json(party)))
		from (
			select Distinct e.endorsementdescriptione,e.endorsmentsubname  from kaveri.partyinfo p 
			join kaveri.partyinfo p2 on p.partyid = p2.linkpartyid 
			join kaveri.partyinfo p3 on p.partyid = p3.linkpartyid 
			join kaveri.EndorsementFlowMaster e  on e.endorsmentname = case when p.ispresenter='true' then 'Presentation' else null end
			where p.ispresenter=true and p2.linkpartyid is not null and p2.partytypeid = 5 and p3.partytypeid=5 and   e.endorsmentsubname = 'With Power of attorney')as  party into v_array;
			--group by  p.partyid ,p2.linkpartyid 
		
	-------With Covering Letter---------		
		elseif(V_section88exemption=true)		
		then
			select array_to_json(array_agg(row_to_json(party)))
		from (	
			select distinct e.endorsementdescriptione,e.endorsmentsubname  from kaveri.partyinfo p 
				join kaveri.EndorsementFlowMaster e  on e.endorsmentname = case when p.ispresenter='true' then 'Presentation' else null end
				where p.section88exemption =true and  e.endorsmentsubname = 'With Covering Letter')as  party into v_array;
			
	----- Normal At Work-------		
		
		elseif(v_privateattendence=false and V_linkparty is null  and V_section88exemption=false )		
		then
			select array_to_json(array_agg(row_to_json(party)))
		from (	
				select Distinct e.endorsementdescriptione,e.endorsmentsubname  from kaveri.partyinfo p 
				join kaveri.EndorsementFlowMaster e  on e.endorsmentname = case when p.ispresenter='true' then 'Presentation' else null end
				where p.ispresenter=true and p.isprivateattendance = false and p.linkpartyid is null and p.section88exemption = false
				and e.endorsmentsubname='Normal at Office' )as  party into v_array;
			
			
			
	
		end if;
	
	
	end if;
 end loop;
return (v_array);

end;
$$;


ALTER FUNCTION kaveri.fn_fetch_endorsementdetails(_applicationnumber character varying, srocode bigint) OWNER TO csgadmin;

--
-- Name: fn_fetch_endorsementdetails_bak(character varying, bigint); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_endorsementdetails_bak(_applicationnumber character varying, _srocode bigint) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_array json;
v_pid json;
v_presenter boolean;
v_privateattendence boolean;
V_linkparty bigint;
V_section88exemption boolean;
--v_rearray bigint[];
v_executor boolean;
v_fingerid bigint;

begin
	
for v_presenter,v_privateattendence,V_linkparty,V_section88exemption,v_executor,v_fingerid in (select distinct p.ispresenter,p.isprivateattendance,p.linkpartyid,p.section88exemption,p.isexecutor,p.fingerid  
	from kaveri.partyinfo p where p.applicationnumber = _applicationnumber and p.srocode=_srocode)
	loop
	
	
		
		
	if(v_presenter=true)
	then 
		
		
	-----At private attandance------
	
		if(v_privateattendence=true)
		then 
		

		 select array_to_json(array_agg(row_to_json(party)))
      	from (
		select Distinct e.endorsementdescriptione,e.endorsementdescriptionk from kaveri.partyinfo p 
		 join kaveri.EndorsementFlowMaster e on e.endorsmentname  = case when p.ispresenter='true' then 'Presentation' else null end
		 where e.endorsmentsubname='At private attandance' and p.isprivateattendance = true and p.applicationnumber=_applicationnumber
		 and p.srocode=_srocode) as  party into v_array ;
		
	------With Power of attorney----
		
		elseif(V_linkparty is not null)
		then 
		select array_to_json(array_agg(row_to_json(party)))
		from (
			select Distinct e.endorsementdescriptione,e.endorsementdescriptionk  from kaveri.partyinfo p 
			join kaveri.partyinfo p2 on p.partyid = p2.linkpartyid 
			join kaveri.partyinfo p3 on p.partyid = p3.linkpartyid 
			join kaveri.EndorsementFlowMaster e  on e.endorsmentname = case when p.ispresenter='true' then 'Presentation' else null end
			where p.ispresenter=true and p2.linkpartyid is not null and p2.partytypeid = 5 and p3.partytypeid=5 and 
			e.endorsmentsubname = 'With Power of attorney' and p.applicationnumber=_applicationnumber
		 	and p.srocode=_srocode)as  party into v_array;
			--group by  p.partyid ,p2.linkpartyid 
		
	-------With Covering Letter---------		
		elseif(V_section88exemption=true)		
		then
			select array_to_json(array_agg(row_to_json(party)))
		from (	
			select Distinct e.endorsementdescriptione,e.endorsementdescriptionk  from kaveri.partyinfo p 
				join kaveri.EndorsementFlowMaster e  on e.endorsmentname = case when p.ispresenter='true' then 'Presentation' else null end
				where p.section88exemption =true and  e.endorsmentsubname = 'With Covering Letter' and p.applicationnumber=_applicationnumber
				 and p.srocode=_srocode)as  party into v_array;
			
	----- Normal At Work-------		
		
		elseif(v_privateattendence=false and V_linkparty is null  and V_section88exemption=false )		
		then
			select array_to_json(array_agg(row_to_json(party)))
		from (	
				select Distinct e.endorsementdescriptione,e.endorsementdescriptionk  from kaveri.partyinfo p 
				join kaveri.EndorsementFlowMaster e  on e.endorsmentname = case when p.ispresenter='true' then 'Presentation' else null end
				where p.ispresenter=true and p.isprivateattendance = false and p.linkpartyid is null and p.section88exemption = false
				and e.endorsmentsubname='Normal at Office' and p.applicationnumber=_applicationnumber
				 and p.srocode=_srocode)as  party into v_array;
			
			
			
	
		end if;
	
	elseif (v_executor=true)
	then 
	
	-----Normal Finger :- It mean Left Thumb-----
		if(v_fingerid=1)
		then
		select array_to_json(array_agg(row_to_json(party)))
		from 
		(select Distinct e.endorsementdescriptione,e.endorsementdescriptionk  from kaveri.partyinfo p 
		join kaveri.fingertypemaster f on p.fingerid = f.fingerid 
		join kaveri.EndorsementFlowMaster e  on e.endorsmentname = case when p.isexecutor ='true' then 'Executant acceptance' else null end
		where p.fingerid=1 and p.isexecutor = true and e.endorsmentsubname='Normal ' and p.applicationnumber=_applicationnumber
		 and p.srocode=_srocode)as  party into v_array;
	
	----With Right thumb or any other fingers---
	
		elseif(v_fingerid in (6,2,3,4,5,7,8,9,10))
		then
		select array_to_json(array_agg(row_to_json(party)))
		from(select Distinct e.endorsementdescriptione,e.endorsementdescriptionk  from kaveri.partyinfo p 
			join kaveri.fingertypemaster f on p.fingerid = f.fingerid 
			join kaveri.EndorsementFlowMaster e  on e.endorsmentname = case when p.isexecutor ='true' then 'Executant acceptance' else null end
			where p.fingerid in(6,2,3,4,5,7,8,9,10)  and p.isexecutor = true and e.endorsmentsubname = 'With Right thumb or any other fingers' 
			and p.applicationnumber=_applicationnumber and p.srocode=_srocode) as  party into v_array;
	
		elseif(v_fingerid=0)
		then
		select array_to_json(array_agg(row_to_json(party)))
		from(select e.endorsementdescriptione,e.endorsementdescriptionk  from kaveri.partyinfo p 
			join kaveri.fingertypemaster f on p.fingerid = f.fingerid 
			join kaveri.EndorsementFlowMaster e on e.endorsmentname = case when p.isexecutor ='true' then 'Executant acceptance' else null end
			where p.fingerid=0 and e.endorsmentsubname ='Party with out finger' and p.applicationnumber=_applicationnumber and p.srocode=_srocode) as  party into v_array;
		
		elseif(v_executor=true)
			then
			select array_to_json(array_agg(row_to_json(party)))
		from(
				select distinct e.endorsementdescriptione,e.endorsementdescriptionk  from kaveri.witnessinfo w 
				join kaveri.partyinfo p on w.documentid =p.documentid 
				join kaveri.EndorsementFlowMaster e on e.endorsmentname = case when w.isexicutent  ='true' then 'Witness identifying executants' else null end
				where w.isexicutent = true and e.endorsmentsubname ='Witness identifying executants' and p.applicationnumber=_applicationnumber and p.srocode=_srocode)as  party into v_array;

		end if;
	
		
	
	end if;
 end loop;
return (v_array);

end;
$$;


ALTER FUNCTION kaveri.fn_fetch_endorsementdetails_bak(_applicationnumber character varying, _srocode bigint) OWNER TO csgadmin;

