CREATE FUNCTION kaveri.fn_fetch_executant_details(_applicationnumber character varying) RETURNS TABLE(partyid bigint, districtcode integer, districtnamee character varying, talukcode integer, taluknamee character varying, hoblicode integer, hoblinamee character varying, villagecode bigint, villagenamee character varying, srocode integer, sronamee character varying, partytypeid integer, descriptioninenglish character varying, firstname character varying, middlename character varying, lastname character varying, address character varying, age character varying, sex smallint, isexecutor boolean, ispresenter boolean, admissiondate timestamp without time zone, aliasname character varying, correctedname character varying, relationship character varying, relativename character varying, epic character varying, pan character varying, phonenumber character varying, availableextacre integer, availableextgunta integer, availableextfgunta numeric, bincom character varying, category character varying, dateofdeath timestamp without time zone, fingerid integer, fingerverificationstatusid smallint, ispartofrtc boolean, landcode bigint, mainownerno bigint, ownerno bigint, partypoa character varying, photopath character varying, poaadmission bigint, poapresentation bigint, primaryseller boolean, profession character varying, restriction character varying, restrictiondescription character varying, restrictiontype character varying, section88exemption boolean, thumbmatchfailedreasonid integer, thumbminutiae bytea, thumbpath character varying, totalextacre integer, totalextgunta integer, totalextfgunta numeric, transactextacre integer, transactextgunta integer, transactextfgunta numeric, volumename character varying, hasgpa boolean, isaua boolean, importedpartyparentid bigint, salutationid smallint, descriptione character varying, isorganization boolean, organizationid integer, applicationnumber character varying, verified boolean, issroapproved character varying, tanno character varying, yearofincorp integer, orgpoaauthsignfname text, orgpoaauthsignmname text, orgpoaauthsignlname text, linkpartyid bigint, housenumber text, pin integer, propertyid bigint, propertynumber character varying, idprooftypeid smallint, isconsentwitness boolean, isprivateattendance boolean, idprooftypename character varying, ispartyrefused boolean, refuseremarks text, islateapperance boolean, section88file character, isduplicate boolean, duplicatepartyid bigint, isbiometricrefused boolean, iscitizennotappeared boolean, isendorseprinted boolean, aadharhash character varying, datetimeofconsent character varying, nameasperaadhar character varying, digilockerid character varying, isdeptaadharvalidated boolean, iscitizenaadharverified boolean, aadhaardeclinereason character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
if(_applicationnumber is null) then
raise exception 'Missing Applicationnumber';
end if;

return query
SELECT DISTINCT a.partyid,
    a.districtcode,
    e.districtnamee,
    a.talukcode,
    f.taluknamee,
    a.hoblicode,
    g.hoblinamee,
    a.villagecode,
    h.villagenamee,
    a.srocode,
    b.sronamee,
    a.partytypeid,
    c.descriptioninenglish,
    a.firstname,
    a.middlename,
    a.lastname,
    a.address,
    a.age,
    a.sex,
    a.isexecutor,
    a.ispresenter,
    a.admissiondate,
    a.aliasname,
    a.correctedname,
    a.relationship,
    a.relativename,
    a.epic,
    a.pan,
    a.phonenumber,
    a.availableextacre,
    a.availableextgunta,
    a.availableextfgunta,
    a.bincom,
    a.category,
    a.dateofdeath,
    a.fingerid,
    a.fingerverificationstatusid,
    a.ispartofrtc,
    a.landcode,
    a.mainownerno,
    a.ownerno,
    a.partypoa,
    a.photopath,
    a.poaadmission,
    a.poapresentation,
    a.primaryseller,
    a.profession,
    a.restriction,
    a.restrictiondescription,
    a.restrictiontype,
    a.section88exemption,
    a.thumbmatchfailedreasonid,
    a.thumbminutiae,
    a.thumbpath,
    a.totalextacre,
    a.totalextgunta,
    a.totalextfgunta,
    a.transactextacre,
    a.transactextgunta,
    a.transactextfgunta,
    a.volumename,
    a.hasgpa,
    a.isaua,
    a.importedpartyparentid,
    a.salutationid,
    d.descriptione,
    a.isorganization,
    a.organizationid,
    a.applicationnumber,
    a.verified,
    a.issroapproved,
    a.tanno,
    a.yearofincorp,
    a.orgpoaauthsignfname,
    a.orgpoaauthsignmname,
    a.orgpoaauthsignlname,
    a.linkpartyid,
    a.housenumber,
    a.pin,
    a.propertyid,
    a.propertynumber,
    a.idprooftypeid,
    a.isconsentwitness,
    a.isprivateattendance,
    k.description AS idprooftypename,
    a.ispartyrefused,
    ap.refuseremarks,
    a.islateapperance,
    a.section88file,
    a.isduplicate,
    a.duplicatepartyid,
    a.isbiometricrefused,
    a.iscitizennotappeared,
    a.isendorseprinted,
    a.aadharhash,
    a.datetimeofconsent,
    a.nameasperaadhar,
    a.digilockerid,
        CASE
            WHEN dd.partyid IS NOT NULL AND dd.responsestatus::text = 'Y'::text THEN true
            ELSE false
        END AS isdeptaadharvalidated,
    a.iscitizenaadharverified,
    a.aadhaardeclinereason
   FROM kaveri.partyinfo a
	JOIN kaveri.applicantapplicationdetails ap ON a.applicationnumber::text = ap.applicationnumber::text     
 	JOIN kaveri.partytypemaster c ON a.partytypeid = c.partytypeid 
     JOIN kaveri.sromaster b ON a.srocode = b.srocode
	LEFT JOIN kaveri.salutationmaster d ON a.salutationid = d.salutationid
     LEFT JOIN kaveri.aadhar_authentication_log dd ON a.partyid = dd.partyid and dd.responsestatus::text = 'Y'::text
     LEFT JOIN kaveri.districtmaster e ON a.districtcode = e.districtcode
     LEFT JOIN kaveri.talukmaster f ON a.talukcode = f.talukcode
     LEFT JOIN kaveri.hoblimaster g ON a.hoblicode = g.hoblicode
     LEFT JOIN kaveri.villagemaster h ON a.villagecode = h.villagecode
     LEFT JOIN kaveri.mas_idprooftypes k ON a.idprooftypeid = k.idprooftypeid
  WHERE a.applicationnumber =_applicationnumber;
end;
$$;


