     LEFT JOIN kaveri.villagemaster h ON a.villagecode = h.villagecode
     LEFT JOIN kaveri.propertynumberdetails j ON a.propertyid = j.propertyid
     LEFT JOIN kaveri.mas_idprooftypes k ON a.idprooftypeid = k.idprooftypeid
     
  WHERE a.applicationnumber =_applicationnumber
  ORDER BY a.partyid, a.propertyid;
end;
$$;


ALTER FUNCTION kaveri.fn_fetch_executant_details_test(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_executant_details_test_1(character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_executant_details_test_1(_applicationnumber character varying) RETURNS TABLE(partyid bigint, districtcode integer, districtnamee character varying, talukcode integer, taluknamee character varying, hoblicode integer, hoblinamee character varying, villagecode bigint, villagenamee character varying, srocode integer, sronamee character varying, partytypeid integer, descriptioninenglish character varying, firstname character varying, middlename character varying, lastname character varying, address character varying, age character varying, sex smallint, isexecutor boolean, ispresenter boolean, admissiondate timestamp without time zone, aliasname character varying, correctedname character varying, relationship character varying, relativename character varying, epic character varying, pan character varying, phonenumber character varying, availableextacre integer, availableextgunta integer, availableextfgunta numeric, bincom character varying, category character varying, dateofdeath timestamp without time zone, fingerid integer, fingerverificationstatusid smallint, ispartofrtc boolean, landcode bigint, mainownerno bigint, ownerno bigint, partypoa character varying, photopath character varying, poaadmission bigint, poapresentation bigint, primaryseller boolean, profession character varying, restriction character varying, restrictiondescription character varying, restrictiontype character varying, section88exemption boolean, thumbmatchfailedreasonid integer, thumbminutiae bytea, thumbpath character varying, totalextacre integer, totalextgunta integer, totalextfgunta numeric, transactextacre integer, transactextgunta integer, transactextfgunta numeric, volumename character varying, hasgpa boolean, isaua boolean, importedpartyparentid bigint, salutationid smallint, descriptione character varying, isorganization boolean, organizationid integer, applicationnumber character varying, verified boolean, issroapproved character varying, tanno character varying, yearofincorp integer, orgpoaauthsignfname text, orgpoaauthsignmname text, orgpoaauthsignlname text, linkpartyid bigint, housenumber text, pin integer, propertyid bigint, propertynumber character varying, idprooftypeid smallint, isconsentwitness boolean, isprivateattendance boolean, idprooftypename character varying, ispartyrefused boolean, refuseremarks text, islateapperance boolean, section88file character, isduplicate boolean, duplicatepartyid bigint, isbiometricrefused boolean, iscitizennotappeared boolean, isendorseprinted boolean, aadharhash character varying, datetimeofconsent character varying, nameasperaadhar character varying, digilockerid character varying, isdeptaadharvalidated boolean, iscitizenaadharverified boolean, aadhaardeclinereason character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
if(_applicationnumber is null) then
raise exception 'Missing Applicationnumber';
end if;

return query
SELECT DISTINCT a.partyid,
    a.districtcode,
    e.districtnamee,
    a.talukcode,
    f.taluknamee,
    a.hoblicode,
    g.hoblinamee,
    a.villagecode,
    h.villagenamee,
    a.srocode,
    b.sronamee,
    a.partytypeid,
    c.descriptioninenglish,
    a.firstname,
    a.middlename,
    a.lastname,
    a.address,
    a.age,
    a.sex,
    a.isexecutor,
    a.ispresenter,
    a.admissiondate,
    a.aliasname,
    a.correctedname,
    a.relationship,
    a.relativename,
    a.epic,
    a.pan,
    a.phonenumber,
    a.availableextacre,
    a.availableextgunta,
    a.availableextfgunta,
    a.bincom,
    a.category,
    a.dateofdeath,
    a.fingerid,
    a.fingerverificationstatusid,
    a.ispartofrtc,
    a.landcode,
    a.mainownerno,
    a.ownerno,
    a.partypoa,
    a.photopath,
    a.poaadmission,
    a.poapresentation,
    a.primaryseller,
    a.profession,
    a.restriction,
    a.restrictiondescription,
    a.restrictiontype,
    a.section88exemption,
    a.thumbmatchfailedreasonid,
    a.thumbminutiae,
    a.thumbpath,
    a.totalextacre,
    a.totalextgunta,
    a.totalextfgunta,
    a.transactextacre,
    a.transactextgunta,
    a.transactextfgunta,
    a.volumename,
    a.hasgpa,
    a.isaua,
    a.importedpartyparentid,
    a.salutationid,
    d.descriptione,
    a.isorganization,
    a.organizationid,
    a.applicationnumber,
    a.verified,
    a.issroapproved,
    a.tanno,
    a.yearofincorp,
    a.orgpoaauthsignfname,
    a.orgpoaauthsignmname,
    a.orgpoaauthsignlname,
    a.linkpartyid,
    a.housenumber,
    a.pin,
    a.propertyid,
    a.propertynumber,
    a.idprooftypeid,
    a.isconsentwitness,
    a.isprivateattendance,
    k.description AS idprooftypename,
    a.ispartyrefused,
    ap.refuseremarks,
    a.islateapperance,
    a.section88file,
    a.isduplicate,
    a.duplicatepartyid,
    a.isbiometricrefused,
    a.iscitizennotappeared,
    a.isendorseprinted,
    a.aadharhash,
    a.datetimeofconsent,
    a.nameasperaadhar,
    a.digilockerid,
        CASE
            WHEN dd.partyid IS NOT NULL AND dd.responsestatus::text = 'Y'::text THEN true
            ELSE false
        END AS isdeptaadharvalidated,
    a.iscitizenaadharverified,
    a.aadhaardeclinereason
   FROM kaveri.partyinfo a
	JOIN kaveri.applicantapplicationdetails ap ON a.applicationnumber::text = ap.applicationnumber::text     
 	JOIN kaveri.partytypemaster c ON a.partytypeid = c.partytypeid 
     JOIN kaveri.sromaster b ON a.srocode = b.srocode
	LEFT JOIN kaveri.salutationmaster d ON a.salutationid = d.salutationid
     LEFT JOIN kaveri.aadhar_authentication_log dd ON a.partyid = dd.partyid
     LEFT JOIN kaveri.districtmaster e ON a.districtcode = e.districtcode
     LEFT JOIN kaveri.talukmaster f ON a.talukcode = f.talukcode
     LEFT JOIN kaveri.hoblimaster g ON a.hoblicode = g.hoblicode
     LEFT JOIN kaveri.villagemaster h ON a.villagecode = h.villagecode
     LEFT JOIN kaveri.mas_idprooftypes k ON a.idprooftypeid = k.idprooftypeid
  WHERE a.applicationnumber =_applicationnumber;
end;
$$;


ALTER FUNCTION kaveri.fn_fetch_executant_details_test_1(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_fda_pending(bigint); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_fda_pending(_sfdaid bigint DEFAULT NULL::bigint) RETURNS TABLE(v_doc bigint, v_assigntoday bigint, v_pendingec bigint, v_pendingcc bigint)
    LANGUAGE plpgsql
    AS $$
declare 
v_doc bigint;
v_assigntoday bigint;
v_pendingEC bigint;
v_pendingCC bigint;

begin

select coalesce(count(applicationnumber),0) into v_pendingEC from kaveri.applicantapplicationdetails adss  where  sfdaid =_sfdaid and currentstatus in ('CE139','CE105') ;

select coalesce(count(applicationnumber),0)	into v_pendingCC from kaveri.applicantapplicationdetails adss  where  sfdaid =_sfdaid and currentstatus in ('CC105') ;

return query
with a as(
select applicationnumber
from kaveri.applicantapplicationdetails a 
where a.sfdaid =_sfdaid and a.applicationtypeid=1 and a.currentstatus='CD103')
select 
count(DISTINCT a.applicationnumber) as v_doc,
count(a2.applicationnumber) filter (where a2.crtdt::date=current_date and a2.wrkflowstatusid ='CD103') as v_assigntoday,
v_pendingEC,
v_pendingCC
from a
join kaveri.applicationaudit a2 on a.applicationnumber =a2.applicationnumber;

end;
$$;


ALTER FUNCTION kaveri.fn_fetch_fda_pending(_sfdaid bigint) OWNER TO csgadmin;

--
-- Name: fn_fetch_fda_pending_11(bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_fda_pending_11(_sfdaid bigint DEFAULT NULL::bigint) RETURNS TABLE(v_doc bigint, v_assigntoday bigint, v_pendingec bigint, v_pendingcc bigint)
    LANGUAGE plpgsql
    AS $$
declare 
v_doc bigint;
v_assigntoday bigint;
v_pendingEC bigint;
v_pendingCC bigint;

begin

return query	
select coalesce(sum(sf.doc),0)::bigint as v_doc,coalesce(sum(sf.assigntoday),0)::bigint as v_assigntoday
,coalesce(sum(sf.pendingec),0)::bigint as v_pendingec
,coalesce(sum(sf.pendingcc),0)::bigint as v_pendingcc from (
select  
(case when a.currentstatus='CD103' then count(a.applicationnumber)end) as doc ,
count(distinct a2.applicationnumber) as assigntoday,
(case when  a.currentstatus in ('CE139','CE105') 
then count(ea.applicationnumber) end) pendingec,
(case when a.currentstatus in ('CC105') then count(ca.applicationnumber) 
end ) as pendingcc
from 
kaveri.applicantapplicationdetails a 
left join kaveri.applicationaudit a2 on a.applicationnumber =a2.applicationnumber 
and a2.wrkflowstatusid ='CD103' and a2.crtusr::date=current_date
left join kaveri.ec_applicationdetails ea on ea.applicationnumber =a.applicationnumber 
left join kaveri.cc_applicationdetails ca on a.applicationnumber =ca.applicationnumber 
where a.sfdaid =_sfdaid
group by a.currentstatus) as sf;

end;
$$;


ALTER FUNCTION kaveri.fn_fetch_fda_pending_11(_sfdaid bigint) OWNER TO postgres;

--
-- Name: fn_fetch_fda_pending_20260630_1(bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_fda_pending_20260630_1(_sfdaid bigint DEFAULT NULL::bigint) RETURNS TABLE(v_doc bigint, v_assigntoday bigint, v_pendingec bigint, v_pendingcc bigint)
    LANGUAGE plpgsql
    AS $$
declare 
v_doc bigint;
v_assigntoday bigint;
v_pendingEC bigint;
v_pendingCC bigint;

begin

select coalesce(count(applicationnumber),0) into v_pendingEC from kaveri.applicantapplicationdetails adss  where  sfdaid =_sfdaid and currentstatus in ('CE139','CE105') ;

select coalesce(count(applicationnumber),0)	into v_pendingCC from kaveri.applicantapplicationdetails adss  where  sfdaid =_sfdaid and currentstatus in ('CC105') ;

return query
	with a as(
	select applicationnumber,currentstatus
	from kaveri.applicantapplicationdetails a 
	where a.sfdaid =_sfdaid and a.applicationtypeid=1 and a.currentstatus='CD103')
	select 
	count(a.applicationnumber) as v_doc,
	count(a2.applicationnumber) filter (where a2.crtdt::date=current_date and a2.wrkflowstatusid ='CD103') as v_assigntoday,
	v_pendingEC,
	v_pendingCC
	from a
	join kaveri.applicationaudit a2 on a.applicationnumber =a2.applicationnumber;

end;
$$;


ALTER FUNCTION kaveri.fn_fetch_fda_pending_20260630_1(_sfdaid bigint) OWNER TO postgres;

--
-- Name: fn_fetch_fda_pending_ab(bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_fda_pending_ab(_sfdaid bigint DEFAULT NULL::bigint) RETURNS TABLE(v_doc bigint, v_assigntoday bigint, v_pendingec bigint, v_pendingcc bigint)
    LANGUAGE plpgsql
    AS $$
declare 
v_doc bigint;
v_assigntoday bigint;
v_pendingEC bigint;
v_pendingCC bigint;

begin

select count(*) into v_pendingEC from kaveri.applicantapplicationdetails adss  where currentstatus in ('CE139','CE105') and sfdaid =_sfdaid ;

select count(*) into v_pendingcc from kaveri.applicantapplicationdetails adss  where currentstatus in ('CC105') and sfdaid =_sfdaid;

select count(*) into v_doc from kaveri.applicantapplicationdetails where currentstatus='CD103' and sfdaid = _sfdaid;

select COUNT(*) into v_assigntoday from kaveri.applicantapplicationdetails a
where a.sfdaid = _sfdaid
  and a.applicationtypeid = 1
  and exists (select 1 from kaveri.applicationaudit a2
        where a2.applicationnumber = a.applicationnumber
          and a2.wrkflowstatusid = 'CD103'
          and a2.crtdt >= CURRENT_DATE
          and a2.crtdt < CURRENT_DATE + INTERVAL '1 day'
  )
  and exists(select 1 from kaveri.wrkflowmaster w
        where w.wrkflowstatusid = a.currentstatus and w.wrkfloworder >= 3);

return query
    select v_doc, v_assigntoday, v_pendingec, v_pendingcc;
end;
$$;


ALTER FUNCTION kaveri.fn_fetch_fda_pending_ab(_sfdaid bigint) OWNER TO postgres;

--
-- Name: fn_fetch_feesrequired_marriage(integer, integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_feesrequired_marriage(_marriagetype integer, _marriagemode integer) RETURNS TABLE(feerulecode integer, description text, value numeric)
    LANGUAGE plpgsql
    AS $$

DECLARE
BEGIN
	if _marriagetype=1 and _marriagemode=1 THEN  --Hindu Marriage online
	
		return query
		select f.feerulecode,f.descriptione::text,f.value::numeric from kaveri.feesrulemaster f 
		where f.feerulecode in (66,67);
	elsif _marriagetype=1 and _marriagemode=2 THEN  ----Hindu Marriage OFFLINE
	
		return query
		select f.feerulecode,f.descriptione::text,f.value::numeric from kaveri.feesrulemaster f 
		where f.feerulecode in (66,67,68,85);
	
	elsif _marriagetype=2 and _marriagemode=1 THEN --Hindu Marriage special online
	
	 return query
	 select f.feerulecode,f.descriptione::text,f.value::numeric from kaveri.feesrulemaster f where f.feerulecode in (66,67);
	
	
	elsif _marriagetype=2 and _marriagemode=2 THEN     --Hindu Marriage special offline
	
	 return query
	 select f.feerulecode,f.descriptione::text,f.value::numeric from kaveri.feesrulemaster f 
	 where f.feerulecode in (66,67,68,85);
	
	elsif _marriagetype=3 and _marriagemode=1 THEN   --Hindu Marriage special others online
	
	 return query
	 select f.feerulecode,f.descriptione::text,f.value::numeric from kaveri.feesrulemaster f where f.feerulecode in (66,67);
	
	elsif _marriagetype=3 and _marriagemode=2 THEN    --Hindu Marriage special offline
	
	 return query
	 select f.feerulecode,f.descriptione::text,f.value::numeric from kaveri.feesrulemaster f 
	 where f.feerulecode in (66,67,68,85);
	 
	 end if;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_feesrequired_marriage(_marriagetype integer, _marriagemode integer) OWNER TO csgadmin;

--
-- Name: fn_fetch_feesrequired_marriage_byapplication(character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_feesrequired_marriage_byapplication(_applicationnumber character varying) RETURNS TABLE(feeruleid smallint, feedescription character varying, payableamount numeric)
    LANGUAGE plpgsql
    AS $$
declare
v_nocopy int;

begin
	return query
	select mr.feeruleid,
			mr.feedescription,
			mr.payableamount from kaveri.mrg_requiredfees mr 
		join kaveri.marriageregistration m on m.applicationnumber = mr.applicationnumber
		where m.applicationnumber = _applicationnumber;
end;
$$;


