--
-- Name: fn_fetch_filing_book1_property_details_json(text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_filing_book1_property_details_json(_applicationnumber text) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_data_json JSON;
BEGIN
    -- Prepare the JSON data for each property
    SELECT json_agg(data_json) INTO v_data_json
    FROM (
        WITH property_details AS (
            SELECT 
                pm.propertyid AS property_id,
                pm.regsrocode AS reg_sro_code,
                pm.propertytypeid AS property_type_id,
                dm.districtcode AS district_code,
                tm.talukcode AS taluk_code,
                hm.hoblicode AS hobli_code,
                pm.villagecode AS village_code,
                pm.totalarea AS total_area,
                pm.unitid AS unit_id,
                pm.northboundary AS north_boundary,
                pm.southboundary AS south_boundary,
                pm.eastboundary AS east_boundary,
                pm.westboundary AS west_boundary,
                COALESCE(fb1.amount_paid, '0') AS stamp_duty,
                fb1.challan_number AS challan_number,
                CASE 
                    WHEN fb1.payment_type_id = '0' THEN 'No'
                    WHEN fb1.payment_type_id = '1' THEN 'Received'
                    WHEN fb1.payment_type_id = '2' THEN 'E-Stamp'
                    WHEN fb1.payment_type_id = '3' THEN 'K2-Challan'
                    ELSE ''
                END AS payment_type,
                CASE 
                    WHEN fb1.book_id = 7 THEN NULL
                    ELSE fb1.order_number
                END AS order_number,
                CASE 
                    WHEN fb1.book_id = 7 THEN NULL
                    ELSE pm.consideration
                END AS surety_amount,
                pm.documentid AS doc_id,
                pm.srocode AS sro_code,
                pm.ismovableproperty AS is_movable,
                ps.description AS schedule_desc,
				--pi.isorganization AS type_of_party,
				bool_or(pi.isorganization) AS type_of_party,
                -- Combining current_property_type_ids and current_number as an object
                json_agg(
                   DISTINCT jsonb_build_object(
                        'currentPropertyTypeId', pnd.currentpropertytypeid,
                        'currentNumber', pnd.currentnumber
                    )
                ) AS current_property_details,
                COALESCE(
                    jsonb_agg(
                        DISTINCT jsonb_build_object(
                            'partyid', pi.partyid,
                            'salutationid', COALESCE(pi.salutationid, 0),
                            'firstname', pi.firstname,
                            'middlename', pi.middlename,
                            'lastname', pi.lastname,
                            'address', pi.address,
                            'isexecutor', pi.isexecutor,
                            'ispresenter', pi.ispresenter,
                            'partytypeid', pi.partytypeid,
                            'age', pi.age
                        )
                    ) FILTER (WHERE (fb1.book_id = 7 AND pi.partytypeid = 1) OR (fb1.book_id = 14 AND pi.partytypeid = 2 AND pi.isorganization IS FALSE)), 
                    '[]'::jsonb
                ) AS party_details,

				COALESCE(
                    jsonb_agg(
                        DISTINCT jsonb_build_object(
                            'partyid', pi.partyid,
                            'orgname', pi.firstname,
                            'yearofincorp', pi.yearofincorp,
                            'tanno', pi.tanno,
                            --'houseno', pi.housenumber,
                            'streetaddress', pi.address,
							--'districtcode', pi.districtcode,
							--'talukcode', pi.talukcode,
							--'pincode', pi.pin,
                            'ispresenter', pi.ispresenter,
							'isexecutor', pi.isexecutor,
                            'partytypeid', pi.partytypeid
                        )
                    ) FILTER (WHERE fb1.book_id = 14 AND pi.partytypeid = 2 AND pi.isorganization IS TRUE),  
                    '[]'::jsonb
                ) AS org_details

            FROM kaveri.propertymaster pm
            LEFT JOIN kaveri.propertyschedules ps ON pm.propertyid = ps.propertyid
            LEFT JOIN kaveri.propertynumberdetails pnd ON pm.propertyid = pnd.propertyid
            LEFT JOIN kaveri.partyinfo pi ON pm.propertyid = pi.propertyid -- pm.applicationnumber = pi.applicationnumber
            LEFT JOIN kaveri.villagemaster vm ON pm.villagecode = vm.villagecode
            LEFT JOIN kaveri.hoblimaster hm ON vm.hoblicode = hm.hoblicode
            LEFT JOIN kaveri.talukmaster tm ON hm.talukcode = tm.talukcode
            LEFT JOIN kaveri.districtmaster dm ON tm.districtcode = dm.districtcode
            LEFT JOIN kaveri.filing_book1 fb1 ON pm.applicationnumber = fb1.applicationnumber
            WHERE pm.applicationnumber = _applicationnumber
            GROUP BY 
                pm.propertyid, ps.description, pm.regsrocode, pm.propertytypeid, dm.districtcode, tm.talukcode, hm.hoblicode,
                pm.villagecode, pm.totalarea, pm.unitid, pm.northboundary, pm.southboundary,
                pm.eastboundary, pm.westboundary, fb1.amount_paid, fb1.challan_number, fb1.payment_type_id, 
                fb1.book_id, fb1.order_number, fb1.surety_amount, pm.documentid, pm.srocode, pm.ismovableproperty --,pi.isorganization
        )
        SELECT 
            property_id, 
            reg_sro_code, 
            property_type_id,
            district_code,
            taluk_code,
            hobli_code, 
            village_code, 
            total_area, 
            unit_id, 
            north_boundary, 
            south_boundary, 
            east_boundary, 
            west_boundary, 
            stamp_duty,
            challan_number,
            payment_type,
            order_number,
            surety_amount,
            doc_id, 
            sro_code, 
            is_movable,
			type_of_party, 
            schedule_desc, 
            current_property_details, 
            party_details,
			org_details
        FROM property_details
    ) data_json;

    -- Return the JSON result
    RETURN v_data_json;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_filing_book1_property_details_json(_applicationnumber text) OWNER TO postgres;

--
-- Name: fn_fetch_filing_propertyremark(character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_filing_propertyremark(_application_no character varying) RETURNS TABLE(propertyid bigint, applicationno character varying, bookid integer, groupeddetails jsonb)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        r.property_id as PropertyId,
		_application_no as ApplicationNo,
		fb.book_id AS BookId, 
        jsonb_agg(jsonb_build_object(
            'verification_id', r.verification_id,
            'application_no', r.application_no,
            'prop_details_remarks_fda', r.prop_details_remarks_fda,
            'prop_details_verify_fda', r.prop_details_verify_fda,
            'bound_details_remarks_fda', r.bound_details_remarks_fda,
            'bound_details_verify_fda', r.bound_details_verify_fda,
            'sd_details_remarks_fda', r.sd_details_remarks_fda,
            'sd_details_verify_fda', r.sd_details_verify_fda,
            'party_details_remarks_fda', r.party_details_remarks_fda,
            'party_details_verify_fda', r.party_details_verify_fda,
            'prop_details_remarks_sro', r.prop_details_remarks_sro,
            'prop_details_verify_sro', r.prop_details_verify_sro,
            'bound_details_remarks_sro', r.bound_details_remarks_sro,
            'bound_details_verify_sro', r.bound_details_verify_sro,
            'sd_details_remarks_sro', r.sd_details_remarks_sro,
            'sd_details_verify_sro', r.sd_details_verify_sro,
            'party_details_remarks_sro', r.party_details_remarks_sro,
            'party_details_verify_sro', r.party_details_verify_sro
        )) AS GroupedDetails
    FROM kaveri.tbl_book1_part3_remarks r 
	--JOIN kaveri.filing_book1 fb ON r.application_no = fb.applicationnumber
JOIN (
    SELECT applicationnumber, book_id FROM kaveri.filing_book1
    UNION
    SELECT applicationnumber, 7 FROM kaveri.book1_part3_court
) fb ON r.application_no = fb.applicationnumber
    WHERE r.application_no = _application_no
    GROUP BY r.property_id, fb.book_id;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_filing_propertyremark(_application_no character varying) OWNER TO postgres;

--
-- Name: fn_fetch_filing_propertyremark_by_propertyid(character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_filing_propertyremark_by_propertyid(_application_no character varying) RETURNS TABLE(propertyid bigint, applicationno character varying, bookid integer, groupeddetails jsonb)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        r.property_id,
        r.application_no,
        fb.book_id,
        jsonb_agg(jsonb_build_object(
            'verification_id', r.verification_id,
            'application_no', r.application_no,
            'prop_details_remarks_fda', r.prop_details_remarks_fda,
            'prop_details_verify_fda', r.prop_details_verify_fda,
            'bound_details_remarks_fda', r.bound_details_remarks_fda,
            'bound_details_verify_fda', r.bound_details_verify_fda,
            'sd_details_remarks_fda', r.sd_details_remarks_fda,
            'sd_details_verify_fda', r.sd_details_verify_fda,
            'party_details_remarks_fda', r.party_details_remarks_fda,
            'party_details_verify_fda', r.party_details_verify_fda,
            'prop_details_remarks_sro', r.prop_details_remarks_sro,
            'prop_details_verify_sro', r.prop_details_verify_sro,
            'bound_details_remarks_sro', r.bound_details_remarks_sro,
            'bound_details_verify_sro', r.bound_details_verify_sro,
            'sd_details_remarks_sro', r.sd_details_remarks_sro,
            'sd_details_verify_sro', r.sd_details_verify_sro,
            'party_details_remarks_sro', r.party_details_remarks_sro,
            'party_details_verify_sro', r.party_details_verify_sro
        )) AS groupeddetails
    FROM kaveri.tbl_book1_part3_remarks r 
    --JOIN kaveri.filing_book1 fb ON r.application_no = fb.applicationnumber
JOIN (
    SELECT applicationnumber, book_id FROM kaveri.filing_book1
    UNION
    SELECT applicationnumber, 7 FROM kaveri.book1_part3_court
) fb ON r.application_no = fb.applicationnumber

    WHERE r.property_id IN (
        SELECT pm.propertyid FROM kaveri.propertymaster pm WHERE pm.applicationnumber = _application_no
    )
    GROUP BY r.property_id, fb.book_id, r.application_no;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_filing_propertyremark_by_propertyid(_application_no character varying) OWNER TO postgres;

--
-- Name: fn_fetch_filing_summary_json(text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_filing_summary_json(_applicationnumber text) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_data_json JSON;
BEGIN
    SELECT json_agg(data_json) INTO v_data_json
    FROM (
        SELECT
            -- Property Details
            pm.propertyid AS property_id,
			fb.book_id AS book_id,
            di.districtnamee AS district,
            ta.taluknamee AS taluk,
            ho.hoblinamee AS hobli,
            vi.villagenamee AS index_ii_village,
            pt.propertytypename AS property_type,
            ps.eastboundary AS east,
            ps.westboundary AS west,
            ps.northboundary AS north,
            ps.southboundary AS south,
			pm.stampduty AS stamp_duty,
			pm.consideration AS consideration,
			--pnd.currentnumber AS present_property_no,

            -- Schedule Description Details
            COALESCE((SELECT array_to_json(array_agg(row_to_json(schedule_data)))
             FROM (
                SELECT
                    'Schedule: ' || ps.scheduletype AS schedule_type,
                    --'Survey Number: ' || pnd.survey_no AS property_details,
					COALESCE(
					    (SELECT string_agg(pnm.typenameenglish || ': ' || pnd.currentnumber, ', ')
					     FROM kaveri.propertynumberdetails pnd
					     JOIN kaveri.propertynotypemaster pnm 
					         ON pnd.currentpropertytypeid = pnm.propertytypeid
					     WHERE pnd.propertyid = pm.propertyid
					    ),
					    'No details available'
					) AS property_details,

                    pm.totalarea AS area,
                    mm.measurementnamee AS unit,
                    ps.description AS description,

                    -- Executants (partytypeid = 2)
                    (SELECT array_to_json(array_agg(row_to_json(party_data)))
                     FROM (
                        --SELECT pi.firstname AS name
						SELECT concat_ws(' ', pi.firstname, pi.middlename, pi.lastname) AS name
                        FROM kaveri.partyinfo pi
                        WHERE pi.applicationnumber = _applicationnumber AND pi.partytypeid = 2
						AND pi.propertyid = pm.propertyid
                        GROUP BY pi.firstname, pi.middlename, pi.lastname
                     ) party_data) AS executants,

				-- Claimants (partytypeid = 1) filtered by propertyId
                CASE 
                    WHEN book_id = 7 THEN
                        (SELECT array_to_json(array_agg(row_to_json(party_data)))
                        FROM (
                            --SELECT pi.firstname AS name
							SELECT concat_ws(' ', pi.firstname, pi.middlename, pi.lastname) AS name
                            FROM kaveri.partyinfo pi
                            INNER JOIN kaveri.partyschedules ps 
                                ON pi.partyid = ps.partyid 
                                AND pi.propertyid = ps.propertyid
                            WHERE ps.applicationnumber = _applicationnumber 
                                AND ps.isdelete = false
                                AND pi.partytypeid = 1
                                AND ps.propertyid = pm.propertyid
                            GROUP BY pi.firstname, pi.middlename, pi.lastname
                        ) party_data)
                    WHEN book_id = 14 THEN
                        (SELECT array_to_json(array_agg(row_to_json(party_data)))
                        FROM (
                            SELECT pi.firstname AS name
                            FROM kaveri.partyinfo pi
                            WHERE pi.applicationnumber = _applicationnumber AND pi.partytypeid = 1
                            --AND pi.propertyid = pm.propertyid
                            GROUP BY pi.firstname
                        ) party_data)
                END AS claimants

                FROM kaveri.propertyschedules ps
                LEFT JOIN kaveri.measurementmaster mm ON ps.unitid = mm.measurementcode
                LEFT JOIN kaveri.propertynumberdetails pnd ON ps.propertyid = pnd.propertyid
                WHERE ps.propertyid = pm.propertyid
                GROUP BY ps.scheduletype, pnd.survey_no, pm.totalarea, mm.measurementnamee, ps.description
             ) schedule_data
			), '[]') AS schedule_description_details,

		--Stamp Duty Details
		(SELECT array_to_json(array_agg(row_to_json(challan_data)))
             FROM (
			SELECT bc.challan_number AS challan_number,
			--CASE
				--WHEN bc.book_id = 7 THEN COALESCE(bc.amount_paid::decimal, 0)
				--WHEN bc.book_id = 14 THEN COALESCE(bc.surety_amount::decimal, 0)
				--ELSE 0
			--END AS amount_paid,
			CASE 
            	WHEN bc.payment_type_id = '0' THEN 'No'
				WHEN bc.payment_type_id = '1' THEN 'Received'
            	WHEN bc.payment_type_id = '2' THEN 'E-Stamp'
            	WHEN bc.payment_type_id = '3' THEN 'K2-Challan'
            ELSE ''
        	END AS payment_type
			FROM kaveri.filing_book1 bc WHERE bc.applicationnumber = _applicationnumber --AND bc.is_stamp_duty_paid = true
			GROUP BY bc.challan_number, bc.amount_paid, bc.payment_type_id, bc.book_id, bc.surety_amount ) challan_data) AS stamp_duty_details

        FROM kaveri.propertymaster pm
        LEFT JOIN kaveri.villagemaster vi ON pm.villagecode = vi.villagecode
        LEFT JOIN kaveri.hoblimaster ho ON vi.hoblicode = ho.hoblicode
        LEFT JOIN kaveri.talukmaster ta ON vi.talukcode = ta.talukcode
        LEFT JOIN kaveri.districtmaster di ON ta.districtcode = di.districtcode
        LEFT JOIN kaveri.propertytypemaster pt ON pm.propertytypeid = pt.propertytypeid
        LEFT JOIN kaveri.propertyschedules ps ON pm.propertyid = ps.propertyid
		LEFT JOIN kaveri.propertynumberdetails pnd ON pm.propertyid = pnd.propertyid
		LEFT JOIN kaveri.filing_book1 fb ON pm.applicationnumber = fb.applicationnumber
        WHERE pm.applicationnumber = _applicationnumber
        GROUP BY pm.propertyid, fb.book_id, di.districtnamee, ta.taluknamee, ho.hoblinamee, vi.villagenamee, pt.propertytypename,
                 ps.eastboundary, ps.westboundary, ps.northboundary, ps.southboundary, pm.totalarea, pm.stampduty, pm.consideration
    ) data_json;

    RETURN v_data_json;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_filing_summary_json(_applicationnumber text) OWNER TO postgres;

--
-- Name: fn_fetch_filing_summary_json(text, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_filing_summary_json(_applicationnumber text, _book_type integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_data_json JSON;
BEGIN
    SELECT json_agg(data_json) INTO v_data_json
    FROM (
        SELECT
            -- Property Details
            pm.propertyid AS property_id,
            di.districtnamee AS district,
            ta.taluknamee AS taluk,
            ho.hoblinamee AS hobli,
            vi.villagenamee AS index_ii_village,
            pt.propertytypename AS property_type,
            ps.eastboundary AS east,
            ps.westboundary AS west,
            ps.northboundary AS north,
            ps.southboundary AS south,
			--pnd.currentnumber AS present_property_no,

            -- Schedule Description Details
            COALESCE((SELECT array_to_json(array_agg(row_to_json(schedule_data)))
             FROM (
                SELECT
                    'Schedule: ' || ps.scheduletype AS schedule_type,
                    --'Survey Number: ' || pnd.survey_no AS property_details,
					COALESCE(
					    (SELECT string_agg(pnm.typenameenglish || ': ' || pnd.currentnumber, ', ')
					     FROM kaveri.propertynumberdetails pnd
					     JOIN kaveri.propertynotypemaster pnm 
					         ON pnd.currentpropertytypeid = pnm.propertytypeid
					     WHERE pnd.propertyid = pm.propertyid
					    ),
					    'No details available'
					) AS property_details,

                    pm.totalarea AS area,
                    mm.measurementnamee AS unit,
                    ps.description AS description,

                    -- Executants (partytypeid = 2)
                    (SELECT array_to_json(array_agg(row_to_json(party_data)))
                     FROM (
                        SELECT pi.firstname AS name
                        FROM kaveri.partyinfo pi
                        WHERE pi.applicationnumber = _applicationnumber AND pi.partytypeid = 2
						AND pi.propertyid = pm.propertyid
                        GROUP BY pi.firstname
                     ) party_data) AS executants,

				-- Claimants (partytypeid = 1) filtered by propertyId
                CASE 
                    WHEN _book_type = 3 THEN
                        (SELECT array_to_json(array_agg(row_to_json(party_data)))
                        FROM (
                            SELECT pi.firstname AS name
                            FROM kaveri.partyinfo pi
                            INNER JOIN kaveri.partyschedules ps 
                                ON pi.partyid = ps.partyid 
                                AND pi.propertyid = ps.propertyid
                            WHERE ps.applicationnumber = _applicationnumber 
                                AND ps.isdelete = false
                                AND pi.partytypeid = 1
                                AND ps.propertyid = pm.propertyid
                            GROUP BY pi.firstname
                        ) party_data)
                    WHEN _book_type = 6 THEN
                        (SELECT array_to_json(array_agg(row_to_json(party_data)))
                        FROM (
                            SELECT pi.firstname AS name
                            FROM kaveri.partyinfo pi
                            WHERE pi.applicationnumber = _applicationnumber AND pi.partytypeid = 1
                            --AND pi.propertyid = pm.propertyid
                            GROUP BY pi.firstname
                        ) party_data)
                END AS claimants

                FROM kaveri.propertyschedules ps
                LEFT JOIN kaveri.measurementmaster mm ON ps.unitid = mm.measurementcode
                LEFT JOIN kaveri.propertynumberdetails pnd ON ps.propertyid = pnd.propertyid
                WHERE ps.propertyid = pm.propertyid
                GROUP BY ps.scheduletype, pnd.survey_no, pm.totalarea, mm.measurementnamee, ps.description
             ) schedule_data
			), '[]') AS schedule_description_details,

		--Stamp Duty Details
		(SELECT array_to_json(array_agg(row_to_json(challan_data)))
             FROM (
			SELECT bc.challan_number AS challan_number,
			COALESCE(bc.amount_paid, '0') AS amount_paid,
			CASE 
            	WHEN bc.payment_type_id = '0' THEN 'No'
				WHEN bc.payment_type_id = '1' THEN 'Received'
            	WHEN bc.payment_type_id = '2' THEN 'E-Stamp'
            	WHEN bc.payment_type_id = '3' THEN 'K2-Challan'
            ELSE ''
        	END AS payment_type
			FROM kaveri.book1_part3_court bc WHERE bc.applicationnumber = _applicationnumber --AND bc.is_stamp_duty_paid = true
			GROUP BY bc.challan_number, bc.amount_paid, bc.payment_type_id ) challan_data) AS stamp_duty_details

        FROM kaveri.propertymaster pm
        LEFT JOIN kaveri.villagemaster vi ON pm.villagecode = vi.villagecode
        LEFT JOIN kaveri.hoblimaster ho ON vi.hoblicode = ho.hoblicode
        LEFT JOIN kaveri.talukmaster ta ON vi.talukcode = ta.talukcode
        LEFT JOIN kaveri.districtmaster di ON ta.districtcode = di.districtcode
        LEFT JOIN kaveri.propertytypemaster pt ON pm.propertytypeid = pt.propertytypeid
        LEFT JOIN kaveri.propertyschedules ps ON pm.propertyid = ps.propertyid
		LEFT JOIN kaveri.propertynumberdetails pnd ON pm.propertyid = pnd.propertyid
        WHERE pm.applicationnumber = _applicationnumber
        GROUP BY pm.propertyid, di.districtnamee, ta.taluknamee, ho.hoblinamee, vi.villagenamee, pt.propertytypename,
                 ps.eastboundary, ps.westboundary, ps.northboundary, ps.southboundary, pm.totalarea
    ) data_json;

    RETURN v_data_json;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_filing_summary_json(_applicationnumber text, _book_type integer) OWNER TO postgres;

--
-- Name: fn_fetch_final_regnumber(integer, character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_final_regnumber(_srocode integer, _applicationnumber character varying, OUT fn_fetch_final_regnumber text, OUT applicationtype text) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_regnumber text;
	v_serialnumber bigint;
	v_BOOKID bigint;
	v_regdocnumber text default null;
	v_shortname character varying(50);
	V_FINYEAR character varying(50);
	v_pname varchar;
BEGIN

V_FINYEAR:=(case when EXTRACT(MONTH FROM CURRENT_DATE) <= 3 then 
			to_CHAR(current_date + interval '-12 month', 'YYYY') || 
'-' || to_char(CURRENT_DATE, 'YY') else to_char(CURRENT_DATE, 'YYYY') 
			||'-' || to_char(current_date + interval '12 month', 'YY') end );

select dm.finalregistrationnumber, b.printablename, -- dm.bookid,
sro.shortnamee,coalesce(srl.finalserial,0)+1,sm.servicename 
into v_regdocnumber, v_pname, --v_BOOKID,
v_shortname,v_serialnumber,applicationtype
from kaveri.documentmaster dm 
inner join kaveri.sromaster  sro on (dm.srocode=sro.srocode) 
INNER join kaveri.applicantapplicationdetails appd on (dm.applicationnumber = appd.applicationnumber)
left join kaveri.servicesmaster sm on (appd.applicationtypeid = sm.serviceid)  
left join kaveri.sroserialmaster srl on (srl.srocode=dm.srocode and srl.bookid=dm.bookid and srl.finyear = V_FINYEAR)
join kaveri.booktypemaster b on dm.bookid = b.bookid -- Added on Decemeber 16, 2022, to fetch the printable name of the sro
where dm.applicationnumber = _applicationnumber and dm.srocode= _srocode limit 1;
			
-- v_regnumber:= v_shortname||'-'||v_BOOKID||'-'||to_char(v_serialnumber,'fm00000')||'-'||V_FINYEAR;
v_regnumber:= v_shortname||'-'||v_pname||'-'||to_char(v_serialnumber,'fm00000')||'-'||V_FINYEAR;

/* select COALESCE(sro.registrationdocserial,0)+1,shortnamee into v_serialnumber,v_shortname
 from  kaveri.sromaster sro where srocode = _srocode;
SELECT BOOKID INTO v_BOOKID FROM KAVERI.DOCUMENTMASTER WHERE applicationnumber = _applicationnumber LIMIT 1;
select dm.finalregistrationnumber,sm.servicename into v_regdocnumber,applicationtype from kaveri.documentmaster dm 
left join kaveri.applicantapplicationdetails appd on (dm.applicationnumber = appd.applicationnumber)
left join kaveri.servicesmaster sm on (appd.applicationtypeid = sm.serviceid)  
where dm.applicationnumber = _applicationnumber and dm.srocode= _srocode;*/

if (v_regdocnumber is null) then
update kaveri.documentmaster set finalregistrationnumber= v_regnumber,documentnumber=v_serialnumber,
registrationdatetime = CURRENT_TIMEstamp, isregistrationcompleted = true
where applicationnumber = _applicationnumber and srocode= _srocode
and finalregistrationnumber is null;
fn_fetch_final_regnumber:=v_regnumber;
else 
fn_fetch_final_regnumber:=v_regdocnumber;
end if;

END;
$$;


ALTER FUNCTION kaveri.fn_fetch_final_regnumber(_srocode integer, _applicationnumber character varying, OUT fn_fetch_final_regnumber text, OUT applicationtype text) OWNER TO csgadmin;

--
-- Name: fn_fetch_final_regnumber_fruits(integer, character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_final_regnumber_fruits(_srocode integer, _applicationnumber character varying, OUT fn_fetch_final_regnumber_fruits text, OUT applicationtype text) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_regnumber text;
	v_serialnumber bigint;
	v_BOOKID bigint;
	v_regdocnumber text default null;
	v_cnt bigint;
	v_shortname character varying(50);
	V_FINYEAR character varying(50);
	v_pname varchar;
	v_consideration_amt bigint;
BEGIN

select sum(consideration) into v_consideration_amt from kaveri.propertymaster p 
where p.applicationnumber = _applicationnumber 
group by p.applicationnumber;

select bookid into v_BOOKID FROM kaveri.documentmaster d where applicationnumber = _applicationnumber;

if(v_consideration_amt <= 300000) then --and _formiiidata != '' ) then
	update kaveri.fruits_data_recv_details set applicationstatus = 1
	where applicationnumber = _applicationnumber;
/*else 
	update kaveri.fruits_data_recv_details f set f.applicationstatus = 2
	where applicationnumber = _applicationnumber;*/
end if;
	
select --COALESCE(sro.registrationdocserial,0)+1,
	COALESCE(srl.finalserial,0)+1,
	shortnamee into v_serialnumber,v_shortname
from kaveri.sromaster s
join kaveri.sroserialmaster srl on srl.srocode = s.srocode 
where s.srocode = _srocode and srl.bookid = v_BOOKID;

--SELECT BOOKID INTO v_BOOKID FROM KAVERI.DOCUMENTMASTER WHERE applicationnumber = _applicationnumber LIMIT 1;
select b.printablename into v_pname from kaveri.booktypemaster b where bookid = v_BOOKID;
-- (select bookid FROM kaveri.documentmaster d where applicationnumber = _applicationnumber limit 1);


V_FINYEAR:=(case when EXTRACT(MONTH FROM CURRENT_DATE) <= 3 then 
			to_CHAR(current_date + interval '-12 month', 'YYYY') || 
'-' || to_char(CURRENT_DATE, 'YY') else to_char(CURRENT_DATE, 'YYYY') 
			||'-' || to_char(current_date + interval '12 month', 'YY') end );
			
--v_regnumber:= v_shortname||'-'||v_BOOKID||'-Part-IV-'||to_char(v_serialnumber,'fm00000')||'-'||V_FINYEAR;
v_regnumber:= v_shortname||'-'||v_pname||'-'||to_char(v_serialnumber,'fm00000')||'-'||V_FINYEAR;

select dm.finalregistrationnumber,sm.servicename into v_regdocnumber,applicationtype from kaveri.documentmaster dm 
left join kaveri.applicantapplicationdetails appd on (dm.applicationnumber = appd.applicationnumber)
left join kaveri.servicesmaster sm on (appd.applicationtypeid = sm.serviceid)  
where dm.applicationnumber = _applicationnumber;-- and dm.srocode= _srocode;

if (v_regdocnumber is null) then
	update kaveri.documentmaster set finalregistrationnumber= v_regnumber,
	documentnumber=v_serialnumber, registrationdatetime = CURRENT_TIMEstamp,
	isregistrationcompleted = true
	where applicationnumber = _applicationnumber --and srocode= _srocode
	and finalregistrationnumber is null;
	fn_fetch_final_regnumber_fruits:=v_regnumber;

	/*update kaveri.sroserialmaster set finalserial = v_serialnumber
	where s.srocode = _srocode and srl.bookid = v_BOOKID;*/

	update kaveri.applicantapplicationdetails set currentstatus = 'CD120'
	where applicationnumber = _applicationnumber;
else 
	fn_fetch_final_regnumber_fruits:=v_regdocnumber;
end if;

END;
$$;


ALTER FUNCTION kaveri.fn_fetch_final_regnumber_fruits(_srocode integer, _applicationnumber character varying, OUT fn_fetch_final_regnumber_fruits text, OUT applicationtype text) OWNER TO csgadmin;

--
-- Name: fn_fetch_final_regnumber_rule_17_3(integer, character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_final_regnumber_rule_17_3(_srocode integer, _applicationnumber character varying, OUT fn_fetch_final_regnumber text, OUT applicationtype text) RETURNS record
    LANGUAGE plpgsql
    AS $$
	DECLARE
		v_regnumber text;
		v_serialnumber bigint;
		v_BOOKID bigint;
		v_regdocnumber text default null;
		v_shortname character varying(50);
		V_FINYEAR character varying(50);
		v_pname varchar;
	BEGIN
	
	V_FINYEAR:=(case when EXTRACT(MONTH FROM CURRENT_DATE) <= 3 then 
				to_CHAR(current_date + interval '-12 month', 'YYYY') || 
	'-' || to_char(CURRENT_DATE, 'YY') else to_char(CURRENT_DATE, 'YYYY') 
				||'-' || to_char(current_date + interval '12 month', 'YY') end );
	
	select  dm.finalregistrationnumber, b.printablename,  dm.bookid,
	sro.shortnamee--,sm.servicename 
	into v_regdocnumber, v_pname, v_BOOKID,
	v_shortname--,applicationtype
	from kaveri.documentmaster dm 
	inner join kaveri.sromaster  sro on (dm.srocode=sro.srocode) 
	--INNER join kaveri.applicantapplicationdetails appd on (dm.applicationnumber = appd.applicationnumber)
	--left join kaveri.servicesmaster sm on (appd.applicationtypeid = sm.serviceid)  
	--left join kaveri.sroserialmaster srl on (srl.srocode=dm.srocode and srl.bookid=dm.bookid and srl.finyear = V_FINYEAR)
	join kaveri.booktypemaster b on dm.bookid = b.bookid -- Added on Decemeber 16, 2022, to fetch the printable name of the sro
	where dm.applicationnumber = _applicationnumber and dm.srocode= _srocode limit 1;
	
	v_serialnumber:=0;
		
	update kaveri.sroserialmaster set finalserial = (coalesce(finalserial,0)+1)::bigint
	where srocode= _srocode and bookid=v_BOOKID and finyear=V_FINYEAR 
	returning finalserial into v_serialnumber;	
	
	if(v_serialnumber=0)
	 then 
	
	 	raise EXCEPTION  'Serial Number could not be generated(%)',v_BOOKID; --EXCEPTION 'Courtorder --> %', v_ordernumber
							--USING HINT = 'Please check property data';
	 	
	end if;
		
	
	
	--select  coalesce(srl.finalserial,0)+1 into v_serialnumber 
	--from kaveri.sroserialmaster srl where srocode=_srocode and bookid=v_BOOKID and finyear=V_FINYEAR  for update;
	
	--select v_serialnumber from (select coalesce(srl.finalserial,0)+1
	--into v_serialnumber
	--from kaveri.documentmaster dm 
	--inner join kaveri.sromaster  sro on (dm.srocode=sro.srocode) 
	--INNER join kaveri.applicantapplicationdetails appd on (dm.applicationnumber = appd.applicationnumber)
	--left join kaveri.servicesmaster sm on (appd.applicationtypeid = sm.serviceid)  
	--left join kaveri.sroserialmaster srl on (srl.srocode=dm.srocode and srl.bookid=dm.bookid and srl.finyear = V_FINYEAR)
	--join kaveri.booktypemaster b on dm.bookid = b.bookid -- Added on Decemeber 16, 2022, to fetch the printable name of the sro
	--where dm.applicationnumber = _applicationnumber and dm.srocode= _srocode limit 1) for update;
	
	-- v_regnumber:= v_shortname||'-'||v_BOOKID||'-'||to_char(v_serialnumber,'fm00000')||'-'||V_FINYEAR;
	v_regnumber:= v_shortname||'-'||v_pname||'-'||to_char(v_serialnumber,'fm00000')||'-'||V_FINYEAR;
	
	/* select COALESCE(sro.registrationdocserial,0)+1,shortnamee into v_serialnumber,v_shortname
	 from  kaveri.sromaster sro where srocode = _srocode;
	SELECT BOOKID INTO v_BOOKID FROM KAVERI.DOCUMENTMASTER WHERE applicationnumber = _applicationnumber LIMIT 1;
	select dm.finalregistrationnumber,sm.servicename into v_regdocnumber,applicationtype from kaveri.documentmaster dm 
	left join kaveri.applicantapplicationdetails appd on (dm.applicationnumber = appd.applicationnumber)
	left join kaveri.servicesmaster sm on (appd.applicationtypeid = sm.serviceid)  
	where dm.applicationnumber = _applicationnumber and dm.srocode= _srocode;*/
	
	if (v_regdocnumber is null) then
	update kaveri.documentmaster set finalregistrationnumber= v_regnumber,documentnumber=v_serialnumber,
	registrationdatetime = CURRENT_TIMEstamp, isregistrationcompleted = true
	where applicationnumber = _applicationnumber and srocode= _srocode
	and finalregistrationnumber is null;
	fn_fetch_final_regnumber:=v_regnumber;
	
	else 
	fn_fetch_final_regnumber:=v_regdocnumber;
	end if;
	
	END;
	$$;


ALTER FUNCTION kaveri.fn_fetch_final_regnumber_rule_17_3(_srocode integer, _applicationnumber character varying, OUT fn_fetch_final_regnumber text, OUT applicationtype text) OWNER TO postgres;

--
-- Name: fn_fetch_functiondefination(); Type: PROCEDURE; Schema: kaveri; Owner: postgres
--

CREATE PROCEDURE kaveri.fn_fetch_functiondefination()
    LANGUAGE plpgsql
    AS $$

declare
v_routinname record;
v_data1 text;
v_text text;
begin

for v_routinname in (select distinct routine_name from information_schema.routines where routine_schema = 'kaveri' and routine_definition like '%fn%' order by routine_name)
loop
	
	select concat('kaveri.',v_routinname.routine_name) into v_data1 ;

	select pg_get_functiondef(v_data1::regproc)::text into v_text;

	insert into kaveri.function_def 
	--select replace(v_text,v_routinname.routine_name,concat(v_routinname.routine_name,'_anl'));
	select v_text;

end loop;
end;
$$;


ALTER PROCEDURE kaveri.fn_fetch_functiondefination() OWNER TO postgres;

--
-- Name: fn_fetch_getvillageasync(bigint, boolean); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_getvillageasync(p_hoblicode bigint, p_showuda boolean DEFAULT false) RETURNS TABLE(ulbcode integer, villagecode bigint, villagenamek character varying, villagenamee character varying, srocode integer, bhoomitalukcode integer, bhoomidistrictcode integer, bhoomivillagecode integer, isurban boolean)
    LANGUAGE plpgsql
    AS $$

BEGIN
if(p_showuda=false) THEN
			Return query
			Select  distinct
			c.ulbcode,
			--null::int as ulbcode,
			a.villagecode,a.villagenamek,a.villagenamee,
			a.srocode as srocode,bm.bhoomitalukcode,bm.BhoomiDistrictCode,
			bm.bhoomivillagecode,a.isurban 
			From kaveri.villagemaster a
			left outer join kaveri.ulbmapping b on a.srocode = b.srocode
			left outer join kaveri.ulbmaster c on c.ulbcode = b.ulbcode
			left outer join kaveri.bhoomimappingdetails bm on bm.kaverivillagecode = a.villagecode 
			where a.hoblicode=p_hoblicode 
			and a.isactive=true --and a.villagecode not in (14798) --raghavendra:Request for remapping of "Lakshmipura" Index Village to BBMP eAasthi
			order by villagenamee asc;
			
else
	-- village for RLB
		return query
		Select distinct 
			--c.ulbcode,
		null::int as ulbcode,
		a.villagecode,a.villagenamek,a.villagenamee,a.srocode as srocode,
		bm.bhoomitalukcode,bm.BhoomiDistrictCode,bm.bhoomivillagecode,a.isurban 
		From kaveri.villagemaster a
		left outer join kaveri.ulbmapping b on a.srocode = b.srocode 
		left outer join kaveri.ulbmaster c on c.ulbcode = b.ulbcode
		left outer join kaveri.bhoomimappingdetails bm on bm.kaverivillagecode = a.villagecode 
		where 
		a.hoblicode=p_hoblicode and
		a.villagecode 
		in (select distinct v.villagecode  from kaveri.villageurbanmapping v where deptid =10   -- village for UDA

		except 

		select distinct mp.villagecode  from kaveri.villagewardmapping  mp  --village for bbmp
	) and a.isactive=true;
END IF;

END;
$$;


ALTER FUNCTION kaveri.fn_fetch_getvillageasync(p_hoblicode bigint, p_showuda boolean) OWNER TO postgres;

--
-- Name: fn_fetch_grouped_by_propertyremark(character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_grouped_by_propertyremark(_application_no character varying) RETURNS TABLE(propertyid bigint, applicationno character varying, groupeddetails jsonb)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        r.property_id as PropertyId,
		_application_no as ApplicationNo,
        jsonb_agg(jsonb_build_object(
            'verification_id', r.verification_id,
            'application_no', r.application_no,
            'prop_details_remarks_fda', r.prop_details_remarks_fda,
            'prop_details_verify_fda', r.prop_details_verify_fda,
            'bound_details_remarks_fda', r.bound_details_remarks_fda,
            'bound_details_verify_fda', r.bound_details_verify_fda,
            'sd_details_remarks_fda', r.sd_details_remarks_fda,
            'sd_details_verify_fda', r.sd_details_verify_fda,
            'party_details_remarks_fda', r.party_details_remarks_fda,
            'party_details_verify_fda', r.party_details_verify_fda,
            'prop_details_remarks_sro', r.prop_details_remarks_sro,
            'prop_details_verify_sro', r.prop_details_verify_sro,
            'bound_details_remarks_sro', r.bound_details_remarks_sro,
            'bound_details_verify_sro', r.bound_details_verify_sro,
            'sd_details_remarks_sro', r.sd_details_remarks_sro,
            'sd_details_verify_sro', r.sd_details_verify_sro,
            'party_details_remarks_sro', r.party_details_remarks_sro,
            'party_details_verify_sro', r.party_details_verify_sro
        )) AS GroupedDetails
    FROM kaveri.tbl_book1_part3_remarks r  -- Use alias 'r' for the table
    WHERE r.application_no = _application_no
    GROUP BY r.property_id;  -- Ensure alias is used here as well
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_grouped_by_propertyremark(_application_no character varying) OWNER TO postgres;

--
-- Name: fn_fetch_gscno(); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_gscno() RETURNS TABLE(applicationnumber character varying, gscno character varying, srocode integer)
    LANGUAGE plpgsql
    AS $$
begin
return query
select d.applicationnumber,d.gscno,d.srocode
from kaveri.documentmaster d where d.isregistrationcompleted =true and d.gscno is not null 
union all 
select ca.applicationnumber,ca.gscno,ca.kaverisrocode from kaveri.cc_applicationdetails ca 
inner join kaveri.applicantapplicationdetails a 
on a.applicationnumber = ca.applicationnumber where ca.gscno is not null 
and a.currentstatus='CC109' and ca.gscno is not null 
union all 
select ea.applicationnumber,ea.gscno,ea.kaverisrocode  from kaveri.ec_applicationdetails ea 
inner join kaveri.applicantapplicationdetails aa on aa.applicationnumber=ea.applicationnumber 
where ea.gscno is not null and aa.currentstatus='CE110' and ea.gscno is not null;
end;
$$;


ALTER FUNCTION kaveri.fn_fetch_gscno() OWNER TO csgadmin;

--
-- Name: fn_fetch_holidays_for_apps_scrutiny(date); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_holidays_for_apps_scrutiny(today_date date) RETURNS TABLE(curr_date date, day_name text, holiday_details text)
    LANGUAGE plpgsql
    AS $$
	begin
		return query 

		
( with all_dates as (
select
	generate_series(
           today_date,
	-- start date (current date)
           today_date,
	-- end date (adjust as needed)
           interval '1 day'
	-- interval between dates (adjust as needed)
       )::date as cur_date
)
select
				cur_date,
				cast((case
					when extract(DOW from cur_date) = 0 then 'Sunday'
					when extract(DOW from cur_date) = 6 and extract(day from cur_date) <= 7 then 'First Saturday'
					when extract(DOW from cur_date) = 6 and extract(day from cur_date) > 7 and extract(day from cur_date) <= 14 then 'Second Saturday' 
					when extract(DOW from cur_date) = 6 and extract(day from cur_date) > 14 then 'Fourth Saturday' end) as text) as day_type, 
				cast(to_char (cur_date::date, 'Day') as text) as holiday_name
	from
		all_dates
	where extract(ISODOW from cur_date) = 7 -- Sunday
		or (extract(ISODOW from cur_date) = 6
		and (extract(day from cur_date)::integer - 1) / 7 + 1 in (2, 4))) -- Second and Fourth Saturday
	union all
	
	  select
		holidaydate::date as cur_date,
		to_char (holidaydate::date,
		'Day') as day_of_month,
		cast(holidayname as text) as holiday_name
	from
		kaveri.holidaymaster
	where
		holidaydate::date = today_date;
		
	END;
$$;


ALTER FUNCTION kaveri.fn_fetch_holidays_for_apps_scrutiny(today_date date) OWNER TO postgres;

--
-- Name: fn_fetch_igrdashboard(timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_igrdashboard(_fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$

 

DECLARE 
PageOffset INTEGER := 0;
v_data_json json;
v_fromdate date;
v_todate date;

BEGIN	 
PageOffset := ((pagenumber - 1) * pagesize);
v_fromdate :=_fromdate;
v_todate :=_todate;
	 
select array_to_json(array_agg(row_to_json(dashboard)))   into v_data_json 

from (select distinct to_char(current_date,'DD-MM-YYYY') as current_date, 
concat(to_char(v_fromdate,'DD-MM-YYYY'),' - ',to_char(v_todate,'DD-MM-YYYY'))as date_range, d.districtcode,d.districtnamee,  

count(distinct case when a.currentstatus in ('CD102') then a.applicationnumber else null end) as Received_from_Citizen,  

count(distinct case when a.currentstatus in ('CD103') then a.applicationnumber else null end) as Allocated_to_SDA_FDA,  

count(distinct case when a.currentstatus in ('CD104') then a.applicationnumber else null end) as Received_from_SDA_FDA,  

count(distinct case when a.currentstatus in ('CD106') then a.applicationnumber else null end) as Sent_to_citizen_for_confirmation,  

count(distinct case when a.currentstatus in ('CD108') then a.applicationnumber else null end) as Received_from_citizen_after_confirmation,  

count(distinct case when a.currentstatus in ('CD110') then a.applicationnumber else null end) as Allocated_to_DEO_for_Biometric,  

count(distinct case when a.currentstatus in ('CD111') then a.applicationnumber else null end) as Received_from_DEO_after_Biometric_with_Summary,  

count(distinct case when a.currentstatus in ('CD112') then a.applicationnumber else null end) as Allocated_to_DEO_for_Printing_with_scanning,  

count(distinct case when a.currentstatus in ('CD112') then a.applicationnumber else null end) as Allocated_to_DEO_for_Printing_with_scanning,	  

count(distinct case when a.currentstatus in ('CD115') then a.applicationnumber else null end) as Receivedfordigisign,  

count(distinct case when a.currentstatus in ('CD116') then a.applicationnumber else null end) as Sent_to_FDA_SDA_for_Acknowledgement  

from kaveri.applicantapplicationdetails a  

join kaveri.sromaster s on s.srocode = a.srocode  

join kaveri.districtmaster d on d.districtcode = s.districtcode  

where a.applicationtypeid in (1,2) 

and a.applicationstartdate::date >=_fromdate and a.applicationstartdate::date <=_todate

group by  d.districtcode,d.districtnamee
order by d.districtnamee asc)as dashboard
OFFSET PageOffset
FETCH NEXT pagesize ROWS ONLY;

return v_data_json; 

END; 

$$;


ALTER FUNCTION kaveri.fn_fetch_igrdashboard(_fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_fetch_igrdashboard_sro(integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_igrdashboard_sro(_districtcode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
v_data_json json;

BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	
	select array_to_json(array_agg(row_to_json(dashboard)))  into v_data_json

from (select distinct to_char(current_date,'DD-MM-YYYY')as current_date , s.sronamee,  

sum(case when a.currentstatus in ('CD102') then 1 else 0 end) as Received_from_Citizen,  

sum(case when a.currentstatus in ('CD103') then 1 else 0 end) as Allocated_to_SDA_FDA,  

sum(case when a.currentstatus in ('CD104') then 1 else 0 end) as Received_from_SDA_FDA,  

sum(case when a.currentstatus in ('CD106') then 1 else 0 end) as Sent_to_citizen_for_confirmation,  

sum(case when a.currentstatus in ('CD108') then 1 else 0 end) as Received_from_citizen_after_confirmation,  

sum(case when a.currentstatus in ('CD110') then 1 else 0 end) as Allocated_to_DEO_for_Biometric,  

sum(case when a.currentstatus in ('CD111') then 1 else 0 end) as Received_from_DEO_after_Biometric_with_Summary,  

sum(case when a.currentstatus in ('CD112') then 1 else 0 end) as Allocated_to_DEO_for_Printing_with_scanning,  

sum(case when a.currentstatus in ('CD112') then 1 else 0 end) as Allocated_to_DEO_for_Printing_with_scanning,	  

sum(case when a.currentstatus in ('CD115') then 1 else 0 end) as Receivedfordigisign,  

sum(case when a.currentstatus in ('CD116') then 1 else 0 end) as Sent_to_FDA_SDA_for_Acknowledgement  

from kaveri.applicantapplicationdetails a  
join kaveri.sromaster s on s.srocode = a.srocode  and s.districtcode =_districtcode
join kaveri.districtmaster d on d.districtcode = s.districtcode  
where a.applicationtypeid in (1,2) 
	  
	  and a.applicationstartdate::date >=_fromdate and a.applicationstartdate::date <=_todate 

group by s.sronamee
order by s.sronamee)as dashboard 
OFFSET PageOffset
FETCH NEXT pagesize ROWS ONLY;
/*update kaveri.marriageregistration set   numberofcopy=_numberofcopy,
 declarationdate=current_timestamp,
 declarationplace=_declarationplace where applicationnumber = _applicationnumber;*/
return v_data_json;

END;
$$;


ALTER FUNCTION kaveri.fn_fetch_igrdashboard_sro(_districtcode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_fetch_indexii_final_registration(character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_indexii_final_registration(_finalregistrationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
BEGIN
select row_to_json(data_json) into v_data_json from ( 
select array_to_json(array_agg(row_to_json(app_json)))
	
--select row_to_json(app_json) into v_data_json
from ( select 
 pm.applicationnumber,
 pm.propertyid,
 pm.marketvalue,
 pm.consideration,
 ra.articlenamee,
 pm.eastboundary AS east,
 pm.westboundary AS west,
 pm.northboundary AS north,
 pm.southboundary AS south,
 pm.totalarea AS area,
 pm.villagecode,
 v.villagenamee,
 v.hoblicode,
 --h.hoblinamee,
 --r.referencetext,
 (select referencetext from kaveri.referencemaster where documentid=dm.documentid order by lstupddate desc limit 1),
( select array_to_json(array_agg(row_to_json(propertynodetails)))
      from ( select 
pn.currentpropertytypeid,
 pn.currentnumber,
 pn.currentnumber AS aptno_new,
 pn.oldnumber AS oldno
from  kaveri.propertynumberdetails pn WHERE
			pm.propertyid = pn.propertyid  
			and (pn_src.srocode,pn_src.currentpropertytypeid, pn_src.currentnumber) = 
			(pn.srocode,pn.currentpropertytypeid, pn.currentnumber)
  )propertynodetails) as propnumberdetails,
( select array_to_json(array_agg(row_to_json(propertyschedules)))
      from ( 
--Code Begins for Property Schedules
select 
ps.easttowest,
 ps.northtosouth,
 case when pas.propertyid is not null then
 case when ps.description is not null and  ps.description<>'' then  
 concat(ps.description, ' Allotted to: ', string_agg(pin.firstname || pin.middlename || pin.lastname,' & '))
 else concat('District: ', d.districtnamee,', ' , 'Taluk: ', tm.taluknamee,', ' , 'Village: ',v2.villagenamee,', ', '', 'Survey No: ',p.survey_no,', ', 'Hissa No: ', p.hissa_no,', ', 'BoundaryDetails: [North: ',ps.northboundary,', '
 , 'East: ',ps.eastboundary,', '
 , 'West: ', ps.westboundary,', ', 'South: ', ps.southboundary,', ','] measuring ',ps.totalarea,' acre') end 
else
ps.description end as
 description
from kaveri.propertyschedules ps 
left join kaveri.propertynumberdetails  p on ps.propertyid=p.propertyid 
left join kaveri.propertymaster pp on ps.propertyid=pp.propertyid 
left outer join kaveri.partyschedules pas on ps.propertyid=pas.propertyid 
left outer join kaveri.partyinfo pin on pas.partyid=pin.partyid 
left join kaveri.villagemaster v2 on pp.villagecode=v2.villagecode 
left join kaveri.talukmaster tm on v2.talukcode =tm.talukcode 
left join kaveri.districtmaster d on tm.districtcode =d.districtcode 
where ps.srocode = pm.srocode and ps.propertyid = pm.propertyid
		   group by ps.easttowest, ps.northtosouth,ps.description,pas.propertyid,d.districtnamee,tm.taluknamee,v2.villagenamee,
		   p.survey_no,p.hissa_no,ps.northboundary,ps.eastboundary,ps.westboundary,ps.southboundary,ps.totalarea
--Code Ends for Property Schedules	  
)propertyschedules)as propertyschedules,
( select array_to_json(array_agg(row_to_json(partydetails)))
      from ( select distinct pi.partyid,
 (
        CASE
            WHEN pi.partytypeid = 1 THEN concat(pi.firstname,' ', pi.middlename,' ', pi.lastname)
            ELSE NULL::text
        END::text) AS claimant,
 (
        CASE
            WHEN pi.partytypeid = 2 THEN concat(pi.firstname,' ', pi.middlename,' ', pi.lastname)
            ELSE NULL::text
        END::text) AS executant,
		     pi.address from kaveri.partyinfo pi 
			left outer join kaveri.partyschedules ps on pi.partyid=ps.partyid
			where pi.srocode = dm.srocode AND pi.documentid = dm.documentid
--group by pi.partyid,pi.address,ps.propertyid
)partydetails) as partydetails,
( select array_to_json(array_agg(row_to_json(documentdetails)))
   from (select dm.documentid,
    dm.srocode,
    dm.registrationdatetime::date AS executiondate,
    dm.cdnumber,
    dm.pagecount,
    dm.finalregistrationnumber AS documentreference)documentdetails)as documentdetails, 
	(select note_enteredpart from kaveri.dec_drpndnote where propertyid=pm.propertyid order by insertdatetime desc limit 1) as correctionnote
     from 
	  kaveri.documentmaster dm left outer join
	  kaveri.propertymaster pm ON pm.documentid = dm.documentid and Isregistrationcompleted=true
	  inner join kaveri.villagemaster v on pm.villagecode = v.villagecode --reverting to revenue village code instead of v.bhoomivillagecode 
	  inner join kaveri.propertynumberdetails pn_src on pm.propertyid = pn_src.propertyid AND pn_src.srocode = v.srocode
      --inner JOIN kaveri.hoblimaster h ON v.hoblicode = h.hoblicode --Commenting hoblimaster join as FRUITS is using dummy data
      left JOIN kaveri.registrationarticles ra ON ra.regarticlecode = dm.regarticlecode
      where  dm.finalregistrationnumber =_finalregistrationnumber
--) app_json;
)  app_json ) data_json;
return v_data_json;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_indexii_final_registration(_finalregistrationnumber character varying) OWNER TO csgadmin;

--
-- Name: fn_fetch_indexii_final_registration_for_correctionnote(character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_indexii_final_registration_for_correctionnote(_finalregistrationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
BEGIN
select row_to_json(data_json) into v_data_json from ( 
select array_to_json(array_agg(row_to_json(app_json)))
	
--select row_to_json(app_json) into v_data_json
from ( select 
 pm.applicationnumber,
 pm.propertyid,
 pm.marketvalue,
 pm.consideration,
 ra.articlenamee,
 pm.eastboundary AS east,
 pm.westboundary AS west,
 pm.northboundary AS north,
 pm.southboundary AS south,
 pm.totalarea AS area,
 pm.villagecode,
 v.villagenamee,
 v.hoblicode,
 --h.hoblinamee,
 --r.referencetext,
 (select referencetext from kaveri.referencemaster where documentid=dm.documentid order by lstupddate desc limit 1),
( select array_to_json(array_agg(row_to_json(propertynodetails)))
      from ( select 
pn.currentpropertytypeid,
 pn.currentnumber,
 pn.currentnumber AS aptno_new,
 pn.oldnumber AS oldno
from  kaveri.propertynumberdetails pn WHERE
			pm.propertyid = pn.propertyid  
			and (pn_src.srocode,pn_src.currentpropertytypeid, pn_src.currentnumber) = 
			(pn.srocode,pn.currentpropertytypeid, pn.currentnumber)
  )propertynodetails) as propnumberdetails,
( select array_to_json(array_agg(row_to_json(propertyschedules)))
      from ( 
--Code Begins for Property Schedules
select 
ps.easttowest,
 ps.northtosouth,
 case when pas.propertyid is not null then
 concat(ps.description, ' Allotted to: ', string_agg(pin.firstname || pin.middlename || pin.lastname,' & ')) 
else
ps.description end as
 description
from kaveri.propertyschedules ps left outer join kaveri.partyschedules pas
on ps.propertyid=pas.propertyid left outer join kaveri.partyinfo pin on 
pas.partyid=pin.partyid where ps.srocode = pm.srocode and ps.propertyid = pm.propertyid
		   group by ps.easttowest, ps.northtosouth,ps.description,pas.propertyid
--Code Ends for Property Schedules	  
)propertyschedules)as propertyschedules,
( select array_to_json(array_agg(row_to_json(partydetails)))
      from ( select distinct pi.partyid,
 (
        CASE
            WHEN pi.partytypeid = 1 or ps.propertyid is not null THEN concat(pi.firstname, pi.middlename, pi.lastname)
            ELSE NULL::text
        END::text) AS claimant,
 (
        CASE
            WHEN pi.partytypeid = 2 THEN concat(pi.firstname, pi.middlename, pi.lastname)
            ELSE NULL::text
        END::text) AS executant,
		     pi.address from kaveri.partyinfo pi 
			left outer join kaveri.partyschedules ps on pi.partyid=ps.partyid
			where pi.srocode = dm.srocode AND pi.documentid = dm.documentid
--group by pi.partyid,pi.address,ps.propertyid
)partydetails) as partydetails,
( select array_to_json(array_agg(row_to_json(documentdetails)))
   from (select dm.documentid,
    dm.srocode,
    dm.registrationdatetime AS executiondate,
    dm.cdnumber,
    dm.pagecount,
    dm.finalregistrationnumber AS documentreference)documentdetails)as documentdetails, 
(select concat(note_enteredpart, (SELECT 
            ((((' as per the order number '::text || o.ordernumber::text) || ' dated '::text) || to_char(o.orderdate, 'dd-mm-yyyy'::text)) || ' by District Registrar '::text) || d.districtnamee::text AS col1
           FROM kaveri.propertymaster pc
             LEFT JOIN kaveri.documentmaster dm ON pc.documentid = dm.documentid
             LEFT JOIN kaveri.dec_drordermaster o ON dm.documentid = o.documentid
             LEFT JOIN kaveri.districtmaster d ON o.districtcode = d.districtcode
									where pc.propertyid=pm.propertyid limit 1)) as note_enteredpart from kaveri.dec_drpndnote where propertyid=pm.propertyid order by insertdatetime desc limit 1) as correctionnote
     from 
	  kaveri.documentmaster dm left outer join
	  kaveri.propertymaster pm ON pm.documentid = dm.documentid and Isregistrationcompleted=true
	  inner join kaveri.villagemaster v on pm.villagecode = v.villagecode 
	  inner join kaveri.propertynumberdetails pn_src on pm.propertyid = pn_src.propertyid AND pn_src.srocode = v.srocode
      --inner JOIN kaveri.hoblimaster h ON v.hoblicode = h.hoblicode --Commenting hoblimaster join as FRUITS is using dummy data
      left JOIN kaveri.registrationarticles ra ON ra.regarticlecode = dm.regarticlecode
      where  dm.finalregistrationnumber =_finalregistrationnumber
--) app_json;
)  app_json ) data_json;
return v_data_json;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_indexii_final_registration_for_correctionnote(_finalregistrationnumber character varying) OWNER TO csgadmin;

--
-- Name: fn_fetch_insert_documentmaster_pending_regis(character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_insert_documentmaster_pending_regis(_applicationnumber character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$

declare
v_applicationnumber varchar;
v_regarticlecode int;
v_stamp5datetime timestamp without time zone;
v_bookid int;
v_remarks varchar;
v_minutedate timestamp without time zone;
v_pendingdocumentnumber varchar;
v_sronoofscanpages int;
v_docid bigint;
v_cnt bigint;
v_srocode int;

begin 
	v_applicationnumber := _applicationnumber;

	select count(*) into v_cnt from kaveri.documentmaster where applicationnumber = _applicationnumber;

	if v_cnt = 0 then

	select p.applicationnumber,
		p.srocode ,
		p.regarticlecode,
		LOCALTIMESTAMP as stamp5datetime,
		r.bookid,
		md.remarks,
		md.minutedate,
		md.pendingregistrationnumber,
		p.sronoofscanpages into v_applicationnumber,v_srocode,v_regarticlecode,v_stamp5datetime,
		v_bookid,v_remarks,v_minutedate,v_pendingdocumentnumber,v_sronoofscanpages
	from kaveri.propertymaster p
	join kaveri.minutebook_data md on md.applicationnumber = p.applicationnumber 
	join kaveri.registrationarticles r on p.regarticlecode = r.regarticlecode 
	where p.applicationnumber  =_applicationnumber limit 1;


	select * into v_docid from kaveri.fn_insert_documentmaster_pending_regis(v_applicationnumber,null,v_srocode,v_regarticlecode,v_stamp5datetime,v_bookid,v_remarks,v_minutedate,v_pendingdocumentnumber,v_sronoofscanpages);
	
	else
	
	select documentid into v_docid from kaveri.documentmaster d where applicationnumber = _applicationnumber;

end if;
return v_docid;
end
$$;


ALTER FUNCTION kaveri.fn_fetch_insert_documentmaster_pending_regis(_applicationnumber character varying) OWNER TO csgadmin;

--
-- Name: fn_fetch_insert_documentmaster_pending_regis(character varying, integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_insert_documentmaster_pending_regis(_applicationnumber character varying, _srocode integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$

declare
v_applicationnumber varchar;
v_regarticlecode int;
v_stamp5datetime timestamp without time zone;
v_bookid int;
v_remarks varchar;
v_minutedate timestamp without time zone;
v_pendingdocumentnumber varchar;
v_noofscanpages int;
v_docid bigint;
v_cnt bigint;
--v_srocode int;

begin 
	v_applicationnumber := _applicationnumber;

	select count(*) into v_cnt from kaveri.documentmaster where applicationnumber = _applicationnumber and srocode = _srocode;

	if v_cnt = 0 then

	select p.applicationnumber,
		--p.srocode ,
		p.regarticlecode,
		LOCALTIMESTAMP as stamp5datetime,
		r.bookid,
		md.remarks,
		md.minutedate,
		md.pendingregistrationnumber,
		p.noofscanpages into v_applicationnumber,v_regarticlecode,v_stamp5datetime,
		v_bookid,v_remarks,v_minutedate,v_pendingdocumentnumber,v_noofscanpages
	from kaveri.propertymaster p
	join kaveri.minutebook_data md on md.applicationnumber = p.applicationnumber 
	join kaveri.registrationarticles r on p.regarticlecode = r.regarticlecode 
	where p.applicationnumber  =_applicationnumber limit 1;


	select * into v_docid from kaveri.fn_insert_documentmaster_pending_regis(v_applicationnumber,null,_srocode,v_regarticlecode,v_stamp5datetime,v_bookid,v_remarks,v_minutedate,v_pendingdocumentnumber,v_noofscanpages);
	
	else
	
	select documentid into v_docid from kaveri.documentmaster d where applicationnumber = _applicationnumber and srocode = _srocode;

end if;
return v_docid;
end
$$;


