--
-- Name: fn_fetch_isstepaccessallowed_1(integer, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_isstepaccessallowed_1(_srocode integer, _stepcode integer, _stepcodedesigntypid integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$

declare
v_flag boolean;
v_cnt int;
v_prelunchstrtime time;
v_prelunchendtime time;
v_postlunchstrtime time;
v_postlunchendtime time;
v_additionslotstrtime time;
v_additionslotendtime time;

begin
	select count(*) into v_cnt from kaveri.departmentaccesslotmaster
	where srocode = _srocode and stepcode = _stepcode and stepcodedesigntypid = _stepcodedesigntypid;
	
	select prelunchstrtime,prelunchendtime,postlunchstrtime,postlunchendtime,additionslotstrtime,additionslotendtime 
	into v_prelunchstrtime,v_prelunchendtime,v_postlunchstrtime,v_postlunchendtime,v_additionslotstrtime,v_additionslotendtime from kaveri.departmentaccesslotmaster
	where srocode = _srocode and stepcode = _stepcode and stepcodedesigntypid = _stepcodedesigntypid;
	
	if(v_cnt = 1)then
		if((current_time between v_prelunchstrtime and v_prelunchendtime) or 
			(current_time between v_postlunchstrtime and v_postlunchendtime) or 
			(current_time between v_additionslotstrtime and v_additionslotendtime))then
			select true into v_flag;
			else 
			select false into v_flag;
		end if;
--	else
--	raise notice 'No record found';
	end if;
return v_flag;
end;
$$;


ALTER FUNCTION kaveri.fn_fetch_isstepaccessallowed_1(_srocode integer, _stepcode integer, _stepcodedesigntypid integer) OWNER TO postgres;

--
-- Name: fn_fetch_jslip_easthi_details(character varying, character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_jslip_easthi_details(_finalregistrationnumber character varying, _jsliptype character varying) RETURNS TABLE(documentid bigint, applicationnumber character varying, finalregistrationnumber character varying, regid text, srocode integer, registrationdate date, regarticlecode integer, propertyid bigint, villagecode bigint, stampduty numeric, prevpropertyid numeric, receiptnumber text, jsliptype text, xmltypeforeswathu text, prevregid text, prevarticlecode integer, isownertobeclaimant boolean)
    LANGUAGE plpgsql
    AS $$
BEGIN	

if(_jsliptype='EAASTHI')
then
return query 	
SELECT DISTINCT dm.documentid,
    dm.applicationnumber,
    dm.finalregistrationnumber,
    dm.documentid || to_char(dm.registrationdatetime, 'ddMMYYYY'::text) AS regid,
    dm.srocode,
    dm.registrationdatetime::date AS registrationdate,
    dm.regarticlecode,
    pm.propertyid,
    pm.villagecode,
    sum(pm.stampduty) OVER (PARTITION BY pm.documentid ORDER BY pm.propertyid) AS stampduty,
    pm.sdrefund AS prevpropertyid,
    '3042'::text AS receiptnumber,
    'EAASTHI'::text AS jsliptype,
    '0'::text AS xmltypeforeswathu,
    '(0)'::text AS prevregid,
    0 AS prevarticlecode,
	sr.isownertobeclaimant
   FROM kaveri.documentmaster dm
     JOIN kaveri.propertymaster pm ON dm.applicationnumber::text = pm.applicationnumber::text
     JOIN kaveri.propertynumberdetails ps ON pm.propertyid = ps.propertyid
     LEFT JOIN kaveri.vw_fetch_stamprules_flags sr ON pm.stampruleid = sr.stampruleid
  WHERE pm.propertytypeid <> 17 AND dm.finalregistrationnumber IS NOT NULL AND dm.registrationdatetime IS NOT NULL AND (ps.currentpropertytypeid = ANY (ARRAY[65, 59]))
	and dm.finalregistrationnumber=_finalregistrationnumber;
else
return query
 SELECT DISTINCT dm.documentid::bigint,
    dm.applicationnumber::character varying,
    dm.finalregistrationnumber:: character varying,
    dm.documentid || to_char(dm.registrationdatetime, 'ddMMYYYY'::text) AS regid,
    dm.srocode,
    dm.registrationdatetime::date AS registrationdate,
    dm.regarticlecode,
    pm.propertyid,
    pm.villagecode,
    sum(pm.stampduty) OVER (PARTITION BY pm.documentid ORDER BY pm.propertyid) AS stampduty,
    pm.sdrefund AS prevpropertyid,
    'REC02'::text AS receiptnumber,
    'ESWATHU'::text AS jsliptype,
    sr.xmltypeforeswathu::text,
    kd1.prevregid::text,
    kd1.prevarticlecode,
	sr.isownertobeclaimant
   FROM kaveri.documentmaster dm
     JOIN kaveri.propertymaster pm ON pm.applicationnumber::text = dm.applicationnumber::text
     JOIN kaveri.propertynumberdetails ps ON ps.propertyid = pm.propertyid
     LEFT JOIN kaveri.vw_fetch_stamprules_flags sr ON sr.stampruleid = pm.stampruleid
     LEFT JOIN kaveri.k1documentdetails kd1 ON kd1.applicationnumber::text = dm.applicationnumber::text
  WHERE pm.propertytypeid <> 17 AND dm.finalregistrationnumber IS NOT NULL AND dm.registrationdatetime IS NOT NULL AND ps.currentpropertytypeid = 60 and dm.finalregistrationnumber=_finalregistrationnumber;
end if;
end;
$$;


