--
-- Name: fn_fetch_jslipcount(integer, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_jslipcount(_srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_json json;
begin 

	with docreg as (
		select d.srocode,applicationnumber,finalregistrationnumber,d.regarticlecode
		from kaveri.documentmaster d 
		where d.srocode = _srocode and d.isregistrationcompleted = true 
		and d.registrationdatetime >= _fromdate 
		and d.registrationdatetime <= _todate),
	sro as (
		select dm.districtnamee,s.sronamee 
		from docreg dd
		join kaveri.sromaster s on s.srocode = dd.srocode
		join kaveri.districtmaster dm on s.districtcode = dm.districtcode
		where s.srocode = dd.srocode),
	bhoomi as (
		select coalesce(count(distinct d.finalregistrationnumber),0) as bhoomidocreg,
		coalesce(count(distinct bm.finalregistrationnumber) filter(where bm.finalregistrationnumber is not null),0) as bhoomijslipcnt
		from docreg d
		left join kaveri.bhoomifileuploaddetails bm on d.finalregistrationnumber = bm.finalregistrationnumber and d.regarticlecode in (106,69,91,121,116,45,68,85,86,139)
		where exists(select 1
		      from kaveri.propertymaster p
		      join kaveri.propertynumberdetails pn on p.propertyid = pn.propertyid and pn.currentpropertytypeid = 1 -- Survey No
		      join kaveri.stamprulesflag sf on p.stampruleid = sf.stampruleid and sf.isjslipagri = true
		      where p.applicationnumber = d.applicationnumber)),
	eaasthi as (
		select coalesce(count(distinct d.finalregistrationnumber),0) as eaasthidocreg,
		coalesce(count(distinct bm.finalregistrationnumber) filter(where bm.finalregistrationnumber is not null),0) as eaasthijslipcnt
		from docreg d
		left join kaveri.easthi_eswathu_fileuploaddetails bm on d.finalregistrationnumber = bm.finalregistrationnumber
		where exists(select 1
		      from kaveri.propertymaster p
		      join kaveri.propertynumberdetails pn on p.propertyid = pn.propertyid and pn.currentpropertytypeid in(65,59) -- eaasthi and bbmp pid
		      join kaveri.stamprulesflag sf on p.stampruleid = sf.stampruleid and sf.isjslipeqvltnonagri = true
		      where p.applicationnumber = d.applicationnumber)),
	eswathu as (
		select coalesce(count(distinct d.finalregistrationnumber),0) as eswathudocreg,
		coalesce(count(distinct bm.finalregistrationnumber) filter(where bm.finalregistrationnumber is not null),0) as eswathujslipcnt
		from docreg d
		left join kaveri.easthi_eswathu_fileuploaddetails bm on d.finalregistrationnumber = bm.finalregistrationnumber
		where exists(select 1
		      from kaveri.propertymaster p
		      join kaveri.propertynumberdetails pn on p.propertyid = pn.propertyid and pn.currentpropertytypeid = 60 -- eswathu
		      join kaveri.stamprulesflag sf on p.stampruleid = sf.stampruleid and sf.isjslipeqvltnonagri = true
		      where p.applicationnumber = d.applicationnumber)),
	bda as (
		select coalesce(count(distinct d.finalregistrationnumber),0) as bdadocreg,
		coalesce(count(distinct bm.finalregistrationnumber) filter(where bm.finalregistrationnumber is not null),0) as bdajslipcnt
		from docreg d
		left join kaveri.bda_fileuploaddetails bm on d.finalregistrationnumber = bm.finalregistrationnumber
		where exists(select 1
		      from kaveri.propertymaster p
		      join kaveri.propertynumberdetails pn on p.propertyid = pn.propertyid and pn.currentpropertytypeid in (67) -- bda
		      join kaveri.stamprulesflag sf on p.stampruleid = sf.stampruleid and sf.isjslipeqvltnonagri = true
		      where p.applicationnumber = d.applicationnumber)),
	khb as (
		select coalesce(count(distinct d.finalregistrationnumber),0) as khbdocreg,
		coalesce(count(distinct bm.finalregistrationnumber) filter(where bm.finalregistrationnumber is not null),0) as khbjslipcnt
		from docreg d
		left join kaveri.bda_fileuploaddetails bm on d.finalregistrationnumber = bm.finalregistrationnumber
		where exists(select 1
		      from kaveri.propertymaster p
		      join kaveri.propertynumberdetails pn on p.propertyid = pn.propertyid and pn.currentpropertytypeid in (68) -- khb
		      join kaveri.stamprulesflag sf on p.stampruleid = sf.stampruleid and sf.isjslipeqvltnonagri = true
		      where p.applicationnumber = d.applicationnumber))
	select row_to_json(ss) into v_json from (
	select *,
	(bhoomidocreg + eaasthidocreg + eswathudocreg + bdadocreg + khbdocreg) as totaldocreg,
	(bhoomijslipcnt + eaasthijslipcnt + eswathujslipcnt + bdajslipcnt + khbjslipcnt) as totalcnt
	from sro,bhoomi,eaasthi,eswathu,bda,khb limit 1) ss;
return v_json;
end;
$$;


ALTER FUNCTION kaveri.fn_fetch_jslipcount(_srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_fetch_jslipcount(integer, integer, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_jslipcount(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
    v_json json;
begin 

    with docreg as (
        select
            d.srocode,
            d.applicationnumber,
            d.finalregistrationnumber
        from kaveri.documentmaster d
        join kaveri.sromaster s
            on s.srocode = d.srocode
        where d.isregistrationcompleted = true
          and d.registrationdatetime >= _fromdate
          and d.registrationdatetime <= _todate
          and (_srocode = 0 or d.srocode = _srocode)
          and (_districtcode = 0 or s.districtcode = _districtcode)
    ),
    sro as (
        select distinct
            s.srocode,
            dm.districtnamee,
            s.sronamee
        from docreg dd
        join kaveri.sromaster s
            on s.srocode = dd.srocode
        join kaveri.districtmaster dm
            on s.districtcode = dm.districtcode
    ),
    bhoomi as (
        select
            d.srocode,
            count(distinct d.finalregistrationnumber) as bhoomidocreg,
            count(distinct bm.finalregistrationnumber) filter(where bm.finalregistrationnumber is not null) as bhoomijslipcnt
        from docreg d
        left join kaveri.bhoomifileuploaddetails bm
            on d.finalregistrationnumber = bm.finalregistrationnumber
        where exists (
            select 1
            from kaveri.propertymaster p
            join kaveri.propertynumberdetails pn
                on p.propertyid = pn.propertyid
               and pn.currentpropertytypeid = 1
            join kaveri.stamprulesflag sf
                on p.stampruleid = sf.stampruleid
               and sf.isjslipagri = true
            where p.applicationnumber = d.applicationnumber
        )
        group by d.srocode
    ),
    eaasthi as (
        select
            d.srocode,
            count(distinct d.finalregistrationnumber) as eaasthidocreg,
            count(distinct bm.finalregistrationnumber) filter(where bm.finalregistrationnumber is not null) as eaasthijslipcnt
        from docreg d
        left join kaveri.easthi_eswathu_fileuploaddetails bm
            on d.finalregistrationnumber = bm.finalregistrationnumber
        where exists (
            select 1
            from kaveri.propertymaster p
            join kaveri.propertynumberdetails pn
                on p.propertyid = pn.propertyid
               and pn.currentpropertytypeid in (65,59)
            join kaveri.stamprulesflag sf
                on p.stampruleid = sf.stampruleid
               and sf.isjslipeqvltnonagri = true
            where p.applicationnumber = d.applicationnumber
        )
        group by d.srocode
    ),
    eswathu as (
        select
            d.srocode,
            count(distinct d.finalregistrationnumber) as eswathudocreg,
            count(distinct bm.finalregistrationnumber) filter(where bm.finalregistrationnumber is not null) as eswathujslipcnt
        from docreg d
        left join kaveri.easthi_eswathu_fileuploaddetails bm
            on d.finalregistrationnumber = bm.finalregistrationnumber
        where exists (
            select 1
            from kaveri.propertymaster p
            join kaveri.propertynumberdetails pn
                on p.propertyid = pn.propertyid
               and pn.currentpropertytypeid = 60
            join kaveri.stamprulesflag sf
                on p.stampruleid = sf.stampruleid
               and sf.isjslipeqvltnonagri = true
            where p.applicationnumber = d.applicationnumber
        )
        group by d.srocode
    ),
    bda as (
        select
            d.srocode,
            count(distinct d.finalregistrationnumber) as bdadocreg,
            count(distinct bm.finalregistrationnumber) filter(where bm.finalregistrationnumber is not null) as bdajslipcnt
        from docreg d
        left join kaveri.bda_fileuploaddetails bm
            on d.finalregistrationnumber = bm.finalregistrationnumber
        where exists (
            select 1
            from kaveri.propertymaster p
            join kaveri.propertynumberdetails pn
                on p.propertyid = pn.propertyid
               and pn.currentpropertytypeid = 67
            join kaveri.stamprulesflag sf
                on p.stampruleid = sf.stampruleid
               and sf.isjslipeqvltnonagri = true
            where p.applicationnumber = d.applicationnumber
        )
        group by d.srocode
    ),
    khb as (
        select
            d.srocode,
            count(distinct d.finalregistrationnumber) as khbdocreg,
            count(distinct bm.finalregistrationnumber) filter(where bm.finalregistrationnumber is not null) as khbjslipcnt
        from docreg d
        left join kaveri.bda_fileuploaddetails bm
            on d.finalregistrationnumber = bm.finalregistrationnumber
        where exists (
            select 1
            from kaveri.propertymaster p
            join kaveri.propertynumberdetails pn
                on p.propertyid = pn.propertyid
               and pn.currentpropertytypeid = 68
            join kaveri.stamprulesflag sf
                on p.stampruleid = sf.stampruleid
               and sf.isjslipeqvltnonagri = true
            where p.applicationnumber = d.applicationnumber
        )
        group by d.srocode
    )
    select json_agg(ss order by ss.districtnamee, ss.sronamee)
    into v_json
    from (
        select
            sro.districtnamee,
            sro.sronamee,
            coalesce(bhoomi.bhoomidocreg, 0) as bhoomidocreg,
            coalesce(bhoomi.bhoomijslipcnt, 0) as bhoomijslipcnt,
            coalesce(eaasthi.eaasthidocreg, 0) as eaasthidocreg,
            coalesce(eaasthi.eaasthijslipcnt, 0) as eaasthijslipcnt,
            coalesce(eswathu.eswathudocreg, 0) as eswathudocreg,
            coalesce(eswathu.eswathujslipcnt, 0) as eswathujslipcnt,
            coalesce(bda.bdadocreg, 0) as bdadocreg,
            coalesce(bda.bdajslipcnt, 0) as bdajslipcnt,
            coalesce(khb.khbdocreg, 0) as khbdocreg,
            coalesce(khb.khbjslipcnt, 0) as khbjslipcnt,
            (
                coalesce(bhoomi.bhoomidocreg, 0) +
                coalesce(eaasthi.eaasthidocreg, 0) +
                coalesce(eswathu.eswathudocreg, 0) +
                coalesce(bda.bdadocreg, 0) +
                coalesce(khb.khbdocreg, 0)
            ) as totaldocreg,
            (
                coalesce(bhoomi.bhoomijslipcnt, 0) +
                coalesce(eaasthi.eaasthijslipcnt, 0) +
                coalesce(eswathu.eswathujslipcnt, 0) +
                coalesce(bda.bdajslipcnt, 0) +
                coalesce(khb.khbjslipcnt, 0)
            ) as totalcnt
        from sro
        left join bhoomi
            on sro.srocode = bhoomi.srocode
        left join eaasthi
            on sro.srocode = eaasthi.srocode
        left join eswathu
            on sro.srocode = eswathu.srocode
        left join bda
            on sro.srocode = bda.srocode
        left join khb
            on sro.srocode = khb.srocode
    ) ss;

    return v_json;
end;
$$;


ALTER FUNCTION kaveri.fn_fetch_jslipcount(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_fetch_jslipcount_1(integer, integer, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_jslipcount_1(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
    v_json json;
begin 

    with docreg as (
        select
            d.srocode,
            d.applicationnumber,
            d.finalregistrationnumber
        from kaveri.documentmaster d
        join kaveri.sromaster s
            on s.srocode = d.srocode
        where d.isregistrationcompleted = true
          and d.registrationdatetime >= _fromdate
          and d.registrationdatetime <= _todate
          and (_srocode = 0 or d.srocode = _srocode)
          and (_districtcode = 0 or s.districtcode = _districtcode)
    ),
    sro as (
        select distinct
            s.srocode,
            dm.districtnamee,
            s.sronamee
        from docreg dd
        join kaveri.sromaster s
            on s.srocode = dd.srocode
        join kaveri.districtmaster dm
            on s.districtcode = dm.districtcode
    ),
    bhoomi as (
        select
            d.srocode,
            count(distinct d.finalregistrationnumber) as bhoomidocreg,
            count(distinct bm.finalregistrationnumber) filter(where bm.finalregistrationnumber is not null) as bhoomijslipcnt
        from docreg d
        left join kaveri.bhoomifileuploaddetails bm
            on d.finalregistrationnumber = bm.finalregistrationnumber
        where exists (
            select 1
            from kaveri.propertymaster p
            join kaveri.propertynumberdetails pn
                on p.propertyid = pn.propertyid
               and pn.currentpropertytypeid = 1
            join kaveri.stamprulesflag sf
                on p.stampruleid = sf.stampruleid
               and sf.isjslipagri = true
            where p.applicationnumber = d.applicationnumber
        )
        group by d.srocode
    ),
    eaasthi as (
        select
            d.srocode,
            count(distinct d.finalregistrationnumber) as eaasthidocreg,
            count(distinct bm.finalregistrationnumber) filter(where bm.finalregistrationnumber is not null) as eaasthijslipcnt
        from docreg d
        left join kaveri.easthi_eswathu_fileuploaddetails bm
            on d.finalregistrationnumber = bm.finalregistrationnumber
        where exists (
            select 1
            from kaveri.propertymaster p
            join kaveri.propertynumberdetails pn
                on p.propertyid = pn.propertyid
               and pn.currentpropertytypeid in (65,59)
            join kaveri.stamprulesflag sf
                on p.stampruleid = sf.stampruleid
               and sf.isjslipeqvltnonagri = true
            where p.applicationnumber = d.applicationnumber
        )
        group by d.srocode
    ),
    eswathu as (
        select
            d.srocode,
            count(distinct d.finalregistrationnumber) as eswathudocreg,
            count(distinct bm.finalregistrationnumber) filter(where bm.finalregistrationnumber is not null) as eswathujslipcnt
        from docreg d
        left join kaveri.easthi_eswathu_fileuploaddetails bm
            on d.finalregistrationnumber = bm.finalregistrationnumber
        where exists (
            select 1
            from kaveri.propertymaster p
            join kaveri.propertynumberdetails pn
                on p.propertyid = pn.propertyid
               and pn.currentpropertytypeid = 60
            join kaveri.stamprulesflag sf
                on p.stampruleid = sf.stampruleid
               and sf.isjslipeqvltnonagri = true
            where p.applicationnumber = d.applicationnumber
        )
        group by d.srocode
    ),
    bda as (
        select
            d.srocode,
            count(distinct d.finalregistrationnumber) as bdadocreg,
            count(distinct bm.finalregistrationnumber) filter(where bm.finalregistrationnumber is not null) as bdajslipcnt
        from docreg d
        left join kaveri.bda_fileuploaddetails bm
            on d.finalregistrationnumber = bm.finalregistrationnumber
        where exists (
            select 1
            from kaveri.propertymaster p
            join kaveri.propertynumberdetails pn
                on p.propertyid = pn.propertyid
               and pn.currentpropertytypeid = 67
            join kaveri.stamprulesflag sf
                on p.stampruleid = sf.stampruleid
               and sf.isjslipeqvltnonagri = true
            where p.applicationnumber = d.applicationnumber
        )
        group by d.srocode
    ),
    khb as (
        select
            d.srocode,
            count(distinct d.finalregistrationnumber) as khbdocreg,
            count(distinct bm.finalregistrationnumber) filter(where bm.finalregistrationnumber is not null) as khbjslipcnt
        from docreg d
        left join kaveri.bda_fileuploaddetails bm
            on d.finalregistrationnumber = bm.finalregistrationnumber
        where exists (
            select 1
            from kaveri.propertymaster p
            join kaveri.propertynumberdetails pn
                on p.propertyid = pn.propertyid
               and pn.currentpropertytypeid = 68
            join kaveri.stamprulesflag sf
                on p.stampruleid = sf.stampruleid
               and sf.isjslipeqvltnonagri = true
            where p.applicationnumber = d.applicationnumber
        )
        group by d.srocode
    )
    select json_agg(ss order by ss.districtnamee, ss.sronamee)
    into v_json
    from (
        select
            sro.districtnamee,
            sro.sronamee,
            coalesce(bhoomi.bhoomidocreg, 0) as bhoomidocreg,
            coalesce(bhoomi.bhoomijslipcnt, 0) as bhoomijslipcnt,
            coalesce(eaasthi.eaasthidocreg, 0) as eaasthidocreg,
            coalesce(eaasthi.eaasthijslipcnt, 0) as eaasthijslipcnt,
            coalesce(eswathu.eswathudocreg, 0) as eswathudocreg,
            coalesce(eswathu.eswathujslipcnt, 0) as eswathujslipcnt,
            coalesce(bda.bdadocreg, 0) as bdadocreg,
            coalesce(bda.bdajslipcnt, 0) as bdajslipcnt,
            coalesce(khb.khbdocreg, 0) as khbdocreg,
            coalesce(khb.khbjslipcnt, 0) as khbjslipcnt,
            (
                coalesce(bhoomi.bhoomidocreg, 0) +
                coalesce(eaasthi.eaasthidocreg, 0) +
                coalesce(eswathu.eswathudocreg, 0) +
                coalesce(bda.bdadocreg, 0) +
                coalesce(khb.khbdocreg, 0)
            ) as totaldocreg,
            (
                coalesce(bhoomi.bhoomijslipcnt, 0) +
                coalesce(eaasthi.eaasthijslipcnt, 0) +
                coalesce(eswathu.eswathujslipcnt, 0) +
                coalesce(bda.bdajslipcnt, 0) +
                coalesce(khb.khbjslipcnt, 0)
            ) as totalcnt
        from sro
        left join bhoomi
            on sro.srocode = bhoomi.srocode
        left join eaasthi
            on sro.srocode = eaasthi.srocode
        left join eswathu
            on sro.srocode = eswathu.srocode
        left join bda
            on sro.srocode = bda.srocode
        left join khb
            on sro.srocode = khb.srocode
    ) ss;

    return v_json;
end;
$$;


ALTER FUNCTION kaveri.fn_fetch_jslipcount_1(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_fetch_jslipcount_new(integer, integer, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_jslipcount_new(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_json json;
begin 
--	with docreg as (
--	    select dm.districtnamee,s.sronamee,
--	        d.applicationnumber,
--	        d.finalregistrationnumber,
--	        d.regarticlecode
--	    from kaveri.documentmaster d
--	    join kaveri.sromaster s on s.srocode = d.srocode
--		join kaveri.districtmaster dm on s.districtcode = dm.districtcode
--		where 
--			(CASE WHEN _districtcode <> 0 then dm.districtcode = _districtcode ELSE true END)
--	        AND (CASE WHEN _srocode <> 0 then d.srocode = _srocode ELSE true END) and
--	        d.isregistrationcompleted = true
--	      	and d.registrationdatetime >= _fromdate
--	      	and d.registrationdatetime <= _todate
--		),
--	classified as (
--	    select distinct
--	        d.applicationnumber,
--	        d.finalregistrationnumber,
--	        max(case when pn.currentpropertytypeid = 1 and sf.isjslipagri = true and d.regarticlecode in(106,69,91,121,116,45,68,85,86,139) then 1 else 0 end) over (partition by d.applicationnumber) as is_bhoomi,
--	        max(case when pn.currentpropertytypeid in (65, 59) and sf.isjslipeqvltnonagri = true then 1 else 0 end) over (partition by d.applicationnumber) as is_eaasthi,
--	        max(case when pn.currentpropertytypeid = 60 and sf.isjslipeqvltnonagri = true then 1 else 0 end) over (partition by d.applicationnumber) as is_eswathu,
--	        max(case when pn.currentpropertytypeid = 67 and sf.isjslipeqvltnonagri = true then 1 else 0 end) over (partition by d.applicationnumber) as is_bda,
--	        max(case when pn.currentpropertytypeid = 68 and sf.isjslipeqvltnonagri = true then 1 else 0 end) over (partition by d.applicationnumber) as is_khb
--	    from docreg d
--	    join kaveri.propertymaster p on p.applicationnumber = d.applicationnumber
--	    join kaveri.propertynumberdetails pn on pn.propertyid = p.propertyid and pn.currentpropertytypeid in (1, 65, 59, 60, 67, 68)
--	    join kaveri.stamprulesflag sf on sf.stampruleid = p.stampruleid and (sf.isjslipagri = true or sf.isjslipeqvltnonagri = true)
--	),
--	bhoomi_uploads as (
--	    select distinct c.finalregistrationnumber
--	    from classified c
--	    join kaveri.bhoomifileuploaddetails bm on bm.finalregistrationnumber = c.finalregistrationnumber --and acknowledgeno <> '0'
--	    where c.is_bhoomi = 1
--	),
--	eaasthi_uploads as (
--	    select distinct c.finalregistrationnumber
--	    from classified c
--	    join kaveri.easthi_eswathu_fileuploaddetails ea on ea.finalregistrationnumber = c.finalregistrationnumber --and acknowledgeno::int > 1000 and acknowledgeno::int < 2000
--	    where c.is_eaasthi = 1
--	),
--	eswathu_uploads as (
--	    select distinct c.finalregistrationnumber
--	    from classified c
--	    join kaveri.easthi_eswathu_fileuploaddetails ea on ea.finalregistrationnumber = c.finalregistrationnumber --and acknowledgeno::int > 1000 and acknowledgeno::int < 2000
--	    where c.is_eswathu = 1
--	),
--	bda_uploads as (
--	    select distinct c.finalregistrationnumber
--	    from classified c
--	    join kaveri.bda_fileuploaddetails bda on bda.finalregistrationnumber = c.finalregistrationnumber
--	    where c.is_bda = 1
--	),
--	khb_uploads as (
--	    select distinct c.finalregistrationnumber
--	    from classified c
--	    join kaveri.bda_fileuploaddetails khb on khb.finalregistrationnumber = c.finalregistrationnumber
--	    where c.is_khb = 1
--	)
--	select row_to_json(ss) into v_json from (
--	select ss.districtnamee,ss.sronamee,
--			sum(ss.bhoomidocreg),
--			sum(ss.bhoomijslipcnt),
--			sum(ss.eaasthidocreg),
--			sum(ss.eaasthijslipcnt),
--			sum(ss.eswathudocreg),
--			sum(ss.eswathujslipcnt),
--			sum(ss.bdadocreg),
--			sum(ss.bdajslipcnt),
--			sum(ss.khbdocreg),
--			sum(ss.khbjslipcnt)
--			from (
--	select 
--		dd.districtnamee,dd.sronamee,
--	    count(distinct c.finalregistrationnumber)filter (where c.is_bhoomi = 1)as bhoomidocreg,
--	    count(distinct bu.finalregistrationnumber) as bhoomijslipcnt,
--	    count(distinct c.finalregistrationnumber) filter (where c.is_eaasthi = 1)as eaasthidocreg,
--	    count(distinct eu.finalregistrationnumber)as eaasthijslipcnt,
--	    count(distinct c.finalregistrationnumber) filter (where c.is_eswathu = 1)as eswathudocreg,
--	    count(distinct esu.finalregistrationnumber)as eswathujslipcnt,
--	    count(distinct c.finalregistrationnumber) filter (where c.is_bda = 1)as bdadocreg,
--	    count(distinct bdu.finalregistrationnumber)as bdajslipcnt,
--	    count(distinct c.finalregistrationnumber) filter (where c.is_khb = 1)as khbdocreg,
--	    count(distinct ku.finalregistrationnumber)as khbjslipcnt
--	from classified c
--	left join docreg dd on c.finalregistrationnumber = dd.finalregistrationnumber
--	left join bhoomi_uploads bu on c.finalregistrationnumber = bu.finalregistrationnumber
--	left join eaasthi_uploads eu on c.finalregistrationnumber = eu.finalregistrationnumber
--	left join eswathu_uploads esu on c.finalregistrationnumber = esu.finalregistrationnumber
--	left join bda_uploads bdu on c.finalregistrationnumber = bdu.finalregistrationnumber
--	left join khb_uploads ku on c.finalregistrationnumber = ku.finalregistrationnumber
--	group by dd.districtnamee,dd.sronamee)ss group by ss.districtnamee,ss.sronamee) ss;
	
	with docreg as (
	    select d.srocode, applicationnumber, finalregistrationnumber, d.regarticlecode
	    from kaveri.documentmaster d
		join kaveri.sromaster s on s.srocode = d.srocode
		join kaveri.districtmaster dm on s.districtcode = dm.districtcode
	    where (CASE WHEN _districtcode <> 0 then dm.districtcode = _districtcode ELSE true END)
	        AND (CASE WHEN _srocode <> 0 then d.srocode = _srocode ELSE true END) and 
	    	d.isregistrationcompleted = true 
	      and d.registrationdatetime >= _fromdate
	      and d.registrationdatetime <= _todate),
	bhoomi as (select d.srocode,
	        count(distinct d.finalregistrationnumber) as bhoomidocreg,
	        count(distinct bm.finalregistrationnumber) filter(where bm.finalregistrationnumber is not null) as bhoomijslipcnt
	    from docreg d
	    left join kaveri.bhoomifileuploaddetails bm on d.finalregistrationnumber = bm.finalregistrationnumber 
	       and d.regarticlecode in (106,69,91,121,116,45,68,85,86,139) and bm.acknowledgeno <> '0'
	    where exists (select 1
	        from kaveri.propertymaster p
	        join kaveri.propertynumberdetails pn on p.propertyid = pn.propertyid and pn.currentpropertytypeid = 1
	        join kaveri.stamprulesflag sf on p.stampruleid = sf.stampruleid and sf.isjslipagri = true
	        where p.applicationnumber = d.applicationnumber)
	    group by d.srocode),
	eaasthi as (select 
	        d.srocode,
	        count(distinct d.finalregistrationnumber) as eaasthidocreg,
	        count(distinct bm.finalregistrationnumber) filter(where bm.finalregistrationnumber is not null) as eaasthijslipcnt
	    from docreg d
	    left join kaveri.easthi_eswathu_fileuploaddetails bm on d.finalregistrationnumber = bm.finalregistrationnumber and bm.acknowledgeno::int > 1000
	    where exists (select 1
	        from kaveri.propertymaster p
	        join kaveri.propertynumberdetails pn on p.propertyid = pn.propertyid and pn.currentpropertytypeid in (65,59)
	        join kaveri.stamprulesflag sf on p.stampruleid = sf.stampruleid and sf.isjslipeqvltnonagri = true
	        where p.applicationnumber = d.applicationnumber)group by d.srocode),
	eswathu as (select d.srocode,
	        count(distinct d.finalregistrationnumber) as eswathudocreg,
	        count(distinct bm.finalregistrationnumber) filter(where bm.finalregistrationnumber is not null) as eswathujslipcnt
	    from docreg d
	    left join kaveri.easthi_eswathu_fileuploaddetails bm on d.finalregistrationnumber = bm.finalregistrationnumber and bm.acknowledgeno::int > 1000
	    where exists (select 1
	        from kaveri.propertymaster p
	        join kaveri.propertynumberdetails pn on p.propertyid = pn.propertyid and pn.currentpropertytypeid = 60
	        join kaveri.stamprulesflag sf on p.stampruleid = sf.stampruleid and sf.isjslipeqvltnonagri = true
	        where p.applicationnumber = d.applicationnumber)group by d.srocode),
	bda as (select d.srocode,
	        count(distinct d.finalregistrationnumber) as bdadocreg,
	        count(distinct bm.finalregistrationnumber) filter(where bm.finalregistrationnumber is not null) as bdajslipcnt
	    from docreg d
	    left join kaveri.bda_fileuploaddetails bm on d.finalregistrationnumber = bm.finalregistrationnumber
	    where exists (
	        select 1
	        from kaveri.propertymaster p
	        join kaveri.propertynumberdetails pn on p.propertyid = pn.propertyid and pn.currentpropertytypeid = 67
	        join kaveri.stamprulesflag sf on p.stampruleid = sf.stampruleid and sf.isjslipeqvltnonagri = true
	        where p.applicationnumber = d.applicationnumber)group by d.srocode),
	khb as (
	    select 
	        d.srocode,
	        count(distinct d.finalregistrationnumber) as khbdocreg,
	        count(distinct bm.finalregistrationnumber) filter(where bm.finalregistrationnumber is not null) as khbjslipcnt
	    from docreg d
	    left join kaveri.bda_fileuploaddetails bm on d.finalregistrationnumber = bm.finalregistrationnumber
	    where exists (select 1
	        from kaveri.propertymaster p
	        join kaveri.propertynumberdetails pn on p.propertyid = pn.propertyid and pn.currentpropertytypeid = 68
	        join kaveri.stamprulesflag sf on p.stampruleid = sf.stampruleid and sf.isjslipeqvltnonagri = true
	        where p.applicationnumber = d.applicationnumber)group by d.srocode)
	select array_to_json(array_agg(row_to_json(ss))) into v_json from (        
	select dm.districtnamee, s.sronamee,
	    coalesce(b.bhoomidocreg,0) as bhoomidocreg,
	    coalesce(b.bhoomijslipcnt,0) as bhoomijslipcnt,
	    coalesce(e.eaasthidocreg,0) as eaasthidocreg,
	    coalesce(e.eaasthijslipcnt,0) as eaasthijslipcnt,
	    coalesce(es.eswathudocreg,0) as eswathudocreg,
	    coalesce(es.eswathujslipcnt,0) as eswathujslipcnt,
	    coalesce(bd.bdadocreg,0) as bdadocreg,
	    coalesce(bd.bdajslipcnt,0) as bdajslipcnt,
	    coalesce(k.khbdocreg,0) as khbdocreg,
	    coalesce(k.khbjslipcnt,0) as khbjslipcnt,
	    (coalesce(b.bhoomidocreg,0) + coalesce(e.eaasthidocreg,0) + coalesce(es.eswathudocreg,0) + coalesce(bd.bdadocreg,0) + coalesce(k.khbdocreg,0)) as totaldocreg,
	    (coalesce(b.bhoomijslipcnt,0) + coalesce(e.eaasthijslipcnt,0) + coalesce(es.eswathujslipcnt,0) + coalesce(bd.bdajslipcnt,0) + coalesce(k.khbjslipcnt,0)) as totaljslip
	from kaveri.sromaster s 
	join kaveri.districtmaster dm on s.districtcode = dm.districtcode
	left join bhoomi b on s.srocode = b.srocode 
	full outer join eaasthi e on b.srocode = e.srocode
	full outer join eswathu es on b.srocode = es.srocode
	full outer join bda bd on b.srocode = bd.srocode
	full outer join khb k on b.srocode = k.srocode
	order by dm.districtnamee, s.sronamee) ss;
	
return v_json;
end;
$$;


ALTER FUNCTION kaveri.fn_fetch_jslipcount_new(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_fetch_liability_details(bigint, kaveri.ec_srch_property[]); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_liability_details(_villagecode bigint, p_srch_property kaveri.ec_srch_property[]) RETURNS TABLE(issuedate timestamp without time zone, issuedby text, amount integer, ordernumber text, liabilitynote text, srocode integer, sronamee text, propertyid bigint)
    LANGUAGE plpgsql
    AS $$
 
declare
 
v_propertyids bigint[];
begin

 
 
    SELECT array_agg(DISTINCT pm.propertyid) into v_propertyids
    FROM kaveri.propertynumberdetails pn
    JOIN kaveri.propertymaster pm ON pn.propertyid = pm.propertyid
    WHERE pm.villagecode = _villagecode
      AND (pn.currentpropertytypeid, pn.currentnumber) IN (
        SELECT * FROM unnest(p_srch_property) a
      );
 
return query 
select a.orderdate AS issuedate,
    a.issuedby,
    a.liabilityamount AS amount,
    a.ordernumber,
    a.liabilitynote,
    a.srocode,
    c.sronamee,
    a.userid,
    a.drocode,
    a.propertyid
   from kaveri.liabilitydetails_new ld
      JOIN sromaster c ON c.srocode = a.srocode
where ld.propertyid in (select * from unnest(v_propertyids)b) and ld.iscleared=false;
 
 END;
$$;


ALTER FUNCTION kaveri.fn_fetch_liability_details(_villagecode bigint, p_srch_property kaveri.ec_srch_property[]) OWNER TO postgres;

--
-- Name: fn_fetch_liability_details_json_check(bigint, bigint, text, bigint, bigint, character varying, bigint, character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_liability_details_json_check(_srocode bigint, _bookid bigint, _finyear text, _documentnumber bigint DEFAULT NULL::bigint, _propertyid bigint DEFAULT NULL::bigint, _propertynumber character varying DEFAULT NULL::character varying, _survey_no bigint DEFAULT NULL::bigint, _hissa_no character varying DEFAULT NULL::character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare v_data_json json;
BEGIN
select row_to_json(app_json) into v_data_json
from (
		SELECT A.SROCODE,
			B.SRONAMEE AS SRONAMEE,
			A.Bookid,
			C.BOOKNAMEENGLISH AS BOOKNAME,
			case
				when cast(to_char(A.EXECUTIONDATETIME, 'MM') as bigint) > 3 then cast(to_char(A.EXECUTIONDATETIME, 'YYYY') as bigint) || '-' || to_char(A.EXECUTIONDATETIME + interval '1 year', 'YY')
				else cast(to_char(A.EXECUTIONDATETIME, 'YYYY') as bigint) -1 || '-' || to_char(A.EXECUTIONDATETIME, 'YY')
			end AS FINANCIAL_YEAR,
			A.DOCUMENTNUMBER,
			--*****************Add Property Number details***********************--
			(
				select array_to_json(array_agg(row_to_json(propertynodetails)))
				from (
						select 'NOTE :' || ' ' || ps.SCHEDULETYPE || ' ' || ps.DESCRIPTION AS PROPERTY_DETAILS,
							pn.CURRENTNUMBER AS PROPERTYNUMBERDETAILS,
							string_agg(
								distinct case
									when pi.partytypeid = 1 --or ps.propertyid is not null -- Commented by Shubham on 06-01-2023.
									then pi.firstname || '' || pi.middlename || '' || pi.lastname
								end,
								','
							) as claimant,
							string_agg(
								distinct case
									when pi.partytypeid = 2 then pi.firstname || '' || pi.middlename || '' || pi.lastname
								end,
								','
							) as executant,
							'Order number :' || ' ' || lop.ORDERNUMBER || '<br/><br/>' || lop.liabilitynote || ' Issue Date :' || ' ' || to_char(lop.issuedate, 'dd-MM-yyyy') as liabilitydetails,
							pn.propertyid
						from kaveri.partyinfo pi
							left outer join kaveri.propertyschedules ps on pi.applicationnumber = ps.applicationnumber
							left outer join kaveri.propertynumberdetails pn on pn.propertyid = ps.propertyid
							left join kaveri.propertymaster pm on pm.propertyid=pn.propertyid
							left outer join kaveri.LIABILITYONPROPERTYDETAILS lp on pn.propertyid = lp.propertyid --and lp.orderissuedate is not null
							left join kaveri.liabilitydetails lop on lp.liabilityid = lop.liabilityid
						where pi.applicationnumber = A.applicationnumber
							and pm.regsrocode= a.srocode
						group by pn.CURRENTNUMBER,
							ps.DESCRIPTION,
							ps.SCHEDULETYPE,
							lop.ORDERNUMBER,
							lop.issuedate,
							lop.liabilitynote,
							pn.propertyid
					) propertynodetails
			) as propnumberdetails,
			--*****************Exact Property Number details***********************--
			(
				select array_to_json(array_agg(row_to_json(exactpropertydetails)))
				from (
						select distinct dm.FINALREGISTRATIONNUMBER,
							dm.EXECUTIONDATETIME AS EXECUTIONDATE,
							sm.ARTICLENAMEE AS ARTICLENAME,
							pm1.LANDMARK,
							pnd.CURRENTNUMBER AS PROPERTYNUMBERDETAILS,
							'NOTE :' || ' ' || psd.SCHEDULETYPE || ' ' || psd.DESCRIPTION AS PROPERTYDESCRIPTION,
							pm1.propertyid
						from kaveri.propertynumberdetails pnd
							left join kaveri.propertymaster pm1 on pnd.propertyid = pm1.propertyid
							left join kaveri.documentmaster dm on pm1.applicationnumber = dm.applicationnumber
							left join kaveri.stamparticles sm on pm1.stamparticlecode = sm.stamparticlecode
							left join kaveri.propertyschedules psd on pm1.propertyid = psd.propertyid
						where pnd.currentnumber = PR.currentnumber
							and finalregistrationnumber is not null
							and pnd.srocode = a.srocode
					) exactpropertydetails
			) as exactpropdetails,
			--*****************Similar Property Number details***********************--
			(
				select array_to_json(array_agg(row_to_json(similarpropertydetails)))
				from (
						select distinct dm1.FINALREGISTRATIONNUMBER,
							dm1.EXECUTIONDATETIME AS EXECUTIONDATE,
							sm1.ARTICLENAMEE AS ARTICLENAME,
							pm2.LANDMARK,
							pnd1.CURRENTNUMBER AS PROPERTYNUMBERDETAILS,
							'NOTE :' || ' ' || psd1.SCHEDULETYPE || ' ' || psd1.DESCRIPTION AS PROPERTYDESCRIPTION,
							pm2.propertyid
						from kaveri.propertynumberdetails pnd1
							left join kaveri.propertymaster pm2 on pnd1.propertyid = pm2.propertyid
							left join kaveri.documentmaster dm1 on pm2.applicationnumber = dm1.applicationnumber
							left join kaveri.stamparticles sm1 on pm2.stamparticlecode = sm1.stamparticlecode
							left join kaveri.propertyschedules psd1 on pm2.propertyid = psd1.propertyid
						where pnd1.currentnumber like '%' || PR.currentnumber || '%'
							and finalregistrationnumber is not null
							and pnd1.srocode = a.srocode
					) similarpropertydetails
			) as similarpropdetails
		FROM KAVERI.DOCUMENTMASTER A
			LEFT OUTER JOIN KAVERI.SROMASTER B ON A.SROCODE = B.SROCODE
			AND EXECUTIONDATETIME IS NOT NULL
			and a.srocode > 0
			LEFT OUTER JOIN KAVERI.BOOKTYPEMASTER C ON C.BOOKID = A.BOOKID
			LEFT OUTER JOIN KAVERI.PROPERTYMASTER D ON D.DOCUMENTID = A.DOCUMENTID
			LEFT OUTER join KAVERI.PROPERTYNUMBERDETAILS PR ON D.PROPERTYID = PR.PROPERTYID
			LEFT OUTER join KAVERI.STAMPARTICLES S ON S.STAMPARTICLECODE = D.STAMPARTICLECODE
		where a.srocode = _srocode
			and a.bookid = _bookid
			and (
				a.documentnumber = _documentnumber
				or (
					PR.currentpropertytypeid = _propertyid
					and (
						pr.currentnumber = _propertynumber
						or (
							pr.survey_no = _survey_no
							and pr.hissa_no = _hissa_no
						)
					)
				)
			)
			and case
				when cast(to_char(A.EXECUTIONDATETIME, 'MM') as bigint) > 3 then cast(to_char(A.EXECUTIONDATETIME, 'YYYY') as bigint) || '-' || to_char(A.EXECUTIONDATETIME + interval '1 year', 'YY')
				else cast(to_char(A.EXECUTIONDATETIME, 'YYYY') as bigint) -1 || '-' || to_char(A.EXECUTIONDATETIME, 'YY')
			end = _finyear
			and A.FINALREGISTRATIONNUMBER IS NOT NULL
	) app_json;
return v_data_json;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_liability_details_json_check(_srocode bigint, _bookid bigint, _finyear text, _documentnumber bigint, _propertyid bigint, _propertynumber character varying, _survey_no bigint, _hissa_no character varying) OWNER TO csgadmin;

--
-- Name: fn_fetch_liability_details_json_check-dup(bigint, bigint, text, bigint); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri."fn_fetch_liability_details_json_check-dup"(_srocode bigint, _bookid bigint, _finyear text, _documentnumber bigint) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
BEGIN
select  row_to_json(app_json) into v_data_json
from 
(
SELECT  A.SROCODE,
B.SRONAMEE AS SRONAMEE,
A.Bookid,
C.BOOKNAMEENGLISH AS BOOKNAME,
case when cast(to_char(A.EXECUTIONDATETIME,'MM') as bigint)>3 then cast(to_char(A.EXECUTIONDATETIME,'YYYY')as bigint) ||'-'|| to_char(A.EXECUTIONDATETIME  + interval '1 year','YY')
else cast(to_char(A.EXECUTIONDATETIME,'YYYY')as bigint)-1 ||'-'|| to_char(A.EXECUTIONDATETIME,'YY') end AS FINANCIAL_YEAR,
A.DOCUMENTNUMBER,
	--*****************Add Property Number details***********************--
	( select array_to_json(array_agg(row_to_json(propertynodetails)))
      from (
	  select  'NOTE :'||' '||ps.SCHEDULETYPE ||' '||ps.DESCRIPTION AS PROPERTY_DETAILS,
      pn.CURRENTNUMBER AS PROPERTYNUMBERDETAILS,
	  string_agg(distinct case when pi.partytypeid = 1 
	 --or ps.propertyid is not null -- Commented by Shubham on 06-01-2023.
	 then pi.firstname||''||pi.middlename||''||pi.lastname end,',') as claimant,
	  string_agg(distinct case when pi.partytypeid = 2 then pi.firstname||''||pi.middlename||''||pi.lastname end,',') as executant,
        'Order number :'||' '||lop.ORDERNUMBER||'<br/><br/>'||lop.liabilitynote||' Issue Date :'||' '||to_char(lop.issuedate,'dd-MM-yyyy') as liabilitydetails,
	  pn.propertyid
	  from kaveri.partyinfo pi left outer join kaveri.propertyschedules ps
	  on pi.applicationnumber=ps.applicationnumber left outer join kaveri.propertynumberdetails pn on
	  pn.propertyid=ps.propertyid left outer join kaveri.LIABILITYONPROPERTYDETAILS lp
	  on pn.propertyid=lp.propertyid --and lp.orderissuedate is not null
	  left join kaveri.liabilitydetails lop on lp.liabilityid=lop.liabilityid
	  where pi.applicationnumber=A.applicationnumber and pn.srocode=a.srocode 
	  group by pn.CURRENTNUMBER, ps.DESCRIPTION, ps.SCHEDULETYPE, lop.ORDERNUMBER,lop.issuedate,lop.liabilitynote,pn.propertyid
	  )propertynodetails) as propnumberdetails,
	  --*****************Exact Property Number details***********************--
      (select array_to_json(array_agg(row_to_json(exactpropertydetails)))
      from (select distinct dm.FINALREGISTRATIONNUMBER,
      dm.EXECUTIONDATETIME AS EXECUTIONDATE,
      sm.ARTICLENAMEE AS ARTICLENAME,
      pm1.LANDMARK,
      pnd.CURRENTNUMBER AS PROPERTYNUMBERDETAILS,
      'NOTE :'||' '||psd.SCHEDULETYPE ||' '||psd.DESCRIPTION AS PROPERTYDESCRIPTION, pm1.propertyid
	  from kaveri.propertynumberdetails pnd 
	  left join kaveri.propertymaster pm1 on pnd.propertyid=pm1.propertyid 
	  left join kaveri.documentmaster dm on pm1.applicationnumber=dm.applicationnumber
	  left join kaveri.stamparticles sm on pm1.stamparticlecode=sm.stamparticlecode
	  left join kaveri.propertyschedules psd on pm1.propertyid=psd.propertyid
	  where pnd.currentnumber=PR.currentnumber and finalregistrationnumber is not null and pnd.srocode=a.srocode
	  )exactpropertydetails ) 
	  as exactpropdetails,
	  --*****************Similar Property Number details***********************--
      (select array_to_json(array_agg(row_to_json(similarpropertydetails)))
      from (select distinct dm1.FINALREGISTRATIONNUMBER,
      dm1.EXECUTIONDATETIME AS EXECUTIONDATE,
      sm1.ARTICLENAMEE AS ARTICLENAME,
      pm2.LANDMARK,
      pnd1.CURRENTNUMBER AS PROPERTYNUMBERDETAILS,
      'NOTE :'||' '||psd1.SCHEDULETYPE ||' '||psd1.DESCRIPTION AS PROPERTYDESCRIPTION, pm2.propertyid 
	  from kaveri.propertynumberdetails pnd1 
	  left join kaveri.propertymaster pm2 on pnd1.propertyid=pm2.propertyid 
	  left join kaveri.documentmaster dm1 on pm2.applicationnumber=dm1.applicationnumber
	  left join kaveri.stamparticles sm1 on pm2.stamparticlecode=sm1.stamparticlecode
	  left join kaveri.propertyschedules psd1 on pm2.propertyid=psd1.propertyid
	  where pnd1.currentnumber like '%'||PR.currentnumber||'%' and finalregistrationnumber is not null
	  and pnd1.srocode=a.srocode
	  )similarpropertydetails ) 
	  as similarpropdetails
	
FROM KAVERI.DOCUMENTMASTER A LEFT OUTER JOIN KAVERI.SROMASTER B
ON A.SROCODE = B.SROCODE AND EXECUTIONDATETIME IS NOT NULL and a.srocode > 0
LEFT OUTER JOIN KAVERI.BOOKTYPEMASTER C ON C.BOOKID = A.BOOKID
LEFT OUTER JOIN KAVERI.PROPERTYMASTER D ON D.DOCUMENTID = A.DOCUMENTID 
--LEFT OUTER JOIN KAVERI.PROPERTYNUMBERDETAILS E ON E.PROPERTYID = D.PROPERTYID
--LEFT OUTER JOIN KAVERI.PROPERTYSCHEDULES F ON F.PROPERTYID = E.PROPERTYID 
--LEFT OUTER JOIN KAVERI.PARTYINFO G ON G.PROPERTYID = E.PROPERTYID --AND G.PARTYTYPEID IN (1,2)
--LEFT OUTER join KAVERI.LIABILITYONPROPERTYDETAILS H ON H.documentid = a.documentid
LEFT OUTER join KAVERI.PROPERTYNUMBERDETAILS PR ON D.PROPERTYID = PR.PROPERTYID
--LEFT OUTER join KAVERI.PROPERTYNUMBERDETAILS PR1 ON PR1.propertyid = PR.propertyid  and
--PR.currentnumber LIKE '%'|| PR.currentnumber || '%'
--= PR1.currentnumber LIKE '%'||  PR.currentnumber ||'/%'
--b.currentnumber like '7/%' and a.currentnumber = '7'
--and PR.currentnumber != '' and PR. currentnumber != '0'
LEFT OUTER join KAVERI.STAMPARTICLES S ON S.STAMPARTICLECODE = D.STAMPARTICLECODE
where a.srocode = _srocode and a.bookid = _bookid and a.documentnumber=_documentnumber and 
case when cast(to_char(A.EXECUTIONDATETIME,'MM') as bigint)>3 then cast(to_char(A.EXECUTIONDATETIME,'YYYY')as bigint) ||'-'|| to_char(A.EXECUTIONDATETIME  + interval '1 year','YY')
else cast(to_char(A.EXECUTIONDATETIME,'YYYY')as bigint)-1 ||'-'|| to_char(A.EXECUTIONDATETIME,'YY') end=_finyear
--and PR.DESCRIPTION not like '' and  G.firstname not like '' and G.middlename not like '' and G.lastname not like ''
--and pr.currentnumber not like '' and d.landmark not like '' and s.articlenamee not like ''
and A.FINALREGISTRATIONNUMBER IS NOT NULL-- AND C.BOOKID > 0 AND A.SROCODE > 0
/*GROUP BY A.SROCODE,B.SRONAMEE,A.BOOKID,C.BOOKNAMEENGLISH,A.EXECUTIONDATETIME,
A.DOCUMENTNUMBER,F.SCHEDULETYPE,F.DESCRIPTION,E.CURRENTNUMBER,d.propertyid,h.ORDERNUMBER,h.orderissuedate,
a.documentid,A.FINALREGISTRATIONNUMBER,A.EXECUTIONDATETIME,S.ARTICLENAMEE,D.LANDMARK,
PR.CURRENTNUMBER,PR.DESCRIPTION,c.bookid*/
) app_json ;
return v_data_json;
END;
$$;


ALTER FUNCTION kaveri."fn_fetch_liability_details_json_check-dup"(_srocode bigint, _bookid bigint, _finyear text, _documentnumber bigint) OWNER TO csgadmin;

--
-- Name: fn_fetch_liability_details_rows(bigint, bigint, text, bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_liability_details_rows(_srocode bigint, _bookid bigint, _finyear text, _documentnumber bigint DEFAULT NULL::bigint) RETURNS TABLE(srocode integer, sronamee character varying, bookid integer, bookname character varying, finalregistrationnumber character varying, financial_year text, documentnumber integer, propertyid bigint, property_details text, propertynumberdetails text, liabilitydetails text, claimant text, executant text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
	SELECT 
        A.SROCODE,
        B.SRONAMEE AS SRONAMEE,
        A.Bookid,
        C.BOOKNAMEENGLISH AS BOOKNAME,
        A.finalregistrationnumber,
        CASE
            WHEN CAST(TO_CHAR(A.EXECUTIONDATETIME, 'MM') AS bigint) > 3 
            THEN CAST(TO_CHAR(A.EXECUTIONDATETIME, 'YYYY') AS bigint) || '-' || TO_CHAR(A.EXECUTIONDATETIME + INTERVAL '1 year', 'YY')
            ELSE CAST(TO_CHAR(A.EXECUTIONDATETIME, 'YYYY') AS bigint) - 1 || '-' || TO_CHAR(A.EXECUTIONDATETIME, 'YY')
        END AS FINANCIAL_YEAR,
        A.DOCUMENTNUMBER,
        pm.propertyid,
        array_to_string(
                array_agg(
                    ('(Schedule '::text || COALESCE(tab2.scheduletype, ''::character varying)::text) || 
                    ') '::text || COALESCE(tab2.description, ''::character varying)::text
                ),
                ','::text
        ) AS PROPERTY_DETAILS,
        array_to_string(
                array_agg(h.typenameenglish || ': ' || g.currentnumber), 
                ', '::text
        ) AS PROPERTYNUMBERDETAILS,
        tab4.liability AS liabilitydetails,
        array_to_string(array_agg(
       		(COALESCE(cl.firstname, ''::character varying)::text || 
       		COALESCE(cl.middlename, ''::character varying)::text) || 
       		COALESCE(cl.lastname, ''::character varying)::text
       		), 
       		', '::text
        )AS claimant,
        array_to_string(array_agg(
       		(COALESCE(ec.firstname, ''::character varying)::text || 
       		COALESCE(ec.middlename, ''::character varying)::text) || 
       		COALESCE(ec.lastname, ''::character varying)::text
       		), 
       		', '::text
        )AS executant
    FROM KAVERI.DOCUMENTMASTER A
    LEFT JOIN KAVERI.SROMASTER B ON A.SROCODE = B.SROCODE
        AND A.EXECUTIONDATETIME IS NOT NULL
        AND A.srocode > 0
    LEFT JOIN KAVERI.BOOKTYPEMASTER C ON C.BOOKID = A.BOOKID
    LEFT JOIN KAVERI.PROPERTYMASTER pm ON pm.DOCUMENTID = A.DOCUMENTID
    LEFT JOIN KAVERI.STAMPARTICLES S ON S.STAMPARTICLECODE = pm.STAMPARTICLECODE
    left join kaveri.propertyschedules tab2 on tab2.propertyid = pm.propertyid
    left join kaveri.propertynumberdetails g on g.propertyid = pm.propertyid
    left join kaveri.propertynotypemaster h on h.propertytypeid = g.currentpropertytypeid
    join kaveri.partyinfo cl on cl.applicationnumber =a.applicationnumber and cl.partytypeid = 1
    join kaveri.partyinfo ec on ec.applicationnumber =a.applicationnumber and ec.partytypeid = 2
    LEFT JOIN (
        SELECT 
            numbered_liability.propertyid,
            array_to_string(
                array_agg(
                    numbered_liability.liability_note
                ),
                ',#'
            ) AS liability
        FROM (
            SELECT 
                lp.propertyid,
                'Liability Note ' || ROW_NUMBER() OVER (PARTITION BY lp.propertyid ORDER BY lp.orderdate) || ': Order number: ' || 
                COALESCE(lp.ORDERNUMBER, 'N/A') || 
                ', with note: ' || COALESCE(lp.liabilitynote, 'No note') || 
                ', issued on ' || COALESCE(TO_CHAR(lp.orderdate, 'dd-MM-yyyy'), 'N/A')||
                CASE WHEN lp.iscleared = true THEN ', cleared with note: ' || COALESCE(lp.clearnote, 'No clearing note') ELSE '' END AS liability_note
            FROM kaveri.liabilitydetails_new lp
        ) numbered_liability
        GROUP BY numbered_liability.propertyid
    ) tab4 ON pm.propertyid = tab4.propertyid
   WHERE A.srocode = _srocode
        AND A.bookid = _bookid
        AND A.documentnumber = _documentnumber
        AND CASE
            WHEN CAST(TO_CHAR(A.EXECUTIONDATETIME, 'MM') AS bigint) > 3 
            THEN CAST(TO_CHAR(A.EXECUTIONDATETIME, 'YYYY') AS bigint) || '-' || TO_CHAR(A.EXECUTIONDATETIME + INTERVAL '1 year', 'YY')
            ELSE CAST(TO_CHAR(A.EXECUTIONDATETIME, 'YYYY') AS bigint) - 1 || '-' || TO_CHAR(A.EXECUTIONDATETIME, 'YY')
        END = _finyear
        AND A.FINALREGISTRATIONNUMBER IS NOT null
        group by a.srocode,B.SRONAMEE,A.Bookid,C.BOOKNAMEENGLISH,A.finalregistrationnumber,tab4.liability,A.EXECUTIONDATETIME,A.DOCUMENTNUMBER,pm.propertyid,A.applicationnumber;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_liability_details_rows(_srocode bigint, _bookid bigint, _finyear text, _documentnumber bigint) OWNER TO postgres;

--
-- Name: fn_fetch_liability_details_rows_05112025(bigint, bigint, text, bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_liability_details_rows_05112025(_srocode bigint, _bookid bigint, _finyear text, _documentnumber bigint DEFAULT NULL::bigint) RETURNS TABLE(srocode integer, sronamee character varying, bookid integer, bookname character varying, finalregistrationnumber character varying, financial_year text, documentnumber integer, propertyid bigint, property_details text, propertynumberdetails text, liabilitydetails text, claimant text, executant text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        A.SROCODE,
        B.SRONAMEE AS SRONAMEE,
        A.Bookid,
        C.BOOKNAMEENGLISH AS BOOKNAME,
        A.finalregistrationnumber,
        CASE
            WHEN CAST(TO_CHAR(A.EXECUTIONDATETIME, 'MM') AS bigint) > 3 
            THEN CAST(TO_CHAR(A.EXECUTIONDATETIME, 'YYYY') AS bigint) || '-' || TO_CHAR(A.EXECUTIONDATETIME + INTERVAL '1 year', 'YY')
            ELSE CAST(TO_CHAR(A.EXECUTIONDATETIME, 'YYYY') AS bigint) - 1 || '-' || TO_CHAR(A.EXECUTIONDATETIME, 'YY')
        END AS FINANCIAL_YEAR,
        A.DOCUMENTNUMBER,
        pm.propertyid,
        tab2.col1 AS PROPERTY_DETAILS,
        tab3.propdetails AS PROPERTYNUMBERDETAILS,
        tab4.liability AS liabilitydetails,
        (
            SELECT STRING_AGG(claimantname, ', ') AS claimantname 
            FROM (
                SELECT array_to_string(
                    array_agg(
                        (COALESCE(ec.firstname, ''::character varying)::text || 
                         COALESCE(ec.middlename, ''::character varying)::text) || 
                         COALESCE(ec.lastname, ''::character varying)::text
                    ), 
                    ', '::text
                ) AS claimantname
                FROM kaveri.partyinfo ec
                WHERE ec.applicationnumber::text = A.applicationnumber::text 
                AND ec.partytypeid = 1
                GROUP BY ec.partyid
            ) AS ss
        ) AS claimant,
        (
            SELECT STRING_AGG(executantname, ', ') AS executantname 
            FROM (
                SELECT array_to_string(
                    array_agg(
                        (COALESCE(ec.firstname, ''::character varying)::text || 
                         COALESCE(ec.middlename, ''::character varying)::text) || 
                         COALESCE(ec.lastname, ''::character varying)::text
                    ), 
                    ', '::text
                ) AS executantname
                FROM kaveri.partyinfo ec
                WHERE ec.applicationnumber::text = A.applicationnumber::text 
                AND ec.partytypeid = 2
                GROUP BY ec.partyid
            ) AS ss
        ) AS executant
    FROM KAVERI.DOCUMENTMASTER A
    LEFT JOIN KAVERI.SROMASTER B ON A.SROCODE = B.SROCODE
        AND A.EXECUTIONDATETIME IS NOT NULL
        AND A.srocode > 0
    LEFT JOIN KAVERI.BOOKTYPEMASTER C ON C.BOOKID = A.BOOKID
    LEFT JOIN KAVERI.PROPERTYMASTER pm ON pm.DOCUMENTID = A.DOCUMENTID
    LEFT JOIN KAVERI.STAMPARTICLES S ON S.STAMPARTICLECODE = pm.STAMPARTICLECODE
    LEFT JOIN (
        SELECT 
            f.propertyid,
            array_to_string(
                array_agg(
                    ('(Schedule '::text || COALESCE(f.scheduletype, ''::character varying)::text) || 
                    ') '::text || COALESCE(f.description, ''::character varying)::text
                ),
                ','::text
            ) AS col1
        FROM kaveri.propertyschedules f
        GROUP BY f.propertyid
    ) tab2 ON pm.propertyid = tab2.propertyid
    LEFT JOIN (
        SELECT 
            numbered_liability.propertyid,
            array_to_string(
                array_agg(
                    numbered_liability.liability_note
                ),
                ',#'
            ) AS liability
        FROM (
            SELECT 
                lp.propertyid,
                'Liability Note ' || ROW_NUMBER() OVER (PARTITION BY lp.propertyid ORDER BY lp.orderdate) || ': Order number: ' || 
                COALESCE(lp.ORDERNUMBER, 'N/A') || 
                ', with note: ' || COALESCE(lp.liabilitynote, 'No note') || 
                ', issued on ' || COALESCE(TO_CHAR(lp.orderdate, 'dd-MM-yyyy'), 'N/A')||
                CASE WHEN lp.iscleared = true THEN ', cleared with note: ' || COALESCE(lp.clearnote, 'No clearing note') ELSE '' END AS liability_note
            FROM kaveri.liabilitydetails_new lp
        ) numbered_liability
        GROUP BY numbered_liability.propertyid
    ) tab4 ON pm.propertyid = tab4.propertyid
    LEFT JOIN (
        SELECT 
            g.propertyid,
            array_to_string(
                array_agg(h.typenameenglish || ': ' || g.currentnumber), 
                ', '::text
            ) AS propdetails
        FROM kaveri.propertynotypemaster h
        JOIN kaveri.propertynumberdetails g ON h.propertytypeid = g.currentpropertytypeid
        GROUP BY g.propertyid
    ) tab3 ON pm.propertyid = tab3.propertyid
    WHERE A.srocode = _srocode
        AND A.bookid = _bookid
        AND A.documentnumber = _documentnumber
        AND CASE
            WHEN CAST(TO_CHAR(A.EXECUTIONDATETIME, 'MM') AS bigint) > 3 
            THEN CAST(TO_CHAR(A.EXECUTIONDATETIME, 'YYYY') AS bigint) || '-' || TO_CHAR(A.EXECUTIONDATETIME + INTERVAL '1 year', 'YY')
            ELSE CAST(TO_CHAR(A.EXECUTIONDATETIME, 'YYYY') AS bigint) - 1 || '-' || TO_CHAR(A.EXECUTIONDATETIME, 'YY')
        END = _finyear
        AND A.FINALREGISTRATIONNUMBER IS NOT NULL;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_liability_details_rows_05112025(_srocode bigint, _bookid bigint, _finyear text, _documentnumber bigint) OWNER TO postgres;

--
-- Name: fn_fetch_liability_details_rows_for_clear(bigint, bigint, text, bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_liability_details_rows_for_clear(_srocode bigint, _bookid bigint, _finyear text, _documentnumber bigint DEFAULT NULL::bigint) RETURNS TABLE(liabilityid bigint, srocode integer, sronamee character varying, bookid integer, bookname character varying, finalregistrationnumber character varying, financial_year text, documentnumber integer, propertyid bigint, property_details text, propertynumberdetails text, liabilitydetails text, claimant text, executant text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
		lp.liabilityid,
        A.SROCODE,
        B.SRONAMEE AS SRONAMEE,
        A.Bookid,
        C.BOOKNAMEENGLISH AS BOOKNAME,
        A.finalregistrationnumber,
        CASE
            WHEN CAST(TO_CHAR(A.EXECUTIONDATETIME, 'MM') AS bigint) > 3 
            THEN CAST(TO_CHAR(A.EXECUTIONDATETIME, 'YYYY') AS bigint) || '-' || TO_CHAR(A.EXECUTIONDATETIME + INTERVAL '1 year', 'YY')
            ELSE CAST(TO_CHAR(A.EXECUTIONDATETIME, 'YYYY') AS bigint) - 1 || '-' || TO_CHAR(A.EXECUTIONDATETIME, 'YY')
        END AS FINANCIAL_YEAR,
        A.DOCUMENTNUMBER,
        pm.propertyid,
        tab2.col1 AS PROPERTY_DETAILS,
        tab3.propdetails AS PROPERTYNUMBERDETAILS,
        'Liability Note: Order number ' || COALESCE(lp.ORDERNUMBER, 'N/A') || ' with note ' ||
        COALESCE(lp.liabilitynote, 'No note') || ' issued on ' ||
        COALESCE(TO_CHAR(lp.orderdate, 'dd-MM-yyyy'), 'N/A') AS liabilitydetails,
        (
            SELECT STRING_AGG(claimantname, ', ') AS claimantname 
            FROM (
                SELECT array_to_string(
                    array_agg(
                        (COALESCE(ec.firstname, ''::character varying)::text || 
                         COALESCE(ec.middlename, ''::character varying)::text) || 
                         COALESCE(ec.lastname, ''::character varying)::text
                    ), 
                    ', '::text
                ) AS claimantname
                FROM kaveri.partyinfo ec
                WHERE ec.applicationnumber::text = A.applicationnumber::text 
                AND ec.partytypeid = 1
                GROUP BY ec.partyid
            ) AS ss
        ) AS claimant,
        (
            SELECT STRING_AGG(executantname, ', ') AS executantname 
            FROM (
                SELECT array_to_string(
                    array_agg(
                        (COALESCE(ec.firstname, ''::character varying)::text || 
                         COALESCE(ec.middlename, ''::character varying)::text) || 
                         COALESCE(ec.lastname, ''::character varying)::text
                    ), 
                    ', '::text
                ) AS executantname
                FROM kaveri.partyinfo ec
                WHERE ec.applicationnumber::text = A.applicationnumber::text 
                AND ec.partytypeid = 2
                GROUP BY ec.partyid
            ) AS ss
        ) AS executant
    FROM KAVERI.DOCUMENTMASTER A
    LEFT JOIN KAVERI.SROMASTER B ON A.SROCODE = B.SROCODE
        AND A.EXECUTIONDATETIME IS NOT NULL
        AND A.srocode > 0
    LEFT JOIN KAVERI.BOOKTYPEMASTER C ON C.BOOKID = A.BOOKID
    LEFT JOIN KAVERI.PROPERTYMASTER pm ON pm.DOCUMENTID = A.DOCUMENTID
    LEFT JOIN KAVERI.STAMPARTICLES S ON S.STAMPARTICLECODE = pm.STAMPARTICLECODE
    LEFT JOIN (
        SELECT 
            f.propertyid,
            array_to_string(
                array_agg(
                    ('(Schedule '::text || COALESCE(f.scheduletype, ''::character varying)::text) || 
                    ') '::text || COALESCE(f.description, ''::character varying)::text
                ),
                ','::text
            ) AS col1
        FROM kaveri.propertyschedules f
        GROUP BY f.propertyid
    ) tab2 ON pm.propertyid = tab2.propertyid
    LEFT JOIN (
        SELECT 
            g.propertyid,
            array_to_string(
                array_agg(h.typenameenglish || ': ' || g.currentnumber), 
                ', '::text
            ) AS propdetails
        FROM kaveri.propertynotypemaster h
        JOIN kaveri.propertynumberdetails g ON h.propertytypeid = g.currentpropertytypeid
        GROUP BY g.propertyid
    ) tab3 ON pm.propertyid = tab3.propertyid
    JOIN kaveri.liabilitydetails_new lp ON lp.propertyid = pm.propertyid and lp.iscleared = false
    WHERE A.srocode = _srocode
        AND A.bookid = _bookid
        AND A.documentnumber = _documentnumber
        AND CASE
            WHEN CAST(TO_CHAR(A.EXECUTIONDATETIME, 'MM') AS bigint) > 3 
            THEN CAST(TO_CHAR(A.EXECUTIONDATETIME, 'YYYY') AS bigint) || '-' || TO_CHAR(A.EXECUTIONDATETIME + INTERVAL '1 year', 'YY')
            ELSE CAST(TO_CHAR(A.EXECUTIONDATETIME, 'YYYY') AS bigint) - 1 || '-' || TO_CHAR(A.EXECUTIONDATETIME, 'YY')
        END = _finyear
        AND A.FINALREGISTRATIONNUMBER IS NOT NULL order by lp.orderdate;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_liability_details_rows_for_clear(_srocode bigint, _bookid bigint, _finyear text, _documentnumber bigint) OWNER TO postgres;

--
-- Name: fn_fetch_liability_report_json_check(bigint, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_liability_report_json_check(_srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
BEGIN
select array_to_json(array_agg(row_to_json(app_json))) into v_data_json
from (
select  a.liabilityid, a.srocode,
	s.sronamee as sroname,
	a.issuedate as liabilitydate,
	d.finalregistrationnumber,
	c.documentid,
	d.documentnumber,
	a.liabilitynote,
	a.ordernumber,
	c.propertyid,
	'Schedule '||ps.scheduletype || ' - ' || ps.description as Schedule,
	string_agg(g.currentnumber,', ') propertynumberdetails,
	f.villagenamee,
	a.liabilityfromdate,
a.liabilityadditionalnote,
a.amount,
a.issuedby
    /*( select array_to_json(array_agg(row_to_json(liability_report)))
      from (select  --'report generated from'||' '||_fromdate||' '||_todate,
			c.ordernumber,
			a.liabilitynote,
			a.issuedate as liabilitydate,
			'' as liabilityadditionalnote,
            d.finalregistrationnumber,
			g.currentnumber||','||g.survey_no as propertyschedule,
			g.currentnumber as propertynumberdetails
            --e.villagecode,
			--f.villagenamee 
		   )liability_report ) 
			as liabilityreport*/
	from
kaveri.liabilitydetails a 
left join kaveri.sromaster s on s.srocode = a.srocode
left join kaveri.liabilityonpropertydetails c on c.liabilityid = a.liabilityid
left join kaveri.propertyschedules ps on c.propertyid=ps.propertyid
left join kaveri.documentmaster d on d.documentnumber = c.documentid and d.srocode=a.srocode
 join kaveri.propertymaster e on e.documentid = d.documentid and e.propertyid=c.propertyid
left join kaveri.villagemaster f on f.villagecode = e.villagecode
left join kaveri.propertynumberdetails g on g.propertyid = e.propertyid 
where a.srocode = _srocode and a.isdeleted=false
and a.issuedate between _fromdate and _todate
	group by a.liabilityid, a.srocode, s.sronamee, a.issuedate, d.finalregistrationnumber, c.documentid,
	d.documentnumber, a.liabilitynote, c.propertyid, ps.scheduletype, ps.description, f.villagenamee
--and g.currentnumber||','||g.survey_no is not null and g.currentnumber||','||g.survey_no not like 'string%'
) app_json ;
return v_data_json;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_liability_report_json_check(_srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO csgadmin;

--
-- Name: fn_fetch_liability_report_rows(bigint, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_liability_report_rows(_srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS TABLE(liabilityid bigint, srocode integer, sronamee character varying, liabilitydate timestamp without time zone, finalregistrationnumber character varying, documentnumber integer, liabilitynote text, ordernumber character varying, propertyid bigint, schedule text, propertynumberdetails text, villagenamee character varying, clearnote character varying, liabilityamount numeric, issuedby character varying)
    LANGUAGE plpgsql
    AS $$

BEGIN
    RETURN QUERY
    SELECT 
        a.liabilityid,
        a.srocode,
        s.sronamee AS sronamee,
        a.orderdate AS liabilitydate,
        d.finalregistrationnumber,
        d.documentnumber,
        'Liability Note ' || ROW_NUMBER() OVER (PARTITION BY a.propertyid ORDER BY a.orderdate) || ': Order number: ' || 
        COALESCE(a.ordernumber, 'N/A') || 
        ', with note: ' || COALESCE(a.liabilitynote, 'No note') || 
        ', issued on ' || COALESCE(TO_CHAR(a.orderdate, 'dd-MM-yyyy'), 'N/A') ||
        CASE WHEN a.iscleared = true THEN ', cleared with note: ' || COALESCE(a.clearnote, 'No clearing note') ELSE '' END AS liabilitynote,
        a.ordernumber,
        a.propertyid,
        'Schedule ' || COALESCE(ps.scheduletype, '') || ' - ' || COALESCE(ps.description, '') AS schedule,
		tab.propdetails AS propertynumberdetails,
		f.villagenamee,
        a.clearnote,
        a.liabilityamount,
        a.issuedby
    FROM kaveri.liabilitydetails_new a
    LEFT JOIN kaveri.sromaster s ON s.srocode = a.srocode
    LEFT JOIN kaveri.propertyschedules ps ON a.propertyid = ps.propertyid
	 JOIN kaveri.propertymaster e ON e.propertyid = a.propertyid 
    LEFT JOIN kaveri.documentmaster d ON d.documentid = e.documentid AND d.srocode = a.srocode
    LEFT JOIN kaveri.villagemaster f ON f.villagecode = e.villagecode
    LEFT JOIN (
        SELECT 
            g.propertyid,
            array_to_string(
                array_agg(h.typenameenglish || ': ' || g.currentnumber), 
                ', '::text
            ) AS propdetails
        FROM kaveri.propertynotypemaster h
        JOIN kaveri.propertynumberdetails g ON h.propertytypeid = g.currentpropertytypeid
        GROUP BY g.propertyid
    ) tab ON e.propertyid = tab.propertyid
    WHERE a.srocode = _srocode
        AND a.orderdate BETWEEN _fromdate AND _todate
    GROUP BY 
        a.liabilityid,
        a.srocode,
        s.sronamee,
        a.orderdate,
        d.finalregistrationnumber,
        d.documentnumber,
        a.liabilitynote,
        a.ordernumber,
        a.propertyid,
        ps.scheduletype,
        ps.description,
        f.villagenamee,
        a.clearnote,
        a.liabilityamount,
        a.issuedby,
        a.iscleared,
		tab.propdetails;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_liability_report_rows(_srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_fetch_marriage_lgdmaster1(integer, integer, integer, integer, bigint); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_marriage_lgdmaster1(_statecode integer, _districtcode integer, _talukcode integer, _hoblicode integer DEFAULT NULL::integer, _villagecode bigint DEFAULT NULL::bigint) RETURNS TABLE(statecode integer, statenamee character varying, districtcode integer, districtnamee character varying, talukcode integer, taluknamee character varying, hoblicode integer, hoblinamee character varying, villagecode bigint, villagenamee character varying)
    LANGUAGE plpgsql
    AS $$
begin
if(_statecode = 29) then 
return query
    select _statecode,
            h.statenamee,
            _districtcode,
            d.districtnamee,
            _talukcode,
            e.taluknamee,
            _hoblicode,
            f.hoblinamee,
            _villagecode,
            g.villagenamee             
      from  kaveri.villagemaster g 
      JOIN kaveri.talukmaster e ON e.talukcode = g.talukcode
      JOIN kaveri.hoblimaster f ON f.hoblicode = g.hoblicode
      JOIN kaveri.districtmaster d ON d.districtcode = e.districtcode
      JOIN kaveri.statemaster h ON h.statecode = _statecode
    where h.statecode = _statecode and d.districtcode = _districtcode and  
   e.talukcode =_talukcode and f.hoblicode= _hoblicode and g.villagecode=_villagecode;
    else
    return query
    select _statecode,
            h.statenamee,
            _districtcode,
            d.districtnamee,
            _talukcode,
            e.taluknamee,
            0 as hoblicode,
            ''::character varying as hoblinamee,
            0::bigint as villagecode,
            ''::character varying as villagenamee     
     from kaveri.lgd_talukmaster e
     JOIN kaveri.lgd_districtmaster d ON d.districtcode = e.lgd_districtcode
     JOIN kaveri.lgd_statemaster h ON h.statecode = _statecode 
     where e.talukcode =_talukcode;
   end if;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_marriage_lgdmaster1(_statecode integer, _districtcode integer, _talukcode integer, _hoblicode integer, _villagecode bigint) OWNER TO csgadmin;

--
-- Name: fn_fetch_marriage_mas_idprooftypes(integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_marriage_mas_idprooftypes(_prooftypeid integer) RETURNS TABLE(prooftype character varying, idprooftypeid smallint, description character varying)
    LANGUAGE plpgsql
    AS $$
begin
	
return query
select mp.prooftype ,mi.idprooftypeid ,mi.description 
from kaveri.mas_idprooftypes mi
join kaveri.mas_prooftypes_idproof_mapping mm on mm.idprooftypeid  = mi.idprooftypeid
join kaveri.mas_prooftypes mp on mp.prooftypeid = mm.prooftypeid 
where mm.prooftypeid = _prooftypeid;
end;
$$;


ALTER FUNCTION kaveri.fn_fetch_marriage_mas_idprooftypes(_prooftypeid integer) OWNER TO csgadmin;

--
-- Name: fn_fetch_marriage_wrkflowcount(bigint); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_marriage_wrkflowcount(_srocode bigint) RETURNS TABLE(receivedfromcitizen bigint, allocatedtofda_sda bigint, receivedfromfda_sda_sda bigint, senttocitizenforconfirmations bigint, receivedfromcitizenafterconfirmation bigint, allocatedtoscanfda_sda bigint, readyfordigisign bigint)
    LANGUAGE plpgsql
    AS $$



DECLARE

v_AllocatedtoFDA_SDA bigint;

v_ReceivedfromFDA_SDA_SDA bigint;
AllocatedtoScanFDA_SDA bigint;

--v_array bigint[];

begin 



select Count(*) as ReceivedFromCitizen into ReceivedFromCitizen  from(

select distinct * from kaveri.vw_fetch_mr_sro_dashboard where srocode= _srocode and currentstatus='MR106') receivedfromcit;

    

select Count(*) as AllocatedtoFDA_SDA  into AllocatedtoFDA_SDA from(

select distinct * from kaveri.vw_fetch_mr_sro_dashboard where srocode= _srocode and currentstatus='MR107')allocatedtofda_sda;



select Count(*) as ReceivedfromFDA_SDA_SDA into ReceivedfromFDA_SDA_SDA     from(

select distinct * from kaveri.vw_fetch_mr_sro_dashboard where srocode= _srocode and currentstatus='MR108') sda ;



select Count(*) as SenttocitizenforConfirmations into SenttocitizenforConfirmations  from(

select distinct * from kaveri.vw_fetch_mr_sro_dashboard where srocode= _srocode and currentstatus in ('MR110','MR112','MR113'))SenttocitizenforConfirmation;



select Count(*) as Receivedfromcitizenafterconfirmation into Receivedfromcitizenafterconfirmation  from(

SELECT distinct * FROM kaveri.vw_fetch_mr_sro_dashboard where SROCODE= _srocode and currentstatus ='MR116')Receivedfromcitizenafterconfirmation;



select Count(*) as AllocatedtoScanFDA_SDA  into AllocatedtoScanFDA_SDA from(

select distinct * from kaveri.vw_fetch_mr_sro_dashboard where srocode= _srocode and currentstatus='MR123')allocatedtoscanfda_sda;



select Count(*) as readyfordigiSign into readyfordigiSign  from(

SELECT distinct * FROM kaveri.vw_fetch_mr_sro_dashboard where SROCODE= _srocode and currentstatus in ('MR114','MR124'))AllocatedtoDEo_SD;





return query 

select ReceivedFromCitizen,AllocatedtoFDA_SDA,ReceivedfromFDA_SDA_SDA,SenttocitizenforConfirmations,Receivedfromcitizenafterconfirmation,AllocatedtoScanFDA_SDA,readyfordigiSign;



end;

$$;


ALTER FUNCTION kaveri.fn_fetch_marriage_wrkflowcount(_srocode bigint) OWNER TO csgadmin;

--
-- Name: fn_fetch_masval_pendingapproval_sro(integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_masval_pendingapproval_sro(_valrateheaderid integer) RETURNS TABLE(valrateheaderid bigint, circularinfo text, circularpath text, effectivedate timestamp without time zone, roadcode bigint, roadname character varying, roadnamek character varying, srocode bigint, villagecode bigint, villagename character varying, villagenamek character varying, hoblicode integer, hobliname character varying, sfdaid bigint, masval json)
    LANGUAGE plpgsql
    AS $$

BEGIN
   RETURN QUERY
   SELECT mh.valrateheaderid,
    mh.circularinfo,
    mh.circularpath,
    mh.effectivedate,
    mval.roadcode,
    rm.roadnamee AS roadname,
    rm.roadnamek,
    mval.srocode,
    vm.villagecode,
    vm.villagenamee AS villagename,
    vm.villagenamek,
    h.hoblicode,
    h.hoblinamee AS hobliname,
    mh.sfdaid,
    ( SELECT array_to_json(array_agg(row_to_json(val.*))) AS array_to_json
           FROM ( SELECT 'Agriculture'::text AS propertytype,
                    ra.rate,
                    ra.agrilandtypedesc AS typedesc,
                    ra.rate_val
                   FROM ( SELECT m.roadcode,
                            r.agrilandtypeid,
                            r.measurementcode,
                            r.rate,
                            r.effectivedate,
                            agri_ty.description AS agrilandtypedesc,
                            m.rate AS rate_val
                           FROM kaveri.mas_valratedetail m
                             JOIN kaveri.mas_val_agrilandtypes agri_ty ON m.agrilandtypeid = agri_ty.agrilandtypeid
                             LEFT JOIN ( SELECT ad.roadcode,
                                    ad.agrilandtypeid,
                                    ad.villagecode,
                                    ad.measurementcode,
                                    ad.rate,
                                    ad.effectivedate,
                                    COALESCE(lead(ad.effectivedate, 1) OVER (PARTITION BY ad.roadcode, ad.agrilandtypeid ORDER BY ad.effectivedate), CURRENT_DATE::timestamp without time zone) AS effectivetodate
                                   FROM kaveri.rateagriculturaldetail ad) r ON r.roadcode = m.roadcode AND m.agrilandtypeid = r.agrilandtypeid AND m.propertytypeid = 17 AND CURRENT_DATE >= r.effectivedate AND CURRENT_DATE <= r.effectivetodate
                          WHERE  m.valrateheaderid=_valrateheaderid AND mval.roadcode = m.roadcode AND mval.sfdaid = m.sfdaid AND m.propertytypeid = 17) ra
                  WHERE mval.roadcode = ra.roadcode
                UNION ALL
                 SELECT 'Vacant Land/Building'::text AS propertytype,
                    ra.rate,
                    ra.propertytypename AS typedesc,
                    ra.rate_val
                   FROM ( SELECT m.roadcode,
                            r.propertytypeid,
                            r.measurementcode,
                            r.rate,
                            r.effectivedate,
                            ptm.propertytypename,
                            m.rate AS rate_val
                           FROM kaveri.mas_valratedetail m
                             JOIN kaveri.propertytypemaster ptm ON ptm.propertytypeid = m.propertytypeid
                             LEFT JOIN ( SELECT br.roadcode,
                                    br.propertytypeid,
                                    br.rate,
                                    br.measurementcode,
                                    br.effectivedate,
                                    COALESCE(lead(br.effectivedate, 1) OVER (PARTITION BY br.roadcode, br.propertytypeid ORDER BY br.effectivedate), CURRENT_DATE::timestamp without time zone) AS effectivetodate
                                   FROM kaveri.openbuiltratedetail br) r ON r.roadcode = m.roadcode AND m.propertytypeid <> 17 AND m.agrilandtypeid IS NULL AND m.propertytypeid = r.propertytypeid AND CURRENT_DATE >= r.effectivedate AND CURRENT_DATE <= r.effectivetodate
                          WHERE  m.valrateheaderid=_valrateheaderid AND mval.roadcode = m.roadcode AND mval.sfdaid = m.sfdaid AND m.agrilandtypeid IS NULL AND m.amenitiesid IS NULL) ra
                  WHERE mval.roadcode = ra.roadcode
                UNION ALL
                 SELECT 'Apartment/Flat'::text AS propertytype,
                    ra.rate,
                    ra.namewithamenities AS typedesc,
                    ra.rate_val
                   FROM ( SELECT m.roadcode,
                            r.propertytypeid,
                            r.measurementcode,
                            r.rate,
                            r.effectivedate,
                            ptm.propertytypename,
                            m.amenitiesid,
                            m.floorid,
                            amn.namewithamenities,
                            m.rate AS rate_val
                           FROM kaveri.mas_valratedetail m
                             JOIN kaveri.mas_val_apartmentsamenities amn ON amn.amenitiesid = m.amenitiesid
                             JOIN kaveri.propertytypemaster ptm ON ptm.propertytypeid = m.propertytypeid
                             LEFT JOIN ( SELECT op.roadid AS roadcode,
                                    op.propertytypeid,
                                    op.amenitiesid,
                                    op.floorid,
                                    op.unitid AS measurementcode,
                                    op.rate,
                                    op.effectivedate,
                                    COALESCE(lead(op.effectivedate, 1) OVER (PARTITION BY op.roadid, op.propertytypeid, op.amenitiesid, op.floorid ORDER BY op.effectivedate), CURRENT_DATE::timestamp without time zone) AS effectivetodate
                                   FROM kaveri.mas_val_flatrates op
                                  WHERE op.amenitiesid IS NOT NULL) r ON r.roadcode = m.roadcode AND m.propertytypeid <> 17 AND m.agrilandtypeid IS NULL AND m.propertytypeid = r.propertytypeid AND m.amenitiesid = r.amenitiesid AND m.floorid = r.floorid AND CURRENT_DATE >= r.effectivedate AND CURRENT_DATE <= r.effectivetodate
                          WHERE  m.valrateheaderid=_valrateheaderid AND mval.roadcode = m.roadcode AND mval.sfdaid = m.sfdaid AND m.amenitiesid IS NOT NULL AND m.agrilandtypeid IS NULL) ra
                  WHERE ra.roadcode = mval.roadcode) val) AS masval
   FROM kaveri.mas_valrateheader mh
     JOIN ( SELECT DISTINCT mas_valratedetail.sfdaid,
            mas_valratedetail.srocode,
            mas_valratedetail.roadcode,
            mas_valratedetail.valrateheaderid
           FROM kaveri.mas_valratedetail
          WHERE mas_valratedetail.valrateheaderid IS NOT null and mas_valratedetail.valrateheaderid=_valrateheaderid) mval ON mh.valrateheaderid = mval.valrateheaderid
     JOIN kaveri.roadmaster rm ON rm.roadcode = mval.roadcode
     JOIN kaveri.villagemaster vm ON vm.villagecode = rm.villagecode
     JOIN kaveri.hoblimaster h ON vm.hoblicode = h.hoblicode
     where mh.valrateheaderid =_valrateheaderid;
	 
	 END;
$$;


ALTER FUNCTION kaveri.fn_fetch_masval_pendingapproval_sro(_valrateheaderid integer) OWNER TO postgres;

--
-- Name: fn_fetch_masval_pendingapproval_sro(integer, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_masval_pendingapproval_sro(_valrateheaderid integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
v_data_json json;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
 

SELECT array_to_json(array_agg(row_to_json(arr))) into  v_data_json
from  (
select array_to_json(array_agg(row_to_json(temp))) as data,count(*) as Total from (


SELECT mh.valrateheaderid as requestNo,
    mh.circularinfo,
    mh.circularpath,
    mval.roadcode,
    mh.effectivedate,
    rm.roadnamee AS roadname,
    mval.srocode,
    vm.villagenamee AS villagename,
    h.hoblinamee AS hobliname,
    ( SELECT array_to_json(array_agg(row_to_json(val.*))) AS array_to_json
           FROM ( SELECT 'Agriculture'::text AS propertytype,
                    ra.rate,
                    ra.agrilandtypedesc AS typedesc,
                    ra.rate_val
                   FROM ( SELECT m.roadcode,
                            r.agrilandtypeid,
                            r.measurementcode,
                            r.rate,
                            r.effectivedate,
                            agri_ty.description AS agrilandtypedesc,
                            m.rate AS rate_val
                           FROM kaveri.mas_valratedetail m
                             JOIN kaveri.mas_val_agrilandtypes agri_ty ON m.agrilandtypeid = agri_ty.agrilandtypeid
                             LEFT JOIN ( SELECT ad.roadcode,
                                    ad.agrilandtypeid,
                                    ad.villagecode,
                                    ad.measurementcode,
                                    ad.rate,
                                    ad.effectivedate,
                                    COALESCE(lead(ad.effectivedate, 1) OVER (PARTITION BY ad.roadcode, ad.agrilandtypeid ORDER BY ad.effectivedate), CURRENT_DATE::timestamp without time zone) AS effectivetodate
                                   FROM kaveri.rateagriculturaldetail ad) r ON r.roadcode = m.roadcode AND m.agrilandtypeid = r.agrilandtypeid AND m.propertytypeid = 17 AND CURRENT_DATE >= r.effectivedate AND CURRENT_DATE <= r.effectivetodate
                          WHERE  m.valrateheaderid=_valrateheaderid AND mval.roadcode = m.roadcode AND mval.sfdaid = m.sfdaid AND m.propertytypeid = 17) ra
                  WHERE mval.roadcode = ra.roadcode
                UNION ALL
                 SELECT 'Vacant Land/Building'::text AS propertytype,
                    ra.rate,
                    ra.propertytypename AS typedesc,
                    ra.rate_val
                   FROM ( SELECT m.roadcode,
                            r.propertytypeid,
                            r.measurementcode,
                            r.rate,
                            r.effectivedate,
                            ptm.propertytypename,
                            m.rate AS rate_val
                           FROM kaveri.mas_valratedetail m
                             JOIN kaveri.propertytypemaster ptm ON ptm.propertytypeid = m.propertytypeid
                             LEFT JOIN ( SELECT br.roadcode,
                                    br.propertytypeid,
                                    br.rate,
                                    br.measurementcode,
                                    br.effectivedate,
                                    COALESCE(lead(br.effectivedate, 1) OVER (PARTITION BY br.roadcode, br.propertytypeid ORDER BY br.effectivedate), CURRENT_DATE::timestamp without time zone) AS effectivetodate
                                   FROM kaveri.openbuiltratedetail br) r ON r.roadcode = m.roadcode AND m.propertytypeid <> 17 AND m.agrilandtypeid IS NULL AND m.propertytypeid = r.propertytypeid AND CURRENT_DATE >= r.effectivedate AND CURRENT_DATE <= r.effectivetodate
                          WHERE  m.valrateheaderid=_valrateheaderid AND mval.roadcode = m.roadcode AND mval.sfdaid = m.sfdaid AND m.agrilandtypeid IS NULL AND m.amenitiesid IS NULL) ra
                  WHERE mval.roadcode = ra.roadcode
                UNION ALL
                 SELECT 'Apartment/Flat'::text AS propertytype,
                    ra.rate,
                    ra.namewithamenities AS typedesc,
                    ra.rate_val
                   FROM ( SELECT m.roadcode,
                            r.propertytypeid,
                            r.measurementcode,
                            r.rate,
                            r.effectivedate,
                            ptm.propertytypename,
                            m.amenitiesid,
                            m.floorid,
                            amn.namewithamenities,
                            m.rate AS rate_val
                           FROM kaveri.mas_valratedetail m
                             JOIN kaveri.mas_val_apartmentsamenities amn ON amn.amenitiesid = m.amenitiesid
                             JOIN kaveri.propertytypemaster ptm ON ptm.propertytypeid = m.propertytypeid
                             LEFT JOIN ( SELECT op.roadid AS roadcode,
                                    op.propertytypeid,
                                    op.amenitiesid,
                                    op.floorid,
                                    op.unitid AS measurementcode,
                                    op.rate,
                                    op.effectivedate,
                                    COALESCE(lead(op.effectivedate, 1) OVER (PARTITION BY op.roadid, op.propertytypeid, op.amenitiesid, op.floorid ORDER BY op.effectivedate), CURRENT_DATE::timestamp without time zone) AS effectivetodate
                                   FROM kaveri.mas_val_flatrates op
                                  WHERE op.amenitiesid IS NOT NULL) r ON r.roadcode = m.roadcode AND m.propertytypeid <> 17 AND m.agrilandtypeid IS NULL AND m.propertytypeid = r.propertytypeid AND m.amenitiesid = r.amenitiesid AND m.floorid = r.floorid AND CURRENT_DATE >= r.effectivedate AND CURRENT_DATE <= r.effectivetodate
                          WHERE  m.valrateheaderid=_valrateheaderid AND mval.roadcode = m.roadcode AND mval.sfdaid = m.sfdaid AND m.amenitiesid IS NOT NULL AND m.agrilandtypeid IS NULL) ra
                  WHERE ra.roadcode = mval.roadcode) val) AS masval
   FROM kaveri.mas_valrateheader mh
     JOIN ( SELECT DISTINCT mas_valratedetail.sfdaid,
            mas_valratedetail.srocode,
            mas_valratedetail.roadcode,
            mas_valratedetail.valrateheaderid
           FROM kaveri.mas_valratedetail
          WHERE mas_valratedetail.valrateheaderid IS NOT null and mas_valratedetail.valrateheaderid=_valrateheaderid
		  and (mas_valratedetail.isapproved is null )) mval ON mh.valrateheaderid = mval.valrateheaderid
     JOIN kaveri.roadmaster rm ON rm.roadcode = mval.roadcode
     JOIN kaveri.villagemaster vm ON vm.villagecode = rm.villagecode
     JOIN kaveri.hoblimaster h ON vm.hoblicode = h.hoblicode
     where mh.valrateheaderid =_valrateheaderid 
     

     
     OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY)temp) as arr;
	 return  v_data_json;
	 END;
$$;


ALTER FUNCTION kaveri.fn_fetch_masval_pendingapproval_sro(_valrateheaderid integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_minutebook_deo(text); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_minutebook_deo(p_deoid text) RETURNS TABLE(applicationnum character varying, applicationdate date, applicationtime time without time zone, srocode integer, applicationtypeid integer, servicename character varying, currentstatus character varying, wrkflowstatusnamee text, ispropertydetails boolean, ispartydetails boolean, ispropertyschedule boolean, isvaluationfees boolean, ispaymentdetails boolean, presentdate date, executedate date, pendingdocumentnumber character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
   RETURN QUERY
  select ad.applicationnumber applicationnum,slot.slotbookdate as applicationdate,
  slot.slotbooktime as applicationtime,ad.srocode,ad.applicationtypeid,sm.servicename,
ad.currentstatus,wm.wrkflowstatusnamee,coalesce(dm.ispropertydetails,'false') as ispropertydetails,
coalesce(dm.ispartydetails,'false') as ispartydetails,
coalesce(dm.ispropertyschedule,'false') as ispropertyschedule,
coalesce(dm.isvaluationfees,'false') as isvaluationfees,
coalesce(dm.ispaymentdetails,'false') as ispaymentdetails,
dm.presentdatetime::date presentdate,
dm.executiondatetime::date as executedate,dm.pendingdocumentnumber
from kaveri.ApplicantApplicationdetails ad 
inner join kaveri.documentmaster dm on (dm.applicationnumber = ad.applicationnumber)
inner join (select sl.applicationnumber,sl.sltbookedon, sl.sltbookedon::date as slotbookdate,
			sl.sltbookedon::time as slotbooktime
			from kaveri.slottxn sl
	where sltservicestatus= 1
			and sltbookedon = 
			(select max(sltbookedon) from kaveri.slottxn slt
			 where slt.applicationnumber = sl.applicationnumber)) slot 
						   on slot.applicationnumber= ad.applicationnumber
left outer join kaveri.Wrkflowmaster wm on wm.wrkflowstatusid = ad.currentstatus 
left join Kaveri.servicesmaster sm on ad.applicationtypeid = sm.serviceid 
where ad.assignedto = p_deoid and 
ad.currentstatus in ('CD121')
order by slot.sltbookedon ;

END;
$$;


ALTER FUNCTION kaveri.fn_fetch_minutebook_deo(p_deoid text) OWNER TO csgadmin;

--
-- Name: fn_fetch_module_info(); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_module_info() RETURNS json
    LANGUAGE plpgsql
    AS $$

DECLARE
v_data_json json;
BEGIN
  select json_agg(mdl) as modules into v_data_json from  (select m.moduleid,m.modulename,(select json_agg(sbm) as submodules from
 (select s.submoduleid,s.submodulename,(select json_agg(fbm)as functions from (select f.functionid,f.functionname  from kaveri.functionmaster f 
 where f.moduleid=s.moduleid and f.submoduleid=s.submoduleid ) as fbm)
 from kaveri.submodulemaster s where moduleid=m.moduleid  ) as sbm) 
 
 from kaveri.modulemaster as  m ) as mdl;
 
 return v_data_json;
 
END;

$$;


ALTER FUNCTION kaveri.fn_fetch_module_info() OWNER TO csgadmin;

--
-- Name: fn_fetch_movable_property_details_json_check(text); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_movable_property_details_json_check(_applicationnumber text) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
BEGIN
select row_to_json(app_json) into v_data_json
from (
select
	a.propertytypeid,
    k.applicationnumber,
    (l.propertytypename::text || ' '::text) || a.movablepropertydesc as propertydescription,
    a.propertyid,
    a.stamparticlecode,
    b.articlenamee AS stamparticleselected,
    a.stampruleid,
    c.descriptione AS stampsubarticleselected,
    a.regarticlecode,
    d.articlenamee AS registrationfeearticleselected,
    d.bookid,
    e.booknameenglish AS booknumber,
	j.deedattachpath AS uploaddeeddocument,
    j.executiondatetime AS dateofexecution,
	( select array_to_json(array_agg(row_to_json(feecalculation)))
      from (select 
	a.consideration AS totalconsiderationamount,
    a.govtduty,
    a.noofscanpages::numeric * 2.5 AS scanningfees,
    0 AS denotationofstampduty
	  )feecalculation) as feedetails,
( select array_to_json(array_agg(row_to_json(partyinfodetails)))
      from (select   string_agg(
        CASE
            WHEN f.ispresenter = true THEN concat(f.firstname, f.middlename, f.lastname)
            ELSE NULL::text
        END, ', '::text) AS presenter,
    string_agg(
        CASE
            WHEN f.isexecutor = false THEN concat(f.firstname, f.middlename, f.lastname)
            ELSE NULL::text
        END, ', '::text) AS claimant,
    string_agg(
        CASE
            WHEN f.isorganization = true AND f.isexecutor = true THEN concat(f.firstname, f.middlename, f.lastname)
            ELSE NULL::text
        END, ', '::text) AS executant,
    f.age,
    f.sex,
    f.address,
    f.pan,
    f.profession from
		kaveri.partyinfo f where f.propertyid = a.propertyid
						group by  f.age,
    f.sex,
    f.address,
    f.pan,
    f.profession
		   )partyinfodetails ) 
			as partydetails,
	( select array_to_json(array_agg(row_to_json(witnessdetails)))
      from ( select
	 h.name,
    h.age AS witnessage,
    h.sex AS witnesssex,
    h.address AS witnessaddress  
		  from kaveri.witnessinfo h 
     JOIN  kaveri.partywitness g ON 
			g.witnessid = h.witnessid
			join kaveri.partyinfo p on
			p.partyid = g.partyid
	  )witnessdetails) as witnessinformation,
	( select array_to_json(array_agg(row_to_json(srodetails)))
      from ( select
	 a.srocode,
    i.sronamee  
		  from kaveri.sromaster i where i.srocode = a.srocode
	  )srodetails) as srodetail
	FROM kaveri.propertymaster a
     JOIN kaveri.stamparticles b ON a.stamparticlecode = b.stamparticlecode AND b.stamparticlecode = 5
     JOIN kaveri.stamprules c ON c.stamparticlecode = b.stamparticlecode AND c.stampruleid = 19 AND c.stamparticlecode = 5
     JOIN kaveri.registrationarticles d ON d.regarticlecode = a.regarticlecode AND d.regarticlecode = 72
     JOIN kaveri.booktypemaster e ON e.bookid = d.bookid
     JOIN kaveri.documentmaster j ON j.documentid in (select documentid from kaveri.documentmaster)
     JOIN kaveri.applicantapplicationdetails k ON k.applicationnumber::text = a.applicationnumber::text
     JOIN kaveri.propertytypemaster l ON l.propertytypeid = a.propertytypeid
  --GROUP BY a.propertyid, a.movablepropertydesc, a.stamparticlecode, b.articlenamee, a.stampruleid, c.descriptione, a.regarticlecode, d.articlenamee, d.bookid, e.booknameenglish, a.consideration, a.govtduty, a.noofscanpages, f.age, f.sex, f.address, f.pan, f.profession, f.partyid, h.name, h.age, h.sex, h.address, h.profession, a.srocode, i.sronamee, a.applicationnumber, j.deedattachpath, j.executiondatetime, k.applicationnumber, a.propertytypeid, l.propertytypename;
) app_json ;
return v_data_json;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_movable_property_details_json_check(_applicationnumber text) OWNER TO csgadmin;

--
-- Name: fn_fetch_online_cc_dashboard_count(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_online_cc_dashboard_count(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$

 

DECLARE 
PageOffset INTEGER := 0;
v_data_json json;
v_fromdate date;
v_todate date;

BEGIN	 
--PageOffset := ((pagenumber - 1) * pagesize);
PageOffset := (pagesize*pagenumber) - pagesize;
v_fromdate :=_fromdate;
v_todate :=_todate;
	 
select array_to_json(array_agg(row_to_json(dashboard)))   into v_data_json 

from (select distinct to_char(current_date,'DD-MM-YYYY') as current_date, 

s.sronamee, 

COALESCE(a.srocode, au.kaverisrocode) AS srocode,

concat(to_char(v_fromdate,'DD-MM-YYYY'),' - ',to_char(v_todate,'DD-MM-YYYY'))as date_range, d.districtcode,d.districtnamee,  

count(distinct case when a.currentstatus in ('CC101') then a.applicationnumber else null end) as Application_In_Progress,  

count(distinct case when a.currentstatus in ('CC102') then a.applicationnumber else null end) as Pending_for_Payment,  

count(distinct case when a.currentstatus in ('CC103') then a.applicationnumber else null end) as Ready_for_ESign,  

count(distinct case when a.currentstatus in ('CC104') then a.applicationnumber else null end) as Pending_at_SRO,  

count(distinct case when a.currentstatus in ('CC105') then a.applicationnumber else null end) as Allocated_To_FDA_SDA_From_SRO_For_Preparation,  

count(distinct case when a.currentstatus in ('CC106') then a.applicationnumber else null end) as Allocated_To_FDA_SDA_From_SRO_For_Verification,  

count(distinct case when a.currentstatus in ('CC107') then a.applicationnumber else null end) as Application_Forwarded_To_SRO,  

count(distinct case when a.currentstatus in ('CC108') then a.applicationnumber else null end) as Application_rectification_required,  

count(distinct case when a.currentstatus in ('CC109') then a.applicationnumber else null end) as Application_Digitally_Signed_by_SRO 


from kaveri.applicantapplicationdetails a  

JOIN kaveri.cc_applicationdetails au ON au.applicationnumber::text = a.applicationnumber::text

inner join kaveri.sromaster s on au.kaverisrocode = s.srocode	

join kaveri.districtmaster d on d.districtcode = au.kaveridrocode  

where a.applicationtypeid = 12

and (case when _fromdate is not null and _todate is not null then a.applicationstartdate::date between _fromdate

             and _todate

                     else true 

             end)



and 
 (case when _districtcode <> 0 then s.districtcode = _districtcode
					else
						true
				end)
				
and (case when _srocode <> 0 then au.kaverisrocode =_srocode
					else 
						true
				end)
				

group by  d.districtcode,d.districtnamee, s.sronamee, a.srocode, au.kaverisrocode
order by d.districtnamee asc)as dashboard


limit pagesize offset PageOffset;

return v_data_json; 

END; 

$$;


ALTER FUNCTION kaveri.fn_fetch_online_cc_dashboard_count(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_online_ec_dashboard_count(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_online_ec_dashboard_count(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$

 

DECLARE 
PageOffset INTEGER := 0;
v_data_json json;
v_fromdate date;
v_todate date;

BEGIN	 
--PageOffset := ((pagenumber - 1) * pagesize);
PageOffset := (pagesize*pagenumber) - pagesize;
v_fromdate :=_fromdate;
v_todate :=_todate;
	 
select array_to_json(array_agg(row_to_json(dashboard)))   into v_data_json 

from (select distinct to_char(current_date,'DD-MM-YYYY') as current_date, s.sronamee, s.srocode,
concat(to_char(v_fromdate,'DD-MM-YYYY'),' - ',to_char(v_todate,'DD-MM-YYYY'))as date_range, d.districtcode,d.districtnamee,  

count(distinct case when a.currentstatus in ('CE101') then a.applicationnumber else null end) as Application_in_Progress,  

count(distinct case when a.currentstatus in ('CE102') then a.applicationnumber else null end) as Pending_for_Payment,  

count(distinct case when a.currentstatus in ('CE103') then a.applicationnumber else null end) as Ready_for_ESign,  

count(distinct case when a.currentstatus in ('CE104') then a.applicationnumber else null end) as Pending_at_SRO,  

count(distinct case when a.currentstatus in ('CE105') then a.applicationnumber else null end) as Allocated_To_FDA_SDA_from_SRO,  

count(distinct case when a.currentstatus in ('CE106') then a.applicationnumber else null end) as Application_Prepared_by_SDA_FDA,  

count(distinct case when a.currentstatus in ('CE107') then a.applicationnumber else null end) as Application_verified_by_SDA_FDA,  

count(distinct case when a.currentstatus in ('CE108') then a.applicationnumber else null end) as Application_rectification_required,  

count(distinct case when a.currentstatus in ('CE110') then a.applicationnumber else null end) as Application_eSigned_by_SRO,	  

count(distinct case when a.currentstatus in ('CE138') then a.applicationnumber else null end) as Application_Submitted_to_SDA ,  

count(distinct case when a.currentstatus in ('CE139') then a.applicationnumber else null end) as Application_forwarded_to_FDA ,

count(distinct case when a.currentstatus in ('CE140') then a.applicationnumber else null end) as Application_forwarded_to_SRO  


from kaveri.applicantapplicationdetails a  

JOIN kaveri.ec_applicationdetails au ON au.applicationnumber::text = a.applicationnumber::text

join kaveri.sromaster s on s.srocode = a.srocode  -- and s.districtcode =_districtcode

join kaveri.districtmaster d on d.districtcode = s.districtcode  

where a.applicationtypeid = 13 

and (case when _fromdate is not null and _todate is not null then a.applicationstartdate::date between _fromdate

             and _todate

                     else true 

             end)



and 
 (case when _districtcode <> 0 then s.districtcode = _districtcode
					else
						true
				end)
				
and (case when _srocode <> 0 then s.srocode =_srocode
					else 
						true
				end)
				

group by  d.districtcode,d.districtnamee, s.sronamee, s.srocode
order by d.districtnamee asc)as dashboard


limit pagesize offset PageOffset;

return v_data_json; 

END; 

$$;


ALTER FUNCTION kaveri.fn_fetch_online_ec_dashboard_count(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_party_data_doc_summary(text); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_party_data_doc_summary(_applicationnumber text) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json1 json;
BEGIN

select array_to_json(array_agg(row_to_json(prty))) into v_data_json1
      from (
		select 
		vw_party.applicationnumber,vw_party.partyid,case when (vw_party.aliasname='' or vw_party.aliasname is null)  then  vw_party.name else CONCAT(vw_party.name,', alias:',vw_party.aliasname) end  as partyname,vw_party.age::text, vw_party.address ,vw_party.profession,
		vw_party.phonenumber,vw_party.epic,vw_party.partytypeid,vw_party.partytypename,vw_party.isexecutor,vw_party.ispresenter,vw_party.admissiondate,
		vw_party.section88exemption,vw_party.fingerid,vw_party.thumbpath,vw_party.photopath,vw_party.idprooftypedesc,vw_party.idproofnumber,
		vw_party.relationship,vw_party.relativename,string_agg(wi.name||' '||wi.middlename||' '||wi.lastname,',') as witness_name ,
		vw_party.isEndorsePrinted,vw_party.gender as sex, vw_party.isorganization, vw_party.tanno, vw_party.minorguardianname, vw_party.poaname,
		vw_party.auname, vw_party.auaddress, vw_party.isprivateattendance, vw_party.coveringletterno, vw_party.thumbremarks
		,vw_party.ispartyrefused,vw_party.islateapperance,sl.descriptione as salutation
		from kaveri.vw_fetch_party vw_party 
		left join kaveri.partywitness pw on vw_party.partyid=pw.partyid 
		left join kaveri.witnessinfo wi on pw.witnessid = wi.witnessid 
		left join kaveri.salutationmaster sl on sl.salutationid=vw_party.salutationid
			where vw_party.applicationnumber = _applicationnumber and
			vw_party.partytypeid in (1,2)
			group by vw_party.applicationnumber,vw_party.applicationnumber,vw_party.partyid,vw_party.name ,vw_party.age::text, vw_party.address ,vw_party.profession,
		vw_party.phonenumber,vw_party.epic,vw_party.partytypeid,vw_party.partytypename,vw_party.isexecutor,vw_party.ispresenter,vw_party.admissiondate,
		vw_party.section88exemption,vw_party.fingerid,vw_party.thumbpath,vw_party.photopath,vw_party.idprooftypedesc,vw_party.idproofnumber,
		vw_party.relationship,vw_party.relativename,vw_party.isEndorsePrinted,vw_party.gender, vw_party.isorganization, vw_party.tanno, vw_party.minorguardianname, vw_party.poaname,
		vw_party.auname, vw_party.auaddress, vw_party.isprivateattendance, vw_party.coveringletterno, vw_party.thumbremarks,vw_party.ispartyrefused,vw_party.aliasname
		,vw_party.islateapperance,sl.descriptione
			order by partytypeid) prty;
    
return v_data_json1;

END;
$$;


ALTER FUNCTION kaveri.fn_fetch_party_data_doc_summary(_applicationnumber text) OWNER TO csgadmin;

--
-- Name: fn_fetch_party_details_rule_17_3_json(text, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_party_details_rule_17_3_json(_applicationnumber text, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare
v_data_json json;
pageoffset integer:=0;
v_countrecord int;
v_partytypeid bool;

begin
		
select count(*) into v_countrecord from kaveri.partyinfo p where applicationnumber=_applicationnumber;

pageoffset:=((pagenumber-1) * pagesize);

select row_to_json(party_json) into v_data_json  from (
	select array_to_json(array_agg(row_to_json(partypndetails)))
from (
select distinct a.partyid ,
COALESCE(coalesce(a.firstname,' ')||' '||coalesce(a.middlename,' ')||' '||coalesce(a.lastname,' '), NULL::text)  AS name,
a.partytypeid ,a.address, a.isexecutor, a.ispresenter,v_countrecord, a.salutationid, a.age from
kaveri.partyinfo a
where a.applicationnumber = _applicationnumber
group by a.address, a.isexecutor, a.ispresenter,a.partytypeid,a.firstname,a.middlename,  a.lastname,a.partyid, a.salutationid, a.age

offset pageoffset
fetch next pagesize rows only
 
)partypndetails) party_json;

return v_data_json;

	END;
$$;


ALTER FUNCTION kaveri.fn_fetch_party_details_rule_17_3_json(_applicationnumber text, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_party_forxml(character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_party_forxml(_applicationnumber character varying) RETURNS TABLE(applicationnumber character varying, partyid bigint, srocode integer, sronamee character varying, partytypeid integer, partytypename character varying, isorganization boolean, firstname character varying, middlename character varying, lastname character varying, name text, address text, aliasname character varying, tanno character varying, idproofnumber character varying, idprooftypeid smallint, idprooftypedesc character varying, age integer, gender smallint, relationship character varying, relativename character varying, isexecutor boolean, ispresenter boolean, isconsentwitness boolean, isprivateattendance boolean, admissiondate date, epic character varying, phonenumber character varying, fingerid integer, fingerverificationstatusid smallint, ownerno bigint, photopath character varying, profession character varying, section88exemption boolean, thumbpath character varying, organizationid integer, yearofincorp integer, linkpartyid bigint, housenumber text, pin integer, propertyid bigint, isendorseprinted boolean, auname text, auaddress text, aualiasname character varying, auage integer, ausex smallint, auidprooftypeid smallint, auidprooftypedesc character varying, auidproofnumber character varying, auprofession character varying, poaisorganization boolean, poaname text, poaaddress text, poaage integer, poasex smallint, poaidproofnumber character varying, poatan character varying, poaprofession character varying, poarelationship character varying, poarelativename character varying, poapartytypeid integer, poaidprooftypeid smallint, poaidprooftypedesc character varying, poapartytypename character varying, poayearofincorp integer, orgpoaauthsignfname text, orgpoaauthsignmname text, orgpoaauthsignlname text, minorguardianname text, minorguardianage integer, minorguardianrelationship character varying, minorguardianrelativename character varying, coveringletterno character, section88file character, thumbremarks character varying, ispartyrefused boolean, islateapperance boolean, presenternamee character varying, salutationid smallint, isbiometricrefused boolean, iscitizennotappeared boolean, nameasperaadhar character varying, iscitizenaadharverified boolean, isdeptaadharvalidated boolean, aadhaardeclinereason character varying, minorguardianaadharname text, poanameasperaadhar character varying, transactextacre integer, transactextgunta integer, transactextfgunta numeric, districtcode integer, districtnamee character varying, talukcode integer, taluknamee character varying, statecode integer, statenamee character varying, hoblicode integer, hoblinamee character varying, villagecode bigint, villagenamee character varying, descriptioninenglish character varying, aadharhash character varying, vault_id character varying, ekyctxnno character varying, ekyctimestamp character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN		
return query
SELECT DISTINCT f.applicationnumber,
    a.partyid,
    a.srocode,
    b.sronamee,
    a.partytypeid,
    d.descriptioninenglish AS partytypename,
    a.isorganization,
    a.firstname,
    a.middlename,
    a.lastname,
        CASE
            WHEN au.partytypeid = 4 AND poa.firstname IS NOT NULL THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is rep. by minor guardian ', au.firstname, ' ', au.middlename, ' ', au.lastname, ', whose POA is ', sal_poa.descriptione, poa.firstname, ' ', poa.middlename, ' ', poa.lastname)
            WHEN au.partytypeid = 4 AND poa.firstname IS NULL THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is rep. by minor guardian ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname)
            WHEN au.partytypeid = 5 AND a.isorganization = true THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' POA by ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname, ' is Rep. by ', au.orgpoaauthsignfname, ' ', au.orgpoaauthsignlname)
            WHEN au.partytypeid = 5 AND a.isorganization = false THEN concat(sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname, ' is POA of ', e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
            WHEN au.partytypeid = 9 AND a.isorganization = true AND poa.firstname IS NOT NULL THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is Rep. by ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname, ', whose POA is ', sal_poa.descriptione, poa.firstname, ' ', poa.middlename, ' ', poa.lastname)
            WHEN au.partytypeid = 9 AND a.isorganization = true AND poa.firstname IS NULL THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is Rep. by ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname)
            WHEN au.partytypeid IS NULL AND a.partytypeid = 1 THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
            WHEN au.partytypeid IS NULL AND a.partytypeid = 2 THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
            ELSE NULL::text
        END AS name,
        CASE
            WHEN md.ispendingdocument = true THEN a.address::text
            ELSE concat_ws(' '::text, (((((
            CASE
                WHEN a.housenumber IS NULL THEN ''::text
                ELSE a.housenumber
            END || ', '::text) || a.address::text) || ', '::text) || kaveri.fn_fetch_address_village(a.talukcode::bigint)) || ' - '::text) || a.pin)
        END AS address,
    a.aliasname,
    a.tanno,
        CASE
            WHEN au.partytypeid = 9 THEN au.pan
            ELSE a.pan
        END AS idproofnumber,
        CASE
            WHEN au.partytypeid = 9 THEN au.idprooftypeid
            ELSE a.idprooftypeid
        END AS idprooftypeid,
    id.description AS idprooftypedesc,
        CASE
            WHEN a.age::text >= '0'::text THEN a.age
            ELSE NULL::character varying
        END::integer AS age,
    a.sex AS gender,
        CASE
            WHEN a.isorganization = true AND poa.firstname IS NULL THEN r_au.relatione
            WHEN a.isorganization = true AND poa.firstname IS NOT NULL THEN r_poa.relatione
            WHEN a.age::text < '18'::text THEN r_au.relatione
            ELSE r.relatione
        END AS relationship,
        CASE
            WHEN a.isorganization = true AND poa.firstname IS NULL THEN au.relativename
            WHEN a.isorganization = true AND poa.firstname IS NOT NULL THEN poa.relativename
            WHEN a.age::text < '18'::text THEN au.relativename
            ELSE a.relativename
        END AS relativename,
    a.isexecutor,
    a.ispresenter,
    a.isconsentwitness,
    a.isprivateattendance,
    a.admissiondate::date AS admissiondate,
    a.epic,
    a.phonenumber,
    a.fingerid,
    a.fingerverificationstatusid,
    a.ownerno,
    a.photopath,
    a.profession,
    a.section88exemption,
    a.thumbpath,
    a.organizationid,
    a.yearofincorp,
    a.linkpartyid,
    a.housenumber,
    a.pin,
    a.propertyid,
    a.isendorseprinted,
        CASE
            WHEN au.partytypeid = 9 THEN concat_ws(' '::text, sal_au.descriptione, au.firstname, au.middlename, au.lastname)
            ELSE NULL::text
        END AS auname,
        CASE
            WHEN au.partytypeid = 9 THEN concat_ws(' '::text, au.housenumber, ', '::text, au.address, ', '::text, (kaveri.fn_fetch_address_village(au.talukcode::bigint) || ' - '::text) || au.pin)
            ELSE NULL::text
        END AS auaddress,
        CASE
            WHEN au.partytypeid = 9 THEN au.aliasname
            ELSE NULL::character varying
        END AS aualiasname,
        CASE
            WHEN au.partytypeid = 9 THEN
            CASE
                WHEN au.age::text >= '0'::text THEN au.age
                ELSE NULL::character varying
            END::integer
            ELSE NULL::integer
        END AS auage,
        CASE
            WHEN au.partytypeid = 9 THEN au.sex
            ELSE NULL::smallint
        END AS ausex,
        CASE
            WHEN au.partytypeid = 9 THEN au.idprooftypeid
            ELSE NULL::smallint
        END AS auidprooftypeid,
        CASE
            WHEN au.partytypeid = 9 THEN id_au.description
            ELSE NULL::character varying
        END AS auidprooftypedesc,
        CASE
            WHEN au.partytypeid = 9 THEN au.pan
            ELSE NULL::character varying
        END AS auidproofnumber,
        CASE
            WHEN au.partytypeid = 9 THEN au.profession
            ELSE NULL::character varying
        END AS auprofession,
    poa.isorganization AS poaisorganization,
    concat_ws(' '::text, sal_poa.descriptione, poa.firstname, poa.middlename, poa.lastname) AS poaname,
    concat_ws(' '::text, poa.housenumber, ', '::text, poa.address, ', '::text, (kaveri.fn_fetch_address_village(poa.talukcode::bigint) || ' - '::text) || poa.pin) AS poaaddress,
        CASE
            WHEN poa.age::text >= '0'::text THEN poa.age
            ELSE NULL::character varying
        END::integer AS poaage,
    poa.sex AS poasex,
    poa.pan AS poaidproofnumber,
    poa.tanno AS poatan,
    poa.profession AS poaprofession,
    rel.relatione AS poarelationship,
    poa.relativename AS poarelativename,
    poa.partytypeid AS poapartytypeid,
    poa.idprooftypeid AS poaidprooftypeid,
    id_poa.description AS poaidprooftypedesc,
    poa_type.descriptioninenglish AS poapartytypename,
    poa.yearofincorp AS poayearofincorp,
    poa.orgpoaauthsignfname,
    poa.orgpoaauthsignmname,
    poa.orgpoaauthsignlname,
        CASE
            WHEN au.partytypeid = 4 THEN concat_ws(' '::text, sal_au.descriptione, au.firstname, au.middlename, au.lastname)
            ELSE NULL::text
        END AS minorguardianname,
        CASE
            WHEN au.partytypeid = 4 THEN
            CASE
                WHEN au.age::text >= '0'::text THEN au.age
                ELSE NULL::character varying
            END::integer
            ELSE NULL::integer
        END AS minorguardianage,
        CASE
            WHEN au.partytypeid = 4 THEN r_au.relatione
            ELSE NULL::character varying
        END AS minorguardianrelationship,
        CASE
            WHEN au.partytypeid = 4 THEN au.relativename
            ELSE NULL::character varying
        END AS minorguardianrelativename,
    a.coveringletterno,
    a.section88file,
    a.thumbremarks,
    a.ispartyrefused,
    a.islateapperance,
    a.presenternamee,
    a.salutationid,
    a.isbiometricrefused,
    a.iscitizennotappeared,
    a.nameasperaadhar,
    a.iscitizenaadharverified,
    a.isdeptaadharvalidated,
    a.aadhaardeclinereason,
        CASE
            WHEN au.partytypeid = 4 THEN au.nameasperaadhar::text
            ELSE NULL::text
        END AS minorguardianaadharname,
    poa.nameasperaadhar AS poanameasperaadhar,
    a.transactextacre,
    a.transactextgunta,
    a.transactextfgunta,
    a.districtcode,
    dm.districtnamee,
    a.talukcode,
    ( SELECT t2.taluknamee
           FROM kaveri.talukmaster t2
          WHERE t2.talukcode = a.talukcode) AS taluknamee,
    s.statecode,
    s.statenamee,
    a.hoblicode,
    ( SELECT h2.hoblinamee
           FROM kaveri.hoblimaster h2
          WHERE h2.hoblicode = a.hoblicode) AS hoblinamee,
    a.villagecode,
    ( SELECT v2.villagenamee
           FROM kaveri.villagemaster v2
          WHERE v2.villagecode = a.villagecode) AS villagenamee,
    ( SELECT p2.descriptioninenglish
           FROM kaveri.partytypemaster p2
          WHERE p2.partytypeid = a.partytypeid) AS descriptioninenglish,
    al.aadharhash,
    al.vault_id,
    al.ekyctxnno,
    al.ekyctimestamp
   FROM kaveri.partyinfo a
     JOIN kaveri.applicantapplicationdetails f ON a.applicationnumber::text = f.applicationnumber::text
     LEFT JOIN kaveri.minutebook_data md ON a.applicationnumber::text = md.applicationnumber::text
     JOIN kaveri.sromaster b ON a.srocode = b.srocode
     LEFT JOIN kaveri.partyinfo au ON a.partyid = au.linkpartyid AND (au.partytypeid = ANY (ARRAY[9, 4, 5]))
     LEFT JOIN kaveri.partyinfo poa ON poa.linkpartyid = au.partyid AND (poa.partytypeid = ANY (ARRAY[5]))
     LEFT JOIN kaveri.relationshipmasters rel ON rel.id::text = poa.relationship::text
     LEFT JOIN kaveri.partytypemaster d ON a.partytypeid = d.partytypeid
     LEFT JOIN kaveri.partytypemaster au_type ON au.partytypeid = au_type.partytypeid
     LEFT JOIN kaveri.partytypemaster poa_type ON poa.partytypeid = poa_type.partytypeid
     LEFT JOIN kaveri.salutationmaster e ON a.salutationid = e.salutationid
     LEFT JOIN kaveri.salutationmaster sal_au ON au.salutationid = sal_au.salutationid
     LEFT JOIN kaveri.salutationmaster sal_poa ON sal_poa.salutationid = poa.salutationid
     LEFT JOIN kaveri.mas_idprooftypes id ON id.idprooftypeid = a.idprooftypeid
     LEFT JOIN kaveri.mas_idprooftypes id_au ON id_au.idprooftypeid = au.idprooftypeid
     LEFT JOIN kaveri.mas_idprooftypes id_poa ON id_poa.idprooftypeid = poa.idprooftypeid
     LEFT JOIN kaveri.relationshipmasters r ON r.id::text = a.relationship::text
     LEFT JOIN kaveri.relationshipmasters r_au ON r_au.id::text = au.relationship::text
     LEFT JOIN kaveri.relationshipmasters r_poa ON r_poa.id::text = poa.relationship::text
     LEFT JOIN kaveri.lgd_districtmaster dm ON a.districtcode = dm.districtcode
     LEFT JOIN kaveri.lgd_statemaster s ON dm.lgdstatecode = s.statecode
     LEFT JOIN kaveri.aadhar_authentication_log al ON al.partyid = a.partyid
  WHERE a.applicationnumber =_applicationnumber;
  
  end;
  $$;


ALTER FUNCTION kaveri.fn_fetch_party_forxml(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_party_schedules_data(text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_party_schedules_data(_applicationnumber text) RETURNS TABLE(propertyid bigint, partyid bigint, firstname character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        ps.propertyid,
        pi.partyid,
        pi.firstname
    FROM kaveri.partyschedules ps
    JOIN kaveri.propertymaster pm ON ps.propertyid = pm.propertyid
    LEFT JOIN kaveri.partyinfo pi ON pi.partyid = ps.partyid
    WHERE pm.applicationnumber = _applicationnumber
      AND pi.partytypeid = 1
    ORDER BY ps.propertyid, pi.partyid;

END;
$$;


ALTER FUNCTION kaveri.fn_fetch_party_schedules_data(_applicationnumber text) OWNER TO postgres;

--
-- Name: fn_fetch_party_witness_json(text); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_party_witness_json(_applicationnumber text) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 

--p_witnessdetails kaveri.witnessinfo1_input[] DEFAULT NULL::kaveri.witnessinfo1_input[]

v_data_json json;
BEGIN


 select row_to_json(app_json) as fn_fetch_party_witness_json   into v_data_json

from ( 
select array_to_json(array_agg(row_to_json(data_json)))

from (
SELECT 
   -- a.partyid,
   -- (((e.firstname::text || ' '::text) || e.middlename::text) || ' '::text) || e.lastname::text AS partyname,
    --b.name,
	
	( select array_to_json(array_agg(row_to_json(NameAndParty)))
	from (
	 select x.partyid,
     (((y.firstname::text || ' '::text) || y.middlename::text) || ' '::text) || y.lastname::text AS name
	FROM 
	-- kaveri.witnessinfo b LEFT JOIN 
     kaveri.partywitness x   -- ON    b.witnessid = a.witnessid
     Inner JOIN kaveri.partyinfo y ON y.partyid = x.partyid  and b.witnessid = x.witnessid
	where 	y.applicationnumber = b.applicationnumber  and 
			y.applicationnumber =	_applicationnumber and 
						a.partyid =  x.partyid
	) NameAndParty ) as PartyIdAndName ,
	
    --b.middlename,
   -- b.lastname,
    b.age,
    b.address,
    b.sex,
    b.profession,
    b.witnessid,
    b.registrationid,
    b.dateofbirth,
    b.status,
    b.phoneno,
    b.relation,
    b.mothername,
    b.fathersname,
    b.srocode,
    b.applicationnumber,
    b.verified,
    b.issroapproved,
    b.statecode,
    b.districtcode,
    b.talukcode,
    b.hoblicode,
    b.villagecode,
    b.relativename,
    b.pincode,
    b.houseno,
    b.iscliment,
    b.isexicutent
   FROM kaveri.witnessinfo b
     LEFT JOIN kaveri.partywitness a ON b.witnessid = a.witnessid
     LEFT JOIN kaveri.partyinfo e ON e.partyid = a.partyid  
	where 			b.applicationnumber = _applicationnumber 
) data_json  ) app_json ;

return v_data_json;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_party_witness_json(_applicationnumber text) OWNER TO csgadmin;

--
-- Name: fn_fetch_partydetails(bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_partydetails(_partyid bigint) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_data json;
	
BEGIN
	select row_to_json(ss) into v_data from (select a.applicationnumber ,
		a.partyid ,a.linkpartyid ,a.partytypeid ,
		a.firstname, a.middlename ,a.lastname ,
		concat(a.firstname,' ',a.middlename,' ',a.lastname) as name,
		a.aadharhash ,a.vaultid ,a.nameasperaadhar ,
		a.pan,a.isorganization ,a.relativename ,a.phonenumber,a.idprooftypeid,

		au.partyid as fl_partyid,au.linkpartyid as fl_linkpartyid,au.partytypeid as fl_partytypeid ,
		au.firstname as fl_firstname, au.middlename as fl_middlename ,au.lastname as fl_lastname,
		concat(au.firstname,' ',au.middlename,' ',au.lastname) as fl_name,
		au.aadharhash as fl_aadharhash,au.vaultid as fl_vaultid ,au.nameasperaadhar as fl_nameasperaadhar ,
		au.isorganization as fl_isorganization,au.orgpoaauthsignfname as fl_orgpoaauthsignfname,au.orgpoaauthsignmname as fl_orgpoaauthsignmname,au.orgpoaauthsignlname as fl_orgpoaauthsignlname,au.pan as fl_pan,
		au.relativename as fl_relativename,au.phonenumber as fl_phonenumber,au.idprooftypeid as fl_idprooftypeid ,

		poa.partyid as sl_partyid,poa.linkpartyid as sl_linkpartyid,poa.partytypeid as sl_partytypeid ,
		poa.firstname as sl_firstname, poa.middlename as sl_middlename ,poa.lastname as sl_lastname,
		concat(poa.firstname,' ',poa.middlename,' ',poa.lastname) as sl_name,
		poa.aadharhash as sl_aadharhash,poa.vaultid as sl_vaultid ,poa.nameasperaadhar as sl_nameasperaadhar ,
		poa.isorganization as sl_isorganization,poa.orgpoaauthsignfname as sl_orgpoaauthsignfname,poa.orgpoaauthsignmname as sl_orgpoaauthsignmname,poa.orgpoaauthsignlname as sl_orgpoaauthsignlname,poa.pan as sl_pan,
		poa.relativename as sl_relativename,poa.phonenumber as sl_phonenumber,poa.idprooftypeid as sl_idprooftypeid 

	FROM kaveri.partyinfo a
	JOIN kaveri.applicantapplicationdetails f ON a.applicationnumber::text = f.applicationnumber::text
	LEFT JOIN kaveri.partyinfo au ON a.partyid = au.linkpartyid AND (au.partytypeid = ANY (ARRAY[9, 4, 5]))
	LEFT JOIN kaveri.partyinfo poa ON au.partyid = poa.linkpartyid AND (poa.partytypeid = ANY (ARRAY[5]))
	where a.partyid = _partyid)ss ;
return v_data;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_partydetails(_partyid bigint) OWNER TO postgres;

--
-- Name: fn_fetch_partyinfo_documentsummary_json_1(text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_partyinfo_documentsummary_json_1(_applicationnumber text) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json1 json;
BEGIN

select array_to_json(array_agg(row_to_json(prty))) into v_data_json1
      from (
		select 
		vw_party.applicationnumber,vw_party.partyid,case when (vw_party.aliasname='' or vw_party.aliasname is null)  then  vw_party.name else CONCAT(vw_party.name,', alias:',vw_party.aliasname) end  as partyname,vw_party.age, vw_party.address ,vw_party.profession,
		vw_party.phonenumber,vw_party.epic,vw_party.partytypeid,vw_party.partytypename,vw_party.isexecutor,vw_party.ispresenter,vw_party.admissiondate,
		vw_party.section88exemption,vw_party.fingerid,vw_party.thumbpath,vw_party.photopath,vw_party.idprooftypedesc,vw_party.idproofnumber,
		vw_party.relationship,vw_party.relativename,string_agg(wi.name||' '||wi.middlename||' '||wi.lastname,',') as witness_name ,
		vw_party.isEndorsePrinted,vw_party.gender as sex, vw_party.isorganization, vw_party.tanno, vw_party.minorguardianname, vw_party.poaname,
		vw_party.auname, vw_party.auaddress, vw_party.isprivateattendance, vw_party.coveringletterno, vw_party.thumbremarks,vw_party.ispartyrefused 
		from kaveri.vw_fetch_party vw_party 
		left join kaveri.partywitness pw on vw_party.partyid=pw.partyid 
		left join kaveri.witnessinfo wi on pw.witnessid = wi.witnessid 
			where vw_party.applicationnumber = _applicationnumber and
			vw_party.partytypeid in (1,2)
			group by vw_party.applicationnumber,vw_party.applicationnumber,vw_party.partyid,vw_party.name ,vw_party.age, vw_party.address ,vw_party.profession,
		vw_party.phonenumber,vw_party.epic,vw_party.partytypeid,vw_party.partytypename,vw_party.isexecutor,vw_party.ispresenter,vw_party.admissiondate,
		vw_party.section88exemption,vw_party.fingerid,vw_party.thumbpath,vw_party.photopath,vw_party.idprooftypedesc,vw_party.idproofnumber,
		vw_party.relationship,vw_party.relativename,vw_party.isEndorsePrinted,vw_party.gender, vw_party.isorganization, vw_party.tanno, vw_party.minorguardianname, vw_party.poaname,
		vw_party.auname, vw_party.auaddress, vw_party.isprivateattendance, vw_party.coveringletterno, vw_party.thumbremarks,vw_party.ispartyrefused,vw_party.aliasname
			order by partytypeid) prty;
    
return v_data_json1;

END;
$$;


ALTER FUNCTION kaveri.fn_fetch_partyinfo_documentsummary_json_1(_applicationnumber text) OWNER TO postgres;

