--
-- Name: fn_fetch_pending_regnumber(integer, character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_pending_regnumber(_srocode integer, _applicationnumber character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$
DECLARE
   v_regnumber text;
   v_serialnumber bigint;
   v_pendingnumber text default null;
    v_shortname character varying(50);  
   V_FINYEAR character varying(50);
    v_BOOKID bigint;  
BEGIN

V_FINYEAR:=(case when EXTRACT(MONTH FROM CURRENT_DATE) <= 3 then 
			to_CHAR(current_date + interval '-12 month', 'YYYY') || 
'-' || to_char(CURRENT_DATE, 'YY') else to_char(CURRENT_DATE, 'YYYY') 
			||'-' || to_char(current_date + interval '12 month', 'YY') end );

select dm.pendingdocumentnumber,dm.bookid,sro.shortnamee,coalesce(srl.pendingserial,0)+1
into v_pendingnumber,v_BOOKID,v_shortname,v_serialnumber
from kaveri.documentmaster dm 
inner join kaveri.sromaster  sro on (dm.srocode=sro.srocode) 
left join kaveri.sroserialmaster srl on (srl.srocode=dm.srocode and srl.bookid=dm.bookid and srl.finyear = V_FINYEAR)
where dm.applicationnumber = _applicationnumber and dm.srocode= _srocode limit 1;
/*
select dm.pendingdocumentnumber,presentdatetime::date,sm.servicename into 
pendingregnumber,presentdate,applicationtype
from kaveri.documentmaster dm 
inner join kaveri.applicantapplicationdetails appd on (dm.applicationnumber = appd.applicationnumber)
left join kaveri.servicesmaster sm on (appd.applicationtypeid = sm.serviceid)  
where dm.applicationnumber = _applicationnumber and dm.srocode= _srocode; */

if (v_pendingnumber is null) then	
v_regnumber:= 'P-'||to_char(v_serialnumber,'fm00000')||'-'||v_shortname||'-'||V_FINYEAR;
	v_pendingnumber := v_regnumber;
	update kaveri.documentmaster set pendingdocumentnumber= v_regnumber,
	presentdatetime = Current_timestamp
	where applicationnumber = _applicationnumber and srocode= _srocode
	and pendingdocumentnumber is null;
	update kaveri.applicantapplicationdetails set registrationstartdate= Current_timestamp
	where applicationnumber = _applicationnumber and srocode= _srocode;
end if;
v_pendingnumber = regexp_replace(v_pendingnumber, '^([^-]*-[^-]*)-.*$', '\1') ;

return _applicationnumber;

END;
$_$;


ALTER FUNCTION kaveri.fn_fetch_pending_regnumber(_srocode integer, _applicationnumber character varying) OWNER TO csgadmin;

--
-- Name: fn_fetch_pending_sro_appnum(integer, character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_pending_sro_appnum(_srocode integer, _currentstatus character varying) RETURNS TABLE(applicationnum character varying, applicationdate timestamp without time zone, applicationtime text, srocode integer, applicationtypeid integer, servicename character varying, currentstatus character varying, wrkflowstatusnamee text, sfdaid bigint, username text, sakalanumber character varying, remarks text, issubregistrarallocate boolean, articlenamee character varying, ispaymentdone boolean, regarticlecode integer, ispaperless boolean, documentid bigint, isdigitallyexecuted boolean, uploaddocdeedpath text, uploadthumbregisterpath character varying)
    LANGUAGE plpgsql
    AS $$
begin
	if (_currentstatus in ('CD102', 'CD103', 'CD104', 'CD106', 'CD119', 'CD121', 'CD134', 'CD141', 'CD142'))
	then	
	return query
	SELECT DISTINCT ad.applicationnumber AS applicationnum,
    t.crtdt AS applicationdate,
    to_char(COALESCE(t.crtdt, ad.applicationdate), 'HH12:MI:SS AM'::text) AS applicationtime,
    ad.srocode,
    ad.applicationtypeid,
    sm.servicename,
    ad.currentstatus,
    wm.wrkflowstatusnamee,
    ad.sfdaid,
    usr.username,
    dm.gscno AS sakalanumber,
    ad.remarks,
    sn.issubregistrarallocateapp AS issubregistrarallocate,
    rg.articlenamee,
--        CASE
--            WHEN ad.applicationnumber::text = fk.applicationnumber::text THEN true
--            ELSE false
--        END AS ispaymentdone
	false as ispaymentdone,
	dm.regarticlecode,
	-- paperless change
	ad.ispaperless,
	dm.documentid,
	dm.isdigitallyexecuted,
	dm.uploaddocdeedpath,
	dm.uploadthumbregisterpath
   FROM kaveri.applicantapplicationdetails ad
    left JOIN (SELECT ss.applicationnumber,
            ss.crtdt
--            ss.wrkflowstatusid,
--            ss.srocode
           FROM (SELECT row_number() OVER (PARTITION BY t_1.applicationnumber ORDER BY t_1.activityorder DESC) AS rnk,
                    t_1.applicationnumber,
--                    t_1.wrkflowstatusid,
--                    t_1.activityorder,
                    t_1.crtdt
--                    t_1.srocode
                   FROM kaveri.applicationaudit t_1
                  where t_1.applicationnumber in (select ass.applicationnumber from kaveri.applicantapplicationdetails ass where ass.srocode=_srocode 
					and ass.currentstatus=_currentstatus and ass.isdeleted=false)  and t_1.wrkflowstatusid='CD102'
                ) ss
          WHERE ss.rnk = 1 ) t ON t.applicationnumber = ad.applicationnumber 
     JOIN kaveri.documentmaster dm ON dm.applicationnumber = ad.applicationnumber
     LEFT JOIN kaveri.vw_department_users usr ON usr.userid = ad.sfdaid
     JOIN kaveri.registrationarticles rg ON dm.regarticlecode = rg.regarticlecode
     JOIN kaveri.wrkflowmaster wm ON wm.wrkflowstatusid = ad.currentstatus
     JOIN kaveri.servicesmaster sm ON ad.applicationtypeid = sm.serviceid
  left  JOIN kaveri.propertymaster pm ON pm.applicationnumber = ad.applicationnumber
   left  JOIN kaveri.stamprulesflag sn ON pm.stampruleid = sn.stampruleid
--  Commented on 2024-10-16 as all the applications in the below table have been either completed or deleted and there are no pending application with the citizens
--     LEFT JOIN kaveri.feesrequired_paymentchk fk ON ad.applicationnumber::text = fk.applicationnumber::text --
  WHERE ad.srocode = _srocode and ad.isdeleted = false and ad.currentstatus=_currentstatus 
 order by applicationdate;
end if;

END;
$$;


ALTER FUNCTION kaveri.fn_fetch_pending_sro_appnum(_srocode integer, _currentstatus character varying) OWNER TO postgres;

--
-- Name: fn_fetch_pending_sro_appnum_audit(integer, character varying[]); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_pending_sro_appnum_audit(_srocode integer, _currentstatus character varying[]) RETURNS TABLE(applicationnum character varying, applicationdate timestamp without time zone, applicationtime text, srocode integer, applicationtypeid integer, servicename character varying, currentstatus character varying, wrkflowstatusnamee text, sfdaid bigint, username text, sakalanumber character varying, remarks text, issubregistrarallocate boolean, articlenamee character varying, ispaymentdone boolean)
    LANGUAGE plpgsql
    AS $$
declare

--v_status character varying[];
begin

--v_status=_currentstatus;	
return query
SELECT DISTINCT ad.applicationnumber AS applicationnum,
    t.crtdt AS applicationdate,
    to_char(COALESCE(t.crtdt, ad.applicationdate), 'HH12:MI:SS AM'::text) AS applicationtime,
    ad.srocode,
    ad.applicationtypeid,
    sm.servicename,
    ad.currentstatus,
    wm.wrkflowstatusnamee,
    ad.sfdaid,
    usr.username,
    dm.gscno AS sakalanumber,
    ad.remarks,
    sn.issubregistrarallocateapp AS issubregistrarallocate,
    rg.articlenamee,
        CASE
            WHEN ad.applicationnumber::text = fk.applicationnumber::text THEN true
            ELSE false
        END AS ispaymentdone
   FROM kaveri.applicantapplicationdetails ad
    left JOIN (SELECT ss.applicationnumber,
            ss.crtdt,
            ss.wrkflowstatusid,
            ss.srocode
           FROM (SELECT row_number() OVER (PARTITION BY t_1.applicationnumber ORDER BY t_1.activityorder DESC) AS rnk,
                    t_1.applicationnumber,
                    t_1.wrkflowstatusid,
                    t_1.activityorder,
                    t_1.crtdt,
                    t_1.srocode
                   FROM kaveri.applicationaudit t_1
                 -- where t_1.srocode = _srocode and t_1.wrkflowstatusid::text = ANY (ARRAY['CD102'::character varying::text, 'CD142'::character varying::text, 'CD103'::character varying::text, 'CD104'::character varying::text])
                  where t_1.srocode = _srocode and t_1.wrkflowstatusid::text = ANY (ARRAY['CD141'::character varying::text,'CD142'::character varying::text])
                ORDER BY t_1.crtdt) ss
          WHERE ss.rnk = 1 and ss.srocode = _srocode) t ON t.applicationnumber::text = ad.applicationnumber::text
     JOIN kaveri.documentmaster dm ON dm.applicationnumber::text = ad.applicationnumber::text
     LEFT JOIN kaveri.vw_department_users usr ON usr.userid = ad.sfdaid
     JOIN kaveri.registrationarticles rg ON dm.regarticlecode = rg.regarticlecode
     JOIN kaveri.wrkflowmaster wm ON wm.wrkflowstatusid::text = ad.currentstatus::text
     JOIN kaveri.servicesmaster sm ON ad.applicationtypeid = sm.serviceid
  left  JOIN kaveri.propertymaster pm ON pm.applicationnumber::text = ad.applicationnumber::text
   left  JOIN kaveri.stamprulesflag sn ON pm.stampruleid = sn.stampruleid
     LEFT JOIN kaveri.feesrequired_paymentchk fk ON ad.applicationnumber::text = fk.applicationnumber::text
  WHERE ad.currentstatus::text = ANY (ARRAY['CD102'::text, 'CD103'::text, 'CD104'::text, 'CD106'::text, 'CD119'::text, 'CD121'::text, 'CD134'::text, 'CD141'::text, 'CD142'::text])
  and ad.srocode = _srocode and ad.currentstatus = ANY (ARRAY[_currentstatus]) and ad.isdeleted = false
 order by applicationdate;

END;
$$;


ALTER FUNCTION kaveri.fn_fetch_pending_sro_appnum_audit(_srocode integer, _currentstatus character varying[]) OWNER TO postgres;

--
-- Name: fn_fetch_pending_sro_appnum_filing(integer, character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_pending_sro_appnum_filing(_srocode integer, _currentstatus character varying) RETURNS TABLE(applicationnum character varying, applicationdate timestamp without time zone, applicationtime text, srocode integer, applicationtypeid integer, currentstatus character varying, wrkflowstatusnamee text, sfdaid bigint, fdausername text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (_currentstatus IN ('CD102', 'CD110', 'CD111', 'CD103', 'CD143', 'CD104', 'CD115')) THEN
        RETURN QUERY
        SELECT DISTINCT
            ad.applicationnumber AS applicationnum,
            ad.applicationdate AS applicationdate,
            TO_CHAR(ad.applicationdate, 'HH12:MI:SS AM') AS applicationtime,
            ad.srocode,
            ad.applicationtypeid,
            ad.currentstatus,
            wm.wrkflowstatusnamee,
            ad.sfdaid,
            usr.username AS fdausername
        FROM kaveri.applicantapplicationdetails ad
        LEFT JOIN kaveri.vw_department_users usr ON usr.userid = ad.sfdaid
        JOIN kaveri.wrkflowmaster wm ON wm.wrkflowstatusid = ad.currentstatus
        WHERE ad.srocode = _srocode
        AND ad.isdeleted = FALSE
        AND ad.currentstatus = _currentstatus
        ORDER BY ad.applicationdate;
    END IF;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_pending_sro_appnum_filing(_srocode integer, _currentstatus character varying) OWNER TO postgres;

--
-- Name: fn_fetch_pending_sro_appnum_filing(integer, character varying, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_pending_sro_appnum_filing(_srocode integer, _currentstatus character varying, _bookid integer, _applicationtypeid integer) RETURNS TABLE(applicationnum character varying, applicationdate timestamp without time zone, applicationtime text, regsrocode integer, srocode integer, applicationtypeid integer, currentstatus character varying, wrkflowstatusnamee text, sfdaid bigint, fdausername text, deoid bigint, ordernumber character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (_currentstatus IN ('BK101', 'BK102', 'BK103', 'BK104', 'BK113','BK107')) THEN
        RETURN QUERY
        SELECT DISTINCT
            ad.applicationnumber AS applicationnum,
            ad.applicationstartdate AS applicationdate,
            TO_CHAR(ad.applicationstartdate, 'HH12:MI:SS AM') AS applicationtime,
			ad.regsrocode,
            ad.srocode,
            ad.applicationtypeid,
            ad.currentstatus,
            wm.wrkflowstatusnamee,
            ad.sfdaid,
            usr.username AS fdausername,
			ad.deoid,
			CASE WHEN _bookid = 14 THEN fb.order_number ELSE NULL END AS ordernumber
        FROM kaveri.applicantapplicationdetails ad
        LEFT JOIN kaveri.vw_department_users usr ON usr.userid = ad.sfdaid
        JOIN kaveri.wrkflowmaster wm ON wm.wrkflowstatusid = ad.currentstatus
		LEFT JOIN kaveri.filing_book1 fb ON (_bookid = 14 AND ad.applicationnumber = fb.applicationnumber)
        WHERE ad.srocode = _srocode
		AND ad.bookid = _bookid
		AND ad.applicationtypeid = _applicationtypeid
        AND ad.isdeleted = FALSE
        AND ad.currentstatus = _currentstatus
        ORDER BY ad.applicationstartdate;
    END IF;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_pending_sro_appnum_filing(_srocode integer, _currentstatus character varying, _bookid integer, _applicationtypeid integer) OWNER TO postgres;

--
-- Name: fn_fetch_pendingdocument_chk(integer, character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_pendingdocument_chk(_srocode integer, _pendingdocumentnumber character varying) RETURNS TABLE(note text)
    LANGUAGE plpgsql
    AS $$

declare 
v_cnt int;
--v_note varchar(100);

begin 
	
	select count(*) into v_cnt from kaveri.k1pendingregistrationdata 
	where srocode = _srocode and pendingdocumentnumber =_pendingdocumentnumber;
	
	if(v_cnt = 1)then
	return query
	
	select 'This document has been already been retrived in'||' '||coalesce(c.email,'')||' '||'account, Kindly connect with the'||' '||coalesce(c.firstname,'')||' '||coalesce(c.middlename,'')||' '||coalesce(c.lastname,'') as note
	from kaveri.k1pendingregistrationdata k
	join kaveri.applicantapplicationdetails a on a.applicationnumber = k.applicationnumber 
	join kaveri.citizenmaster c on c.citizenid = a.citizenid
	where k.srocode = _srocode and k.pendingdocumentnumber =_pendingdocumentnumber;
--	returning note into v_note;
	
	else
	raise notice 'No data';
end if;
end;

$$;


