--
-- Name: fn_fetch_permission_by_role(integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_permission_by_role(_rollid integer) RETURNS json
    LANGUAGE plpgsql
    AS $$

DECLARE

v_data_json  json;

BEGIN 

select array_to_json(array_agg(row_to_json(tmp))) INTO
v_data_json from 
(select rmfm.rollid,rmfm.moduleid,m.modulename,rmfm.submoduleid,s.submodulename,rmfm.functionid,f.functionname  
from kaveri.role_module_function_mapping  rmfm
join kaveri.modulemaster m on rmfm.moduleid=m.moduleid 
left join kaveri.submodulemaster s on rmfm.submoduleid=s.submoduleid and rmfm.moduleid=s.moduleid 
left join kaveri.functionmaster f on rmfm.functionid=f.functionid  and rmfm.moduleid=f.moduleid and rmfm.submoduleid=f.submoduleid 
where rmfm.rollid=_rollid  ) as tmp;

	
 
 

return v_data_json;

END;

$$;


ALTER FUNCTION kaveri.fn_fetch_permission_by_role(_rollid integer) OWNER TO csgadmin;

--
-- Name: fn_fetch_prev_pendingdocscnt(character varying, bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_prev_pendingdocscnt(_applicationnumber character varying, _srocode bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $$

declare
v_crtdt timestamp;
v_cnt int;
v_wrkflowstatus varchar;
begin
--select to_char(crtdt,'YYYY-MM-HH HH:MM:SS:MS')::timestamp,wrkflowstatusid into v_crtdt,v_wrkflowstatus 
--from kaveri.applicationaudit where applicationnumber=_applicationnumber 
----and wrkflowstatusid in ('CD102','CD104','CD142')
--and wrkflowstatusid in ('CD102')
--order by crtdt desc limit 1;

select crtdt ,wrkflowstatusid into v_crtdt,v_wrkflowstatus 
from kaveri.applicationaudit where applicationnumber=_applicationnumber 
--and wrkflowstatusid in ('CD102','CD104','CD142')
and wrkflowstatusid in ('CD102')
order by crtdt desc limit 1;


if(v_crtdt is not null)
then
select count(distinct t.applicationnumber) into v_cnt from (select applicationnumber,crtdt,wrkflowstatusid from (
select row_number() over (partition by applicationnumber order by crtdt desc) as rnk 
,* from  kaveri.applicationaudit t 
--where t.wrkflowstatusid in ('CD102','CD104' ,'CD142') and t.srocode=_srocode order by crtdt) as ss 
where t.srocode=_srocode  and t.wrkflowstatusid in ('CD102') order by crtdt) as ss 
	where rnk=1
) t
join kaveri.applicantapplicationdetails a on a.applicationnumber=t.applicationnumber 
-- Bagara hukum application exclude
left join kaveri.documentmaster d on a.applicationnumber = d.applicationnumber
and a.currentstatus in ('CD102','CD104','CD142') and a.isdeleted = false
where a.srocode=_srocode 
-- Bagara hukum application exclude
and d.regarticlecode <> 139
and t.crtdt::timestamp < v_crtdt;

end if;
return v_cnt;
end;
$$;


ALTER FUNCTION kaveri.fn_fetch_prev_pendingdocscnt(_applicationnumber character varying, _srocode bigint) OWNER TO postgres;

--
-- Name: fn_fetch_prev_pendingdocscnt_fda_sda(character varying, bigint, bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_prev_pendingdocscnt_fda_sda(_applicationnumber character varying, _srocode bigint, _userid bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
v_crtdt character varying;
v_cnt int;
begin
select to_char(crtdt,'YYYY-MM-DD HH24:MI:SS.FF3') into v_crtdt 
from kaveri.applicationaudit where applicationnumber=_applicationnumber 
and wrkflowstatusid='CD103'
order by crtdt desc limit 1;

if(v_crtdt is not null)
then
select count(distinct t.applicationnumber) into v_cnt from (select applicationnumber,crtdt,wrkflowstatusid from (
select row_number() over (partition by applicationnumber order by activityorder desc) as rnk 
,* from  kaveri.applicationaudit t 
where t.srocode=_srocode and t.wrkflowstatusid in ('CD103') order by crtdt ) as ss 
where rnk=1
) t
join kaveri.applicantapplicationdetails a on a.applicationnumber=t.applicationnumber and a.currentstatus in ('CD103')
-- Bagar hukum change
join kaveri.documentmaster d on a.applicationnumber=d.applicationnumber
where a.srocode=_srocode and a.sfdaid=_userid 
and d.regarticlecode <> 139 
and a.isdeleted = false
and t.crtdt::character varying < v_crtdt;
end if;
return v_cnt;
end;
$$;


ALTER FUNCTION kaveri.fn_fetch_prev_pendingdocscnt_fda_sda(_applicationnumber character varying, _srocode bigint, _userid bigint) OWNER TO postgres;

--
-- Name: fn_fetch_prev_pendingdocscnt_fda_sda_14052024(character varying, bigint, bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_prev_pendingdocscnt_fda_sda_14052024(_applicationnumber character varying, _srocode bigint, _userid bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
v_crtdt timestamp;
v_cnt int;
begin
select crtdt into v_crtdt 
from kaveri.applicationaudit where applicationnumber=_applicationnumber 
and wrkflowstatusid='CD103'
order by crtdt desc limit 1;

if(v_crtdt is not null)
then
select count(distinct t.applicationnumber) into v_cnt from (select applicationnumber,crtdt,wrkflowstatusid from (
select row_number() over (partition by applicationnumber order by activityorder desc) as rnk 
,* from  kaveri.applicationaudit t 
where t.wrkflowstatusid in ('CD103') and t.srocode=_srocode order by crtdt ) as ss 
where rnk=1
) t
join kaveri.applicantapplicationdetails a on a.applicationnumber=t.applicationnumber and a.currentstatus in ('CD103') 
where a.srocode=_srocode and a.sfdaid=_userid and a.isdeleted = false
and t.crtdt < v_crtdt;
end if;
return v_cnt;
end;
$$;


ALTER FUNCTION kaveri.fn_fetch_prev_pendingdocscnt_fda_sda_14052024(_applicationnumber character varying, _srocode bigint, _userid bigint) OWNER TO postgres;

--
-- Name: fn_fetch_property_details_json_chk(text, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_property_details_json_chk(_applicationnumber text, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare
v_data_json json;
pageoffset integer:=0;
v_countrecord int;
v_partytypeid bool;
v_cntproperty int;
v_lease int;
begin
	
	select count(*) into v_countrecord  from kaveri.propertymaster p where applicationnumber=_applicationnumber;
	
	select count(*) into v_cntproperty from kaveri.propertynumberdetails ps where propertyid in (select propertyid from kaveri.propertymaster where applicationnumber=_applicationnumber) 
	and ps.currentpropertytypeid in (1,60,65);

	select isownertobeclaimant into v_partytypeid from kaveri.stamprulesflag sf where sf.stampruleid in (Select stampruleid from kaveri.propertymaster p where p.applicationnumber =_applicationnumber limit 1);

	Select p.stamparticlecode into v_lease from kaveri.propertymaster p where p.applicationnumber = _applicationnumber;

pageoffset:=((pagenumber-1) * pagesize);

select row_to_json(data_json) into v_data_json from (

select array_to_json(array_agg(row_to_json(app_json)))

from (

select pm.propertyid as PIDNO,pm.villagecode,vi.villagenamee as Village,

ho.hoblicode,ho.hoblinamee as Hobli,ta.talukcode,ta.taluknamee as Taluk,

ta.districtcode,se.districtcode as kaveridistrictcode,di.districtnamee as District,

                pm.stamparticlecode,

                sp.articlenamee as stamparticle,

                pm.stampruleid,

                sr.descriptione as stampsubarticle,

                pm.regarticlecode,

                ra.articlenamee as registrationfeearticle,

--             sr.bookid,

                (case when pm.stamparticlecode = 14 and pm.isbefore2004=false  then

                 (select bookid from kaveri.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else dc.bookid end ) as bookid,

                --bt.booknameenglish as bookname,
	
                (select booknameenglish from kaveri.booktypemaster where bookid =

                (case when pm.stamparticlecode = 14 and pm.isbefore2004=false  then

                 (select bookid from kaveri.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else dc.bookid end )) as bookname,
                pm.srocode,

                se.sronamee as sroname,

                pm.propertytypeid,

                pt.propertytypename,

                pm.noofscanpages,

                pm.ismovableproperty,

                pm.movablepropertydesc,

                w.wardid,

                pm.totalarea,

                me.descriptionenglish as unit,

                w.wardnumber,

                pm.landmark,

                pm.zoneid,

				(select STRING_AGG(concat_ws(' ', p2.firstname, p2.middlename, p2.lastname), ', ') 
				from kaveri.propertymaster p 
				join kaveri.partyinfo p2 on p2.propertyid = p.referencepropertyid  where p.applicationnumber = _applicationnumber and v_lease = 80)as leaseownername,

                zone.departmentname as zonename,

                subpropertytypeid,
				
				-- upor change 
				pm.upormutationfee,pm.uporprcardfee ,pm.uportotalarea,pm.uporpartarea,pm.isuporpartextent,

                ( select array_to_json(array_agg(row_to_json(partypndetails)))

      from (

                  select b.survey_no,b.hissa_no,
--				(select string_agg(firstname,', ')  from kaveri.partyinfo pp where pp.propertyid =a.propertyid and pp.partytypeid= (case when v_partytypeid=true then 1 else 2 end)) as ownername,

                                  /* COMMENTED ON 01-10-2022 as ownername is only single owner*/

                                --  string_agg(a.firstname,',') as ownername,

--                                  coalesce(r.relatione,a.relationship) as relationship,a.relativename,
				
				(select string_agg(coalesce(firstname ||' '|| r.relatione ||' '|| relativename),', ') 
				from kaveri.partyinfo pp 
				join kaveri.relationshipmasters r on r.id::text =pp.relationship::text
				where pp.propertyid = a.propertyid and pp.ownerno in (select min(ownerno) from kaveri.partyinfo p where propertyid=a.propertyid and p.partytypeid= (case WHEN v_lease = 80 THEN 2 when v_partytypeid=true then 1 else 2 end)) 
				and pp.partytypeid= (CASE 
								        WHEN v_lease = 80 THEN 2
								        WHEN v_partytypeid = TRUE THEN 1
								        ELSE 2
								    END)
				) as ownername ,'' as relationship,'' as relativename,  
                  
--				(select coalesce(r.relatione,a.relationship) from kaveri.partyinfo a1 
--							where a1.ownerno in (select min(ownerno) from kaveri.partyinfo p where propertyid=a.propertyid) 
--									and r.id::text=a1.relationship::text
--							and a1.propertyid=a.propertyid and a1.partytypeid= (case when v_partytypeid=true then 1 else 2 end ))   as relationship,a.relativename,                

a.transactextacre as transactextacre,a.transactextgunta as transactextgunta ,a.transactextfgunta as transactextfgunta from

kaveri.partyinfo a inner join kaveri.propertynumberdetails b on a.propertyid = b.propertyid

                                 -- and a.partytypeid = 2 /* commented on 30-07-2022 - in discharge deed, owner will be marked as claimant */

--                                  left join kaveri.relationshipmasters r on r.id::text = a.relationship::text 

                                  --a.relationship in ('3','4','5','6','7','8')

                                  where a.applicationnumber = pm.applicationnumber and pm.propertyid= b.propertyid and a.partytypeid= (case WHEN v_lease = 80 THEN 2 when v_partytypeid=true then 1 else 2 end)
									group by b.survey_no,b.hissa_no,
--									r.relatione,r.id
									a.relationship,a.relativename,a.transactextacre,a.transactextgunta,a.transactextfgunta,a.propertyid,a.ownerno
                                   order by a.ownerno limit 1
                                 
									--group by b.survey_no , b.hissa_no,r.relatione,a.relativename,a.relationship,

     --  a.transactextacre,a.transactextgunta,

                                --   a.transactextfgunta

                  )partypndetails) as partyinfopropnumberdetails,

( select array_to_json(array_agg(row_to_json(prptyno)))

      from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,

                                                pntm.typenameenglish as propertynumbertype,

                                                pnd.currentnumber,pnd.hissa_no,pnd.survey_no,pnd.description as propertynumberdescription
												

                                                from kaveri.propertynumberdetails pnd

                                   left join kaveri.propertynotypemaster pntm                                    

                                                on (pntm.propertytypeid = pnd.currentpropertytypeid)

                                   where pnd.propertyid = pm.propertyid and

                                                pm.applicationnumber = _applicationnumber
									
                                   )prptyno )

                                                as propertynumberdetails,

                ( select array_to_json(array_agg(row_to_json(courtorderagri)))

                from (              

                select * from kaveri.vw_fetch_court_order_details co  where  co.propertyid in (select pm.propertyid from kaveri.propertymaster pm where applicationnumber=_applicationnumber)
		 and

                applicationnumber = _applicationnumber and (co.currentpropertytypeid <> 1 or co.currentpropertytypeid=1) and co.villagecode in (select p7.villagecode from kaveri.propertymaster p7 where applicationnumber=_applicationnumber) 

                ) courtorderagri) as Courtdataagri,

                ( select array_to_json(array_agg(row_to_json(partynonagri

)))

                from (

                select pm.assessment as pid,

                pa.firstname as ownername,

                pm.landmark as propertydescription ,

                pm.ownedarea as totalarea

     from kaveri.partyinfo pa where pa.propertyid = pm.propertyid

                )partynonagri)partyinfononagri,

                ( select array_to_json(array_agg(row_to_json(courtordernonagri)))

                from (

                                select * from kaveri.vw_fetch_court_order_details na where na.propertyid in (select pm.propertyid from kaveri.propertymaster pm where applicationnumber=_applicationnumber)
			and

                applicationnumber = _applicationnumber and (na.currentpropertytypeid <>1 or na.currentpropertytypeid=1) and na.villagecode in (select p6.villagecode from kaveri.propertymaster p6 where applicationnumber=_applicationnumber)

                                )courtordernonagri)as courtdatanonagri,

                ( select array_agg(row_to_json(propertyliability))

                from (SELECT
a.orderdate as issuedate,
a.issuedby,
a.liabilityamount as amount,
a.ordernumber,
a.liabilitynote,
s.sronamee,
a.propertyid

from kaveri.liabilitydetails_new a join kaveri.sromaster s on a.srocode=s.srocode where a.propertyid=pm.propertyid and a.iscleared = false
) propertyliability ) as liabilitydata,

                ( select array_to_json(array_agg(row_to_json(propertyschedules)))

                from

(select scheduleid,

                ps.propertyid,

                ps.srocode,

                ps.partyid,

                ps.scheduletype,

                pm.totalarea,

                ps.unitid,

                ps.description,

                ps.partyids,

                ps.aileniatedauthorityid,

                ps.alieniatedorder,

                ps.bhoomisellerpartyids,

                ps.govtrestricorder,

                ps.govtrestrictionid,

                ps.landcode,propertygroup,

                ps.giftshare,

                ps.giftsharedetails,

                ps.easttowest,

                ps.northtosouth,

                ps.blockchainpropertyid,

                ps.assignedblockchainpid,

                ps.applicationnumber,

                ps.verified,

                ps.issroapproved,

                ps.eastboundary,

                ps.westboundary,

                ps.northboundary,

                ps.southboundary,

                p.transactextacre,

                p.transactextgunta,

                p.transactextfgunta

                from kaveri.propertyschedules ps
                 join (select * from kaveri.partyinfo p where partytypeid = 2 and (case when v_cntproperty>0 then
				 propertyid=pm.propertyid else p.applicationnumber=_applicationnumber end) order by ownerno limit 1)as p
				on (case when v_cntproperty>0 then ps.propertyid=p.propertyid else p.applicationnumber=ps.applicationnumber end)
				 join kaveri.propertymaster pmm on ps.propertyid=pmm.propertyid               
				left join kaveri.stamprulesflag sf on sf.stampruleid =pmm.stampruleid 
				where ps.applicationnumber=_applicationnumber and ps.propertyid  = pm.propertyid and  p.partytypeid =(case when sf.isownertobeclaimant=true then 1 else 2 end)

                order by ps.scheduleid 


                
) propertyschedules) as propertyschedulesdata,

v_countrecord as countofrecord,

pm.roadcode as roadcode,

rd.roadnamee as roadnamee,

ta.unit as unittype,

pt.isagri as isagriculture


from kaveri.propertymaster pm 
join kaveri.bhoomimappingdetails bh on (pm.villagecode=bh.kaverivillagecode) and bh.bhoomivillagecode<>0
left join kaveri.bhoomivillagemaster vi on (bh.bhoomivillagecode  = vi.villagecode and bh.bhoomitalukcode=vi.talukcode and bh.bhoomidistrictcode=vi.districtcode and bh.bhoomihobicode=vi.hoblicode)
left join kaveri.bhoomihoblimaster ho on (ho.hoblicode =bh.bhoomihobicode and ho.talukcode=bh.bhoomitalukcode  and ho.districtcode=bh.bhoomidistrictcode)
join kaveri.bhoomitalukmaster ta on (bh.bhoomitalukcode=ta.talukcode and bh.bhoomidistrictcode=ta.districtcode)
left join kaveri.bhoomidistrictmaster  di on (di.districtcode = ta.districtcode)
left join kaveri.documentmaster dc on (dc.regarticlecode = pm.regarticlecode and dc.documentid=pm.documentid)
left join kaveri.stamparticles sp on (sp.stamparticlecode = pm.stamparticlecode)
left join kaveri.stamprules sr on (sr.stampruleid = pm.stampruleid)
left join kaveri.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
left join kaveri.booktypemaster bt on (bt.bookid = sr.bookid)
left join kaveri.sromaster se on (se.srocode = pm.srocode)
left join kaveri.propertytypemaster pt on pt.propertytypeid = pm.propertytypeid
left join kaveri.villagewardmapping vw on vw.villagecode = pm.villagecode and vw.wardid = pm.wardid and pm.ismovableproperty=false
left join kaveri.warddetails w on  w.wardid = pm.wardid
left join kaveri.measunitmaster me on me.unitid = pm.unitid
left join kaveri.integrationdepartment zone on pm.zoneid = zone.udeptid
left join kaveri.roadmaster rd on (pm.roadcode=rd.roadcode)
where pm.applicationnumber = _applicationnumber and pt.isagri=true

group by pm.propertyid,pm.villagecode,vi.villagenamee,ho.hoblicode,ho.hoblinamee,ta.talukcode,ta.taluknamee,ta.districtcode,di.districtnamee              

,pm.stamparticlecode,sp.articlenamee,pm.stampruleid,sr.descriptione,pm.regarticlecode,ra.articlenamee,dc.bookid,bt.booknameenglish  

,pm.srocode,se.sronamee,

pm.propertytypeid,

                pt.propertytypename,

                pm.noofscanpages,

                pm.ismovableproperty,

                pm.movablepropertydesc,

                w.wardid,

                pm.totalarea,

                me.descriptionenglish,

                w.wardnumber,

                pm.landmark,

                pm.zoneid,

                zone.departmentname,

                subpropertytypeid,pm.applicationnumber,pm.assessment,pm.ownedarea,pm.roadcode,rd.roadnamee
                ,ta.unit,pt.isagri,pm.isbefore2004,se.districtcode
				-- upor change
				,pm.upormutationfee,pm.uporprcardfee ,pm.uportotalarea,pm.uporpartarea,pm.isuporpartextent



union ALL


select pm.propertyid as PIDNO,pm.villagecode,vi.villagenamee as Village,

vi.hoblicode,ho.hoblinamee as Hobli,vi.talukcode,ta.taluknamee as Taluk,

sm.districtcode,se.districtcode as kaveridistrictcode,di.districtnamee as District,

                pm.stamparticlecode,

                sp.articlenamee as stamparticle,

                pm.stampruleid,

                sr.descriptione as stampsubarticle,

                pm.regarticlecode,

                ra.articlenamee as registrationfeearticle,

--             sr.bookid,

                (case when pm.stamparticlecode = 14 and pm.isbefore2004=false then

                 (select bookid from kaveri.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else dc.bookid end ) as bookid,

                --bt.booknameenglish as bookname,
	
                (select booknameenglish from kaveri.booktypemaster where bookid =

                (case when pm.stamparticlecode = 14 and pm.isbefore2004=false then

                 (select bookid from kaveri.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else dc.bookid end )) as bookname,
                pm.srocode,

                se.sronamee as sroname,

                pm.propertytypeid,

                pt.propertytypename,

                pm.noofscanpages,

                pm.ismovableproperty,

                pm.movablepropertydesc,

                w.wardid,

                pm.totalarea,

                me.descriptionenglish as unit,

                w.wardnumber,

                pm.landmark,

                pm.zoneid,

				(select STRING_AGG(concat_ws(' ', p2.firstname, p2.middlename, p2.lastname), ', ') 
				from kaveri.propertymaster p 
				join kaveri.partyinfo p2 on p2.propertyid = p.referencepropertyid  where p.applicationnumber = _applicationnumber and v_lease = 80)as leaseownername,

                zone.departmentname as zonename,

                subpropertytypeid,
				-- upor change 
				pm.upormutationfee,pm.uporprcardfee ,pm.uportotalarea,pm.uporpartarea,pm.isuporpartextent,

                ( select array_to_json(array_agg(row_to_json(partypndetails)))

      from (

                  select b.survey_no,b.hissa_no,
--				(select string_agg(firstname,', ')  from kaveri.partyinfo pp where pp.propertyid =a.propertyid and pp.partytypeid= (case when v_partytypeid=true then 1 else 2 end)) as ownername,

                                  /* COMMENTED ON 01-10-2022 as ownername is only single owner*/

                                  --string_agg(a.firstname,',') as ownername,

--                                  coalesce(r.relatione,a.relationship) as relationship,a.relativename,
				
				(select string_agg(coalesce(firstname ||' '|| r.relatione ||' '|| relativename),', ') 
				from kaveri.partyinfo pp 
				join kaveri.relationshipmasters r on r.id::text =pp.relationship::text
				where pp.propertyid = a.propertyid and pp.ownerno in (select min(ownerno) from kaveri.partyinfo p where propertyid=a.propertyid and p.partytypeid= (case when v_partytypeid=true then 1 else 2 end)) 
				and pp.partytypeid= (case when v_partytypeid=true then 1 else 2 end)
				) as ownername,'' as relationship,'' as relativename,
                  
--(select coalesce(r.relatione,a.relationship) from kaveri.partyinfo a1
--							where a1.ownerno in (select min(ownerno) from kaveri.partyinfo p 
--															where propertyid=a.propertyid) 
--									and r.id::text=a1.relationship::text
--							and a1.propertyid=a.propertyid)   as relationship,a.relativename,

a.availableextacre as transactextacre,a.availableextgunta as transactextgunta ,a.availableextfgunta as transactextfgunta from

kaveri.partyinfo a inner join kaveri.propertynumberdetails b on a.propertyid = b.propertyid

                                 -- and a.partytypeid = 2 /* commented on 30-07-2022 - in discharge deed, owner will be marked as claimant */

--                                  left join kaveri.relationshipmasters r on r.id::text = a.relationship::text 

                                  --a.relationship in ('3','4','5','6','7','8')

                                  where a.applicationnumber = pm.applicationnumber and pm.propertyid= b.propertyid and a.partytypeid= (case when v_partytypeid=true then 1 else 2 end)
								group by b.survey_no,b.hissa_no,
								--r.relatione,r.id
								a.relationship,a.availableextacre ,a.availableextgunta,a.availableextfgunta,a.relativename
								,a.propertyid,a.ownerno
								order by a.ownerno limit 1
								--group by b.survey_no , b.hissa_no,r.relatione,a.relativename,a.relationship,

     --  a.transactextacre,a.transactextgunta,

                                --   a.transactextfgunta

                  )partypndetails) as partyinfopropnumberdetails,

( select array_to_json(array_agg(row_to_json(prptyno)))

      from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,

                                                pntm.typenameenglish as propertynumbertype,

                                                pnd.currentnumber,pnd.hissa_no,pnd.survey_no,pnd.description as propertynumberdescription												

                                                from kaveri.propertynumberdetails pnd

                                   left join kaveri.propertynotypemaster pntm                                    

                                                on (pntm.propertytypeid = pnd.currentpropertytypeid)

                                   where pnd.propertyid = pm.propertyid and

                                                pm.applicationnumber = _applicationnumber
									
                                   )prptyno )

                                                as propertynumberdetails,

                ( select array_to_json(array_agg(row_to_json(courtorderagri)))

                from (

               

                select * from kaveri.vw_fetch_court_order_details co  where  co.propertyid in (select pm.propertyid from kaveri.propertymaster pm where applicationnumber=_applicationnumber)
		 and

                applicationnumber = _applicationnumber and (co.currentpropertytypeid <> 1 or co.currentpropertytypeid=1) and co.villagecode in (select p7.villagecode from kaveri.propertymaster p7 where applicationnumber=_applicationnumber) 

                ) courtorderagri) as Courtdataagri,

                ( select array_to_json(array_agg(row_to_json(partynonagri

)))

                from (

                select pm.assessment as pid,

                pa.firstname as ownername,

                pm.landmark as propertydescription ,

                pm.ownedarea as totalarea

     from kaveri.partyinfo pa where pa.propertyid = pm.propertyid

                )partynonagri)partyinfononagri,

 ( select array_to_json(array_agg(row_to_json(courtordernonagri)))
                from (
select * from kaveri.vw_fetch_court_order_details na where na.propertyid in (select pm.propertyid from kaveri.propertymaster pm where applicationnumber=_applicationnumber) 
and
 applicationnumber = _applicationnumber and (na.currentpropertytypeid <>1 or na.currentpropertytypeid=1) 
 and na.villagecode in (select p6.villagecode from kaveri.propertymaster p6 where applicationnumber=_applicationnumber)
)courtordernonagri)as courtdatanonagri,

                ( select array_agg(row_to_json(propertyliability))

                from (SELECT
a.orderdate as issuedate,
a.issuedby,
a.liabilityamount as amount,
a.ordernumber,
a.liabilitynote,
s.sronamee,
a.propertyid

from kaveri.liabilitydetails_new a join kaveri.sromaster s on a.srocode=s.srocode where a.propertyid=pm.propertyid and a.iscleared = false
) propertyliability ) as liabilitydata,
                ( select array_to_json(array_agg(row_to_json(propertyschedules)))
                from
(select scheduleid,
                ps.propertyid,
                ps.srocode,
                ps.partyid,
                ps.scheduletype,
                pm.totalarea,
                ps.unitid,
                ps.description,
                ps.partyids,
                ps.aileniatedauthorityid,
                ps.alieniatedorder,
                ps.bhoomisellerpartyids,
                ps.govtrestricorder,
                ps.govtrestrictionid,
                ps.landcode,propertygroup,
                ps.giftshare,
                ps.giftsharedetails,
                ps.easttowest,
                ps.northtosouth,
                ps.blockchainpropertyid,
                ps.assignedblockchainpid,
                ps.applicationnumber,
                ps.verified,
                ps.issroapproved,
                ps.eastboundary,
                ps.westboundary,
                ps.northboundary,
                ps.southboundary,
                p.transactextacre,
                p.transactextgunta,
                p.transactextfgunta
                from kaveri.propertyschedules ps
                 join (select * from kaveri.partyinfo p where partytypeid = 2 and (case when v_cntproperty>0 then
				 propertyid  = pm.propertyid else p.applicationnumber=_applicationnumber end) order by ownerno limit 1)as p 
				 on (case when v_cntproperty>0 then ps.propertyid=p.propertyid else p.applicationnumber=ps.applicationnumber end)
                 join kaveri.propertymaster pmm on ps.propertyid=pmm.propertyid               
				left join kaveri.stamprulesflag sf on sf.stampruleid =pmm.stampruleid 
                where ps.applicationnumber=_applicationnumber and ps.propertyid  = pm.propertyid and  p.partytypeid =(case when sf.isownertobeclaimant=true then 1 else 2 end)
                order by ps.scheduleid limit 1
) propertyschedules) as propertyschedulesdata,
v_countrecord as countofrecord,
pm.roadcode as roadcode,
rd.roadnamee as roadnamee,
ta.unit as unittype,
pt.isagri as isagriculture
from kaveri.propertymaster pm 
left join kaveri.villagemaster vi on (pm.villagecode = vi.villagecode)
left join kaveri.sromaster sm on (vi.srocode=sm.srocode)
left join kaveri.hoblimaster ho on (ho.hoblicode = vi.hoblicode)
left join kaveri.talukmaster ta on (ta.talukcode=vi.talukcode)
left join kaveri.districtmaster di on (di.districtcode = sm.districtcode)
--left join kaveri.bhoomidistrictmaster  di on (di.districtcode = ta.districtcode)
left join kaveri.documentmaster dc on (dc.regarticlecode = pm.regarticlecode and dc.documentid=pm.documentid)
left join kaveri.stamparticles sp on (sp.stamparticlecode = pm.stamparticlecode)
left join kaveri.stamprules sr on (sr.stampruleid = pm.stampruleid)
left join kaveri.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
left join kaveri.booktypemaster bt on (bt.bookid = sr.bookid)
left join kaveri.sromaster se on (se.srocode = pm.srocode)
left join kaveri.propertytypemaster pt on pt.propertytypeid = pm.propertytypeid
left join kaveri.villagewardmapping vw on vw.villagecode = pm.villagecode and vw.wardid = pm.wardid and pm.ismovableproperty=false
left join kaveri.warddetails w on  w.wardid = pm.wardid
left join kaveri.measunitmaster me on me.unitid = pm.unitid
left join kaveri.integrationdepartment zone on pm.zoneid = zone.udeptid
left join kaveri.roadmaster rd on (pm.roadcode=rd.roadcode)
where pm.applicationnumber = _applicationnumber and pt.isagri=false
group by pm.propertyid,pm.villagecode,vi.villagenamee,vi.hoblicode,ho.hoblinamee,vi.talukcode,ta.taluknamee,sm.districtcode,di.districtnamee              
,pm.stamparticlecode,sp.articlenamee,pm.stampruleid,sr.descriptione,pm.regarticlecode,ra.articlenamee,dc.bookid,bt.booknameenglish  
,pm.srocode,se.sronamee,
pm.propertytypeid,
                pt.propertytypename,
                pm.noofscanpages,
                pm.ismovableproperty,
                pm.movablepropertydesc,
                w.wardid,
                pm.totalarea,
                me.descriptionenglish,
                w.wardnumber,
                pm.landmark,
                pm.zoneid,
                zone.departmentname,
                subpropertytypeid,pm.applicationnumber,pm.assessment,pm.ownedarea,pm.roadcode,rd.roadnamee
                ,ta.unit,pt.isagri,pm.isbefore2004  ,se.districtcode
				-- upor change
				,pm.upormutationfee,pm.uporprcardfee ,pm.uportotalarea,pm.uporpartarea,pm.isuporpartextent
			
offset pageoffset

fetch next pagesize rows only

)  app_json ) data_json;

return v_data_json;

END;

$$;


ALTER FUNCTION kaveri.fn_fetch_property_details_json_chk(_applicationnumber text, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_fetch_property_details_json_chk_03032026(text, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_property_details_json_chk_03032026(_applicationnumber text, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare
v_data_json json;
pageoffset integer:=0;
v_countrecord int;
v_partytypeid bool;
v_cntproperty int;
begin
	
	select count(*) into v_countrecord  from kaveri.propertymaster p where applicationnumber=_applicationnumber;
	
	select count(*) into v_cntproperty from kaveri.propertynumberdetails ps where propertyid in (select propertyid from kaveri.propertymaster where applicationnumber=_applicationnumber) 
	and ps.currentpropertytypeid in (1,60,65);

	select isownertobeclaimant into v_partytypeid from kaveri.stamprulesflag sf where sf.stampruleid in (Select stampruleid from kaveri.propertymaster p where p.applicationnumber =_applicationnumber limit 1);

pageoffset:=((pagenumber-1) * pagesize);

select row_to_json(data_json) into v_data_json from (

select array_to_json(array_agg(row_to_json(app_json)))

from (

select pm.propertyid as PIDNO,pm.villagecode,vi.villagenamee as Village,

ho.hoblicode,ho.hoblinamee as Hobli,ta.talukcode,ta.taluknamee as Taluk,

ta.districtcode,se.districtcode as kaveridistrictcode,di.districtnamee as District,

                pm.stamparticlecode,

                sp.articlenamee as stamparticle,

                pm.stampruleid,

                sr.descriptione as stampsubarticle,

                pm.regarticlecode,

                ra.articlenamee as registrationfeearticle,

--             sr.bookid,

                (case when pm.stamparticlecode = 14 and pm.isbefore2004=false  then

                 (select bookid from kaveri.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else dc.bookid end ) as bookid,

                --bt.booknameenglish as bookname,
	
                (select booknameenglish from kaveri.booktypemaster where bookid =

                (case when pm.stamparticlecode = 14 and pm.isbefore2004=false  then

                 (select bookid from kaveri.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else dc.bookid end )) as bookname,
                pm.srocode,

                se.sronamee as sroname,

                pm.propertytypeid,

                pt.propertytypename,

                pm.noofscanpages,

                pm.ismovableproperty,

                pm.movablepropertydesc,

                w.wardid,

                pm.totalarea,

                me.descriptionenglish as unit,

                w.wardnumber,

                pm.landmark,

                pm.zoneid,

                zone.departmentname as zonename,

                subpropertytypeid,

                ( select array_to_json(array_agg(row_to_json(partypndetails)))

      from (

                  select b.survey_no,b.hissa_no,
--				(select string_agg(firstname,', ')  from kaveri.partyinfo pp where pp.propertyid =a.propertyid and pp.partytypeid= (case when v_partytypeid=true then 1 else 2 end)) as ownername,

                                  /* COMMENTED ON 01-10-2022 as ownername is only single owner*/

                                --  string_agg(a.firstname,',') as ownername,

--                                  coalesce(r.relatione,a.relationship) as relationship,a.relativename,
				--raghavendra 
				(select string_agg(coalesce(firstname ||' '|| r.relatione ||' '|| relativename),', ') 
				from kaveri.partyinfo pp 
				join kaveri.relationshipmasters r on r.id::text =pp.relationship::text
				where pp.propertyid = a.propertyid and pp.ownerno in (select min(ownerno) from kaveri.partyinfo p where propertyid=a.propertyid and p.partytypeid= (case when v_partytypeid=true then 1 else 2 end)) 
				and pp.partytypeid= (case when v_partytypeid=true then 1 else 2 end)
				) as ownername ,'' as relationship,'' as relativename,  
                  
--				(select coalesce(r.relatione,a.relationship) from kaveri.partyinfo a1 
--							where a1.ownerno in (select min(ownerno) from kaveri.partyinfo p where propertyid=a.propertyid) 
--									and r.id::text=a1.relationship::text
--							and a1.propertyid=a.propertyid and a1.partytypeid= (case when v_partytypeid=true then 1 else 2 end ))   as relationship,a.relativename,                

a.transactextacre as transactextacre,a.transactextgunta as transactextgunta ,a.transactextfgunta as transactextfgunta from

kaveri.partyinfo a inner join kaveri.propertynumberdetails b on a.propertyid = b.propertyid

                                 -- and a.partytypeid = 2 /* commented on 30-07-2022 - in discharge deed, owner will be marked as claimant */

--                                  left join kaveri.relationshipmasters r on r.id::text = a.relationship::text 

                                  --a.relationship in ('3','4','5','6','7','8')

                                  where a.applicationnumber = pm.applicationnumber and pm.propertyid= b.propertyid and a.partytypeid= (case when v_partytypeid=true then 1 else 2 end)
									group by b.survey_no,b.hissa_no,
--									r.relatione,r.id
									a.relationship,a.relativename,a.transactextacre,a.transactextgunta,a.transactextfgunta,a.propertyid,a.ownerno
                                   order by a.ownerno limit 1
                                 
									--group by b.survey_no , b.hissa_no,r.relatione,a.relativename,a.relationship,

     --  a.transactextacre,a.transactextgunta,

                                --   a.transactextfgunta

                  )partypndetails) as partyinfopropnumberdetails,

( select array_to_json(array_agg(row_to_json(prptyno)))

      from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,

                                                pntm.typenameenglish as propertynumbertype,

                                                pnd.currentnumber,pnd.hissa_no,pnd.survey_no,pnd.description as propertynumberdescription

                                                from kaveri.propertynumberdetails pnd

                                   left join kaveri.propertynotypemaster pntm                                    

                                                on (pntm.propertytypeid = pnd.currentpropertytypeid)

                                   where pnd.propertyid = pm.propertyid and

                                                pm.applicationnumber = _applicationnumber

                                   )prptyno )

                                                as propertynumberdetails,

                ( select array_to_json(array_agg(row_to_json(courtorderagri)))

                from (

               

                select * from kaveri.vw_fetch_court_order_details co  where  co.propertyid in (select pm.propertyid from kaveri.propertymaster pm where applicationnumber=_applicationnumber)
		 and

                applicationnumber = _applicationnumber and (co.currentpropertytypeid <> 1 or co.currentpropertytypeid=1) and co.villagecode in (select p7.villagecode from kaveri.propertymaster p7 where applicationnumber=_applicationnumber) 

                ) courtorderagri) as Courtdataagri,

                ( select array_to_json(array_agg(row_to_json(partynonagri

)))

                from (

                select pm.assessment as pid,

                pa.firstname as ownername,

                pm.landmark as propertydescription ,

                pm.ownedarea as totalarea

     from kaveri.partyinfo pa where pa.propertyid = pm.propertyid

                )partynonagri)partyinfononagri,

                ( select array_to_json(array_agg(row_to_json(courtordernonagri)))

                from (

                                select * from kaveri.vw_fetch_court_order_details na where na.propertyid in (select pm.propertyid from kaveri.propertymaster pm where applicationnumber=_applicationnumber)
			and

                applicationnumber = _applicationnumber and (na.currentpropertytypeid <>1 or na.currentpropertytypeid=1) and na.villagecode in (select p6.villagecode from kaveri.propertymaster p6 where applicationnumber=_applicationnumber)

                                )courtordernonagri)as courtdatanonagri,

                ( select array_agg(row_to_json(propertyliability))

                from (SELECT
a.orderdate as issuedate,
a.issuedby,
a.liabilityamount as amount,
a.ordernumber,
a.liabilitynote,
s.sronamee,
a.propertyid

from kaveri.liabilitydetails_new a join kaveri.sromaster s on a.srocode=s.srocode 
where a.propertyid=pm.propertyid and a.iscleared = false
) propertyliability ) as liabilitydata,

                ( select array_to_json(array_agg(row_to_json(propertyschedules)))

                from

(select scheduleid,

                ps.propertyid,

                ps.srocode,

                ps.partyid,

                ps.scheduletype,

                pm.totalarea,

                ps.unitid,

                ps.description,

                ps.partyids,

                ps.aileniatedauthorityid,

                ps.alieniatedorder,

                ps.bhoomisellerpartyids,

                ps.govtrestricorder,

                ps.govtrestrictionid,

                ps.landcode,propertygroup,

                ps.giftshare,

                ps.giftsharedetails,

                ps.easttowest,

                ps.northtosouth,

                ps.blockchainpropertyid,

                ps.assignedblockchainpid,

                ps.applicationnumber,

                ps.verified,

                ps.issroapproved,

                ps.eastboundary,

                ps.westboundary,

                ps.northboundary,

                ps.southboundary,

                p.transactextacre,

                p.transactextgunta,

                p.transactextfgunta

                from kaveri.propertyschedules ps
                 join (select * from kaveri.partyinfo p where partytypeid = 2 and (case when v_cntproperty>0 then
				 propertyid=pm.propertyid else p.applicationnumber=_applicationnumber end) order by ownerno limit 1)as p
				on (case when v_cntproperty>0 then ps.propertyid=p.propertyid else p.applicationnumber=ps.applicationnumber end)
				 join kaveri.propertymaster pmm on ps.propertyid=pmm.propertyid               
				left join kaveri.stamprulesflag sf on sf.stampruleid =pmm.stampruleid 
				where ps.applicationnumber=_applicationnumber and ps.propertyid  = pm.propertyid and  p.partytypeid =(case when sf.isownertobeclaimant=true then 1 else 2 end)

                order by ps.scheduleid 


                
) propertyschedules) as propertyschedulesdata,

v_countrecord as countofrecord,

pm.roadcode as roadcode,

rd.roadnamee as roadnamee,

ta.unit as unittype,

pt.isagri as isagriculture


from kaveri.propertymaster pm 
join kaveri.bhoomimappingdetails bh on (pm.villagecode=bh.kaverivillagecode) and bh.bhoomivillagecode<>0
left join kaveri.bhoomivillagemaster vi on (bh.bhoomivillagecode  = vi.villagecode and bh.bhoomitalukcode=vi.talukcode and bh.bhoomidistrictcode=vi.districtcode and bh.bhoomihobicode=vi.hoblicode)
left join kaveri.bhoomihoblimaster ho on (ho.hoblicode =bh.bhoomihobicode and ho.talukcode=bh.bhoomitalukcode  and ho.districtcode=bh.bhoomidistrictcode)
join kaveri.bhoomitalukmaster ta on (bh.bhoomitalukcode=ta.talukcode and bh.bhoomidistrictcode=ta.districtcode)
left join kaveri.bhoomidistrictmaster  di on (di.districtcode = ta.districtcode)
left join kaveri.documentmaster dc on (dc.regarticlecode = pm.regarticlecode and dc.documentid=pm.documentid)
left join kaveri.stamparticles sp on (sp.stamparticlecode = pm.stamparticlecode)
left join kaveri.stamprules sr on (sr.stampruleid = pm.stampruleid)
left join kaveri.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
left join kaveri.booktypemaster bt on (bt.bookid = sr.bookid)
left join kaveri.sromaster se on (se.srocode = pm.srocode)
left join kaveri.propertytypemaster pt on pt.propertytypeid = pm.propertytypeid
left join kaveri.villagewardmapping vw on vw.villagecode = pm.villagecode and vw.wardid = pm.wardid and pm.ismovableproperty=false
left join kaveri.warddetails w on  w.wardid = pm.wardid
left join kaveri.measunitmaster me on me.unitid = pm.unitid
left join kaveri.integrationdepartment zone on pm.zoneid = zone.udeptid
left join kaveri.roadmaster rd on (pm.roadcode=rd.roadcode)
where pm.applicationnumber = _applicationnumber and pt.isagri=true

group by pm.propertyid,pm.villagecode,vi.villagenamee,ho.hoblicode,ho.hoblinamee,ta.talukcode,ta.taluknamee,ta.districtcode,di.districtnamee              

,pm.stamparticlecode,sp.articlenamee,pm.stampruleid,sr.descriptione,pm.regarticlecode,ra.articlenamee,dc.bookid,bt.booknameenglish  

,pm.srocode,se.sronamee,

pm.propertytypeid,

                pt.propertytypename,

                pm.noofscanpages,

                pm.ismovableproperty,

                pm.movablepropertydesc,

                w.wardid,

                pm.totalarea,

                me.descriptionenglish,

                w.wardnumber,

                pm.landmark,

                pm.zoneid,

                zone.departmentname,

                subpropertytypeid,pm.applicationnumber,pm.assessment,pm.ownedarea,pm.roadcode,rd.roadnamee
                ,ta.unit,pt.isagri,pm.isbefore2004,se.districtcode



union ALL


select pm.propertyid as PIDNO,pm.villagecode,vi.villagenamee as Village,

vi.hoblicode,ho.hoblinamee as Hobli,vi.talukcode,ta.taluknamee as Taluk,

sm.districtcode,se.districtcode as kaveridistrictcode,di.districtnamee as District,

                pm.stamparticlecode,

                sp.articlenamee as stamparticle,

                pm.stampruleid,

                sr.descriptione as stampsubarticle,

                pm.regarticlecode,

                ra.articlenamee as registrationfeearticle,

--             sr.bookid,

                (case when pm.stamparticlecode = 14 and pm.isbefore2004=false then

                 (select bookid from kaveri.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else dc.bookid end ) as bookid,

                --bt.booknameenglish as bookname,
	
                (select booknameenglish from kaveri.booktypemaster where bookid =

                (case when pm.stamparticlecode = 14 and pm.isbefore2004=false then

                 (select bookid from kaveri.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else dc.bookid end )) as bookname,
                pm.srocode,

                se.sronamee as sroname,

                pm.propertytypeid,

                pt.propertytypename,

                pm.noofscanpages,

                pm.ismovableproperty,

                pm.movablepropertydesc,

                w.wardid,

                pm.totalarea,

                me.descriptionenglish as unit,

                w.wardnumber,

                pm.landmark,

                pm.zoneid,

                zone.departmentname as zonename,

                subpropertytypeid,

                ( select array_to_json(array_agg(row_to_json(partypndetails)))

      from (

                  select b.survey_no,b.hissa_no,
--				(select string_agg(firstname,', ')  from kaveri.partyinfo pp where pp.propertyid =a.propertyid and pp.partytypeid= (case when v_partytypeid=true then 1 else 2 end)) as ownername,

                                  /* COMMENTED ON 01-10-2022 as ownername is only single owner*/

                                  --string_agg(a.firstname,',') as ownername,

--                                  coalesce(r.relatione,a.relationship) as relationship,a.relativename,
				-- raghavendra
				(select string_agg(coalesce(firstname ||' '|| r.relatione ||' '|| relativename),', ') 
				from kaveri.partyinfo pp 
				join kaveri.relationshipmasters r on r.id::text =pp.relationship::text
				where pp.propertyid = a.propertyid and pp.ownerno in (select min(ownerno) from kaveri.partyinfo p where propertyid=a.propertyid and p.partytypeid= (case when v_partytypeid=true then 1 else 2 end)) 
				and pp.partytypeid= (case when v_partytypeid=true then 1 else 2 end)
				) as ownername,'' as relationship,'' as relativename,
                  
--(select coalesce(r.relatione,a.relationship) from kaveri.partyinfo a1
--							where a1.ownerno in (select min(ownerno) from kaveri.partyinfo p 
--															where propertyid=a.propertyid) 
--									and r.id::text=a1.relationship::text
--							and a1.propertyid=a.propertyid)   as relationship,a.relativename,

a.availableextacre as transactextacre,a.availableextgunta as transactextgunta ,a.availableextfgunta as transactextfgunta from

kaveri.partyinfo a inner join kaveri.propertynumberdetails b on a.propertyid = b.propertyid

                                 -- and a.partytypeid = 2 /* commented on 30-07-2022 - in discharge deed, owner will be marked as claimant */

--                                  left join kaveri.relationshipmasters r on r.id::text = a.relationship::text 

                                  --a.relationship in ('3','4','5','6','7','8')

                                  where a.applicationnumber = pm.applicationnumber and pm.propertyid= b.propertyid and a.partytypeid= (case when v_partytypeid=true then 1 else 2 end)
								group by b.survey_no,b.hissa_no,
								--r.relatione,r.id
								a.relationship,a.availableextacre ,a.availableextgunta,a.availableextfgunta,a.relativename
								,a.propertyid,a.ownerno
								order by a.ownerno limit 1
								--group by b.survey_no , b.hissa_no,r.relatione,a.relativename,a.relationship,

     --  a.transactextacre,a.transactextgunta,

                                --   a.transactextfgunta

                  )partypndetails) as partyinfopropnumberdetails,

( select array_to_json(array_agg(row_to_json(prptyno)))

      from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,

                                                pntm.typenameenglish as propertynumbertype,

                                                pnd.currentnumber,pnd.hissa_no,pnd.survey_no,pnd.description as propertynumberdescription

                                                from kaveri.propertynumberdetails pnd

                                   left join kaveri.propertynotypemaster pntm                                    

                                                on (pntm.propertytypeid = pnd.currentpropertytypeid)

                                   where pnd.propertyid = pm.propertyid and

                                                pm.applicationnumber = _applicationnumber

                                   )prptyno )

                                                as propertynumberdetails,

                ( select array_to_json(array_agg(row_to_json(courtorderagri)))

                from (

               

                select * from kaveri.vw_fetch_court_order_details co  where  co.propertyid in (select pm.propertyid from kaveri.propertymaster pm where applicationnumber=_applicationnumber)
		 and

                applicationnumber = _applicationnumber and (co.currentpropertytypeid <> 1 or co.currentpropertytypeid=1) and co.villagecode in (select p7.villagecode from kaveri.propertymaster p7 where applicationnumber=_applicationnumber) 

                ) courtorderagri) as Courtdataagri,

                ( select array_to_json(array_agg(row_to_json(partynonagri

)))

                from (

                select pm.assessment as pid,

                pa.firstname as ownername,

                pm.landmark as propertydescription ,

                pm.ownedarea as totalarea

     from kaveri.partyinfo pa where pa.propertyid = pm.propertyid

                )partynonagri)partyinfononagri,

 ( select array_to_json(array_agg(row_to_json(courtordernonagri)))
                from (
select * from kaveri.vw_fetch_court_order_details na where na.propertyid in (select pm.propertyid from kaveri.propertymaster pm where applicationnumber=_applicationnumber) 
and
 applicationnumber = _applicationnumber and (na.currentpropertytypeid <>1 or na.currentpropertytypeid=1) 
 and na.villagecode in (select p6.villagecode from kaveri.propertymaster p6 where applicationnumber=_applicationnumber)
)courtordernonagri)as courtdatanonagri,

                ( select array_agg(row_to_json(propertyliability))

                from (SELECT
a.orderdate as issuedate,
a.issuedby,
a.liabilityamount as amount,
a.ordernumber,
a.liabilitynote,
s.sronamee,
a.propertyid

from kaveri.liabilitydetails_new a join kaveri.sromaster s on a.srocode=s.srocode 
where a.propertyid=pm.propertyid and a.iscleared = false
) propertyliability ) as liabilitydata,
                ( select array_to_json(array_agg(row_to_json(propertyschedules)))
                from
(select scheduleid,
                ps.propertyid,
                ps.srocode,
                ps.partyid,
                ps.scheduletype,
                pm.totalarea,
                ps.unitid,
                ps.description,
                ps.partyids,
                ps.aileniatedauthorityid,
                ps.alieniatedorder,
                ps.bhoomisellerpartyids,
                ps.govtrestricorder,
                ps.govtrestrictionid,
                ps.landcode,propertygroup,
                ps.giftshare,
                ps.giftsharedetails,
                ps.easttowest,
                ps.northtosouth,
                ps.blockchainpropertyid,
                ps.assignedblockchainpid,
                ps.applicationnumber,
                ps.verified,
                ps.issroapproved,
                ps.eastboundary,
                ps.westboundary,
                ps.northboundary,
                ps.southboundary,
                p.transactextacre,
                p.transactextgunta,
                p.transactextfgunta
                from kaveri.propertyschedules ps
                 join (select * from kaveri.partyinfo p where partytypeid = 2 and (case when v_cntproperty>0 then
				 propertyid  = pm.propertyid else p.applicationnumber=_applicationnumber end) order by ownerno limit 1)as p 
				 on (case when v_cntproperty>0 then ps.propertyid=p.propertyid else p.applicationnumber=ps.applicationnumber end)
                 join kaveri.propertymaster pmm on ps.propertyid=pmm.propertyid               
				left join kaveri.stamprulesflag sf on sf.stampruleid =pmm.stampruleid 
                where ps.applicationnumber=_applicationnumber and ps.propertyid  = pm.propertyid and  p.partytypeid =(case when sf.isownertobeclaimant=true then 1 else 2 end)
                order by ps.scheduleid limit 1
) propertyschedules) as propertyschedulesdata,
v_countrecord as countofrecord,
pm.roadcode as roadcode,
rd.roadnamee as roadnamee,
ta.unit as unittype,
pt.isagri as isagriculture
from kaveri.propertymaster pm 
left join kaveri.villagemaster vi on (pm.villagecode = vi.villagecode)
left join kaveri.sromaster sm on (vi.srocode=sm.srocode)
left join kaveri.hoblimaster ho on (ho.hoblicode = vi.hoblicode)
left join kaveri.talukmaster ta on (ta.talukcode=vi.talukcode)
left join kaveri.districtmaster di on (di.districtcode = sm.districtcode)
--left join kaveri.bhoomidistrictmaster  di on (di.districtcode = ta.districtcode)
left join kaveri.documentmaster dc on (dc.regarticlecode = pm.regarticlecode and dc.documentid=pm.documentid)
left join kaveri.stamparticles sp on (sp.stamparticlecode = pm.stamparticlecode)
left join kaveri.stamprules sr on (sr.stampruleid = pm.stampruleid)
left join kaveri.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
left join kaveri.booktypemaster bt on (bt.bookid = sr.bookid)
left join kaveri.sromaster se on (se.srocode = pm.srocode)
left join kaveri.propertytypemaster pt on pt.propertytypeid = pm.propertytypeid
left join kaveri.villagewardmapping vw on vw.villagecode = pm.villagecode and vw.wardid = pm.wardid and pm.ismovableproperty=false
left join kaveri.warddetails w on  w.wardid = pm.wardid
left join kaveri.measunitmaster me on me.unitid = pm.unitid
left join kaveri.integrationdepartment zone on pm.zoneid = zone.udeptid
left join kaveri.roadmaster rd on (pm.roadcode=rd.roadcode)
where pm.applicationnumber = _applicationnumber and pt.isagri=false
group by pm.propertyid,pm.villagecode,vi.villagenamee,vi.hoblicode,ho.hoblinamee,vi.talukcode,ta.taluknamee,sm.districtcode,di.districtnamee              
,pm.stamparticlecode,sp.articlenamee,pm.stampruleid,sr.descriptione,pm.regarticlecode,ra.articlenamee,dc.bookid,bt.booknameenglish  
,pm.srocode,se.sronamee,
pm.propertytypeid,
                pt.propertytypename,
                pm.noofscanpages,
                pm.ismovableproperty,
                pm.movablepropertydesc,
                w.wardid,
                pm.totalarea,
                me.descriptionenglish,
                w.wardnumber,
                pm.landmark,
                pm.zoneid,
                zone.departmentname,
                subpropertytypeid,pm.applicationnumber,pm.assessment,pm.ownedarea,pm.roadcode,rd.roadnamee
                ,ta.unit,pt.isagri,pm.isbefore2004  ,se.districtcode
			
offset pageoffset

fetch next pagesize rows only

)  app_json ) data_json;

return v_data_json;

END;

$$;


ALTER FUNCTION kaveri.fn_fetch_property_details_json_chk_03032026(_applicationnumber text, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_property_details_json_chk_06062025(text, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_property_details_json_chk_06062025(_applicationnumber text, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare
v_data_json json;
pageoffset integer:=0;
v_countrecord int;
v_partytypeid bool;
v_cntproperty int;
begin
	
	select count(*) into v_countrecord  from kaveri.propertymaster p where applicationnumber=_applicationnumber;
	
	select count(*) into v_cntproperty from kaveri.propertynumberdetails ps where propertyid in (select propertyid from kaveri.propertymaster where applicationnumber=_applicationnumber) 
	and ps.currentpropertytypeid in (1,60,65);

	select isownertobeclaimant into v_partytypeid from kaveri.stamprulesflag sf where sf.stampruleid in (Select stampruleid from kaveri.propertymaster p where p.applicationnumber =_applicationnumber limit 1);

pageoffset:=((pagenumber-1) * pagesize);

select row_to_json(data_json) into v_data_json from (

select array_to_json(array_agg(row_to_json(app_json)))

from (

select pm.propertyid as PIDNO,pm.villagecode,vi.villagenamee as Village,

ho.hoblicode,ho.hoblinamee as Hobli,ta.talukcode,ta.taluknamee as Taluk,

ta.districtcode,se.districtcode as kaveridistrictcode,di.districtnamee as District,

                pm.stamparticlecode,

                sp.articlenamee as stamparticle,

                pm.stampruleid,

                sr.descriptione as stampsubarticle,

                pm.regarticlecode,

                ra.articlenamee as registrationfeearticle,

--             sr.bookid,

                (case when pm.stamparticlecode = 14 and pm.isbefore2004=false  then

                 (select bookid from kaveri.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else dc.bookid end ) as bookid,

                --bt.booknameenglish as bookname,
	
                (select booknameenglish from kaveri.booktypemaster where bookid =

                (case when pm.stamparticlecode = 14 and pm.isbefore2004=false  then

                 (select bookid from kaveri.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else dc.bookid end )) as bookname,
                pm.srocode,

                se.sronamee as sroname,

                pm.propertytypeid,

                pt.propertytypename,

                pm.noofscanpages,

                pm.ismovableproperty,

                pm.movablepropertydesc,

                w.wardid,

                pm.totalarea,

                me.descriptionenglish as unit,

                w.wardnumber,

                pm.landmark,

                pm.zoneid,

                zone.departmentname as zonename,

                subpropertytypeid,

                ( select array_to_json(array_agg(row_to_json(partypndetails)))

      from (

                  select b.survey_no,b.hissa_no,(select string_agg(firstname,', ')  from kaveri.partyinfo pp where pp.propertyid =a.propertyid and pp.partytypeid= (case when v_partytypeid=true then 1 else 2 end)) as ownername,

                                  /* COMMENTED ON 01-10-2022 as ownername is only single owner*/

                                --  string_agg(a.firstname,',') as ownername,

--                                  coalesce(r.relatione,a.relationship) as relationship,a.relativename,
                  
				(select coalesce(r.relatione,a.relationship) from kaveri.partyinfo a1 
							where a1.ownerno in (select min(ownerno) from kaveri.partyinfo p where propertyid=a.propertyid) 
									and r.id::text=a1.relationship::text
							and a1.propertyid=a.propertyid and a1.partytypeid= (case when v_partytypeid=true then 1 else 2 end ))   as relationship,a.relativename,                

a.transactextacre as transactextacre,a.transactextgunta as transactextgunta ,a.transactextfgunta as transactextfgunta from

kaveri.partyinfo a inner join kaveri.propertynumberdetails b on a.propertyid = b.propertyid

                                 -- and a.partytypeid = 2 /* commented on 30-07-2022 - in discharge deed, owner will be marked as claimant */

                                  left join kaveri.relationshipmasters r on r.id::text = a.relationship::text 

                                  --a.relationship in ('3','4','5','6','7','8')

                                  where a.applicationnumber = pm.applicationnumber and pm.propertyid= b.propertyid and a.partytypeid= (case when v_partytypeid=true then 1 else 2 end)
									group by b.survey_no,b.hissa_no,r.relatione,a.relationship,a.relativename
                                   ,a.transactextacre,a.transactextgunta,a.transactextfgunta,a.propertyid,r.id,a.ownerno
                                   order by a.ownerno limit 1
                                 
									--group by b.survey_no , b.hissa_no,r.relatione,a.relativename,a.relationship,

     --  a.transactextacre,a.transactextgunta,

                                --   a.transactextfgunta

                  )partypndetails) as partyinfopropnumberdetails,

( select array_to_json(array_agg(row_to_json(prptyno)))

      from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,

                                                pntm.typenameenglish as propertynumbertype,

                                                pnd.currentnumber,pnd.hissa_no,pnd.survey_no,pnd.description as propertynumberdescription

                                                from kaveri.propertynumberdetails pnd

                                   left join kaveri.propertynotypemaster pntm                                    

                                                on (pntm.propertytypeid = pnd.currentpropertytypeid)

                                   where pnd.propertyid = pm.propertyid and

                                                pm.applicationnumber = _applicationnumber

                                   )prptyno )

                                                as propertynumberdetails,

                ( select array_to_json(array_agg(row_to_json(courtorderagri)))

                from (

               

                select * from kaveri.vw_fetch_court_order_details co  where  co.propertyid in (select pm.propertyid from kaveri.propertymaster pm where applicationnumber=_applicationnumber)
		 and

                applicationnumber = _applicationnumber and (co.currentpropertytypeid <> 1 or co.currentpropertytypeid=1) and co.villagecode in (select p7.villagecode from kaveri.propertymaster p7 where applicationnumber=_applicationnumber) 

                ) courtorderagri) as Courtdataagri,

                ( select array_to_json(array_agg(row_to_json(partynonagri

)))

                from (

                select pm.assessment as pid,

                pa.firstname as ownername,

                pm.landmark as propertydescription ,

                pm.ownedarea as totalarea

     from kaveri.partyinfo pa where pa.propertyid = pm.propertyid

                )partynonagri)partyinfononagri,

                ( select array_to_json(array_agg(row_to_json(courtordernonagri)))

                from (

                                select * from kaveri.vw_fetch_court_order_details na where na.propertyid in (select pm.propertyid from kaveri.propertymaster pm where applicationnumber=_applicationnumber)
			and

                applicationnumber = _applicationnumber and (na.currentpropertytypeid <>1 or na.currentpropertytypeid=1) and na.villagecode in (select p6.villagecode from kaveri.propertymaster p6 where applicationnumber=_applicationnumber)

                                )courtordernonagri)as courtdatanonagri,

                ( select array_to_json(array_agg(row_to_json(propertyliability)))

                from (SELECT

a.liabilityid,

a.entrydate,

a.issuedate,

a.issuedby,

a.amount,

a.ordernumber,

a.liabilitynote,

a.srocode,

a.sronamee,

a.userid,

a.drocode,

a.mappingid,

a.documentid,

a.propertyid,

false

FROM kaveri.vw_liability_search a

where a.srocode = pm.srocode and a.currentnumber

in

(select pnd.currentnumber from kaveri.propertymaster pm1 left outer join kaveri.propertynumberdetails pnd on pm1.propertyid=pnd.propertyid

where pm1.propertyid=pm.propertyid)) propertyliability ) as liabilitydata,

                ( select array_to_json(array_agg(row_to_json(propertyschedules)))

                from

(select scheduleid,

                ps.propertyid,

                ps.srocode,

                ps.partyid,

                ps.scheduletype,

                pm.totalarea,

                ps.unitid,

                ps.description,

                ps.partyids,

                ps.aileniatedauthorityid,

                ps.alieniatedorder,

                ps.bhoomisellerpartyids,

                ps.govtrestricorder,

                ps.govtrestrictionid,

                ps.landcode,propertygroup,

                ps.giftshare,

                ps.giftsharedetails,

                ps.easttowest,

                ps.northtosouth,

                ps.blockchainpropertyid,

                ps.assignedblockchainpid,

                ps.applicationnumber,

                ps.verified,

                ps.issroapproved,

                ps.eastboundary,

                ps.westboundary,

                ps.northboundary,

                ps.southboundary,

                p.transactextacre,

                p.transactextgunta,

                p.transactextfgunta

                from kaveri.propertyschedules ps
                 join (select * from kaveri.partyinfo p where partytypeid = 2 and (case when v_cntproperty>0 then
				 propertyid=pm.propertyid else p.applicationnumber=_applicationnumber end) order by ownerno limit 1)as p
				on (case when v_cntproperty>0 then ps.propertyid=p.propertyid else p.applicationnumber=ps.applicationnumber end)
				 join kaveri.propertymaster pmm on ps.propertyid=pmm.propertyid               
				left join kaveri.stamprulesflag sf on sf.stampruleid =pmm.stampruleid 
				where ps.applicationnumber=_applicationnumber and ps.propertyid  = pm.propertyid and  p.partytypeid =(case when sf.isownertobeclaimant=true then 1 else 2 end)

                order by ps.scheduleid 


                
) propertyschedules) as propertyschedulesdata,

v_countrecord as countofrecord,

pm.roadcode as roadcode,

rd.roadnamee as roadnamee,

ta.unit as unittype,

pt.isagri as isagriculture


from kaveri.propertymaster pm 
join kaveri.bhoomimappingdetails bh on (pm.villagecode=bh.kaverivillagecode) and bh.bhoomivillagecode<>0
left join kaveri.bhoomivillagemaster vi on (bh.bhoomivillagecode  = vi.villagecode and bh.bhoomitalukcode=vi.talukcode and bh.bhoomidistrictcode=vi.districtcode and bh.bhoomihobicode=vi.hoblicode)
left join kaveri.bhoomihoblimaster ho on (ho.hoblicode =bh.bhoomihobicode and ho.talukcode=bh.bhoomitalukcode  and ho.districtcode=bh.bhoomidistrictcode)
join kaveri.bhoomitalukmaster ta on (bh.bhoomitalukcode=ta.talukcode and bh.bhoomidistrictcode=ta.districtcode)
left join kaveri.bhoomidistrictmaster  di on (di.districtcode = ta.districtcode)
left join kaveri.documentmaster dc on (dc.regarticlecode = pm.regarticlecode and dc.documentid=pm.documentid)
left join kaveri.stamparticles sp on (sp.stamparticlecode = pm.stamparticlecode)
left join kaveri.stamprules sr on (sr.stampruleid = pm.stampruleid)
left join kaveri.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
left join kaveri.booktypemaster bt on (bt.bookid = sr.bookid)
left join kaveri.sromaster se on (se.srocode = pm.srocode)
left join kaveri.propertytypemaster pt on pt.propertytypeid = pm.propertytypeid
left join kaveri.villagewardmapping vw on vw.villagecode = pm.villagecode and vw.wardid = pm.wardid and pm.ismovableproperty=false
left join kaveri.warddetails w on  w.wardid = pm.wardid
left join kaveri.measunitmaster me on me.unitid = pm.unitid
left join kaveri.integrationdepartment zone on pm.zoneid = zone.udeptid
left join kaveri.roadmaster rd on (pm.roadcode=rd.roadcode)
where pm.applicationnumber = _applicationnumber and pt.isagri=true

group by pm.propertyid,pm.villagecode,vi.villagenamee,ho.hoblicode,ho.hoblinamee,ta.talukcode,ta.taluknamee,ta.districtcode,di.districtnamee              

,pm.stamparticlecode,sp.articlenamee,pm.stampruleid,sr.descriptione,pm.regarticlecode,ra.articlenamee,dc.bookid,bt.booknameenglish  

,pm.srocode,se.sronamee,

pm.propertytypeid,

                pt.propertytypename,

                pm.noofscanpages,

                pm.ismovableproperty,

                pm.movablepropertydesc,

                w.wardid,

                pm.totalarea,

                me.descriptionenglish,

                w.wardnumber,

                pm.landmark,

                pm.zoneid,

                zone.departmentname,

                subpropertytypeid,pm.applicationnumber,pm.assessment,pm.ownedarea,pm.roadcode,rd.roadnamee
                ,ta.unit,pt.isagri,pm.isbefore2004,se.districtcode



union ALL


select pm.propertyid as PIDNO,pm.villagecode,vi.villagenamee as Village,

vi.hoblicode,ho.hoblinamee as Hobli,vi.talukcode,ta.taluknamee as Taluk,

sm.districtcode,se.districtcode as kaveridistrictcode,di.districtnamee as District,

                pm.stamparticlecode,

                sp.articlenamee as stamparticle,

                pm.stampruleid,

                sr.descriptione as stampsubarticle,

                pm.regarticlecode,

                ra.articlenamee as registrationfeearticle,

--             sr.bookid,

                (case when pm.stamparticlecode = 14 and pm.isbefore2004=false then

                 (select bookid from kaveri.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else dc.bookid end ) as bookid,

                --bt.booknameenglish as bookname,
	
                (select booknameenglish from kaveri.booktypemaster where bookid =

                (case when pm.stamparticlecode = 14 and pm.isbefore2004=false then

                 (select bookid from kaveri.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else dc.bookid end )) as bookname,
                pm.srocode,

                se.sronamee as sroname,

                pm.propertytypeid,

                pt.propertytypename,

                pm.noofscanpages,

                pm.ismovableproperty,

                pm.movablepropertydesc,

                w.wardid,

                pm.totalarea,

                me.descriptionenglish as unit,

                w.wardnumber,

                pm.landmark,

                pm.zoneid,

                zone.departmentname as zonename,

                subpropertytypeid,

                ( select array_to_json(array_agg(row_to_json(partypndetails)))

      from (

                  select b.survey_no,b.hissa_no,(select string_agg(firstname,', ')  from kaveri.partyinfo pp where pp.propertyid =a.propertyid and pp.partytypeid= (case when v_partytypeid=true then 1 else 2 end)) as ownername,

                                  /* COMMENTED ON 01-10-2022 as ownername is only single owner*/

                                  --string_agg(a.firstname,',') as ownername,

--                                  coalesce(r.relatione,a.relationship) as relationship,a.relativename,
                  (select coalesce(r.relatione,a.relationship) from kaveri.partyinfo a1
							where a1.ownerno in (select min(ownerno) from kaveri.partyinfo p 
															where propertyid=a.propertyid) 
									and r.id::text=a1.relationship::text
							and a1.propertyid=a.propertyid)   as relationship,a.relativename,

a.availableextacre as transactextacre,a.availableextgunta as transactextgunta ,a.availableextfgunta as transactextfgunta from

kaveri.partyinfo a inner join kaveri.propertynumberdetails b on a.propertyid = b.propertyid

                                 -- and a.partytypeid = 2 /* commented on 30-07-2022 - in discharge deed, owner will be marked as claimant */

                                  left join kaveri.relationshipmasters r on r.id::text = a.relationship::text 

                                  --a.relationship in ('3','4','5','6','7','8')

                                  where a.applicationnumber = pm.applicationnumber and pm.propertyid= b.propertyid and a.partytypeid= (case when v_partytypeid=true then 1 else 2 end)
								group by b.survey_no,b.hissa_no,r.relatione,a.relationship,a.availableextacre ,a.availableextgunta,a.availableextfgunta,a.relativename
								,a.propertyid,r.id,a.ownerno
								order by a.ownerno limit 1
								--group by b.survey_no , b.hissa_no,r.relatione,a.relativename,a.relationship,

     --  a.transactextacre,a.transactextgunta,

                                --   a.transactextfgunta

                  )partypndetails) as partyinfopropnumberdetails,

( select array_to_json(array_agg(row_to_json(prptyno)))

      from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,

                                                pntm.typenameenglish as propertynumbertype,

                                                pnd.currentnumber,pnd.hissa_no,pnd.survey_no,pnd.description as propertynumberdescription

                                                from kaveri.propertynumberdetails pnd

                                   left join kaveri.propertynotypemaster pntm                                    

                                                on (pntm.propertytypeid = pnd.currentpropertytypeid)

                                   where pnd.propertyid = pm.propertyid and

                                                pm.applicationnumber = _applicationnumber

                                   )prptyno )

                                                as propertynumberdetails,

                ( select array_to_json(array_agg(row_to_json(courtorderagri)))

                from (

               

                select * from kaveri.vw_fetch_court_order_details co  where  co.propertyid in (select pm.propertyid from kaveri.propertymaster pm where applicationnumber=_applicationnumber)
		 and

                applicationnumber = _applicationnumber and (co.currentpropertytypeid <> 1 or co.currentpropertytypeid=1) and co.villagecode in (select p7.villagecode from kaveri.propertymaster p7 where applicationnumber=_applicationnumber) 

                ) courtorderagri) as Courtdataagri,

                ( select array_to_json(array_agg(row_to_json(partynonagri

)))

                from (

                select pm.assessment as pid,

                pa.firstname as ownername,

                pm.landmark as propertydescription ,

                pm.ownedarea as totalarea

     from kaveri.partyinfo pa where pa.propertyid = pm.propertyid

                )partynonagri)partyinfononagri,

 ( select array_to_json(array_agg(row_to_json(courtordernonagri)))
                from (
select * from kaveri.vw_fetch_court_order_details na where na.propertyid in (select pm.propertyid from kaveri.propertymaster pm where applicationnumber=_applicationnumber) 
and
 applicationnumber = _applicationnumber and (na.currentpropertytypeid <>1 or na.currentpropertytypeid=1) 
 and na.villagecode in (select p6.villagecode from kaveri.propertymaster p6 where applicationnumber=_applicationnumber)
)courtordernonagri)as courtdatanonagri,

                ( select array_to_json(array_agg(row_to_json(propertyliability)))

                from (SELECT

a.liabilityid,

a.entrydate,

a.issuedate,

a.issuedby,

a.amount,

a.ordernumber,

a.liabilitynote,

a.srocode,

a.sronamee,
a.userid,
a.drocode,
a.mappingid,
a.documentid,
a.propertyid,
false
FROM kaveri.vw_liability_search a
where a.srocode = pm.srocode and a.currentnumber
in
(select pnd.currentnumber from kaveri.propertymaster pm1 left outer join kaveri.propertynumberdetails pnd on pm1.propertyid=pnd.propertyid
where pm1.propertyid=pm.propertyid)) propertyliability ) as liabilitydata,
                ( select array_to_json(array_agg(row_to_json(propertyschedules)))
                from
(select scheduleid,
                ps.propertyid,
                ps.srocode,
                ps.partyid,
                ps.scheduletype,
                pm.totalarea,
                ps.unitid,
                ps.description,
                ps.partyids,
                ps.aileniatedauthorityid,
                ps.alieniatedorder,
                ps.bhoomisellerpartyids,
                ps.govtrestricorder,
                ps.govtrestrictionid,
                ps.landcode,propertygroup,
                ps.giftshare,
                ps.giftsharedetails,
                ps.easttowest,
                ps.northtosouth,
                ps.blockchainpropertyid,
                ps.assignedblockchainpid,
                ps.applicationnumber,
                ps.verified,
                ps.issroapproved,
                ps.eastboundary,
                ps.westboundary,
                ps.northboundary,
                ps.southboundary,
                p.transactextacre,
                p.transactextgunta,
                p.transactextfgunta
                from kaveri.propertyschedules ps
                 join (select * from kaveri.partyinfo p where partytypeid = 2 and (case when v_cntproperty>0 then
				 propertyid  = pm.propertyid else p.applicationnumber=_applicationnumber end) order by ownerno limit 1)as p 
				 on (case when v_cntproperty>0 then ps.propertyid=p.propertyid else p.applicationnumber=ps.applicationnumber end)
                 join kaveri.propertymaster pmm on ps.propertyid=pmm.propertyid               
				left join kaveri.stamprulesflag sf on sf.stampruleid =pmm.stampruleid 
                where ps.applicationnumber=_applicationnumber and ps.propertyid  = pm.propertyid and  p.partytypeid =(case when sf.isownertobeclaimant=true then 1 else 2 end)
                order by ps.scheduleid limit 1
) propertyschedules) as propertyschedulesdata,
v_countrecord as countofrecord,
pm.roadcode as roadcode,
rd.roadnamee as roadnamee,
ta.unit as unittype,
pt.isagri as isagriculture
from kaveri.propertymaster pm 
left join kaveri.villagemaster vi on (pm.villagecode = vi.villagecode)
left join kaveri.sromaster sm on (vi.srocode=sm.srocode)
left join kaveri.hoblimaster ho on (ho.hoblicode = vi.hoblicode)
left join kaveri.talukmaster ta on (ta.talukcode=vi.talukcode)
left join kaveri.districtmaster di on (di.districtcode = sm.districtcode)
--left join kaveri.bhoomidistrictmaster  di on (di.districtcode = ta.districtcode)
left join kaveri.documentmaster dc on (dc.regarticlecode = pm.regarticlecode and dc.documentid=pm.documentid)
left join kaveri.stamparticles sp on (sp.stamparticlecode = pm.stamparticlecode)
left join kaveri.stamprules sr on (sr.stampruleid = pm.stampruleid)
left join kaveri.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
left join kaveri.booktypemaster bt on (bt.bookid = sr.bookid)
left join kaveri.sromaster se on (se.srocode = pm.srocode)
left join kaveri.propertytypemaster pt on pt.propertytypeid = pm.propertytypeid
left join kaveri.villagewardmapping vw on vw.villagecode = pm.villagecode and vw.wardid = pm.wardid and pm.ismovableproperty=false
left join kaveri.warddetails w on  w.wardid = pm.wardid
left join kaveri.measunitmaster me on me.unitid = pm.unitid
left join kaveri.integrationdepartment zone on pm.zoneid = zone.udeptid
left join kaveri.roadmaster rd on (pm.roadcode=rd.roadcode)
where pm.applicationnumber = _applicationnumber and pt.isagri=false
group by pm.propertyid,pm.villagecode,vi.villagenamee,vi.hoblicode,ho.hoblinamee,vi.talukcode,ta.taluknamee,sm.districtcode,di.districtnamee              
,pm.stamparticlecode,sp.articlenamee,pm.stampruleid,sr.descriptione,pm.regarticlecode,ra.articlenamee,dc.bookid,bt.booknameenglish  
,pm.srocode,se.sronamee,
pm.propertytypeid,
                pt.propertytypename,
                pm.noofscanpages,
                pm.ismovableproperty,
                pm.movablepropertydesc,
                w.wardid,
                pm.totalarea,
                me.descriptionenglish,
                w.wardnumber,
                pm.landmark,
                pm.zoneid,
                zone.departmentname,
                subpropertytypeid,pm.applicationnumber,pm.assessment,pm.ownedarea,pm.roadcode,rd.roadnamee
                ,ta.unit,pt.isagri,pm.isbefore2004  ,se.districtcode
			
offset pageoffset

fetch next pagesize rows only

)  app_json ) data_json;

return v_data_json;

END;

$$;


ALTER FUNCTION kaveri.fn_fetch_property_details_json_chk_06062025(_applicationnumber text, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_fetch_property_details_json_chk_1(text, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_property_details_json_chk_1(_applicationnumber text, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare
v_data_json json;
pageoffset integer:=0;
v_countrecord int;
v_partytypeid bool;
v_cntproperty int;
begin
	
	select count(*) into v_countrecord  from kaveri.propertymaster p where applicationnumber=_applicationnumber;
	
	select count(*) into v_cntproperty from kaveri.propertynumberdetails ps where propertyid in (select propertyid from kaveri.propertymaster where applicationnumber=_applicationnumber) 
	and ps.currentpropertytypeid in (1,60,65);

	select isownertobeclaimant into v_partytypeid from kaveri.stamprulesflag sf where sf.stampruleid in (Select stampruleid from kaveri.propertymaster p where p.applicationnumber =_applicationnumber limit 1);

pageoffset:=((pagenumber-1) * pagesize);

select row_to_json(data_json) into v_data_json from (

select array_to_json(array_agg(row_to_json(app_json)))

from (

select pm.propertyid as PIDNO,pm.villagecode,vi.villagenamee as Village,

ho.hoblicode,ho.hoblinamee as Hobli,ta.talukcode,ta.taluknamee as Taluk,

ta.districtcode,di.districtnamee as District,

                pm.stamparticlecode,

                sp.articlenamee as stamparticle,

                pm.stampruleid,

                sr.descriptione as stampsubarticle,

                pm.regarticlecode,

                ra.articlenamee as registrationfeearticle,

--             sr.bookid,

                (case when pm.stamparticlecode = 14 and pm.isbefore2004=false  then

                 (select bookid from kaveri.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else dc.bookid end ) as bookid,

                --bt.booknameenglish as bookname,
	
                (select booknameenglish from kaveri.booktypemaster where bookid =

                (case when pm.stamparticlecode = 14 and pm.isbefore2004=false  then

                 (select bookid from kaveri.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else dc.bookid end )) as bookname,
                pm.srocode,

                se.sronamee as sroname,

                pm.propertytypeid,

                pt.propertytypename,

                pm.noofscanpages,

                pm.ismovableproperty,

                pm.movablepropertydesc,

                w.wardid,

                pm.totalarea,

                me.descriptionenglish as unit,

                w.wardnumber,

                pm.landmark,

                pm.zoneid,

                zone.departmentname as zonename,

                subpropertytypeid,

                ( select array_to_json(array_agg(row_to_json(partypndetails)))

      from (

                  select b.survey_no,b.hissa_no,(select string_agg(firstname,', ')  from kaveri.partyinfo pp where pp.propertyid =a.propertyid and pp.partytypeid= (case when v_partytypeid=true then 1 else 2 end)) as ownername,

                                  /* COMMENTED ON 01-10-2022 as ownername is only single owner*/

                                --  string_agg(a.firstname,',') as ownername,

--                                  coalesce(r.relatione,a.relationship) as relationship,a.relativename,
                  
				(select coalesce(r.relatione,a.relationship) from kaveri.partyinfo a1 
							where a1.ownerno in (select min(ownerno) from kaveri.partyinfo p where propertyid=a.propertyid) 
									and r.id::text=a1.relationship::text
							and a1.propertyid=a.propertyid and a1.partytypeid= (case when v_partytypeid=true then 1 else 2 end ))   as relationship,a.relativename,                

a.transactextacre as transactextacre,a.transactextgunta as transactextgunta ,a.transactextfgunta as transactextfgunta from

kaveri.partyinfo a inner join kaveri.propertynumberdetails b on a.propertyid = b.propertyid

                                 -- and a.partytypeid = 2 /* commented on 30-07-2022 - in discharge deed, owner will be marked as claimant */

                                  left join kaveri.relationshipmasters r on r.id::text = a.relationship::text 

                                  --a.relationship in ('3','4','5','6','7','8')

                                  where a.applicationnumber = pm.applicationnumber and pm.propertyid= b.propertyid and a.partytypeid= (case when v_partytypeid=true then 1 else 2 end)
									group by b.survey_no,b.hissa_no,r.relatione,a.relationship,a.relativename
                                   ,a.transactextacre,a.transactextgunta,a.transactextfgunta,a.propertyid,r.id,a.ownerno
                                   order by a.ownerno limit 1
                                 
									--group by b.survey_no , b.hissa_no,r.relatione,a.relativename,a.relationship,

     --  a.transactextacre,a.transactextgunta,

                                --   a.transactextfgunta

                  )partypndetails) as partyinfopropnumberdetails,

( select array_to_json(array_agg(row_to_json(prptyno)))

      from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,

                                                pntm.typenameenglish as propertynumbertype,

                                                pnd.currentnumber,pnd.hissa_no,pnd.survey_no,pnd.description as propertynumberdescription

                                                from kaveri.propertynumberdetails pnd

                                   left join kaveri.propertynotypemaster pntm                                    

                                                on (pntm.propertytypeid = pnd.currentpropertytypeid)

                                   where pnd.propertyid = pm.propertyid and

                                                pm.applicationnumber = _applicationnumber

                                   )prptyno )

                                                as propertynumberdetails,

                ( select array_to_json(array_agg(row_to_json(courtorderagri)))

                from (

               

                select * from kaveri.vw_fetch_court_order_details co  where  co.propertyid in (select pm.propertyid from kaveri.propertymaster pm where applicationnumber=_applicationnumber)
		 and

                applicationnumber = _applicationnumber and (co.currentpropertytypeid <> 1 or co.currentpropertytypeid=1) and co.villagecode in (select p7.villagecode from kaveri.propertymaster p7 where applicationnumber=_applicationnumber) 

                ) courtorderagri) as Courtdataagri,

                ( select array_to_json(array_agg(row_to_json(partynonagri

)))

                from (

                select pm.assessment as pid,

                pa.firstname as ownername,

                pm.landmark as propertydescription ,

                pm.ownedarea as totalarea

     from kaveri.partyinfo pa where pa.propertyid = pm.propertyid

                )partynonagri)partyinfononagri,

                ( select array_to_json(array_agg(row_to_json(courtordernonagri)))

                from (

                                select * from kaveri.vw_fetch_court_order_details na where na.propertyid in (select pm.propertyid from kaveri.propertymaster pm where applicationnumber=_applicationnumber)
			and

                applicationnumber = _applicationnumber and (na.currentpropertytypeid <>1 or na.currentpropertytypeid=1) and na.villagecode in (select p6.villagecode from kaveri.propertymaster p6 where applicationnumber=_applicationnumber)

                                )courtordernonagri)as courtdatanonagri,

                ( select array_to_json(array_agg(row_to_json(propertyliability)))

                from (SELECT

a.liabilityid,

a.entrydate,

a.issuedate,

a.issuedby,

a.amount,

a.ordernumber,

a.liabilitynote,

a.srocode,

a.sronamee,

a.userid,

a.drocode,

a.mappingid,

a.documentid,

a.propertyid,

false

FROM kaveri.vw_liability_search a

where a.srocode = pm.srocode and a.currentnumber

in

(select pnd.currentnumber from kaveri.propertymaster pm1 left outer join kaveri.propertynumberdetails pnd on pm1.propertyid=pnd.propertyid

where pm1.propertyid=pm.propertyid)) propertyliability ) as liabilitydata,

                ( select array_to_json(array_agg(row_to_json(propertyschedules)))

                from

(select scheduleid,

                ps.propertyid,

                ps.srocode,

                ps.partyid,

                ps.scheduletype,

                pm.totalarea,

                ps.unitid,

                ps.description,

                ps.partyids,

                ps.aileniatedauthorityid,

                ps.alieniatedorder,

                ps.bhoomisellerpartyids,

                ps.govtrestricorder,

                ps.govtrestrictionid,

                ps.landcode,propertygroup,

                ps.giftshare,

                ps.giftsharedetails,

                ps.easttowest,

                ps.northtosouth,

                ps.blockchainpropertyid,

                ps.assignedblockchainpid,

                ps.applicationnumber,

                ps.verified,

                ps.issroapproved,

                ps.eastboundary,

                ps.westboundary,

                ps.northboundary,

                ps.southboundary,

                p.transactextacre,

                p.transactextgunta,

                p.transactextfgunta

                from kaveri.propertyschedules ps
                 join (select * from kaveri.partyinfo p where partytypeid = 2 and (case when v_cntproperty>0 then
				 propertyid=pm.propertyid else p.applicationnumber=_applicationnumber end) order by ownerno limit 1)as p
				on (case when v_cntproperty>0 then ps.propertyid=p.propertyid else p.applicationnumber=ps.applicationnumber end)
				 join kaveri.propertymaster pmm on ps.propertyid=pmm.propertyid               
				left join kaveri.stamprulesflag sf on sf.stampruleid =pmm.stampruleid 
				where ps.applicationnumber=_applicationnumber and ps.propertyid  = pm.propertyid and  p.partytypeid =(case when sf.isownertobeclaimant=true then 1 else 2 end)

                order by ps.scheduleid 


                
) propertyschedules) as propertyschedulesdata,

v_countrecord as countofrecord,

pm.roadcode as roadcode,

rd.roadnamee as roadnamee,

ta.unit as unittype,

pt.isagri as isagriculture


from kaveri.propertymaster pm 
join kaveri.bhoomimappingdetails bh on (pm.villagecode=bh.kaverivillagecode) and bh.bhoomivillagecode<>0
left join kaveri.bhoomivillagemaster vi on (bh.bhoomivillagecode  = vi.villagecode and bh.bhoomitalukcode=vi.talukcode and bh.bhoomidistrictcode=vi.districtcode and bh.bhoomihobicode=vi.hoblicode)
left join kaveri.bhoomihoblimaster ho on (ho.hoblicode =bh.bhoomihobicode and ho.talukcode=bh.bhoomitalukcode  and ho.districtcode=bh.bhoomidistrictcode)
join kaveri.bhoomitalukmaster ta on (bh.bhoomitalukcode=ta.talukcode and bh.bhoomidistrictcode=ta.districtcode)
left join kaveri.bhoomidistrictmaster  di on (di.districtcode = ta.districtcode)
left join kaveri.documentmaster dc on (dc.regarticlecode = pm.regarticlecode and dc.documentid=pm.documentid)
left join kaveri.stamparticles sp on (sp.stamparticlecode = pm.stamparticlecode)
left join kaveri.stamprules sr on (sr.stampruleid = pm.stampruleid)
left join kaveri.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
left join kaveri.booktypemaster bt on (bt.bookid = sr.bookid)
left join kaveri.sromaster se on (se.srocode = pm.srocode)
left join kaveri.propertytypemaster pt on pt.propertytypeid = pm.propertytypeid
left join kaveri.villagewardmapping vw on vw.villagecode = pm.villagecode and vw.wardid = pm.wardid and pm.ismovableproperty=false
left join kaveri.warddetails w on  w.wardid = pm.wardid
left join kaveri.measunitmaster me on me.unitid = pm.unitid
left join kaveri.integrationdepartment zone on pm.zoneid = zone.udeptid
left join kaveri.roadmaster rd on (pm.roadcode=rd.roadcode)
where pm.applicationnumber = _applicationnumber and pt.isagri=true

group by pm.propertyid,pm.villagecode,vi.villagenamee,ho.hoblicode,ho.hoblinamee,ta.talukcode,ta.taluknamee,ta.districtcode,di.districtnamee              

,pm.stamparticlecode,sp.articlenamee,pm.stampruleid,sr.descriptione,pm.regarticlecode,ra.articlenamee,dc.bookid,bt.booknameenglish  

,pm.srocode,se.sronamee,

pm.propertytypeid,

                pt.propertytypename,

                pm.noofscanpages,

                pm.ismovableproperty,

                pm.movablepropertydesc,

                w.wardid,

                pm.totalarea,

                me.descriptionenglish,

                w.wardnumber,

                pm.landmark,

                pm.zoneid,

                zone.departmentname,

                subpropertytypeid,pm.applicationnumber,pm.assessment,pm.ownedarea,pm.roadcode,rd.roadnamee
                ,ta.unit,pt.isagri,pm.isbefore2004



union ALL


select pm.propertyid as PIDNO,pm.villagecode,vi.villagenamee as Village,

vi.hoblicode,ho.hoblinamee as Hobli,vi.talukcode,ta.taluknamee as Taluk,

sm.districtcode,di.districtnamee as District,

                pm.stamparticlecode,

                sp.articlenamee as stamparticle,

                pm.stampruleid,

                sr.descriptione as stampsubarticle,

                pm.regarticlecode,

                ra.articlenamee as registrationfeearticle,

--             sr.bookid,

                (case when pm.stamparticlecode = 14 and pm.isbefore2004=false then

                 (select bookid from kaveri.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else dc.bookid end ) as bookid,

                --bt.booknameenglish as bookname,
	
                (select booknameenglish from kaveri.booktypemaster where bookid =

                (case when pm.stamparticlecode = 14 and pm.isbefore2004=false then

                 (select bookid from kaveri.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else dc.bookid end )) as bookname,
                pm.srocode,

                se.sronamee as sroname,

                pm.propertytypeid,

                pt.propertytypename,

                pm.noofscanpages,

                pm.ismovableproperty,

                pm.movablepropertydesc,

                w.wardid,

                pm.totalarea,

                me.descriptionenglish as unit,

                w.wardnumber,

                pm.landmark,

                pm.zoneid,

                zone.departmentname as zonename,

                subpropertytypeid,

                ( select array_to_json(array_agg(row_to_json(partypndetails)))

      from (

                  select b.survey_no,b.hissa_no,(select string_agg(firstname,', ')  from kaveri.partyinfo pp where pp.propertyid =a.propertyid and pp.partytypeid= (case when v_partytypeid=true then 1 else 2 end)) as ownername,

                                  /* COMMENTED ON 01-10-2022 as ownername is only single owner*/

                                  --string_agg(a.firstname,',') as ownername,

--                                  coalesce(r.relatione,a.relationship) as relationship,a.relativename,
                  (select coalesce(r.relatione,a.relationship) from kaveri.partyinfo a1
							where a1.ownerno in (select min(ownerno) from kaveri.partyinfo p 
															where propertyid=a.propertyid) 
									and r.id::text=a1.relationship::text
							and a1.propertyid=a.propertyid)   as relationship,a.relativename,

a.availableextacre as transactextacre,a.availableextgunta as transactextgunta ,a.availableextfgunta as transactextfgunta from

kaveri.partyinfo a inner join kaveri.propertynumberdetails b on a.propertyid = b.propertyid

                                 -- and a.partytypeid = 2 /* commented on 30-07-2022 - in discharge deed, owner will be marked as claimant */

                                  left join kaveri.relationshipmasters r on r.id::text = a.relationship::text 

                                  --a.relationship in ('3','4','5','6','7','8')

                                  where a.applicationnumber = pm.applicationnumber and pm.propertyid= b.propertyid and a.partytypeid= (case when v_partytypeid=true then 1 else 2 end)
								group by b.survey_no,b.hissa_no,r.relatione,a.relationship,a.availableextacre ,a.availableextgunta,a.availableextfgunta,a.relativename
								,a.propertyid,r.id,a.ownerno
								order by a.ownerno limit 1
								--group by b.survey_no , b.hissa_no,r.relatione,a.relativename,a.relationship,

     --  a.transactextacre,a.transactextgunta,

                                --   a.transactextfgunta

                  )partypndetails) as partyinfopropnumberdetails,

( select array_to_json(array_agg(row_to_json(prptyno)))

      from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,

                                                pntm.typenameenglish as propertynumbertype,

                                                pnd.currentnumber,pnd.hissa_no,pnd.survey_no,pnd.description as propertynumberdescription

                                                from kaveri.propertynumberdetails pnd

                                   left join kaveri.propertynotypemaster pntm                                    

                                                on (pntm.propertytypeid = pnd.currentpropertytypeid)

                                   where pnd.propertyid = pm.propertyid and

                                                pm.applicationnumber = _applicationnumber

                                   )prptyno )

                                                as propertynumberdetails,

                ( select array_to_json(array_agg(row_to_json(courtorderagri)))

                from (

               

                select * from kaveri.vw_fetch_court_order_details co  where  co.propertyid in (select pm.propertyid from kaveri.propertymaster pm where applicationnumber=_applicationnumber)
		 and

                applicationnumber = _applicationnumber and (co.currentpropertytypeid <> 1 or co.currentpropertytypeid=1) and co.villagecode in (select p7.villagecode from kaveri.propertymaster p7 where applicationnumber=_applicationnumber) 

                ) courtorderagri) as Courtdataagri,

                ( select array_to_json(array_agg(row_to_json(partynonagri

)))

                from (

                select pm.assessment as pid,

                pa.firstname as ownername,

                pm.landmark as propertydescription ,

                pm.ownedarea as totalarea

     from kaveri.partyinfo pa where pa.propertyid = pm.propertyid

                )partynonagri)partyinfononagri,

 ( select array_to_json(array_agg(row_to_json(courtordernonagri)))
                from (
select * from kaveri.vw_fetch_court_order_details na where na.propertyid in (select pm.propertyid from kaveri.propertymaster pm where applicationnumber=_applicationnumber) 
and
 applicationnumber = _applicationnumber and (na.currentpropertytypeid <>1 or na.currentpropertytypeid=1) 
 and na.villagecode in (select p6.villagecode from kaveri.propertymaster p6 where applicationnumber=_applicationnumber)
)courtordernonagri)as courtdatanonagri,

                ( select array_to_json(array_agg(row_to_json(propertyliability)))

                from (SELECT

a.liabilityid,

a.entrydate,

a.issuedate,

a.issuedby,

a.amount,

a.ordernumber,

a.liabilitynote,

a.srocode,

a.sronamee,
a.userid,
a.drocode,
a.mappingid,
a.documentid,
a.propertyid,
false
FROM kaveri.vw_liability_search a
where a.srocode = pm.srocode and a.currentnumber
in
(select pnd.currentnumber from kaveri.propertymaster pm1 left outer join kaveri.propertynumberdetails pnd on pm1.propertyid=pnd.propertyid
where pm1.propertyid=pm.propertyid)) propertyliability ) as liabilitydata,
                ( select array_to_json(array_agg(row_to_json(propertyschedules)))
                from
(select scheduleid,
                ps.propertyid,
                ps.srocode,
                ps.partyid,
                ps.scheduletype,
                pm.totalarea,
                ps.unitid,
                ps.description,
                ps.partyids,
                ps.aileniatedauthorityid,
                ps.alieniatedorder,
                ps.bhoomisellerpartyids,
                ps.govtrestricorder,
                ps.govtrestrictionid,
                ps.landcode,propertygroup,
                ps.giftshare,
                ps.giftsharedetails,
                ps.easttowest,
                ps.northtosouth,
                ps.blockchainpropertyid,
                ps.assignedblockchainpid,
                ps.applicationnumber,
                ps.verified,
                ps.issroapproved,
                ps.eastboundary,
                ps.westboundary,
                ps.northboundary,
                ps.southboundary,
                p.transactextacre,
                p.transactextgunta,
                p.transactextfgunta
                from kaveri.propertyschedules ps
                 join (select * from kaveri.partyinfo p where partytypeid = 2 and (case when v_cntproperty>0 then
				 propertyid  = pm.propertyid else p.applicationnumber=_applicationnumber end) order by ownerno limit 1)as p 
				 on (case when v_cntproperty>0 then ps.propertyid=p.propertyid else p.applicationnumber=ps.applicationnumber end)
                 join kaveri.propertymaster pmm on ps.propertyid=pmm.propertyid               
				left join kaveri.stamprulesflag sf on sf.stampruleid =pmm.stampruleid 
                where ps.applicationnumber=_applicationnumber and ps.propertyid  = pm.propertyid and  p.partytypeid =(case when sf.isownertobeclaimant=true then 1 else 2 end)
                order by ps.scheduleid limit 1
) propertyschedules) as propertyschedulesdata,
v_countrecord as countofrecord,
pm.roadcode as roadcode,
rd.roadnamee as roadnamee,
ta.unit as unittype,
pt.isagri as isagriculture
from kaveri.propertymaster pm 
left join kaveri.villagemaster vi on (pm.villagecode = vi.villagecode)
left join kaveri.sromaster sm on (vi.srocode=sm.srocode)
left join kaveri.hoblimaster ho on (ho.hoblicode = vi.hoblicode)
left join kaveri.talukmaster ta on (ta.talukcode=vi.talukcode)
left join kaveri.districtmaster di on (di.districtcode = sm.districtcode)
--left join kaveri.bhoomidistrictmaster  di on (di.districtcode = ta.districtcode)
left join kaveri.documentmaster dc on (dc.regarticlecode = pm.regarticlecode and dc.documentid=pm.documentid)
left join kaveri.stamparticles sp on (sp.stamparticlecode = pm.stamparticlecode)
left join kaveri.stamprules sr on (sr.stampruleid = pm.stampruleid)
left join kaveri.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
left join kaveri.booktypemaster bt on (bt.bookid = sr.bookid)
left join kaveri.sromaster se on (se.srocode = pm.srocode)
left join kaveri.propertytypemaster pt on pt.propertytypeid = pm.propertytypeid
left join kaveri.villagewardmapping vw on vw.villagecode = pm.villagecode and vw.wardid = pm.wardid and pm.ismovableproperty=false
left join kaveri.warddetails w on  w.wardid = pm.wardid
left join kaveri.measunitmaster me on me.unitid = pm.unitid
left join kaveri.integrationdepartment zone on pm.zoneid = zone.udeptid
left join kaveri.roadmaster rd on (pm.roadcode=rd.roadcode)
where pm.applicationnumber = _applicationnumber and pt.isagri=false
group by pm.propertyid,pm.villagecode,vi.villagenamee,vi.hoblicode,ho.hoblinamee,vi.talukcode,ta.taluknamee,sm.districtcode,di.districtnamee              
,pm.stamparticlecode,sp.articlenamee,pm.stampruleid,sr.descriptione,pm.regarticlecode,ra.articlenamee,dc.bookid,bt.booknameenglish  
,pm.srocode,se.sronamee,
pm.propertytypeid,
                pt.propertytypename,
                pm.noofscanpages,
                pm.ismovableproperty,
                pm.movablepropertydesc,
                w.wardid,
                pm.totalarea,
                me.descriptionenglish,
                w.wardnumber,
                pm.landmark,
                pm.zoneid,
                zone.departmentname,
                subpropertytypeid,pm.applicationnumber,pm.assessment,pm.ownedarea,pm.roadcode,rd.roadnamee
                ,ta.unit,pt.isagri,pm.isbefore2004  
			
offset pageoffset

fetch next pagesize rows only

)  app_json ) data_json;

return v_data_json;

END;

$$;


ALTER FUNCTION kaveri.fn_fetch_property_details_json_chk_1(_applicationnumber text, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_property_details_json_chk_30102025(text, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: raghavendrap
--

CREATE FUNCTION kaveri.fn_fetch_property_details_json_chk_30102025(_applicationnumber text, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare
v_data_json json;
pageoffset integer:=0;
v_countrecord int;
v_partytypeid bool;
v_cntproperty int;
begin
	
	select count(*) into v_countrecord  from kaveri.propertymaster p where applicationnumber=_applicationnumber;
	
	select count(*) into v_cntproperty from kaveri.propertynumberdetails ps where propertyid in (select propertyid from kaveri.propertymaster where applicationnumber=_applicationnumber) 
	and ps.currentpropertytypeid in (1,60,65);

	select isownertobeclaimant into v_partytypeid from kaveri.stamprulesflag sf where sf.stampruleid in (Select stampruleid from kaveri.propertymaster p where p.applicationnumber =_applicationnumber limit 1);

pageoffset:=((pagenumber-1) * pagesize);

select row_to_json(data_json) into v_data_json from (

select array_to_json(array_agg(row_to_json(app_json)))

from (

select pm.propertyid as PIDNO,pm.villagecode,vi.villagenamee as Village,

ho.hoblicode,ho.hoblinamee as Hobli,ta.talukcode,ta.taluknamee as Taluk,

ta.districtcode,se.districtcode as kaveridistrictcode,di.districtnamee as District,

                pm.stamparticlecode,

                sp.articlenamee as stamparticle,

                pm.stampruleid,

                sr.descriptione as stampsubarticle,

                pm.regarticlecode,

                ra.articlenamee as registrationfeearticle,

--             sr.bookid,

                (case when pm.stamparticlecode = 14 and pm.isbefore2004=false  then

                 (select bookid from kaveri.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else dc.bookid end ) as bookid,

                --bt.booknameenglish as bookname,
	
                (select booknameenglish from kaveri.booktypemaster where bookid =

                (case when pm.stamparticlecode = 14 and pm.isbefore2004=false  then

                 (select bookid from kaveri.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else dc.bookid end )) as bookname,
                pm.srocode,

                se.sronamee as sroname,

                pm.propertytypeid,

                pt.propertytypename,

                pm.noofscanpages,

                pm.ismovableproperty,

                pm.movablepropertydesc,

                w.wardid,

                pm.totalarea,

                me.descriptionenglish as unit,

                w.wardnumber,

                pm.landmark,

                pm.zoneid,

                zone.departmentname as zonename,

                subpropertytypeid,

                ( select array_to_json(array_agg(row_to_json(partypndetails)))

      from (

                  select b.survey_no,b.hissa_no,
--				(select string_agg(firstname,', ')  from kaveri.partyinfo pp where pp.propertyid =a.propertyid and pp.partytypeid= (case when v_partytypeid=true then 1 else 2 end)) as ownername,

                                  /* COMMENTED ON 01-10-2022 as ownername is only single owner*/

                                --  string_agg(a.firstname,',') as ownername,

--                                  coalesce(r.relatione,a.relationship) as relationship,a.relativename,
				--raghavendra 
				(select string_agg(coalesce(firstname ||' '|| r.relatione ||' '|| relativename),', ') 
				from kaveri.partyinfo pp 
				join kaveri.relationshipmasters r on r.id::text =pp.relationship::text
				where pp.propertyid = a.propertyid and pp.ownerno in (select min(ownerno) from kaveri.partyinfo p where propertyid=a.propertyid and p.partytypeid= (case when v_partytypeid=true then 1 else 2 end)) 
				and pp.partytypeid= (case when v_partytypeid=true then 1 else 2 end)
				) as ownername ,'' as relationship,'' as relativename,  
                  
--				(select coalesce(r.relatione,a.relationship) from kaveri.partyinfo a1 
--							where a1.ownerno in (select min(ownerno) from kaveri.partyinfo p where propertyid=a.propertyid) 
--									and r.id::text=a1.relationship::text
--							and a1.propertyid=a.propertyid and a1.partytypeid= (case when v_partytypeid=true then 1 else 2 end ))   as relationship,a.relativename,                

a.transactextacre as transactextacre,a.transactextgunta as transactextgunta ,a.transactextfgunta as transactextfgunta from

kaveri.partyinfo a inner join kaveri.propertynumberdetails b on a.propertyid = b.propertyid

                                 -- and a.partytypeid = 2 /* commented on 30-07-2022 - in discharge deed, owner will be marked as claimant */

--                                  left join kaveri.relationshipmasters r on r.id::text = a.relationship::text 

                                  --a.relationship in ('3','4','5','6','7','8')

                                  where a.applicationnumber = pm.applicationnumber and pm.propertyid= b.propertyid and a.partytypeid= (case when v_partytypeid=true then 1 else 2 end)
									group by b.survey_no,b.hissa_no,
--									r.relatione,r.id
									a.relationship,a.relativename,a.transactextacre,a.transactextgunta,a.transactextfgunta,a.propertyid,a.ownerno
                                   order by a.ownerno limit 1
                                 
									--group by b.survey_no , b.hissa_no,r.relatione,a.relativename,a.relationship,

     --  a.transactextacre,a.transactextgunta,

                                --   a.transactextfgunta

                  )partypndetails) as partyinfopropnumberdetails,

( select array_to_json(array_agg(row_to_json(prptyno)))

      from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,

                                                pntm.typenameenglish as propertynumbertype,

                                                pnd.currentnumber,pnd.hissa_no,pnd.survey_no,pnd.description as propertynumberdescription

                                                from kaveri.propertynumberdetails pnd

                                   left join kaveri.propertynotypemaster pntm                                    

                                                on (pntm.propertytypeid = pnd.currentpropertytypeid)

                                   where pnd.propertyid = pm.propertyid and

                                                pm.applicationnumber = _applicationnumber

                                   )prptyno )

                                                as propertynumberdetails,

                ( select array_to_json(array_agg(row_to_json(courtorderagri)))

                from (

               

                select * from kaveri.vw_fetch_court_order_details co  where  co.propertyid in (select pm.propertyid from kaveri.propertymaster pm where applicationnumber=_applicationnumber)
		 and

                applicationnumber = _applicationnumber and (co.currentpropertytypeid <> 1 or co.currentpropertytypeid=1) and co.villagecode in (select p7.villagecode from kaveri.propertymaster p7 where applicationnumber=_applicationnumber) 

                ) courtorderagri) as Courtdataagri,

                ( select array_to_json(array_agg(row_to_json(partynonagri

)))

                from (

                select pm.assessment as pid,

                pa.firstname as ownername,

                pm.landmark as propertydescription ,

                pm.ownedarea as totalarea

     from kaveri.partyinfo pa where pa.propertyid = pm.propertyid

                )partynonagri)partyinfononagri,

                ( select array_to_json(array_agg(row_to_json(courtordernonagri)))

                from (

                                select * from kaveri.vw_fetch_court_order_details na where na.propertyid in (select pm.propertyid from kaveri.propertymaster pm where applicationnumber=_applicationnumber)
			and

                applicationnumber = _applicationnumber and (na.currentpropertytypeid <>1 or na.currentpropertytypeid=1) and na.villagecode in (select p6.villagecode from kaveri.propertymaster p6 where applicationnumber=_applicationnumber)

                                )courtordernonagri)as courtdatanonagri,

                ( select array_to_json(array_agg(row_to_json(propertyliability)))

                from (SELECT

a.liabilityid,

a.entrydate,

a.issuedate,

a.issuedby,

a.amount,

a.ordernumber,

a.liabilitynote,

a.srocode,

a.sronamee,

a.userid,

a.drocode,

a.mappingid,

a.documentid,

a.propertyid,

false

FROM kaveri.vw_liability_search a

where a.srocode = pm.srocode and a.currentnumber

in

(select pnd.currentnumber from kaveri.propertymaster pm1 left outer join kaveri.propertynumberdetails pnd on pm1.propertyid=pnd.propertyid

where pm1.propertyid=pm.propertyid)) propertyliability ) as liabilitydata,

                ( select array_to_json(array_agg(row_to_json(propertyschedules)))

                from

(select scheduleid,

                ps.propertyid,

                ps.srocode,

                ps.partyid,

                ps.scheduletype,

                pm.totalarea,

                ps.unitid,

                ps.description,

                ps.partyids,

                ps.aileniatedauthorityid,

                ps.alieniatedorder,

                ps.bhoomisellerpartyids,

                ps.govtrestricorder,

                ps.govtrestrictionid,

                ps.landcode,propertygroup,

                ps.giftshare,

                ps.giftsharedetails,

                ps.easttowest,

                ps.northtosouth,

                ps.blockchainpropertyid,

                ps.assignedblockchainpid,

                ps.applicationnumber,

                ps.verified,

                ps.issroapproved,

                ps.eastboundary,

                ps.westboundary,

                ps.northboundary,

                ps.southboundary,

                p.transactextacre,

                p.transactextgunta,

                p.transactextfgunta

                from kaveri.propertyschedules ps
                 join (select * from kaveri.partyinfo p where partytypeid = 2 and (case when v_cntproperty>0 then
				 propertyid=pm.propertyid else p.applicationnumber=_applicationnumber end) order by ownerno limit 1)as p
				on (case when v_cntproperty>0 then ps.propertyid=p.propertyid else p.applicationnumber=ps.applicationnumber end)
				 join kaveri.propertymaster pmm on ps.propertyid=pmm.propertyid               
				left join kaveri.stamprulesflag sf on sf.stampruleid =pmm.stampruleid 
				where ps.applicationnumber=_applicationnumber and ps.propertyid  = pm.propertyid and  p.partytypeid =(case when sf.isownertobeclaimant=true then 1 else 2 end)

                order by ps.scheduleid 


                
) propertyschedules) as propertyschedulesdata,

v_countrecord as countofrecord,

pm.roadcode as roadcode,

rd.roadnamee as roadnamee,

ta.unit as unittype,

pt.isagri as isagriculture


from kaveri.propertymaster pm 
join kaveri.bhoomimappingdetails bh on (pm.villagecode=bh.kaverivillagecode) and bh.bhoomivillagecode<>0
left join kaveri.bhoomivillagemaster vi on (bh.bhoomivillagecode  = vi.villagecode and bh.bhoomitalukcode=vi.talukcode and bh.bhoomidistrictcode=vi.districtcode and bh.bhoomihobicode=vi.hoblicode)
left join kaveri.bhoomihoblimaster ho on (ho.hoblicode =bh.bhoomihobicode and ho.talukcode=bh.bhoomitalukcode  and ho.districtcode=bh.bhoomidistrictcode)
join kaveri.bhoomitalukmaster ta on (bh.bhoomitalukcode=ta.talukcode and bh.bhoomidistrictcode=ta.districtcode)
left join kaveri.bhoomidistrictmaster  di on (di.districtcode = ta.districtcode)
left join kaveri.documentmaster dc on (dc.regarticlecode = pm.regarticlecode and dc.documentid=pm.documentid)
left join kaveri.stamparticles sp on (sp.stamparticlecode = pm.stamparticlecode)
left join kaveri.stamprules sr on (sr.stampruleid = pm.stampruleid)
left join kaveri.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
left join kaveri.booktypemaster bt on (bt.bookid = sr.bookid)
left join kaveri.sromaster se on (se.srocode = pm.srocode)
left join kaveri.propertytypemaster pt on pt.propertytypeid = pm.propertytypeid
left join kaveri.villagewardmapping vw on vw.villagecode = pm.villagecode and vw.wardid = pm.wardid and pm.ismovableproperty=false
left join kaveri.warddetails w on  w.wardid = pm.wardid
left join kaveri.measunitmaster me on me.unitid = pm.unitid
left join kaveri.integrationdepartment zone on pm.zoneid = zone.udeptid
left join kaveri.roadmaster rd on (pm.roadcode=rd.roadcode)
where pm.applicationnumber = _applicationnumber and pt.isagri=true

group by pm.propertyid,pm.villagecode,vi.villagenamee,ho.hoblicode,ho.hoblinamee,ta.talukcode,ta.taluknamee,ta.districtcode,di.districtnamee              

,pm.stamparticlecode,sp.articlenamee,pm.stampruleid,sr.descriptione,pm.regarticlecode,ra.articlenamee,dc.bookid,bt.booknameenglish  

,pm.srocode,se.sronamee,

pm.propertytypeid,

                pt.propertytypename,

                pm.noofscanpages,

                pm.ismovableproperty,

                pm.movablepropertydesc,

                w.wardid,

                pm.totalarea,

                me.descriptionenglish,

                w.wardnumber,

                pm.landmark,

                pm.zoneid,

                zone.departmentname,

                subpropertytypeid,pm.applicationnumber,pm.assessment,pm.ownedarea,pm.roadcode,rd.roadnamee
                ,ta.unit,pt.isagri,pm.isbefore2004,se.districtcode



union ALL


select pm.propertyid as PIDNO,pm.villagecode,vi.villagenamee as Village,

vi.hoblicode,ho.hoblinamee as Hobli,vi.talukcode,ta.taluknamee as Taluk,

sm.districtcode,se.districtcode as kaveridistrictcode,di.districtnamee as District,

                pm.stamparticlecode,

                sp.articlenamee as stamparticle,

                pm.stampruleid,

                sr.descriptione as stampsubarticle,

                pm.regarticlecode,

                ra.articlenamee as registrationfeearticle,

--             sr.bookid,

                (case when pm.stamparticlecode = 14 and pm.isbefore2004=false then

                 (select bookid from kaveri.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else dc.bookid end ) as bookid,

                --bt.booknameenglish as bookname,
	
                (select booknameenglish from kaveri.booktypemaster where bookid =

                (case when pm.stamparticlecode = 14 and pm.isbefore2004=false then

                 (select bookid from kaveri.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else dc.bookid end )) as bookname,
                pm.srocode,

                se.sronamee as sroname,

                pm.propertytypeid,

                pt.propertytypename,

                pm.noofscanpages,

                pm.ismovableproperty,

                pm.movablepropertydesc,

                w.wardid,

                pm.totalarea,

                me.descriptionenglish as unit,

                w.wardnumber,

                pm.landmark,

                pm.zoneid,

                zone.departmentname as zonename,

                subpropertytypeid,

                ( select array_to_json(array_agg(row_to_json(partypndetails)))

      from (

                  select b.survey_no,b.hissa_no,
--				(select string_agg(firstname,', ')  from kaveri.partyinfo pp where pp.propertyid =a.propertyid and pp.partytypeid= (case when v_partytypeid=true then 1 else 2 end)) as ownername,

                                  /* COMMENTED ON 01-10-2022 as ownername is only single owner*/

                                  --string_agg(a.firstname,',') as ownername,

--                                  coalesce(r.relatione,a.relationship) as relationship,a.relativename,
				-- raghavendra
				(select string_agg(coalesce(firstname ||' '|| r.relatione ||' '|| relativename),', ') 
				from kaveri.partyinfo pp 
				join kaveri.relationshipmasters r on r.id::text =pp.relationship::text
				where pp.propertyid = a.propertyid and pp.ownerno in (select min(ownerno) from kaveri.partyinfo p where propertyid=a.propertyid and p.partytypeid= (case when v_partytypeid=true then 1 else 2 end)) 
				and pp.partytypeid= (case when v_partytypeid=true then 1 else 2 end)
				) as ownername,'' as relationship,'' as relativename,
                  
--(select coalesce(r.relatione,a.relationship) from kaveri.partyinfo a1
--							where a1.ownerno in (select min(ownerno) from kaveri.partyinfo p 
--															where propertyid=a.propertyid) 
--									and r.id::text=a1.relationship::text
--							and a1.propertyid=a.propertyid)   as relationship,a.relativename,

a.availableextacre as transactextacre,a.availableextgunta as transactextgunta ,a.availableextfgunta as transactextfgunta from

kaveri.partyinfo a inner join kaveri.propertynumberdetails b on a.propertyid = b.propertyid

                                 -- and a.partytypeid = 2 /* commented on 30-07-2022 - in discharge deed, owner will be marked as claimant */

--                                  left join kaveri.relationshipmasters r on r.id::text = a.relationship::text 

                                  --a.relationship in ('3','4','5','6','7','8')

                                  where a.applicationnumber = pm.applicationnumber and pm.propertyid= b.propertyid and a.partytypeid= (case when v_partytypeid=true then 1 else 2 end)
								group by b.survey_no,b.hissa_no,
								--r.relatione,r.id
								a.relationship,a.availableextacre ,a.availableextgunta,a.availableextfgunta,a.relativename
								,a.propertyid,a.ownerno
								order by a.ownerno limit 1
								--group by b.survey_no , b.hissa_no,r.relatione,a.relativename,a.relationship,

     --  a.transactextacre,a.transactextgunta,

                                --   a.transactextfgunta

                  )partypndetails) as partyinfopropnumberdetails,

( select array_to_json(array_agg(row_to_json(prptyno)))

      from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,

                                                pntm.typenameenglish as propertynumbertype,

                                                pnd.currentnumber,pnd.hissa_no,pnd.survey_no,pnd.description as propertynumberdescription

                                                from kaveri.propertynumberdetails pnd

                                   left join kaveri.propertynotypemaster pntm                                    

                                                on (pntm.propertytypeid = pnd.currentpropertytypeid)

                                   where pnd.propertyid = pm.propertyid and

                                                pm.applicationnumber = _applicationnumber

                                   )prptyno )

                                                as propertynumberdetails,

                ( select array_to_json(array_agg(row_to_json(courtorderagri)))

                from (

               

                select * from kaveri.vw_fetch_court_order_details co  where  co.propertyid in (select pm.propertyid from kaveri.propertymaster pm where applicationnumber=_applicationnumber)
		 and

                applicationnumber = _applicationnumber and (co.currentpropertytypeid <> 1 or co.currentpropertytypeid=1) and co.villagecode in (select p7.villagecode from kaveri.propertymaster p7 where applicationnumber=_applicationnumber) 

                ) courtorderagri) as Courtdataagri,

                ( select array_to_json(array_agg(row_to_json(partynonagri

)))

                from (

                select pm.assessment as pid,

                pa.firstname as ownername,

                pm.landmark as propertydescription ,

                pm.ownedarea as totalarea

     from kaveri.partyinfo pa where pa.propertyid = pm.propertyid

                )partynonagri)partyinfononagri,

 ( select array_to_json(array_agg(row_to_json(courtordernonagri)))
                from (
select * from kaveri.vw_fetch_court_order_details na where na.propertyid in (select pm.propertyid from kaveri.propertymaster pm where applicationnumber=_applicationnumber) 
and
 applicationnumber = _applicationnumber and (na.currentpropertytypeid <>1 or na.currentpropertytypeid=1) 
 and na.villagecode in (select p6.villagecode from kaveri.propertymaster p6 where applicationnumber=_applicationnumber)
)courtordernonagri)as courtdatanonagri,

                ( select array_to_json(array_agg(row_to_json(propertyliability)))

                from (SELECT

a.liabilityid,

a.entrydate,

a.issuedate,

a.issuedby,

a.amount,

a.ordernumber,

a.liabilitynote,

a.srocode,

a.sronamee,
a.userid,
a.drocode,
a.mappingid,
a.documentid,
a.propertyid,
false
FROM kaveri.vw_liability_search a
where a.srocode = pm.srocode and a.currentnumber
in
(select pnd.currentnumber from kaveri.propertymaster pm1 left outer join kaveri.propertynumberdetails pnd on pm1.propertyid=pnd.propertyid
where pm1.propertyid=pm.propertyid)) propertyliability ) as liabilitydata,
                ( select array_to_json(array_agg(row_to_json(propertyschedules)))
                from
(select scheduleid,
                ps.propertyid,
                ps.srocode,
                ps.partyid,
                ps.scheduletype,
                pm.totalarea,
                ps.unitid,
                ps.description,
                ps.partyids,
                ps.aileniatedauthorityid,
                ps.alieniatedorder,
                ps.bhoomisellerpartyids,
                ps.govtrestricorder,
                ps.govtrestrictionid,
                ps.landcode,propertygroup,
                ps.giftshare,
                ps.giftsharedetails,
                ps.easttowest,
                ps.northtosouth,
                ps.blockchainpropertyid,
                ps.assignedblockchainpid,
                ps.applicationnumber,
                ps.verified,
                ps.issroapproved,
                ps.eastboundary,
                ps.westboundary,
                ps.northboundary,
                ps.southboundary,
                p.transactextacre,
                p.transactextgunta,
                p.transactextfgunta
                from kaveri.propertyschedules ps
                 join (select * from kaveri.partyinfo p where partytypeid = 2 and (case when v_cntproperty>0 then
				 propertyid  = pm.propertyid else p.applicationnumber=_applicationnumber end) order by ownerno limit 1)as p 
				 on (case when v_cntproperty>0 then ps.propertyid=p.propertyid else p.applicationnumber=ps.applicationnumber end)
                 join kaveri.propertymaster pmm on ps.propertyid=pmm.propertyid               
				left join kaveri.stamprulesflag sf on sf.stampruleid =pmm.stampruleid 
                where ps.applicationnumber=_applicationnumber and ps.propertyid  = pm.propertyid and  p.partytypeid =(case when sf.isownertobeclaimant=true then 1 else 2 end)
                order by ps.scheduleid limit 1
) propertyschedules) as propertyschedulesdata,
v_countrecord as countofrecord,
pm.roadcode as roadcode,
rd.roadnamee as roadnamee,
ta.unit as unittype,
pt.isagri as isagriculture
from kaveri.propertymaster pm 
left join kaveri.villagemaster vi on (pm.villagecode = vi.villagecode)
left join kaveri.sromaster sm on (vi.srocode=sm.srocode)
left join kaveri.hoblimaster ho on (ho.hoblicode = vi.hoblicode)
left join kaveri.talukmaster ta on (ta.talukcode=vi.talukcode)
left join kaveri.districtmaster di on (di.districtcode = sm.districtcode)
--left join kaveri.bhoomidistrictmaster  di on (di.districtcode = ta.districtcode)
left join kaveri.documentmaster dc on (dc.regarticlecode = pm.regarticlecode and dc.documentid=pm.documentid)
left join kaveri.stamparticles sp on (sp.stamparticlecode = pm.stamparticlecode)
left join kaveri.stamprules sr on (sr.stampruleid = pm.stampruleid)
left join kaveri.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
left join kaveri.booktypemaster bt on (bt.bookid = sr.bookid)
left join kaveri.sromaster se on (se.srocode = pm.srocode)
left join kaveri.propertytypemaster pt on pt.propertytypeid = pm.propertytypeid
left join kaveri.villagewardmapping vw on vw.villagecode = pm.villagecode and vw.wardid = pm.wardid and pm.ismovableproperty=false
left join kaveri.warddetails w on  w.wardid = pm.wardid
left join kaveri.measunitmaster me on me.unitid = pm.unitid
left join kaveri.integrationdepartment zone on pm.zoneid = zone.udeptid
left join kaveri.roadmaster rd on (pm.roadcode=rd.roadcode)
where pm.applicationnumber = _applicationnumber and pt.isagri=false
group by pm.propertyid,pm.villagecode,vi.villagenamee,vi.hoblicode,ho.hoblinamee,vi.talukcode,ta.taluknamee,sm.districtcode,di.districtnamee              
,pm.stamparticlecode,sp.articlenamee,pm.stampruleid,sr.descriptione,pm.regarticlecode,ra.articlenamee,dc.bookid,bt.booknameenglish  
,pm.srocode,se.sronamee,
pm.propertytypeid,
                pt.propertytypename,
                pm.noofscanpages,
                pm.ismovableproperty,
                pm.movablepropertydesc,
                w.wardid,
                pm.totalarea,
                me.descriptionenglish,
                w.wardnumber,
                pm.landmark,
                pm.zoneid,
                zone.departmentname,
                subpropertytypeid,pm.applicationnumber,pm.assessment,pm.ownedarea,pm.roadcode,rd.roadnamee
                ,ta.unit,pt.isagri,pm.isbefore2004  ,se.districtcode
			
offset pageoffset

fetch next pagesize rows only

)  app_json ) data_json;

return v_data_json;

END;

$$;


ALTER FUNCTION kaveri.fn_fetch_property_details_json_chk_30102025(_applicationnumber text, pagenumber integer, pagesize integer) OWNER TO raghavendrap;

--
-- Name: fn_fetch_property_details_json_chk_bck(text, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_property_details_json_chk_bck(_applicationnumber text, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare
v_data_json json;
pageoffset integer:=0;
v_countrecord int;
v_partytypeid bool;
v_cntproperty int;
begin
	
	select count(*) into v_countrecord  from kaveri.propertymaster p where applicationnumber=_applicationnumber;
	
	select count(*) into v_cntproperty from kaveri.propertynumberdetails ps where propertyid in (select propertyid from kaveri.propertymaster where applicationnumber=_applicationnumber) 
	and ps.currentpropertytypeid in (1,60,65);

	select isownertobeclaimant into v_partytypeid from kaveri.stamprulesflag sf where sf.stampruleid in (Select stampruleid from kaveri.propertymaster p where p.applicationnumber =_applicationnumber limit 1);

pageoffset:=((pagenumber-1) * pagesize);

select row_to_json(data_json) into v_data_json from (

select array_to_json(array_agg(row_to_json(app_json)))

from (

select pm.propertyid as PIDNO,pm.villagecode,vi.villagenamee as Village,

ho.hoblicode,ho.hoblinamee as Hobli,ta.talukcode,ta.taluknamee as Taluk,

ta.districtcode,se.districtcode as kaveridistrictcode,di.districtnamee as District,

                pm.stamparticlecode,

                sp.articlenamee as stamparticle,

                pm.stampruleid,

                sr.descriptione as stampsubarticle,

                pm.regarticlecode,

                ra.articlenamee as registrationfeearticle,

--             sr.bookid,

                (case when pm.stamparticlecode = 14 and pm.isbefore2004=false  then

                 (select bookid from kaveri.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else dc.bookid end ) as bookid,

                --bt.booknameenglish as bookname,
	
                (select booknameenglish from kaveri.booktypemaster where bookid =

                (case when pm.stamparticlecode = 14 and pm.isbefore2004=false  then

                 (select bookid from kaveri.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else dc.bookid end )) as bookname,
                pm.srocode,

                se.sronamee as sroname,

                pm.propertytypeid,

                pt.propertytypename,

                pm.noofscanpages,

                pm.ismovableproperty,

                pm.movablepropertydesc,

                w.wardid,

                pm.totalarea,

                me.descriptionenglish as unit,

                w.wardnumber,

                pm.landmark,

                pm.zoneid,

                zone.departmentname as zonename,

                subpropertytypeid,

                ( select array_to_json(array_agg(row_to_json(partypndetails)))

      from (

                  select b.survey_no,b.hissa_no,(select string_agg(firstname,', ')  from kaveri.partyinfo pp where pp.propertyid =a.propertyid and pp.partytypeid= (case when v_partytypeid=true then 1 else 2 end)) as ownername,

                                  /* COMMENTED ON 01-10-2022 as ownername is only single owner*/

                                --  string_agg(a.firstname,',') as ownername,

--                                  coalesce(r.relatione,a.relationship) as relationship,a.relativename,
                  
				(select coalesce(r.relatione,a.relationship) from kaveri.partyinfo a1 
							where a1.ownerno in (select min(ownerno) from kaveri.partyinfo p where propertyid=a.propertyid) 
									and r.id::text=a1.relationship::text
							and a1.propertyid=a.propertyid and a1.partytypeid= (case when v_partytypeid=true then 1 else 2 end ))   as relationship,a.relativename,                

a.transactextacre as transactextacre,a.transactextgunta as transactextgunta ,a.transactextfgunta as transactextfgunta from

kaveri.partyinfo a inner join kaveri.propertynumberdetails b on a.propertyid = b.propertyid

                                 -- and a.partytypeid = 2 /* commented on 30-07-2022 - in discharge deed, owner will be marked as claimant */

                                  left join kaveri.relationshipmasters r on r.id::text = a.relationship::text 

                                  --a.relationship in ('3','4','5','6','7','8')

                                  where a.applicationnumber = pm.applicationnumber and pm.propertyid= b.propertyid and a.partytypeid= (case when v_partytypeid=true then 1 else 2 end)
									group by b.survey_no,b.hissa_no,r.relatione,a.relationship,a.relativename
                                   ,a.transactextacre,a.transactextgunta,a.transactextfgunta,a.propertyid,r.id,a.ownerno
                                   order by a.ownerno limit 1
                                 
									--group by b.survey_no , b.hissa_no,r.relatione,a.relativename,a.relationship,

     --  a.transactextacre,a.transactextgunta,

                                --   a.transactextfgunta

                  )partypndetails) as partyinfopropnumberdetails,

( select array_to_json(array_agg(row_to_json(prptyno)))

      from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,

                                                pntm.typenameenglish as propertynumbertype,

                                                pnd.currentnumber,pnd.hissa_no,pnd.survey_no,pnd.description as propertynumberdescription

                                                from kaveri.propertynumberdetails pnd

                                   left join kaveri.propertynotypemaster pntm                                    

                                                on (pntm.propertytypeid = pnd.currentpropertytypeid)

                                   where pnd.propertyid = pm.propertyid and

                                                pm.applicationnumber = _applicationnumber

                                   )prptyno )

                                                as propertynumberdetails,

                ( select array_to_json(array_agg(row_to_json(courtorderagri)))

                from (

               

                select * from kaveri.vw_fetch_court_order_details co  where  co.propertyid in (select pm.propertyid from kaveri.propertymaster pm where applicationnumber=_applicationnumber)
		 and

                applicationnumber = _applicationnumber and (co.currentpropertytypeid <> 1 or co.currentpropertytypeid=1) and co.villagecode in (select p7.villagecode from kaveri.propertymaster p7 where applicationnumber=_applicationnumber) 

                ) courtorderagri) as Courtdataagri,

                ( select array_to_json(array_agg(row_to_json(partynonagri

)))

                from (

                select pm.assessment as pid,

                pa.firstname as ownername,

                pm.landmark as propertydescription ,

                pm.ownedarea as totalarea

     from kaveri.partyinfo pa where pa.propertyid = pm.propertyid

                )partynonagri)partyinfononagri,

                ( select array_to_json(array_agg(row_to_json(courtordernonagri)))

                from (

                                select * from kaveri.vw_fetch_court_order_details na where na.propertyid in (select pm.propertyid from kaveri.propertymaster pm where applicationnumber=_applicationnumber)
			and

                applicationnumber = _applicationnumber and (na.currentpropertytypeid <>1 or na.currentpropertytypeid=1) and na.villagecode in (select p6.villagecode from kaveri.propertymaster p6 where applicationnumber=_applicationnumber)

                                )courtordernonagri)as courtdatanonagri,

                ( select array_to_json(array_agg(row_to_json(propertyliability)))

                from (SELECT

a.liabilityid,

a.entrydate,

a.issuedate,

a.issuedby,

a.amount,

a.ordernumber,

a.liabilitynote,

a.srocode,

a.sronamee,

a.userid,

a.drocode,

a.mappingid,

a.documentid,

a.propertyid,

false

FROM kaveri.vw_liability_search a

where a.srocode = pm.srocode and a.currentnumber

in

(select pnd.currentnumber from kaveri.propertymaster pm1 left outer join kaveri.propertynumberdetails pnd on pm1.propertyid=pnd.propertyid

where pm1.propertyid=pm.propertyid)) propertyliability ) as liabilitydata,

                ( select array_to_json(array_agg(row_to_json(propertyschedules)))

                from

(select scheduleid,

                ps.propertyid,

                ps.srocode,

                ps.partyid,

                ps.scheduletype,

                pm.totalarea,

                ps.unitid,

                ps.description,

                ps.partyids,

                ps.aileniatedauthorityid,

                ps.alieniatedorder,

                ps.bhoomisellerpartyids,

                ps.govtrestricorder,

                ps.govtrestrictionid,

                ps.landcode,propertygroup,

                ps.giftshare,

                ps.giftsharedetails,

                ps.easttowest,

                ps.northtosouth,

                ps.blockchainpropertyid,

                ps.assignedblockchainpid,

                ps.applicationnumber,

                ps.verified,

                ps.issroapproved,

                ps.eastboundary,

                ps.westboundary,

                ps.northboundary,

                ps.southboundary,

                p.transactextacre,

                p.transactextgunta,

                p.transactextfgunta

                from kaveri.propertyschedules ps
                 join (select * from kaveri.partyinfo p where partytypeid = 2 and (case when v_cntproperty>0 then
				 propertyid=pm.propertyid else p.applicationnumber=_applicationnumber end) order by ownerno limit 1)as p
				on (case when v_cntproperty>0 then ps.propertyid=p.propertyid else p.applicationnumber=ps.applicationnumber end)
				 join kaveri.propertymaster pmm on ps.propertyid=pmm.propertyid               
				left join kaveri.stamprulesflag sf on sf.stampruleid =pmm.stampruleid 
				where ps.applicationnumber=_applicationnumber and ps.propertyid  = pm.propertyid and  p.partytypeid =(case when sf.isownertobeclaimant=true then 1 else 2 end)

                order by ps.scheduleid 


                
) propertyschedules) as propertyschedulesdata,

v_countrecord as countofrecord,

pm.roadcode as roadcode,

rd.roadnamee as roadnamee,

ta.unit as unittype,

pt.isagri as isagriculture


from kaveri.propertymaster pm 
join kaveri.bhoomimappingdetails bh on (pm.villagecode=bh.kaverivillagecode) and bh.bhoomivillagecode<>0
left join kaveri.bhoomivillagemaster vi on (bh.bhoomivillagecode  = vi.villagecode and bh.bhoomitalukcode=vi.talukcode and bh.bhoomidistrictcode=vi.districtcode and bh.bhoomihobicode=vi.hoblicode)
left join kaveri.bhoomihoblimaster ho on (ho.hoblicode =bh.bhoomihobicode and ho.talukcode=bh.bhoomitalukcode  and ho.districtcode=bh.bhoomidistrictcode)
join kaveri.bhoomitalukmaster ta on (bh.bhoomitalukcode=ta.talukcode and bh.bhoomidistrictcode=ta.districtcode)
left join kaveri.bhoomidistrictmaster  di on (di.districtcode = ta.districtcode)
left join kaveri.documentmaster dc on (dc.regarticlecode = pm.regarticlecode and dc.documentid=pm.documentid)
left join kaveri.stamparticles sp on (sp.stamparticlecode = pm.stamparticlecode)
left join kaveri.stamprules sr on (sr.stampruleid = pm.stampruleid)
left join kaveri.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
left join kaveri.booktypemaster bt on (bt.bookid = sr.bookid)
left join kaveri.sromaster se on (se.srocode = pm.srocode)
left join kaveri.propertytypemaster pt on pt.propertytypeid = pm.propertytypeid
left join kaveri.villagewardmapping vw on vw.villagecode = pm.villagecode and vw.wardid = pm.wardid and pm.ismovableproperty=false
left join kaveri.warddetails w on  w.wardid = pm.wardid
left join kaveri.measunitmaster me on me.unitid = pm.unitid
left join kaveri.integrationdepartment zone on pm.zoneid = zone.udeptid
left join kaveri.roadmaster rd on (pm.roadcode=rd.roadcode)
where pm.applicationnumber = _applicationnumber and pt.isagri=true

group by pm.propertyid,pm.villagecode,vi.villagenamee,ho.hoblicode,ho.hoblinamee,ta.talukcode,ta.taluknamee,ta.districtcode,di.districtnamee              

,pm.stamparticlecode,sp.articlenamee,pm.stampruleid,sr.descriptione,pm.regarticlecode,ra.articlenamee,dc.bookid,bt.booknameenglish  

,pm.srocode,se.sronamee,

pm.propertytypeid,

                pt.propertytypename,

                pm.noofscanpages,

                pm.ismovableproperty,

                pm.movablepropertydesc,

                w.wardid,

                pm.totalarea,

                me.descriptionenglish,

                w.wardnumber,

                pm.landmark,

                pm.zoneid,

                zone.departmentname,

                subpropertytypeid,pm.applicationnumber,pm.assessment,pm.ownedarea,pm.roadcode,rd.roadnamee
                ,ta.unit,pt.isagri,pm.isbefore2004,se.districtcode



union ALL


select pm.propertyid as PIDNO,pm.villagecode,vi.villagenamee as Village,

vi.hoblicode,ho.hoblinamee as Hobli,vi.talukcode,ta.taluknamee as Taluk,

sm.districtcode,se.districtcode as kaveridistrictcode,di.districtnamee as District,

                pm.stamparticlecode,

                sp.articlenamee as stamparticle,

                pm.stampruleid,

                sr.descriptione as stampsubarticle,

                pm.regarticlecode,

                ra.articlenamee as registrationfeearticle,

--             sr.bookid,

                (case when pm.stamparticlecode = 14 and pm.isbefore2004=false then

                 (select bookid from kaveri.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else dc.bookid end ) as bookid,

                --bt.booknameenglish as bookname,
	
                (select booknameenglish from kaveri.booktypemaster where bookid =

                (case when pm.stamparticlecode = 14 and pm.isbefore2004=false then

                 (select bookid from kaveri.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else dc.bookid end )) as bookname,
                pm.srocode,

                se.sronamee as sroname,

                pm.propertytypeid,

                pt.propertytypename,

                pm.noofscanpages,

                pm.ismovableproperty,

                pm.movablepropertydesc,

                w.wardid,

                pm.totalarea,

                me.descriptionenglish as unit,

                w.wardnumber,

                pm.landmark,

                pm.zoneid,

                zone.departmentname as zonename,

                subpropertytypeid,

                ( select array_to_json(array_agg(row_to_json(partypndetails)))

      from (

                  select b.survey_no,b.hissa_no,(select string_agg(firstname,', ')  from kaveri.partyinfo pp where pp.propertyid =a.propertyid and pp.partytypeid= (case when v_partytypeid=true then 1 else 2 end)) as ownername,

                                  /* COMMENTED ON 01-10-2022 as ownername is only single owner*/

                                  --string_agg(a.firstname,',') as ownername,

--                                  coalesce(r.relatione,a.relationship) as relationship,a.relativename,
                  (select coalesce(r.relatione,a.relationship) from kaveri.partyinfo a1
							where a1.ownerno in (select min(ownerno) from kaveri.partyinfo p 
															where propertyid=a.propertyid) 
									and r.id::text=a1.relationship::text
							and a1.propertyid=a.propertyid)   as relationship,a.relativename,

a.availableextacre as transactextacre,a.availableextgunta as transactextgunta ,a.availableextfgunta as transactextfgunta from

kaveri.partyinfo a inner join kaveri.propertynumberdetails b on a.propertyid = b.propertyid

                                 -- and a.partytypeid = 2 /* commented on 30-07-2022 - in discharge deed, owner will be marked as claimant */

                                  left join kaveri.relationshipmasters r on r.id::text = a.relationship::text 

                                  --a.relationship in ('3','4','5','6','7','8')

                                  where a.applicationnumber = pm.applicationnumber and pm.propertyid= b.propertyid and a.partytypeid= (case when v_partytypeid=true then 1 else 2 end)
								group by b.survey_no,b.hissa_no,r.relatione,a.relationship,a.availableextacre ,a.availableextgunta,a.availableextfgunta,a.relativename
								,a.propertyid,r.id,a.ownerno
								order by a.ownerno limit 1
								--group by b.survey_no , b.hissa_no,r.relatione,a.relativename,a.relationship,

     --  a.transactextacre,a.transactextgunta,

                                --   a.transactextfgunta

                  )partypndetails) as partyinfopropnumberdetails,

( select array_to_json(array_agg(row_to_json(prptyno)))

      from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,

                                                pntm.typenameenglish as propertynumbertype,

                                                pnd.currentnumber,pnd.hissa_no,pnd.survey_no,pnd.description as propertynumberdescription

                                                from kaveri.propertynumberdetails pnd

                                   left join kaveri.propertynotypemaster pntm                                    

                                                on (pntm.propertytypeid = pnd.currentpropertytypeid)

                                   where pnd.propertyid = pm.propertyid and

                                                pm.applicationnumber = _applicationnumber

                                   )prptyno )

                                                as propertynumberdetails,

                ( select array_to_json(array_agg(row_to_json(courtorderagri)))

                from (

               

                select * from kaveri.vw_fetch_court_order_details co  where  co.propertyid in (select pm.propertyid from kaveri.propertymaster pm where applicationnumber=_applicationnumber)
		 and

                applicationnumber = _applicationnumber and (co.currentpropertytypeid <> 1 or co.currentpropertytypeid=1) and co.villagecode in (select p7.villagecode from kaveri.propertymaster p7 where applicationnumber=_applicationnumber) 

                ) courtorderagri) as Courtdataagri,

                ( select array_to_json(array_agg(row_to_json(partynonagri

)))

                from (

                select pm.assessment as pid,

                pa.firstname as ownername,

                pm.landmark as propertydescription ,

                pm.ownedarea as totalarea

     from kaveri.partyinfo pa where pa.propertyid = pm.propertyid

                )partynonagri)partyinfononagri,

 ( select array_to_json(array_agg(row_to_json(courtordernonagri)))
                from (
select * from kaveri.vw_fetch_court_order_details na where na.propertyid in (select pm.propertyid from kaveri.propertymaster pm where applicationnumber=_applicationnumber) 
and
 applicationnumber = _applicationnumber and (na.currentpropertytypeid <>1 or na.currentpropertytypeid=1) 
 and na.villagecode in (select p6.villagecode from kaveri.propertymaster p6 where applicationnumber=_applicationnumber)
)courtordernonagri)as courtdatanonagri,

                ( select array_to_json(array_agg(row_to_json(propertyliability)))

                from (SELECT

a.liabilityid,

a.entrydate,

a.issuedate,

a.issuedby,

a.amount,

a.ordernumber,

a.liabilitynote,

a.srocode,

a.sronamee,
a.userid,
a.drocode,
a.mappingid,
a.documentid,
a.propertyid,
false
FROM kaveri.vw_liability_search a
where a.srocode = pm.srocode and a.currentnumber
in
(select pnd.currentnumber from kaveri.propertymaster pm1 left outer join kaveri.propertynumberdetails pnd on pm1.propertyid=pnd.propertyid
where pm1.propertyid=pm.propertyid)) propertyliability ) as liabilitydata,
                ( select array_to_json(array_agg(row_to_json(propertyschedules)))
                from
(select scheduleid,
                ps.propertyid,
                ps.srocode,
                ps.partyid,
                ps.scheduletype,
                pm.totalarea,
                ps.unitid,
                ps.description,
                ps.partyids,
                ps.aileniatedauthorityid,
                ps.alieniatedorder,
                ps.bhoomisellerpartyids,
                ps.govtrestricorder,
                ps.govtrestrictionid,
                ps.landcode,propertygroup,
                ps.giftshare,
                ps.giftsharedetails,
                ps.easttowest,
                ps.northtosouth,
                ps.blockchainpropertyid,
                ps.assignedblockchainpid,
                ps.applicationnumber,
                ps.verified,
                ps.issroapproved,
                ps.eastboundary,
                ps.westboundary,
                ps.northboundary,
                ps.southboundary,
                p.transactextacre,
                p.transactextgunta,
                p.transactextfgunta
                from kaveri.propertyschedules ps
                 join (select * from kaveri.partyinfo p where partytypeid = 2 and (case when v_cntproperty>0 then
				 propertyid  = pm.propertyid else p.applicationnumber=_applicationnumber end) order by ownerno limit 1)as p 
				 on (case when v_cntproperty>0 then ps.propertyid=p.propertyid else p.applicationnumber=ps.applicationnumber end)
                 join kaveri.propertymaster pmm on ps.propertyid=pmm.propertyid               
				left join kaveri.stamprulesflag sf on sf.stampruleid =pmm.stampruleid 
                where ps.applicationnumber=_applicationnumber and ps.propertyid  = pm.propertyid and  p.partytypeid =(case when sf.isownertobeclaimant=true then 1 else 2 end)
                order by ps.scheduleid limit 1
) propertyschedules) as propertyschedulesdata,
v_countrecord as countofrecord,
pm.roadcode as roadcode,
rd.roadnamee as roadnamee,
ta.unit as unittype,
pt.isagri as isagriculture
from kaveri.propertymaster pm 
left join kaveri.villagemaster vi on (pm.villagecode = vi.villagecode)
left join kaveri.sromaster sm on (vi.srocode=sm.srocode)
left join kaveri.hoblimaster ho on (ho.hoblicode = vi.hoblicode)
left join kaveri.talukmaster ta on (ta.talukcode=vi.talukcode)
left join kaveri.districtmaster di on (di.districtcode = sm.districtcode)
--left join kaveri.bhoomidistrictmaster  di on (di.districtcode = ta.districtcode)
left join kaveri.documentmaster dc on (dc.regarticlecode = pm.regarticlecode and dc.documentid=pm.documentid)
left join kaveri.stamparticles sp on (sp.stamparticlecode = pm.stamparticlecode)
left join kaveri.stamprules sr on (sr.stampruleid = pm.stampruleid)
left join kaveri.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
left join kaveri.booktypemaster bt on (bt.bookid = sr.bookid)
left join kaveri.sromaster se on (se.srocode = pm.srocode)
left join kaveri.propertytypemaster pt on pt.propertytypeid = pm.propertytypeid
left join kaveri.villagewardmapping vw on vw.villagecode = pm.villagecode and vw.wardid = pm.wardid and pm.ismovableproperty=false
left join kaveri.warddetails w on  w.wardid = pm.wardid
left join kaveri.measunitmaster me on me.unitid = pm.unitid
left join kaveri.integrationdepartment zone on pm.zoneid = zone.udeptid
left join kaveri.roadmaster rd on (pm.roadcode=rd.roadcode)
where pm.applicationnumber = _applicationnumber and pt.isagri=false
group by pm.propertyid,pm.villagecode,vi.villagenamee,vi.hoblicode,ho.hoblinamee,vi.talukcode,ta.taluknamee,sm.districtcode,di.districtnamee              
,pm.stamparticlecode,sp.articlenamee,pm.stampruleid,sr.descriptione,pm.regarticlecode,ra.articlenamee,dc.bookid,bt.booknameenglish  
,pm.srocode,se.sronamee,
pm.propertytypeid,
                pt.propertytypename,
                pm.noofscanpages,
                pm.ismovableproperty,
                pm.movablepropertydesc,
                w.wardid,
                pm.totalarea,
                me.descriptionenglish,
                w.wardnumber,
                pm.landmark,
                pm.zoneid,
                zone.departmentname,
                subpropertytypeid,pm.applicationnumber,pm.assessment,pm.ownedarea,pm.roadcode,rd.roadnamee
                ,ta.unit,pt.isagri,pm.isbefore2004  ,se.districtcode
			
offset pageoffset

fetch next pagesize rows only

)  app_json ) data_json;

return v_data_json;

END;

$$;


ALTER FUNCTION kaveri.fn_fetch_property_details_json_chk_bck(_applicationnumber text, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_fetch_property_details_rule_17_3_json(text, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_property_details_rule_17_3_json(_applicationnumber text, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare
v_data_json json;
pageoffset integer:=0;
v_countrecord int;
v_partytypeid bool;
v_cntproperty int;

begin
		
		select count(*) into v_countrecord from kaveri.propertymaster p where applicationnumber=_applicationnumber;
		select count(*) into v_cntproperty from kaveri.propertynumberdetails ps where propertyid in (select propertyid from kaveri.propertymaster where applicationnumber=_applicationnumber);
	
pageoffset:=((pagenumber-1) * pagesize);

select row_to_json(data_json) into v_data_json from (

select array_to_json(array_agg(row_to_json(app_json)))
from (

select pm.propertyid as PIDNO,pm.villagecode,vi.villagenamee as Village,
 
vi.hoblicode,ho.hoblinamee as Hobli,vi.talukcode,ta.taluknamee as Taluk,
 
sm.districtcode,di.districtnamee as District,
 
pm.stamparticlecode,
 
sp.articlenamee as stamparticle,
 
pm.stampruleid,
 
sr.descriptione as stampsubarticle,
 
pm.regarticlecode,
 
ra.articlenamee as registrationfeearticle,
 
sr.bookid,
 
bt.booknameenglish as bookname,
pm.srocode,
 
se.sronamee as sroname,
 
pm.propertytypeid,
 
pt.propertytypename,
 
pm.noofscanpages,
 
pm.ismovableproperty,
 
pm.movablepropertydesc,
 
w.wardid,
 
pm.totalarea,
 
me.descriptionenglish as unit,
 
w.wardnumber,
 
pm.landmark,
 
pm.zoneid,
 
zone.departmentname as zonename,
 
subpropertytypeid,
pm.valuationreport,
 
( select array_to_json(array_agg(row_to_json(partypndetails)))
from (
select distinct a.partyid ,ptm.descriptioninenglish,
COALESCE(coalesce(a.firstname,' ')||' '||coalesce(a.middlename,' ')||' '||coalesce(a.lastname,' '), NULL::text)  AS name,
a.firstname,
a.middlename,
a.lastname,
a.partytypeid ,a.address, a.isexecutor, a.ispresenter, a.salutationid, a.age, s.descriptione from
kaveri.partyinfo a
left join kaveri.partytypemaster ptm on ptm.partytypeid=a.partytypeid
left join kaveri.salutationmaster s on s.salutationid=a.salutationid
where a.applicationnumber = _applicationnumber
and a.propertyid = pm.propertyid
group by a.address, a.isexecutor, a.ispresenter,a.partytypeid,a.firstname,a.middlename,  a.lastname,a.partyid,ptm.descriptioninenglish, a.salutationid, a.age,s.descriptione
 
)partypndetails) as partyinfopropnumberdetails,


 
( select array_to_json(array_agg(row_to_json(prptyno)))
 
from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,
 
pntm.typenameenglish as propertynumbertype, --pnd.propertynumberdetailid,
 
pnd.currentnumber,pnd.hissa_no,pnd.survey_no,pnd.description as propertynumberdescription
 
from kaveri.propertynumberdetails pnd
 
 left join kaveri.propertynotypemaster pntm
 
on (pntm.propertytypeid = pnd.currentpropertytypeid)
 
 where pnd.propertyid = pm.propertyid and
 
pm.applicationnumber = _applicationnumber
 
 )prptyno )
 
as propertynumberdetails,
 
( select array_to_json(array_agg(row_to_json(propertyschedules)))
from
(select scheduleid,
ps.propertyid,
ps.srocode,
ps.partyid,
ps.scheduletype,
pm.totalarea,
ps.unitid,
ps.description,
ps.partyids,
ps.aileniatedauthorityid,
ps.alieniatedorder,
ps.bhoomisellerpartyids,
ps.govtrestricorder,
ps.govtrestrictionid,
ps.landcode,propertygroup,
ps.giftshare,
ps.giftsharedetails,
ps.easttowest,
ps.northtosouth,
ps.blockchainpropertyid,
ps.assignedblockchainpid,
ps.applicationnumber,
ps.verified,
ps.issroapproved,
ps.eastboundary,
ps.westboundary,
ps.northboundary,
ps.southboundary,
mm.measurementnamee
from kaveri.propertyschedules ps
 join kaveri.propertymaster pmm on ps.propertyid=pmm.propertyid 
left join kaveri.stamprulesflag sf on sf.stampruleid =pmm.stampruleid 
left join kaveri.measurementmaster mm on ps.unitid= mm.measurementcode
where ps.applicationnumber=_applicationnumber and ps.propertyid= pm.propertyid
order by ps.scheduleid
) propertyschedules) as propertyschedulesdata,

pm.roadcode as roadcode,
rd.roadnamee as roadnamee,
ta.unit as unittype,
pt.isagri as isagriculture
from kaveri.propertymaster pm 
left join kaveri.villagemaster vi on (pm.villagecode = vi.villagecode)
left join kaveri.sromaster sm on (vi.srocode=sm.srocode)
left join kaveri.hoblimaster ho on (ho.hoblicode = vi.hoblicode)
left join kaveri.talukmaster ta on (ta.talukcode=vi.talukcode)
left join kaveri.districtmaster di on (di.districtcode = sm.districtcode)
--left join kaveri.bhoomidistrictmasterdi on (di.districtcode = ta.districtcode)
left join kaveri.documentmaster dc on (dc.regarticlecode = pm.regarticlecode and dc.documentid=pm.documentid)
left join kaveri.stamparticles sp on (sp.stamparticlecode = pm.stamparticlecode)
left join kaveri.stamprules sr on (sr.stampruleid = pm.stampruleid)
left join kaveri.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
left join kaveri.booktypemaster bt on (bt.bookid = sr.bookid)
left join kaveri.sromaster se on (se.srocode = pm.srocode)
left join kaveri.propertytypemaster pt on pt.propertytypeid = pm.propertytypeid
left join kaveri.villagewardmapping vw on vw.villagecode = pm.villagecode and vw.wardid = pm.wardid and pm.ismovableproperty=false
left join kaveri.warddetails w on w.wardid = pm.wardid
left join kaveri.measunitmaster me on me.unitid = pm.unitid
left join kaveri.integrationdepartment zone on pm.zoneid = zone.udeptid
left join kaveri.roadmaster rd on (pm.roadcode=rd.roadcode)
where pm.applicationnumber = _applicationnumber
group by pm.propertyid,pm.villagecode,vi.villagenamee,vi.hoblicode,ho.hoblinamee,vi.talukcode,ta.taluknamee,sm.districtcode,di.districtnamee
,pm.stamparticlecode,sp.articlenamee,pm.stampruleid,sr.descriptione,pm.regarticlecode,ra.articlenamee,sr.bookid,bt.booknameenglish
,pm.srocode,se.sronamee,
pm.propertytypeid,
pt.propertytypename,
pm.noofscanpages,
pm.ismovableproperty,
pm.movablepropertydesc,
w.wardid,
pm.totalarea,
me.descriptionenglish,
w.wardnumber,
pm.landmark,
pm.zoneid,
zone.departmentname,
subpropertytypeid,pm.applicationnumber,pm.assessment,pm.ownedarea,pm.roadcode,rd.roadnamee,ta.unit,pt.isagri , pm.valuationreport
offset pageoffset
fetch next pagesize rows only
 
)app_json


) data_json;
return v_data_json;
	END;
$$;


ALTER FUNCTION kaveri.fn_fetch_property_details_rule_17_3_json(_applicationnumber text, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_property_numbertype_details_json_check(text); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_property_numbertype_details_json_check(_applicationnumber text) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
BEGIN
select row_to_json(app_json) into v_data_json
from (
select  a.wardid,a.wardnumber,b.villagecode,c.villagenamee,
d.roadcode,d.roadnamee,c.talukcode,e.taluknamee,c.hoblicode,
f.hoblinamee,e.districtcode,g.districtnamee,i.currentnumber as UPORNumber,
	( select array_to_json(array_agg(row_to_json(propertynotype)))
      from (
	   select i.currentpropertytypeid,
j.typenameenglish as propertytype,i.currentnumber as propertynumberdetails
	  )propertynotype) as propertynotype
	from kaveri.warddetails a 
inner join kaveri.villagewardmapping b
on a.wardid = b.wardid and a.integrationenabled = true
inner join kaveri.villagemaster c on c.villagecode = b.villagecode
inner join kaveri.roadmaster d on d.villagecode = c.villagecode
inner join kaveri.talukmaster e on e.talukcode = c.talukcode
inner join kaveri.hoblimaster f on f.hoblicode = c.hoblicode
inner join kaveri.districtmaster g on g.districtcode = e.districtcode
inner join kaveri.propertymaster h on h.villagecode = b.villagecode
inner join kaveri.propertynumberdetails i on i.propertyid = h.propertyid 
and i.currentpropertytypeid = h.propertytypeid
inner join kaveri.propertynotypemaster j on j.propertytypeid = i.currentpropertytypeid
inner join kaveri.sromaster k on k.districtcode = g.districtcode 
where h.applicationnumber = _applicationnumber
	order by a.wardid,a.wardnumber,b.villagecode,d.roadcode,c.talukcode,
c.hoblicode,e.districtcode
) app_json ;
return v_data_json;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_property_numbertype_details_json_check(_applicationnumber text) OWNER TO csgadmin;

--
-- Name: fn_fetch_propertydetailschk(text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_propertydetailschk(_applicationnumber text) RETURNS TABLE(pidno bigint, villagecode bigint, village character varying, hoblicode integer, hobli character varying, talukcode integer, taluk character varying, districtcode integer, district character varying, stamparticlecode integer, stamparticle character varying, stampruleid integer, stampsubarticle character varying, regarticlecode integer, registrationfeearticle character varying, bookid integer, bookname character varying, srocode integer, sroname character varying, propertytypeid integer, propertytypename character varying, noofscanpages integer, ismovableproperty boolean, movablepropertydesc text, wardid integer, totalarea numeric, unit character varying, wardnumber character varying, landmark character varying, zoneid integer, zonename character varying, subpropertytypeid integer, countofrecord integer, roadcode bigint, roadnamee character varying, unittype character varying, isagriculture boolean)
    LANGUAGE plpgsql
    AS $$
declare
v_countrecord int;
begin
	
select count(*) into v_countrecord  from kaveri.propertymaster p where applicationnumber=_applicationnumber;
	
create temporary table isagridata
as 
select pm.propertyid as PIDNO,pm.villagecode,vi.villagenamee as Village,
ho.hoblicode,ho.hoblinamee as Hobli,ta.talukcode,ta.taluknamee as Taluk,
ta.districtcode,di.districtnamee as District,
pm.stamparticlecode,
sp.articlenamee as stamparticle,
pm.stampruleid,
sr.descriptione as stampsubarticle,
pm.regarticlecode,
ra.articlenamee as registrationfeearticle,
(case when pm.stamparticlecode = 14 and pm.isbefore2004=false  then
(select kd.bookid from kaveri.k1documentdetails kd where kd.applicationnumber =_applicationnumber limit 1)
else sr.bookid end ) as bookid,
--bt.booknameenglish as bookname,
(select booknameenglish from kaveri.booktypemaster bk where bk.bookid =
(case when pm.stamparticlecode = 14 and pm.isbefore2004=false  then
(select kd1.bookid from kaveri.k1documentdetails kd1 where kd1.applicationnumber =_applicationnumber limit 1)
else sr.bookid end )) as bookname,
pm.srocode,
se.sronamee as sroname,
pm.propertytypeid,
pt.propertytypename,
pm.noofscanpages,
pm.ismovableproperty,
pm.movablepropertydesc,
w.wardid,
pm.totalarea,
me.descriptionenglish as unit,
w.wardnumber,
pm.landmark,
pm.zoneid,
zone.departmentname as zonename,
pm.subpropertytypeid,
v_countrecord as countofrecord,
pm.roadcode as roadcode,
rd.roadnamee as roadnamee,
ta.unit as unittype,
pt.isagri as isagriculture
from kaveri.propertymaster pm 
left join kaveri.bhoomimappingdetails bh on (pm.villagecode=bh.kaverivillagecode)
left join kaveri.bhoomivillagemaster vi on (bh.bhoomivillagecode  = vi.villagecode and bh.bhoomitalukcode=vi.talukcode and bh.bhoomidistrictcode=vi.districtcode and bh.bhoomihobicode=vi.hoblicode)
left join kaveri.bhoomihoblimaster ho on (ho.hoblicode =bh.bhoomihobicode and ho.talukcode=bh.bhoomitalukcode  and ho.districtcode=bh.bhoomidistrictcode)
left join kaveri.bhoomitalukmaster ta on (bh.bhoomitalukcode=ta.talukcode and bh.bhoomidistrictcode=ta.districtcode)
left join kaveri.bhoomidistrictmaster  di on (di.districtcode = ta.districtcode)
left join kaveri.documentmaster dc on pm.applicationnumber=dc.applicationnumber  --(dc.regarticlecode = pm.regarticlecode and dc.documentid=pm.documentid)
left join kaveri.stamparticles sp on (sp.stamparticlecode = pm.stamparticlecode)
left join kaveri.stamprules sr on (sr.stampruleid = pm.stampruleid)
left join kaveri.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
left join kaveri.booktypemaster bt on (bt.bookid = sr.bookid)
left join kaveri.sromaster se on (se.srocode = pm.srocode)
left join kaveri.propertytypemaster pt on pt.propertytypeid = pm.propertytypeid
left join kaveri.villagewardmapping vw on vw.villagecode = pm.villagecode and vw.wardid = pm.wardid and pm.ismovableproperty=false
left join kaveri.warddetails w on  w.wardid = pm.wardid
left join kaveri.measunitmaster me on me.unitid = pm.unitid
left join kaveri.integrationdepartment zone on pm.zoneid = zone.udeptid
left join kaveri.roadmaster rd on (pm.roadcode=rd.roadcode)
where pm.applicationnumber =_applicationnumber and pt.isagri=true;


create temporary table isnonagridata
as 
select pm.propertyid as PIDNO,pm.villagecode,vi.villagenamee as Village,
vi.hoblicode,ho.hoblinamee as Hobli,vi.talukcode,ta.taluknamee as Taluk,
sm.districtcode,di.districtnamee as District,
pm.stamparticlecode,
sp.articlenamee as stamparticle,
pm.stampruleid,
sr.descriptione as stampsubarticle,
pm.regarticlecode,
ra.articlenamee as registrationfeearticle,
(case when pm.stamparticlecode = 14 and pm.isbefore2004=false then
(select kd2.bookid from kaveri.k1documentdetails kd2 where kd2.applicationnumber =_applicationnumber limit 1)
else sr.bookid end ) as bookid,
--bt.booknameenglish as bookname,
(select booknameenglish from kaveri.booktypemaster bk1 where bk1.bookid =
(case when pm.stamparticlecode = 14 and pm.isbefore2004=false then
(select kd3.bookid from kaveri.k1documentdetails kd3 where kd3.applicationnumber =_applicationnumber limit 1)
else sr.bookid end )) as bookname,
pm.srocode,
sm.sronamee as sroname,
pm.propertytypeid,
pt.propertytypename,
pm.noofscanpages,
pm.ismovableproperty,
pm.movablepropertydesc,
w.wardid,
pm.totalarea,
me.descriptionenglish as unit,
w.wardnumber,
pm.landmark,
pm.zoneid,
zone.departmentname as zonename,
pm.subpropertytypeid ,
v_countrecord as countofrecord,
pm.roadcode as roadcode,
rd.roadnamee as roadnamee,
ta.unit as unittype,
pt.isagri as isagriculture
from kaveri.propertymaster pm 
left join kaveri.villagemaster vi on (pm.villagecode = vi.villagecode)
left join kaveri.sromaster sm on (vi.srocode=sm.srocode)
left join kaveri.hoblimaster ho on (ho.hoblicode = vi.hoblicode)
left join kaveri.talukmaster ta on (ta.talukcode=vi.talukcode)
left join kaveri.districtmaster di on (di.districtcode = sm.districtcode)
--left join kaveri.bhoomidistrictmaster  di on (di.districtcode = ta.districtcode)
left join kaveri.documentmaster dc on dc.applicationnumber=pm.applicationnumber ---(dc.regarticlecode = pm.regarticlecode and dc.documentid=pm.documentid)
left join kaveri.stamparticles sp on (sp.stamparticlecode = pm.stamparticlecode)
left join kaveri.stamprules sr on (sr.stampruleid = pm.stampruleid)
left join kaveri.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
left join kaveri.booktypemaster bt on (bt.bookid = sr.bookid)
--left join kaveri.sromaster se on (se.srocode = pm.srocode)
left join kaveri.propertytypemaster pt on pt.propertytypeid = pm.propertytypeid
left join kaveri.villagewardmapping vw on vw.villagecode = pm.villagecode and vw.wardid = pm.wardid and pm.ismovableproperty=false
left join kaveri.warddetails w on  w.wardid = pm.wardid
left join kaveri.measunitmaster me on me.unitid = pm.unitid
left join kaveri.integrationdepartment zone on pm.zoneid = zone.udeptid
left join kaveri.roadmaster rd on (pm.roadcode=rd.roadcode)
where pm.applicationnumber =_applicationnumber and pt.isagri=false;

return query
select isagri.* from isagridata isagri
union 
select isnonagri.* from isnonagridata isnonagri;

drop  table isagridata;
drop  table isnonagridata;

end;
$$;


ALTER FUNCTION kaveri.fn_fetch_propertydetailschk(_applicationnumber text) OWNER TO postgres;

--
-- Name: fn_fetch_propertydetailschk_k1pending(text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_propertydetailschk_k1pending(_applicationnumber text) RETURNS TABLE(pidno bigint, villagecode bigint, village character varying, hoblicode integer, hobli character varying, talukcode integer, taluk character varying, districtcode integer, district character varying, stamparticlecode integer, stamparticle character varying, stampruleid integer, stampsubarticle character varying, regarticlecode integer, registrationfeearticle character varying, bookid integer, bookname character varying, srocode integer, sroname character varying, propertytypeid integer, propertytypename character varying, noofscanpages integer, ismovableproperty boolean, movablepropertydesc text, wardid integer, totalarea numeric, unit character varying, wardnumber character varying, landmark character varying, zoneid integer, zonename character varying, subpropertytypeid integer, countofrecord integer, roadcode bigint, roadnamee character varying, unittype character varying, isagriculture boolean, kaveridistrictcode bigint)
    LANGUAGE plpgsql
    AS $$
declare
v_countrecord int;
begin
	
select count(*) into v_countrecord  from kaveri.propertymaster p where applicationnumber=_applicationnumber;
	
create temporary table isagridata
as 
select pm.propertyid as PIDNO,pm.villagecode,vi.villagenamee as Village,
ho.hoblicode,ho.hoblinamee as Hobli,ta.talukcode,ta.taluknamee as Taluk,
ta.districtcode,di.districtnamee as District,
pm.stamparticlecode,
sp.articlenamee as stamparticle,
pm.stampruleid,
sr.descriptione as stampsubarticle,
pm.regarticlecode,
ra.articlenamee as registrationfeearticle,
(case when pm.stamparticlecode = 14 and pm.isbefore2004=false  then
(select kd.bookid from kaveri.k1documentdetails kd where kd.applicationnumber =_applicationnumber limit 1)
else sr.bookid end ) as bookid,
--bt.booknameenglish as bookname,
(select booknameenglish from kaveri.booktypemaster bk where bk.bookid =
(case when pm.stamparticlecode = 14 and pm.isbefore2004=false  then
(select kd1.bookid from kaveri.k1documentdetails kd1 where kd1.applicationnumber =_applicationnumber limit 1)
else sr.bookid end )) as bookname,
pm.srocode,
se.sronamee as sroname,
pm.propertytypeid,
pt.propertytypename,
pm.noofscanpages,
pm.ismovableproperty,
pm.movablepropertydesc,
w.wardid,
pm.totalarea,
me.descriptionenglish as unit,
w.wardnumber,
pm.landmark,
pm.zoneid,
zone.departmentname as zonename,
pm.subpropertytypeid,
v_countrecord as countofrecord,
pm.roadcode as roadcode,
rd.roadnamee as roadnamee,
ta.unit as unittype,
pt.isagri as isagriculture,
se.districtcode as kaveridistrictcode
from kaveri.propertymaster pm 
left join kaveri.bhoomimappingdetails bh on (pm.villagecode=bh.kaverivillagecode)
left join kaveri.bhoomivillagemaster vi on (bh.bhoomivillagecode  = vi.villagecode and bh.bhoomitalukcode=vi.talukcode and bh.bhoomidistrictcode=vi.districtcode and bh.bhoomihobicode=vi.hoblicode)
left join kaveri.bhoomihoblimaster ho on (ho.hoblicode =bh.bhoomihobicode and ho.talukcode=bh.bhoomitalukcode  and ho.districtcode=bh.bhoomidistrictcode)
left join kaveri.bhoomitalukmaster ta on (bh.bhoomitalukcode=ta.talukcode and bh.bhoomidistrictcode=ta.districtcode)
left join kaveri.bhoomidistrictmaster  di on (di.districtcode = ta.districtcode)
left join kaveri.documentmaster dc on pm.applicationnumber=dc.applicationnumber  --(dc.regarticlecode = pm.regarticlecode and dc.documentid=pm.documentid)
left join kaveri.stamparticles sp on (sp.stamparticlecode = pm.stamparticlecode)
left join kaveri.stamprules sr on (sr.stampruleid = pm.stampruleid)
left join kaveri.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
left join kaveri.booktypemaster bt on (bt.bookid = sr.bookid)
left join kaveri.sromaster se on (se.srocode = pm.srocode)
left join kaveri.propertytypemaster pt on pt.propertytypeid = pm.propertytypeid
left join kaveri.villagewardmapping vw on vw.villagecode = pm.villagecode and vw.wardid = pm.wardid and pm.ismovableproperty=false
left join kaveri.warddetails w on  w.wardid = pm.wardid
left join kaveri.measunitmaster me on me.unitid = pm.unitid
left join kaveri.integrationdepartment zone on pm.zoneid = zone.udeptid
left join kaveri.roadmaster rd on (pm.roadcode=rd.roadcode)
where pm.applicationnumber =_applicationnumber and pt.isagri=true;


create temporary table isnonagridata
as 
select pm.propertyid as PIDNO,pm.villagecode,vi.villagenamee as Village,
vi.hoblicode,ho.hoblinamee as Hobli,vi.talukcode,ta.taluknamee as Taluk,
sm.districtcode,di.districtnamee as District,
pm.stamparticlecode,
sp.articlenamee as stamparticle,
pm.stampruleid,
sr.descriptione as stampsubarticle,
pm.regarticlecode,
ra.articlenamee as registrationfeearticle,
(case when pm.stamparticlecode = 14 and pm.isbefore2004=false then
(select kd2.bookid from kaveri.k1documentdetails kd2 where kd2.applicationnumber =_applicationnumber limit 1)
else sr.bookid end ) as bookid,
--bt.booknameenglish as bookname,
(select booknameenglish from kaveri.booktypemaster bk1 where bk1.bookid =
(case when pm.stamparticlecode = 14 and pm.isbefore2004=false then
(select kd3.bookid from kaveri.k1documentdetails kd3 where kd3.applicationnumber =_applicationnumber limit 1)
else sr.bookid end )) as bookname,
pm.srocode,
sm.sronamee as sroname,
pm.propertytypeid,
pt.propertytypename,
pm.noofscanpages,
pm.ismovableproperty,
pm.movablepropertydesc,
w.wardid,
pm.totalarea,
me.descriptionenglish as unit,
w.wardnumber,
pm.landmark,
pm.zoneid,
zone.departmentname as zonename,
pm.subpropertytypeid ,
v_countrecord as countofrecord,
pm.roadcode as roadcode,
rd.roadnamee as roadnamee,
ta.unit as unittype,
pt.isagri as isagriculture,
NULL::bigint as kaveridistrictcode
from kaveri.propertymaster pm 
left join kaveri.villagemaster vi on (pm.villagecode = vi.villagecode)
left join kaveri.sromaster sm on (vi.srocode=sm.srocode)
left join kaveri.hoblimaster ho on (ho.hoblicode = vi.hoblicode)
left join kaveri.talukmaster ta on (ta.talukcode=vi.talukcode)
left join kaveri.districtmaster di on (di.districtcode = sm.districtcode)
--left join kaveri.bhoomidistrictmaster  di on (di.districtcode = ta.districtcode)
left join kaveri.documentmaster dc on dc.applicationnumber=pm.applicationnumber ---(dc.regarticlecode = pm.regarticlecode and dc.documentid=pm.documentid)
left join kaveri.stamparticles sp on (sp.stamparticlecode = pm.stamparticlecode)
left join kaveri.stamprules sr on (sr.stampruleid = pm.stampruleid)
left join kaveri.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
left join kaveri.booktypemaster bt on (bt.bookid = sr.bookid)
--left join kaveri.sromaster se on (se.srocode = pm.srocode)
left join kaveri.propertytypemaster pt on pt.propertytypeid = pm.propertytypeid
left join kaveri.villagewardmapping vw on vw.villagecode = pm.villagecode and vw.wardid = pm.wardid and pm.ismovableproperty=false
left join kaveri.warddetails w on  w.wardid = pm.wardid
left join kaveri.measunitmaster me on me.unitid = pm.unitid
left join kaveri.integrationdepartment zone on pm.zoneid = zone.udeptid
left join kaveri.roadmaster rd on (pm.roadcode=rd.roadcode)
where pm.applicationnumber =_applicationnumber and pt.isagri=false;

return query
select isagri.* from isagridata isagri
union 
select isnonagri.* from isnonagridata isnonagri;

drop  table isagridata;
drop  table isnonagridata;

end;
$$;


ALTER FUNCTION kaveri.fn_fetch_propertydetailschk_k1pending(_applicationnumber text) OWNER TO postgres;

--
-- Name: fn_fetch_propertymaster_documentsummary_json_1(text, bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_propertymaster_documentsummary_json_1(_applicationnumber text, _srocode bigint) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json1 json;
v_app text;
begin
v_app:=	_applicationnumber;
	

select array_to_json(array_agg(row_to_json(propertyinfo))) into v_data_json1
from (SELECT pm.applicationnumber,	  
			pm.propertyid,
			pm.documentid,
			stm.articlenamee as stamparticle,
			pm.ismovableproperty,
			d.villagenamee,
			pm.propertytypeid,
			ptm.propertytypename as propertytype,
			c.sronamee sroname,
			pm.northboundary,
			pm.denodescription ,
			pm.estampdescription,
			pm.adjudescription ,
			pm.southboundary,
			pm.eastboundary,
			pm.westboundary,
			pm.landmark,
			pm.consideration,
			pm.marketvalue,
			pm.sroconsideration,
			case when pm.sromarketvalue is null then 0 else pm.sromarketvalue end sromarketvalue,
			pm.cessduty,
			pm.govtduty,
			pm.additionalduty,
			pm.stampduty,
			pm.valid1 as duplicatecopies,
			calc.duplicatefee,
			calc.duplicatestampduty,
			calc.duplicateregistrationfee,
			calc.privateattendancefee,
			--calc.stampduty, 		
			pm.valuationreport,
			pm.sronoofscanpages, /* added a new column on 07/10/2022 to fetch number of scan pages in document summary page */
			sr.ismarketvaluationdone, /* added a new column on 06/11/2022 */
			h.hoblinamee as hobli, /* added a new column on 06/11/2022 */
			srf.ispartytopropertyschd, /* added a new column on 07/11/2022 */
			( select array_to_json(array_agg(row_to_json(schd)))
			  from (

				  select distinct ps.propertyid as propertyschedulespropertyid, 
						ps.scheduletype, 
						ps.totalarea,
					string_agg(pi.name,',') as bhoomisellername, pnam.firstname as name, ps.description as scheduledescription,
					case when pm.propertytypeid=17 then string_agg(pi.name,',') else null end as bhoomisellerparty,
					ps.eastboundary, ps.westboundary, ps.northboundary, ps.southboundary
				  from kaveri.propertyschedules ps 
				  left join kaveri.vw_fetch_party pi on pi.propertyid = ps.propertyid
				  left join (select ps1.scheduleid, array_to_string(array_agg(distinct pi2.name),',') 
								AS firstname from kaveri.partyschedules ps1
			left join 
						(select name,partyid from kaveri.vw_fetch_party vf where vf.applicationnumber = v_app ) as pi2 
							 on pi2.partyid = ps1.partyid 
							group by ps1.scheduleid)
				  as pnam on ps.scheduleid = pnam.scheduleid
				  where  ps.propertyid = pm.propertyid 
				  group by ps.propertyid, ps.scheduletype, ps.totalarea, pnam.firstname, ps.description, ps.eastboundary,
				  ps.westboundary, ps.northboundary, ps.southboundary)schd ) as propertyschedules,			
			  ( select array_to_json(array_agg(row_to_json(prptyno)))
			   from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,
					 pntm.typenameenglish as propertynumbertype, pnd.currentnumber, coalesce(pnd.hissa_no,'') as hissa_no,
					 coalesce(pnd.survey_no,0) as survey_no, pnd.description as propertynumberdescription
					from kaveri.propertynumberdetails pnd 
					 left join kaveri.propertynotypemaster pntm on (pntm.propertytypeid = pnd.currentpropertytypeid) 
					 where pnd.propertyid = pm.propertyid )prptyno ) as propertynumberdetails
		   FROM kaveri.propertymaster pm 
		    join kaveri.propertytypemaster ptm on (ptm.propertytypeid = pm.propertytypeid) 
			 join kaveri.stamparticles stm on (stm.stamparticlecode=pm.stamparticlecode)
			 join kaveri.stamprules sr on pm.stampruleid = sr.stampruleid
			 join kaveri.stamprulesflag srf ON sr.stampruleid = srf.stampruleid
		    join  kaveri.sromaster c on (pm.srocode = c.srocode)
		    join kaveri.villagemaster d on (pm.villagecode = d.villagecode)
			 join kaveri.hoblimaster h on d.hoblicode = h.hoblicode
		    left join kaveri.vw_fee_calculation_details_chk_v3 calc on (pm.applicationnumber = calc.applicationnumber)
		   where pm.applicationnumber=v_app and pm.srocode=_srocode) as propertyinfo;
	
	
return v_data_json1;

END;
$$;


ALTER FUNCTION kaveri.fn_fetch_propertymaster_documentsummary_json_1(_applicationnumber text, _srocode bigint) OWNER TO postgres;

--
-- Name: fn_fetch_propertyschedulesdata(text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_propertyschedulesdata(_applicationnumber text) RETURNS TABLE(scheduleid bigint, propertyid bigint, srocode integer, partyid bigint, scheduletype character varying, totalarea numeric, unitid integer, description character varying, partyids character varying, aileniatedauthorityid boolean, alieniatedorder character varying, bhoomisellerpartyids character varying, govtrestricorder character varying, govtrestrictionid boolean, landcode bigint, propertygroup smallint, giftshare numeric, giftsharedetails character varying, easttowest character varying, northtosouth character varying, blockchainpropertyid character varying, assignedblockchainpid character varying, applicationnumber character varying, verified boolean, issroapproved character varying, eastboundary character varying, westboundary character varying, northboundary character varying, southboundary character varying, transactextacre integer, transactextgunta integer, transactextfgunta numeric)
    LANGUAGE plpgsql
    AS $$
Declare
v_cntproperty bigint;

begin

select count(*) into v_cntproperty
from kaveri.propertynumberdetails ps 
join kaveri.propertymaster pm on ps.propertyid=pm.propertyid
where pm.applicationnumber=_applicationnumber and ps.currentpropertytypeid in (1,60,65);
	

return query
select ps.scheduleid,
ps.propertyid,
ps.srocode,
ps.partyid,
ps.scheduletype,
pmm.totalarea,
ps.unitid,
ps.description,
ps.partyids,
ps.aileniatedauthorityid,
ps.alieniatedorder,
ps.bhoomisellerpartyids,
ps.govtrestricorder,
ps.govtrestrictionid,
ps.landcode,ps.propertygroup,
ps.giftshare,
ps.giftsharedetails,
ps.easttowest,
ps.northtosouth,
ps.blockchainpropertyid,
ps.assignedblockchainpid,
ps.applicationnumber,
ps.verified,
ps.issroapproved,
ps.eastboundary,
ps.westboundary,
ps.northboundary,
ps.southboundary,
p.transactextacre,
p.transactextgunta,
p.transactextfgunta
from kaveri.propertyschedules ps
left join (select p.* from kaveri.partyinfo p
left join kaveri.propertymaster pm on p.applicationnumber=pm.applicationnumber and pm.propertyid in (select ps.propertyid
from kaveri.propertynumberdetails ps 
join kaveri.propertymaster pm on ps.propertyid=pm.propertyid
where pm.applicationnumber=_applicationnumber --and ps.currentpropertytypeid in (1,60,65)
)
 where pm.applicationnumber=_applicationnumber and  partytypeid = 2  order by ownerno limit 1)as p
on  p.applicationnumber=ps.applicationnumber 
join kaveri.propertymaster pmm on ps.propertyid=pmm.propertyid               
left join kaveri.stamprulesflag sf on sf.stampruleid =pmm.stampruleid 
where ps.applicationnumber=_applicationnumber and  p.partytypeid =(case when sf.isownertobeclaimant=true then 1 else 2 end)
order by ps.scheduleid; 

end;
$$;


ALTER FUNCTION kaveri.fn_fetch_propertyschedulesdata(_applicationnumber text) OWNER TO postgres;

--
-- Name: fn_fetch_propnumberdetails(text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_propnumberdetails(_applicationnumber text) RETURNS TABLE(propertyid bigint, surveyno integer, hissano character varying, ownername text, transactextacre integer, transactextgunta integer, transactextfgunta numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
v_partytypeid BOOL;
begin

select isownertobeclaimant into v_partytypeid from kaveri.stamprulesflag sf where sf.stampruleid in (Select stampruleid from kaveri.propertymaster p where p.applicationnumber =_applicationnumber limit 1);


return query	
select b.propertyid,b.survey_no as SurveyNo,
b.hissa_no as HissaNo,
--(select string_agg(firstname,', ')  from kaveri.partyinfo pp where pp.propertyid =a.propertyid and pp.partytypeid=
--(case when false=true then 1 else 2 end)) as ownername,
(select string_agg(ss.name,', ') from(
				select pp.ownerno ,string_agg(coalesce(firstname,' ') ||' '|| coalesce(r.relatione,' ') ||' '||coalesce(pp.relativename,' '),' ') as name
				from kaveri.partyinfo pp 
				join kaveri.relationshipmasters r on r.id::text=pp.relationship::text
				where pp.propertyid =a.propertyid --and pp.ownerno in (select min(ownerno) from kaveri.partyinfo p where propertyid=pp.propertyid) 
				and pp.partytypeid= (case when v_partytypeid=true then 1 else 2 end)group by pp.ownerno order by ownerno
				)ss) as ownername,
--(select coalesce(r.relatione,a.relationship)
--from kaveri.partyinfo a1
--where a1.ownerno in (select min(ownerno) from kaveri.partyinfo p 
--where p.propertyid=a.propertyid) 
--and r.id::text=a1.relationship::text
--and a1.propertyid=a.propertyid) as relationship,a.relativename,
a.availableextacre as transactextacre,a.availableextgunta as transactextgunta ,a.availableextfgunta as transactextfgunta 
from
kaveri.partyinfo a 
inner join kaveri.propertynumberdetails b on a.propertyid = b.propertyid
left join kaveri.relationshipmasters r on r.id::text = a.relationship::text 
where a.applicationnumber = _applicationnumber --and pm.propertyid= b.propertyid 
and a.partytypeid= (case when v_partytypeid=true then 1 else 2 end)
order by a.ownerno;

end;
$$;


ALTER FUNCTION kaveri.fn_fetch_propnumberdetails(_applicationnumber text) OWNER TO postgres;

--
