			calc.duplicatefee,
			calc.duplicatestampduty,
			calc.duplicateregistrationfee,
			calc.privateattendancefee,
			--calc.stampduty, 		
			pm.valuationreport,
			pm.sronoofscanpages, /* added a new column on 07/10/2022 to fetch number of scan pages in document summary page */
			sr.ismarketvaluationdone, /* added a new column on 06/11/2022 */
			h.hoblinamee as hobli, /* added a new column on 06/11/2022 */
			srf.ispartytopropertyschd, /* added a new column on 07/11/2022 */
			( select array_to_json(array_agg(row_to_json(schd)))
			  from (

				  select distinct ps.propertyid as propertyschedulespropertyid, 
						ps.scheduletype, 
						ps.totalarea,
					string_agg(pi.name,',') as bhoomisellername, pnam.firstname as name, ps.description as scheduledescription,
					case when pm.propertytypeid=17 then string_agg(pi.name,',') else null end as bhoomisellerparty,
