				  ps.westboundary, ps.northboundary, ps.southboundary)schd ) as propertyschedules,			
			  ( select array_to_json(array_agg(row_to_json(prptyno)))
			   from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,
					 pntm.typenameenglish as propertynumbertype, pnd.currentnumber, coalesce(pnd.hissa_no,'') as hissa_no,
					 coalesce(pnd.survey_no,0) as survey_no, pnd.description as propertynumberdescription
					from kaveri.propertynumberdetails pnd 
					 left join kaveri.propertynotypemaster pntm on (pntm.propertytypeid = pnd.currentpropertytypeid) 
					 where pnd.propertyid = pm.propertyid )prptyno ) as propertynumberdetails
		   FROM kaveri.propertymaster pm 
		    join kaveri.propertytypemaster ptm on (ptm.propertytypeid = pm.propertytypeid) 
			 join kaveri.stamparticles stm on (stm.stamparticlecode=pm.stamparticlecode)
			 join kaveri.stamprules sr on pm.stampruleid = sr.stampruleid
			 join kaveri.stamprulesflag srf ON sr.stampruleid = srf.stampruleid
		    join  kaveri.sromaster c on (pm.srocode = c.srocode)
		    join kaveri.villagemaster d on (pm.villagecode = d.villagecode)
			 join kaveri.hoblimaster h on d.hoblicode = h.hoblicode
		    left join kaveri.vw_fee_calculation_details_chk_v2 calc on (pm.applicationnumber = calc.applicationnumber)
		   where pm.applicationnumber=v_app) as propertyinfo;
	
	
return v_data_json1;

END;
$$;


ALTER FUNCTION kaveri.fn_fetch_prpty_data_doc_summary(_applicationnumber text) OWNER TO csgadmin;

--
-- Name: fn_fetch_ratedetails(bigint, boolean, timestamp with time zone); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_ratedetails(_roadcode bigint, isreadyrecknor boolean, _date timestamp with time zone) RETURNS TABLE(flaterateid bigint, floor character varying, floorid smallint, propertytype character varying, unit character varying, unitid integer, amenities character varying, amenitiesid integer, rate numeric)
    LANGUAGE plpgsql
    AS $$



declare
v_cnt int;
v_max_rate bigint;
v_measure_id int;
v_rate bigint;
begin
	

	if (isreadyrecknor=false)
		then 
		return query
		select s.flaterateid,s.floor,s.floorid,s.propertytype, s.unit, s.unitid, s.amenities, s.amenitiesid,s.rate from (
		select flatRates.flaterateid,flatRates.floor,flatRates.floorid,flatRates.propertytype, flatRates.unit, flatRates.unitid, flatRates.amenities,flatRates.amenitiesid,  
		(case when flatRates.unitid = 3 then (flatRates.rate::decimal * 10.7639::decimal) else flatRates.rate::decimal end) 
		as rate from (select frm.flaterateid,br.description as floor,br.floorid,pm.propertytypename as propertytype,mu.descriptionenglish as unit
		,mu.unitid ,am.namewithamenities as amenities,am.amenitiesid,frm.rate, ROW_NUMBER() OVER(PARTITION BY frm.propertytypeid , 
		frm.floorid,frm.unitid,frm.amenitiesid  ORDER BY frm.effectivedate  desc) AS Row from kaveri.mas_val_flatrates frm
		left join kaveri.measunitmaster mu on frm.unitid=mu.unitid
		left join kaveri.mas_val_buildingfloors br on frm.floorid=br.floorid
		left join kaveri.mas_val_apartmentsamenities am on frm.amenitiesid=am.amenitiesid 
		left join kaveri.propertytypemaster pm on frm.propertytypeid=pm.propertytypeid
		where frm.roadid=_roadcode and frm.effectivedate::date <= _date )flatRates where row =1) s;
			
	
	elsif(isreadyrecknor=true)
		then
		select count(*) into v_cnt from (select frm.flaterateid,br.description as floor,br.floorid,pm.propertytypename as propertytype,mu.descriptionenglish as unit
		,mu.unitid ,am.namewithamenities as amenities,am.amenitiesid,frm.rate, ROW_NUMBER() OVER(PARTITION BY frm.propertytypeid, 
		frm.floorid,frm.unitid,frm.amenitiesid  ORDER BY frm.effectivedate  desc) AS Row from kaveri.mas_val_flatrates frm 
	    left join kaveri.measunitmaster mu on frm.unitid=mu.unitid
		left join kaveri.mas_val_buildingfloors br on frm.floorid=br.floorid
		left join kaveri.mas_val_apartmentsamenities am on frm.amenitiesid=am.amenitiesid 
		left join kaveri.propertytypemaster pm on frm.propertytypeid=pm.propertytypeid
		where frm.roadid=_roadcode and frm.effectivedate::date <= _date)flatRates where row =1;
		
		select frm.rate into v_rate from kaveri.mas_val_flatrates frm 
	    left join kaveri.measunitmaster mu on frm.unitid=mu.unitid
		left join kaveri.mas_val_buildingfloors br on frm.floorid=br.floorid
		left join kaveri.mas_val_apartmentsamenities am on frm.amenitiesid=am.amenitiesid 
		left join kaveri.propertytypemaster pm on frm.propertytypeid=pm.propertytypeid
		where frm.roadid=_roadcode and frm.effectivedate::date <= _date;
		
		if(v_cnt>0 and v_rate>0)
		then

			
			return query
			select m.flaterateid,m.floor,m.floorid,m.propertytype, m.unit, m.unitid, m.amenities, m.amenitiesid,m.rate from (
			select flatRates.flaterateid,flatRates.floor,flatRates.floorid,flatRates.propertytype, flatRates.unit, flatRates.unitid, flatRates.amenities
			, flatRates.amenitiesid,  
			(case when flatRates.unitid = 3 then (flatRates.rate::decimal * 10.7639::decimal) else flatRates.rate::decimal end) 
			as rate from (select frm.flaterateid,br.description as floor,br.floorid,pm.propertytypename as propertytype,mu.descriptionenglish as unit
			,mu.unitid ,am.namewithamenities as amenities,am.amenitiesid,frm.rate, ROW_NUMBER() OVER(PARTITION BY frm.propertytypeid, 
			frm.floorid,frm.unitid,frm.amenitiesid  ORDER BY frm.effectivedate  desc) AS Row from kaveri.mas_val_flatrates frm 
			left join kaveri.measunitmaster mu on frm.unitid=mu.unitid
			left join kaveri.mas_val_buildingfloors br on frm.floorid=br.floorid
			left join kaveri.mas_val_apartmentsamenities am on frm.amenitiesid=am.amenitiesid 
			left join kaveri.propertytypemaster pm on frm.propertytypeid=pm.propertytypeid
			where frm.roadid=_roadcode and frm.effectivedate::date <= _date)flatRates where row =1) m;
		
		else
		
		
			select ss.rate into v_max_rate  from (
			select (case when o.measurementcode=3 then max(o.rate)::decimal * 10.7639::decimal  
			else max(o.rate)::decimal end) as rate ,
--			into v_max_rate ,
			o.effectivedate,
			COALESCE(lead(o.effectivedate, 1) OVER (PARTITION BY o.roadcode, o.propertytypeid 
			ORDER BY o.effectivedate), CURRENT_DATE::timestamp without time zone) AS effectivetodate
			from kaveri.openbuiltratedetail o where roadcode =_roadcode
			group by o.measurementcode,o.effectivedate,o.roadcode, o.propertytypeid) as ss 
			where CURRENT_DATE >= ss.effectivedate AND CURRENT_DATE <= ss.effectivetodate
				;
			
	
		
	
			return query	
			select null::bigint as flaterateid,'Ground Floor'::character varying as floor,1::smallint as floorid
			,'Commercial'::character varying as propertytype,'Sq.metre'::character varying as unit,4 as unitid
			, 'Readyreckoner Rate'::character varying  as amenities,null::int as amenitiesid, flatrate::numeric as rate from kaveri.mas_val_readyreckoner_flats mvrf 
				where (vctratefrom<=v_max_rate and vctrateto>=v_max_rate); 
		
		end if;
	end if;

end;
$$;


ALTER FUNCTION kaveri.fn_fetch_ratedetails(_roadcode bigint, isreadyrecknor boolean, _date timestamp with time zone) OWNER TO csgadmin;

--
-- Name: fn_fetch_referencemaster_data(character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_referencemaster_data(_finalregistrationnumber character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
declare
v_newsrocode bigint;
v_oldsrocode bigint;
v_documentidnew bigint;
v_documentidold bigint;
v_sdcalculationstring character varying default null;
v_trid integer;
v_referencetext character varying ;
begin
if(_finalregistrationnumber is not null)
then
select pm.sdcalculationstring, dm.documentid, dm.srocode
into v_sdcalculationstring,v_documentidnew,v_newsrocode
from kaveri.documentmaster dm left outer join kaveri.propertymaster pm on
dm.applicationnumber=pm.applicationnumber
where dm.finalregistrationnumber=_finalregistrationnumber;

if (v_sdcalculationstring is not null) then
select  dm.documentid, dm.srocode  
into v_documentidold,v_oldsrocode
from kaveri.documentmaster dm left outer join kaveri.propertymaster pm on
dm.applicationnumber=pm.applicationnumber
where dm.finalregistrationnumber=v_sdcalculationstring ;

select string_agg(referencetext, '. ') into v_referencetext from kaveri.referencemaster 
where documentid in (v_documentidnew,v_documentidold); --and srocode in v_newsrocode;
 

RETURN v_referencetext;
else
return 1001;
end if;
end if;
end;
$$;


ALTER FUNCTION kaveri.fn_fetch_referencemaster_data(_finalregistrationnumber character varying) OWNER TO csgadmin;

--
-- Name: fn_fetch_registration_districts(integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_registration_districts(_districtcode integer) RETURNS TABLE(districtcode integer, districtnamee character varying)
    LANGUAGE plpgsql
    AS $$

begin
return query
	select d.districtcode,d.districtnamee from kaveri.districtmaster d
	join kaveri.bhoomidistrictmaster b on d.bhoomidistrictcode=b.districtcode
	where b.districtcode  = _districtcode;
end;
$$;


