--

CREATE FUNCTION kaveri.fn_fetch_report_queue_by_user(_deptuserid bigint) RETURNS TABLE(requestedreport character varying, fromdate character varying, todate character varying, status character varying, reportfilepath character varying, isreportdownloaded boolean)
    LANGUAGE plpgsql
    AS $$
BEGIN
   RETURN QUERY
 	select requestedreport||' reqid '||rid,to_char(fromdate,'dd-Mon-YYYY'),
 	to_char(todate,'dd-Mon-YYYY'),status,reportfilepath ,isreportdownloaded
from kaverimis.report_queue rq where isfiledeleted=false  and
requesteduser =_deptuserid  order by rq.rid asc;
END;
$$;


