--
-- Name: fn_fetch_reuploadjslip(character varying[]); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_reuploadjslip(_finalregistrationnumber character varying[]) RETURNS TABLE(documentid bigint, srocode integer, bookid integer, regarticlecode integer, applicationnumber character varying, finalregistrationnumber character varying, registrationdatetime timestamp without time zone, acknowledgeno character varying, remarks character varying, uploaddate timestamp without time zone, jslipsuccess boolean)
    LANGUAGE plpgsql
    AS $$
begin
return query
SELECT sub.documentid,
    sub.srocode,
    sub.bookid,
    sub.regarticlecode,
    sub.applicationnumber,
    sub.finalregistrationnumber,
    sub.registrationdatetime,
    sub.acknowledgeno,
    sub.remarks,
    sub.createddate AS uploaddate,
    sub.jslipsuccess
   FROM (
SELECT DISTINCT dm.documentid,
            dm.srocode,
            dm.bookid,
            dm.regarticlecode,
            dm.applicationnumber,
            dm.finalregistrationnumber,
            dm.registrationdatetime,
            COALESCE(bf.acknowledgeno, '0'::character varying) AS acknowledgeno,
            bf.remarks,
            bf.createddate,
                CASE
                    WHEN bf.remarks::text = ANY (ARRAY['Already Saved'::character varying::text, 'Saved'::character varying::text]) THEN true
                    ELSE false
                END AS jslipsuccess,
            dense_rank() OVER (PARTITION BY dm.applicationnumber, bf.finalregistrationnumber ORDER BY bf.acknowledgeno DESC NULLS LAST, bf.createddate DESC NULLS LAST) AS rank1
           FROM kaveri.documentmaster dm
             LEFT JOIN kaveri.bhoomifileuploaddetails bf ON dm.finalregistrationnumber::text = bf.finalregistrationnumber::text
             LEFT JOIN kaveri.propertymaster pm ON dm.documentid = pm.documentid
             LEFT JOIN kaveri.stamprulesflag s ON pm.stampruleid = s.stampruleid
          WHERE dm.isregistrationcompleted = true AND pm.propertytypeid = 17 AND s.isjslipagri IS true 
         and dm.finalregistrationnumber= any(_finalregistrationnumber) )sub;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_reuploadjslip(_finalregistrationnumber character varying[]) OWNER TO postgres;

--
-- Name: fn_fetch_review_marriage_details(character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_review_marriage_details(_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
begin
select row_to_json(data_json) into v_data_json 
from (select row_to_json(app_json)
from (select m.regsrocode as srocode,
			sm.sronamee as sroname,
			a.citizenid,
			to_char(m.applicationsubmit,'DD-MM-YYYY') as applicationsubmit,
			m.signedformpath,
			m.esignedsummarypath,
			m.currentstatus,--c.districtnamee,--c.drcode
(select array_to_json(array_agg(row_to_json(Marriagedetails))) 
from (select d.dateofmarriage::date as marriagedate,
      			d.districtcode,
      			d.talukacode,
      			d.hoblicode,
      			d.cityvillagecode,
      			d.statecode,
      			case when fun.statecode = 29 then
				coalesce(d.housebuildingname,'')||', '||coalesce(d.streetaddr,'')||', '||fun.districtnamee||', '||fun.taluknamee||', '||coalesce(fun.hoblinamee,'')||', '||coalesce(fun.villagenamee,'')||', '||INITCAP(fun.statenamee)||'-'||d.pincode
				else coalesce(d.housebuildingname,'')||', '||coalesce(d.streetaddr,'')||', '||INITCAP(fun.districtnamee)||', '||fun.taluknamee||', '||INITCAP(fun.statenamee)||'-'||d.pincode end as marriageaddress,
            	d.combinephotopath as Jointphotoofthebrideandbridegroom,
            	d.form_1path,
            	d.form_1apath,
            	d.marriageproofid,
				d.marriageproofpath,--d.intendedfilepath,
				d.bridegroomphoto,
				d.bridephoto,
				d.marriagemodeid,
				d.marriagetypeid,
				mm.marriagemode,
				mt.marriagetype,
				d.scannedform1path,
				d.numberofcopy
from kaveri.marriageregistration d join kaveri.mas_marriagemode mm on mm.marriagemodeid = d.marriagemodeid
									join kaveri.mas_marriagetype mt on mt.marriagetypeid = d.marriagetypeid
--									left join kaveri.districtmaster di on d.districtcode = di.districtcode
--			                        left join kaveri.talukmaster ta on d.talukacode = ta.talukcode
--			                        left join kaveri.hoblimaster ho on d.hoblicode = ho.hoblicode
--			                        left join kaveri.villagemaster vill on d.cityvillagecode = vill.villagecode
--			                        left join kaveri.statemaster stat on d.statecode = stat.statecode
									left JOIN LATERAL kaveri.fn_fetch_marriage_lgdmaster1(d.statecode, d.districtcode, d.talukacode, d.hoblicode, d.cityvillagecode::bigint) fun(statecode, statenamee, districtcode, districtnamee, talukcode, taluknamee, hoblicode, hoblinamee, villagecode, villagenamee) ON d.statecode = fun.statecode							
			 						where d.applicationnumber = _applicationnumber)Marriagedetails) as Marriageform,
			 						
(select array_to_json(array_agg(row_to_json(Bridegroom)))
from (select bg.personid,
			bg.salutation,
			s.descriptione as salutation,
			bg.firstname,
			bg.middlename,
			bg.lastname,
			bg.age,
			bg.perdistrictcode,
			bg.pertalukacode,
			bg.perhoblicode,
			bg.percityvillagecode,
			bg.predistrictcode,
			bg.pretalukacode,
			bg.prehoblicode,
			bg.precityvillagecode,--bg.statecode,
			case when fun.statecode = 29 then
			coalesce(bg.perhousebuildname,'')||', '||coalesce(bg.perstreetname,'')||', '||fun.districtnamee||', '||fun.taluknamee||', '||coalesce(fun.hoblinamee,'')||', '||coalesce(fun.villagenamee,'')||', '||INITCAP(fun.statenamee)||'-'||bg.perpincode 
			else coalesce(bg.perhousebuildname)||', '||coalesce(bg.perstreetname,'')||', '||INITCAP(fun.districtnamee)||', '||fun.taluknamee||', '||INITCAP(fun.statenamee)||'-'||bg.perpincode end as permanentaddress,  
			case when fun1.statecode = 29 then 
            coalesce(bg.prehousebuildname,'')||', '||coalesce(bg.prestreetname,'')||', '||fun1.districtnamee||', '||fun1.taluknamee||', '||coalesce(fun1.hoblinamee,'')||', '||coalesce(fun1.villagenamee,'')||', '||INITCAP(fun1.statenamee)||'-'||bg.prepincode
            else coalesce(bg.prehousebuildname,'')||', '||coalesce(bg.prestreetname,'')||', '||INITCAP(fun1.districtnamee)||', '||fun1.taluknamee||', '||INITCAP(fun1.statenamee)||'-'||bg.prepincode end as currentaddress,--,bg.currentpincode,bg.status,
			bg.dob as dateofbirth,
			bg.phoneno as phonenumber,
			s.descriptione as salutation,
			(select descriptione from kaveri.salutationmaster s join kaveri.persondetails bg on bg.fathersalutation = s.salutationid
			where bg.sex = 'M' and bg.applicationnumber = _applicationnumber) as fathersalutation,
			coalesce(bg.fatherfirstname,'')||' '||coalesce(bg.fathermiddlename,'')||' '||coalesce(bg.fatherlastname,'') as fathername,
			(select descriptione from kaveri.salutationmaster s join kaveri.persondetails bg on bg.mothersalutation = s.salutationid
			where bg.sex = 'M' and bg.applicationnumber = _applicationnumber) as mothersalutation,
			coalesce(bg.motherfirstname,'')||' '||coalesce(bg.mothermiddlename,'')||' '||coalesce(bg.motherlastname,'') as mothername,--bg.durationin,
			bg.occupation,
			bg.deathcertificateid,
			bg.deathcertificatefilepath,
			bg.divorcecertificateid,
			bg.divorcecertificatefilepath,
			bg.identityproofid,bg.email,
			bg.identityprooffilepath,
			bg.ageproofid,
			bg.ageprooffilepath,
			bg.addressproofid,
			bg.addressprooffilepath,
			bg.durationofstayproofpath,
			mb.description as status
		from kaveri.persondetails bg left join kaveri.mas_marriagebeforestatus mb on mb.statusid =bg.statusid
									left join kaveri.districtmaster distper on bg.perdistrictcode = distper.districtcode 
--			                        left join kaveri.talukmaster talper on bg.pertalukacode = talper.talukcode 
--			                        left join kaveri.hoblimaster hobper on bg.perhoblicode = hobper.hoblicode 
--			                        left join kaveri.villagemaster vilper on bg.percityvillagecode = vilper.villagecode
--                                  left join kaveri.districtmaster distcur on bg.perdistrictcode = distcur.districtcode 
--			                        left join kaveri.talukmaster talcur on bg.pertalukacode = talcur.talukcode 
--			                        left join kaveri.hoblimaster hobcur on bg.perhoblicode = hobcur.hoblicode 
--			                        left join kaveri.villagemaster vilcur on bg.percityvillagecode = vilcur.villagecode  
--                                  left join kaveri.statemaster stat on bg.perstatecode = stat.statecode
								 	join kaveri.salutationmaster s on bg.salutation = s.salutationid
									left JOIN LATERAL kaveri.fn_fetch_marriage_lgdmaster1(bg.perstatecode, bg.perdistrictcode, bg.pertalukacode, bg.perhoblicode, bg.percityvillagecode::bigint) fun(statecode, statenamee, districtcode, districtnamee, talukcode, taluknamee, hoblicode, hoblinamee, villagecode, villagenamee) ON bg.perstatecode = fun.statecode
     								left JOIN LATERAL kaveri.fn_fetch_marriage_lgdmaster1(bg.prestatecode, bg.predistrictcode, bg.pretalukacode, bg.prehoblicode, bg.precityvillagecode::bigint) fun1(statecode, statenamee, districtcode, districtnamee, talukcode, taluknamee, hoblicode, hoblinamee, villagecode, villagenamee) ON bg.prestatecode = fun1.statecode
									where bg.sex = 'M' and bg.applicationnumber = _applicationnumber)Bridegroom) as bridegroom,
									
(select array_to_json(array_agg(row_to_json(Bride)))
from(select br.personid,
			br.salutation,
			s.descriptione as salutation,
			br.firstname,
			br.middlename,
			br.lastname,
			br.age,--br.permanentaddress,br.presentaddress,
			br.perdistrictcode,
			br.pertalukacode,
			br.perhoblicode,
			br.percityvillagecode,
			br.predistrictcode,
			br.pretalukacode,
			br.prehoblicode,
			br.precityvillagecode,
			case when fun.statecode = 29 then
			coalesce(br.perhousebuildname,'')||', '||coalesce(br.perstreetname,'')||', '||fun.districtnamee||', '||fun.taluknamee||', '||coalesce(fun.hoblinamee,'')||', '||coalesce(fun.villagenamee,'')||', '||INITCAP(fun.statenamee)||'-'||br.perpincode 
			else coalesce(br.perhousebuildname,'')||', '||coalesce(br.perstreetname,'')||', '||INITCAP(fun.districtnamee)||', '||fun.taluknamee||', '||INITCAP(fun.statenamee)||'-'||br.perpincode end as permanentaddress,
            case when fun1.statecode = 29 then 
            coalesce(br.prehousebuildname,'')||', '||coalesce(br.prestreetname,'')||', '||fun1.districtnamee||', '||fun1.taluknamee||', '||coalesce(fun1.hoblinamee,'')||', '||coalesce(fun1.villagenamee,'')||', '||INITCAP(fun1.statenamee)||'-'||br.prepincode
            else coalesce(br.prehousebuildname,'')||', '||coalesce(br.prestreetname,'')||', '||INITCAP(fun1.districtnamee)||', '||fun1.taluknamee||', '||INITCAP(fun1.statenamee)||'-'||br.prepincode end as currentaddress,--br.status,
			br.dob as dateofbirth,
			br.phoneno as phonenumber,
			(select descriptione from kaveri.salutationmaster s join kaveri.persondetails bg on bg.fathersalutation = s.salutationid
			where bg.sex = 'F' and bg.applicationnumber = _applicationnumber) as fathersalutation,
			coalesce(br.fatherfirstname,'')||' '||coalesce(br.fathermiddlename,'')||' '||coalesce(br.fatherlastname,'')  as fathername,
			(select descriptione from kaveri.salutationmaster s join kaveri.persondetails bg on bg.mothersalutation = s.salutationid
			where bg.sex = 'F' and bg.applicationnumber = _applicationnumber) as mothersalutation,
			coalesce(br.motherfirstname,'')||' '||coalesce(br.mothermiddlename,'')||' '||coalesce(br.motherlastname,'')  as mothername,--br.durationin,
			br.occupation,
			br.deathcertificateid,
			br.deathcertificatefilepath,
			br.divorcecertificateid,
			br.divorcecertificatefilepath,
			br.identityproofid,
			br.email,
			br.identityprooffilepath,
			br.ageproofid,
			br.ageprooffilepath,
			br.addressproofid,
			br.addressprooffilepath,
			br.durationofstayproofpath,
			mb.description as status
			from kaveri.persondetails br left join kaveri.mas_marriagebeforestatus mb on mb.statusid =br.statusid
--									left join kaveri.districtmaster distper on br.perdistrictcode = distper.districtcode 
--			                        left join kaveri.talukmaster talper on br.pertalukacode = talper.talukcode 
--			                        left join kaveri.hoblimaster hobper on br.perhoblicode = hobper.hoblicode 
--			                        left join kaveri.villagemaster vilper on br.percityvillagecode = vilper.villagecode
--                                  left join kaveri.districtmaster distcur on br.predistrictcode = distcur.districtcode 
--			                        left join kaveri.talukmaster talcur on br.pretalukacode = talcur.talukcode 
--			                        left join kaveri.hoblimaster hobcur on br.prehoblicode = hobcur.hoblicode 
--			                        left join kaveri.villagemaster vilcur on br.precityvillagecode = vilcur.villagecode  
--                                  left join kaveri.statemaster stat on br.perstatecode = stat.statecode
									left join kaveri.salutationmaster s on br.salutation = s.salutationid
									left JOIN LATERAL kaveri.fn_fetch_marriage_lgdmaster1(br.perstatecode, br.perdistrictcode, br.pertalukacode, br.perhoblicode, br.percityvillagecode::bigint) fun(statecode, statenamee, districtcode, districtnamee, talukcode, taluknamee, hoblicode, hoblinamee, villagecode, villagenamee) ON br.perstatecode = fun.statecode
     								left JOIN LATERAL kaveri.fn_fetch_marriage_lgdmaster1(br.prestatecode, br.predistrictcode, br.pretalukacode, br.prehoblicode, br.precityvillagecode::bigint) fun1(statecode, statenamee, districtcode, districtnamee, talukcode, taluknamee, hoblicode, hoblinamee, villagecode, villagenamee) ON br.prestatecode = fun1.statecode
									where br.sex = 'F' and br.applicationnumber = _applicationnumber)Bride) as bride,
									
									
(select array_to_json(array_agg(row_to_json(witness)))
from (select e.witnessid,
			e.salutation,
			s.descriptione as salutation,
			coalesce(e.firstname,null) as firstname,
			coalesce(e.middlename,'') as middlename,
			coalesce(e.lastname,'') as lastname,
			e.age,
			--a.presentaddress,a.permanentaddress,
			e.perdistrictcode,
			e.pertalukacode,
			e.perhoblicode,
			e.pervillagecode,
			coalesce(e.perhouseno,'')||', '||coalesce(e.perstreetaddress,'')||', '||INITCAP(distper.districtnamee)||', '||talper.taluknamee||', '||INITCAP(stat.statenamee)||'-'||perpincode as permanentaddress,
            coalesce(e.currenthouseno,'')||', '||coalesce(e.currentstreetaddress,'')||', '||INITCAP(distcur.districtnamee)||', '||talcur.taluknamee||', '||INITCAP(statcur.statenamee)||'-'||e.currentpincode as currentaddress,
--			case when fun.statecode = 29 then
--			coalesce(e.perhouseno,'')||' '||coalesce(e.perstreetaddress,'')||' '||fun.districtnamee||' '||fun.taluknamee||' '||fun.hoblinamee||' '||fun.villagenamee||' '||INITCAP(fun.statenamee)||'-'||perpincode
--			else coalesce(e.perhouseno,'')||' '||coalesce(e.perstreetaddress,'')||' '||INITCAP(fun.districtnamee)||' '||fun.taluknamee||' '||INITCAP(fun.statenamee)||'-'||perpincode end as permanentaddress,
--			case when fun1.statecode = 29 then
--          coalesce(e.currenthouseno,'')||' '||coalesce(e.currentstreetaddress,'')||' '||fun1.districtnamee||' '||fun1.taluknamee||' '||fun1.hoblinamee||' '||fun1.villagenamee||' '||INITCAP(fun1.statenamee)||'-'||e.currentpincode
--           else coalesce(e.currenthouseno,'')||' '||coalesce(e.currentstreetaddress,'')||' '||INITCAP(fun1.districtnamee)||' '||fun1.taluknamee||' '||INITCAP(fun1.statenamee)||'-'||e.currentpincode end as currentaddress,
			--case when a.sex = 'M'  then
			-- a.bridegroomrelation 
			----z.relationname
			--when a.sex = 'F' then
			-- a.briderelation end as relation ,
			-- case when z.persontypeid = 1  then
			--'Bride Groom'
			----z.relationname
			--when a.persontypeid = 2 then
			-- 'Bride' end as relation,
			--z.relationname end as relation,
             z.relationname as relation,
			 mp.persontypename as witnessrelatedto,
			 e.dob,
			 e.email,
			 e.phoneno,
			 g.descriptione as gender
	from kaveri.marriagewitnessinfo e left join kaveri.gendermaster g on g.genderid = e.genderid
									left join kaveri.marriagewitnessrelationmaster z on z.relationid = e.relationid --and
									inner join kaveri.marriageregistration mr on mr.applicationnumber = e.applicationnumber
									join kaveri.mas_persontype mp on mp.persontypeid = e.witnessrelatedto
                        			join kaveri.lgd_districtmaster distper on e.perdistrictcode = distper.districtcode 
			                        join kaveri.lgd_talukmaster talper on e.pertalukacode = talper.talukcode 
--			                        left join kaveri.hoblimaster hobper on e.perhoblicode = hobper.hoblicode 
--			                        left join kaveri.villagemaster vilper on e.pervillagecode = vilper.villagecode
                                    join kaveri.lgd_districtmaster distcur on e.currentdistrictcode = distcur.districtcode 
			                        join kaveri.lgd_talukmaster talcur on e.currenttalukacode = talcur.talukcode 
--			                        left join kaveri.hoblimaster hobcur on e.currenthoblicode = hobcur.hoblicode 
--			                        left join kaveri.villagemaster vilcur on e.currentvillagecode = vilcur.villagecode
			                        join kaveri.lgd_statemaster stat on e.perstatecode = stat.statecode
			                        join kaveri.lgd_statemaster statcur on e.currrentstatecode = statcur.statecode
--									JOIN LATERAL kaveri.fn_fetch_marriage_lgdmaster1(e.perstatecode, e.perdistrictcode, e.pertalukacode, e.perhoblicode, e.pervillagecode::bigint) fun(statecode, statenamee, districtcode, districtnamee, talukcode, taluknamee, hoblicode, hoblinamee, villagecode, villagenamee) ON e.perstatecode = fun.statecode
--     								JOIN LATERAL kaveri.fn_fetch_marriage_lgdmaster1(e.currrentstatecode, e.currentdistrictcode, e.currenttalukacode, e.currenthoblicode, e.currentvillagecode::bigint) fun1(statecode, statenamee, districtcode, districtnamee, talukcode, taluknamee, hoblicode, hoblinamee, villagecode, villagenamee) ON e.currrentstatecode = fun1.statecode
									join kaveri.salutationmaster s on e.salutation = s.salutationid
							where e.applicationnumber = _applicationnumber order by e.witnessid asc )witness) as witness,
							
							
(select array_to_json(array_agg(row_to_json(VerificationDetails)))
from (select ar.verificationid,
			ar.marriagedetailsremarks_fda,
			ar.bridegroomdetailsremarks_fda,
			ar.bridedetailsremarks_fda,
			ar.witnessdetailsremarks_fda,
			ar.marriagedetailsremarks_sr,
			ar.bridegroomdetailsremarks_sr,
			ar.bridedetailsremarks_sr,
			ar.witnessdetailsremarks_sr,
			ar.canpreocesstopaymentremarks_sr		
from kaveri.marriageapplicationremarks ar where ar.applicationnumber = _applicationnumber )VerificationDetails) as VerificationRemarks
 				
from kaveri.marriageregistration m 
 			left join kaveri.applicantapplicationdetails a on m.applicationnumber = a.applicationnumber
 			join kaveri.sromaster sm on m.regsrocode = sm.srocode
 			--JOIN kaveri.villagemaster v ON v.villagecode = a.percityvillagecode
 			--JOIN kaveri.sromaster sm ON v.srocode = sm.srocode
			--inner join kaveri.districtmaster c on sm.districtcode = c.districtcode     	
			where m.applicationnumber = _applicationnumber
		)app_json) data_json;
	return v_data_json;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_review_marriage_details(_applicationnumber character varying) OWNER TO csgadmin;

--
-- Name: fn_fetch_road_details(bigint, boolean); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_road_details(p_villagecode bigint, p_isactive boolean) RETURNS TABLE(roadcode bigint, roadnamee character varying, roadnamek character varying)
    LANGUAGE plpgsql
    AS $$

BEGIN
if(p_isactive=true) THEN
			Return query
			select distinct  r.roadcode,r.roadnamee,r.roadnamek from kaveri.roadmaster r
			inner join kaveri.rateagriculturaldetail agri on r.roadcode=agri.roadcode
			where r.villagecode = p_villagecode and r.isactive = true and agri.rate>0
		Union all 	
			select distinct r.roadcode,r.roadnamee,r.roadnamek from kaveri.roadmaster r
		--left outer join kaveri.mas_val_flatrates f on r.roadcode=f.roadid
		left outer join kaveri.openbuiltratedetail o on r.roadcode=o.roadcode
		where r.villagecode = p_villagecode 
		 and r.isactive = true 
		 and o.rate>0;
		 --and (f.rate>0 and o.rate>0);		
ELSE
		return query
		select distinct r.roadcode,r.roadnamee,r.roadnamek from kaveri.roadmaster r
		left outer join kaveri.mas_val_flatrates f on r.roadcode=f.roadid
		left outer join kaveri.openbuiltratedetail o on r.roadcode=o.roadcode
		where r.villagecode = p_villagecode and r.isactive = true and (f.rate>0 or o.rate>0);
END IF;

END;
$$;


ALTER FUNCTION kaveri.fn_fetch_road_details(p_villagecode bigint, p_isactive boolean) OWNER TO csgadmin;

--
-- Name: fn_fetch_roadmasterdetails(integer, integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_roadmasterdetails(_srocode integer, _districtcode integer, _talukacode integer, _hoblicode integer, _villagecode integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(roadcode bigint, roadnamee character varying, roadnamek character varying, villagecode bigint, villagenamee character varying, isactive boolean, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);


return query 

with cte as (select  distinct r.roadcode,r.roadnamee,r.roadnamek,r.villagecode,v.villagenamee,r.isactive from kaveri.roadmaster r
inner join kaveri.villagemaster v on r.villagecode=v.villagecode
where r.villagecode =_villagecode),cte_count as (select count(*) as total_rows from cte)
   select * from cte
   right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
FETCH NEXT pagesize ROWS ONLY;

END;
$$;


ALTER FUNCTION kaveri.fn_fetch_roadmasterdetails(_srocode integer, _districtcode integer, _talukacode integer, _hoblicode integer, _villagecode integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_roleinfo_byuseid(integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_roleinfo_byuseid(user_id integer) RETURNS TABLE(rolesinfo json)
    LANGUAGE plpgsql
    AS $$

DECLARE


BEGIN


	
   RETURN QUERY
   
	select (select array_to_json(array_agg(row_to_json(roles))) 
			from (
			select 0 as userroleid, dr.designationid,dm.designame,'Default' as rolename,
			false as candelete,
			sr.officename||'-'||mo.officetypedesc  as sroname, 
			sr.officenamer||'-'||mo.officetypedescr as sronamek,
			concat_ws(' '::text, dr.firstname, dr.lastname) AS Name,
			dr.mobileno  as MobileNumber, 
			concat_ws(' '::text, dr.firstname, dr.lastname)||' - '||dm.designame as displayName,
			dr.userid,0 as mappeduserid,'' as mappedUser
			FROM kaveri.desigmaster dm
			inner join kaveri.departmentusers dr on dm.designationid=dr.designationid  
			left join kaveri.mas_officemaster sr on(sr.officeid = dr.officeid)
			join kaveri.mas_officetypes mo on sr.officetypeid=mo.officetypeid
			where dr.userid=user_id	
			union all			
			select rl.userroleid ,rl.designationid,dmrl.designame::character varying,dmrl.designame::character varying as rolename,
			true as candelete,
			sr.officename||'-'||mo.officetypedesc  as sroname, 
			sr.officenamer||'-'||mo.officetypedescr as sronamek,
			concat_ws(' '::text, dr.firstname, dr.lastname) AS Name,
			dr.mobileno  as MobileNumber,
			concat_ws(' '::text, dr.firstname, dr.lastname)||' - '||dmrl.designame as displayName,
			dr.userid,rl.mappeduserid as mappeduserid, concat_ws(' '::text, c.firstname, c.lastname) as mappedUser
			from kaveri.departmentuserroles rl 
			inner join Kaveri.desigmaster dmrl on (rl.designationid = dmrl.designationid)
			inner join kaveri.departmentusers dr on (dr.userid = rl.userid)
			inner join kaveri.departmentusers c  on (c.userid =rl.mappeduserid)
			left join kaveri.mas_officemaster sr on(sr.officeid = rl.mappedofficeid)
			join kaveri.mas_officetypes mo on sr.officetypeid=mo.officetypeid
			where rl.userid =user_id				
			Union All
			select rl.userroleid ,rl.designationid,dmrl.designame::character varying,dmrl.designame::character varying as rolename,
			true as candelete,
			sr.officename||'-'||mo.officetypedesc  as sroname, 
			sr.officenamer||'-'||mo.officetypedescr as sronamek,
			concat_ws(' '::text, dr.firstname, dr.lastname) AS Name,
			dr.mobileno  as MobileNumber,
			concat_ws(' '::text, dr.firstname, dr.lastname)||' - '||dmrl.designame as displayName,
			dr.userid,
			null  as mappeduserid, 
		     null  as mappedUser
			from kaveri.departmentuserroles rl 
			inner join Kaveri.desigmaster dmrl on (rl.designationid = dmrl.designationid)
			inner join kaveri.departmentusers dr on (dr.userid = rl.userid) and rl.mappeduserid is NULL
			left join kaveri.mas_officemaster sr on(sr.officeid = dr.officeid)
			join kaveri.mas_officetypes mo on sr.officetypeid=mo.officetypeid
			where rl.userid =user_id 
								
			) roles)as roleinfo;
			

		
			
			END;
$$;


ALTER FUNCTION kaveri.fn_fetch_roleinfo_byuseid(user_id integer) OWNER TO csgadmin;

