CREATE FUNCTION kaveri.fn_fetch_rule17_deo_wrkflowcount(_deoid bigint) RETURNS TABLE(recieved_from_sro_for_de bigint, recieved_from_sro_with_remarks_for_corrections bigint, recieved_from_fda_with_remarks_for_corrections bigint, recieved_from_sro_to_scan_and_upload bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE

begin 

select Count(*) as RECIEVED_FROM_SRO_FOR_DE into RECIEVED_FROM_SRO_FOR_DE  from(

select * from kaveri.vw_fetch_rule_17_deo_dashboard where deoid = _deoid and currentstatus in ('RL131','RL132','RL144')) recievedfromsroforde;


--select Count(*) as DATA_ENTRY_IN_PROGRESS_DE into RECIEVED_FROM_SRO_FOR_DE  from(

--select * from kaveri.vw_fetch_rule_17_deo_dashboard where deoid = _deoid and currentstatus in ('RL144')) dataentryinprogress;

    
select Count(*) as RECIEVED_FROM_SRO_WITH_REMARKS_FOR_CORRECTIONS  into RECIEVED_FROM_SRO_WITH_REMARKS_FOR_CORRECTIONS from(

select distinct * from kaveri.vw_fetch_rule_17_deo_dashboard where deoid= _deoid and currentstatus='RL141')recievedfromsrowithremarksforcorrections;

select Count(*) as RECIEVED_FROM_FDA_WITH_REMARKS_FOR_CORRECTIONS into RECIEVED_FROM_FDA_WITH_REMARKS_FOR_CORRECTIONS  from(

