select Count(*) as RECIEVED_FROM_SRO_TO_SCAN_AND_UPLOAD into RECIEVED_FROM_SRO_TO_SCAN_AND_UPLOAD  from(

select distinct * from kaveri.vw_fetch_rule_17_deo_dashboard where deoid= _deoid and currentstatus in ('RL138'))recievedfromsrotoscanandupload;
return query 

select RECIEVED_FROM_SRO_FOR_DE, RECIEVED_FROM_SRO_WITH_REMARKS_FOR_CORRECTIONS, RECIEVED_FROM_FDA_WITH_REMARKS_FOR_CORRECTIONS,RECIEVED_FROM_SRO_TO_SCAN_AND_UPLOAD;

end;

$$;


