--
-- Name: fn_fetch_rule17_sro_wrkflowcount(bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_rule17_sro_wrkflowcount(_srocode bigint) RETURNS TABLE(allocate_deo_de bigint, reallocate_to_deo bigint, recieved_from_deo_for_verification bigint, reallocate_to_fda_for_verification bigint, recieved_from_deo_with_correction bigint, recieved_from_fda_for_approval bigint, recieved_from_deo_for_scan bigint, ready_for_digi_sign bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE

v_AllocatedtoFDA_SDA bigint;

v_ReceivedfromFDA_SDA_SDA bigint;
AllocatedtoScanFDA_SDA bigint;

--v_array bigint[];

begin 

select Count(*) as Allocate_DEO_DE into Allocate_DEO_DE  from(

select * from kaveri.vw_fetch_rule_17_sro_dashboard where srocode = _srocode and currentstatus in ('RL131')) allocate_deo_de;

    
select Count(*) as Reallocate_TO_DEO  into Reallocate_TO_DEO from(

select distinct * from kaveri.vw_fetch_rule_17_sro_dashboard where srocode= _srocode and currentstatus in ('RL132','RL144'))allocatedtodeo;

select Count(*) as Recieved_FROM_DEO_FOR_VERIFICATION into Recieved_FROM_DEO_FOR_VERIFICATION  from(

select distinct * from kaveri.vw_fetch_rule_17_sro_dashboard where srocode= _srocode and currentstatus='RL133') sda ;

select Count(*) as Reallocate_TO_FDA_FOR_VERIFICATION into Reallocate_TO_FDA_FOR_VERIFICATION  from(

select distinct * from kaveri.vw_fetch_rule_17_sro_dashboard where srocode= _srocode and currentstatus in ('RL133', 'RL134'))reallocatetofdaforverification;

select Count(*) as Recieved_FROM_DEO_WITH_CORRECTION into Recieved_FROM_DEO_WITH_CORRECTION  from(

SELECT distinct * FROM kaveri.vw_fetch_rule_17_sro_dashboard where SROCODE= _srocode and currentstatus in ('RL136','RL145'))recievedfromdeowithcorrection;

select Count(*) as Recieved_FROM_FDA_FOR_APPROVAL into Recieved_FROM_FDA_FOR_APPROVAL  from(

SELECT distinct * FROM kaveri.vw_fetch_rule_17_sro_dashboard where SROCODE= _srocode and currentstatus ='RL135')recievedfromfdaforapproval;

select Count(*) as Recieved_FROM_DEO_FOR_SCAN into Recieved_FROM_DEO_FOR_SCAN  from(

SELECT distinct * FROM kaveri.vw_fetch_rule_17_sro_dashboard where SROCODE= _srocode and currentstatus ='RL138')recievedfromdeoforscan;

select Count(*) as Ready_FOR_DIGI_SIGN  into Ready_FOR_DIGI_SIGN from(

select distinct * from kaveri.vw_fetch_rule_17_sro_dashboard where srocode= _srocode and currentstatus='RL139')readyfordigisign;

return query 

select Allocate_DEO_DE, Reallocate_TO_DEO, Recieved_FROM_DEO_FOR_VERIFICATION,Reallocate_TO_FDA_FOR_VERIFICATION,Recieved_FROM_DEO_WITH_CORRECTION,Recieved_FROM_FDA_FOR_APPROVAL,Recieved_FROM_DEO_FOR_SCAN,Ready_FOR_DIGI_SIGN;

end;

$$;


ALTER FUNCTION kaveri.fn_fetch_rule17_sro_wrkflowcount(_srocode bigint) OWNER TO postgres;

--
-- Name: fn_fetch_sakalaapplicationdetails(character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_sakalaapplicationdetails(_applicationnumber character varying) RETURNS TABLE(applnumber character varying, applicationtype integer, srocode integer)
    LANGUAGE plpgsql
    AS $$
Declare
v_applicationtype int;
v_cnt integer;
begin


	select count(1)  into v_cnt from kaveri.applicantapplicationdetails 
		where applicationnumber=_applicationnumber;

	if v_cnt=0 then

			return query select null::character varying,null::integer,null::integer;
	else
  
		select applicationtypeid into v_applicationtype 
		from kaveri.applicantapplicationdetails 
		where applicationnumber=_applicationnumber;


		
			-- online EC
			if v_applicationtype =13 then
			return query
			select distinct aad.applicationnumber::character varying as appno1 ,
			aad.applicationtypeid::integer as aplicationtype1,
				ea.kaverisrocode::integer as srocode1 
			from kaveri.applicantapplicationdetails aad 
			join kaveri.ec_applicationdetails ea on aad.applicationnumber=ea.applicationnumber
			where aad.applicationnumber=_applicationnumber;

			-- online CC
			elseif v_applicationtype =12 then
			return query
			select distinct aad.applicationnumber::character varying as appno1 ,
			aad.applicationtypeid::integer as aplicationtype1,
				ea.kaverisrocode::integer as srocode1 
			from kaveri.applicantapplicationdetails aad 
			join kaveri.cc_applicationdetails ea on aad.applicationnumber=ea.applicationnumber
			where aad.applicationnumber=_applicationnumber;
						
			else 

			return query
			select distinct aad.applicationnumber::character varying as appno1,
			aad.applicationtypeid::integer as aplicationtype1,
				aad.srocode::integer  as srocode1
			from kaveri.applicantapplicationdetails aad 
			where aad.applicationnumber=_applicationnumber;

				
						
	end if;
		

end if;
end;
$$;


ALTER FUNCTION kaveri.fn_fetch_sakalaapplicationdetails(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_section68_property_details(integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_section68_property_details(_documentid integer) RETURNS TABLE(propertyid bigint, srocode integer, documentid bigint, documentnumber integer, bookid integer, ismovable boolean, financialyear text, propertydescription text, executiondate timestamp without time zone, stampruleid integer, natureofdocument character varying, claimant text, executant text, pagecount integer, deedattachpath text, finalregistrationnumber character varying)
    LANGUAGE plpgsql
    AS $$
--declare
--v_propertyd bigint[];
begin
	
	
	
--select * from kaveri.documentmaster d where applicationnumber='PRP-01062023-0616406'
 
RETURN QUERY
select distinct  a.propertyid , c.srocode,
    c.documentid,
    c.documentnumber,
    c.bookid,
vs.ismovable,
    ((to_char(c.executiondatetime, 'YYYY'::text)::bigint - 1) || '-'::text) || to_char(c.executiondatetime, 'YYYY'::text)::bigint AS financialyear,
CASE
            WHEN vs.footnotefordesc IS NOT NULL THEN (vs.propertydescription || '##'::text) || vs.footnotefordesc
            ELSE vs.propertydescription
        END AS propertydescription,
        c.executiondatetime AS executiondate,
    a.stampruleid,
    d.descriptione AS natureofdocument,
    ( select string_agg(claimantname,', ') as claimantname from (
		SELECT
		array_to_string(array_agg((COALESCE(p1.firstname, ''::character varying)::text || COALESCE(p1.middlename,
		''::character varying)::text) || COALESCE(p1.lastname, ''::character varying)::text), ', '::text)
		
AS claimantname
FROM kaveri.partyinfo p1
WHERE p1.applicationnumber::text = c.applicationnumber::text AND p1.partytypeid = 1
group by p1.partyid) as ss
	) AS claimant,
	(select string_agg(executantname,', ') as executantname  from(
	SELECT
	array_to_string(array_agg((COALESCE(p1.firstname, ''::character varying)::text || COALESCE(p1.middlename, ''::character varying)::text) || COALESCE(p1.lastname, ''::character varying)::text), ', '::text)
	AS executantname
           FROM kaveri.partyinfo p1
          WHERE p1.applicationnumber::text = c.applicationnumber::text AND p1.partytypeid = 2
	group by p1.partyid) AS ss) AS executant,
    a.sronoofscanpages AS pagecount,
    c.uploaddocdeedpath as deedattachpath,
    c.finalregistrationnumber
                FROM kaveri.propertymaster a
   left JOIN kaveri.propertynumberdetails b ON a.propertyid = b.propertyid
     JOIN kaveri.documentmaster c ON a.documentid = c.documentid --AND a.applicationnumber::text = c.applicationnumber::text
     JOIN kaveri.applicantapplicationdetails ap ON ap.applicationnumber = c.applicationnumber
     JOIN kaveri.stamprules d ON a.stampruleid = d.stampruleid
   left JOIN kaveri.propertyschedules f ON b.propertyid = f.propertyid
--      JOIN kaveri.vw_fetch_section68_property_return_string vs ON a.propertyid = vs.propertyid
    LEFT join (select v.propertyid,v.ismovable,v.footnotefordesc,v.propertydescription from kaveri.fn_fetch_section68_property_return_string(_documentid) v where v.propertyid in (select p.propertyid from kaveri.propertymaster p where p.documentid =_documentid))
      as vs on  a.propertyid = vs.propertyid
     where a.documentid = _documentid;
     END;
$$;


ALTER FUNCTION kaveri.fn_fetch_section68_property_details(_documentid integer) OWNER TO postgres;

