           FROM kaveri.partyinfo p1
          WHERE p1.applicationnumber::text = c.applicationnumber::text AND p1.partytypeid = 1) AS claimant,
    ( SELECT array_to_string(array_agg((COALESCE(p1.firstname, ''::character varying)::text || COALESCE(p1.middlename, ''::character varying)::text) || COALESCE(p1.lastname, ''::character varying)::text), ', '::text) AS executantname
           FROM kaveri.partyinfo p1
          WHERE p1.applicationnumber::text = c.applicationnumber::text AND p1.partytypeid = 2) AS executant,
    a.sronoofscanpages AS pagecount,
    ap.deedattachpath,
    c.finalregistrationnumber
                FROM kaveri.propertymaster a
   left JOIN kaveri.propertynumberdetails b ON a.propertyid = b.propertyid
     JOIN kaveri.documentmaster c ON a.documentid = c.documentid --AND a.applicationnumber::text = c.applicationnumber::text
     JOIN kaveri.applicantapplicationdetails ap ON ap.applicationnumber = c.applicationnumber
     JOIN kaveri.stamprules d ON a.stampruleid = d.stampruleid
   left JOIN kaveri.propertyschedules f ON b.propertyid = f.propertyid
--      JOIN kaveri.vw_fetch_section68_property_return_string vs ON a.propertyid = vs.propertyid
    LEFT join (select v.propertyid,v.footnotefordesc,v.propertydescription from kaveri.fn_fetch_section68_property_return_string(_documentid) v where v.propertyid in (select p.propertyid from kaveri.propertymaster p where p.documentid =_documentid))
      as vs on  a.propertyid = vs.propertyid
     where a.documentid = _documentid;
     END;
$$;


