--
-- Name: fn_fetch_section68_property_return_string(integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_section68_property_return_string(_documentid integer) RETURNS TABLE(propertyid bigint, propertydescription text, footnotefordesc text, ismovable boolean)
    LANGUAGE plpgsql
    AS $$
--declare
--v_propertyd bigint[];
begin
	return query
SELECT tab1.propertyid,
    tab1.col1 || tab2.col1 AS propertydescription,
    tab3.col1 AS footnotefordesc,
	case when tab3.bookid in (3.4) then
       false
    else
       tab1.ismovable
    end as ismovable
 
   FROM
(SELECT a.propertyid,
            ((((((((((((((((((('(Village)'::text || COALESCE(b.villagenamee, ''::character varying)::text) || ', '::text)
            || COALESCE(tab3_1.typenameenglish, ''::text)) || '. '::text)
            || COALESCE(tab3_1.currentnumber, ''::text)) || ', '::text)
            || COALESCE(c.hoblinamee, ''::character varying)::text) || ', '::text)
            || COALESCE(d.taluknamee, ''::character varying)::text) || ', '::text)
            || COALESCE(e.districtnamee, ''::character varying)::text) || ',(North)'::text)
            || COALESCE(a.northboundary, ''::character varying)::text) || ',(South)'::text)
            || COALESCE(a.southboundary, ''::character varying)::text) || ',(East)'::text)
            || COALESCE(a.eastboundary, ''::character varying)::text) || ',(West)'::text)
            || COALESCE(a.westboundary, ''::character varying)::text) || ', '::text AS col1,
			case when tab3_1.propertyid is not null then
				true
			else
				false
			end as ismovable
           FROM kaveri.propertymaster a
             JOIN kaveri.villagemaster b ON a.villagecode = b.villagecode
             JOIN kaveri.hoblimaster c ON b.hoblicode = c.hoblicode
             JOIN kaveri.talukmaster d ON c.talukcode = d.talukcode
             JOIN kaveri.districtmaster e ON d.districtcode = e.districtcode
             left JOIN ( SELECT g.propertyid,
                    array_to_string(array_agg(h.typenameenglish), ','::text) AS typenameenglish,
                    array_to_string(array_agg(g.currentnumber), ','::text) AS currentnumber
                   FROM kaveri.propertynotypemaster h
                     JOIN kaveri.propertynumberdetails g ON h.propertytypeid = g.currentpropertytypeid
                     where g.propertyid in (select p.propertyid from kaveri.propertymaster p where documentid=_documentid)
                  GROUP BY g.propertyid) tab3_1 ON a.propertyid = tab3_1.propertyid
             where (a.propertyid,a.documentid) in (select p.propertyid,p.documentid from kaveri.propertymaster p where documentid=_documentid))tab1,
             ( SELECT f.propertyid,
            'Private Property Note :'::text || array_to_string(array_agg((('(Schedule '::text || COALESCE(f.scheduletype, ''::character varying)::text) || ') '::text) || COALESCE(f.description, ''::character varying)::text), ','::text) AS col1
           FROM kaveri.propertyschedules f
           where f.propertyid in (select p.propertyid from kaveri.propertymaster p where documentid=_documentid)
          GROUP BY f.propertyid)tab2,
           (WITH cte AS (
    SELECT pm.propertyid,dm.bookid,
           ROW_NUMBER() OVER(PARTITION BY pm.propertyid
                                 ORDER BY o.insertdatetime DESC) AS rank,      
       (((('as per the order number '::text || o.ordernumber::text) || ' dated '::text) || to_char(o.orderdate, 'dd-mm-yyyy'::text)) || ' by District Registrar '::text) || d.districtnamee::text AS col1
           FROM kaveri.propertymaster pm
             LEFT JOIN kaveri.documentmaster dm ON pm.documentid = dm.documentid
             LEFT JOIN kaveri.dec_drordermaster o ON dm.documentid = o.documentid-- and o.statuscode = 4
             LEFT JOIN kaveri.districtmaster d ON o.districtcode = d.districtcode
             where pm.propertyid in (select p.propertyid from kaveri.propertymaster p where documentid=_documentid))
select * from cte where rank=1  ) tab3
               WHERE tab1.propertyid = tab2.propertyid AND tab3.propertyid = tab1.propertyid;
    END;
$$;


ALTER FUNCTION kaveri.fn_fetch_section68_property_return_string(_documentid integer) OWNER TO postgres;

--
-- Name: fn_fetch_section68_property_return_string_1(integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_section68_property_return_string_1(_documentid integer) RETURNS TABLE(propertyid bigint, propertydescription text, footnotefordesc text)
    LANGUAGE plpgsql
    AS $$
--declare 
--v_propertyd bigint[];
begin
	return query
 SELECT tab1.propertyid,
    tab1.col1 || tab2.col1 AS propertydescription,
    tab3.col1 AS footnotefordesc
   FROM 
 (SELECT a.propertyid,
            ((((((((((((((((((('(Village)'::text || COALESCE(b.villagenamee, ''::character varying)::text) || ', '::text) 
            || COALESCE(tab3_1.typenameenglish, ''::text)) || '. '::text)
            || COALESCE(tab3_1.currentnumber, ''::text)) || ', '::text)
            || COALESCE(c.hoblinamee, ''::character varying)::text) || ', '::text) 
            || COALESCE(d.taluknamee, ''::character varying)::text) || ', '::text)
            || COALESCE(e.districtnamee, ''::character varying)::text) || ',(North)'::text) 
            || COALESCE(a.northboundary, ''::character varying)::text) || ',(South)'::text) 
            || COALESCE(a.southboundary, ''::character varying)::text) || ',(East)'::text)
            || COALESCE(a.eastboundary, ''::character varying)::text) || ',(West)'::text) 
            || COALESCE(a.westboundary, ''::character varying)::text) || ', '::text AS col1
           FROM kaveri.propertymaster a
             JOIN kaveri.villagemaster b ON a.villagecode = b.villagecode
             JOIN kaveri.hoblimaster c ON b.hoblicode = c.hoblicode
             JOIN kaveri.talukmaster d ON c.talukcode = d.talukcode
             JOIN kaveri.districtmaster e ON d.districtcode = e.districtcode
             JOIN ( SELECT g.propertyid,
                    array_to_string(array_agg(h.typenameenglish), ','::text) AS typenameenglish,
                    array_to_string(array_agg(g.currentnumber), ','::text) AS currentnumber
                   FROM kaveri.propertynotypemaster h
                     JOIN kaveri.propertynumberdetails g ON h.propertytypeid = g.currentpropertytypeid
                     where g.propertyid in (select p.propertyid from kaveri.propertymaster p where documentid=_documentid)
                  GROUP BY g.propertyid) tab3_1 ON a.propertyid = tab3_1.propertyid
             where a.propertyid in (select p.propertyid from kaveri.propertymaster p where documentid=_documentid))tab1,
             ( SELECT f.propertyid,
            'Private Property Note :'::text || array_to_string(array_agg((('(Schedule '::text || COALESCE(f.scheduletype, ''::character varying)::text) || ') '::text) || COALESCE(f.description, ''::character varying)::text), ','::text) AS col1
           FROM kaveri.propertyschedules f
           where f.propertyid in (select p.propertyid from kaveri.propertymaster p where documentid=_documentid)
          GROUP BY f.propertyid)tab2,
           ( 
           select * from (
           SELECT row_number() over(partition by pm.propertyid order by o.orderdate desc) as rn,pm.propertyid,
            (((('as per the order number '::text || o.ordernumber::text) || ' dated '::text) || to_char(o.orderdate, 'dd-mm-yyyy'::text)) || ' by District Registrar '::text) || d.districtnamee::text AS col1
           FROM kaveri.propertymaster pm
             LEFT JOIN kaveri.documentmaster dm ON pm.documentid = dm.documentid
             LEFT JOIN kaveri.dec_drordermaster o ON dm.documentid = o.documentid
             LEFT JOIN kaveri.districtmaster d ON o.districtcode = d.districtcode
             where pm.propertyid in (select p.propertyid from kaveri.propertymaster p where documentid=_documentid)
             )as ss where rn=1) tab3
               WHERE tab1.propertyid = tab2.propertyid AND tab3.propertyid = tab1.propertyid;
    END;
$$;


ALTER FUNCTION kaveri.fn_fetch_section68_property_return_string_1(_documentid integer) OWNER TO postgres;

