           FROM kaveri.propertymaster a
             JOIN kaveri.villagemaster b ON a.villagecode = b.villagecode
             JOIN kaveri.hoblimaster c ON b.hoblicode = c.hoblicode
             JOIN kaveri.talukmaster d ON c.talukcode = d.talukcode
             JOIN kaveri.districtmaster e ON d.districtcode = e.districtcode
             left JOIN ( SELECT g.propertyid,
                    array_to_string(array_agg(h.typenameenglish), ','::text) AS typenameenglish,
                    array_to_string(array_agg(g.currentnumber), ','::text) AS currentnumber
                   FROM kaveri.propertynotypemaster h
                     JOIN kaveri.propertynumberdetails g ON h.propertytypeid = g.currentpropertytypeid
                     where g.propertyid in (select p.propertyid from kaveri.propertymaster p where documentid=_documentid)
                  GROUP BY g.propertyid) tab3_1 ON a.propertyid = tab3_1.propertyid
             where (a.propertyid,a.documentid) in (select p.propertyid,p.documentid from kaveri.propertymaster p where documentid=_documentid))tab1,
             ( SELECT f.propertyid,
            'Private Property Note :'::text || array_to_string(array_agg((('(Schedule '::text || COALESCE(f.scheduletype, ''::character varying)::text) || ') '::text) || COALESCE(f.description, ''::character varying)::text), ','::text) AS col1
           FROM kaveri.propertyschedules f
           where f.propertyid in (select p.propertyid from kaveri.propertymaster p where documentid=_documentid)
          GROUP BY f.propertyid)tab2,
           (SELECT pm.propertyid,dm.bookid,
            (((('as per the order number '::text || o.ordernumber::text) || ' dated '::text) || to_char(o.orderdate, 'dd-mm-yyyy'::text)) || ' by District Registrar '::text) || d.districtnamee::text AS col1
           FROM kaveri.propertymaster pm
             LEFT JOIN kaveri.documentmaster dm ON pm.documentid = dm.documentid
             LEFT JOIN kaveri.dec_drordermaster o ON dm.documentid = o.documentid and o.statuscode = 4
             LEFT JOIN kaveri.districtmaster d ON o.districtcode = d.districtcode
             where pm.propertyid in (select p.propertyid from kaveri.propertymaster p where documentid=_documentid) order by o.insertdatetime desc limit 1) tab3
               WHERE tab1.propertyid = tab2.propertyid AND tab3.propertyid = tab1.propertyid;
    END;
$$;


