--

CREATE FUNCTION kaveri.fn_fetch_signed_document(_applicationnumber character varying, _searchby character varying) RETURNS TABLE(filepath character varying, filetype character varying)
    LANGUAGE plpgsql
    AS $$
begin
	return query
	select p.filepath,p.filetype 
	from kaveri.documentmaster d
	join kaveri.partysigneddocuments p on d.documentid = p.documentid
	WHERE (_searchby = 'applicationnumber' AND d.applicationnumber = _applicationnumber)
	OR (_searchby = 'documentnumber'  AND d.finalregistrationnumber = _applicationnumber);
end;
$$;


