CREATE FUNCTION kaveri.fn_fetch_slotconfiguration(_srocode integer) RETURNS TABLE(srocode integer, shiftstarttime time without time zone, shiftendtime time without time zone, timetakenforbiometric integer, timetakenfor1pgscan integer, timetakenforsignature integer, timetakenforsrverification integer, timetakenbydeo integer, timetakenfordigisigning integer, timetakenforacknowledgement integer, scrutinywindowstarttime time without time zone, scrutinywindowendtime time without time zone, vipwindowstarttime time without time zone, vipwindowendtime time without time zone, vipapplicationallowedmax integer, vipprocessedapplcount integer)
    LANGUAGE plpgsql
    AS $$

declare
v_remark int;

begin

select count(remark) into v_remark from kaveri.eligibleappointmentdatedetails s where s.srocode = _srocode and inserteddatetime::date =current_date; 
	
   RETURN QUERY
   
select 
	a.srocode,
	a.shiftstarttime,
	a.shiftendtime,
	a.timetakenforbiometric,
	a.timetakenfor1pgscan,
	a.timetakenforsignature,
	a.timetakenforsrverification,
	a.timetakenbydeo,
	a.timetakenfordigisigning,
	a.timetakenforacknowledgement,
	a.scrutinywindowstarttime,
	a.scrutinywindowendtime,
	a.vipwindowstarttime,
	a.vipwindowendtime,
	a.vipapplicationallowedmax,
	v_remark as vipprocessedapplcount
	from kaveri.slotconfigurationmaster a 
where a.srocode=_srocode;

END;
$$;


