--
-- Name: fn_fetch_sro_cnt(bigint, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_sro_cnt(_srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS TABLE(applicationtypeid integer, applicationtypename character varying, cnt_totalapplication bigint, srocode integer, bookid integer, bookname character varying)
    LANGUAGE plpgsql
    AS $$
begin
return query
select ss.applicationtypeid,ss.applicationtypename,count(ss.applicationnumber) cnt_totalapplication
,ss.srocode,ss.bookid,ss.bookname from (
SELECT ad.applicationtypeid,
    sm.servicename AS applicationtypename,
   ad.applicationnumber,
    ad.srocode,
    ad.bookid,
    bm.booknameenglish AS bookname,
    ad.applicationenddate
   FROM kaveri.applicantapplicationdetails ad
     JOIN kaveri.servicesmaster sm ON sm.serviceid = ad.applicationtypeid
     JOIN kaveri.booktypemaster bm ON ad.bookid = bm.bookid
  where ad.srocode=_srocode and ad.currentstatus::text = 'CD120'::text 
  and ad.applicationenddate::date>=_fromdate and ad.applicationenddate::date<=_todate
 ) as ss
 group by ss.applicationtypeid,ss.applicationtypename,ss.srocode,ss.bookid,ss.bookname
UNION all
select ss.applicationtypeid,ss.applicationtypename,count(ss.applicationnumber) cnt_totalapplication
,ss.srocode,ss.bookid,ss.bookname from (
 SELECT ad.applicationtypeid,
    sm.servicename AS applicationtypename,
    ad.applicationnumber,
    ea.kaverisrocode AS srocode,
    ea.booktype AS bookid,
    NULL::character varying(150) AS bookname,
    ad.applicationenddate
   FROM kaveri.applicantapplicationdetails ad
     JOIN kaveri.cc_applicationdetails ea ON ad.applicationnumber::text = ea.applicationnumber::text
     JOIN kaveri.servicesmaster sm ON sm.serviceid = ad.applicationtypeid
  where ea.kaverisrocode=_srocode and  ad.currentstatus::text = 'CC109'::text
  and ad.applicationenddate::date>=_fromdate and ad.applicationenddate::date<=_todate
) as ss
 group by ss.applicationtypeid,ss.applicationtypename,ss.srocode,ss.bookid,ss.bookname
 UNION ALL
select ss.applicationtypeid,ss.applicationtypename,count(ss.applicationnumber) cnt_totalapplication
,ss.srocode,ss.bookid,ss.bookname from (
SELECT ad.applicationtypeid,
    sm.servicename AS applicationtypename,
    ad.applicationnumber,
    ea.kaverisrocode AS srocode,
    ad.bookid,
    NULL::character varying(150) AS bookname,
    ad.applicationenddate
   FROM kaveri.applicantapplicationdetails ad
     JOIN kaveri.ec_applicationdetails ea ON ad.applicationnumber::text = ea.applicationnumber::text
     JOIN kaveri.servicesmaster sm ON sm.serviceid = ad.applicationtypeid
  WHERE ad.srocode=_srocode and ad.currentstatus::text = 'CE110'::text 
  and ad.applicationenddate::date>=_fromdate and ad.applicationenddate::date<=_todate
  ) as ss
 group by ss.applicationtypeid,ss.applicationtypename,ss.srocode,ss.bookid,ss.bookname;

end;
$$;


