     JOIN kaveri.servicesmaster sm ON sm.serviceid = ad.applicationtypeid
     JOIN kaveri.booktypemaster bm ON ad.bookid = bm.bookid
  where ad.srocode=_srocode and  ad.currentstatus::text = 'CD120'::text and ad.applicationenddate>=_fromdate and ad.applicationenddate<=_todate
  union all
   SELECT ad.applicationtypeid,
    sm.servicename AS applicationtypename,
