    ea.booktype AS bookid,
    NULL::character varying(150) AS bookname,
    ad.applicationenddate
   FROM kaveri.applicantapplicationdetails ad
     JOIN kaveri.cc_applicationdetails ea ON ad.applicationnumber::text = ea.applicationnumber::text
     JOIN kaveri.servicesmaster sm ON sm.serviceid = ad.applicationtypeid
  where ea.kaverisrocode=_srocode and  ad.currentstatus::text = 'CC109'::text and ad.applicationenddate>=_fromdate and ad.applicationenddate<=_todate
