ALTER FUNCTION kaveri.fn_fetch_sro_graphcnt_1(_srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_fetch_sro_graphcnt_2(bigint, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_sro_graphcnt_2(_srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS TABLE(applicationtypeid integer, applicationtypename character varying, cnt_totalapplication bigint, srocode integer, bookid integer, bookname character varying, fromdate date, todate date)
    LANGUAGE plpgsql
    AS $$
declare 
v_address text;
BEGIN		
return query
 WITH cte AS (
         SELECT ad.applicationtypeid,
            sm.servicename AS applicationtypename,
            ad.applicationnumber,
                CASE
                    WHEN ad.applicationtypeid = 13 THEN ea.kaverisrocode::integer
                    WHEN ad.applicationtypeid = 12 THEN ca.kaverisrocode
                    ELSE ad.srocode
                END AS srocode,
                CASE
                    WHEN ad.applicationtypeid = 1 AND ad.bookid IS NOT NULL THEN ad.bookid
                    WHEN ad.applicationtypeid = 12 THEN ca.booktype::integer
                    WHEN ad.applicationtypeid = 13 THEN NULL::integer
                    ELSE NULL::integer
                END AS bookid,
            bm.booknameenglish AS bookname,
            ad.applicationenddate
           FROM kaveri.applicantapplicationdetails ad
             LEFT JOIN kaveri.cc_applicationdetails ca ON ad.applicationnumber::text = ca.applicationnumber::text
             LEFT JOIN kaveri.ec_applicationdetails ea ON ad.applicationnumber::text = ea.applicationnumber::text
             JOIN kaveri.servicesmaster sm ON sm.serviceid = ad.applicationtypeid
             LEFT JOIN kaveri.booktypemaster bm ON ad.bookid = bm.bookid
          where (ad.srocode=_srocode or ca.kaverisrocode=_srocode or ea.kaverisrocode=_srocode)
	 and ad.currentstatus::text = ANY (ARRAY['CD120'::text, 'CC109'::text, 'CE110'::text]) and applicationenddate between _fromdate and _todate
        )
--return query
select sp.applicationtypeid,sp.applicationtypename,count(sp.applicationnumber) cnt_totalapplication,sp.srocode
,sp.bookid,sp.bookname,_fromdate::Date as fromdate,_todate::Date as todate
 from (
 SELECT ss.applicationtypeid,
    ss.applicationtypename,
    ss.applicationnumber,
    ss.srocode,
    ss.bookid,
    ss.bookname,
    ss.applicationenddate
   FROM cte ss
  WHERE ss.bookid =
        CASE
            WHEN ss.applicationtypeid = 1 OR ss.bookid IS NOT NULL OR ss.applicationtypeid = 12 AND ss.bookname IS NULL THEN ss.bookid
            ELSE NULL::integer
        END
UNION
 SELECT ss.applicationtypeid,
    ss.applicationtypename,
    ss.applicationnumber,
    ss.srocode,
    ss.bookid,
    ss.bookname,
    ss.applicationenddate
   FROM cte ss
  WHERE ss.applicationtypeid = 13) as sp 
 group by sp.applicationtypeid,sp.applicationtypename,sp.srocode,sp.bookid,sp.bookname;
  
 end;
$$;


ALTER FUNCTION kaveri.fn_fetch_sro_graphcnt_2(_srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_fetch_srostepcount(bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_srostepcount(_srocode bigint) RETURNS TABLE(step1_cnt bigint, step2_cnt bigint, step3_cnt bigint, step3a_cnt bigint, step4_cnt bigint, step5_cnt bigint, step6_cnt bigint, step7_cnt bigint, step8_cnt bigint, step9_cnt bigint, step10_cnt bigint)
    LANGUAGE plpgsql
    AS $$

begin 
return query
select 
count(a.applicationnumber) filter (where a.currentstatus='CD102') as step1_cnt,
count(a.applicationnumber) filter (where a.currentstatus='CD103') as step2_cnt,
count(a.applicationnumber) filter (where a.currentstatus='CD104') as step3_cnt,
count(a.applicationnumber) filter (where a.currentstatus in ('CD141','CD142')) as step3A_cnt,
count(a.applicationnumber) filter (where a.currentstatus='CD106') as step4_cnt,
count(am.applicationnumber) filter (where a.currentstatus='CD108') as step5_cnt,
count(am.applicationnumber) filter (where a.currentstatus='CD110') as step6_cnt,
count(a.applicationnumber) filter (where a.currentstatus='CD111') as step7_cnt,
count(a.applicationnumber) filter (where a.currentstatus='CD112' and a.deoid is not null ) as step8_cnt,
count(a.applicationnumber) filter (where a.currentstatus='CD115' and a.deoid is not null) as step9_cnt,
count(a.applicationnumber) filter (where a.currentstatus='CD116' and a.deoid is not null) as step10_cnt
from kaveri.applicantapplicationdetails a
left join kaveri.appointmentmaster am on a.applicationnumber=am.applicationnumber  and am.status='1'
where a.srocode=_srocode and a.isdeleted=false;

end;
$$;


ALTER FUNCTION kaveri.fn_fetch_srostepcount(_srocode bigint) OWNER TO postgres;

--
-- Name: fn_fetch_transaction_count(timestamp without time zone, timestamp without time zone, bigint); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_transaction_count(_fromdt timestamp without time zone, _todt timestamp without time zone, _userid bigint) RETURNS TABLE(documentregcount bigint, marriageregcount bigint, ecregcount bigint, ccregcount bigint)
    LANGUAGE plpgsql
    AS $$
declare
DocumentregCount bigint;
marriageregcount bigint;
ecregcount bigint;
ccregcount bigint;
v_srocode bigint;
v_districtcode bigint;
v_array bigint[];
begin
	select  d.srocode,d2.districtcode into v_srocode,v_districtcode  from kaveri.departmentusers d 
		join kaveri.sromaster s on d.srocode =s.srocode 
		join kaveri.districtmaster d2 on d2.districtcode = s.districtcode where  d.userid=_userid ;
	
-- FETCH DOC COUNT---	
	
	select count(*) into DocumentregCount from kaveri.documentmaster d 
			join kaveri.sromaster s on d.srocode = s.srocode 
		join kaveri.districtmaster d2 on s.districtcode = d2.districtcode 
		where d.isregistrationcompleted =true and d.registrationdatetime  >= _fromDT and d.registrationdatetime  <= _TODT 
		and d.srocode in (v_srocode)   and d2.districtcode in (v_districtcode);

	-- Marriage Reg
	
	select count(*)  as MarriageRegCount into marriageregcount 
	from  kaveri.marriageregistration m
	join kaveri.sromaster s on s.srocode = m.srocode 
	join kaveri.districtmaster d2  on s.districtcode = d2.districtcode 
	where m.dateofregistration >=_fromDT and m.dateofregistration<= _TODT and m.srocode in (v_srocode) and d2.districtcode in(v_districtcode);

--- EC REG

	select count(*)  as ECRegCount into ecregcount  from kaveri.applicantapplicationdetails a
	join kaveri.sromaster s on s.srocode = a.srocode 
	join kaveri.districtmaster d on d.districtcode = s.districtcode 
	where a.applicationtypeid=13 and a.currentstatus = 'CD120' and a.applicationstartdate <=_fromDT and a.applicationenddate  <=_TODT 
	and a.srocode in (v_srocode) and d.districtcode in (v_districtcode) ; -- sro EC

----CC REG
	
	select count(*)  as CCRegCount into ccregcount  from kaveri.applicantapplicationdetails a
	join kaveri.sromaster s on s.srocode = a.srocode 
	join kaveri.districtmaster d on d.districtcode = s.districtcode 
	where a.applicationtypeid=12 and a.currentstatus = 'CD120' and a.applicationstartdate <=_fromDT and a.applicationenddate  <=_TODT
	and a.srocode in (v_srocode) and d.districtcode in (v_districtcode) ; --ApplicantApplicatonDetails
	
	return query
	select DocumentregCount,marriageregcount,ecregcount,ccregcount;

end;
$$;


ALTER FUNCTION kaveri.fn_fetch_transaction_count(_fromdt timestamp without time zone, _todt timestamp without time zone, _userid bigint) OWNER TO csgadmin;

--
-- Name: fn_fetch_transaction_count(timestamp without time zone, timestamp without time zone, bigint, bigint); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
