    LANGUAGE plpgsql
    AS $$
declare
DocumentregCount bigint;
marriageregcount bigint;
ecregcount bigint;
ccregcount bigint;
v_srocode bigint;
v_districtcode bigint;
v_array bigint[];
begin
	select  d.srocode,d2.districtcode into v_srocode,v_districtcode  from kaveri.departmentusers d 
		join kaveri.sromaster s on d.srocode =s.srocode 
		join kaveri.districtmaster d2 on d2.districtcode = s.districtcode where d.designationid=_desigid and d.userid=_userid ;
	
-- FETCH DOC COUNT---	
	
	select count(*) into DocumentregCount from kaveri.documentmaster d 
			join kaveri.sromaster s on d.srocode = s.srocode 
		join kaveri.districtmaster d2 on s.districtcode = d2.districtcode 
		where d.isregistrationcompleted =true and d.registrationdatetime  >= _fromDT and d.registrationdatetime  <= _TODT 
		and d.srocode in (v_srocode)   and d2.districtcode in (v_districtcode);

	-- Marriage Reg
	
	select count(*)  as MarriageRegCount into marriageregcount 
	from  kaveri.marriageregistration m
	join kaveri.sromaster s on s.srocode = m.srocode 
	join kaveri.districtmaster d2  on s.districtcode = d2.districtcode 
	where m.dateofregistration >=_fromDT and m.dateofregistration<= _TODT and m.srocode in (v_srocode) and d2.districtcode in(v_districtcode);

--- EC REG

	select count(*)  as ECRegCount into ecregcount  from kaveri.applicantapplicationdetails a
	join kaveri.sromaster s on s.srocode = a.srocode 
	join kaveri.districtmaster d on d.districtcode = s.districtcode 
	where a.applicationtypeid=13 and a.currentstatus = 'CD120' and a.applicationstartdate <=_fromDT and a.applicationenddate  <=_TODT 
	and a.srocode in (v_srocode) and d.districtcode in (v_districtcode) ; -- sro EC

	select count(*)  as CCRegCount into ccregcount  from kaveri.applicantapplicationdetails a
	join kaveri.sromaster s on s.srocode = a.srocode 
	join kaveri.districtmaster d on d.districtcode = s.districtcode 
	where a.applicationtypeid=12 and a.currentstatus = 'CD120' and a.applicationstartdate <=_fromDT and a.applicationenddate  <=_TODT
	and a.srocode in (v_srocode) and d.districtcode in (v_districtcode) ; --ApplicantApplicatonDetails
	
	return query
	select DocumentregCount,marriageregcount,ecregcount,ccregcount;

end;
$$;


ALTER FUNCTION kaveri.fn_fetch_transaction_count(_fromdt timestamp without time zone, _todt timestamp without time zone, _userid bigint, _desigid bigint) OWNER TO csgadmin;

--
-- Name: fn_fetch_transaction_sakalapending_count(timestamp without time zone, timestamp without time zone, bigint); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_transaction_sakalapending_count(_fromdt timestamp without time zone, _todt timestamp without time zone, _userid bigint) RETURNS TABLE(documentregcount bigint, marriageregcount bigint, ecregcount bigint, ccregcount bigint)
    LANGUAGE plpgsql
    AS $$
declare
DocumentregCount bigint;
marriageregcount bigint;
ecregcount bigint;
ccregcount bigint;
v_srocode bigint;
v_districtcode bigint;
v_array bigint[];
v_desigid bigint;
begin

--- Fetching SRO CODE AND DR CODE---	
select d.srocode,d2.districtcode into v_srocode, v_districtcode from kaveri.departmentusers d 
join kaveri.sromaster s on d.srocode = s.srocode 
join kaveri.districtmaster d2 on s.districtcode  = d2.districtcode 
where d.srocode  not in (select srocode  from kaveri.sakala_partydetails sp)  and userid =_userid;

--- FETCHING COUNT OF DOCUMENT REGISTERED

select count(*) into DocumentregCount from kaveri.documentmaster d 
		join kaveri.sromaster s on d.srocode = s.srocode 
		join kaveri.districtmaster d2 on s.districtcode = d2.districtcode 
		where d.isregistrationcompleted =true and d.executiondatetime >= _fromDT and d.executiondatetime <= _TODT 
		and d.srocode in (v_srocode)  and isregistrationcompleted = true and d2.districtcode in (v_districtcode);


select count(*) as Marriageregcount into marriageregcount 
	from  kaveri.marriageregistration m
	join kaveri.sromaster s on s.srocode = m.srocode 
	join kaveri.districtmaster d2  on s.districtcode = d2.districtcode 
	where m.dateofregistration >=_fromDT and m.dateofregistration<= _TODT and m.srocode in (v_srocode) and d2.districtcode in(v_districtcode);

	select count(*)  as ECRegCount into ecregcount  from kaveri.applicantapplicationdetails a
	join kaveri.sromaster s on s.srocode = a.srocode 
	join kaveri.districtmaster d on d.districtcode = s.districtcode 
	where a.applicationtypeid=13 and a.currentstatus = 'CD120' and a.applicationstartdate <=_fromDT and a.applicationstartdate <=_TODT 
	and a.srocode in (v_srocode) and d.districtcode in (v_districtcode) ; -- sro EC

	select count(*)  as CCRegCount into ccregcount  from kaveri.applicantapplicationdetails a
	join kaveri.sromaster s on s.srocode = a.srocode 
	join kaveri.districtmaster d on d.districtcode = s.districtcode 
	where a.applicationtypeid=12 and a.currentstatus = 'CD120' and a.applicationstartdate <=_fromDT and a.applicationstartdate <=_TODT
	and a.srocode in (v_srocode) and d.districtcode in (v_districtcode) ; --ApplicantApplicatonDetails
	
	return query
	select DocumentregCount,marriageregcount,ecregcount,ccregcount;

end;
$$;


ALTER FUNCTION kaveri.fn_fetch_transaction_sakalapending_count(_fromdt timestamp without time zone, _todt timestamp without time zone, _userid bigint) OWNER TO csgadmin;

--
-- Name: fn_fetch_unaudited_assigned_applications_audit_scheduler(); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_unaudited_assigned_applications_audit_scheduler() RETURNS TABLE(applicationnumber character varying, regarticlecode bigint, auditor integer, dateofallocation timestamp without time zone, noofallocations integer, isaccepted boolean, isrejected boolean, isnochange boolean, sr_remarks character varying, isauditcompleted boolean, auditcompleteddatetime timestamp without time zone, audtr_rmrksfilepath character varying, stamparticlecode integer, stampruleid integer, auditorstampruleid integer, auditorstamparticlecode integer, auditorregarticlecode bigint, due_time timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
	begin
		return query 
select a.applicationnumber, a.regarticlecode , a.auditor , a.dateofallocation, a.noofallocations, a.isaccepted, a.isrejected, a.isnochange, a.sr_remarks, a.isauditcompleted, a.auditcompleteddatetime, a.audtr_rmrksfilepath, a.stamparticlecode , a.stampruleid , a.auditorstampruleid , a.auditorstamparticlecode , a.auditorregarticlecode ,  
(a.dateofallocation + interval '24 hours' ) as due_time
from kaveri.applicationforscrutiny a join kaveri.applicantapplicationdetails a2 on a2.applicationnumber::text = a.applicationnumber::text
where  current_timestamp - a.dateofallocation > INTERVAL '24 HOURS' and a.isauditcompleted is false;
	END;
$$;


