--
-- Name: fn_fetch_upd_prtydata_summary(bigint[]); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_upd_prtydata_summary(_partyid bigint[]) RETURNS TABLE(partyid bigint, linkpartyid bigint, photopath character varying, thumbpath character varying, fingerid integer, admissiondate timestamp without time zone, islateapperance boolean, iscitizennotappeared boolean, isbiometricrefused boolean, isendorseprinted boolean, nameasperaadhar character varying, errormessage character varying, aadharverified boolean, isduplicate boolean, duplicatepartyid bigint, aadharhash character varying, vault_id character varying)
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$

BEGIN

return query	
select p.partyid,p.linkpartyid, p.photopath, p.thumbpath, p.fingerid, p.admissiondate, p.islateapperance,
p.iscitizennotappeared, p.isbiometricrefused, p.isendorseprinted, aal.nameasperaadhar, aal.errormessage,
case when aal.partyid is not null 
			then
				case when aal.responsestatus = 'Y' then true 
				 	when aal.responsestatus = 'N' then false
			when aal.partyid is null then null end
		end as aadharverified,
p.isduplicate ,p.duplicatepartyid, aal.aadharhash,aal.vault_id
from kaveri.partyinfo p
left join (select * from (select aa.nameasperaadhar, aa.errormessage,aa.partyid,aa.responsestatus,aa.aadharhash,aa.vault_id,row_number() over (partition by aa.partyid order by aa.id desc) as rn  
from  kaveri.aadhar_authentication_log aa
where aa.partyid = any(_partyid)
) as ss where rn=1) aal on p.partyid =aal.partyid or p.duplicatepartyid =aal.partyid
where p.partyid = any(_partyid)
order by p.partyid desc;

end;
$$;


ALTER FUNCTION kaveri.fn_fetch_upd_prtydata_summary(_partyid bigint[]) OWNER TO postgres;

