--
-- Name: fn_fetch_upor_xml(bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_upor_xml(_docid bigint) RETURNS TABLE(rtcowners text, inputrtcowners text)
    LANGUAGE plpgsql
    AS $$
BEGIN
RETURN query
	select bxl.rtcowners,bxl.inputrtcowners from kaveri.documentmaster dm
	left join kaveri.propertymaster pm
		on pm.documentid = dm.documentid  
		and pm.applicationnumber ::text = dm.applicationnumber ::text
	left join kaveri.propertynumberdetails pnds
		on pnds.propertyid = pm.propertyid
		and pnds.currentpropertytypeid = 61
	left join kaveri.bhoomixmllog bxl
		on bxl.propertyid = pm.propertyid
	where dm.documentid = _docid;
END;
$$;


ALTER FUNCTION kaveri.fn_fetch_upor_xml(_docid bigint) OWNER TO postgres;

--
-- Name: fn_fetch_valuations_json_data(bigint, bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_valuations_json_data(_propertyid bigint, _propertytypeid bigint) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
BEGIN
		

select row_to_json(data_json) into v_data_json from ( 
select array_to_json(array_agg(row_to_json(app_json)))
	--select row_to_json(app_json) into v_data_json
from (select a.applicationnumber,a.propertyid,
  a.valid,a.srocode,i.sronamee,a.regsrocode,a.villagecode,
a.roadcode,a.valuationdate::date valuationdate,a.propertytypeid,a.totalarea,a.unitid,a.marketvalue,
a.leasetype,a.leaseamount,a.northboundary,a.southboundary,a.eastboundary,
a.westboundary, a.assessment,a.regarticlecode,a.verified,
a.issroapproved,
	   (
      select array_to_json(array_agg(row_to_json(agri)))
		   from (
	  	select ag.agriculturedetailsid,ag.agrilandtypeid,ag.unitid,ag.valuationid,
								ag.verified,ag.agrirateid,ag.rate,ag.srocode,ag.regsrocode
								from kaveri.val_agriculturedetails ag
			                    where a.valid = ag.valuationid)agri)as agriculture,
    (
      select array_to_json(array_agg(row_to_json(val)))
      from (SELECT distinct a.valid,a.applicationnumber,a.propertyid,
			b.flatrateid,b.rate,k.floorid
FROM 
kaveri.val_flatratedetails b,
kaveri.mas_val_flatrates k
where a.valid = b.valuationid 
and a.propertytypeid = b.propertytypeid 
and a.unitid = b.unitid
and b.flatrateid = k.flaterateid
		   ) val
    ) as flatratedetails,	
	    (
      select array_to_json(array_agg(row_to_json(val)))
      from (SELECT distinct a.valid,a.applicationnumber,a.propertyid,
b.openbuiltvalid,b.rate,b.openbuiltrateid 
FROM --kaveri.valuationdetails a,
kaveri.val_openbuiltvaluationdetails b,
kaveri.mas_val_openbuiltrates k
where a.valid = b.valuationid 
and a.propertytypeid = b.propertytypeid 
and a.unitid = b.unitid
and b.openbuiltrateid = k.openbuiltrateid
		   ) val
    ) as openbuiltvaluationdetails,	
	(
	select array_to_json(array_agg(row_to_json(crd)))
	 from (SELECT distinct a.valid,a.applicationnumber,a.propertyid,
		   s.constructiondetailsid,s.constructiontypeid,s.gfarea,s.agfarea,
		   s.rate,s.verified,s.valuationid,s.srocode,s.regsrocode
		   from kaveri.val_constructionratedetails s
		   where a.valid = s.valuationid
		   ) crd
	)  as constructionratedetails,
	  
	 (
      select array_to_json(array_agg(row_to_json(amn)))
      from (SELECT distinct a.valid,a.applicationnumber,a.propertyid,
c.amenetiesdetailsid,c.apartmentamenetyruleid,c.rate as rate1
FROM 
kaveri.val_apartmentamenitydetails c
where a.valid = c.valuationid 
		   ) amn
    ) as apartmentamenitydetails,
/* ============================================*/
	  
	  (
      select array_to_json(array_agg(row_to_json(amz)))
      from (SELECT distinct a.valid,a.applicationnumber,a.propertyid,d.useramenetiesdetailsid,
d.apartmentamenityid,d.isselected,d.verified
FROM --kaveri.valuationdetails a,
kaveri.val_userapartmentamenitydetails d
where a.valid = d.valuationid 
--and a.propertytypeid =12  and a.applicationnumber = 'PRP-15122021-01686'
		   ) amz
    ) as userapartmentamenitydetails,
	  
/*  ===========================================*/
	  
	(  select array_to_json(array_agg(row_to_json(anx)))
      from (SELECT distinct a.valid,a.applicationnumber,a.propertyid,
d.annexuredetailsid,d.annexureid,d.rate as rate2,d.isselected,d.area
FROM --kaveri.valuationdetails a,
kaveri.val_annexuredetails d
where a.valid = d.valuationid
--and a.propertytypeid =12  and a.applicationnumber = 'PRP-15122021-01686'
		   ) anx
	) as annexuredetails,
	( select array_to_json(array_agg(row_to_json(prk)))
      from (SELECT distinct a.valid,a.applicationnumber,a.propertyid,
e.parkingdetailsid,e.parkingtypeid,e.totalparkings,e.rate as rate3
FROM --kaveri.valuationdetails a,
kaveri.val_parkingratedetails e
where a.valid = e.valuationid
--and a.propertytypeid =12  and a.applicationnumber = 'PRP-15122021-01686'
		   )prk ) as parkingratedetails,
	( select array_to_json(array_agg(row_to_json(flr)))
      from (SELECT distinct a.valid,a.applicationnumber,a.propertyid,
f.flatfloordetailsid,f.apartmentfloorrateid,f.rate as rate4 
FROM --kaveri.valuationdetails a,
kaveri.val_flatfloordetails f
where a.valid = f.valuationid
--and a.propertytypeid =12  and a.applicationnumber = 'PRP-15122021-01686'
		   )flr ) as flatfloordetails
  FROM kaveri.valuationdetails a 
  	left join kaveri.sromaster i on (a.srocode = i.srocode)
	  where a.propertytypeid =_propertytypeid--12  
	  and a.propertyid = _propertyid--'PRP-15122021-01686'
)  app_json ) data_json;

return v_data_json;

END;
$$;


ALTER FUNCTION kaveri.fn_fetch_valuations_json_data(_propertyid bigint, _propertytypeid bigint) OWNER TO postgres;

