		   from (
	  	select ag.agriculturedetailsid,ag.agrilandtypeid,ag.unitid,ag.valuationid,
								ag.verified,ag.agrirateid,ag.rate,ag.srocode,ag.regsrocode
								from kaveri.val_agriculturedetails ag
			                    where a.valid = ag.valuationid)agri)as agriculture,
    (
      select array_to_json(array_agg(row_to_json(val)))
      from (SELECT distinct a.valid,a.applicationnumber,a.propertyid,
			b.flatrateid,b.rate,k.floorid
FROM 
kaveri.val_flatratedetails b,
kaveri.mas_val_flatrates k
where a.valid = b.valuationid 
and a.propertytypeid = b.propertytypeid 
and a.unitid = b.unitid
and b.flatrateid = k.flaterateid
		   ) val
    ) as flatratedetails,	
	    (
      select array_to_json(array_agg(row_to_json(val)))
      from (SELECT distinct a.valid,a.applicationnumber,a.propertyid,
b.openbuiltvalid,b.rate,b.openbuiltrateid 
FROM --kaveri.valuationdetails a,
kaveri.val_openbuiltvaluationdetails b,
kaveri.mas_val_openbuiltrates k
where a.valid = b.valuationid 
and a.propertytypeid = b.propertytypeid 
and a.unitid = b.unitid
and b.openbuiltrateid = k.openbuiltrateid
		   ) val
    ) as openbuiltvaluationdetails,	
	(
	select array_to_json(array_agg(row_to_json(crd)))
	 from (SELECT distinct a.valid,a.applicationnumber,a.propertyid,
		   s.constructiondetailsid,s.constructiontypeid,s.gfarea,s.agfarea,
		   s.rate,s.verified,s.valuationid,s.srocode,s.regsrocode
		   from kaveri.val_constructionratedetails s
		   where a.valid = s.valuationid
		   ) crd
	)  as constructionratedetails,
	  
	 (
      select array_to_json(array_agg(row_to_json(amn)))
      from (SELECT distinct a.valid,a.applicationnumber,a.propertyid,
c.amenetiesdetailsid,c.apartmentamenetyruleid,c.rate as rate1
FROM 
kaveri.val_apartmentamenitydetails c
where a.valid = c.valuationid 
		   ) amn
    ) as apartmentamenitydetails,
/* ============================================*/
	  
	  (
      select array_to_json(array_agg(row_to_json(amz)))
      from (SELECT distinct a.valid,a.applicationnumber,a.propertyid,d.useramenetiesdetailsid,
d.apartmentamenityid,d.isselected,d.verified
FROM --kaveri.valuationdetails a,
kaveri.val_userapartmentamenitydetails d
where a.valid = d.valuationid 
--and a.propertytypeid =12  and a.applicationnumber = 'PRP-15122021-01686'
		   ) amz
    ) as userapartmentamenitydetails,
	  
/*  ===========================================*/
	  
	(  select array_to_json(array_agg(row_to_json(anx)))
      from (SELECT distinct a.valid,a.applicationnumber,a.propertyid,
d.annexuredetailsid,d.annexureid,d.rate as rate2,d.isselected,d.area
FROM --kaveri.valuationdetails a,
kaveri.val_annexuredetails d
where a.valid = d.valuationid
--and a.propertytypeid =12  and a.applicationnumber = 'PRP-15122021-01686'
		   ) anx
	) as annexuredetails,
	( select array_to_json(array_agg(row_to_json(prk)))
      from (SELECT distinct a.valid,a.applicationnumber,a.propertyid,
e.parkingdetailsid,e.parkingtypeid,e.totalparkings,e.rate as rate3
FROM --kaveri.valuationdetails a,
kaveri.val_parkingratedetails e
where a.valid = e.valuationid
--and a.propertytypeid =12  and a.applicationnumber = 'PRP-15122021-01686'
		   )prk ) as parkingratedetails,
	( select array_to_json(array_agg(row_to_json(flr)))
      from (SELECT distinct a.valid,a.applicationnumber,a.propertyid,
f.flatfloordetailsid,f.apartmentfloorrateid,f.rate as rate4 
FROM --kaveri.valuationdetails a,
kaveri.val_flatfloordetails f
where a.valid = f.valuationid
--and a.propertytypeid =12  and a.applicationnumber = 'PRP-15122021-01686'
		   )flr ) as flatfloordetails
  FROM kaveri.valuationdetails a 
	  left join kaveri.sromaster i on (a.srocode = i.srocode) where 
	a.propertytypeid =_propertytypeid--12  
	  and a.applicationnumber = _applicationnumber--'PRP-15122021-01686'
)  app_json ) data_json;

return v_data_json;

END;
$$;


ALTER FUNCTION kaveri.fn_fetch_valuations_json_data(_applicationnumber text, _propertytypeid bigint) OWNER TO postgres;

--
-- Name: fn_fetch_village_deptid(bigint); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_fetch_village_deptid(_villagecode bigint) RETURNS TABLE(deptid integer, villagecode integer, departmentname character varying)
    LANGUAGE plpgsql
    AS $$
declare 

begin
	if(_villagecode in(select a.villagecode from kaveri.villageurbanmapping a)) then 
	return query
	select v.deptid,v.villagecode,i.departmentname from kaveri.villageurbanmapping v 
	join kaveri.integrationdepartment i on v.deptid=i.udeptid where v.villagecode = _villagecode and v.deptid in (2,46,10);
	else
	return query
	select distinct v.deptid, _villagecode::integer as villagecode ,i.departmentname from kaveri.villageurbanmapping v 
	join kaveri.integrationdepartment i on v.deptid=i.udeptid where v.deptid in (2,46);
end if;
--return query;
--select deptid,villagecode,departmentname;
end;
$$;


ALTER FUNCTION kaveri.fn_fetch_village_deptid(_villagecode bigint) OWNER TO csgadmin;

--
-- Name: fn_fetch_warddetails(integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_warddetails(_choice integer) RETURNS TABLE(wardid integer, wardnumber character varying, integrationenabled boolean)
    LANGUAGE plpgsql
    AS $$
--Declare
--v_ward int[];
begin
	
	if _choice = 1 then 
	


	return query
	select w.wardid, w.wardnumber, w.integrationenabled from kaveri.warddetails w 
	where w.wardid in (select distinct w.wardid from kaveri.villagewardmapping w 
	where w.integrationenabled = true )
	order by w.wardid;
	
	elsif _choice = 2 then 
	return query
	select w.wardid, w.wardnumber, w.integrationenabled from kaveri.warddetails w 
    order by w.wardid;
   else
	return query
	select a.wardid, a.wardnumber, a.integrationenabled from kaveri.warddetails a 
    where 
   a.integrationenabled = false 
    order by a.wardid;
	end if;

END;
$$;


ALTER FUNCTION kaveri.fn_fetch_warddetails(_choice integer) OWNER TO postgres;

--
-- Name: fn_fetch_wrkflowcount(bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_fetch_wrkflowcount(_srocode bigint) RETURNS TABLE(receivedfromcitizen bigint, allocatedtofda_sda bigint, receivedfromfda_sda_sda bigint, senttocitizenforconfirmations bigint, receivedfromcitizenafterconfirmation bigint, allocatedtodeo_sda bigint, from_audits bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
v_AllocatedtoFDA_SDA bigint;
v_ReceivedfromFDA_SDA_SDA bigint;
--v_array bigint[];
begin 

select Count(*) as ReceivedFromCitizen into ReceivedFromCitizen  from(
select  * from kaveri.vw_fetch_pending_sro_appnum where srocode= _srocode and currentstatus='CD102') receivedfromcit;
	
select Count(*) as AllocatedtoFDA_SDA  into AllocatedtoFDA_SDA from(
select  * from kaveri.vw_fetch_pending_sro_appnum where srocode= _srocode and currentstatus='CD103')wrkflw;


select Count(*) as ReceivedfromFDA_SDA_SDA into ReceivedfromFDA_SDA_SDA     from(
select  * from kaveri.vw_fetch_pending_sro_appnum where srocode= _srocode and currentstatus='CD104') sda ;

select Count(*) as SenttocitizenforConfirmations into SenttocitizenforConfirmations  from(
select  * from kaveri.vw_fetch_pending_sro_appnum where srocode= _srocode and currentstatus='CD106')SenttocitizenforConfirmation;

select Count(*) as Receivedfromcitizenafterconfirmation into Receivedfromcitizenafterconfirmation  from(
SELECT  * FROM kaveri.vw_fetch_pending_docreg where SROCODE= 173 and currentstatus in ('CD108','CD109'))Receivedfromcitizenafterconfirmatio;

select Count(*) as AllocatedtoDEo_SDA into AllocatedtoDEo_SDA  from(
SELECT  * FROM kaveri.vw_fetch_pending_docreg where SROCODE= 173 and currentstatus in ('CD110'))AllocatedtoDEo_SD;

select Count(*) as From_Audits into From_Audits     from(
select  * from kaveri.vw_fetch_pending_sro_appnum where srocode= _srocode and currentstatus in ('CD141','CD142')) From_Audits ;

return query 
select ReceivedFromCitizen,AllocatedtoFDA_SDA,ReceivedfromFDA_SDA_SDA,SenttocitizenforConfirmations,Receivedfromcitizenafterconfirmation,AllocatedtoDEo_SDA, From_Audits;



end;
$$;


ALTER FUNCTION kaveri.fn_fetch_wrkflowcount(_srocode bigint) OWNER TO postgres;

