-- Name: fn_generate_cc_certificatenumber(character varying, integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_generate_cc_certificatenumber(_applicationnumber character varying, _srocode integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE 
v_ecid bigint;
v_shortnamee text;
v_cnt integer;
_inserted_id text;
l_now text;
v_certificatenumber  character varying;
v_sessionid bigint;
v_totalamount numeric;
v_applicationid  bigint;
v_srocode integer;
v_certificateid bigint;
v_month integer;
v_length int;
begin

/* generation of certificate number */

--Get the EC ID for the given application number

--select ecid into v_ecid from kaveri.ec_applicationdetails 
--where applicationnumber=_applicationnumber;

--if v_ecid >=1 then 

 select certificatenumber into v_certificatenumber
 from kaveri.cc_applicationdetails 
where applicationnumber=_applicationnumber; 

if v_certificatenumber is not null then 

 return v_certificatenumber; 

else 

select shortnamee into v_shortnamee from kaveri.sromaster where srocode = _srocode;

--select lpad(nextval('kaveri.CC_applicationnumber_seq')::text,6,'0') into _inserted_id;
select length(last_value::varchar) into v_length from kaveri.CC_applicationnumber_seq;
if(v_length<6)
then
select lpad(nextval('kaveri.CC_applicationnumber_seq')::text,6,'0') into _inserted_id;
else
select nextval('kaveri.CC_applicationnumber_seq'::text) into _inserted_id;
end if;


SELECT EXTRACT(MONTH FROM now()) into v_month;

if v_month < 4 then
select cast(to_char(now(),'YYYY')as bigint)-1 ||'-'|| cast(to_char(now(),'YY')as bigint) into l_now;
else
select cast(to_char(now(),'YYYY')as bigint) ||'-'|| cast(to_char(now(),'YY')as bigint)+1 into l_now;
end if;

--v_certificatenumber := v_shortnamee  ||'-'||'A'||'-'||_inserted_id||'-'||l_now;

v_certificatenumber := v_shortnamee|| '-' || 'CC' ||'-'||'A'||'-'||_inserted_id||'-'||l_now;

 Update kaveri.cc_applicationdetails   
 set certificatenumber =  v_certificatenumber
where applicationnumber = _applicationnumber; 

return v_certificatenumber; 

end if ;

--select count(*) into v_cnt from kaveri.applicantapplicationdetails 
--where applicationnumber = _applicationnumber;

/*
if v_cnt >= 1 then
update kaveri.applicantapplicationdetails set srocode = _srocode,currentstatus=_currentstatus,sfdaid=_sfdaid where 
applicationnumber = _applicationnumber returning srocode into v_srocode;
end if;

insert into kaveri.eccertificatemaster(sessionid, searchdate, certificatenumber, 
applicationnumber,fromdate,todate,isnec,istransmitted) values 
(nextval('kaveri.sessionid_seq'),CURRENT_TIMESTAMP,v_certificatenumber,_applicationnumber,_fromdate,_todate,false,false)
returning sessionid into v_sessionid;

insert into kaveri.eccertificates
(
   certificateid,
    srocode,
    certificatenumber,
    applicationid,
    certificatedate,
    certificatetype
) values
(
 nextval('kaveri.certificateid_seq'),
    v_srocode,
    v_certificatenumber,
    nextval('kaveri.applicationid_seq'),
    CURRENT_TIMESTAMP,
    _certificatetype
) returning certificateid into v_certificateid;

select sum(payableamount) into v_totalamount from  kaveri.ec_requiredfees where ecid = v_ecid;

update kaveri.ec_applicationdetails set certificatenumber=v_certificatenumber,
pagecount=_pagecount,totalamount=v_totalamount where ecid = v_ecid returning ecid into v_ecid;

select applicationid into v_applicationid from kaveri.eccertificates where certificateid = v_certificateid and srocode = v_srocode;

insert into kaveri.eccertificatepdf
(
    fileid,
    applicationid,
    srocode,
    certificateid,
    certificatefile
)
values
(
nextval('kaveri.fileid_seq'),
v_applicationid,
v_srocode,
v_certificateid,
_certificatefile
) returning certificateid into v_certificateid;
return v_certificateid;

*/

end;
$$;


ALTER FUNCTION kaveri.fn_generate_cc_certificatenumber(_applicationnumber character varying, _srocode integer) OWNER TO csgadmin;

