--
-- Name: fn_get_applicationreview_details(character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_get_applicationreview_details(p_applicationnumber character varying) RETURNS TABLE(applicationnumber character varying, currentstatus character varying, srocode integer, reviewid integer, reviewname text, issroapprove boolean, sroremarks text, deptuserid bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
   RETURN QUERY
  select ad.applicationnumber,ad.currentstatus,ad.srocode
,ad.reviewid,ad.reviewname,ar.isverified,ar.remarks,ar.deptuserid 
from (select a.applicationnumber,a.currentstatus,a.srocode,arm.reviewid,arm.reviewname
from kaveri.applicantapplicationdetails a,
kaveri.applicationreviewmaster arm where a.applicationnumber= p_applicationnumber
     ) ad 
left join (select arr.applicationnumber,arr.reviewid,arr.isverified,arr.remarks,arr.deptuserid,arr.crtdate 
from kaveri.applicationreviewdetails arr 
where coalesce(arr.issroremarks,'false')='false' and arr.applicationnumber = p_applicationnumber and arr.crtdate = (select max(crtdate) from kaveri.applicationreviewdetails rd 
                    where rd.applicationnumber=arr.applicationnumber 
                     and rd.reviewid =arr.reviewid))ar
on (ar.applicationnumber = ad.applicationnumber 
                                                and ad.reviewid = ar.reviewid)
where ad.applicationnumber= p_applicationnumber ;
END;
$$;


ALTER FUNCTION kaveri.fn_get_applicationreview_details(p_applicationnumber character varying) OWNER TO csgadmin;

--
-- Name: fn_get_applicationreview_details_sro(character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_get_applicationreview_details_sro(p_applicationnumber character varying) RETURNS TABLE(applicationnumber character varying, currentstatus character varying, srocode integer, reviewid integer, reviewname text, issroapprove boolean, sroremarks text, deptuserid bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
   RETURN QUERY
  
  select ad.applicationnumber,ad.currentstatus,ad.srocode
,ad.reviewid,ad.reviewname,ar.isverified,ar.remarks,ar.deptuserid 
from 
	(select a.applicationnumber,a.currentstatus,a.srocode,arm.reviewid,arm.reviewname
		from kaveri.applicantapplicationdetails a,
		kaveri.applicationreviewmaster arm where a.applicationnumber= p_applicationnumber
	 ) ad 
left join 
		(select arr.applicationnumber,arr.reviewid,arr.isverified,arr.remarks,arr.deptuserid,arr.crtdate 
		from kaveri.applicationreviewdetails arr 
		where coalesce(arr.issroremarks,'true')='true' and 
      arr.applicationnumber = p_applicationnumber and 
	  arr.crtdate = (select max(crtdate) from kaveri.applicationreviewdetails rd 
					where rd.applicationnumber=arr.applicationnumber 
					 and rd.reviewid =arr.reviewid))ar
					 
on 
		(ar.applicationnumber = ad.applicationnumber 
		and ad.reviewid = ar.reviewid)
where 
		ad.applicationnumber= p_applicationnumber ;
END;
$$;


ALTER FUNCTION kaveri.fn_get_applicationreview_details_sro(p_applicationnumber character varying) OWNER TO csgadmin;

--
-- Name: fn_get_departmentpersons_byregioncode(integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_get_departmentpersons_byregioncode(_srocode integer) RETURNS TABLE(userid bigint, firstname text, displayname text, mobileno text, designationid integer)
    LANGUAGE plpgsql
    AS $$


DECLARE



BEGIN 

  return query
	select 
	du.userid,concat_ws(' '::text, du.firstname, du.lastname) AS FirstName,
	concat_ws(' '::text, du.firstname, du.lastname)||' - '||d2.designame AS displayName,
	du.mobileno::text  as MobileNumber, du.designationid 
	from 
	kaveri.departmentusers du 
	inner join kaveri.desigmaster d2 on du.designationid =d2.designationid 
	and du.designationid in (1,2,3)
	where
	srocode=_srocode
	and 
	du.serviceflag=true order by FirstName;

 

END;

$$;


ALTER FUNCTION kaveri.fn_get_departmentpersons_byregioncode(_srocode integer) OWNER TO postgres;

--
-- Name: fn_get_drc_property_detail(text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_get_drc_property_detail(reg_no text) RETURNS json
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN (
        SELECT json_build_object(
            'TxnNo', pm.assessment,
            'DrcNumber', pndls.currentnumber,
            'RegistrationNumber', dm.finalregistrationnumber,

            'PropertyDetails',
            (
                SELECT json_agg(
                    json_build_object(
                        'UnitsTransacted', pmd.totalarea,
                        'Uom', pmd.unitid,
                        'PropertyAddress', '',
                        'Boundaries',
                            (
                                SELECT json_build_object(
                                    'North',  pmm.northboundary,
                                    'South',  pmm.southboundary,
                                    'East',   pmm.eastboundary,
                                    'West',   pmm.westboundary
                                )
                                FROM kaveri.propertymaster pmm
                                WHERE pmm.propertyid = pm.propertyid
                                LIMIT 1                -- <= ensures single object
                            )
                    )
                )
                FROM kaveri.propertymaster pmd 
                WHERE pmd.propertyid = pm.propertyid
            ),

            'PartyDetails',
            (
                SELECT json_agg(
                    json_build_object(
                        'Name', p.firstname,
                        'middlename', p.middlename,
                        'lastname', p.lastname,
                        'PartyTypeId', p.partytypeid,
                        'RelativeName', p.relativename,
                        'Address', p.address,
                        'IsOrg', p.isorganization
                    )
                )
                FROM kaveri.partyinfo p 
                WHERE p.documentid = pm.documentid
            )
        ) AS document_json
        FROM kaveri.documentmaster dm
        LEFT JOIN kaveri.propertymaster pm 
               ON pm.documentid = dm.documentid 
              AND dm.applicationnumber::text = pm.applicationnumber::text
        LEFT JOIN kaveri.propertynumberdetails pndls 
               ON pndls.propertyid = pm.propertyid
        WHERE dm.finalregistrationnumber IS NOT NULL
          AND dm.registrationdatetime IS NOT NULL
          AND dm.finalregistrationnumber = reg_no
    );
END;
$$;


ALTER FUNCTION kaveri.fn_get_drc_property_detail(reg_no text) OWNER TO postgres;

--
-- Name: fn_get_drc_property_detailby_documentid(text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_get_drc_property_detailby_documentid(docid text) RETURNS json
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN (
        SELECT to_json(drc)
        FROM kaveri.documentmaster dm
        LEFT JOIN kaveri.propertymaster pm 
            ON pm.documentid = dm.documentid 
           AND dm.applicationnumber::text = pm.applicationnumber::text
        LEFT JOIN kaveri.propertynumberdetails pndls 
            ON pndls.propertyid = pm.propertyid 
           AND pndls.currentpropertytypeid = 69
        LEFT JOIN kaveri.khatadrcresptable drc 
            ON drc.khatareqid::text = pm.assessment::text
        WHERE dm.documentid = docid::bigint
        LIMIT 1
    );
END;
$$;


