--
-- Name: fn_get_login_details(text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_get_login_details(p_login_name text) RETURNS TABLE(userid bigint, loginname text, srocode integer, username text, designationid integer, designame character varying, mobile bigint, active boolean, sroname character varying, sronamek character varying, districtcode integer, districtname character varying, districtnamek character varying, passwrd text, rolesinfo json, ispaperless boolean)
    LANGUAGE plpgsql
    AS $$
BEGIN
   RETURN QUERY
 select du.userid, 
 du.loginname,
 case when du.designationid  in (5,10,11) then sr.districtcode else du.srocode end
  as srocode,
  du.firstname||' '||du.lastname as username,
  du.designationid,
  dm.designame::character varying ,
  du.mobileno as mobile,
  du.serviceflag as active,
  case when du.designationid in (5,10,11,17) then di.districtnamee else sr.sronamee end as sroname,
  case when du.designationid in (5,10,11) then di.districtnamek else sr.sronamek end as sronamek,
  sr.districtcode,
  di.districtnamee as districtname,di.districtnamek,du.passwd,
  (  select array_to_json(array_agg(row_to_json(roles)))
      from (select 0 as userroleId, du.designationid,du.userid as mappeduserid, dm.designame::character varying, 'Default' as rolename,
			case when du.designationid  in (5,10,11,17) then di.districtcode else du.srocode end as mappedsroid,
			case when du.designationid in (5,10,11,17) then di.districtnamee else sr.sronamee end as sroname,
			case when du.designationid in (5,10,11,17) then di.districtnamek else sr.sronamek end as sronamek
			union all
			select rl.userroleid as userroleId, rl.designationid,rl.mappeduserid as mappeduserid,
			dmrl.designame::character varying,dmrl.designame::character varying as rolename,
			ofm.kavericode as mappedsroid,
			ofm.officename  as sroname, 
			ofm.officenamer as sronamek
			from kaveri.departmentuserroles rl 
			left join kaveri.mas_officemaster ofm on (rl.mappedofficeid=ofm.officeid)
			inner join Kaveri.desigmaster dmrl on (rl.designationid = dmrl.designationid)
where du.userid = rl.userid ) roles
	) as rolesinfo,
(select v.ispaperless from kaveri.vw_fetch_paperless_trans v where v.srocode = du.srocode limit 1)
from Kaveri.departmentusers du
inner join Kaveri.desigmaster dm on (du.designationid = dm.designationid)
left join kaveri.sromaster sr on (sr.srocode=du.srocode)
left join kaveri.districtmaster di on (sr.districtcode=di.districtcode)
where du.serviceflag= 'true' and du.isactive is true and du.loginname= p_login_name;
END;
$$;


ALTER FUNCTION kaveri.fn_get_login_details(p_login_name text) OWNER TO postgres;

--
-- Name: fn_get_login_details(text, text); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_get_login_details(p_login_name text, p_pwd text) RETURNS TABLE(userid bigint, loginname text, srocode integer, username text, designationid integer, designame character varying, mobile bigint, active boolean, sroname character varying, sronamek character varying, districtcode integer, districtname character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
   RETURN QUERY
  select du.userid, du.loginname,case when du.designationid =5 then sr.districtcode else du.srocode end
  as srocode,du.firstname||' '||du.lastname as username,
  du.designationid,dm.designame::character varying ,du.mobileno as mobile,du.serviceflag as active,
  case when du.designationid =5 then di.districtnamee else sr.sronamee end as sroname,
  case when du.designationid =5 then di.districtnamek else sr.sronamek end as sronamek,sr.districtcode,di.districtnamee as districtname
from Kaveri.departmentusers du
inner join Kaveri.desigmaster dm on (du.designationid = dm.designationid)
left join kaveri.sromaster sr on (sr.srocode=du.srocode)
left join kaveri.districtmaster di on (sr.districtcode=di.districtcode)
where du.serviceflag= 'true' and du.loginname= p_login_name and du.passwd = p_pwd;
END;
$$;


ALTER FUNCTION kaveri.fn_get_login_details(p_login_name text, p_pwd text) OWNER TO csgadmin;

--
-- Name: fn_get_property_schedule_data_by_applicationnumber(text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_get_property_schedule_data_by_applicationnumber(applicationno text) RETURNS TABLE(propertyid bigint, scheduletype character varying, totalarea numeric, eastboundary character varying, westboundary character varying, northboundary character varying, southboundary character varying, description character varying, partydetails json, executantdetails json)
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Query to get property schedule data with correlated party details as a JSON array
    RETURN QUERY
    SELECT
        p.propertyid,
		p.scheduletype,
        p.totalarea,
        p.eastboundary,
        p.westboundary,
        p.northboundary,
        p.southboundary,
        p.description,
        (
            -- JSON aggregation happens here
            SELECT JSON_AGG(
                JSON_BUILD_OBJECT(
                    'partyid', pi.partyid,
                    'firstname', pi.firstname
                )
            )
            FROM kaveri.partyinfo pi
            WHERE pi.applicationnumber = applicationno and pi.partytypeid = 1
        ) AS partydetails,
		(
            -- Aggregate executants where partytypeid = 2
            SELECT JSON_AGG(
                JSON_BUILD_OBJECT(
                    'partyid', pi.partyid,
                    'firstname', pi.firstname
                )
            )
            FROM kaveri.partyinfo pi
            WHERE pi.applicationnumber = applicationno AND pi.partytypeid = 2
        ) AS executantdetails
    FROM
        kaveri.propertyschedules p
    WHERE
        p.applicationnumber = applicationno;
END;
$$;


ALTER FUNCTION kaveri.fn_get_property_schedule_data_by_applicationnumber(applicationno text) OWNER TO postgres;

--
-- Name: fn_get_registration_and_survey_data_k2_jslip(integer, text, integer, text, text); Type: FUNCTION; Schema: kaveri; Owner: raghupathi
--

CREATE FUNCTION kaveri.fn_get_registration_and_survey_data_k2_jslip(p_talukcode integer, p_finalregnumbers text, p_srocode integer, p_bhoomidistrict text, p_bhoomitaluk text) RETURNS TABLE(documentid bigint, applicationnumber character varying, finalregistrationnumber character varying, regid text, srocode integer, sronamee character varying, registrationdate text, regarticlecode integer, previousarticlecode integer, previousfinalregistrationnumber character varying, previousregistrationdate date, jslipnumber text, villagecode bigint, correctedcolumncodes text, cost numeric, receiptnumber text, propertyid bigint, articlenamee character varying, totalarea numeric, unit character varying, measurementnamee character varying, survey_no integer, hissa_no character varying, currentnumber character varying, village character varying, hoblicode integer, hobli character varying, talukcode integer, taluk character varying, districtcode integer, district character varying, govtrestrictioncleared text, govtrestrictionid text, govtrestrictionorder text, isownertobeclaimant boolean)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH base_combinations AS (
        SELECT
            d.finalregistrationnumber,
            bm.bhoomidistrictcode,
            bm.bhoomitalukcode,
            pm.srocode,
            pm.villagecode
        FROM kaveri.propertymaster pm
        JOIN kaveri.villagemaster v ON v.villagecode = pm.villagecode
        JOIN kaveri.hoblimaster h ON h.hoblicode = v.hoblicode
        JOIN kaveri.talukmaster t ON t.talukcode = h.talukcode
        JOIN kaveri.bhoomimappingdetails bm ON bm.kaverivillagecode = pm.villagecode
        JOIN kaveri.documentmaster d ON d.applicationnumber = pm.applicationnumber AND d.documentid = pm.documentid
        JOIN kaveri.stamprulesflag st ON st.stampruleid = pm.stampruleid
        WHERE t.talukcode = p_talukcode
          AND d.finalregistrationnumber = ANY(string_to_array(p_finalregnumbers, ','))
          AND pm.propertytypeid = 17
          AND pm.srocode = p_srocode
          AND bm.bhoomidistrictcode = p_bhoomidistrict::Integer
          AND bm.bhoomitalukcode = p_bhoomitaluk::Integer
    )
    SELECT DISTINCT 
        vj.documentid::BIGINT,
        vj.applicationnumber::VARCHAR,
        vj.finalregistrationnumber::VARCHAR,
        vj.regid::text,
        vj.srocode,
        vj.sronamee::VARCHAR,
        TO_CHAR(vj.registrationdate, 'DD/MM/YYYY'),
        vj.regarticlecode,
        vj.previousarticlecode,
        vj.previousfinalregistrationnumber,
        vj.previousregistrationdate,
        vj.jslipnumber,
        vs.villagecode,
        vj.correctedcolumncodes,
        vj.cost,
        vj.receiptnumber,

        vs.propertyid,
        vs.articlenamee,
        vs.totalarea,
        vs.unit,
        vs.measurementnamee,
        vs.survey_no,
        vs.hissa_no,
        vs.currentnumber,
        vs.village,
        vs.hoblicode,
        vs.hobli,
        vs.talukcode AS talukcode_survey,
        vs.taluk,
        vs.districtcode,
        vs.district,
        vs.govtrestrictioncleared,
        vs.govtrestrictionid,
        vs.govtrestrictionorder,
        vs.isownertobeclaimant
    FROM base_combinations bc
    JOIN kaveri.vw_jslip_applicationdetails_for_old_methods vj 
        ON vj.finalregistrationnumber = bc.finalregistrationnumber AND vj.srocode = bc.srocode
    LEFT JOIN kaveri.vw_jslip_surveynumberdetails_for_old_method vs 
        ON vs.finalregistrationnumber = bc.finalregistrationnumber AND vs.kaverivillagecode = bc.villagecode;

END;
$$;


ALTER FUNCTION kaveri.fn_get_registration_and_survey_data_k2_jslip(p_talukcode integer, p_finalregnumbers text, p_srocode integer, p_bhoomidistrict text, p_bhoomitaluk text) OWNER TO raghupathi;

