--
-- Name: fn_get_vaultid_excel(bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_get_vaultid_excel(p_partyid bigint) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_vaultid VARCHAR;
    v_aadharhash VARCHAR;
BEGIN
    -- Get party details
    SELECT pi.vaultid, pi.aadharhash
    INTO v_vaultid, v_aadharhash
    FROM kaveri.partyinfo pi
    WHERE pi.partyid = p_partyid;

    -- If vaultid already exists, return it
    IF v_vaultid IS NOT NULL THEN
        RETURN v_vaultid;
    END IF;

    -- Check decrypt table
    SELECT d.vaultrefnumber
    INTO v_vaultid
    FROM kaveri.aadhaar_log_citizen_decrypt d
    WHERE d.aadhaarhash = v_aadharhash
      AND d.status = 'Y'
    LIMIT 1;

    IF v_vaultid IS NOT NULL THEN
        RETURN v_vaultid;
    END IF;

    -- Get latest vaultid from authentication log
    SELECT aal.vault_id
    INTO v_vaultid
    FROM kaveri.aadhar_authentication_log_citizen aal
    WHERE aal.aadharhash = v_aadharhash
    ORDER BY aal.inserteddatetime DESC
    LIMIT 1;

    RETURN v_vaultid;
END;
$$;


ALTER FUNCTION kaveri.fn_get_vaultid_excel(p_partyid bigint) OWNER TO postgres;

