    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN

  return query
  
  select v.villagecode, v.villagenamee, v.isurban, v.bhoomidistrictcode, v.bhoomitalukcode, v.bhoomivillagecode,v.srocode  as srocode 
