--
-- Name: fn_getzonefromvillage(bigint, boolean); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_getzonefromvillage(_villagecode bigint, _showuda boolean DEFAULT false) RETURNS TABLE(udeptid1 integer, departmentname1 character varying, getdata1 boolean, status1 boolean)
    LANGUAGE plpgsql
    AS $$


DECLARE
v_count integer;

begin

_showuda:=false;
	
if _showuda=false then 

			select count(*) into v_count from 
			(select v2.villagecode,v2.villagenamee ,v2.isurban,v2.bhoomidistrictcode,v2.bhoomitalukcode,
			v2.bhoomivillagecode,v2.srocode 	from kaveri.villagewardmapping v
			 join kaveri.villagemaster v2 on v.villagecode=v2.villagecode
			 where v.villagecode=_villagecode)temp;
			 
			 if (v_count>0) then
			 
			 	return query
			  
					  select udeptid,departmentname,getdata,status  from kaveri.IntegrationDepartment 
					where udeptid in
					(select deptid from kaveri.villageurbanmapping where villagecode=_villagecode 
					 and deptid not in(2,4,10)  union select 46
					 union select 1
					) and isactive=true order by udeptid ;
					
				else
			
			
			
			 	 return query
			  
			 	 select udeptid,departmentname,getdata,status  from kaveri.IntegrationDepartment where udeptid in
				(select deptid from kaveri.villageurbanmapping where villagecode=_villagecode 
				 and deptid not in(2,4,10)  union select 46 
				) and isactive=true order by udeptid ;
			
			end if;
	else 
	
		return query
			  
			 	 select udeptid,departmentname,getdata,status  from kaveri.IntegrationDepartment
			 	 where udeptid =10 and isactive=true;
				
			
	
	end if;
END;
$$;


