--
-- Name: fn_ins_propertymaster_dupe(character varying, character varying, boolean, bigint, bigint, bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_ins_propertymaster_dupe(p_finalregnum character varying, p_applicationnum character varying, p_mutationflag boolean, p_regarticlecode bigint, p_stamparticlecode bigint, p_stampruleid bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$

DECLARE v_valheaderid bigint;
v_applicationnumber character varying;
v_ary_propertyid bigint [];
v_propertyid_reference bigint;
v_propertyid bigint;
v_ary_partyid bigint [];
v_partyid_reference bigint;
v_partyid bigint;
v_mutation_partyid bigint;
v_swap boolean;
v_bookid integer;
v_srocode integer;
v_registrationdatetime timestamp without time zone;
v_stampduty integer;
v_docid character varying;
v_regdatetime character varying;
v_partyidd bigint;
v_dupparties bigint[];
v_linkpartyid record;
v_regarticlecode int;
v_lease boolean;
BEGIN


-------Fetching appno,docid,regdatetime from propertymaster --------------------------

select applicationnumber,
	documentid,
	to_char(registrationdatetime::date, 'DDMMYYYY')::text,
	regarticlecode
	into v_applicationnumber,
	v_docid,
	v_regdatetime,
	v_regarticlecode
from kaveri.documentmaster
where finalregistrationnumber = p_finalregnum;
