INSERT INTO kaveri.k1documentdetails(
		applicationnumber,
		finalregistrationnumber,
		bookid,
		stampduty,
		srocode,
		registrationdate,
		prevarticlecode,
		prevregid
	)
VALUES (
		p_applicationnum,
		p_finalregnum,
		v_bookid,
		v_stampduty,
		v_srocode,
		v_registrationdatetime,
		v_regarticlecode,
		concat(v_docid || v_regdatetime)
	);
if(
	p_mutationflag is not null
	and p_mutationflag = true
) then for v_mutation_partyid in (
	select partyid
	from kaveri.partyinfo
	where applicationnumber = p_applicationnum
		and partytypeid = 1
		and propertyid is not null
) loop
update kaveri.partyinfo pi
set propertyid = (
		select pm.propertyid
		from kaveri.partyinfo pm
		where pm.partyid = v_mutation_partyid
	)
where pi.applicationnumber = p_applicationnum
	and pi.partyid in (
		select partyid
		from kaveri.partyinfo p
		where p.applicationnumber = p_applicationnum
			and p.partytypeid = 2
			and p.propertyid is null
		limit 1
	);
update kaveri.partyinfo pi
set propertyid = null
where partyid = v_mutation_partyid;
end loop;
end if;
else return 'No Records Found';
end if;
return p_applicationnum;
END;
$$;


ALTER FUNCTION kaveri.fn_ins_propertymaster_dupe(p_finalregnum character varying, p_applicationnum character varying, p_mutationflag boolean, p_regarticlecode bigint, p_stamparticlecode bigint, p_stampruleid bigint) OWNER TO postgres;

--
-- Name: fn_ins_propertymaster_dupe_03030206(character varying, character varying, boolean, bigint, bigint, bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
