 then
select array_agg(pm.propertyid) into v_ary_propertyid
from kaveri.propertymaster pm
where applicationnumber = v_applicationnumber;

select array_agg(partyid) into v_ary_partyid
from kaveri.partyinfo
where applicationnumber = v_applicationnumber --and propertyid is not null
	and linkpartyid is null;

--select propertyid into v_pid from kaveri.propertymaster
--where referencepropertyid in (select unnest(v_prop_id));

