----Droping Temporary Table-----

drop table propernodetails;


------fetching bookid,srocode,regdatetime from documentmaster on the basis of oldfinalregistrationnumber----------------------------------------

select bookid,
	srocode,
	registrationdatetime into v_bookid,
	v_srocode,
	v_registrationdatetime
from kaveri.documentmaster
where finalregistrationnumber = p_finalregnum;

----------------------------------------------------------------------------------------------

INSERT INTO kaveri.k1documentdetails(
		applicationnumber,
		finalregistrationnumber,
		bookid,
		stampduty,
		srocode,
		registrationdate,
		prevarticlecode,
		prevregid
	)
VALUES (
		p_applicationnum,
		p_finalregnum,
		v_bookid,
		v_stampduty,
		v_srocode,
		v_registrationdatetime,
		v_regarticlecode,
		concat(v_docid || v_regdatetime)
	);
if(
	p_mutationflag is not null
	and p_mutationflag = true
) then for v_mutation_partyid in (
	select partyid
	from kaveri.partyinfo
	where applicationnumber = p_applicationnum
		and partytypeid = 1
		and propertyid is not null
) loop
update kaveri.partyinfo pi
set propertyid = (
		select pm.propertyid
		from kaveri.partyinfo pm
		where pm.partyid = v_mutation_partyid
	)
where pi.applicationnumber = p_applicationnum
	and pi.partyid in (
		select partyid
		from kaveri.partyinfo p
		where p.applicationnumber = p_applicationnum
			and p.partytypeid = 2
			and p.propertyid is null
		limit 1
	);
update kaveri.partyinfo pi
set propertyid = null
where partyid = v_mutation_partyid;
end loop;
end if;
else return 'No Records Found';
end if;
return p_applicationnum;
END;
$$;


ALTER FUNCTION kaveri.fn_ins_propertymaster_dupe_03030206(p_finalregnum character varying, p_applicationnum character varying, p_mutationflag boolean, p_regarticlecode bigint, p_stamparticlecode bigint, p_stampruleid bigint) OWNER TO postgres;

--
-- Name: fn_ins_propertymaster_dupe_20042024(character varying, character varying, boolean, bigint, bigint, bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_ins_propertymaster_dupe_20042024(p_finalregnum character varying, p_applicationnum character varying, p_mutationflag boolean, p_regarticlecode bigint, p_stamparticlecode bigint, p_stampruleid bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE v_valheaderid bigint;
v_applicationnumber character varying;
v_ary_propertyid bigint [];
v_propertyid_reference bigint;
v_propertyid bigint;
v_ary_partyid bigint [];
v_partyid_reference bigint;
v_partyid bigint;
v_mutation_partyid bigint;
v_swap boolean;
v_bookid integer;
v_srocode integer;
v_registrationdatetime timestamp without time zone;
v_stampduty integer;
v_docid character varying;
v_regdatetime character varying;
BEGIN

-------Fetching appno,docid,regdatetime from propertymaster --------------------------

select applicationnumber,
	documentid,
	to_char(registrationdatetime::date, 'DDMMYYYY')::text 
	into v_applicationnumber,
	v_docid,
	v_regdatetime
from kaveri.documentmaster
where finalregistrationnumber = p_finalregnum;
--	select b.stampduty into v_stmpduty from kaveri.propertymaster b where b.propertytypeid in (17) and b.sdcalculationstring = p_finalregnum limit 1;

----------fetching stampduty from propertymaster for propertytypeid=17----------------------

select p.stampduty into v_stampduty
from kaveri.propertymaster p
where p.propertytypeid =17
and p.applicationnumber = v_applicationnumber
limit 1;



if p_stampruleid in (281, 278, 273, 284, 164) then v_swap = false;
else v_swap = true;
end if;
if (v_applicationnumber is not null and v_applicationnumber <> '')
 then
select array_agg(propertyid) into v_ary_propertyid
from kaveri.propertymaster
where applicationnumber = v_applicationnumber;
if (v_ary_propertyid is not null and array_length(v_ary_propertyid, 1) > 0) 
then 

foreach v_propertyid_reference IN array v_ary_propertyid --(SELECT kaveri.fn_fetch_1d_arrayofarray(v_partyid)) 
loop begin
insert into kaveri.propertymaster (
		propertyid,
		documentid,
		applicationnumber,
		referencepropertyid,
		villagecode,
		regsrocode,
		srocode,
		totalarea,
		unitid,
		northboundary,
		southboundary,
		eastboundary,
		westboundary,
		landmark,
		marketvalue,
		assessment,
		sdcalculationstring,
		stampduty,
		transferliabilities,
		consideration,
		additionalduty,
		cessduty,
		govtduty,
		isexempted,
		exemptiondescription,
		ismovableproperty,
		sdrefund,
		docmarketvalue,
		valid1,
		isimdemnified,
		restriction,
		restrictiontype,
		restrictiondescription,
		enumber,
		claimingblocknumber,
		retainingblocknumber,
		valuationreport,
		loanpurposeid,
		verified,
		issroapproved,
		stamparticlecode,
		stampruleid,
		regarticlecode,
		propertytypeid,
		noofscanpages,
		movablepropertydesc,
		roadcode,
		wardid,
		pidno,
		udeptid,
		sfdastamparticlecode,
		sfdastampruleid,
		sfdanoofscanpages,
		srostamparticlecode,
		srostampruleid,
		sronoofscanpages,
		sfdamarketvalue,
		sromarketvalue,
		ownedarea,
		sfdanatureofdocument,
		sronatureofdocument,
		denodescription,
		estampdescription,
		adjudescription,
		sroconsideration,
		sfdaconsideration,
		inserteddatetime
	)
select nextval('kaveri.propertymastersequence_seq'),
	0,
	p_applicationnum,
	v_propertyid_reference,
	villagecode,
	regsrocode,
	srocode,
	totalarea,
	unitid,
	northboundary,
	southboundary,
	eastboundary,
	westboundary,
	landmark,
	marketvalue,
	assessment,
	p_finalregnum,
	stampduty,
	transferliabilities,
	consideration,
	additionalduty,
	cessduty,
	govtduty,
	isexempted,
	exemptiondescription,
	ismovableproperty,
	sdrefund,
	docmarketvalue,
	valid1,
	isimdemnified,
	restriction,
	restrictiontype,
	restrictiondescription,
	enumber,
	claimingblocknumber,
	retainingblocknumber,
	valuationreport,
	loanpurposeid,
	verified,
	issroapproved,
	p_stamparticlecode,
	p_stampruleid,
	p_regarticlecode,
	propertytypeid,
	noofscanpages,
	movablepropertydesc,
	roadcode,
	wardid,
	pidno,
	udeptid,
	sfdastamparticlecode,
	sfdastampruleid,
	sfdanoofscanpages,
	srostamparticlecode,
	srostampruleid,
	sronoofscanpages,
	sfdamarketvalue,
	sromarketvalue,
	ownedarea,
	sfdanatureofdocument,
	sronatureofdocument,
	denodescription,
	estampdescription,
	adjudescription,
	sroconsideration,
	sfdaconsideration,
	current_timestamp
from kaveri.propertymaster
where propertyid = v_propertyid_reference
	and applicationnumber = v_applicationnumber
RETURNING propertyid::bigint into v_propertyid;


insert into kaveri.propertynumberdetails (
		propertyid,
		srocode,
