	thumbremarks
FROM kaveri.partyinfo
where linkpartyid = v_partyid_reference;
end;
end loop;
end if;

------fetching bookid,srocode,regdatetime from documentmaster on the basis of oldfinalregistrationnumber----------------------------------------

select bookid,
	srocode,
	registrationdatetime into v_bookid,
	v_srocode,
	v_registrationdatetime
from kaveri.documentmaster
where finalregistrationnumber = p_finalregnum;

----------------------------------------------------------------------------------------------

INSERT INTO kaveri.k1documentdetails(
		applicationnumber,
		finalregistrationnumber,
		bookid,
		stampduty,
		srocode,
		registrationdate,
		prevarticlecode,
		prevregid
	)
VALUES (
		p_applicationnum,
		p_finalregnum,
		v_bookid,
		v_stampduty,
		v_srocode,
		v_registrationdatetime,
		p_regarticlecode,
		concat(v_docid || v_regdatetime)
	);
if(
	p_mutationflag is not null
	and p_mutationflag = true
) then for v_mutation_partyid in (
	select partyid
	from kaveri.partyinfo
	where applicationnumber = p_applicationnum
		and partytypeid = 1
		and propertyid is not null
) loop
update kaveri.partyinfo pi
set propertyid = (
		select pm.propertyid
		from kaveri.partyinfo pm
		where pm.partyid = v_mutation_partyid
	)
where pi.applicationnumber = p_applicationnum
	and pi.partyid in (
		select partyid
		from kaveri.partyinfo p
		where p.applicationnumber = p_applicationnum
			and p.partytypeid = 2
			and p.propertyid is null
		limit 1
	);
update kaveri.partyinfo pi
set propertyid = null
where partyid = v_mutation_partyid;
end loop;
end if;
else return 'No Records Found';
end if;
return p_applicationnum;
END;
$$;


ALTER FUNCTION kaveri.fn_ins_propertymaster_dupe_20042024(p_finalregnum character varying, p_applicationnum character varying, p_mutationflag boolean, p_regarticlecode bigint, p_stamparticlecode bigint, p_stampruleid bigint) OWNER TO postgres;

--
-- Name: fn_ins_upd_ddchallannumbertrack(character varying, character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_ins_upd_ddchallannumbertrack(_ddchallannumber character varying, _applicationnumber character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
v_check int;
v_receipttotal numeric;
begin

select COALESCE(receipttotal, 0) into v_receipttotal from kaveri.otherreceiptdetails where ddchallannumber = _ddchallannumber;
if (v_receipttotal>0)
	then
	if exists(select applicationnumber from kaveri.ddchallannumbertrack where ddchallannumber = _ddchallannumber and isused = true)
		then
		-- Challan Number already used...
		v_check := 2;
	else 
		insert into kaveri.ddchallannumbertrack(ddchallannumber, applicationnumber, isused,receipttotal)
		values(_ddchallannumber, _applicationnumber, true,v_receipttotal);
		-- Challan Number is Processed...
		v_check := 3;
	end if;
else
	-- Challan Number is not entered by SR...
	v_check := 1;
end if;
return v_check;
end;
$$;


ALTER FUNCTION kaveri.fn_ins_upd_ddchallannumbertrack(_ddchallannumber character varying, _applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_ins_upd_persondetails(kaveri.persondetails1_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_ins_upd_persondetails(p_persondetails kaveri.persondetails1_input[]) RETURNS integer
    LANGUAGE plpgsql
    AS $$

declare
v_cnt bigint;
v_personid integer;
v_person_arry p_persondetails%type;
v_gender character varying (1);
begin

if(p_persondetails is not null and array_length(p_persondetails,1)>0 ) then
FOR v_person_arry  IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_persondetails))
loop
  v_cnt:= 0;
  Select count(*) into v_cnt from kaveri.persondetails where personid in 
  (select a._personid from unnest(v_person_arry) a) ;
  if v_cnt = 0 then
    insert into kaveri.persondetails
	(personid,imagefilepath,salutation,firstname,middlename,lastname,mothersalutation,motherfirstname,
     mothermiddlename,motherlastname,fathersalutation,fatherfirstname,fathermiddlename,fatherlastname,
     sex,prehousebuildname,prestreetname,prestatecode,predistrictcode,pretalukacode,prehoblicode,
	 precityvillagecode,prepincode,ispresentaddresssameaspermanent,perhousebuildname,perstreetname,
     perstatecode,perdistrictcode,pertalukacode,perhoblicode,percityvillagecode,perpincode,phoneno,email,
	dob,age,--srocode,drcode,
	registrationid,applicationnumber,occupation,
	 --marriagemodeid,marriagetypeid,
	 deathcertificatefilepath,
	 divorcecertificatefilepath,persontypeid,--durationin,
	statusid)
select 
nextval('kaveri.personid_seq'),
a._imagefilepath,
a._salutation,
a._firstname,
a._middlename,
a._lastname,
a._mothersalutation,
a._motherfirstname,
a._mothermiddlename,
a._motherlastname,
a._fathersalutation,
a._fatherfirstname,
a._fathermiddlename,
a._fatherlastname,
a._sex,
a._prehousebuildname,
a._prestreetname,
a._prestatecode,
a._predistrictcode,
a._pretalukacode,
a._prehoblicode,
a._precityvillagecode,
a._prepincode,
a._ispresentaddresssameaspermanent,
a._perhousebuildname,
a._perstreetname,
a._perstatecode,
a._perdistrictcode,
a._pertalukacode,
a._perhoblicode,
a._percityvillagecode,
a._perpincode,
a._phoneno,
a._email,
a._dob,
a._age,
--a._srocode,
--a._drcode,
a._registrationid,
a._applicationnumber,
a._occupation,
--a._marriagemodeid,
--a._marriagetypeid,
a._deathcertificatefilepath,
a._divorcecertificatefilepath,
a._persontypeid,
--a._durationin,
a._statusid

 from unnest(v_person_arry) a
 returning personid into v_personid; 

 select a._sex into v_gender from unnest(v_person_arry) a ;
 if(v_gender like 'F%') then 
 update kaveri.marriageregistration set bridepersonid = v_personid,currentstatus='MR103' 
 where applicationnumber = (select a._applicationnumber from unnest(v_person_arry) a);
 
update kaveri.ApplicantApplicationdetails set currentstatus='MR103' 
 where applicationnumber = (select a._applicationnumber from unnest(v_person_arry) a);
 
 elsif(v_gender like 'M%') then
 update kaveri.marriageregistration set bridegroompersonid = v_personid,currentstatus='MR102' 
 where applicationnumber = (select a._applicationnumber from unnest(v_person_arry) a);
 
update kaveri.ApplicantApplicationdetails set currentstatus='MR102' 
 where applicationnumber = (select a._applicationnumber from unnest(v_person_arry) a);
 end if;
 
		else
				update kaveri.persondetails set 
				imagefilepath=COALESCE(a._imagefilepath,imagefilepath),
				salutation=COALESCE(a._salutation,salutation),
				firstname = COALESCE(a._firstname,firstname), 
				middlename = COALESCE(a._middlename,middlename),
				lastname = COALESCE(a._lastname,lastname),
				mothersalutation= COALESCE(a._mothersalutation,mothersalutation),
				motherfirstname= COALESCE(a._motherfirstname,motherfirstname),
				mothermiddlename= COALESCE(a._mothermiddlename,mothermiddlename),
				motherlastname= COALESCE(a._motherlastname,motherlastname),
				fathersalutation = COALESCE(a._fathersalutation,fathersalutation),
				fatherfirstname= COALESCE(a._fatherfirstname,fatherfirstname),
				fathermiddlename= COALESCE(a._fathermiddlename,fathermiddlename),
				fatherlastname= COALESCE(a._fatherlastname,fatherlastname),
				sex=COALESCE(a._sex,sex),
				prehousebuildname= COALESCE(a._prehousebuildname,prehousebuildname),
				prestreetname= COALESCE(a._prestreetname,prestreetname),
				prestatecode = COALESCE(a._prestatecode,prestatecode),
				predistrictcode = COALESCE(a._predistrictcode,predistrictcode),
				pretalukacode = COALESCE(a._pretalukacode,pretalukacode),
				prehoblicode = COALESCE(a._prehoblicode,prehoblicode),
				precityvillagecode = COALESCE(a._precityvillagecode,precityvillagecode),
				prepincode=COALESCE(a._prepincode,prepincode),
				ispresentaddresssameaspermanent=COALESCE(a._ispresentaddresssameaspermanent,ispresentaddresssameaspermanent),
				perhousebuildname= COALESCE(a._perhousebuildname,perhousebuildname),
				perstreetname= COALESCE(a._perstreetname,perstreetname),
				perstatecode = COALESCE(a._perstatecode,perstatecode),
				perdistrictcode = COALESCE(a._perdistrictcode,perdistrictcode),
				pertalukacode = COALESCE(a._pertalukacode,pertalukacode),
				perhoblicode = COALESCE(a._perhoblicode,perhoblicode),
				percityvillagecode = COALESCE(a._percityvillagecode,percityvillagecode),
				perpincode=COALESCE(a._perpincode,perpincode),
				phoneno= COALESCE(a._phoneno,phoneno),
				dob= COALESCE(a._dob,dob),
				age= COALESCE(a._age,age),
				--srocode= COALESCE(a._srocode,srocode),
				--drcode= COALESCE(a._drcode,drcode),
				registrationid= COALESCE(a._registrationid,registrationid),
				applicationnumber= COALESCE(a._applicationnumber,applicationnumber),
				email= COALESCE(a._email,email),
				occupation = COALESCE(a._occupation,occupation),
				--durationin = coalesce (a._durationin,durationin),
				--marriagemodeid = coalesce (a._marriagemodeid,marriagemodeid),
				--marriagetypeid = coalesce (a._marriagetypeid,marriagetypeid),
				deathcertificatefilepath = a._deathcertificatefilepath,
				divorcecertificatefilepath = a._divorcecertificatefilepath,
				persontypeid=COALESCE(a._persontypeid,persontypeid),
				statusid=COALESCE(a._statusid,statusid)
				from unnest(v_person_arry) a
			  where personid in  (select a._personid from unnest(v_person_arry) a) 
			   returning personid into v_personid;
 end if;

 END LOOP;
 end if;

return v_personid;
end;
$$;


