--

CREATE FUNCTION kaveri.fn_insert__witness_info(p_partydetails kaveri.witnessinfo_input[] DEFAULT NULL::kaveri.witnessinfo_input[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $_$
DECLARE
	id_val bigint;
    --inserted_id integer;
	cit_id text;
   --property_arry $1%type;
   property_arry kaveri.witnessinfo_input[];
   v_witnessid bigint;
   var_r record;
   v_pid bigint[];
v_cnt integer;
begin
Select count(*) into v_cnt from kaveri.witnessinfo where witnessid in 
(select a._witnessid from unnest($1) a) ;
if(p_partydetails is not null and array_length(p_partydetails,1)>0 ) then
FOR property_arry IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_partydetails))
loop
v_cnt:= 0;
Select count(*) into v_cnt from kaveri.witnessinfo where witnessid in 
(select a._witnessid from unnest(property_arry) a) ;
if v_cnt = 0 then
INSERT INTO kaveri.witnessinfo( witnessid,
    documentid,
    name,
    address,
    sex,
    age,
    profession,
    registrationid,
    dateofbirth,
    status,
    phoneno,
    relation,
    mothername,
    fathersname,
    presentatsolemanization,
	srocode,
    isonline,
	applicationnumber,
	verified,
	issroapproved,
	statecode,
    districtcode,
    talukcode,
    hoblicode,
    villagecode,
    relativename,
    pincode,
    middlename,
    lastname,
    houseno,
    iscliment,
    isexicutent)
    select  
	nextval('kaveri.witnessinfo_witnessid_seq'),
    _documentid,
    _name,
    _address,
    _sex,
    _age,
    _profession,
    _registrationid,
    _dateofbirth,
    _status,
    _phoneno,
    _relation,
    _mothername,
    _fathersname,
    _presentatsolemanization,
	_srocode,
    _isonline,
	_applicationnumber,
	_verified,
	_issroapproved,
	_statecode,
    _districtcode,
    _talukcode,
    _hoblicode,
    _villagecode,
    _relativename,
    _pincode,
    _middlename,
    _lastname,
    _houseno,
    _iscliment,
    _isexicutent
	from unnest(property_arry)	
	 returning witnessid::bigint into v_witnessid;
	 else
	 update kaveri.witnessinfo set
	  documentid= a._documentid,
    name=a._name,
    address=a._address,
    sex=a._sex,
    age=a._age,
    profession=a._profession,
    registrationid=a._registrationid,
    dateofbirth=a._dateofbirth,
    status=a._status,
    phoneno=a._phoneno,
    relation=a._relation,
    mothername=a._mothername,
    fathersname=a._fathersname,
    presentatsolemanization=a._presentatsolemanization,
	srocode=a._srocode,
    isonline=a._isonline,
	applicationnumber=a._applicationnumber,
	verified=a._verified,
	issroapproved=a._issroapproved,
	statecode=a._statecode,
    districtcode=a._districtcode,
    talukcode=a._talukcode,
    hoblicode=a._hoblicode,
    villagecode=a._villagecode,
    relativename=a._relativename,
    pincode=a._pincode,
    middlename=a._middlename,
    lastname=a._lastname,
    houseno=a._houseno,
    iscliment=a._iscliment,
    isexicutent=a._isexicutent
	from unnest(property_arry) a  where witnessid in 
			 (select a._witnessid from unnest(property_arry) a) 
			 RETURNING witnessid::bigint into v_witnessid;
	end if;
	v_pid := array_append(v_pid,v_witnessid);
	end loop;
	end if;
Return v_pid;
end;
$_$;


