--
-- Name: fn_insert_application_auditentry(); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_application_auditentry() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE 
V_ACTIVITYORDER INTEGER DEFAULT 0;
BEGIN
SELECT COALESCE(MAX(ACTIVITYORDER),0)+1 INTO V_ACTIVITYORDER FROM Kaveri.ApplicationAudit
WHERE applicationnumber = NEW.applicationnumber;
         INSERT INTO Kaveri.ApplicationAudit(applicationnumber,srocode,wrkflowstatusid,activityby,ACTIVITYORDER,remarks)
         VALUES(NEW.applicationnumber,new.srocode,new.currentstatus,new.lastupdatedby,V_ACTIVITYORDER,new.remarks);
 
    RETURN NEW;
END;
$$;


ALTER FUNCTION kaveri.fn_insert_application_auditentry() OWNER TO csgadmin;

--
-- Name: fn_insert_appreviewdetails(kaveri.application_reviewdetails_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_appreviewdetails(kaveri.application_reviewdetails_input[]) RETURNS text
    LANGUAGE plpgsql
    AS $_$
DECLARE
   party_arry $1%type;
   v_applicationnumber text;
   v_issro boolean default null;
   v_srocnt bigint default 0;
BEGIN
   FOR party_arry IN (SELECT kaveri.fn_fetch_1d_arrayofarray($1))    
	loop
	if(v_srocnt = 0 and v_issro is null) then 
		select count(*) into v_srocnt from kaveri.vw_department_users v
		where v.userid in ( SELECT _deptuserid FROM unnest(party_arry)) 
		and v.designationid in (1) ;
	
	
		if v_srocnt > 0 then
			v_issro = 'true';
		else
		select count(*) into v_srocnt from kaveri.departmentuserroles
		where mappeduserid in ( SELECT _deptuserid FROM unnest(party_arry))
		and designationid in (1);
			if v_srocnt > 0 then
			v_issro = 'true';
			else
			v_issro = 'false';
		end if;
		end if;
	end if;
	
	  INSERT INTO kaveri.applicationreviewdetails (reviewid,applicationnumber,isverified,remarks,deptuserid,issroremarks)
	  SELECT _reviewid,_applicationnumber,_issroapprove,_sroremarks,_deptuserid,v_issro FROM unnest(party_arry)
	  RETURNING applicationnumber::TEXT INTO v_applicationnumber;
     END LOOP;
   return v_applicationnumber;
END;
$_$;


ALTER FUNCTION kaveri.fn_insert_appreviewdetails(kaveri.application_reviewdetails_input[]) OWNER TO csgadmin;

--
-- Name: fn_insert_appverification(kaveri.application_verification_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_appverification(p_verification kaveri.application_verification_input[]) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
   v_applicationnumber text;
   v_cnt bigint default 0;
BEGIN
  
update kaveri.APPLICATIONVERIFICATION set
	eval_Presentor = a._eval_Presentor,
    eval_executiondate   = a._eval_executiondate,
    eval_partydetails  = a._eval_partydetails,
    eval_scheduleid  = a._eval_scheduleid,
	eval_voluntaryexec  = a._eval_voluntaryexec,
	eval_docclasstype  = a._eval_docclasstype,
	eval_valuationduty  = a._eval_valuationduty,
	eval_payment  = a._eval_payment,
	eval_requireddocuments  = a._eval_requireddocuments,
	eval_deedattachment  = a._eval_deedattachment,
	eval_attestation  = a._eval_attestation,
	eval_executantsbeforeme =a._eval_executantsbeforeme ,
	eval_annexure =a._eval_annexure
			from unnest(p_verification) a
		 where applicationnumber= a._applicationnumber
		 returning applicationnumber into v_applicationnumber;
		 
if(v_applicationnumber is null or v_applicationnumber = '') then 
insert into kaveri.APPLICATIONVERIFICATION (
	applicationnumber,eval_Presentor,eval_executiondate,eval_partydetails ,
    eval_scheduleid ,eval_voluntaryexec,eval_docclasstype,eval_valuationduty ,
	eval_payment ,eval_requireddocuments,eval_deedattachment,eval_attestation,eval_executantsbeforeme,eval_annexure) 
	select _applicationnumber,_eval_Presentor,_eval_executiondate,_eval_partydetails ,
    _eval_scheduleid ,_eval_voluntaryexec,_eval_docclasstype,_eval_valuationduty ,
	_eval_payment ,_eval_requireddocuments,_eval_deedattachment,_eval_attestation,_eval_executantsbeforeme,_eval_annexure from unnest(p_verification) 
	returning applicationnumber into v_applicationnumber;
end if;
		 
   return v_applicationnumber;
END;
$$;


ALTER FUNCTION kaveri.fn_insert_appverification(p_verification kaveri.application_verification_input[]) OWNER TO csgadmin;

--
-- Name: fn_insert_articlefeecalculationdetails(bigint, character varying, integer, integer, numeric, integer, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_articlefeecalculationdetails(_id bigint, _applicationnumber character varying, _propertyid integer, _stampruleid integer, _ownerratio numeric, _moneyfromowner integer, _moneyfrombuilder integer, _moneyifany integer) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
Declare
v_cnt bigint;
v_id bigint;
begin
select count(*) into v_cnt from kaveri.articlefeecalculationdetails where id = _id;
if (v_cnt = 0) then
INSERT INTO kaveri.articlefeecalculationdetails(
    applicationnumber,
    propertyid,
    stampruleid,
    ownerratio,
    moneyfromowner,
    moneyfrombuilder,
    moneyifany
)
values
(
    _applicationnumber,
    _propertyid,
    _stampruleid,
    _ownerratio,
    _moneyfromowner,
    _moneyfrombuilder,
    _moneyifany
)  RETURNING id into v_id;
else
update kaveri.articlefeecalculationdetails
set applicationnumber=_applicationnumber,
    propertyid=_propertyid,
    stampruleid=_stampruleid,
    ownerratio=_ownerratio,
    moneyfromowner=_moneyfromowner,
    moneyfrombuilder=_moneyfrombuilder,
    moneyifany=_moneyifany where id = _id returning id into v_id;
end if;
return v_id;
   END;
$$;


ALTER FUNCTION kaveri.fn_insert_articlefeecalculationdetails(_id bigint, _applicationnumber character varying, _propertyid integer, _stampruleid integer, _ownerratio numeric, _moneyfromowner integer, _moneyfrombuilder integer, _moneyifany integer) OWNER TO csgadmin;

--
-- Name: fn_insert_auditor_deptfeesrequired(kaveri.feesrequired_auditor_input[], boolean); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_auditor_deptfeesrequired(fees_arry kaveri.feesrequired_auditor_input[], auditorupdate boolean) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
DECLARE
   id_val integer;
   fees_arry $1%type;
   v_cnt integer;
   rows_effected integer := 0;
   v_auditorupdate boolean;
   v_row_effect integer;
   v_propid bigint ;
 
begin
	
	select propertyid into v_propid
from kaveri.feesrequired a where a.applicationnumber in (select b._applicationnumber from unnest($1) b);

  FOR fees_arry IN (SELECT kaveri.fn_fetch_1d_arrayofarray($1))
     loop
   Select count(*) into v_cnt from kaveri.scrutinyfeechange where (applicationnumber,feerulecode) in 
(select a._applicationnumber,a._feerulecode from unnest(fees_arry) a);
  if (v_cnt > 0) then
  
  	if(auditorupdate) then
  	
	rows_effected := rows_effected+1;
	update kaveri.scrutinyfeechange set 
	auditoramountrequired = _amountrequired 
    from unnest(fees_arry)
	where (applicationnumber,feerulecode) in 
(select a._applicationnumber,a._feerulecode from unnest(fees_arry) a) 
RETURNING feerulecode::integer into id_val;

    end if;
   
 else
   
		   INSERT INTO kaveri.scrutinyfeechange(
		
		    documentid,
		
		    feerulecode,
		
		    auditoramountrequired,
		
			applicationnumber,
		
		    propertyid
		
			) select
		
			_documentid,
		
		    _feerulecode,
		
		    _amountrequired,
		
		    _applicationnumber,
		    
		    _propertyid
		
		    ---(case when (_propertyid is not null or _feerulecode in (91,109,110,90))then  v_propid else _propertyid end) as propertyid
		
		from unnest(fees_arry)                        
		
		    RETURNING feerulecode::integer into id_val;
   
  end if;
 
    end loop;
	
	select rows_effected into v_row_effect;
	
	return v_row_effect;
end;
$_$;


ALTER FUNCTION kaveri.fn_insert_auditor_deptfeesrequired(fees_arry kaveri.feesrequired_auditor_input[], auditorupdate boolean) OWNER TO postgres;

--
-- Name: fn_insert_auditor_feesrequired(kaveri.feesrequired_auditor_input[]); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_auditor_feesrequired(kaveri.feesrequired_auditor_input[]) RETURNS integer[]
    LANGUAGE plpgsql
    AS $_$

DECLARE

   id_val integer;

   fees_arry $1%type;

   v_applicationnumber text;

    v_txt text;

   v_propertyid bigint;

   v_cnt integer;

   var_r record;

   v_pid integer[];


v_propid bigint;
BEGIN


FOR fees_arry IN (SELECT kaveri.fn_fetch_1d_arrayofarray($1))

     loop

   Select count(*) into v_cnt from kaveri.scrutinyfeechange where (applicationnumber,feerulecode) in

(select a._applicationnumber,a._feerulecode from unnest(fees_arry) a);

  if v_cnt = 0 then

INSERT INTO kaveri.scrutinyfeechange(

    --documentid,

    feerulecode,

    amountrequired,

	applicationnumber,

    propertyid

) select

	--_documentid,

    a._feerulecode,

    a._amountrequired,

    a._applicationnumber,

    (case when (_propertyid is not null or a._feerulecode in (91,109,110,90))then  v_propid else a._propertyid end) as propertyid

from unnest(fees_arry)     a                   

    RETURNING feerulecode::integer into id_val;
   if not found then 
		raise exception 'Something went wrong! feesrequired insertion failed.'; 
	end if;

	--update kaveri.feesrequired set exemptdescription =v_exemptdescription where applicationnumber in (select 
	--_applicationnumber from unnest($1)) and feerulecode in (91,110,109,90);

    else

update kaveri.scrutinyfeechange set

    --documentid = b._documentid,

    feerulecode = b._feerulecode,

    amountrequired = b._amountrequired,

                
    applicationnumber = b._applicationnumber,

    propertyid = (case when (b._propertyid is not null or _feerulecode in (91,109,110,90))then  v_propid else b._propertyid end)

    from unnest(fees_arry) b

    where (coalesce(propertyid,0),applicationnumber,feerulecode) in

   (select coalesce(a._propertyid,0),a._applicationnumber,a._feerulecode from unnest(fees_arry) a)

RETURNING feerulecode::integer into id_val;
   if not found then 
		raise exception 'Something went wrong! feesrequired update failed.'; 
	end if;
	
	--update kaveri.feesrequired set exemptdescription =v_exemptdescription where applicationnumber in (select 
	--_applicationnumber from unnest($1)) and feerulecode in (91,110,109,90);

    end if;

     v_pid := array_append(v_pid,id_val);

    end loop;

    return v_pid;

end;

$_$;


ALTER FUNCTION kaveri.fn_insert_auditor_feesrequired(kaveri.feesrequired_auditor_input[]) OWNER TO postgres;

--
-- Name: fn_insert_bhoomifileuploaddetails(kaveri.bhoomifileuploaddetails_input_new[]); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_bhoomifileuploaddetails(kaveri.bhoomifileuploaddetails_input_new[] DEFAULT NULL::kaveri.bhoomifileuploaddetails_input_new[]) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
DECLARE
--   v_cnt integer;
  v_refcount int;
  v_refid bigint;			
begin
	select count(_referenceid) into v_refcount from unnest($1);
	
	if (v_refcount=0)
		then
		
		INSERT INTO kaveri.bhoomifileuploaddetails(referenceid, uploaddate, jslipxml, jslipindexxml
		, acknowledgeno, finalregistrationnumber, remarks, confirmationsent,srocode,bhoomivillagecode,createddate,k1k2_flag,errorcode,haschange)
		select  nextval('kaveri.referenceid_seq'),current_timestamp::timestamp without time zone,_jslipxml,_jslipindexxml,
		_acknowledgeno,_finalregistrationnumber,_remarks,_confirmationsent,_srocode,_bhoomivillagecode
		,current_timestamp as createddate,2 as k1k2_flag,_errorcode,_haschange
		from unnest($1)
		returning referenceid into v_refid;
	
	
	
	
	end if;

return v_refid;
end;
 $_$;


