    LANGUAGE plpgsql
    AS $$
declare 
v_ccid bigint;
v_cnt integer;
v_shortnamee text;
v_nomenclature text;
v_scheduletype text;
v_finyear text;
v_applicationnumber text;
_inserted_id text;
l_now text;
v_year text;
v_month text;
-- v_ccrequiredfees p_ccrequiredfees%type;
  v_pid bigint[];
begin
select count(*) into v_cnt from kaveri.cc_applicationdetails where ccid = _ccid;
