select nomenclature into v_nomenclature from kaveri.servicesmaster where serviceid = 12;
select distinct scheduletype into v_scheduletype from kaveri.propertyschedules where scheduletype = _scheduletype;
select lpad(nextval('kaveri.cc_applicationnumber_seq')::text,5,'0') into _inserted_id;
select cast(to_char(now(),'YYYY')as bigint)-1 ||'-'|| cast(to_char(now(),'YY')as bigint) into l_now;
v_applicationnumber := v_shortnamee  ||'-'||v_nomenclature ||'-'||_scheduletype ||'-'||_inserted_id||'-'||l_now;*/

-- Production code to genearate TMP applicaitons
select right(split_part(current_date::text,'-',1),2) as year into v_year;

select split_part(current_date::text,'-',2) as month into v_month;

select lpad(nextval('kaveri.tmp_applicationnumber_seq')::text,8,'0') into _inserted_id;
v_applicationnumber := 'TMPCC-'||v_year||v_month||_inserted_id;


