    signedby,
    signeddatetime,
    appliedsignedcopy,
    comparedby,
    compareddatetime,
    certificatenumber,
    accepteddatetime,*/
    marriagetypeid,
    firmtypeid,
	applicationnumber,
	isprior2003,
	reason,
	isappliedbydept
) values
(
nextval('kaveri.cc_applicationdetails_seq'),
  -- _ccnumber,
    _ccdate,
    _userid,
    _documenttype,
    _kaveridrocode,
    _kaverisrocode,
    _documentnumber,
    _booktype,
    _yearofregistration,
    _pagecount,
    _totalamount,
    _isappliedforsignedcopy,
    _documentstatusid,
    _submittedby,
    _submitteddatetime,
   /* _preparedby,
    _prepareddatetime,
    _signedby,
    _signeddatetime,
    _appliedsignedcopy,
    _comparedby,
    _compareddatetime,
    _certificatenumber,
    _accepteddatetime,*/
    _marriagetypeid,
    _firmtypeid,
	v_applicationnumber,
	_isprior2003,
	_reason,
	_isappliedbydept
) returning ccid::bigint into v_ccid;
else
update kaveri.cc_applicationdetails set 
	  -- ccnumber=_ccnumber,
    ccdate=_ccdate,
    userid=_userid,
    documenttype=_documenttype,
    kaveridrocode=_kaveridrocode,
    kaverisrocode=_kaverisrocode,
    documentnumber=_documentnumber,
    booktype=_booktype,
    yearofregistration=_yearofregistration,
    pagecount=_pagecount,
    totalamount=_totalamount,
    isappliedforsignedcopy=_isappliedforsignedcopy,
    documentstatusid=_documentstatusid,
    submittedby=_submittedby,
    submitteddatetime=_submitteddatetime,
   /* preparedby=_preparedby,
    prepareddatetime=_prepareddatetime,
    signedby=_signedby,
    signeddatetime=_signeddatetime,
    appliedsignedcopy=_appliedsignedcopy,
    comparedby=_comparedby,
    compareddatetime=_compareddatetime,
    certificatenumber=_certificatenumber,
    accepteddatetime=_accepteddatetime,*/
    marriagetypeid=_marriagetypeid,
    firmtypeid=_firmtypeid,
    isprior2003 =_isprior2003,
	reason = _reason,
	isappliedbydept = _isappliedbydept
	--applicationnumber=v_applicationnumber
	where ccid = _ccid returning ccid::bigint into v_ccid;
       -- v_pid := array_append(v_pid,v_ccid);
	  -- v_pid := array_append(v_pid,v_applicationnumber);
	end if;
	
	

/* Fees Required */
--	if(p_ccrequiredfees is not null and array_length(p_ccrequiredfees,1)>0 ) then
--FOR v_ccrequiredfees IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_ccrequiredfees))
--loop
--v_cnt:= 0;
--Select count(*) into v_cnt from kaveri.cc_requiredfees where requiredfeeid in 
--(select a._requiredfeeid from unnest(v_ccrequiredfees) a) ;
--if v_cnt = 0 then 
--INSERT INTO kaveri.cc_requiredfees( 
--     requiredfeeid,
--    ccid,
--    feeruleid,
--    payableamount,
--    ispaid,
--    serviceid,
--    feedescription
--)
--	select nextval('kaveri.cc_requiredfees_seq'),
--   v_ccid,
--  a._feeruleid,
--a._payableamount,
--a._ispaid,
--a._serviceid,
--a._feedescription
--from unnest(v_ccrequiredfees) a	
--	 returning ccid::bigint into v_ccid;
--	 else
--	 update kaveri.cc_requiredfees set
--	 ccid=v_ccid,
--   feeruleid=a._feeruleid,
--   payableamount=a._payableamount,
--   ispaid=a._ispaid,
--   serviceid=a._serviceid,
--   feedescription=a._feedescription
--	from unnest(v_ccrequiredfees) a where requiredfeeid in 
--			 (select a._requiredfeeid from unnest(v_ccrequiredfees) a) 
--			 RETURNING ccid::bigint into v_ccid;
--	 end if;
----v_pid := array_append(v_pid,v_ccid);
----v_pid := array_append(v_pid,v_applicationnumber);
--	end loop;
