--
-- Name: fn_insert_cc_applicationdetails_requiredfees(kaveri.requiredfees[]); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_cc_applicationdetails_requiredfees(v_cc_requiredfees kaveri.requiredfees[] DEFAULT NULL::kaveri.requiredfees[]) RETURNS bigint
    LANGUAGE plpgsql
    AS $_$
DECLARE
v_ccrequiredfees record;
v_cnt int;
v_ccid bigint;

BEGIN

--select applicationnumber into v_applicationnumber from kaveri.ec_applicationdetails where ecid in (v_ec_requiredfees._ecid);

--FOR v_ccrequiredfees IN (SELECT * from unnest(v_cc_requiredfees))
--loop

--raise notice '%', v_ecrequiredfees;

select count(*) into v_cnt from kaveri.cc_requiredfees where ccid in (select  ss._ccid from unnest($1) ss);

--raise notice '%', v_cnt;
v_ccid:=0;

if v_cnt = 0 then 
		INSERT INTO kaveri.cc_requiredfees( 
		requiredfeeid,
	    ccid,
    	feeruleid,
    	payableamount,
    	ispaid,
    	serviceid,
    	feedescription
		)
		select nextval('kaveri.cc_requiredfees_seq'),
		_ccid,
		_feeruleid,
		_payableamount,
		_ispaid,
		_serviceid,
		_feedescription
		from unnest($1);
		GET DIAGNOSTICS v_ccid = ROW_COUNT;
--		returning 0::bigint into v_ccid;
	if not found then 
		raise exception 'Something went wrong! ec_requiredfees insertion failed.'; 
	end if;
	 
else
	 update kaveri.cc_requiredfees set
		ccid=a._ccid,
	   	feeruleid=a._feeruleid,
   		payableamount=a._payableamount,
   		ispaid=a._ispaid,
   		serviceid=a._serviceid,
   		feedescription=a._feedescription
		from unnest($1) a 
	where requiredfeeid in (a._requiredfeeid);
	GET DIAGNOSTICS v_ccid = ROW_COUNT;
--	RETURNING 1::bigint into v_ccid;
	if not found then 
		raise exception 'Something went wrong! ec_requiredfees update failed.'; 
	end if;
	 end if;
	--v_pid := array_append(v_pid,v_ecid);
--	end loop;
return v_ccid;
end;
$_$;


