CREATE FUNCTION kaveri.fn_insert_cc_cscapplicantdetails(_cscapplicantid bigint, _firstname character varying, _middlename character varying, _lastname character varying, _address character varying, _pincode character varying, _mobilenumber character varying, _email character varying, _uid character varying, _ccid bigint, _operatorid character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare 
v_ccid bigint;
v_cscapplicantid bigint;
v_count integer;
begin
select count(*) into v_count from kaveri.cc_cscapplicantdetails where cscapplicantid = _cscapplicantid;
if v_count = 0 then
insert into kaveri.cc_cscapplicantdetails (
  cscapplicantid,
    firstname,
    middlename,
    lastname,
    address,
    pincode,
    mobilenumber,
    email,
    uid,
    ccid,
    operatorid
) values
(
nextval('kaveri.cc_cscapplicantid_seq'),
    _firstname,
    _middlename,
    _lastname,
    _address,
    _pincode,
    _mobilenumber,
    _email,
    _uid,
    _ccid,
    _operatorid
) returning cscapplicantid::bigint into v_cscapplicantid;
else
update kaveri.cc_cscapplicantdetails set 
