    middlename=_middlename,
    lastname=_lastname,
    address=_address,
    pincode=_pincode,
    mobilenumber=_mobilenumber,
    email=_email,
    uid=_uid,
    ccid=_ccid,
    operatorid=_operatorid
	where cscapplicantid = _cscapplicantid returning cscapplicantid::bigint into v_cscapplicantid;
	end if;
return v_cscapplicantid;
end;
$$;


