--

CREATE FUNCTION kaveri.fn_insert_cc_documents(_applicationnumber text, _cccertificate text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare
v_cnt bigint;
v_ccdocumentid bigint;
v_ccid bigint;
begin

select ccid  into v_ccid from kaveri.cc_applicationdetails where applicationnumber = _applicationnumber;
select count(*) into v_cnt from kaveri.cc_documents where ccid = v_ccid;

if v_cnt = 0 then
INSERT INTO kaveri.cc_documents
(
ccid,
cccertificate
) VALUES
(
v_ccid,
_cccertificate
) RETURNING ccdocumentid into v_ccdocumentid;
else
update kaveri.cc_documents set
cccertificate = _cccertificate 
where ccid = v_ccid  RETURNING ccdocumentid into v_ccdocumentid;
end if;
return v_ccdocumentid;
end;
$$;


