--
-- Name: fn_insert_citizenlogininfo(bigint, character varying, bigint, character varying, bigint, character varying, character varying, character varying, boolean, character varying, character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_citizenlogininfo(_citizenid bigint, _publicip character varying, _localport bigint, _localip character varying, _remoteport bigint, _macaddress character varying, _location character varying, _country character varying, _isactive boolean, _jwttoken character varying, _reftoken character varying) RETURNS TABLE(citizenid bigint, isactive boolean, ismultilogin boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
v_isactive character varying;
v_array character varying[];
v_citizenid character varying;
BEGIN

if((select count(c.*) from kaveri.citizenloginloginfo c where c.citizenid = _citizenid and c.isactive=true)>0) 
THEN
 update kaveri.citizenloginloginfo cll set ismultilogin=true where cll.citizenid = _citizenid and cll.isactive=true;
 
 insert into kaveri.citizenloginloginfo( c_logseqid, citizenid, publicip, localport, localip, remoteport, macaddress, location, country,
isactive, jwttoken, reftoken,ismultilogin) values
(NEXTVAL('kaveri.citizenlogin'),_citizenid,_publicip,_localport,_localip,_remoteport,_macaddress,_location,_country,_isactive,_jwttoken,_reftoken,true);
 
RETURN QUERY ( select b.citizenid, true as isactive, true as ismultilogin from kaveri.citizenloginloginfo b where b.citizenid = _citizenid limit 1);

else
insert into kaveri.citizenloginloginfo( c_logseqid, citizenid, publicip, localport, localip, remoteport, macaddress, location, country,
isactive, jwttoken, reftoken) values
(NEXTVAL('kaveri.citizenlogin'),_citizenid,_publicip,_localport,_localip,_remoteport,_macaddress,_location,_country,_isactive,_jwttoken,_reftoken);

RETURN QUERY (select c.citizenid, true as isactive, false as ismultilogin from kaveri.citizenloginloginfo c where c.citizenid = _citizenid limit 1);
end if;
end;
$$;


