-- Name: fn_insert_citizenlogininfo_new(bigint, character varying, boolean, boolean); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_citizenlogininfo_new(_citizenid bigint, _publicip character varying, _isactive boolean, _issamesession boolean) RETURNS TABLE(citizenid bigint, isactive boolean, ismultilogin boolean)
    LANGUAGE plpgsql
    AS $$

BEGIN

if((select count(c.*) from kaveri.citizenloginloginfo_new c where c.citizenid = _citizenid and c.isactive=true)>0)
THEN

RETURN QUERY (select b.citizenid, true as isactive, true as ismultilogin from kaveri.citizenloginloginfo_new b where b.citizenid = _citizenid limit 1);

else
insert into kaveri.citizenloginloginfo_new(
	citizenid,
	publicip,
	isactive,
	issamesession) 
values(_citizenid,
	_publicip,
	_isactive,
	_issamesession);

RETURN QUERY (select c.citizenid, true as isactive, false as ismultilogin from kaveri.citizenloginloginfo_new c where c.citizenid = _citizenid limit 1);
end if;
end;
$$;


