--
-- Name: fn_insert_citizenmaster_ekyc(character varying, character varying, smallint, character varying, bigint, character varying, boolean); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_citizenmaster_ekyc(p_loginname character varying, p_firstname character varying, p_gender smallint, p_email character varying, p_phone bigint, p_aadharhash character varying, p_isemailverified boolean) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_citizenid BIGINT;
BEGIN
    INSERT INTO kaveri.citizenmaster (
        loginname, firstname, gender, email, phone, aadharhash, 
        isemailverified, ismobileverified, isekycdone,
        middlename, lastname, password, secquestion, secanswer, isloggedin, 
        lstupdusr, permanentaddress, pin, pan, lstupddt, citizenimagepath, 
        invalidlogincount, forgotpasswordcount, k1k2_flag, isinstitution, bankid, branchid
    )
    VALUES (
        p_loginname, p_firstname, p_gender, p_email, p_phone, p_aadharhash, 
        p_isemailverified, TRUE, TRUE,
        NULL, '', '', 1, '', null, 
        NULL, NULL, NULL, NULL, current_timestamp, NULL, 
        0, 0, 2, false, NULL, NULL
    )RETURNING citizenid INTO v_citizenid;
    
    RETURN v_citizenid;
END;
$$;


