--

CREATE FUNCTION kaveri.fn_insert_citizeotpdetails(_citizenid bigint, _otp smallint, _otpcount integer) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare 
v_cnt integer;
v_citizenid bigint;
begin
select count(*) into v_cnt from kaveri.citizeotpdetails where citizenid = _citizenid;
if v_cnt = 1 then
delete from kaveri.citizeotpdetails where citizenid = _citizenid;
end if;

insert into  kaveri.citizeotpdetails (citizenid,
    otp ,
	otptime,
    otpcount,
	incorrectotpcnt	 )
values
(
_citizenid,
    _otp ,
	CURRENT_TIMESTAMP,
    _otpcount,
	0
) returning citizenid into v_citizenid;

return v_citizenid;
end;
$$;


