--
-- Name: fn_insert_constructionratedetails(kaveri.constructionratedetails_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_constructionratedetails(p_constructionratedetails kaveri.constructionratedetails_input[] DEFAULT NULL::kaveri.constructionratedetails_input[]) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
Declare

v_arry_constructionratedetails kaveri.constructionratedetails_input[];
v_cnt integer;
v_valid bigint;
begin
		if(p_constructionratedetails is not null and array_length(p_constructionratedetails,1)>0 ) then
				FOR v_arry_constructionratedetails IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_constructionratedetails)) 
					loop
						v_cnt:= 0;
						Select count(*) into v_cnt from kaveri.val_constructionratedetails where constructiondetailsid in 
						(select a._constructiondetailsid from unnest(v_arry_constructionratedetails) a) ;
						if v_cnt = 0 then
							insert into kaveri.val_constructionratedetails (
								constructiondetailsid,
                                constructiontypeid,
                                gfarea,
                                agfarea,
                                rate,
                                verified,
                                valuationid,
                                 srocode,
                                 regsrocode
								)
								select 
								 nextval('kaveri.val_constructionratedetails_seq'),
								 a._constructiontypeid,
                                a._gfarea,
                                a._agfarea,
                                a._rate,
                                a._verified,
                                a._valuationid,
                                 a._srocode,
                                 a._regsrocode
								from unnest(v_arry_constructionratedetails)	a
								 returning valuationid::bigint into v_valid;
						else
							update kaveri.val_constructionratedetails set
												 constructiontypeid=a._constructiontypeid,
                                                 gfarea=a._gfarea,
                                                 agfarea=a._agfarea,
                                                 rate=a._rate,
                                                 verified=a._verified,
                                                 valuationid=a._valuationid,
                                                 srocode=a._srocode,
                                                 regsrocode=a._regsrocode
												 from unnest(v_arry_constructionratedetails) a where constructiondetailsid in 
														 (select a._constructiondetailsid from unnest(v_arry_constructionratedetails) a) 
														 RETURNING valuationid::bigint into v_valid;
						end if;
						
					end loop;
			end if;
Return v_valid;
   END;
$$;


ALTER FUNCTION kaveri.fn_insert_constructionratedetails(p_constructionratedetails kaveri.constructionratedetails_input[]) OWNER TO csgadmin;

--
-- Name: fn_insert_court_info(kaveri.courtorder_input[], kaveri.bannedproperties_input[], kaveri.bannedpropertynumbers_input[], kaveri.bannedparties_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_court_info(p_courtorder kaveri.courtorder_input[], p_courtproperties kaveri.bannedproperties_input[], p_courtpropertynumberdetails kaveri.bannedpropertynumbers_input[], p_courtparty kaveri.bannedparties_input[]) RETURNS text
    LANGUAGE plpgsql
    AS $$

DECLARE
   v_ordernumber text;
   v_success boolean;
   v_srocode integer;
   v_iscancelled boolean;
  v_court_arry kaveri.courtorder_input[];
  v_courtproperties_arry kaveri.bannedproperties_INPUT[];
   v_txt text;
   v_courtorderid bigint;
   v_cnt integer;
BEGIN

if(p_courtorder is not null and array_length(p_courtorder,1)>0 ) then 

--	Select count(*) into v_cnt from kaveri.courtorders where COURTORDERID in 
--								(select a._orderid from unnest(p_courtorder) a) ;
							
Select count(*) into v_cnt from kaveri.courtorders where COURTORDERID = ((p_courtorder)[1])._orderid and srocode= ((p_courtorder)[1])._srocode ;
	
--	select a._iscancelled into v_iscancelled from unnest(p_courtorder) a ;
			
	if (v_cnt = 0 and (((p_courtorder)[1])._iscancelled=false or ((p_courtorder)[1])._iscancelled is null)) then
		  INSERT INTO kaveri.courtorders(srocode,
		ordernumber,issuingauthority,issueddate,casetype,description
		,iscancelled,isinforce,username,orderentrydatetime)
			select 	a._srocode,
			a._ordernumber,a._issuingauthority,a._issueddate,a._casetype,a._description
			,'false','true',a._username,current_timestamp
			from unnest(p_courtorder) a
			 RETURNING COURTORDERID::text,ordernumber::text into v_courtorderid,v_ordernumber;
	 elsif (((p_courtorder)[1])._iscancelled = 'true') then
			 	update kaveri.courtorders set
			dateofcancellation = coalesce(a._dateofcancellation,dateofcancellation)
		,iscancelled =((p_courtorder)[1])._iscancelled --v_iscancelled
		,isinforce = 'false'
		,cancellationdate = coalesce(a._cancellationdate,cancellationdate)
		,cancellationremarks = coalesce(a._cancellationremarks,cancellationremarks)
		,username = a._username
			from unnest(p_courtorder) a
		  where (COURTORDERID) in 
		(select a._orderid from unnest(p_courtorder) a) and srocode=(select b._srocode from unnest(p_courtorder) b)
		 RETURNING null,ordernumber::text into v_courtorderid,v_ordernumber;		 
	else
		  update kaveri.courtorders set
			issuingauthority = coalesce(a._issuingauthority,issuingauthority)
		,issueddate = coalesce(a._issueddate,issueddate)
		,casetype= coalesce(a._casetype,casetype)
		,description = coalesce(a._description,description)
		,isinforce = coalesce(a._isinforce,isinforce)
		,username = a._username
			from unnest(p_courtorder) a
		  where (COURTORDERID) in 
		(select a._orderid from unnest(p_courtorder) a) and srocode=(select b._srocode from unnest(p_courtorder) b)
		 RETURNING COURTORDERID::text,ordernumber::text into v_courtorderid,v_ordernumber;
		 end if;
		 
		 if(v_courtorderid is not null and v_courtorderid > 0) then
			   if(p_courtproperties is not null and array_length(p_courtproperties,1)>0 ) then
				   --call court propertyinsert
				   begin
				   select kaveri.fn_insert_property_details_court(v_courtorderid,p_courtproperties,p_courtpropertynumberdetails) into v_success ;
				   exception when others then
					RAISE; --EXCEPTION 'Courtorder --> %', v_ordernumber
						--USING HINT = 'Please check property data';
						end;
			   end if;
		 		if(p_courtparty is not null and array_length(p_courtparty,1)>0 ) then
				   --call court partyinsert
					begin
				   select kaveri.fn_insert_party_info_court(v_courtorderid,p_courtparty) into v_success ;
				   exception when others then
					RAISE;-- EXCEPTION 'Courtorder --> %', v_ordernumber
						--USING HINT = 'Please check party data';
						end;
			   end if;
		 end if;

 end if;
	return v_ordernumber;
	
END;
$$;


ALTER FUNCTION kaveri.fn_insert_court_info(p_courtorder kaveri.courtorder_input[], p_courtproperties kaveri.bannedproperties_input[], p_courtpropertynumberdetails kaveri.bannedpropertynumbers_input[], p_courtparty kaveri.bannedparties_input[]) OWNER TO csgadmin;

