-- Name: fn_insert_dataentry_documentmaster(bigint, integer, bigint, character varying, character varying, character varying, numeric, timestamp without time zone, numeric, timestamp without time zone, numeric, numeric, timestamp without time zone, timestamp without time zone, character varying, character varying, character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_dataentry_documentmaster(_dataentryid bigint, _srocode integer, _documentid bigint, _refusalscribe character varying, _refusalreasons character varying, _dailyregrefusalsummons character varying, _dailyregtreasamt numeric, _dailyregtreasdate timestamp without time zone, _dailyregmutfee numeric, _dailyregmutfeedate timestamp without time zone, _impdefstamp numeric, _imppenal numeric, _impdycomrref timestamp without time zone, _impdycomrret timestamp without time zone, _imppurp character varying, _imphowdis character varying, _inx4rem character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare
v_cnt bigint;
v_dataentryid bigint;
begin 
select count(*) into v_cnt from kaveri.dataentry_documentmaster where 
dataentryid = _dataentryid;
/* if dataentryid does not exist*/
if v_cnt = 0 then
insert into kaveri.dataentry_documentmaster (
srocode,
documentid,
refusalscribe,
refusalreasons,
dailyregrefusalsummons,
dailyregtreasamt,
dailyregtreasdate,
dailyregmutfee,
dailyregmutfeedate,
impdefstamp,
imppenal,
impDyComrRef,
impDyComrRet,
impPurp,
imphowdis,
inx4rem 
) values 
(
_srocode,
_documentid,
_refusalscribe,
_refusalreasons,
_dailyregrefusalsummons,
_dailyregtreasamt,
_dailyregtreasdate,
_dailyregmutfee,
_dailyregmutfeedate,
_impdefstamp,
_imppenal,
_impDyComrRef,
_impDyComrRet,
_impPurp,
_imphowdis,
_inx4rem 
) returning dataentryid into v_dataentryid;
else  /*  if dataentryid  exist  */
update kaveri.dataentry_documentmaster 
set 
refusalscribe=_refusalscribe,
refusalreasons=_refusalreasons,
dailyregrefusalsummons=_dailyregrefusalsummons,
dailyregtreasamt=_dailyregtreasamt,
dailyregtreasdate=_dailyregtreasdate,
dailyregmutfee=_dailyregmutfee,
dailyregmutfeedate=_dailyregmutfeedate,
impdefstamp=_impdefstamp,
imppenal=_imppenal,
impDyComrRef=_impDyComrRef,
impDyComrRet=_impDyComrRet,
impPurp=_impPurp,
imphowdis=_imphowdis,
inx4rem=_inx4rem 
where dataentryid = _dataentryid
 returning dataentryid into v_dataentryid;
end if;
return v_dataentryid;
end;
$$;


ALTER FUNCTION kaveri.fn_insert_dataentry_documentmaster(_dataentryid bigint, _srocode integer, _documentid bigint, _refusalscribe character varying, _refusalreasons character varying, _dailyregrefusalsummons character varying, _dailyregtreasamt numeric, _dailyregtreasdate timestamp without time zone, _dailyregmutfee numeric, _dailyregmutfeedate timestamp without time zone, _impdefstamp numeric, _imppenal numeric, _impdycomrref timestamp without time zone, _impdycomrret timestamp without time zone, _imppurp character varying, _imphowdis character varying, _inx4rem character varying) OWNER TO csgadmin;

