--

CREATE FUNCTION kaveri.fn_insert_dec_drordermaster(v_note_details kaveri.dec_drordermaster_type) RETURNS bigint
    LANGUAGE plpgsql
    AS $_$


DECLARE 
v_orderid bigint;
v_cnt bigint;
v_cnt1 bigint;
v_noteid bigint;
v_propertyid bigint;
v_note_preparedpart text;
v_note_enteredpart text;
--note_arry $1%type;

begin
--select count(*) from kaveri.dec_drordermaster where orderid = 238;
select count(*) into v_cnt from kaveri.dec_drordermaster where orderid = v_note_details._orderid;

raise notice 'v_cnt is %',v_cnt;

if v_cnt = 0 then

raise notice 'inside insert %',v_cnt;

insert into kaveri.dec_drordermaster 
(
orderid,
districtcode,
srocode,
documentid,
ordernumber,
orderdate,
relativepath,
statuscode,
correctionnote,
documentrescan,
userid,
absolutefilepath,
rescannoofpages,
sroid,
finalregistrationnumber
) values
(
 nextval('kaveri.orderid_seq'),
v_note_details._districtcode,
v_note_details._srocode,
v_note_details._documentid,
v_note_details._ordernumber,
v_note_details._orderdate,
v_note_details._relativepath,
1,
v_note_details._correctionnote,
v_note_details._documentrescan,
v_note_details._userid,
v_note_details._AbsoluteFilePath,
v_note_details._rescannoofpages,
v_note_details._sroid,
v_note_details._finalregistrationnumber
)
returning orderid into v_orderid;

raise notice 'orderid is %',v_orderid;


else
if v_note_details._ordernumber is not null and length(trim(v_note_details._ordernumber)) > 0 then

raise notice 'inside update, wrong path!!, order number is %',v_note_details._ordernumber;
update kaveri.dec_drordermaster
set 
districtcode=v_note_details._districtcode,
srocode=v_note_details._srocode,
documentid=v_note_details._documentid,
ordernumber=v_note_details._ordernumber,
orderdate=v_note_details._orderdate,
relativepath=v_note_details._relativepath,
correctionnote=v_note_details._correctionnote,
documentrescan=v_note_details._documentrescan,
userid=v_note_details._userid,
absolutefilepath=v_note_details._absolutefilepath,
rescannoofpages=v_note_details._rescannoofpages,
sroid=v_note_details._sroid,
statuscode=1
where orderid=v_note_details._orderid
returning orderid into v_orderid;
end if;
end if;

select distinct b.note_preparedpart,b.note_enteredpart 
into  v_note_preparedpart, v_note_enteredpart from unnest(v_note_details._dec_drpndnote_type) b;

if v_note_enteredpart is not null then
select distinct b.propertyid into v_propertyid
from unnest(v_note_details._dec_drpndnote_type)b;

if v_propertyid is null then
raise notice 'property id is null';

select distinct b.note_preparedpart,b.note_enteredpart 
into  v_note_preparedpart, v_note_enteredpart from unnest(v_note_details._dec_drpndnote_type) b;

select count(*) into v_cnt from kaveri.dec_drpndnote where orderid=case when v_note_details._orderid is null then v_orderid else v_note_details._orderid end;

if v_cnt=0 then
insert into  kaveri.dec_drpndnote 
(
    noteid,
    orderid,
    propertyid,
	note_preparedpart,
    note_enteredpart,
	userid
)
select
   nextval('kaveri.noteid_seq'),
   case when v_note_details._orderid is null then v_orderid else v_note_details._orderid end,
   a.propertyid,
   a.note_preparedpart,
   a.note_enteredpart,
   v_note_details._sroid
from unnest(v_note_details._dec_drpndnote_type)	a;
	return case when v_note_details._orderid is null then v_orderid else v_note_details._orderid end;

else

update kaveri.dec_drpndnote c
set note_preparedpart=v_note_preparedpart,
    note_enteredpart=v_note_enteredpart
    where orderid=case when v_note_details._orderid is null then v_orderid else v_note_details._orderid end;
    return case when v_note_details._orderid is null then v_orderid else v_note_details._orderid end;

raise notice 'update evry record for this order for note';
end if;

else

select count(*) into v_cnt from kaveri.dec_drpndnote a where (a.noteid,a.propertyid) in 
(select b.noteid,b.propertyid from unnest(v_note_details._dec_drpndnote_type)b);  --and a.noteid = _noteid;

raise notice 'count for this note and order and property %',v_cnt;

if v_cnt = 0 then
insert into  kaveri.dec_drpndnote 
(
    noteid,
    orderid,
    propertyid,
	note_preparedpart,
    note_enteredpart,
	userid
)
select
   nextval('kaveri.noteid_seq'),
  case when v_note_details._orderid is null then v_orderid else v_note_details._orderid end,
   a.propertyid,
   a.note_preparedpart,
   a.note_enteredpart,
   v_note_details._sroid
from unnest(v_note_details._dec_drpndnote_type)	a;
	return case when v_note_details._orderid is null then v_orderid else v_note_details._orderid end;
else 
update kaveri.dec_drpndnote c
set note_preparedpart=b.note_preparedpart,
    note_enteredpart=b.note_enteredpart
    from unnest(v_note_details._dec_drpndnote_type) b
    where c.noteid=b.noteid and b.propertyid=c.propertyid;
    return case when v_note_details._orderid is null then v_orderid else v_note_details._orderid end;
end if;
end if;
end if;




/*
end if;

select count(*) into v_cnt from kaveri.dec_drpndnote a inner join 
kaveri.dec_drordermaster b on a.orderid = b.orderid and a.orderid = _orderid ;  --and a.noteid = _noteid;

if v_cnt = 0 then

insert into  kaveri.dec_drpndnote 
(
    noteid,
    orderid,
    propertyid,
	note_preparedpart,
    note_enteredpart,
	userid
)
select
   nextval('kaveri.noteid_seq'),
   v_orderid,
   a.propertyid,
   a.note_preparedpart,
   a.note_enteredpart,
   v_note_details._userid
from unnest(v_note_details._dec_drpndnote_type)	a;
 --returning orderid into v_orderid;
 */


--select count(*) into v_cnt1 from kaveri.dec_drordermaster where orderid = v_note_details._orderid;

--if v_cnt1 = 1 then

/*update kaveri.dec_drordermaster
set
   sroid = v_note_details._sroid,
   statuscode = 1
   
where 
   orderid = v_note_details._orderid;*/-- inner join 
--kaveri.dec_drordermaster b on a.orderid = b.orderid and a.orderid = v_note_details._orderid


 
--end if;
return v_orderid;

end;
$_$;


