--
-- Name: fn_insert_dec_drpndnote(integer, bigint, bigint, character varying, character varying, bigint); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_dec_drpndnote(_noteid integer, _orderid bigint, _propertyid bigint, _note_preparedpart character varying, _note_enteredpart character varying, _userid bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE 
v_orderid bigint;
v_cnt bigint;
begin
select count(*) into v_cnt from kaveri.dec_drpndnote a inner join 
kaveri.dec_drordermaster b on a.orderid = b.orderid and a.noteid = _noteid;
if v_cnt = 0 then
insert into  kaveri.dec_drpndnote 
(
    noteid,
    orderid,
    propertyid,
	note_preparedpart,
    note_enteredpart,
	userid
)
values
(
   nextval('kaveri.noteid_seq'),
   _orderid,
   _propertyid,
	_note_preparedpart,
   _note_enteredpart,
   _userid
) returning orderid into v_orderid;
end if;
return v_orderid;
end;
$$;


