--
-- Name: fn_insert_departmentloginloginfo(bigint, integer, character varying, bigint, character varying, bigint, character varying, character varying, character varying, boolean, character varying, character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_departmentloginloginfo(_userid bigint, _srocode integer, _publicip character varying, _localport bigint, _localip character varying, _remoteport bigint, _macaddress character varying, _location character varying, _country character varying, _isactive boolean, _jwttoken character varying, _reftoken character varying) RETURNS TABLE(userid bigint, isactive boolean, ismultilogin boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
v_isactive character varying;
v_array character varying[];
v_citizenid character varying;
BEGIN

if((select count(c.*) from kaveri.departmentloginloginfo c where c.userid = _userid and c.isactive=true)>0) 
THEN
 update kaveri.departmentloginloginfo cll set ismultilogin=true where cll.userid = _userid and cll.isactive=true;
-- commit;
 	insert into kaveri.departmentloginloginfo(c_userid,userid,srocode ,	localip ,localport,publicip ,remoteport ,macaddress ,location ,country,isactive ,jwttoken,reftoken)
	values(NEXTVAL('kaveri.departmentloginlog'),_userid,_srocode,_localip,_localport,_publicip,_remoteport,_macaddress,_location,_country,_isactive,_jwttoken,_reftoken);

RETURN QUERY ( select b.userid, true as isactive, true as ismultilogin from kaveri.departmentloginloginfo b where b.userid = _userid limit 1);

else
	insert into kaveri.departmentloginloginfo(c_userid,userid,srocode ,	localip ,localport,publicip ,remoteport ,macaddress ,location ,country,isactive ,jwttoken,reftoken)
	values(NEXTVAL('kaveri.departmentloginlog'),_userid,_srocode,_localip,_localport,_publicip,_remoteport,_macaddress,_location,_country,_isactive,_jwttoken,_reftoken);

RETURN QUERY (select c.userid, true as isactive, false as ismultilogin from kaveri.departmentloginloginfo c where c.userid = _userid limit 1);
end if;
end;
$$;


ALTER FUNCTION kaveri.fn_insert_departmentloginloginfo(_userid bigint, _srocode integer, _publicip character varying, _localport bigint, _localip character varying, _remoteport bigint, _macaddress character varying, _location character varying, _country character varying, _isactive boolean, _jwttoken character varying, _reftoken character varying) OWNER TO csgadmin;

--
-- Name: fn_insert_departmentloginloginfo_new(bigint, integer, character varying, boolean); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_departmentloginloginfo_new(_userid bigint, _srocode integer, _publicip character varying, _isactive boolean) RETURNS TABLE(userid bigint, ismultilogin boolean)
    LANGUAGE plpgsql
    AS $$

BEGIN

if((select count(c.*) from kaveri.departmentloginloginfo_new c where c.userid = _userid and c.isactive=true)>0) 
THEN
RETURN QUERY ( select b.userid, true as ismultilogin from kaveri.departmentloginloginfo_new b where b.userid = _userid limit 1);
-- commit;

else
	
	INSERT INTO kaveri.departmentloginloginfo_new(
	c_userid, userid, srocode, publicip, isactive, logindatetime, logoutdatetime)
	VALUES (NEXTVAL('kaveri.departmentloginlog_new'), _userid, _srocode, _publicip, _isactive, Current_timestamp, null);
	
RETURN QUERY (select c.userid, false as ismultilogin from kaveri.departmentloginloginfo_new c where c.userid = _userid limit 1);
end if;
end;
$$;


ALTER FUNCTION kaveri.fn_insert_departmentloginloginfo_new(_userid bigint, _srocode integer, _publicip character varying, _isactive boolean) OWNER TO postgres;

