--
-- Name: fn_insert_deptfeesrequired(kaveri.feesrequired_input[], boolean); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_deptfeesrequired(fees_arry kaveri.feesrequired_input[], sroupdate boolean) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
DECLARE
   id_val integer;
   fees_arry $1%type;
   v_cnt integer;
   rows_effected integer := 0;
   v_sroupdate boolean;
   v_row_effect integer;
BEGIN

  FOR fees_arry IN (SELECT kaveri.fn_fetch_1d_arrayofarray($1))
     loop
   Select count(*) into v_cnt from kaveri.feesrequired where (applicationnumber,feerulecode) in 
(select a._applicationnumber,a._feerulecode from unnest(fees_arry) a);
  if (v_cnt > 0) then
  	if(sroupdate) then
	rows_effected := rows_effected+1;
	update kaveri.feesrequired set --documentid = _documentid,
    --feerulecode = _feerulecode,
    --isexempted = _isexempted,
    --exemptdescription = _exemptdescription,
	--isactive=_isactive,
    --feecalculationstring=_feecalculationstring, 
    --srocode=_srocode, 
	--isonline=_isonline,
	sroamountrequired = _amountrequired 
    --applicationnumber = _applicationnumber,
	--propertyid = _propertyid
	from unnest(fees_arry)
	where (applicationnumber,feerulecode) in 
(select a._applicationnumber,a._feerulecode from unnest(fees_arry) a) 
RETURNING feerulecode::integer into id_val;

else
rows_effected := rows_effected+1;
update kaveri.feesrequired set --documentid = _documentid,
 --   feerulecode = _feerulecode,
    --isexempted = _isexempted,
   -- exemptdescription = _exemptdescription,
--	isactive=_isactive,
  -- feecalculationstring=_feecalculationstring, 
   -- srocode=_srocode, 
--	isonline=_isonline,
	sfdaamountrequired = _amountrequired 
--    applicationnumber = _applicationnumber,
--	propertyid = _propertyid
	from unnest(fees_arry)
	where (applicationnumber,feerulecode) in 
(select a._applicationnumber,a._feerulecode from unnest(fees_arry) a) 
RETURNING feerulecode::integer into id_val;
    end if;
	end if;
    end loop;
	
	select rows_effected into v_row_effect;
	
	return v_row_effect;
end;
$_$;


ALTER FUNCTION kaveri.fn_insert_deptfeesrequired(fees_arry kaveri.feesrequired_input[], sroupdate boolean) OWNER TO csgadmin;

