CREATE FUNCTION kaveri.fn_insert_deptotpdetails(_userid bigint, _otp smallint, _otpcount integer) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare 
v_cnt integer;
v_userid bigint;
begin
select count(*) into v_cnt from kaveri.deptotpdetails where userid = _userid;
if v_cnt = 1 then
delete from kaveri.deptotpdetails where userid = _userid;
end if;

insert into  kaveri.deptotpdetails (userid,
    otp ,
	otptime,
    otpcount,
	incorrectotpcnt	 )
values
(
_userid,
    _otp ,
	CURRENT_TIMESTAMP,
    _otpcount,
	0
) returning userid into v_userid;

return v_userid;
end;
$$;


