--
-- Name: fn_insert_document_paths(character varying, text, text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_document_paths(_applicationnumber character varying, _uploaddocannexurepath text, _uploaddocdeedpath text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Check if the row exists
    IF EXISTS (
        SELECT 1 
        FROM kaveri.documentmaster
        WHERE applicationnumber = _applicationnumber
    ) THEN
        UPDATE kaveri.documentmaster
        SET 
            uploaddocannexurepath = _uploaddocannexurepath,
            uploaddocdeedpath = _uploaddocdeedpath,
            --uploadsummarydocpath = _uploadsummarydocpath,
            lstupddate = NOW(),
			isprintendorsement = true,
			isuploaddocuments = true,
			ispaymentdetails = true,
			verified = true
        WHERE applicationnumber = _applicationnumber;
    ELSE
        RAISE EXCEPTION 'No document paths found for application number: %', _applicationnumber;
    END IF;
END;
$$;


ALTER FUNCTION kaveri.fn_insert_document_paths(_applicationnumber character varying, _uploaddocannexurepath text, _uploaddocdeedpath text) OWNER TO postgres;

