--
-- Name: fn_insert_documentmaster_pending_regis(character varying, character varying, bigint, bigint, timestamp without time zone, bigint, text, timestamp without time zone, character varying, integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_documentmaster_pending_regis(_applicationnumber character varying, _finalregnumber character varying, _srocode bigint, _regarticlecode bigint, _stamp5datetime timestamp without time zone, _bookid bigint, _remarks text, _executiondatetime timestamp without time zone, _pendingdocumentnumber character varying DEFAULT NULL::character varying, _pagecount integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$


declare 
v_cnt int;
v_docid int;
v_isbefore2003 boolean;
v_currentstatus character varying;
begin 

select currentstatus into v_currentstatus from kaveri.applicantapplicationdetails a where applicationnumber =_applicationnumber ;

if(v_currentstatus='CD101' or v_currentstatus='CD119' or v_currentstatus='CD118')	
	then
	select isbefore2003 into v_isbefore2003 from kaveri.minutebook_data md where applicationnumber = _applicationnumber ;
	
	select count(*) into v_cnt from kaveri.documentmaster where -- finalregistrationnumber=_finalregnumber 
	applicationnumber = _applicationnumber
	and srocode=_srocode ; 
	
	if (v_cnt=0)
	then
	insert into kaveri.documentmaster (documentid,applicationnumber,finalregistrationnumber,srocode,regarticlecode,stamp5datetime,bookid, executiondatetime,presentdatetime ,pendingdocumentnumber)
	values (nextval('kaveri.document_seq'),_applicationnumber,_finalregnumber,_srocode,_regarticlecode,_stamp5datetime,_bookid,_executiondatetime,_executiondatetime,concat('P-',_pendingdocumentnumber))
	returning documentid into v_docid;
	if not found then 
		raise exception 'Something went wrong! DocumentMaster insertion failed.'; 
	end if;

--update kaveri.propertymaster set documentid = v_docid,
--regsrocode=_srocode
--where applicationnumber = _applicationnumber; -- Krishna goutam changes 26-04-2023

update kaveri.propertymaster 
set documentid = v_docid,
	sroconsideration = consideration,
	sromarketvalue = marketvalue,
	regsrocode=_srocode,
	sronoofscanpages = _pagecount,
	noofscanpages = _pagecount
where applicationnumber = _applicationnumber;
 if not found then 
		raise exception 'Something went wrong! PropertyMaster update failed.'; 
	end if;

update kaveri.propertyschedules set srocode=_srocode where applicationnumber = _applicationnumber;
-- if not found then 
--		raise exception 'Something went wrong! Propertyschedules update failed.'; 
--	end if;

update kaveri.partyinfo set documentid = v_docid,
srocode=_srocode where applicationnumber = _applicationnumber;
 if not found then 
		raise exception 'Something went wrong! partyinfo update failed.'; 
	end if;

update kaveri.applicantapplicationdetails set srocode=_srocode,remarks=_remarks 
where applicationnumber = _applicationnumber;
 if not found then 
		raise exception 'Something went wrong! applicantapplicationdetails update failed.'; 
	end if;

--update kaveri.minutebook_data b 
--set reasonid =rr.reasonid_k1 from kaveri.reasonmaster_k1 rr where b.reasonid =rr.reasonid and b.applicationnumber =_applicationnumber;

--update kaveri.minutebook_data b 
--set reasonid = rr.reasonid from kaveri.reasonmaster_k1 rr where b.reasonid = rr.reasonid_k1 and b.applicationnumber = _applicationnumber;

-- if not found then 
--		raise exception 'Something went wrong! minutebook_data update failed.'; 
--	end if;

if v_isbefore2003 = true then

	update kaveri.minutebook_data b 
	set srocode = _srocode
	where b.applicationnumber = _applicationnumber;

--else
--	update kaveri.minutebook_data b 
--	set reasonid = rr.reasonid
--	from kaveri.reasonmaster_k1 rr where b.reasonid = rr.reasonid_k1 and b.applicationnumber = _applicationnumber;

end if;
	end if;
end if;
return v_docid;
	
end;
$$;


ALTER FUNCTION kaveri.fn_insert_documentmaster_pending_regis(_applicationnumber character varying, _finalregnumber character varying, _srocode bigint, _regarticlecode bigint, _stamp5datetime timestamp without time zone, _bookid bigint, _remarks text, _executiondatetime timestamp without time zone, _pendingdocumentnumber character varying, _pagecount integer) OWNER TO csgadmin;

--
-- Name: fn_insert_documentsummary(text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_documentsummary(_applicationnumber text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
declare 
v_cnt int;
v_srocode int;
v_jsonvalues text;
v_jsonval json;
BEGIN

select count(*) into v_cnt from kaveri.documentsummary where applicationnumber=_applicationnumber;	


select json_value into v_jsonvalues from kaveri.documentsummary where applicationnumber=_applicationnumber;	

select srocode into v_srocode from kaveri.documentmaster d where applicationnumber =_applicationnumber;
if (v_cnt=0) 
then 


insert into kaveri.documentsummary(applicationnumber,json_value)
select _applicationnumber,*  from kaveri.fn_fetch_documentsummary_json(_applicationnumber,v_srocode);

elsif (v_cnt>0)
then
select * into v_jsonval from  kaveri.fn_fetch_documentsummary_json(_applicationnumber,v_srocode);
update kaveri.documentsummary set json_value = v_jsonval::text
where applicationnumber =_applicationnumber
;

end if;

return true;
end;

$$;


ALTER FUNCTION kaveri.fn_insert_documentsummary(_applicationnumber text) OWNER TO postgres;

