--
-- Name: fn_insert_ec_applicationdetail(kaveri.ec_application_type); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_ec_applicationdetail(v_ec_applicationdetails kaveri.ec_application_type) RETURNS TABLE(applicationnumber character varying, eecid bigint)
    LANGUAGE plpgsql
    AS $_$
DECLARE
id_val bigint;
    --inserted_id integer;
	 cit_id text;
   --property_arry $1%type;
   v_party_arry record;--p_propertynodetails%type;
   v_ecrequiredfees record; --p_ecrequiredfees%type;
--  v_ec_applicationdetails p_ec_application%type;
   v_ecpropertynoid bigint;
   var_r record;
  -- v_pid bigint[];
--  v_pid text[];
v_cnt integer;
v_ecid bigint;
v_count integer;
v_schid bigint;
v_cnt1 integer;
v_shortnamee text;
v_nomenclature text;
v_scheduletype text;
v_finyear text;
v_applicationnumber text;
_inserted_id text;
l_now text;
v_length int;
v_lengths int;
v_year text;
v_month text;
BEGIN
--select count(*) into v_count from kaveri.ec_applicationdetails where ecid in (0);

select count(*) into v_count from kaveri.ec_applicationdetails e where e.applicationnumber=v_ec_applicationdetails._applicationnumber;
/*select shortnamee into v_shortnamee from kaveri.sromaster where srocode = _kaverisrocode;
select nomenclature into v_nomenclature from kaveri.servicesmaster where serviceid = 13;
select distinct scheduletype into v_scheduletype from kaveri.propertyschedules where scheduletype = _scheduletype;
select lpad(nextval('kaveri.EC_applicationnumber_seq')::text,5,'0') into _inserted_id;
select cast(to_char(now(),'YYYY')as bigint)-1 ||'-'|| cast(to_char(now(),'YY')as bigint) into l_now;
v_applicationnumber := v_shortnamee  ||'-'||v_nomenclature ||'-'||v_scheduletype ||'-'||_inserted_id||'-'||l_now;*/



