--
-- Name: fn_insert_ec_applicationdetail_requiredfees(kaveri.requiredfees[]); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_ec_applicationdetail_requiredfees(v_ec_requiredfees kaveri.requiredfees[] DEFAULT NULL::kaveri.requiredfees[]) RETURNS bigint
    LANGUAGE plpgsql
    AS $_$
DECLARE
v_ecrequiredfees record;
v_cnt int;
v_ecid bigint;

BEGIN

--select applicationnumber into v_applicationnumber from kaveri.ec_applicationdetails where ecid in (v_ec_requiredfees._ecid);

--FOR v_ecrequiredfees IN (SELECT * from unnest(v_ec_requiredfees))
--loop

--raise notice '%', v_ecrequiredfees;

select count(*) into v_cnt from kaveri.ec_requiredfees where ecid in (select s._ecid from unnest($1) s);

--raise notice '%', v_cnt;
v_ecid:=0;

if v_cnt = 0 then 
		INSERT INTO kaveri.ec_requiredfees( 
		requiredfeeid,
		ecid,
		feeruleid,
		payableamount,
		ispaid,
		serviceid,
		feedescription
		)
		select  nextval('kaveri.ec_requiredfees_seq'),
		_ecid,
		_feeruleid,
		_payableamount,
		_ispaid,
		_serviceid,
		_feedescription
		from unnest($1);
		GET DIAGNOSTICS v_ecid = ROW_COUNT; 
		--from unnest(v_ecrequiredfees) a
			 --returning 0::bigint into v_ecid;
	if not found then 
		raise exception 'Something went wrong! ec_requiredfees insertion failed.'; 
	end if;
	 else
	 update kaveri.ec_requiredfees set
	 ecid=a._ecid,
   feeruleid=a._feeruleid,
   payableamount=a._payableamount,
   ispaid=a._ispaid,
   serviceid=a._serviceid,
   feedescription=a._feedescription
	from unnest($1) a 
	where requiredfeeid in 
			 (a._requiredfeeid );
			GET DIAGNOSTICS v_ecid = ROW_COUNT;			 
			 --RETURNING 1::bigint into v_ecid;
	if not found then 
		raise exception 'Something went wrong! ec_requiredfees update failed.'; 
	end if;
	 end if;
	--v_pid := array_append(v_pid,v_ecid);
--	end loop;
return v_ecid;
end;
$_$;


