--
-- Name: fn_insert_ec_certificate(integer, character varying, integer, character varying, bigint, timestamp without time zone, timestamp without time zone, integer, bigint, boolean, text, character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_ec_certificate(_pagecount integer, _applicationnumber character varying, _srocode integer, _currentstatus character varying, _sfdaid bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _certificatetype integer, _userid bigint, _isnec boolean, _certificatefile text, _opflag character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE 
v_ecid bigint;
v_shortnamee text;
v_cnt integer;
_inserted_id text;
l_now text;
v_certificatenumber  character varying; -- text;
v_sessionid bigint;
v_totalamount numeric;
v_applicationid  bigint;
v_srocode integer;
v_certificateid bigint;
v_month integer;
begin

/* generation of certificate number */

-- select shortnamee into v_shortnamee from kaveri.sromaster where srocode = _srocode;
--select nomenclature into v_nomenclature from kaveri.servicesmaster where serviceid = 13;
--select distinct scheduletype into v_scheduletype from kaveri.propertyschedules where scheduletype = _scheduletype;

--select lpad(nextval('kaveri.EC_applicationnumber_seq')::text,6,'0') into _inserted_id;

/*
SELECT EXTRACT(MONTH FROM now()) into v_month;
if v_month < 4 then
select cast(to_char(now(),'YYYY')as bigint)-1 ||'-'|| cast(to_char(now(),'YY')as bigint) into l_now;
else
select cast(to_char(now(),'YYYY')as bigint) ||'-'|| cast(to_char(now(),'YY')as bigint)+1 into l_now;
end if;

v_certificatenumber := v_shortnamee  ||'-'||'A'||'-'||_inserted_id||'-'||l_now;

*/

select count(*) into v_cnt from kaveri.applicantapplicationdetails 
where applicationnumber = _applicationnumber;

--Get the EC ID for the given application number
select ecid , certificatenumber
into v_ecid , v_certificatenumber
from kaveri.ec_applicationdetails where applicationnumber=_applicationnumber ;

--returning certificatenumber into v_certificatenumber;

/* update srocode,currentstatus, sfdaid columns in applicantapplicationdetails */

if v_cnt >= 1 then
update kaveri.applicantapplicationdetails 
set srocode = _srocode,
	currentstatus=_currentstatus,
	applicationenddate=current_timestamp, 
	sfdaid=_sfdaid where 
applicationnumber = _applicationnumber returning _srocode into v_srocode;
end if;

/* Insering records into eccertificatemaster using the columns 
sessionid(a), searchdate(a), 
certificatenumber (a) - 3 digit sroname-A-runningseries (6 digit)-financialyear) , 
applicationnumber, fromdate , todate */

/*
insert into kaveri.eccertificatemaster
(sessionid, searchdate, certificatenumber, 
applicationnumber,fromdate,todate,isnec,istransmitted) values 
(nextval('kaveri.sessionid_seq'),CURRENT_TIMESTAMP,v_certificatenumber,_applicationnumber,_fromdate,_todate,
false,false  )
returning sessionid into v_sessionid;
*/

select count(*) into v_cnt from kaveri.eccertificate
where applicationnumber = _applicationnumber;

if v_cnt = 0 then 

insert into kaveri.eccertificate  
(
    --sessionid ,
	certificateid ,
	srocode ,
    searchdate ,
    certificatenumber ,
	certificatedate ,
    applicationnumber ,
    fromdate ,
    todate,
    isnec ,
    searchdescription ,
    uid ,
    liabilitydetails ,
    istransmitted ,
	certificatetype ,
	certificatefile 
)
Values 	
(
nextval('kaveri.certificateid_seq'),
_srocode ,
CURRENT_TIMESTAMP,   --- searchdate
v_certificatenumber,   -- certificatenumber
CURRENT_TIMESTAMP ,   -- certificatedate
_applicationnumber,  -- applicationnumber
_fromdate,	-- fromdate
_todate,	-- todate 
_isnec ,	-- isnec	
null,	-- searchdescription
null,	-- uid
null,   -- liabilitydetails
false ,  -- istransmitted
_certificatetype,    -- certificatetype
_certificatefile    ---  certificatefile

) returning certificateid into v_certificateid; 

else 

Update kaveri.eccertificate  
Set 
   -- certificateid = ,
	srocode = _srocode,
    searchdate = CURRENT_TIMESTAMP,
    certificatenumber = v_certificatenumber,
	certificatedate = CURRENT_TIMESTAMP,
  --  applicationnumber ,
    fromdate = _fromdate ,
    todate = _todate ,
    isnec = _isnec,
    searchdescription = null ,
    uid = null,
    liabilitydetails = null,
    istransmitted = false ,
	certificatetype = _certificatetype ,
	certificatefile = _certificatefile
where applicationnumber = _applicationnumber returning certificateid into v_certificateid; 	
	
end if;

/* certificatenumber (pervious), pagecount, totalamount (ec_requiredfees - total payableamount for ecid )*/

select sum(payableamount) into v_totalamount from  kaveri.ec_requiredfees where ecid = v_ecid;

/*update kaveri.ec_applicationdetails
 set --certificatenumber=v_certificatenumber,
pagecount=_pagecount,
totalamount=v_totalamount 
where ecid = v_ecid returning ecid into v_ecid;*/

if _opflag = 'prepared' then
update kaveri.ec_applicationdetails
 set preparedby = _sfdaid, prepareddatetime = now(),
 pagecount=_pagecount,
totalamount=v_totalamount
 where ecid = v_ecid returning ecid into v_ecid;
elsif _opflag = 'verified' then
update kaveri.ec_applicationdetails
 set comparedby = _sfdaid, compareddatetime = now(),
 pagecount=_pagecount,
totalamount=v_totalamount
 where ecid = v_ecid returning ecid into v_ecid;
elsif _opflag = 'signed' then
update kaveri.ec_applicationdetails
 set signedby = _sfdaid, signeddatetime = now(),
 pagecount=_pagecount,
totalamount=v_totalamount
 where ecid = v_ecid returning ecid into v_ecid;
end if;

/*
select applicationid into v_applicationid 
from kaveri.eccertificates where 
certificateid = v_certificateid and 
srocode = v_srocode;
*/

/*
insert into kaveri.eccertificatepdf
(
    fileid,
    applicationid,
    srocode,
    certificateid,
    certificatefile
)
values
(
nextval('kaveri.fileid_seq'),
v_applicationid,
_srocode,
v_certificateid,
_certificatefile
) returning certificateid into v_certificateid;
*/
return v_certificateid;
end;
$$;


ALTER FUNCTION kaveri.fn_insert_ec_certificate(_pagecount integer, _applicationnumber character varying, _srocode integer, _currentstatus character varying, _sfdaid bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _certificatetype integer, _userid bigint, _isnec boolean, _certificatefile text, _opflag character varying) OWNER TO csgadmin;

--
-- Name: fn_insert_ec_remarks(character varying, character varying, smallint, bigint); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_ec_remarks(_remark character varying, _applicationnumber character varying, _documentstatusid smallint, _userid bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE 
v_ecid bigint;
v_remarkid integer := 0;
v_documentstatusid integer;
begin
--Get the EC ID for the given application number
select ecid into v_ecid from kaveri.ec_applicationdetails where applicationnumber=   _applicationnumber;
/*select documentstatusid  into v_documentstatusid from  kaveri.mas_documentstatustypes a inner join
kaveri.servicesmaster b on a.serviceid = b.serviceid and b.serviceid = 13;*/
if v_ecid is not null then
	insert into kaveri.ec_remarkdetails (
		remarkid,
		remark,
		ecid,
		documentstatusid,
		userid,
		documentstatusdatetime
	) values ( 
		nextval('kaveri.remarkid_seq'),
		_remark,
		v_ecid,
		_documentstatusid,
		_userid,
		CURRENT_TIMESTAMP
	) returning remarkid into v_remarkid;

else

select ccid into v_ecid from kaveri.cc_applicationdetails where applicationnumber=   _applicationnumber;
/*select documentstatusid  into v_documentstatusid from  kaveri.mas_documentstatustypes a inner join
kaveri.servicesmaster b on a.serviceid = b.serviceid and b.serviceid = 13;*/
if v_ecid is not null then
	insert into kaveri.cc_remarkdetails (
		remarkid,
		remark,
		ccid,
		documentstatusid,
		userid,
		documentstatusdatetime
	) values ( 
		nextval('kaveri.cc_remarkid_seq'),
		_remark,
		v_ecid,
		_documentstatusid,
		_userid,
		CURRENT_TIMESTAMP
	) returning remarkid into v_remarkid;

end if;

end if;
return v_remarkid;
end;
$$;


