--
-- Name: fn_insert_ecapplicationdetails(bigint, integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_ecapplicationdetails(_citizenid bigint, _applicationtypeid integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$
DECLARE
	--id_val bigint;
	_applicationnumber text;
	_application text;
	_nomenclature character varying(3);
        _shortname character varying(3);
        _scheduletype varchar(1);
	l_now varchar(7);
	_inserted_id text;
	cit_id text;
   v_txt text;
   v_propertyid bigint;
   v_cnt integer;
   var_r record;
   v_pid text[];
   application_arry $1%type;
begin

l_now := cast(to_char(now(),'YYYY')as bigint)-1 ||'-'|| cast(to_char(now(),'YY')as bigint);

select shortnamee into _shortname from kaveri.sromaster where srocode in 
(select a._srocode from unnest($1) a);

select nomenclature into _nomenclature   from kaveri.servicesmaster where serviceid in
(select a._applicationtypeid from unnest($1) a) ;

select lpad(nextval('kaveri.EC_applicationnumber_seq')::text,5,'0') into _inserted_id;

select distinct scheduletype into _scheduletype from kaveri.propertyschedules 
 where srocode in 
(select a._srocode from unnest($1) a) and scheduletype is not null;

_applicationnumber := _shortname  ||'-'||_nomenclature ||'-'||_scheduletype ||'-'||_inserted_id||'-'||l_now;

INSERT INTO kaveri.applicantapplicationdetails(
	citizenid,
    applicationnumber,
    applicationtypeid,
    applicationstartdate,
    currentstatus
    )
    values  
	(_citizenid,
	_applicationnumber, 
	_applicationtypeid,
	now(),
	'CD101')			 
    RETURNING applicationnumber into _application;

INSERT INTO kaveri.applicationaudit(
	applicationnumber, wrkflowstatusid, activityby, activityorder, crtusr)
	VALUES (_applicationnumber, 'CD101', _citizenid, 1, _citizenid);

    RETURN _application;
end
$_$;


