--
-- Name: fn_insert_ecprepared(bigint, text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_ecprepared(_ecid bigint, _json text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE 
v_cnt bigint;
v_ecid bigint;
begin
	select count(*) into v_cnt from kaveri.ec_prepared where ecid=_ecid;
if (v_cnt=0)
then
	insert into kaveri.ec_prepared(ecid,json) values(_ecid,_json);
	v_ecid:=_ecid;
else
	update kaveri.ec_prepared set json=_json where ecid=_ecid;
	v_ecid:=_ecid;	
end if;
	
return v_ecid; 
end;
$$;


