--

CREATE FUNCTION kaveri.fn_insert_ecpropertysearchkeyvalues(kaveri.type_ecpropertysearchkeyvalues_request[] DEFAULT NULL::kaveri.type_ecpropertysearchkeyvalues_request[]) RETURNS bigint
    LANGUAGE plpgsql
    AS $_$
DECLARE 
v_orderid bigint;
v_cnt bigint;
begin
select count(*) into v_cnt from kaveri.ecpropertysearchkeyvalues a 
inner join kaveri.dec_drordermaster b on a.orderid = b.orderid and a.keyid in (select ss._keyid from unnest($1) ss);

if v_cnt = 0 then
	insert into kaveri.ecpropertysearchkeyvalues(
	 keyid,
	 villagecode,
	 propertyid,
	 srocode,
	 documentid,
	 newpropertyid,
	 newsrocode,
	 currentpropertytypeid,
	 currentnumber,
	 oldpropertytypeid,
	 oldnumber,
	 survey_no,
	 surnoc,
	 hissa_no,
	 orderid,
	 isactivated,
	 actiontype
	)
	select 
	  nextval('kaveri.keyid_seq'),
	 _villagecode,
	 _propertyid,
	 _srocode,
	 _documentid,
	 _newpropertyid,
	 _newsrocode,
	 _currentpropertytypeid,
	 _currentnumber,
	 _oldpropertytypeid,
	 _oldnumber,
	 _survey_no,
	 _surnoc,
	 _hissa_no,
	 _orderid,
	 _isactivated,
	 _actiontype from unnest($1);
end if;

select distinct a._orderid into v_orderid  from unnest($1) a ;
return v_orderid;
end;
$_$;


