-- Name: fn_insert_eligibleappointmentdatedetails(character varying, character varying, timestamp without time zone, integer, character varying, character varying, timestamp without time zone, bigint, text, timestamp without time zone); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_eligibleappointmentdatedetails(_elgapplicationnumber character varying, _elgdocumenttype character varying, _elgappointmentdate timestamp without time zone, _srocode integer, _selectedapplicationnumber character varying, _selecteddocumenttype character varying, _selectedappointmentdate timestamp without time zone, _deptuserid bigint, _remark text, _newappointmentdate timestamp without time zone) RETURNS text
    LANGUAGE plpgsql
    AS $$

declare
v_cnt bigint;
v_applicationnumber text;
begin

Select count(*) into v_cnt from kaveri.eligibleappointmentdatedetails where selectedapplicationnumber = _selectedapplicationnumber;

if v_cnt = 0 
then 
  insert into kaveri.eligibleappointmentdatedetails
	(elgappid,
	elgapplicationnumber,
	elgdocumenttype,
	elgappointmentdate,
	srocode,
	selectedapplicationnumber,
	selecteddocumenttype,
	selectedappointmentdate,
	deptuserid,
	remark,
	newappointmentdate)
values 
(nextval('kaveri.elgappid_seq'),
	_elgapplicationnumber,
	_elgdocumenttype,
	_elgappointmentdate,
	_srocode,
	_selectedapplicationnumber,
	_selecteddocumenttype,
	_selectedappointmentdate,
	_deptuserid,
	_remark,
	_newappointmentdate) 
returning _selectedapplicationnumber into v_applicationnumber;

	else 
	
	update kaveri.eligibleappointmentdatedetails set 
	elgapplicationnumber=_elgapplicationnumber,
	elgdocumenttype=_elgdocumenttype,
	elgappointmentdate=_elgappointmentdate,
	srocode=_srocode,
	selectedapplicationnumber=_selectedapplicationnumber,
	selecteddocumenttype=_selecteddocumenttype,
	selectedappointmentdate=_selectedappointmentdate,
	deptuserid=_deptuserid,
	remark=_remark,
	newappointmentdate=_newappointmentdate
	
	where selectedapplicationnumber = _selectedapplicationnumber
	returning selectedapplicationnumber into v_applicationnumber;
	
 end if;

return v_applicationnumber;

end;
$$;


