--
-- Name: fn_insert_emp_master(bigint, character varying, character varying, integer, timestamp without time zone, character varying, character varying, character varying, character varying, character varying, character varying, character varying, boolean); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_emp_master(_empid bigint, _displayname character varying, _office character varying, _designationid integer, _dateofjoining timestamp without time zone, _joininglocation character varying, _permaddress character varying, _curraddress character varying, _mobile character varying, _emergencycontactno character varying, _emailid character varying, _panno character varying, _activeflag boolean) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
Declare
v_cnt integer;
v_empid bigint;
begin
select count(*) into v_cnt from kaveri.emp_master where empid = _empid;
if v_cnt = 0 then
insert into kaveri.emp_master (
     empid,
    displayname,
    office,
    designationid,
    dateofjoining,
    joininglocation,
    permaddress,
    curraddress,
    mobile,
    emergencycontactno,
    emailid,
    panno,
    activeflag)
values
(
    nextval('kaveri.emp_master_seq'),
    _displayname,
    _office,
    _designationid,
    _dateofjoining,
    _joininglocation,
    _permaddress,
    _curraddress,
    _mobile,
    _emergencycontactno,
    _emailid,
    _panno,
    _activeflag
)RETURNING empid::bigint into v_empid;
else
update kaveri.emp_master set
    office=_office,
    designationid=_designationid,
    dateofjoining=_dateofjoining,
    joininglocation=_joininglocation,
    permaddress=_permaddress,
    curraddress=_curraddress,
    mobile=_mobile,
    emergencycontactno=_emergencycontactno,
    emailid=_emailid,
    panno=_panno,
    activeflag=_activeflag
where empid = _empid returning empid::bigint into v_empid;
end if;
return v_empid;
end;
$$;


