--
-- Name: fn_insert_emp_transfer_details(bigint, bigint, bigint, character varying, character varying, timestamp without time zone, timestamp without time zone, character varying, character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_emp_transfer_details(_transferid bigint, _empid bigint, _designationid bigint, _currentlocation character varying, _transferlocation character varying, _from_date timestamp without time zone, _to_date timestamp without time zone, _reason character varying, _transferstatus character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
Declare
v_cnt integer;
v_transferid bigint;
v_loginname text;
begin
select count(*) into v_cnt from kaveri.emp_transfer_details where transferid = _transferid;
if v_cnt = 0 then
insert into kaveri.emp_transfer_details (
empid,
designationid,
currentlocation,
transferlocation,
from_date,
to_date,
reason,
transferstatus)
values
(
_empid,
_designationid,
_currentlocation,
_transferlocation,
_from_date,
_to_date,
_reason,
_transferstatus
)RETURNING transferid::bigint into v_transferid;
else
update kaveri.emp_transfer_details set
designationid=_designationid,
currentlocation=_currentlocation,
transferlocation=_transferlocation,
from_date=_from_date,
to_date=_to_date,
reason=_reason,
transferstatus=_transferstatus
where transferid = _transferid returning transferid::bigint into v_transferid;
end if;
select count(*) into v_cnt from kaveri.emp_transfer_details where transferid = v_transferid;
select distinct loginname into v_loginname from kaveri.emp_transfer_details a inner join
kaveri.departmentusers b on a.empid = b.userid and transferid = v_transferid;
if v_cnt > 0 then
update kaveri.emp_transfer_details set username = v_loginname where transferid = v_transferid;
end if;
return v_transferid;
end;
$$;


