--
-- Name: fn_insert_empleavedetails(bigint, bigint, bigint, timestamp without time zone, timestamp without time zone, bigint, character varying, bigint, character varying, character varying, bigint, character varying, character varying, timestamp without time zone, timestamp without time zone, timestamp without time zone, bigint); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_empleavedetails(_empleavedetailsid bigint, _empid bigint, _leavetypeid bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _noofdays bigint, _reason character varying, _designationid bigint, _reportingto character varying, _reportingperson character varying, _holidayid bigint, _leavestatus character varying, _rejectionreason character varying, _leaveapplydate timestamp without time zone, _leaveapprovedate timestamp without time zone, _leavemonth timestamp without time zone, _lstupdusrid bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare
_cnt integer;
v_cnt integer;
v_empleavedetailsid bigint;
v_leavebalance bigint;
v_noofdays bigint;
v_months bigint;
v_totaldays bigint;
begin 
select count(*) into v_cnt from kaveri.empleavedetails where 
empleavedetailsid = _empleavedetailsid;
/* if employee has applied a new leave request*/
if v_cnt = 0 then
insert into kaveri.empleavedetails (
    empid ,
    leavetypeid,
    fromdate,
    todate,
    noofdays,
    reason,
    designationid,
    reportingto,
    reportingperson,
    holidayid,
    leavestatus,
    rejectionreason,
    leaveapplydate,
    leaveapprovedate,
    leavemonth,
    lstupdusrid 
) values 
(
    _empid ,
    _leavetypeid,
    _fromdate,
    _todate,
    _noofdays,
    _reason,
    _designationid,
    _reportingto,
    _reportingperson,
    _holidayid,
    _leavestatus,
    _rejectionreason,
    _leaveapplydate,
    _leaveapprovedate,
	_leavemonth,
    _lstupdusrid 
) returning empleavedetailsid into v_empleavedetailsid;
else  /* employee leave request is either approved or rejected with proper reason */
update kaveri.empleavedetails set leavestatus = _leavestatus,rejectionreason=_rejectionreason where empleavedetailsid = _empleavedetailsid
 returning empleavedetailsid into v_empleavedetailsid;
end if;
/* if the leave type is maternity leave in case of lady employees total leave should not exceed 6 months (180 days) */
if (_leavetypeid = 3 and  _leavestatus = 'Approved') then
select (_todate::date-_fromdate::date) into v_noofdays;
   if (v_noofdays > 180 ) then
   v_noofdays = 180;
end if;
update kaveri.empleavebalance set leavebalance = leavebalance - v_noofdays where empid = _empid and leavetypeid = _leavetypeid and 
leaveyear = (DATE_PART('year',now()::timestamp with time zone))::bigint;
update kaveri.yearlyleavebalance set outstandingleave = outstandingleave - v_noofdays where empid = _empid and leavetypeid = _leavetypeid and 
leaveyear = (DATE_PART('year',now()::timestamp with time zone))::bigint;
elseif (_leavetypeid = 1 and _leavestatus = 'Approved') then /* if the leave type is CL for all employees and total number of days should not exceed 10 days */
SELECT count(*) into v_noofdays
FROM   generate_series(_fromdate::timestamp
                     , _todate::timestamp - interval '1 day'
                     , interval '1 day') the_day
WHERE  extract('ISODOW' FROM the_day) < 7;
if v_noofdays > 10 then
v_noofdays = 10;
end if;
update kaveri.empleavebalance set leavebalance = leavebalance - v_noofdays where empid = _empid and leavetypeid = _leavetypeid and 
leaveyear = (DATE_PART('year',now()::timestamp with time zone))::bigint;
update kaveri.yearlyleavebalance set outstandingleave = outstandingleave - v_noofdays where empid = _empid and leavetypeid = _leavetypeid and 
leaveyear = (DATE_PART('year',now()::timestamp with time zone))::bigint;
elseif (_leavetypeid in (2,4) and _leavestatus = 'Approved')  then /* if the leave type is earned leave for all employees and paternity leave for male employees total days should not exceed 15 days */
select (_todate::date-_fromdate::date) into v_noofdays;
if v_noofdays > 15 then
v_noofdays = 15;
end if;
update kaveri.empleavebalance set leavebalance = leavebalance - v_noofdays where empid = _empid and leavetypeid = _leavetypeid and 
leaveyear = (DATE_PART('year',now()::timestamp with time zone))::bigint;
update kaveri.yearlyleavebalance set outstandingleave = outstandingleave - v_noofdays where empid = _empid and leavetypeid = _leavetypeid and 
leaveyear = (DATE_PART('year',now()::timestamp with time zone))::bigint;
elseif (_leavetypeid = 1 and _leavestatus = 'Rejected') then /* if the CL is rejected then leave will be credited to the respective employee account */
select leavebalance into v_leavebalance from kaveri.empleavebalance where empid = _empid and leavetypeid = _leavetypeid;
SELECT count(*) into v_noofdays
FROM   generate_series(_fromdate::timestamp
                     , _todate::timestamp - interval '1 day'
                     , interval '1 day') the_day
WHERE  extract('ISODOW' FROM the_day) < 7;
v_totaldays = v_leavebalance + v_noofdays;
if (v_totaldays)  > 10 then
v_totaldays = 10;
end if;
update kaveri.empleavebalance set leavebalance = v_totaldays where empid = _empid and leavetypeid = _leavetypeid and 
leaveyear = (DATE_PART('year',now()::timestamp with time zone))::bigint;
update kaveri.yearlyleavebalance set outstandingleave = v_totaldays where empid = _empid and leavetypeid = _leavetypeid and 
leaveyear = (DATE_PART('year',now()::timestamp with time zone))::bigint;
elseif (_leavetypeid  in (2,4) and _leavestatus = 'Rejected')  then /* if the EL is rejected then leave will be credited to the respective employee account */
select leavebalance into v_leavebalance from kaveri.empleavebalance where empid = _empid and leavetypeid = _leavetypeid;
select (_todate::date - _fromdate::date) into v_noofdays;
v_totaldays = v_leavebalance + v_noofdays;
if (v_totaldays)  > 15 then
v_totaldays = 15;
end if;
update kaveri.empleavebalance set leavebalance = v_totaldays where empid = _empid and leavetypeid = _leavetypeid and 
leaveyear = (DATE_PART('year',now()::timestamp with time zone))::bigint;
update kaveri.yearlyleavebalance set outstandingleave = v_totaldays where empid = _empid and leavetypeid = _leavetypeid and 
leaveyear = (DATE_PART('year',now()::timestamp with time zone))::bigint;
elseif (_leavetypeid  = 3 and _leavestatus = 'Rejected')  then /* if the maternity leave for lady employees rejected */
select leavebalance into v_leavebalance from kaveri.empleavebalance where empid = _empid and leavetypeid = _leavetypeid;
select (_todate::date - _fromdate::date) into v_noofdays;
v_totaldays = v_leavebalance + v_noofdays;
if (v_totaldays)  > 180 then
v_totaldays = 180;
end if;
update kaveri.empleavebalance set leavebalance = v_totaldays where empid = _empid and leavetypeid = _leavetypeid and 
leaveyear = (DATE_PART('year',now()::timestamp with time zone))::bigint;
update kaveri.yearlyleavebalance set outstandingleave = v_totaldays where empid = _empid and leavetypeid = _leavetypeid and 
leaveyear = (DATE_PART('year',now()::timestamp with time zone))::bigint;
end if;
return v_empleavedetailsid;
end;
$$;


ALTER FUNCTION kaveri.fn_insert_empleavedetails(_empleavedetailsid bigint, _empid bigint, _leavetypeid bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _noofdays bigint, _reason character varying, _designationid bigint, _reportingto character varying, _reportingperson character varying, _holidayid bigint, _leavestatus character varying, _rejectionreason character varying, _leaveapplydate timestamp without time zone, _leaveapprovedate timestamp without time zone, _leavemonth timestamp without time zone, _lstupdusrid bigint) OWNER TO csgadmin;

--
-- Name: fn_insert_endorsement_referencemaster(bigint, bigint, integer, integer, character varying, integer, character varying, numeric, numeric, character varying, integer, timestamp without time zone, character varying, character varying, timestamp without time zone, timestamp without time zone, character varying, integer, boolean, integer, integer, integer, character varying, bigint); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_endorsement_referencemaster(_documentid bigint, _srocode bigint, _trid integer, _throughid integer, _referencetext character varying, _bookid integer, _year character varying, _stampduty numeric, _registrationfees numeric, _bankname character varying, _courtordernumber integer, _courtorderdate timestamp without time zone, _nameofcourt character varying, _receiptnumber character varying, _remiteddate timestamp without time zone, _endorsementdate timestamp without time zone, _partyname character varying, _documentnumber integer, _isregisterinnewbifurcatedoffice boolean, _volumnnumber integer, _frompagenumber integer, _topagenumber integer, _uploadcourtorderpath character varying, _remittedtypeid bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
_referenceno text;
l_now varchar(4);
--v_cnt bigint;
_inserted_id text;
v_refid integer;
v_documentid bigint;
begin

select documentid into v_documentid from kaveri.documentmaster where srocode = _srocode and
documentnumber = _documentnumber and bookid = _bookid and
case when cast(to_char(REGISTRATIONDATETIME,'MM') as bigint)>3 then cast(to_char(REGISTRATIONDATETIME,'YYYY')as bigint) ||'-'|| to_char(REGISTRATIONDATETIME  + interval '1 year','YY')
else cast(to_char(REGISTRATIONDATETIME,'YYYY')as bigint)-1 ||'-'|| to_char(REGISTRATIONDATETIME,'YY') end=_year;

insert into kaveri.referencemaster
(
  documentid,
  srocode,
  trid,
  throughid,
  referencetext,
  bookid,
  year,
  stampduty,
  registrationfees,
  bankname,
  courtordernumber,
    courtorderdate,
    nameofcourt,
    receiptnumber,
    remiteddate,
    endorsementdate,
    partyname,
    documentnumber,
    isregisterinnewbifurcatedoffice,
    volumnnumber,
    frompagenumber,
    topagenumber,
    uploadcourtorderpath,
    remittedtypeid
)
values
(
    v_documentid,
    _srocode,
    _trid,
    _throughid,
    _referencetext,
    _bookid,
    _year,
    _stampduty,
    _registrationfees,
    _bankname,
    _courtordernumber,
    _courtorderdate,
    _nameofcourt,
    _receiptnumber,
    _remiteddate,
    _endorsementdate,
    _partyname,
    _documentnumber,
    _isregisterinnewbifurcatedoffice,
    _volumnnumber,
    _frompagenumber,
    _topagenumber,
    _uploadcourtorderpath,
    _remittedtypeid
) RETURNING refid into v_refid;
 RETURN v_refid;
end
$$;


ALTER FUNCTION kaveri.fn_insert_endorsement_referencemaster(_documentid bigint, _srocode bigint, _trid integer, _throughid integer, _referencetext character varying, _bookid integer, _year character varying, _stampduty numeric, _registrationfees numeric, _bankname character varying, _courtordernumber integer, _courtorderdate timestamp without time zone, _nameofcourt character varying, _receiptnumber character varying, _remiteddate timestamp without time zone, _endorsementdate timestamp without time zone, _partyname character varying, _documentnumber integer, _isregisterinnewbifurcatedoffice boolean, _volumnnumber integer, _frompagenumber integer, _topagenumber integer, _uploadcourtorderpath character varying, _remittedtypeid bigint) OWNER TO csgadmin;

--
-- Name: fn_insert_feesrequired(kaveri.feesrequired_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_feesrequired(kaveri.feesrequired_input[]) RETURNS integer[]
    LANGUAGE plpgsql
    AS $_$

DECLARE

   id_val integer;

   fees_arry $1%type;

   v_applicationnumber text;

    v_txt text;

   v_propertyid bigint;

   v_cnt integer;

   var_r record;

   v_pid integer[];

v_isexempted bool;
v_exemtype character varying;
v_exemamount integer;
v_exemdocpath character varying;
v_denodocpath character varying;
v_regexemtype character varying;
v_regexemamount integer;
v_exemptdescription varchar;
v_currentstatus character varying;
BEGIN

--select currentstatus into v_currentstatus from kaveri.applicantapplicationdetails a where applicationnumber in (select b._applicationnumber from unnest($1) b);	
--
--if(v_currentstatus='CD101')
--then	
	
select exemtype,exemamount,exemdocpath,denodocpath, regexemtype,regexemamount,isexempted--,exemptdescription
into v_exemtype,v_exemamount,v_exemdocpath,v_denodocpath, v_regexemtype,v_regexemamount,v_isexempted--,v_exemptdescription
from kaveri.feesrequired a where a.feerulecode=58 and a.applicationnumber in (select b._applicationnumber from unnest($1) b);

select exemptdescription
into v_exemptdescription
from kaveri.feesrequired a where a.feerulecode=58 and a.applicationnumber in (select b._applicationnumber from unnest($1) b);

FOR fees_arry IN (SELECT kaveri.fn_fetch_1d_arrayofarray($1))

     loop

   Select count(*) into v_cnt from kaveri.feesrequired where (applicationnumber,feerulecode) in

(select a._applicationnumber,a._feerulecode from unnest(fees_arry) a);

  if v_cnt = 0 then

INSERT INTO kaveri.feesrequired(

    --documentid,

    feerulecode,

    isexempted,

    exemptdescription,

    isactive,

    feecalculationstring,

    srocode,

    isonline,

    amountrequired,

	undervaluationamount,

    applicationnumber,

    propertyid,

    exemtype,

    exemamount,

    exemdocpath,

    denodocpath,

    regexemtype,

    regexemamount,

    lastupdateddate,

    paymentstatus

) select

	--_documentid,

    _feerulecode,

    (case when (_isexempted is null or _feerulecode in (90,110,109,91)) then v_isexempted else _isexempted end) as isexempted,

    _exemptdescription,

    _isactive,

    _feecalculationstring,

    _srocode,

    _isonline,

    _amountrequired,

                undervaluationamount,

    _applicationnumber,

    _propertyid,

    (case when (_exemtype is null or _feerulecode in (91,109,110,90)) then v_exemtype else _exemtype end) as exemptype ,

    (case when (_exemamount is null or _feerulecode in (91,109,110,90)) then v_exemamount else _exemamount end) as exemamount,

    (case when (_exemdocpath is null or _feerulecode in (91,109,110,90)) then v_exemdocpath else _exemdocpath end) as exemdocpath,

    (case when (_denodocpath is null or _feerulecode in (91,109,110,90)) then v_denodocpath else _denodocpath end) as denodocpath,

    (case when (_regexemtype is null or _feerulecode in (91,109,110,90)) then v_regexemtype else _regexemtype end) as regexemtype,

    (case when (_regexemamount is null or _feerulecode in (91,109,110,90)) then v_regexemamount else _regexemamount end) as regexemamount,

    CURRENT_TIMESTAMP,

    'Pending'

from unnest(fees_arry)                        

    RETURNING feerulecode::integer into id_val;
   if not found then 
		raise exception 'Something went wrong! feesrequired insertion failed.'; 
	end if;

	update kaveri.feesrequired set exemptdescription =v_exemptdescription where applicationnumber in (select 
	_applicationnumber from unnest($1)) and feerulecode in (91,110,109,90);

    else

update kaveri.feesrequired set

    --documentid = b._documentid,

    feerulecode = b._feerulecode,

    isexempted = (case when (b._isexempted is null or b._feerulecode in (90,110,109,91)) then v_isexempted else b._isexempted end) ,

    exemptdescription = b._exemptdescription,

    isactive=b._isactive,

    feecalculationstring=b._feecalculationstring,

    srocode=b._srocode,

    isonline=b._isonline,

    amountrequired = b._amountrequired,

                undervaluationamount = b.undervaluationamount,

    applicationnumber = b._applicationnumber,

    propertyid = b._propertyid,

    exemtype=(case when (b._exemtype is null or b._feerulecode in (91,109,110,90)) then v_exemtype else b._exemtype end) ,

    exemamount=(case when (b._exemamount is null or b._feerulecode in (91,109,110,90)) then v_exemamount else b._exemamount end),

    exemdocpath=(case when (b._exemdocpath is null or b._feerulecode in (91,109,110,90)) then v_exemdocpath else b._exemdocpath end),

    denodocpath=(case when (b._denodocpath is null or b._feerulecode in (91,109,110,90)) then v_denodocpath else b._denodocpath end),

    regexemtype=(case when (b._regexemtype is null or b._feerulecode in (91,109,110,90)) then v_regexemtype else b._regexemtype end) ,

    regexemamount=(case when (b._regexemamount is null or b._feerulecode in (91,109,110,90)) then v_regexemamount else b._regexemamount end)

    from unnest(fees_arry) b

    where (applicationnumber,feerulecode) in

   (select a._applicationnumber,a._feerulecode from unnest(fees_arry) a)

RETURNING feerulecode::integer into id_val;
   if not found then 
		raise exception 'Something went wrong! feesrequired update failed.'; 
	end if;
	
	update kaveri.feesrequired set exemptdescription =v_exemptdescription where applicationnumber in (select 
	_applicationnumber from unnest($1)) and feerulecode in (91,110,109,90);

    end if;

     v_pid := array_append(v_pid,id_val);

    end loop;
--  end if; 
    return v_pid;

end;

$_$;


ALTER FUNCTION kaveri.fn_insert_feesrequired(kaveri.feesrequired_input[]) OWNER TO csgadmin;

--
-- Name: fn_insert_feesrequired_all(kaveri.feesrequired_input_all[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_feesrequired_all(kaveri.feesrequired_input_all[]) RETURNS integer[]
    LANGUAGE plpgsql
    AS $_$
DECLARE
   id_val integer;
   fees_arry $1%type;
   v_applicationnumber text;
    v_txt text;
   v_propertyid bigint;
   v_cnt integer;
   var_r record;
   v_pid integer[];
BEGIN
  FOR fees_arry IN (SELECT kaveri.fn_fetch_1d_arrayofarray($1))
     loop
     
   Select count(*) into v_cnt from kaveri.feesrequired where (coalesce(propertyid,0),applicationnumber,feerulecode) in
(select coalesce(a._propertyid,0),a._applicationnumber,a._feerulecode from unnest(fees_arry) a);

 if v_cnt = 0 then
INSERT INTO kaveri.feesrequired(
 documentid,
feerulecode,
isexempted,
exemptdescription,
isactive,
feecalculationstring,
srocode,
isonline,
amountrequired,
applicationnumber,
propertyid,
lastupdateddate,
exemtype,
exemamount,
exemdocpath,
denodocpath,
sfdaamountrequired,
sroamountrequired,
amountpaid,
valuatiotypeid,
sfdastamprule,
srostamprule,
regexemtype,
regexemamount,
paymentstatus	
) select
    _documentid,
_feerulecode,
_isexempted,
_exemptdescription,
_isactive,
_feecalculationstring,
_srocode,
_isonline,
_amountrequired,
_applicationnumber,
_propertyid,
CURRENT_TIMESTAMP,
_exemtype,
_exemamount,
_exemdocpath,
_denodocpath,
_sfdaamountrequired,
_sroamountrequired,
_amountpaid,
_valuatiotypeid,
_sfdastamprule,
_srostamprule,
_regexemtype,
_regexemamount,
'Pending'
from unnest(fees_arry)                         
    RETURNING feerulecode::integer into id_val;
    else
update kaveri.feesrequired set
    documentid = _documentid,
    feerulecode = _feerulecode,
    isexempted = _isexempted,
    exemptdescription = _exemptdescription,
    isactive=_isactive,
    feecalculationstring=_feecalculationstring,
    srocode=_srocode,
    isonline=_isonline,
    amountrequired = _amountrequired,
    applicationnumber = _applicationnumber,
    propertyid = _propertyid,
	lastupdateddate = CURRENT_TIMESTAMP ,	
    exemtype=_exemtype,
    exemamount=_exemamount,
    exemdocpath=_exemdocpath,
    denodocpath=_denodocpath,
	sfdaamountrequired = _sfdaamountrequired,
	sroamountrequired = _sroamountrequired,
	amountpaid = _amountpaid,
	valuatiotypeid = _valuatiotypeid,
	sfdastamprule = _sfdastamprule,
	srostamprule = _srostamprule,
    regexemtype = _regexemtype ,
    regexemamount=_regexemamount
    from unnest(fees_arry)
    where (coalesce(propertyid,0),applicationnumber,feerulecode) in
   (select coalesce(a._propertyid,0),a._applicationnumber,a._feerulecode from unnest(fees_arry) a)

RETURNING feerulecode::integer into id_val;
    end if;
     v_pid := array_append(v_pid,id_val);
    end loop;
    return v_pid;
end;
$_$;


ALTER FUNCTION kaveri.fn_insert_feesrequired_all(kaveri.feesrequired_input_all[]) OWNER TO csgadmin;

--
-- Name: fn_insert_feesrequired_check(kaveri.feesrequired_check1_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_feesrequired_check(p_feesdetails kaveri.feesrequired_check1_input[]) RETURNS integer[]
    LANGUAGE plpgsql
    AS $_$
DECLARE
   id_val integer;
   --fees_arry $1%type;
   v_fees_arry kaveri.feesrequired_check1_input[];
   v_applicationnumber text;
    v_txt text;
   v_propertyid bigint;
   v_cnt integer;
   var_r record;
   v_pid integer[];
   v_srostamparticlecode integer;
   v_srostampruleid integer;
   v_sronatureofdocument integer;
   v_valuatiotypeid smallint;
BEGIN
 Select count(*) into v_cnt from kaveri.feesrequired where (applicationnumber,feerulecode) in 
(select a._applicationnumber,a._valuatiotypeid from unnest($1) a);
if(p_feesdetails  is not null and array_length(p_feesdetails ,1)>0 ) then
  FOR v_fees_arry IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_feesdetails))
     loop
   Select count(*) into v_cnt from kaveri.feesrequired where (applicationnumber,feerulecode) in 
(select a._applicationnumber,a._feerulecode from unnest(v_fees_arry) a);
  if v_cnt >= 1 then
	update kaveri.feesrequired set
	valuatiotypeid=_valuatiotypeid,
	amountpaid=_amountpaid -- november 03, 2023 - removed amountpaid updation, this is already handled in fn_save_paymentgateway post payment, verification
	from unnest(v_fees_arry)
	where (applicationnumber,feerulecode) in 
(select 
 a._applicationnumber,a._feerulecode from unnest(v_fees_arry) a) 
RETURNING feerulecode::integer into id_val;
    end if;
	update kaveri.propertymaster set valuationtypeid = (select a._valuatiotypeid from unnest(v_fees_arry) a)
		where (applicationnumber) in 
		(select 
		a._applicationnumber from unnest(v_fees_arry) a) ;
	/* logic to implement if valuationtype (valuatiotypeid -2 )is normal update 
    stamparticlecode,stampruleid,natureofdocument to 
	srostamparticlecode,srostampruleid,sronatureofdocument*/
	select a.srostamparticlecode,a.srostampruleid,a.sronatureofdocument,b.valuatiotypeid
	into v_srostamparticlecode,v_srostampruleid,v_sronatureofdocument,v_valuatiotypeid from kaveri.propertymaster a
	inner join kaveri.feesrequired b on a.applicationnumber = b.applicationnumber and b.valuatiotypeid = 2
	and (a.applicationnumber) in 
(select a._applicationnumber from unnest(v_fees_arry) a);
    if v_valuatiotypeid::smallint = '2' and 
	(v_srostamparticlecode::integer is not null and v_srostampruleid::integer is not null
							   and v_sronatureofdocument::integer is not null) then
	update kaveri.propertymaster set stamparticlecode = v_srostamparticlecode::integer,
	stampruleid = v_srostampruleid::integer,
	regarticlecode = v_sronatureofdocument ::integer
	from unnest(v_fees_arry)
	where (applicationnumber) in 
(select 
 a._applicationnumber from unnest(v_fees_arry) a) ;
--RETURNING feerulecode::integer into id_val;
end if;
	 v_pid := array_append(v_pid,id_val);
    end loop;
	end if;
	return v_pid;
end;
$_$;


ALTER FUNCTION kaveri.fn_insert_feesrequired_check(p_feesdetails kaveri.feesrequired_check1_input[]) OWNER TO csgadmin;

--
-- Name: fn_insert_flatfloordetails(kaveri.val_flatfloordetails1_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_flatfloordetails(p_flatfloordetails kaveri.val_flatfloordetails1_input[] DEFAULT NULL::kaveri.val_flatfloordetails1_input[]) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
Declare

v_arry_flatfloordetails kaveri.val_flatfloordetails1_input[];
v_cnt integer;
v_valid bigint;
begin
		if(p_flatfloordetails is not null and array_length(p_flatfloordetails,1)>0 ) then
				FOR v_arry_flatfloordetails IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_flatfloordetails)) 
					loop
						v_cnt:= 0;
						Select count(*) into v_cnt from kaveri.val_flatfloordetails where flatfloordetailsid in 
						(select a._flatfloordetailsid from unnest(v_arry_flatfloordetails) a) ;
						if v_cnt = 0 then
							insert into kaveri.val_flatfloordetails (
								flatfloordetailsid,
    							apartmentfloorrateid,
   								 rate,
    							verified,
    							valuationid,
    							srocode,
    							regsrocode
								)
								select 
								 nextval('kaveri.val_flatfloordetails_seq'),
								a._apartmentfloorrateid,
   								 a._rate,
    							a._verified,
    							a._valuationid,
    							a._srocode,
    							a._regsrocode
								from unnest(v_arry_flatfloordetails) a
								 returning valuationid::bigint into v_valid;
						else
							update kaveri.val_flatfloordetails set
											apartmentfloorrateid=a._apartmentfloorrateid,
   								 			rate=a._rate,
    										verified=a._verified,
    										valuationid=a._valuationid,
    										srocode=a._srocode,
    										regsrocode=a._regsrocode		
												 from unnest(v_arry_flatfloordetails) a where flatfloordetailsid in 
														 (select a._flatfloordetailsid from unnest(v_arry_flatfloordetails) a) 
														 RETURNING valuationid::bigint into v_valid;
						end if;
						
					end loop;
			end if;
Return v_valid;
   END;
$$;


ALTER FUNCTION kaveri.fn_insert_flatfloordetails(p_flatfloordetails kaveri.val_flatfloordetails1_input[]) OWNER TO csgadmin;

--
-- Name: fn_insert_flatratedetails(kaveri.val_flatratedetails_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_flatratedetails(p_flatratedetails kaveri.val_flatratedetails_input[] DEFAULT NULL::kaveri.val_flatratedetails_input[]) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
Declare
v_arry_annexure kaveri.val_flatratedetails_input[];
v_cnt integer;
v_valid bigint;
begin
		if(p_flatratedetails is not null and array_length(p_flatratedetails,1)>0 ) then
				FOR v_arry_annexure IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_flatratedetails)) 
					loop
						v_cnt:= 0;
						Select count(*) into v_cnt from kaveri.val_flatratedetails where flatratedetailsid in 
						(select a._flatratedetailsid from unnest(v_arry_annexure) a) ;
						if v_cnt = 0 then
							insert into kaveri.val_flatratedetails (
								flatratedetailsid,
    							propertytypeid,
    							amenitiesid,
   								unitid,
    							rate,
    							flatrateid,
    							verified,
    							floorid,
    							valuationid,
    							srocode,
    							regsrocode)
								select 
								nextval('kaveri.flatratedetails_seq'),
   								 a._propertytypeid,
    							a._amenitiesid,
    							a._unitid,
    							a._rate,
    							a._flatrateid,
    							a._verified,
    							a._floorid,
    							a._valuationid,
    							a._srocode,
    							a._regsrocode
								from unnest(v_arry_annexure)	a
								 returning valuationid::bigint into v_valid;
						else
							update kaveri.val_flatratedetails set
												propertytypeid=a._propertytypeid,
    											amenitiesid=a._amenitiesid,
    											unitid=a._unitid,
    										    rate=a._rate,
    											flatrateid=a._flatrateid,
    											verified=a._verified,
    											floorid=a._floorid,
    											valuationid=a._valuationid,
    											srocode=a._srocode,
    											regsrocode=a._regsrocode
												 from unnest(v_arry_annexure) a where flatratedetailsid in 
														 (select a._flatratedetailsid from unnest(v_arry_annexure) a) 
														 RETURNING valuationid::bigint into v_valid;
						end if;
						
					end loop;
			end if;
Return v_valid;
   END;
$$;


ALTER FUNCTION kaveri.fn_insert_flatratedetails(p_flatratedetails kaveri.val_flatratedetails_input[]) OWNER TO csgadmin;

--
-- Name: fn_insert_fruits_data(character varying, integer, text, text, character varying, character varying, character varying, bigint, integer, character varying, character, boolean, integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_fruits_data(_referenceno character varying, _srocode integer, _formiiidata text, _transxml text, _formiiipath character varying, _transxmlpath character varying, _acknowledgementno character varying, _documentid bigint, _issignedformiiiuploaded integer, _applicationnumber character varying, _transactiontype character, _isaadharapatra boolean, _noofpages integer) RETURNS bigint
    LANGUAGE plpgsql
    AS $$

DECLARE
v_consideration_amt bigint;
v_propertyid bigint;
v_bookid integer;
v_applicationstatus integer;
v_reqid integer;
v_noofscanpages integer;
v_scanfees numeric;
v_value numeric;
v_mutationfee numeric;
v_cnt bigint;
BEGIN
/* Application Status Codes for FRUITS
	0 -> Status Pending as SRO
	1 -> AutoFiled
	2 -> Registered
	3 -> Withdrawn
	4 -> Rejected
*/
v_applicationstatus = 0;

select value into v_value from kaveri.feesrulemaster where feerulecode = 2;

v_noofscanpages = _noofpages + 3;
v_scanfees = (v_noofscanpages * v_value)::numeric;

select value into v_value from kaveri.feesrulemaster where feerulecode = 6;
select count(propertyid) into v_cnt  from kaveri.propertymaster where applicationnumber=_applicationnumber;

v_mutationfee:= (v_value * v_cnt)::numeric;

select consideration, propertyid into v_consideration_amt, v_propertyid from kaveri.propertymaster p 
where p.applicationnumber = _applicationnumber;

update kaveri.propertymaster set sroconsideration = consideration,documentid=_documentid where applicationnumber = _applicationnumber;
update kaveri.documentmaster set considerationamount = v_consideration_amt where applicationnumber = _applicationnumber;
update kaveri.partyinfo set documentid = _documentid,srocode=_srocode where applicationnumber = _applicationnumber; 
update kaveri.orgdatajslip set documentid=_documentid where applicationnumber = _applicationnumber;


--if(v_consideration_amt > 300000 or _formiiidata = '' ) then	
--if(v_consideration_amt > 300000) then	
if(_transactiontype = 'M' ) then --if(_formiiipath = '') then
	-- Insert scanning/ service fee and Mutation fee(35 Rs), into feesrequired table
	/*perform kaveri.fn_insert_feesrequired_check(
		array[(_applicationnumber, 2, 2, 45)]::kaveri.feesrequired_check1_input[]);*/

	v_bookid = 1;
	perform kaveri.fn_insert_feesrequired(
		array[
		(_documentid, 2, false, '', true, '2', _srocode, true, v_scanfees, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0),
		(_documentid, 6, false, '', true, '6', _srocode, true, v_mutationfee, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0)]::kaveri.feesrequired_input[]);
	
	perform kaveri.fn_insert_deptfeesrequired(
		array[
		(_documentid, 2, false, '', true, '2', _srocode, true, v_scanfees, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0),
		(_documentid, 6, false, '', true, '6', _srocode, true, v_mutationfee, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0)]::kaveri.feesrequired_input[], true);		

	update kaveri.applicantapplicationdetails a set currentstatus = 'CD106'
	where a.applicationnumber = _applicationnumber;

	update kaveri.propertymaster set sronoofscanpages = v_noofscanpages
	where applicationnumber = _applicationnumber;
else 
	if(_transactiontype in ('A',  'R') or _isaadharapatra = true) then
		v_bookid = 10;
	else
		v_bookid = 9;
	end if;

	update kaveri.applicantapplicationdetails a set currentstatus = 'CD112'
	where a.applicationnumber = _applicationnumber;
end if;
/*if(v_consideration_amt <= 300000 and _formiiidata != '' ) then
	v_applicationstatus = 1;
else
	v_applicationstatus = 0;
end if;*/

/*if(_transactiontype = 'M') then
	--if(v_consideration_amt > 300000 or _formiiidata = '') then
	if(v_consideration_amt > 300000) then
		v_bookid = 1;
		/*update kaveri.propertymaster set sronoofscanpages = v_noofscanpages --4
		where applicationnumber = _applicationnumber;	*/
		
		-- Commenting as below operation should happen regardless of Book-I or Book-i Part IV/ V
		/*update kaveri.documentmaster 
			set uploaddocdeedpath = _formiiipath,
			deedattachpath = _formiiipath
		where applicationnumber = _applicationnumber;*/
	elsif(_isaadharapatra = true) then		
		v_bookid = 10;
	/*elsif(_formiiidata != '' ) then
		v_bookid = 9;*/
	else
		v_bookid = 9;
		
		/*update kaveri.propertymaster set sronoofscanpages = 4
		where applicationnumber = _applicationnumber;	*/
	end if;
elsif(_transactiontype = 'R') then
	v_bookid = 10;
end if;
*/
update kaveri.documentmaster d 
	set bookid = v_bookid, uploaddocdeedpath = _formiiipath, deedattachpath = _formiiipath
where d.applicationnumber = _applicationnumber;

INSERT INTO kaveri.fruits_data_recv_details (
	psrocode, referenceno, srocode, formiiidata, transxml, formiiipath, transxmlpath, aknowledgementno, 
	datareceiveddate, documentid, issignedformiiiuploaded, kaigreg_insertdatetime, 
	applicationnumber, transactiontype, isformiiisrsigned, applicationstatus, isaadharapatra, consideration
	--istransmitted, isrejectedtransmitted, actiondatetime, actionstatuscode, formiiidatasigned, documentstatuscode, 
) VALUES (
	_srocode, _referenceno, _srocode, _formiiidata, _transxml, _formiiipath, _transxmlpath, _acknowledgementno, 
	CURRENT_TIMESTAMP, _documentid, _issignedformiiiuploaded, CURRENT_TIMESTAMP, 
	_applicationnumber, _transactiontype, false, v_applicationstatus, _isaadharapatra, v_consideration_amt
) returning requestid into v_reqid;

return v_reqid;
END;
$$;


ALTER FUNCTION kaveri.fn_insert_fruits_data(_referenceno character varying, _srocode integer, _formiiidata text, _transxml text, _formiiipath character varying, _transxmlpath character varying, _acknowledgementno character varying, _documentid bigint, _issignedformiiiuploaded integer, _applicationnumber character varying, _transactiontype character, _isaadharapatra boolean, _noofpages integer) OWNER TO csgadmin;

--
-- Name: fn_insert_fruits_data(character varying, integer, text, text, character varying, character varying, character varying, bigint, integer, character varying, character, boolean, integer, character varying, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_fruits_data(_referenceno character varying, _srocode integer, _formiiidata text, _transxml text, _formiiipath character varying, _transxmlpath character varying, _acknowledgementno character varying, _documentid bigint, _issignedformiiiuploaded integer, _applicationnumber character varying, _transactiontype character, _isaadharapatra boolean, _noofpages integer, _loantype character varying, _cropcode integer) RETURNS bigint
    LANGUAGE plpgsql
    AS $$

DECLARE
v_consideration_amt bigint;
v_propertyid bigint;
v_bookid integer;
v_stampruleid integer;
v_applicationstatus integer;
v_reqid integer;
v_noofscanpages integer;
v_scanfees numeric;
v_value numeric;
v_mutationfee numeric;
v_cnt bigint;
v_sd numeric;
v_regfees numeric;
v_sdvalue numeric;
v_sdunit integer;
v_sdcalcon bpchar(2);
v_sdispercent bool;
v_sdisfixduty bool;
v_regval numeric;
v_regpercent bool;
v_regvalue numeric; 
v_regispercent bool ;
v_regmaxlimit numeric;
v_regcalconconsideration char;
v_issurcharge bool;
v_surchargeval numeric;
v_surcharge numeric;
--v_currentstatus character varying;
BEGIN
/* Application Status Codes for FRUITS
	0 -> Status Pending as SRO
	1 -> AutoFiled
	2 -> Registered
	3 -> Withdrawn
	4 -> Rejected
*/

--select a.currentstatus into v_currentstatus from kaveri.applicantapplicationdetails a  where applicationnumber=_applicationnumber;

--if (v_currentstatus='CD101')
--then	
v_applicationstatus = 0;

select value into v_value from kaveri.feesrulemaster where feerulecode = 2;

v_noofscanpages = _noofpages + 3;
v_scanfees = (v_noofscanpages * v_value)::numeric;

select value into v_value from kaveri.feesrulemaster where feerulecode = 6;
select  stampruleid, consideration, propertyid into  v_stampruleid, v_consideration_amt, v_propertyid 
from kaveri.propertymaster where applicationnumber=_applicationnumber;

select count(propertyid) into v_cnt 
from kaveri.propertymaster where applicationnumber=_applicationnumber;



v_mutationfee:= (v_value * v_cnt)::numeric;

--select consideration, propertyid into v_consideration_amt, v_propertyid from kaveri.propertymaster p 
--where p.applicationnumber = _applicationnumber;

update kaveri.propertymaster set sroconsideration = consideration,documentid=_documentid where applicationnumber = _applicationnumber;
update kaveri.documentmaster set considerationamount = v_consideration_amt where applicationnumber = _applicationnumber;
update kaveri.partyinfo set documentid = _documentid,srocode=_srocode where applicationnumber = _applicationnumber; 
update kaveri.orgdatajslip set documentid=_documentid where applicationnumber = _applicationnumber;

if(_transactiontype = 'M') then 
--if(_formiiipath = '') then
--if(v_consideration_amt > 300000 or _formiiidata = '' ) then	
--if(v_consideration_amt > 300000) then	
	-- Insert scanning/ service fee and Mutation fee(35 Rs), into feesrequired table
	/*perform kaveri.fn_insert_feesrequired_check(
		array[(_applicationnumber, 2, 2, 45)]::kaveri.feesrequired_check1_input[]);*/
		
	v_bookid = 1;
	if(_cropcode in (67, 69, 210, 211, 212, 305, 306)) then
		select value, unit, sdcalcon, isinpercentage, isfixduty, regvalue, regispercent, regmaxlimit, regcalconconsideration,issurcharge, ruralvalue
		into v_sdvalue, v_sdunit, v_sdcalcon, v_sdispercent, v_sdisfixduty,v_regvalue,v_regispercent,v_regmaxlimit,v_regcalconconsideration,v_issurcharge, v_surchargeval
		from kaveri.stamprules where stampruleid=v_stampruleid;
		
		if(v_sdisfixduty) then
			v_sd=v_sdvalue;
		elsif(v_sdispercent and v_sdcalcon='C') then
			v_sd=(v_sdvalue/v_sdunit)*v_consideration_amt;
		end if;
		
		if (v_regispercent and v_regcalconconsideration='C') then
			v_regfees=(v_regvalue/100)*v_consideration_amt;
			if(v_regfees > v_regmaxlimit) then 
				v_regfees=v_regmaxlimit;
			end if;
		end if;
		
		if(v_issurcharge) then
				v_surcharge=(v_surchargeval/100)*v_sd;
		end if;
	
		perform kaveri.fn_insert_feesrequired(array[
			(_documentid, 36, false, '', true, '36', _srocode, true, v_sd, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0),
			(_documentid, 58, false, '', true, '58', _srocode, true, v_surcharge, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0),
			(_documentid, 1, false, '', true, '1', _srocode, true, v_regfees, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0),
			(_documentid, 2, false, '', true, '2', _srocode, true, v_scanfees, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0),
			(_documentid, 6, false, '', true, '6', _srocode, true, v_mutationfee, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0)]::kaveri.feesrequired_input[]);
		
		perform kaveri.fn_insert_deptfeesrequired(array[
			(_documentid, 36, false, '', true, '36', _srocode, true, v_sd, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0),
			(_documentid, 58, false, '', true, '58', _srocode, true, v_surcharge, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0),
			(_documentid, 1, false, '', true, '1', _srocode, true, v_regfees, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0),
			(_documentid, 2, false, '', true, '2', _srocode, true, v_scanfees, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0),
			(_documentid, 6, false, '', true, '6', _srocode, true, v_mutationfee, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0)]::kaveri.feesrequired_input[], true);	
	else
		perform kaveri.fn_insert_feesrequired(
			array[
			(_documentid, 2, false, '', true, '2', _srocode, true, v_scanfees, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0),
			(_documentid, 6, false, '', true, '6', _srocode, true, v_mutationfee, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0)]::kaveri.feesrequired_input[]);
		
		perform kaveri.fn_insert_deptfeesrequired(
			array[
			(_documentid, 2, false, '', true, '2', _srocode, true, v_scanfees, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0),
			(_documentid, 6, false, '', true, '6', _srocode, true, v_mutationfee, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0)]::kaveri.feesrequired_input[], true);			
	end if;

	update kaveri.applicantapplicationdetails a set currentstatus = 'CD106'
	where a.applicationnumber = _applicationnumber;

	update kaveri.propertymaster set sronoofscanpages = v_noofscanpages
	where applicationnumber = _applicationnumber;
else 
	if(_transactiontype in ('A',  'R') or _isaadharapatra = true) then
		v_bookid = 10;
	else
		v_bookid = 9;
	end if;

	update kaveri.applicantapplicationdetails a set currentstatus = 'CD112'
	where a.applicationnumber = _applicationnumber;
end if;
/*if(v_consideration_amt <= 300000 and _formiiidata != '' ) then
	v_applicationstatus = 1;
else
	v_applicationstatus = 0;
end if;*/

/*if(_transactiontype = 'M') then
	--if(v_consideration_amt > 300000 or _formiiidata = '') then
	if(v_consideration_amt > 300000) then
		v_bookid = 1;
		update kaveri.propertymaster set sronoofscanpages = v_noofscanpages --4
		where applicationnumber = _applicationnumber;	
		
		-- Commenting as below operation should happen regardless of Book-I or Book-i Part IV/ V
		update kaveri.documentmaster 
			set uploaddocdeedpath = _formiiipath,
			deedattachpath = _formiiipath
		where applicationnumber = _applicationnumber;
	elsif(_isaadharapatra = true) then		
		v_bookid = 10;
	elsif(_formiiidata != '' ) then
		v_bookid = 9;
	else
		v_bookid = 9;
		
		update kaveri.propertymaster set sronoofscanpages = 4
		where applicationnumber = _applicationnumber;	
	end if;
elsif(_transactiontype = 'R') then
	v_bookid = 10;
end if;*/

update kaveri.documentmaster d 
	set bookid = v_bookid, uploaddocdeedpath = _formiiipath, deedattachpath = _formiiipath
where d.applicationnumber = _applicationnumber;

INSERT INTO kaveri.fruits_data_recv_details (
	psrocode, referenceno, srocode, formiiidata, transxml, formiiipath, transxmlpath, aknowledgementno, 
	datareceiveddate, documentid, issignedformiiiuploaded, kaigreg_insertdatetime, 
	applicationnumber, transactiontype, isformiiisrsigned, applicationstatus, isaadharapatra, consideration, loantype, cropid
	--istransmitted, isrejectedtransmitted, actiondatetime, actionstatuscode, formiiidatasigned, documentstatuscode, 
) VALUES (
	_srocode, _referenceno, _srocode, _formiiidata, _transxml, _formiiipath, _transxmlpath, _acknowledgementno, 
	CURRENT_TIMESTAMP, _documentid, _issignedformiiiuploaded, CURRENT_TIMESTAMP, 
	_applicationnumber, _transactiontype, false, v_applicationstatus, _isaadharapatra, v_consideration_amt, _loanType, _cropcode
) returning requestid into v_reqid;

if v_reqid > 0 then 
	update kaveri.applicantapplicationdetails
	set isfruits = true
	where applicationnumber =_applicationnumber;
end if;

--end if;
return v_reqid;
END;
$$;


ALTER FUNCTION kaveri.fn_insert_fruits_data(_referenceno character varying, _srocode integer, _formiiidata text, _transxml text, _formiiipath character varying, _transxmlpath character varying, _acknowledgementno character varying, _documentid bigint, _issignedformiiiuploaded integer, _applicationnumber character varying, _transactiontype character, _isaadharapatra boolean, _noofpages integer, _loantype character varying, _cropcode integer) OWNER TO postgres;

--
-- Name: fn_insert_into_applicantapplicationdetails(bigint, integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_into_applicantapplicationdetails(_citizenid bigint, _applicationtypeid integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
	--id_val bigint;
	_applicationnumber text;
	_application text;
	_nomenclature character varying(3);
	l_now varchar(8);
	_inserted_id text;
	_servicestatus text; 
		l_reset_date varchar(8);
v_length int;
begin
l_now := to_char(now(),'DDMMYYYY');

l_reset_date := to_char(now(),'DDMM');

select nomenclature into _nomenclature   from kaveri.servicesmaster where serviceid = _applicationtypeid;

if _applicationtypeid = 13 then
_servicestatus = 'CE101';
elsif _applicationtypeid = 53 then
_servicestatus = 'RS101';
else 
_servicestatus = 'CD101';
end if;

/* In the April 01st the serquence will reset to 1 */
/*
if l_reset_date = '0104' then
ALTER SEQUENCE kaveri.ApplicantApplicationdetails_applicationnumber_seq RESTART WITH 1;
end if;
*/

--select lpad(nextval('kaveri.ApplicantApplicationdetails_applicationnumber_seq')::text,5,'0') into _inserted_id;

select length(last_value::varchar) into v_length from kaveri.ApplicantApplicationdetails_applicationnumber_seq;
if(v_length<7)
then
select lpad(nextval('kaveri.ApplicantApplicationdetails_applicationnumber_seq')::text,7,'0') into _inserted_id;
else
select nextval('kaveri.ApplicantApplicationdetails_applicationnumber_seq'::text) into _inserted_id;
end if;

_applicationnumber := _nomenclature ||'-'||l_now ||'-'||_inserted_id;

INSERT INTO kaveri.applicantapplicationdetails(
	citizenid,
    applicationnumber,
    applicationtypeid,
    applicationstartdate,
    currentstatus
    )
    values  
	(_citizenid,
	_applicationnumber, 
	_applicationtypeid,
	now(),
	_servicestatus)			 
    RETURNING applicationnumber into _application;

INSERT INTO kaveri.applicationaudit(
	applicationnumber, wrkflowstatusid, activityby, activityorder, crtusr)
	VALUES (_applicationnumber, _servicestatus, _citizenid, 1, _citizenid);

    RETURN _application;
end
$$;


ALTER FUNCTION kaveri.fn_insert_into_applicantapplicationdetails(_citizenid bigint, _applicationtypeid integer) OWNER TO csgadmin;

