CREATE FUNCTION kaveri.fn_insert_into_applicantapplicationdetails_marriage(_citizenid bigint, _applicationtypeid integer) RETURNS text
    LANGUAGE plpgsql
    AS $$

DECLARE
	--id_val bigint;
	_applicationnumber text;
	_application text;
	_nomenclature character varying(3);
	l_now varchar(8);
	_inserted_id text;
	_servicestatus text; 
		l_reset_date varchar(8);
	v_cnt bigint;

begin
l_now := to_char(now(),'DDMMYYYY');

l_reset_date := to_char(now(),'DDMM');

select nomenclature into _nomenclature   from kaveri.servicesmaster where serviceid = _applicationtypeid;

if _applicationtypeid = 4 then
_servicestatus = 'MR101';
end if;

/* In the April 01st the serquence will reset to 1 
if l_reset_date = '0104' then
ALTER SEQUENCE kaveri.ApplicantApplicationdetails_applicationnumber_seq RESTART WITH 1;
end if;

--select lpad(nextval('kaveri.ApplicantApplicationdetails_applicationnumber_seq')::text,5,'0') into _inserted_id;*/

select lpad(nextval('kaveri.ApplicantApplicationdetails_applicationnumber_seq')::text,7,'0') into _inserted_id;

_applicationnumber := _nomenclature ||'-'||l_now ||'-'||_inserted_id;

INSERT INTO kaveri.applicantapplicationdetails(
	citizenid,
    applicationnumber,
    applicationtypeid,
    applicationstartdate,
    currentstatus
    )
    values  
	(_citizenid,
	_applicationnumber, 
	_applicationtypeid,
	now(),
	_servicestatus)			 
    RETURNING applicationnumber into _application;

INSERT INTO kaveri.applicationaudit(
	applicationnumber, wrkflowstatusid, activityby, activityorder, crtusr)
	VALUES (_applicationnumber, _servicestatus, _citizenid, 1, _citizenid);

RETURN _application;
end
$$;


