--

CREATE FUNCTION kaveri.fn_insert_into_property_master_movable_property(_propertyid bigint, _documentid bigint, _villagecode bigint, _regsrocode integer, _srocode integer, _totalarea numeric, _unitid integer, _northboundary character varying, _southboundary character varying, _eastboundary character varying, _westboundary character varying, _landmark character varying, _marketvalue numeric, _assessment character varying, _sdcalculationstring character varying, _stampduty numeric, _transferliabilities smallint, _consideration numeric, _additionalduty numeric, _cessduty numeric, _govtduty numeric, _isexempted boolean, _exemptiondescription character varying, _ismovableproperty boolean, _sdrefund numeric, _docmarketvalue numeric, _valid1 bigint, _isimdemnified boolean, _restriction character varying, _restrictiontype character varying, _restrictiondescription character varying, _enumber character varying, _claimingblocknumber character varying, _retainingblocknumber character varying, _valuationreport character varying, _loanpurposeid smallint, _applicationnumber character varying, _verified boolean, _issroapproved character varying, _stamparticlecode integer, _stampruleid integer, _regarticlecode integer, _propertytypeid integer, _noofscanpages integer, _movablepropertydesc text, _isbefore2004 boolean DEFAULT NULL::boolean) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE 
_cnt integer;
v_propertyid bigint;
begin
select count(*) into _cnt from kaveri.propertymaster where propertyid = _propertyid
and ismovableproperty = true;
if _cnt = 0 then
INSERT INTO kaveri.propertymaster(
	 propertyid,
    documentid,
    villagecode,
    regsrocode,
    srocode,
    totalarea,
    unitid,
    northboundary,
    southboundary,
    eastboundary,
    westboundary,
    landmark,
    marketvalue,
    assessment,
    sdcalculationstring,
    stampduty,
    transferliabilities,
    consideration,
    additionalduty,
    cessduty,
    govtduty,
    isexempted,
    exemptiondescription,
    ismovableproperty,
    sdrefund,
    docmarketvalue,
    valid1,
    isimdemnified,
    restriction,
    restrictiontype,
    restrictiondescription,
    enumber,
    claimingblocknumber,
    retainingblocknumber,
    valuationreport,
    loanpurposeid,
    applicationnumber,
    verified,
    issroapproved,
    stamparticlecode,
    stampruleid,
     regarticlecode,
    propertytypeid,
    noofscanpages,
    movablepropertydesc,
	isbefore2004)
	values
    (nextval('kaveri.propertymastersequence_seq'),
    _documentid,
    _villagecode,
    _regsrocode,
    _srocode,
    _totalarea,
    _unitid,
    _northboundary,
    _southboundary,
    _eastboundary,
    _westboundary,
    _landmark,
    _marketvalue,
    _assessment,
    _sdcalculationstring,
    _stampduty,
    _transferliabilities,
    _consideration,
    _additionalduty,
    _cessduty,
    _govtduty,
    _isexempted,
    _exemptiondescription,
    _ismovableproperty,
    _sdrefund,
    _docmarketvalue,
    _valid1,
    _isimdemnified,
    _restriction,
    _restrictiontype,
    _restrictiondescription,
    _enumber,
    _claimingblocknumber,
    _retainingblocknumber,
    _valuationreport,
    _loanpurposeid,
    _applicationnumber,
    _verified,
    _issroapproved,
    _stamparticlecode,
    _stampruleid,
	 _regarticlecode,
	 _propertytypeid,
	 _noofscanpages,
	 _movablepropertydesc,
	 _isbefore2004
	) returning propertyid into v_propertyid;
	else 
	update  kaveri.propertymaster set
	 documentid = _documentid,
    villagecode = _villagecode,
    regsrocode = _regsrocode,
    srocode = _srocode,
    totalarea = _totalarea,
    unitid = _unitid,
    northboundary = _northboundary,
    southboundary = _southboundary,
    eastboundary = _eastboundary,
    westboundary = _westboundary,
    landmark = _landmark,
    marketvalue = _marketvalue,
    assessment = _assessment,
    sdcalculationstring = _sdcalculationstring,
    stampduty = _stampduty,
    transferliabilities = _transferliabilities,
    consideration = _consideration,
    additionalduty = _additionalduty,
    cessduty = _cessduty,
    govtduty = _govtduty,
    isexempted = _isexempted,
    exemptiondescription = _exemptiondescription,
    ismovableproperty = _ismovableproperty,
    sdrefund = _sdrefund,
    docmarketvalue = _docmarketvalue,
    valid1 = _valid1,
    isimdemnified = _isimdemnified,
    restriction = _restriction,
    restrictiontype = _restrictiontype,
    restrictiondescription = _restrictiondescription,
    enumber = _enumber,
    claimingblocknumber = _claimingblocknumber,
    retainingblocknumber = _retainingblocknumber,
    valuationreport = _valuationreport,
    loanpurposeid = _loanpurposeid,
    applicationnumber = _applicationnumber,
    verified = _verified,
    issroapproved = _issroapproved,
    stamparticlecode = _stamparticlecode,
    stampruleid = _stampruleid, 
	  regarticlecode=_regarticlecode,
    propertytypeid=_propertytypeid,
    noofscanpages=_noofscanpages,
    movablepropertydesc=_movablepropertydesc,
	isbefore2004 = _isbefore2004
	where propertyid = _propertyid 
	returning _propertyid into v_propertyid;
	end if;
	return v_propertyid;
	end
$$;


ALTER FUNCTION kaveri.fn_insert_into_property_master_movable_property(_propertyid bigint, _documentid bigint, _villagecode bigint, _regsrocode integer, _srocode integer, _totalarea numeric, _unitid integer, _northboundary character varying, _southboundary character varying, _eastboundary character varying, _westboundary character varying, _landmark character varying, _marketvalue numeric, _assessment character varying, _sdcalculationstring character varying, _stampduty numeric, _transferliabilities smallint, _consideration numeric, _additionalduty numeric, _cessduty numeric, _govtduty numeric, _isexempted boolean, _exemptiondescription character varying, _ismovableproperty boolean, _sdrefund numeric, _docmarketvalue numeric, _valid1 bigint, _isimdemnified boolean, _restriction character varying, _restrictiontype character varying, _restrictiondescription character varying, _enumber character varying, _claimingblocknumber character varying, _retainingblocknumber character varying, _valuationreport character varying, _loanpurposeid smallint, _applicationnumber character varying, _verified boolean, _issroapproved character varying, _stamparticlecode integer, _stampruleid integer, _regarticlecode integer, _propertytypeid integer, _noofscanpages integer, _movablepropertydesc text, _isbefore2004 boolean) OWNER TO postgres;

