CREATE FUNCTION kaveri.fn_insert_jslipoldmethodlog(_filename character varying, _isconfirmationsent boolean, _srocode bigint) RETURNS integer
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$
declare 
v_refid int;
BEGIN	
	if(_filename is not null )
	then
	insert into kaveri.jslipoldmethodlog(refid,filename,isconfirmationsent,srocode)
	values (_filename,_isconfirmationsent,_srocode)
	returning refid into v_refid;
	end if;
return v_refid;
END
$$;


