-- Name: fn_insert_k1documentdetails(character varying, character varying, integer, numeric, integer, timestamp without time zone); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_k1documentdetails(_applicationnumber character varying, _finalregistrationnumber character varying, _bookid integer, _stampduty numeric, _srocode integer, _registrationdate timestamp without time zone) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
   v_applicationnumber character varying;
   v_cnt integer;
begin

Select count(*) into v_cnt from kaveri.k1documentdetails where applicationnumber = _applicationnumber;

if v_cnt = 0 then

INSERT INTO kaveri.k1documentdetails( 
	applicationnumber ,
	finalregistrationnumber,
	bookid ,
	stampduty ,  
	srocode ,
	registrationdate
)
    select  
	_applicationnumber ,
	_finalregistrationnumber,
	_bookid ,
	_stampduty ,
	_srocode ,
	_registrationdate	
	returning applicationnumber::character varying into v_applicationnumber;
else

  update kaveri.k1documentdetails
  set 
	applicationnumber = _applicationnumber,
	finalregistrationnumber = _finalregistrationnumber,
	bookid = _bookid ,
	stampduty = _stampduty,
	srocode = _srocode,
	registrationdate = _registrationdate
where applicationnumber = _applicationnumber
		 returning applicationnumber::character varying into v_applicationnumber;

	end if;
Return v_applicationnumber;
end;
$$;


