CREATE FUNCTION kaveri.fn_insert_khajaneresponse(_applicationnumber character varying, _khajaneinputxml text, _khajaneresponse text, _logid bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
Declare
v_applicationnumber character varying(100);
v_logid bigint;
begin
if (_khajaneresponse is not null and coalesce(_khajaneresponse,'') <> '') then
update kaveri.ams_reg_khajaneresponselog set khajanexmlrespone =_khajaneresponse
where logid = _logid and applicationnumber = _applicationnumber returning logid into v_logid;
end if;

if(_khajaneinputxml is not null and coalesce(_khajaneinputxml,'') <> '') then
update kaveri.ams_reg_khajaneresponselog set khajaneinputxml =_khajaneinputxml
where logid = _logid and applicationnumber = _applicationnumber returning logid into v_logid;
end if;
return v_logid;
   END;
$$;


