CREATE FUNCTION kaveri.fn_insert_liabilitydetails(_liabilityid bigint, _issuedate timestamp without time zone, _issuedby character varying, _amount numeric, _ordernumber character varying, _srocode integer, _userid integer, _drocode integer, _propertyid bigint, _liabilitynote character varying, _cleardate timestamp without time zone, _clearedby character varying, _challannumber character varying, _clearnote character varying, _isclear boolean, _finalregistrationnumber character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
 
DECLARE
	vs_liabilityid bigint;
begin
	
	if _isclear=false then
 
INSERT INTO kaveri.liabilitydetails_new(
finalregistrationnumber,
propertyid,
orderdate,
ordernumber,
issuedby,
liabilityamount,
liabilitynote,
srocode,
userid,
drocode,
iscleared,
k1k2_flag)
	VALUES (
      _finalregistrationnumber,
     _propertyid,
	_issuedate,
      _ordernumber,
	    _issuedby,
	    _amount,
	    _liabilitynote,
	    _srocode,
	    _userid,
	    _drocode,
		false,
         2
) RETURNING liabilityid into vs_liabilityid;
	
	else
	update kaveri.liabilitydetails_new set
	    cleardate=_cleardate,
	    clearedby=_clearedby,
        iscleared=true,
	    clearnote=_clearnote,
		clearorder = _ordernumber,
challannumber=_challannumber
where liabilityid = _liabilityid returning liabilityid into vs_liabilityid;
	   
 
end if;
 
    RETURN vs_liabilityid;
end;
$$;


