CREATE FUNCTION kaveri.fn_insert_liabilitydetails(_liabilityid bigint, _entrydate timestamp without time zone, _issuedate timestamp without time zone, _issuedby character varying, _amount numeric, _ordernumber character varying, _srocode integer, _userid integer, _drocode integer, _mappingid bigint, _documentid bigint, _propertyid bigint, _orderissuedate timestamp without time zone, _note character varying, _liabilitynote character varying, _liabilityfromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _liabilityadditionalnote character varying DEFAULT NULL::character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$

DECLARE
	--id_val bigint;
	v_liabilityid bigint;
	vs_liabilityid bigint;
	v_cnt integer;
	--v_id bigint;
begin
select count(*) into v_cnt from kaveri.liabilitydetails where liabilityid = _liabilityid;
if v_cnt = 0 then
	INSERT INTO kaveri.liabilitydetails(
		liabilityid,
	    entrydate,
	    issuedate,
	    issuedby,
	    amount,
	    ordernumber,
	    liabilitynote,
	    srocode,
	    userid,
	    drocode,
		liabilityfromdate,
		liabilityadditionalnote
	    )
	    values  
		(
		nextval('kaveri.liabilitydetails_seq'),
	    _entrydate,
	    _issuedate,
	    _issuedby,
	    _amount,
	    _ordernumber,
	    _liabilitynote,
	    _srocode,
	    _userid,
	    _drocode,
		_liabilityfromdate,
		_liabilityadditionalnote)			 
	    RETURNING liabilityid into vs_liabilityid;
	   
	   insert into kaveri.liabilityonpropertydetails (
		mappingid,
		srocode1,
		liabilityid,
		documentid,
		propertyid,
		srocode,
		ordernumber,
		orderissuedate,
		note,
		amount
		) values
		(
		nextval('kaveri.liabilityonpropertydetails_seq'),
		_srocode,
		vs_liabilityid,
		--v_id, /* to populate the liability id */
		_documentid,
		_propertyid,
		_srocode,
		_ordernumber,
		_issuedate,
		_note,
		_amount
		);
else
	update kaveri.liabilitydetails set
	     entrydate=_entrydate,
	    issuedate=_issuedate,
	    issuedby=_issuedby,
	    amount=_amount,
	    ordernumber=_ordernumber,
	    liabilitynote=_liabilitynote,
	    srocode=_srocode,
	    userid=_userid,
	    drocode=_drocode,
		liabilityfromdate=_liabilityfromdate,
		liabilityadditionalnote=_liabilityadditionalnote
	where liabilityid = _liabilityid returning liabilityid into vs_liabilityid;
end if;
/*select count(*) into v_cnt from kaveri.liabilityonpropertydetails where liabilityid = _liabilityid;-- mappingid = _mappingid;
--select liabilityid into v_id from kaveri.liabilitydetails where liabilityid = _liabilityid;
if v_cnt = 0 then
insert into kaveri.liabilityonpropertydetails (
mappingid,
srocode1,
liabilityid,
documentid,
propertyid,
srocode,
ordernumber,
orderissuedate,
note,
amount
) values
(
nextval('kaveri.liabilityonpropertydetails_seq'),
_srocode,
vs_liabilityid,
--v_id, /* to populate the liability id */
_documentid,
_propertyid,
_srocode,
_ordernumber,
_issuedate,
_note,
_amount
)   RETURNING liabilityid into v_liabilityid;
else
update kaveri.liabilityonpropertydetails set
srocode1=_srocode,
--documentid=_documentid,
--propertyid=_propertyid,
srocode=_srocode,
ordernumber=_ordernumber,
orderissuedate=_issuedate,
note=_note,
amount=_amount
where liabilityid = _liabilityid returning liabilityid into v_liabilityid;
end if;*/
    RETURN vs_liabilityid;
end;
$$;


