CREATE FUNCTION kaveri.fn_insert_marriageregistration(_registrationid bigint, _applicationnumber character varying, _marriagetypeid integer, _dateofmarriage timestamp without time zone, _housebuildingname character varying, _streetaddress character varying, _villagecode bigint, _statecode bigint, _pincode bigint, _combinephotopath character varying, _bridegroomphoto character varying, _bridephoto character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare
v_cnt bigint;
v_registrationid integer;
begin
select count(*) into v_cnt from kaveri.marriageregistration where registrationid =_registrationid ;
if v_cnt = 0 then
insert into kaveri.marriageregistration
(
registrationid, marriagetypeid,applicationnumber, dateofmarriage,
	combinephotopath,bridegroomphoto,bridephoto,housebuildingname,streetaddr,cityvillagecode,statecode,pincode

) values
(
nextval('kaveri.registrationid_seq'), _marriagetypeid,_applicationnumber,_dateofmarriage,
	_combinephotopath,_bridegroomphoto,_bridephoto,_housebuildingname,_streetaddress,_villagecode,_statecode,_pincode
) returning registrationid into v_registrationid;
else
update kaveri.marriageregistration set
    housebuildingname= _housebuildingname,streetaddr=_streetaddress,marriagetypeid=_marriagetypeid,
    dateofmarriage=_dateofmarriage,cityvillagecode=_villagecode,statecode=_statecode,pincode=_pincode,
	combinephotopath=_combinephotopath,bridegroomphoto=_bridegroomphoto,bridephoto=_bridephoto
where registrationid = _registrationid returning registrationid into v_registrationid;
end if;
return v_registrationid;
end;
$$;


