--
-- Name: fn_insert_masvaluation_approve(bigint, kaveri.masvalsro_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_masvaluation_approve(p_sro bigint, p_masvalsro kaveri.masvalsro_input[] DEFAULT NULL::kaveri.masvalsro_input[]) RETURNS integer
    LANGUAGE plpgsql
    AS $$

DECLARE
  v_masvalsro_arry kaveri.masvalsro_input[];
   v_valrateheaderid bigint;   
   v_roadcode bigint;
   v_cnt bigint;
   v_isapprove boolean ;
   v_finalapprove boolean ;
   v_remarks text;
  v_success int;
  v_cntheader int;
BEGIN

if(p_masvalsro is not null and array_length(p_masvalsro,1)>0 ) then
 
 v_finalapprove:= true;
 FOR v_masvalsro_arry IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_masvalsro)) 
	loop
		v_cnt:= 0;
	begin	
	--select count(*) into v_cnt from kaveri.mas_valratedetail where valratedetailid in 
	select a._valrateheaderid,a._roadcode,a._isapprove,a._remarks
	into v_valrateheaderid,v_roadcode,v_isapprove,v_remarks
	 from unnest(v_masvalsro_arry) a ;
	 
	 
	
	if (v_valrateheaderid > 0 and v_isapprove = true) then
		update kaveri.mas_valratedetail set isapproved=v_isapprove, updatedby=p_sro::character varying,
		updateddate =current_timestamp
			where valrateheaderid = v_valrateheaderid and roadcode = v_roadcode;
		GET DIAGNOSTICS v_success = ROW_COUNT;
			
			update kaveri.mas_valuationrates set isapproved=v_isapprove, updatedby=p_sro::character varying,
		updateddate =current_timestamp
			where valrateheaderid = v_valrateheaderid and roadcode = v_roadcode;
			GET DIAGNOSTICS v_success = ROW_COUNT;	
		
			insert into kaveri.rateagriculturaldetail 
			(rateagricode,roadcode,agrilandtypeid,villagecode,measurementcode,rate,effectivedate)
			select nextval('kaveri.rateagriculturaldetail_seq_s'),mv.roadcode,agrilandtypeid,villagecode,unitid,rate,effectivedate 
				from kaveri.mas_valratedetail mv
				inner join kaveri.roadmaster rm on (rm.roadcode=mv.roadcode)
				where valrateheaderid = v_valrateheaderid and mv.roadcode = v_roadcode and isapproved=true 
				and agrilandtypeid is not null ;
				GET DIAGNOSTICS v_success = ROW_COUNT;
			
				insert into kaveri.openbuiltratedetail
			(openbuildratecode,roadcode,villagecode,propertytypeid,measurementcode,rate,effectivedate)
			select nextval('kaveri.openbuiltratedetails_seq'), mv.roadcode,villagecode,propertytypeid,unitid,rate,effectivedate 
				from kaveri.mas_valratedetail mv
				inner join kaveri.roadmaster rm on (rm.roadcode=mv.roadcode)
				where valrateheaderid = v_valrateheaderid and mv.roadcode = v_roadcode and isapproved=true 
				and agrilandtypeid is null  and propertytypeid<>12 ;
				GET DIAGNOSTICS v_success = ROW_COUNT;
			
				insert into  kaveri.mas_val_flatrates 
			(flaterateid,roadid,propertytypeid,unitid,rate,effectivedate,amenitiesid,floorid)
			select nextval('kaveri.mas_val_flatrates_seq'),mv.roadcode,propertytypeid,unitid,rate,effectivedate ,amenitiesid,1 as floorid
				from kaveri.mas_valratedetail mv
				where valrateheaderid = v_valrateheaderid and roadcode = v_roadcode and isapproved=true 
				and agrilandtypeid is null  and propertytypeid=12;
				GET DIAGNOSTICS v_success = ROW_COUNT;
			
	elsif(v_isapprove = false) then
		v_finalapprove:= false;
		update kaveri.mas_valratedetail set isapproved=v_isapprove, updatedby=p_sro::character varying,
		updateddate =current_timestamp,remarks=v_remarks
			where valrateheaderid = v_valrateheaderid and roadcode = v_roadcode;
			GET DIAGNOSTICS v_success = ROW_COUNT;
--			update kaveri.mas_valuationrates set isapproved=null, updatedby=p_sro::character varying,
--		updateddate =current_timestamp,valrateheaderid=null
--			where valrateheaderid = v_valrateheaderid and roadcode = v_roadcode;
		
		delete from kaveri.mas_valuationrates where valrateheaderid = v_valrateheaderid and roadcode = v_roadcode;
		GET DIAGNOSTICS v_success = ROW_COUNT;						
	end if;
	select count(*)  into v_cntheader from kaveri.mas_valratedetail where valrateheaderid = v_valrateheaderid and isapproved is null;
	if(v_cntheader=0)
	then
	 update kaveri.mas_valrateheader set isapproved=v_finalapprove,updatedby=p_sro::character varying,
			updateddate =current_timestamp 
			where valrateheaderid = v_valrateheaderid;
		GET DIAGNOSTICS v_success = ROW_COUNT;
	end if;
  --exception when others then	 
	--RAISE EXCEPTION 'Master Valuation data Status --> %', v_success
     --USING HINT = 'Please check valuation data';
	 end ;
	 
 END LOOP;
 end if;
	return v_success;
END;
$$;


ALTER FUNCTION kaveri.fn_insert_masvaluation_approve(p_sro bigint, p_masvalsro kaveri.masvalsro_input[]) OWNER TO csgadmin;

--
-- Name: fn_insert_masvaluation_detail(kaveri.valratedetail_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_masvaluation_detail(p_valratedetail kaveri.valratedetail_input[] DEFAULT NULL::kaveri.valratedetail_input[]) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_valratedetail_arry kaveri.valratedetail_input[];
   v_propertytypeid bigint;   
   v_agrilandtypeid bigint;
   v_amenitiesid bigint;
   v_valratedetailid bigint;
   v_cnt bigint;
   v_isdelete boolean ;
   v_success int ;
BEGIN

if(p_valratedetail is not null and array_length(p_valratedetail,1)>0 ) then
--   v_success:='Success';
 FOR v_valratedetail_arry IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_valratedetail)) 
					loop
		v_cnt:= 0;
	begin
	
	--select count(*) into v_cnt from kaveri.mas_valratedetail where valratedetailid in 
	select a._valratedetailid,a._agrilandtypeid,a._propertytypeid,a._amenitiesid,a._isdeleted--,a._amenitiesname 
	into v_valratedetailid,v_agrilandtypeid,v_propertytypeid,v_amenitiesid,v_isdelete--,v_amenitiesname
	 from unnest(v_valratedetail_arry) a ;
	
	if(v_valratedetailid is null or v_valratedetailid =0)	then
	
		if (v_agrilandtypeid is not null and v_agrilandtypeid <> 0 and v_propertytypeid=17) then 
				insert into kaveri.mas_valuationrates 
					(roadcode,srocode,propertytypeid, agrilandtypeid,unitid,rate,sfdaid,updatedby) 
						select a._roadcode,a._srocode,v_propertytypeid, a._agrilandtypeid,
						a._unitid,a._rate,a._sfdaid,a._sfdaid::character varying from unnest(v_valratedetail_arry) a; 
					GET DIAGNOSTICS v_success = ROW_COUNT;
		--elsif (v_amenitiesname is not null and v_amenitiesname <> '' and (v_amenitiesid is null or v_amenitiesid = 0)) then 
--		elsif (v_amenitiesid is not null and v_amenitiesid <> 0) then
		elsif (v_propertytypeid is not null and v_propertytypeid=12)then		
				--insert into kaveri.mas_val_apartmentsamenities 
				--(namewithamenities,isactive) 
				--select f._amenitiesname,false from unnest(v_valratedetail_arry) f returning amenitiesid into v_amenitiesid;
				insert into kaveri.mas_valuationrates 
				(roadcode,srocode,propertytypeid, floorid,amenitiesid, unitid,rate,sfdaid,updatedby) 
					select a._roadcode,a._srocode,a._propertytypeid,a._floorid,
					v_amenitiesid, a._unitid,a._rate,a._sfdaid,a._sfdaid::character varying from unnest(v_valratedetail_arry) a; 
				GET DIAGNOSTICS v_success = ROW_COUNT;
		elsif (v_propertytypeid is not null and v_propertytypeid <> 0 and v_propertytypeid <> 17) then 
				insert into kaveri.mas_valuationrates 
					(roadcode,srocode,propertytypeid,unitid,rate,sfdaid,updatedby) 
						select a._roadcode,a._srocode,v_propertytypeid,
						a._unitid,a._rate,a._sfdaid,a._sfdaid::character varying from unnest(v_valratedetail_arry) a;
					GET DIAGNOSTICS v_success = ROW_COUNT;
		end if;	
		
	elsif (v_valratedetailid is not null and v_valratedetailid > 0) then 
		
		if(v_isdelete is not null and v_isdelete = 'true') then
				delete from kaveri.mas_valuationrates where valratedetailid = v_valratedetailid; 
				GET DIAGNOSTICS v_success = ROW_COUNT;
		elsif (v_agrilandtypeid is not null and v_agrilandtypeid <> 0 and v_propertytypeid=17) then 
				update kaveri.mas_valuationrates set
					agrilandtypeid = a._agrilandtypeid,unitid = a._unitid,rate = a._rate,
					 sfdaid=a._sfdaid,updatedby=a._sfdaid::character varying 
					 from unnest(v_valratedetail_arry) a
						where valratedetailid = v_valratedetailid; 
					GET DIAGNOSTICS v_success = ROW_COUNT;
--		elsif (v_amenitiesid is not null and v_amenitiesid <> 0) then 
		elsif (v_propertytypeid is not null and v_propertytypeid=12)	then
				update kaveri.mas_valuationrates set
				unitid = a._unitid,rate = a._rate,
					 sfdaid=a._sfdaid,updatedby=a._sfdaid::character varying 
					 from unnest(v_valratedetail_arry) a
						where valratedetailid = v_valratedetailid; 
					GET DIAGNOSTICS v_success = ROW_COUNT;
		elsif (v_propertytypeid is not null and v_propertytypeid <> 0 and v_propertytypeid <> 17) then
				update kaveri.mas_valuationrates set
				propertytypeid = a._propertytypeid,unitid = a._unitid,rate = a._rate,
					 sfdaid=a._sfdaid,updatedby=a._sfdaid::character varying 
					 from unnest(v_valratedetail_arry) a
						where valratedetailid = v_valratedetailid; 
					GET DIAGNOSTICS v_success = ROW_COUNT;
		end if;
	
	end if;
  exception when others then
	 v_success:=-1;

	-- RAISE EXCEPTION 'Master Valuation data Status --> %', v_success
     --USING HINT = 'Please check valuation data';
	 end ;
	 
 END LOOP;
 end if;
	return v_success;
END;
$$;


ALTER FUNCTION kaveri.fn_insert_masvaluation_detail(p_valratedetail kaveri.valratedetail_input[]) OWNER TO csgadmin;

--
-- Name: fn_insert_masvaluation_header(bigint, timestamp without time zone, bigint, text, text); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_masvaluation_header(p_srocode bigint, p_effectivedate timestamp without time zone, p_sfdaid bigint, p_circularpath text, p_circularinfo text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
   v_valheaderid bigint;
BEGIN 
		insert into kaveri.mas_valrateheader 
		(srocode,effectivedate,active,sfdaid,circularpath,circularinfo,updatedby,requestdate)
		values (p_srocode,p_effectivedate,'true',p_sfdaid,p_circularpath,p_circularinfo,p_sfdaid::character varying,current_timestamp) 
		returning valrateheaderid into v_valheaderid;
		
		insert into kaveri.mas_valratedetail 
		(valrateheaderid,roadcode,srocode,propertytypeid,agrilandtypeid,
			floorid,amenitiesid, unitid,rate,sfdaid,updatedby,effectivedate)
		select v_valheaderid,roadcode,srocode,propertytypeid,agrilandtypeid,
			floorid,amenitiesid, unitid,rate,p_sfdaid,p_sfdaid::character varying,p_effectivedate
		from kaveri.mas_valuationrates 
		where srocode = p_srocode and sfdaid=p_sfdaid and valrateheaderid is null;
		
		update kaveri.mas_valuationrates set valrateheaderid=v_valheaderid,effectivedate=p_effectivedate
		where srocode = p_srocode and sfdaid=p_sfdaid and valrateheaderid is null;

	return v_valheaderid; 
END;
$$;


ALTER FUNCTION kaveri.fn_insert_masvaluation_header(p_srocode bigint, p_effectivedate timestamp without time zone, p_sfdaid bigint, p_circularpath text, p_circularinfo text) OWNER TO csgadmin;

