--
-- Name: fn_insert_memofeesrequired(character varying, numeric); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_memofeesrequired(_applicationnumber character varying, _amount numeric) RETURNS integer
    LANGUAGE plpgsql
    AS $$

DECLARE
v_cnt int;
v_fee int;
begin
	select count(*) into v_cnt from kaveri.feesrequired where applicationnumber =_applicationnumber and feerulecode =90;	
	if v_cnt=0
	then 

	insert into kaveri.feesrequired
	select documentid,91 as feerulecode,isexempted,exemptdescription,isactive,feecalculationstring,srocode,isonline,_amount
	,applicationnumber,propertyid,lastupdateddate,exemtype,exemamount,exemdocpath,denodocpath,sfdaamountrequired
	,sroamountrequired,amountpaid,valuatiotypeid,sfdastamprule,srostamprule,regexemtype,regexemamount,paymentstatus,inserteddatetime
	,k1k2_flag,receiptid,undervaluationamount
 	from kaveri.feesrequired where applicationnumber=_applicationnumber limit 1
	RETURNING feerulecode::integer into v_fee;
	
	else 

	update kaveri.feesrequired set amountrequired=_amount 
	where applicationnumber=_applicationnumber and feerulecode=90
	RETURNING feerulecode::integer into v_fee;
	
	end if;
return v_fee;
end;
$$;


ALTER FUNCTION kaveri.fn_insert_memofeesrequired(_applicationnumber character varying, _amount numeric) OWNER TO postgres;

--
-- Name: fn_insert_mrg_feedetail(kaveri.mrg_requiredfees_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_mrg_feedetail(p_mrgrequiredfees kaveri.mrg_requiredfees_input[]) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
     v_mrgrequiredfees p_mrgrequiredfees%type;
 v_cnt integer;
 v_applicationnumber character varying;
 v_srocode int;
 
BEGIN
	/* Fees Required */
	
	if(p_mrgrequiredfees is not null and array_length(p_mrgrequiredfees,1)>0 ) then
FOR v_mrgrequiredfees IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_mrgrequiredfees))
loop
v_cnt:= 0;
Select count(*) into v_cnt from kaveri.mrg_requiredfees where applicationnumber in 
(select a._applicationnumber from unnest(v_mrgrequiredfees) a) and feeruleid in 
(select a._feeruleid from unnest(v_mrgrequiredfees) a);

select regsrocode into v_srocode from kaveri.applicantapplicationdetails a where applicationnumber in
(select a._applicationnumber from unnest(v_mrgrequiredfees) a);

if v_cnt = 0 then 
INSERT INTO kaveri.mrg_requiredfees(
requiredfeeid,
mrgregistrationid,
feeruleid,
payableamount,
ispaid,
serviceid,
feedescription,
applicationnumber,
srocode,
amountpaid
)
select nextval('kaveri.mrg_requiredfees_seq'),
a._mrgregistrationid,
a._feeruleid,
a._payableamount,
a._ispaid,
a._serviceid,
a._feedescription,
a._applicationnumber,
v_srocode,
a._payableamount
from unnest(v_mrgrequiredfees) a
RETURNING applicationnumber::character varying into v_applicationnumber;
else 
	 update kaveri.mrg_requiredfees set
	 mrgregistrationid=a._mrgregistrationid,
   feeruleid=a._feeruleid,
   payableamount=a._payableamount,
   ispaid=a._ispaid,
   serviceid=a._serviceid,
   feedescription=a._feedescription,
   applicationnumber = a._applicationnumber,
   srocode = v_srocode,
   amountpaid = a._payableamount
	from unnest(v_mrgrequiredfees) a where applicationnumber in 
			 (select a._applicationnumber from unnest(v_mrgrequiredfees) a) and feeruleid in 
(select a._feeruleid from unnest(v_mrgrequiredfees) a)
		RETURNING applicationnumber::character varying into v_applicationnumber;
	 end if;
	
--	if a._ispaid = true 
--	
--	update kaveri.mrg_requiredfees set amountpaid = a._payableamount from unnest(v_mrgrequiredfees) a where applicationnumber in 
--			 (select a._applicationnumber from unnest(v_mrgrequiredfees) a) and feeruleid in 
--	(select a._feeruleid from unnest(v_mrgrequiredfees) a)
	
	end loop;
	end if;
        Return v_applicationnumber;
		
end;
$$;


ALTER FUNCTION kaveri.fn_insert_mrg_feedetail(p_mrgrequiredfees kaveri.mrg_requiredfees_input[]) OWNER TO csgadmin;

--
-- Name: fn_insert_multiplerole(integer, bigint, boolean, integer, kaveri.multiplerole_type[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_multiplerole(_userid integer, _phoneno bigint, _isactive boolean, _updatedby integer, _rollinfo_array kaveri.multiplerole_type[] DEFAULT NULL::kaveri.multiplerole_type[]) RETURNS integer
    LANGUAGE plpgsql
    AS $$




DECLARE

v_permission_row record;
v_count integer;
v_counter integer;
BEGIN 

	if(_rollinfo_array is not null and array_length(_rollinfo_array,1)=1 ) then
	
		for v_permission_row in 
				(
				 	 select a.userid,a.designationid  from unnest(_rollinfo_array)a 
				)
				
					loop
						
						update kaveri.departmentusers set designationid=v_permission_row.designationid,
						mobileno=_phoneno,serviceflag=_isactive,createdby=_updatedby where userid=_userid;
		
	  					 delete from kaveri.departmentuserroles  where userid=_userid and (mappeduserid is null or mappeduserid=0);
						
							
					end loop;
		
	
	elsif(_rollinfo_array is not null and array_length(_rollinfo_array,1)>1 ) then

			
				for v_permission_row in 
				(
				 (select userid,designationid  from kaveri.departmentuserroles where userid=_userid  and  (mappeduserid is null or mappeduserid=0)
				 except 
				 select a.userid,a.designationid  from unnest(_rollinfo_array)a )
				 
				 union all
				 
				 select a.userid,a.designationid  from unnest(_rollinfo_array)a limit 1
				 
				 
				)
				
					loop
						
						delete from kaveri.departmentuserroles  where  userid=v_permission_row.userid and designationid=v_permission_row.designationid and (mappeduserid is null or mappeduserid=0);
							
					end loop;
		
				v_counter:=1;
				 for v_permission_row in  
				 (	select a.userid,a.designationid  from unnest(_rollinfo_array)a  )
				 	
				 	loop
					    if v_counter=1 then
						
							update kaveri.departmentusers set designationid=v_permission_row.designationid,
							mobileno=_phoneno,serviceflag=_isactive,createdby=_updatedby where userid=_userid;
						ELSE
						
						
						
								select count(*) into v_count from kaveri.departmentuserroles  where  userid=v_permission_row.userid and
								designationid=v_permission_row.designationid and (mappeduserid is null or mappeduserid=0);
							
								if v_count=0 then
						
									insert into kaveri.departmentuserroles (userid,designationid,updatedby)
									values(v_permission_row.userid,v_permission_row.designationid,_updatedby);
								end if;
						end if;
					 v_counter:=v_counter+1;
					 	
					 	
				 		
				 	end loop;

end if;
 	
		


 
raise notice 'roll updated for rollid %',_userid;
return _userid;
  

END;

$$;


ALTER FUNCTION kaveri.fn_insert_multiplerole(_userid integer, _phoneno bigint, _isactive boolean, _updatedby integer, _rollinfo_array kaveri.multiplerole_type[]) OWNER TO csgadmin;

--
-- Name: fn_insert_openbuiltvaluationdetails(kaveri.val_openbuiltvaluationdetails_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_openbuiltvaluationdetails(p_openbuiltvaluationdetails kaveri.val_openbuiltvaluationdetails_input[] DEFAULT NULL::kaveri.val_openbuiltvaluationdetails_input[]) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
Declare

v_arry_openbuiltvaluationdetails kaveri.val_openbuiltvaluationdetails_input[];
v_cnt integer;
v_valid bigint;
 v_pid bigint[];
begin
		if(p_openbuiltvaluationdetails is not null and array_length(p_openbuiltvaluationdetails,1)>0 ) then
				FOR v_arry_openbuiltvaluationdetails IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_openbuiltvaluationdetails)) 
					loop
						v_cnt:= 0;
						Select count(*) into v_cnt from kaveri.val_openbuiltvaluationdetails where openbuiltvalid in 
						(select a._openbuiltvalid from unnest(v_arry_openbuiltvaluationdetails) a) ;
						if v_cnt = 0 then
							insert into kaveri.val_openbuiltvaluationdetails (
								 openbuiltvalid,
									propertytypeid,
									roadid,
									unitid,
									rate,
									valuationid,
									verified,
									openbuiltrateid,
									srocode,
									regsrocode)
									select nextval('kaveri.val_openbuiltvaluationdetails_seq'),
									a._propertytypeid,
									a._roadid,
									a._unitid,
									a._rate,
									a._valuationid,
									a._verified,
									a._openbuiltrateid,
									a._srocode,
									a._regsrocode
								from unnest(v_arry_openbuiltvaluationdetails) a
								 returning valuationid::bigint into v_valid;
								--v_pid := array_append(v_pid,v_valid);
						else
							update kaveri.val_openbuiltvaluationdetails set
												--annexuredetailsid = a._annexuredetailsid,
												propertytypeid=a._propertytypeid,
									           roadid=a._roadid,
									           unitid=a._unitid,
									           rate=a._rate,
									          valuationid=a._valuationid,
									          verified=a._verified,
									          openbuiltrateid=a._openbuiltrateid,
									          srocode=a._srocode,
									          regsrocode=a._regsrocode
												 from unnest(v_arry_openbuiltvaluationdetails) a where openbuiltvalid in 
														 (select a._openbuiltvalid from unnest(v_arry_openbuiltvaluationdetails) a) 
														 RETURNING valuationid::bigint into v_valid;
						end if;
						--v_pid := array_append(v_pid,v_valid);
					end loop;
			end if;
Return v_valid;
   END;
$$;


ALTER FUNCTION kaveri.fn_insert_openbuiltvaluationdetails(p_openbuiltvaluationdetails kaveri.val_openbuiltvaluationdetails_input[]) OWNER TO csgadmin;

--
-- Name: fn_insert_orgdatajslip(kaveri.orgdatajslip_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_orgdatajslip(kaveri.orgdatajslip_input[] DEFAULT NULL::kaveri.orgdatajslip_input[]) RETURNS character varying
    LANGUAGE plpgsql
    AS $_$
declare 
v_cnt integer;
v_applicationnumber character varying;
begin 
	select count(*) into v_cnt from kaveri.orgdatajslip where propertyid  in (select a2._propertyid from unnest($1) a2) 
and partyid in (select a3._partyid from unnest($1)a3) and partytypeid in (select a4._partytypeid from unnest($1) a4);

if (v_cnt=0)

then 
insert into kaveri.orgdatajslip(partyid ,documentid ,propertyid,partytypeid ,firstname ,mainownerno ,ownerno ,transactextacre ,transactextgunta ,transactextfgunta ,applicationnumber,relativename,relationship)
select a._partyid 
,a._documentid 
,a._propertyid 
,a._partytypeid
,a._firstname 
,a._mainownereno 
,a._ownerno ,a._transactextacre ,a._transactextgunta ,a._transactextfgunta ,a._applicationnumber,a._relativename,a._relationship from unnest($1) a;
 select a1._applicationnumber into v_applicationnumber from unnest($1) a1 ;

else 
v_applicationnumber:='Already Exists';
end if;

return  v_applicationnumber;
end;
$_$;


ALTER FUNCTION kaveri.fn_insert_orgdatajslip(kaveri.orgdatajslip_input[]) OWNER TO csgadmin;

--
-- Name: fn_insert_otherreceiptdetails(kaveri.otherpaymentdetails_input[], kaveri.otherfeereequired[]); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_otherreceiptdetails(kaveri.otherpaymentdetails_input[], _otherfeerequired kaveri.otherfeereequired[]) RETURNS bigint
    LANGUAGE plpgsql
    AS $_$
 DECLARE
v_Arr bigint;
v_departmentuserid bigint;
 v_cnt int;	  
begin
select departmentuserid into v_departmentuserid from unnest(_otherfeerequired);
select count(*) into v_cnt from kaveri.otherreceiptdetails where lower(ddchallannumber) in (select lower(ddchallannumber) from unnest($1));	 
if(v_cnt=0)
then 	 
	  insert into kaveri.otherreceiptdetails
       (receiptid,
       partyfirstname,
       partymiddlename,
       partylastname,
       receipttype,
       receiptdate,
       paymentmode,
       receipttotal,
       paymentdescription,
       ifsccode,
       micrcode,
       ddchallannumber,
       dddate ,
       subpurposedetails,
       receipttypefromdate,
       receipttypetodate,
       financialYears,
       bookdetails,
       ceritificateruletype,departmentuserid)
       select 
       nextval('kaveri.otherrecdetail_receiptid_seq'),
       b.partyfirstname ,
       b.partymiddlename ,
       b.partylastname ,
       b.receipttype,
       b.receiptdate,
       b.paymentmode,
       b.receipttotal,
       b.paymentdescription,
       b.ifsccode,
       b.micrcode ,
       upper(b.ddchallannumber),
       b.dddate,
       b.subpurposedetails,
       b.receipttypefromdate,
       b.receipttypetodate,
       b.financialYears,
       b.bookdetails,
       b.ceritificateruletype, 
       v_departmentuserid from unnest($1) b
	  	returning receiptid::bigint into v_Arr;
	   
	   insert into kaveri.otherfeesrequired 
	   (feerulecode,
	   applicationnumber,
	   feerequied,
	   receiptid,
	   departmentuserid)
	   select 
	   c.feerulecode,
	   c.applicationnumber,
	   c.feerequired,
		v_Arr,
	   v_departmentuserid
	  from unnest(_otherfeerequired) c;
end if;		
	
		 return v_Arr;
	  
	  end;
	 
	  $_$;


ALTER FUNCTION kaveri.fn_insert_otherreceiptdetails(kaveri.otherpaymentdetails_input[], _otherfeerequired kaveri.otherfeereequired[]) OWNER TO postgres;

--
-- Name: fn_insert_parkingratedetails(kaveri.val_parkingratedetails_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_parkingratedetails(p_parkingratedetails kaveri.val_parkingratedetails_input[] DEFAULT NULL::kaveri.val_parkingratedetails_input[]) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
Declare

v_arry_parkingratedetails kaveri.val_parkingratedetails_input[];
v_cnt integer;
v_valid bigint;
begin
		if(p_parkingratedetails is not null and array_length(p_parkingratedetails,1)>0 ) then
				FOR v_arry_parkingratedetails IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_parkingratedetails)) 
					loop
						v_cnt:= 0;
						Select count(*) into v_cnt from kaveri.val_parkingratedetails where parkingdetailsid in 
						(select a._parkingdetailsid from unnest(v_arry_parkingratedetails) a) ;
						if v_cnt = 0 then
							insert into kaveri.val_parkingratedetails (
								parkingdetailsid,
    							parkingtypeid,
    							totalparkings,
    							rate,
    							verified,
    							valuationid,
    							srocode,
    							regsrocode
								)
								select 
								 nextval('kaveri.val_parkingratedetails_seq'),
								a._parkingtypeid,
    							a._totalparkings,
    							a._rate,
    							a._verified,
    							a._valuationid,
    							a._srocode,
    							a._regsrocode
								from unnest(v_arry_parkingratedetails)	a
								 returning valuationid::bigint into v_valid;
						else
							update kaveri.val_parkingratedetails set
												parkingtypeid=a._parkingtypeid,
    											totalparkings=a._totalparkings,
    											rate=a._rate,
    											verified=a._verified,
    											valuationid=a._valuationid,
    											srocode=a._srocode,
    											regsrocode=a._regsrocode
												 from unnest(v_arry_parkingratedetails) a where parkingdetailsid in 
														 (select a._parkingdetailsid from unnest(v_arry_parkingratedetails) a) 
														 RETURNING valuationid::bigint into v_valid;
						end if;
						
					end loop;
			end if;
Return v_valid;
   END;
$$;


ALTER FUNCTION kaveri.fn_insert_parkingratedetails(p_parkingratedetails kaveri.val_parkingratedetails_input[]) OWNER TO csgadmin;

--
-- Name: fn_insert_party_info(kaveri.party_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_party_info(p_partydetails kaveri.party_input[] DEFAULT NULL::kaveri.party_input[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $_$
DECLARE cit_id text;
-- party_arry $1%type;
v_party_arry kaveri.party_input [];
v_txt text;
v_partyid bigint;
v_partyid1 bigint;
v_partytypeid integer;
v_cnt integer;
var_r record;
v_linkpartyid bigint;
v_pid bigint [];
BEGIN --Select count(*) into v_cnt from kaveri.partyinfo where partyid in 
--(select a._partyid from unnest($1) a) ;
if(
	p_partydetails is not null
