FOR v_party_arry IN (
	SELECT kaveri.fn_fetch_1d_arrayofarray(p_partydetails)
) loop v_cnt := 0;
Select count(*) into v_cnt
from kaveri.partyinfo
where partyid in (
		select a._partyid
