		availableextacre,
		availableextgunta,
		availableextfgunta,
		bincom,
		category,
		dateofdeath,
		fingerid,
		fingerverificationstatusid,
		ispartofrtc,
		landcode,
		mainownerno,
		ownerno,
		partypoa,
		photopath,
		poaadmission,
		poapresentation,
		primaryseller,
		profession,
		restriction,
		restrictiondescription,
		restrictiontype,
		section88exemption,
		thumbmatchfailedreasonid,
		thumbminutiae,
		thumbpath,
		totalextacre,
		totalextgunta,
		totalextfgunta,
		transactextacre,
		transactextgunta,
		transactextfgunta,
		volumename,
		hasgpa,
		isaua,
		importedpartyparentid,
		salutationid,
		isorganization,
		organizationid,
		applicationnumber,
		verified,
		issroapproved,
		districtcode,
		talukcode,
		hoblicode,
		villagecode,
		tanno,
		yearofincorp,
		orgpoaauthsignfname,
		orgpoaauthsignmname,
		orgpoaauthsignlname,
		linkpartyid,
		housenumber,
		pin,
		propertyid,
		propertynumber,
		idprooftypeid,
		coveringLetterNo,
		section88File
	)
select nextval('kaveri.partyinfo_partyid_seq'),
	--_partyid,
	_srocode,
	_documentid,
	_partytypeid,
	_firstname,
	_middlename,
	_lastname,
	_address,
	_age,
	_sex,
	_isexecutor,
	_ispresenter,
	_admissiondate,
	_aliasname,
	_correctedname,
	_relationship,
	_relativename,
	_epic,
	_pan,
	_phonenumber,
	_availableextacre,
	_availableextgunta,
	_availableextfgunta,
	_bincom,
	_category,
	_dateofdeath,
	_fingerid,
	_fingerverificationstatusid,
	_ispartofrtc,
	_landcode,
	_mainownerno,
	_ownerno,
	_partypoa,
	_photopath,
	_poaadmission,
	_poapresentation,
	_primaryseller,
	_profession,
	_restriction,
	_restrictiondescription,
	_restrictiontype,
	_section88exemption,
	_thumbmatchfailedreasonid,
	_thumbminutiae,
	_thumbpath,
	_totalextacre,
	_totalextgunta,
	_totalextfgunta,
	_transactextacre,
	_transactextgunta,
	_transactextfgunta,
	_volumename,
	_hasgpa,
	_isaua,
	_importedpartyparentid,
	_salutationid,
	_isorganization,
	_organizationid,
	_applicationnumber,
	_verified,
	_issroapproved,
	_districtcode,
	_talukcode,
	_hoblicode,
	_villagecode,
	_tanno,
	_yearofincorp,
	_orgpoaauthsignfname,
	_orgpoaauthsignmname,
	_orgpoaauthsignlname,
	_linkpartyid,
	_housenumber,
	_pin,
	_propertyid,
	_propertynumber,
	_idprooftypeid,
	_coveringLetterNo,
	_section88File --from unnest(party_arry)	
from unnest(v_party_arry)
RETURNING partyid::bigint into v_partyid;
else --	cit_id := v_txt||' '||cit_id;
update kaveri.partyinfo
set srocode = a._srocode,
	documentid = a._documentid,
	partytypeid = a._partytypeid,
	firstname = a._firstname,
	middlename = a._middlename,
	lastname = a._lastname,
	address = a._address,
	age = a._age,
	sex = a._sex,
	isexecutor = a._isexecutor,
	ispresenter = a._ispresenter,
	admissiondate = a._admissiondate,
	aliasname = a._aliasname,
	correctedname = a._correctedname,
	relationship = a._relationship,
	relativename = a._relativename,
	epic = a._epic,
	pan = a._pan,
	phonenumber = a._phonenumber,
	--availableextacre=a._availableextacre, 
	--availableextgunta=a._availableextgunta, 
	--availableextfgunta=a._availableextfgunta, 
	bincom = a._bincom,
	category = a._category,
	dateofdeath = a._dateofdeath,
	fingerid = a._fingerid,
	fingerverificationstatusid = a._fingerverificationstatusid,
	ispartofrtc = a._ispartofrtc,
	landcode = a._landcode,
	mainownerno = a._mainownerno,
	ownerno = a._ownerno,
	partypoa = a._partypoa,
	photopath = a._photopath,
	poaadmission = a._poaadmission,
	poapresentation = a._poapresentation,
	primaryseller = a._primaryseller,
	profession = a._profession,
	restriction = a._restriction,
	restrictiondescription = a._restrictiondescription,
	restrictiontype = a._restrictiontype,
	section88exemption = a._section88exemption,
	thumbmatchfailedreasonid = a._thumbmatchfailedreasonid,
	thumbminutiae = a._thumbminutiae,
	thumbpath = a._thumbpath,
	totalextacre = a._totalextacre,
	totalextgunta = a._totalextgunta,
	totalextfgunta = a._totalextfgunta,
	transactextacre = a._transactextacre,
	transactextgunta = a._transactextgunta,
	transactextfgunta = a._transactextfgunta,
	volumename = a._volumename,
	hasgpa = a._hasgpa,
	isaua = a._isaua,
	importedpartyparentid = a._importedpartyparentid,
	salutationid = a._salutationid,
	isorganization = a._isorganization,
	organizationid = a._organizationid,
	--applicationnumber=a._applicationnumber,
	verified = a._verified,
	issroapproved = a._issroapproved,
	districtcode = a._districtcode,
	talukcode = a._talukcode,
	hoblicode = a._hoblicode,
	villagecode = a._villagecode,
	tanno = a._tanno,
	yearofincorp = a._yearofincorp,
	orgpoaauthsignfname = a._orgpoaauthsignfname,
	orgpoaauthsignmname = a._orgpoaauthsignmname,
	orgpoaauthsignlname = a._orgpoaauthsignlname,
	--linkpartyid=a._linkpartyid,
	housenumber = a._housenumber,
	pin = a._pin,
	--propertyid=a._propertyid,
	propertynumber = a._propertynumber,
	idprooftypeid = a._idprooftypeid,
	coveringLetterNo = a._coveringLetterNo,
	section88File = a._section88File
from unnest(v_party_arry) a
where partyid in (
		select a._partyid
		from unnest(v_party_arry) a
	)
	and applicationnumber in (
		select a9._applicationnumber
		from unnest(v_party_arry) a9
	)
RETURNING partyid::bigint into v_partyid;
end if;
select partytypeid,
	linkpartyid into v_partytypeid,
	v_linkpartyid
from kaveri.partyinfo
where partyid = v_partyid;
/* select partyid,partytypeid into v_partyid1,v_partytypeid
 from kaveri.partyinfo where partyid = v_partyid;*/
if (v_partytypeid = 9)
and (v_linkpartyid is not null) then null;
elsif (v_partytypeid = 5)
and (v_linkpartyid is not null) then null;
elsif (v_partytypeid = 4)
and (v_linkpartyid is not null) then null;
end if;
if (v_partytypeid = 9)
and (v_linkpartyid is null) then
update kaveri.partyinfo
set linkpartyid = v_partyid -1
where partyid = v_partyid -- Authorized signatory
	and partytypeid = 9;
-- and linkpartyid = null;
elsif (v_partytypeid = 5)
and (v_linkpartyid is null) then
update kaveri.partyinfo
set linkpartyid = v_partyid -1
where partyid = v_partyid -- Power of attorney
	and partytypeid = 5;
--  and linkpartyid = null;
elsif (v_partytypeid = 4)
and (v_linkpartyid is null) then
update kaveri.partyinfo
set linkpartyid = v_partyid -1
where partyid = v_partyid --  Minor Guardian
	and partytypeid = 4;
end if;
/*if v_partytypeid = 9 then
 update kaveri.partyinfo set linkpartyid = v_partyid-1 where partytypeid = 9
 and partyid = v_partyid;
 elsif v_partytypeid = 5 then
 update kaveri.partyinfo set linkpartyid = v_partyid-1 where partytypeid = 5
 and partyid = v_partyid;
 end if;*/
--end if;
v_pid := array_append(v_pid, v_partyid);
END LOOP;
end if;
return v_pid;
END;
$_$;


ALTER FUNCTION kaveri.fn_insert_party_info(p_partydetails kaveri.party_input[]) OWNER TO csgadmin;

--
-- Name: fn_insert_party_info(kaveri.partyinfo_input[], bigint); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_party_info(p_partydetails kaveri.partyinfo_input[] DEFAULT NULL::kaveri.partyinfo_input[], p_linkpartyid bigint DEFAULT NULL::bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $_$

DECLARE
  v_party_arry kaveri.partyinfo_input[];
   v_partyid bigint;
   v_cnt integer;
   v_partyid_guid varchar(50);
   v_party_success boolean default 'true';
   v_party_exists boolean default 'false';
   v_isdelete boolean ;
   v_application varchar(100);
   v_propertyid int;
   v_partytypeid int;
  v_partyid_org int;
 v_currentstatus character varying;
v_isduecorrection boolean;
BEGIN

select currentstatus,isduecorrection into v_currentstatus,v_isduecorrection
from kaveri.applicantapplicationdetails a where applicationnumber =(p_partydetails)[1]._applicationnumber;

	
if(v_currentstatus<>'CD101' and not (v_currentstatus = 'CD106' and v_isduecorrection = true))
then
	
raise exception 'Invalid user operation';


end if;
		
	
if(p_partydetails is not null and array_length(p_partydetails,1)>0 ) then
   
 FOR v_party_arry IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_partydetails)) 
					loop
		v_cnt:= 0;
		v_partyid:=null;
		v_partyid_guid :=null;
		v_party_exists := 'false';

	begin					
		

		
	select a._partyid,(a._partyid ~ '^[0-9]+$'),a._verified,a._applicationnumber into 
		v_partyid_guid,v_party_exists,v_isdelete,v_application from unnest(v_party_arry) a ;
		
	if (v_partyid_guid is not null) then 
	  Select count(*) into v_cnt from kaveri.partyinfo where partyid in 
					(case when v_party_exists ='true' then v_partyid_guid::bigint 
							   else 0 end);							   
							   
	
	if v_cnt = 0 then
  INSERT INTO kaveri.partyinfo(partyid,
srocode,DOCUMENTID, partytypeid, firstname, middlename, lastname, address, age, sex, 
isexecutor, ispresenter,  aliasname, relationship, relativename,  pan, 
	phonenumber, dateofdeath, partypoa, profession, restriction, restrictiondescription, restrictiontype, section88exemption, 
isaua, salutationid, isorganization, organizationid,applicationnumber,verified,districtcode,talukcode,
hoblicode,villagecode,
tanno,yearofincorp,orgpoaauthsignfname, orgpoaauthsignmname, orgpoaauthsignlname,linkpartyid,housenumber,pin,
		idprooftypeid,propertyid,availableextacre,availableextgunta,availableextfgunta,
	bincom,category,landcode,mainownerno,ownerno,totalextacre,totalextgunta,totalextfgunta,
	transactextacre,transactextgunta,transactextfgunta,isconsentwitness,isprivateattendance,
			coveringLetterNo,section88File,isduplicate,duplicatepartyid,photopath,thumbpath,isendorseprinted,islateapperance,admissiondate)
    select  nextval('kaveri.partyinfo_partyid_seq'),
	_srocode,0, _partytypeid, _firstname,_middlename,_lastname, coalesce(_address,' '),_age,_sex,_isexecutor,
	_ispresenter, _aliasname,_relationship,_relativename,_pan,_phonenumber,
	_dateofdeath,_partypoa,_profession,_restriction,_restrictiondescription,
	_restrictiontype,_section88exemption ,_isaua,_salutationid ,_isorganization ,_organizationid,_applicationnumber,
	_verified,_districtcode,_talukcode,_hoblicode,_villagecode,
	 _tanno,_yearofincorp,_orgpoaauthsignfname,_orgpoaauthsignmname,_orgpoaauthsignlname,
    coalesce(p_linkpartyid,(CASE WHEN _linkpartyid IS NOT NULL THEN _linkpartyid::BIGINT ELSE NULL END),NULL),_housenumber,_pin,_idprooftypeid,
	_propertyid,_availableextacre,_availableextgunta,_availableextfgunta,
	_bincom,_category,_landcode,_mainownerno,_ownerno,_totalextacre,_totalextgunta,_totalextfgunta,
	_transactextacre,_transactextgunta,_transactextfgunta ,_isconsentwitness,_isprivateattendance,
	_coveringLetterNo,_section88File,_isduplicate,_duplicatepartyid,_photopath,_thumbpath,_isendorseprinted,_islateapperance,_admissiondate
	from unnest(v_party_arry)
    RETURNING partyid::bigint into v_partyid;
	
	select _propertyid into v_propertyid from unnest(v_party_arry);
   
	if (v_propertyid is not null)
	then 
   
   	insert into  kaveri.orgdatajslip(partyid,documentid,propertyid,partytypeid,firstname,mainownerno,ownerno,transactextacre,transactextgunta,transactextfgunta,applicationnumber, relationship, relativename)
   	select v_partyid,null as documentid,_propertyid,_partytypeid,CONCAT(_firstname,_middlename,_lastname),_mainownerno,_ownerno,_transactextacre,_transactextgunta,_transactextfgunta,_applicationnumber,_relationship,_relativename from unnest(v_party_arry);
	
	
	end if;
	
	
	 else
  update kaveri.partyinfo set
srocode = a._srocode,
partytypeid = a._partytypeid, 
firstname = a._firstname, 
middlename = a._middlename, 
lastname = a._lastname, 
address = coalesce(a._address,' '), 
age = a._age, 
sex = a._sex, 
isexecutor = a._isexecutor, 
ispresenter=a._ispresenter, 
aliasname=a._aliasname, 
relationship=a._relationship, 
relativename=a._relativename,
pan=a._pan, 
phonenumber=a._phonenumber, 
dateofdeath=a._dateofdeath, 
partypoa=a._partypoa, 
profession=a._profession, 
restriction=a._restriction, 
restrictiondescription=a._restrictiondescription, 
restrictiontype=a._restrictiontype, 
section88exemption=a._section88exemption, 
isaua=a._isaua,
salutationid=a._salutationid, 
isorganization=a._isorganization, 
organizationid=a._organizationid,
--applicationnumber=a._applicationnumber,
verified=a._verified,
districtcode=a._districtcode,
talukcode=a._talukcode,
hoblicode=a._hoblicode,
villagecode=a._villagecode,
tanno = a._tanno,
yearofincorp = a._yearofincorp,
orgpoaauthsignfname = a._orgpoaauthsignfname, 
orgpoaauthsignmname = a._orgpoaauthsignmname, 
orgpoaauthsignlname = a._orgpoaauthsignlname,
housenumber=a._housenumber,
	pin=a._pin,
	idprooftypeid=a._idprooftypeid,
	isconsentwitness=a._isconsentwitness,
	isprivateattendance=a._isprivateattendance	,
	coveringLetterNo=a._coveringLetterNo,
	section88File=a._section88File,
	isduplicate=a._isduplicate,
	duplicatepartyid=a._duplicatepartyid,
	photopath=a._photopath,
	thumbpath=a._thumbpath,
	isendorseprinted=a._isendorseprinted,
	islateapperance =a._islateapperance,
	admissiondate =a._admissiondate
	from unnest(v_party_arry) a
  where partyid = v_partyid_guid::bigint
 RETURNING partyid::bigint into v_partyid;

select a._partyid  into
		v_partyid_org from unnest(v_party_arry) a ;

select partytypeid into v_partytypeid from kaveri.orgdatajslip where partyid =v_partyid_org::bigint and partytypeid=1;	
		
 if (v_partytypeid is not null)
 then 
 
 update kaveri.orgdatajslip set firstname=CONCAT(a._firstname,a._middlename,a._lastname), relativename=a._relativename,relationship=a._relationship
 from unnest(v_party_arry) a
 where partyid=v_partyid_org::bigint and partytypeid=1;
 
 end if;
 
 end if;
 end if;
 -- exception when others then
	-- v_party_success:='false';
	--  RAISE EXCEPTION 'Party ID --> %', v_application
    --  USING HINT = 'Please check party data';

--end if;
	 end ;
	 
 END LOOP;
 
 end if;
return v_partyid;
END;
$_$;


ALTER FUNCTION kaveri.fn_insert_party_info(p_partydetails kaveri.partyinfo_input[], p_linkpartyid bigint) OWNER TO csgadmin;

--
-- Name: fn_insert_party_info_all(kaveri.party_schedules_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_party_info_all(party_schedules kaveri.party_schedules_input[] DEFAULT NULL::kaveri.party_schedules_input[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $_$
DECLARE 
v_arr_partyschedule record;
v_applicationnumber character varying;
v_pid bigint [];
v_partyid bigint;
v_partyscheduled bigint;
v_partyschedulecnt bigint;
v_partyscheduleid bigint;
v_isdelete_partyschedule boolean default 'false';
v_countofparty bigint;
BEGIN
if (party_schedules is not null and array_length(party_schedules, 1) > 0)
then

FOR v_arr_partyschedule IN (select _partyscheduleid,_partyid,_scheduleid,_propertyid,_applicationnumber
,_isdelete from unnest(party_schedules)) 
loop
 v_partyschedulecnt := 0;
begin
	
if(v_arr_partyschedule._isdelete= 'false' 
and v_arr_partyschedule._partyscheduleid is null
) then 
select count(partyid) into v_countofparty
from kaveri.partyschedules p
where p.applicationnumber = v_arr_partyschedule._applicationnumber
	and p.scheduleid = v_arr_partyschedule._scheduleid --v_partyscheduled
	and p.partyid= v_arr_partyschedule._partyid::bigint ;
--v_partyid;
if(v_countofparty = 0) then
INSERT INTO kaveri.partyschedules(
		partyid,
		scheduleid,
		propertyid,
		applicationnumber
	)
select v_arr_partyschedule._partyid::bigint,
	v_arr_partyschedule._scheduleid,
	v_arr_partyschedule._propertyid,
	v_arr_partyschedule._applicationnumber;
-- from unnest(v_arr_partyschedule) a;
--                    ELSE
--                    
--                            delete from kaveri.partyschedules where applicationnumber=v_applicationnumber and partyid=v_partyid and scheduleid=v_partyscheduled;
--                            /*delete from kaveri.partyschedules where
--                         partyscheduleid  in  (select a._partyscheduleid
--                        from unnest(v_arr_partyschedule) a);*/
end if;
elsif (
	v_arr_partyschedule._isdelete = 'true'
	and v_arr_partyschedule._partyscheduleid is not null
) then

--raise notice 'block 2';
select count(partyid) into v_countofparty
from kaveri.partyschedules p
where p.applicationnumber = v_arr_partyschedule._applicationnumber
	and p.partyscheduleid = v_arr_partyschedule._partyscheduleid
	and p.partyid = v_arr_partyschedule._partyid::bigint;


if(v_countofparty > 0) then
/*delete from kaveri.partyschedules where
 partyscheduleid  in  (select a._partyscheduleid
 from unnest(v_arr_partyschedule) a);*/
delete from kaveri.partyschedules
where applicationnumber = v_arr_partyschedule._applicationnumber
	and partyid = v_arr_partyschedule._partyid::bigint
	and scheduleid = v_arr_partyschedule._scheduleid
	and partyscheduleid = v_arr_partyschedule._partyscheduleid;
delete from kaveri.orgdatajslip
where applicationnumber = v_arr_partyschedule._applicationnumber
	and partyid = v_arr_partyschedule._partyid::bigint
	and propertyid in (
		select propertyid
		from kaveri.propertyschedules
		where scheduleid = v_arr_partyschedule._scheduleid
	)
	and partytypeid = 1;
else

INSERT INTO kaveri.partyschedules(
		partyid,
		scheduleid,
		propertyid,
		applicationnumber
	)
select v_arr_partyschedule._partyid::bigint,
	v_arr_partyschedule._scheduleid,
	v_arr_partyschedule._propertyid,
	v_arr_partyschedule._applicationnumber;
-- from unnest(v_arr_partyschedule) a;
end if;
end if;
-- exception when others then
-- RAISE EXCEPTION 'Partydata ID --> %', v_partyid
--    USING HINT = 'Please check partyschedules data';
end;
end loop;
end if;
--        if(v_partyid is not null ) then
