ALTER FUNCTION kaveri.fn_insert_party_info_all(party_schedules kaveri.party_schedules_input[]) OWNER TO csgadmin;

--
-- Name: fn_insert_party_info_all(kaveri.partyinfo_input[], kaveri.party_schedules_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_party_info_all(p_partydetails kaveri.partyinfo_input[] DEFAULT NULL::kaveri.partyinfo_input[], p_party_schedules kaveri.party_schedules_input[] DEFAULT NULL::kaveri.party_schedules_input[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_party_arry kaveri.partyinfo_input[];
  v_linkparty_arry kaveri.partyinfo_input[];
  v_arr_partyschedule kaveri.party_schedules_input[];
  v_partyid_out bigint; 
   v_partyid bigint; 
   v_ignorepartyid varchar(50);
   v_pid bigint[];
   --v_pid_ignore text[] default null;
   v_partyid_guid varchar(50);
   v_linkpartyid_guid varchar(50);
   v_party_exists boolean default 'false';
   v_linkparty_exists boolean default 'false';   
   v_linkpartyguid_exists boolean default 'false';
   v_partyschedulecnt bigint;
   v_partyscheduleid bigint;
   v_isdelete_partyschedule boolean  default 'false';
   v_partyschedule_partyid_guid varchar(50);
BEGIN

if(p_partydetails is not null and array_length(p_partydetails,1)>0 ) then
   
 FOR v_party_arry IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_partydetails)) 
					loop
		v_partyid:=null;
		v_partyid_guid :=null;
		v_party_exists := 'false';
		v_linkpartyguid_exists := null;
		
	select a._partyid,(a._partyid ~ '^[0-9]+$'),(coalesce(a._linkpartyid,'0') ~ '^[0-9]+$') into 
	v_partyid_guid,v_party_exists,v_linkpartyguid_exists from unnest(v_party_arry) a ;
						
		if(v_party_exists = 'false' and v_linkpartyguid_exists = 'false') then 
			continue;		
		--elsif(v_pid_ignore is null or (v_partyid_guid::text <> any(v_pid_ignore)) ) then
		else
			select kaveri.fn_insert_party_info(v_party_arry) into v_partyid;
		end if;
		if (v_partyid is not null and v_partyid > 0 and p_party_schedules is not null and array_length(p_party_schedules,1)>0) then 
			 
			 FOR v_arr_partyschedule IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_party_schedules))
				loop
				v_partyschedulecnt:= 0;
				v_isdelete_partyschedule := 'false';
				v_partyscheduleid:=null;
				begin
				
				select a._partyscheduleid,a._isdelete,a._partyid into 
				v_partyscheduleid,v_isdelete_partyschedule,v_partyschedule_partyid_guid
				from unnest(v_arr_partyschedule) a ;
				
				if(v_partyschedule_partyid_guid = v_partyid_guid and 
				   v_party_exists = 'false' and v_partyscheduleid is null) then 					
					INSERT INTO kaveri.partyschedules(
					partyid ,scheduleid,  propertyid,applicationnumber)
					select v_partyid ,a._scheduleid,  a._propertyid,a._applicationnumber
						from unnest(v_arr_partyschedule) a;
				elsif(v_partyschedule_partyid_guid::text = v_partyid::text and 
				   v_party_exists = 'true' and v_partyscheduleid is null) then 					
					INSERT INTO kaveri.partyschedules(
					partyid ,scheduleid,  propertyid,applicationnumber)
					select a._partyid::bigint ,a._scheduleid,  a._propertyid,a._applicationnumber
						from unnest(v_arr_partyschedule) a;
				elsif (v_isdelete_partyschedule = 'true' and v_partyscheduleid is not null) then
						delete from kaveri.partyschedules where
						 partyscheduleid  
						 in  (select a._partyscheduleid
						from unnest(v_arr_partyschedule) a);						
				end if;			
			-- exception when others then
			-- RAISE EXCEPTION 'Partydata ID --> %', v_partyid
      		--	USING HINT = 'Please check partyschedules data';
			 end;
			 end loop; 
			 
			end if;
		
		if(v_partyid_guid is not null and v_partyid is not null) then
			FOR v_linkparty_arry IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_partydetails)) 
			loop
		v_ignorepartyid:=null;
		v_linkpartyid_guid :=null;
		v_linkparty_exists := null;
			select a._partyid,a._linkpartyid,(a._linkpartyid ~ '^[0-9]+$') into 
			v_ignorepartyid,v_linkpartyid_guid,v_linkparty_exists from unnest(v_linkparty_arry) a ;
			if(v_partyid_guid = v_linkpartyid_guid and v_linkparty_exists ='false') then 
				select kaveri.fn_insert_party_info(v_linkparty_arry,v_partyid) into v_partyid_out;
				--v_pid_ignore := array_append(v_pid_ignore,v_ignorepartyid);
				 v_pid := array_append(v_pid,v_partyid_out);
			end if;
			
			end loop;
		end if;	
		
	v_pid := array_append(v_pid,v_partyid);
	
 END LOOP;
 end if;
	return v_pid;
END;
$_$;


