--
-- Name: fn_insert_party_info_all_dum(kaveri.party_schedules_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_party_info_all_dum(p_party_schedules kaveri.party_schedules_input[] DEFAULT NULL::kaveri.party_schedules_input[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $$
DECLARE
--  v_party_arry kaveri.partyinfo_input[];
--  v_linkparty_arry kaveri.partyinfo_input[];
  v_arr_partyschedule kaveri.party_schedules_input[];
  v_partyid_out bigint; 
   v_partyids bigint; 
   v_ignorepartyid varchar(50);
   v_pid bigint[];
   --v_pid_ignore text[] default null;
   v_partyid bigint;
   v_partyscheduled bigint ;
--   v_linkpartyid_guid varchar(50);
--   v_party_exists boolean default 'false';
--   v_linkparty_exists boolean default 'false';   
--   v_linkpartyguid_exists boolean default 'false';
   v_partyschedules bigint;
   v_partyschedulecnt bigint;
   v_partyscheduleid bigint;
   v_isdelete_partyschedule boolean  default 'false';
--   v_partyschedule_partyid_guid varchar(50);
BEGIN

	if (p_party_schedules is not null and array_length(p_party_schedules,1)>0) then 
--			 
			 FOR v_arr_partyschedule IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_party_schedules))
				loop
				v_partyschedulecnt:= 0;
				v_isdelete_partyschedule := 'false';
				v_partyscheduleid:=null;
				begin
				
				select a._partyscheduleid,a._isdelete,a._partyid,a._scheduleid into 
				v_partyscheduleid,v_isdelete_partyschedule,v_partyid,v_partyscheduled
				from unnest(v_arr_partyschedule) a ;
			
				select b.partyid,b.scheduleid  into v_partyids,v_partyschedules  from kaveri.partyschedules b ;
				
				if(v_isdelete_partyschedule = 'false' and v_partyscheduleid is null and v_partyid<>v_partyids and v_partyscheduled<>v_partyschedules) then 					
					INSERT INTO kaveri.partyschedules(
					partyid ,scheduleid,  propertyid,applicationnumber)
					select v_partyschedule_partyid_guid ,a._scheduleid,  a._propertyid,a._applicationnumber
						from unnest(v_arr_partyschedule) a;
--				elsif(
--				   v_isdelete_partyschedule = 'true' and v_partyscheduleid is null) then 					
--					INSERT INTO kaveri.partyschedules(
--					partyid ,scheduleid,  propertyid,applicationnumber)
--					select a._partyid::bigint ,a._scheduleid,  a._propertyid,a._applicationnumber
--						from unnest(v_arr_partyschedule) a;
				elsif (v_isdelete_partyschedule = 'true' and v_partyscheduleid is not null and v_partyschedule_partyid_guid=v_partyid and  v_partyscheduled=v_partyschedules) 
				then
						delete from kaveri.partyschedules where
						 partyscheduleid  
						 in  (select a._partyscheduleid
						from unnest(v_arr_partyschedule) a);						
				end if;			
			-- exception when others then
			-- RAISE EXCEPTION 'Partydata ID --> %', v_partyid
      		--	USING HINT = 'Please check partyschedules data';
			 end;
			 end loop; 
			 
			end if;
END
$$;


