CREATE FUNCTION kaveri.fn_insert_party_info_all_dumy(party_schedules kaveri.party_schedules_input[] DEFAULT NULL::kaveri.party_schedules_input[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $_$

DECLARE

 v_arr_partyschedule kaveri.party_schedules_input[];
   v_applicationnumber character varying;
   v_pid bigint[];
   v_partyid bigint;
   v_partyscheduled bigint ;
   v_partyschedulecnt bigint;
   v_partyscheduleid bigint;
   v_isdelete_partyschedule boolean  default 'false';
   v_countofparty bigint;
BEGIN

   if (party_schedules is not null and array_length(party_schedules,1)>0) then
             FOR v_arr_partyschedule IN (SELECT kaveri.fn_fetch_1d_arrayofarray(party_schedules))
                loop
                v_partyschedulecnt:= 0;
                v_isdelete_partyschedule := 'false';
                v_partyscheduleid:=null;
                begin
                
                select a._partyscheduleid,a._isdelete,a._partyid,a._scheduleid,a._applicationnumber into
                v_partyscheduleid,v_isdelete_partyschedule,v_partyid,v_partyscheduled,v_applicationnumber
                from unnest(v_arr_partyschedule) a ;
            
--                select b.partyid,b.scheduleid  into v_partyids,v_partyschedules  from kaveri.partyschedules b ;
                
                if(v_isdelete_partyschedule = 'false' and v_partyscheduleid is null ) then                     
                 
                   select count(partyid) into v_countofparty from kaveri.partyschedules p where p.applicationnumber=v_applicationnumber and p.scheduleid=v_partyscheduled
                    and p.partyid=v_partyid;
                    
                    if(v_countofparty=0) then
                    INSERT INTO kaveri.partyschedules(
                    partyid ,scheduleid,  propertyid,applicationnumber)
                    select v_partyid ,a._scheduleid,  a._propertyid,a._applicationnumber
                        from unnest(v_arr_partyschedule) a;
--                    ELSE
--                    
--                            delete from kaveri.partyschedules where applicationnumber=v_applicationnumber and partyid=v_partyid and scheduleid=v_partyscheduled;
--                            /*delete from kaveri.partyschedules where
--                         partyscheduleid  in  (select a._partyscheduleid
--                        from unnest(v_arr_partyschedule) a);*/
                    end if;
                    
                elsif (v_isdelete_partyschedule = 'true' and v_partyscheduleid is not null)
                then
                         select count(partyid) into v_countofparty from kaveri.partyschedules p where p.applicationnumber=v_applicationnumber and p.scheduleid=v_partyscheduled
                    and p.partyid=v_partyid;
                    
                    if(v_countofparty>0) then
                    /*delete from kaveri.partyschedules where
                         partyscheduleid  in  (select a._partyscheduleid
                        from unnest(v_arr_partyschedule) a);*/
						
                        delete from kaveri.partyschedules where applicationnumber=v_applicationnumber and partyid=v_partyid and scheduleid=v_partyscheduled
						and partyscheduleid=v_partyscheduleid;
						
                    else
                    INSERT INTO kaveri.partyschedules(
                    partyid ,scheduleid,  propertyid,applicationnumber)
                    select v_partyid ,a._scheduleid,  a._propertyid,a._applicationnumber
                        from unnest(v_arr_partyschedule) a;
                    end if;                    
                end if;            
            -- exception when others then
            -- RAISE EXCEPTION 'Partydata ID --> %', v_partyid
              --    USING HINT = 'Please check partyschedules data';
             end;
             end loop;
             
            end if;
        
--        if(v_partyid is not null ) then
--            FOR v_arr_partyschedule IN (SELECT kaveri.fn_fetch_1d_arrayofarray(party_schedules))
--            loop
--        v_ignorepartyid:=null;
--        v_linkpartyid_guid :=null;
--        v_linkparty_exists := null;
--            select a._partyid,a._linkpartyid,(a._linkpartyid ~ '^[0-9]+$') into
--            v_ignorepartyid,v_linkpartyid_guid,v_linkparty_exists from unnest(v_arr_partyschedule) a ;
--            if(v_partyid = v_linkpartyid_guid and v_linkparty_exists ='false') then
--                select kaveri.fn_insert_party_info(v_linkparty_arry,v_partyid) into v_partyid_out;
--                --v_pid_ignore := array_append(v_pid_ignore,v_ignorepartyid);
--                 v_pid := array_append(v_pid,v_partyid_out);
--            end if;
--            
--            
--        end if;    
        
    v_pid := array_append(v_pid,v_partyid);
    
-- END LOOP;
-- end if;
    return v_pid;
END;
$_$;


