--

CREATE FUNCTION kaveri.fn_insert_party_info_auth(p_partydetails kaveri.party_input[] DEFAULT NULL::kaveri.party_input[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $_$
DECLARE
