	admissiondate = a._admissiondate,
	idcardhash = encode(sha256(a._pan::bytea),
	'hex'),
	aadharhash = COALESCE(a._aadharhash,aadharhash),
	datetimeofconsent = a._datetimeofconsent,
	nameasperaadhar = a._nameasperaadhar,
	digilockerid = a._digilockerid,
