--
-- Name: fn_insert_party_info_court(bigint, kaveri.bannedparties_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_party_info_court(p_courtorderid bigint, p_partydetails kaveri.bannedparties_input[]) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_party_arry kaveri.bannedparties_INPUT[];
   v_txt text;
   v_partyid bigint;
   V_party_success boolean default 'true';
   v_cnt integer;
   v_isdelete boolean;
BEGIN

if(p_partydetails is not null and array_length(p_partydetails,1)>0 ) then
 FOR v_party_arry IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_partydetails)) 
loop
			begin
			v_cnt:= 0;
			 Select count(*) into v_cnt 
			 from kaveri.bannedparties where courtpartyid in 
									(select a._partyid from unnest(v_party_arry) a) ;
		select a._isdelete into v_isdelete from unnest(v_party_arry) a ;
		if v_cnt = 0 then
			  INSERT INTO kaveri.bannedparties(srocode,orderid,salutation,firstname,
			middlename,lastname,age,house_building_name,address,
			villagecode,districtcode,statecode,pincode)
				select 
				a._srocode,p_courtorderid,a._salutation,a._firstname,
			a._middlename,a._lastname,a._age,a._house_building_name,a._address,
			a._villagecode,a._districtcode,a._statecode,a._pincode
				from unnest(v_party_arry) a;
		elsif(v_isdelete = 'true') then 
			update kaveri.bannedparties   set 
			isdelete = 	v_isdelete
				from unnest(v_party_arry) a
			  where (orderid,courtpartyid) in  (select p_courtorderid,a._partyid from unnest(v_party_arry) a);
		else
			  update kaveri.bannedparties   set 
			   srocode = COALESCE(a._srocode,srocode),
			  salutation = COALESCE(a._salutation,salutation),
			 firstname = COALESCE(a._firstname,firstname),
				middlename =	COALESCE(a._middlename,middlename),
				lastname = 	 COALESCE(a._lastname,lastname),
				age =	COALESCE(a._age ,age),
				house_building_name =	COALESCE(a._house_building_name,house_building_name),
				address =	COALESCE(a._address,address),
				villagecode =	COALESCE(a._villagecode,villagecode),
				districtcode = 	 COALESCE(a._districtcode,districtcode),
				statecode =	COALESCE(a._statecode ,statecode),
				pincode =	COALESCE(a._pincode,pincode)
				from unnest(v_party_arry) a
			  where (orderid,courtpartyid) in  (select p_courtorderid,a._partyid from unnest(v_party_arry) a);
 end if;
exception when others then
V_party_success:= 'false';
			    RAISE; --EXCEPTION 'Courtorder --> %', p_courtorderid
      				--USING HINT = 'Please check party data';
					end;
 END LOOP;
 end if;
	return V_party_success;
END;
$$;


