	orgpoaauthsignmname = a._orgpoaauthsignmname,
	orgpoaauthsignlname = a._orgpoaauthsignlname,
	housenumber = a._housenumber,
	pin = a._pin,
	idprooftypeid = a._idprooftypeid,
	isconsentwitness = a._isconsentwitness,
	isprivateattendance = a._isprivateattendance ,
	coveringLetterNo = a._coveringLetterNo,
	section88File = a._section88File,
	isduplicate = a._isduplicate,
	duplicatepartyid = a._duplicatepartyid,
	idcardhash = encode(sha256(a._pan::bytea),
	'hex'),
	aadharhash = COALESCE(a._aadharhash,aadharhash),
	datetimeofconsent = a._datetimeofconsent,
	nameasperaadhar = a._nameasperaadhar,
	digilockerid = a._digilockerid,
	aadhaardeclinereason = a._aadhaardeclinereason
from
	unnest(v_party_arry) a
where
	partyid = v_partyid_guid::bigint
 returning partyid::bigint
into
	v_partyid;

select
	a._partyid
into
		v_partyid_org
from
	unnest(v_party_arry) a ;

select
	partytypeid
into
	v_partytypeid
from
	kaveri.orgdatajslip
where
	partyid = v_partyid_org::bigint
	and partytypeid = 1;

if (v_partytypeid is not null)
 then 
 
 update
	kaveri.orgdatajslip
set
	firstname = a._firstname ,
