--
-- Name: fn_insert_party_schedule_filing(character varying, jsonb); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_party_schedule_filing(app_number character varying, property_party_list jsonb) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    property_data RECORD;
    party_id BIGINT;
    schedule_id BIGINT;
    partySchID INT;
    existing_party_ids BIGINT[];
    current_party_id BIGINT;
BEGIN
    -- Loop through each property-party mapping in the JSONB array
    FOR property_data IN 
        SELECT * 
        FROM jsonb_to_recordset(property_party_list) AS x(
            "propertyId" BIGINT, 
            "partyIds" BIGINT[]
        )
    LOOP
        -- Fetch the schedule ID corresponding to the property ID
        SELECT scheduleid INTO schedule_id
        FROM kaveri.propertyschedules
        WHERE propertyid = property_data."propertyId";

        -- Get all existing party IDs for this property ID
        SELECT ARRAY_AGG(partyid) 
        INTO existing_party_ids
        FROM kaveri.partyschedules
        WHERE propertyid = property_data."propertyId" 
          AND isdelete = false;

        -- If property has existing parties, update isdelete for missing ones
        IF existing_party_ids IS NOT NULL THEN
            FOR current_party_id IN SELECT UNNEST(existing_party_ids) 
            LOOP
                -- If current party exists in new list, skip update
                IF NOT (current_party_id = ANY (property_data."partyIds")) THEN
                    -- Mark as deleted
                    UPDATE kaveri.partyschedules
                    SET isdelete = true
                    WHERE propertyid = property_data."propertyId"
                      AND partyid = current_party_id;
                END IF;
            END LOOP;
        END IF;

        -- Insert only new party IDs (that do not exist in table)
        IF property_data."partyIds" IS NOT NULL AND array_length(property_data."partyIds", 1) > 0 THEN
            FOREACH party_id IN ARRAY property_data."partyIds"
            LOOP
                -- Check if party_id is already in the table, skip if exists
                IF existing_party_ids IS NULL OR NOT (party_id = ANY (existing_party_ids)) THEN
                    INSERT INTO kaveri.partyschedules (
                        partyscheduleid, 
                        partyid, 
                        scheduleid, 
                        propertyid, 
                        applicationnumber, 
                        isdelete, 
                        inserteddatetime, 
                        k1k2_flag
                    )
                    VALUES (
                        nextval('kaveri.partyschedules_partyscheduleid_seq'),
                        party_id,
                        schedule_id,
                        property_data."propertyId",
                        app_number,
                        false, 
                        NOW(),
                        2 
                    )
                    RETURNING partyscheduleid INTO partySchID;
                END IF;
            END LOOP;
        END IF;
    END LOOP;

    -- Return the last inserted partyschedule ID
    RETURN partySchID;
END;
$$;


ALTER FUNCTION kaveri.fn_insert_party_schedule_filing(app_number character varying, property_party_list jsonb) OWNER TO postgres;

--
-- Name: fn_insert_party_search_key(bigint, bigint, integer, integer, bigint, character varying, character varying, character varying, bigint, integer, character); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_party_search_key(_keyid bigint, _documentid bigint, _srocode integer, _partytypeid integer, _partyid bigint, _firstname character varying, _middlename character varying, _lastname character varying, _orderid bigint, _isactivated integer, _actiontype character) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE 
v_orderid bigint;
v_cnt bigint;
begin
select count(*) into v_cnt from kaveri.ecnamesearchkeyvalues
a inner join kaveri.dec_drordermaster b on a.orderid = b.orderid
and keyid = _keyid;
if v_cnt = 0 then
insert into kaveri.ecnamesearchkeyvalues 
(
    keyid,
    documentid,
    srocode,
    partytypeid,
    partyid,
    firstname,
    middlename,
    lastname,
    orderid,
    isactivated,
    actiontype
) values
(
     nextval('kaveri.keyid_seq'),
    _documentid,
    _srocode,
    _partytypeid,
    _partyid,
    _firstname,
    _middlename,
    _lastname,
    _orderid,
    _isactivated,
    _actiontype
) returning orderid into v_orderid;
end if;
return v_orderid;
end;
$$;


