--
-- Name: fn_insert_party_witness(kaveri.party_witness_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_party_witness(p_partydetails kaveri.party_witness_input[] DEFAULT NULL::kaveri.party_witness_input[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $_$
DECLARE
	id_val bigint;
    --inserted_id integer;
	 cit_id text;
   --property_arry $1%type;
   v_party_arry kaveri.party_witness_input[];
   v_partyid bigint;
   var_r record;
   v_pid bigint[];
v_cnt integer;
begin
Select count(*) into v_cnt from kaveri.partywitness where partyid in 
(select a.partyid from unnest($1) a) ;
if(p_partydetails is not null and array_length(p_partydetails,1)>0 ) then
FOR v_party_arry IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_partydetails))
loop
v_cnt:= 0;
Select count(*) into v_cnt from kaveri.partywitness where partyid in 
(select a.partyid from unnest(v_party_arry) a) ;
if v_cnt = 0 then 
INSERT INTO kaveri.partywitness( partyid,
    witnessid,
    witnessdate,
    srocode)
	select partyid,
	--nextval('kaveri.partywitness_seq'),
    witnessid,
    witnessdate,
    srocode
from unnest(v_party_arry)	
	 returning partyid::bigint into v_partyid;	
	 else
	 update kaveri.partywitness set
	-- partyid=a.partyid,
   --witnessid= a.witnessid,
   
    --srocode=a.srocode,
	witnessdate = a.witnessdate
	from unnest(v_party_arry) a where a.partyid in 
			 (select a.partyid from unnest(v_party_arry) a);
			 select a.partyid into v_partyid from unnest(v_party_arry) a;
	 end if;
	v_pid := array_append(v_pid,v_partyid);
	end loop;
	end if;
Return v_pid;
end;
$_$;


