--
-- Name: fn_insert_partypandetails(integer, character varying, boolean, character varying, timestamp without time zone, character varying, character varying, character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_partypandetails(_partyid integer, _applicationnumber character varying, _haspan boolean, _panname character varying, _dob timestamp without time zone, _pannumber character varying, _form60path character varying, _panstatus character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
v_partyinfocnt int;
v_partycnt int;
begin
	select count(*) into v_partyinfocnt from kaveri.partyinfo where partyid = _partyid and applicationnumber = _applicationnumber;
	
	select count(*) into v_partycnt from kaveri.partypandetails where partyid = _partyid;
	
	if v_partycnt = 0 and v_partyinfocnt>0 then
	insert into kaveri.partypandetails(
	partyid,
	applicationnumber,
	haspan,
	panname,
	dob,
	pannumber,
	form60path,
	panstatus)
	values(
	_partyid,
	_applicationnumber,
	_haspan,
	_panname,
	_dob, 
	rPAD('*',(LENGTH(_pannumber) - 4),'*')|| right(_pannumber,4),
	_form60path,
	_panstatus);
	
	else
	
	update kaveri.partypandetails
	set partyid =_partyid ,
	applicationnumber = _applicationnumber,
	haspan = _haspan,
	panname = _panname,
	dob = _dob,
	pannumber = rPAD('*',(LENGTH(_pannumber) - 4),'*')|| right(_pannumber,4),
	form60path = _form60path,
	panstatus = _panstatus
	where partyid = _partyid;

end if;
	return _partyid;
end;
$$;


ALTER FUNCTION kaveri.fn_insert_partypandetails(_partyid integer, _applicationnumber character varying, _haspan boolean, _panname character varying, _dob timestamp without time zone, _pannumber character varying, _form60path character varying, _panstatus character varying) OWNER TO postgres;

--
-- Name: fn_insert_partysigneddocuments(bigint, text, text, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_partysigneddocuments(_documentid bigint, _filepath text, _filetype text, _isexecuted integer DEFAULT NULL::integer) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
 
	insert into kaveri.partysigneddocuments (documentid, filepath, filetype) values (_documentid, _filepath, _filetype);
 
 	if _isexecuted = 1 then 
	update kaveri.documentmaster set
	executiondatetime= current_timestamp
	where documentid = _documentid;
	end if;

return _documentid;
END;
$$;


ALTER FUNCTION kaveri.fn_insert_partysigneddocuments(_documentid bigint, _filepath text, _filetype text, _isexecuted integer) OWNER TO postgres;

--
-- Name: fn_insert_paymentgateway(character varying, character varying, character varying, character varying, character varying, timestamp without time zone, bigint); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_paymentgateway(_deptreferencecode character varying, _banktransactionnumber character varying, _bankname character varying, _paymentmode character varying, _paymentstatuscode character varying, _transactiontimestamp timestamp without time zone, _amount bigint) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
Declare
v_deptrefcode character varying(100);
v_transactionid text;
begin
if (_deptreferencecode is not null and coalesce(_deptreferencecode,'') <> '') then
insert into kaveri.ams_reg_epaymentbankackdetails(
deptreferencecode,
 banktransactionnumber,
 bankname,
 paymentmode,
 paymentstatuscode,
 transactiontimestamp,
  amount
) 
values (
_deptreferencecode,
    _banktransactionnumber,
    _bankname,
    _paymentmode,
    _paymentstatuscode,
    _transactiontimestamp,
    _amount
)
returning transactionid into v_transactionid;
end if;
return v_transactionid;
   END;
$$;


