-- Name: fn_insert_persondetails(integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, timestamp without time zone, character varying, character varying, character varying, integer, character varying, integer, integer, boolean, integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_persondetails(_personid integer, _firstname character varying, _middlename character varying, _lastname character varying, _mothername character varying, _fatherguardianname character varying, _sex character varying, _status character varying, _placeofmarriage character varying, _presentaddress character varying, _permanentaddress character varying, _phoneno character varying, _dob timestamp without time zone, _briderelation character varying, _bridegroomrelation character varying, _imagefilepath character varying, _age integer, _supportdocuments character varying, _srocode integer, _drcode integer, _ispresentaddresssameaspermanent boolean, _marriagetypeid integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
v_cnt bigint;
v_personid integer;
begin
select count(*) into v_cnt from kaveri.persondetails where personid=_personid;
if v_cnt = 0 then
insert into kaveri.persondetails 
(
 personid,
    firstname,
    middlename,
    lastname,
    mothername,
    fatherguardianname,
    sex,
    status,
   -- lengthofresidence,
    placeofmarriage,
    presentaddress,
    permanentaddress,
    phoneno,
    dob,
   -- occupation,
  --  persontype,
    briderelation,
    bridegroomrelation,
    imagefilepath,
    age,
    supportdocuments,
  --  photo,
    srocode,
    drcode,
	ispresentaddresssameaspermanent,
	marriagetypeid
) values
(
nextval('kaveri.personid_seq'),
    _firstname,
    _middlename,
    _lastname,
    _mothername,
    _fatherguardianname,
    _sex,
    _status,
   -- _lengthofresidence,
    _placeofmarriage,
    _presentaddress,
    _permanentaddress,
    _phoneno,
    _dob,
   -- _occupation,
   -- _persontype,
    _briderelation,
    _bridegroomrelation,
    _imagefilepath,
    _age,
    _supportdocuments,
  --  _photo,
    _srocode,
    _drcode,
	_ispresentaddresssameaspermanent,
	_marriagetypeid
) returning personid into v_personid;
else
update kaveri.persondetails set
    firstname=_firstname,
    middlename=_middlename,
    lastname=_lastname,
    mothername=_mothername,
    fatherguardianname=_fatherguardianname,
   -- sex=_sex,
    status=_status,
    --lengthofresidence=_lengthofresidence,
    placeofmarriage=_placeofmarriage,
    presentaddress=_presentaddress,
    permanentaddress=_permanentaddress,
    phoneno=_phoneno,
    dob=_dob,
   -- occupation=_occupation,
  --  persontype=_persontype,
    briderelation=_briderelation,
    bridegroomrelation=_bridegroomrelation,
    imagefilepath=_imagefilepath,
    --age=_age,
    supportdocuments=_supportdocuments,
  --  photo=_photo,
    srocode=_srocode,
    drcode=_drcode,
	ispresentaddresssameaspermanent=_ispresentaddresssameaspermanent,
	marriagetypeid=_marriagetypeid
	where personid = _personid returning personid into v_personid;
end if;
return v_personid;
end;
$$;


