--
-- Name: fn_insert_property_details_court(bigint, kaveri.bannedproperties_input[], kaveri.bannedpropertynumbers_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_property_details_court(p_courtorderid bigint, p_courtproperties kaveri.bannedproperties_input[], p_courtpropertynumberdetails kaveri.bannedpropertynumbers_input[]) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$
DECLARE 
   v_arr_courtproperties p_courtproperties%type;
   v_arr_propertynumberdetails kaveri.bannedpropertynumbers_INPUT[];
   v_propertyid bigint;
   v_propertynumberid bigint;
   v_propertyid_guid varchar(50);
   v_propertynumberpropertyid_guid varchar(50);
   v_cnt integer;
   v_cnt1 integer;
   v_property_success boolean default 'true';
   v_property_exists boolean default 'false';
   v_isdelete boolean ;
   v_isdelete_propertynumber boolean ;
begin

if(p_courtproperties is not null and array_length(p_courtproperties,1)>0 ) then
	FOR v_arr_courtproperties IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_courtproperties)) 
	loop
		v_cnt:= 0;
		v_propertyid:=null;
		v_propertyid_guid :=null;
		v_property_exists := 'false';
		begin
		
		select a._propertyid,(a._propertyid ~ '^[0-9]+$'),a._isdelete into 
		v_propertyid_guid, v_property_exists, v_isdelete from unnest(v_arr_courtproperties) a ;
		raise notice 'v_propertyid_guid -- %',v_propertyid_guid;
		if(v_propertyid_guid is not null) then
			Select count(*) into v_cnt from kaveri.bannedproperties where --v_property_exists ='true' and
			courtpropertyid in (case when v_property_exists ='true' then v_propertyid_guid::bigint 
							   else -1 end) ;
				raise notice 'v_cnt --> %',v_cnt;
				 if v_cnt = 0 then 
				 INSERT INTO kaveri.bannedproperties(
				 ORDERID,srocode,jurisdictionsrcode,
		villagecode,propertydescription,isagriculturalproperty,
		northboundary,southboundary,eastboundary,westboundary ,
		extentinformation,area,measurementunit)
			select p_courtorderid,a._srocode,a._jurisdictionsrcode,
		a._villagecode,a._propertydescription,a._isagriculturalproperty,
		a._northboundary,a._southboundary,a._eastboundary,a._westboundary ,
		a._extentinformation,a._area,a._measurementunit
				from unnest(v_arr_courtproperties) a	
				 returning COURTpropertyid::bigint into v_propertyid;
	elsif(v_isdelete = 'true') then
	raise notice 'v_isdelete --> %',v_isdelete;
		update kaveri.bannedproperties set 
			isdelete = v_isdelete where (orderid,COURTpropertyid) in
			(select p_courtorderid,a._propertyid::bigint from unnest(v_arr_courtproperties) a);
			update kaveri.bannedpropertynumbers set 
			isdelete = v_isdelete where (orderid,propertyid) in
			(select p_courtorderid,a._propertyid::bigint from unnest(v_arr_courtproperties) a);
	else 
				raise notice 'v_propertyid1 --> %',v_propertyid;
				update kaveri.bannedproperties set
				villagecode = COALESCE(a._villagecode,villagecode),
				propertydescription = COALESCE(a._propertydescription,propertydescription),
				isagriculturalproperty = COALESCE(a._isagriculturalproperty,isagriculturalproperty),
				northboundary =COALESCE( a._northboundary,northboundary),
				southboundary =COALESCE( a._southboundary,southboundary),
				eastboundary = COALESCE(a._eastboundary,eastboundary),
				westboundary = COALESCE(a._westboundary ,westboundary),
				extentinformation = COALESCE(a._extentinformation,extentinformation),
				area = COALESCE(a._area,area),
				measurementunit = COALESCE(a._measurementunit,measurementunit)
				from unnest(v_arr_courtproperties) a	
				 where (orderid,COURTpropertyid,srocode) in  
				 (select p_courtorderid,a._propertyid::bigint,a._srocode from unnest(v_arr_courtproperties) a)
			 RETURNING COURTpropertyid::bigint into v_propertyid;
			 raise notice 'v_propertyid2 --> %',v_propertyid;
			 end if;
			end if;
	
	 exception when others then
	 v_property_success:='false';
	 RAISE EXCEPTION 'Courtorderid ID --> %, v_propertyid --> %', p_courtorderid,v_propertyid
     USING HINT = 'Please check property data';
	 end ;
	 
 		if(v_propertyid is not null and coalesce(v_isdelete,'false') = 'false') then
			--select a._propertynumbers into p_arr_propertynumberdetails 
			--from unnest(v_arr_courtproperties) a;
			
			FOR v_arr_propertynumberdetails IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_courtpropertynumberdetails))
				loop
				v_cnt1:= 0;
				v_property_exists := 'false';
				v_propertynumberpropertyid_guid:=null;
				begin
				
				select a._propertyid,(a._propertyid ~ '^[0-9]+$'),a._isdelete,a._propertynumberid into v_propertynumberpropertyid_guid
				,v_property_exists,v_isdelete_propertynumber,v_propertynumberid 
				from unnest(v_arr_propertynumberdetails) a ;
				if(v_propertynumberpropertyid_guid = v_propertyid_guid) then 
					
				--Select count(*) into v_cnt1 from kaveri.bannedpropertynumbers a where (propertyid,currentpropertytypeid) in  
					--	(select v_propertyid,a._currentpropertytypeid from unnest(v_arr_propertynumberdetails) a);
				if (v_propertynumberid is null or v_propertynumberid = 0) then --and v_propertyid1 = v_propertyid then
						 INSERT INTO kaveri.bannedpropertynumbers(
					srocode,propertyid,orderid,currentpropertytypeid,
					currentnumber,oldnumber,
					survey_no,hissa_no)
					select a._srocode,v_propertyid,p_courtorderid,a._currentpropertytypeid,
						a._currentnumber,a._oldnumber,
						a._survey_no,a._hissa_no
						from unnest(v_arr_propertynumberdetails) a;
				elsif (v_isdelete_propertynumber = 'true') then
						update  kaveri.bannedpropertynumbers set
						isdelete = v_isdelete_propertynumber where
						 (propertyid,courtpropertynumberid) 
						 in  (select v_propertyid,a._propertynumberid 
						from unnest(v_arr_propertynumberdetails) a);
						
				else 
						update  kaveri.bannedpropertynumbers set
						currentnumber=coalesce(a._currentnumber,currentnumber),
						oldnumber = coalesce(a._oldnumber,oldnumber),
						survey_no = coalesce(a._survey_no,survey_no),
						hissa_no = coalesce(a._hissa_no,hissa_no)
						from unnest(v_arr_propertynumberdetails)	a
						 where (propertyid,courtpropertynumberid) 
						 in  (select v_propertyid,a._propertynumberid 
						from unnest(v_arr_propertynumberdetails) a);
				end if;
			end if;
			 exception when others then
			 v_property_success := 'false';
			 RAISE EXCEPTION 'Courtorderid ID --> %, v_propertyid --> %, v_propertynumberid --> %', p_courtorderid,v_propertyid,v_propertynumberid
      			USING HINT = 'Please check propertynumber data';
			 end;
			 end loop; 
 		end if;
 	end loop;
 end if;

 RETURN v_property_success;
 end;
$_$;


ALTER FUNCTION kaveri.fn_insert_property_details_court(p_courtorderid bigint, p_courtproperties kaveri.bannedproperties_input[], p_courtpropertynumberdetails kaveri.bannedpropertynumbers_input[]) OWNER TO csgadmin;

--
-- Name: fn_insert_property_master(kaveri.property_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_property_master(kaveri.property_input[]) RETURNS character varying[]
    LANGUAGE plpgsql
    AS $_$


DECLARE 
   cit_id text;
   property_arry $1%type;
   v_txt text;
   v_propertyid character varying[];
   v_cnt integer;
   var_r record;
  v_applicationnumber character varying;
--   v_pid bigint[];
v_docid bigint;
begin
Select count(*) into v_cnt from kaveri.propertymaster pm where pm.propertyid in 
(select a.propertyid from unnest($1) a) ;

select a.applicationnumber into v_applicationnumber from unnest($1) a;

select documentid into v_docid from kaveri.documentmaster where applicationnumber=v_applicationnumber;

	 if v_cnt = 0 then

--select nextval('kaveri.propertymastersequence_seq')::bigint into v_propertyid ;
	 
INSERT INTO kaveri.propertymaster(
	 propertyid,
    documentid,
    villagecode,
    regsrocode,
    srocode,
    totalarea,
    unitid,
    northboundary,
    southboundary,
    eastboundary,
    westboundary,
    landmark,
    marketvalue,
    assessment,
    sdcalculationstring,
    stampduty,
    transferliabilities,
    consideration,
    additionalduty,
    cessduty,
    govtduty,
    isexempted,
    exemptiondescription,
    ismovableproperty,
    sdrefund,
    docmarketvalue,
    valid1,
    isimdemnified,
    restriction,
    restrictiontype,
    restrictiondescription,
    enumber,
    claimingblocknumber,
    retainingblocknumber,
    valuationreport,
    loanpurposeid,
    applicationnumber,
    verified,
    issroapproved,
    stamparticlecode,
    stampruleid,
    regarticlecode,
	propertytypeid,
	 noofscanpages,
	 denodescription,
	estampdescription,
	adjudescription,
	 surcharge)
select 
   nextval('kaveri.propertymastersequence_seq') ,
    b.documentid,
    b.villagecode,
   b.regsrocode,
    b.srocode,
    b.totalarea,
    b.unitid,
    b.northboundary,
    b.southboundary,
    b.eastboundary,
    b.westboundary,  
    b.landmark,
    b.marketvalue,
    b.assessment,
    b.sdcalculationstring,
    b.stampduty,
    b.transferliabilities,
    b.consideration,
    b.additionalduty,
    b.cessduty,
    b.govtduty,
    b.isexempted,
    b.exemptiondescription,
    b.ismovableproperty,
    b.sdrefund,
    b.docmarketvalue,
    b.valid1,
    b.isimdemnified,
    b.restriction,
    b.restrictiontype,
    b.restrictiondescription,
    b.enumber,
    b.claimingblocknumber,
    b.retainingblocknumber,
    b.valuationreport,
    b.loanpurposeid,
   	b.applicationnumber,
    b.verified,
    b.issroapproved,
    b.stamparticlecode,
    b.stampruleid,
	b.regarticlecode,
	b.propertytypeid,
	b.noofscanpages,
	b.denodescription,
	b.estampdescription,
	b.adjudescription,
	b.surcharge
	from unnest($1) b;
	select propertyid into v_propertyid  from unnest($1) ;--::kaveri.property_input[] 	;
	else 
	update kaveri.propertymaster pm set
	 documentid = (case when v_docid is null then 0 else v_docid end),--a.documentid,
    villagecode = a.villagecode,
   	regsrocode = a.regsrocode,
    srocode = a.srocode,
    totalarea = a.totalarea,
    unitid = a.unitid,
    northboundary = a.northboundary,
    southboundary = a.southboundary,
    eastboundary = a.eastboundary,
    westboundary = a.westboundary,
    landmark = a.landmark,
    marketvalue = a.marketvalue,
    assessment = a.assessment,
    sdcalculationstring = a.sdcalculationstring,
    stampduty = a.stampduty,
    transferliabilities = a.transferliabilities,
    consideration = a.consideration,
    additionalduty = a.additionalduty,
    cessduty = a.cessduty,
    govtduty = a.govtduty,
    isexempted = a.isexempted,
    exemptiondescription = a.exemptiondescription,
    ismovableproperty = a.ismovableproperty,
    sdrefund = a.sdrefund,
    docmarketvalue = a.docmarketvalue,
    valid1 = a.valid1,
    isimdemnified = a.isimdemnified,
    restriction = a.restriction,
    restrictiontype = a.restrictiontype,
    restrictiondescription = a.restrictiondescription,
    enumber = a.enumber,
    claimingblocknumber = a.claimingblocknumber,
    retainingblocknumber = a.retainingblocknumber,
    valuationreport = a.valuationreport,
    loanpurposeid = a.loanpurposeid,
    applicationnumber = a.applicationnumber,
    verified = a.verified,
    issroapproved = a.issroapproved,
    stamparticlecode = a.stamparticlecode,
    stampruleid = a.stampruleid,
	regarticlecode=a.regarticlecode,
	propertytypeid=a.propertytypeid,
	 noofscanpages=a.noofscanpages,
	 denodescription=a.denodescription,
	estampdescription=a.estampdescription,
	adjudescription=a.adjudescription,
	surcharge=a.surcharge,
	inserteddatetime=now()
	from unnest($1) a--::kaveri.property_input[] 	;
	where pm.propertyid = a.propertyid;
			select array_Agg(s) into v_propertyid  from 
		(select propertyid  from unnest($1) )s;
	end if;
	
--	and p.documentid in (select documentid from unnest($1))) s;
--	 v_pid := array_append(v_pid,v_propertyid);
-- end loop;
 RETURN v_propertyid;
 end;
$_$;


ALTER FUNCTION kaveri.fn_insert_property_master(kaveri.property_input[]) OWNER TO csgadmin;

--
-- Name: fn_insert_property_master_and_propertyno_details_check(kaveri.property_input_array[], kaveri.mojanixml_input[], kaveri.bhoomixmllog_input[], kaveri.eaasti_eswatuxmllog_array[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_property_master_and_propertyno_details_check(p_propertymaster kaveri.property_input_array[] DEFAULT NULL::kaveri.property_input_array[], p_mojanixmldetails kaveri.mojanixml_input[] DEFAULT NULL::kaveri.mojanixml_input[], p_bhoomixmllogdetails kaveri.bhoomixmllog_input[] DEFAULT NULL::kaveri.bhoomixmllog_input[], p_eaasti_eswatuxmllog kaveri.eaasti_eswatuxmllog_array[] DEFAULT NULL::kaveri.eaasti_eswatuxmllog_array[]) RETURNS bigint[]
    LANGUAGE plpgsql PARALLEL SAFE
    AS $_$
DECLARE 
   v_schid bigint;
   cit_id text; 
   v_arr_propertymaster p_propertymaster%type;
   v_propertyid_for_chk bigint;
   
   p_arr_propertynumberdetails kaveri.propertynumberdetails_input[];
   v_arr_propertynumberdetails kaveri.propertynumberdetails_input[];
   v_arr_mojanixmldetails kaveri.mojanixml_input[];
   v_arr_bhoomixmllogdetails p_bhoomixmllogdetails%type;
   v_arr_eaasti_eswatuxmllog kaveri.eaasti_eswatuxmllog_array[];
   
   --property_arry $1%type;
   v_txt text;
   v_propertyid bigint;
   v_cnt integer;
   v_cnt1 integer;
   v_cnt2 integer;
   var_r record;
   v_pid bigint[];
   v_propertytypeid integer;
   v_srocode integer;
   v_documentid integer;
  -- v_propertyid_for_chk bigint;
   v_currentnumber text;
   v_cnt_currno integer;
   v_cnt3 integer;
   v_registercount integer;
  v_doccnt int;
 v_currentstatus character varying;
v_isduecorrection boolean;	
begin

Select currentstatus,isduecorrection into v_currentstatus,v_isduecorrection 
from kaveri.applicantapplicationdetails ab  where applicationnumber =((p_propertymaster)[1]).applicationnumber; 
if(v_currentstatus<>'CD101' or not (v_currentstatus = 'CD106' and v_isduecorrection = true))
then	

raise exception 'invalid user operation';
end if;
	

if(p_propertymaster is not null and array_length(p_propertymaster,1)>0 ) then
	FOR v_arr_propertymaster IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_propertymaster)) 
	loop
		v_cnt:= 0;
		v_propertyid:=null;

	
    /* ============================================*/	
   /* first we will check whether this data has mojani data associated with it
   if Yes then we will check whether the sketch number exist */
   select count(*) into v_registercount from kaveri.documentmaster where applicationnumber in (select a.applicationnumber from unnest(v_arr_propertymaster) a);
   
   	
   if(p_mojanixmldetails is not null and array_length(p_mojanixmldetails,1)>0) then
			
			FOR v_arr_mojanixmldetails IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_mojanixmldetails))
				loop
				v_cnt3:= 0;			 
                      Select count(*) into v_cnt3 from kaveri.mojanixml a where
                      inputsketchdetails in (select a.inputsketchdetails 
											 from unnest(v_arr_mojanixmldetails) a);
                      if (v_cnt3 > 0 and v_registercount > 0) then
					  return '{1003}';
					  end if;
				 end loop;
	else 
   /* we are searching for existing properties against the submitted applicationnumbers */
				
				/*
	for v_propertyid_for_chk in	(select a3.propertyid from kaveri.propertymaster a3 where (applicationnumber,villagecode) 
		in(select a.applicationnumber,a.villagecode from unnest(v_arr_propertymaster) a)) 
		loop  
	-- for these properties we will find if the current number provided in propertynumber details
	-- match the current number submitted 
	select a.propertynumberdetails into p_arr_propertynumberdetails from unnest(v_arr_propertymaster) a;
			FOR v_arr_propertynumberdetails IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_arr_propertynumberdetails))
				loop		
				
				
	select count(*) into v_cnt_currno from kaveri.propertynumberdetails where 
	propertyid = v_propertyid_for_chk and (currentnumber,currentpropertytypeid) 
	in (select a.currentnumber,a.currentpropertytypeid from unnest(v_arr_propertynumberdetails) a);
	if v_cnt_currno > 0 then
	return '{1003}';
	end if;
	end loop;
	end loop;
	end if;
*/
	    /* ============================================*/	
	
	
--(select a3.propertyid from kaveri.propertymaster a3 where (applicationnumber,villagecode, propertytypeid) 

-- execture for agriculture propertytypeid = 17
for v_propertyid_for_chk in (select a.propertyid from unnest(v_arr_propertymaster) a where  a.propertytypeid = 17) 
  loop
	/* for these properties we will find if the current number provided in propertynumber details
	match the current number submitted */
	
	
	select a.propertynumberdetails into p_arr_propertynumberdetails from unnest(v_arr_propertymaster) a;
			FOR v_arr_propertynumberdetails IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_arr_propertynumberdetails))
				loop		
			
	select count(*) into v_cnt_currno from kaveri.propertynumberdetails where 
	propertyid = v_propertyid_for_chk and (currentnumber,currentpropertytypeid) 
	in (select a.currentnumber,a.currentpropertytypeid from unnest(v_arr_propertynumberdetails) a);
	if v_cnt_currno > 0 then
	return '{1003}';
	end if;
	end loop;
	end loop;
	

-- execture for non-agriculture propertytypeid = 28
for v_propertyid_for_chk in	(select a.propertyid from unnest(v_arr_propertymaster) a where a.propertytypeid = 28) 
  loop
	/* for these properties we will find if the current number provided in propertynumber details
	match the current number submitted */
		
	select a.propertynumberdetails into p_arr_propertynumberdetails from unnest(v_arr_propertymaster) a;
			FOR v_arr_propertynumberdetails IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_arr_propertynumberdetails))
				loop		
			
	select count(*) into v_cnt_currno from kaveri.propertynumberdetails where 
	propertyid = v_propertyid_for_chk and (currentnumber,currentpropertytypeid) 
	in (select a.currentnumber,a.currentpropertytypeid 
		from unnest(v_arr_propertynumberdetails) a  where a.currentpropertytypeid in (60, 65));
	

	if v_cnt_currno > 0 then
	return '{1003}';
	end if;
	end loop;
	end loop;
	
end if;	
	
	
	/* following section is the original query that inserts or updates property details */
	Select count(*) into v_cnt from kaveri.propertymaster where propertyid in 
	(select a.propertyid from unnest(v_arr_propertymaster) a) ;
		 if v_cnt = 0 then
		 INSERT INTO kaveri.propertymaster(
		 propertyid,
		documentid,
		villagecode,
		regsrocode,
		srocode,
		totalarea,
		unitid,
		northboundary,
		southboundary,
		eastboundary,
		westboundary,
		landmark,
		marketvalue,
		assessment,
		sdcalculationstring,
		stampduty,
		transferliabilities,
		consideration,
		additionalduty,
		cessduty,
		govtduty,
		isexempted,
		exemptiondescription,
		ismovableproperty,
		sdrefund,
		docmarketvalue,
		valid1,
		isimdemnified,
		restriction,
		restrictiontype,
		restrictiondescription,
		enumber,
		claimingblocknumber,
		retainingblocknumber,
		valuationreport,
		loanpurposeid,
		applicationnumber,
		verified,
		issroapproved,
		stamparticlecode,
		stampruleid,
		regarticlecode,
		propertytypeid,
		noofscanpages,
		movablepropertydesc,
		roadcode,
		ownedarea,
		wardid,   -- To Save the ward number with respect to the wardid in BBMP Screen
	    isbefore2004,
		zoneId,
		subpropertytypeid,
		upormutationfee,
		uporprcardfee,
		uportotalarea,
		uporpartarea,
		isuporpartextent
		--,pidno
		 )
	select 
		nextval('kaveri.propertymastersequence_seq'),
		a.documentid,
		a.villagecode,
		a.regsrocode,
		a.srocode,
		a.totalarea,
		a.unitid,
		a.northboundary,
		a.southboundary,
		a.eastboundary,
		a.westboundary,
		a.landmark,
		a.marketvalue,
		a.assessment,
		a.sdcalculationstring,
		a.stampduty,
		a.transferliabilities,
		a.consideration,
		a.additionalduty,
		a.cessduty,
		a.govtduty,
		a.isexempted,
		a.exemptiondescription,
		a.ismovableproperty,
		a.sdrefund,
		a.docmarketvalue,
		a.valid1,
		a.isimdemnified,
		a.restriction,
		a.restrictiontype,
		a.restrictiondescription,
		a.enumber,
		a.claimingblocknumber,
		a.retainingblocknumber,
		a.valuationreport,
		a.loanpurposeid,
		a.applicationnumber,
		a.verified,
		a.issroapproved,
		a.stamparticlecode,
		a.stampruleid,
		a.regarticlecode,
		a.propertytypeid,
		a.noofscanpages,
		a.movablepropertydesc,
		a.roadcode,
		a.ownedarea,
		a.wardid,
		a.isbefore2004,
		a.zoneId,
		a.subpropertytypeid,
		a.upormutationfee,
		a.uporprcardfee,
		a.uportotalarea,
		a.uporpartarea,
		a.isuporpartextent
		 --, a._pidno
		from unnest(v_arr_propertymaster) a	
		 returning propertyid::bigint into v_propertyid;
		else 
		update kaveri.propertymaster p set
		documentid = a.documentid,
		villagecode = a.villagecode,
		regsrocode = a.regsrocode,
		srocode = a.srocode,
		totalarea = a.totalarea,
		unitid = a.unitid,
		northboundary = a.northboundary,
		southboundary = a.southboundary,
		eastboundary = a.eastboundary,
		westboundary = a.westboundary,
		landmark = a.landmark,
		marketvalue = a.marketvalue,
		assessment = a.assessment,
		sdcalculationstring = a.sdcalculationstring,
		stampduty = a.stampduty,
		transferliabilities = a.transferliabilities,
		consideration = a.consideration,
		additionalduty = a.additionalduty,
		cessduty = a.cessduty,
		govtduty = a.govtduty,
		isexempted = a.isexempted,
		exemptiondescription = a.exemptiondescription,
		ismovableproperty = a.ismovableproperty,
		sdrefund = a.sdrefund,
		docmarketvalue = a.docmarketvalue,
		valid1 = a.valid1,
		isimdemnified = a.isimdemnified,
		restriction = a.restriction,
		restrictiontype = a.restrictiontype,
		restrictiondescription = a.restrictiondescription,
		enumber = a.enumber,
		claimingblocknumber = a.claimingblocknumber,
		retainingblocknumber = a.retainingblocknumber,
		valuationreport = a.valuationreport,
		loanpurposeid = a.loanpurposeid,
		applicationnumber = a.applicationnumber,
		verified = a.verified,
		issroapproved = a.issroapproved,
		stamparticlecode = a.stamparticlecode,
		stampruleid = a.stampruleid,
		regarticlecode=a.regarticlecode,
		propertytypeid=a.propertytypeid,
		 noofscanpages=a.noofscanpages,
		 movablepropertydesc=a.movablepropertydesc,
		 roadcode=a.roadcode,
		 ownedarea=a.ownedarea,
		 wardid=a.wardid,
		isbefore2004=a.isbefore2004,
		upormutationfee = a.upormutationfee,
		uporprcardfee= a.uporprcardfee,
		uportotalarea = a.uportotalarea,
		uporpartarea = a.uporpartarea,
		isuporpartextent = a.isuporpartextent
		/*,
		 zoneId=a._zoneid,
		 subpropertytypeid=a._subpropertytypeid*/
		 --pidno=a._pidno
		from unnest(v_arr_propertymaster) a	
		 where p.propertyid in  (select a1.propertyid from unnest(v_arr_propertymaster) a1)
	 RETURNING a.propertyid::bigint into v_propertyid;
	 end if;
		
		 select count(*) into v_doccnt from kaveri.documentmaster d where applicationnumber in (select a1.applicationnumber from unnest(v_arr_propertymaster) a1 );

		if (v_doccnt>0)
		then 
		
		update kaveri.documentmaster d set regarticlecode =a.regarticlecode  from unnest(v_arr_propertymaster) a	
			where d.applicationnumber in  (select a2.applicationnumber from unnest(v_arr_propertymaster) a2);
		end if;
	
	
 		if(v_propertyid is not null) then
			select a.propertynumberdetails into p_arr_propertynumberdetails from unnest(v_arr_propertymaster) a;
			FOR v_arr_propertynumberdetails IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_arr_propertynumberdetails))
				loop
				v_cnt1:= 0;
				 select documentid,srocode,propertytypeid into v_documentid,v_srocode,v_propertytypeid
			 from kaveri.propertymaster where propertyid = v_propertyid;
				Select count(*) into v_cnt1 from kaveri.propertynumberdetails a  
				where (propertyid,currentpropertytypeid) in  
				(select a.propertyid,a.currentpropertytypeid from unnest(v_arr_propertynumberdetails) a);
			/*Select count(*) into v_cnt from kaveri.propertynumberdetails where propertyid in 
			(select a._propertyid from unnest($1) a) ;*/
			 if (v_cnt1 = 0 ) then --and v_propertyid1 = v_propertyid then
				 INSERT INTO kaveri.propertynumberdetails(
				propertyid,
				srocode,
				currentpropertytypeid,
				currentnumber,
			   -- oldpropertytypeid,
			   -- oldnumber,
			   -- description,
				survey_no,
			   -- surnoc,
				hissa_no)
			select 
				 v_propertyid,
				v_srocode,
				a.currentpropertytypeid,
				a.currentnumber,
			   -- null,--_oldpropertytypeid,
			   -- null,--_oldnumber,
			   -- null,--_description,
				a.survey_no,
			   --  null,--_surnoc,
				a.hissa_no
				from unnest(v_arr_propertynumberdetails) a	
				 returning propertyid::bigint into v_schid;
				else 
				update  kaveri.propertynumberdetails p1 set
				-- propertyid = _propertyid,
				srocode=a.srocode,
				currentpropertytypeid=a.currentpropertytypeid,
				currentnumber=a.currentnumber,
			   -- oldpropertytypeid=null,--_oldpropertytypeid,
			   -- oldnumber=null,--_oldnumber,
			   -- description=null,--_description,
				survey_no=a.survey_no,
			  --  surnoc=null,--_surnoc,
				hissa_no=a.hissa_no
				from unnest(v_arr_propertynumberdetails)	a
				 where (p1.propertyid,p1.currentpropertytypeid) in  (select a1.propertyid,a1.currentpropertytypeid from unnest(v_arr_propertynumberdetails) a1)
			 RETURNING a.propertyid::bigint into v_schid;
			 end if;
			  -- v_pid := array_append(v_pid,v_schid);
			 end loop; 
 		end if;
 	v_pid := array_append(v_pid,v_schid);
	/* Mojani starts here */
	if(v_propertyid is not null and p_mojanixmldetails is not null and array_length(p_mojanixmldetails,1)>0) then
			
			FOR v_arr_mojanixmldetails IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_mojanixmldetails))
				loop
				v_cnt2:= 0;			 
				/* changed propertyid to inputsketchdetails on 23/09/2022 in order to avoid duplicate mojini sketch number entry 
                      Select count(*) into v_cnt2 from kaveri.mojanixml a where
                      inputsketchdetails in (select a._inputsketchdetails from unnest(v_arr_mojanixmldetails) a);
                      if (v_cnt2 = 0) then */
                      insert into kaveri.mojanixml
                     (
                       logid,
                       srocode,
		       propertyid,
		       inputsketchdetails,
		       receivedxmldetails,
		       receivedencxmldetails,
		       verified,
		       isuploaded,
		       uploaddatetime,
		       ackxmldetails,
		       acknumber,
		       sentxmldetails,
		       isfinalregistration
                     )
                     select 
                     nextval('kaveri.mojini_logid_seq'),
                       v_srocode,
		       v_propertyid,
		       a.inputsketchdetails,
		       a.receivedxmldetails,
		       a.receivedencxmldetails,
		       a.verified,
		       a.isuploaded,
		       a.uploaddatetime,
		       a.ackxmldetails,
		       a.acknumber,
		       a.sentxmldetails,
		       a.isfinalregistration
                       from unnest(v_arr_mojanixmldetails) a	
				 returning propertyid::bigint into v_schid;
                     /*else 
				update  kaveri.mojanixml set
                       -- inputsketchdetails=a._inputsketchdetails,
		       			receivedxmldetails=a._receivedxmldetails,
		       			receivedencxmldetails=a._receivedencxmldetails,
		       			verified=a._verified,
		       			isuploaded=a._isuploaded,
		       			uploaddatetime=a._uploaddatetime,
		       			ackxmldetails=a._ackxmldetails,
		       			acknumber=a._acknumber,
		       			sentxmldetails=a._sentxmldetails,
		       			isfinalregistration=a._isfinalregistration
						from unnest(v_arr_mojanixmldetails)	a
						 changed propertyid to inputsketchdetails on 23/09/2022 in order to avoid duplicate mojini sketch number entry */
                    /*where inputsketchdetails in (select a._inputsketchdetails from unnest(v_arr_mojanixmldetails ) a)
                       returning propertyid::bigint into v_schid;
                   end if;*/
				  end loop;
			end if;
			 select documentid,srocode into v_documentid,v_srocode
			 from kaveri.propertymaster where propertyid = v_propertyid;
			 if(v_propertyid is not null and p_bhoomixmllogdetails is not null and array_length(p_bhoomixmllogdetails,1)>0) then
			FOR v_arr_bhoomixmllogdetails IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_bhoomixmllogdetails))
				loop
				v_cnt2:= 0;			 
                      Select count(*) into v_cnt2 from kaveri.bhoomixmllog a where
                      propertyid in (select a.propertyid from unnest(v_arr_bhoomixmllogdetails) a);
                  --if (v_cnt2 = 0) then
                   insert into kaveri.bhoomixmllog(
                      logid,
    		      propertyid,
    		      inputrtcowners,
    		      rtcowners,
    		      inputsurveynolist,
    		      surveynolist,
    		      srocode
                      )
                     select nextval('kaveri.bhoomi_logid_seq'),
                     v_propertyid,
                      bh.inputrtcowners,
    		      bh.rtcowners,
    		      bh.inputsurveynolist,
    		      bh.surveynolist,
    		      v_srocode
                      from unnest(v_arr_bhoomixmllogdetails) bh	
				 returning propertyid::bigint into v_schid;
                   /*  else
                     update  kaveri.bhoomixmllog set
                      inputrtcowners=a._inputrtcowners,
					   rtcowners=a._rtcowners,
                      inputsurveynolist=a._inputsurveynolist,
					  surveynolist=a._surveynolist
					  from unnest(v_arr_bhoomixmllogdetails) a
                       where propertyid in (select a._propertyid from unnest(v_arr_bhoomixmllogdetails ) a)
                       returning propertyid::bigint into v_schid;
                   end if;*/                                         
             end loop;
          end if;
	if(v_propertyid is not null and p_eaasti_eswatuxmllog is not null and array_length(p_eaasti_eswatuxmllog,1)>0) then
			FOR v_arr_eaasti_eswatuxmllog IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_eaasti_eswatuxmllog))
	loop
				v_cnt2:= 0;			 
                      Select count(*) into v_cnt2 from kaveri.eaasti_eswatuxmllog a where
                      a.propertyid in (select a1.propertyid from unnest(v_arr_eaasti_eswatuxmllog) a1);
                  if (v_cnt2 = 0) then
	insert into kaveri.eaasti_eswatuxmllog
	(
	  logid,
    documentid,
    propertyid,
    pid,
    xml,
    srocode
	) 
	select
	 nextval('kaveri.logid_seq'),
    v_documentid,
	v_propertyid,
    --v_propertyid,
    a.pid,
    a.xml,
    v_srocode
	 from unnest(v_arr_eaasti_eswatuxmllog) a	
				 returning propertyid::bigint into v_propertyid;
	 else
     update  kaveri.eaasti_eswatuxmllog p2 set
	 documentid=a._documentid,
    --propertyid=a._propertyid,
    pid=a.pid,
    xml=a.xml,
    srocode=a.srocode
	from unnest(v_arr_eaasti_eswatuxmllog)	a
                       where p2.propertyid in (select a1.propertyid from unnest(v_arr_eaasti_eswatuxmllog ) a1)
                       returning a.propertyid::bigint into v_propertyid;
	end if;
	end loop;
	end if;
--	end if;
	end loop;
 end if;
 RETURN v_pid;
 end;
$_$;


ALTER FUNCTION kaveri.fn_insert_property_master_and_propertyno_details_check(p_propertymaster kaveri.property_input_array[], p_mojanixmldetails kaveri.mojanixml_input[], p_bhoomixmllogdetails kaveri.bhoomixmllog_input[], p_eaasti_eswatuxmllog kaveri.eaasti_eswatuxmllog_array[]) OWNER TO csgadmin;

--
-- Name: fn_insert_property_master_and_propertyno_details_check_260423(kaveri.property_input_array[], kaveri.mojanixml_input[], kaveri.bhoomixmllog_input[], kaveri.eaasti_eswatuxmllog_array[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_property_master_and_propertyno_details_check_260423(p_propertymaster kaveri.property_input_array[] DEFAULT NULL::kaveri.property_input_array[], p_mojanixmldetails kaveri.mojanixml_input[] DEFAULT NULL::kaveri.mojanixml_input[], p_bhoomixmllogdetails kaveri.bhoomixmllog_input[] DEFAULT NULL::kaveri.bhoomixmllog_input[], p_eaasti_eswatuxmllog kaveri.eaasti_eswatuxmllog_array[] DEFAULT NULL::kaveri.eaasti_eswatuxmllog_array[]) RETURNS bigint[]
    LANGUAGE plpgsql PARALLEL SAFE
    AS $_$
DECLARE 
   v_schid bigint;
   cit_id text; 
   v_arr_propertymaster p_propertymaster%type;
   v_propertyid_for_chk bigint;
   
   p_arr_propertynumberdetails kaveri.propertynumberdetails_input[];
   v_arr_propertynumberdetails kaveri.propertynumberdetails_input[];
   v_arr_mojanixmldetails kaveri.mojanixml_input[];
   v_arr_bhoomixmllogdetails p_bhoomixmllogdetails%type;
   v_arr_eaasti_eswatuxmllog kaveri.eaasti_eswatuxmllog_array[];
   
   --property_arry $1%type;
   v_txt text;
   v_propertyid bigint;
   v_cnt integer;
   v_cnt1 integer;
   v_cnt2 integer;
   var_r record;
   v_pid bigint[];
   v_propertytypeid integer;
   v_srocode integer;
   v_documentid integer;
  -- v_propertyid_for_chk bigint;
   v_currentnumber text;
   v_cnt_currno integer;
   v_cnt3 integer;
   v_registercount integer;
begin
/*Select count(*) into v_cnt from kaveri.propertymaster where propertyid in 
(select a._propertyid from unnest($1) a) ;*/

if(p_propertymaster is not null and array_length(p_propertymaster,1)>0 ) then
	FOR v_arr_propertymaster IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_propertymaster)) 
	loop
		v_cnt:= 0;
		v_propertyid:=null;
    /* ============================================*/	
   /* first we will check whether this data has mojani data associated with it
   if Yes then we will check whether the sketch number exist */
   select count(*) into v_registercount from kaveri.documentmaster where applicationnumber in (select a.applicationnumber from unnest(v_arr_propertymaster) a);
   
   	
   if(p_mojanixmldetails is not null and array_length(p_mojanixmldetails,1)>0) then
			
			FOR v_arr_mojanixmldetails IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_mojanixmldetails))
				loop
				v_cnt3:= 0;			 
                      Select count(*) into v_cnt3 from kaveri.mojanixml a where
                      inputsketchdetails in (select a.inputsketchdetails 
											 from unnest(v_arr_mojanixmldetails) a);
                      if (v_cnt3 > 0 and v_registercount > 0) then
					  return '{1003}';
					  end if;
				 end loop;
	else 
   /* we are searching for existing properties against the submitted applicationnumbers */
				
	for v_propertyid_for_chk in	(select a3.propertyid   from kaveri.propertymaster a3 where (applicationnumber,villagecode) 
		in(select a.applicationnumber,a.villagecode from unnest(v_arr_propertymaster) a)) 
		loop
	/* for these properties we will find if the current number provided in propertynumber details
	match the current number submitted */
	select a.propertynumberdetails into p_arr_propertynumberdetails from unnest(v_arr_propertymaster) a;
			FOR v_arr_propertynumberdetails IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_arr_propertynumberdetails))
				loop		
				
	select count(*) into v_cnt_currno from kaveri.propertynumberdetails where 
	propertyid = v_propertyid_for_chk and (currentnumber,currentpropertytypeid) 
	in (select a.currentnumber,a.currentpropertytypeid from unnest(v_arr_propertynumberdetails) a);
	if v_cnt_currno > 0 then
	return '{1003}';
	end if;
	end loop;
	end loop;
	end if;
	    /* ============================================*/	
	/* following section is the original query that inserts or updates property details */
	Select count(*) into v_cnt from kaveri.propertymaster where propertyid in 
	(select a.propertyid from unnest(v_arr_propertymaster) a) ;
		 if v_cnt = 0 then
		 INSERT INTO kaveri.propertymaster(
		 propertyid,
		documentid,
		villagecode,
		regsrocode,
		srocode,
		totalarea,
		unitid,
		northboundary,
		southboundary,
		eastboundary,
		westboundary,
		landmark,
		marketvalue,
		assessment,
		sdcalculationstring,
		stampduty,
		transferliabilities,
		consideration,
		additionalduty,
		cessduty,
		govtduty,
		isexempted,
		exemptiondescription,
		ismovableproperty,
		sdrefund,
		docmarketvalue,
		valid1,
		isimdemnified,
		restriction,
		restrictiontype,
		restrictiondescription,
		enumber,
		claimingblocknumber,
		retainingblocknumber,
		valuationreport,
		loanpurposeid,
		applicationnumber,
		verified,
		issroapproved,
		stamparticlecode,
		stampruleid,
		regarticlecode,
		propertytypeid,
		noofscanpages,
		movablepropertydesc,
		roadcode,
		ownedarea,
		wardid,   -- To Save the ward number with respect to the wardid in BBMP Screen
	    isbefore2004,
		zoneId,
		subpropertytypeid
		--,pidno
		 )
	select 
		nextval('kaveri.propertymastersequence_seq'),
		a.documentid,
		a.villagecode,
		a.regsrocode,
		a.srocode,
		a.totalarea,
		a.unitid,
		a.northboundary,
		a.southboundary,
		a.eastboundary,
		a.westboundary,
		a.landmark,
		a.marketvalue,
		a.assessment,
		a.sdcalculationstring,
		a.stampduty,
		a.transferliabilities,
		a.consideration,
		a.additionalduty,
		a.cessduty,
		a.govtduty,
		a.isexempted,
		a.exemptiondescription,
		a.ismovableproperty,
		a.sdrefund,
		a.docmarketvalue,
		a.valid1,
		a.isimdemnified,
		a.restriction,
		a.restrictiontype,
		a.restrictiondescription,
		a.enumber,
		a.claimingblocknumber,
		a.retainingblocknumber,
		a.valuationreport,
		a.loanpurposeid,
		a.applicationnumber,
		a.verified,
		a.issroapproved,
		a.stamparticlecode,
		a.stampruleid,
		a.regarticlecode,
		a.propertytypeid,
		a.noofscanpages,
		a.movablepropertydesc,
		a.roadcode,
		a.ownedarea,
		a.wardid,
		a.isbefore2004,
		a.zoneId,
		a.subpropertytypeid
		 --, a._pidno
		from unnest(v_arr_propertymaster) a	
		 returning propertyid::bigint into v_propertyid;
		else 
		update kaveri.propertymaster p set
		documentid = a.documentid,
		villagecode = a.villagecode,
		regsrocode = a.regsrocode,
		srocode = a.srocode,
		totalarea = a.totalarea,
		unitid = a.unitid,
		northboundary = a.northboundary,
		southboundary = a.southboundary,
		eastboundary = a.eastboundary,
		westboundary = a.westboundary,
		landmark = a.landmark,
