CREATE FUNCTION kaveri.fn_insert_property_master_dumy(kaveri.property_input[]) RETURNS character varying[]
    LANGUAGE plpgsql
    AS $_$

DECLARE 
   cit_id text;
   property_arry $1%type;
   v_txt text;
   v_propertyid character varying[];
   v_cnt integer;
   var_r record;
--   v_pid bigint[];
begin
Select count(*) into v_cnt from kaveri.propertymaster pm where pm.propertyid in 
(select a.propertyid from unnest($1) a) ;


	 if v_cnt = 0 then

--select nextval('kaveri.propertymastersequence_seq')::bigint into v_propertyid ;
	 
INSERT INTO kaveri.propertymaster(
	 propertyid,
    documentid,
    villagecode,
    regsrocode,
    srocode,
    totalarea,
    unitid,
    northboundary,
    southboundary,
    eastboundary,
    westboundary,
    landmark,
