CREATE FUNCTION kaveri.fn_insert_property_master_propertyno_details_partyinfo_rule17(p_propertymaster kaveri.property_party_info_rule_17_input_array[] DEFAULT NULL::kaveri.property_party_info_rule_17_input_array[]) RETURNS bigint
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$
DECLARE 

   v_arr_propertymaster p_propertymaster%type;
   v_arr_propertynumberdetails kaveri.propertynumberdetails_input[];
   v_arr_propertyscheduledetails kaveri.obj_property_schedules[];
   v_arr_partydetails kaveri.party_input_rule17[];
   
   v_propertyid bigint;
