		sdrefund,
		docmarketvalue,
		valid1,
		isimdemnified,
		restriction,
		restrictiontype,
		restrictiondescription,
		enumber,
		claimingblocknumber,
		retainingblocknumber,
		valuationreport,
		loanpurposeid,
		applicationnumber,
		verified,
		issroapproved,
