		stampruleid,
		regarticlecode,
		propertytypeid,
		noofscanpages,
		movablepropertydesc,
		roadcode,
		ownedarea,
		wardid,   -- To Save the ward number with respect to the wardid in BBMP Screen
	    isbefore2004,
		zoneId,
		subpropertytypeid
		--,pidno
		 )
	select 
		nextval('kaveri.propertymastersequence_seq'),
		a.documentid,
		a.villagecode,
		a.regsrocode,
		a.srocode,
		a.totalarea,
		a.unitid,
		a.northboundary,
		a.southboundary,
