--
-- Name: fn_insert_property_number_details(bigint, kaveri.propertynumberdetails_input[]); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_property_number_details(p_propertyid bigint, p_propertynumberdetails kaveri.propertynumberdetails_input[] DEFAULT NULL::kaveri.propertynumberdetails_input[]) RETURNS bigint[]
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$

Declare

v_cnt integer;

v_arr_propertynumberdetails kaveri.propertynumberdetails_input[];

v_cnt1 integer;

v_pid bigint[];

v_srocode integer;

v_documentid integer;

v_propertytypeid integer;

v_schid bigint;

begin

if(p_propertyid is not null) then

FOR v_arr_propertynumberdetails IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_propertynumberdetails))

	loop

		

		v_cnt1:= 0;

	

		select documentid,srocode,propertytypeid into v_documentid,v_srocode,v_propertytypeid

			 from kaveri.propertymaster where propertyid = p_propertyid;

				Select count(*) into v_cnt1 from kaveri.propertynumberdetails a  
				where (propertyid,currentpropertytypeid,currentnumber) in  

				(select a.propertyid,a.currentpropertytypeid,a.currentnumber 
				from unnest(v_arr_propertynumberdetails) a);

			

		if (v_cnt1 = 0 ) then --and v_propertyid1 = v_propertyid then

				 INSERT INTO kaveri.propertynumberdetails(

				 --propertynumberdetailid,

				propertyid,

				srocode,

				currentpropertytypeid,

				currentnumber,

			   -- oldpropertytypeid,

			   -- oldnumber,

			   -- description,

				survey_no,

			   -- surnoc,

				hissa_no)

			select

				--nextval('kaveri.propertynumberdetails_seq'),

			 	p_propertyid,

				v_srocode,

				a.currentpropertytypeid,

				a.currentnumber,

			   -- null,--_oldpropertytypeid,

			   -- null,--_oldnumber,

			   -- null,--_description,

				a.survey_no,

			   -- null,--_surnoc,

				a.hissa_no

				from unnest(v_arr_propertynumberdetails) a	

				 returning propertyid::bigint into v_schid;

			else

				

				update  kaveri.propertynumberdetails p1 set

				-- propertyid = _propertyid,

				srocode=a.srocode,

				currentpropertytypeid=a.currentpropertytypeid,

				currentnumber=a.currentnumber,

			   -- oldpropertytypeid=null,--_oldpropertytypeid,

			   -- oldnumber=null,--_oldnumber,

			   -- description=null,--_description,

				survey_no=a.survey_no,

			  -- surnoc=null,--_surnoc,

				hissa_no=a.hissa_no

				from unnest(v_arr_propertynumberdetails)	a

				 where (p1.propertyid,p1.currentpropertytypeid,p1.currentnumber) 
				 in  (select a1.propertyid,a1.currentpropertytypeid,a1.currentnumber
				 from unnest(v_arr_propertynumberdetails) a1)

			 RETURNING a.propertyid::bigint into v_schid;

		end if;

			 end loop;

			 v_pid := array_append(v_pid,v_schid);

		end if;

 

Return v_pid;

   END;

$$;


ALTER FUNCTION kaveri.fn_insert_property_number_details(p_propertyid bigint, p_propertynumberdetails kaveri.propertynumberdetails_input[]) OWNER TO postgres;

--
-- Name: fn_insert_property_rule_17_schedules(bigint, kaveri.obj_property_schedules[]); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_property_rule_17_schedules(p_propertyid bigint, p_propertyscheduledetails kaveri.obj_property_schedules[]) RETURNS bigint[]
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$

Declare
v_schid bigint;
v_scheduleid bigint;
   property_arry kaveri.obj_property_schedules[];
   v_cnt integer;
   v_pid bigint[];
begin

FOR property_arry IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_propertyscheduledetails))
	 LOOP
Select count(*) into v_cnt from kaveri.propertyschedules where scheduleid in 
(select a._scheduleid from unnest(property_arry) a) ;	 
--select count(*) into _cnt from kaveri.propertyschedules where scheduleid = _scheduleid;
if v_cnt = 0 then


INSERT INTO kaveri.propertyschedules(scheduleid,propertyid,srocode,partyid,scheduletype,totalarea,unitid,description,partyids
									,aileniatedauthorityid,alieniatedorder,bhoomisellerpartyids,govtrestricorder,govtrestrictionid,landcode,
									 propertygroup,giftshare,giftsharedetails,easttowest,northtosouth,blockchainpropertyid,assignedblockchainpid,
									 applicationnumber,verified,issroapproved,
									  eastboundary,
									westboundary,
									northboundary,
									southboundary
								)
								select 
									
  		    nextval('kaveri.propertyschedules_scheduleid_seq'),(select p_propertyid),_srocode,_partyid,_scheduletype,_totalarea,_unitid,_description,_partyids,_aileniatedauthorityid,_alieniatedorder,
			_govtrestricorder,_bhoomisellerpartyids,_govtrestrictionid,_landcode,_propertygroup,_giftshare,_giftsharedetails,
											_easttowest,_northtosouth,_blockchainpropertyid,_assignedblockchainpid,_applicationnumber,
									_verified,_issroapproved,
									 _eastboundary,
									_westboundary,
									_northboundary,
									_southboundary from unnest(property_arry)
   RETURNING scheduleid into v_scheduleid;
  else
  update  kaveri.propertyschedules set 
  propertyid = _propertyid,
  srocode = _srocode,
  partyid = _partyid,
  scheduletype = _scheduletype, 
  totalarea = _totalarea, 
  unitid = _unitid,
  description=_description,
  partyids=_partyids,
  aileniatedauthorityid=_aileniatedauthorityid,
  alieniatedorder=_alieniatedorder,
  bhoomisellerpartyids=_bhoomisellerpartyids,
  govtrestricorder = _govtrestricorder, 
  landcode=_landcode,
  propertygroup=_propertygroup,
  giftshare=_giftshare,
  giftsharedetails=_giftsharedetails,
  easttowest=_easttowest,
  northtosouth=_northtosouth,
  blockchainpropertyid=_blockchainpropertyid,
  assignedblockchainpid=_assignedblockchainpid,
 -- applicationnumber=_applicationnumber,
  verified = _verified,
  issroapproved = _issroapproved,
   eastboundary=_eastboundary,
   westboundary=_westboundary,
   northboundary=_northboundary,
   southboundary=_southboundary
  from unnest(property_arry)	
	 where scheduleid in  (select a._scheduleid from unnest(property_arry) a)
returning scheduleid into v_scheduleid;
end if;
 v_pid := array_append(v_pid,v_scheduleid);
 end loop;
Return v_pid;
   END;
$$;


