-- Name: fn_insert_propertyclassification(bigint, integer, character varying, character varying, integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_propertyclassification(_propertyid bigint, _urbandeptid integer, _sellerpartyids character varying, _purchaserpartyids character varying, _wardid integer) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE 
   v_propertyid bigint;
   v_cnt integer;
   v_srocode integer;
v_cnt1 integer;
begin
/*select count(distinct a.propertyid) 
from kaveri.propertymaster a inner join kaveri.propertynumberdetails b on a.propertyid = b.propertyid
and b.propertyid not in (select propertyid from kaveri.propertyclassification) and a.propertyid = _propertyid;*/
select a.srocode into v_srocode from kaveri.propertymaster a 
inner join kaveri.villagewardmapping b
on a.villagecode = b.villagecode and a.propertyid = _propertyid;
select count(*) into v_cnt from kaveri.propertyclassification where propertyid = _propertyid;
      if v_cnt = 0 then
	 INSERT INTO kaveri.propertyclassification (
	 propertyid,
    urbandeptid,
    sellerpartyids,
    purchaserpartyids,
    srocode,
    wardid)
values (
     _propertyid,
    _urbandeptid,
    _sellerpartyids,
    _purchaserpartyids,
    v_srocode,
    _wardid)	
	 returning propertyid::bigint into v_propertyid;
	else 
	update  kaveri.propertyclassification  set
  --  urbandeptid=a._urbandeptid,
    sellerpartyids=_sellerpartyids,
    purchaserpartyids=_purchaserpartyids
   -- srocode=a._srocode,
   -- wardid=a._wardid
	 where propertyid = _propertyid returning propertyid into v_propertyid;
end if;
 RETURN v_propertyid;
 end;
$$;


