--
-- Name: fn_insert_quicksearch_cc_applicationdetails_test_1(bigint, timestamp without time zone, bigint, smallint, integer, integer, numeric, boolean, bigint, timestamp without time zone, smallint, smallint, boolean, character varying, boolean, integer, integer, integer, character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_quicksearch_cc_applicationdetails_test_1(_ccid bigint, _ccdate timestamp without time zone, _userid bigint, _documentstatusid smallint, _kaverisrocode integer, _pagecount integer, _totalamount numeric, _isappliedforsignedcopy boolean, _submittedby bigint, _submitteddatetime timestamp without time zone, _marriagetypeid smallint, _firmtypeid smallint, _isprior2003 boolean, _finalregistrationnumber character varying, _isquicksearch boolean, _documenttype integer, _kaveridrocode integer, _booktype integer, _yearofregistration character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
declare 
v_ccid bigint;
v_cnt integer;
-- v_shortnamee text;
-- v_nomenclature text;
-- v_scheduletype text;
-- v_finyear text;
v_applicationnumber text;
_inserted_id text;
-- l_now text;
v_year text;
v_month text;
-- v_ccrequiredfees p_ccrequiredfees%type;
  v_pid bigint[];
begin
select count(*) into v_cnt from kaveri.cc_applicationdetails where ccid = _ccid;

raise notice 'v_cnt--%',v_cnt;

-- Production code to genearate TMP applicaitons
select right(split_part(current_date::text,'-',1),2) as year into v_year;

select split_part(current_date::text,'-',2) as month into v_month;

select lpad(nextval('kaveri.tmp_applicationnumber_seq')::text,8,'0') into _inserted_id;
v_applicationnumber := 'TMPCC-'||v_year||v_month||_inserted_id;

RAISE NOTICE 'Generate v_applicationnumber %',v_applicationnumber;

if v_cnt = 0 then
insert into kaveri.cc_applicationdetails (
	ccid,
	documenttype,
	kaveridrocode,
	-- documentnumber,
	booktype,
	yearofregistration,
	-- ccnumber,
    ccdate,
    userid,
    kaverisrocode,
    pagecount,
    totalamount,
    isappliedforsignedcopy,
    documentstatusid,
    submittedby,
    submitteddatetime,
/*    preparedby,
    prepareddatetime,
    signedby,
    signeddatetime,
    appliedsignedcopy,
    comparedby,
    compareddatetime,
    certificatenumber,
    accepteddatetime,*/
    marriagetypeid,
    firmtypeid,
	applicationnumber,
	isprior2003,
	finalregistrationnumber,
	isquicksearch
) values
(
nextval('kaveri.cc_applicationdetails_seq'),
  -- _ccnumber,
    _documenttype,
    _kaveridrocode,
    -- _documentnumber,
    _booktype,
    _yearofregistration,
    -- _documentstatusid,
    _ccdate,
    _userid,
    _kaverisrocode,
    _pagecount,
    _totalamount,
    _isappliedforsignedcopy,
	_documentstatusid,
    _submittedby,
    _submitteddatetime,
   /* _preparedby,
    _prepareddatetime,
    _signedby,
    _signeddatetime,
    _appliedsignedcopy,
    _comparedby,
    _compareddatetime,
    _certificatenumber,
    _accepteddatetime,*/
    _marriagetypeid,
    _firmtypeid,
	v_applicationnumber,
	_isprior2003,
	_finalregistrationnumber,
	_isquicksearch
) returning ccid::bigint into v_ccid;
RAISE NOTICE 'insert v_ccid %',v_ccid;
else
update kaveri.cc_applicationdetails set 
	  -- ccnumber=_ccnumber,
    documenttype=_documenttype,
    kaveridrocode=_kaveridrocode,
    -- documentnumber=_documentnumber,
    booktype=_booktype,
    yearofregistration=_yearofregistration,
    -- documentstatusid=_documentstatusid,
    ccdate=_ccdate,
    userid=_userid,
    kaverisrocode=_kaverisrocode,
    pagecount=_pagecount,
    totalamount=_totalamount,
    isappliedforsignedcopy=_isappliedforsignedcopy,
    submittedby=_submittedby,
    submitteddatetime=_submitteddatetime,
   /* preparedby=_preparedby,
    prepareddatetime=_prepareddatetime,
    signedby=_signedby,
    signeddatetime=_signeddatetime,
    appliedsignedcopy=_appliedsignedcopy,
    comparedby=_comparedby,
    compareddatetime=_compareddatetime,
    certificatenumber=_certificatenumber,
    accepteddatetime=_accepteddatetime,*/
    marriagetypeid=_marriagetypeid,
    firmtypeid=_firmtypeid,
    isprior2003 =_isprior2003,
	finalregistrationnumber=_finalregistrationnumber,
	isquicksearch=_isquicksearch
	--applicationnumber=v_applicationnumber
	where ccid = _ccid returning ccid::bigint into v_ccid;
	RAISE NOTICE 'update v_ccid %',v_ccid;
       -- v_pid := array_append(v_pid,v_ccid);
	  -- v_pid := array_append(v_pid,v_applicationnumber);
	end if;
	
	

	--update kaveri.applicantapplicationdetails set currentstatus = 'CC106',
--APPLICATIONDATE = current_timestamp where applicationnumber = v_applicationnumber ;
--returning applicationnumber into v_applicationnumber;
RAISE NOTICE 'update v_applicationnumber %',v_applicationnumber;
 Return v_applicationnumber;
end;
$$;


