--
-- Name: fn_insert_receiptdetails_check(character varying, character varying, integer, bigint, character varying, character varying, timestamp without time zone, integer, character varying, numeric); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_receiptdetails_check(_applicationnumber character varying, _paymentstatuscode character varying, _receipttypeid integer, _paymentmodeid bigint, _description character varying, _ddnumber character varying, _dddate timestamp without time zone, _ifsccodeid integer, _ifsccode character varying, _micrcode numeric) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare
v_cnt integer;
v_cnt1 integer;
v_receiptid bigint;
v_documentid bigint;
v_srocode integer;
v_totalamountpaid  bigint;
v_feerulecode integer;
v_amountpaid numeric;
v_partyid bigint;
begin
select count(*) into v_cnt 
from kaveri.receiptmaster /*rm
left join kaveri.receiptdetails rd
on rm.receiptid = rd.receiptid
left join kaveri.receiptpaymentdetails rp on rd.receiptid = rp.receiptid*/
where applicationnumber = _applicationnumber
and srocode = _srocode;
select count(*) into v_cnt1 
from kaveri.ams_reg_epaymentamtpaiddetails epd
left join kaveri.ams_reg_epaymentbankackdetails epa
on epa.deptreferencecode=epd.chlnrefnum
where applicationnumber=_applicationnumber and--'PRP-25042022-04887' and
paymentstatuscode=_paymentstatuscode;--'10700072';
select documentid,srocode,partyid into v_documentid,v_srocode,v_partyid from kaveri.partyinfo where applicationnumber = _applicationnumber;
select sum(amountpaid) into v_totalamountpaid from kaveri.feesrequired where applicationnumber = _applicationnumber;
select srocode,feerulecode,amountpaid into v_srocode,v_feerulecode,v_amountpaid from kaveri.feesrequired where
applicationnumber = _applicationnumber;
if v_cnt = 1 then
select rm.receiptid into v_receiptid from kaveri.receiptmaster rm
left join kaveri.receiptdetails rd
on rm.receiptid = rd.receiptid
left join kaveri.receiptpaymentdetails rp on rd.receiptid = rp.receiptid
where applicationnumber = _applicationnumber;
return(v_receiptid);
end if;
 if v_cnt1 = 0 then
insert into kaveri.receiptmaster 
(
   receiptid,
    documentid,
    srocode,
    receipttypeid,
    receiptnumber,
    partyid,
    dateofreceipt,
    isprinted,
    printbanner,
    docreturntime,
    applicationnumber,
    totalamount
) values
(
nextval('kaveri.receiptmaster_receiptid_seq'),
v_documentid,
v_srocode,
_receipttypeid,
nextval('kaveri.receiptmaster_receiptnumber_seq'),
v_partyid,
CURRENT_TIMESTAMP,
false,
null,
null,
_applicationnumber,
v_totalamountpaid 
) returning receiptid into v_receiptid;
end if;
select count(*) into v_cnt from kaveri.receiptdetails where receiptid = v_receiptid;
if (v_cnt = 0) then
insert into kaveri.receiptdetails
(
    receiptid,
    srocode,
    feerulecode,
    deptsubpurposeid,
    amountpaid
)
select v_receiptid,v_srocode,v_feerulecode,null,v_amountpaid
from kaveri.feesrequired where applicationnumber = _applicationnumber
returning receiptid into v_receiptid;
end if;
select count(*) into v_cnt from kaveri.receiptpaymentdetails where receiptid = v_receiptid;
if (v_cnt = 0) then
insert into kaveri.receiptpaymentdetails
(
 receiptid,
    srocode,
    paymentmodeid,
    description,
    ddnumber,
    dddate,
    ifsccodeid,
    ifsccode,
    micrcode,
    amount)
values
( v_receiptid,v_srocode,_paymentmodeid,_description,
_ddnumber,_dddate,_ifsccodeid,_ifsccode,_micrcode,v_amount
) returning receiptid into v_receiptid;
end if;
return v_receiptid;
end;
$$;


