--
-- Name: fn_insert_referencemaster_check(kaveri.referancemaster_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_referencemaster_check(p_referencedetails kaveri.referancemaster_input[] DEFAULT NULL::kaveri.referancemaster_input[]) RETURNS integer[]
    LANGUAGE plpgsql
    AS $_$
DECLARE
v_cnt integer;
v_referencedetails_arry kaveri.referancemaster_input[];
v_refid integer;
v_pid integer[];
BEGIN
Select count(*) into v_cnt from kaveri.referencemaster where refid in 
(select a._refid from unnest($1) a) ;
if (p_referencedetails is not null and array_length(p_referencedetails,1)>0 ) then 
 FOR v_referencedetails_arry IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_referencedetails)) 
					loop
						v_cnt:= 0;
Select count(*) into v_cnt from kaveri.referencemaster where refid in 
						(select a._refid from unnest(v_referencedetails_arry) a) ;
	 if v_cnt = 0 then
INSERT INTO kaveri.referencemaster(
    documentid,
    srocode,
    trid,
    throughid,
    referencetext,
    olddocumentid,
    bookid,
    year,
	isregisterinnewbifurcatedoffice,
	volumnnumber,
	frompagenumber,
	topagenumber,
	courtordernumber,
	courtorderdate,
	nameofcourt,
	uploadcourtorderpath
)
select  
    _documentid,
    _srocode,
    _trid,
    _throughid,
    _referencetext,
    _olddocumentid,
    _bookid,
    _year,
	_isregisterinnewbifurcatedoffice,
	_volumnnumber,
	_frompagenumber,
	_topagenumber,
	_courtordernumber,
	_courtorderdate,
	_nameofcourt,
	_uploadcourtorderpath
 from unnest(v_referencedetails_arry)
    RETURNING refid::integer into v_refid;
end if;
v_pid := array_append(v_pid,v_refid);
END LOOP;
 end if;
	return v_pid;
END;
$_$;


ALTER FUNCTION kaveri.fn_insert_referencemaster_check(p_referencedetails kaveri.referancemaster_input[]) OWNER TO csgadmin;

--
-- Name: fn_insert_referencemaster_during_registration(character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_referencemaster_during_registration(_finalregistrationnumber character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
v_newdocumentnumber bigint;
v_olddocumentnumber bigint;
v_srocode bigint;
v_documentidnew bigint;
v_documentidold bigint;
v_sdcalculationstring character varying default null;
v_finalregistrationold character varying;
v_bookidnew bigint;
v_bookidold bigint;
v_trid integer;
v_yearnew character varying;
v_yearold character varying;
v_stampruleid bigint;
referencetextnew character varying ;
referencetextold character varying;
v_refid integer;
begin
if(_finalregistrationnumber is not null)
then
select pm.sdcalculationstring, dm.documentnumber, dm.documentid, dm.srocode, dm.bookid,right(dm.finalregistrationnumber,7),pm.stampruleid
into v_sdcalculationstring,v_newdocumentnumber,v_documentidnew,v_srocode,v_bookidnew,v_yearnew,v_stampruleid
from kaveri.documentmaster dm left outer join kaveri.propertymaster pm on
dm.applicationnumber=pm.applicationnumber
where dm.finalregistrationnumber=_finalregistrationnumber;

select  dm.documentid, dm.srocode, dm.bookid,right(dm.finalregistrationnumber,7),dm.finalregistrationnumber  
into v_documentidold,v_srocode,v_bookidold,v_yearold,v_finalregistrationold
from kaveri.documentmaster dm left outer join kaveri.propertymaster pm on
dm.applicationnumber=pm.applicationnumber
where dm.finalregistrationnumber=v_sdcalculationstring ;
 
if( v_stampruleid=151 )then  --This is for Revocation
        v_trid:=1 ;
      referencetextnew:='This Document Revokes Document No. '||v_sdcalculationstring;
      referencetextold:='This Document has been Revoked by Document No. '||_finalregistrationnumber;

  elsif(v_stampruleid in(39,289,324,320,321)) then --This for Cancellation
        v_trid:=2;
      referencetextnew:='This Document Cancels Document No. '||v_sdcalculationstring;
      referencetextold:='This Document has been Cancelled by Document No. '||_finalregistrationnumber;
-- 
--    elsif(v_trid=4)
--      referencetextnew:='This Document modifies Document No. '|| v_sdcalculationstring.value
--      referencetextold:='This Document has been modified by Document No. '||v_finalregistrationold

  elsif(v_stampruleid in (281,278, 273, 284,164)) then --This is for Rectification
        v_trid:=3;
      referencetextnew:='This Document Rectifies Document No. '||v_sdcalculationstring;
      referencetextold:='This Document has been Rectified by Document No. '||_finalregistrationnumber;

end if;


if(v_documentidold is not null and v_stampruleid in (151,39,289,324,320,321,281,278, 273, 284,164)) then


insert into kaveri.referencemaster
(

  documentid,
  srocode,
  trid,
  throughid,
  referencetext,
  bookid,
  year,
   courtordernumber,
    courtorderdate,
    nameofcourt,
    documentnumber,
    isregisterinnewbifurcatedoffice,
    uploadcourtorderpath,
    oldisregisterinnewbifurcatedoffice
)
values
(

    v_documentidnew,
    v_srocode,
    v_trid,
    1,
    referencetextnew,
    v_bookidnew,
    v_yearnew,
    null,
    null,
    null,
    v_newdocumentnumber,
    false,
    null,
    false
) RETURNING refid into v_refid;

insert into kaveri.referencemaster
(

  documentid,
  srocode,
  trid,
  throughid,
  referencetext,
  bookid,
  year,
   courtordernumber,
    courtorderdate,
    nameofcourt,
    documentnumber,
    isregisterinnewbifurcatedoffice,
    uploadcourtorderpath,
    oldisregisterinnewbifurcatedoffice
)
values
(
    v_documentidold,
    v_srocode,
    v_trid,
    1,
    referencetextold,
    v_bookidold,
    v_yearold,
    null,
    null,
    null,
    v_olddocumentnumber,
    false,
    null,
    false
) RETURNING refid into v_refid;
 else
 return 1001;
end if;
RETURN 1000;
end if;
end;
$$;


ALTER FUNCTION kaveri.fn_insert_referencemaster_during_registration(_finalregistrationnumber character varying) OWNER TO csgadmin;

--
-- Name: fn_insert_referencemaster_during_registration_rule17(character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_referencemaster_during_registration_rule17(_finalregistrationnumber character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
v_newdocumentnumber bigint;
v_olddocumentnumber character varying default null;
v_srocode bigint;
v_documentidnew bigint;
v_documentidold bigint;
v_sdcalculationstring character varying default null;
v_finalregistrationold character varying;
v_bookidnew bigint;
v_bookidold bigint;
v_trid integer;
v_yearnew character varying;
v_yearold character varying;
v_regarticlecode bigint;
referencetextnew character varying ;
referencetextold character varying;
v_refid integer;

v_applicationnumber character varying;

begin
if(_finalregistrationnumber is not null)
then


select dm.documentnumber, dm.documentid, dm.srocode, dm.bookid,right(dm.finalregistrationnumber,7),dm.regarticlecode, dm.applicationnumber
into v_newdocumentnumber,v_documentidnew,v_srocode,v_bookidnew,v_yearnew,v_regarticlecode,v_applicationnumber
from kaveri.documentmaster dm left outer join kaveri.propertymaster pm on 
dm.applicationnumber=pm.applicationnumber
where dm.finalregistrationnumber=_finalregistrationnumber limit 1;

select rf.olddocumentnumber into v_olddocumentnumber from kaveri.rule17filing rf where rf.applicationnumber = v_applicationnumber;

 
if( v_regarticlecode=83 )then  --This is for Revocation
        v_trid:=1 ;
      referencetextnew:='This Document Modified Document No. '||v_olddocumentnumber;
      --referencetextold:='This Document has been Modified by Document No. '||_finalregistrationnumber;

  elsif(v_regarticlecode =32) then --This for Cancellation
        v_trid:=2;
      referencetextnew:='This Document Cancels Document No. '|| v_olddocumentnumber;
      --referencetextold:='This Document has been Cancelled by Document No. '||_finalregistrationnumber;
-- 
--    elsif(v_trid=4)
--      referencetextnew:='This Document modifies Document No. '|| v_sdcalculationstring.value
--      referencetextold:='This Document has been modified by Document No. '||v_finalregistrationold

  elsif(v_regarticlecode=98) then --This is for Rectification
        v_trid:=3;
      referencetextnew:='This Document Rectifies Document No. '||v_olddocumentnumber;
      --referencetextold:='This Document has been Rectified by Document No. '||_finalregistrationnumber;

end if;

insert into kaveri.referencemaster
(

  documentid,
  srocode,
  trid,
  throughid,
  referencetext,
  bookid,
  year,
   courtordernumber,
    courtorderdate,
    nameofcourt,
    documentnumber,
    isregisterinnewbifurcatedoffice,
    uploadcourtorderpath,
    oldisregisterinnewbifurcatedoffice
)
values
(

    v_documentidnew,
    v_srocode,
    v_trid,
    1,
    referencetextnew,
    v_bookidnew,
    v_yearnew,
    null,
    null,
    null,
    v_newdocumentnumber,
    false,
    null,
    false
) RETURNING refid into v_refid;

RETURN v_refid;
end if;
end;
$$;


ALTER FUNCTION kaveri.fn_insert_referencemaster_during_registration_rule17(_finalregistrationnumber character varying) OWNER TO postgres;

--
-- Name: fn_insert_referencemaster_registered_document_chk(bigint, integer, integer, character varying, character varying, integer, character varying, integer, character varying, integer, timestamp without time zone, character varying, integer, integer, boolean, integer, integer, integer, character varying, boolean); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_referencemaster_registered_document_chk(_srocode bigint, _trid integer, _throughid integer, _referencetextnew character varying, _referencetextold character varying, _bookidnew integer, _yearnew character varying, _bookidold integer, _yearold character varying, _courtordernumber integer, _courtorderdate timestamp without time zone, _nameofcourt character varying, _newdocumentnumber integer, _olddocumentnumber integer, _isregisterinnewbifurcatedoffice boolean, _volumnnumber integer, _frompagenumber integer, _topagenumber integer, _uploadcourtorderpath character varying, _oldisregisterinnewbifurcatedoffice boolean) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
 _referenceno text;
 l_now varchar(4);
v_cnt bigint;
_inserted_id text;
v_refid integer;
v_cnt1 integer;
v_cnt_old bigint default 0;
v_documentid bigint;
v_documentid_old bigint;
begin

select count(*), documentid into v_cnt, v_documentid from kaveri.documentmaster where srocode = _srocode and
documentnumber = _newdocumentnumber and bookid = _bookidnew and
case when cast(to_char(REGISTRATIONDATETIME,'MM') as bigint)>3 then cast(to_char(REGISTRATIONDATETIME,'YYYY')as bigint) ||'-'|| to_char(REGISTRATIONDATETIME  + interval '1 year','YY')
else cast(to_char(REGISTRATIONDATETIME,'YYYY')as bigint)-1 ||'-'|| to_char(REGISTRATIONDATETIME,'YY') end=_yearnew
group by documentid;

/*if not found then 
return 1002;
end if;*/

select count(*), documentid into v_cnt_old, v_documentid_old from kaveri.documentmaster where srocode = _srocode and
documentnumber = _olddocumentnumber and bookid = _bookidold  and
case when cast(to_char(REGISTRATIONDATETIME,'MM') as bigint)>3 then cast(to_char(REGISTRATIONDATETIME,'YYYY')as bigint) ||'-'|| to_char(REGISTRATIONDATETIME  + interval '1 year','YY')
else cast(to_char(REGISTRATIONDATETIME,'YYYY')as bigint)-1 ||'-'|| to_char(REGISTRATIONDATETIME,'YY') end=_yearold
group by documentid;

--if not found and split_part(_yearold,'-',1)::bigint>2003 then 
--return 1001;
--end if;

if (_newdocumentnumber is not null) then
insert into kaveri.referencemaster
(
  documentid,
  srocode,
  trid,
  throughid,
  referencetext,
  bookid,
  year,
   courtordernumber,
    courtorderdate,
    nameofcourt,
    documentnumber,
    isregisterinnewbifurcatedoffice,
    volumnnumber,
    frompagenumber,
    topagenumber,
    uploadcourtorderpath,
	oldisregisterinnewbifurcatedoffice
)
values
(
    v_documentid,
    _srocode,
    _trid,
    _throughid,
    _referencetextnew,
    _bookidnew,
    _yearnew,
    _courtordernumber,
    _courtorderdate,
    _nameofcourt,
    _newdocumentnumber,
    _isregisterinnewbifurcatedoffice,
    _volumnnumber,
    _frompagenumber,
    _topagenumber,
    _uploadcourtorderpath,
	_oldisregisterinnewbifurcatedoffice
) RETURNING refid into v_refid;
end if;

if (v_documentid_old is not null)
then

if v_cnt_old >= 1 then
insert into kaveri.referencemaster
(
  documentid,
  srocode,
  trid,
  throughid,
  referencetext,
  bookid,
  year,
   courtordernumber,
    courtorderdate,
    nameofcourt,
    documentnumber,
    isregisterinnewbifurcatedoffice,
    volumnnumber,
    frompagenumber,
    topagenumber,
    uploadcourtorderpath,
	oldisregisterinnewbifurcatedoffice
)
values
(
    v_documentid_old,
    _srocode,
    _trid,
    _throughid,
    _referencetextold,
    _bookidold,
    _yearold,
    _courtordernumber,
    _courtorderdate,
    _nameofcourt,
    _olddocumentnumber,
    _isregisterinnewbifurcatedoffice,
    _volumnnumber,
    _frompagenumber,
    _topagenumber,
    _uploadcourtorderpath,
	_oldisregisterinnewbifurcatedoffice
) RETURNING refid into v_refid;
end if;
else

insert into kaveri.referencemaster
(
  documentid,
  srocode,
  trid,
  throughid,
  referencetext,
  bookid,
  year,
   courtordernumber,
    courtorderdate,
    nameofcourt,
    documentnumber,
    isregisterinnewbifurcatedoffice,
    volumnnumber,
    frompagenumber,
    topagenumber,
    uploadcourtorderpath,
	oldisregisterinnewbifurcatedoffice
)
values
(
    0,
    _srocode,
    _trid,
    _throughid,
    _referencetextold,
    _bookidold,
    _yearold,
    _courtordernumber,
    _courtorderdate,
    _nameofcourt,
    _olddocumentnumber,
    _isregisterinnewbifurcatedoffice,
    _volumnnumber,
    _frompagenumber,
    _topagenumber,
    _uploadcourtorderpath,
	_oldisregisterinnewbifurcatedoffice
) RETURNING refid into v_refid;


end if;


 RETURN 1000;
end
$$;


ALTER FUNCTION kaveri.fn_insert_referencemaster_registered_document_chk(_srocode bigint, _trid integer, _throughid integer, _referencetextnew character varying, _referencetextold character varying, _bookidnew integer, _yearnew character varying, _bookidold integer, _yearold character varying, _courtordernumber integer, _courtorderdate timestamp without time zone, _nameofcourt character varying, _newdocumentnumber integer, _olddocumentnumber integer, _isregisterinnewbifurcatedoffice boolean, _volumnnumber integer, _frompagenumber integer, _topagenumber integer, _uploadcourtorderpath character varying, _oldisregisterinnewbifurcatedoffice boolean) OWNER TO csgadmin;

--
-- Name: fn_insert_roadmaster_details(integer, character varying, character varying, boolean); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_roadmaster_details(_villagecode integer, _roadnamee character varying, _roadnamek character varying, _isactive boolean) RETURNS bigint
    LANGUAGE plpgsql
    AS $$

DECLARE 
v_roadcode bigint;
v_cnt integer;

begin
	
select count(*) into v_cnt from kaveri.roadmaster r where villagecode = _villagecode and roadnamee = _roadnamee;
select roadcode into v_roadcode from kaveri.roadmaster r where villagecode = _villagecode and roadnamee = _roadnamee;

if v_cnt = 0 then
insert into kaveri.roadmaster(
roadcode,
roadnamee,
roadnamek,
villagecode,
roadref,
isactive
) values (
nextval('kaveri.roadcode_seq'),
_roadnamee,
_roadnamek,
_villagecode,
0,
_isactive)
returning roadcode into v_roadcode;

else
update kaveri.roadmaster set isactive = _isactive where roadcode = v_roadcode returning roadcode into v_roadcode;
end if;
return v_roadcode;

end;

$$;


ALTER FUNCTION kaveri.fn_insert_roadmaster_details(_villagecode integer, _roadnamee character varying, _roadnamek character varying, _isactive boolean) OWNER TO postgres;

