--
-- Name: fn_insert_sakala_gscno(character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_sakala_gscno(_applicationnumber character varying) RETURNS TABLE(gscno text, chk boolean)
    LANGUAGE plpgsql
    AS $$
Declare
v_gscno text;
chk boolean;
v_applicationtype int;
begin
  
select applicationtypeid into v_applicationtype from kaveri.applicantapplicationdetails where applicationnumber=_applicationnumber;

chk:=false;

if v_applicationtype =13 then
	select e.gscno into v_gscno from kaveri.ec_applicationdetails e where applicationnumber = _applicationnumber;

	if v_gscno is null or v_gscno = '' then
	 	v_gscno='IG000'||to_char(current_date,'YY')||to_char(nextval('kaveri.gsc_no_seq'),'fm00000000');
		update kaveri.ec_applicationdetails set gscno = v_gscno
    	where applicationnumber=_applicationnumber;
		chk:=true;
	end if;

elseif v_applicationtype =12 then
	select c.gscno into v_gscno from kaveri.cc_applicationdetails c where applicationnumber = _applicationnumber;

	if v_gscno is null or v_gscno = '' then
		v_gscno='IG000'||to_char(current_date,'YY')||to_char(nextval('kaveri.gsc_no_seq'),'fm00000000');
		update kaveri.cc_applicationdetails set gscno = v_gscno
    	where applicationnumber=_applicationnumber;
		chk:=true;
	end if;

else 
	select d.gscno into v_gscno from kaveri.documentmaster d where applicationnumber = _applicationnumber;

	if v_gscno is null or v_gscno = '' then
		v_gscno='IG000'||to_char(current_date,'YY')||to_char(nextval('kaveri.gsc_no_seq'),'fm00000000'); 
		update kaveri.documentmaster set gscno = v_gscno
    	where applicationnumber=_applicationnumber;
		chk:=true;
	end if;
end if;
return query
select v_gscno,chk;
end;
$$;


ALTER FUNCTION kaveri.fn_insert_sakala_gscno(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_insert_sakala_gscno_new(character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_sakala_gscno_new(_applicationnumber character varying) RETURNS TABLE(gscno text, numexists boolean, servicecode integer, subservicecode integer)
    LANGUAGE plpgsql
    AS $$
Declare
v_gscno text;
NumExists boolean;
v_servicecode integer;
v_subservicecode integer;
v_applicationtype int;
v_searchfromdate date;
v_searchtodate date;
v_isbefore2004 boolean;
v_age integer;
v_marriagetype integer;
v_cnt integer;
v_ccdocumenttype integer;
v_ccmarriagetypeid integer;

begin


	select count(1)  into v_cnt from kaveri.applicantapplicationdetails 
		where applicationnumber=_applicationnumber;

	if v_cnt=0 then

			return query select null::text,null::boolean,null::integer,null::integer;
	else
  
		select applicationtypeid into v_applicationtype 
		from kaveri.applicantapplicationdetails 
		where applicationnumber=_applicationnumber;


		NumExists:=false;

			if v_applicationtype =13 then
				select e.gscno,searchfromdate,searchtodate,isbefore2004
				into v_gscno,v_searchfromdate,v_searchtodate,v_isbefore2004 
				from kaveri.ec_applicationdetails e 
				where applicationnumber = _applicationnumber;
			
					if v_isbefore2004=false then 
			     
					        select  
							-- scm.sakalaservicecode,
							12 as sakalaservicecode,0 as sakalasubservicecode
							-- sscm.sakalasubservicecode 
							into v_servicecode,v_subservicecode;
							-- from 
							-- kaveri.sakalaservicecodemaster scm 
							-- join kaveri.sakalasubservicecodemaster sscm on scm.sakalaservicecode=sscm.sakalaservicecode and sscm.isactive = true
							-- where scm.serviceid=v_applicationtype and sscm.fromyearduration is null ;
					else
							select 
							ceiling((v_searchtodate - v_searchfromdate) / 365.25) into v_age ;
							select -- scm.sakalaservicecode,
							case when v_age < 40 then 13 
			 					when v_age > 41 and v_age < 80 then 14
			 					when v_age > 80 then 15 end as sakalaservicecode ,
							0 as sakalasubservicecode
							into v_servicecode,v_subservicecode;
							-- from 
							-- kaveri.sakalaservicecodemaster scm 
							-- join kaveri.sakalasubservicecodemaster sscm on scm.sakalaservicecode=sscm.sakalaservicecode and sscm.isactive = true
							-- where scm.serviceid=v_applicationtype and  v_age>= sscm.fromyearduration and 
					  		--v_age<=sscm.toyearduration;
			        
					end if;
			
				if v_gscno is null or v_gscno = '' then
				 	v_gscno='IG000'||to_char(current_date,'YY')||to_char(nextval('kaveri.gsc_no_seq'),'fm00000000');
					update kaveri.ec_applicationdetails set gscno = v_gscno
			    	where applicationnumber=_applicationnumber;
					NumExists:=true;
				end if;
			
			elseif v_applicationtype =12 then
					select c.gscno,c.documenttype,c.marriagetypeid
  					into v_gscno,v_ccdocumenttype,v_ccmarriagetypeid
					from kaveri.cc_applicationdetails c  					
					where applicationnumber = _applicationnumber;
			 		
				if(v_ccdocumenttype=0 or v_ccdocumenttype is null ) then
						select  scm.sakalaservicecode,sscm.sakalasubservicecode 
						into v_servicecode,v_subservicecode
						from 
						kaveri.sakalaservicecodemaster scm 
						join kaveri.sakalasubservicecodemaster sscm on scm.sakalaservicecode=sscm.sakalaservicecode and sscm.isactive = true
						where scm.serviceid=v_applicationtype and scm.subserviceid=v_ccdocumenttype;

				elseif(v_ccdocumenttype=1) then
			
						select  scm.sakalaservicecode,sscm.sakalasubservicecode 
						into v_servicecode,v_subservicecode
						from 
						kaveri.sakalaservicecodemaster scm 
						join kaveri.sakalasubservicecodemaster sscm on scm.sakalaservicecode=sscm.sakalaservicecode and sscm.isactive = true
						where scm.serviceid=v_applicationtype and scm.subserviceid=v_ccmarriagetypeid; 
						--and  scm.marriagetypeid=v_ccmarriagetypeid;
				end if;
				
			
				if v_gscno is null or v_gscno = '' then
					v_gscno='IG000'||to_char(current_date,'YY')||to_char(nextval('kaveri.gsc_no_seq'),'fm00000000');
					update kaveri.cc_applicationdetails set gscno = v_gscno
			    	where applicationnumber=_applicationnumber;
					NumExists:=true;
				end if;
			
			/*elseif v_applicationtype =4 then
			
				select e.gscno,marriagetypeid
				 into v_gscno,v_marriagetype from kaveri.marriageregistration e 
				where applicationnumber = _applicationnumber ;
				
				select  scm.sakalaservicecode,sscm.sakalasubservicecode 
				into v_servicecode,v_subservicecode
				from 
				kaveri.sakalaservicecodemaster scm 
				join kaveri.sakalasubservicecodemaster sscm on scm.sakalaservicecode=sscm.sakalaservicecode 
				where scm.serviceid=v_applicationtype and 
				scm.subserviceid=v_marriagetype and sscm.fromyearduration is null ;
			
				NumExists:=false;
				
				if(v_gscno is null)
				then 
				v_gscno='IG000'||to_char(current_date,'YY')||to_char(nextval('kaveri.gsc_no_seq'),'fm00000000');
				--select 'IG000'||to_char(current_date,'YY')||to_char(nextval('kaveri.gsc_no_seq'),'fm00000000')
				update kaveri.marriageregistration set gscno = v_gscno
					where applicationnumber=_applicationnumber;
					
				NumExists:=true ;
			
				end if;*/
			
				
			
			else 
				select d.gscno into v_gscno from kaveri.documentmaster d 
				where applicationnumber = _applicationnumber;
				select  scm.sakalaservicecode,sscm.sakalasubservicecode 
				into v_servicecode,v_subservicecode
				from 
				kaveri.sakalaservicecodemaster scm 
				join kaveri.sakalasubservicecodemaster sscm on scm.sakalaservicecode=sscm.sakalaservicecode and sscm.isactive = true
				where scm.serviceid=1 and sscm.fromyearduration is null ;
			
				if v_gscno is null or v_gscno = '' then
					v_gscno='IG000'||to_char(current_date,'YY')||to_char(nextval('kaveri.gsc_no_seq'),'fm00000000'); 
					update kaveri.documentmaster set gscno = v_gscno
			    	where applicationnumber=_applicationnumber;
					NumExists:=true;
				end if;
			
		end if;
		return query
			select v_gscno,NumExists,v_servicecode,v_subservicecode;

end if;
end;
$$;


