--

CREATE FUNCTION kaveri.fn_insert_sakala_uploadfiledetails(_gscno character varying, _srocode integer, _webmethod character varying, _isuploaded boolean, _uploaddatetime timestamp without time zone, _processingcode integer, _processingstatus character varying, _recordsinserted integer, _errordatacount integer, _inputdataset character varying, _istransmitted boolean, _isdeliverytransmitted boolean) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
Declare
v_cnt integer;
v_sid bigint;
begin
insert into kaveri.sakala_uploadfiledetails
(
  sid,
    gscno,
    srocode,
    webmethod,
    isuploaded,
    uploaddatetime,
    processingcode,
    processingstatus,
    recordsinserted,
    errordatacount,
    inputdataset,
    transferdatetime,
    istransmitted,
    isdeliverytransmitted
) values
(
 nextval('kaveri.sid_seq'),
    _gscno,
    _srocode,
    _webmethod,
    _isuploaded,
    _uploaddatetime,
    _processingcode,
    _processingstatus,
    _recordsinserted,
    _errordatacount,
    _inputdataset,
	current_timestamp,
    _istransmitted,
    _isdeliverytransmitted
) returning sid into v_sid;
return v_sid;
end;
$$;


