--

CREATE FUNCTION kaveri.fn_insert_scannedfileuploaddetails(_documentid bigint, _srocode integer, _scannedfilename character varying, _uploadpath character varying, _uploaddatetime timestamp without time zone, _rootdirectory character varying, _documenttypeid integer) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare 
v_docid bigint;
v_count integer;
begin
select count(*) into v_count from kaveri.scannedfileuploaddetails where documentid = _documentid;
if v_count = 0 then
insert into kaveri.scannedfileuploaddetails (
     documentid,
	srocode,
    scannedfilename,
    uploadpath,
    uploaddatetime,
    rootdirectory,
    documenttypeid
) values
(
nextval('kaveri.scannedfileuploaddetails_seq'),
  _srocode,
    _scannedfilename,
    _uploadpath,
    _uploaddatetime,
    _rootdirectory,
    _documenttypeid
) returning documentid::bigint into v_docid;
else
update kaveri.scannedfileuploaddetails set 
	 srocode=_srocode,
    scannedfilename=_scannedfilename,
    uploadpath=_uploadpath,
    uploaddatetime=_uploaddatetime,
    rootdirectory=_rootdirectory,
    documenttypeid=_documenttypeid
	where documentid = _documentid returning documentid::bigint into v_docid;
	end if;
return v_docid;
end;
$$;


ALTER FUNCTION kaveri.fn_insert_scannedfileuploaddetails(_documentid bigint, _srocode integer, _scannedfilename character varying, _uploadpath character varying, _uploaddatetime timestamp without time zone, _rootdirectory character varying, _documenttypeid integer) OWNER TO csgadmin;

--
-- Name: fn_insert_scrutiny_feechange(character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_scrutiny_feechange(_applicationnumber character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$

declare 

v_feesrequired_record kaveri.feesrequired%rowtype;
v_temp_record record;
--v_temp_record record;

v_success bigint;
v_fee_count bigint;

begin
	
	select count(*) into v_fee_count from kaveri.scrutinyfeechange f where f.applicationnumber = _applicationnumber;
	
if v_fee_count = 0 then 
	
	
SELECT * into v_feesrequired_record FROM kaveri.feesrequired f where f.applicationnumber = _applicationnumber ;

if found then 

  FOR v_temp_record IN (select f.applicationnumber, f.feerulecode, f.amountrequired, f.sroamountrequired, f.sfdaamountrequired, propertyid,
	documentid from kaveri.feesrequired f where f.applicationnumber = _applicationnumber )
  
  LOOP
   INSERT INTO kaveri.scrutinyfeechange
( feerulecode, applicationnumber, amountrequired, sroamountrequired, sfdaamountrequired, auditoramountrequired, propertyid, documentid)
VALUES( v_temp_record.feerulecode , v_temp_record.applicationnumber, v_temp_record.amountrequired,v_temp_record.sroamountrequired, v_temp_record.sfdaamountrequired, null, v_temp_record.propertyid,v_temp_record.documentid);

 v_success=1;

END LOOP; 

ELSE
   
   raise notice'Not able to Insert  v_feesrequired_record into scrutnyfeechange ' ;
   v_success=0;
		
	
  
 end if;

else
v_success = 0;
end if;

 return v_success;
	END;
$$;


ALTER FUNCTION kaveri.fn_insert_scrutiny_feechange(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_insert_signed_file_upload_details(text, character varying, text); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_signed_file_upload_details(_fileid text, _applicationnumber character varying, _filepath text) RETURNS text
    LANGUAGE plpgsql
    AS $$
declare 
v_fileid text;
v_cnt integer;
begin
	select count(*) into v_cnt from kaveri.signed_file_upload_details where applicationnumber =_applicationnumber;
	
	if (v_cnt)=0
	then 
	
	insert into kaveri.signed_file_upload_details (fileid,applicationnumber,filepath)
	values (_fileid,_applicationnumber,_filepath);
	
	v_fileid:=_fileid;

	else
	
	update kaveri.signed_file_upload_details 
	set filepath=_filepath
	where applicationnumber=_applicationnumber;
	
	select fileid into v_fileid from kaveri.signed_file_upload_details where applicationnumber =_applicationnumber;
	
	end if;	

return v_fileid;
end
$$;


