--

CREATE FUNCTION kaveri.fn_insert_slotmaster(_sltid bigint, _sltdate timestamp without time zone, _srocode bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
Declare
v_sltid bigint;
v_cnt bigint;
begin
select count(*) into v_cnt from kaveri.slotmaster where sltid = _sltid;
if v_cnt = 0 then
insert into kaveri.slotmaster 
(
     sltid,
    srocode,
    serviceid,
    sltdate,
    sltstarttime,
    sltendtime,
    sltcapacity,
    sltavlcapacity,
    sltisactive,
    isexpress) values
(nextval('kaveri.slotmaster_sltid_seq'),_srocode,1,_sltdate,'09:00','10:00',5,5,true,true),
(nextval('kaveri.slotmaster_sltid_seq'),_srocode,1,_sltdate,'10:00','11:00',5,5,true,true),
(nextval('kaveri.slotmaster_sltid_seq'),_srocode,1,_sltdate,'11:00','12:00',5,5,true,true),
(nextval('kaveri.slotmaster_sltid_seq'),_srocode,1,_sltdate,'13:00','14:00',5,5,true,true),
(nextval('kaveri.slotmaster_sltid_seq'),_srocode,1,_sltdate,'14:00','15:00',5,5,true,true),
(nextval('kaveri.slotmaster_sltid_seq'),_srocode,1,_sltdate,'15:00','16:00',5,5,true,true),
(nextval('kaveri.slotmaster_sltid_seq'),_srocode,1,_sltdate,'16:00','17:00',5,5,true,true)
returning sltid into v_sltid;
end if;
return v_sltid;
end;
$$;


