--

CREATE FUNCTION kaveri.fn_insert_ulmspropertyd(_propertyid bigint, _pid character varying, _json text, _srocode bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$   
declare
v_cnt int;
begin
	
if (Select count(*) from kaveri.ulms_property_importlog a where
                      a.propertyid=_propertyid)=0
then insert into kaveri.ulms_property_importlog(
    propertyid,
    pid,
    json,
    srocode
	) values (_propertyid,_pid,_json,_srocode) ;
	else
	update  kaveri.ulms_property_importlog p2 set
    --propertyid=a._propertyid,
    pid=_pid,
    json=_json,
    srocode=_srocode where p2.propertyid=_propertyid;
    end if;
   return _propertyid;
   end $$;


