--
-- Name: fn_insert_update_bda(bigint, json); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_update_bda(_khatareqid bigint, _khatadetails json) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
    v_count integer;
begin
-- Check if a record already exists for the given khatareqid
select COUNT(*) into v_count from kaveri.KhataBDARespTable where khatareqid = _khatareqid;
if v_count = 0 then
-- Insert a new record if none exists
        insert into kaveri.KhataBDARespTable (khatareqid, khatadetails)
        values (_khatareqid, _khatadetails);
else
-- Update the existing record
        update kaveri.KhataBDARespTable set
		khatadetails = _khatadetails
	where khatareqid = _khatareqid;

end if;
end;

$$;


ALTER FUNCTION kaveri.fn_insert_update_bda(_khatareqid bigint, _khatadetails json) OWNER TO postgres;

--
-- Name: fn_insert_update_cvcopeningclosing(kaveri.cvcopeningclosing_input[]); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_update_cvcopeningclosing(kaveri.cvcopeningclosing_input[] DEFAULT NULL::kaveri.cvcopeningclosing_input[]) RETURNS bigint
    LANGUAGE plpgsql
    AS $_$

declare
v_cnt int;
v_id bigint;
v_check int;
begin 
	
	select count(*) into v_cnt from kaveri.cvcopeningclosing where id in(select a._id from unnest($1)a);
	
--	select count(*) into v_check from( 
--	select * from kaveri.cvcopeningclosing c 
--	join kaveri.sromaster s on s.srocode = c.srocode
--	where c.srocode = a._srocode 
--	and (opendate >=a._opendate or closedate >= a._closedate or extendedcloserdate >= a._extendedcloserdate) and
--	((opendate <= a._opendate or closedate <= a._closedate or extendedcloserdate <= a._extendedcloserdate)))b 
--	where b.srocode in(select a._srocode from unnest($1)a);


select count(*) into v_check from( 
	select * from kaveri.cvcopeningclosing c 
	join kaveri.sromaster s on s.srocode = c.srocode
	where c.srocode = (select a._srocode from unnest($1)a)
	and (opendate >=(select a._opendate from unnest($1)a) or closedate >= (select a._closedate from unnest($1)a) or extendedcloserdate >=(select a._extendedcloserdate from unnest($1)a)) and
	((opendate <=(select a._opendate from unnest($1)a) or closedate <=(select a._closedate from unnest($1)a) or extendedcloserdate <=(select a._extendedcloserdate from unnest($1)a))))b;
	

	if(v_check = 0)then

		if (v_cnt = 0) then
		insert into kaveri.cvcopeningclosing(
			id,
			srocode,
			districtcode,
			opendate,
			closedate,
			extendedcloserdate,
			remark,
			entrydoneby,
			entrydate,
			isenabled,
			disabledby,
			disabledate,
			isapplicabletoalldistrict,
			isapplicabletoallstate,
			lasteditedby,
			lastediteddate
			)
			select
			nextval('kaveri.cvcid_seq'),
			a._srocode,
			a._districtcode,
			a._opendate,
			a._closedate,
			a._extendedcloserdate,
			a._remark,
			a._entrydoneby,
			a._entrydate,
			a._isenabled,
			a._disabledby,
			a._disabledate,
			a._isapplicabletoalldistrict,
			a._isapplicabletoallstate,
			a._lasteditedby,
			current_timestamp
			from unnest($1) a
			returning id into v_id;
		
		else
		
		update kaveri.cvcopeningclosing set
			--srocode = a._srocode,
			--districtcode = a._districtcode,
			--opendate = a._opendate,
			--closedate = a._closedate,
			extendedcloserdate = a._extendedcloserdate,
			--remark = a._remark,
			--entrydoneby = a._entrydoneby,
			--entrydate = a._entrydate,
			isenabled = a._isenabled,
			disabledby = a._disabledby,
			disabledate = a._disabledate,
			--isapplicabletoalldistrict = a._isapplicabletoalldistrict,
			--isapplicabletoallstate = a._isapplicabletoallstate,
			lasteditedby = a._lasteditedby,
			lastediteddate = current_timestamp
			from unnest($1) a
			where id in (select a._id from unnest($1)a) returning id into v_id;
		end if;
	else
		select -1 into v_id;
	end if;
	
return v_id;
end
$_$;


ALTER FUNCTION kaveri.fn_insert_update_cvcopeningclosing(kaveri.cvcopeningclosing_input[]) OWNER TO postgres;

--
-- Name: fn_insert_update_dsc_download_transaction(bigint, character varying, integer, character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_update_dsc_download_transaction(_userid bigint, _version character varying, _versioncode integer, _ipaddress character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
declare
v_check bool;
BEGIN
	if not exists(select 1 from kaveri.dsc_download_transaction where userid = _userid and versioncode = _versioncode) then
		insert into kaveri.dsc_download_transaction(userid,version,versioncode,ipaddress,isactive)
		values(_userid,_version,_versioncode,_ipaddress,true)
		returning true into v_check;
	else 
		update kaveri.dsc_download_transaction 
		set version = _version,versioncode = _versioncode,ipaddress = _ipaddress
		where userid = _userid and versioncode = _versioncode
		returning true into v_check;
	end if;
	return v_check;
END;
$$;


ALTER FUNCTION kaveri.fn_insert_update_dsc_download_transaction(_userid bigint, _version character varying, _versioncode integer, _ipaddress character varying) OWNER TO postgres;

--
-- Name: fn_insert_update_filing_partyinfov2j(jsonb, character varying, jsonb, jsonb, integer, integer, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_update_filing_partyinfov2j(v_property_id_updated jsonb, _application_no character varying, _party_details jsonb, _org_details jsonb, _indiv_or_org integer, _module_type integer, _sro_code integer, _doc_id integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    party_data jsonb;
    org_data jsonb;
    issuing_authority_value character varying;
    property_id integer;
    property_id_array integer[];
    v_property_id_list integer[];
    v_property_id integer;
BEGIN
    -- Convert JSONB property ID list to integer array
    SELECT array_agg(value::integer) 
    INTO property_id_array
    FROM jsonb_array_elements(v_property_id_updated);

    -- Delete existing party details using application number
    DELETE FROM kaveri.partyinfo WHERE applicationnumber = _application_no;


IF _module_type = 3 THEN

-- Insert Individual Party Details
    IF _indiv_or_org = 1 AND _party_details IS NOT NULL THEN
        FOR party_data IN SELECT jsonb_array_elements(_party_details) LOOP
            INSERT INTO kaveri.partyinfo (
                propertyid, applicationnumber, partyid, salutationid, firstname, 
                middlename, lastname, address, isexecutor, ispresenter, srocode, 
                documentid, partytypeid, age
            ) VALUES (
                property_id, _application_no, nextval('kaveri.partyinfo_partyid_seq'),
                (party_data->>'SalutationId')::smallint,
                party_data->>'FirstName',
                party_data->>'MiddleName',
                party_data->>'LastName',
                party_data->>'Address',
                CASE WHEN _module_type = 3 THEN FALSE ELSE TRUE END,
                CASE WHEN _module_type = 3 THEN TRUE ELSE FALSE END,
                _sro_code, _doc_id,
                CASE WHEN _module_type = 3 THEN 1 ELSE 2 END,
                (party_data->>'Age')::integer
            );
        END LOOP;
    END IF;

    -- Insert Organization Details
    IF _indiv_or_org = 2 AND _org_details IS NOT NULL THEN
        FOR org_data IN SELECT jsonb_array_elements(_org_details) LOOP
            INSERT INTO kaveri.partyinfo (
                propertyid, applicationnumber, partyid, firstname, 
                yearofincorp, tanno, 
				--housenumber, 
				address,
				isorganization,
				--pin, 
				--districtcode, 
				--talukcode, 
                isexecutor, ispresenter, srocode, documentid, partytypeid
            ) VALUES (
                property_id, _application_no, nextval('kaveri.partyinfo_partyid_seq'),
                org_data->>'OrgName',
                (org_data->>'YearOfIncorp')::integer, org_data->>'TANNo',
				--org_data->>'HouseNo',
				org_data->>'StreetAddress',
				TRUE,
                --(org_data->>'Pincode')::integer,
				--(org_data->>'DistrictCode')::integer,
				--(org_data->>'TalukCode')::integer,
                TRUE,
                TRUE,
                _sro_code, _doc_id,
                2
            );
        END LOOP;
    END IF;

    -- Handle issuing authority based on module type
   
        SELECT issuingauthority INTO issuing_authority_value 
        FROM kaveri.filing_book1 
        WHERE applicationnumber = _application_no;

    IF issuing_authority_value IS NOT NULL THEN
        SELECT ARRAY(SELECT propertyid FROM kaveri.propertymaster WHERE applicationnumber = _application_no)
        INTO v_property_id_list;

        FOREACH v_property_id IN ARRAY v_property_id_list LOOP
            INSERT INTO kaveri.partyinfo (
                propertyid, applicationnumber, partyid, firstname, middlename, 
                lastname, address, isexecutor, ispresenter, srocode, documentid, partytypeid, age
            ) VALUES (
                --CASE WHEN _module_type = 6 THEN NULL ELSE v_property_id END, 
				v_property_id,
				_application_no, nextval('kaveri.partyinfo_partyid_seq'),
                issuing_authority_value, NULL, NULL, issuing_authority_value,
                CASE WHEN _module_type = 3 THEN TRUE ELSE FALSE END,
                CASE WHEN _module_type = 3 THEN FALSE ELSE TRUE END,
                _sro_code, _doc_id, 
                CASE WHEN _module_type = 3 THEN 2 ELSE 1 END, 
                NULL
            );
        END LOOP;
    END IF;

END IF;

IF _module_type = 6 THEN

-- Insert Individual Party Details
IF _indiv_or_org = 1 AND _party_details IS NOT NULL THEN
    FOR party_data IN SELECT jsonb_array_elements(_party_details) LOOP
        -- Loop through property_id_array
        FOREACH v_property_id IN ARRAY property_id_array LOOP
            INSERT INTO kaveri.partyinfo (
                propertyid, applicationnumber, partyid, salutationid, firstname, 
                middlename, lastname, address, isexecutor, ispresenter, srocode, 
                documentid, partytypeid, age
            ) VALUES (
                --CASE WHEN _module_type = 6 THEN v_property_id ELSE NULL END, 
				v_property_id,
                _application_no, nextval('kaveri.partyinfo_partyid_seq'),
                (party_data->>'SalutationId')::smallint,
                party_data->>'FirstName',
                party_data->>'MiddleName',
                party_data->>'LastName',
                party_data->>'Address',
                CASE WHEN _module_type = 3 THEN FALSE ELSE TRUE END,
                CASE WHEN _module_type = 3 THEN TRUE ELSE FALSE END,
                _sro_code, _doc_id,
                CASE WHEN _module_type = 3 THEN 1 ELSE 2 END,
                (party_data->>'Age')::integer
            );
        END LOOP;
    END LOOP;
END IF;

-- Insert Organization Details
IF _indiv_or_org = 2 AND _org_details IS NOT NULL THEN
    FOR org_data IN SELECT jsonb_array_elements(_org_details) LOOP
        -- Loop through property_id_array
        FOREACH v_property_id IN ARRAY property_id_array LOOP
            INSERT INTO kaveri.partyinfo (
                propertyid, applicationnumber, partyid, firstname, 
                yearofincorp, tanno,
				--housenumber, 
				address,
				isorganization,
				--pin, 
				--districtcode, 
				--talukcode, 
                isexecutor, ispresenter, srocode, documentid, partytypeid
            ) VALUES (
                --CASE WHEN _module_type = 6 THEN v_property_id ELSE NULL END, 
				v_property_id,
                _application_no, nextval('kaveri.partyinfo_partyid_seq'),
                org_data->>'OrgName',
                (org_data->>'YearOfIncorp')::integer, org_data->>'TANNo', 
				--org_data->>'HouseNo', 
				org_data->>'StreetAddress',
				TRUE,
                --(org_data->>'Pincode')::integer, 
				--(org_data->>'DistrictCode')::integer, 
				--(org_data->>'TalukCode')::integer,
                TRUE, TRUE,
                _sro_code, _doc_id,
                2
            );
        END LOOP;
    END LOOP;
END IF;

 	 	

    -- Handle issuing authority based on module type
   
        SELECT issuingauthority INTO issuing_authority_value 
        FROM kaveri.filing_book1 
        WHERE applicationnumber = _application_no;
   
    IF issuing_authority_value IS NOT NULL THEN
            INSERT INTO kaveri.partyinfo (
                propertyid, applicationnumber, partyid, firstname, middlename, 
                lastname, address, isexecutor, ispresenter, srocode, documentid, partytypeid, age
            ) VALUES (
                NULL, _application_no, nextval('kaveri.partyinfo_partyid_seq'),
                issuing_authority_value, NULL, NULL, issuing_authority_value,
                FALSE, TRUE, -- isexecutor = FALSE, ispresenter = TRUE
                _sro_code, _doc_id, 
                1,
                NULL
            );
        END IF;

END IF;

    
END;
$$;


ALTER FUNCTION kaveri.fn_insert_update_filing_partyinfov2j(v_property_id_updated jsonb, _application_no character varying, _party_details jsonb, _org_details jsonb, _indiv_or_org integer, _module_type integer, _sro_code integer, _doc_id integer) OWNER TO postgres;

--
-- Name: fn_insert_update_filing_property_details(character varying, integer, integer, bigint, numeric, integer, character varying, character varying, character varying, character varying, numeric, bigint, integer, boolean, integer[], character varying[], character varying, json, character varying, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_update_filing_property_details(_application_no character varying, _reg_sro_code integer, _property_type_id integer, _village_code bigint, _total_area numeric, _unit_id integer, _north_boundary character varying, _south_boundary character varying, _east_boundary character varying, _west_boundary character varying, _stamp_duty numeric, _doc_id bigint, _sro_code integer, _is_movable boolean, _current_property_type_ids integer[], _current_number character varying[], _schedule_desc character varying, _party_details json, _challan_number character varying, _payment_type integer, _module_type integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_property_id integer;
    party_data jsonb;
    issuing_authority_value character varying;
    v_property_id_list integer[];
    v_property_id_count integer;
    v_table_name text;
BEGIN
    -- Check if a property detail already exists for the given application_no
    SELECT propertyid INTO v_property_id
    FROM kaveri.propertymaster
    WHERE applicationnumber = _application_no AND regsrocode = _reg_sro_code;

    IF v_property_id IS NULL THEN
        INSERT INTO kaveri.propertymaster (
            propertyid, applicationnumber, regsrocode, propertytypeid, villagecode, 
            totalarea, unitid, northboundary, southboundary, eastboundary, westboundary, 
            stampduty, documentid, srocode, ismovableproperty
        ) VALUES (
            nextval('kaveri.propertymastersequence_seq'),
            _application_no, _reg_sro_code, _property_type_id, _village_code, 
            _total_area, _unit_id, _north_boundary, _south_boundary, _east_boundary, _west_boundary, 
            _stamp_duty, _doc_id, _sro_code, _is_movable
        ) RETURNING propertyid INTO v_property_id;
    ELSE
        UPDATE kaveri.propertymaster
        SET propertytypeid = _property_type_id, villagecode = _village_code, 
            totalarea = _total_area, unitid = _unit_id, northboundary = _north_boundary, 
            southboundary = _south_boundary, eastboundary = _east_boundary, 
            westboundary = _west_boundary, stampduty = _stamp_duty, 
            documentid = _doc_id, srocode = _sro_code, ismovableproperty = _is_movable
        WHERE propertyid = v_property_id;
    END IF;

    -- Update filing_book1 based on module type
    IF _module_type = 3 THEN
        UPDATE kaveri.filing_book1
        SET challan_number = _challan_number, payment_type_id = _payment_type, amount_paid = _stamp_duty
        WHERE applicationnumber = _application_no;
    ELSIF _module_type = 6 THEN
        UPDATE kaveri.filing_book1
        SET surety_amount = _surety_amount
        WHERE applicationnumber = _application_no;
    END IF;

    -- Handle property number details
    IF _current_number IS NOT NULL AND _current_property_type_ids IS NOT NULL THEN
        IF array_length(_current_number, 1) = array_length(_current_property_type_ids, 1) THEN
            DELETE FROM kaveri.propertynumberdetails WHERE propertyid = v_property_id;
            FOR i IN 1..array_length(_current_number, 1) LOOP
                INSERT INTO kaveri.propertynumberdetails (
                    propertyid, currentpropertytypeid, currentnumber, srocode
                ) VALUES (
                    v_property_id, _current_property_type_ids[i], _current_number[i], _sro_code
                );
            END LOOP;
        ELSE
            RAISE EXCEPTION 'Array lengths of _current_number and _current_property_type_ids do not match.';
        END IF;
    END IF;

    -- Delete existing party details
    DELETE FROM kaveri.partyinfo WHERE propertyid = v_property_id;

    -- Insert new party details
    IF _party_details IS NOT NULL THEN
        FOR party_data IN SELECT jsonb_array_elements(_party_details::jsonb) LOOP
            INSERT INTO kaveri.partyinfo (
                propertyid, applicationnumber, partyid, salutationid, firstname, 
                middlename, lastname, address, isexecutor, ispresenter, srocode, 
                documentid, partytypeid, age
            ) VALUES (
                v_property_id, _application_no, nextval('kaveri.partyinfo_partyid_seq'),
                 CASE 
                	WHEN _module_type = 3 THEN (party_data->>'SalutationId')::smallint 
                	WHEN _module_type = 6 THEN NULL 
            	 END, 
				 party_data->>'FirstName',
                party_data->>'MiddleName', party_data->>'LastName', party_data->>'Address',
                CASE WHEN _module_type = 3 THEN FALSE ELSE TRUE END,
            	CASE WHEN _module_type = 3 THEN TRUE ELSE FALSE END,
                _sro_code, _doc_id,
				CASE WHEN _module_type = 3 THEN 1 ELSE 2 END,
				(party_data->>'Age')::integer
            );
        END LOOP;
    END IF;

    -- Handle issuing authority based on module type
    IF _module_type = 3 THEN
        SELECT issuingauthority INTO issuing_authority_value FROM kaveri.filing_book1 WHERE applicationnumber = _application_no;
    ELSIF _module_type = 6 THEN
        SELECT issuingauthority INTO issuing_authority_value FROM kaveri.filing_book1 WHERE applicationnumber = _application_no;
    END IF;

    IF issuing_authority_value IS NOT NULL THEN
        SELECT ARRAY(SELECT propertyid FROM kaveri.propertymaster WHERE applicationnumber = _application_no)
        INTO v_property_id_list;

        FOREACH v_property_id IN ARRAY v_property_id_list LOOP
            INSERT INTO kaveri.partyinfo (
                propertyid, applicationnumber, partyid, firstname, middlename, 
                lastname, address, 
				isexecutor,
                ispresenter,
 				srocode, documentid, partytypeid, age
            ) VALUES (
                v_property_id, _application_no, nextval('kaveri.partyinfo_partyid_seq'),
                issuing_authority_value, NULL, NULL, issuing_authority_value,
				CASE WHEN _module_type = 3 THEN TRUE ELSE FALSE END,
            	CASE WHEN _module_type = 3 THEN FALSE ELSE TRUE END,
				 _sro_code, _doc_id, 
				CASE WHEN _module_type = 3 THEN 2 ELSE 1 END, 
				NULL
            );
        END LOOP;
    END IF;

    -- Insert into propertyschedules (only for book1part3)
	IF _module_type = 3 THEN
    	DELETE FROM kaveri.propertyschedules WHERE propertyid = v_property_id;
    	INSERT INTO kaveri.propertyschedules (
        	scheduleid, scheduletype, propertyid, northboundary, southboundary, 
        	eastboundary, westboundary, totalarea, unitid, applicationnumber, srocode, description
    	) VALUES (
        	nextval('kaveri.propertyschedules_scheduleid_seq'),
        	(SELECT COUNT(*)+1 FROM kaveri.propertyschedules WHERE applicationnumber = _application_no)::text || 'A',
        	v_property_id, _north_boundary, _south_boundary, _east_boundary, 
        	_west_boundary, _total_area, _unit_id, _application_no, _sro_code, _schedule_desc
    	);
	END IF;
    RETURN v_property_id;
END;
$$;


ALTER FUNCTION kaveri.fn_insert_update_filing_property_details(_application_no character varying, _reg_sro_code integer, _property_type_id integer, _village_code bigint, _total_area numeric, _unit_id integer, _north_boundary character varying, _south_boundary character varying, _east_boundary character varying, _west_boundary character varying, _stamp_duty numeric, _doc_id bigint, _sro_code integer, _is_movable boolean, _current_property_type_ids integer[], _current_number character varying[], _schedule_desc character varying, _party_details json, _challan_number character varying, _payment_type integer, _module_type integer) OWNER TO postgres;

--
-- Name: fn_insert_update_filing_property_details(character varying, integer, integer, bigint, numeric, integer, character varying, character varying, character varying, character varying, numeric, numeric, bigint, integer, boolean, integer[], character varying[], character varying, json, character varying, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_update_filing_property_details(_application_no character varying, _reg_sro_code integer, _property_type_id integer, _village_code bigint, _total_area numeric, _unit_id integer, _north_boundary character varying, _south_boundary character varying, _east_boundary character varying, _west_boundary character varying, _stamp_duty numeric, _surety_amount numeric, _doc_id bigint, _sro_code integer, _is_movable boolean, _current_property_type_ids integer[], _current_number character varying[], _schedule_desc character varying, _party_details json, _challan_number character varying, _payment_type integer, _module_type integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_property_id integer;
    party_data jsonb;
    issuing_authority_value character varying;
    v_property_id_list integer[];
    v_property_id_count integer;
    v_table_name text;
BEGIN
    -- Check if a property detail already exists for the given application_no
    SELECT propertyid INTO v_property_id
    FROM kaveri.propertymaster
    WHERE applicationnumber = _application_no AND regsrocode = _reg_sro_code;

    IF v_property_id IS NULL THEN
        INSERT INTO kaveri.propertymaster (
            propertyid, applicationnumber, regsrocode, propertytypeid, villagecode, 
            totalarea, unitid, northboundary, southboundary, eastboundary, westboundary, 
            stampduty, documentid, srocode, ismovableproperty
        ) VALUES (
            nextval('kaveri.propertymastersequence_seq'),
            _application_no, _reg_sro_code, _property_type_id, _village_code, 
            _total_area, _unit_id, _north_boundary, _south_boundary, _east_boundary, _west_boundary, 
            _stamp_duty, _doc_id, _sro_code, _is_movable
        ) RETURNING propertyid INTO v_property_id;
    ELSE
        UPDATE kaveri.propertymaster
        SET propertytypeid = _property_type_id, villagecode = _village_code, 
            totalarea = _total_area, unitid = _unit_id, northboundary = _north_boundary, 
            southboundary = _south_boundary, eastboundary = _east_boundary, 
            westboundary = _west_boundary, stampduty = _stamp_duty, 
            documentid = _doc_id, srocode = _sro_code, ismovableproperty = _is_movable
        WHERE propertyid = v_property_id;
    END IF;

    -- Update filing_book1 based on module type
    IF _module_type = 3 THEN
        UPDATE kaveri.filing_book1
        SET challan_number = _challan_number, payment_type_id = _payment_type, amount_paid = _stamp_duty
        WHERE applicationnumber = _application_no;
    ELSIF _module_type = 6 THEN
        UPDATE kaveri.filing_book1
        SET surety_amount = _surety_amount
        WHERE applicationnumber = _application_no;
    END IF;

    -- Handle property number details
    IF _current_number IS NOT NULL AND _current_property_type_ids IS NOT NULL THEN
        IF array_length(_current_number, 1) = array_length(_current_property_type_ids, 1) THEN
            DELETE FROM kaveri.propertynumberdetails WHERE propertyid = v_property_id;
            FOR i IN 1..array_length(_current_number, 1) LOOP
                INSERT INTO kaveri.propertynumberdetails (
                    propertyid, currentpropertytypeid, currentnumber, srocode
                ) VALUES (
                    v_property_id, _current_property_type_ids[i], _current_number[i], _sro_code
                );
            END LOOP;
        ELSE
            RAISE EXCEPTION 'Array lengths of _current_number and _current_property_type_ids do not match.';
        END IF;
    END IF;

    -- Delete existing party details
    DELETE FROM kaveri.partyinfo WHERE propertyid = v_property_id;

    -- Insert new party details
    IF _party_details IS NOT NULL THEN
        FOR party_data IN SELECT jsonb_array_elements(_party_details::jsonb) LOOP
            INSERT INTO kaveri.partyinfo (
                propertyid, applicationnumber, partyid, salutationid, firstname, 
                middlename, lastname, address, isexecutor, ispresenter, srocode, 
                documentid, partytypeid, age
            ) VALUES (
                v_property_id, _application_no, nextval('kaveri.partyinfo_partyid_seq'),
                 CASE 
                	WHEN _module_type = 3 THEN (party_data->>'SalutationId')::smallint 
                	WHEN _module_type = 6 THEN NULL 
            	 END, 
				 party_data->>'FirstName',
                party_data->>'MiddleName', party_data->>'LastName', party_data->>'Address',
                CASE WHEN _module_type = 3 THEN FALSE ELSE TRUE END,
            	CASE WHEN _module_type = 3 THEN TRUE ELSE FALSE END,
                _sro_code, _doc_id,
				CASE WHEN _module_type = 3 THEN 1 ELSE 2 END,
				(party_data->>'Age')::integer
            );
        END LOOP;
    END IF;

    -- Handle issuing authority based on module type
    IF _module_type = 3 THEN
        SELECT issuingauthority INTO issuing_authority_value FROM kaveri.filing_book1 WHERE applicationnumber = _application_no;
    ELSIF _module_type = 6 THEN
        SELECT issuingauthority INTO issuing_authority_value FROM kaveri.filing_book1 WHERE applicationnumber = _application_no;
    END IF;

    IF issuing_authority_value IS NOT NULL THEN
        SELECT ARRAY(SELECT propertyid FROM kaveri.propertymaster WHERE applicationnumber = _application_no)
        INTO v_property_id_list;

        FOREACH v_property_id IN ARRAY v_property_id_list LOOP
            INSERT INTO kaveri.partyinfo (
                propertyid, applicationnumber, partyid, firstname, middlename, 
                lastname, address, 
				isexecutor,
                ispresenter,
 				srocode, documentid, partytypeid, age
            ) VALUES (
                v_property_id, _application_no, nextval('kaveri.partyinfo_partyid_seq'),
                issuing_authority_value, NULL, NULL, issuing_authority_value,
				CASE WHEN _module_type = 3 THEN TRUE ELSE FALSE END,
            	CASE WHEN _module_type = 3 THEN FALSE ELSE TRUE END,
				 _sro_code, _doc_id, 
				CASE WHEN _module_type = 3 THEN 2 ELSE 1 END, 
				NULL
            );
        END LOOP;
    END IF;

    -- Insert into propertyschedules (only for book1part3)
	IF _module_type = 3 THEN
    	DELETE FROM kaveri.propertyschedules WHERE propertyid = v_property_id;
    	INSERT INTO kaveri.propertyschedules (
        	scheduleid, scheduletype, propertyid, northboundary, southboundary, 
        	eastboundary, westboundary, totalarea, unitid, applicationnumber, srocode, description
    	) VALUES (
        	nextval('kaveri.propertyschedules_scheduleid_seq'),
        	(SELECT COUNT(*)+1 FROM kaveri.propertyschedules WHERE applicationnumber = _application_no)::text || 'A',
        	v_property_id, _north_boundary, _south_boundary, _east_boundary, 
        	_west_boundary, _total_area, _unit_id, _application_no, _sro_code, _schedule_desc
    	);
	END IF;
    RETURN v_property_id;
END;
$$;


ALTER FUNCTION kaveri.fn_insert_update_filing_property_details(_application_no character varying, _reg_sro_code integer, _property_type_id integer, _village_code bigint, _total_area numeric, _unit_id integer, _north_boundary character varying, _south_boundary character varying, _east_boundary character varying, _west_boundary character varying, _stamp_duty numeric, _surety_amount numeric, _doc_id bigint, _sro_code integer, _is_movable boolean, _current_property_type_ids integer[], _current_number character varying[], _schedule_desc character varying, _party_details json, _challan_number character varying, _payment_type integer, _module_type integer) OWNER TO postgres;

--
-- Name: fn_insert_update_filing_property_details(character varying, integer, integer, bigint, numeric, integer, character varying, character varying, character varying, character varying, numeric, numeric, bigint, integer, boolean, integer[], character varying[], character varying, json, json, character varying, integer, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_update_filing_property_details(_application_no character varying, _reg_sro_code integer, _property_type_id integer, _village_code bigint, _total_area numeric, _unit_id integer, _north_boundary character varying, _south_boundary character varying, _east_boundary character varying, _west_boundary character varying, _stamp_duty numeric, _surety_amount numeric, _doc_id bigint, _sro_code integer, _is_movable boolean, _current_property_type_ids integer[], _current_number character varying[], _schedule_desc character varying, _party_details json, _org_details json, _challan_number character varying, _payment_type integer, _module_type integer, _indiv_or_org integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_property_id integer;
    party_data jsonb;
	org_data jsonb;
    issuing_authority_value character varying;
    v_property_id_list integer[];
    v_property_id_count integer;
    v_table_name text;
BEGIN
    -- Check if a property detail already exists for the given application_no
    SELECT propertyid INTO v_property_id
    FROM kaveri.propertymaster
    WHERE applicationnumber = _application_no AND regsrocode = _reg_sro_code;

    IF v_property_id IS NULL THEN
        INSERT INTO kaveri.propertymaster (
            propertyid, applicationnumber, regsrocode, propertytypeid, villagecode, 
            totalarea, unitid, northboundary, southboundary, eastboundary, westboundary, 
            stampduty, documentid, srocode, ismovableproperty
        ) VALUES (
            nextval('kaveri.propertymastersequence_seq'),
            _application_no, _reg_sro_code, _property_type_id, _village_code, 
            _total_area, _unit_id, _north_boundary, _south_boundary, _east_boundary, _west_boundary, 
            _stamp_duty, _doc_id, _sro_code, _is_movable
        ) RETURNING propertyid INTO v_property_id;
    ELSE
        UPDATE kaveri.propertymaster
        SET propertytypeid = _property_type_id, villagecode = _village_code, 
            totalarea = _total_area, unitid = _unit_id, northboundary = _north_boundary, 
            southboundary = _south_boundary, eastboundary = _east_boundary, 
            westboundary = _west_boundary, stampduty = _stamp_duty, 
            documentid = _doc_id, srocode = _sro_code, ismovableproperty = _is_movable
        WHERE propertyid = v_property_id;
    END IF;

    -- Update filing_book1 based on module type
    IF _module_type = 3 THEN
        UPDATE kaveri.filing_book1
        SET challan_number = _challan_number, payment_type_id = _payment_type, amount_paid = _stamp_duty
        WHERE applicationnumber = _application_no;
    ELSIF _module_type = 6 THEN
        UPDATE kaveri.propertymaster
        SET consideration = _surety_amount
        WHERE applicationnumber = _application_no;
    END IF;

    -- Handle property number details
    IF _current_number IS NOT NULL AND _current_property_type_ids IS NOT NULL THEN
        IF array_length(_current_number, 1) = array_length(_current_property_type_ids, 1) THEN
            DELETE FROM kaveri.propertynumberdetails WHERE propertyid = v_property_id;
            FOR i IN 1..array_length(_current_number, 1) LOOP
                INSERT INTO kaveri.propertynumberdetails (
                    propertyid, currentpropertytypeid, currentnumber, srocode
                ) VALUES (
                    v_property_id, _current_property_type_ids[i], _current_number[i], _sro_code
                );
            END LOOP;
        ELSE
            RAISE EXCEPTION 'Array lengths of _current_number and _current_property_type_ids do not match.';
        END IF;
    END IF;

    -- Delete existing party details
    DELETE FROM kaveri.partyinfo WHERE propertyid = v_property_id;

    -- Insert new party details
    IF _indiv_or_org = 1 AND _party_details IS NOT NULL THEN
        FOR party_data IN SELECT jsonb_array_elements(_party_details::jsonb) LOOP
            INSERT INTO kaveri.partyinfo (
                propertyid, applicationnumber, partyid, salutationid, firstname, 
                middlename, lastname, address, isexecutor, ispresenter, srocode, 
                documentid, partytypeid, age
            ) VALUES (
                v_property_id, _application_no, nextval('kaveri.partyinfo_partyid_seq'),
                 CASE 
                	WHEN _module_type = 3 THEN (party_data->>'SalutationId')::smallint 
                	ELSE NULL  
            	 END, 
				 party_data->>'FirstName',
                party_data->>'MiddleName', party_data->>'LastName', party_data->>'Address',
                CASE WHEN _module_type = 3 THEN FALSE ELSE TRUE END,
            	CASE WHEN _module_type = 3 THEN TRUE ELSE FALSE END,
                _sro_code, _doc_id,
				CASE WHEN _module_type = 3 THEN 1 ELSE 2 END,
				(party_data->>'Age')::integer
            );
        END LOOP;
    END IF;

		-- Insert Organization Details
		IF _indiv_or_org = 2 AND _org_details IS NOT NULL THEN
        FOR org_data IN SELECT jsonb_array_elements(_org_details::jsonb) LOOP
            INSERT INTO kaveri.partyinfo (
                propertyid, applicationnumber, partyid, firstname, 
                yearofincorp, tanno, housenumber, address, pin, districtcode, talukcode, 
				isexecutor, ispresenter, srocode, documentid, partytypeid
            ) VALUES (
                v_property_id, _application_no, nextval('kaveri.partyinfo_partyid_seq'),
				 org_data->>'OrgName',
                (org_data->>'YearOfIncorp')::integer, org_data->>'TANNo', org_data->>'HouseNo', org_data->>'StreetAddress',
				(org_data->>'Pincode')::integer, (org_data->>'DistrictCode')::integer, (org_data->>'TalukCode')::integer,
                TRUE,
            	TRUE,
                _sro_code, _doc_id,
				2
            );
        END LOOP;
    END IF;

    -- Handle issuing authority based on module type
    IF _module_type = 3 THEN
        SELECT issuingauthority INTO issuing_authority_value FROM kaveri.filing_book1 WHERE applicationnumber = _application_no;
    ELSIF _module_type = 6 THEN
        SELECT issuingauthority INTO issuing_authority_value FROM kaveri.filing_book1 WHERE applicationnumber = _application_no;
    END IF;

    IF issuing_authority_value IS NOT NULL THEN
        SELECT ARRAY(SELECT propertyid FROM kaveri.propertymaster WHERE applicationnumber = _application_no)
        INTO v_property_id_list;

        FOREACH v_property_id IN ARRAY v_property_id_list LOOP
            INSERT INTO kaveri.partyinfo (
                propertyid, applicationnumber, partyid, firstname, middlename, 
                lastname, address, 
				isexecutor,
                ispresenter,
 				srocode, documentid, partytypeid, age
            ) VALUES (
                v_property_id, _application_no, nextval('kaveri.partyinfo_partyid_seq'),
                issuing_authority_value, NULL, NULL, issuing_authority_value,
				CASE WHEN _module_type = 3 THEN TRUE ELSE FALSE END,
            	CASE WHEN _module_type = 3 THEN FALSE ELSE TRUE END,
				 _sro_code, _doc_id, 
				CASE WHEN _module_type = 3 THEN 2 ELSE 1 END, 
				NULL
            );
        END LOOP;
    END IF;

    -- Insert into propertyschedules
    	DELETE FROM kaveri.propertyschedules WHERE propertyid = v_property_id;
    	INSERT INTO kaveri.propertyschedules (
        	scheduleid, scheduletype, propertyid, northboundary, southboundary, 
        	eastboundary, westboundary, totalarea, unitid, applicationnumber, srocode, description
    	) VALUES (
        	nextval('kaveri.propertyschedules_scheduleid_seq'),
        	(SELECT COUNT(*)+1 FROM kaveri.propertyschedules WHERE applicationnumber = _application_no)::text || 'A',
        	v_property_id, _north_boundary, _south_boundary, _east_boundary, 
        	_west_boundary, _total_area, _unit_id, _application_no, _sro_code, _schedule_desc
    	);
    RETURN v_property_id;
END;
$$;


ALTER FUNCTION kaveri.fn_insert_update_filing_property_details(_application_no character varying, _reg_sro_code integer, _property_type_id integer, _village_code bigint, _total_area numeric, _unit_id integer, _north_boundary character varying, _south_boundary character varying, _east_boundary character varying, _west_boundary character varying, _stamp_duty numeric, _surety_amount numeric, _doc_id bigint, _sro_code integer, _is_movable boolean, _current_property_type_ids integer[], _current_number character varying[], _schedule_desc character varying, _party_details json, _org_details json, _challan_number character varying, _payment_type integer, _module_type integer, _indiv_or_org integer) OWNER TO postgres;

--
-- Name: fn_insert_update_filing_property_detailsv2j(jsonb, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_update_filing_property_detailsv2j(_properties jsonb, _module_type integer) RETURNS TABLE(prop_id integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    property jsonb;
    v_property_id integer;
    v_existing_properties integer[];
    v_is_update boolean;
    _payment_type integer;
    _challan_number character varying;
    _stamp_duty numeric;
    _surety_amount numeric;
    module_type integer;
BEGIN 
    IF _properties IS NULL OR jsonb_array_length(_properties) = 0 THEN
        RETURN;
    END IF;

    CREATE TEMP TABLE IF NOT EXISTS temp_processed_properties(property_id integer) ON COMMIT DROP;

	-- Delete all existing schedules for the given property ID
    DELETE FROM kaveri.propertyschedules
	WHERE applicationnumber = (SELECT (propertys ->> 'application_no') 
                           FROM jsonb_array_elements(_properties) AS propertys
                           LIMIT 1);

    -- Fetch common fields
    SELECT (propertys ->> 'payment_type')::integer, 
           propertys ->> 'challan_number', 
           (propertys ->> 'stamp_duty')::numeric,
           (propertys ->> 'surety_amount')::numeric,
           _module_type
    INTO _payment_type, _challan_number, _stamp_duty, _surety_amount, module_type
    FROM jsonb_array_elements(_properties) AS propertys
    LIMIT 1;

    

    -- Loop through each property
    FOR property IN SELECT * FROM jsonb_array_elements(_properties) LOOP
        v_is_update := false;
        
        IF (property->>'propertyid') IS NOT NULL THEN
            v_property_id := (property->>'propertyid')::integer;
            
            IF EXISTS (SELECT 1 FROM kaveri.propertymaster WHERE propertyid = v_property_id) THEN
                v_is_update := true;
                
                UPDATE kaveri.propertymaster
                SET propertytypeid = (property->>'property_type_id')::integer,
                    villagecode = (property->>'village_code')::bigint,
                    totalarea = (property->>'total_area')::numeric,
                    unitid = (property->>'unit_id')::integer,
                    northboundary = property->>'north_boundary',
                    southboundary = property->>'south_boundary',
                    eastboundary = property->>'east_boundary',
                    westboundary = property->>'west_boundary',
                    stampduty = (property->>'stamp_duty')::numeric,
					consideration = (property->>'surety_amount')::numeric,
					sroconsideration = (property->>'surety_amount')::numeric,
                    documentid = (property->>'doc_id')::bigint,
                    srocode = (property->>'sro_code')::integer,
                    ismovableproperty = (property->>'is_movable')::boolean
                WHERE propertyid = v_property_id;
            ELSE
                INSERT INTO kaveri.propertymaster (
                    propertyid, applicationnumber, regsrocode, propertytypeid, villagecode, 
                    totalarea, unitid, northboundary, southboundary, eastboundary, westboundary, 
					stamparticlecode, stampruleid, regarticlecode,
                    stampduty, consideration, sroconsideration, documentid, srocode, ismovableproperty
                ) VALUES (
                    nextval('kaveri.propertymastersequence_seq'),
                    property->>'application_no', (property->>'reg_sro_code')::integer,
                    (property->>'property_type_id')::integer, (property->>'village_code')::bigint,
                    (property->>'total_area')::numeric, (property->>'unit_id')::integer,
                    property->>'north_boundary', property->>'south_boundary',
                    property->>'east_boundary', property->>'west_boundary',
					(property->>'_stamparticlecode')::numeric,(property->>'_stampruleid')::numeric,
					(property->>'_regarticlecode')::numeric,
                    (property->>'stamp_duty')::numeric,
					(property->>'surety_amount')::numeric,
					(property->>'surety_amount')::numeric,
					(property->>'doc_id')::bigint,
                    (property->>'sro_code')::integer, (property->>'is_movable')::boolean
                ) RETURNING propertyid INTO v_property_id;
            END IF;

            INSERT INTO temp_processed_properties(property_id) VALUES (v_property_id);
        END IF;

		-- Update filing_book1 or propertymaster based on module type
	RAISE NOTICE 'Module Type: %', _module_type;

		IF module_type IS NULL THEN
    		RAISE NOTICE 'Error: _module_type is NULL!';
		END IF;

    IF module_type = 3 THEN
        UPDATE kaveri.filing_book1
        SET challan_number = _challan_number, payment_type_id = _payment_type, amount_paid = _stamp_duty
        WHERE applicationnumber = (SELECT propertys ->> 'application_no' FROM jsonb_array_elements(_properties) AS propertys LIMIT 1);
    END IF;
	IF module_type = 6 THEN
        --UPDATE kaveri.propertymaster
        --SET consideration = _surety_amount, stampduty = null
        --WHERE applicationnumber = (SELECT propertys ->> 'application_no' FROM jsonb_array_elements(_properties) AS propertys LIMIT 1);
		UPDATE kaveri.filing_book1
        SET surety_amount = _surety_amount
        WHERE applicationnumber = (SELECT propertys ->> 'application_no' FROM jsonb_array_elements(_properties) AS propertys LIMIT 1);
    END IF;

        -- Handle property number details
        DELETE FROM kaveri.propertynumberdetails WHERE propertyid = v_property_id;
        PERFORM kaveri.fn_insert_update_propertynumberdetailsV2(
            v_property_id,
            ARRAY(SELECT (jsonb_array_elements(property -> 'current_property_type_ids'))::int),
            --ARRAY(SELECT (jsonb_array_elements(property -> 'current_number'))::varchar),
    		ARRAY(SELECT trim(both '"' FROM jsonb_array_elements_text(property -> 'current_number'))),
            (property->>'reg_sro_code')::int
        );

        -- Handle property schedules
        IF v_property_id IS NOT NULL THEN
            PERFORM kaveri.fn_insert_update_propertyschedulesV2(
                v_property_id,
        btrim(property ->> 'application_no'),
        btrim(property ->> 'north_boundary'),
        btrim(property ->> 'south_boundary'),
        btrim(property ->> 'east_boundary'),
        btrim(property ->> 'west_boundary'),
        (property ->> 'total_area')::numeric,
        (property ->> 'unit_id')::integer,
        (property ->> 'reg_sro_code')::integer,
        btrim(property ->> '_schedule_desc')
            );
        END IF;
    END LOOP;

    -- Delete unprocessed properties
    DELETE FROM kaveri.propertymaster
    WHERE propertyid = ANY(v_existing_properties)
    AND propertyid NOT IN (SELECT property_id FROM temp_processed_properties);

    RETURN QUERY SELECT property_id FROM temp_processed_properties;
END;
$$;


ALTER FUNCTION kaveri.fn_insert_update_filing_property_detailsv2j(_properties jsonb, _module_type integer) OWNER TO postgres;

--
-- Name: fn_insert_update_k1pendingdashboard(character varying, character varying, integer, integer, bigint, character varying, timestamp without time zone); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_update_k1pendingdashboard(_applicationnumber character varying, _pendingnumber character varying, _pendingsrocode integer, _statuscode integer, _citizenid bigint, _drorderfilepathcitizen character varying, _presentationdate timestamp without time zone) RETURNS text
    LANGUAGE plpgsql
    AS $$

declare
v_cnt bigint;
v_applicationid bigint;
--v_partner_arry kaveri.type_k1pendingdashboard[];
v_applicationnumber text;
begin

-- if(p_partnerdetails is not null and array_length(p_partnerdetails,1)>0 ) then

--  FOR v_partner_arry IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_partnerdetails)) 

			 Select count(*) into v_cnt from kaveri.k1pendingdashboard where applicationnumber = _applicationnumber;
		if v_cnt = 0 
		
		then
			  Update kaveri.applicantapplicationdetails set currentstatus = 'CD118' where applicationnumber = _applicationnumber;--Added by shubham date 20/12/2023

			  insert into kaveri.k1pendingdashboard
			  (applicationid,
			   applicationnumber,
			   pendingnumber,
			   pendingsrocode,
			   statuscode,
			   citizenid,
			   drorderfilepathcitizen,
			   presentationDate
			  )
values(
nextval('kaveri.k1pendingsudashboard_applicationid_seq'),
	_applicationnumber,
	_pendingnumber,
	_pendingsrocode,
	_statuscode,
	_citizenid ,
	_drorderfilepathcitizen,
    _presentationDate)
 returning applicationnumber into v_applicationnumber;
	

		else

			if _statuscode = 4 then
				Update kaveri.applicantapplicationdetails set currentstatus = 'CD119' where applicationnumber = _applicationnumber;--Added by shubham date 20/12/2023
			end if;
			update kaveri.k1pendingdashboard p1 set 
			--applicationnumber=COALESCE(_applicationnumber,applicationnumber),
			-- pendingnumber= COALESCE(_pendingnumber,pendingnumber),
			--pendingsrocode=COALESCE(_pendingsrocode,pendingsrocode),
			statuscode = COALESCE(_statuscode,statuscode) 
			--citizenid = COALESCE(_citizenid,citizenid),
			where applicationnumber = _applicationnumber returning applicationnumber into v_applicationnumber;

		
 end if;
--end if;
return v_applicationnumber;

end;
$$;


ALTER FUNCTION kaveri.fn_insert_update_k1pendingdashboard(_applicationnumber character varying, _pendingnumber character varying, _pendingsrocode integer, _statuscode integer, _citizenid bigint, _drorderfilepathcitizen character varying, _presentationdate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_insert_update_otherreasonremarks(bigint, character varying, integer, character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_update_otherreasonremarks(_id bigint, _applicationnumber character varying, _reasonid integer, _remarks character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$

DECLARE 
v_cnt integer;
v_id bigint;

begin

	select count(*) into v_cnt from kaveri.otherreasonremarks where applicationnumber = _applicationnumber; -- and id = _id;

if v_cnt = 0 then

	insert into kaveri.otherreasonremarks(
	id,
	applicationnumber,
	reasonid,
	remarks) 
	values (
	nextval('kaveri.otherreasonremarks_id'),
	_applicationnumber,
	_reasonid,
	_remarks)
	returning id into v_id;

 else

 update kaveri.otherreasonremarks 
 	set remarks = _remarks,
 		reasonid = _reasonid
 	where applicationnumber  = _applicationnumber 
 returning _id into v_id;

 end if;

return v_id;

end;

$$;


ALTER FUNCTION kaveri.fn_insert_update_otherreasonremarks(_id bigint, _applicationnumber character varying, _reasonid integer, _remarks character varying) OWNER TO postgres;

--
-- Name: fn_insert_update_partyinfov2j(jsonb, character varying, jsonb, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_update_partyinfov2j(v_property_id_updated jsonb, _application_no character varying, _party_details jsonb, _sro_code integer, _doc_id integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    party_data jsonb;
    issuing_authority_value character varying;
    property_id integer;
    property_id_array integer[];
BEGIN
    -- Convert JSONB property ID list to integer array
    SELECT array_agg(value::integer) 
    INTO property_id_array
    FROM jsonb_array_elements(v_property_id_updated);

    -- Delete existing party details using application number
    DELETE FROM kaveri.partyinfo WHERE applicationnumber = _application_no;

    -- Insert new party details
    IF _party_details IS NOT NULL THEN
        FOR party_data IN SELECT jsonb_array_elements(_party_details) LOOP
            INSERT INTO kaveri.partyinfo (
                applicationnumber, partyid, salutationid, firstname, middlename, lastname, 
                address, isexecutor, ispresenter, srocode, documentid, partytypeid, age
            ) VALUES (
                _application_no, nextval('kaveri.partyinfo_partyid_seq'),
                (party_data->>'SalutationId')::smallint, party_data->>'FirstName', 
                party_data->>'MiddleName', party_data->>'LastName', party_data->>'Address', 
                (party_data->>'IsExecutor')::boolean, (party_data->>'IsPresenter')::boolean, 
                _sro_code, _doc_id, 1, (party_data->>'Age')::integer
            );
        END LOOP;
    END IF;

    -- Fetch issuing authority
    SELECT issuingauthority INTO issuing_authority_value 
    FROM kaveri.book1_part3_court
    WHERE applicationnumber = _application_no;

    -- If issuing authority exists, update all associated property IDs
    IF issuing_authority_value IS NOT NULL THEN
        FOREACH property_id IN ARRAY property_id_array LOOP
            INSERT INTO kaveri.partyinfo (
                propertyid, applicationnumber, partyid, firstname, middlename, lastname, 
                address, isexecutor, ispresenter, srocode, documentid, partytypeid, age
            ) VALUES (
                property_id, _application_no, nextval('kaveri.partyinfo_partyid_seq'),
                issuing_authority_value, NULL, NULL, issuing_authority_value, TRUE, FALSE, 
                _sro_code, _doc_id, 2, NULL
            );
        END LOOP;
    END IF;
END;
$$;


ALTER FUNCTION kaveri.fn_insert_update_partyinfov2j(v_property_id_updated jsonb, _application_no character varying, _party_details jsonb, _sro_code integer, _doc_id integer) OWNER TO postgres;

--
-- Name: fn_insert_update_property_details(character varying, integer, integer, bigint, numeric, integer, character varying, character varying, character varying, character varying, numeric, bigint, integer, boolean, integer[], character varying[], character varying, json); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_update_property_details(_application_no character varying, _reg_sro_code integer, _property_type_id integer, _village_code bigint, _total_area numeric, _unit_id integer, _north_boundary character varying, _south_boundary character varying, _east_boundary character varying, _west_boundary character varying, _stamp_duty numeric, _doc_id bigint, _sro_code integer, _is_movable boolean, _current_property_type_ids integer[], _current_number character varying[], _schedule_desc character varying, _party_details json) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_property_id integer;
	--current_property_type_id integer;
	party_data jsonb;
	current_number character varying;
	issuing_authority_value character varying;
	v_property_id_list integer[];
	v_property_id_count integer;
BEGIN
    -- Check if a property detail already exists for the given application_no
    SELECT propertyid INTO v_property_id
    FROM kaveri.propertymaster
    WHERE applicationnumber = _application_no AND regsrocode = _reg_sro_code;

    IF v_property_id IS NULL THEN
        -- Insert new record if it does not exist
        INSERT INTO kaveri.propertymaster (
            propertyid,
            applicationnumber,
            regsrocode,
            propertytypeid,
            villagecode,
            totalarea,
            unitid,
            northboundary,
            southboundary,
            eastboundary,
            westboundary,
