--
-- Name: fn_insert_update_property_detailsv2j(jsonb); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_update_property_detailsv2j(_properties jsonb) RETURNS TABLE(prop_id integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    property jsonb;
    v_property_id integer;
    v_existing_properties integer[];
    v_is_update boolean;
	_payment_type integer;
    _challan_number character varying;
    _stamp_duty numeric;
BEGIN 
    -- Check if the input JSON is NULL or an empty array
    IF _properties IS NULL OR jsonb_array_length(_properties) = 0 THEN
        RETURN;
    END IF;

    -- Create a temporary table to store processed property IDs
    CREATE TEMP TABLE IF NOT EXISTS temp_processed_properties(property_id integer) ON COMMIT DROP;

		-- Delete all existing schedules for the given property ID
    DELETE FROM kaveri.propertyschedules
	WHERE applicationnumber = (SELECT (propertys ->> 'application_no') 
                           FROM jsonb_array_elements(_properties) AS propertys
                           LIMIT 1);

	SELECT (propertys ->> 'payment_type')::integer, 
       propertys ->> 'challan_number', 
       (propertys ->> 'stamp_duty')::numeric
		INTO _payment_type, _challan_number, _stamp_duty
		FROM jsonb_array_elements(_properties) AS propertys
		LIMIT 1;

	-- Update the book1_part3_court table with the fetched values
	UPDATE kaveri.book1_part3_court
	SET challan_number = _challan_number, 
    	payment_type_id = _payment_type, 
    	amount_paid = _stamp_duty
	WHERE applicationnumber = (SELECT (propertys ->> 'application_no') 
                           FROM jsonb_array_elements(_properties) AS propertys
                           LIMIT 1);


    -- Loop through each property in the input JSON array
    FOR property IN SELECT * FROM jsonb_array_elements(_properties) LOOP
        v_is_update := false;

        -- Check if the property ID exists in the input
        IF (property->>'propertyid') IS NOT NULL THEN
            v_property_id := (property->>'propertyid')::integer;

            -- Check if the property ID exists in the database
            IF EXISTS (SELECT 1 FROM kaveri.propertymaster WHERE propertyid = v_property_id) THEN
                v_is_update := true;

                -- Update existing property
                UPDATE kaveri.propertymaster
                SET
                    propertytypeid = (property->>'property_type_id')::integer,
                    villagecode = (property->>'village_code')::bigint,
                    totalarea = (property->>'total_area')::numeric,
                    unitid = (property->>'unit_id')::integer,
                    northboundary = property->>'north_boundary',
                    southboundary = property->>'south_boundary',
                    eastboundary = property->>'east_boundary',
                    westboundary = property->>'west_boundary',
                    stampduty = (property->>'stamp_duty')::numeric,
                    documentid = (property->>'doc_id')::bigint,
                    srocode = (property->>'sro_code')::integer,
                    ismovableproperty = (property->>'is_movable')::boolean
                WHERE propertyid = v_property_id;
            ELSE
                -- Insert new property
                INSERT INTO kaveri.propertymaster (
                    propertyid,
                    applicationnumber,
                    regsrocode,
                    propertytypeid,
                    villagecode,
                    totalarea,
                    unitid,
                    northboundary,
                    southboundary,
                    eastboundary,
                    westboundary,
					stamparticlecode, 
					stampruleid, 
					regarticlecode,
                    stampduty,
                    documentid,
                    srocode,
                    ismovableproperty
                ) VALUES (
                    nextval('kaveri.propertymastersequence_seq'),
                    property->>'application_no',
                    (property->>'reg_sro_code')::integer,
                    (property->>'property_type_id')::integer,
                    (property->>'village_code')::bigint,
                    (property->>'total_area')::numeric,
                    (property->>'unit_id')::integer,
                    property->>'north_boundary',
                    property->>'south_boundary',
                    property->>'east_boundary',
                    property->>'west_boundary',
					15,
					42,
					39,
                    (property->>'stamp_duty')::numeric,
                    (property->>'doc_id')::bigint,
                    (property->>'sro_code')::integer,
                    (property->>'is_movable')::boolean
                ) RETURNING propertyid INTO v_property_id;
            END IF;

            -- Track processed property IDs
            INSERT INTO temp_processed_properties(property_id) VALUES (v_property_id);
        END IF;

		DELETE FROM kaveri.propertynumberdetails
    	WHERE propertyid = v_property_id;

        -- Call related functions
        PERFORM kaveri.fn_insert_update_propertynumberdetailsV2(
            v_property_id,
            ARRAY(SELECT (jsonb_array_elements(property -> 'current_property_type_ids'))::int),
--            ARRAY(SELECT (jsonb_array_elements(property -> 'current_number'))::varchar),
    		ARRAY(SELECT trim(both '"' FROM jsonb_array_elements_text(property -> 'current_number'))),
            (property->>'reg_sro_code')::int
        );

        IF v_property_id IS NOT NULL THEN
            PERFORM kaveri.fn_insert_update_propertyschedulesV2(
                v_property_id,
                property ->> 'application_no',
                property ->> 'north_boundary',
                property ->> 'south_boundary',
                property ->> 'east_boundary',
                property ->> 'west_boundary',
                (property ->> 'total_area')::numeric,
                (property ->> 'unit_id')::integer,
                (property ->> 'reg_sro_code')::integer,
                property ->> '_schedule_desc'
            );
        END IF;
    END LOOP;

    -- Delete unprocessed properties
    DELETE FROM kaveri.propertymaster
    WHERE propertyid = ANY(v_existing_properties)
    AND propertyid NOT IN (SELECT property_id FROM temp_processed_properties);

    -- Return the result from the temporary table
    RETURN QUERY SELECT property_id FROM temp_processed_properties;
END;
$$;


ALTER FUNCTION kaveri.fn_insert_update_property_detailsv2j(_properties jsonb) OWNER TO postgres;

--
-- Name: fn_insert_update_propertynumberdetailsv2(integer, integer[], character varying[], integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_update_propertynumberdetailsv2(v_property_id integer, _current_property_type_ids integer[], _current_number character varying[], _sro_code integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    i integer;
BEGIN
    -- Check if arrays are not NULL or empty
    IF _current_property_type_ids IS NOT NULL AND array_length(_current_property_type_ids, 1) > 0 THEN
        FOR i IN 1..array_length(_current_number, 1) LOOP
            INSERT INTO kaveri.propertynumberdetails (
                propertyid,
                currentpropertytypeid,
                currentnumber,
                srocode
            ) VALUES (
                v_property_id,
                _current_property_type_ids[i],
                _current_number[i],
                _sro_code
            );
        END LOOP;
    END IF;
END;
$$;


ALTER FUNCTION kaveri.fn_insert_update_propertynumberdetailsv2(v_property_id integer, _current_property_type_ids integer[], _current_number character varying[], _sro_code integer) OWNER TO postgres;

--
-- Name: fn_insert_update_propertyschedulesv2(integer, character varying, character varying, character varying, character varying, character varying, numeric, integer, integer, character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_update_propertyschedulesv2(v_property_id integer, _application_no character varying, _north_boundary character varying, _south_boundary character varying, _east_boundary character varying, _west_boundary character varying, _total_area numeric, _unit_id integer, _sro_code integer, _schedule_desc character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_schedule_id integer;
    v_property_id_list integer[];
    v_property_id_count integer;
    v_max_count integer;
BEGIN

    -- Get the current maximum count for the given application number
    SELECT COALESCE(MAX(CAST(substring(scheduletype, 1, LENGTH(scheduletype) - 1) AS integer)), 0) + 1
    INTO v_max_count
    FROM kaveri.propertyschedules
    WHERE applicationnumber = _application_no;

    -- Insert a new schedule
    INSERT INTO kaveri.propertyschedules (
        scheduleid,
        scheduletype,
        propertyid,
        northboundary,
        southboundary,
        eastboundary,
        westboundary,
        totalarea,
        unitid,
        applicationnumber,
        srocode,
        description
    ) VALUES (
        nextval('kaveri.propertyschedules_scheduleid_seq'),
        v_max_count || 'A',
        v_property_id,
        _north_boundary,
        _south_boundary,
        _east_boundary,
        _west_boundary,
        _total_area,
        _unit_id,
        _application_no,
        _sro_code,
        _schedule_desc
    );
END;
$$;


ALTER FUNCTION kaveri.fn_insert_update_propertyschedulesv2(v_property_id integer, _application_no character varying, _north_boundary character varying, _south_boundary character varying, _east_boundary character varying, _west_boundary character varying, _total_area numeric, _unit_id integer, _sro_code integer, _schedule_desc character varying) OWNER TO postgres;

--
-- Name: fn_insert_update_roadmaster(integer, character varying, character varying, boolean); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_update_roadmaster(_roadcode integer, _roadnamee character varying, _roadnamek character varying, _isactive boolean) RETURNS bigint
    LANGUAGE plpgsql
    AS $$

DECLARE 
v_roadcode bigint;
v_villagecode bigint;
v_cnt integer;
v_cnt2 integer;
v_roadnamee varchar;
v_roadnamek varchar;
v_isactive bool;
v_check int;

begin


select count(*) into v_check from
(select distinct c.srocode from kaveri.cvcopeningclosing c 
join kaveri.villagemaster v on v.srocode = c.srocode
join kaveri.roadmaster r on r.villagecode = v.villagecode
where (opendate >= CURRENT_TIMESTAMP::date or 
closedate >= CURRENT_TIMESTAMP::date or extendedcloserdate >= CURRENT_TIMESTAMP::date) 
and isenabled=true and r.roadcode= _roadcode)as ss;

if v_check = 1 then 

select roadnamee,roadnamek,isactive into v_roadnamee,v_roadnamek,v_isactive from kaveri.roadmaster r where roadcode = _roadcode;

--select count(*) into v_cnt from kaveri.roadmaster where roadcode = _roadcode;
	update kaveri.roadmaster 
	set roadnamee = _roadnamee,
	    roadnamek = _roadnamek,
	    isactive =_isactive
	where roadcode = _roadcode 
	returning roadcode into v_roadcode;
	
select villagecode into v_villagecode from kaveri.roadmaster r where roadcode = _roadcode;

select count(roadcode) into v_cnt2 from kaveri.roadmaster r where villagecode = v_villagecode and roadnamee = _roadnamee;

if v_cnt2 >= 2 then
	update kaveri.roadmaster 
	set roadnamee = v_roadnamee,
	    roadnamek = v_roadnamek,
	    isactive = v_isactive
	where roadcode = _roadcode 
	returning -1 into v_roadcode;
else 
	update kaveri.roadmaster 
	set roadnamee = _roadnamee,
	    roadnamek = _roadnamek,
	    isactive = _isactive
	where roadcode = _roadcode 
	returning roadcode into v_roadcode;
end if;

else 
	select -1 into v_roadcode;
end if;
return v_roadcode;
end;
$$;


