--
-- Name: fn_insert_update_rule17filing(character varying, character varying, integer, integer, integer, integer, timestamp without time zone, integer, character varying, character varying, character varying, character varying, boolean, character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_insert_update_rule17filing(_applicationnumber character varying, _communicationnumber character varying, _srocode integer, _bookid integer, _registrationarticle integer, _stamparticle integer, _dateofcommunication timestamp without time zone, _stampruleid integer, _currentstatus character varying, _indexiisummary character varying DEFAULT NULL::character varying, _endorsementdocument character varying DEFAULT NULL::character varying, _courtdocument character varying DEFAULT NULL::character varying, _isdigitalsigned boolean DEFAULT NULL::boolean, _olddocumentnumber character varying DEFAULT NULL::character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$

declare

v_cnt bigint;

 

v_requestid integer;

begin

select count(*) into v_cnt from kaveri.rule17filing where applicationnumber = _applicationnumber ;


if v_cnt = 0 then

insert into kaveri.rule17filing ( requestid,
	applicationnumber,
	communicationnumber,
	srocode,
	bookid,
	registrationarticle,
	stamparticle,
	dateofcommunication,
	stampruleid,
	currentstatus,
	indexiisummary,
	endorsementdocument,
	courtdocument,
	olddocumentnumber
	)
values(
	nextval('kaveri.rule17filing_requestid_seq'),
	_applicationnumber,
	_communicationnumber,
	_srocode,
	_bookid,
	_registrationarticle,
	_stamparticle,
	_dateofcommunication,
	_stampruleid,
	_currentstatus,
	_indexiisummary,
	_endorsementdocument,
	_courtdocument,
	_olddocumentnumber
) returning requestid into v_requestid;

else

update kaveri.rule17filing set

	--applicationnumber=_applicationnumber,

	communicationnumber = _communicationnumber,
	srocode = _srocode,
	bookid = _bookid,
	registrationarticle =_registrationarticle,
	stamparticle = _stamparticle ,
	dateofcommunication = _dateofcommunication,
	stampruleid = _stampruleid,
	currentstatus = _currentstatus,
	indexiisummary = _indexiisummary,
	endorsementdocument = _endorsementdocument,
	courtdocument = _courtdocument
where applicationnumber =_applicationnumber

returning requestid into v_requestid;

end if;


if( _isdigitalsigned =true) then 
	UPDATE kaveri.documentmaster set 
	isdigitalsigned=_isdigitalsigned,
	uploaddocdeedpath=_courtdocument,
	isfiling = true,
	isregistrationaccepted=true,
	isprintendorsement = true,
	isregistrationcompleted =true,
	uploadsummarydocpath = _endorsementdocument
	where applicationnumber= _applicationnumber;
	--returning applicationnumber into v_appnumber;
	
end if;

return v_requestid;

end;

$$;


