_scheduledesciptiondetailsverified_sr,
_partydetailsremarks_sr,
_partydetailsverified_sr,
_canpreocesstopaymentremarks_sr,
_canpreocesstopaymentverified_sr,
_verificationdatetime_sr,
_propertydetailsremarks_sda,
_propertydetailsverified_sda,
_boundarydetailsremarks_sda,
_boundarydetailsverified_sda,
_scheduledesciptiondetailsremarks_sda,
_scheduledesciptiondetailsverified_sda,
_partydetailsremarks_sda,
_partydetailsverified_sda,
_canpreocesstopaymentremarks_sda,
_canpreocesstopaymentverified_sda,
_verificationdatetime_sda,
_inserteddatetime,
_k1k2_flag ) returning verificationid into v_verificationid ;

else

update
	kaveri.rule17filingremarks
set
