--
-- Name: fn_insert_userapartmentamenitydetails(kaveri.val_userapartmentamenitydetails_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_userapartmentamenitydetails(p_apt_rev kaveri.val_userapartmentamenitydetails_input[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $$
Declare
   v_apartment_arry kaveri.val_userapartmentamenitydetails_input[];
     v_cnt integer;
   v_valid bigint;
   v_pid bigint[];
begin

	if(p_apt_rev is not null and array_length(p_apt_rev,1)>0 ) then
		FOR v_apartment_arry IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_apt_rev)) 
			loop
				v_cnt:= 0;
				Select count(*) into v_cnt from kaveri.val_userapartmentamenitydetails b 
				inner join kaveri.mas_val_apartmentsamenities c 
				on (b.apartmentamenityid = c.amenitiesid)
				where (apartmentamenityid,valuationid) in
						(select a._apartmentamenityid,a._valuationid from unnest(v_apartment_arry) a);
				 if v_cnt = 0 then
				 
                                 insert into kaveri.val_userapartmentamenitydetails
                                 (
    					apartmentamenityid,
    					isselected,
    					valuationid,
    					verified,
    					srocode,
    					regsrocode

                                )
                                   select --null,
                         _apartmentamenityid,
    					_isselected,
    					_valuationid,
    					_verified,
    					_srocode,
    					_regsrocode
					from unnest(v_apartment_arry)	
								 returning valuationid::bigint into v_valid;
					else
                        update kaveri.val_userapartmentamenitydetails set 
    					isselected=a._isselected,
    					verified=a._verified,
    					srocode=a._srocode,
    					regsrocode=a._regsrocode
                        from unnest(v_apartment_arry) a where (valuationid,apartmentamenityid) in 
					(select a._valuationid,a._apartmentamenityid  from unnest(v_apartment_arry ) a) 
					RETURNING valuationid::bigint into v_valid;
                                	end if;
				v_pid := array_append(v_pid,v_valid);
				end loop;
				end if;
				return v_pid;
   END;
$$;


ALTER FUNCTION kaveri.fn_insert_userapartmentamenitydetails(p_apt_rev kaveri.val_userapartmentamenitydetails_input[]) OWNER TO csgadmin;

--
-- Name: fn_insert_val_agriculture(kaveri.agriculturedetails_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_val_agriculture(p_agriculturedetails kaveri.agriculturedetails_input[] DEFAULT NULL::kaveri.agriculturedetails_input[]) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
Declare

v_arry_agriculture kaveri.agriculturedetails_input[];
v_cnt integer;
v_valid bigint;
begin
		if(p_agriculturedetails is not null and array_length(p_agriculturedetails,1)>0 ) then
				FOR v_arry_agriculture IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_agriculturedetails)) 
					loop
						v_cnt:= 0;
						Select count(*) into v_cnt from kaveri.val_agriculturedetails where agriculturedetailsid in 
						(select a._agriculturedetailsid from unnest(v_arry_agriculture) a) ;
						if v_cnt = 0 then
							insert into kaveri.val_agriculturedetails (
								agriculturedetailsid,agrilandtypeid,unitid,valuationid,
								verified,agrirateid,rate,srocode,regsrocode)
								select nextval('kaveri.val_agricultural_details_seq'),
								 a._agrilandtypeid,a._unitid,a._valuationid,--p_valuationid,
								 a._verified,a._agrirateid,a._rate,
								 a._srocode,a._regsrocode
								from unnest(v_arry_agriculture)	a
								 returning valuationid::bigint into v_valid;
						else
							update kaveri.val_agriculturedetails set
												agrilandtypeid = a._agrilandtypeid,
												unitid=a._unitid,
												verified = a._verified,
												agrirateid = a._agrirateid,
												rate=a._rate,
												srocode = a._srocode,
												regsrocode = a._regsrocode
												 from unnest(v_arry_agriculture) a where agriculturedetailsid in 
														 (select a._agriculturedetailsid from unnest(v_arry_agriculture) a) 
														 RETURNING valuationid::bigint into v_valid;
						end if;
						
					end loop;
			end if;
Return v_valid;
   END;
$$;


ALTER FUNCTION kaveri.fn_insert_val_agriculture(p_agriculturedetails kaveri.agriculturedetails_input[]) OWNER TO csgadmin;

