v_cnt integer;
v_valid bigint;
begin
		if(p_annexuredetails is not null and array_length(p_annexuredetails,1)>0 ) then
				FOR v_arry_annexure IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_annexuredetails)) 
					loop
						v_cnt:= 0;
						Select count(*) into v_cnt from kaveri.val_annexuredetails where annexuredetailsid in 
						(select a._annexuredetailsid from unnest(v_arry_annexure) a) ;
						if v_cnt = 0 then
							insert into kaveri.val_annexuredetails (
								annexuredetailsid,annexureid,area,rate,
								valuationid,verified,srocode,regsrocode,isselected)
								select 
								 nextval('kaveri.val_annexuredetails_seq'),a._annexureid,a._area,--p_valuationid,
								 a._rate,a._valuationid,a._verified,
								 a._srocode,a._regsrocode,a._isselected
								from unnest(v_arry_annexure)	a
								 returning valuationid::bigint into v_valid;
						else
							update kaveri.val_annexuredetails set
												--annexuredetailsid = a._annexuredetailsid,
												annexureid=a._annexureid,
												area = a._area,
												rate=a._rate,
												valuationid = a._valuationid,
												verified=a._verified,
												srocode = a._srocode,
												regsrocode=a._regsrocode,
												isselected=a._isselected
												 from unnest(v_arry_annexure) a where annexuredetailsid in 
														 (select a._annexuredetailsid from unnest(v_arry_annexure) a) 
														 RETURNING valuationid::bigint into v_valid;
