--
-- Name: fn_insert_valuation_details(kaveri.valuation_details[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_valuation_details(p_valuationdetails kaveri.valuation_details[] DEFAULT NULL::kaveri.valuation_details[]) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
Declare
v_arry_valuation p_valuationdetails%type;
v_valuationid bigint;
v_cnt integer;
v_valid bigint;
begin
/*select count(*) into v_cnt from kaveri.valuationdetails where valid in 
(select a._valid from unnest(p_valuationdetails) a) ;*/
if(p_valuationdetails is not null and array_length(p_valuationdetails,1)>0 ) then
	FOR v_arry_valuation IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_valuationdetails)) 
		loop
			v_cnt:= 0;
			select count(*) into v_cnt from kaveri.valuationdetails where valid in 
			(select a._valid from unnest(v_arry_valuation) a) ;
			
			if v_cnt = 0 then
			  INSERT INTO kaveri.valuationdetails(
				valid ,
				srocode,
				regsrocode,
				villagecode,
				roadcode,
				valuationdate,
				propertytypeid,
				totalarea,
				unitid,
				marketvalue,
				leasetype,
				leaseamount,
				northboundary,
				southboundary,
				eastboundary,
				westboundary,
				assessment,
				regarticlecode,
				applicationnumber,
				 verified,
				issroapproved,
				propertyid)
				select  nextval('kaveri.valuationdetails_seq'), 
				a._srocode,
				a._regsrocode,
				a._villagecode,
				a._roadcode,
				a._valuationdate,
				a._propertytypeid,
				a._totalarea,
				a._unitid,
				a._marketvalue,
				a._leasetype,
				a._leaseamount,
				a._northboundary,
				a._southboundary,
				a._eastboundary,
				a._westboundary,
				a._assessment,
				a._regarticlecode,
				a._applicationnumber,
				 a._verified,
				a._issroapproved,
				a._propertyid from unnest(v_arry_valuation) a
				 returning valid::bigint into v_valuationid;
			else 
				update kaveri.valuationdetails
				set srocode=a._srocode,
				regsrocode=a._regsrocode,
				villagecode=a._villagecode,
				roadcode=a._roadcode,
				valuationdate=a._valuationdate,
				propertytypeid=a._propertytypeid,
				totalarea=a._totalarea,
				unitid=a._unitid,
				marketvalue=a._marketvalue,
				leasetype=a._leasetype,
				leaseamount=a._leaseamount,
				northboundary=a._northboundary,
				southboundary=a._southboundary,
				eastboundary=a._eastboundary,
				westboundary=a._westboundary,
				assessment=a._assessment,
				regarticlecode=a._regarticlecode,
				applicationnumber=a._applicationnumber,
				verified = a._verified,
				issroapproved=a._issroapproved,
				propertyid=a._propertyid from unnest(v_arry_valuation) a  where valid in 
						 (select a._valid from unnest(v_arry_valuation) a) and srocode in (select b._srocode from unnest(v_arry_valuation) b); 
						 --RETURNING valid::bigint  into v_valuationid;
					select distinct "valid" into v_valuationid from kaveri.valuationdetails v where "valid" in (select _valid from unnest(v_arry_valuation));
						
			end if;	
	   end loop;
end if;
Return v_valuationid;
	--Return v_schid;
   END;
$$;


ALTER FUNCTION kaveri.fn_insert_valuation_details(p_valuationdetails kaveri.valuation_details[]) OWNER TO csgadmin;

--
-- Name: fn_insert_withdrawapplications(bigint, character varying, timestamp without time zone, character varying, character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_withdrawapplications(_id bigint, _applicationnumber character varying, _withdrawndate timestamp without time zone, _remarks character varying, _withdrawdocumentpath character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare
v_id bigint;
begin 
select count(*) into v_id from kaveri.Withdrawapplications where id = _id;
if v_id = 0 then
insert into kaveri.Withdrawapplications (
applicationnumber,
withdrawndate,
remarks,
withdrawdocumentpath
) values 
(
_applicationnumber,
_withdrawndate,
_remarks,
_withdrawdocumentpath
) returning id into v_id;
else 
update kaveri.Withdrawapplications 
set withdrawndate=_withdrawndate,
remarks=_remarks,withdrawdocumentpath=_withdrawdocumentpath
where id = _id returning id into v_id;
end if;
return v_id;
end;
$$;


ALTER FUNCTION kaveri.fn_insert_withdrawapplications(_id bigint, _applicationnumber character varying, _withdrawndate timestamp without time zone, _remarks character varying, _withdrawdocumentpath character varying) OWNER TO csgadmin;

--
-- Name: fn_insert_witness_info_chk(kaveri.witnessinfo1_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_witness_info_chk(p_witnessdetails kaveri.witnessinfo1_input[] DEFAULT NULL::kaveri.witnessinfo1_input[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $_$
DECLARE
	id_val bigint;
    --inserted_id integer;
	cit_id text;
   --property_arry $1%type;
   v_arr_witnessinfo p_witnessdetails%type;
   p_arr_partywitnessdetails kaveri.party_witness_input[];
   v_arr_partywitnessdetails kaveri.party_witness_input[];
   v_witnessid bigint;
   vs_witnessid bigint;
   var_r record;
   v_pid bigint[];
v_cnt integer;
v_cnt1 integer;
v_srocode bigint;
v_partyid bigint;
begin
/*Select count(*) into v_cnt from kaveri.witnessinfo where witnessid in 
(select a._witnessid from unnest($1) a) ;*/
if(p_witnessdetails  is not null and array_length(p_witnessdetails,1)>0 ) then
FOR v_arr_witnessinfo  IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_witnessdetails))
loop
v_cnt:= 0;
v_witnessid:=0;
Select count(*) into v_cnt from kaveri.witnessinfo where witnessid in 
(select a.witnessid from unnest(v_arr_witnessinfo) a) ;
if v_cnt = 0 then
INSERT INTO kaveri.witnessinfo( witnessid,
    documentid,
    name,
    address,
    sex,
    age,
    profession,
    registrationid,
    dateofbirth,
    status,
    phoneno,
    relation,
    mothername,
    fathersname,
    presentatsolemanization,
	srocode,
    isonline,
	applicationnumber,
	verified,
	issroapproved,
	statecode,
    districtcode,
    talukcode,
    hoblicode,
    villagecode,
    relativename,
    pincode,
    middlename,
    lastname,
    houseno,
    iscliment,
    isexicutent)
    select  
	nextval('kaveri.witnessinfo_witnessid_seq'),
    documentid,
    name,
    address,
    sex,
    age,
    profession,
    registrationid,
    dateofbirth,
    status,
    phoneno,
    relation,
    mothername,
    fathersname,
    presentatsolemanization,
	srocode,
    isonline,
	applicationnumber,
	verified,
	issroapproved,
	statecode,
    districtcode,
    talukcode,
    hoblicode,
    villagecode,
    relativename,
    pincode,
    middlename,
    lastname,
    houseno,
    iscliment,
    isexicutent
	from unnest(v_arr_witnessinfo)	
	 returning witnessid::bigint into v_witnessid;
	 else
	 update kaveri.witnessinfo set
	  documentid= a.documentid,
    name=a.name,
    address=a.address,
    sex=a.sex,
    age=a.age,
    profession=a.profession,
    registrationid=a.registrationid,
    dateofbirth=a.dateofbirth,
    status=a.status,
    phoneno=a.phoneno,
    relation=a.relation,
    mothername=a.mothername,
    fathersname=a.fathersname,
    presentatsolemanization=a.presentatsolemanization,
	--srocode=a.srocode,
    isonline=a.isonline,
	applicationnumber=a.applicationnumber,
	verified=a.verified,
	issroapproved=a.issroapproved,
	statecode=a.statecode,
    districtcode=a.districtcode,
    talukcode=a.talukcode,
    hoblicode=a.hoblicode,
    villagecode=a.villagecode,
    relativename=a.relativename,
    pincode=a.pincode,
    middlename=a.middlename,
    lastname=a.lastname,
    houseno=a.houseno,
    iscliment=a.iscliment,
    isexicutent=a.isexicutent
	from unnest(v_arr_witnessinfo) a  where a.witnessid in 
			 (select b.witnessid from unnest(v_arr_witnessinfo) b);
			 --RETURNING a.witnessid::bigint into v_witnessid;
			 select c.witnessid into v_witnessid from unnest(v_arr_witnessinfo) c limit 1;
	end if;
      
        if(v_witnessid is not null) then  /* To check whether the witnessid returned from witnessinfo is null or not null */
       /* select a._partywitness into p_arr_partywitnessdetails from unnest(v_arr_witnessinfo) a;*/
		 --if(v_witnessid is not null) then
		--if(p_arr_partywitnessdetails  is not null and array_length(p_witnessdetails,1)>0 ) then
			  delete from kaveri.partywitness where witnessid= v_witnessid;
		select a.partywitness into p_arr_partywitnessdetails from unnest(v_arr_witnessinfo) a;
			FOR v_arr_partywitnessdetails IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_arr_partywitnessdetails))
				loop
	
          select srocode into v_srocode from kaveri.witnessinfo where witnessid = v_witnessid;	

        INSERT INTO kaveri.partywitness( partyid,witnessid,witnessdate, srocode)
	select partyid,v_witnessid,witnessdate,v_srocode 
	from  unnest(v_arr_partywitnessdetails)	
	 returning witnessid::bigint into v_witnessid;
		v_pid := array_append(v_pid,v_witnessid);
        end loop;
        end if;
	v_pid := array_append(v_pid,v_witnessid);
	end loop;
	end if;
Return v_pid;
end;
$_$;


ALTER FUNCTION kaveri.fn_insert_witness_info_chk(p_witnessdetails kaveri.witnessinfo1_input[]) OWNER TO csgadmin;

--
-- Name: fn_insert_witness_info_mrg_chk(kaveri.marriagewitnessinfo_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_insert_witness_info_mrg_chk(p_witnessdetails kaveri.marriagewitnessinfo_input[] DEFAULT NULL::kaveri.marriagewitnessinfo_input[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $_$


DECLARE
DECLARE
   id_val bigint;
    --inserted_id integer;
   cit_id text;
   --property_arry $1%type;
   v_arr_witnessinfo p_witnessdetails%type;
   --p_arr_partywitnessdetails kaveri.marriagepartywitness_input[];
   --v_arr_partywitnessdetails kaveri.marriagepartywitness_input[];
   v_witnessid bigint;
   var_r record;
   v_pid bigint[];
   v_cnt integer;
   v_cnt1 integer;
   v_srocode integer;
   v_partyid bigint;
begin
if(p_witnessdetails  is not null and array_length(p_witnessdetails,1)>0 ) then
FOR v_arr_witnessinfo  IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_witnessdetails))
loop
v_cnt:= 0;
v_witnessid:=0;
Select count(*) into v_cnt from kaveri.marriagewitnessinfo where witnessid in 
(select a._witnessid from unnest(v_arr_witnessinfo) a) ;
if v_cnt = 0 then
insert into kaveri.marriagewitnessinfo
(   witnessid,
    --isallwitnesspresent,
    digisignpath,
--    srocode,
 --   documentid,
    registrationid,
    salutation,
    applicationnumber,
    firstname,
    middlename,
    lastname,
    dob,
    age,
    genderid,
	email,
    phoneno,
    perhouseno,
    perstreetaddress,
    perstatecode,
    perdistrictcode,
    pertalukacode,
    perhoblicode,
    pervillagecode,
    perpincode,
    iscurrentaddresssameaspermanent,
    currenthouseno,
    currentstreetaddress,
    currrentstatecode,
    currentdistrictcode,
    currenttalukacode,
    currenthoblicode,
    currentvillagecode,
    currentpincode,
    witnessrelatedto,
    relationid,
    status,
    verified,
    isapproved)
--	marriagetypeid,
--	marriagemodeid)
    select  
	nextval('kaveri.marriagewitnessinfo_witnessid_seq'),
	--_isallwitnesspresent,
	_digisignpath,
--    _srocode,
--    _documentid,
    _registrationid,
    _salutationid,
    _applicationnumber,
    _firstname,
    _middlename,
    _lastname,
	_dob,
    _age,
    _genderid,
	_email,
	_phoneno,
    _perhouseno,
    _perstreetaddress,
    _perstatecode,
    _perdistrictcode,
	_pertalukacode,
    _perhoblicode,
    _pervillagecode,
    _perpincode,
    _iscurrentaddresssameaspermanent,
	_currenthouseno,
    _currentstreetaddress,
    _currrentstatecode,
    _currentdistrictcode,
	_currenttalukacode,
    _currenthoblicode,
    _currentvillagecode,
    _currentpincode,
    _witnessrelatedto,
    _relationid,
    _status,
    _verified,
    _isapproved
	--_marriagetypeid,
	--_marriagemodeid
	from unnest(v_arr_witnessinfo)
	 returning witnessid::bigint into v_witnessid;
	 
	 update kaveri.marriageregistration set witnessid_1 = coalesce(witnessid_1,v_witnessid),
	 witnessid_2 = (case when witnessid_1 is not null then
	                coalesce(witnessid_2,v_witnessid) else null end), 
	 witnessid_3 = (case when  witnessid_1 is not null and witnessid_2 is not null
					then coalesce(witnessid_3,v_witnessid) else null end),currentstatus='MR104' 
					where applicationnumber in 
			 (select a._applicationnumber from unnest(v_arr_witnessinfo) a);
	 update kaveri.ApplicantApplicationdetails set currentstatus='MR104' 
	 where applicationnumber in 
	(select a._applicationnumber from unnest(v_arr_witnessinfo) a);			
			 
    else 
      update kaveri.marriagewitnessinfo set 
      --isallwitnesspresent=_isallwitnesspresent,
      digisignpath=_digisignpath,
      registrationid=_registrationid,
	  salutation=_salutationid,
	  firstname=_firstname,
	  middlename=_middlename,
      lastname=_lastname,
	  dob=_dob,
      age=_age,
      genderid=_genderid,
	  email=_email,
	  phoneno=_phoneno,
      perhouseno=_perhouseno,
      perstreetaddress=_perstreetaddress,
      perstatecode=_perstatecode,
      perdistrictcode=_perdistrictcode,
	  pertalukacode=_pertalukacode,
      perhoblicode=_perhoblicode,
      pervillagecode=_pervillagecode,
      perpincode=_perpincode,
      iscurrentaddresssameaspermanent=_iscurrentaddresssameaspermanent,
      currenthouseno=_currenthouseno,
      currentstreetaddress=_currentstreetaddress,
      currrentstatecode=_currrentstatecode,
      currentdistrictcode=_currentdistrictcode,
	  currenttalukacode=_currenttalukacode,
      currenthoblicode=_currenthoblicode,
      currentvillagecode= _currentvillagecode,
      currentpincode=_currentpincode,
      witnessrelatedto=_witnessrelatedto,
      relationid=_relationid,
      status=_status,
      verified=_verified,
      isapproved=_isapproved
	--marriagemodeid=_marriagemodeid,
	--marriagetypeid = _marriagetypeid
    	from unnest(v_arr_witnessinfo) a  where witnessid in 
			 (select a._witnessid from unnest(v_arr_witnessinfo) a) 
			 RETURNING witnessid::bigint into v_witnessid;
	end if;
	v_pid := array_append(v_pid,v_witnessid);
	end loop;
	end if;
Return v_pid;
end;
$_$;


ALTER FUNCTION kaveri.fn_insert_witness_info_mrg_chk(p_witnessdetails kaveri.marriagewitnessinfo_input[]) OWNER TO csgadmin;

