		--if(p_arr_partywitnessdetails  is not null and array_length(p_witnessdetails,1)>0 ) then
			  delete from kaveri.partywitness where witnessid= v_witnessid;
		select a.partywitness into p_arr_partywitnessdetails from unnest(v_arr_witnessinfo) a;
			FOR v_arr_partywitnessdetails IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_arr_partywitnessdetails))
				loop
	
          select srocode into v_srocode from kaveri.witnessinfo where witnessid = v_witnessid;	

        INSERT INTO kaveri.partywitness( partyid,witnessid,witnessdate, srocode)
	select partyid,v_witnessid,witnessdate,v_srocode 
	from  unnest(v_arr_partywitnessdetails)	
	 returning witnessid::bigint into v_witnessid;
		v_pid := array_append(v_pid,v_witnessid);
        end loop;
        end if;
	v_pid := array_append(v_pid,v_witnessid);
	end loop;
	end if;
Return v_pid;
end;
$_$;


