--

CREATE FUNCTION kaveri.fn_reject_fruits_filing(_applicationnumber character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_referenceno varchar;
BEGIN  
update kaveri.documentmaster set currentstatus = 'CD134'
where applicationnumber= _applicationnumber;

update kaveri.fruits_data_recv_details set applicationstatus = 4
where applicationnumber= _applicationnumber returning referenceno into v_referenceno;
return v_referenceno;
END;
$$;


ALTER FUNCTION kaveri.fn_reject_fruits_filing(_applicationnumber character varying) OWNER TO csgadmin;

--
-- Name: fn_revert_application_sro(); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_revert_application_sro() RETURNS TABLE(applicationnumber_to_revert character varying[], applicationnumber_reverted character varying[])
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY 
    WITH AuditHistory AS (
        SELECT 
            applicantapp.applicationnumber,
            a2.wrkflowstatusid,
            a2.crtdt,
            applicantapp.applicationtypeid,
			applicantapp.lastupdatedby,
            ROW_NUMBER() OVER (PARTITION BY a2.applicationnumber ORDER BY a2.activityorder DESC) as rnk
        FROM ( 
                SELECT applicationnumber, currentstatus, applicationtypeid, lastupdatedby 
                FROM kaveri.applicantapplicationdetails 
                WHERE currentstatus IN ('CD103')
            ) AS applicantapp
        LEFT JOIN kaveri.applicationaudit a2 USING(applicationnumber)
    ),
    Analysis AS (
        SELECT 
            curr.applicationnumber,
			curr.lastupdatedby,
            prev.wrkflowstatusid as revert_to_status,
            (prev.wrkflowstatusid NOT IN ('CD103')) as is_eligible
        FROM AuditHistory curr
        JOIN AuditHistory prev ON curr.applicationnumber = prev.applicationnumber AND prev.rnk = 2
        WHERE curr.rnk = 1
          AND curr.applicationtypeid = 1
          AND curr.crtdt < NOW() - INTERVAL '24 hours'
          AND curr.crtdt > NOW() - INTERVAL '48 hours'
    ),
    UpdatedApps AS (
        UPDATE kaveri.applicantapplicationdetails a
        SET currentstatus = t.revert_to_status,
			assignedto = t.lastupdatedby,
            lastupdatedby = 'RevertToSroScheduler'
        FROM Analysis t
        WHERE a.applicationnumber = t.applicationnumber
          AND t.is_eligible = TRUE
        RETURNING a.applicationnumber
    )
    SELECT 
        (SELECT COALESCE(array_agg(applicationnumber), '{}') FROM Analysis WHERE is_eligible = FALSE),
        (SELECT COALESCE(array_agg(applicationnumber), '{}') FROM UpdatedApps);
END;
$$;


ALTER FUNCTION kaveri.fn_revert_application_sro() OWNER TO postgres;

--
-- Name: fn_save_book1_part3_details(integer, integer, integer, integer, timestamp without time zone, character varying, character varying, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_save_book1_part3_details(_citizen_id integer, _application_type_id integer, _sro_id integer, _deo_id integer, _date_on_certificate timestamp without time zone, _issuing_authority character varying, _current_status character varying, _last_updated_by integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    _application_no VARCHAR;
    _book_id INT := 7;
BEGIN
    -- Fetch Application Number
    SELECT kaveri.fn_insert_into_applicantapplicationdetails(_citizen_id, _application_type_id) 
    INTO _application_no;
    
    IF _application_no IS NULL THEN
        RETURN NULL;
    END IF;

    -- Update SRO Code in applicantapplicationdetails
    UPDATE kaveri.applicantapplicationdetails
    SET srocode = _sro_id, regsrocode = _sro_id, bookid = _book_id
    WHERE applicationnumber = _application_no;

    -- Update Application Status
    PERFORM kaveri.fn_upd_application_status(
        p_applicationnumber => _application_no,
        p_currentstatus => _current_status,
        p_lastupdatedby => _last_updated_by::TEXT,
        p_sfdaid => NULL,
        p_deoid => _deo_id
    );

    -- Insert into Book1Part3 Court Table
    INSERT INTO kaveri.book1_part3_court (certificatesaledate, issuingauthority, applicationnumber)
    VALUES (_date_on_certificate, _issuing_authority, _application_no);

    RETURN _application_no;
END;
$$;


ALTER FUNCTION kaveri.fn_save_book1_part3_details(_citizen_id integer, _application_type_id integer, _sro_id integer, _deo_id integer, _date_on_certificate timestamp without time zone, _issuing_authority character varying, _current_status character varying, _last_updated_by integer) OWNER TO postgres;

--
-- Name: fn_save_docdeeddownloadlink(character varying, character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_save_docdeeddownloadlink(_linkid character varying, _applicationnumber character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $$

declare
v_uploaddocdeedpath text;
v_check bool default false;

begin
	select uploaddocdeedpath into v_uploaddocdeedpath from kaveri.documentmaster where applicationnumber = _applicationnumber;
	
	if (v_uploaddocdeedpath is not null 
		and not exists
		(select 1 from kaveri.docdeeddownloadlink where linkid = _linkid and applicationnumber = _applicationnumber and isactive = true)
		and exists(select 1 from kaveri.applicantapplicationdetails where applicationnumber = _applicationnumber ))then
			
			insert into kaveri.docdeeddownloadlink(linkid,applicationnumber)
			values(_linkid,_applicationnumber) returning true into v_check;

	end if;
	return v_check;
end;
$$;


ALTER FUNCTION kaveri.fn_save_docdeeddownloadlink(_linkid character varying, _applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_save_docesign(character varying, text); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_save_docesign(_doc_guid character varying, _esign_data text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_cnt int;
   v_doc_guid text;
BEGIN
   select count(1) into v_cnt from kaveri.document_esign where doc_guid = _doc_guid;
   if (coalesce(v_cnt,0) > 0 ) then
    update kaveri.document_esign set esign_data = _esign_data where doc_guid = _doc_guid 
		 returning  doc_guid into v_doc_guid;	 
	else
		 INSERT INTO kaveri.document_esign (doc_guid,esign_data,docdate)
	  values (_doc_guid,_esign_data,current_timestamp)	returning  doc_guid into v_doc_guid;
	 end if;
   return v_doc_guid;
END;
$$;


ALTER FUNCTION kaveri.fn_save_docesign(_doc_guid character varying, _esign_data text) OWNER TO csgadmin;

--
-- Name: fn_save_documentmaster(bigint, character varying, boolean, boolean, text, boolean, text, text, boolean, boolean, boolean, character varying, character varying, text, text, integer[], timestamp without time zone, character varying, boolean, boolean, boolean, boolean); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_save_documentmaster(_documentid bigint, _applicationnumber character varying, _isregistrationaccepted boolean DEFAULT NULL::boolean, _isuploadprintsummary boolean DEFAULT NULL::boolean, _uploadsummarydocpath text DEFAULT NULL::text, _isprintendorsement boolean DEFAULT NULL::boolean, _uploadregistereddocpath text DEFAULT NULL::text, _uploadannexuredocpath text DEFAULT NULL::text, _isuploaddocuments boolean DEFAULT NULL::boolean, _isdigitalsigned boolean DEFAULT NULL::boolean, _isregistrationcompleted boolean DEFAULT NULL::boolean, _currentstatus character varying DEFAULT NULL::character varying, _lastupdatedby character varying DEFAULT NULL::character varying, _remarks text DEFAULT NULL::text, _remarksk text DEFAULT NULL::text, p_wintess integer[] DEFAULT NULL::integer[], _ackdatetime timestamp without time zone DEFAULT NULL::timestamp without time zone, _ackuser character varying DEFAULT NULL::character varying, _isphotothumbtransmitted boolean DEFAULT NULL::boolean, _isprintsummary boolean DEFAULT NULL::boolean, _isbiometricrefused boolean DEFAULT false, _iscitizennotappiared boolean DEFAULT false) RETURNS text
    LANGUAGE plpgsql
    AS $$


Declare
v_appnumber text;
v_finalregnum text;
v_srocode bigint;
v_valid bigint;
_cnt integer;
v_fruits_appl integer;
v_isdigitalsigned boolean;
v_isbefore2003 bool;
begin

select count(*) into v_fruits_appl from kaveri.fruits_data_recv_details fdrd where fdrd.applicationnumber = _applicationnumber; 
	
if(_currentstatus is not null and _currentstatus <> '' and _lastupdatedby is not null and _lastupdatedby<> '') then 
select kaveri.fn_upd_application_status(p_applicationnumber=>_applicationnumber,
										p_currentstatus=>_currentstatus,
										p_lastupdatedby=>_lastupdatedby,
									   p_remarks=>_remarks,
									   p_remarksk=>_remarksk   --- To update the Kannada text added on 28-11-2022
									   ) into v_appnumber;
end if;

/*To handle refusal remarks */
if ((_remarks is not null or _remarks <> '') and (_remarksk is not null or _remarksk <> ''))then
	update kaveri.applicantapplicationdetails set remarks =_remarks, remarksk = _remarksk where applicationnumber =_applicationnumber;
end if;

/*select isdigitalsigned into v_isdigitalsigned from kaveri.documentmaster
where documentid = _documentid and 
	applicationnumber= _applicationnumber;
*/
--if (v_isdigitalsigned is null) or (v_isdigitalsigned is not null and v_isdigitalsigned =true or v_isdigitalsigned =false)  then 
--if(v_isdigitalsigned is not null and v_isdigitalsigned =true)  then 
if( _isdigitalsigned =true) then 
	UPDATE kaveri.documentmaster set 
	isdigitalsigned=_isdigitalsigned,
	uploaddocdeedpath=_uploadregistereddocpath
	where documentid = _documentid and 
	applicationnumber= _applicationnumber;
	--returning applicationnumber into v_appnumber;
	
end if;

if(_isregistrationaccepted is not null) then 
	UPDATE kaveri.documentmaster set 
	isregistrationaccepted=_isregistrationaccepted
	where documentid = _documentid and 
	applicationnumber= _applicationnumber
	returning applicationnumber,srocode into v_appnumber,v_srocode;
	select kaveri.fn_fetch_pending_regnumber(v_srocode::integer,v_appnumber::character varying) into v_appnumber;
	
end if;

if(_isuploadprintsummary is not null) then 
	UPDATE kaveri.documentmaster set 
	isprintsummary=_isuploadprintsummary,
	uploadsummarydocpath = _uploadsummarydocpath
	where documentid = _documentid and 
	applicationnumber= _applicationnumber
	returning applicationnumber into v_appnumber;	
	
end if;

if(_isprintendorsement is not null) then
	UPDATE kaveri.documentmaster set 
	isprintendorsement=_isprintendorsement
	where documentid = _documentid and 
	applicationnumber= _applicationnumber
	returning applicationnumber,srocode into v_appnumber,v_srocode;
	 
	
	if(_currentstatus = 'CD112') THEN
		select kaveri.fn_update_final_regnumber(v_srocode::integer,v_appnumber::character varying) into v_finalregnum;
	end if;
	
	
	if(_isprintendorsement = true) then
	update kaveri.partyinfo set isEndorsePrinted= 'true' where documentid = _documentid and 
	applicationnumber= _applicationnumber and ((thumbpath is not null and photopath is not null 
	and thumbpath <> '' and photopath <> '' )or(section88exemption =true));
	
--	update kaveri.partyinfo set isEndorsePrinted= 'true' where documentid = _documentid and 
--    applicationnumber= _applicationnumber and section88exemption =true;
--	
		if(p_wintess is not null and array_length(p_wintess,1) > 0) then
			update kaveri.witnessinfo set isEndorsePrinted= 'true'
			where witnessid in (select * from unnest(p_wintess::int[]));
		end if;
	end if;	
end if;

if (_isuploaddocuments is not null) then -- and _isuploaddocuments= true 
	UPDATE kaveri.documentmaster set 
	isuploaddocuments=_isuploaddocuments,
	uploaddocdeedpath = _uploadregistereddocpath,
	uploaddocannexurepath = _uploadannexuredocpath,
	uploaddocdatetime = CURRENT_TIMEstamp
	where documentid = _documentid and 
	applicationnumber= _applicationnumber
	returning applicationnumber into v_appnumber;	
end if;

/*if(_isdigitalsigned is not null and _isdigitalsigned ='True') then 
--if( _isdigitalsigned =true::boolean) then 
	UPDATE kaveri.documentmaster set 
	isdigitalsigned=_isdigitalsigned::boolean,
	uploaddocdeedpath=_uploadregistereddocpath
	where documentid = _documentid and 
	applicationnumber= _applicationnumber;
	--returning applicationnumber into v_appnumber;
	
end if;*/

if(_isregistrationcompleted is not null and _isregistrationcompleted =true) then 
	UPDATE kaveri.documentmaster set 
	isregistrationcompleted=_isregistrationcompleted
	where documentid = _documentid and 
	applicationnumber= _applicationnumber;
--	returning applicationnumber into v_appnumber;
--	return v_appnumber;
end if;
/* Added logic to update isscancompleted as true for CD115 - Pending for Digital Signature   as on 13/10/2022 */
		
	--if(_currentstatus = 'CD115') THEN /* commented and added code to update is uploaddocument = False */
	
	--commented the because we are hadling above 08-05-2024
	 --if(_currentstatus = 'CD112' and  _isuploaddocuments=False) THEN
	--update kaveri.documentmaster set isscancompleted = True,
	--isuploaddocuments=_isuploaddocuments
	--where documentid = _documentid and 
	--applicationnumber= _applicationnumber;
--	returning applicationnumber into v_appnumber;
--	return v_appnumber;
	--end if;
	
	/*If this is a refusal then set the bookid to 2*/ 
	if(_currentstatus = 'CD134') THEN
		update kaveri.documentmaster set bookid = 2, isrefused=true, refusaldate=current_timestamp  
		where documentid = _documentid and 
		applicationnumber= _applicationnumber;
--		returning applicationnumber into v_appnumber;
--		return v_appnumber;			
		-- Updating ApplicationStatus in FruitsTbl, if FRUITS application
		if(v_fruits_appl > 0) then
			update kaveri.fruits_data_recv_details set applicationstatus = 4
			where applicationnumber= _applicationnumber;	
		end if;
	end if;
	
	/*Acknowledgement Datetime and user is saved*/
	if(_currentstatus = 'CD120') THEN
		update kaveri.documentmaster set ackdatetime = current_timestamp, ackuser=_lastupdatedby  
		where documentid = _documentid and 		
		applicationnumber= _applicationnumber;
	--	returning applicationnumber into v_appnumber;
	--	return v_appnumber;
		-- Updating ApplicationStatus in FruitsTbl, if FRUITS application
		if(v_fruits_appl > 0) then
			update kaveri.fruits_data_recv_details set applicationstatus = 2
			where applicationnumber= _applicationnumber;	
		end if;
	end if;

	if(_ackdatetime is not null) then 
	UPDATE kaveri.documentmaster set 
	-- ackdatetime=_ackdatetime   -- Commented as part of Pilot-Production fix
	ackdatetime = current_timestamp 
	where documentid = _documentid and 
	applicationnumber= _applicationnumber;
--	returning applicationnumber into v_appnumber;
--	return v_appnumber;
	end if;

	if(_ackuser is not null) then 
	UPDATE kaveri.documentmaster set 
	ackuser=_ackuser
	where documentid = _documentid and 
	applicationnumber= _applicationnumber;
--	returning applicationnumber into v_appnumber;
--	return v_appnumber;
	end if;

	-- Uncommenting to handle FRUITS application withdrawal
	if(_currentstatus in ('CD135', 'CD136')) THEN
		/*update kaveri.documentmaster set withdrawdocument=_withdrawdocument
		where documentid = _documentid and 
		applicationnumber= _applicationnumber;*/
--		returning applicationnumber into v_appnumber;
--		return v_appnumber;	
		-- Updating ApplicationStatus in FruitsTbl, if FRUITS application
		if(v_fruits_appl > 0) then
			update kaveri.fruits_data_recv_details set applicationstatus = 3
			where applicationnumber= _applicationnumber;
		end if;
	end if;
    v_appnumber:=_applicationnumber;
	/*if(_currentstatus = 'CD119') THEN
	update kaveri.documentmaster set isundervaluation = _isundervaluation
	where documentid = _documentid and 
	applicationnumber= _applicationnumber;
end if;*/
   
   if(_isphotothumbtransmitted = true) then
   update kaveri.documentmaster set isphotothumbtransmitted = true where applicationnumber= _applicationnumber;
   elseif(_isphotothumbtransmitted = false) then
	update kaveri.documentmaster set isphotothumbtransmitted = false where applicationnumber= _applicationnumber;
   end if;
   
   if(_isprintsummary = true) then
   update kaveri.documentmaster set isprintsummary = true where applicationnumber= _applicationnumber;
   end if;
  
  select isbefore2003 into v_isbefore2003 from kaveri.minutebook_data where applicationnumber=_applicationnumber;
  
    if(_isprintendorsement = true and v_isbefore2003=true) then
    update kaveri.partyinfo set isEndorsePrinted= true where documentid = _documentid and 
    applicationnumber= _applicationnumber;
    end if;
   
   if(_isbiometricrefused = true) then
   update kaveri.partyinfo set isbiometricrefused = true where applicationnumber= _applicationnumber;
   end if;
   
   
    if(_iscitizennotappiared = true) then
   update kaveri.partyinfo set iscitizennotappeared = true where applicationnumber= _applicationnumber;
   end if;

return v_appnumber;
   END;
$$;


