	update kaveri.documentmaster set isundervaluation = _isundervaluation
	where documentid = _documentid and 
	applicationnumber= _applicationnumber;
end if;*/

return v_appnumber;
   END;
$$;


ALTER FUNCTION kaveri.fn_save_documentmaster_bb(_documentid bigint, _applicationnumber character varying, _isregistrationaccepted boolean, _isuploadprintsummary boolean, _uploadsummarydocpath text, _isprintendorsement boolean, _uploadregistereddocpath text, _uploadannexuredocpath text, _isuploaddocuments boolean, _isdigitalsigned boolean, _isregistrationcompleted boolean, _currentstatus character varying, _lastupdatedby character varying, _remarks text, _remarksk text, p_wintess integer[], _ackdatetime timestamp without time zone, _ackuser character varying) OWNER TO csgadmin;

--
-- Name: fn_save_documentmaster_new(bigint, character varying, boolean, boolean, text, boolean, text, text, boolean, boolean, boolean, character varying, character varying, text, text, integer[], character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_save_documentmaster_new(_documentid bigint, _applicationnumber character varying, _isregistrationaccepted boolean DEFAULT NULL::boolean, _isuploadprintsummary boolean DEFAULT NULL::boolean, _uploadsummarydocpath text DEFAULT NULL::text, _isprintendorsement boolean DEFAULT NULL::boolean, _uploadregistereddocpath text DEFAULT NULL::text, _uploadannexuredocpath text DEFAULT NULL::text, _isuploaddocuments boolean DEFAULT NULL::boolean, _isdigitalsigned boolean DEFAULT NULL::boolean, _isregistrationcompleted boolean DEFAULT NULL::boolean, _currentstatus character varying DEFAULT NULL::character varying, _lastupdatedby character varying DEFAULT NULL::character varying, _remarks text DEFAULT NULL::text, _remarksk text DEFAULT NULL::text, p_wintess integer[] DEFAULT NULL::integer[], _withdrawdocument character varying DEFAULT NULL::character varying) RETURNS text
    LANGUAGE plpgsql
    AS $$

Declare
v_appnumber text;
v_finalregnum text;
v_srocode bigint;
v_valid bigint;
_cnt integer;
begin

if(_currentstatus is not null and _currentstatus <> '' and _lastupdatedby is not null and _lastupdatedby<> '') then 
select kaveri.fn_upd_application_status(p_applicationnumber=>_applicationnumber,
										p_currentstatus=>_currentstatus,
										p_lastupdatedby=>_lastupdatedby,
									   p_remarks=>_remarks,
									   p_remarksk=>_remarksk   --- To update the Kannada text added on 28-11-2022
									   ) into v_appnumber;
end if;

if(_isregistrationaccepted is not null) then 
	UPDATE kaveri.documentmaster set 
	isregistrationaccepted=_isregistrationaccepted
	where documentid = _documentid and 
	applicationnumber= _applicationnumber
	returning applicationnumber,srocode into v_appnumber,v_srocode;
	select kaveri.fn_fetch_pending_regnumber(v_srocode::integer,v_appnumber::character varying) into v_appnumber;
	
end if;

if(_isuploadprintsummary is not null) then 
	UPDATE kaveri.documentmaster set 
	isprintsummary=_isuploadprintsummary,
	uploadsummarydocpath = _uploadsummarydocpath
	where documentid = _documentid and 
	applicationnumber= _applicationnumber
	returning applicationnumber into v_appnumber;	
	
end if;

if(_isprintendorsement is not null) then 
	UPDATE kaveri.documentmaster set 
	isprintendorsement=_isprintendorsement
	where documentid = _documentid and 
	applicationnumber= _applicationnumber
	returning applicationnumber,srocode into v_appnumber,v_srocode;
	
	if(_currentstatus = 'CD112') THEN
		select kaveri.fn_update_final_regnumber(v_srocode::integer,v_appnumber::character varying) into v_finalregnum;
	end if;
	
	
	if(_isprintendorsement = true) then
	update kaveri.partyinfo set isEndorsePrinted= 'true' where documentid = _documentid and 
	applicationnumber= _applicationnumber and thumbpath is not null and photopath is not null 
	and thumbpath <> '' and photopath <> '';
		if(p_wintess is not null and array_length(p_wintess,1) > 0) then
			update kaveri.witnessinfo set isEndorsePrinted= 'true'
			where witnessid in (select * from unnest(p_wintess::int[]));
		end if;
	end if;	
end if;

if (_isuploaddocuments is not null and _isuploaddocuments= true) then
	UPDATE kaveri.documentmaster set 
	isuploaddocuments=_isuploaddocuments,
	uploaddocdeedpath = _uploadregistereddocpath,
	uploaddocannexurepath = _uploadannexuredocpath,
	uploaddocdatetime = CURRENT_TIMEstamp
	where documentid = _documentid and 
	applicationnumber= _applicationnumber
	returning applicationnumber into v_appnumber;	
end if;

if(_isdigitalsigned is not null and _isdigitalsigned =true) then 
	UPDATE kaveri.documentmaster set 
	isdigitalsigned=_isdigitalsigned,
	uploaddocdeedpath=_uploadregistereddocpath
	where documentid = _documentid and 
	applicationnumber= _applicationnumber
	returning applicationnumber into v_appnumber;
	
end if;

if(_isregistrationcompleted is not null and _isregistrationcompleted =true) then 
	UPDATE kaveri.documentmaster set 
	isregistrationcompleted=_isregistrationcompleted
	where documentid = _documentid and 
	applicationnumber= _applicationnumber
	returning applicationnumber into v_appnumber;
	return v_appnumber;
end if;
/* Added logic to update isscancompleted as true for CD115 - Pending for Digital Signature   as on 13/10/2022 */
	if(_currentstatus = 'CD115') THEN
	update kaveri.documentmaster set isscancompleted = True  
	where documentid = _documentid and 
	applicationnumber= _applicationnumber;
	end if;
	
	/*If this is a refusal then set the bookid to 2*/ 
	if(_currentstatus = 'CD134') THEN
	update kaveri.documentmaster set bookid = 2, isrefused=true, refusaldate=current_timestamp  
	where documentid = _documentid and 
	applicationnumber= _applicationnumber;
	end if;

	if(_currentstatus = 'CD135') THEN
	update kaveri.documentmaster set withdrawdocument=_withdrawdocument
	where documentid = _documentid and 
	applicationnumber= _applicationnumber;
	end if;

	/*if(_currentstatus = 'CD119') THEN
	update kaveri.documentmaster set isundervaluation = _isundervaluation
	where documentid = _documentid and 
	applicationnumber= _applicationnumber;
end if;*/

return v_appnumber;
   END;
$$;


ALTER FUNCTION kaveri.fn_save_documentmaster_new(_documentid bigint, _applicationnumber character varying, _isregistrationaccepted boolean, _isuploadprintsummary boolean, _uploadsummarydocpath text, _isprintendorsement boolean, _uploadregistereddocpath text, _uploadannexuredocpath text, _isuploaddocuments boolean, _isdigitalsigned boolean, _isregistrationcompleted boolean, _currentstatus character varying, _lastupdatedby character varying, _remarks text, _remarksk text, p_wintess integer[], _withdrawdocument character varying) OWNER TO csgadmin;

--
-- Name: fn_save_enablepaperlesstrans(integer, kaveri.enablepaperlesstrans_input[]); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_save_enablepaperlesstrans(_districtcode integer, p_paperless kaveri.enablepaperlesstrans_input[] DEFAULT NULL::kaveri.enablepaperlesstrans_input[]) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
Declare
v_arry_paperless kaveri.enablepaperlesstrans_input[];
v_cnt integer;
v_success bool;
begin
	if(p_paperless is not null and array_length(p_paperless,1)>0 ) then
		FOR v_arry_paperless IN (SELECT kaveri.fn_fetch_1d_arrayofarray(p_paperless)) 
		loop
			if (select a._ispaperless from unnest(v_arry_paperless) a) = true then
				v_cnt:= 0;
				select count(*) into v_cnt from kaveri.enablepaperlesstrans
				where srocode in (select a._srocode from unnest(v_arry_paperless) a) and
				ispaperless = true;
				--in (select a._ispaperless from unnest(v_arry_paperless) a); --= true;
				raise notice 'v_cnt -- %',v_cnt;
					if v_cnt = 0 then
						insert into kaveri.enablepaperlesstrans
						(districtcode,srocode,startdate,createdby,modifiedby,modifieddate,ispaperless)
						select _districtcode,a._srocode,
	    				current_timestamp,a._createdby,a._modifiedby,a._modifieddate,a._ispaperless
						from unnest(v_arry_paperless) a
						returning true into v_success;
					end if;
			else
				update kaveri.enablepaperlesstrans
				set ispaperless = a._ispaperless,
					enddate = current_timestamp,
					modifiedby = a._modifiedby,
					modifieddate = current_timestamp
				from unnest(v_arry_paperless) a 
				where srocode in (select a._srocode from unnest(v_arry_paperless) a)
				and ispaperless = true
				RETURNING true into v_success;
			end if;
--			 v_pid := array_append(v_pid,v_id);
		end loop;
	end if;
return v_success;
END;
$$;


ALTER FUNCTION kaveri.fn_save_enablepaperlesstrans(_districtcode integer, p_paperless kaveri.enablepaperlesstrans_input[]) OWNER TO postgres;

--
-- Name: fn_save_filing_book1_details(integer, integer, integer, integer, integer, timestamp without time zone, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_save_filing_book1_details(_citizen_id integer, _application_type_id integer, _sro_id integer, _deo_id integer, _book_type integer, _filing_date timestamp without time zone, _issuing_authority character varying, _order_number character varying, _current_status character varying, _last_updated_by integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    _application_no VARCHAR;
    _book_id INT;
    _rows_affected INT;
BEGIN
    -- Fetch Application Number
    SELECT kaveri.fn_insert_into_applicantapplicationdetails(_citizen_id, _application_type_id) INTO _application_no;
    IF _application_no IS NULL THEN
        RETURN NULL;
    END IF;

    -- Determine Book ID based on Book Type
    CASE _book_type
        WHEN 3 THEN _book_id := 7;
        WHEN 6 THEN _book_id := 14;
        ELSE _book_id := 0;
    END CASE;

    -- Update SRO Code in applicantapplicationdetails
    UPDATE kaveri.applicantapplicationdetails
    SET srocode = _sro_id, regsrocode = _sro_id, bookid = _book_id
    WHERE applicationnumber = _application_no;

    -- Update Application Status
    PERFORM kaveri.fn_upd_application_status(
        p_applicationnumber => _application_no,
        p_currentstatus => _current_status,
        p_lastupdatedby => _last_updated_by::text,
        p_sfdaid => 0,
        p_deoid => _deo_id
    );

    -- Insert into Filing Book1 Details
    INSERT INTO kaveri.filing_book1 (filing_date, issuingauthority, applicationnumber, book_id, order_number)
    VALUES (_filing_date, _issuing_authority, _application_no, _book_id, 
        CASE WHEN _book_type = 6 THEN _order_number ELSE NULL END)
    RETURNING applicationnumber INTO _application_no;

    RETURN _application_no;
END;
$$;


ALTER FUNCTION kaveri.fn_save_filing_book1_details(_citizen_id integer, _application_type_id integer, _sro_id integer, _deo_id integer, _book_type integer, _filing_date timestamp without time zone, _issuing_authority character varying, _order_number character varying, _current_status character varying, _last_updated_by integer) OWNER TO postgres;

--
-- Name: fn_save_index2_configuration(integer, integer, integer, integer, integer, numeric, bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_save_index2_configuration(p_id integer, p_reportid integer, p_maxyear integer, p_searchcount integer, p_feerulecode integer, p_amount numeric, p_user bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare
    v_configid int;
begin

    if p_id = 0 then
    
        insert into kaveri.reportmasterconfiguration
        (	id,
            reportid,
            maxyear,
            searchcriteriacount,
            feerulecode,
            amount,
            createdby
        )
        values
        (
            nextval('kaveri.reportmasterconfiguration_id_seq'),
            p_reportid,
            p_maxyear,
            p_searchcount,
            p_feerulecode,
            p_amount,
            p_user
        )
        returning id INTO v_configid;

        update kaveri.feesrulemaster
        set value = p_amount
        where feerulecode = p_feerulecode
        and serviceid = 53;

    else

        update kaveri.reportmasterconfiguration
        set reportid = p_reportid,
            maxyear = p_maxyear,
            searchcriteriacount = p_searchcount,
            feerulecode = p_feerulecode,
            amount = p_amount,
            updatedby = p_user
        where id = p_id;

        update kaveri.feesrulemaster
        set value = p_amount
        where feerulecode = p_feerulecode
        and serviceid = 53;

        v_configid := p_id;

    end if;

    return v_configid;

end;
$$;


ALTER FUNCTION kaveri.fn_save_index2_configuration(p_id integer, p_reportid integer, p_maxyear integer, p_searchcount integer, p_feerulecode integer, p_amount numeric, p_user bigint) OWNER TO postgres;

