-- Name: fn_save_mojinidatain_partyschedule(kaveri.mojinidatain_partyschedule_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_save_mojinidatain_partyschedule(p_mojinidata kaveri.mojinidatain_partyschedule_input[] DEFAULT NULL::kaveri.mojinidatain_partyschedule_input[]) RETURNS character varying
    LANGUAGE plpgsql
    AS $$

declare
--v_array_partyinfo kaveri.partyinfo_input[];
--v_array_propertyschedule kaveri.property_schedules_inpu[];
--v_array p_mojinidata%type;
v_isschedulesavereqd bool;
v_scheduleid int;
v_row p_mojinidata%type;
v_partyid int;
v_applicationnumber character varying;
v_partyids character varying;
v_partytypeid bigint;

BEGIN

	for v_row in (SELECT kaveri.fn_fetch_1d_arrayofarray(p_mojinidata))
loop
	
	select _applicationnumber into v_applicationnumber from unnest(v_row);

	insert into kaveri.partyinfo(partyid,srocode,documentid,partytypeid,firstname,middlename,lastname,address,age,sex,isexecutor,ispresenter,mainownerno,
	ownerno,relationship,relativename,availableextacre,availableextgunta,availableextfgunta,transactextacre,transactextgunta,transactextfgunta,
	propertyid,landcode,applicationnumber,isorganization,organizationid,bincom,category,restriction,restrictiondescription,totalextacre,totalextgunta,
	totalextfgunta)
	select nextval('kaveri.partyinfo_partyid_seq'),_srocode,1 as documentid,_parttypeid,_firstname,_middlename,_lastname,_address,_age,_sex,_executor,_ispresenter,_mainownerno,
			_ownerno,_relationship,_relativename,_availableextacre,_availableextgunta,_availableextfgunta,_transactextacre,_transactextgunta,
			_transactextfgunta,_propertyid,_landcode,v_applicationnumber,_isorganization,_organizationid,_bincom,_category,_restriction,_restrictiondescription
			,_totalextacre,_totalextgunta,_totalextfgunta
			from unnest(v_row)
			 returning partyid into v_partyid;

	insert into kaveri.orgdatajslip(partyid,documentid,propertyid,partytypeid,firstname,mainownerno,ownerno,transactextacre,transactextgunta,transactextfgunta,applicationnumber, relationship, relativename)
   		select v_partyid,1 as documentid,_propertyid,_parttypeid,_firstname,_mainownerno,_ownerno,_transactextacre,_transactextgunta,_transactextfgunta,v_applicationnumber,_relationship,_relativename from unnest(v_row);
 
   	select _isschedulesavereqd into v_isschedulesavereqd from unnest(v_row);
   
    select _parttypeid into v_partytypeid from unnest(v_row);

	if (v_isschedulesavereqd=true)
		then 
		

   	
insert into kaveri.propertyschedules(scheduleid,propertyid,srocode,scheduletype,totalarea,unitid,description,giftshare,giftsharedetails,easttowest,
northtosouth,applicationnumber,eastboundary,westboundary,northboundary,southboundary,partyids)
select nextval('kaveri.propertyschedules_scheduleid_seq'),_propertyid,_srocode,_scheduletype,_totalarea,_unitid,_description,_giftshare,
_giftsharedetails,_easttowest,_northtosouth,v_applicationnumber,_eastboundary,_westboundary,_northboundary,_southboundary,_partyids
from unnest(v_row)
returning scheduleid into v_scheduleid;

end if;

select scheduleid  into v_scheduleid   from kaveri.propertyschedules p where propertyid in (select _propertyid from unnest(v_row)) and partyids in (select _scheduleid from unnest(v_row));

if(v_partytypeid<>2)
then

insert into  kaveri.partyschedules (partyid,scheduleid,propertyid,applicationnumber)
select v_partyid,v_scheduleid,_propertyid,v_applicationnumber from unnest(v_row);

--select _applicationnumber into v_applicationnumber from unnest(v_row);

end if;

end loop;
return v_applicationnumber;
END;
$$;


