   END;
$$;


ALTER FUNCTION kaveri.fn_save_partyinfo_photothumb_04052026(_partyid bigint, _fingerid integer, _thumbpath text, _photopath text, _thumbremarks character varying) OWNER TO postgres;

--
-- Name: fn_save_partyinfo_photothumb_bkp_20260624(bigint, integer, text, text, character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_save_partyinfo_photothumb_bkp_20260624(_partyid bigint, _fingerid integer, _thumbpath text, _photopath text, _thumbremarks character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
Declare
v_partyid bigint;
begin
/* Thumbremarks added in both if and else -- as requested by Krishna Gautam as on 30/09/2022 */
if (_photopath is not null and coalesce(_photopath,'') <> '' and trim(_photopath)<>'') then
update kaveri.partyinfo set photopath =_photopath,--,thumbremarks = _thumbremarks  -- commented thumbremarks as requested by Krishna Gautam as on 18/10/2022
admissiondate = CURRENT_TIMESTAMP
where partyid = _partyid returning partyid into v_partyid;
--return v_partyid;
elsif(_thumbpath is not null and coalesce(_thumbpath,'')<>'' and trim(_thumbpath)<>'') then
update kaveri.partyinfo set fingerid= _fingerid, thumbpath=_thumbpath,
thumbremarks = _thumbremarks, admissiondate = CURRENT_TIMESTAMP
where partyid = _partyid returning partyid into v_partyid;
end if;
/*update kaveri.partyinfo set thumbremarks = _thumbremarks
where partyid = _partyid returning partyid into v_partyid;*/
return v_partyid;
   END;
$$;


ALTER FUNCTION kaveri.fn_save_partyinfo_photothumb_bkp_20260624(_partyid bigint, _fingerid integer, _thumbpath text, _photopath text, _thumbremarks character varying) OWNER TO csgadmin;

--
-- Name: fn_save_partyinfo_photothumb_paperless(bigint, integer, text, text, character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_save_partyinfo_photothumb_paperless(_partyid bigint, _fingerid integer, _thumbpath text, _photopath text, _thumbremarks character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
Declare
v_partyid bigint;
party_ids bigint[];
v_exists boolean;
v_application varchar;
begin

select applicationnumber into v_application from kaveri.partyinfo where partyid = _partyid limit 1;

SELECT EXISTS (SELECT 1 FROM kaveri.partyinfo WHERE partyid = _partyid) INTO v_exists;
    IF NOT v_exists THEN
        RETURN FALSE;
    END IF;
        
    with recursive linked AS (
        select p.partyid, p.linkpartyid,p.duplicatepartyid
        from kaveri.partyinfo p
        where p.applicationnumber = v_application and p.partyid = _partyid
        union
        -- expand: any row whose partyid is linked to any already-seen partyid
        select p.partyid, p.linkpartyid,p.duplicatepartyid
        from kaveri.partyinfo p
        join linked l on (p.partyid = l.linkpartyid or p.linkpartyid = l.partyid OR p.duplicatepartyid = l.partyid OR p.partyid = l.duplicatepartyid)
		where p.applicationnumber = v_application
    )
      select array(select partyid from linked INTO party_ids);


/* Thumbremarks added in both if and else -- as requested by Krishna Gautam as on 30/09/2022 */
if (_photopath is not null and coalesce(_photopath,'') <> '' and trim(_photopath)<>'') then
	update kaveri.partyinfo set photopath =_photopath,--,thumbremarks = _thumbremarks  -- commented thumbremarks as requested by Krishna Gautam as on 18/10/2022
	admissiondate = CURRENT_TIMESTAMP
	where partyid = any(party_ids); -- returning partyid into v_partyid;
--return v_partyid;
elsif(_thumbpath is not null and coalesce(_thumbpath,'')<>'' and trim(_thumbpath)<>'') then
	update kaveri.partyinfo set fingerid= _fingerid, thumbpath=_thumbpath,
	thumbremarks = _thumbremarks, admissiondate = CURRENT_TIMESTAMP
	where partyid = any(party_ids); -- returning partyid into v_partyid;
end if;
/*update kaveri.partyinfo set thumbremarks = _thumbremarks
where partyid = _partyid returning partyid into v_partyid;*/
return _partyid;
   END;
$$;


ALTER FUNCTION kaveri.fn_save_partyinfo_photothumb_paperless(_partyid bigint, _fingerid integer, _thumbpath text, _photopath text, _thumbremarks character varying) OWNER TO postgres;

--
-- Name: fn_save_paymentdetails(character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_save_paymentdetails(_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$

Declare
v_appnumber text;
v_nomenclature character varying (50);
v_serial character varying (50);
v_deptrefcode character varying (50);
v_subdeptrefcode character varying (50);
v_transactionid character varying (50);

pmnt_row record;
subref_row record;
v_data_json json;
v_cnt bigint ;
v_nomen character varying (50);
v_serialno character varying (50);
v_transactid character varying (50);
v_count bigint;
v_exemption_amount numeric;
v_deptreferencecode_delete character varying(50);
v_alreadypaidfee int;
v_newfee int;
v_feerulearray varchar[];
begin

v_deptrefcode := '';
v_nomenclature :='RG'||to_char(now(),'MM')||''||to_char(now(),'YY');
v_transactionid:=v_nomenclature||v_serial;


select count(*) into v_cnt from kaveri.ec_applicationdetails 
where applicationnumber = _applicationnumber;

if(v_cnt > 0) then
select count(*) into v_count  from kaveri.ams_reg_epaymenttransdetails ept
where ept.applicationnumber=_applicationnumber and ept.isdelete=false;
if (v_count=0) then
    select lpad(nextval('kaveri.deptreferencecode_seq')::text,8,'0') into v_serial ;
    for pmnt_row in (select distinct ecapp.applicationnumber,ecfees.ecid, fm.prpsnamehead 
        from kaveri.ec_applicationdetails ecapp
        inner join kaveri.ec_requiredfees ecfees on ecapp.ecid = ecfees.ecid 
        left join kaveri.vw_feesrule_mapping fm on  ecfees.feeruleid = fm.feerulecode
        where ecapp.applicationnumber = _applicationnumber AND fm.prpsnamehead IS NOT NULL) loop 
        v_deptrefcode := '';
        v_deptrefcode :=v_nomenclature||pmnt_row.prpsnamehead||v_serial;
        insert into kaveri.ams_reg_khajaneresponselog (deptreferencecode,applicationnumber,transactionid,datetimestamp)
        values (v_deptrefcode,_applicationnumber,v_transactionid,current_timestamp) ;
        
	    for subref_row in (select ecapp.applicationnumber,ecfees.ecid, ecfees.feeruleid, ecfees.payableamount, 
			ecfees.serviceid,fm.feerulename, fm.deptpurposeid, fm.accntheadname, fm.prpsname, 
			fm.trsrycode,fm.prpsnamehead,ecapp.kaverisrocode,fm.subrefcode,
					   concat_ws(' '::text, cm.firstname, cm.middlename, cm.lastname) AS remittername from 
					   kaveri.ec_applicationdetails ecapp 
					   inner join kaveri.ec_requiredfees ecfees on ecapp.ecid = ecfees.ecid
					   left join kaveri.citizenmaster cm on (ecapp.userid = cm.citizenid)
			left join kaveri.vw_feesrule_mapping fm on  ecfees.feeruleid = fm.feerulecode
			where ecapp.applicationnumber = _applicationnumber  and fm.prpsnamehead=pmnt_row.prpsnamehead ) loop		
		    
            v_subdeptrefcode:=v_deptrefcode||UPPER(subref_row.subrefcode);
        
            insert into kaveri.ams_reg_epaymentamtpaiddetails(
            chlnrefnum, deptpurposeid, headofaccount, totalamount,amountpaid, applicationnumber, deptreferencecode)
            values(v_subdeptrefcode,subref_row.deptpurposeid,subref_row.prpsname,abs(subref_row.payableamount),0,
                _applicationnumber,v_deptrefcode) ;
                	
            INSERT INTO kaveri.ams_reg_epaymenttransdetails
            ( officeid, remittername, totalamount, chlnrefnum, deptreferencecode,  applicationnumber,treasurycode , documentid,  feerulecode,ecid )
            values(subref_row.kaverisrocode,subref_row.remittername,abs(subref_row.payableamount),
            v_subdeptrefcode,v_deptrefcode,_applicationnumber,subref_row.trsrycode, subref_row.ecid, subref_row.feeruleid,subref_row.ecid  ) ;            
		end loop;	
    end loop;
	else 
	    select deptreferencecode into v_deptrefcode from kaveri.ams_reg_epaymenttransdetails where applicationnumber=_applicationnumber and isdelete=false;
    end if;
end if;

/* Logic for Property Registration */

select count(*) into v_cnt from kaveri.feesrequired fd
join kaveri.applicantapplicationdetails ad on fd.applicationnumber=ad.applicationnumber where fd.applicationnumber=_applicationnumber and ad.isdeleted=false;
if (v_cnt > 0) then
	select count(*) into v_alreadypaidfee from kaveri.ams_reg_epaymentamtpaiddetails are2  
	join kaveri.ams_reg_epaymentbankackdetails are3 on are2.deptreferencecode=are3.deptreferencecode and are3.paymentstatuscode in ('10700066','10700072')
	where applicationnumber=_applicationnumber;	
	if(v_alreadypaidfee=0)
		then
    --* Commented on Jun 14, 2023; to start generating new deptrefcode on every transaction and handle null on exemption amount.
	 select distinct deptreferencecode into v_deptreferencecode_delete from kaveri.ams_reg_epaymenttransdetails ept --join kaveri.ams_reg_epaymentbankackdetails epb on ept.deptreferencecode=epb.deptreferencecode
	 where ept.applicationnumber=_applicationnumber and ept.isdelete=false; --and (epb.paymentstatuscode='10700066');
	 
	-- select count(*) into v_count from kaveri.ams_reg_epaymenttransdetails ept  where ept.applicationnumber=_applicationnumber and ept.isdelete=false; 
    
	--update kaveri.ams_reg_epaymenttransdetails set isdelete=true where deptreferencecode=v_deptreferencecode_delete;
	
	select coalesce(abs(sum(coalesce(amountpaid,0))),0) into v_exemption_amount from kaveri.feesrequired f 
    where f.applicationnumber = _applicationnumber and f.feerulecode in ('35', '104', '88','89');
	
	
	if (v_deptreferencecode_delete is null) then	

		select lpad(nextval('kaveri.deptreferencecode_seq')::text,12,'0') into v_serial ;
		for pmnt_row in (select distinct app.applicationnumber,fm.prpsnamehead
			from kaveri.applicantapplicationdetails app
			inner join kaveri.feesrequired fees on fees.applicationnumber = app.applicationnumber
			left join kaveri.vw_feesrule_mapping fm on  fees.feerulecode = fm.feerulecode
			where app.applicationnumber = _applicationnumber AND fm.prpsnamehead IS NOT NULL) loop 
				
			v_deptrefcode := '';
			v_deptrefcode :=v_nomenclature||v_serial;
		
			insert into kaveri.ams_reg_khajaneresponselog (deptreferencecode,applicationnumber,transactionid,datetimestamp)
			values (v_deptrefcode,_applicationnumber,v_transactid,current_timestamp) ;
		
			for subref_row in (select app.applicationnumber,fees.feerulecode, 
				sum(case when fees.feerulecode='36' then
						(case when coalesce(fees.amountpaid,0) <= v_exemption_amount then 0 
						else (coalesce(fees.amountpaid,0) - v_exemption_amount) end)
					else coalesce(fees.amountpaid,0) end) as amountrequired, fm.feerulename, fm.deptpurposeid, 
				fm.accntheadname, fm.prpsname, fm.trsrycode,fm.prpsnamehead,app.srocode,fm.subrefcode,
				(case when cm.isinstitution=true then cm.middlename else concat_ws(' '::text, cm.firstname, cm.middlename, cm.lastname) end) AS remittername,
				fees.documentid ,  fees.feerulecode from  kaveri.applicantapplicationdetails app 
				-- join kaveri.partyinfo p on app.applicationnumber =p.applicationnumber
				inner join kaveri.feesrequired fees on app.applicationnumber = fees.applicationnumber and coalesce(fees.amountpaid,0)>0
				--commented on March 15, 2023 to calculate the sum total of deficit duties
				--left join kaveri.feesrequired fees_def on (app.applicationnumber = fees_def.applicationnumber and fees_def.feerulecode in ('35', '104'))
				join kaveri.citizenmaster cm on (app.citizenid = cm.citizenid)
				join kaveri.vw_feesrule_mapping fm on  fees.feerulecode = fm.feerulecode
				where fees.applicationnumber = _applicationnumber  and fm.prpsnamehead=pmnt_row.prpsnamehead 
				group by  app.applicationnumber,fees.feerulecode, fm.feerulename, fm.deptpurposeid, fm.accntheadname, fm.prpsname, fm.subrefcode,
				fm.trsrycode,fm.prpsnamehead,app.srocode,cm.firstname, cm.middlename, cm.lastname, fees.documentid ,  fees.feerulecode,cm.isinstitution ) loop
				
				v_subdeptrefcode:=v_deptrefcode||UPPER(subref_row.subrefcode);
		
				insert into kaveri.ams_reg_epaymentamtpaiddetails(
				chlnrefnum, deptpurposeid, headofaccount, totalamount,amountpaid, applicationnumber, deptreferencecode)
				values(v_subdeptrefcode,subref_row.deptpurposeid,subref_row.prpsname,(subref_row.amountrequired),0,
					_applicationnumber,v_deptrefcode) ;
		
				INSERT INTO kaveri.ams_reg_epaymenttransdetails
				( officeid, remittername, totalamount, chlnrefnum, 
				deptreferencecode,  applicationnumber,treasurycode, documentid ,feerulecode  )
				values(subref_row.srocode,subref_row.remittername,(subref_row.amountrequired),
				v_subdeptrefcode,v_deptrefcode,_applicationnumber,subref_row.trsrycode, subref_row.documentid  ,
				subref_row.feerulecode ) ;
			end loop;
		end loop;
	
    else
        select deptreferencecode into v_deptrefcode from kaveri.ams_reg_epaymenttransdetails 
        where applicationnumber=_applicationnumber and isdelete=false order by inserteddatetime desc limit 1;		
        --update kaveri.ams_reg_epaymenttransdetails  set isdelete=true where deptreferencecode<>v_deptrefcode;
	end if;	
else 
		
		select array_agg(feerulecode::text::json) into v_feerulearray from kaveri.feesrequired 
		where applicationnumber=_applicationnumber 
		and  feerulecode not in (select feerulecode from kaveri.ams_reg_epaymenttransdetails are1 
		join kaveri.ams_reg_epaymentbankackdetails are2 on are1.deptreferencecode =are2.deptreferencecode 
		and are2.paymentstatuscode in ('10700066','10700072') where applicationnumber=_applicationnumber 
		and are1.feerulecode not in (109)) and sroamountrequired>0
		and feerulecode not in ('35', '104', '88','89','105') and (coalesce(sroamountrequired,0) - coalesce(amountpaid,0))<>0 ; ---taking all the feerulecode for which payment has not been made
		
		if(array_length(v_feerulearray,1)>0) ---Checking the length of array 
		then 	

		for pmnt_row in (select distinct app.applicationnumber,fm.prpsnamehead
			from kaveri.applicantapplicationdetails app
			inner join kaveri.feesrequired fees on fees.applicationnumber = app.applicationnumber
			left join kaveri.vw_feesrule_mapping fm on  fees.feerulecode = fm.feerulecode
			where app.applicationnumber = _applicationnumber AND fm.prpsnamehead IS NOT NULL and fees.feerulecode::varchar = any(v_feerulearray)	
			and fees.sroamountrequired>0 and fees.feerulecode not in ('35', '104', '88','89','105') ) ------------taking headofaccount and applicationnumber
			loop 
				
			v_deptrefcode := '';
			v_deptrefcode :=v_nomenclature||(select lpad(nextval('kaveri.deptreferencecode_seq')::text,12,'0'));
		
			insert into kaveri.ams_reg_khajaneresponselog (deptreferencecode,applicationnumber,transactionid,datetimestamp)
			values (v_deptrefcode,_applicationnumber,v_transactid,current_timestamp) ;
		
			for subref_row in (select app.applicationnumber,fees.feerulecode, 
				sum(coalesce(fees.sroamountrequired,0) - coalesce(fees.amountpaid,0))  as amountrequired,  ---------taking the difference amount of sroamountrequired and amountpaid, if he has done some partial payment so the difference amount he has to pay
				fm.feerulename, fm.deptpurposeid, 
				fm.accntheadname, fm.prpsname, fm.trsrycode,fm.prpsnamehead,app.srocode,fm.subrefcode,
				(case when cm.isinstitution=true then cm.middlename else concat_ws(' '::text, cm.firstname, cm.middlename, cm.lastname) end) AS remittername,
				fees.documentid ,  fees.feerulecode from  kaveri.applicantapplicationdetails app 
				-- join kaveri.partyinfo p on app.applicationnumber =p.applicationnumber
				inner join kaveri.feesrequired fees on app.applicationnumber = fees.applicationnumber and fees.feerulecode not in ('35', '104', '88','89','105') -------Removed Exemption feerulecode------  --and coalesce(fees.amountpaid,0)>0
				--commented on March 15, 2023 to calculate the sum total of deficit duties
				--left join kaveri.feesrequired fees_def on (app.applicationnumber = fees_def.applicationnumber and fees_def.feerulecode in ('35', '104'))
				join kaveri.citizenmaster cm on (app.citizenid = cm.citizenid)
				join kaveri.vw_feesrule_mapping fm on  fees.feerulecode = fm.feerulecode
				where fees.applicationnumber = _applicationnumber  and fm.prpsnamehead=pmnt_row.prpsnamehead 
				and fees.feerulecode::varchar = any(v_feerulearray) -----feerulecode which has not been paid for those feerulecode payment will proceed
				group by  app.applicationnumber,fees.feerulecode, fm.feerulename, fm.deptpurposeid, fm.accntheadname, fm.prpsname, fm.subrefcode,
				fm.trsrycode,fm.prpsnamehead,app.srocode,cm.firstname, cm.middlename, cm.lastname, fees.documentid ,  fees.feerulecode,cm.isinstitution ) loop
				
				v_subdeptrefcode:=v_deptrefcode||UPPER(subref_row.subrefcode);
		
				insert into kaveri.ams_reg_epaymentamtpaiddetails(
				chlnrefnum, deptpurposeid, headofaccount, totalamount,amountpaid, applicationnumber, deptreferencecode)
				values(v_subdeptrefcode,subref_row.deptpurposeid,subref_row.prpsname,(subref_row.amountrequired),(subref_row.amountrequired),
					_applicationnumber,v_deptrefcode) ;
		
				INSERT INTO kaveri.ams_reg_epaymenttransdetails
				( officeid, remittername, totalamount, chlnrefnum, 
				deptreferencecode,  applicationnumber,treasurycode, documentid ,feerulecode  )
				values(subref_row.srocode,subref_row.remittername,(subref_row.amountrequired),
				v_subdeptrefcode,v_deptrefcode,_applicationnumber,subref_row.trsrycode, subref_row.documentid  ,
				subref_row.feerulecode ) ;
			end loop;
		end loop;
	
		else
			select deptreferencecode into v_deptrefcode from kaveri.ams_reg_epaymenttransdetails 
			where applicationnumber=_applicationnumber and isdelete=false order by inserteddatetime desc limit 1;		
        --update kaveri.ams_reg_epaymenttransdetails  set isdelete=true where deptreferencecode<>v_deptrefcode;
	end if;	
---end if;	
end if;
end if;
--end if;	
/* Logic for Certified copy */
select count(*) into v_cnt from kaveri.cc_applicationdetails  where applicationnumber = _applicationnumber;

if(v_cnt > 0) then
    select count(*) into v_count from kaveri.ams_reg_epaymenttransdetails ept
   	where ept.applicationnumber=_applicationnumber and ept.isdelete=false; 
    if(v_count=0) then
        select lpad(nextval('kaveri.deptreferencecode_seq')::text,8,'0') into v_serial ;
        for pmnt_row in (select distinct ccapp.applicationnumber,ccfees.ccid, fm.prpsnamehead 
            from kaveri.cc_applicationdetails ccapp
            inner join kaveri.cc_requiredfees ccfees on ccapp.ccid = ccfees.ccid 
            left join kaveri.vw_feesrule_mapping fm on  ccfees.feeruleid = fm.feerulecode
            where ccapp.applicationnumber = _applicationnumber AND fm.prpsnamehead IS NOT NULL) loop 

            v_deptrefcode := '';
            v_deptrefcode :=v_nomenclature||pmnt_row.prpsnamehead||v_serial;
            insert into kaveri.ams_reg_khajaneresponselog (deptreferencecode,applicationnumber,transactionid,datetimestamp)
            values (v_deptrefcode,_applicationnumber,v_transactionid,current_timestamp) ;
	
	        for subref_row in (select ccapp.applicationnumber,ccfees.ccid, ccfees.feeruleid, ccfees.payableamount, 
                ccfees.serviceid,fm.feerulename, fm.deptpurposeid, fm.accntheadname, fm.prpsname, 
                fm.trsrycode,fm.prpsnamehead,ccapp.kaverisrocode,fm.subrefcode,
                concat_ws(' '::text, cm.firstname, cm.middlename, cm.lastname)  AS remittername 
                from kaveri.cc_applicationdetails ccapp 
                --  join kaveri.partyinfo p on ccapp.applicationnumber =p.applicationnumber 
                inner join kaveri.cc_requiredfees ccfees on ccapp.ccid = ccfees.ccid
                left join kaveri.citizenmaster cm on (ccapp.userid = cm.citizenid)
			    left join kaveri.vw_feesrule_mapping fm on  ccfees.feeruleid = fm.feerulecode
			    where ccapp.applicationnumber = _applicationnumber and fm.prpsnamehead=pmnt_row.prpsnamehead) loop		
		        
                v_subdeptrefcode:=v_deptrefcode||UPPER(subref_row.subrefcode);
	
                insert into kaveri.ams_reg_epaymentamtpaiddetails(
                chlnrefnum, deptpurposeid, headofaccount, totalamount,amountpaid, applicationnumber, deptreferencecode)
                values(v_subdeptrefcode,subref_row.deptpurposeid,subref_row.prpsname,abs(subref_row.payableamount),0,
                    _applicationnumber,v_deptrefcode) ;
                
                INSERT INTO kaveri.ams_reg_epaymenttransdetails
                ( officeid, remittername, totalamount, chlnrefnum, deptreferencecode,  applicationnumber,treasurycode , documentid,  feerulecode,ccid)
                values(subref_row.kaverisrocode,subref_row.remittername,abs(subref_row.payableamount),
                v_subdeptrefcode,v_deptrefcode,_applicationnumber,subref_row.trsrycode,subref_row.ccid,subref_row.feeruleid,subref_row.ccid) ;
		    end loop;
        end loop;
    else
        select deptreferencecode into v_deptrefcode from kaveri.ams_reg_epaymenttransdetails am where am.applicationnumber=_applicationnumber and isdelete=false;
    end if;
end if;

/* Logic for Index 2 report */
select count(*) into v_cnt from kaveri.tbl_index2_audit_log  where applicationnumber = _applicationnumber;
-- raise notice 'applicationnumber %',_applicationnumber;
if(v_cnt > 0) then
   select count(*) into v_count from kaveri.ams_reg_epaymenttransdetails ept
  	where ept.applicationnumber=_applicationnumber and ept.isdelete=false; 
   if(v_count=0) then
       select lpad(nextval('kaveri.deptreferencecode_seq')::text,8,'0') into v_serial ;
       for pmnt_row in (select distinct ecapp.applicationnumber, fm.prpsnamehead 
       from kaveri.tbl_index2_audit_log ecapp
       left join kaveri.vw_feesrule_mapping fm on fm.feerulecode = 142 -- feerulecode for form2 index 2 report 
       where ecapp.applicationnumber = _applicationnumber AND fm.prpsnamehead IS NOT null) loop 

           v_deptrefcode := '';
           v_deptrefcode :=v_nomenclature||pmnt_row.prpsnamehead||v_serial;
           insert into kaveri.ams_reg_khajaneresponselog (deptreferencecode,applicationnumber,transactionid,datetimestamp)
           values (v_deptrefcode,_applicationnumber,v_transactionid,current_timestamp) ;
	
	        for subref_row in (select ccapp.applicationnumber,fm.feerulecode as feeruleid, frm.value as payableamount  , 
               frm.serviceid,fm.feerulename, fm.deptpurposeid, fm.accntheadname, fm.prpsname, 
               fm.trsrycode,fm.prpsnamehead,vm.srocode,fm.subrefcode,
               concat_ws(' '::text, cm.firstname, cm.middlename, cm.lastname)  AS remittername 
               from kaveri.tbl_index2_audit_log ccapp 
               join kaveri.feesrulemaster frm on frm.feerulecode  = 142
               join kaveri.villagemaster vm on vm.villagecode = ccapp.villagecode
               left join kaveri.citizenmaster cm on ccapp.userid::bigint = cm.citizenid
			    left join kaveri.vw_feesrule_mapping fm on fm.feerulecode = 142
			    where ccapp.applicationnumber = _applicationnumber and fm.prpsnamehead=pmnt_row.prpsnamehead) loop		
		        
               v_subdeptrefcode:=v_deptrefcode||UPPER(subref_row.subrefcode);
	
               insert into kaveri.ams_reg_epaymentamtpaiddetails(
               chlnrefnum, deptpurposeid, headofaccount, totalamount,amountpaid, applicationnumber, deptreferencecode)
               values(v_subdeptrefcode,subref_row.deptpurposeid,subref_row.prpsname,abs(subref_row.payableamount),0,
                   _applicationnumber,v_deptrefcode) ;
               
               INSERT INTO kaveri.ams_reg_epaymenttransdetails
               ( officeid, remittername, totalamount, chlnrefnum, deptreferencecode, applicationnumber, treasurycode, feerulecode)
               values(subref_row.srocode, subref_row.remittername, abs(subref_row.payableamount),
               v_subdeptrefcode,v_deptrefcode,_applicationnumber,subref_row.trsrycode,subref_row.feeruleid) ;
		    end loop;
       end loop;
   else
