/* =====================Generation of Json begins here ==================== */
--select deptreferencecode into v_deptrefcode from kaveri.ams_reg_epaymenttransdetails 
--where applicationnumber=_applicationnumber order by inserteddatetime desc limit 1;




select row_to_json(app_json) into v_data_json
from (
  select khj.deptreferencecode,khj.applicationnumber,khj.datetimestamp, 
	epay.officeid,epay.remittername,epay.treasurycode,
	 epay.totalamount,
	ddo.ddocode,'33E' AS deptrefcode,
     (
      select array_to_json(array_agg(row_to_json(subref)))
      from (select deptreferencecode,chlnrefnum, deptpurposeid, headofaccount as prpsname, --1 as amount
			abs(totalamount) as amount
			from kaveri.ams_reg_epaymentamtpaiddetails sub_ref
			where sub_ref.deptreferencecode = khj.deptreferencecode and totalamount > 0) subref
    ) as ChlnDetailsList

  from kaveri.ams_reg_khajaneresponselog khj 
	inner join (select officeid,deptreferencecode,remittername,treasurycode, --7 as totalamount -- 
				sum(totalamount) as totalamount
				from kaveri.ams_reg_epaymenttransdetails where totalamount>0 group by officeid,deptreferencecode,remittername,treasurycode) epay
		on (epay.deptreferencecode = khj.deptreferencecode)
	-- left join kaveri.mas_officemaster mo on (mo.officeid = epay.officeid ) 
	 join kaveri.mas_officemaster mo on (mo.kavericode = epay.officeid and mo.officetypeid = 3) 
	-- left join kaveri.mas_ams_khajaneddocodemapping ddo on (ddo.srocode = epay.officeid)
	 join kaveri.mas_ams_khajaneddocodemapping ddo on (ddo.srocode = epay.officeid)
	
  where khj.deptreferencecode = v_deptrefcode 
) app_json ;

	RETURN v_data_json;
   END;
$$;


ALTER FUNCTION kaveri.fn_save_paymentdetails_3(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_save_paymentgateway(character varying, bigint, character varying, character varying, character varying, character varying, timestamp without time zone, character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_save_paymentgateway(_banktransactionnumber character varying, _amount bigint, _deptreferencecode character varying, _paymentstatuscode character varying, _bankname character varying, _paymentmode character varying, _transactiontimestamp timestamp without time zone, _checksum character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
Declare
--v_deptrefcode character varying(100);
v_amount bigint;
v_paidamount bigint;
upd_amnt_row record;
v_applicationtypeid int;
v_citizenid bigint;
v_applicationnumber character varying;
v_appno character varying;
v_exemptamount bigint;
v_deptrefcodeexits bigint;
v_paystatuscode character varying;
v_srocode int;
v_receiptidcnt bigint[];
v_totalamt bigint;
begin

select a.applicationtypeid,a.citizenid,a.applicationnumber,a.srocode,sum(r.totalamount)
into v_applicationtypeid,  v_citizenid,  v_applicationnumber,v_srocode,v_totalamt
from kaveri.ams_reg_epaymenttransdetails r
join kaveri.applicantapplicationdetails a on a.applicationnumber=r.applicationnumber
where deptreferencecode=_deptreferencecode and r.isdelete=false
group by a.applicationtypeid,a.citizenid,a.applicationnumber,a.srocode;

--select sum(r1.totalamount) into v_totalamt
--from kaveri.ams_reg_epaymenttransdetails r1
--where r1.deptreferencecode=_deptreferencecode and r1.isdelete=false;

select coalesce(abs(sum(coalesce(amountpaid,0))),0) into v_exemptamount 
from kaveri.feesrequired f where f.applicationnumber = v_applicationnumber and f.feerulecode in ('104', '88','89');

if (_deptreferencecode is not null and coalesce(_deptreferencecode,'') <> '') 
then



insert into kaveri.ams_reg_epaymentbankackdetails(deptreferencecode, banktransactionnumber, bankname, paymentmode, 
												   paymentstatuscode, transactiontimestamp, amount, checksum) 
values (_deptreferencecode, _banktransactionnumber, _bankname, _paymentmode, 
												   _paymentstatuscode, _transactiontimestamp, _amount, _checksum);
												  

	if (_paymentstatuscode in ('10700066','10700072')) then
		v_amount = _amount;
	
		/* for upd_amnt_row in (select a.chlnrefnum,a.totalamount,a.deptreferencecode
						 from kaveri.ams_reg_epaymentamtpaiddetails a
							 where a.deptreferencecode = _deptreferencecode and totalamount>0 
							order by totalamount)
			*/				
					--24/05/2023 bankackdetails Update only on Payment Success; In case of Pending Payments, isdelete flag continues to be false		
		
							
		for upd_amnt_row in ( select b.feerulecode, b.documentid , a.chlnrefnum,a.totalamount,a.deptreferencecode , b.applicationnumber
						 from kaveri.ams_reg_epaymentamtpaiddetails a 
						  join kaveri.ams_reg_epaymenttransdetails b on a.deptreferencecode = b.deptreferencecode and a.chlnrefnum  = b.chlnrefnum
						where a.totalamount > 0 and a.deptreferencecode = _deptreferencecode
						order by totalamount
					) loop 
			if(v_amount > 0) then
				v_paidamount = upd_amnt_row.totalamount;			
				if (v_amount > 0 and v_amount < v_paidamount) then
					v_paidamount:=v_amount;
				end if;				
				
				update kaveri.ams_reg_epaymentamtpaiddetails a  
				set amountpaid = v_paidamount
				where chlnrefnum = upd_amnt_row.chlnrefnum and 
				a.deptreferencecode = upd_amnt_row.deptreferencecode ;
				
				
				-- To update the Fees paid status 
				update kaveri.feesrequired a
				set paymentstatus = 'Online Success',amountpaid =(case when feerulecode=36 then v_paidamount+v_exemptamount
				when (feerulecode=109 and (sroamountrequired=amountpaid+v_paidamount)) then amountpaid+v_paidamount	 else v_paidamount end )
				where a.applicationnumber =  upd_amnt_row.applicationnumber
				and documentid = upd_amnt_row.documentid 
				and feerulecode = upd_amnt_row.feerulecode ;
				

				
				v_amount = v_amount-v_paidamount;
			end if;			
		end loop;
		
			

--	if (coalesce(array_length(v_receiptidcnt, 1), 0)=0) then 
--		raise exception 'Something went wrong! FeesRequired updation failed.'; 
--		end if;
--	
		
	
	
		if ((v_applicationtypeid=1 or v_applicationtypeid=2) and v_totalamt=_amount )
		then 
			select  * into v_receiptidcnt from kaveri.fn_updatefetch_receipt_paid_details(v_applicationnumber,v_srocode) ;
		if (coalesce(array_length(v_receiptidcnt, 1), 0)=0) then 
		raise exception 'Something went wrong! FeesRequired updation failed.'; 
		end if;
			update kaveri.applicantapplicationdetails d set currentstatus='CD140' where applicationnumber  in (
			select distinct a.applicationnumber  from kaveribck.applicantapplicationdetails_regrepayment a
			join kaveri.applicantapplicationdetails ad on a.applicationnumber =ad.applicationnumber and ad.currentstatus ='CD106'
			join kaveri.ams_reg_epaymenttransdetails ar on a.applicationnumber =ar.applicationnumber and ar.isdelete =false
			join kaveri.feesrequired f on a.applicationnumber=f.applicationnumber and f.feerulecode=109
			where a.applicationnumber =v_applicationnumber and  a.currentstatus ='CD106' and f.sroamountrequired<>f.amountpaid)
			returning d.applicationnumber into v_appno;	
			
			update kaveri.ams_reg_epaymenttransdetails set isdelete=true where applicationnumber in (v_appno) and isdelete=false;
		
			if(v_appno is null)			
			then
			-- paperless change
			update kaveri.applicantapplicationdetails
                set currentstatus = case
                                        when ispaperless = true then 'CD107A'
                                        else 'CD107'
                                    end
                where applicationnumber = v_applicationnumber;
			
			update kaveri.applicantapplicationdetails ass set currentstatus= (case when ss.currentstatus='CD108' then ss.currentstatus else 'CD107' end)
			from (select a.currentstatus,a.applicationnumber from kaveribck.applicantapplicationdetails_regrepayment a where a.applicationnumber=v_applicationnumber ) as ss
			where ass.applicationnumber=ss.applicationnumber;
			end if;
			
		elsif(v_applicationtypeid =12)
		then 
			perform kaveri.fn_update_ccapplicantdetails(v_applicationnumber,v_citizenid,'update');
		elsif (v_applicationtypeid=13)
		then
			perform kaveri.fn_update_ecapplicantdetails(v_applicationnumber,v_citizenid,'update');
		elsif (v_applicationtypeid=53)
		then
			update kaveri.applicantapplicationdetails set currentstatus = 'RS102', applicationenddate = current_timestamp where applicationnumber = v_applicationnumber;
		end if;
		

		elsif (_paymentstatuscode in ('10700068','10700098','10700103','10700220'))
		then
		update kaveri.ams_reg_epaymenttransdetails set isdelete=true where deptreferencecode=_deptreferencecode;
		--end if;
		
	end if;
	

end if;

return _deptreferencecode;
--
exception
when UNIQUE_VIOLATION then

	return _deptreferencecode;
   END;
  
$$;


ALTER FUNCTION kaveri.fn_save_paymentgateway(_banktransactionnumber character varying, _amount bigint, _deptreferencecode character varying, _paymentstatuscode character varying, _bankname character varying, _paymentmode character varying, _transactiontimestamp timestamp without time zone, _checksum character varying) OWNER TO csgadmin;

--
-- Name: fn_save_paymentgateway_1(character varying, bigint, character varying, character varying, character varying, character varying, timestamp without time zone, character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_save_paymentgateway_1(_banktransactionnumber character varying, _amount bigint, _deptreferencecode character varying, _paymentstatuscode character varying, _bankname character varying, _paymentmode character varying, _transactiontimestamp timestamp without time zone, _checksum character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
Declare
--v_deptrefcode character varying(100);
v_amount bigint;
v_paidamount bigint;
upd_amnt_row record;
v_applicationtypeid int;
v_citizenid bigint;
v_applicationnumber character varying;
v_exemptamount bigint;
v_deptrefcodeexits bigint;
v_paystatuscode character varying;
v_srocode int;
v_receiptidcnt bigint[];
v_totalamt bigint;
begin

select a.applicationtypeid,a.citizenid,a.applicationnumber,a.srocode,sum(r.totalamount)
into v_applicationtypeid,  v_citizenid,  v_applicationnumber,v_srocode,v_totalamt
from kaveri.ams_reg_epaymenttransdetails r
join kaveri.applicantapplicationdetails a on a.applicationnumber=r.applicationnumber
where deptreferencecode=_deptreferencecode and r.isdelete=false
group by a.applicationtypeid,a.citizenid,a.applicationnumber,a.srocode;

--select sum(r1.totalamount) into v_totalamt
--from kaveri.ams_reg_epaymenttransdetails r1
--where r1.deptreferencecode=_deptreferencecode and r1.isdelete=false;

select coalesce(abs(sum(coalesce(amountpaid,0))),0) into v_exemptamount 
from kaveri.feesrequired f where f.applicationnumber = v_applicationnumber and f.feerulecode in ('104', '88','89');

if (_deptreferencecode is not null and coalesce(_deptreferencecode,'') <> '') 
then



insert into kaveri.ams_reg_epaymentbankackdetails(deptreferencecode, banktransactionnumber, bankname, paymentmode, 
												   paymentstatuscode, transactiontimestamp, amount, checksum) 
values (_deptreferencecode, _banktransactionnumber, _bankname, _paymentmode, 
												   _paymentstatuscode, _transactiontimestamp, _amount, _checksum);
												  

	if (_paymentstatuscode in ('10700066','10700072')) then
		v_amount = _amount;
	
		/* for upd_amnt_row in (select a.chlnrefnum,a.totalamount,a.deptreferencecode
						 from kaveri.ams_reg_epaymentamtpaiddetails a
							 where a.deptreferencecode = _deptreferencecode and totalamount>0 
							order by totalamount)
			*/				
					--24/05/2023 bankackdetails Update only on Payment Success; In case of Pending Payments, isdelete flag continues to be false		
		
							
		for upd_amnt_row in ( select b.feerulecode, b.documentid , a.chlnrefnum,a.totalamount,a.deptreferencecode , b.applicationnumber
						 from kaveri.ams_reg_epaymentamtpaiddetails a 
						  join kaveri.ams_reg_epaymenttransdetails b on a.deptreferencecode = b.deptreferencecode and a.chlnrefnum  = b.chlnrefnum
						where a.totalamount > 0 and a.deptreferencecode = _deptreferencecode
						order by totalamount
					) loop 
			if(v_amount > 0) then
				v_paidamount = upd_amnt_row.totalamount;			
				if (v_amount > 0 and v_amount < v_paidamount) then
					v_paidamount:=v_amount;
				end if;				
				raise notice 'inside if %',v_paidamount;
				update kaveri.ams_reg_epaymentamtpaiddetails a  
				set amountpaid = v_paidamount
				where chlnrefnum = upd_amnt_row.chlnrefnum and 
				a.deptreferencecode = upd_amnt_row.deptreferencecode ;
				
				
				-- To update the Fees paid status 
				update kaveri.feesrequired a
				set paymentstatus = 'Online Success',amountpaid =(case when feerulecode=36 then v_paidamount+v_exemptamount
				when (feerulecode=109 and (sroamountrequired=amountpaid+v_paidamount)) then amountpaid+v_paidamount	 else v_paidamount end )
				where a.applicationnumber =  upd_amnt_row.applicationnumber
				and documentid = upd_amnt_row.documentid 
				and feerulecode = upd_amnt_row.feerulecode ;
				raise notice 'documentid:- % applicationnumber:- % feerulecode:- %',upd_amnt_row.documentid,upd_amnt_row.applicationnumber,upd_amnt_row.feerulecode;

				
				v_amount = v_amount-v_paidamount;
			end if;			
		end loop;
		
			

--	if (coalesce(array_length(v_receiptidcnt, 1), 0)=0) then 
--		raise exception 'Something went wrong! FeesRequired updation failed.'; 
--		end if;
--	
		
	
	
		if ((v_applicationtypeid=1 or v_applicationtypeid=2) and v_totalamt=_amount )
		then 
			select  * into v_receiptidcnt from kaveri.fn_updatefetch_receipt_paid_details(v_applicationnumber,v_srocode) ;
		if (coalesce(array_length(v_receiptidcnt, 1), 0)=0) then 
		raise exception 'Something went wrong! FeesRequired updation failed.'; 
		end if;
			update kaveri.applicantapplicationdetails set currentstatus= 'CD107' 
			where applicationnumber=v_applicationnumber;
		elsif(v_applicationtypeid =12)
		then 
			perform kaveri.fn_update_ccapplicantdetails(v_applicationnumber,v_citizenid,'update');
		elsif (v_applicationtypeid=13)
		then
			perform kaveri.fn_update_ecapplicantdetails(v_applicationnumber,v_citizenid,'update');
		end if;

		elsif (_paymentstatuscode not in ('10700092','10700070'))
		then
		update kaveri.ams_reg_epaymenttransdetails set isdelete=true where deptreferencecode=_deptreferencecode;
		--end if;
		
	end if;
	

end if;

return _deptreferencecode;
--
exception
when UNIQUE_VIOLATION then

	return _deptreferencecode;
   END;
  
$$;


ALTER FUNCTION kaveri.fn_save_paymentgateway_1(_banktransactionnumber character varying, _amount bigint, _deptreferencecode character varying, _paymentstatuscode character varying, _bankname character varying, _paymentmode character varying, _transactiontimestamp timestamp without time zone, _checksum character varying) OWNER TO postgres;

--
-- Name: fn_save_paymentgateway_book1(character varying, bigint, character varying, character varying, character varying, character varying, timestamp without time zone, character varying, character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_save_paymentgateway_book1(_banktransactionnumber character varying, _amount bigint, _deptreferencecode character varying, _paymentstatuscode character varying, _bankname character varying, _paymentmode character varying, _transactiontimestamp timestamp without time zone, _checksum character varying, application_number character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
Declare
--v_deptrefcode character varying(100);
v_amount bigint;
v_paidamount bigint;
upd_amnt_row record;
v_applicationtypeid int;
v_citizenid bigint;
v_applicationnumber character varying;
v_appno character varying;
v_exemptamount bigint;
v_deptrefcodeexits bigint;
v_paystatuscode character varying;
v_srocode int;
v_receiptidcnt bigint[];
v_totalamt bigint;
begin


if (_deptreferencecode is not null and coalesce(_deptreferencecode,'') <> '') 
then



insert into kaveri.ams_reg_epaymentbankackdetails(deptreferencecode, banktransactionnumber, bankname, paymentmode, 
												   paymentstatuscode, transactiontimestamp, amount, checksum) 
values (_deptreferencecode, _banktransactionnumber, _bankname, _paymentmode, 
												   _paymentstatuscode, _transactiontimestamp, _amount, _checksum);
												  

	if (_paymentstatuscode in ('10700066','10700072')) then


		insert into kaveri.ams_reg_epaymentamtpaiddetails( chlnrefnum, deptpurposeid, headofaccount, amountpaid, applicationnumber,
        deptreferencecode, totalamount, k1k2_flag)
		values (_deptreferencecode || 'AH1D', 1, '0030~02~103~0~01~000', _amount, application_number, _deptreferencecode, _amount, 2);
	
	end if;			


end if;

return _deptreferencecode;
--
exception
when UNIQUE_VIOLATION then

	return _deptreferencecode;
   END;
  
$$;


ALTER FUNCTION kaveri.fn_save_paymentgateway_book1(_banktransactionnumber character varying, _amount bigint, _deptreferencecode character varying, _paymentstatuscode character varying, _bankname character varying, _paymentmode character varying, _transactiontimestamp timestamp without time zone, _checksum character varying, application_number character varying) OWNER TO postgres;

--
-- Name: fn_save_paymentgateway_verify(character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_save_paymentgateway_verify(_deptreferencecode character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
Declare
v_totalamt bigint;
v_amount bigint;
v_verify boolean;
begin

select sum(totalamount) into v_totalamt
from kaveri.ams_reg_epaymenttransdetails r
where deptreferencecode=_deptreferencecode and isdelete=false;

select amount into v_amount
from kaveri.ams_reg_epaymentbankackdetails r
where deptreferencecode=_deptreferencecode and paymentstatuscode in ('10700066','10700072');

if (v_totalamt=v_amount)
then

v_verify:=TRUE;

else 

v_verify:=FALSE;

end if;

return v_verify;

   END;
  
$$;


ALTER FUNCTION kaveri.fn_save_paymentgateway_verify(_deptreferencecode character varying) OWNER TO postgres;

--
-- Name: fn_save_pending_paymentdetails(character varying, character varying, timestamp without time zone); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_save_pending_paymentdetails(_applicationnumber character varying, _challennumber character varying, _challendate timestamp without time zone) RETURNS json
    LANGUAGE plpgsql
    AS $$
Declare
v_appnumber text;
v_nomenclature character varying (50);
v_serial character varying (50);
v_deptrefcode character varying (50);
v_subdeptrefcode character varying (50);
v_transactionid character varying (50);

pmnt_row record;
subref_row record;
v_data_json json;
v_cnt bigint ;
v_nomen character varying (50);
v_serialno character varying (50);
v_transactid character varying (50);
begin

v_deptrefcode := _challennumber;

v_nomenclature :='IG'||to_char(now(),'MM')||''||to_char(now(),'YY');

select lpad(nextval('kaveri.deptreferencecode_seq')::text,8,'0') into v_serial ;
v_transactionid:=v_nomenclature||v_serial;

		select count(*) into v_cnt from kaveri.feesrequired where applicationnumber=_applicationnumber;
		if (v_cnt > 0) then
		
		for pmnt_row in (select distinct app.applicationnumber,fm.prpsnamehead 
				 from kaveri.applicantapplicationdetails app
					inner join kaveri.feesrequired fees on fees.applicationnumber = app.applicationnumber 
					left join kaveri.vw_feesrule_mapping fm on  fees.feerulecode = fm.feerulecode
					where app.applicationnumber = _applicationnumber AND fm.prpsnamehead IS NOT NULL)

loop 
	v_deptrefcode := _challennumber ;
--	v_deptrefcode :=v_nomenclature||pmnt_row.prpsnamehead||v_serial;
	
	insert into kaveri.ams_reg_khajaneresponselog (deptreferencecode,applicationnumber,transactionid,datetimestamp)
	values (v_deptrefcode,_applicationnumber,v_transactid,current_timestamp) ;
	
	for subref_row in (select app.applicationnumber,fees.feerulecode, fees.amountpaid,
					fm.feerulename, fm.deptpurposeid, fm.accntheadname, fm.prpsname, 
					fm.trsrycode,fm.prpsnamehead,app.srocode,fm.subrefcode,
					   concat_ws(' '::text, cm.firstname, cm.middlename, cm.lastname) AS remittername ,
					   fees.documentid ,  fees.feerulecode
					   from 
					   kaveri.applicantapplicationdetails app 
					   inner join kaveri.feesrequired fees on app.applicationnumber = fees.applicationnumber 
					   and coalesce(fees.amountpaid,0)>0
					 --  left join kaveri.feesrequired fees_def on 
					  -- (app.applicationnumber = fees_def.applicationnumber 
						--	 and fees_def.feerulecode='35')
					   left join kaveri.citizenmaster cm on (app.citizenid = cm.citizenid)
			left join kaveri.vw_feesrule_mapping fm on  fees.feerulecode = fm.feerulecode
			where fees.applicationnumber = _applicationnumber  and fm.prpsnamehead=pmnt_row.prpsnamehead
					   and fees.paymentstatus='Pending'
					group by  app.applicationnumber,fees.feerulecode, fm.feerulename, 
					   fm.deptpurposeid, fm.accntheadname, fm.prpsname, fm.subrefcode,
			fm.trsrycode,fm.prpsnamehead,app.srocode,cm.firstname, cm.middlename, cm.lastname,
				fees.amountpaid,fees.documentid ,  fees.feerulecode
			)
	
		loop		
		v_subdeptrefcode:=v_deptrefcode||UPPER(subref_row.subrefcode);
	
	insert into kaveri.ams_reg_epaymentamtpaiddetails(
	chlnrefnum, deptpurposeid, headofaccount, totalamount,amountpaid, applicationnumber, deptreferencecode)
	values(v_subdeptrefcode,subref_row.deptpurposeid,subref_row.prpsname, subref_row.amountpaid,
	subref_row.amountpaid,  _applicationnumber, v_deptrefcode) ;
	
		INSERT INTO kaveri.ams_reg_epaymenttransdetails
		( officeid, remittername, totalamount, chlnrefnum, 
	deptreferencecode,  applicationnumber,treasurycode, documentid ,feerulecode  )
	values(subref_row.srocode,subref_row.remittername,subref_row.amountpaid,
	v_subdeptrefcode,v_deptrefcode,_applicationnumber,subref_row.trsrycode, subref_row.documentid  ,
	subref_row.feerulecode ) ;
	

		end loop;
	
    end loop;
	end if;

/* =====================Generation of Json begins here ==================== */
select row_to_json(app_json) into v_data_json
from (
  select khj.deptreferencecode,khj.applicationnumber,khj.datetimestamp, 
	epay.officeid,epay.remittername,epay.treasurycode,
	 epay.totalamount,
	ddo.ddocode,'33E' AS deptrefcode,
     (
      select array_to_json(array_agg(row_to_json(subref)))
      from (select deptreferencecode,chlnrefnum, deptpurposeid, headofaccount as prpsname, --1 as amount
			abs(totalamount) as amount
			from kaveri.ams_reg_epaymentamtpaiddetails sub_ref
			where sub_ref.deptreferencecode = khj.deptreferencecode and totalamount > 0) subref
    ) as ChlnDetailsList

  from kaveri.ams_reg_khajaneresponselog khj 
	inner join (select officeid,deptreferencecode,remittername,treasurycode, --7 as totalamount -- 
				sum(totalamount) as totalamount
				from kaveri.ams_reg_epaymenttransdetails group by officeid,deptreferencecode,remittername,treasurycode) epay
		on (epay.deptreferencecode = khj.deptreferencecode)
	left join kaveri.mas_officemaster mo on (mo.officeid = epay.officeid ) 
	left join kaveri.mas_ams_khajaneddocodemapping ddo on (ddo.srocode = epay.officeid)
  where khj.deptreferencecode = v_deptrefcode 
) app_json ;

	RETURN v_data_json;
   END;
$$;


ALTER FUNCTION kaveri.fn_save_pending_paymentdetails(_applicationnumber character varying, _challennumber character varying, _challendate timestamp without time zone) OWNER TO csgadmin;

--
-- Name: fn_save_pending_paymentgateway(character varying, bigint, character varying, character varying, character varying, character varying, timestamp without time zone, character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_save_pending_paymentgateway(_banktransactionnumber character varying, _amount bigint, _deptreferencecode character varying, _paymentstatuscode character varying, _bankname character varying, _paymentmode character varying, _transactiontimestamp timestamp without time zone, _checksum character varying) RETURNS TABLE(deptreferencecode character varying, applicationnumber character varying, applicationtypeid integer, applicationtype character varying, srocode integer, sronamee character varying, presentername text)
    LANGUAGE plpgsql
    AS $$
Declare
v_deptrefcode character varying(100);
v_amount bigint;
v_paidamount bigint;
upd_amnt_row record;
begin
if (_deptreferencecode is not null and coalesce(_deptreferencecode,'') <> '') then

insert into kaveri.ams_reg_epaymentbankackdetails(deptreferencecode, banktransactionnumber, bankname, paymentmode, 
												   paymentstatuscode, transactiontimestamp, amount, checksum) 
values (_deptreferencecode, _banktransactionnumber, _bankname, _paymentmode, 
												   _paymentstatuscode, _transactiontimestamp, _amount, _checksum);
--returning deptreferencecode into v_deptrefcode;
	if (_paymentstatuscode = '10700066') then
		v_amount = _amount;
							
	for upd_amnt_row in (	 select  
b.feerulecode, b.documentid ,
a.chlnrefnum,a.totalamount,a.deptreferencecode , b.applicationnumber
						 from kaveri.ams_reg_epaymentamtpaiddetails a 
						  join 
						       kaveri.ams_reg_epaymenttransdetails b 
							 on a.deptreferencecode = b.deptreferencecode 						 
							 and a.chlnrefnum  = b.chlnrefnum
							 where a.totalamount > 0   
							and a.deptreferencecode = _deptreferencecode
						order by totalamount
					)
						
						
						
		loop 
			if(v_amount > 0) then
				v_paidamount = upd_amnt_row.totalamount;			
				if (v_amount > 0 and v_amount < v_paidamount) then
					v_paidamount:=v_amount;
				end if;				
				
				update kaveri.ams_reg_epaymentamtpaiddetails a  
				set amountpaid = v_paidamount
				where chlnrefnum = upd_amnt_row.chlnrefnum and 
				a.deptreferencecode = upd_amnt_row.deptreferencecode ;
				
				
				-- To update the Fees paid status 
			update kaveri.feesrequired a
			set 
				paymentstatus = 'Challan Success'
			where  
			    a.applicationnumber =  upd_amnt_row.applicationnumber
			and documentid = upd_amnt_row.documentid 
			and feerulecode = upd_amnt_row.feerulecode ;
		 
		 v_amount = v_amount-v_paidamount;
			end if;			
		end loop;	
	end if;

end if;
--return v_deptrefcode;
return query

select distinct a.deptreferencecode,a.applicationnumber,b.applicationtypeid,e.servicename as applicationtype,
b.srocode,d.sronamee,
f.descriptione||' '||c.firstname||' '||c.middlename||' '||c.lastname as presentername
from 
	kaveri.ams_reg_epaymentamtpaiddetails a 
left join
	kaveri.applicantapplicationdetails b
on a.applicationnumber = b.applicationnumber
left join kaveri.partyinfo c on b.applicationnumber = c.applicationnumber and 
			b.srocode = c.srocode and ispresenter=true
left join kaveri.sromaster d on c.srocode = d.srocode
left join kaveri.servicesmaster e on b.applicationtypeid = e.serviceid
left join kaveri.salutationmaster f on c.salutationid = f.salutationid
where a.deptreferencecode = _deptreferencecode;

   END;
$$;


ALTER FUNCTION kaveri.fn_save_pending_paymentgateway(_banktransactionnumber character varying, _amount bigint, _deptreferencecode character varying, _paymentstatuscode character varying, _bankname character varying, _paymentmode character varying, _transactiontimestamp timestamp without time zone, _checksum character varying) OWNER TO csgadmin;

--
-- Name: fn_save_post_in_office(integer, integer, text, integer, integer, text); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_save_post_in_office(_createdby integer, _designationid integer, _postdescription text, _officetypeid integer, _officeid integer, _supportingdocpath text) RETURNS integer
    LANGUAGE plpgsql
    AS $$

DECLARE

v_postid integer;
v_count integer;

BEGIN 
	
	select count(*) into v_count from  kaveri.post_office_details where 
	officeid=_officeid and designationid=_designationid and officetypeid=_officetypeid;
	
	if v_count>0 then 
	  
		v_postid=0;
	ELSE
	
	 insert into kaveri.post_office_details(createdby,postid,designationid,postdescription,officetypeid,officeid,supportingdocpath)
	 values(_createdby,nextval('kaveri.postid_seq'::regclass),_designationid,_postdescription,_officetypeid,_officeid,_supportingdocpath)
	 returning postid into v_postid;
	 
	 end if;
	 
	 return v_postid;

	

END;

$$;


ALTER FUNCTION kaveri.fn_save_post_in_office(_createdby integer, _designationid integer, _postdescription text, _officetypeid integer, _officeid integer, _supportingdocpath text) OWNER TO csgadmin;

--
-- Name: fn_save_rescandetails(kaveri.rescandetails_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_save_rescandetails(kaveri.rescandetails_input[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $_$
DECLARE
   id_val bigint;
   fees_arry $1%type;
    v_txt text;
   v_documentid bigint;
   v_cnt integer;
   var_r record;
   v_pid bigint[];
BEGIN
  FOR fees_arry IN (SELECT kaveri.fn_fetch_1d_arrayofarray($1))
     loop
	 
   Select count(*) into v_cnt from kaveri.rescandetails where (coalesce(documentid,0)) in 
(select coalesce(a.documentid,0) from unnest(fees_arry) a);

  if v_cnt = 0 then
INSERT INTO kaveri.rescandetails(
	documentid,
	documenttypeid,
	backuppath,
    filename,
	istransmitted,
	isuploaded
) select 
	documentid,
	documenttypeid,
	backuppath,
    filename,
	True,
	True
 from unnest(fees_arry)						 
    RETURNING documentid::bigint into id_val;
	else
update kaveri.rescandetails set
	documentid=a.documentid,
	documenttypeid=a.documenttypeid,
	backuppath=a.backuppath,
    filename=a.filename
	from unnest(fees_arry) a
	where coalesce(documentid,0) in 
   (select coalesce(a.documentid,0) from unnest(fees_arry) a) 
RETURNING documentid::bigint into id_val;
    end if;
	 v_pid := array_append(v_pid,id_val);
    end loop;
	return v_pid;
end;
$_$;


ALTER FUNCTION kaveri.fn_save_rescandetails(kaveri.rescandetails_input[]) OWNER TO csgadmin;

--
-- Name: fn_save_roadmaster(bigint, character varying, character varying, bigint, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_save_roadmaster(_roadcode bigint, _roadnamee character varying, _roadnamek character varying, _villagecode bigint, _regionid integer) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE 
v_roadcode bigint;
v_cnt integer;
begin

select count(*) into v_cnt from kaveri.roadmaster where roadcode in (select roadcode from kaveri.roadmaster where roadnamee = _roadnamee) and villagecode = _villagecode;

if v_cnt = 0 then
insert into kaveri.roadmaster(
roadcode,
roadnamee,
roadnamek,
villagecode,
regionid 
) values (
nextval('kaveri.roadcode_seq'),
_roadnamee,
_roadnamek,
_villagecode,
_regionid)
returning roadcode into v_roadcode;
else
update kaveri.roadmaster set roadnamee = _roadnamee, roadnamek = _roadnamek,
villagecode = _villagecode,regionid = _regionid
where roadcode = (select roadcode from kaveri.roadmaster where roadnamee = _roadnamee and regionid = _regionid) returning roadcode into v_roadcode;
end if;
return v_roadcode;
end;
$$;


ALTER FUNCTION kaveri.fn_save_roadmaster(_roadcode bigint, _roadnamee character varying, _roadnamek character varying, _villagecode bigint, _regionid integer) OWNER TO postgres;

