--
-- Name: fn_sro_approval(integer, timestamp without time zone, character varying, text, text); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_sro_approval(_srocode integer, _executiondatetime timestamp without time zone, _applicationnumber character varying, _deedattachpath text, _annexurepath text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$

declare
v_applicationnumber character varying;
v_documentid bigint;
v_cnt integer;
v_bookid integer;
v_regarticlecode integer;
v_pagecount integer;
_movable boolean default true;
--_vararry bigint;
_minval int;
v_movableproperty boolean;
v_stampruleid bigint;
_varbookid bigint;
v_stamparticlecode integer;
v_feecount integer;
v_isgricnt int;
v_jsrocode bigint;
v_propertyids bigint;
v_propnum_inval_count int;
v_propnumcheck_inval_count int;
v_bookids int;
v_currentstatus character varying;
v_ispaperless bool;
begin
begin

select documentid into v_documentid from kaveri.documentmaster where applicationnumber = _applicationnumber limit 1;
exception when no_data_found then
	v_documentid = 0;
end;

select currentstatus into  v_currentstatus 	from kaveri.applicantapplicationdetails a where applicationnumber =_applicationnumber;

select count(*) into v_propnum_inval_count from kaveri.propertynumberdetails p 
join kaveri.propertymaster p1 on p.propertyid = p1.propertyid 
where p1.applicationnumber = _applicationnumber and 
 (p.currentnumber = '' or p.currentnumber is null);
 
 select count(*) into v_propnumcheck_inval_count from kaveri.propertynumberdetails p 
join kaveri.propertymaster p1 on p.propertyid = p1.propertyid 
join kaveri.stamprulesflag s on p1.stampruleid =s.stampruleid
--join kaveri.documentmaster dm on p1.applicationnumber =dm.applicationnumber 
where p1.applicationnumber = _applicationnumber and 
(case when s.isprevregddocnoreqd=false then
(p.currentnumber is not null and  p.currentpropertytypeid  in (65,67,59,60,1)) 
else
p.currentpropertytypeid not in (65,67,59,60,1)  end) ;

select a.bookid into v_bookids from kaveri.applicantapplicationdetails a where a.applicationnumber=_applicationnumber;


if(v_currentstatus='CD101' and (v_propnum_inval_count>0 or v_propnumcheck_inval_count=0) and v_bookids=1)
then
raise exception 'failed to submit, invalid application ';
else 

select stamparticlecode into v_stamparticlecode from kaveri.propertymaster
where applicationnumber =_applicationnumber;
	
if (v_stamparticlecode = 14) then
	select bookid into v_bookid from kaveri.k1documentdetails where applicationnumber = _applicationnumber ;

	if (v_bookid is null) then 
		for v_movableproperty,v_stampruleid,v_regarticlecode  --, v_stamparticlecode
			in select ismovableproperty,stampruleid,regarticlecode  --, stamparticlecode
			from kaveri.propertymaster where applicationnumber =_applicationnumber loop

			if(v_movableproperty=false) then
				_movable = false;
			end if;
			select bookid into _varbookid from kaveri.stamprules where stampruleid=v_stampruleid ;
	--		_vararry=_varbookid;
		end loop;
		select min(bookid) into _minval from kaveri.stamprules where stampruleid=v_stampruleid;
		if(_movable=True and _minval=1) then
			v_bookid=4;
		else 
			v_bookid=_minval;
		end if;
	end if;
else 
	for v_movableproperty,v_stampruleid,v_regarticlecode  --, v_stamparticlecode
		in select ismovableproperty,stampruleid,regarticlecode  --, stamparticlecode
		from kaveri.propertymaster where applicationnumber =_applicationnumber loop

		if(v_movableproperty=false) then
			_movable = false;
		end if;
		select bookid into _varbookid from kaveri.stamprules where stampruleid=v_stampruleid ;
--		_vararry=_varbookid;
	end loop;
	select min(bookid) into _minval from kaveri.stamprules where stampruleid=v_stampruleid;
	if(_movable=True and _minval=1)
	then
		v_bookid=4;
	else 
		v_bookid=_minval;
	end if;
end if;

	
if (v_documentid = 0  or v_documentid is null)  then

	select distinct  pm.regarticlecode, pm.noofscanpages into v_regarticlecode,v_pagecount 
	from kaveri.propertymaster pm inner join kaveri.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
		where pm.applicationnumber = _applicationnumber limit 1;
	
	insert into kaveri.documentmaster
	 (  documentid,srocode, bookid,regarticlecode,
		 executiondatetime,pagecount,applicationnumber
	 ) values ( nextval('kaveri.document_seq'),
	 _srocode,v_bookid,v_regarticlecode,
	 _executiondatetime,v_pagecount,_applicationnumber ) returning documentid into v_documentid;
	 
	 if not found then 
		raise exception 'Something went wrong! DocumentMaster insertion failed.'; 
	end if;
	  
	update kaveri.applicantapplicationdetails set regarticlecode=coalesce(regarticlecode,v_regarticlecode) 
	where applicationnumber = _applicationnumber ;
	if not found then 
		raise exception 'Something went wrong! ApplicantApplicationDetails updation failed.'; 
	end if;
else
	update kaveri.documentmaster set
	srocode= _srocode, 
	executiondatetime=_executiondatetime 
	where applicationnumber=_applicationnumber
	returning documentid into v_documentid;
 end if; 

update kaveri.partyinfo set documentid = v_documentid,srocode=_srocode where applicationnumber = _applicationnumber ; 
if not found then 
	raise exception 'Something went wrong! PartyInfo updation failed.'; 
end if;

update kaveri.propertymaster set documentid = v_documentid,regsrocode=_srocode where applicationnumber = _applicationnumber ;
if not found then 
	raise exception 'Something went wrong! PropertyMaster updation failed.'; 
end if;

--select count(*) into v_isgricnt from kaveri.propertymaster p where propertytypeid =17 and applicationnumber = _applicationnumber;

select count(*) into v_isgricnt from kaveri.propertymaster p 
join kaveri.stamprulesflag s on p.stampruleid = s.stampruleid
where propertytypeid =17 and s.isprevregddocnoreqd = false and applicationnumber = _applicationnumber;


if (v_isgricnt>0)
then
update kaveri.orgdatajslip set documentid=v_documentid where applicationnumber = _applicationnumber ;
if not found then 
	raise exception 'Something went wrong! OrgDataJslip updation failed.'; 
end if;
end if;


for v_propertyids,v_jsrocode in (select propertyid,srocode from kaveri.propertymaster where applicationnumber=_applicationnumber)
loop
update kaveri.propertyschedules set srocode=v_jsrocode where propertyid = v_propertyids;
end loop;
-- need to uncomment the srocode update once the functionality is present 
update kaveri.witnessinfo set documentid = v_documentid, srocode=_srocode where applicationnumber = _applicationnumber ;

-- partywitness need to be updated with the same srocode during document for approval
update kaveri.partywitness set srocode = _srocode where witnessid in 
(select witnessid from kaveri.witnessinfo where applicationnumber = _applicationnumber);

select count(*) into v_feecount from kaveri.feesrequired where applicationnumber=_applicationnumber; 
if v_feecount>0 then
	update kaveri.feesrequired set documentid = v_documentid,srocode=_srocode where applicationnumber = _applicationnumber ;
	if not found then 
		raise exception 'Something went wrong! FeesRequired updation failed.'; 
	end if;
end if;
 --srocode update should be removed later
update kaveri.mojanixml set documentid = v_documentid,srocode=_srocode where propertyid in (select propertyid from kaveri.propertymaster
where applicationnumber = _applicationnumber) ;

update kaveri.bhoomixmllog set documentid = v_documentid,srocode=_srocode where propertyid in (select propertyid from kaveri.propertymaster
where applicationnumber = _applicationnumber) ;
 
update kaveri.applicantapplicationdetails set currentstatus = 'CD102'
,bookid=v_bookid,regarticlecode= v_regarticlecode
,regsrocode=_srocode,srocode=_srocode,issubmitted=true,isduecorrection=false
,deedattachpath=_deedattachpath,annexurepath=_annexurepath
,APPLICATIONDATE = current_timestamp,lastupdatedby=citizenid::text where applicationnumber = _applicationnumber;

-- paperless change
SELECT ispaperless INTO v_ispaperless FROM kaveri.vw_fetch_paperless_trans WHERE srocode = _srocode LIMIT 1;
IF v_ispaperless = TRUE THEN
	update kaveri.applicantapplicationdetails set ispaperless = true where applicationnumber = _applicationnumber;
END IF;

end if;
return v_documentid;
end;
$$;


ALTER FUNCTION kaveri.fn_sro_approval(_srocode integer, _executiondatetime timestamp without time zone, _applicationnumber character varying, _deedattachpath text, _annexurepath text) OWNER TO csgadmin;

--
-- Name: fn_sro_approval(bigint, integer, integer, integer, integer, integer, character varying, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, integer, character varying, boolean, boolean, boolean, boolean, boolean, boolean, boolean, boolean, timestamp without time zone, character varying, character varying, character varying, bigint, character varying, character varying, character varying, boolean, integer, character varying, boolean, boolean, timestamp without time zone, boolean, numeric, numeric, numeric, character varying, character varying, boolean, character varying, text); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_sro_approval(_documentid bigint, _srocode integer, _bookid integer, _stamparticlecode integer, _regarticlecode integer, _documentnumber integer, _finalregistrationnumber character varying, _presentdatetime timestamp without time zone, _executiondatetime timestamp without time zone, _dateofstamp timestamp without time zone, _stamp1datetime timestamp without time zone, _stamp2datetime timestamp without time zone, _stamp3datetime timestamp without time zone, _stamp4datetime timestamp without time zone, _stamp5datetime timestamp without time zone, _withdrawaldate timestamp without time zone, _pagecount integer, _index2shera character varying, _isvisited boolean, _isfiling boolean, _ispending boolean, _isscanned boolean, _isrefused boolean, _ispaymentofmoney boolean, _isadjudicated boolean, _iswithdrawn boolean, _refusaldate timestamp without time zone, _refusalreason character varying, _remarksbyuser character varying, _remarksbysystem character varying, _correctionreference bigint, _olddocreference character varying, _adjudicationdetails character varying, _cdnumber character varying, _isxmltransferredtobhoomi boolean, _uid integer, _pendingdocumentnumber character varying, _istransmitted boolean, _isphotothumbtransmitted boolean, _inserteddatetime timestamp without time zone, _initialtransmitted boolean, _considerationamount numeric, _requiredstampduty numeric, _paidstampduty numeric, _documentstatus character varying, _applicationnumber character varying, _verified boolean, _issroapproved character varying, _deedattachpath text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare
_cnt integer;
v_applicationnumber character varying;
v_documentid bigint;
v_cnt integer;
--v_documentid bigint;
--v_cnt integer;
_movable boolean default true;
--_vararry bigint;
_minval int;
v_bookid int;
v_movableproperty boolean;
v_stampruleid bigint;
_varbookid bigint;
v_regarticlecode bigint;
v_feecount integer;
v_jsrocode bigint;
v_propertyids bigint;
v_currentstatus character varying;
v_propnum_inval_count int;
v_propnumcheck_inval_count int;
v_bookids int;
begin
	
select currentstatus into  v_currentstatus 	from kaveri.applicantapplicationdetails a where applicationnumber =_applicationnumber;

select count(*) into v_propnum_inval_count from kaveri.propertynumberdetails p 
join kaveri.propertymaster p1 on p.propertyid = p1.propertyid 
where p1.applicationnumber = _applicationnumber and 
 (p.currentnumber = '' or p.currentnumber is null);

select a.bookid into v_bookids from kaveri.applicantapplicationdetails a where a.applicationnumber=_applicationnumber;

 
 select count(*) into v_propnumcheck_inval_count from kaveri.propertynumberdetails p 
join kaveri.propertymaster p1 on p.propertyid = p1.propertyid 
join kaveri.stamprulesflag s on p1.stampruleid =s.stampruleid
--join kaveri.documentmaster dm on p1.applicationnumber =dm.applicationnumber 
where p1.applicationnumber = _applicationnumber and 
(case when s.isprevregddocnoreqd=false then
(p.currentnumber is not null and  p.currentpropertytypeid  in (65,67,59,60,1)) 
else
p.currentpropertytypeid not in (65,67,59,60,1)  end) ;

if(v_currentstatus='CD101' and  (v_propnum_inval_count>0 or v_propnumcheck_inval_count=0) and v_bookids=1)
then	

	raise exception 'invalid application failed to submit';
else 

	for v_movableproperty,v_stampruleid,v_regarticlecode in select ismovableproperty,stampruleid,regarticlecode  from kaveri.propertymaster
	where applicationnumber =_applicationnumber
	loop
		if(v_movableproperty=false)
		then
		_movable = false;
		end if;
		select bookid into _varbookid from kaveri.stamprules where stampruleid=v_stampruleid ;
--		_vararry=_varbookid;
	end loop;
		 if(_movable=True)
		then
		v_bookid=4;
		else 
		select min(bookid) into _minval from kaveri.stamprules where stampruleid=v_stampruleid;
		v_bookid=_minval;
		end if;

select count(*) into v_cnt from kaveri.documentmaster where documentid = _documentid;
if v_cnt = 0 then
insert into kaveri.documentmaster
 ( 
documentid,
 srocode, 
 bookid, 
 stamparticlecode, 
 regarticlecode, 
 documentnumber, 
 finalregistrationnumber, 
 presentdatetime, 
 executiondatetime, 
 dateofstamp, 
 stamp1datetime, 
 stamp2datetime, 
 stamp3datetime, 
 stamp4datetime, 
 stamp5datetime, 
 withdrawaldate, 
 pagecount, 
 index2shera, 
 isvisited, 
 isfiling, 
 ispending, 
 isscanned, 
 isrefused, 
 ispaymentofmoney, 
 isadjudicated, 
 iswithdrawn, 
 refusaldate, 
 refusalreason, 
 remarksbyuser, 
 remarksbysystem, 
 correctionreference, 
 olddocreference, 
 adjudicationdetails, 
 cdnumber, 
 isxmltransferredtobhoomi, 
 uid, 
 pendingdocumentnumber, 
 istransmitted, 
 isphotothumbtransmitted, 
 inserteddatetime, 
 initialtransmitted, 
 considerationamount, 
 requiredstampduty, 
 paidstampduty, 
 documentstatus, 
 applicationnumber, 
 verified, 
 issroapproved,
 deedattachpath
 ) values (
 nextval('kaveri.document_seq'),
 _srocode, 
 v_bookid, 
 _stamparticlecode, 
 v_regarticlecode, 
 _documentnumber, 
 _finalregistrationnumber, 
 _presentdatetime, 
 _executiondatetime, 
 _dateofstamp, 
 _stamp1datetime, 
 _stamp2datetime, 
 _stamp3datetime, 
 _stamp4datetime, 
 _stamp5datetime, 
 _withdrawaldate, 
 _pagecount, 
 _index2shera, 
 _isvisited, 
 _isfiling, 
 _ispending, 
 _isscanned, 
 _isrefused, 
 _ispaymentofmoney, 
 _isadjudicated, 
 _iswithdrawn, 
 _refusaldate, 
 _refusalreason, 
 _remarksbyuser, 
 _remarksbysystem, 
 _correctionreference, 
 _olddocreference, 
 _adjudicationdetails, 
 _cdnumber, 
 _isxmltransferredtobhoomi, 
 _uid, 
 _pendingdocumentnumber, 
 _istransmitted, 
 _isphotothumbtransmitted, 
 _inserteddatetime, 
 _initialtransmitted, 
 _considerationamount, 
 _requiredstampduty, 
 _paidstampduty, 
 _documentstatus, 
 _applicationnumber, 
 _verified, 
 _issroapproved,
 _deedattachpath
  ) returning documentid into v_documentid;
  else
  
  update kaveri.documentmaster set
 srocode= _srocode, 
 bookid=v_bookid, 
 stamparticlecode=_stamparticlecode, 
 regarticlecode=v_regarticlecode, 
 documentnumber=_documentnumber, 
 finalregistrationnumber=finalregistrationnumber, 
 presentdatetime=_presentdatetime, 
 executiondatetime=_executiondatetime, 
 dateofstamp=_dateofstamp, 
 stamp1datetime=_stamp1datetime, 
 stamp2datetime=_stamp2datetime, 
 stamp3datetime=_stamp3datetime, 
 stamp4datetime=_stamp4datetime, 
 stamp5datetime=_stamp5datetime, 
 withdrawaldate=_withdrawaldate, 
 pagecount=_pagecount, 
 index2shera=_index2shera, 
 isvisited=_isvisited, 
 isfiling=_isfiling, 
 ispending=_ispending, 
 isscanned=_isscanned, 
 isrefused=_isrefused, 
 ispaymentofmoney=_ispaymentofmoney, 
 isadjudicated=_isadjudicated, 
 iswithdrawn=_iswithdrawn, 
 refusaldate=_refusaldate, 
 refusalreason=_refusalreason, 
 remarksbyuser=_remarksbyuser, 
 remarksbysystem=_remarksbysystem, 
 correctionreference=_correctionreference, 
 olddocreference=_olddocreference, 
 adjudicationdetails=_adjudicationdetails, 
 cdnumber=_cdnumber, 
 isxmltransferredtobhoomi=_isxmltransferredtobhoomi, 
 uid=_uid, 
 pendingdocumentnumber=_pendingdocumentnumber, 
 istransmitted=_istransmitted, 
 isphotothumbtransmitted=_isphotothumbtransmitted, 
 inserteddatetime=_inserteddatetime, 
 initialtransmitted=_initialtransmitted, 
 considerationamount=_considerationamount, 
 requiredstampduty=_requiredstampduty, 
 paidstampduty=_paidstampduty, 
 documentstatus=_documentstatus, 
 applicationnumber=_applicationnumber, 
 verified=_verified, 
 issroapproved=_issroapproved, 
 deedattachpath=_deedattachpath where documentid = _documentid
 returning documentid into v_documentid;
 end if;
 --if v_cnt = 1 then
 --srocode update should be removed later
 
 
update kaveri.partyinfo set documentid = v_documentid,srocode=_srocode where applicationnumber = _applicationnumber; 
 if not found then 
		raise exception 'Something went wrong! partyinfo insertion failed.'; 
	end if;

update kaveri.propertymaster set documentid = v_documentid,srocode=_srocode where applicationnumber = _applicationnumber; 
 if not found then 
		raise exception 'Something went wrong! propertymaster insertion failed.'; 
	end if;
	
-- need to uncomment the srocode update once the functionality is present 
update kaveri.witnessinfo set 
documentid = v_documentid,
srocode=_srocode 
where applicationnumber = _applicationnumber;

-- partywitness need to be updated with the same srocode during document for approval
update kaveri.partywitness set srocode = _srocode where witnessid in 
(select witnessid from kaveri.witnessinfo where applicationnumber = _applicationnumber);

for v_propertyids,v_jsrocode in (select propertyid,srocode from kaveri.propertymaster where applicationnumber=_applicationnumber)
loop
update kaveri.propertyschedules set srocode=v_jsrocode where propertyid=v_propertyids;--applicationnumber = _applicationnumber;
end loop;

select count(*) into v_feecount from kaveri.feesrequired where applicationnumber=_applicationnumber; 
if v_feecount>0 then
update kaveri.feesrequired set documentid = v_documentid,srocode=_srocode where applicationnumber = _applicationnumber;
if not found then 
		raise exception 'Something went wrong! FeesRequired updation failed.'; 
	end if;
end if;
--srocode update should be removed later

