-- Name: fn_transfer_dept_user(integer, integer, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_transfer_dept_user(_userid integer, _newofficeid integer, _doj_new_office timestamp without time zone, _designationid integer, _updatedby integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$



DECLARE

v_count integer;
v_success integer;
v_srocode bigint;
v_temp_record record;
v_officetypeid integer;
v_loginname text;
BEGIN 

 select loginname into v_loginname from kaveri.departmentusers d where userid=_userid;
--SELECT  regexp_replace(v_loginname,'^\d+', '') AS login_name into v_loginname;
  select officetypeid  into v_officetypeid from kaveri.mas_officemaster  where officeid=_newofficeid;
  
  if v_officetypeid < 3 then
    select srocode into v_srocode from kaveri.sromaster where districtcode=
	(select  districtid from kaveri.mas_officemaster mo where officeid=_newofficeid ) limit 1;
  ELSE
	select  kavericode into v_srocode from kaveri.mas_officemaster mo where officeid=_newofficeid;

 end if;

 
  select count(*) into v_count from kaveri.departmentusers where userid=_userid;
  if v_count=1 then 
	select * into v_temp_record from kaveri.departmentusers where userid=_userid;
	--insert previous service history
	--office1
   --select v_srocode||v_loginname into v_loginname;
	update kaveri.departmentusers_service_history set isactive=false where userid=_userid;
	insert into kaveri.departmentusers_service_history(userid,srocode,designationid,updatedby,officeid,servicestartdate,serviceexpdate,employeetypeid,isactive)
	values(_userid,v_temp_record.srocode,v_temp_record.designationid,_updatedby,v_temp_record.officeid,v_temp_record.doj,current_date,v_temp_record.employeetypeid,true);
   update kaveri.departmentusers
   set srocode=v_srocode,doj=_doj_new_office,officeid=_newofficeid,designationid=_designationid,createdby=_updatedby,
   loginname=v_loginname
   where userid=_userid; --office2
   v_success=1;
   
   ELSE
   
   
   v_success=0;
   
   end if;
    
   
 
return v_success;
END;

$$;


ALTER FUNCTION kaveri.fn_transfer_dept_user(_userid integer, _newofficeid integer, _doj_new_office timestamp without time zone, _designationid integer, _updatedby integer) OWNER TO csgadmin;

--
-- Name: fn_transfer_dept_user_deo(integer, integer, integer, integer, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_transfer_dept_user_deo(from_userid integer, to_userid integer, from_officeid integer, _newofficeid integer, _doj_new_office timestamp without time zone, _designationid integer, _updatedby integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$



DECLARE

v_fromdistrictcode integer;
v_todistrictcode integer;
v_success integer;
v_srocode bigint;
v_temp_record record;
v_from_record kaveri.departmentusers%rowtype;
v_to_record kaveri.departmentusers%rowtype;
v_officetypeid integer;

BEGIN 

--	Fetching from to and Office details
	select * into v_from_record from kaveri.departmentusers where userid=from_userid;


if found then 

	select * into v_to_record from kaveri.departmentusers where userid= to_userid;



if found then 
  	

select districtcode into v_fromdistrictcode  from kaveri.sromaster s where srocode =  v_from_record.srocode ; 
select districtcode into v_todistrictcode  from kaveri.sromaster s where srocode =  v_to_record.srocode; 

-- Inserting DEO details after user's service history entry



insert
	into
	kaveri.departmentusers_deo_service_history(
	from_userid,
	from_srocode,
	from_designationid,
	from_officeid,
	from_firstname,
	from_lastname,
	from_middlename,
	from_phone,
	to_userid,
	to_srocode,
	to_designationid,
	to_officeid,
	to_firstname,
	to_lastname,
	to_middlename,
	to_phone,
	updatedby,
	employeetypeid,
	servicestartdate,
	serviceexpdate,
	istransfer,
	from_districtcode,
	to_districtcode)
values(from_userid,
v_from_record.srocode,
v_from_record.designationid,
v_from_record.officeid,
v_from_record.firstname,
v_from_record.lastname,
v_from_record.middlename,
v_from_record.mobileno,
to_userid,
v_to_record.srocode,
v_to_record.designationid,
v_to_record.officeid,
v_to_record.firstname,
v_to_record.lastname,
v_to_record.middlename,
v_to_record.mobileno,
_updatedby,
v_from_record.employeetypeid,
_doj_new_office,
current_date,
true,
v_fromdistrictcode,
v_todistrictcode);

-- Updating To-Office details with 
update
	kaveri.departmentusers
set
	doj = _doj_new_office,
	createdby = _updatedby,
	firstname = v_from_record.firstname,
	middlename = v_from_record.middlename,
	lastname = v_from_record.lastname,
	mobileno = v_from_record.mobileno,
	isactive = true
   --serviceflag = true
   where userid = to_userid; --office2
      
   -- Updating from -Office details - disabling existing  id
update
	kaveri.departmentusers
set
	isactive = false
   
   where userid = from_userid;

   v_success=1;
   
   ELSE
   
   raise notice'Not able to find v_to_record ' ;
   v_success=0;
   
   end if;
  
ELSE
   
   raise notice'Not able to find v_from_record ' ;
  v_success=0;
  end if;
   
return v_success;
END;

$$;


ALTER FUNCTION kaveri.fn_transfer_dept_user_deo(from_userid integer, to_userid integer, from_officeid integer, _newofficeid integer, _doj_new_office timestamp without time zone, _designationid integer, _updatedby integer) OWNER TO postgres;

--
-- Name: fn_upd_application_status(character varying, text, text, integer, integer, text, text, kaveri.application_reviewdetails_input[], kaveri.application_verification_input[]); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_upd_application_status(p_applicationnumber character varying, p_currentstatus text, p_lastupdatedby text, p_sfdaid integer DEFAULT NULL::integer, p_deoid integer DEFAULT NULL::integer, p_remarks text DEFAULT NULL::text, p_remarksk text DEFAULT NULL::text, p_reviewdetails kaveri.application_reviewdetails_input[] DEFAULT NULL::kaveri.application_reviewdetails_input[], p_verification kaveri.application_verification_input[] DEFAULT NULL::kaveri.application_verification_input[]) RETURNS text
    LANGUAGE plpgsql
    AS $$
declare
v_applicationnumber character varying;
v_applicationnumberreview character varying;
v_applicationnumberverification character varying;
v_isduecorrection boolean default null;
v_appointmentid bigint;
status_count integer;
v_apptype int;
begin

--SELECT COUNT(*)
--      INTO status_count
--      FROM kaveri.validworkflowmaster
--     WHERE currentstatus = (select currentstatus from kaveri.applicantapplicationdetails where applicationnumber = p_applicationnumber) and validstatus = p_currentstatus;
-- 
--if(status_count = 0) then
--	return 'Invalid status code change';
--end if;

if exists(select applicationnumber from kaveri.applicantapplicationdetails where applicationnumber =p_applicationnumber and applicationtypeid = 1) then
	SELECT COUNT(*)
	      INTO status_count
	      FROM kaveri.validworkflowmaster
	     WHERE currentstatus = (select currentstatus from kaveri.applicantapplicationdetails where applicationnumber = p_applicationnumber) and validstatus = p_currentstatus; --and env = 'PreProd';
	if(status_count = 0) then
		return 'Invalid status code change';
	end if;
end if;

select appointmentid into v_appointmentid from kaveri.appointmentmaster a where applicationnumber =p_applicationnumber order by appointmentdate desc limit 1;

	if(p_reviewdetails is not null and array_length(p_reviewdetails,1) > 0) then
		select kaveri.fn_insert_appreviewdetails(p_reviewdetails) into v_applicationnumberreview;
		begin
		select 'true' into v_isduecorrection where
		exists(select sr.isverified,sr.remarks,sr.deptuserid,sr.crtdate 
			from (select * from kaveri.applicationreviewdetails  
			where applicationnumber= p_applicationnumber and coalesce(issroremarks,'true')='true' 
			 order by crtdate desc limit 8) sr 
			where coalesce(sr.issroremarks,'true')='true' and sr.isverified ='false');
			   exception when no_data_found then 
			   v_isduecorrection := 'false';
		end;
		if(v_isduecorrection is null) then 
		  v_isduecorrection := 'false';
		 end if; 
	end if;
	
	if(p_verification is not null and array_length(p_verification,1) > 0) then
		select kaveri.fn_insert_appverification(p_verification) into v_applicationnumberverification;
	end if;

	
if(p_sfdaid is not null and p_sfdaid > 0) then
	update kaveri.applicantapplicationdetails
	set currentstatus = p_currentstatus,
	lastupdatedby = p_lastupdatedby,
	remarks = coalesce(p_remarks,remarks),
	remarksk = coalesce(p_remarksk,remarksk), --- To update the Kannada text added on 28-11-2022
	sfdaid=p_sfdaid,
	assignedto=p_sfdaid::text
	where applicationnumber = p_applicationnumber returning applicationnumber into v_applicationnumber;
elsif(p_deoid is not null and p_deoid > 0) then
	update kaveri.applicantapplicationdetails
	set currentstatus = p_currentstatus,
	lastupdatedby = p_lastupdatedby,
	remarks = coalesce(p_remarks,remarks),
	remarksk = coalesce(p_remarksk,remarksk), --- To update the Kannada text added on 28-11-2022
	deoid=p_deoid,
	assignedto=p_deoid::text
	where applicationnumber = p_applicationnumber returning applicationnumber into v_applicationnumber;
elsif(p_currentstatus='CD115')then
	update kaveri.applicantapplicationdetails
	set currentstatus = p_currentstatus,lastupdatedby = p_lastupdatedby
	where applicationnumber = p_applicationnumber and currentstatus in ('CD112','CD113','CD114') returning applicationnumber into v_applicationnumber;
else
	update kaveri.applicantapplicationdetails
	set currentstatus = p_currentstatus,lastupdatedby = p_lastupdatedby,
	remarks = coalesce((case when p_currentstatus = 'CD109' THEN NULL ELSE p_remarks END ),remarks),
	remarksk = coalesce((case when p_currentstatus = 'CD109' THEN NULL ELSE p_remarksk END ),remarksk), --- To update the Kannada text added on 28-11-2022
	isduecorrection = coalesce(v_isduecorrection,isduecorrection)
	where applicationnumber = p_applicationnumber returning applicationnumber into v_applicationnumber;
end if;

if(p_currentstatus='CD134') THEN
	update kaveri.applicantapplicationdetails
	set bookid=2
	where applicationnumber = p_applicationnumber returning applicationnumber into v_applicationnumber;
end if;
if(p_currentstatus='CD105') THEN
	update kaveri.applicantapplicationdetails
	set currentstatus = 'CD106',lastupdatedby = p_lastupdatedby
	where applicationnumber = p_applicationnumber returning applicationnumber into v_applicationnumber;
end if;
if(p_currentstatus='CD109') THEN
	update kaveri.documentmaster set partypaymentdetails = p_remarks   --- To update the Kannada text added on 28-11-2022
	where applicationnumber = p_applicationnumber returning applicationnumber into v_applicationnumber;
	
	--- raghavendra -- 22-05-2024 appointment is expired while verifying SR
	update kaveri.appointmentmaster set status = '1' where applicationnumber= p_applicationnumber and appointmentid=v_appointmentid;
	
END IF;
if(p_currentstatus in ('CD120','CE110','CC109')) then
UPDATE kaveri.applicantapplicationdetails SET APPLICATIONENDDATE = current_timestamp,
registrationenddate=current_timestamp
where applicationnumber = p_applicationnumber;
END IF;

if(p_currentstatus in ('CD112','CD134','CD135','CD136')) then
	-- 16-05-2024, raghavendra; setting status as completed in appointmentmaster on summary approval
	update kaveri.appointmentmaster set status = '2' where applicationnumber= p_applicationnumber and status = '1' and appointmentid=v_appointmentid;
END IF;

if(p_currentstatus = 'BK114') then
	update kaveri.documentmaster set isdigitalsigned = true
	where applicationnumber = p_applicationnumber;
END IF;
return v_applicationnumber;
end;
$$;


ALTER FUNCTION kaveri.fn_upd_application_status(p_applicationnumber character varying, p_currentstatus text, p_lastupdatedby text, p_sfdaid integer, p_deoid integer, p_remarks text, p_remarksk text, p_reviewdetails kaveri.application_reviewdetails_input[], p_verification kaveri.application_verification_input[]) OWNER TO postgres;

--
-- Name: fn_upd_application_status_09022026(character varying, text, text, integer, integer, text, text, kaveri.application_reviewdetails_input[], kaveri.application_verification_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_upd_application_status_09022026(p_applicationnumber character varying, p_currentstatus text, p_lastupdatedby text, p_sfdaid integer DEFAULT NULL::integer, p_deoid integer DEFAULT NULL::integer, p_remarks text DEFAULT NULL::text, p_remarksk text DEFAULT NULL::text, p_reviewdetails kaveri.application_reviewdetails_input[] DEFAULT NULL::kaveri.application_reviewdetails_input[], p_verification kaveri.application_verification_input[] DEFAULT NULL::kaveri.application_verification_input[]) RETURNS text
    LANGUAGE plpgsql
    AS $$
declare
v_applicationnumber character varying;
v_applicationnumberreview character varying;
v_applicationnumberverification character varying;
v_isduecorrection boolean default null;
v_appointmentid bigint;
v_pendingcnt int;
v_rescanapp int;
begin
 
-- To handle pending applications
select count(*) into v_pendingcnt from kaveri.applicationaudit where applicationnumber=p_applicationnumber and wrkflowstatusid='CD119';
 
-- To handle rescan applications
select count(*) into v_rescanapp from kaveri.applicantapplicationdetails where applicationnumber=p_applicationnumber and currentstatus ='CD115';
 
 
if (p_currentstatus in ('CD101','CD102','CD103','CD104','CD105','CD106','CD107','CD107A')) then
	if exists
		(select 1 from kaveri.applicationaudit where applicationnumber = p_applicationnumber and wrkflowstatusid ='CD108')
		then
			raise notice 'Somthing went wrong, Application Already submitted to SR...';
	else
	
		select appointmentid into v_appointmentid from kaveri.appointmentmaster a where applicationnumber =p_applicationnumber order by appointmentdate desc limit 1;
		
			if(p_reviewdetails is not null and array_length(p_reviewdetails,1) > 0) then
				select kaveri.fn_insert_appreviewdetails(p_reviewdetails) into v_applicationnumberreview;
				begin
				select 'true' into v_isduecorrection where
				exists(select sr.isverified,sr.remarks,sr.deptuserid,sr.crtdate
					from (select * from kaveri.applicationreviewdetails  
					where applicationnumber= p_applicationnumber and coalesce(issroremarks,'true')='true'
					 order by crtdate desc limit 8) sr
					where coalesce(sr.issroremarks,'true')='true' and sr.isverified ='false');
					   exception when no_data_found then
					   v_isduecorrection := 'false';
				end;
				if(v_isduecorrection is null) then
				  v_isduecorrection := 'false';
				 end if;
			end if;
			
			if(p_verification is not null and array_length(p_verification,1) > 0) then
				select kaveri.fn_insert_appverification(p_verification) into v_applicationnumberverification;
			end if;
		
			
		if(p_sfdaid is not null and p_sfdaid > 0) then
			update kaveri.applicantapplicationdetails
			set currentstatus = p_currentstatus,
			lastupdatedby = p_lastupdatedby,
			remarks = coalesce(p_remarks,remarks),
			remarksk = coalesce(p_remarksk,remarksk), --- To update the Kannada text added on 28-11-2022
			sfdaid=p_sfdaid,
			assignedto=p_sfdaid::text
			where applicationnumber = p_applicationnumber returning applicationnumber into v_applicationnumber;
		elsif(p_deoid is not null and p_deoid > 0) then
			update kaveri.applicantapplicationdetails
			set currentstatus = p_currentstatus,
			lastupdatedby = p_lastupdatedby,
			remarks = coalesce(p_remarks,remarks),
			remarksk = coalesce(p_remarksk,remarksk), --- To update the Kannada text added on 28-11-2022
			deoid=p_deoid,
			assignedto=p_deoid::text
			where applicationnumber = p_applicationnumber returning applicationnumber into v_applicationnumber;
		elsif(p_currentstatus='CD115')then
			update kaveri.applicantapplicationdetails
			set currentstatus = p_currentstatus,lastupdatedby = p_lastupdatedby
			where applicationnumber = p_applicationnumber and currentstatus in ('CD112','CD113','CD114') returning applicationnumber into v_applicationnumber;
		else
			update kaveri.applicantapplicationdetails
			set currentstatus = p_currentstatus,lastupdatedby = p_lastupdatedby,
			remarks = coalesce((case when p_currentstatus = 'CD109' THEN NULL ELSE p_remarks END ),remarks),
			remarksk = coalesce((case when p_currentstatus = 'CD109' THEN NULL ELSE p_remarksk END ),remarksk), --- To update the Kannada text added on 28-11-2022
			isduecorrection = coalesce(v_isduecorrection,isduecorrection)
			where applicationnumber = p_applicationnumber returning applicationnumber into v_applicationnumber;
		end if;
		
		if(p_currentstatus='CD134') THEN
			update kaveri.applicantapplicationdetails
			set bookid=2
			where applicationnumber = p_applicationnumber returning applicationnumber into v_applicationnumber;
		end if;
		if(p_currentstatus='CD105') THEN
			update kaveri.applicantapplicationdetails
			set currentstatus = 'CD106',lastupdatedby = p_lastupdatedby
			where applicationnumber = p_applicationnumber returning applicationnumber into v_applicationnumber;
		end if;
		if(p_currentstatus='CD109') THEN
			update kaveri.documentmaster set partypaymentdetails = p_remarks   --- To update the Kannada text added on 28-11-2022
			where applicationnumber = p_applicationnumber returning applicationnumber into v_applicationnumber;
			
			--- raghavendra -- 22-05-2024 appointment is expired while verifying SR
			update kaveri.appointmentmaster set status = '1' where applicationnumber= p_applicationnumber and appointmentid=v_appointmentid;
			
		END IF;
		if(p_currentstatus in ('CD120','CE110','CC109')) then
		UPDATE kaveri.applicantapplicationdetails SET APPLICATIONENDDATE = current_timestamp,
		registrationenddate=current_timestamp
		where applicationnumber = p_applicationnumber;
		END IF;
		
		if(p_currentstatus in ('CD112','CD134','CD135','CD136')) then
			-- 16-05-2024, raghavendra; setting status as completed in appointmentmaster on summary approval
			update kaveri.appointmentmaster set status = '2' where applicationnumber= p_applicationnumber and status = '1' and appointmentid=v_appointmentid;
		END IF;
		
		if(p_currentstatus = 'BK114') then
			update kaveri.documentmaster set isdigitalsigned = true
			where applicationnumber = p_applicationnumber;
		END IF;
	end if;
else
	if((select wrkfloworder::int from kaveri.wrkflowmaster where wrkflowstatusid = p_currentstatus)<
	(select wrkfloworder::int from kaveri.wrkflowmaster where wrkflowstatusid in(
	select currentstatus from kaveri.applicantapplicationdetails where applicationnumber = p_applicationnumber and currentstatus not in ('CD115'))) and v_pendingcnt=0) then
		
		raise notice 'Something went wrong, Application can''t move Back...';
	elsif(v_rescanapp>0 and p_currentstatus not in ('CD112','CD116'))
	then
	raise notice 'Something went wrong, Application can''t move Back...';
	else
		select appointmentid into v_appointmentid from kaveri.appointmentmaster a where applicationnumber =p_applicationnumber order by appointmentdate desc limit 1;
		
			if(p_reviewdetails is not null and array_length(p_reviewdetails,1) > 0) then
				select kaveri.fn_insert_appreviewdetails(p_reviewdetails) into v_applicationnumberreview;
				begin
				select 'true' into v_isduecorrection where
				exists(select sr.isverified,sr.remarks,sr.deptuserid,sr.crtdate
					from (select * from kaveri.applicationreviewdetails  
					where applicationnumber= p_applicationnumber and coalesce(issroremarks,'true')='true'
					 order by crtdate desc limit 8) sr
					where coalesce(sr.issroremarks,'true')='true' and sr.isverified ='false');
					   exception when no_data_found then
					   v_isduecorrection := 'false';
				end;
				if(v_isduecorrection is null) then
				  v_isduecorrection := 'false';
				 end if;
			end if;
			
			if(p_verification is not null and array_length(p_verification,1) > 0) then
				select kaveri.fn_insert_appverification(p_verification) into v_applicationnumberverification;
			end if;
		
			
		if(p_sfdaid is not null and p_sfdaid > 0) then
			update kaveri.applicantapplicationdetails
			set currentstatus = p_currentstatus,
			lastupdatedby = p_lastupdatedby,
			remarks = coalesce(p_remarks,remarks),
			remarksk = coalesce(p_remarksk,remarksk), --- To update the Kannada text added on 28-11-2022
			sfdaid=p_sfdaid,
			assignedto=p_sfdaid::text
			where applicationnumber = p_applicationnumber returning applicationnumber into v_applicationnumber;
		elsif(p_deoid is not null and p_deoid > 0) then
			update kaveri.applicantapplicationdetails
			set currentstatus = p_currentstatus,
			lastupdatedby = p_lastupdatedby,
			remarks = coalesce(p_remarks,remarks),
			remarksk = coalesce(p_remarksk,remarksk), --- To update the Kannada text added on 28-11-2022
			deoid=p_deoid,
			assignedto=p_deoid::text
			where applicationnumber = p_applicationnumber returning applicationnumber into v_applicationnumber;
		elsif(p_currentstatus='CD115')then
			update kaveri.applicantapplicationdetails
			set currentstatus = p_currentstatus,lastupdatedby = p_lastupdatedby
			where applicationnumber = p_applicationnumber and currentstatus in ('CD112','CD113','CD114') returning applicationnumber into v_applicationnumber;
		else
			update kaveri.applicantapplicationdetails
			set currentstatus = p_currentstatus,lastupdatedby = p_lastupdatedby,
			remarks = coalesce((case when p_currentstatus = 'CD109' THEN NULL ELSE p_remarks END ),remarks),
			remarksk = coalesce((case when p_currentstatus = 'CD109' THEN NULL ELSE p_remarksk END ),remarksk), --- To update the Kannada text added on 28-11-2022
			isduecorrection = coalesce(v_isduecorrection,isduecorrection)
			where applicationnumber = p_applicationnumber returning applicationnumber into v_applicationnumber;
		end if;
		
		if(p_currentstatus='CD134') THEN
			update kaveri.applicantapplicationdetails
			set bookid=2
			where applicationnumber = p_applicationnumber returning applicationnumber into v_applicationnumber;
		end if;
		if(p_currentstatus='CD105') THEN
			update kaveri.applicantapplicationdetails
			set currentstatus = 'CD106',lastupdatedby = p_lastupdatedby
			where applicationnumber = p_applicationnumber returning applicationnumber into v_applicationnumber;
		end if;
		if(p_currentstatus='CD109') THEN
			update kaveri.documentmaster set partypaymentdetails = p_remarks   --- To update the Kannada text added on 28-11-2022
			where applicationnumber = p_applicationnumber returning applicationnumber into v_applicationnumber;
			
			--- raghavendra -- 22-05-2024 appointment is expired while verifying SR
			update kaveri.appointmentmaster set status = '1' where applicationnumber= p_applicationnumber and appointmentid=v_appointmentid;
			
		END IF;
		if(p_currentstatus in ('CD120','CE110','CC109')) then
		UPDATE kaveri.applicantapplicationdetails SET APPLICATIONENDDATE = current_timestamp,
		registrationenddate=current_timestamp
		where applicationnumber = p_applicationnumber;
		END IF;
		
		if(p_currentstatus in ('CD112','CD134','CD135','CD136')) then
			-- 16-05-2024, raghavendra; setting status as completed in appointmentmaster on summary approval
			update kaveri.appointmentmaster set status = '2' where applicationnumber= p_applicationnumber and status = '1' and appointmentid=v_appointmentid;
		END IF;
		
		if(p_currentstatus = 'BK114') then
			update kaveri.documentmaster set isdigitalsigned = true
			where applicationnumber = p_applicationnumber;
		END IF;
	end if;
end if;
return v_applicationnumber;
end;
$$;


