--
-- Name: fn_upd_application_status_20260202(character varying, text, text, integer, integer, text, text, kaveri.application_reviewdetails_input[], kaveri.application_verification_input[]); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_upd_application_status_20260202(p_applicationnumber character varying, p_currentstatus text, p_lastupdatedby text, p_sfdaid integer DEFAULT NULL::integer, p_deoid integer DEFAULT NULL::integer, p_remarks text DEFAULT NULL::text, p_remarksk text DEFAULT NULL::text, p_reviewdetails kaveri.application_reviewdetails_input[] DEFAULT NULL::kaveri.application_reviewdetails_input[], p_verification kaveri.application_verification_input[] DEFAULT NULL::kaveri.application_verification_input[]) RETURNS text
    LANGUAGE plpgsql
    AS $$
declare
v_applicationnumber character varying;
v_applicationnumberreview character varying;
v_applicationnumberverification character varying;
v_isduecorrection boolean default null;
v_appointmentid bigint;
begin

select appointmentid into v_appointmentid from kaveri.appointmentmaster a where applicationnumber =p_applicationnumber order by appointmentdate desc limit 1;

	if(p_reviewdetails is not null and array_length(p_reviewdetails,1) > 0) then
		select kaveri.fn_insert_appreviewdetails(p_reviewdetails) into v_applicationnumberreview;
		begin
		select 'true' into v_isduecorrection where
		exists(select sr.isverified,sr.remarks,sr.deptuserid,sr.crtdate 
			from (select * from kaveri.applicationreviewdetails  
			where applicationnumber= p_applicationnumber and coalesce(issroremarks,'true')='true' 
			 order by crtdate desc limit 8) sr 
			where coalesce(sr.issroremarks,'true')='true' and sr.isverified ='false');
			   exception when no_data_found then 
			   v_isduecorrection := 'false';
		end;
		if(v_isduecorrection is null) then 
		  v_isduecorrection := 'false';
		 end if; 
	end if;
	
	if(p_verification is not null and array_length(p_verification,1) > 0) then
		select kaveri.fn_insert_appverification(p_verification) into v_applicationnumberverification;
	end if;

	
if(p_sfdaid is not null and p_sfdaid > 0) then
	update kaveri.applicantapplicationdetails
	set currentstatus = p_currentstatus,
	lastupdatedby = p_lastupdatedby,
	remarks = coalesce(p_remarks,remarks),
	remarksk = coalesce(p_remarksk,remarksk), --- To update the Kannada text added on 28-11-2022
	sfdaid=p_sfdaid,
	assignedto=p_sfdaid::text
	where applicationnumber = p_applicationnumber returning applicationnumber into v_applicationnumber;
elsif(p_deoid is not null and p_deoid > 0) then
	update kaveri.applicantapplicationdetails
	set currentstatus = p_currentstatus,
	lastupdatedby = p_lastupdatedby,
	remarks = coalesce(p_remarks,remarks),
	remarksk = coalesce(p_remarksk,remarksk), --- To update the Kannada text added on 28-11-2022
	deoid=p_deoid,
	assignedto=p_deoid::text
	where applicationnumber = p_applicationnumber returning applicationnumber into v_applicationnumber;
elsif(p_currentstatus='CD115')then
	update kaveri.applicantapplicationdetails
	set currentstatus = p_currentstatus,lastupdatedby = p_lastupdatedby
	where applicationnumber = p_applicationnumber and currentstatus in ('CD112','CD113','CD114') returning applicationnumber into v_applicationnumber;
else
	update kaveri.applicantapplicationdetails
	set currentstatus = p_currentstatus,lastupdatedby = p_lastupdatedby,
	remarks = coalesce((case when p_currentstatus = 'CD109' THEN NULL ELSE p_remarks END ),remarks),
	remarksk = coalesce((case when p_currentstatus = 'CD109' THEN NULL ELSE p_remarksk END ),remarksk), --- To update the Kannada text added on 28-11-2022
	isduecorrection = coalesce(v_isduecorrection,isduecorrection)
	where applicationnumber = p_applicationnumber returning applicationnumber into v_applicationnumber;
end if;

if(p_currentstatus='CD134') THEN
	update kaveri.applicantapplicationdetails
	set bookid=2
	where applicationnumber = p_applicationnumber returning applicationnumber into v_applicationnumber;
end if;
if(p_currentstatus='CD105') THEN
	update kaveri.applicantapplicationdetails
	set currentstatus = 'CD106',lastupdatedby = p_lastupdatedby
	where applicationnumber = p_applicationnumber returning applicationnumber into v_applicationnumber;
end if;
if(p_currentstatus='CD109') THEN
	update kaveri.documentmaster set partypaymentdetails = p_remarks   --- To update the Kannada text added on 28-11-2022
	where applicationnumber = p_applicationnumber returning applicationnumber into v_applicationnumber;
	
	--- raghavendra -- 22-05-2024 appointment is expired while verifying SR
	update kaveri.appointmentmaster set status = '1' where applicationnumber= p_applicationnumber and appointmentid=v_appointmentid;
	
END IF;
if(p_currentstatus in ('CD120','CE110','CC109')) then
UPDATE kaveri.applicantapplicationdetails SET APPLICATIONENDDATE = current_timestamp,
registrationenddate=current_timestamp
where applicationnumber = p_applicationnumber;
END IF;

if(p_currentstatus in ('CD112','CD134','CD135','CD136')) then
	-- 16-05-2024, raghavendra; setting status as completed in appointmentmaster on summary approval
	update kaveri.appointmentmaster set status = '2' where applicationnumber= p_applicationnumber and status = '1' and appointmentid=v_appointmentid;
END IF;

if(p_currentstatus = 'BK114') then
	update kaveri.documentmaster set isdigitalsigned = true
	where applicationnumber = p_applicationnumber;
END IF;
return v_applicationnumber;
end;
$$;


ALTER FUNCTION kaveri.fn_upd_application_status_20260202(p_applicationnumber character varying, p_currentstatus text, p_lastupdatedby text, p_sfdaid integer, p_deoid integer, p_remarks text, p_remarksk text, p_reviewdetails kaveri.application_reviewdetails_input[], p_verification kaveri.application_verification_input[]) OWNER TO postgres;

--
-- Name: fn_upd_application_status_marriage(character varying, text); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_upd_application_status_marriage(p_applicationnumber character varying, p_currentstatus text) RETURNS text
    LANGUAGE plpgsql
    AS $$

declare
v_applicationnumber character varying;

begin

update kaveri.applicantapplicationdetails set currentstatus = p_currentstatus
where applicationnumber = p_applicationnumber returning applicationnumber into v_applicationnumber;

update kaveri.marriageregistration set currentstatus = p_currentstatus
where applicationnumber = p_applicationnumber returning applicationnumber into v_applicationnumber;

if(p_currentstatus in ('MR115','MR126')) then
update kaveri.marriageregistration set currentstatus = p_currentstatus,dateofregistration = current_timestamp,isregistraioncomplete = true
where applicationnumber = p_applicationnumber;

update kaveri.applicantapplicationdetails set currentstatus = p_currentstatus,applicationenddate = current_timestamp,
registrationenddate=current_timestamp
where applicationnumber = p_applicationnumber;
END IF;

if(p_currentstatus in ('MR106')) then
update kaveri.marriageapplicationremarks set
marriagedetailsremarks_fda = ' ',
marriagedetailsverified_fda = false,
bridegroomdetailsremarks_fda  = ' ',
bridegroomdetailsverified_fda = false,
bridedetailsremarks_fda = ' ',
bridedetailsverified_fda = false,
witnessdetailsremarks_fda = ' ',
witnessdetailsverified_fda = false,
marriagedetailsremarks_sr = ' ',
marriagedetailsverified_sr = false,
bridegroomdetailsremarks_sr = ' ',
bridegroomdetailsverified_sr = false,
bridedetailsremarks_sr = ' ',
bridedetailsverified_sr = false,
witnessdetailsremarks_sr = ' ',
witnessdetailsverified_sr = false,
canpreocesstopaymentremarks_sr = ' ',
canpreocesstopaymentverified_sr = false
where applicationnumber = p_applicationnumber;
END IF;

return v_applicationnumber;
end;
$$;


ALTER FUNCTION kaveri.fn_upd_application_status_marriage(p_applicationnumber character varying, p_currentstatus text) OWNER TO csgadmin;

