--
-- Name: fn_update_accepted_feesrequired_auditor(character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_update_accepted_feesrequired_auditor(_applicationnumber character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$

declare 

--v_feesrequired_scrutiny kaveri.scrutinyfeechange%rowtype;
v_feesrequired_scrutiny record;
v_temp_record record;

v_result_count INT;
v_success bigint;
v_fee_count bigint;

begin
	
	select count(*) into v_fee_count from kaveri.scrutinyfeechange f where f.applicationnumber = _applicationnumber;

if v_fee_count > 0 then 

  FOR v_feesrequired_scrutiny IN (select * from kaveri.scrutinyfeechange s where s.applicationnumber = _applicationnumber)
   
  
  	loop

--	 Comparing data between feesrequired table and scrutinyfeechange table
	 SELECT COUNT(*) INTO v_result_count FROM kaveri.feesrequired f 
     WHERE f.propertyid = v_feesrequired_scrutiny.propertyid AND f.feerulecode = v_feesrequired_scrutiny.feerulecode;
       
      if  v_result_count = 0 THEN  
      
      RAISE NOTICE 'v_result_count: %, v_feesrequired_scrutiny: %', v_result_count, v_feesrequired_scrutiny;
      
		insert
			into
			kaveri.feesrequired(feerulecode,
			applicationnumber,
			amountrequired,
			sroamountrequired,
			sfdaamountrequired,
			propertyid,
			documentid)
		values( v_feesrequired_scrutiny.feerulecode ,
		v_feesrequired_scrutiny.applicationnumber,
		v_feesrequired_scrutiny.amountrequired,
		v_feesrequired_scrutiny.auditoramountrequired,
		v_feesrequired_scrutiny.sfdaamountrequired,
		v_feesrequired_scrutiny.propertyid,
		v_feesrequired_scrutiny.documentid);

	else
	
		UPDATE kaveri.feesrequired SET sroamountrequired = v_feesrequired_scrutiny.auditoramountrequired
		WHERE propertyid = v_feesrequired_scrutiny.propertyid AND feerulecode = v_feesrequired_scrutiny.feerulecode;	

	end if;


 END LOOP; 

FOR v_temp_record IN (SELECT id, propertyid, auditorstamparticlecode, auditorstampruleid, auditorregarticlecode, auditormarketvalue, auditorconsideration, applicationnumber, inserteddatetime
FROM kaveri.application_for_scrutiny_property_master where applicationnumber = _applicationnumber )
  
  LOOP
  
	  UPDATE kaveri.propertymaster
SET  sromarketvalue = v_temp_record.auditormarketvalue , sroconsideration = v_temp_record.auditorconsideration , srostampruleid = v_temp_record.auditorstampruleid , srostamparticlecode = v_temp_record.auditorstamparticlecode
WHERE propertyid= v_temp_record.propertyid and applicationnumber = _applicationnumber;


end loop;

 v_success=1;

else
   
   raise notice'Not able to get the application details from scrutinyfeechange ' ;
   v_success=0;
 
end if;

 return v_success;
	END;
$$;


ALTER FUNCTION kaveri.fn_update_accepted_feesrequired_auditor(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_update_anywhere_reg(character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_update_anywhere_reg(_applicationnumber character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
v_cnt integer := 0;
unjurisdictional_prop_cnt integer := 0;
is_reg_complete boolean := false;
rw record;
v_jdistrictcode int;
v_rdistrictcode int;
BEGIN	

select isregistrationcompleted into is_reg_complete 
from kaveri.documentmaster d where d.applicationnumber=_applicationnumber;

if(is_reg_complete = true) then
	select count(*) into v_cnt from kaveri.propertymaster p 
	where p.applicationnumber = _applicationnumber;
		
	if(v_cnt>0) then
		for rw in (select pm.documentid, pm.applicationnumber, pm.propertyid, pm.regsrocode, pm.srocode,pm.ismovableproperty,pm.villagecode from kaveri.propertymaster pm where pm.applicationnumber=_applicationnumber) loop
			if(rw.srocode != rw.regsrocode and (rw.ismovableproperty=false or rw.ismovableproperty is null)) then
				
				select districtcode into v_jdistrictcode from kaveri.sromaster where srocode in (rw.srocode);
				select districtcode into v_rdistrictcode from kaveri.sromaster where srocode in (rw.regsrocode);
				if(v_jdistrictcode<>v_rdistrictcode) --or (v_jdistrictcode=v_rdistrictcode and v_rdistrictcode not in (35,36,1,34,33,29,7))))
				then
				insert into kaveri.anywhere_reg_log(documentid, applicationnumber, propertyid, regsrocode, srocode, ismemosent, isjurisdictionsroaccepted)
				values (rw.documentid, _applicationnumber, rw.propertyid, rw.regsrocode, rw.srocode, false, false);
				unjurisdictional_prop_cnt = unjurisdictional_prop_cnt + 1;
				end if;
			end if;
		end loop;
	end if;
end if;

return unjurisdictional_prop_cnt;
end;
$$;


ALTER FUNCTION kaveri.fn_update_anywhere_reg(_applicationnumber character varying) OWNER TO csgadmin;

--
-- Name: fn_update_application_isdeleted(text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_update_application_isdeleted(app_no text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_exists BOOLEAN;
BEGIN
    -- Check if a valid record exists
    SELECT EXISTS (
        SELECT 1 
        FROM kaveri.applicantapplicationdetails 
        WHERE applicationnumber = app_no 
        AND isdeleted = false 
        AND assignedto IS NULL
    ) INTO v_exists;

    -- If record exists, update isdeleted
    IF v_exists THEN
        UPDATE kaveri.applicantapplicationdetails
        SET isdeleted = true
        WHERE applicationnumber = app_no 
        AND isdeleted = false 
        AND assignedto IS NULL;
        
        RETURN TRUE;
    END IF;

    RETURN FALSE;
END;
$$;


ALTER FUNCTION kaveri.fn_update_application_isdeleted(app_no text) OWNER TO postgres;

--
-- Name: fn_update_appointment(bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_update_appointment(_srocode bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$

declare
v_record record;
v_applicationnumber character varying;
v_starttime time;
v_endtime time;
v_deoid int[];
p_starttime time;
p_endtime time;
v_deo int;
i int;
v_appointment int;
duration time;
v_srocode bigint;
begin
	
	
select array_agg(userid) into v_deoid from kaveri.departmentusers d where srocode =_srocode and designationid = 4;

for v_deo in (select unnest(v_deoid))
loop
	i = 0;

	raise notice 'deoid %',v_deo;
	for v_appointment in (select appointmentid from kaveri.appointmentmaster a 
			where deoperator = v_deo and appointmentdate::date = current_date and starttime>='14:30:00')
	loop 

		select starttime,endtime into v_starttime,v_endtime
			from kaveri.appointmentmaster a 
			where deoperator = v_deo and appointmentdate::date = current_date and starttime>='14:30:00'
 			and appointmentid=v_appointment;	

 		i=i+1;

 	if(i=1)
 	then
 	p_starttime=v_starttime;
	p_endtime=v_endtime;
	end if;

	if(i>1) then
			raise notice 'appointmentid %',v_appointment;
--		((endtime - starttime)::interval+starttime::time)
		
		duration=(v_endtime-v_starttime);
	
		raise notice 'duration %',duration;
		raise notice 'old_end %',p_endtime;
		raise notice 'new_end %', (p_endtime::time+duration::interval);
		update kaveri.appointmentmaster set starttime=p_endtime,endtime =(p_endtime::time+duration::interval) 
		where appointmentid =v_appointment;
	
	p_starttime=p_endtime;
	p_endtime=(p_endtime::time+duration::interval);
	
	end if;
 
 
end loop;
	
	
	
v_srocode=_srocode;	
end loop;
	

return v_srocode;
end;
$$;


ALTER FUNCTION kaveri.fn_update_appointment(_srocode bigint) OWNER TO postgres;

--
-- Name: fn_update_cc_scanned_file_path(text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_update_cc_scanned_file_path(_applicationnumber text) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INT;
   v_signedfilepath text;
  v_cnt int;
 _ccid int;
begin
	
	
	select filepath into v_signedfilepath from kaveri.signed_file_upload_details
	where applicationnumber =_applicationnumber;

select ccid into _ccid from kaveri.cc_applicationdetails ca where applicationnumber =_applicationnumber;
	
	select count(*) into v_cnt from  kaveri.cc_documents cd  where ccid =_ccid;

if(v_cnt=0)
then
    -- Insert data into kaveri.eccertificate table based on the provided parameters
    INSERT INTO kaveri.cc_documents (
        ccid, cccertificate
    ) VALUES (
    _ccid,v_signedfilepath
        
    );

    -- Get the count of rows affected by the INSERT statement
    GET DIAGNOSTICS v_count = ROW_COUNT;

    -- Check if any row was affected by the INSERT operation
    IF v_count > 0 THEN
        RETURN 1; -- Successful insertion
    ELSE
        RETURN 0; -- Insertion failed
    END IF;

   
else
	update kaveri.cc_documents  set cccertificate=v_signedfilepath where ccid =_ccid;
   
    -- Get the count of rows affected by the INSERT statement
    GET DIAGNOSTICS v_count = ROW_COUNT;

    -- Check if any row was affected by the INSERT operation
    IF v_count > 0 THEN
        RETURN 1; -- Successful insertion
    ELSE
        RETURN 0; -- Insertion failed
    END IF;
end if;
END;
$$;


ALTER FUNCTION kaveri.fn_update_cc_scanned_file_path(_applicationnumber text) OWNER TO postgres;

