    v_cnt int;
   _ccid int;
BEGIN
    -- Insert data into kaveri.eccertificate table based on the provided parameters
	
	select ccid into _ccid from kaveri.cc_applicationdetails ca where applicationnumber =_applicationnumber;
	
	select count(*) into v_cnt from kaveri.cc_documents where ccid=_ccid;
	
if(v_cnt=0)
then
    INSERT INTO kaveri.cc_documents (
        ccid,cccertificate
    ) VALUES (
        _ccid,_scandfilepath
    );
	
   
   
    -- Get the count of rows affected by the INSERT statement
    GET DIAGNOSTICS v_count = ROW_COUNT;

    -- Check if any row was affected by the INSERT operation
    IF v_count > 0 THEN
        RETURN 1; -- Successful insertion
    ELSE
        RETURN 0; -- Insertion failed
    END IF;
   
      
else
	update kaveri.cc_documents  set cccertificate=_scandfilepath where ccid =_ccid;

	update kaveri.cc_applicationdetails set signeddatetime =current_timestamp where applicationnumber =_applicationnumber;--added 02072024 raghavendra
    -- Get the count of rows affected by the INSERT statement
    GET DIAGNOSTICS v_count = ROW_COUNT;

    -- Check if any row was affected by the INSERT operation
    IF v_count > 0 THEN
        RETURN 1; -- Successful insertion
    ELSE
        RETURN 0; -- Insertion failed
    END IF;
end if;
END;

$$;


