--
-- Name: fn_update_ccapplicantdetails(character varying, bigint, character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_update_ccapplicantdetails(_appnum character varying, _citizenid bigint, _flag character varying) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
	_applicationnumber text;
	_application text;
	_nomenclature character varying(3);
	l_now varchar(8);
	_inserted_id text;
	_servicestatus text; 
	v_applicationnumber text;
	v_isprior2003 bool;
begin
	
select 	isprior2003 into v_isprior2003 from kaveri.cc_applicationdetails c 
where c.applicationnumber=_appnum;	

if _flag = 'insert' then
INSERT INTO kaveri.applicantapplicationdetails(
	citizenid,
    applicationnumber,
    applicationtypeid,
    applicationstartdate,
    currentstatus
    )
    values  
	(_citizenid,
	_appnum, 
	12,
	now(),
	'CC102')			 
    RETURNING applicationnumber into v_applicationnumber;

INSERT INTO kaveri.applicationaudit(
	applicationnumber, wrkflowstatusid, activityby, activityorder, crtusr)
	VALUES (_appnum, 'CC102', _citizenid, 1, _citizenid);

elsif _flag = 'update' then

if (v_isprior2003=false)
then
	
l_now := to_char(now(),'DDMMYYYY');
select nomenclature into _nomenclature from kaveri.servicesmaster where serviceid = 12;
select nextval('kaveri.ApplicantApplicationdetails_applicationnumber_seq')::text into _inserted_id;
_applicationnumber := _nomenclature ||'-'||l_now ||'-'||_inserted_id;

Delete from kaveri.applicationaudit 
	where applicationnumber = _appnum; 



update kaveri.applicantapplicationdetails 
	set applicationnumber = _applicationnumber, currentstatus = 'CC103'
	where applicationnumber = _appnum
	RETURNING applicationnumber into v_applicationnumber;

/*update kaveri.applicationaudit
	set applicationnumber = v_applicationnumber
	where applicationnumber = _appnum;*/

INSERT INTO kaveri.applicationaudit(applicationnumber, wrkflowstatusid, activityby, activityorder, crtusr)
	VALUES (v_applicationnumber, 'CC103', _citizenid, 1, _citizenid);

update kaveri.cc_applicationdetails 
	set applicationnumber = v_applicationnumber
	where applicationnumber = _appnum;

elsif (v_isprior2003=true)
then
update kaveri.applicantapplicationdetails set currentstatus='CC109' where applicationnumber=_appnum
returning applicationnumber into v_applicationnumber;
end if;

/*update kaveri.applicantapplicationdetails
	set currentstatus = 'CE104'
	where applicationnumber = v_applicationnumber;*/
end if;

Return v_applicationnumber;
end
$$;


