--
-- Name: fn_update_ec_scanned_file_path(text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_update_ec_scanned_file_path(_applicationnumber text) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INT;
   v_signedfilepath text;
  v_cnt int;
begin
	
	
	select filepath into v_signedfilepath from kaveri.signed_file_upload_details
	where applicationnumber =_applicationnumber;
	
	select count(*) into v_cnt from  kaveri.eccertificate where applicationnumber =_applicationnumber;

if(v_cnt=0)
then
    -- Insert data into kaveri.eccertificate table based on the provided parameters
    INSERT INTO kaveri.eccertificate (
        certificateid, srocode, searchdate, certificatenumber, certificatedate, 
        applicationnumber, fromdate, todate, isnec, searchdescription, uid, 
        liabilitydetails, istransmitted, certificatetype, certificatefile, 
        inserteddatetime, k1k2_flag
    ) VALUES (
        nextval('kaveri.certificateid_seq'), 0, CURRENT_TIMESTAMP, '', CURRENT_TIMESTAMP, 
        _applicationnumber, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 
        false, null, 0, null, false, 0, v_signedfilepath, 
        CURRENT_TIMESTAMP, 2
    );
   
	update kaveri.ec_applicationdetails set prepareddatetime =current_timestamp ,compareddatetime =current_timestamp 
	where applicationnumber =_applicationnumber;-- 02072024 done by raghavendra

    -- Get the count of rows affected by the INSERT statement
    GET DIAGNOSTICS v_count = ROW_COUNT;

    -- Check if any row was affected by the INSERT operation
    IF v_count > 0 THEN
        RETURN 1; -- Successful insertion
    ELSE
        RETURN 0; -- Insertion failed
    END IF;

   
else
	update kaveri.eccertificate set certificatefile=v_signedfilepath where applicationnumber =_applicationnumber;
   	
	update kaveri.ec_applicationdetails set signeddatetime = current_timestamp where applicationnumber =_applicationnumber;-- 02072024 done by raghavendra
	
    -- Get the count of rows affected by the INSERT statement
    GET DIAGNOSTICS v_count = ROW_COUNT;

    -- Check if any row was affected by the INSERT operation
    IF v_count > 0 THEN
        RETURN 1; -- Successful insertion
    ELSE
        RETURN 0; -- Insertion failed
    END IF;
end if;
END;
$$;


ALTER FUNCTION kaveri.fn_update_ec_scanned_file_path(_applicationnumber text) OWNER TO postgres;

--
-- Name: fn_update_ec_scanned_file_path(text, text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_update_ec_scanned_file_path(_applicationnumber text, _scandfilepath text) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INT;
   v_signedfilepath text;
  v_cnt int;
begin
	
select count(*) into v_cnt from  kaveri.eccertificate 
where applicationnumber =_applicationnumber;

v_count:=0;
if(v_cnt>0)
then

update kaveri.eccertificate set certificatefile=_scandfilepath 
where applicationnumber =_applicationnumber;

update kaveri.ec_applicationdetails set signeddatetime = current_timestamp where applicationnumber =_applicationnumber;

-- Get the count of rows affected by the INSERT statement
GET DIAGNOSTICS v_count = ROW_COUNT;
-- Check if any row was affected by the INSERT operation

end if;
return v_count;
END;
$$;


ALTER FUNCTION kaveri.fn_update_ec_scanned_file_path(_applicationnumber text, _scandfilepath text) OWNER TO postgres;

--
-- Name: fn_update_ecapplicantdetails(character varying, bigint, character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_update_ecapplicantdetails(_appnum character varying, _citizenid bigint, _flag character varying) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
	_applicationnumber text;
	_application text;
	_nomenclature character varying(3);
	l_now varchar(8);
	_inserted_id text;
	_servicestatus text; 
	v_applicationnumber text;
	v_isbefore2004 bool;
begin

select 	isbefore2004 into v_isbefore2004 from kaveri.ec_applicationdetails where applicationnumber=_appnum;	
	
if _flag = 'insert' then
INSERT INTO kaveri.applicantapplicationdetails(
	citizenid,
    applicationnumber,
    applicationtypeid,
    applicationstartdate,
    currentstatus
    )
    values  
	(_citizenid,
	_appnum, 
	13,
	now(),
	'CE102')			 
    RETURNING applicationnumber into v_applicationnumber;

INSERT INTO kaveri.applicationaudit(
	applicationnumber, wrkflowstatusid, activityby, activityorder, crtusr)
	VALUES (_appnum, 'CE102', _citizenid, 1, _citizenid);

elsif _flag = 'update' then
if (v_isbefore2004=false)
	then	
l_now := to_char(now(),'DDMMYYYY');
select nomenclature into _nomenclature from kaveri.servicesmaster where serviceid = 13;
select nextval('kaveri.ApplicantApplicationdetails_applicationnumber_seq') into _inserted_id;
_applicationnumber := _nomenclature ||'-'||l_now ||'-'||_inserted_id;

Delete from kaveri.applicationaudit 
	where applicationnumber = _appnum; 

update kaveri.applicantapplicationdetails 
	set applicationnumber = _applicationnumber, currentstatus = 'CE103'
	where applicationnumber = _appnum
	RETURNING applicationnumber into v_applicationnumber;

/*update kaveri.applicationaudit
	set applicationnumber = v_applicationnumber
	where applicationnumber = _appnum;*/

INSERT INTO kaveri.applicationaudit(applicationnumber, wrkflowstatusid, activityby, activityorder, crtusr)
	VALUES (v_applicationnumber, 'CE103', _citizenid, 1, _citizenid);

update kaveri.ec_applicationdetails 
	set applicationnumber = v_applicationnumber
	where applicationnumber = _appnum;
elsif (v_isbefore2004=true)
then
update kaveri.applicantapplicationdetails set currentstatus='CE110' where applicationnumber=_appnum
returning applicationnumber into v_applicationnumber;
end if;

/*update kaveri.applicantapplicationdetails
	set currentstatus = 'CE103'
	where applicationnumber = v_applicationnumber;*/
end if;

Return v_applicationnumber;
end
$$;


ALTER FUNCTION kaveri.fn_update_ecapplicantdetails(_appnum character varying, _citizenid bigint, _flag character varying) OWNER TO csgadmin;

