--
-- Name: fn_update_final_regnumber(integer, character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_update_final_regnumber(_srocode integer, _applicationnumber character varying) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
   v_regnumber text;
   v_serialnumber bigint;
   v_BOOKID bigint;
   v_regdocnumber text default null;
   v_shortname character varying(50);
   V_FINYEAR character varying(50);
  
BEGIN

V_FINYEAR:=(case when EXTRACT(MONTH FROM CURRENT_DATE) <= 3 then 
			to_CHAR(current_date + interval '-12 month', 'YYYY') || 
'-' || to_char(CURRENT_DATE, 'YY') else to_char(CURRENT_DATE, 'YYYY') 
			||'-' || to_char(current_date + interval '12 month', 'YY') end );

select dm.finalregistrationnumber,dm.bookid,sro.shortnamee,coalesce(srl.finalserial,0)+1
into v_regdocnumber,v_BOOKID,v_shortname,v_serialnumber
from kaveri.documentmaster dm 
inner join kaveri.sromaster  sro on (dm.srocode=sro.srocode) 
inner join kaveri.sroserialmaster srl on (srl.srocode=dm.srocode and srl.bookid=dm.bookid and srl.finyear = V_FINYEAR)
where dm.applicationnumber = _applicationnumber and dm.srocode= _srocode limit 1;
			
v_regnumber:= v_shortname||'-'||v_BOOKID||'-'||to_char(v_serialnumber,'fm00000')||'-'||V_FINYEAR;

/* select COALESCE(sro.registrationdocserial,0)+1,shortnamee into v_serialnumber,v_shortname
 from  kaveri.sromaster sro where srocode = _srocode;
SELECT BOOKID INTO v_BOOKID FROM KAVERI.DOCUMENTMASTER WHERE applicationnumber = _applicationnumber LIMIT 1;
select dm.finalregistrationnumber,sm.servicename into v_regdocnumber,applicationtype from kaveri.documentmaster dm 
left join kaveri.applicantapplicationdetails appd on (dm.applicationnumber = appd.applicationnumber)
left join kaveri.servicesmaster sm on (appd.applicationtypeid = sm.serviceid)  
where dm.applicationnumber = _applicationnumber and dm.srocode= _srocode;*/

if (v_regdocnumber is null) then
update kaveri.documentmaster set finalregistrationnumber= v_regnumber,documentnumber=v_serialnumber,
registrationdatetime = CURRENT_TIMEstamp
where applicationnumber = _applicationnumber and srocode= _srocode
and finalregistrationnumber is null;
v_regdocnumber:=v_regnumber;
else 
return v_regdocnumber;
end if;
return v_regdocnumber;
END;
$$;


ALTER FUNCTION kaveri.fn_update_final_regnumber(_srocode integer, _applicationnumber character varying) OWNER TO csgadmin;

--
-- Name: fn_update_final_regnumber_marriage(character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_update_final_regnumber_marriage(_applicationnumber character varying) RETURNS TABLE(v_regdocnumber character varying, v_dateofreg timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
declare
   v_cnt int;
   v_regnumber text;
   v_marriagetype character varying(5);
   v_serialnumber bigint;
   v_regdocnumber character varying(50) default null;
   v_shortname character varying(50);
   V_FINYEAR character varying(50);
   v_dateofreg timestamp;
  
BEGIN

	select count(finalregistrationnumber) into v_cnt  from kaveri.marriageregistration m where applicationnumber = _applicationnumber;

if(v_cnt = 1)then

	select finalregistrationnumber into v_regdocnumber from kaveri.marriageregistration m where applicationnumber =_applicationnumber;
	select dateofregistration into v_dateofreg from kaveri.marriageregistration m where applicationnumber =_applicationnumber;
	return query
	select v_regdocnumber ,v_dateofreg;

else
	
V_FINYEAR:=(case when EXTRACT(MONTH FROM CURRENT_DATE) <= 3 then 
			to_CHAR(current_date + interval '-12 month', 'YYYY') || 
'-' || to_char(CURRENT_DATE, 'YY') else to_char(CURRENT_DATE, 'YYYY') 
			||'-' || to_char(current_date + interval '12 month', 'YY') end );

select m.finalregistrationnumber,sro.shortnamee,mt.shortnamee,nextval('kaveri.marriage_finalreg_seq')
into v_regdocnumber,v_shortname,v_marriagetype,v_serialnumber
from kaveri.marriageregistration m 
inner join kaveri.sromaster sro on (m.regsrocode=sro.srocode) 
inner join kaveri.districtmaster d on d.districtcode = sro.districtcode
inner join kaveri.mas_marriagetype mt on mt.marriagetypeid = m.marriagetypeid
where m.applicationnumber = _applicationnumber limit 1;
			
v_regnumber:= v_shortname||'-'||v_marriagetype||to_char(v_serialnumber,'fm00000')||'-'||V_FINYEAR;

if (v_regdocnumber is null) then
update kaveri.marriageregistration 
set finalregistrationnumber= v_regnumber,
	dateofregistration = CURRENT_TIMEstamp,
	documentnumber=v_serialnumber,
	isregistraioncomplete = true
where applicationnumber = _applicationnumber
and finalregistrationnumber is null
returning finalregistrationnumber,dateofregistration into v_regdocnumber,v_dateofreg;
--v_regdocnumber:=v_regnumber;
--v_dateofreg:=dateofregistration;
end if;
return query
select v_regdocnumber,v_dateofreg;
end if;
END;
$$;


ALTER FUNCTION kaveri.fn_update_final_regnumber_marriage(_applicationnumber character varying) OWNER TO csgadmin;

