--
-- Name: fn_update_isendorsementsigned_party(character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_update_isendorsementsigned_party(_applicationnumber character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
declare
v_partyid bigint[];
begin
	select array_agg(partyid) into v_partyid from kaveri.partyinfo 
	where iscitizennotappeared= false 
	and isbiometricrefused = false 
	and islateapperance = false
	and applicationnumber = _applicationnumber;

	if v_partyid is null then return false;
	else 
	update kaveri.partyinfo 
	set isendorsementsigned = true,
		isthumbregistersigned = true
	where partyid = any(v_partyid) and applicationnumber = _applicationnumber;

	return true;
	end if;
end;
$$;


