--
-- Name: fn_update_marriageregistartion_status(character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_update_marriageregistartion_status(_applicationnumber character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
Declare

v_marriagemodeid int ;

begin 
	
--		select r.paymentmodeid into v_paymentmodeid from kaveri.receiptmaster r2 
--		join kaveri.receiptpaymentdetails r on r2.receiptid =r.receiptid 
--		where r2.applicationnumber =_applicationnumber;

		select marriagemodeid into v_marriagemodeid from kaveri.marriageregistration m where applicationnumber =_applicationnumber ;
	
		if(v_marriagemodeid=1)
		then 
		update kaveri.applicantapplicationdetails set currentstatus='MR114' where applicationnumber=_applicationnumber;
		
		elsif(v_marriagemodeid=2)
		then
			update kaveri.applicantapplicationdetails set currentstatus='MR113' where applicationnumber=_applicationnumber;
		
		end if;
		
	
	return 	_applicationnumber;	
end;
$$;


ALTER FUNCTION kaveri.fn_update_marriageregistartion_status(_applicationnumber character varying) OWNER TO csgadmin;

--
-- Name: fn_update_namematchpercentage(integer, character varying, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_update_namematchpercentage(_partyid integer, _applicationnumber character varying, _namematchpercentage integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
declare
row_count int;
begin
	update kaveri.partyinfo 
	set namematchpercentage = _namematchpercentage
	where partyid = _partyid and applicationnumber = _applicationnumber;

	GET DIAGNOSTICS row_count = row_count;
	
	if row_count = 0 then
        return false;
    else
        RETURN TRUE;
    end if;
	return true;
end;
$$;


