--
-- Name: fn_update_or_return_endorsement_date(character varying, timestamp with time zone); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_update_or_return_endorsement_date(_applicationnumber character varying, _endorsement_date timestamp with time zone) RETURNS timestamp without time zone
    LANGUAGE plpgsql
    AS $$
DECLARE
    existing_date TIMESTAMP;
    amountPaid NUMERIC;
    book_id INT;
BEGIN
    -- Step 1: Fetch the book_id
    SELECT bookid INTO book_id
    FROM kaveri.applicantapplicationdetails
    WHERE applicationnumber = _applicationnumber;

    -- Step 2: Get endorsement_date and amount_paid if book_id = 7
    IF book_id = 7 THEN
        SELECT endorsement_date, amount_paid
        INTO existing_date, amountPaid
        FROM kaveri.book1_part3_court
        WHERE applicationnumber = _applicationnumber;
    ELSE
        SELECT endorsement_date
        INTO existing_date
        FROM kaveri.filing_book1
        WHERE applicationnumber = _applicationnumber;
        amountPaid := 0; -- Default to 0 for non-book_id=7
    END IF;

    -- Step 3: Return existing date if present
    IF existing_date IS NOT NULL THEN
        RETURN existing_date;
    END IF;

    -- Step 4: Update endorsement_date where missing
    IF book_id = 7 THEN
        UPDATE kaveri.book1_part3_court
        SET endorsement_date = _endorsement_date
        WHERE applicationnumber = _applicationnumber;
    ELSE
        UPDATE kaveri.filing_book1
        SET endorsement_date = _endorsement_date
        WHERE applicationnumber = _applicationnumber;
    END IF;

    -- Step 5: Update documentmaster with endorsement flag and paid amount
    UPDATE kaveri.documentmaster
    SET 
        isprintendorsement = TRUE,
        paidstampduty = amountPaid
    WHERE applicationnumber = _applicationnumber;

    -- Step 6: Return new endorsement date
    RETURN _endorsement_date;
END;
$$;


ALTER FUNCTION kaveri.fn_update_or_return_endorsement_date(_applicationnumber character varying, _endorsement_date timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_update_panverified_app(character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_update_panverified_app(_applicationnumber character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
  
declare 
v_check bool default false;
begin
	if ((select bool_and(coalesce(ispartypanverified,false)) from kaveri.partyinfo p where applicationnumber = _applicationnumber) = true) then
		v_check:=true;	
		update kaveri.applicantapplicationdetails set ispanverified = true where applicationnumber =_applicationnumber;
	end if;
return v_check;
END;
$$;


ALTER FUNCTION kaveri.fn_update_panverified_app(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_update_party_aadhar_details(character varying, character varying, bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_update_party_aadhar_details(_applicationnumber character varying, _ekyctxnno character varying, _partyid bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$
 
DECLARE
    v_applicationnumber text;
    v_citizen_aadharhash text;
    v_department_aadharhash text;
   	v_aadhar_record kaveri.aadhar_authentication_log%rowtype;
 
begin	
		select * into v_aadhar_record from kaveri.aadhar_authentication_log WHERE ekyctxnno = _ekyctxnno;
 
if found then
 
    -- Update aadhar_authentication_log
    UPDATE kaveri.aadhar_authentication_log SET applicationnumber = _applicationnumber, partyid = _partyid
    WHERE ekyctxnno = _ekyctxnno;
 
    -- Fetch citizen's aadharhash
--    SELECT p.aadharhash INTO v_citizen_aadharhash FROM kaveri.partyinfo p
--    	WHERE p.applicationnumber = _applicationnumber AND p.isdeptaadharvalidated = false AND p.partyid = _partyid LIMIT 1;
SELECT p.aadharhash INTO v_citizen_aadharhash FROM kaveri.partyinfo p WHERE p.applicationnumber = _applicationnumber  AND p.partyid = _partyid LIMIT 1;
 
    -- Fetch department's aadharhash
--    SELECT aal.aadharhash INTO v_department_aadharhash FROM kaveri.aadhar_authentication_log aal WHERE ekyctxnno = _ekyctxnno LIMIT 1;
SELECT aal.aadharhash INTO v_department_aadharhash FROM kaveri.aadhar_authentication_log aal WHERE ekyctxnno = _ekyctxnno LIMIT 1; 

    -- Check if aadharhashes match and update partyinfo accordingly
    IF v_citizen_aadharhash = v_department_aadharhash THEN
        
    	UPDATE kaveri.partyinfo SET isdeptaadharvalidated = true WHERE partyid = _partyid
        	RETURNING applicationnumber INTO v_applicationnumber;
    ELSE
        RAISE NOTICE 'Aadharhash is not matching with citizen or already validated';
         v_applicationnumber := '0';
    END IF;
   
else
   
   raise notice 'Not able to find v_aadhar_record for _ekyctxnno ' ;
  v_applicationnumber:='-1';
  end if;
 
    RETURN v_applicationnumber;
END;
$$;


ALTER FUNCTION kaveri.fn_update_party_aadhar_details(_applicationnumber character varying, _ekyctxnno character varying, _partyid bigint) OWNER TO postgres;

--
-- Name: fn_update_party_aadhar_details_citizen(character varying, character varying, bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_update_party_aadhar_details_citizen(_applicationnumber character varying, _ekyctxnno character varying, _partyid bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$

DECLARE
    v_applicationnumber text;
    v_citizen_aadharhash text;
    v_department_aadharhash text;
    v_aadhar_record kaveri.aadhaar_log_citizen_encrypt%rowtype;

begin 
  select * into v_aadhar_record from kaveri.aadhaar_log_citizen_encrypt WHERE transactionnumber=_ekyctxnno;

if found and v_aadhar_record.partyid is null then

    -- Update aadhar_authentication_log
    UPDATE kaveri.aadhaar_log_citizen_encrypt SET applicationnumber = _applicationnumber, partyid = _partyid
    WHERE transactionnumber=_ekyctxnno;

 UPDATE kaveri.partyinfo SET iscitizenaadharverified = true WHERE partyid = _partyid
    RETURNING applicationnumber INTO v_applicationnumber;
   
 else
   
   raise notice 'Not able to find v_aadhar_record for _valutrefnumber ' ;
  v_applicationnumber:='-1';
  end if;

    RETURN v_applicationnumber;
END;
$$;


ALTER FUNCTION kaveri.fn_update_party_aadhar_details_citizen(_applicationnumber character varying, _ekyctxnno character varying, _partyid bigint) OWNER TO postgres;

--
-- Name: fn_update_party_links_duplicate(bigint, character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_update_party_links_duplicate(_partyid bigint, _applicationnumber character varying) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $$
DECLARE
    party_ids bigint[];
    v_exists boolean;
BEGIN
    -- Check if the party exists
    SELECT EXISTS (SELECT 1 FROM kaveri.partyinfo WHERE partyid = _partyid) INTO v_exists;
    IF NOT v_exists THEN
        RETURN FALSE;
    END IF;

    WITH RECURSIVE linked_parties AS (
    -- Start row
    SELECT partyid, linkpartyid, duplicatepartyid
    FROM kaveri.partyinfo
    WHERE applicationnumber = _applicationnumber
      AND partyid = _partyid

    UNION

    -- Recursive step
    SELECT p.partyid, p.linkpartyid, p.duplicatepartyid
    FROM kaveri.partyinfo p
    JOIN linked_parties lp
      ON (p.linkpartyid = lp.partyid OR p.partyid = lp.linkpartyid OR p.duplicatepartyid = lp.partyid OR p.partyid = lp.duplicatepartyid)
    WHERE p.applicationnumber = _applicationnumber
)

SELECT ARRAY(SELECT DISTINCT partyid FROM linked_parties) INTO party_ids;
    --update all related records
    update kaveri.partyinfo set ispartypanverified = true WHERE partyid = ANY(party_ids);

    RETURN party_ids;
END;
$$;


ALTER FUNCTION kaveri.fn_update_party_links_duplicate(_partyid bigint, _applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_update_party_signed_flag(text, bigint, text, text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_update_party_signed_flag(p_applicationnumber text, p_partyid bigint, p_falg text, p_partytype text) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    rows_affected INT := 0;
BEGIN
    -- Validate inputs
    IF p_falg IS NULL OR p_partytype IS NULL THEN
        RETURN json_build_object(
            'statusCode', '400',
            'message', 'Invalid input. Flag or party type missing.',
            'rowsAffected', rows_affected
        );
    END IF;

    -- ==========================
    -- PARTY TABLE UPDATES
    -- ==========================
    IF p_partytype = '1' THEN
        
        IF p_falg = 'endorsement' THEN
            UPDATE kaveri.partyinfo
            SET isendorsementsigned = TRUE
            WHERE applicationnumber = p_applicationnumber AND partyid = p_partyid;
        ELSIF p_falg = 'documentexecuted' THEN
            UPDATE kaveri.partyinfo
            SET isdocumentexecuted = TRUE
            WHERE applicationnumber = p_applicationnumber AND partyid = p_partyid;
        ELSIF p_falg = 'thumbregister' THEN
            UPDATE kaveri.partyinfo
            SET isthumbregistersigned = TRUE
            WHERE applicationnumber = p_applicationnumber AND partyid = p_partyid;
        END IF;

    -- ==========================
    -- WITNESS TABLE UPDATES
    -- ==========================
    ELSIF p_partytype = '2' THEN

        IF p_falg = 'endorsement' THEN
            UPDATE kaveri.witnessinfo
            SET isendorsementsigned = TRUE
            WHERE applicationnumber = p_applicationnumber AND witnessid = p_partyid;
        ELSIF p_falg = 'documentexecuted' THEN
            UPDATE kaveri.witnessinfo
            SET isdocumentexecuted = TRUE
            WHERE applicationnumber = p_applicationnumber AND witnessid = p_partyid;
        ELSIF p_falg = 'thumbregister' THEN
            UPDATE kaveri.witnessinfo
            SET isthumbregistersigned = TRUE
            WHERE applicationnumber = p_applicationnumber AND witnessid = p_partyid;
        END IF;

    END IF;

    GET DIAGNOSTICS rows_affected = ROW_COUNT;

    IF rows_affected = 0 THEN
        RETURN json_build_object(
            'statusCode', '400',
            'message', 'No rows updated.',
            'rowsAffected', rows_affected
        );
    END IF;

    RETURN json_build_object(
        'statusCode', '200',
        'message', 'Flag updated successfully.',
        'rowsAffected', rows_affected
    );
END;
$$;


ALTER FUNCTION kaveri.fn_update_party_signed_flag(p_applicationnumber text, p_partyid bigint, p_falg text, p_partytype text) OWNER TO postgres;

