-- Name: fn_update_previousproperty(bigint, bigint, integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_update_previousproperty(_keyid bigint, _orderid bigint, _isactivated integer) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare
v_orderid bigint;
v_cnt integer;
begin
select count(*) into v_cnt from kaveri.ecpropertysearchkeyvalues
where keyid = _keyid and orderid = _orderid;
if v_cnt = 1 then
update kaveri.ecpropertysearchkeyvalues set isactivated = _isactivated where
keyid = _keyid  and
orderid = _orderid returning orderid into v_orderid;
end if;
return v_orderid;
end;
$$;


