--
-- Name: fn_update_prior_cc_pay_details(text, integer, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_update_prior_cc_pay_details(_applicationnumber text, _feeruleid integer, _amount integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
cc_id int4;
v_ccid int4;
BEGIN
    -- Select ecid from kaveri.ec_applicationdetails based on applicationnumber
    SELECT ccid INTO cc_id
    FROM kaveri.cc_applicationdetails a
    WHERE a.applicationnumber = _applicationnumber;

    -- Update payableamount in kaveri.ec_requiredfees
    UPDATE kaveri.cc_requiredfees cr
    SET payableamount = _amount
    WHERE cr.ccid = cc_id AND cr.feeruleid = _feeruleid
   	returning cr.ccid into v_ccid;
  
	 IF(v_ccid is not null) then
      	--select '1';
        RETURN 1; -- Successful update
    else
    	--select '0';
        RETURN 0; -- Update failed
    END IF;
END;
$$;


ALTER FUNCTION kaveri.fn_update_prior_cc_pay_details(_applicationnumber text, _feeruleid integer, _amount integer) OWNER TO postgres;

