-- Name: fn_update_private_remark_minutebook_data(character varying, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_update_private_remark_minutebook_data(_applicationnumber character varying, _reasonid integer, _dr_order_number character varying, _dr_order_filepath character varying, _remarks character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$

Declare
v_docid bigint;
begin
select docid into v_docid from kaveri.minutebook_data where applicationnumber=_applicationnumber and reasonid=_reasonid order by minutedate desc limit 1;
update kaveri.minutebook_data set dr_order_number=_dr_order_number, dr_order_filepath=_dr_order_filepath, private_remark=_remarks 
where applicationnumber=_applicationnumber and docid=v_docid and reasonid=_reasonid;
return v_docid;
   END;
$$;


