--
-- Name: fn_update_property_master(kaveri.property_fees_input_array[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_update_property_master(p_propertymaster kaveri.property_fees_input_array[] DEFAULT NULL::kaveri.property_fees_input_array[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $_$
declare
v_schid bigint;
v_propertyid bigint;
   property_arry $1%type;
   v_deptid integer;
   v_cnt integer;
   v_pid bigint[];
   v_formarketvalue boolean;
begin
FOR property_arry IN (SELECT kaveri.fn_fetch_1d_arrayofarray($1))
	 LOOP
/*Select count(*) into v_cnt from kaveri.propertymaster where propertyid in 
(select a._propertyid from unnest(property_arry) a) ; */
select a._deptid,a._formarketvalue into v_deptid,v_formarketvalue from unnest(property_arry) a limit 1 ;
if  (v_deptid = 2 or v_deptid = 3) and v_formarketvalue = false then
update kaveri.propertymaster
SET sfdastamparticlecode = a._sfdastamparticlecode, sfdastampruleid = a._sfdastampruleid, 
	sfdanoofscanpages = a._sfdanoofscanpages,valuationreport=coalesce(a._valuationreport,valuationreport),
	sfdanatureofdocument = a._sfdanatureofdocument, sfdaconsideration=a._sfdaconsideration,
	sfdastampduty=a._sfdastampduty ,
	sfdacessduty=a._sfdacessduty ,
	sfdasurcharge=a._sfdasurcharge
from unnest(property_arry) a	
		 where propertyid in  (select a._propertyid from unnest(property_arry) a limit 1);
	 select b._propertyid into v_propertyid from unnest(property_arry) b;
elsif  v_deptid = 1 and v_formarketvalue = false then
update kaveri.propertymaster
SET srostamparticlecode = a._sfdastamparticlecode, srostampruleid = a._sfdastampruleid, 
	sronoofscanpages = case when a._sfdanoofscanpages is null then case when sronoofscanpages is null or sronoofscanpages=0 then noofscanpages else sronoofscanpages end  else a._sfdanoofscanpages  end ,valuationreport=coalesce(a._valuationreport,valuationreport),
	sronatureofdocument = a._sfdanatureofdocument,sroconsideration=a._sfdaconsideration,
	srostampduty=a._sfdastampduty ,
	srocessduty=a._sfdacessduty ,
	srosurcharge=a._sfdasurcharge
from unnest(property_arry) a	
		 where propertyid in  (select a._propertyid from unnest(property_arry) a limit 1);
	 select b._propertyid into v_propertyid from unnest(property_arry) b;
elsif  v_deptid = 1 and v_formarketvalue = true then
update kaveri.propertymaster
SET sromarketvalue = a._marketvalue,valuationreport=coalesce(a._valuationreport,valuationreport),sroroadcode=a._sfdaroadcode
from unnest(property_arry) a	
		 where propertyid in  (select a._propertyid from unnest(property_arry) a limit 1);
	 select b._propertyid into v_propertyid from unnest(property_arry) b;
elsif  (v_deptid = 2 or v_deptid = 3) and v_formarketvalue = true then
update kaveri.propertymaster
SET sfdamarketvalue = a._marketvalue,valuationreport=coalesce(a._valuationreport,valuationreport),sfdaroadcode=a._sfdaroadcode
from unnest(property_arry) a	
		 where propertyid in  (select a._propertyid from unnest(property_arry) a limit 1);
	 select b._propertyid into v_propertyid from unnest(property_arry) b;
else
null;
end if;
v_pid := array_append(v_pid,v_propertyid);
 end loop;
Return v_pid;
   END;
$_$;


ALTER FUNCTION kaveri.fn_update_property_master(p_propertymaster kaveri.property_fees_input_array[]) OWNER TO csgadmin;

--
-- Name: fn_update_property_master_auditor(kaveri.property_fees_input_array_auditor[]); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_update_property_master_auditor(p_propertymaster kaveri.property_fees_input_array_auditor[] DEFAULT NULL::kaveri.property_fees_input_array_auditor[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $_$
declare
v_schid bigint;
v_propertyid bigint;
   property_arry $1%type;
   v_deptid integer;
   v_cnt integer;
  
   v_pid bigint[];
   v_formarketvalue boolean;
   v_auditorconsideration integer;
   v_auditormarketvalue integer;
  v_applicationnumber text;

begin
FOR property_arry IN (SELECT kaveri.fn_fetch_1d_arrayofarray($1))
	 LOOP
/*Select count(*) into v_cnt from kaveri.propertymaster where propertyid in 
(select a._propertyid from unnest(property_arry) a) ; */
select a._deptid,a._formarketvalue into v_deptid,v_formarketvalue from unnest(property_arry) a limit 1 ;



Select count(*) into v_cnt from kaveri.application_for_scrutiny_property_master afspm  where propertyid in 
(select a._propertyid from unnest(property_arry) a) ;

if v_cnt = 0 then 
insert
	into
	kaveri.application_for_scrutiny_property_master
(id,
	propertyid,
	auditorstamparticlecode,
	auditorstampruleid,
	auditorregarticlecode,
	auditormarketvalue,
	auditorconsideration,
	applicationnumber,
	auditorroadcode,
	auditornoofscanpages,
	auditorvaluationreport,
	auditorstampduty,
	auditorcessduty,
	auditorsurcharge
	)
select 
nextval('kaveri.application_for_scrutiny_property_master_id_seq'::regclass),
a._propertyid,
a._auditorstamparticlecode,
a._auditorstampruleid,
a._auditorregarticlecode,
a._auditormarketvalue,
a._auditorconsideration,
a._applicationnumber,
a._auditorroadcode,
a._auditornoofscanpages, 
a._auditorvaluationreport,
a._auditorstampduty,
a._auditorcessduty,
a._auditorsurcharge

from unnest(property_arry) a	
--	 select b._propertyid into v_propertyid from unnest(property_arry) b;

returning propertyid::bigint into v_propertyid;

elseif v_deptid = 1 and v_formarketvalue = true then

UPDATE kaveri.application_for_scrutiny_property_master
SET auditorstamparticlecode=a._auditorstamparticlecode, auditorstampruleid=a._auditorstampruleid, 
auditorregarticlecode=a._auditorregarticlecode, 
auditormarketvalue=a._auditormarketvalue, 
auditorroadcode = a._auditorroadcode,
auditorvaluationreport = a._auditorvaluationreport
from unnest(property_arry) a	
		 where propertyid in  (select a._propertyid from unnest(property_arry) a limit 1);
	 select b._propertyid into v_propertyid from unnest(property_arry) b;

elseif v_deptid = 1 and v_formarketvalue = false then

UPDATE kaveri.application_for_scrutiny_property_master
SET auditorstamparticlecode=a._auditorstamparticlecode, auditorstampruleid=a._auditorstampruleid, 
auditorregarticlecode=a._auditorregarticlecode, 
auditorconsideration=a._auditorconsideration, 
auditornoofscanpages = a._auditornoofscanpages,
auditorstampduty = a._auditorstampduty,
auditorcessduty = a._auditorcessduty,
auditorsurcharge = a._auditorsurcharge
from unnest(property_arry) a	
		 where propertyid in  (select a._propertyid from unnest(property_arry) a limit 1);
	 select b._propertyid into v_propertyid from unnest(property_arry) b;

end if;
v_pid := array_append(v_pid,v_propertyid);
 end loop;
Return v_pid;
   END;
$_$;


