--
-- Name: fn_update_reschedule(); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_update_reschedule() RETURNS boolean
    LANGUAGE plpgsql
    AS $$

declare

v_applicationnumber record;
v_check boolean default false;

begin
	
--	select applicationnumber into v_applicationnumber from kaveri.applicantapplicationdetails a where applicationnumber in 
--	(select applicationnumber from kaveri.appointmentmaster where appointmentdate::date = current_date) and currentstatus = 'CD108';
	
--	for v_applicationnumber in (select applicationnumber from kaveri.applicantapplicationdetails a where applicationnumber in 
--	(select applicationnumber from kaveri.appointmentmaster where appointmentdate::date <= current_date and (endtime::time + '00:15:00')<current_time) and currentstatus = 'CD108')
	
--	for v_applicationnumber in (select a.applicationnumber from kaveri.applicantapplicationdetails a 
--	join kaveri.documentmaster d on d.applicationnumber = a.applicationnumber 
--	where a.applicationnumber in (select applicationnumber from kaveri.appointmentmaster where appointmentdate::date <= current_date and (endtime::time + '00:15:00')<current_time)
--	and currentstatus in('CD108','CD109') --and d.isregistrationaccepted != true
--	)

for v_applicationnumber in (select a.applicationnumber from kaveri.applicantapplicationdetails a  
join kaveri.appointmentmaster a2 on a.applicationnumber = a2.applicationnumber 
where (a2.appointmentdate::date < current_date or
(a2.appointmentdate::date = current_date and (a2.endtime::time+'00:55:00'::interval)<current_time::time))
and a.currentstatus in('CD108','CD109')and a2.status ='1')

	
	loop
		update kaveri.applicantapplicationdetails set currentstatus = 'CD107' where applicationnumber = v_applicationnumber.applicationnumber
		returning true into v_check;
		
		update kaveri.documentmaster set isregistrationaccepted = false where applicationnumber = v_applicationnumber.applicationnumber;
		
		--delete from kaveri.appointmentmaster where applicationnumber = v_applicationnumber.applicationnumber;
		update kaveri.appointmentmaster set status='3' where applicationnumber = v_applicationnumber.applicationnumber;
	
	end loop;

return v_check;
end;
$$;


ALTER FUNCTION kaveri.fn_update_reschedule() OWNER TO postgres;

--
-- Name: fn_update_reschedule_application(timestamp without time zone, interval, interval, text[]); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_update_reschedule_application(_appointmentdate timestamp without time zone, _slotstarttime interval, _slotendtime interval, p_applications text[]) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
--  v_appno character varying[];
--	v_appno1 character varying;
	v_applications varchar;
	v_row_count int;
	v_check boolean;
BEGIN

--IF _slotstarttime::time >= current_time  then

	IF _slotstarttime < _slotendtime THEN
	
	for v_applications in select * from unnest(p_applications) 
	loop
	            -- Update the appointmentmaster table and return the updated application numbers
--	            UPDATE kaveri.appointmentmaster 
--	            SET 
--	                appointmentdate = _appointmentdate,
--	                starttime = _slotstarttime,
--	                endtime = _slotendtime,
--	                status = '1'
--	            WHERE applicationnumber = v_applications
--	            AND appointmentdate = current_date 
--	            AND status = '3';

				-- insert new appointment in appointmentmaster table instead of update
				INSERT INTO kaveri.appointmentmaster (appointmenttypeid, srocode, deoperator, applicationnumber, appointmentdate, starttime, endtime, noofapplicants, status) 
				select appointmenttypeid, ap.srocode, deoperator, ap.applicationnumber, _appointmentdate , _slotstarttime , _slotendtime , noofapplicants, 1 from kaveri.appointmentmaster ap
				join kaveri.applicantapplicationdetails a on a.applicationnumber = ap.applicationnumber 
				where ap.applicationnumber = v_applications and a.currentstatus= 'CD107' and ap.status ='3' and ap.appointmentdate::date = current_date limit 1;
				
				update kaveri.applicantapplicationdetails set currentstatus = 'CD108' where applicationnumber = v_applications and currentstatus = 'CD107';
				GET DIAGNOSTICS v_row_count = ROW_COUNT;
				
				if v_row_count >0 then 
					select true into v_check;
				else 
					select false into v_check;
				end if;
	
		end loop;
	    ELSE 
	        -- If slot start time is not less than end time, return an array with a single element '-1'
	        select null into v_check;
		END IF;
--		ELSE
--			select null into v_check;
--END IF;
    RETURN v_check;
END;
$$;


ALTER FUNCTION kaveri.fn_update_reschedule_application(_appointmentdate timestamp without time zone, _slotstarttime interval, _slotendtime interval, p_applications text[]) OWNER TO postgres;

--
-- Name: fn_update_role_module_function_mapping(integer, kaveri.rollmapping_input[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_update_role_module_function_mapping(_rollid integer, _required_permission_array kaveri.rollmapping_input[] DEFAULT NULL::kaveri.rollmapping_input[]) RETURNS integer
    LANGUAGE plpgsql
    AS $$

DECLARE
v_success  integer;
v_permission_row record;
--v_position integer;
v_count integer;
v_count2 integer;
v_count3 integer;

BEGIN 



v_success:=null::integer;
if(_required_permission_array is not null and array_length(_required_permission_array,1)>0 ) then

	select count(*) into v_count from  (select a._rollid,a._moduleid,a._submoduleid,a._functionid from unnest(_required_permission_array)a 
 INTERSECT
	select rollid,moduleid,submoduleid,functionid from kaveri.role_module_function_mapping where rollid=_rollid) b;
	
	select count(*) into v_count2  from kaveri.role_module_function_mapping where rollid=_rollid;
	select  count(*) into v_count3 from unnest(_required_permission_array)a;
	
if  v_count=v_count2 and v_count=v_count3 then 

   v_success:=1;
   return v_success;
end if;
	
	
if(_required_permission_array is not null and array_length(_required_permission_array,1)>0 ) then

	for v_permission_row in 
	(
	 select rollid,moduleid,submoduleid,functionid from kaveri.role_module_function_mapping where rollid=_rollid 
	 except 
	 select a._rollid,a._moduleid,a._submoduleid,a._functionid from unnest(_required_permission_array)a 
	)
	
		loop
			
			if v_permission_row.submoduleid is null then
			  delete from kaveri.role_module_function_mapping  where rollid=v_permission_row.rollid and moduleid=v_permission_row.moduleid and 
			submoduleid is null;
			v_success:=1;
			
			elsif v_permission_row.functionid is null then
			
			delete from kaveri.role_module_function_mapping  where rollid=v_permission_row.rollid and moduleid=v_permission_row.moduleid and 
			submoduleid=v_permission_row.submoduleid and functionid is null ;
			v_success:=1;
			
			else
			  
			delete from kaveri.role_module_function_mapping  where rollid=v_permission_row.rollid and moduleid=v_permission_row.moduleid and 
			submoduleid=v_permission_row.submoduleid and functionid=v_permission_row.functionid;
			v_success:=1;
			end if;
				
		end loop;
		
		
 for v_permission_row in  
 (	select a._rollid,a._moduleid,a._submoduleid,a._functionid from unnest(_required_permission_array)a  )
 	
 	loop
		
		if v_permission_row._submoduleid is null then
			select count(*) into v_count from kaveri.vw_fetch_module_submodule_info  where  moduleid=v_permission_row._moduleid and 
			submoduleid is null;
			 			
			elsif v_permission_row._functionid is null then
			
			select count(*) into v_count from kaveri.vw_fetch_module_submodule_info  where  moduleid=v_permission_row._moduleid and 
			submoduleid=v_permission_row._submoduleid and functionid is null;
			
					
			else
			  
			select count(*) into v_count from kaveri.vw_fetch_module_submodule_info  where  moduleid=v_permission_row._moduleid and 
			submoduleid=v_permission_row._submoduleid and functionid=v_permission_row._functionid;
		end if;
		
		
		
		
		if v_count>0 then
		
		
			if v_permission_row._submoduleid is null then
				select count(*) into v_count from kaveri.role_module_function_mapping  where  moduleid=v_permission_row._moduleid and 
				submoduleid is null and rollid=v_permission_row._rollid ;
			 			
			elsif v_permission_row._functionid is null then
			
				select count(*) into v_count from kaveri.role_module_function_mapping  where  moduleid=v_permission_row._moduleid and 
				submoduleid=v_permission_row._submoduleid and functionid is null and rollid=v_permission_row._rollid;
			
					
			else
			  
				select count(*) into v_count from kaveri.role_module_function_mapping  where  moduleid=v_permission_row._moduleid and 
				submoduleid=v_permission_row._submoduleid and functionid=v_permission_row._functionid and rollid=v_permission_row._rollid;
			end if;
		
	 		
			if v_count=0 then
		
				 insert into kaveri.role_module_function_mapping(rollid,moduleid,submoduleid,functionid)
				 values(v_permission_row._rollid,v_permission_row._moduleid,v_permission_row._submoduleid,v_permission_row._functionid);
				 v_success:=1;
			 end if;
		end if;
	 	
 		
 	end loop;

end if;
 	
else

   delete from kaveri.role_module_function_mapping where rollid=_rollid;
   v_success:=1;
   
end if;

--v_success=1;

 

return v_success;

END;

$$;


ALTER FUNCTION kaveri.fn_update_role_module_function_mapping(_rollid integer, _required_permission_array kaveri.rollmapping_input[]) OWNER TO csgadmin;

