--
-- Name: fn_update_scanned_endorsement_docpath(bigint[], text, text, text, bigint); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_update_scanned_endorsement_docpath(p_partyid bigint[], p_applicationnumber text, p_uploadregistereddocpath text, p_type text, p_documentid bigint) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    rows_affected INT := 0;
BEGIN
    -- Validate required inputs
    IF p_type IS NULL THEN
        RETURN json_build_object(
            'statusCode', '400',
            'message', 'Invalid input. Registered path or type missing.',
            'rowsAffected', rows_affected
        );
    END IF;

    -- Clean and normalize type input
    p_type := LOWER(TRIM(p_type));

    -- Update based on type value
      IF p_type = 'lateappearancerecapture' THEN
        UPDATE kaveri.partyinfo
        SET isendorsementsigned = false
        WHERE applicationnumber = p_applicationnumber and partyid = ANY(p_partyid);
	
	  elsIF p_type = 'uploaddocdeedpath' THEN
        UPDATE kaveri.applicantapplicationdetails
		SET deedattachpath =p_uploadregistereddocpath
        WHERE applicationnumber = p_applicationnumber;

       ELSIF p_type = 'sendforrecapture' THEN

    UPDATE kaveri.documentmaster
    SET uploaddocdeedpath = NULL,uploadthumbregisterpath = null,isendorsepagenumber= false        -- use NULL if you truly want null
    WHERE applicationnumber = p_applicationnumber;

    UPDATE kaveri.partyinfo
    SET isendorsementsigned = false, isthumbregistersigned =false
    WHERE applicationnumber = p_applicationnumber;

ELSE
    RETURN json_build_object(
            'statusCode', '400',
            'message', 'Invalid type. Allowed values: endorsement or thumbregister.',
            'rowsAffected', rows_affected
        );
    END IF;

    -- Record number of affected rows
    GET DIAGNOSTICS rows_affected = ROW_COUNT;

    IF rows_affected = 0 THEN
        RETURN json_build_object(
            'statusCode', '400',
            'message', 'No rows updated.',
            'rowsAffected', rows_affected
        );
    END IF;

    RETURN json_build_object(
        'statusCode', '200',
        'message', 'Path updated successfully.',
        'rowsAffected', rows_affected
    );
END;
$$;


ALTER FUNCTION kaveri.fn_update_scanned_endorsement_docpath(p_partyid bigint[], p_applicationnumber text, p_uploadregistereddocpath text, p_type text, p_documentid bigint) OWNER TO postgres;

