CREATE FUNCTION kaveri.fn_update_sectionfilepath(_applicationnumber character varying, _section88file character varying, _partyid bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare
v_cnt bigint;
v_status integer;
begin
v_status = 0;
select count(*) into v_cnt from kaveri.partyinfo where applicationnumber = _applicationnumber ;
if  v_cnt > 0 then
update kaveri.partyinfo set section88file= _section88file where applicationnumber = _applicationnumber and partyid=_partyid
returning 1 into v_status;
end if;
return v_status;

end;
$$;


