--
-- Name: fn_update_sro_serial(); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_update_sro_serial() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE 
V_ACTIVITYORDER INTEGER DEFAULT 0;
BEGIN

if(old.pendingdocumentnumber is null and new.pendingdocumentnumber is not null) then
--update kaveri.sromaster set pendingdocserial = COALESCE(pendingdocserial,0)+1 
--where srocode= new.srocode;
update kaveri.sroserialmaster set pendingserial = COALESCE(pendingserial,0)+1 
where srocode= new.srocode and bookid=new.bookid and finyear=(case when EXTRACT(MONTH FROM CURRENT_DATE) <= 3 then 
			to_CHAR(current_date + interval '-12 month', 'YYYY') || 
'-' || to_char(CURRENT_DATE, 'YY') else to_char(CURRENT_DATE, 'YYYY') 
			||'-' || to_char(current_date + interval '12 month', 'YY') end );
end if;

if(old.finalregistrationnumber is null and new.finalregistrationnumber is not null) then
update kaveri.sroserialmaster set finalserial = COALESCE(finalserial,0)+1 
where srocode= new.srocode and bookid=new.bookid and finyear=(case when EXTRACT(MONTH FROM CURRENT_DATE) <= 3 then 
 			to_CHAR(current_date + interval '-12 month', 'YYYY') || 
 '-' || to_char(CURRENT_DATE, 'YY') else to_char(CURRENT_DATE, 'YYYY') 
 			||'-' || to_char(current_date + interval '12 month', 'YY') end );
end if;
return new;
END;
$$;


ALTER FUNCTION kaveri.fn_update_sro_serial() OWNER TO csgadmin;

--
-- Name: fn_update_time_citizen_master(bigint); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_update_time_citizen_master(_citizenid bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
v_citizenid bigint;

begin

update kaveri.citizenmaster set lstupddt=Current_timestamp
where citizenid = _citizenid returning citizenid into v_citizenid;
return v_citizenid;
exception
WHEN unique_violation then
raise notice 'duplicate user';
  end;
$$;


ALTER FUNCTION kaveri.fn_update_time_citizen_master(_citizenid bigint) OWNER TO csgadmin;

--
-- Name: fn_update_usergroup_role(integer, text, boolean, integer[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_update_usergroup_role(_groupid integer, _groupdesc text, _isactive boolean, _rollarray integer[] DEFAULT NULL::integer[]) RETURNS integer
    LANGUAGE plpgsql
    AS $$




DECLARE
v_roleid integer;
BEGIN 

		update kaveri.deptmentusergroup 
		set  isactive=_isactive,groupdesc=_groupdesc	where groupid=_groupid ;
		
		if(_rollarray is not null and array_length(_rollarray,1)>0 ) then
		
			delete from kaveri.group_roll_mapping where groupid=_groupid and rollid not in (select * from unnest(_rollarray)a);
			for v_roleid in 
			(select * from unnest(_rollarray)a except select rollid from kaveri.group_roll_mapping where groupid=_groupid ) 
		 LOOP
		 
			insert into kaveri.group_roll_mapping(groupid,rollid) values(_groupid,v_roleid);
		 end loop;
	 end if;
		
		
		return _groupid;
		 
END;

$$;


ALTER FUNCTION kaveri.fn_update_usergroup_role(_groupid integer, _groupdesc text, _isactive boolean, _rollarray integer[]) OWNER TO csgadmin;

--
-- Name: fn_updatefetch_mrg_receipt_paid_details(character varying, integer); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.fn_updatefetch_mrg_receipt_paid_details(_applicationnumber character varying, _srocode integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
v_loop_count integer;
v_pay_cnt integer;
--v_receipt_count integer[];
v_pending_fee_count integer;
v_cnt integer;
array_receiptarray record;
v_receiptnumber bigint[];
v_receiptid bigint;
v_total numeric;
v_data json;
BEGIN

/* checking the receiptid already exists */
-- What if there will be more recipt for given applicationnumber and srocode ??
select array(select distinct rm.receiptid
from kaveri.receiptmaster rm
left join kaveri.receiptdetails rd
on rm.receiptid = rd.receiptid
where applicationnumber = _applicationnumber
and rm.srocode = _srocode
Group by rm.receiptid) into v_receiptnumber;

/*check whether all payments in mrg_requiredfees table has a receipt issued*/
select count(*) into v_pending_fee_count from kaveri.mrg_requiredfees where applicationnumber = _applicationnumber
and receiptid is null and payableamount>=1;

/* if receiptid exists then it returns receiptid */

if v_pending_fee_count=0 then
select array_to_json(array_agg(temp1))as payment_history into v_data
from 
(select receiptid,(select array_to_json(array_agg(temp)) as paymentdetails from 
(select feeruleid,feedescription,amountpaid 
from kaveri.mrg_requiredfees mr where applicationnumber=_applicationnumber and srocode=_srocode)temp)

from kaveri.mrg_requiredfees mr where applicationnumber=_applicationnumber and srocode=_srocode limit 1)temp1;
return v_data;
end if;

select count(*) into v_pay_cnt from (
select epa.deptreferencecode,epa.amount as receiptamount, epd.applicationnumber,
sum(epd.amountpaid) as amountreceived, sum(epd.totalamount) as requestedamount
from kaveri.ams_reg_epaymentamtpaiddetails epd
inner join kaveri.ams_reg_epaymentbankackdetails epa
on epa.deptreferencecode=epd.deptreferencecode
where epd.applicationnumber = _applicationnumber and
paymentstatuscode='10700066'
group by epa.deptreferencecode,epa.amount,epd.applicationnumber
) x where requestedamount = amountreceived and amountreceived = receiptamount;

/* if the payment count is greater than zero, it means that payment is done
as such we can now insert into paymentmaster and child tables */

if(v_pay_cnt > 0) then

select sum(payableamount) into v_total from kaveri.mrg_requiredfees where 
applicationnumber=_applicationnumber and srocode = _srocode and receiptid is null;

v_loop_count:=0;



for array_receiptarray in (
select a.registrationid, b.feeruleid,c.citizenid, b.payableamount 
from kaveri.marriageregistration a
inner join kaveri.applicantapplicationdetails c on c.applicationnumber = a.applicationnumber
inner join kaveri.mrg_requiredfees b on a.applicationnumber = b.applicationnumber and b.payableamount is not null and b.payableamount>=1
and a.regsrocode = b.srocode and b.receiptid is null)
--inner join kaveri.partyinfo c on b.applicationnumber = c.applicationnumber 
--and ispresenter=true and b.srocode = c.srocode
--where a.applicationnumber=_applicationnumber and a.srocode = _srocode)
loop

--Take a copy of the documentid and partyid for later updation
--select documentid into v_documentid1 from unnest(array_receiptarray) ;
--select partyid into v_partyid1 from unnest(array_receiptarray) ;

if (v_loop_count=0) then
Insert into kaveri.receiptmaster
(
receiptid , -- Auto Increment
documentid ,
srocode ,
receipttypeid ,
receiptnumber , -- AutoIncrement
partyid ,
dateofreceipt ,
isprinted ,
printbanner ,
docreturntime ,
applicationnumber,
totalamount
)
values
(
nextval('kaveri.receiptmaster_receiptid_seq'),
array_receiptarray.registrationid,
_srocode,
5, -- receipttypeid 1 -- document
nextval('kaveri.receiptmaster_receiptnumber_seq'),
array_receiptarray.citizenid,
current_timestamp,
	false,
	null,
	null,
	_applicationnumber,
	v_total
	) returning receiptid into v_receiptid;
	
end if;

--Insert multiple entries for multiple feerulecode
--select feerulecode into v_feerulecode1 from unnest(array_receiptarray) ;
--select amountrequired into v_amountrequired1 from unnest(array_receiptarray) ;
--Multiple entry for each feerulecode

insert into kaveri.receiptdetails (receiptid ,
srocode ,
feerulecode ,
amountpaid) values
(
v_receiptid ,
_srocode ,
array_receiptarray.feeruleid,
array_receiptarray.payableamount
);

v_loop_count=v_loop_count+1;

insert into kaveri.receiptpaymentdetails
(
receiptid ,
srocode ,
paymentmodeid,
description ,
ddnumber ,
dddate ,
ifsccodeid,
ifsccode ,
micrcode ,
amount
)
values(
v_receiptid,
_srocode,--rm.srocode ,
4, -- paymentmodeid
'Paid through e-Payment an amount of Rs.' || v_total ,
null,--sd.ddnumber ,
null,--sd.ddchaldate as dddate,
null,--sd.ifccodeid ,
null,--sd.ifccode ,
null,--sd.micrcode ,
v_total
);


end loop;

--Update null values in receiptid column of the feesrequired table with new receiptid
update kaveri.mrg_requiredfees set receiptid=v_receiptid where applicationnumber=_applicationnumber
and receiptid is null and payableamount>=1;

update kaveri.marriageregistration set receiptid=v_receiptid where applicationnumber=_applicationnumber;

update kaveri.ams_reg_epaymenttransdetails set receiptid=v_receiptid where applicationnumber = _applicationnumber
and receiptid is null;

/* inserting data into receipt details wrto receiptid */
/*
insert into kaveri.receiptpaymentdetails
(
receiptid ,
srocode ,
paymentmodeid,
description ,
ddnumber ,
dddate ,
ifsccodeid,
ifsccode ,
micrcode ,
amount
)
values(
v_receiptid,
_srocode,--rm.srocode ,
4, -- paymentmodeid
'Paid through e-Payment an amount of Rs.' || v_total ,
null,--sd.ddnumber ,
null,--sd.ddchaldate as dddate,
null,--sd.ifccodeid ,
null,--sd.ifccode ,
null,--sd.micrcode ,
v_total
);
*/


elseif (v_pay_cnt=0) then
RAISE NOTICE'Payment Not Done';
end if;

--Return all the receipts available
/*select array(select distinct rm.receiptid
from kaveri.receiptmaster rm
where applicationnumber = _applicationnumber
and rm.srocode = _srocode
Group by rm.receiptid) into v_receiptnumber;*/

select array_to_json(array_agg(temp1))as payment_history into v_data
from 
(select receiptid,(select array_to_json(array_agg(temp)) as paymentdetails from 
(select feeruleid,feedescription,amountpaid 
from kaveri.mrg_requiredfees mr where applicationnumber=_applicationnumber and srocode=_srocode)temp)

from kaveri.mrg_requiredfees mr where applicationnumber=_applicationnumber and srocode=_srocode limit 1)temp1;

return v_data;

end;
$$;


ALTER FUNCTION kaveri.fn_updatefetch_mrg_receipt_paid_details(_applicationnumber character varying, _srocode integer) OWNER TO csgadmin;

