where applicationnumber = _applicationnumber
and rm.srocode = _srocode
Group by rm.receiptid) into v_receiptnumber;

/*check whether all payments in feerequired table has a receipt issued*/
select count(*) into v_pending_fee_count from kaveri.feesrequired where applicationnumber = _applicationnumber
and receiptid is null and amountpaid>=1;

