CREATE FUNCTION kaveri.fn_upload_documents_marriageregistration(_applicationnumber character varying, _form_1path character varying, _form_1apath character varying, _marriageproofid integer, _marriageproofpath character varying, _identityprooffilepath_bg character varying, _ageprooffilepath_bg character varying, _addressprooffilepath_bg character varying, _identifyproofid_bg bigint, _ageproofid_bg bigint, _addressproofid_bg bigint, _identityprooffilepath_b character varying, _ageprooffilepath_b character varying, _addressprooffilepath_b character varying, _identifyproofid_b bigint, _ageproofid_b bigint, _addressproofid_b bigint, _durationofstayproofpath_bg character varying, _durationofstayproofpath_b character varying, _numberofcopy integer DEFAULT 0) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
v_applicationnumber text;
v_cnt integer;
v_bridegroompersonid integer;
v_bridepersonid integer;
v_sex character varying;
--v_iswidow boolean;
--v_isdivorce boolean;

begin

/* upload marriage registration proof documents */

update kaveri.marriageregistration 
    set 
	form_1path = _form_1path, 
	form_1apath = _form_1apath ,
	marriageproofid = _marriageproofid , 
	marriageproofpath = _marriageproofpath,
	--intendedfilepath=_intendedfilepath,
	currentstatus='MR105',
	numberofcopy = _numberofcopy
where 	
	applicationnumber = _applicationnumber returning applicationnumber into v_applicationnumber;

update kaveri.ApplicantApplicationdetails set currentstatus='MR105' 
where applicationnumber = _applicationnumber returning applicationnumber into v_applicationnumber;
	
	/* upload bridegroom death certificate and divorse certificates */

update kaveri.persondetails  
    set 
    --deathcertificateid = 0,
	--deathcertificatefilepath = _deathcertificatefilepath_bg ,
	--divorcecertificateid = 0,
	--divorcecertificatefilepath = _divorcecertificatefilepath_bg,
	identityproofid = _identifyproofid_bg,
	identityprooffilepath = _identityprooffilepath_bg,
	ageproofid = _ageproofid_bg,
	ageprooffilepath = _ageprooffilepath_bg,
	addressproofid = _addressproofid_bg,
	addressprooffilepath = _addressprooffilepath_bg,
	durationofstayproofpath=_durationofstayproofpath_bg
 where --sex like 'M%'
 persontypeid=1 and
applicationnumber=_applicationnumber returning applicationnumber into v_applicationnumber;

	/* upload bride death certificate and divorse certificates */

update kaveri.persondetails  
set 
    --deathcertificateid = 0,
	--deathcertificatefilepath = _deathcertificatefilepath_b ,
	--divorcecertificateid = 0,
	--divorcecertificatefilepath = _divorcecertificatefilepath_b,
	identityproofid = _identifyproofid_b,
	identityprooffilepath = _identityprooffilepath_b,
	ageproofid = _ageproofid_b,
	ageprooffilepath = _ageprooffilepath_b,
	addressproofid = _addressproofid_b,
	addressprooffilepath = _addressprooffilepath_b,
	durationofstayproofpath=_durationofstayproofpath_b
where --persontype like 'F%'
 persontypeid=2 and
applicationnumber=_applicationnumber returning applicationnumber into v_applicationnumber;

update kaveri.marriageregistration 
set applicationsubmit = current_timestamp
where applicationnumber=_applicationnumber returning applicationnumber into v_applicationnumber;

return v_applicationnumber;

end;
$$;


