ALTER FUNCTION kaveri.fn_upload_iscitizennotappiared_isbiometricrefused(_partyid integer, _applicationnumber character varying, _iscitizennotappiared boolean, _isbiometricrefused boolean, _photopath character varying, _thumbpath character varying) OWNER TO postgres;

--
-- Name: fn_upload_iscitizennotappiared_isbiometricrefused(integer, character varying, boolean, boolean, character varying, character varying, boolean); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_upload_iscitizennotappiared_isbiometricrefused(_partyid integer, _applicationnumber character varying, _iscitizennotappiared boolean, _isbiometricrefused boolean, _photopath character varying, _thumbpath character varying, _islateapperance boolean) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    party_ids bigint[];
    v_exists boolean;
begin
SELECT EXISTS (SELECT 1 FROM kaveri.partyinfo WHERE partyid = _partyid) INTO v_exists;
    IF NOT v_exists THEN
        RETURN FALSE;
    END IF;
        
    with recursive linked AS (
        select p.partyid, p.linkpartyid
        from kaveri.partyinfo p
        where p.applicationnumber = _applicationnumber
          and p.partyid = _partyid
 
        union
 
        -- expand: any row whose partyid is linked to any already-seen partyid
        select p.partyid, p.linkpartyid
        from kaveri.partyinfo p
        join linked l
          on p.applicationnumber = _applicationnumber
         and (p.partyid = l.linkpartyid or p.linkpartyid = l.partyid or p.partyid = l.partyid)
    )
      select array(select partyid from linked INTO party_ids);
 
  update kaveri.partyinfo f set
     iscitizennotappeared=coalesce(_iscitizennotappiared,f.iscitizennotappeared),
  isbiometricrefused= coalesce(_isbiometricrefused,f.isbiometricrefused),
  photopath =_photopath,
     thumbpath =_thumbpath,
  islateapperance =coalesce(_islateapperance,f.islateapperance)
  --isendorsementsigned=coalesce(_isendorsementsigned,f.isendorsementsigned),
  --isthumbregistersigned=coalesce(_isthumbregistersigned,f.isthumbregistersigned)
  where partyid = ANY(party_ids);
 
return _applicationnumber;
end;
$$;


ALTER FUNCTION kaveri.fn_upload_iscitizennotappiared_isbiometricrefused(_partyid integer, _applicationnumber character varying, _iscitizennotappiared boolean, _isbiometricrefused boolean, _photopath character varying, _thumbpath character varying, _islateapperance boolean) OWNER TO postgres;

