--
-- Name: fn_upsert_partyesignregister(character varying, bigint, character varying, boolean, character varying, bigint, boolean); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_upsert_partyesignregister(p_applicationnumber character varying, p_partyid bigint, p_docpath character varying, p_iswitness boolean, p_linkid character varying, p_documentid bigint, p_isbeingsigned boolean DEFAULT false) RETURNS bigint
    LANGUAGE plpgsql
    AS $$

DECLARE
	v_partyid int; 
	partysigning int; 
    result_id BIGINT;
BEGIN

if(p_isbeingsigned = true) then
	select partyid into v_partyid from kaveri.partyesignregister where applicationnumber = p_applicationnumber and docpath = p_docpath and isbeingsigned = true;
	if(v_partyid is not null and p_partyid <> v_partyid) then
		return v_partyid;
	end if;
end if;

	select Count(*) into partysigning from kaveri.partyesignregister where applicationnumber = p_applicationnumber and docpath = p_docpath and  partyid = p_partyid;
 
	if(partysigning > 0) then
		UPDATE kaveri.partyesignregister
		SET 
			isbeingsigned     = p_isbeingsigned,
			inserteddatetime  = Current_timestamp,
			linkid = p_linkid
		WHERE applicationnumber = p_applicationnumber
		  AND partyid = p_partyid
		RETURNING 0 INTO result_id;
	else
		INSERT INTO kaveri.partyesignregister (
			applicationnumber,
			partyid,
			docpath,
			isbeingsigned,
			iswitness,
			linkid,
			documentid
		) VALUES (
			p_applicationnumber,
			p_partyid,
			p_docpath,
			p_isbeingsigned,
			p_iswitness,
			p_linkid,
			p_documentid
		)
		RETURNING 0 INTO result_id;
	end if;
    RETURN result_id;
END;
$$;


ALTER FUNCTION kaveri.fn_upsert_partyesignregister(p_applicationnumber character varying, p_partyid bigint, p_docpath character varying, p_iswitness boolean, p_linkid character varying, p_documentid bigint, p_isbeingsigned boolean) OWNER TO postgres;

--
-- Name: fn_upsertion_pending_flags(character varying, boolean, boolean, boolean, boolean, boolean); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.fn_upsertion_pending_flags(_applicationnumber character varying, _isimpound boolean, _isundervaluation boolean, _isdelaycondonation boolean, _ispartylateappearance boolean, _isprivateatteandace boolean) RETURNS TABLE(applicationnumber character varying, isimpound boolean, isundervaluation boolean, isdelaycondonation boolean, ispartylateappearance boolean, isprivateatteandace boolean)
    LANGUAGE plpgsql
    AS $$
#variable_conflict use_column
BEGIN
    RETURN QUERY
    INSERT INTO kaveri.pending_flags AS pf (
        applicationnumber,
        isimpound,
        isundervaluation,
        isdelaycondonation,
        ispartylateappearance,
        isprivateatteandace
    )
    VALUES (
        _applicationnumber,
        _isimpound,
        _isundervaluation,
        _isdelaycondonation,
        _ispartylateappearance,
        _isprivateatteandace
    )
    ON CONFLICT (applicationnumber)
     DO UPDATE SET
        -- Using COALESCE to keep existing value (pf) if new value (EXCLUDED) is NULL
        isimpound             = COALESCE(EXCLUDED.isimpound, pf.isimpound),
        isundervaluation      = COALESCE(EXCLUDED.isundervaluation, pf.isundervaluation),
        isdelaycondonation    = COALESCE(EXCLUDED.isdelaycondonation, pf.isdelaycondonation),
        ispartylateappearance = COALESCE(EXCLUDED.ispartylateappearance, pf.ispartylateappearance),
        isprivateatteandace   = COALESCE(EXCLUDED.isprivateatteandace, pf.isprivateatteandace)
    RETURNING
        pf.applicationnumber,
        pf.isimpound,
        pf.isundervaluation,
        pf.isdelaycondonation,
        pf.ispartylateappearance,
        pf.isprivateatteandace;
END;
$$;


ALTER FUNCTION kaveri.fn_upsertion_pending_flags(_applicationnumber character varying, _isimpound boolean, _isundervaluation boolean, _isdelaycondonation boolean, _ispartylateappearance boolean, _isprivateatteandace boolean) OWNER TO postgres;

--
-- Name: get_aadhaar_details(bigint, text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.get_aadhaar_details(p_partyid bigint, p_aadhaarhash text) RETURNS TABLE(v_data jsonb, isencrypted boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_transactionnumber TEXT;
BEGIN
 
    -- Get transaction number
    SELECT pi.transactionnumber
    INTO v_transactionnumber
    FROM kaveri.partyinfo pi
    WHERE pi.partyid = p_partyid;
 
    IF v_transactionnumber IS NULL THEN
 
        -- Encrypted Aadhaar details
        RETURN QUERY
        SELECT
            to_jsonb(alce.aadhaardetails) AS v_data,
            TRUE AS isencrypted
        FROM kaveri.aadhaar_log_citizen_decrypt alcd
        JOIN kaveri.aadhaar_log_citizen_encrypt alce
            ON alcd.encryptid = alce.id and alcd.responsestatus = 'Y'
        WHERE alcd.aadhaarhash = p_aadhaarhash;
  
  if v_data is null then
   -- Non-encrypted eKYC data
   RETURN QUERY
   SELECT
    to_jsonb(aalc.ekycdata) AS v_data,
    FALSE AS isencrypted
   FROM kaveri.aadhar_authentication_log_citizen aalc
   WHERE aalc.aadharhash = p_aadhaarhash and aalc.responsestatus = 'Y'
   order by inserteddatetime desc limit 1;
  end if;
 
    ELSE
 
        -- Transaction number exists
        RETURN QUERY
        SELECT
            to_jsonb(alce.aadhaardetails) AS v_data,
            TRUE AS isencrypted
        FROM kaveri.aadhaar_log_citizen_encrypt alce
        WHERE alce.transactionnumber = v_transactionnumber;
 
    END IF;
 
END;
$$;


ALTER FUNCTION kaveri.get_aadhaar_details(p_partyid bigint, p_aadhaarhash text) OWNER TO postgres;

--
-- Name: get_sro_by_villagecode(bigint[]); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.get_sro_by_villagecode(p_values bigint[]) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare
v_data_json json;
v_array_length numeric(100,0) := 0;
v_msg character varying(100) := null;
i integer;
v_districtcode text[];
begin
 v_array_length:= array_length(p_values,1);
  if (v_array_length > 0 ) then
--  for i in 1..v_array_length loop
select array_agg(distinct districtcode) into v_districtcode 
from kaveri.sromaster s
 inner join kaveri.villagemaster v
on v.srocode = s.srocode and v.villagecode in (select unnest(p_values)); --and s.districtcode not in (14);

--raise notice 'district code %',v_districtcode;


select row_to_json(dro) into v_data_json
from (
select array_to_json(array_agg(row_to_json(drodetails))) as SRO_identify_concerned_DRO from (
select distinct b.srocode,b.sronamee,b.districtcode,d.districtnamee,v.ispaperless
from kaveri.sromaster b 
inner join kaveri.districtmaster d on b.districtcode = d.districtcode-- and d.districtcode <>14
left join  kaveri.villagemaster a on b.srocode =a.srocode
join kaveri.vw_fetch_paperless_trans v on v.srocode = b.srocode
where a.villagecode in  ( select unnest(p_values)) or (b.enableanywherereg=true and d.districtcode::text = any(v_districtcode)) 
or (b.srocode = 206 and  d.districtcode::Text = any(v_districtcode))
--and b.districtcode not in (14)
union 
