--
-- Name: get_sro_by_villagecode_11(bigint[]); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.get_sro_by_villagecode_11(p_values bigint[]) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare
v_data_json json;
v_array_length numeric(100,0) := 0;
v_msg character varying(100) := null;
i integer;
v_districtcode text[];
begin
 v_array_length:= array_length(p_values,1);
  if (v_array_length > 0 ) then
--  for i in 1..v_array_length loop
select array_agg(distinct districtcode) into v_districtcode 
from kaveri.sromaster s
 inner join kaveri.villagemaster v
on v.srocode = s.srocode and v.villagecode in (select unnest(p_values)) and s.districtcode not in (14);

raise notice 'district code %',v_districtcode;


select row_to_json(dro) into v_data_json
from (
select array_to_json(array_agg(row_to_json(drodetails))) as SRO_identify_concerned_DRO from (
select distinct b.srocode,b.sronamee,b.districtcode,d.districtnamee,v.ispaperless
from kaveri.sromaster b 
inner join kaveri.districtmaster d on b.districtcode = d.districtcode and d.districtcode <>14
left join  kaveri.villagemaster a on b.srocode =a.srocode
join kaveri.vw_fetch_paperless_trans v on v.srocode = b.srocode
where a.villagecode in  ( select unnest(p_values)) or (b.enableanywherereg=true and d.districtcode::text = any(v_districtcode)) 
or (b.srocode = 206 and  d.districtcode::Text = any(v_districtcode))
and b.districtcode not in (14)
union 
select v.srocode,v.sronamee,v.districtcode,v.districtnamee,v.ispaperless from kaveri.sromaster sro 
inner join kaveri.districtmaster d 
on sro.districtcode=d.districtcode and d.districtcode <>14
join kaveri.vw_fetch_paperless_trans v
	on v.srocode = sro.srocode
 where sro.enableanywherereg=true and sro.districtcode in (1,33,34,35,36) and sro.districtcode::text = any(v_districtcode)
and sro.districtcode not in (14) 

ORDER BY SRONAMEE
)
as drodetails
) dro;	
--  end loop;

    end if;
  --   i=i+1;
return v_data_json;
END;
$$;


