CREATE FUNCTION kaveri.get_sro_by_villagecode_chk(p_values bigint[]) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare
v_data_json json;
v_array_length numeric(100,0) := 0;
v_msg character varying(100) := null;
i integer;
v_districtcode bigint;
begin
 v_array_length:= array_length(p_values,1);
 select a.districtcode into v_districtcode from (
select distinct a.districtcode,districtnamee,b.srocode,sronamee from 
kaveri.districtmaster a inner join kaveri.sromaster b on a.districtcode = b.districtcode
inner join kaveri.villagemaster c on b.srocode = c.srocode
where a.districtcode in (1,33,34,35,36) AND
	 c.villagecode in (select unnest(p_values) ) 
/*union all
select distinct a.districtcode,districtnamee,b.srocode,sronamee from 
kaveri.districtmaster a inner join kaveri.sromaster b on a.districtcode = b.districtcode
inner join kaveri.villagemaster c on b.srocode = c.srocode
where a.districtcode in (1,33,34,35,36) AND c.villagecode not in  (select unnest(p_values) )*/) as a; 
  if (v_array_length > 0 ) then
	 if (v_districtcode in (1,33,34,35,36)) then
--  for i in 1..v_array_length loop
select row_to_json(dro) into v_data_json
from (
select array_to_json(array_agg(row_to_json(drodetails))) as SRO_identify_concerned_DRO from (
	
/*======================================*/
	select * from (
select distinct a.districtcode,districtnamee,b.srocode,sronamee from 
kaveri.districtmaster a right join kaveri.sromaster b on a.districtcode = b.districtcode
left join kaveri.villagemaster c on b.srocode = c.srocode
where a.districtcode in (1,33,34,35,36) and
	 c.villagecode in (select unnest(p_values) ) 
union all
select distinct a.districtcode,districtnamee,b.srocode,sronamee from 
kaveri.districtmaster a right join kaveri.sromaster b on a.districtcode = b.districtcode
left join kaveri.villagemaster c on b.srocode = c.srocode
where a.districtcode in (1,33,34,35,36) and c.villagecode not in (select unnest(p_values) ) 
union all	
	select distinct a.districtcode,districtnamee,b.srocode,sronamee from 
kaveri.districtmaster a right join kaveri.sromaster b on a.districtcode = b.districtcode
left join kaveri.villagemaster c on b.srocode = c.srocode
where a.districtcode not in (1,33,34,35,36) and
	 c.villagecode in (select unnest(p_values) ) ) as a order by a.districtcode,a.srocode
	
/*======================================*/
		   )
			as drodetails
	) dro;
	else
	select row_to_json(dro) into v_data_json
from (
select array_to_json(array_agg(row_to_json(others))) as SRO_identify_concerned_DRO from (
	
/*======================================*/
	select * from (
select distinct a.districtcode,districtnamee,b.srocode,sronamee from 
kaveri.districtmaster a inner join kaveri.sromaster b on a.districtcode = b.districtcode
inner join kaveri.villagemaster c on b.srocode = c.srocode
where a.districtcode not in (1,33,34,35,36) and
	 c.villagecode in (select unnest(p_values))--(29013,687,23911)
)  as a order by a.districtcode,a.srocode
	
/*======================================*/
		   )
			as others
	) dro;
 end if;
	  	  end if;
	return v_data_json;
END;
$$;


