--
-- Name: getdigilockerdocument_prod(character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.getdigilockerdocument_prod(p_finalregistrationnumber character varying) RETURNS TABLE(finalregistrationnumber character varying, applicationnumber character varying, uploaddocdeedpath text, claimant_name character varying, claimant_phone character varying, claimant_gender character varying, claimant_photo text, claimant_pan character varying, executant_name character varying, executant_phone character varying, executant_gender character varying, executant_photo text, executant_pan character varying, ispresenter boolean)
    LANGUAGE plpgsql
    AS $$
begin
    return query
    select
        bd.finalregistrationnumber,
        bd.applicationnumber,
        bd.uploaddocdeedpath,
        coalesce(ca.auth_name, c.nameasperaadhar) as claimant_name,
        coalesce(ca.auth_phone, c.phonenumber) as claimant_phone,
        gc.descriptione::character varying as claimant_gender,
        coalesce(ca.auth_photo, c.photopath)::text as claimant_photo,
        coalesce(ca.auth_pan, c.pan) as claimant_pan,
        coalesce(ea.auth_name, e.nameasperaadhar) as executant_name,
        coalesce(ea.auth_phone, e.phonenumber) as executant_phone,
        ge.descriptione::character varying as executant_gender,
        coalesce(ea.auth_photo, e.photopath)::text as executant_photo,
        coalesce(ea.auth_pan, e.pan) as executant_pan,
        c.ispresenter as ispresenter
    from (
        select
            dm.documentid,
            dm.applicationnumber,
            dm.finalregistrationnumber,
            dm.uploaddocdeedpath
        from kaveri.documentmaster dm
        where dm.finalregistrationnumber = p_finalregistrationnumber
    ) bd
    left join (
        select *
        from (
            select
                dm.finalregistrationnumber,
                dm.applicationnumber,
                p.partyid,
                p.linkpartyid,
                p.partytypeid,
                p.nameasperaadhar,
                p.phonenumber,
                p.sex,
                p.photopath,
                p.pan,
                p.aadharhash,
                p.idprooftypeid,
                p.isorganization,
                p.ispresenter,
                row_number() over (
                    partition by dm.finalregistrationnumber, p.partytypeid
                    order by p.partyid
                ) as rn
            from kaveri.documentmaster dm
            join kaveri.partyinfo p
                on p.applicationnumber = dm.applicationnumber
            where dm.finalregistrationnumber = p_finalregistrationnumber
              and p.partytypeid in (1, 2)
        ) x
        where x.partytypeid = 1
          and x.rn = 1
    ) c
        on c.finalregistrationnumber = bd.finalregistrationnumber
    left join (
        select *
        from (
            select
                dm.finalregistrationnumber,
                dm.applicationnumber,
                p.partyid,
                p.linkpartyid,
                p.partytypeid,
                p.nameasperaadhar,
                p.phonenumber,
                p.sex,
                p.photopath,
                p.pan,
                p.aadharhash,
                p.idprooftypeid,
                p.isorganization,
                p.ispresenter,
                row_number() over (
                    partition by dm.finalregistrationnumber, p.partytypeid
                    order by p.partyid
                ) as rn
            from kaveri.documentmaster dm
            join kaveri.partyinfo p
                on p.applicationnumber = dm.applicationnumber
            where dm.finalregistrationnumber = p_finalregistrationnumber
              and p.partytypeid in (1, 2)
        ) x
        where x.partytypeid = 2
          and x.rn = 1
    ) e
        on e.finalregistrationnumber = bd.finalregistrationnumber
    left join (
        select *
        from (
            select
                dm.finalregistrationnumber,
                org.partyid as org_partyid,
                org.partytypeid as org_partytypeid,
                ps.partyid as auth_partyid,
                ps.nameasperaadhar as auth_name,
                ps.phonenumber as auth_phone,
                ps.sex as auth_sex,
                ps.photopath as auth_photo,
                ps.pan as auth_pan,
                ps.aadharhash as auth_aadharhash,
                ps.idprooftypeid as auth_idprooftypeid,
                row_number() over (
                    partition by dm.finalregistrationnumber, org.partyid
                    order by ps.partyid
                ) as rn
            from kaveri.documentmaster dm
            join kaveri.partyinfo org
                on org.applicationnumber = dm.applicationnumber
               and org.partytypeid in (1, 2)
               and org.isorganization = true
            join kaveri.partyinfo ps
                on ps.applicationnumber = org.applicationnumber
               and ps.linkpartyid = org.partyid
               and ps.partytypeid = 9
            where dm.finalregistrationnumber = p_finalregistrationnumber
        ) x
        where x.org_partytypeid = 1
          and x.rn = 1
    ) ca
        on ca.finalregistrationnumber = bd.finalregistrationnumber
       and ca.org_partyid = c.partyid
    left join (
        select *
        from (
            select
                dm.finalregistrationnumber,
                org.partyid as org_partyid,
                org.partytypeid as org_partytypeid,
                ps.partyid as auth_partyid,
                ps.nameasperaadhar as auth_name,
                ps.phonenumber as auth_phone,
                ps.sex as auth_sex,
                ps.photopath as auth_photo,
                ps.pan as auth_pan,
                ps.aadharhash as auth_aadharhash,
                ps.idprooftypeid as auth_idprooftypeid,
                row_number() over (
                    partition by dm.finalregistrationnumber, org.partyid
                    order by ps.partyid
                ) as rn
            from kaveri.documentmaster dm
            join kaveri.partyinfo org
                on org.applicationnumber = dm.applicationnumber
               and org.partytypeid in (1, 2)
               and org.isorganization = true
            join kaveri.partyinfo ps
                on ps.applicationnumber = org.applicationnumber
               and ps.linkpartyid = org.partyid
               and ps.partytypeid = 9
            where dm.finalregistrationnumber = p_finalregistrationnumber
        ) x
        where x.org_partytypeid = 2
          and x.rn = 1
    ) ea
        on ea.finalregistrationnumber = bd.finalregistrationnumber
       and ea.org_partyid = e.partyid
    left join kaveri.gendermaster gc
        on gc.genderid = coalesce(ca.auth_sex, c.sex)
    left join kaveri.gendermaster ge
        on ge.genderid = coalesce(ea.auth_sex, e.sex);
end;
$$;


ALTER FUNCTION kaveri.getdigilockerdocument_prod(p_finalregistrationnumber character varying) OWNER TO postgres;

