--
-- Name: insert_third_party_login_log(bigint, character varying, timestamp without time zone); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.insert_third_party_login_log(p_userid bigint, p_publicip character varying, p_logindatetime timestamp without time zone) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_updated BOOLEAN := false;
BEGIN
    
    UPDATE kaveri.ThirdPartyLoginLogInfo_New
    SET    logindatetime = p_logindatetime,
           publicip      = p_publicip
    WHERE  userid = p_userid
      AND  isactive = true;

   
    IF FOUND THEN
        v_updated := true;
    ELSE
       
        INSERT INTO kaveri.ThirdPartyLoginLogInfo_New (
            userid,
            publicip,
            isactive,
            logindatetime,
            logoutdatetime
        )
        VALUES (
            p_userid,
            p_publicip,
            true,
            CURRENT_TIMESTAMP,
            NULL
        );
        v_updated := true;  
    END IF;

    RETURN v_updated; 
END;
$$;


ALTER FUNCTION kaveri.insert_third_party_login_log(p_userid bigint, p_publicip character varying, p_logindatetime timestamp without time zone) OWNER TO postgres;

