--
-- Name: mis_booki_iii_iv(character varying, character varying, integer, character varying, character varying); Type: PROCEDURE; Schema: kaveri; Owner: csgadmin
--

CREATE PROCEDURE kaveri.mis_booki_iii_iv(IN v_passfromdate character varying, IN v_passtodate character varying, IN v_passsrocode integer, IN v_type character varying, IN v_docordmy character varying)
    LANGUAGE plpgsql
    AS $$                 -- Kaveri_2


--delete From BookI_III_IV_Data

Begin

if V_DOCorDMY='DOC' -----------------------For DocWise---------------------------------------------
Then
	begin  -- Begin of 'DOC'

insert into kaveri.BookI_III_IV_Data
		select  
			S1.Month,
			S1.BookID,
			S1.DocNo, 
			S1.NatureOfDoc as NatureOfDoc,
			Coalesce(SSum.MarketValue,0) as MarketValue,
			Coalesce(SSum.Consideration,0) as Consideration
			,Coalesce(SR.RegistrationFees,0) as RegistrationFees,
			Coalesce(SF.ScanningFees,0) as ScanningFees, 
			Coalesce(SFine.Fine,0) as Fine, 
			Coalesce(SO.OtherFees,0) as OtherFees,
			Coalesce(SSum.GovtDuty,0) as GovtDuty,
			Coalesce(SSum.SurchargeDuty,0) as SurchargeDuty,
			Coalesce(SSum.CessDuty,0) as CessDuty ,
			'dd' as DDMMYY
		from
		
		(
			select  
				-- LEFT(CONVERT(varchar(4000),DocumentMAster.Stamp5DateTime,126),10) as Month, -- 2022-03-23
				LEFT(DocumentMAster.Stamp5DateTime::varchar,10) as Month , 
				DocumentMaster.FinalRegistrationNumber as DocNo,
				DocumentMaster.BookID as BookID ,
				PropertyMaster.DocumentID as DocID,
				RegistrationArticles.ArticleNameE as NatureOfDoc
				--sum(PropertyMaster.MarketValue) as MarketValue,
				--sum(PropertyMaster.Consideration)  as Consideration,
				--sum(PropertyMaster.GovtDuty) as GovtDuty,
				--sum(PropertyMaster.AdditionalDuty) as SurchargeDuty,
				--sum(PropertyMaster.CessDuty) as CessDuty
			from 
				kaveri.PropertyMaster , 
				kaveri.DocumentMaster, 
				kaveri.RegistrationArticles		
		where 
				RegistrationArticles.RegArticleCode=DocumentMaster.RegArticleCode
				--and PropertyMaster.totalArea<>-7274 
				and DocumentMaster.DocumentID>15
				and PropertyMaster.DocumentID=DocumentMaster.DocumentID
				--and PropertyMaster.SROCode=DocumentMaster.SROCode
				--and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
				--and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
				
				and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0 
				and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
				
				
				and DocumentMaster.SROCode=V_PassSROCode
				--and isnull(DocumentMaster.FinalRegistrationNumber,'')<>''	
				and COALESCE(DocumentMaster.FinalRegistrationNumber,'')<>''
				and DocumentMaster.BookID in(1,3,4,5,6,7,8,9,10)
		group by 
					PropertyMaster.DocumentID ,DocumentMaster.BookID,
					DocumentMAster.Stamp5DateTime, DocumentMaster.FinalRegistrationNumber
					,RegistrationArticles.ArticleNameE
			) as S1
		Left Outer Join
		(
		select 
			PropertyMaster.DocumentID as DocID,
			sum(PropertyMaster.MarketValue) as MarketValue,
			sum(PropertyMaster.Consideration)  as Consideration,
			sum(PropertyMaster.GovtDuty) as GovtDuty,
			sum(PropertyMaster.AdditionalDuty) as SurchargeDuty,
			sum(PropertyMaster.CessDuty) as CessDuty
		from 
			kaveri.PropertyMaster ,
			kaveri.DocumentMaster
		where 
			PropertyMaster.totalArea<>-7274 
			and DocumentMaster.DocumentID>15
			and PropertyMaster.DocumentID=DocumentMaster.DocumentID
			--and PropertyMaster.SROCode=DocumentMaster.SROCode
			--and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
			--and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
				and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0
			and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
			and DocumentMaster.SROCode=V_PassSROCode
			--and isnull(DocumentMaster.FinalRegistrationNumber,'')<>''	
			and COALESCE(DocumentMaster.FinalRegistrationNumber,'')<>''	
			and DocumentMaster.BookID in(1,5,6,7,8,9,10)   
		group by 
			PropertyMaster.DocumentID 
			
union
		select 
				PropertyMaster.DocumentID as DocID,
				sum(PropertyMaster.MarketValue) as MarketValue,
				sum(PropertyMaster.Consideration)  as Consideration,
				--Market_Val(PropertyMaster.DocumentID) as MarketValue ,
				--Consi_Val(PropertyMaster.DocumentID) as Consideration ,
				sum(PropertyMaster.GovtDuty) as GovtDuty,
				sum(PropertyMaster.AdditionalDuty) as SurchargeDuty,
				sum(PropertyMaster.CessDuty) as CessDuty
		from 
				kaveri.PropertyMaster ,
				kaveri.DocumentMaster
		where 
				--PropertyMaster.totalArea<>-7274 
				DocumentMaster.DocumentID>15
				and PropertyMaster.DocumentID=DocumentMaster.DocumentID
				--and PropertyMaster.SROCode=DocumentMaster.SROCode
				--and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
				--and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
				and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0
				and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
						and DocumentMaster.SROCode=V_PassSROCode
				--and isnull(DocumentMaster.FinalRegistrationNumber,'')<>''	
				and COALESCE(DocumentMaster.FinalRegistrationNumber,'')<>''	
				and DocumentMaster.BookID in(3,4)
		group by 
				PropertyMaster.DocumentID 
		) as SSum
		on S1.DocID = SSum.DocID
Left Outer Join
		(
		SELECT 
				DocumentMaster.DocumentID as DocIDReg,
				sum(ReceiptDetails.AmountPaid) as RegistrationFees 
				from 
						kaveri.ReceiptMaster, 
						kaveri.ReceiptDetails, 
						kaveri.FeesRuleMaster , 
						kaveri.DocumentMaster
				where 
						ReceiptMaster.receiptid=ReceiptDetails.ReceiptId  
					and FeesRuleMaster.FeeRuleCode=ReceiptDetails.FeeRuleCode 
					and ReceiptDetails.FeeRuleCode= 1--Registration Fee
					and ReceiptMaster.DocumentId= DocumentMaster.DocumentID
					and DocumentMaster.DocumentID>15
					and DocumentMaster.SROCode=V_PassSROCode
					--and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
					--and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
					
					and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0
					and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
					and  ReceiptMaster.receipttypeid=1
				group by 
						DocumentMaster.DocumentID
		) as SR
		on S1.DocID = SR.DocIDReg
left outer join 
			(
			SELECT 
				DocumentMaster.DocumentID as DocIDScan,
				sum(ReceiptDetails.AmountPaid) as ScanningFees 
				from 
					kaveri.ReceiptMaster, 
					kaveri.ReceiptDetails, 
					kaveri.FeesRuleMaster , 
					kaveri.DocumentMaster
				where 
						ReceiptMaster.receiptid=ReceiptDetails.ReceiptId  
					and FeesRuleMaster.FeeRuleCode=ReceiptDetails.FeeRuleCode 
					and ReceiptDetails.FeeRuleCode= 2--Scanning Fee
					and ReceiptMaster.DocumentId= DocumentMaster.DocumentID
					and DocumentMaster.DocumentID>15
					and DocumentMaster.SROCode=V_PassSROCode
				--	and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
--					and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
					and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0
					and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
					and  ReceiptMaster.receipttypeid=1
				group by 
					DocumentMaster.DocumentID
			) as SF
		on 
			S1.DocID=SF.DocIDScan
left Outer join
			(
				SELECT DocumentMaster.DocumentID as DocIDOthr,
						sum(ReceiptDetails.AmountPaid) as OtherFees 
				from 
						kaveri.ReceiptMaster, 
						kaveri.ReceiptDetails, 
						kaveri.FeesRuleMaster , 
						kaveri.DocumentMaster
				where 
						ReceiptMaster.receiptid=ReceiptDetails.ReceiptId  
					and FeesRuleMaster.FeeRuleCode=ReceiptDetails.FeeRuleCode 
					and ReceiptDetails.FeeRuleCode Not in(1,2,19,20)	--Other Fee(Except Registration Fee and Scanning Fee and Fine Under Sec 25 & 34)
					and ReceiptMaster.DocumentId= DocumentMaster.DocumentID
					and DocumentMaster.DocumentID>15
						and DocumentMaster.SROCode=V_PassSROCode
					--and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
					--and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
					and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0
					and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
					and  ReceiptMaster.receipttypeid=1
				group by 
						DocumentMaster.DocumentID
			) as SO
		on 
				S1.DocID=SO.DocIDOthr	
left Outer join
			(
				SELECT 
						DocumentMaster.DocumentID as DocIDFine,
						sum(ReceiptDetails.AmountPaid) as Fine 
				from 
						kaveri.ReceiptMaster, 
						kaveri.ReceiptDetails, 
						kaveri.FeesRuleMaster , 
						kaveri.DocumentMaster
				where 
						ReceiptMaster.receiptid=ReceiptDetails.ReceiptId  
					and FeesRuleMaster.FeeRuleCode=ReceiptDetails.FeeRuleCode 
					and ReceiptDetails.FeeRuleCode  in(19,20)	--Fine( Fine Under Sec 25 & 34)
					and ReceiptMaster.DocumentId= DocumentMaster.DocumentID
					and DocumentMaster.DocumentID>15
						and DocumentMaster.SROCode=V_PassSROCode
					--and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
					--and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
					and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0
					and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
					and  ReceiptMaster.receipttypeid=1
				group by 
						DocumentMaster.DocumentID
			) as SFine
		on 
				S1.DocID=SFine.DocIDFine	
		
		Order By S1.BookID;

end ;   -- End of V_DOCorDMY='DOC'


elseif V_DOCorDMY='DMY'  -----------------------For DMYwise-----------------------------------------
Then 
begin   -- Start V_DOCorDMY='DMY'

			insert into 
				kaveri.BookI_III_IV_Data
			select 
				case V_Type
							When 'mm' Then (Datename(mm,a.Month))+datename(yy,a.Month)
							When 'dd' Then	--convert(varchar,a.Month,103 )
											a.Month::varchar	
							When 'yy' Then	
									case 
										when month(a.Month) < 4 then cast((year(a.Month)-1) as varchar(4)) ||'-'|| right(cast((year(a.Month)) as varchar(4)),2)
										when month(a.Month) > 3 then cast((year(a.Month)) as varchar(4)) || '-' || right(cast((year(a.Month)+1) as varchar(4)) ,2)
									end
						End as Month,
				a.BookID as BookID,
				Count(a.DocNo) as DocNo,
				'' as NatureOfDoc,
				sum(a.MarketValue) as MarketValue,
				sum(a.Consideration) as Consideration,
				sum(a.RegistrationFees) as RegistrationFees,
				sum(a.ScanningFees) as ScanningFees,
				sum(a.Fine) as Fine,
				sum(a.OtherFees) as OtherFees,
				sum(a.GovtDuty) as GovtDuty,
				sum(a.SurchargeDuty) as SurchargeDuty,
				sum(a.CessDuty) as CessDuty
				,V_Type as DDMMYY
			
			from
			(
			
			select  
					S1.Month,
					S1.BookID,
					S1.DocNo, 
					S1.NatureOfDoc as NatureOfDoc,
					Coalesce(SSum.MarketValue,0) as MarketValue,
					Coalesce(SSum.Consideration,0) as Consideration,
					Coalesce(SR.RegistrationFees,0) as RegistrationFees,
					Coalesce(SF.ScanningFees,0) as ScanningFees,
					Coalesce(SFine.Fine,0) as Fine, 
					Coalesce(SO.OtherFees,0) as OtherFees,
					Coalesce(SSum.GovtDuty,0) as GovtDuty,
					Coalesce(SSum.SurchargeDuty,0) as SurchargeDuty,
					Coalesce(SSum.CessDuty,0) as CessDuty
			from
			
				(
				select  
						--LEFT(CONVERT(varchar(4000),DocumentMAster.Stamp5DateTime,126),10) as Month, 
						left(DocumentMAster.Stamp5DateTime::varchar,10) as Month,
						DocumentMaster.FinalRegistrationNumber as DocNo,
						DocumentMaster.BookID as BookID ,PropertyMaster.DocumentID as DocID,
						RegistrationArticles.ArticleNameE as NatureOfDoc
						--sum(PropertyMaster.MarketValue) as MarketValue,
						--sum(PropertyMaster.Consideration)  as Consideration,
						--sum(PropertyMaster.GovtDuty) as GovtDuty,
						--sum(PropertyMaster.AdditionalDuty) as SurchargeDuty,
						--sum(PropertyMaster.CessDuty) as CessDuty
					from 
							kaveri.PropertyMaster ,
							kaveri.DocumentMaster,
							kaveri.RegistrationArticles
				where 
						RegistrationArticles.RegArticleCode=DocumentMaster.RegArticleCode
						--and PropertyMaster.totalArea<>-7274 
						and DocumentMaster.DocumentID>15
						and PropertyMaster.DocumentID=DocumentMaster.DocumentID
						--and PropertyMaster.SROCode=DocumentMaster.SROCode
						--and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
						--and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
						and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0
						and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
						and DocumentMaster.SROCode=V_PassSROCode
						--and isnull(DocumentMaster.FinalRegistrationNumber,'')<>''	
						and COALESCE(DocumentMaster.FinalRegistrationNumber,'')<>''	
						and DocumentMaster.BookID in(1,3,4,5,6,7,8,9,10)
			group by 
						PropertyMaster.DocumentID ,
						DocumentMaster.BookID,DocumentMAster.Stamp5DateTime
						,DocumentMaster.FinalRegistrationNumber
						,RegistrationArticles.ArticleNameE
			) as S1
Left Outer Join
			(
			select 
				PropertyMaster.DocumentID as DocID,
				sum(PropertyMaster.MarketValue) as MarketValue,
				sum(PropertyMaster.Consideration)  as Consideration,
				sum(PropertyMaster.GovtDuty) as GovtDuty,
				sum(PropertyMaster.AdditionalDuty) as SurchargeDuty,
				sum(PropertyMaster.CessDuty) as CessDuty
			from 
					kaveri.PropertyMaster , 
					kaveri.DocumentMaster
			where 
					PropertyMaster.totalArea<>-7274 
					and DocumentMaster.DocumentID>15
					and PropertyMaster.DocumentID=DocumentMaster.DocumentID
					--and PropertyMaster.SROCode=DocumentMaster.SROCode
				--	and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
				--	and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
					and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0
					and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
					and DocumentMaster.SROCode=V_PassSROCode
					--and isnull(DocumentMaster.FinalRegistrationNumber,'')<>''	
					and COALESCE(DocumentMaster.FinalRegistrationNumber,'')<>''	
					and DocumentMaster.BookID in(1,5,6,7,8,9,10)     
			group by 
					PropertyMaster.DocumentID 
union
			select 
				PropertyMaster.DocumentID as DocID,
				sum(PropertyMaster.MarketValue) as MarketValue,
				sum(PropertyMaster.Consideration)  as Consideration,
				--Market_Val(PropertyMaster.DocumentID) as MarketValue ,
				--Consi_Val(PropertyMaster.DocumentID) as Consideration ,
				sum(PropertyMaster.GovtDuty) as GovtDuty,
				sum(PropertyMaster.AdditionalDuty) as SurchargeDuty,
				sum(PropertyMaster.CessDuty) as CessDuty
			from 
					kaveri.PropertyMaster ,
					kaveri.DocumentMaster
			where 
					--PropertyMaster.totalArea<>-7274 
					DocumentMaster.DocumentID>15
					and PropertyMaster.DocumentID=DocumentMaster.DocumentID
					--and PropertyMaster.SROCode=DocumentMaster.SROCode
					--and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
					--and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
					and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0
					and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
					and DocumentMaster.SROCode=V_PassSROCode
				--	and isnull(DocumentMaster.FinalRegistrationNumber,'')<>''	
					and COALESCE(DocumentMaster.FinalRegistrationNumber,'')<>''	
					and DocumentMaster.BookID in(3,4)
			group by 
				PropertyMaster.DocumentID 
			
			) as SSum
		on 
				S1.DocID = SSum.DocID
Left Outer Join
			(
			SELECT 
					DocumentMaster.DocumentID as DocIDReg,
					sum(ReceiptDetails.AmountPaid) as RegistrationFees 
			from 
					kaveri.ReceiptMaster,
					kaveri.ReceiptDetails,
					kaveri.FeesRuleMaster ,
					kaveri.DocumentMaster
			where 	ReceiptMaster.receiptid=ReceiptDetails.ReceiptId  
						and FeesRuleMaster.FeeRuleCode=ReceiptDetails.FeeRuleCode 
						and ReceiptDetails.FeeRuleCode= 1--Registration Fee
						and ReceiptMaster.DocumentId= DocumentMaster.DocumentID
						and DocumentMaster.DocumentID>15
							and DocumentMaster.SROCode=V_PassSROCode
						--and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
						--and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
						and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0
						and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
					
						and  ReceiptMaster.receipttypeid=1
				group by 
						DocumentMaster.DocumentID
			) as SR
			on 
					S1.DocID = SR.DocIDReg
	left outer join 
			(
			SELECT 	DocumentMaster.DocumentID as DocIDScan,
					sum(ReceiptDetails.AmountPaid) as ScanningFees 
					from 
						kaveri.ReceiptMaster,
						kaveri.ReceiptDetails,
						kaveri.FeesRuleMaster ,
						kaveri.DocumentMaster
					where ReceiptMaster.receiptid=ReceiptDetails.ReceiptId  
						and FeesRuleMaster.FeeRuleCode=ReceiptDetails.FeeRuleCode 
						and ReceiptDetails.FeeRuleCode= 2--Scanning Fee
						and ReceiptMaster.DocumentId= DocumentMaster.DocumentID
						and DocumentMaster.DocumentID>15
							and DocumentMaster.SROCode=V_PassSROCode
						--and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
						--and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
						and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0
						and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
						and  ReceiptMaster.receipttypeid=1
					group by 
							DocumentMaster.DocumentID
			) as SF
		on 
				S1.DocID=SF.DocIDScan
left Outer join
			(
			SELECT DocumentMaster.DocumentID as DocIDOthr,
					sum(ReceiptDetails.AmountPaid) as OtherFees 
			from 
						kaveri.ReceiptMaster,
						kaveri.ReceiptDetails,
						kaveri.FeesRuleMaster ,
						kaveri.DocumentMaster
			where 
					ReceiptMaster.receiptid=ReceiptDetails.ReceiptId  
						and FeesRuleMaster.FeeRuleCode=ReceiptDetails.FeeRuleCode 
						and ReceiptDetails.FeeRuleCode Not in(1,2,19,20)	--Other Fee(Except Registration Fee and Scanning Fee and Fine Under Sec 25 & 34)
						and ReceiptMaster.DocumentId= DocumentMaster.DocumentID
						and DocumentMaster.DocumentID>15
							and DocumentMaster.SROCode=V_PassSROCode
						--and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
						--and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
						and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0
						and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
						and  ReceiptMaster.receipttypeid=1
					group by 
						DocumentMaster.DocumentID
			) as SO
			on S1.DocID=SO.DocIDOthr	
left Outer join
			(
			SELECT DocumentMaster.DocumentID as DocIDFine,
					sum(ReceiptDetails.AmountPaid) as Fine 
			from kaveri.ReceiptMaster,
						kaveri.ReceiptDetails,
						kaveri.FeesRuleMaster ,
						kaveri.DocumentMaster
				where 
						ReceiptMaster.receiptid=ReceiptDetails.ReceiptId  
						and FeesRuleMaster.FeeRuleCode=ReceiptDetails.FeeRuleCode 
						and ReceiptDetails.FeeRuleCode  in(19,20)	--Fine( Fine Under Sec 25 & 34)
						and ReceiptMaster.DocumentId= DocumentMaster.DocumentID
						and DocumentMaster.DocumentID>15
							and DocumentMaster.SROCode=V_PassSROCode
						--and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
						--and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
						and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0
						and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
						and  ReceiptMaster.receipttypeid=1
					group by 
							DocumentMaster.DocumentID
			) as SFine
		on 
				S1.DocID=SFine.DocIDFine		
				
			) as a 
			group by 
					a.BookID,
				case V_Type
					When 'mm' Then (Datename(mm,a.Month))+datename(yy,a.Month)
					When 'dd' Then	-- convert(varchar,a.Month,103 )
										a.Month::varchar
					When 'yy' Then	
						case 
							when month(a.Month) < 4 then cast((year(a.Month)-1) as varchar(4))|| '-' || right(cast((year(a.Month)) as varchar(4)),2)
							when month(a.Month) > 3 then cast((year(a.Month)) as varchar(4)) || '-' || right(cast((year(a.Month)+1) as varchar(4)) ,2)
					    end -- end of 2nd case 
				end; -- end of 1st case
		--End ;
End ; -- End of V_DOCorDMY='DMY'

End if ;


--End; -- End of First Begin 

End $$;


ALTER PROCEDURE kaveri.mis_booki_iii_iv(IN v_passfromdate character varying, IN v_passtodate character varying, IN v_passsrocode integer, IN v_type character varying, IN v_docordmy character varying) OWNER TO csgadmin;

--
-- Name: proc_daily_dashboard_apps_revenue_details(); Type: PROCEDURE; Schema: kaveri; Owner: postgres
--

CREATE PROCEDURE kaveri.proc_daily_dashboard_apps_revenue_details()
    LANGUAGE plpgsql
    AS $$

declare

ds record;
total_apps_doc bigint := 0;
total_revenue_doc bigint := 0;
total_apps_ec bigint := 0;
total_revenue_ec bigint := 0;
total_apps_cc bigint := 0;
total_revenue_cc bigint := 0;
report_process_date date;
start_process_time timestamp;
end_process_time timestamp;

start_process_scheduler_time timestamp;
end_process_scheduler_time timestamp;

is_success boolean := false;


	begin
		
		
--SELECT CURRENT_DATE - 1 into report_process_date;

select max(darsh.report_date)+1 into report_process_date from kaveri.daily_apps_revenue_scheduler_history darsh;

--- condition for previous date is null
		if report_process_date is null then
		
		report_process_date := CURRENT_DATE - 1;
		
		end if;

SELECT now() into start_process_scheduler_time;

-- loop for any missing dates

while report_process_date <= CURRENT_DATE - 1 loop
	
	  
for ds in select d.districtcode , d.districtnamee , s.srocode ,s.sronamee  from kaveri.sromaster s , kaveri.districtmaster d 
			where s.districtcode =d.districtcode order by d.districtnamee 
    
	loop 
		
				
		SELECT now() into start_process_time;
				
		--document registration application count
		select count(d.*) into total_apps_doc from kaveri.documentmaster d , kaveri.applicantapplicationdetails a where
		a.applicationnumber =d.applicationnumber
		and a.applicationtypeid in (1,2)
		and d.registrationdatetime ::date = report_process_date
		and d.srocode = ds.srocode
		and isregistrationcompleted = true;
		
		--document registration revenue start here
		select coalesce(sum(rr.amountpaid), 0) into total_revenue_doc --,  rr.applicationnumber
		from kaveri.applicantapplicationdetails a
		left join kaveri.documentmaster dm on a.applicationnumber = dm.applicationnumber
		JOIN kaveri.feesrequired rr ON dm.applicationnumber::text = rr.applicationnumber::text
		where
		a.applicationnumber = dm.applicationnumber
		and dm.applicationnumber = rr.applicationnumber
		and a.applicationtypeid in (1,2)
		and dm.registrationdatetime ::date = report_process_date
		and dm.srocode = ds.srocode
		and dm.isregistrationcompleted = true;
		
		-- EC count starts here
		select count(x.*) into total_apps_ec from kaveri.ec_applicationdetails x , kaveri.applicantapplicationdetails a where
		a.applicationnumber =x.applicationnumber
		and a.applicationtypeid in (13)
		and x.kaverisrocode = ds.srocode
		and x.inserteddatetime::date =report_process_date ;
		
		--EC revenue starts here
		select coalesce(sum(total_amount.total),0) into total_revenue_ec from (select distinct ack.deptreferencecode, ack.banktransactionnumber ,
		ack.bankname , ack.paymentmode , ack.paymentstatuscode , ack.transactiontimestamp , ack.amount as total from kaveri.applicantapplicationdetails a
		join  kaveri.ec_applicationdetails eca on eca.applicationnumber = a.applicationnumber
		left join kaveri.ams_reg_epaymenttransdetails pay on eca.ecid = pay.ecid
		join kaveri.ams_reg_epaymentbankackdetails ack on pay.deptreferencecode = ack.deptreferencecode
		where
		a.applicationtypeid = 13
		and eca.kaverisrocode = ds.srocode
		and a.currentstatus='CE103'
		and ack.paymentstatuscode in ('10700066','10700072')
		and ack.transactiontimestamp::date = report_process_date
		group by ack.deptreferencecode, ack.banktransactionnumber ,
		ack.bankname , ack.paymentmode , ack.paymentstatuscode , ack.transactiontimestamp , ack.amount) as total_amount;
		
		-- CC count starts here
		select count(x.*) into total_apps_cc from kaveri.cc_applicationdetails x , kaveri.applicantapplicationdetails a where
		a.applicationnumber =x.applicationnumber
		and a.applicationtypeid in (12)
		and x.kaverisrocode = ds.srocode
		and x.inserteddatetime::date = report_process_date ;
		
		
		--CC revenue starts here
		select coalesce(sum(total_amount.total),0) into total_revenue_cc from (select distinct ack.deptreferencecode, ack.banktransactionnumber ,
		ack.bankname , ack.paymentmode , ack.paymentstatuscode , ack.transactiontimestamp , ack.amount as total from kaveri.applicantapplicationdetails a
		join  kaveri.cc_applicationdetails cca on cca.applicationnumber = a.applicationnumber
		left join kaveri.ams_reg_epaymenttransdetails pay on cca.ccid = pay.ccid
		join kaveri.ams_reg_epaymentbankackdetails ack on pay.deptreferencecode = ack.deptreferencecode
		where
		a.applicationtypeid = 12
		and cca.kaverisrocode = ds.srocode
		and a.currentstatus='CC103'
		and ack.paymentstatuscode in ('10700066','10700072')
		and ack.transactiontimestamp::date = report_process_date
		group by ack.deptreferencecode, ack.banktransactionnumber ,
		ack.bankname , ack.paymentmode , ack.paymentstatuscode , ack.transactiontimestamp , ack.amount) total_amount;
		
		SELECT now() into end_process_time;
		
		insert into kaveri.daily_dashboard_apps_revenue_details (report_date, district_code, district_name, sro_code, sro_name, document_regs, document_revenue, ec_apps, ec_revenue, cc_apps, cc_revenue, start_time, end_time) values 
		(report_process_date, ds.districtcode, ds.districtnamee,ds.srocode ,ds.sronamee,total_apps_doc,total_revenue_doc,total_apps_ec, total_revenue_ec, total_apps_cc, total_revenue_cc, start_process_time,end_process_time);
		
		is_success = true;
		
    end loop;
   
   	SELECT now() into end_process_scheduler_time;

	if is_success = true then
	
		insert into kaveri.daily_apps_revenue_scheduler_history (scheduler_name, scheduler_date, start_time, end_time, is_sucess, report_date) values 
		('Apps_Revenue_Scheduler',CURRENT_DATE,start_process_scheduler_time, end_process_scheduler_time, true, report_process_date );
	
	else
	
		insert into kaveri.daily_apps_revenue_scheduler_history (scheduler_name, scheduler_date, start_time, end_time, is_sucess, report_date) values 
		('Apps_Revenue_Scheduler',CURRENT_DATE,start_process_scheduler_time, end_process_scheduler_time, false, report_process_date );
	
	end if;

	report_process_date := report_process_date + 1;

	end loop;


	end;
$$;


ALTER PROCEDURE kaveri.proc_daily_dashboard_apps_revenue_details() OWNER TO postgres;

