		--EC revenue starts here
		select coalesce(sum(total_amount.total),0) into total_revenue_ec from (select distinct ack.deptreferencecode, ack.banktransactionnumber ,
		ack.bankname , ack.paymentmode , ack.paymentstatuscode , ack.transactiontimestamp , ack.amount as total from kaveri.applicantapplicationdetails a
		join  kaveri.ec_applicationdetails eca on eca.applicationnumber = a.applicationnumber
		left join kaveri.ams_reg_epaymenttransdetails pay on eca.ecid = pay.ecid
