v_record record;
BEGIN
    -- Iterate over all indexes for the specified table
    for v_record in (select tablename,indexname from kaveribck.fragmented_indexes )	
	loop
        -- Build the dynamic SQL command
        -- quote_ident is used for safe handling of identifiers (names)
        v_command := 'REINDEX INDEX CONCURRENTLY ' || quote_ident('kaveri') || '.' || quote_ident(v_record.indexname) || ';';

        -- Execute the command
        RAISE NOTICE 'Executing: %', v_command;
        EXECUTE v_command;
    END LOOP;
END;
$$;


