--
-- Name: save_reg_transactionschedulerlogs(character varying, character varying, character varying, timestamp without time zone); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.save_reg_transactionschedulerlogs(_deptreferencecode character varying, _paymentmode character varying, _paymentstatus character varying, _trsntimestamp timestamp without time zone) RETURNS void
    LANGUAGE plpgsql
    AS $$

begin
	insert into kaveri.ams_reg_transactionschedulerlogs(
	deptreferencecode, 
	paymentmode, 
	paymentstatus, 
	trsntimestamp) 
	values(_deptreferencecode, 
	_paymentmode, 
	_paymentstatus, 
	_trsntimestamp);
	
	if(_paymentstatus ='10700066' or _paymentstatus = '10700072') then
		update kaveri.applicantapplicationdetails set currentstatus= 'CD107' where applicationnumber=(select distinct applicationnumber from kaveri.ams_reg_epaymenttransdetails where  deptreferencecode=_deptreferencecode);
	end if;
end;
$$;


ALTER FUNCTION kaveri.save_reg_transactionschedulerlogs(_deptreferencecode character varying, _paymentmode character varying, _paymentstatus character varying, _trsntimestamp timestamp without time zone) OWNER TO postgres;

--
-- Name: save_reg_transactionschedulerlogs(character varying, character varying, character varying, timestamp without time zone, character varying); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.save_reg_transactionschedulerlogs(_deptreferencecode character varying, _paymentmode character varying, _paymentstatus character varying, _trsntimestamp timestamp without time zone, _oldpaymentstatus character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
	v_application_number varchar;
	v_current_status varchar;
 
begin
	insert into kaveri.ams_reg_transactionschedulerlogs(
	deptreferencecode,
	paymentmode,
	paymentstatus,
	trsntimestamp,
	oldpaymentstatus)
	values(_deptreferencecode,
	_paymentmode,
	_paymentstatus,
	_trsntimestamp,
	_oldpaymentstatus);
	
	select distinct applicationnumber into v_application_number from kaveri.ams_reg_epaymenttransdetails where  deptreferencecode=_deptreferencecode;
	select currentstatus into v_current_status from kaveri.applicantapplicationdetails where applicationnumber = v_application_number;
 
	if((_paymentstatus ='10700066' or _paymentstatus = '10700072') and v_current_status = 'CD106') then
	update kaveri.applicantapplicationdetails set currentstatus= 'CD107' where applicationnumber= v_application_number;
	end if;
end;
$$;


ALTER FUNCTION kaveri.save_reg_transactionschedulerlogs(_deptreferencecode character varying, _paymentmode character varying, _paymentstatus character varying, _trsntimestamp timestamp without time zone, _oldpaymentstatus character varying) OWNER TO postgres;

