--

CREATE FUNCTION kaveri.sf_bhoomi_property_search(_survey_no integer, _hissa_no character varying) RETURNS TABLE(documentid bigint, survey_no integer, hissa_no character varying, firstname character varying, middlename character varying, lastname character varying, relationship character varying, relativename character varying, transactextacre integer, transactextgunta integer, transactextfgunta integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
   RETURN QUERY
   select 
   b.documentid,
   a.survey_no,
   a.hissa_no,  
 -- b.FirstName || ' ' || b.MiddleName || ' ' || b.LastName,
 b.FirstName,
 b.MiddleName,
 b.LastName,
b.relationship,
b.relativename,
b.transactextacre,
b.transactextgunta,
b.transactextfgunta
from kaveri.bannedpropertynumbers a,kaveri.partyinfo b
where  a.srocode = b.srocode and
a.survey_no = _survey_no--22 
and a.hissa_no = _hissa_no--'2' 
and b.FirstName || ' ' || b.MiddleName || ' ' || b.LastName <> ''
and b.transactextacre > 0;
END;
$$;


