--
-- Name: sf_court_orders(integer, integer, character varying); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.sf_court_orders(_srocode integer, _currentpropertyid integer, _currentnumber character varying) RETURNS TABLE(srocode integer, propertyid bigint, orderid bigint, currentpropertyid integer, currentnumber character varying, oldpropertyid integer, oldnumber character varying, description character varying, survey_no integer, surnoc character varying, hissa_no character varying, property_description character varying, isagriculturalprperty boolean, eastbounday character varying, northboundary character varying, westboundary character varying, southboundary character varying, area numeric, measurementunit integer, descriptionenglish character varying, ordernumber character varying, orderentrydatetime timestamp without time zone, iscancelled boolean, reasonofcancellation character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
   RETURN QUERY
   SELECT  --ID
      BPN.SROCode,BPN.PropertyID
      ,BPN.OrderID,CurrentPropertyTypeID
      ,bpn.CurrentNumber,bpn.OldPropertyTypeID
      ,bpn.OldNumber,BPN.Description
      ,bpn.Survey_No,bpn.Surnoc
      ,bpn.Hissa_No,BP.PropertyDescription
 ,BP.IsAgriculturalProperty,BP.EastBoundary
 ,BP.NorthBoundary,BP.WestBoundary
 ,BP.SouthBoundary,BP.Area
 ,BP.MeasurementUnit,MUM.DescriptionEnglish
 ,CO.OrderNumber--,CO.Description as CO_Description
 ,CO.OrderEntryDateTime,CO.IsCancelled
 ,CO.ReasonOfCancellation
  FROM kaveri.BannedPropertyNumbers BPN inner join kaveri.BannedProperties BP
  on
  BPN.PropertyID=BP.PropertyID and BPN.SROCode=BP.SROCode
  inner join kaveri.CourtOrders CO
  on
  BP.SROCode=CO.SROCode and BP.OrderID=CO.OrderID
  inner join kaveri.MeasUnitMaster MUM
  on MUM.UnitID=BP.MeasurementUnit
  where BPN.SROCode=_SROCode--209 
  and bpn.CurrentPropertyTypeID=_CurrentPropertyID--3 
  and bpn.CurrentNumber=_CurrentNumber--'41'
   or BPN.SROCode=_SROCode--209 
   and bpn.OldPropertyTypeID=_CurrentPropertyID--3
   and bpn.OldNumber=_CurrentNumber;--'41';
	END;
   $$;


