--
-- Name: sf_dashboard_application_nomenclature_count(); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.sf_dashboard_application_nomenclature_count() RETURNS TABLE(_applicationstartdate timestamp without time zone, _applicationenddate timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
_DAYS integer;
_DAYS1 integer;
BEGIN
/*select date_trunc('month',
 current_date)+'1month'::interval::interval - date_trunc('month', current_date) into _DAYS1 ;*/
SELECT (applicationenddate::date - applicationstartdate::date ) into _DAYS from kaveri.applicantapplicationdetails;
if _DAYS < 30 then
   RETURN QUERY
  select extract('day' from date_trunc('week', applicationstartdate) -
                   date_trunc('week', date_trunc('month', applicationstartdate))) / 7 as weekno,
left(applicationnumber,3) nomenclature,count(*)
 from kaveri.applicantapplicationdetails where  applicationstartdate 
 between _applicationstartdate and _applicationenddate		
 group by weekno,nomenclature;
 else
 RETURN QUERY
 select TO_CHAR(applicationstartdate, 'Month') as month,left(applicationnumber,3) nomenclature,count(*)
 from kaveri.applicantapplicationdetails where  applicationstartdate 
				   between  _applicationstartdate and _applicationenddate			
 group by month,nomenclature;
 end if;
	END;
$$;


ALTER FUNCTION kaveri.sf_dashboard_application_nomenclature_count() OWNER TO csgadmin;

