--
-- Name: sp_check_application_exist(character varying); Type: PROCEDURE; Schema: kaveri; Owner: raghavendrap
--

CREATE PROCEDURE kaveri.sp_check_application_exist(IN _applicationnumber character varying)
    LANGUAGE plpgsql
    AS $$

DECLARE
    r RECORD;
    rec RECORD;
    cols TEXT;
    vals TEXT;
BEGIN
    IF EXISTS (SELECT * FROM kaveri.applicantapplicationdetails WHERE applicationnumber = _applicationnumber) THEN
    FOR r IN
        SELECT c.table_schema, t.table_name
        FROM information_schema.tables t
        JOIN information_schema.columns c ON t.table_name = c.table_name AND t.table_schema = c.table_schema
        WHERE c.table_schema = 'kaveri'
          AND column_name = 'applicationnumber'
          AND t.table_type = 'BASE TABLE' and t.table_name not in ('fruitsduplicaterecordissue_20260731','fruits_issue_20260731','partyinfo_fruits_20260722','partyschedules_fruits_20260722','propertymaster_fruits_20260722','propertyschedules_fruits_20260722')
        GROUP BY c.table_schema, t.table_name
    LOOP

        SELECT string_agg(quote_ident(column_name), ', ')
        INTO cols
        FROM information_schema.columns
        WHERE table_schema = r.table_schema
          AND table_name = r.table_name
          AND column_name <> 'surid';

        FOR rec IN EXECUTE format(
            'SELECT * FROM %I.%I WHERE applicationnumber::text = %L',
            r.table_schema, r.table_name, _applicationnumber
        )
        LOOP
            SELECT string_agg(
                CASE
                    WHEN val IS NULL THEN 'NULL'
                    ELSE quote_literal(val)
                END, ', '
            )
            INTO vals
            FROM json_each_text(row_to_json(rec)) AS t(col, val)
            WHERE col <> 'surid';

            RAISE NOTICE 'INSERT INTO %.% (%) VALUES (%);',
                r.table_schema, r.table_name, cols, vals;
        END LOOP;

    END LOOP;
    ELSE
        RAISE NOTICE 'Application Not Exist';
    END IF;
END;
$$;


ALTER PROCEDURE kaveri.sp_check_application_exist(IN _applicationnumber character varying) OWNER TO raghavendrap;

