end if;
*/

	
	
	end loop ;   -- End of Cursor 
end loop ;	
	
End $$;


ALTER PROCEDURE kaveri.sp_dailyregister_v3() OWNER TO csgadmin;

--
-- Name: sp_dailyregister_v3(timestamp without time zone); Type: PROCEDURE; Schema: kaveri; Owner: csgadmin
--

CREATE PROCEDURE kaveri.sp_dailyregister_v3(IN passdailydate timestamp without time zone)
    LANGUAGE plpgsql
    AS $$                 -- Kaveri_2
 
-- Variables to hold the date field
--declare Tmp_DailyDate varchar(25);
--declare Tmp_DailyDate character varying(25);

declare Tmp_DailyDate timestamp without time zone;

declare Tmp_SROCode integer;
-- declare c_Tmp_SROCode integer;

--Variables for Insertation of original data;  
-- call stored_procedure_name(argument_list);
  
  
  declare Tmp_PresentDateTime timestamp;
  declare tmp_stamp5datetime  timestamp;
  
  declare Tmp_DocumentID bigint;
  declare Tmp_SROName varchar(500);
  
  declare Tmp_districtcode int;
  
  
  declare Tmp_Presenttimestamp timestamp;
  declare Tmp_PresenterName varchar(500);
  declare Tmp_ArticleName varchar(500);		
  declare Tmp_ConsiderationAmount money;	
  declare Tmp_StampDuty money;	
  declare Tmp_StampDutyRequired money;	
  declare Tmp_StampDutyPaid money;	
  declare Tmp_GovtDuty money;	
  declare Tmp_Infrastructure money;	
  declare Tmp_Muncipal money;	
  declare Tmp_Corporation money;	
  declare Tmp_TalukaBoard money;	
  declare Tmp_DocumentNumber varchar(50);
  declare Tmp_BookID varchar(180);
  declare Tmp_VolumeName varchar(50);
  declare Tmp_Stamp5timestamp timestamp;
  declare Tmp_ReutrnDate timestamp;
  declare Tmp_RegistrationFee money;	
  declare Tmp_Deficient_RegistrationFee money;	
  declare Tmp_Deficient_StampDuty money;
  declare Tmp_CopyFee money;	
  declare Tmp_HinduFee money;	
  declare Tmp_SplOtherFee money;	
  declare Tmp_SplFee money;	
  declare Tmp_MutationFee money;	
  declare Tmp_Remarks varchar(500);
 declare  Tmp_Namef varchar(50);
 declare  Tmp_Namem varchar(50);
 declare  Tmp_Namel varchar(50);
 declare  Tmp_MarriageFees money;
 declare  Tmp_marriageTypeId integer;
declare	Tmp_SDRefund	money; 	/* Addition on 28 Apr 2003 			*/
declare 	Tmp_RFRefund	money; 	/* Addition on 28 Apr 2003 			*/
Declare PaymentModeID 	Integer; /* Addition on 07 May 2003 for Registration Fee	*/
Declare AmountPaid		money;	/* Addition on 07 May 2003 for Registration Fee 	*/
Declare v_ExemptionDescription  Varchar(2000);	/* Addition on 27 May 2003 for Exemption	*/
Declare StampTypeId		Integer;	/* Addition on 23 June 2003 for StampDuty Calculation*/
Declare Amount		Money;	/* Addition on 23 June 2003 for StampDuty Calculation*/
Declare Total_Amount		Money;	/* Addition on 23 June 2003 for StampDuty Calculation*/
declare v_AdditionalDuty		Integer;	/* 16 July 2003*/

--declare SDCalculation	 	Integer;	/* To determine Area Type (Muncipal/Corporation/Taluka/Panchayat) -16 July 2003*/
declare SDCalculation	varchar(500);   -- Kaveri_2  	

declare v_PrevTotalStampDuty	money; 	/* Addition on 16 July 2003 			*/
declare v_PrevTotalRegistrationFees	money; 	/* Addition on 16 July 2003 		*/
declare v_PrevTotalCopyFees	money; 	/* Addition on 16 July 2003 			*/
declare v_PrevTotalMarriageFee	money; 	/* Addition on 16 July 2003 			*/
declare v_PrevTotalMutationFee	money; 	/* Addition on 16 July 2003 			*/

declare Tmp_ReceiptAmount money; 	/* Addition on 05 Aug 2003 			*/
declare Tmp_ReceiptNumber bigint;   /* Addition on 05 Aug 2003 			*/
declare Tmp_ReceiptDate     timestamp; /* Addition on 05 Aug 2003 			*/
declare Tmp_ReceiptType    Integer;   /* Addition on 05 Aug 2003 			*/
declare Tmp_ReceiptDescription  Varchar(75); /* Addition on 05 Aug 2003 			*/
declare Tmp_Name varchar(500); /* Addition on 05 Aug 2003 			*/
declare Tmp_receiptID bigint; /*Added by Patil s m on 30 dec 2004*/

declare fName varchar(1000);
declare mName varchar(1000);
declare lName varchar(1000);

--For Receipt
declare Tmp_DocumentID_Rec bigint;
declare Tmp_ReceiptID_Rec bigint;
declare Tmp_FeeRuleCode_Rec bigint;
declare Tmp_ReceiptAmount_Rec money; 

declare Tmp_ReceiptCount int;
declare Tmp_ReceiptCounter int;
declare Tmp_PreviousDocumentID bigint;
declare Tmp_UPD_Receiptnumber varchar(200);


--Variables for Getting the Data of Previous Date
  declare Tmp_PreviousDate timestamp;
declare Tmp_PreviousDate_Marr timestamp;

--Variables for Insertation of Market Value
declare Tmp_MarketValue money;	

-- Declare records variable for Cursor 
declare cur_DailyRegister record;
declare cur_ForReceiptBifercation record;
declare cur_OtherFees record;

		declare Tmp_ReceiptFeeRulecode integer;
		declare Tmp_ReceipPaymentModeID integer;
		declare Tmp_OtherReceiptID bigint :=0 ; 
		declare Tmp_OtherReceiptIDPresentOrNot bigint  :=0 ; 
		declare Tmp_AmountAlreadyPresent money; 
		Declare Tmp_AmountbyCash money;
		Declare Tmp_AmountbyOther money;
		
		
		declare cur_srocode record;
		
		
Begin 

-- Added for Testing only
  truncate table DailyReceiptFees_V3;
  

  for cur_srocode in   -- Create Cursor for Kaveri_2
   (
 
select 
	distinct sm.srocode, sm.districtcode 
from
	kaveri.sromaster sm , 
	kaveri.districtmaster dm
where 
	sm.districtcode  = dm.districtcode
   )
   
  loop  
  
  

	Tmp_MarketValue := 0::money ;
	--Tmp_DailyDate := PassDailyDate;
	Tmp_DailyDate := current_timestamp;
	
	Tmp_SROCode := cur_srocode.srocode;   --- PassSROCode;
    Tmp_districtcode := cur_srocode.districtcode;
  
--Select Query to calcuate the previous date 

-- Pending -- Need to understand Tmp_PreviousDate Logic 

  
/*   -- commented for Kaveri_2

     SELECT 
	-- TOP 1  -- Kaveri_2
	RM.DateOfReceipt 
		into 
			Tmp_PreviousDate
    FROM kaveri.ReceiptMaster RM
    where 
	    Date_Part('Day', RM.DateOfReceipt - Tmp_DailyDate::timestamp ) >0  AND  -- Kaveri_2 -- Need to validate 
     and RM.srocode = cur_srocode.srocode;   -- Tmp_SROCode
	  
	-- DATEDIFF ( d ,  ReceiptMaster.DateOfReceipt ,convert(timestamp,Tmp_DailyDate,103))>0   -- Kaveri_2
    --AND ReceiptTypeID in (1,2,3,4)
	ORDER BY DateOfReceipt  desc
		LIMIT 1; 	-- Kaveri_2
*/


-- Logic added for Kaveri_2

  

/*
     SELECT 
	-- TOP 1  -- Kaveri_2
	max(RM.DateOfReceipt )
		into 
			Tmp_PreviousDate
    FROM 
		kaveri.ReceiptMaster RM,
		kaveri.sromaster sm
    where 
	    Date_Part('Day', RM.DateOfReceipt - Tmp_DailyDate::timestamp ) >0  AND  -- Kaveri_2 -- Need to validate 
      RM.srocode = Tmp_SROCode AND 
	  RM.srocode = sm.srocode AND 
	  sm.districtcode = Tmp_districtcode; 
*/


-- RAISE NOTICE 'Previous Date: %', Tmp_PreviousDate  ;

 -- Temporary delete until testing is complete
  
  /*  -- comented for Kaveri_2 
Delete from kaveri.DailyReceiptFees_V3
 as d
using kaveri.sromaster  as s 
where d.sroname =  s.sronamee           -- Kaveri_2 need to clarify pending 
and   s.srocode = Tmp_SROCode ;
--AND 1 = 2  ; 

*/

 
  

--select * from DailyReceiptFees_V3
-- select Tmp_ReceiptCounter = 0;  
 Tmp_ReceiptCounter := 0;



for cur_DailyRegister in (
select 
Distinct 
		--DocumentMaster.DocumentID,
		--SROMaster.SRONamek, 
		SROMaster.SROCode,
		SROMaster.districtcode , -- New column for Kaveri_2
		ReceiptMaster.DateOfReceipt ,
		
   (Partyinfo.firstName || ' ' || Partyinfo.middleName || ' ' || Partyinfo.lastName) as PresenterName,    -- Kaveri_2 -- Name of Presenter
	((DocumentMaster.PresentDatetime::date)::timestamp) as PresentDateTime,  -- Date of Presentation
	
	--kaveri.documenttypemaster..documenttypedesc   --(Description of document) need to validate from Mahesh 
	
	RegistrationArticles.ArticleName as documenttypedesc,  -- need to confirm  on this ??
	
	DocumentMaster.ConsiderationAmount,  -- considetaion
	
	--DocumentMaster.DocumentNumber,
	--BookTypeMaster.BookNameKannada,
	DocumentMaster.Stamp5DateTime,        -- CompletionDate 
	DocumentMaster.WithdrawalDate,			-- ReturnDate
	DocumentMaster.CDNumber as VolumnNumber,				-- VolumnNumber
	--ReceiptMaster.receiptID,
	DocumentMaster.BookID
				
from 	kaveri.DocumentMaster,
		--kaveri.documenttypemaster, -- Kaveri_2

		kaveri.RegistrationArticles,
		kaveri.PartyInfo,
		kaveri.SROMaster,
		kaveri.BookTypeMaster, 
		kaveri.ReceiptMaster /* PropertyMaster , */
where  DocumentMaster.RegArticleCode = RegistrationArticles.RegArticleCode 
and DocumentMaster.DocumentID=PartyInfo.DocumentID 
and PartyInfo.ISPresenter = 1::boolean    -- ??
and SROMaster.SROCode = DocumentMaster.SROCode
and SROMaster.districtcode  =   Tmp_districtcode    -- New condition 
and DocumentMaster.SROCode = Tmp_SROCode  
and ReceiptMaster.DocumentID = DocumentMaster.DocumentID
and  ReceiptMaster.srocode = Tmp_SROCode  --  Tmp_SROCode   ---- Added new condition Kaveri_2
and BookTypeMaster.BookID = DocumentMaster.BookID
and DocumentMaster.DocumentID >= 15   --- ??
AND ReceiptMaster.ReceiptTypeID = 1   --- ??
--AND (Date_Part('Day', ReceiptMaster.DateOfReceipt - Tmp_DailyDate::timestamp ) =0  OR
     --Date_Part('Day', ReceiptMaster.DateOfReceipt - Tmp_PreviousDate::timestamp ) =0 )
	 -- Pending -- Need to add Date condition 
	 )


--order by
--	ReceiptMaster.receiptID,

	
	
	

loop


--RAISE NOTICE 'DocumentID - %', cur_DailyRegister.DocumentID;
--RAISE NOTICE 'DocumentNumber - %', cur_DailyRegister.DocumentNumber;
--RAISE NOTICE 'ReceiptID - %', cur_DailyRegister.ReceiptID;


		insert into kaveri.DailyReceiptFees_V3
					( 
					--DocumentID,
				--	SROName,
					srocode,  -- New column Added Kaveri_2
					districtcode ,
					PresentDateTime,
					PresenterName, 
					--StampArticleName,
					ConsiderationAmount,
				--	DocumentNumber,
					BookID,
					CompletionDate,
					DateOfReturn,
					VolumnNumber   --,
					--ReceiptID
					)

				values(	
				   -- cur_DailyRegister.DocumentID,
					--cur_DailyRegister.SRONamek,
					cur_DailyRegister.srocode ,   -- Kaveri_2	
					cur_DailyRegister.districtcode,					
					cur_DailyRegister.PresentDateTime,
					cur_DailyRegister.PresenterName, 
					--cur_DailyRegister.ArticleNameK,    -- StampArticleName
					cur_DailyRegister.ConsiderationAmount,
				--	cur_DailyRegister.DocumentNumber,
					cur_DailyRegister.BookID,
					cur_DailyRegister.Stamp5DateTime,   -- CompletionDate
					cur_DailyRegister.WithdrawalDate, -- DateOfReturn
					cur_DailyRegister.VolumnNumber -- , -- cur_DailyRegister.VolumeName,   
					--cur_DailyRegister.receiptID 
					) ;

		--Update Consideration/Market value which is greater

		/*
if( Tmp_PreviousDocumentID <> cur_DailyRegister.DocumentID )
		Then
		BEGIN
		Tmp_ReceiptCounter := 0;
		END;
end if;
*/

	
	
	end loop ;   -- End of Cursor 
end loop ;	
	
End $$;


