CREATE PROCEDURE kaveri.sp_dailyregister_v3(IN passdailydatestart character varying, IN passdailydateend character varying)
    LANGUAGE plpgsql
    AS $$                 -- Kaveri_2
 
-- Variables to hold the date field
--declare Tmp_DailyDate varchar(25);
