  declare Tmp_StampDutyRequired money;	
  declare Tmp_StampDutyPaid money;	
  declare Tmp_TotDutyOnDocument money;
  
  declare Tmp_GovtDuty money;	
  declare Tmp_Infrastructure money;	
  declare Tmp_Muncipal money;	
  declare Tmp_Corporation money;	
  declare Tmp_TalukaBoard money;	
  declare Tmp_DocumentNumber varchar(50);
  declare Tmp_BookID varchar(180);
