--AND 1 = 2  ; 

*/

 
  

--select * from DailyReceiptFees_V3
-- select Tmp_ReceiptCounter = 0;  
 Tmp_ReceiptCounter := 0;



--for cur_DailyRegister in (
--select 
--Distinct 
--		--DocumentMaster.DocumentID,
--		--SROMaster.SRONamek, 
--		SROMaster.SROCode,
--		SROMaster.districtcode , -- New column for Kaveri_2
--		ReceiptMaster.DateOfReceipt ,
--		
--   (Partyinfo.firstName || ' ' || Partyinfo.middleName || ' ' || Partyinfo.lastName) as PresenterName,    -- Kaveri_2 -- Name of Presenter
--	((DocumentMaster.PresentDatetime::date)::timestamp) as PresentDateTime,  -- Date of Presentation
--	
--	--kaveri.documenttypemaster..documenttypedesc   --(Description of document) need to validate from Mahesh 
--	
--	RegistrationArticles.ArticleNamee as documenttypedesc,  -- need to confirm  on this ??
--	
--	DocumentMaster.ConsiderationAmount,  -- considetaion
--	
--	--DocumentMaster.DocumentNumber,
--	--BookTypeMaster.BookNameKannada,
--	DocumentMaster.Stamp5DateTime,        -- CompletionDate 
--	DocumentMaster.WithdrawalDate,			-- ReturnDate
--	DocumentMaster.CDNumber as VolumnNumber,				-- VolumnNumber
--	--ReceiptMaster.receiptID,
--	DocumentMaster.BookID
--				
--from 	kaveri.DocumentMaster,
--		--kaveri.documenttypemaster, -- Kaveri_2
--
--		kaveri.RegistrationArticles,
--		kaveri.PartyInfo,
--		kaveri.SROMaster,
--		kaveri.BookTypeMaster, 
--		kaveri.ReceiptMaster /* PropertyMaster , */
--where  DocumentMaster.RegArticleCode = RegistrationArticles.RegArticleCode 
--and DocumentMaster.DocumentID=PartyInfo.DocumentID 
--and PartyInfo.ISPresenter = 1::boolean    -- ??
--and SROMaster.SROCode = DocumentMaster.SROCode
--and SROMaster.districtcode  =   Tmp_districtcode    -- New condition 
--and DocumentMaster.SROCode = Tmp_SROCode  
--and ReceiptMaster.DocumentID = DocumentMaster.DocumentID
--and  ReceiptMaster.srocode = Tmp_SROCode  --  Tmp_SROCode   ---- Added new condition Kaveri_2
--and BookTypeMaster.BookID = DocumentMaster.BookID
--and DocumentMaster.DocumentID >= 15   --- ??
--AND ReceiptMaster.ReceiptTypeID = 1   --- ??
----AND (Date_Part('Day', ReceiptMaster.DateOfReceipt - Tmp_DailyDate::timestamp ) =0  OR
--     --Date_Part('Day', ReceiptMaster.DateOfReceipt - Tmp_PreviousDate::timestamp ) =0 )
--	 -- Pending -- Need to add Date condition 
--	 )
--

--order by
--	ReceiptMaster.receiptID,

	
	
for cur_DailyRegister in (
	
 Select 
	DocumentMaster.DocumentID,
	--SROMaster.SRONamek, 
	SROMaster.SROCode,
	SROMaster.districtcode , -- New column for Kaveri_2
	ReceiptMaster.DateOfReceipt ,
	(Partyinfo.firstName || ' ' || Partyinfo.middleName || ' ' || Partyinfo.lastName) as PresenterName,    -- Kaveri_2 -- Name of Presenter
	((DocumentMaster.PresentDatetime::date)::timestamp) as PresentDateTime,  -- Date of Presentation
	--kaveri.documenttypemaster..documenttypedesc   --(Description of document) need to validate from Mahesh 
	RegistrationArticles.ArticleNamee as documenttypedesc,  -- need to confirm  on this ??
	DocumentMaster.ConsiderationAmount,  -- considetaion
	--DocumentMaster.DocumentNumber,
	--BookTypeMaster.BookNameKannada,
	DocumentMaster.Stamp5DateTime,        -- CompletionDate 
	DocumentMaster.WithdrawalDate,			-- ReturnDate
	DocumentMaster.CDNumber as VolumnNumber,				-- VolumnNumber
	ReceiptMaster.receiptID,
	DocumentMaster.BookID
from 
	kaveri.SROMaster,
	kaveri.DocumentMaster,
	--kaveri.BookTypeMaster,
	kaveri.PartyInfo,
	kaveri.RegistrationArticles,
	kaveri.ReceiptMaster
where 
  SROMaster.srocode = Tmp_SROCode and 
  SROMaster.districtcode = Tmp_districtcode and 
  SROMaster.SROCode = DocumentMaster.SROCode and 
  DocumentMaster.DocumentID >= Tmp_SROCode  and 
 -- BookTypeMaster.BookID = DocumentMaster.BookID and 
  DocumentMaster.DocumentID=PartyInfo.DocumentID and 
  DocumentMaster.srocode=PartyInfo.srocode and   
  PartyInfo.ISPresenter = 1::boolean and 
  --BookTypeMaster.BookID = DocumentMaster.BookID and 
  DocumentMaster.RegArticleCode = RegistrationArticles.RegArticleCode and 
  ReceiptMaster.DocumentID = DocumentMaster.DocumentID and
  ReceiptMaster.srocode = Tmp_SROCode -- and 
  -- ReceiptMaster.ReceiptTypeID = 1 	-- need to clarify
  and ( DocumentMaster.Stamp5DateTime >=  PassDailyDateStart::timestamp      and 
  DocumentMaster.Stamp5DateTime <= PassDailyDateEnd::timestamp    )
  )
	

loop


/*  -- Need to confirm if consideration amount need to take from DocumentMaster.ConsiderationAmount or as per below kaveri_1 logic 
SELECT CASE WHEN  sum(MarketValue) < Sum(CASE Consideration WHEN 1 then 0 ELSE Consideration END)  
			THEN Sum(CASE Consideration WHEN 1 then 0 ELSE Consideration END)  
			ELSE sum(MarketValue) 
			END 
		into 
			Tmp_ConsiderationAmount
		from kaveri.PropertyMaster 
		where 
			PropertyMaster.srocode = Tmp_SROCode  and 
			DocumentID = cur_DailyRegister.DocumentID and 
			TotalArea <> -7274;   ---- Need to clarify the number 
*/			
			

		insert into kaveri.DailyReceiptFees_V3
					( 
					DocumentID,
				--	SROName,
					srocode,  -- New column Added Kaveri_2
					districtcode ,
					PresentDateTime,
					PresenterName, 
					--StampArticleName,
					ConsiderationAmount,
				--	DocumentNumber,
					BookID,
					CompletionDate,
					DateOfReturn,
					VolumnNumber   --,
					--ReceiptID
					)

				values(	
				    cur_DailyRegister.DocumentID,
					--cur_DailyRegister.SRONamek,
					cur_DailyRegister.srocode ,   -- Kaveri_2	
					cur_DailyRegister.districtcode,					
					cur_DailyRegister.PresentDateTime,
					cur_DailyRegister.PresenterName, 
					--cur_DailyRegister.ArticleNameK,    -- StampArticleName
					cur_DailyRegister.ConsiderationAmount,
				--	cur_DailyRegister.DocumentNumber,
					cur_DailyRegister.BookID,
					cur_DailyRegister.Stamp5DateTime,   -- CompletionDate
					cur_DailyRegister.WithdrawalDate, -- DateOfReturn
					cur_DailyRegister.VolumnNumber -- , -- cur_DailyRegister.VolumeName,   
					--cur_DailyRegister.receiptID 
					) ;



UPDATE kaveri.DailyReceiptFees_V3 D 
	set 
			StampDuty = B.AmountByCash + B.AmountByOther 
			--StampDuty_Others = B.AmountByOther 
			FROM
					(
						SELECT  
						--	A.srocode,
						--	A.DocumentID,
							SUM(Case A.StampTypeId WHEN 2 THEN A.Amount Else 0 END ) as AmountByCash,
							SUM(Case A.StampTypeId WHEN 2 THEN 0 Else A.Amount  END ) as AmountByOther
					From	 (
							SELECT  sd.StampTypeId, 
									sd.srocode,
									sd.DocumentID ,
									SUM(sd.Amount) as Amount
							FROM 
									kaveri.StampDetails sd
							WHERE 
									sd.DocumentId =   cur_DailyRegister.DocumentID and -- @Tmp_DocumentID
									sd.srocode = Tmp_SROCode
							GROUP BY 
								sd.srocode, sd.DocumentID, sd.StampTypeId
							) as A
					) as B
				WHERE 
					D.srocode =  Tmp_SROCode  AND 
					D.DocumentID =  cur_DailyRegister.DocumentID ;					
			
			
	

			Tmp_Corporation := 0::money;
			Tmp_Muncipal := 0::money;
			Tmp_TalukaBoard := 0::money;
		
		
			SELECT 
			    --Convert(Integer,SUBSTRING(SUBSTRING(SDCalculationString,PATINDEX('%<AD>%', SDCalculationString),6 ),6,1)) as SDCalculation,
				SDCalculationString as SDCalculation,
				AdditionalDuty , 
				GovtDuty as Tmp_GovtDuty, 
				CessDuty as Tmp_Infrastructure,
				(COALESCE(AdditionalDuty,0) + COALESCE(GovtDuty,0) + COALESCE(CessDuty,0)) as TotDutyOnDocument
			into 
				SDCalculation, v_AdditionalDuty, Tmp_GovtDuty, Tmp_Infrastructure, Tmp_TotDutyOnDocument
			FROM 
					kaveri.PropertyMaster
			WHERE   DocumentId =  cur_DailyRegister.DocumentID and 
					srocode = Tmp_SROCode and 
					TotalArea <> -7274;
		
		
			IF 
				SDCalculation = '1'  Then Tmp_Corporation  := v_AdditionalDuty;
				ELSEIf 
				 SDCalculation = '2' Then Tmp_Muncipal  := v_AdditionalDuty;   --- SurchargDutyMuncipal
				ELSEIf
				SDCalculation = '3' Then Tmp_TalukaBoard  := v_AdditionalDuty;   --- SurchrgDutyTalukBoard
			End If ; 	

			
		

				UPDATE kaveri.DailyReceiptFees_V3 D 
					SET 	
						--GovtDuty 			=   Tmp_GovtDuty,
						--Infrastructure 	=   Tmp_Infrastructure,
						SurchargDutyMuncipal	= 	Tmp_Muncipal,
						--Corporation		= 	Tmp_Corporation,
						SurchrgDutyTalukBoard		= 	Tmp_TalukaBoard		,
						TotDutyOnDocument   = Tmp_TotDutyOnDocument
					--From 
						-- Kaveri.DailyReceiptFees_V3 D,
--						kaveri.sromaster  s
					where   
						--	D.sroname =  s.sronamee   and        -- Kaveri_2 need to clarify pending 
							D.srocode =  Tmp_SROCode
						and D.DocumentID =  cur_DailyRegister.DocumentID ;


						
						
						
						
						
		
     --declare cur_ForReceiptBifercation  scroll cursor for 
	   for cur_ForReceiptBifercation in (
				select ReceiptMaster.DocumentID as DocumentID_Rec,
						ReceiptMaster.ReceiptID as ReceiptID_Rec,
						ReceiptDetails.AmountPaid  as AmountPaid_Rec,
						ReceiptDetails.FeeRuleCode as FeeRuleCode_Rec
				From 
						kaveri.ReceiptMaster,
						kaveri.ReceiptDetails
				where 
					ReceiptDetails.ReceiptID = ReceiptMaster.ReceiptID 
				AND ReceiptDetails.ReceiptID = cur_DailyRegister.ReceiptID
				ANd ReceiptMaster.SROCode = ReceiptDetails.SROCode
				AND  ReceiptDetails.SROCode = Tmp_SROCode  
			)

		--	open cur_ForReceiptBifercation;
		--	fetch next from cur_ForReceiptBifercation into   
		--			@Tmp_DocumentID_Rec,@Tmp_ReceiptID_Rec,@Tmp_ReceiptAmount_Rec,@Tmp_FeeRuleCode_Rec
		--		while @@fetch_status=0	
		loop	

				--RAISE NOTICE 'p_FeeRuleCode_Rec %', cur_ForReceiptBifercation.FeeRuleCode_Rec;

			
		if cur_ForReceiptBifercation.FeeRuleCode_Rec = 2
				Then
					BEGIN 
					update kaveri.DailyReceiptFees_V3 D  set 
						CopyFees = COALESCE(D.CopyFees,0) + cur_ForReceiptBifercation.AmountPaid_Rec 
					From 
						kaveri.ReceiptMaster RM
					WHERE 
					    D.srocode =  Tmp_SROCode
					and D.DocumentID = cur_ForReceiptBifercation.DocumentID_Rec 
					and RM.DocumentID = D.DocumentID
					and RM.srocode = D.srocode
					and RM.receiptid = cur_ForReceiptBifercation.ReceiptID_Rec ;
						
					
					
					END ;
				ELSEif cur_ForReceiptBifercation.FeeRuleCode_Rec = 31
			Then
					BEGIN
					
					update kaveri.DailyReceiptFees_V3 D 
				set 
					
			Deficient_RegistrationFees = COALESCE(D.Deficient_RegistrationFees,0) + cur_ForReceiptBifercation.AmountPaid_Rec 
					From 
						kaveri.ReceiptMaster RM
					WHERE 
					    D.srocode =  Tmp_SROCode
					and D.DocumentID = cur_ForReceiptBifercation.DocumentID_Rec 
					and RM.DocumentID = D.DocumentID
					and RM.srocode = D.srocode
					and RM.receiptid = cur_ForReceiptBifercation.ReceiptID_Rec ;
						  
					END ;
					
				elseif cur_ForReceiptBifercation.FeeRuleCode_Rec = 6
			Then
					BEGIN
					
				update kaveri.DailyReceiptFees_V3 D
					set 
					
					MutationFee = COALESCE(D.MutationFee,0) +  cur_ForReceiptBifercation.AmountPaid_Rec 
					From 
						kaveri.ReceiptMaster RM
					WHERE 
					    D.srocode =  Tmp_SROCode
					and D.DocumentID = cur_ForReceiptBifercation.DocumentID_Rec 
					and RM.DocumentID = D.DocumentID
					and RM.srocode = D.srocode
					and RM.receiptid = cur_ForReceiptBifercation.ReceiptID_Rec ;
				
					END ;
				elseif (cur_ForReceiptBifercation.FeeRuleCode_Rec = 28 or  
				        cur_ForReceiptBifercation.FeeRuleCode_Rec = 35) -- Added Fee rule code 35 condition by aparna on 06-05-2019
			Then
				BEGIN
					
					update kaveri.DailyReceiptFees_V3 D 
					set
						
						Deficient_StampDuty = COALESCE(D.Deficient_StampDuty,0) + cur_ForReceiptBifercation.AmountPaid_Rec 
					From 
						kaveri.ReceiptMaster RM
					WHERE 
					    D.srocode =  Tmp_SROCode
					and D.DocumentID = cur_ForReceiptBifercation.DocumentID_Rec 
					and RM.DocumentID = D.DocumentID
					and RM.srocode = D.srocode
					and RM.receiptid = cur_ForReceiptBifercation.ReceiptID_Rec ;
					
					END;
			Else
					BEGIN
					
					update kaveri.DailyReceiptFees_V3 D
					set 
					  RegistrationFees = COALESCE(D.RegistrationFees,0) + cur_ForReceiptBifercation.AmountPaid_Rec 
					From 
						kaveri.ReceiptMaster RM
					WHERE 
					    D.srocode =  Tmp_SROCode
					and D.DocumentID = cur_ForReceiptBifercation.DocumentID_Rec 
					and RM.DocumentID = D.DocumentID
					and RM.srocode = D.srocode
					and RM.receiptid = cur_ForReceiptBifercation.ReceiptID_Rec ;
						
					
					END ;
			
				END IF ;
		end loop;		




















		
		--Update Consideration/Market value which is greater

		/*
if( Tmp_PreviousDocumentID <> cur_DailyRegister.DocumentID )
		Then
		BEGIN
		Tmp_ReceiptCounter := 0;
		END;
end if;
*/

	
	
	end loop ;   -- End of Cursor 
end loop ;	
	
End $$;


