'PRP-17012024-6576414',
'PRP-21112023-5188084',
'PRP-23012024-6744454',
'PRP-23012024-6750776',
'PRP-23112023-5253164',
'PRP-27032024-8835773',
'PRP-31012024-6972698',
'PRP-03082023-2318123',
'PRP-22082023-2821334',
'PRP-04072023-1507095',
'PRP-19022024-7698287',
'PRP-23022024-7835794',
'PRP-26022024-7873578') and a.currentstatus in ('CD102','CD103')
	group by f.applicationnumber,f.feerulecode
	having count(feerulecode)>1)
loop 
	

	select applicationnumber,feerulecode,inserteddatetime into
 	v_applicationnumber,v_feerulecode,v_inserteddatetime
 	from kaveri.feesrequired f where applicationnumber =v_record.applicationnumber and feerulecode=v_record.feerulecode 
	order by inserteddatetime desc limit 1;

	
	delete 	from kaveri.feesrequired f where applicationnumber =v_record.applicationnumber and feerulecode=v_record.feerulecode 
		and inserteddatetime>v_inserteddatetime;
	
--	raise notice 'applicationnumber , feerulecode , inserteddatetime % % %',v_record.applicationnumber ,v_record.feerulecode ,v_inserteddatetime;

	raise notice 'applicationnumber , feerulecode  % %',v_record.applicationnumber ,v_record.feerulecode ;
	
	
	
	
	
	
end loop;
	
	
end;
$$;


