--

CREATE PROCEDURE kaveri.sp_finalfeecalculation(IN _stamparticlecode integer)
    LANGUAGE plpgsql
    AS $$
declare
_govtduty numeric;
_stampduty numeric;
_marketvalue numeric;
_consideration numeric;
_surcharge numeric;
_cessvalue numeric;
_scanningfees numeric;
_mutation numeric;
_denotationofstampduty numeric;
_Totalstampduty numeric;
_Totalregistrationfees numeric;
_Totalpayableamount numeric;
_stamp integer;
_cnt integer;
BEGIN
select count(a.stamparticlecode) into _cnt from kaveri.stamparticles a,kaveri.stamprules b where
a.stamparticlecode = b.stamparticlecode and a.stamparticlecode = _stamparticlecode;
select govtduty,stampduty,marketvalue,consideration into 
_govtduty,_stampduty,_marketvalue,_consideration
from kaveri.propertymaster
where propertyid = 2 and documentid = 15 and villagecode = 28541 and srocode = 9;
if (_cnt = 1 ) then
if (_consideration > _marketvalue) then
_consideration = _marketvalue;
end if;
if _cnt = 1 then
select value into _stampduty from kaveri.stamprules where stamparticlecode = _stamparticlecode;
end if;
_govtduty = _consideration + _stampduty;
_surcharge = 0;
_cessvalue = 0;
_scanningfees = 0;
_mutation = 0;
_denotationofstampduty = 0;
_Totalstampduty = _govtduty + _surcharge + _cessvalue +  _scanningfees + _mutation + _denotationofstampduty;
_Totalregistrationfees = 200;
_Totalpayableamount = _Totalstampduty + _Totalregistrationfees;
end if; 
if (_cnt = 1 ) then
if (_consideration > _marketvalue) then
_consideration = _marketvalue;
end if;
if _cnt = 1 then
select value into _stampduty from kaveri.stamprules where stamparticlecode = _stamparticlecode;
end if;
_govtduty = _consideration + _stampduty;
_surcharge = 0;
_cessvalue = 0;
_scanningfees = 0;
_mutation = 0;
_denotationofstampduty = 0;
_Totalstampduty = _govtduty + _surcharge + _cessvalue +  _scanningfees + _mutation + _denotationofstampduty;
_Totalregistrationfees = 0;
_Totalpayableamount = _Totalstampduty + _Totalregistrationfees;
end if;
select count(a.stamparticlecode) into _cnt from kaveri.stamparticles a,kaveri.stamprules b where
a.stamparticlecode = b.stamparticlecode and a.stamparticlecode = _stamparticlecode and b.isruleactive = 'true';
select govtduty,stampduty,marketvalue,consideration into 
_govtduty,_stampduty,_marketvalue,_consideration
from kaveri.propertymaster
where propertyid = 2 and documentid = 15 and villagecode = 28541 and srocode = 9;
if _cnt = 1 then
if (_consideration > _marketvalue) then
_consideration = _marketvalue;
end if;
if _cnt = 1 then
select value into _stampduty from kaveri.stamprules where stamparticlecode = _stamparticlecode and isruleactive = 'true';
end if;
_govtduty = _consideration + _stampduty * 0.001;
_surcharge = 0;
_cessvalue = 0;
_scanningfees = 0;
_mutation = 0;
_denotationofstampduty = 0;
_Totalstampduty = _govtduty + _surcharge + _cessvalue;
_Totalregistrationfees = _consideration * 0.01;
_Totalpayableamount = _Totalstampduty + _Totalregistrationfees;
end if;
select count(a.stamparticlecode) into _cnt from kaveri.stamparticles a,kaveri.stamprules b where
a.stamparticlecode = b.stamparticlecode and a.stamparticlecode = _stamparticlecode and b.isruleactive = 'true';
select govtduty,stampduty,marketvalue,consideration into 
_govtduty,_stampduty,_marketvalue,_consideration
from kaveri.propertymaster
where propertyid = 2 and documentid = 15 and villagecode = 28541 and srocode = 9;
if _cnt = 1 then
if (_consideration > _marketvalue) then
_consideration = _marketvalue;
end if;
if _cnt = 1 then
select value into _stampduty from kaveri.stamprules where stamparticlecode = _stamparticlecode and isruleactive = 'true';
end if;
_govtduty = _consideration + _stampduty * 0.5;
_surcharge = 0;
_cessvalue = 0;
_scanningfees = 0;
_mutation = 0;
_denotationofstampduty = 0;
_Totalstampduty = _govtduty + _surcharge + _cessvalue;
_Totalregistrationfees = _consideration * 0.01;
_Totalpayableamount = _Totalstampduty + _Totalregistrationfees;
end if;
raise notice '%',_Totalpayableamount;
end;
$$;


