if _stamparticlecode = 29 and _stampruleid = 72 then
_govtduty = _consideration * 0.05;
select isurban into _isurban  from kaveri.villagemaster where villagecode = 28541;-- _villagecode;
if _isurban = 'true' then
_surcharge = _stampduty * 0.02;
else
_surcharge = _stampduty * 0.03;
end if;
_cessvalue = _stampduty * 0.1;
_scanningfees = 0;
_mutation = _mutationfee;
_denotationofstampduty = 0;
_Totalstampduty = _govtduty + _surcharge + _cessvalue +  _scanningfees + _mutationfee + _denotationofstampduty;
_Totalregistrationfees = _marketvalue * 0.01;
_Totalpayableamount = _Totalstampduty + _Totalregistrationfees;
end if;
if _stamparticlecode = 29 and _stampruleid = 73 then
_stampduty1 = 5000;
_govtduty1 = 5000;
_govtduty = _govtduty1;
--if _isurban = 'true' then
_surcharge = _stampduty1 * 0.02;
--end if;
_cessvalue = _stampduty1 * 0.1;
_scanningfees = 0;
_mutation = _mutationfee;
_denotationofstampduty = 0;
_Totalstampduty = _govtduty1 + _surcharge + _cessvalue +  _scanningfees + _mutationfee + _denotationofstampduty;
_Totalregistrationfees = 1000;
_Totalpayableamount = _Totalstampduty + _Totalregistrationfees;
end if;
raise notice 'govtduty  : %',_govtduty;
raise notice 'surcharge : %',_surcharge;
raise notice 'cessvalue : %',_cessvalue;
raise notice 'scanningfees : %',_scanningfees;
raise notice 'mutation : %',_mutation;
raise notice 'denotationofstampduty : %',_denotationofstampduty;
raise notice 'Totalstampduty : %',_Totalstampduty;
raise notice 'Totalregistrationfees : %',_Totalregistrationfees;
raise notice 'Totalpayableamount : %',_Totalpayableamount;
end;
$$;


ALTER PROCEDURE kaveri.sp_finalfeecalculation_new(IN _stamparticlecode integer, IN _stampruleid integer) OWNER TO csgadmin;

--
-- Name: sp_index_rebuild(); Type: PROCEDURE; Schema: kaveri; Owner: postgres
--

CREATE PROCEDURE kaveri.sp_index_rebuild()
    LANGUAGE plpgsql
    AS $$
declare
v_record record;
begin
	
for v_record in (select tablename,indexname,(pgstatindex(schemaname||'.'||indexname)).leaf_fragmentation from pg_indexes
where schemaname='kaveri' and  tablename in ('propertymaster','partyinfo_part1','partyinfo_part2'
,'partyinfo_part3','partyinfo_part4','partyinfo_part5','partyinfo_part6','partyinfo_part7','partyinfo_part8','partyinfo_part9'
,'partyinfo_part10','partyinfo_part11','partyinfo_part12','partyinfo_part13','documentmaster','feesrequired','propertyschedules','propertynumberdetails',
'applicantapplicationdetails') and (pgstatindex(schemaname||'.'||indexname)).leaf_fragmentation>35)
loop
	raise notice 'index-rebuilding %',v_record.indexname;
	reindex index concurrently v_record.indexname;
	raise notice 'index has been rebuild %',v_record.indexname;
end loop;

end
$$;


ALTER PROCEDURE kaveri.sp_index_rebuild() OWNER TO postgres;

--
-- Name: sp_insert_citizen_dashboard_gender(); Type: PROCEDURE; Schema: kaveri; Owner: postgres
--

CREATE PROCEDURE kaveri.sp_insert_citizen_dashboard_gender()
    LANGUAGE plpgsql
    AS $$
declare 
v_record record;
begin
	for v_record in (select srocode,c.applicationtypeid ,fromdate,todate ,c.propertytypeid  from kaveri.citizendashboard c where --c.srocode =1 and  
c.applicationtypeid =1 and fromdate='2025-09-09'
order by fromdate desc ,srocode asc)
loop
----document-applicationnumber--agri

update kaveri.citizendashboard d set male=(case when ss.propertytypeid=17 then coalesce(agrmale,0) when ss.propertytypeid=28 then coalesce(nonagrmale,0) end)
, female=(case when ss.propertytypeid=17 then coalesce(agrfemale,0) when ss.propertytypeid=28 then coalesce(nonagrfemale,0) end),
transgender=(case when ss.propertytypeid=17 then coalesce(agrtransgender,0) when ss.propertytypeid=28 then coalesce(nonagrtransgender,0) end)
from (select count(distinct pp.partyid) filter (where sex=1 and p.propertytypeid =17) as agrmale,
count(distinct pp.partyid) filter (where sex=0 and p.propertytypeid =17) as agrfemale,
count(distinct pp.partyid) filter (where sex=2 and p.propertytypeid =17) as agrtransgender,
count(distinct pp.partyid) filter (where sex=1 and p.propertytypeid =28) as nonagrmale,
count(distinct pp.partyid) filter (where sex=0 and p.propertytypeid =28) as nonagrfemale,
count(distinct pp.partyid) filter (where sex=2 and p.propertytypeid =28) as nonagrtransgender,
d.srocode,
p.propertytypeid 
from kaveri.documentmaster d
join kaveri.propertymaster p on d.applicationnumber=p.applicationnumber
join kaveri.partyinfo pp on d.applicationnumber=pp.applicationnumber
join kaveri.applicantapplicationdetails ad on d.applicationnumber=ad.applicationnumber
where d.srocode=v_record.srocode and registrationdatetime::Date='2025-09-09' and p.propertytypeid =v_record.propertytypeid 
and ad.applicationtypeid=1
group by d.srocode,p.propertytypeid ) as ss 
where d.srocode=ss.srocode and fromdate='2025-09-09' and d.applicationtypeid=1 and d.propertytypeid=ss.propertytypeid;
commit;
raise notice 'srocode % fromdate %',v_record.srocode,v_record.fromdate;

end loop;
	
end;
$$;


ALTER PROCEDURE kaveri.sp_insert_citizen_dashboard_gender() OWNER TO postgres;

--
-- Name: sp_insert_citizen_dashboard_new(); Type: PROCEDURE; Schema: kaveri; Owner: postgres
--

CREATE PROCEDURE kaveri.sp_insert_citizen_dashboard_new()
    LANGUAGE plpgsql
    AS $$
declare 
v_array record;
v_appcntagriend int;
v_appcntagristrt int;
v_appcntagripending int;
v_appcntnonagriend int;
v_appcntnonagristrt int;
v_appcntnonagripending int;
v_appcntccend int;
v_appcntccstrt int;
v_appcntccpending int;
v_appcntecend int;
v_appcntecstrt int;
v_appcntecpending int;
begin 
for v_array in (select srocode from kaveri.sromaster) 
loop

	
	--into v_appcntagristrt into v_appcntagripending
--------------------Agriculture----------------------	
select count(a.applicationnumber) into v_appcntagristrt  from kaveri.applicantapplicationdetails a 
join kaveri.propertymaster p on a.applicationnumber =p.applicationnumber 
where a.applicationstartdate::date=(current_date-1) 
and a.applicationtypeid =1
and p.propertytypeid =17 and a.srocode =v_array.srocode;

	
select count(a.applicationnumber) into v_appcntagriend from kaveri.applicantapplicationdetails a 
join kaveri.propertymaster p on a.applicationnumber =p.applicationnumber 
where a.applicationenddate::date=(current_date-1) 
and a.applicationtypeid =1
and p.propertytypeid =17 and a.srocode =v_array.srocode;

select count(a.applicationnumber) into v_appcntagripending   from kaveri.applicantapplicationdetails a 
join kaveri.propertymaster p on a.applicationnumber =p.applicationnumber 
where a.applicationtypeid =1
and p.propertytypeid =17 and a.currentstatus
in ('CD102','CD108','CD110','CD111','CD112','CD115','CD116')
and a.applicationstartdate::date<=current_date 
and a.srocode =v_array.srocode;

--select * from kaveri.citizendashboard c ;


insert into kaveri.citizendashboard	(applicationsreceived
,applicationsapproved
,applicationspending
,srocode
,applicationtypeid
,propertytypeid,averagetime,mediantime,mintime,maxtime,fromdate,todate)
select 
v_appcntagristrt as ApplicationsReceived,
v_appcntagriend as ApplicationsApproved,
v_appcntagripending as Applicationspending,
v_array.srocode as srocode,
1 as applicationtypeid,
17::int as propertytypeid, 
AVG(d.registrationdatetime - d.presentdatetime) as AverageTime,
percentile_cont(0.5) WITHIN GROUP (ORDER BY d.registrationdatetime - d.presentdatetime) as MedianTime,
MIN(d.registrationdatetime - d.presentdatetime) as MinTime,
MAX(d.registrationdatetime - d.presentdatetime) as max_duration,
(current_date-1) as fromdate,
current_date as todate
FROM kaveri.applicantapplicationdetails a
	join Kaveri.propertymaster p on p.applicationnumber = a.applicationnumber
	join Kaveri.documentmaster d on d.applicationnumber = a.applicationnumber
	where p.propertytypeid in(17) and d.registrationdatetime::date >=(current_date-1) 
	and d.registrationdatetime::date <=current_date 
	and a.applicationtypeid=1
	and a.srocode=v_array.srocode
	and a.applicationnumber not in (select applicationnumber  
	from kaveri.k1pendingregistrationdata kp)
 and  d.registrationdatetime is not null;



--------------------Non-Agriculture----------------------	

select count(a.applicationnumber) into v_appcntnonagristrt  from kaveri.applicantapplicationdetails a 
join kaveri.propertymaster p on a.applicationnumber =p.applicationnumber 
where a.applicationstartdate::date=(current_date-1)  and a.applicationtypeid =1
and p.propertytypeid <>17 and a.srocode =v_array.srocode;

	
select count(a.applicationnumber) into v_appcntnonagriend from kaveri.applicantapplicationdetails a 
join kaveri.propertymaster p on a.applicationnumber =p.applicationnumber 
where a.applicationenddate::date=(current_date-1)  and a.applicationtypeid =1
and p.propertytypeid <>17 and a.srocode =v_array.srocode;

select count(a.applicationnumber) into v_appcntnonagripending   from kaveri.applicantapplicationdetails a 
join kaveri.propertymaster p on a.applicationnumber =p.applicationnumber 
where a.applicationtypeid =1
and p.propertytypeid <>17 and a.currentstatus
in ('CD102','CD108','CD110','CD111','CD112','CD115','CD116')
and a.applicationstartdate::date<=current_date
and a.srocode =v_array.srocode;
	
insert into kaveri.citizendashboard	(applicationsreceived,applicationsapproved,applicationspending,srocode,applicationtypeid,propertytypeid,averagetime,mediantime,mintime,maxtime,fromdate,todate)
select 
v_appcntnonagristrt as ApplicationsReceived,
v_appcntnonagriend as ApplicationsApproved,
v_appcntnonagripending as Applicationspending,
v_array.srocode as srocode,
1 as applicationtypeid,
28 as propertytypeid,
AVG(d.registrationdatetime - d.presentdatetime) as AverageTime,
percentile_cont(0.5) WITHIN GROUP (ORDER BY d.registrationdatetime - d.presentdatetime) as MedianTime,
MIN(d.registrationdatetime - d.presentdatetime) as MinTime,
MAX(d.registrationdatetime - d.presentdatetime) as max_duration,
(current_date-1) as fromdate,
current_date as todate
FROM kaveri.applicantapplicationdetails a
	join Kaveri.propertymaster p on p.applicationnumber = a.applicationnumber
	join Kaveri.documentmaster d on d.applicationnumber = a.applicationnumber
	where p.propertytypeid not in(17) and d.registrationdatetime::date >=(current_date-1) 
	and d.registrationdatetime::date <=current_date 
	and a.applicationtypeid=1 and 
	a.srocode=v_array.srocode --v_array.srocode
	and a.applicationnumber not in (select applicationnumber  
	from kaveri.k1pendingregistrationdata kp)
 and  d.registrationdatetime is not null;

-----------CC Applications-----------------

select count(a.applicationnumber) into v_appcntccstrt  from kaveri.applicantapplicationdetails a 
join kaveri.cc_applicationdetails ea on a.applicationnumber =ea.applicationnumber 
where a.applicationstartdate::date=(current_date-1) 
and a.applicationtypeid =12 and ea.kaverisrocode =v_array.srocode;

select count(a.applicationnumber) into v_appcntccend from kaveri.applicantapplicationdetails a 
join kaveri.cc_applicationdetails ea on a.applicationnumber =ea.applicationnumber 
where a.applicationenddate::date=(current_date-1)
and a.applicationtypeid =12 and ea.kaverisrocode=v_array.srocode;

select count(a.applicationnumber) into v_appcntccpending   from kaveri.applicantapplicationdetails a 
join kaveri.cc_applicationdetails ea on a.applicationnumber =ea.applicationnumber 
where a.applicationtypeid =12 and a.currentstatus
in ('CC104','CC105','CC106','CC107','CC108')
and a.applicationstartdate::date<=current_date 
and ea.kaverisrocode=v_array.srocode;




insert into kaveri.citizendashboard (applicationsreceived,applicationsapproved,applicationspending,srocode,applicationtypeid,propertytypeid,averagetime,mediantime,mintime,maxtime,fromdate,todate)
select 
v_appcntccstrt as ApplicationsReceived,
v_appcntccend as applicationsApproved,
v_appcntccpending as Applicationspending,
v_array.srocode as srocode,
12 as applicationtypeid,
0 as propertytypeid,
AVG(a.applicationenddate - a.applicationstartdate) as AverageTime,
percentile_cont(0.5) WITHIN GROUP (ORDER BY a.applicationenddate - a.applicationstartdate)::time 
as MedianTime,
MIN(a.applicationenddate - a.applicationstartdate) as MinTime,
MAX(a.applicationenddate - a.applicationstartdate) as max_duration,
(current_date-1) as fromdate,
current_date as todate
FROM kaveri.applicantapplicationdetails a
join kaveri.cc_applicationdetails d on a.applicationnumber =d.applicationnumber 
where a.applicationenddate ::date >=(current_date-1) 
and a.applicationenddate ::date<=current_date 
and a.applicationtypeid=12
and  a.applicationstartdate is not null and d.kaverisrocode=v_array.srocode
and a.applicationnumber not in (select applicationnumber  
	from kaveri.k1pendingregistrationdata kp);


--------------EC Applications---------------------------
select count(a.applicationnumber) into v_appcntecstrt  from kaveri.applicantapplicationdetails a 
where a.applicationstartdate::date=(current_date-1) 
and a.applicationtypeid =13 
and a.srocode =v_array.srocode;

select count(a.applicationnumber) into v_appcntecend from kaveri.applicantapplicationdetails a 
where a.applicationenddate::date=(current_date-1)
and a.applicationtypeid =13 
and a.srocode =v_array.srocode;

select count(a.applicationnumber) into v_appcntecpending from kaveri.applicantapplicationdetails a 
where a.applicationtypeid =13 and a.currentstatus
in ('CE104','CE105','CE106','CE107','CE108','CE138','CE139','CE140')
and a.applicationstartdate::date<=current_date 
and a.srocode  =v_array.srocode;


insert into kaveri.citizendashboard (applicationsreceived,applicationsapproved,applicationspending,srocode,applicationtypeid,propertytypeid,averagetime,mediantime,mintime,maxtime,fromdate,todate)
select 
v_appcntecstrt as ApplicationsReceived,
v_appcntecend as applicationsApproved,
v_appcntecpending as Applicationspending,
v_array.srocode as srocode,
13 as applicationtypeid,
0 as propertytypeid,
AVG(a.applicationenddate - a.applicationstartdate) as AverageTime,
percentile_cont(0.5) WITHIN GROUP (ORDER BY a.applicationenddate - a.applicationstartdate) as MedianTime,
MIN(a.applicationenddate - a.applicationstartdate) as MinTime,
MAX(a.applicationenddate - a.applicationstartdate) as max_duration,
(current_date-1) as fromdate,
current_date as todate
FROM kaveri.applicantapplicationdetails a
join kaveri.ec_applicationdetails d on a.applicationnumber =d.applicationnumber 
where a.applicationenddate ::date >=(current_date-1)
and a.applicationenddate ::date <=current_date 
and a.applicationtypeid=13
 and  a.applicationstartdate is not null
and a.applicationnumber not in (select applicationnumber  
	from kaveri.k1pendingregistrationdata kp)
 and a.srocode=v_array.srocode;

end loop;
	
end	;
$$;


