end loop;
	
end	;
$$;


ALTER PROCEDURE kaveri.sp_insert_citizen_dashboard_new_oneday() OWNER TO postgres;

--
-- Name: sp_insert_departmentloginloginfo(bigint, integer, character varying, bigint, character varying, bigint, character varying, character varying, character varying, boolean, character varying, character varying, bigint, boolean, boolean); Type: PROCEDURE; Schema: kaveri; Owner: postgres
--

CREATE PROCEDURE kaveri.sp_insert_departmentloginloginfo(IN _userid bigint, IN _srocode integer, IN _publicip character varying, IN _localport bigint, IN _localip character varying, IN _remoteport bigint, IN _macaddress character varying, IN _location character varying, IN _country character varying, IN _isactive boolean, IN _jwttoken character varying, IN _reftoken character varying, INOUT v_userid bigint DEFAULT NULL::bigint, INOUT v_isactive boolean DEFAULT NULL::boolean, INOUT v_ismultilogin boolean DEFAULT NULL::boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
--v_isactive character varying;
v_array character varying[];
v_citizenid character varying;
--v_isactive bool;
--v_ismultilogin bool;
--v_userid bigint;
BEGIN

if((select count(c.*) from kaveri.departmentloginloginfo c where c.userid = _userid and c.isactive=true)>0) 
THEN
 update kaveri.departmentloginloginfo cll set ismultilogin=true where cll.userid = _userid and cll.isactive=true;
	commit;

insert into kaveri.departmentloginloginfo(c_userid,userid,srocode ,	localip ,localport,publicip ,remoteport ,macaddress ,location ,country,isactive ,jwttoken,reftoken)
	values(NEXTVAL('kaveri.departmentloginlog'),_userid,_srocode,_localip,_localport,_publicip,_remoteport,_macaddress,_location,_country,_isactive,_jwttoken,_reftoken);

--RETURN QUERY ( select b.userid, true as isactive, true as ismultilogin from kaveri.departmentloginloginfo b where b.userid = _userid limit 1);
--v_userid:=(select _userid); return;
select _userid into v_userid;
select true into v_isactive ; 	
select True into v_ismultilogin;
--v_ismultilogin:=true; return;

else
	insert into kaveri.departmentloginloginfo(c_userid,userid,srocode ,	localip ,localport,publicip ,remoteport ,macaddress ,location ,country,isactive ,jwttoken,reftoken)
	values(NEXTVAL('kaveri.departmentloginlog'),_userid,_srocode,_localip,_localport,_publicip,_remoteport,_macaddress,_location,_country,_isactive,_jwttoken,_reftoken);

--v_userid:=(select _userid);
--v_isactive:=true;

select _userid into v_userid;
select true into v_isactive ; 	
select False into v_ismultilogin;

--v_ismultilogin:=false;

--select c.userid, true as isactive, false as ismultilogin from kaveri.departmentloginloginfo c;
end if;
end;
$$;


