--
-- Name: sp_insert_ec_name_details_new(); Type: PROCEDURE; Schema: kaveri; Owner: postgres
--

CREATE PROCEDURE kaveri.sp_insert_ec_name_details_new()
    LANGUAGE plpgsql
    AS $$

declare
v_record record;
v_counter INTEGER := 0;
begin
	
for	v_record in (select a.applicationnumber from kaveri.applicantapplicationdetails a 
join kaveri.documentmaster d on a.applicationnumber=d.applicationnumber where d.registrationdatetime::date>='2023-04-01' and 
d.registrationdatetime::date<='2023-05-30' and a.applicationnumber not in ('PRP-25052023-0523563','PRP-25052023-0523919') and 
d.registrationdatetime >= (select registrationdatetime from kaveri.documentmaster where applicationnumber ='PRP-25052023-0523919')
and a.currentstatus ='CD120' order by a.inserteddatetime)

loop
v_counter := v_counter + 1;
raise notice 'applicationnumber -- % count -- %',v_record.applicationnumber,v_counter;

insert into kaveri.ecname_mapped_details_new
with documentdetails as
(select applicationnumber,registrationdatetime::date from kaveri.documentmaster where applicationnumber =v_record.applicationnumber --registrationdatetime::date >= '2023-05-01' and registrationdatetime::date <= '2023-05-02'
),
---PropertyDetails
propertydetails as 
(select ps.applicationnumber,ps.scheduleid,ps.propertyid,pm.villagecode from kaveri.propertyschedules ps
join documentdetails d on ps.applicationnumber =d.applicationnumber 
join kaveri.propertymaster pm on pm.applicationnumber = d.applicationnumber and ps.propertyid=pm.propertyid where ps.applicationnumber = d.applicationnumber),
----Partydetails
partydetails as 
(select p.applicationnumber,partyid,pt.descriptioninenglish as partytypes,p.partytypeid
,firstname,middlename,lastname,p.linkpartyid,p.salutationid ,p.isorganization ,p.orgpoaauthsignfname ,p.orgpoaauthsignlname 
from kaveri.partyinfo p , documentdetails d2,kaveri.partytypemaster pt where p.applicationnumber = d2.applicationnumber 
and pt.partytypeid=p.partytypeid),
---Partyschedule
partyschedulesdetails as (select pas.applicationnumber,pas.partyid  from kaveri.partyschedules pas , partydetails pd where pas.applicationnumber = pd.applicationnumber and pas.partyid = pd.partyid),
----Result----
result as(select dd.applicationnumber,pd.scheduleid,pad.partyid::varchar as parties,pad.partytypes, pd.propertyid,pd.villagecode
,pad.partytypeid as partytypeid,pad.salutationid,pad.isorganization,pad.firstname,pad.middlename,pad.lastname,pad.linkpartyid
,pad.orgpoaauthsignfname,pad.orgpoaauthsignlname ,dd.registrationdatetime::date
from documentdetails dd
join propertydetails pd on dd.applicationnumber = pd.applicationnumber join partydetails pad on pad.applicationnumber = dd.applicationnumber )
---Query Finalize
select scheduleid,villagecode,registrationdatetime::date,array_agg(fullname) as fullnames,2 as k1k2_flag from (
select a.applicationnumber ,a.scheduleid ,a.villagecode,a.registrationdatetime::date,
(a.partytypes||':- ' || case when pss.applicationnumber is not null
then
case
WHEN au.partytypeid = 4 AND poa.firstname IS NOT NULL THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is rep. by minor guardian ', au.firstname, ' ', au.middlename, ' ', au.lastname, ', whose POA is ', sal_poa.descriptione, poa.firstname, ' ', poa.middlename, ' ', poa.lastname)
    WHEN au.partytypeid = 4 AND poa.firstname IS NULL THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is rep. by minor guardian ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname)
    WHEN au.partytypeid = 5 AND a.isorganization = true THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' POA by ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname, ' is Rep. by ', au.orgpoaauthsignfname, ' ', au.orgpoaauthsignlname)
    WHEN au.partytypeid = 5 AND a.isorganization = false THEN concat(sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname, ' is POA of ', e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
    WHEN au.partytypeid = 9 AND a.isorganization = true AND poa.firstname IS NOT NULL THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is Rep. by ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname, ', whose POA is ', sal_poa.descriptione, poa.firstname, ' ', poa.middlename, ' ', poa.lastname)
    WHEN au.partytypeid = 9 AND a.isorganization = true AND poa.firstname IS NULL THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is Rep. by ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname)
    WHEN au.partytypeid IS NULL AND a.partytypeid = 1 THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
    WHEN au.partytypeid IS NULL AND a.partytypeid = 2 THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
    WHEN au.partytypeid IS NULL AND a.partytypeid = 10 THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
    ELSE NULL::text
end 
else
case
WHEN au.partytypeid = 4 AND poa.firstname IS NOT NULL THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is rep. by minor guardian ', au.firstname, ' ', au.middlename, ' ', au.lastname, ', whose POA is ', sal_poa.descriptione, poa.firstname, ' ', poa.middlename, ' ', poa.lastname)
    WHEN au.partytypeid = 4 AND poa.firstname IS NULL THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is rep. by minor guardian ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname)
    WHEN au.partytypeid = 5 AND a.isorganization = true THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' POA by ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname, ' is Rep. by ', au.orgpoaauthsignfname, ' ', au.orgpoaauthsignlname)
    WHEN au.partytypeid = 5 AND a.isorganization = false THEN concat(sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname, ' is POA of ', e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
    WHEN au.partytypeid = 9 AND a.isorganization = true AND poa.firstname IS NOT NULL THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is Rep. by ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname, ', whose POA is ', sal_poa.descriptione, poa.firstname, ' ', poa.middlename, ' ', poa.lastname)
    WHEN au.partytypeid = 9 AND a.isorganization = true AND poa.firstname IS NULL THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is Rep. by ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname)
    WHEN au.partytypeid IS NULL AND a.partytypeid= 1 THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
    WHEN au.partytypeid IS NULL AND a.partytypeid= 2 THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
    WHEN au.partytypeid IS NULL AND a.partytypeid = 10 THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
    ELSE NULL::text
end
end)
as fullname 
from result a
left join partydetails au on a.parties=au.linkpartyid::varchar AND (au.partytypeid = ANY (ARRAY[9, 4, 5])) 
left join partydetails poa ON poa.linkpartyid = au.partyid AND (poa.partytypeid = ANY (ARRAY[5]))
LEFT JOIN kaveri.salutationmaster e ON a.salutationid = e.salutationid
LEFT JOIN kaveri.salutationmaster sal_au ON au.salutationid = sal_au.salutationid
LEFT JOIN kaveri.salutationmaster sal_poa ON sal_poa.salutationid = poa.salutationid
left join partyschedulesdetails pss on a.applicationnumber=pss.applicationnumber and a.parties=pss.partyid::varchar
group by a.applicationnumber ,a.scheduleid,au.partytypeid,poa.firstname,e.descriptione,a.firstname,a.middlename ,a.lastname
,au.firstname,au.middlename,au.lastname,sal_poa.descriptione,poa.middlename,poa.lastname,sal_au.descriptione,a.isorganization,
au.orgpoaauthsignfname,au.orgpoaauthsignlname,a.partytypeid,a.registrationdatetime::date,pss.applicationnumber ,a.villagecode
,a.partytypes
) as ss group by applicationnumber,scheduleid,registrationdatetime::date,villagecode;
commit;

end loop;
raise notice 'Process completed...';
end;
$$;


ALTER PROCEDURE kaveri.sp_insert_ec_name_details_new() OWNER TO postgres;

--
-- Name: sp_insert_ec_name_details_new_k1(); Type: PROCEDURE; Schema: kaveri; Owner: raghavendrap
--

CREATE PROCEDURE kaveri.sp_insert_ec_name_details_new_k1()
    LANGUAGE plpgsql
    AS $$

declare
v_record record;
--v_counter INTEGER := 0;
--v_fullname text;
--v_partycount int;
begin
	
for	v_record in (select documentid,srocode,registrationdatetime::Date 
from k1data.k1documentmaster kd where kd.registrationdatetime::date>='2021-01-11' and kd.registrationdatetime::date<='2022-12-31')

loop
--	v_counter := v_counter + 1;
	raise notice 'documentid -- % srocode -- %',v_record.documentid,v_record.srocode;
	
	insert into kaveri.ecname_mapped_details_new(scheduleid,villagecode,registrationdatetime,fullname,k1k2_flag)
	select pnn.scheduleid,pm.villagecode,v_record.registrationdatetime, pt.descriptioninenglish||':- '||concat(pf.firstname,' ',pf.middlename,' ',pf.lastname) as fullname ,1 as k1k2_flag 
	from k1data.k1propertymaster pm 
	join k1data.k1propertyschedules pnn on pm.propertyid =pnn.propertyid and pm.regsrocode =pnn.srocode 
	join k1data.k1partyinfo pf on pf.documentid =pm.documentid and pf.srocode =pm.srocode 
	join kaveri.partytypemaster pt on pf.partytypeid = pt.partytypeid  
	where pm.documentid=v_record.documentid and pm.regsrocode =v_record.srocode;
	commit;	
	
end loop;
raise notice 'Process completed...';
end;
$$;


ALTER PROCEDURE kaveri.sp_insert_ec_name_details_new_k1() OWNER TO raghavendrap;

--
-- Name: sp_insert_ec_name_details_new_k2(); Type: PROCEDURE; Schema: kaveri; Owner: postgres
--

CREATE PROCEDURE kaveri.sp_insert_ec_name_details_new_k2()
    LANGUAGE plpgsql
    AS $$

declare
v_record record;
v_counter INTEGER := 0;
v_fullname text;
v_partycount int;
begin
	
for	v_record in (select a.applicationnumber from kaveri.applicantapplicationdetails a 
join kaveri.documentmaster d on a.applicationnumber=d.applicationnumber where d.registrationdatetime::date>='2024-10-10' and 
d.registrationdatetime::date <='2025-12-31' --and a.applicationnumber='PRP-25052023-0523919'
and a.currentstatus ='CD120' order by a.inserteddatetime)

loop
	v_counter := v_counter + 1;
	raise notice 'applicationnumber -- % count -- %',v_record.applicationnumber,v_counter;
	
	select array_agg(fullname) as fullnames into v_fullname from (
	select 
	case when pss.applicationnumber is not null
	then
	pt.descriptioninenglish||':- ' ||case
	WHEN au.partytypeid = 4 AND poa.firstname IS NOT NULL THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is rep. by minor guardian ', au.firstname, ' ', au.middlename, ' ', au.lastname, ', whose POA is ', sal_poa.descriptione, poa.firstname, ' ', poa.middlename, ' ', poa.lastname)
	    WHEN au.partytypeid = 4 AND poa.firstname IS NULL THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is rep. by minor guardian ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname)
	    WHEN au.partytypeid = 5 AND a.isorganization = true THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' POA by ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname, ' is Rep. by ', au.orgpoaauthsignfname, ' ', au.orgpoaauthsignlname)
	    WHEN au.partytypeid = 5 AND a.isorganization = false THEN concat(sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname, ' is POA of ', e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
	    WHEN au.partytypeid = 9 AND a.isorganization = true AND poa.firstname IS NOT NULL THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is Rep. by ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname, ', whose POA is ', sal_poa.descriptione, poa.firstname, ' ', poa.middlename, ' ', poa.lastname)
	    WHEN au.partytypeid = 9 AND a.isorganization = true AND poa.firstname IS NULL THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is Rep. by ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname)
	    WHEN au.partytypeid IS NULL AND a.partytypeid = 1 THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
	    WHEN au.partytypeid IS NULL AND a.partytypeid = 2 THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
	    WHEN au.partytypeid IS NULL AND a.partytypeid = 10 THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
	    ELSE NULL::text
	end 
	else
	pt.descriptioninenglish||':- ' || case
	WHEN au.partytypeid = 4 AND poa.firstname IS NOT NULL THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is rep. by minor guardian ', au.firstname, ' ', au.middlename, ' ', au.lastname, ', whose POA is ', sal_poa.descriptione, poa.firstname, ' ', poa.middlename, ' ', poa.lastname)
	    WHEN au.partytypeid = 4 AND poa.firstname IS NULL THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is rep. by minor guardian ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname)
	    WHEN au.partytypeid = 5 AND a.isorganization = true THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' POA by ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname, ' is Rep. by ', au.orgpoaauthsignfname, ' ', au.orgpoaauthsignlname)
	    WHEN au.partytypeid = 5 AND a.isorganization = false THEN concat(sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname, ' is POA of ', e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
	    WHEN au.partytypeid = 9 AND a.isorganization = true AND poa.firstname IS NOT NULL THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is Rep. by ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname, ', whose POA is ', sal_poa.descriptione, poa.firstname, ' ', poa.middlename, ' ', poa.lastname)
	    WHEN au.partytypeid = 9 AND a.isorganization = true AND poa.firstname IS NULL THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is Rep. by ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname)
	    WHEN au.partytypeid IS NULL AND a.partytypeid= 1 THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
	    WHEN au.partytypeid IS NULL AND a.partytypeid= 2 THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
	    WHEN au.partytypeid IS NULL AND a.partytypeid = 10 THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
	    ELSE NULL::text
	end
	end as fullname
	from kaveri.partyinfo a
	left join kaveri.partyinfo au on a.partyid=au.linkpartyid AND (au.partytypeid = ANY (ARRAY[9, 4, 5])) 
	left join kaveri.partyinfo poa ON poa.linkpartyid = au.partyid AND (poa.partytypeid = ANY (ARRAY[5]))
	LEFT JOIN kaveri.salutationmaster e ON a.salutationid = e.salutationid
	LEFT JOIN kaveri.salutationmaster sal_au ON au.salutationid = sal_au.salutationid
	LEFT JOIN kaveri.salutationmaster sal_poa ON sal_poa.salutationid = poa.salutationid
	join kaveri.partytypemaster pt on pt.partytypeid=a.partytypeid
	left join kaveri.partyschedules pss on a.applicationnumber=pss.applicationnumber and a.partyid=pss.partyid
	where a.applicationnumber =v_record.applicationnumber
	) as ss;
	
	insert into kaveri.ecname_mapped_details_new
	with documentdetails as
	(select applicationnumber,registrationdatetime::date as registrationdatetime from kaveri.documentmaster 
	where applicationnumber =v_record.applicationnumber --registrationdatetime::date >= '2023-05-01' and registrationdatetime::date <= '2023-05-02'
	),
	---PropertyDetails
	propertydetails as 
	(select distinct ps.applicationnumber,ps.scheduleid,ps.propertyid,pm.villagecode from kaveri.propertyschedules ps
	join kaveri.propertymaster pm on pm.applicationnumber = ps.applicationnumber and ps.propertyid=pm.propertyid
	where ps.applicationnumber=v_record.applicationnumber),
	----Partydetails
	partydetails as 
	(select p.applicationnumber,partyid,pt.descriptioninenglish as partytypes,p.partytypeid
	,firstname,middlename,lastname,p.linkpartyid,p.salutationid ,p.isorganization ,p.orgpoaauthsignfname ,p.orgpoaauthsignlname 
	from kaveri.partyinfo p ,kaveri.partytypemaster pt where p.applicationnumber =v_record.applicationnumber and pt.partytypeid=p.partytypeid ),
	---Partyschedule
	partyschedulesdetails as ( select distinct pas.applicationnumber,pas.partyid  from kaveri.partyschedules pas 
	where pas.applicationnumber =v_record.applicationnumber ),
	----Result----
	result as(select pd.scheduleid,pd.villagecode,dd.registrationdatetime--,pad.partyid::varchar as parties,pad.partytypes,
	,v_fullname,2 as k1k2_flag
	--,pad.partytypeid as partytypeid,pad.salutationid,pad.isorganization,pad.firstname,pad.middlename,pad.lastname,pad.linkpartyid
	--,pad.orgpoaauthsignfname,pad.orgpoaauthsignlname ,dd.registrationdatetime::date
	from documentdetails dd
	join propertydetails pd on dd.applicationnumber = pd.applicationnumber 
	--join partydetails pad on pad.applicationnumber = dd.applicationnumber 
	)
	select * from result;commit;

end loop;
raise notice 'Process completed...';
end;
$$;


ALTER PROCEDURE kaveri.sp_insert_ec_name_details_new_k2() OWNER TO postgres;

--
-- Name: sp_insert_ecdetails_1(); Type: PROCEDURE; Schema: kaveri; Owner: postgres
--

CREATE PROCEDURE kaveri.sp_insert_ecdetails_1()
    LANGUAGE plpgsql
    AS $$

declare
v_record record;
v_correction record;
v_claimant text;
v_executant text;
v_allpartyclaimant text;
v_cnt int;
v_namecorrection record;
v_scheduleid bigint;
v_liabilitynote text;
begin
	
for	v_record in (select a.applicationnumber,d.registrationdatetime::date from kaveri.applicantapplicationdetails a 
join kaveri.documentmaster d on a.applicationnumber=d.applicationnumber where d.registrationdatetime::date>'2025-06-12' 
--and d.registrationdatetime::date<'2023-06-01'
and a.currentstatus ='CD120' --and d.applicationnumber ='PRP-15032024-8504703'
)
loop

raise notice 'applicationnumber -- % registrationdatetime -- %',v_record.applicationnumber,v_record.registrationdatetime;

select count(*) into v_cnt from kaveri.ec_fetch_details where scheduleid in (select scheduleid from kaveri.propertyschedules 
where applicationnumber=v_record.applicationnumber);

if(v_cnt=0)	
then
insert into kaveri.ec_mapped_details 
select p3.scheduleid ,p.villagecode ,p2.currentpropertytypeid,p2.currentnumber ,d.registrationdatetime::date from kaveri.applicantapplicationdetails a 
join kaveri.documentmaster d on a.applicationnumber =d.applicationnumber 
join kaveri.propertymaster p on a.applicationnumber=p.applicationnumber 
join kaveri.propertynumberdetails p2 on p.propertyid =p2.propertyid 
join kaveri.propertyschedules p3 on p.propertyid =p3.propertyid 
where d.isregistrationcompleted =true and a.currentstatus ='CD120' and d.applicationnumber =v_record.applicationnumber;
commit;

insert into kaveri.ecname_mapped_details
select p3.scheduleid ,p.villagecode ,concat(p2.firstname,' ',p2.middlename,' ',p2.lastname) as fullname ,d.registrationdatetime::date ,p2.partyid,p2.linkpartyid ,p2.duplicatepartyid 
from kaveri.applicantapplicationdetails a 
join kaveri.documentmaster d on a.applicationnumber =d.applicationnumber 
join kaveri.propertymaster p on a.applicationnumber=p.applicationnumber 
join kaveri.propertyschedules p3 on p.propertyid =p3.propertyid 
join kaveri.partyinfo p2 on d.applicationnumber =p2.applicationnumber 
where d.isregistrationcompleted =true and a.currentstatus ='CD120' and d.applicationnumber =v_record.applicationnumber;
commit;
	
select 
string_agg(
distinct(
case when ps.applicationnumber is not null 
then
	ps.partyid::varchar
else 
	p.partyid::varchar
end)
,', ') AS claimant into v_claimant 
from kaveri.partyinfo p
left JOIN kaveri.partyinfo p1 ON p.partyid = p1.linkpartyid AND (p1.partytypeid = ANY (ARRAY[9, 4, 5]))
left JOIN kaveri.partyinfo p2 ON p2.linkpartyid = p1.partyid AND (p2.partytypeid = ANY (ARRAY[5]))
left JOIN kaveri.salutationmaster s ON p.salutationid = s.salutationid
left JOIN kaveri.salutationmaster s1 ON p1.salutationid = s1.salutationid
left JOIN kaveri.salutationmaster s2 ON p2.salutationid = s2.salutationid
left join kaveri.partyschedules ps on ps.applicationnumber=p.applicationnumber and ps.partyid=p.partyid
where p.applicationnumber=v_record.applicationnumber and 
p.partytypeid=1;

select 
string_agg(distinct
p.partyid::varchar,
', ') AS executant into v_executant
from kaveri.partyinfo p
left JOIN kaveri.partyinfo p1 ON p.partyid = p1.linkpartyid AND (p1.partytypeid = ANY (ARRAY[9, 4, 5]))
left JOIN kaveri.partyinfo p2 ON p2.linkpartyid = p1.partyid AND (p2.partytypeid = ANY (ARRAY[5]))
left JOIN kaveri.salutationmaster s ON p.salutationid = s.salutationid
left JOIN kaveri.salutationmaster s1 ON p1.salutationid = s1.salutationid
left JOIN kaveri.salutationmaster s2 ON p2.salutationid = s2.salutationid
where p.applicationnumber=v_record.applicationnumber and 
p.partytypeid=2;



insert into kaveri.ec_fetch_details(scheduleid,regarticlecode,stamparticlecode,sroconsideration,sromarketvalue,
articlenamee,eastboundary,westboundary,southboundary,northboundary,totalarea,referencetext,executiondate,finalregistrationnumber,
easttowest,northtosouth,description,claimant,executant,villagecode,villagenamee,hoblicode,hobliname)
select distinct p4.scheduleid,
d.regarticlecode,
p.stamparticlecode,p.sroconsideration,p.sromarketvalue,r.articlenamee,p4.eastboundary,p4.westboundary,p4.southboundary,p4.northboundary
,p.totalarea,
(select referencetext from kaveri.referencemaster where documentid=d.documentid order by lstupddate desc limit 1) as referencetext,
--d.documentid,
--d.srocode,
d.executiondatetime AS executiondate
--,d.cdnumber,d.pagecount
,d.finalregistrationnumber AS documentreference,
p4.easttowest,
p4.northtosouth,
case when p5.propertyid is not null 
then
case when  p4.description is not null and  p4.description<>'' then  
concat(p4.description,'')
else concat('District: ', dr.districtnamee,', ' , 'Taluk: ', tm.taluknamee,', ' , 'Village: ',v2.villagenamee,', ', '', 'Survey No: ',p2.survey_no
,', ', 'Hissa No: ', p2.hissa_no,', '
, 'BoundaryDetails: [North: ',p4.northboundary,', '
, 'East: ',p4.eastboundary,', '
, 'West: ', p4.westboundary,', ', 'South: ', p4.southboundary,', ','] measuring '
,p4.totalarea,' acre') end 
else
p4.description end as
description,
v_claimant as claimant,
v_executant as excutant,
p.villagecode,
v2.villagenamee,
h.hoblicode,
h.hoblinamee
from 
kaveri.applicantapplicationdetails a 
join kaveri.documentmaster d on a.applicationnumber =d.applicationnumber 
join kaveri.propertymaster p on d.applicationnumber =p.applicationnumber 
join kaveri.propertynumberdetails p2 on p.propertyid =p2.propertyid 
join kaveri.propertyschedules p4 on p.propertyid =p4.propertyid 
join kaveri.registrationarticles r on d.regarticlecode=r.regarticlecode 
join kaveri.partyinfo p3 on d.applicationnumber =p3.applicationnumber 
left join kaveri.partyschedules p5 on p3.applicationnumber =p5.applicationnumber and p3.partyid =p5.partyid 
join kaveri.villagemaster v2 on p.villagecode=v2.villagecode 
join kaveri.talukmaster tm on v2.talukcode =tm.talukcode --, p.currentnumber)
join kaveri.hoblimaster h on v2.hoblicode=h.hoblicode 
join kaveri.districtmaster dr on tm.districtcode =dr.districtcode
left JOIN kaveri.partyinfo p1 ON p3.partyid = p1.linkpartyid AND (p1.partytypeid = ANY (ARRAY[9, 4, 5])) and p3.partytypeid=1
left JOIN kaveri.partyinfo p6 ON p6.linkpartyid = p1.partyid AND (p6.partytypeid = ANY (ARRAY[5])) and p3.partytypeid=1
left JOIN kaveri.salutationmaster s ON p3.salutationid = s.salutationid
left JOIN kaveri.salutationmaster s1 ON p1.salutationid = s1.salutationid
left JOIN kaveri.salutationmaster s2 ON p6.salutationid = s2.salutationid
where d.isregistrationcompleted =true and d.registrationdatetime::date=v_record.registrationdatetime and a.currentstatus ='CD120' and d.applicationnumber =v_record.applicationnumber
group by a.applicationnumber, p4.scheduleid,
d.regarticlecode,
p.stamparticlecode,p.sroconsideration,p.sromarketvalue,r.articlenamee,p4.eastboundary,p4.westboundary,p4.southboundary,p4.northboundary
,p.totalarea,
d.documentid,
d.srocode,d.executiondatetime ,d.cdnumber,d.pagecount,d.finalregistrationnumber ,
p4.easttowest,
p4.northtosouth,p5.propertyid,p4.description,dr.districtnamee,tm.taluknamee,v2.villagenamee,p2.survey_no,p2.hissa_no,p4.totalarea
,p3.partytypeid,p.villagecode,
v2.villagenamee,
h.hoblicode,
h.hoblinamee;
commit;
end if;
end loop;

update kaveri.ec_fetch_details b set liabilitynote =ss.liabilitynotes
  from (select string_agg(concat('1. Liability Details: Order Number: ', ld.ordernumber, ', Issue Date: ', TO_CHAR(ld.issuedate ::date, 'dd/mm/yyyy'), 	',Liability Note: ', ld.liabilitynote, '<br>2.  Additional Note: ', ld.liabilityadditionalnote),';<br> ') as liabilitynotes
	,ps.scheduleid from kaveri.liabilityonpropertydetails lop
	join kaveri.liabilitydetails ld on lop.liabilityid = ld.liabilityid
	join kaveri.propertyschedules ps  on ps.propertyid=lop.propertyid
	where lop.propertyid = (select propertyid from kaveri.propertyschedules where applicationnumber=v_record.applicationnumber)
group by ps.scheduleid) ss where b.scheduleid=ss.scheduleid ;
commit;

update kaveri.ec_fetch_details d set ecjsondata=s1.js from(
select row_to_json(ss) as js,scheduleid from (
select scheduleid,regarticlecode,stamparticlecode,sroconsideration,sromarketvalue,articlenamee,eastboundary,westboundary
,southboundary,northboundary,totalarea,referencetext,documentid,srocode
,executiondate,cdnumber,pagecount,claimant,executant,finalregistrationnumber,easttowest,northtosouth,description
,stampruleid,stampdescription,liabilitynote,villagecode,villagenamee,hoblicode,hobliname from kaveri.ec_fetch_details) as ss ) as s1
where d.scheduleid=s1.scheduleid;
commit;

----------Correction-Propertysearc------------------

for v_correction in (select distinct  p2.scheduleid,d.applicationnumber , e.currentpropertytypeid,e.currentnumber,e.villagecode,e.newpropertyid,ss.finalregistrationnumber 
,ss.orderid from kaveri.ecpropertysearchkeyvalues e join (select * from (
select row_number() over (partition by dd.finalregistrationnumber order by orderdate desc) as rn
,* from kaveri.dec_drordermaster dd where statuscode =4) as ss where rn=1) as ss on ss.orderid =e.orderid
join kaveri.documentmaster d on d.finalregistrationnumber =ss.finalregistrationnumber 
join kaveri.propertymaster p on d.applicationnumber =p.applicationnumber and p.propertyid =e.propertyid 
join kaveri.propertyschedules p2 on p.propertyid=p2.propertyid 
where ss.statuscode =4 and ss.documentid<>0 and d.registrationdatetime::date=v_record.registrationdatetime --and d.applicationnumber ='PRP-15032024-8504703'
)
loop

select count(*) into v_cnt from kaveri.ec_fetch_details where scheduleid in (select scheduleid from kaveri.propertyschedules 
where applicationnumber=v_correction.applicationnumber);

if(v_cnt>0) then
---- Update Query

update kaveri.ec_mapped_details d set currrentpropertytypeid =ss.currentpropertytypeid,currentnumber =ss.currentnumber,orderid=ss.orderid
from (select e.villagecode,e.newpropertyid,e.currentpropertytypeid,e.currentnumber,e.orderid,
e.oldpropertytypeid ,e.oldnumber,ef.finalregistrationnumber,ed.scheduleid
from kaveri.ecpropertysearchkeyvalues e 
join kaveri.dec_drordermaster dd on e.orderid =dd.orderid and dd.statuscode =4
join kaveri.ec_fetch_details ef on dd.finalregistrationnumber=ef.finalregistrationnumber
join kaveri.ec_mapped_details ed on ef.scheduleid=ed.scheduleid
where e.villagecode=v_correction.villagecode and e.currentpropertytypeid=v_correction.currentpropertytypeid  
and e.currentnumber=v_correction.currentnumber) as ss
where d.scheduleid=ss.scheduleid and d.currrentpropertytypeid=ss.oldpropertytypeid and d.currentnumber=ss.oldnumber
RETURNING d.scheduleid into v_scheduleid;
commit;


update kaveri.ec_mapped_details d set villagecode =ss.newpropertyid
from (select e.villagecode,e.newpropertyid,e.currentpropertytypeid,e.currentnumber,e.orderid,
e.oldpropertytypeid ,e.oldnumber,ef.finalregistrationnumber,ps.scheduleid--ed.scheduleid
from kaveri.ecpropertysearchkeyvalues e 
join kaveri.dec_drordermaster dd on e.orderid =dd.orderid and dd.statuscode =4
join kaveri.ec_fetch_details ef on dd.finalregistrationnumber=ef.finalregistrationnumber
join kaveri.propertyschedules ps on e.propertyid=ps.propertyid
join kaveri.ec_mapped_details ed on ef.scheduleid=ed.scheduleid
where e.villagecode=v_correction.villagecode and e.currentpropertytypeid=v_correction.currentpropertytypeid  
and e.currentnumber=v_correction.currentnumber) as ss
where d.scheduleid=ss.scheduleid --and d.currrentpropertytypeid=ss.oldpropertytypeid and d.currentnumber=ss.oldnumber
RETURNING d.scheduleid into v_scheduleid;
commit;
end if;
end loop;


for v_namecorrection in (select distinct  p2.scheduleid,d.applicationnumber , e.firstname ,e.middlename ,e.lastname,e.partyid ,ss.finalregistrationnumber,e.orderid 
,ss.orderid from kaveri.ecnamesearchkeyvalues  e join (select * from (
select row_number() over (partition by dd.finalregistrationnumber order by orderdate desc) as rn
,* from kaveri.dec_drordermaster dd where statuscode =4) as ss where rn=1) as ss on ss.orderid =e.orderid
join kaveri.documentmaster d on d.finalregistrationnumber =ss.finalregistrationnumber 
join kaveri.propertymaster p on d.applicationnumber =p.applicationnumber --and p.propertyid =e.propertyid 
join kaveri.propertyschedules p2 on p.propertyid=p2.propertyid
join kaveri.ecname_mapped_details ee on p2.scheduleid=ee.scheduleid
where ss.statuscode =4 and ss.documentid<>0 and d.registrationdatetime::date=v_record.registrationdatetime
--and d.applicationnumber ='PRP-15032024-8504703'
)
loop

update kaveri.ecname_mapped_details s set fullname = concat(v_namecorrection.firstname,' ',v_namecorrection.middlename,' ',v_namecorrection.lastname),orderid=v_namecorrection.orderid
where  s.scheduleid=v_namecorrection.scheduleid and s.partyid=v_namecorrection.partyid;
commit;
end loop;

update kaveri.ecname_mapped_details dd set villagecode=ss.villagecode from (select scheduleid,villagecode from kaveri.ec_mapped_details where scheduleid=v_scheduleid) as ss 
where dd.scheduleid=ss.scheduleid;
commit;

end;
$$;


