--
-- Name: sp_insert_ecdetails_1_missed(); Type: PROCEDURE; Schema: kaveri; Owner: postgres
--

CREATE PROCEDURE kaveri.sp_insert_ecdetails_1_missed()
    LANGUAGE plpgsql
    AS $$

declare
v_record record;
v_correction record;
v_claimant text;
v_executant text;
v_allpartyclaimant text;
v_cnt int;
v_namecorrection record;
v_scheduleid bigint;
v_liabilitynote text;
begin
	
--for	v_record in (select a.applicationnumber,d.registrationdatetime::date from kaveri.applicantapplicationdetails a 
--join kaveri.documentmaster d on a.applicationnumber=d.applicationnumber where 
----d.registrationdatetime::date>='2023-05-01' and d.registrationdatetime::date<'2023-06-01'
--d.finalregistrationnumber in ('NMG-1-12174-2024-25') and a.currentstatus ='CD120' 
--)
--for	v_record in (select applicationnumber,registrationdatetime::date from kaveri.ecmisseddata where finalregistrationnumber is not null)
for	v_record in (select applicationnumber,registrationdatetime::date from kaveri.documentmaster d where finalregistrationnumber ='BNS-1-16662-2023-24')
loop

select count(*) into v_cnt from kaveri.ec_fetch_details where scheduleid in (select scheduleid from kaveri.propertyschedules 
where applicationnumber=v_record.applicationnumber);

if(v_cnt=0)	
then
insert into kaveri.ec_mapped_details 
select p3.scheduleid ,p.villagecode ,p2.currentpropertytypeid,p2.currentnumber ,d.registrationdatetime::date from kaveri.applicantapplicationdetails a 
join kaveri.documentmaster d on a.applicationnumber =d.applicationnumber 
join kaveri.propertymaster p on a.applicationnumber=p.applicationnumber 
join kaveri.propertynumberdetails p2 on p.propertyid =p2.propertyid 
join kaveri.propertyschedules p3 on p.applicationnumber =p3.applicationnumber
where d.isregistrationcompleted =true and a.currentstatus ='CD120' and d.applicationnumber =v_record.applicationnumber;
commit;

insert into kaveri.ecname_mapped_details
select p3.scheduleid ,p.villagecode ,concat(p2.firstname,' ',p2.middlename,' ',p2.lastname) as fullname ,d.registrationdatetime::date ,p2.partyid,p2.linkpartyid 
,p2.duplicatepartyid 
from kaveri.applicantapplicationdetails a 
join kaveri.documentmaster d on a.applicationnumber =d.applicationnumber 
join kaveri.propertymaster p on a.applicationnumber=p.applicationnumber 
join kaveri.propertyschedules p3 on p.applicationnumber =p3.applicationnumber
join kaveri.partyinfo p2 on d.applicationnumber =p2.applicationnumber 
where d.isregistrationcompleted =true and a.currentstatus ='CD120' and d.applicationnumber =v_record.applicationnumber;
commit;
	
select 
string_agg(
distinct(
case when ps.applicationnumber is not null 
then
	ps.partyid::varchar
else 
	p.partyid::varchar
end)
,', ') AS claimant into v_claimant 
from kaveri.partyinfo p
left JOIN kaveri.partyinfo p1 ON p.partyid = p1.linkpartyid AND (p1.partytypeid = ANY (ARRAY[9, 4, 5]))
left JOIN kaveri.partyinfo p2 ON p2.linkpartyid = p1.partyid AND (p2.partytypeid = ANY (ARRAY[5]))
left JOIN kaveri.salutationmaster s ON p.salutationid = s.salutationid
left JOIN kaveri.salutationmaster s1 ON p1.salutationid = s1.salutationid
left JOIN kaveri.salutationmaster s2 ON p2.salutationid = s2.salutationid
left join kaveri.partyschedules ps on ps.applicationnumber=p.applicationnumber and ps.partyid=p.partyid
where p.applicationnumber=v_record.applicationnumber and 
p.partytypeid=1;

select 
string_agg(distinct
p.partyid::varchar,
', ') AS executant into v_executant
from kaveri.partyinfo p
left JOIN kaveri.partyinfo p1 ON p.partyid = p1.linkpartyid AND (p1.partytypeid = ANY (ARRAY[9, 4, 5]))
left JOIN kaveri.partyinfo p2 ON p2.linkpartyid = p1.partyid AND (p2.partytypeid = ANY (ARRAY[5]))
left JOIN kaveri.salutationmaster s ON p.salutationid = s.salutationid
left JOIN kaveri.salutationmaster s1 ON p1.salutationid = s1.salutationid
left JOIN kaveri.salutationmaster s2 ON p2.salutationid = s2.salutationid
where p.applicationnumber=v_record.applicationnumber and 
p.partytypeid=2;



insert into kaveri.ec_fetch_details(scheduleid,regarticlecode,stamparticlecode,sroconsideration,sromarketvalue,
articlenamee,eastboundary,westboundary,southboundary,northboundary,totalarea,referencetext,executiondate,finalregistrationnumber,
easttowest,northtosouth,description,claimant,executant,villagecode,villagenamee,hoblicode,hobliname)
select distinct p4.scheduleid,
d.regarticlecode,
p.stamparticlecode,p.sroconsideration,p.sromarketvalue,r.articlenamee,p4.eastboundary,p4.westboundary,p4.southboundary,p4.northboundary
,p.totalarea,
(select referencetext from kaveri.referencemaster where documentid=d.documentid order by lstupddate desc limit 1) as referencetext,
--d.documentid,
--d.srocode,
d.executiondatetime AS executiondate
--,d.cdnumber,d.pagecount
,d.finalregistrationnumber AS documentreference,
p4.easttowest,
p4.northtosouth,
case when p5.propertyid is not null 
then
case when  p4.description is not null and  p4.description<>'' then  
concat(p4.description,'')
else concat('District: ', dr.districtnamee,', ' , 'Taluk: ', tm.taluknamee,', ' , 'Village: ',v2.villagenamee,', ', '', 'Survey No: ',p2.survey_no
,', ', 'Hissa No: ', p2.hissa_no,', '
, 'BoundaryDetails: [North: ',p4.northboundary,', '
, 'East: ',p4.eastboundary,', '
, 'West: ', p4.westboundary,', ', 'South: ', p4.southboundary,', ','] measuring '
,p4.totalarea,' acre') end 
else
p4.description end as
description,
v_claimant as claimant,
v_executant as excutant,
p.villagecode,
v2.villagenamee,
h.hoblicode,
h.hoblinamee
from 
kaveri.applicantapplicationdetails a 
join kaveri.documentmaster d on a.applicationnumber =d.applicationnumber 
join kaveri.propertymaster p on d.applicationnumber =p.applicationnumber 
join kaveri.propertynumberdetails p2 on p.propertyid =p2.propertyid 
join kaveri.propertyschedules p4 on p.applicationnumber =p4.applicationnumber
join kaveri.registrationarticles r on d.regarticlecode=r.regarticlecode 
join kaveri.partyinfo p3 on d.applicationnumber =p3.applicationnumber 
left join kaveri.partyschedules p5 on p3.applicationnumber =p5.applicationnumber and p3.partyid =p5.partyid 
join kaveri.villagemaster v2 on p.villagecode=v2.villagecode 
join kaveri.talukmaster tm on v2.talukcode =tm.talukcode --, p.currentnumber)
join kaveri.hoblimaster h on v2.hoblicode=h.hoblicode 
join kaveri.districtmaster dr on tm.districtcode =dr.districtcode
left JOIN kaveri.partyinfo p1 ON p3.partyid = p1.linkpartyid AND (p1.partytypeid = ANY (ARRAY[9, 4, 5])) and p3.partytypeid=1
left JOIN kaveri.partyinfo p6 ON p6.linkpartyid = p1.partyid AND (p6.partytypeid = ANY (ARRAY[5])) and p3.partytypeid=1
left JOIN kaveri.salutationmaster s ON p3.salutationid = s.salutationid
left JOIN kaveri.salutationmaster s1 ON p1.salutationid = s1.salutationid
left JOIN kaveri.salutationmaster s2 ON p6.salutationid = s2.salutationid
where d.isregistrationcompleted =true and d.registrationdatetime::date=v_record.registrationdatetime and a.currentstatus ='CD120' and d.applicationnumber =v_record.applicationnumber
group by a.applicationnumber, p4.scheduleid,
d.regarticlecode,
p.stamparticlecode,p.sroconsideration,p.sromarketvalue,r.articlenamee,p4.eastboundary,p4.westboundary,p4.southboundary,p4.northboundary
,p.totalarea,
d.documentid,
d.srocode,d.executiondatetime ,d.cdnumber,d.pagecount,d.finalregistrationnumber ,
p4.easttowest,
p4.northtosouth,p5.propertyid,p4.description,dr.districtnamee,tm.taluknamee,v2.villagenamee,p2.survey_no,p2.hissa_no,p4.totalarea
,p3.partytypeid,p.villagecode,
v2.villagenamee,
h.hoblicode,
h.hoblinamee;
commit;
end if;
end loop;

update kaveri.ec_fetch_details b set liabilitynote =ss.liabilitynotes
  from (select string_agg(concat('1. Liability Details: Order Number: ', ld.ordernumber, ', Issue Date: ', TO_CHAR(ld.issuedate ::date, 'dd/mm/yyyy'), 	',Liability Note: ', ld.liabilitynote, '<br>2.  Additional Note: ', ld.liabilityadditionalnote),';<br> ') as liabilitynotes
	,ps.scheduleid from kaveri.liabilityonpropertydetails lop
	join kaveri.liabilitydetails ld on lop.liabilityid = ld.liabilityid
	join kaveri.propertyschedules ps  on ps.propertyid=lop.propertyid
	where lop.propertyid = (select propertyid from kaveri.propertyschedules where applicationnumber=v_record.applicationnumber)
group by ps.scheduleid) ss where b.scheduleid=ss.scheduleid ;
commit;

update kaveri.ec_fetch_details d set ecjsondata=s1.js from(
select row_to_json(ss) as js,scheduleid from (
select scheduleid,regarticlecode,stamparticlecode,sroconsideration,sromarketvalue,articlenamee,eastboundary,westboundary
,southboundary,northboundary,totalarea,referencetext,documentid,srocode
,executiondate,cdnumber,pagecount,claimant,executant,finalregistrationnumber,easttowest,northtosouth,description
,stampruleid,stampdescription,liabilitynote,villagecode,villagenamee,hoblicode,hobliname from kaveri.ec_fetch_details) as ss ) as s1
where d.scheduleid=s1.scheduleid;
commit;

