ALTER PROCEDURE kaveri.sp_insert_ecdetails_1_missed() OWNER TO postgres;

--
-- Name: sp_insert_ecdetails_1_namecorrection(); Type: PROCEDURE; Schema: kaveri; Owner: postgres
--

CREATE PROCEDURE kaveri.sp_insert_ecdetails_1_namecorrection()
    LANGUAGE plpgsql
    AS $$

declare
v_record record;
v_correction record;
v_claimant text;
v_executant text;
v_allpartyclaimant text;
v_cnt int;
v_namecorrection record;
v_scheduleid bigint;
v_liabilitynote text;
begin
	
for	v_record in (select a.applicationnumber,d.registrationdatetime::date from kaveri.applicantapplicationdetails a 
join kaveri.documentmaster d on a.applicationnumber=d.applicationnumber where d.registrationdatetime::date>='2023-05-01' and 
d.registrationdatetime::date<'2023-06-01'
and a.currentstatus ='CD120' limit 10 --and d.applicationnumber ='PRP-15032024-8504703'
)
loop

for v_namecorrection in (select distinct  p2.scheduleid,d.applicationnumber , e.firstname ,e.middlename ,e.lastname,e.partyid ,ss.finalregistrationnumber,e.orderid 
,ss.orderid from kaveri.ecnamesearchkeyvalues  e join (select * from (
select row_number() over (partition by dd.finalregistrationnumber order by orderdate desc) as rn
,* from kaveri.dec_drordermaster dd where statuscode =4) as ss where rn=1) as ss on ss.orderid =e.orderid
join kaveri.documentmaster d on d.finalregistrationnumber =ss.finalregistrationnumber 
join kaveri.propertymaster p on d.applicationnumber =p.applicationnumber --and p.propertyid =e.propertyid 
join kaveri.propertyschedules p2 on p.propertyid=p2.propertyid
join kaveri.ecname_mapped_details ee on p2.scheduleid=ee.scheduleid
where ss.statuscode =4 and ss.documentid<>0 and d.registrationdatetime::date=v_record.registrationdatetime
--and d.applicationnumber ='PRP-15032024-8504703'
)
loop

update kaveri.ecname_mapped_details s set fullname = concat(v_namecorrection.firstname,' ',v_namecorrection.middlename,' ',v_namecorrection.lastname),orderid=v_namecorrection.orderid
where  s.scheduleid=v_namecorrection.scheduleid and s.partyid=v_namecorrection.partyid;
