end loop;
end loop;

update kaveri.ecname_mapped_details dd set villagecode=ss.villagecode from (select scheduleid,villagecode from kaveri.ec_mapped_details where scheduleid=v_scheduleid) as ss 
where dd.scheduleid=ss.scheduleid;
