--
-- Name: sp_insert_ecdetails_k1(); Type: PROCEDURE; Schema: kaveri; Owner: postgres
--

CREATE PROCEDURE kaveri.sp_insert_ecdetails_k1()
    LANGUAGE plpgsql
    AS $$

declare
v_record record;
v_correction record;
v_claimant text;
v_executant text;
v_allpartyclaimant text;
v_cnt int;
v_namecorrection record;
v_scheduleid bigint;
v_liabilitynote text;
begin
	
for	v_record in (select documentid,srocode,registrationdatetime::Date,kd.regarticlecode,stamparticlecode,executiondatetime,finalregistrationnumber,r.articlenamee 
from k1data.k1documentmaster kd 
join kaveri.registrationarticles  r on kd.regarticlecode =r.regarticlecode 
where kd.registrationdatetime::date>='2001-01-01' and kd.registrationdatetime::date<'2010-01-01' --documentid=21 and srocode =118 --registrationdatetime is not null
)

loop

select count(*) into v_cnt from kaveri.ec_fetch_details where (scheduleid,srocode) in (
select pnn.scheduleid,pnn.srocode from k1data.k1propertymaster pm 
join k1data.k1propertyschedules pnn on pm.propertyid =pnn.propertyid and pm.regsrocode =pnn.srocode 
where pm.documentid=v_record.documentid and pm.regsrocode =v_record.srocode);

raise notice 'v_cnt -- %,v_record.documentid -- %,v_record.srocode -- %',v_cnt,v_record.documentid,v_record.srocode;

if(v_cnt=0)
then 

insert into kaveri.ec_mapped_details (scheduleid,villagecode,currrentpropertytypeid,currentnumber,registrationdatetime,k1k2flag)
select pnn.scheduleid,pm.villagecode,pnd.currentpropertytypeid,pnd.currentnumber,v_record.registrationdatetime,1 as k1k2flag from k1data.k1propertymaster pm 
join k1data.k1propertyschedules pnn on pm.propertyid =pnn.propertyid and pm.regsrocode =pnn.srocode 
join k1data.k1propertynumberdetails pnd on pm.propertyid =pnd.propertyid and pm.regsrocode =pnd.srocode
where pm.documentid=v_record.documentid and pm.regsrocode =v_record.srocode;
commit;

insert into kaveri.ecname_mapped_details(scheduleid,villagecode,fullname,registrationdatetime,partyid,k1k2flag)
