--
-- Name: sp_insert_into_citizenmaster(text, text, text, text, integer, text, bigint, text, integer, text, character, text, timestamp without time zone); Type: PROCEDURE; Schema: kaveri; Owner: csgadmin
--

CREATE PROCEDURE kaveri.sp_insert_into_citizenmaster(IN _loginname text, IN _firstname text, IN _middlename text, IN _lastname text, IN _gender integer, IN _email text, IN _phone bigint, IN _password text, IN _secquestion integer, IN _secanswer text, IN _isloggedin character, IN _lstupdusr text, IN _lstupddt timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
declare
 cnt integer;
 err_constraint text;
 columnname text;
begin
INSERT INTO kaveri.citizenmaster
(loginname,firstname,middlename,lastname,gender,email,phone,password,secquestion,secanswer,isloggedin,
                                  lstupdusr,lstupddt)
   VALUES 
   (_loginname,_firstname,_middlename,_lastname,_gender,_email,_phone,_password,_secquestion,_secanswer,
	_isloggedin,_lstupdusr,_lstupddt
   );
   select  max(citizenid) into cnt from kaveri.citizenmaster;
   raise notice '%',cnt;
EXCEPTION
   WHEN SQLSTATE '23505' THEN  -- Class 23 — Integrity Constraint Violation
      GET STACKED DIAGNOSTICS err_constraint = CONSTRAINT_NAME;
	   GET STACKED DIAGNOSTICS columnname = COLUMN_NAME;
      -- do something with it, for instance:
      RAISE NOTICE '%', err_constraint;
	  RAISE NOTICE '%',columnname;
      --RAISE;  -- raise original error
   END;
$$;


ALTER PROCEDURE kaveri.sp_insert_into_citizenmaster(IN _loginname text, IN _firstname text, IN _middlename text, IN _lastname text, IN _gender integer, IN _email text, IN _phone bigint, IN _password text, IN _secquestion integer, IN _secanswer text, IN _isloggedin character, IN _lstupdusr text, IN _lstupddt timestamp without time zone) OWNER TO csgadmin;

--
-- Name: sp_insert_ngdrs_dashboard_data(); Type: PROCEDURE; Schema: kaveri; Owner: postgres
--

CREATE PROCEDURE kaveri.sp_insert_ngdrs_dashboard_data()
    LANGUAGE plpgsql
    AS $$
declare 
v_srocnt int;
v_date date;
v_regcount bigint;
v_subcnt bigint;
v_appointment bigint;
v_scannedcnt bigint;
v_scanpending bigint;
v_revenuegenerated numeric;
v_iterator int;
begin 

select count(*) into v_srocnt from kaveri.sromaster s ;

select (case when max(date)::date is not null
	then max(date) else '2024-04-01' end) into v_date 
from kaveri.ngdrs_dashboard_data;


v_iterator:=1;
v_date:=(case when v_date='2024-04-01'::date then '2024-04-01'::date else  v_date + interval '1 Days' end);

while (v_date<current_date and v_iterator<=1)
	loop

		select count(*) filter (where isregistrationcompleted=true and registrationdatetime::Date=v_date) as regcnt ,
		count(*) filter (where (isregistrationcompleted = false  or isregistrationcompleted is null) and inserteddatetime::date=v_date) as subcnt 
		into v_regcount ,v_subcnt
		from kaveri.documentmaster d ;
--		where d.inserteddatetime::date=v_date;

		select count(*) filter (where d.isregistrationcompleted =true and d.isuploaddocuments=true and am.wrkflowstatusid='CD115'
		and d.registrationdatetime::Date=v_date) as scanneddoc,
		count(*) filter (where d.isregistrationcompleted=true and d.isuploaddocuments=false and am.wrkflowstatusid<>'CD115'
		and d.registrationdatetime::Date=v_date ) as scanpendoc
		into v_scannedcnt,v_scanpending
		from kaveri.documentmaster d 
		left join (	select applicationnumber,wrkflowstatusid,row_number() over (partition by applicationnumber,wrkflowstatusid order by crtusr desc) as rn 
		from kaveri.applicationaudit a 
		where wrkflowstatusid ='CD115' and a.crtdt::Date=v_date) as am on am.applicationnumber=d.applicationnumber and am.rn=1;
--		where d.inserteddatetime::date=v_date;	
	
	
		select count(*) into v_appointment from kaveri.appointmentmaster a where appointmentdate::date=v_date and status ='2';

		select sum(amount) into v_revenuegenerated from kaveri.ams_reg_epaymentbankackdetails are2 
		where paymentstatuscode in ('10700066','10700072') and inserteddatetime::date=v_date;

		insert into kaveri.ngdrs_dashboard_data(no_of_sr_office,no_of_document_registered,no_of_document_submitted,no_of_appointment_requested
			,no_of_scan_docs,no_of_pending_scan,revenue_genereated,"date")
		select coalesce(v_srocnt,0),coalesce(v_regcount,0),coalesce(v_subcnt,0),coalesce(v_appointment,0),coalesce(v_scannedcnt,0),coalesce(v_scanpending,0),coalesce(v_revenuegenerated,0),v_date;
	
		v_date:= v_date + interval '1 Days';
		v_iterator:= v_iterator+1;
		
	end loop;
	
	
	
end;
$$;


ALTER PROCEDURE kaveri.sp_insert_ngdrs_dashboard_data() OWNER TO postgres;

--
-- Name: sp_insert_slots(bigint, date); Type: PROCEDURE; Schema: kaveri; Owner: csgadmin
--

CREATE PROCEDURE kaveri.sp_insert_slots(IN _srocode bigint, IN _slotdate date)
    LANGUAGE plpgsql
    AS $$

BEGIN

insert into kaveri.slotmaster
(
srocode,
serviceid,
sltdate,
sltstarttime,
sltendtime,
sltcapacity,
sltavlcapacity,
sltisactive,
isexpress) values
(_srocode,1,_slotdate,'09:00','10:00',5,5,true,true),
(_srocode,1,_slotdate,'10:00','11:00',5,5,true,true),
(_srocode,1,_slotdate,'11:00','12:00',5,5,true,true),
(_srocode,1,_slotdate,'13:00','14:00',5,5,true,true),
(_srocode,1,_slotdate,'14:00','15:00',5,5,true,true),
(_srocode,1,_slotdate,'15:00','16:00',5,5,true,true),
(_srocode,1,_slotdate,'16:00','17:00',5,5,true,true);

exception 
	   when others then 
	      RAISE INFO 'Error Name:%',SQLERRM;
end;

$$;


ALTER PROCEDURE kaveri.sp_insert_slots(IN _srocode bigint, IN _slotdate date) OWNER TO csgadmin;

--
-- Name: sp_kaveri_grant_permission(character varying); Type: PROCEDURE; Schema: kaveri; Owner: csgadmin
--

CREATE PROCEDURE kaveri.sp_kaveri_grant_permission(IN _role character varying)
    LANGUAGE plpgsql
    AS $$

BEGIN

EXECUTE 'GRANT select,usage ON ALL SEQUENCES IN SCHEMA kaveri TO '||_role;

EXECUTE 'GRANT INSERT, SELECT, UPDATE, DELETE, REFERENCES, TRIGGER ON ALL tables IN SCHEMA kaveri TO '||_role;

EXECUTE 'GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA kaveri TO '||_role;

EXECUTE 'GRANT EXECUTE ON ALL PROCEDURES IN SCHEMA kaveri TO '||_role;

exception 
	   when others then 
	      RAISE INFO 'Error Name:%',SQLERRM;
end;

$$;


ALTER PROCEDURE kaveri.sp_kaveri_grant_permission(IN _role character varying) OWNER TO csgadmin;

