	set
	updateddate = current_date , 
	enddate  = current_date, 
	isactive = false 
	where stamptypeid = i.stamptypeid
		and isactive = true 
		and StartDate < current_date +1 ;
     */ 	
		
end ;

else

Begin   

-- Insert new record from MDM table to master table.

INSERT INTO kaveri.stamptypemaster ( stamptypeid,nameinkannada,nameinenglish,certificationreqd,khajaneremittancedescription) 
select i.stamptypeid, i.nameinkannada, i.nameinenglish, i.certificationreqd, i.khajaneremittancedescription ;


end ;

