where (StartDate = current_date +1 ) 
and isactive = true )

loop

if (select count(*) from kaveri.stampruleslabs where id = i.id) = 1
then

-- Update new changes from mdm table to master table 
Begin
	update kaveri.stampruleslabs b
	set 
		stampruleid = i.stampruleid ,
		slabamtfrom = i.slabamtfrom ,
