		unit = i.unit ,
		maxlimit = i.maxlimit ,
		value = i.value ,
		plusthisamount = i.plusthisamount 
		
	from 
		kaveri.Mdm_stampruleslabs m
	where 
		b.id = i.id ;	
		
 		
	/* - Testing is pending 
	
	Update kaveri.Mdm_stampruleslabs
	set
	updateddate = current_date , 
	enddate  = current_date, 
	isactive = false 
	where id = i.id
		and isactive = true 
