--
-- Name: sp_regenerate_summary(); Type: PROCEDURE; Schema: kaveri; Owner: postgres
--

CREATE PROCEDURE kaveri.sp_regenerate_summary()
    LANGUAGE plpgsql
    AS $$

declare
v_applicationnumber character varying;
v_cnt int;
v_count int;

begin

select count(applicationnumber) into v_count from kaveri.documentmaster where applicationnumber in(
select applicationnumber from kaveri.applicantapplicationdetails where currentstatus in ('CD110','CD111'));

raise notice 'v_count - %',v_count;

for v_applicationnumber in (select applicationnumber from kaveri.documentmaster where applicationnumber in(
select applicationnumber from kaveri.applicantapplicationdetails where currentstatus in ('CD110','CD111')))
loop
	select count(*) into v_cnt from kaveri.documentsummary where applicationnumber = v_applicationnumber;
	
	if v_cnt > 0 then
		perform kaveri.fn_insert_documentsummary(v_applicationnumber);
		raise notice 'applicationnubmer in summary table %',v_applicationnumber;
	else 
		raise notice 'applicationnubmer not in summary table %',v_applicationnumber;
		continue;
	end if;
	
end loop;
end;
$$;


ALTER PROCEDURE kaveri.sp_regenerate_summary() OWNER TO postgres;

--
-- Name: sp_reschedule_apr_appl(); Type: PROCEDURE; Schema: kaveri; Owner: raghavendrap
--

CREATE PROCEDURE kaveri.sp_reschedule_apr_appl()
    LANGUAGE plpgsql
    AS $$

declare
v_record record;
v_count int;

begin

select count(*) into v_count
from kaveri.applicantapplicationdetails a  
join kaveri.appointmentmaster aa on a.applicationnumber = aa.applicationnumber
where a.currentstatus= 'CD108' and aa.appointmentdate::date>='2026-04-01' and
((aa.starttime >= '09:00:00' and aa.endtime <= '10:00:00') or (aa.starttime >= '17:30:00' and aa.endtime <= '19:30:00'))
and aa.status ='1';

raise notice 'v_count - %',v_count;

if v_count > 0 then

for v_record in (select a.applicationnumber ,a.currentstatus ,aa.status,aa.appointmentdate,aa.starttime,aa.endtime,aa.inserteddatetime 
	from kaveri.applicantapplicationdetails a  
	join kaveri.appointmentmaster aa on a.applicationnumber = aa.applicationnumber
	where a.currentstatus= 'CD108' and aa.appointmentdate::date>='2026-04-01' and
	((aa.starttime >= '09:00:00' and aa.endtime < '10:00:00') or (aa.starttime >= '17:30:00' and aa.endtime <= '19:30:00'))
	and aa.status ='1')
loop
	raise notice 'applicationnumber - % currentstatus - % status - % appointmentdate - % starttime - % endtime - %',
	v_record.applicationnumber,v_record.currentstatus ,v_record.status,v_record.appointmentdate,v_record.starttime,v_record.endtime;

	update kaveri.appointmentmaster set status = 3 where applicationnumber = v_record.applicationnumber 
		and appointmentdate = v_record.appointmentdate and status = v_record.status and starttime = v_record.starttime 
		and endtime = v_record.endtime;commit;

	update kaveri.applicantapplicationdetails set currentstatus = 'CD107' where applicationnumber = v_record.applicationnumber and currentstatus = v_record.currentstatus;commit;
	
end loop;
end if;
end;
$$;


ALTER PROCEDURE kaveri.sp_reschedule_apr_appl() OWNER TO raghavendrap;

--
-- Name: sp_statement(integer); Type: PROCEDURE; Schema: kaveri; Owner: csgadmin
--

CREATE PROCEDURE kaveri.sp_statement(IN passyear integer)
    LANGUAGE plpgsql
    AS $$                 -- Kaveri_2

--Variable declaration



  Declare Month		varchar(10); 
  Declare Year			integer;
  Declare TotalDocuments	integer;
  Declare TotalStampDuty 	money;	
  Declare TotalRegFees 	money;
  Declare SDRefund		money; 
  Declare PYear		integer;
  Declare PTotalDocuments	integer;
  Declare PTotalStampDuty 	money;	
  Declare PTotalRegFees 	money;
  Declare SROName		varchar(250); 

declare cur_statement record;
declare cur_statement_p record;

Begin
--declare cur_statement  scroll cursor for 

for cur_statement in   -- Create Cursor cur_statement
   (
	SELECT 	
		 TO_CHAR(DocumentMaster.Stamp5DateTime, 'Month') AS Month,
		date_part('year',DocumentMaster.Stamp5DateTime) as Year,
		count(DocumentMaster.DocumentID) Documents, 
		sum(DocumentMaster.PaidStampDuty) StampDuty,
		sum(ReceiptDetails.AmountPaid) RegFees,
		SROMaster.SRONameK 
	FROM 	kaveri.DocumentMaster, 
			kaveri.ReceiptDetails, 
			kaveri.ReceiptMaster, 
			kaveri.SROMaster
	WHERE 	ReceiptDetails.ReceiptID = ReceiptMaster.ReceiptID 
	and	ReceiptMaster.DocumentID = DocumentMaster.DocumentID
	and	ReceiptDetails.FeeRuleCode = 1
	and	
	
	(
		-- ( Datepart(m,DocumentMaster.Stamp5DateTime) > 3	and
		 ( date_part('month',DocumentMaster.Stamp5DateTime) >3 and 
		--Datepart(yyyy,DocumentMaster.Stamp5DateTime) = PassYear)
		date_part('year',DocumentMaster.Stamp5DateTime)  = PassYear)  OR 
		
	--	or	(Datepart(m,DocumentMaster.Stamp5DateTime) < 4	and
	   ( date_part('month',DocumentMaster.Stamp5DateTime) <4 and 
		
    --	Datepart(yyyy,DocumentMaster.Stamp5DateTime) = PassYear+1)
		date_part('year',DocumentMaster.Stamp5DateTime) = PassYear+1 ) 
		
	)
	and	SROMaster.SROCode = DocumentMaster.SROCode 
	GROUP BY SROMaster.SRONamek, 
    	  TO_CHAR(DocumentMaster.Stamp5DateTime, 'Month') ,
    	date_part('year',DocumentMaster.Stamp5DateTime)
  
	ORDER BY 
		--Datepart(yyyy,DocumentMaster.Stamp5DateTime),
		date_part('year',DocumentMaster.Stamp5DateTime) ,
	   TO_CHAR(DocumentMaster.Stamp5DateTime, 'Month')
	   
		--Datepart(m,DocumentMaster.Stamp5DateTime) 
		-- date_part('month',DocumentMaster.Stamp5DateTime)
   )
   
   

	-- Delete from Statement;

loop

--	Open cur_statement;

/*
	fetch next from cur_statement into   
			   Month		, 
			   Year		,
			   TotalDocuments	,
			   TotalStampDuty 	,	
			   TotalRegFees 	,
			   SROName		;

	while fetch_status=0	
*/


		begin
			insert into kaveri.Statement(
						SROName,
						CMonth,
						CYear,
						CTotalDocuments ,
						CTotalStampDuty,
						CTotalRegFees
						)
			values			(
						cur_statement.SRONameK,
						cur_statement.Month,
						cur_statement.Year,
						cur_statement.Documents,
						cur_statement.StampDuty,
						cur_statement.RegFees
						) ;


			/* Cursor for previous year ***********begins***************************/
		--	declare cur_statement_p  scroll cursor for 
		
		for cur_statement_p in (
				SELECT 
					date_part('Year',DocumentMaster.Stamp5DateTime) as Year,
					count(DocumentMaster.DocumentID) as Documents, 
					sum(DocumentMaster.PaidStampDuty) as StampDuty,
					sum(ReceiptDetails.AmountPaid) as RegFees
				FROM 	kaveri.DocumentMaster, 
						kaveri.ReceiptDetails, 
						kaveri.ReceiptMaster
				WHERE 	ReceiptDetails.ReceiptID = ReceiptMaster.ReceiptID 
				and	ReceiptMaster.DocumentID = DocumentMaster.DocumentID
				and	ReceiptDetails.FeeRuleCode = 1
				and	
				/*((Datepart(m,DocumentMaster.Stamp5DateTime) > 3	and
					Datepart(yyyy,DocumentMaster.Stamp5DateTime) = PassYear-1)
				or	(Datepart(m,DocumentMaster.Stamp5DateTime) < 4	and
					Datepart(yyyy,DocumentMaster.Stamp5DateTime) = PassYear))
				*/	
			--(( EXTRACT(Month FROM TIMESTAMP DocumentMaster.Stamp5DateTime) >3 and 
			(  (date_part('month',DocumentMaster.Stamp5DateTime) >3 and 
			  
			--EXTRACT(YEAR,DocumentMaster.Stamp5DateTime) = PassYear-1)
			 date_part('Year',DocumentMaster.Stamp5DateTime) = PassYear-1)   OR
			 
			 --(EXTRACT(Month,DocumentMaster.Stamp5DateTime) < 4 and
			( date_part('Month',DocumentMaster.Stamp5DateTime) <4 and 
			  
			  --EXTRACT(YEAR,DocumentMaster.Stamp5DateTime) = PassYear)	)
				date_part('Year',DocumentMaster.Stamp5DateTime) = PassYear)	
			)
			 
	--		and 	Datename(m,DocumentMaster.Stamp5DateTime) = month 
			 AND TO_CHAR(DocumentMaster.Stamp5DateTime, 'Month') = cur_statement.Month
			
			GROUP BY 
					--Datepart(m,DocumentMaster.Stamp5DateTime),
					--Datepart(yyyy,DocumentMaster.Stamp5DateTime) 
					date_part('Month',DocumentMaster.Stamp5DateTime),
					date_part('Year',DocumentMaster.Stamp5DateTime)
		)


				--Open cur_statement_p;
			
			/*	fetch next from cur_statement_p into   
						   PYear		,
						   PTotalDocuments	,
						   PTotalStampDuty 	,	
						   PTotalRegFees 	;
			*/

			loop 
				--	while fetch_status=0	
						begin
							UPDATE kaveri.Statement	
							SET	PYear  = cur_statement_p.Year,
								PTotalDocuments = cur_statement_p.Documents ,
								PTotalStampDuty =  cur_statement_p.StampDuty,
								PTotalRegFees	  =  cur_statement_p.RegFees
							Where	CMonth = cur_statement.Month ;

							/*
							fetch next from cur_statement_p into   
							   PYear		,
							   PTotalDocuments	,
							   PTotalStampDuty 	,	
							   PTotalRegFees 	;
							  */
						end ;
				
			--	close cur_statement_p;
			--	deallocate cur_statement_p;
			
			end loop ; -- close cursor cur_statement_p

			/* Cursor for previous year ***********ends***************************/


		/*	fetch next from cur_statement into   
			   Month		, 
			   Year		,
			   TotalDocuments	,
			   TotalStampDuty 	,	
			   TotalRegFees 	,
			   SROName		;
		end
		*/
	End ;   -- End of First Begin 
--close cur_statement;
--deallocate cur_statement;

end loop ;   -- End cursor cur_statement




end $$;


ALTER PROCEDURE kaveri.sp_statement(IN passyear integer) OWNER TO csgadmin;

--
-- Name: sp_update_appointment(); Type: PROCEDURE; Schema: kaveri; Owner: postgres
--

CREATE PROCEDURE kaveri.sp_update_appointment()
    LANGUAGE plpgsql
    AS $$

declare
v_record record;
v_applicationnumber character varying;
v_starttime time;
v_endtime time;
v_deoid int[];
p_starttime time;
p_endtime time;
v_deo int;
i int;
v_appointment int;
duration time;
v_srocode bigint;

begin

for v_srocode in (select srocode from kaveri.sromaster)	
loop
	
select array_agg(userid) into v_deoid from kaveri.departmentusers d where srocode =v_srocode and designationid = 4;

for v_deo in (select unnest(v_deoid))
loop
	i = 0;

	raise notice 'deoid %',v_deo;
	for v_appointment in (select appointmentid from kaveri.appointmentmaster a 
			where deoperator = v_deo and appointmentdate::date = current_date and starttime>='14:30:00')
	loop 

		select starttime,endtime into v_starttime,v_endtime
			from kaveri.appointmentmaster a 
			where deoperator = v_deo and appointmentdate::date = current_date and starttime>='14:30:00'
 			and appointmentid=v_appointment;	

 		i=i+1;

 	if(i=1)
 	then
 	p_starttime=v_starttime;
	p_endtime=v_endtime;
	end if;

	if(i>1) then
			raise notice 'appointmentid %',v_appointment;
--		((endtime - starttime)::interval+starttime::time)
		
		duration=(v_endtime-v_starttime);
	
		raise notice 'duration %',duration;
		raise notice 'old_end %',p_endtime;
		raise notice 'new_end %', (p_endtime::time+duration::interval);
		update kaveri.appointmentmaster set starttime=p_endtime,endtime =(p_endtime::time+duration::interval) 
		where appointmentid =v_appointment;
	
	p_starttime=p_endtime;
	p_endtime=(p_endtime::time+duration::interval);
	
	end if;
 
 
end loop;
	
	
	
end loop;
end loop;
end;
$$;


ALTER PROCEDURE kaveri.sp_update_appointment() OWNER TO postgres;

--
-- Name: sp_update_appointment_new(); Type: PROCEDURE; Schema: kaveri; Owner: postgres
--

CREATE PROCEDURE kaveri.sp_update_appointment_new()
    LANGUAGE plpgsql
    AS $$

declare
v_record record;
v_applicationnumber character varying;
v_starttime time;
v_endtime time;
v_deoid int[];
p_starttime time;
p_endtime time;
v_deo int;
i int;
v_appointment int;
duration time;
v_srocode bigint;

begin

for v_srocode in (select srocode from kaveri.sromaster where srocode in (select distinct srocode 
from kaveri.appointmentmaster a 
where (starttime>'17:30:00' or starttime<'10:00:00') and inserteddatetime ::date='2024-05-17'))

loop
	
select array_agg(userid) into v_deoid from kaveri.departmentusers d where srocode =v_srocode and designationid = 4;

for v_deo in (select unnest(v_deoid))
loop
	i = 0;

	raise notice 'deoid %',v_deo;
	for v_appointment in (select appointmentid from kaveri.appointmentmaster a 
			where deoperator = v_deo and appointmentdate::date = current_date and (starttime>'17:30:00' or starttime<'10:30:00'))
	loop 

		select max(starttime),max(endtime) into v_starttime,v_endtime
			from kaveri.appointmentmaster a 
			where deoperator = v_deo and appointmentdate::date = current_date+1;

		select (endtime-starttime) into duration
			from kaveri.appointmentmaster a 
			where appointmentid=v_appointment;
		
			raise notice 'appointmentid %',v_appointment;

	
		raise notice 'duration %',duration;
		raise notice 'old_end %',v_endtime;
		raise notice 'new_end %', (v_endtime::time+duration::interval);
	
		if (v_endtime is null)
		then 
		v_endtime='10:30:00';
		end if;
		
		update kaveri.appointmentmaster set appointmentdate=(current_Date+1),starttime=v_endtime,endtime=(v_endtime::time+duration::interval) 
		where appointmentid =v_appointment;
	
--	
--	p_starttime=p_endtime;
--	p_endtime=(p_endtime::time+duration::interval);
	
--	end if;
 
 
end loop;
	
	
	
end loop;
end loop;
end;
$$;


ALTER PROCEDURE kaveri.sp_update_appointment_new() OWNER TO postgres;

--
-- Name: sp_update_documentnumber(); Type: PROCEDURE; Schema: kaveri; Owner: csgadmin
--

CREATE PROCEDURE kaveri.sp_update_documentnumber()
    LANGUAGE plpgsql
    AS $$



declare
v_applicationnumber character varying;
v_srocode bigint;
v_considerationamount bigint;
v_considerationfruits bigint;
begin

for v_applicationnumber in (select p.applicationnumber  
from kaveri.documentmaster  p where srocode=102 and finalregistrationnumber is not null)	
loop
	select count(applicationnumber) into v_considerationamount from kaveri.documentmaster d2  where srocode=102 and finalregistrationnumber is not null;
	if (v_considerationamount>0)
	then 
	update kaveri.documentmaster dm  set finalregistrationnumber=(select regexp_replace(finalregistrationnumber,'RONA','RON')  from kaveri.documentmaster where applicationnumber=v_applicationnumber)  
	where dm.applicationnumber =v_applicationnumber;
	raise notice 'applicationnubmer %',v_applicationnumber;
end if;
	
end loop;
end;
$$;


ALTER PROCEDURE kaveri.sp_update_documentnumber() OWNER TO csgadmin;

--
-- Name: sp_update_ec_fetch_details(date, date); Type: PROCEDURE; Schema: kaveri; Owner: raghavendrap
--

CREATE PROCEDURE kaveri.sp_update_ec_fetch_details(IN _fromdate date, IN _todate date)
    LANGUAGE plpgsql
    AS $$

declare
v_record record;
v_rows int;
v_total_updated bigint = 0;
v_count bigint;
begin

select count(*) into v_count
	from kaveri.ec_fetch_details e
		join k1data.k1documentmaster d on e.documentid =d.documentid and e.srocode =d.srocode
		join k1data.k1propertymaster pm on d.documentid=pm.documentid and d.srocode=pm.regsrocode
		join k1data.k1propertyschedules ps on pm.propertyid =ps.propertyid and pm.regsrocode =ps.srocode
	where (e.executiondate >= _fromdate::timestamp AND e.executiondate <  (_todate::timestamp + INTERVAL '1 day')) and
	e.northboundary like '%?%' --or e.southboundary like '%?%' or e.eastboundary like '%?%' or e.westboundary like '%?%' or e.description like '%?%' 
--	and p.isudpated = true and p.isreverted  = true 
	and e.k1k2flag = 1;

raise notice 'fromdate - % | todate - % | count - %',_fromdate,_todate,v_count;

if v_count <> 0 then 
	
	for v_record in (select ps.scheduleid,d.documentid ,d.srocode,
		e.northboundary as oldnorthboundary,
		e.southboundary as oldsouthboundary,
		e.eastboundary as oldeastboundary,
		e.westboundary as oldwestboundary,
		e.description as olddescription,
		pm.northboundary as newnorthboundary,
		pm.southboundary as newsouthboundary,
		pm.eastboundary as neweastboundary,
		pm.westboundary as newwestboundary,
		ps.description as newdescription
		from kaveri.ec_fetch_details e
		join k1data.k1documentmaster d on e.documentid =d.documentid and e.srocode =d.srocode
		join k1data.k1propertymaster pm on d.documentid=pm.documentid and d.srocode=pm.regsrocode
		join k1data.k1propertyschedules ps on pm.propertyid =ps.propertyid and pm.regsrocode =ps.srocode
	where (e.executiondate >= _fromdate::timestamp AND e.executiondate <  (_todate::timestamp + INTERVAL '1 day')) and
	e.northboundary like '%?%' --or e.southboundary like '%?%' or e.eastboundary like '%?%' or e.westboundary like '%?%' or e.description like '%?%' 
--	and p.isudpated = true and p.isreverted  = true 
	and e.k1k2flag = 1)
	loop
		
	  	update kaveri.ec_fetch_details s 
		set	northboundary = v_record.newnorthboundary,
			southboundary = v_record.newsouthboundary,
			eastboundary = v_record.neweastboundary,
			westboundary = v_record.newwestboundary,
			description = v_record.newdescription
		where s.scheduleid=v_record.scheduleid and s.documentid=v_record.documentid and s.srocode=v_record.srocode; commit;
		GET DIAGNOSTICS v_rows = ROW_COUNT;	
		v_total_updated := v_total_updated + v_rows;
		
		raise notice 'scheduleid - % | documentid - % | srocode - % | oldnorthboundary - % | newnorthboundary - % | oldsouthboundary - % | newsouthboundary - % | oldeastboundary - % | neweastboundary - % | oldwestboundary - % | newwestboundary - % | olddescription - % | newdescription - %',
		v_record.scheduleid,v_record.documentid ,v_record.srocode,v_record.oldnorthboundary,v_record.newnorthboundary,v_record.oldsouthboundary,v_record.newsouthboundary,v_record.oldeastboundary,v_record.neweastboundary,v_record.oldwestboundary,v_record.newwestboundary,v_record.olddescription,v_record.newdescription;
	end loop;
	raise notice 'Total updated count - %',v_total_updated;
else 
	raise notice 'No record found for the date range.';
end if;
end;
$$;


ALTER PROCEDURE kaveri.sp_update_ec_fetch_details(IN _fromdate date, IN _todate date) OWNER TO raghavendrap;

--
-- Name: sp_update_ec_mapped_details(date, date); Type: PROCEDURE; Schema: kaveri; Owner: raghavendrap
--

CREATE PROCEDURE kaveri.sp_update_ec_mapped_details(IN _fromdate date, IN _todate date)
    LANGUAGE plpgsql
    AS $$

declare
v_record record;
v_rows int;
v_total_updated bigint = 0;
v_count bigint;
begin

select count(*) into v_count
	from k1data.k1partyinfo p
	join k1data.k1documentmaster d on p.documentid =d.documentid  and p.srocode =d.srocode
	join k1data.k1propertymaster pm on d.documentid=pm.documentid and d.srocode=pm.regsrocode
	join k1data.k1propertyschedules ps on pm.propertyid =ps.propertyid and pm.regsrocode =ps.srocode
	join k1data.k1propertynumberdetails pnd on pm.propertyid =pnd.propertyid and pm.regsrocode =pnd.srocode
	join kaveri.ec_mapped_details e on e.scheduleid =ps.scheduleid and e.villagecode =pm.villagecode 
		and e.registrationdatetime =d.registrationdatetime::Date and e.currrentpropertytypeid = pnd.currentpropertytypeid and 
	 	e.currentnumber like '%?%'
	where (e.registrationdatetime::date between _fromdate::date and _todate::date) 
	and p.isudpated = true and p.isreverted  = true 
	and e.k1k2flag = 1;

raise notice 'fromdate - % | todate - % | count - %',_fromdate,_todate, v_count;

if v_count <> 0 then 
	
	for v_record in (select ps.scheduleid,pm.villagecode
	,d.registrationdatetime::Date,pnd.currentnumber as newcurrentnumber,e.currentnumber as oldcurrentnumber ,pnd.currentpropertytypeid 
	from k1data.k1partyinfo p
	join k1data.k1documentmaster d on p.documentid =d.documentid  and p.srocode =d.srocode
	join k1data.k1propertymaster pm on d.documentid=pm.documentid and d.srocode=pm.regsrocode
	join k1data.k1propertyschedules ps on pm.propertyid =ps.propertyid and pm.regsrocode =ps.srocode
	join k1data.k1propertynumberdetails pnd on pm.propertyid =pnd.propertyid and pm.regsrocode =pnd.srocode
	join kaveri.ec_mapped_details e on e.scheduleid =ps.scheduleid and e.villagecode =pm.villagecode 
		and e.registrationdatetime =d.registrationdatetime::Date and e.currrentpropertytypeid = pnd.currentpropertytypeid 
		and e.currentnumber like '%?%'
	where (e.registrationdatetime::date between _fromdate::date and _todate::date) 
	and p.isudpated = true and p.isreverted  = true 
	and e.k1k2flag = 1)
	loop
		
	  	update kaveri.ec_mapped_details s 
		set currentnumber=v_record.newcurrentnumber
		where s.scheduleid=v_record.scheduleid and s.villagecode = v_record.villagecode and s.registrationdatetime::date=v_record.registrationdatetime::date and s.currrentpropertytypeid = v_record.currentpropertytypeid; commit;
		GET DIAGNOSTICS v_rows = ROW_COUNT;	
		v_total_updated := v_total_updated + v_rows;
		
		raise notice 'scheduleid - % | villagecode - % | registrationdatetime - % | currentpropertytypeid - % | oldcurrentnumber - % | newcurrentnumber - %',v_record.scheduleid,v_record.villagecode,v_record.registrationdatetime::date,v_record.currentpropertytypeid,v_record.oldcurrentnumber,v_record.newcurrentnumber;
	end loop;
	raise notice 'Total updated count - %',v_total_updated;
else 
	raise notice 'No record found for the date range.';
end if;
end;
$$;


ALTER PROCEDURE kaveri.sp_update_ec_mapped_details(IN _fromdate date, IN _todate date) OWNER TO raghavendrap;

--
-- Name: sp_update_ecname_mapped_details(date, date); Type: PROCEDURE; Schema: kaveri; Owner: raghavendrap
--

CREATE PROCEDURE kaveri.sp_update_ecname_mapped_details(IN _fromdate date, IN _todate date)
    LANGUAGE plpgsql
    AS $$

declare
v_record record;
v_rows int;
v_total_updated bigint = 0;
v_count bigint;
begin

select count(*) into v_count
	from k1data.k1partyinfo p
	join k1data.k1documentmaster d on p.documentid =d.documentid  and p.srocode =d.srocode
	join k1data.k1propertymaster pm on d.documentid=pm.documentid and d.srocode=pm.regsrocode
	join k1data.k1propertyschedules ps on pm.propertyid =ps.propertyid and pm.regsrocode =ps.srocode
	join kaveri.ecname_mapped_details en on en.partyid =p.partyid and en.scheduleid =ps.scheduleid 
	and en.registrationdatetime::date =d.registrationdatetime::date and en.fullname like '%?%'
	where (en.registrationdatetime::date between _fromdate::date and _todate::date) and
	p.isudpated = true and p.isreverted = false and
	en.k1k2flag = 1;

raise notice 'fromdate - % | todate - % | count - %',_fromdate,_todate, v_count;

if v_count <> 0 then 
	
	for v_record in (select ps.scheduleid,p.partyid,en.fullname as oldfullname,concat(p.firstname,' ',p.middlename,' ',p.lastname) as newfullname, d.registrationdatetime::date 
		from k1data.k1partyinfo p
		join k1data.k1documentmaster d on p.documentid =d.documentid  and p.srocode =d.srocode
		join k1data.k1propertymaster pm on d.documentid=pm.documentid and d.srocode=pm.regsrocode
		join k1data.k1propertyschedules ps on pm.propertyid =ps.propertyid and pm.regsrocode =ps.srocode
		join kaveri.ecname_mapped_details en on en.partyid =p.partyid and en.scheduleid =ps.scheduleid 
		and en.registrationdatetime::date =d.registrationdatetime::date and en.fullname like '%?%'
		where (en.registrationdatetime::date between _fromdate::date and _todate::date) and
		p.isudpated = true and p.isreverted = false and 
		en.k1k2flag = 1)
	loop
		
	  	update kaveri.ecname_mapped_details s 
		set fullname=v_record.newfullname
		where s.scheduleid=v_record.scheduleid and s.partyid = v_record.partyid and s.registrationdatetime::date=v_record.registrationdatetime::date; commit;
		GET DIAGNOSTICS v_rows = ROW_COUNT;	
		v_total_updated := v_total_updated + v_rows;
		
		raise notice 'scheduleid - % | partyid - % | registrationdatetime - % | oldfullname - % | newfullname - %',v_record.scheduleid,v_record.partyid,v_record.registrationdatetime::date,v_record.oldfullname,v_record.newfullname;
	end loop;
	raise notice 'Total updated count - %',v_total_updated;
else 
	raise notice 'No record found for the date range.';
end if;
end;
$$;


ALTER PROCEDURE kaveri.sp_update_ecname_mapped_details(IN _fromdate date, IN _todate date) OWNER TO raghavendrap;

--
-- Name: sp_update_feesrequired(); Type: PROCEDURE; Schema: kaveri; Owner: postgres
--

CREATE PROCEDURE kaveri.sp_update_feesrequired()
    LANGUAGE plpgsql
    AS $$

declare
v_stampruleid record;
v_srocode bigint;
--v_considerationamount bigint;
--v_stamprule int;
v_applicationnumbers character varying;
v_applicationnumber record;
--v_feesreqired record;
v_array character varying[];
v_exemptdescription character varying;
v_isexempted boolean;
v_exemtype varchar;
v_exemamount int;
v_exemdocpath character varying;
v_denodocpath character varying;
v_regexemtype character varying;
v_regexemamount int;
v_documentid bigint;
--v_cnt int;
begin

for v_applicationnumber in (select distinct fr.applicationnumber 
					from kaveri.feesrequired fr
					join kaveri.applicantapplicationdetails a on fr.applicationnumber=a.applicationnumber
					where  fr.feerulecode in (91,110,104,88,89,105,90,109)  
				and a.currentstatus ='CD106'
			and fr.exemptdescription is not null and fr.exemptdescription<>''
			and a.inserteddatetime::date>='2023-02-01' and a.inserteddatetime::date<='2023-02-28'
				and a.applicationtypeid =1)
		
loop
	
	
	
	if(v_applicationnumber.applicationnumber is not null )
	
	then 	
	select exemptdescription,isexempted,exemtype,exemamount,exemdocpath,
	denodocpath,regexemtype,regexemamount,documentid
	into v_exemptdescription,v_isexempted,v_exemtype,v_exemamount,v_exemdocpath,
	v_denodocpath,v_regexemtype,v_regexemamount,v_documentid
	from kaveri.feesrequired
	where applicationnumber =v_applicationnumber.applicationnumber 
	and feerulecode=58;
	
	update kaveri.feesrequired  set exemptdescription=v_exemptdescription,
			isexempted=v_isexempted,
			exemtype  =v_exemtype,
			exemamount =v_exemamount,
			exemdocpath =v_exemdocpath,
			denodocpath =v_denodocpath,
			regexemtype =v_regexemtype,
			regexemamount=v_regexemamount,
			documentid=v_documentid
			where applicationnumber =v_applicationnumber.applicationnumber 
			and feerulecode in (91,110,104,88,89,105,90,109);
			raise notice 'applicationnumber %',v_applicationnumber.applicationnumber ;	
		

		
--		select array_agg(v_applicationnumber.applicationnumber) into v_array;
		
end if;
	
end loop;
end;
$$;


ALTER PROCEDURE kaveri.sp_update_feesrequired() OWNER TO postgres;

--
-- Name: sp_update_feesrequired_valuationtypeid(); Type: PROCEDURE; Schema: kaveri; Owner: sumit
--

CREATE PROCEDURE kaveri.sp_update_feesrequired_valuationtypeid()
    LANGUAGE plpgsql
    AS $$

declare
v_stampruleid record;
v_srocode bigint;
--v_considerationamount bigint;
--v_stamprule int;
v_applicationnumbers character varying;
v_applicationnumber record;
v_feesreqired record;
begin

for v_applicationnumber in (select distinct fr.applicationnumber,fr.valuatiotypeid 
					from kaveri.feesrequired fr
					join kaveri.applicantapplicationdetails a on fr.applicationnumber=a.applicationnumber
					where fr.valuatiotypeid is not null and fr.valuatiotypeid in (1,3) 
					and a.inserteddatetime::date>='2024-01-01' 
					and a.inserteddatetime::date<='2024-01-06'
					)
		
loop
	if(v_applicationnumber.applicationnumber is not null and v_applicationnumber.valuatiotypeid=1)
	
	then 
	update kaveri.feesrequired set valuatiotypeid=3 where applicationnumber=v_applicationnumber.applicationnumber 
	and valuatiotypeid=1;
	raise notice 'applicationnumber % valuationtypeid %',v_applicationnumber.applicationnumber,v_applicationnumber.valuatiotypeid ;
	elsif (v_applicationnumber.applicationnumber is not null and v_applicationnumber.valuatiotypeid=3)
	then 
		update kaveri.feesrequired set valuatiotypeid=1 where applicationnumber=v_applicationnumber.applicationnumber
		and valuatiotypeid=3;
	raise notice 'applicationnumber % valuationtypeid %',v_applicationnumber.applicationnumber,v_applicationnumber.valuatiotypeid;			
	
end if;
	
end loop;
end;
$$;


ALTER PROCEDURE kaveri.sp_update_feesrequired_valuationtypeid() OWNER TO sumit;

--
-- Name: sp_update_k1data(); Type: PROCEDURE; Schema: kaveri; Owner: postgres
--

CREATE PROCEDURE kaveri.sp_update_k1data()
    LANGUAGE plpgsql
    AS $$
declare 
v_record record;
begin
	for v_record in (select row_to_json(ss) as jsond,ss.scheduleid ,ss.srocode,ss.villagecode from (select 
scheduleid,regarticlecode,stamparticlecode,sroconsideration,sromarketvalue,articlenamee,eastboundary,westboundary,southboundary,northboundary,totalarea,referencetext,documentid,srocode,executiondate,cdnumber,pagecount,claimant,executant,finalregistrationnumber,easttowest,northtosouth,description,stampruleid,stampdescription,liabilitynote,villagecode,villagenamee,hoblicode,hobliname,k1k2flag 
from kaveri.ec_fetch_details where k1k2flag =1  limit 100000) as ss)
	loop
	update kaveri.ec_fetch_details set ecjsondata=v_record.jsond where scheduleid=v_record.scheduleid and villagecode=v_record.villagecode and srocode=ss.srocode;
	commit;	
end loop;
end;
$$;


ALTER PROCEDURE kaveri.sp_update_k1data() OWNER TO postgres;

--
-- Name: sp_update_memodetals(); Type: PROCEDURE; Schema: kaveri; Owner: postgres
--

CREATE PROCEDURE kaveri.sp_update_memodetals()
    LANGUAGE plpgsql
    AS $$

declare
v_appno record;
prptymaster_new record;
prptymaster_old record;
prptysch record;
prptyno record;
begin

for v_appno in (select applicationnumber,newapplicationnumber  
from kaveri.anywhere_reg_log 
where isjurisdictionsroaccepted =true)
loop 
	

	for prptymaster_new in (select propertyid,totalarea,srocode  from kaveri.propertymaster p 
	where applicationnumber=v_appno.newapplicationnumber)
	loop 
		
	for prptymaster_old in (select propertyid,srocode  from kaveri.propertymaster p 
	where applicationnumber=v_appno.applicationnumber and totalarea=prptymaster_new.totalarea
	and srocode =prptymaster_new.srocode)
	
	loop 
	
	for prptysch in (select * from kaveri.propertyschedules p 
	where propertyid=prptymaster_old.propertyid and srocode=prptymaster_old.srocode) 
	loop 
	insert into kaveri.propertyschedules(
	scheduleid,
	propertyid,
	srocode,
	partyid,
	scheduletype,
	totalarea,
	unitid,
	description,
	partyids,
	aileniatedauthorityid,
	alieniatedorder,
	bhoomisellerpartyids,
	govtrestricorder,
	govtrestrictionid,
	landcode,
	propertygroup,
	giftshare,
	giftsharedetails,
	easttowest,
	northtosouth,
	blockchainpropertyid,
	assignedblockchainpid,
	applicationnumber,
	verified,
	issroapproved,
	eastboundary,
	westboundary,
	northboundary,
	southboundary,
	inserteddatetime,
	k1k2_flag,
	electriccompid,
	waterboardid,
	electriccomp,
	waterboard)
	values (
	nextval('kaveri.propertyschedules_scheduleid_seq'),
	prptymaster_new.propertyid,
	prptysch.srocode,
	prptysch.partyid,
	prptysch.scheduletype,
	prptysch.totalarea,
	prptysch.unitid,
	prptysch.description,
	prptysch.partyids,
	prptysch.aileniatedauthorityid,
	prptysch.alieniatedorder,
	prptysch.bhoomisellerpartyids,
	prptysch.govtrestricorder,
	prptysch.govtrestrictionid,
	prptysch.landcode,
	prptysch.propertygroup,
	prptysch.giftshare,
	prptysch.giftsharedetails,
	prptysch.easttowest,
	prptysch.northtosouth,
	prptysch.blockchainpropertyid,
	prptysch.assignedblockchainpid,
	v_appno.newapplicationnumber,
	prptysch.verified,
	prptysch.issroapproved,
	prptysch.eastboundary,
	prptysch.westboundary,
	prptysch.northboundary,
	prptysch.southboundary,
	prptysch.inserteddatetime,
	prptysch.k1k2_flag,
	prptysch.electriccompid,
	prptysch.waterboardid,
	prptysch.electriccomp,
	prptysch.waterboard);
	end loop;
	
	for prptyno in (select * from kaveri.propertynumberdetails p 
	where propertyid=prptymaster_old.propertyid and srocode=prptymaster_old.srocode ) 
	loop 
	insert into kaveri.propertynumberdetails(
	propertyid,
	srocode,
	currentpropertytypeid,
	currentnumber,
	oldpropertytypeid,
	oldnumber,
	description,
	survey_no,
	surnoc,
	hissa_no,
	inserteddatetime,
	k1k2_flag)
	values (
	prptymaster_new.propertyid,
	prptyno.srocode,
	prptyno.currentpropertytypeid,
	prptyno.currentnumber,
	prptyno.oldpropertytypeid,
	prptyno.oldnumber,
	prptyno.description,
	prptyno.survey_no,
	prptyno.surnoc,
	prptyno.hissa_no,
	prptyno.inserteddatetime,
	prptyno.k1k2_flag);
	
	
	
	
end loop;	
	
end loop;

end loop;
end loop;


end;
$$;


ALTER PROCEDURE kaveri.sp_update_memodetals() OWNER TO postgres;

--
-- Name: sp_update_partytype_salutation(); Type: PROCEDURE; Schema: kaveri; Owner: postgres
--

CREATE PROCEDURE kaveri.sp_update_partytype_salutation()
    LANGUAGE plpgsql
    AS $$
declare
v_record record;
v_partytypeid int;
v_salutationid int;

begin

for v_record in 
	(select ec.partyid from kaveri.ecname_mapped_details ec
	where ec.registrationdatetime >= '2023-01-01' and ec.registrationdatetime <= '2025-12-31'
	and ec.k1k2flag = 2 and ec.partytypeid is null
	group by ec.partyid order by ec.partyid
	limit 500)

loop
	raise notice 'Partyid - %',v_record.partyid;
	select partytypeid,salutationid into v_partytypeid,v_salutationid from kaveri.partyinfo where partyid = v_record.partyid;

	update kaveri.ecname_mapped_details set partytypeid = v_partytypeid, salutationid = v_salutationid
	where partyid = v_record.partyid;commit;
	
end loop;
end;
$$;


ALTER PROCEDURE kaveri.sp_update_partytype_salutation() OWNER TO postgres;

--
-- Name: sp_update_propertymaster(); Type: PROCEDURE; Schema: kaveri; Owner: csgadmin
--

CREATE PROCEDURE kaveri.sp_update_propertymaster()
    LANGUAGE plpgsql
    AS $$

declare
v_propertyid record;
--v_srocode bigint;
--v_considerationamount bigint;
v_applicationnumber_cnt int;
--v_considerationfruits bigint;
v_newpropertyid bigint;
v_count int;
v_prop record;
v_cnt int;
v_propertynocnt int;
v_propertyschcnt int;
v_partyinfocnt int;
v_partyschedinfocnt int;
v_orgdatacnt int;
begin

v_count:=0;	
	
for v_propertyid in (select count(*) as cnt, propertyid from kaveri.propertymaster_11092023 p group by propertyid  having count(propertyid)>1 order by count(propertyid) limit 10) 	
loop
	raise notice 'getting duplicates %',v_propertyid.propertyid;
	
	for v_prop in (select propertyid,applicationnumber,regsrocode from kaveri.propertymaster_11092023 where propertyid=v_propertyid.propertyid)
	loop
--	select count(applicationnumber) into v_applicationnumber_cnt from kaveri.propertymaster p  where applicationnumber =v_applicationnumber.applicationnumber;
	if (v_propertyid.cnt>1)
	then 
		v_newpropertyid:=nextval('kaveri.propertymaster_sequence');
	
	raise notice 'Updating Propertymaster with propertyid % with new propertyid %',v_prop.propertyid,v_newpropertyid; 

	update kaveri.propertymaster_11092023 pt set propertyid=v_newpropertyid
	where propertyid=v_prop.propertyid and regsrocode=v_prop.regsrocode;
	get diagnostics v_cnt =row_count;
	
	if(v_cnt=0) then
		raise EXCEPTION 'Propertyid update failed for %',v_count;
	end if;


	select count(*) into v_propertynocnt from kaveri.propertynumberdetails_11092023 where propertyid=v_prop.propertyid and srocode=v_prop.regsrocode;

	if (v_propertynocnt<>0)
	then
	
	raise notice 'Updating propertynumberdetails with propertyid % with new propertyid %',v_prop.propertyid,v_newpropertyid;

	update kaveri.propertynumberdetails_11092023 set propertyid =v_newpropertyid
	where propertyid=v_prop.propertyid and srocode=v_prop.regsrocode;
	get diagnostics v_cnt =row_count;
	
	if(v_cnt=0) then
		raise EXCEPTION 'propertynumberdetails update failed for %',v_count;
	end if;

	end if;

	select count(*) into v_propertyschcnt from kaveri.propertyschedules_11092023 p  where propertyid=v_prop.propertyid and applicationnumber=v_prop.applicationnumber;

	if (v_propertyschcnt<>0)
	then

	raise notice 'Updating propertyschedules with propertyid % with new propertyid %',v_prop.propertyid,v_newpropertyid;

	update kaveri.propertyschedules_11092023 set propertyid =v_newpropertyid
	where propertyid=v_prop.propertyid and applicationnumber=v_prop.applicationnumber;
	get diagnostics v_cnt =row_count;
	
	if(v_cnt=0) then
		raise EXCEPTION 'propertyschedules update failed for %',v_count;
	end if;

	end if;

	select count(*) into v_partyinfocnt from kaveri.partyinfo_11092023 p  where propertyid=v_prop.propertyid and applicationnumber=v_prop.applicationnumber;

	if (v_partyinfocnt<>0)
	then

	raise notice 'Updating partyinfo with propertyid % with new propertyid %',v_prop.propertyid,v_newpropertyid;

	update kaveri.partyinfo_11092023 set propertyid =v_newpropertyid
	where propertyid=v_prop.propertyid and applicationnumber=v_prop.applicationnumber;
	get diagnostics v_cnt =row_count;
	
	if(v_cnt=0) then
		raise EXCEPTION 'partyinfo update failed for %',v_count;
	end if;
	end if;

	select count(*) into v_partyschedinfocnt from kaveri.partyinfo_11092023 p  where propertyid=v_prop.propertyid and applicationnumber=v_prop.applicationnumber;

	if (v_partyschedinfocnt<>0)
	then
	
	raise notice 'Updating partyschedules with propertyid % with new propertyid %',v_prop.propertyid,v_newpropertyid;

	update kaveri.partyschedules_11092023 set propertyid =v_newpropertyid
	where propertyid=v_prop.propertyid and applicationnumber=v_prop.applicationnumber;
	get diagnostics v_cnt =row_count;
	
	if(v_cnt=0) then
		raise EXCEPTION 'partyschedules update failed for %',v_count;
	end if;

	end if;

	select count(*) into v_orgdatacnt from kaveri.orgdatajslip_11092023 p  where propertyid=v_prop.propertyid and applicationnumber=v_prop.applicationnumber;

	if (v_orgdatacnt<>0)
	then

	raise notice 'Updating orgdatajslip with propertyid % with new propertyid %',v_prop.propertyid,v_newpropertyid;

	update kaveri.orgdatajslip_11092023 set propertyid =v_newpropertyid
	where propertyid=v_prop.propertyid and applicationnumber=v_prop.applicationnumber;
	get diagnostics v_cnt =row_count;
	
	if(v_cnt=0) then
		raise EXCEPTION 'orgdatajslip update failed for %',v_count;
	end if;
	end if;

	v_count=v_count+1;
	raise notice 'count %; Propertyid %',v_count,v_newpropertyid;

end if;
end loop;	
end loop;
end;
$$;


ALTER PROCEDURE kaveri.sp_update_propertymaster() OWNER TO csgadmin;

--
-- Name: sp_update_srocode(); Type: PROCEDURE; Schema: kaveri; Owner: postgres
--

CREATE PROCEDURE kaveri.sp_update_srocode()
    LANGUAGE plpgsql
    AS $$


declare
v_applicationnumber character varying;
v_srocode bigint;
v_considerationamount bigint;
v_considerationfruits bigint;
begin

for v_applicationnumber in (select p.applicationnumber from kaveri.rule17filing p )	
loop
	select srocode into v_srocode from kaveri.rule17filing  where applicationnumber =v_applicationnumber;
	if (v_srocode is not null)
	then 
	update kaveri.applicantapplicationdetails ad
	set srocode=v_srocode  
	where ad.applicationnumber =v_applicationnumber;
	raise notice 'applicationnubmer %',v_applicationnumber;
end if;
	
end loop;
end;
$$;


ALTER PROCEDURE kaveri.sp_update_srocode() OWNER TO postgres;

