-- Name: sp_update_stamprules(); Type: PROCEDURE; Schema: kaveri; Owner: postgres
--

CREATE PROCEDURE kaveri.sp_update_stamprules()
    LANGUAGE plpgsql
    AS $$

declare
v_stampruleid int;
v_srocode bigint;
v_considerationamount bigint;
v_stamprule int;
begin

for v_stampruleid in (select stampruleid from  kaveri.stamprules_preprod where stampruleid=138)	
loop
	select count(*) into v_stamprule from  kaveri.stamprules where stampruleid =138;
	if (v_stamprule=1)
	then 
	update kaveri.stamprules b set 
sameasarticleid=s.sameasarticleid
,parentrefid=s.parentrefid
,haschild=s.haschild
,descriptionk=s.descriptionk
,descriptione=s.descriptione
,isslabs=s.isslabs
,unitisamount=s.unitisamount
,unitdescriptionk=s.unitdescriptionk
,unitdescriptione=s.unitdescriptione
,unit=s.unit
,value=s.value
,minlimit=s.minlimit
,maxlimit=s.maxlimit
,multipliedby=s.multipliedby
,sdcalcon=s.sdcalcon
,isinpercentage=s.isinpercentage
,isfixduty=s.isfixduty
,isexempted=s.isexempted
,isruleactive=s.isruleactive
,regvalue=s.regvalue
,regispercent=s.regispercent
,regmaxlimit=s.regmaxlimit
,regminlimit=s.regminlimit
,regcalconconsideration=s.regcalconconsideration
,othercalcrule=s.othercalcrule
,othercalcon=s.othercalcon
,isaddonvalue=s.isaddonvalue
,addonvalue=s.addonvalue
,addoncaptione=s.addoncaptione
,addoncaptionk=s.addoncaptionk
,activefrom=s.activefrom
,activeto=s.activeto
,issurcharge=s.issurcharge
,urbanvalue=s.urbanvalue
,ruralvalue=s.ruralvalue
,issurchargepercentage=s.issurchargepercentage
,iscess=s.iscess
,cessvalue=s.cessvalue
,iscesspercentage=s.iscesspercentage
,ismarketvaluationdone=s.ismarketvaluationdone
,isparttransactallowed=s.isparttransactallowed
,bucketid=s.bucketid
,bookid=s.bookid
,k1k2_flag=s.k1k2_flag
,inserteddatetime=s.inserteddatetime
 from (select * from (
select * 
		from  kaveri.stamprules_preprod ss where stampruleid=v_stampruleid ) as sss) s
 where 
   b.stampruleid=138;
	raise notice 'stampruleid %',v_stampruleid;
end if;
	
end loop;
end;
$$;


ALTER PROCEDURE kaveri.sp_update_stamprules() OWNER TO postgres;

--
-- Name: sp_update_stamprules_flag(); Type: PROCEDURE; Schema: kaveri; Owner: postgres
--

CREATE PROCEDURE kaveri.sp_update_stamprules_flag()
    LANGUAGE plpgsql
    AS $$

