--
-- Name: sp_update_surid_in_batches(); Type: PROCEDURE; Schema: kaveri; Owner: postgres
--

CREATE PROCEDURE kaveri.sp_update_surid_in_batches()
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_rows_updated INT;
    v_remaining BIGINT;
BEGIN
    LOOP
        -- SELECT COUNT(*) INTO v_remaining
        -- FROM kaveri.ecname_mapped_details
        -- WHERE surid IS NULL;

        -- RAISE NOTICE 'Remaining rows: %', v_remaining;

        -- IF v_remaining = 0 THEN
        --     EXIT;
        -- END IF;

        UPDATE kaveri.ecname_mapped_details
        SET surid = nextval('kaveri.ecname_mapped_details_surid_seq')
        WHERE ctid IN (
            SELECT ctid
            FROM kaveri.ecname_mapped_details
            WHERE surid IS NULL
            LIMIT 60000
        );

        GET DIAGNOSTICS v_rows_updated = ROW_COUNT;

        RAISE NOTICE 'Updated rows in this batch: %, Time: %', v_rows_updated,CURRENT_TIMESTAMP;

        IF v_rows_updated = 0 THEN
            RAISE NOTICE 'No rows updated, exiting loop!';
            EXIT;
        END IF;

        COMMIT;

        PERFORM pg_sleep(0.9);

    END LOOP;
END;
$$;


ALTER PROCEDURE kaveri.sp_update_surid_in_batches() OWNER TO postgres;

