--
-- Name: tabledef(oid); Type: FUNCTION; Schema: kaveri; Owner: csgadmin
--

CREATE FUNCTION kaveri.tabledef(oid) RETURNS text
    LANGUAGE sql STRICT
    AS $_$
/* snatched from https://github.com/filiprem/pg-tools */
WITH attrdef AS (
    SELECT
        n.nspname,
        c.relname,
        pg_catalog.array_to_string(c.reloptions || array(select 'toast.' || x from pg_catalog.unnest(tc.reloptions) x), ', ') as relopts,
        c.relpersistence,
        a.attnum,
        a.attname,
        pg_catalog.format_type(a.atttypid, a.atttypmod) as atttype,
        (SELECT substring(pg_catalog.pg_get_expr(d.adbin, d.adrelid, true) for 128) FROM pg_catalog.pg_attrdef d
            WHERE d.adrelid = a.attrelid AND d.adnum = a.attnum AND a.atthasdef) as attdefault,
        a.attnotnull,
        (SELECT c.collname FROM pg_catalog.pg_collation c, pg_catalog.pg_type t
            WHERE c.oid = a.attcollation AND t.oid = a.atttypid AND a.attcollation <> t.typcollation) as attcollation,
        a.attidentity,
        a.attgenerated
    FROM pg_catalog.pg_attribute a
    JOIN pg_catalog.pg_class c ON a.attrelid = c.oid
    JOIN pg_catalog.pg_namespace n ON c.relnamespace = n.oid
    LEFT JOIN pg_catalog.pg_class tc ON (c.reltoastrelid = tc.oid)
    WHERE a.attrelid = $1
        AND a.attnum > 0
        AND NOT a.attisdropped
    ORDER BY a.attnum
),
coldef AS (
    SELECT
        attrdef.nspname,
        attrdef.relname,
        attrdef.relopts,
        attrdef.relpersistence,
        pg_catalog.format(
            '%I %s%s%s%s%s',
            attrdef.attname,
            attrdef.atttype,
            case when attrdef.attcollation is null then '' else pg_catalog.format(' COLLATE %I', attrdef.attcollation) end,
            case when attrdef.attnotnull then ' NOT NULL' else '' end,
            case when attrdef.attdefault is null then ''
                else case when attrdef.attgenerated = 's' then pg_catalog.format(' GENERATED ALWAYS AS (%s) STORED', attrdef.attdefault)
                    when attrdef.attgenerated <> '' then ' GENERATED AS NOT_IMPLEMENTED'
                    else pg_catalog.format(' DEFAULT %s', attrdef.attdefault)
                end
            end,
            case when attrdef.attidentity<>'' then pg_catalog.format(' GENERATED %s AS IDENTITY',
                    case attrdef.attidentity when 'd' then 'BY DEFAULT' when 'a' then 'ALWAYS' else 'NOT_IMPLEMENTED' end)
                else '' end
        ) as col_create_sql
    FROM attrdef
    ORDER BY attrdef.attnum
),
tabdef AS (
    SELECT
        coldef.nspname,
        coldef.relname,
        coldef.relopts,
        coldef.relpersistence,
        string_agg(coldef.col_create_sql, E',\n    ') as cols_create_sql
    FROM coldef
    GROUP BY
        coldef.nspname, coldef.relname, coldef.relopts, coldef.relpersistence
)
SELECT
    format(
        'CREATE%s TABLE %I.%I%s%s%s;',
        case tabdef.relpersistence when 't' then ' TEMP' when 'u' then ' UNLOGGED' else '' end,
        tabdef.nspname,
        tabdef.relname,
        coalesce(
            (SELECT format(E'\n    PARTITION OF %I.%I %s\n', pn.nspname, pc.relname,
                pg_get_expr(c.relpartbound, c.oid))
                FROM pg_class c JOIN pg_inherits i ON c.oid = i.inhrelid
                JOIN pg_class pc ON pc.oid = i.inhparent
                JOIN pg_namespace pn ON pn.oid = pc.relnamespace
                WHERE c.oid = $1),
            format(E' (\n    %s\n)', tabdef.cols_create_sql)
        ),
        case when tabdef.relopts <> '' then format(' WITH (%s)', tabdef.relopts) else '' end,
        coalesce(E'\nPARTITION BY '||pg_get_partkeydef($1), '')
    ) as table_create_sql
FROM tabdef
$_$;


ALTER FUNCTION kaveri.tabledef(oid) OWNER TO csgadmin;

--
-- Name: update_surid_in_batches(); Type: PROCEDURE; Schema: kaveri; Owner: postgres
--

CREATE PROCEDURE kaveri.update_surid_in_batches()
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_rows_updated INT;
    v_remaining BIGINT;
BEGIN
    LOOP
        -- SELECT COUNT(*) INTO v_remaining
        -- FROM kaveri.ecname_mapped_details
        -- WHERE surid IS NULL;
		PERFORM 1
		FROM kaveri.ecname_mapped_details
		WHERE surid IS NULL
		LIMIT 1;

        RAISE NOTICE 'Remaining rows: %', v_remaining;

        -- Exit if nothing left
        IF v_remaining = 0 THEN
            EXIT;
        END IF;

        -- Batch update
        UPDATE kaveri.ecname_mapped_details
        SET surid = nextval('kaveri.ecname_mapped_details_surid_seq')
        WHERE ctid IN (
            SELECT ctid
            FROM kaveri.ecname_mapped_details
            WHERE surid IS NULL
            LIMIT 5000
        );

        GET DIAGNOSTICS v_rows_updated = ROW_COUNT;

        RAISE NOTICE 'Updated rows in this batch: %', v_rows_updated;

        -- Safety check
        IF v_rows_updated = 0 THEN
            RAISE NOTICE 'No rows updated, exiting loop!';
            EXIT;
        END IF;

        COMMIT;

        PERFORM pg_sleep(0.5);

        -- START TRANSACTION;
    END LOOP;
END;
$$;


ALTER PROCEDURE kaveri.update_surid_in_batches() OWNER TO postgres;

--
-- Name: update_witness_endorsement_flags(text, integer[]); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.update_witness_endorsement_flags(p_applicationno text, p_witnessid integer[]) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    rows_affected INTEGER;
BEGIN

    UPDATE kaveri.witnessinfo
    SET isendorsementsigned = false
    WHERE applicationnumber = p_applicationno 
      AND witnessid = ANY(p_witnessid);


    GET DIAGNOSTICS rows_affected = ROW_COUNT;


    IF rows_affected > 0 THEN
        RETURN 1;
    ELSE
        RETURN 0;
    END IF;
END;
$$;


ALTER FUNCTION kaveri.update_witness_endorsement_flags(p_applicationno text, p_witnessid integer[]) OWNER TO postgres;

--
-- Name: upsert_citizenloginotp(character varying, smallint, integer); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.upsert_citizenloginotp(p_otpsource character varying, p_otp smallint, p_otpcount integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $$

BEGIN
    -- Attempt to update if the otpsource number exists
    UPDATE kaveri.citizenloginotp
    SET 
        otp = p_otp,
--        otptime = p_datetime,
        otpcount = p_otpcount
    WHERE otpsource = p_otpsource;
	
    -- If no rows were updated (i.e., otpsource number doesn't exist), insert a new record
    IF NOT FOUND THEN
        INSERT INTO kaveri.citizenloginotp (
            otpsource, otp, otpcount, incorrectotpcnt, incorrectlogincnt, k1k2_flag
        ) VALUES (
            p_otpsource, p_otp, p_otpcount, 0, 0, 2
        );
    END IF;
	return p_otpsource;
END;
$$;


ALTER FUNCTION kaveri.upsert_citizenloginotp(p_otpsource character varying, p_otp smallint, p_otpcount integer) OWNER TO postgres;

--
-- Name: upsert_citizenloginotp(character varying, smallint, integer, timestamp without time zone); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.upsert_citizenloginotp(p_otpsource character varying, p_otp smallint, p_otpcount integer, p_datetime timestamp without time zone) RETURNS character varying
    LANGUAGE plpgsql
    AS $$

BEGIN
    -- Attempt to update if the otpsource number exists
    UPDATE kaveri.citizenloginotp
    SET 
        otp = p_otp,
        otptime = p_datetime,
        otpcount = p_otpcount
    WHERE otpsource = p_otpsource;
	
    -- If no rows were updated (i.e., otpsource number doesn't exist), insert a new record
    IF NOT FOUND THEN
        INSERT INTO kaveri.citizenloginotp (
            otpsource, otp, otptime, otpcount, incorrectotpcnt, incorrectlogincnt,inserteddatetime, k1k2_flag
        ) VALUES (
            p_otpsource, p_otp, p_datetime, p_otpcount, 0, 0, p_datetime, 2
        );
    END IF;
	return p_otpsource;
END;
$$;


ALTER FUNCTION kaveri.upsert_citizenloginotp(p_otpsource character varying, p_otp smallint, p_otpcount integer, p_datetime timestamp without time zone) OWNER TO postgres;

--
-- Name: upsert_k1jslipdata(text, text, text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.upsert_k1jslipdata(p_finalregistrationnumber text, p_actualdata text, p_modifieddata text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE kaveri.k1jslipdata 
    SET actualdata = p_actualdata, 
        modifieddata = p_modifieddata,
        inserted_at = CURRENT_TIMESTAMP 
    WHERE finalregistrationnumber = p_finalregistrationnumber;

    IF NOT FOUND THEN
        INSERT INTO kaveri.k1jslipdata (finalregistrationnumber, actualdata, modifieddata)
        VALUES (p_finalregistrationnumber, p_actualdata, p_modifieddata);
    END IF;
END;
$$;


ALTER FUNCTION kaveri.upsert_k1jslipdata(p_finalregistrationnumber text, p_actualdata text, p_modifieddata text) OWNER TO postgres;

--
-- Name: upsert_k1jslipdata(text, text, text, text); Type: FUNCTION; Schema: kaveri; Owner: postgres
--

CREATE FUNCTION kaveri.upsert_k1jslipdata(p_finalregistrationnumber text, p_actualdata text, p_modifieddata text, p_xml text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE kaveri.k1jslipdata 
    SET actualdata = p_actualdata, 
        modifieddata = p_modifieddata,
        inserteddatetime = CURRENT_TIMESTAMP,
		sentxml = p_xml 
    WHERE finalregistrationnumber = p_finalregistrationnumber;

    IF NOT FOUND THEN
        INSERT INTO kaveri.k1jslipdata (finalregistrationnumber, actualdata, modifieddata,sentxml)
        VALUES (p_finalregistrationnumber, p_actualdata, p_modifieddata,p_xml);
    END IF;
END;
$$;


ALTER FUNCTION kaveri.upsert_k1jslipdata(p_finalregistrationnumber text, p_actualdata text, p_modifieddata text, p_xml text) OWNER TO postgres;

