--
-- Name: feecalculation_v; Type: VIEW; Schema: kaveri; Owner: csgadmin
--

CREATE VIEW kaveri.feecalculation_v AS
 SELECT DISTINCT b.applicationnumber,
    a.valid,
    a.srocode,
    a.villagecode,
    a.roadcode,
    a.valuationdate,
    a.regarticlecode,
    a.propertytypeid,
    a.totalarea,
    a.unitid,
    c.measurementnamee,
    a.marketvalue,
    b.documentid,
    b.feerulecode,
    e.descriptione,
    b.amountrequired
   FROM kaveri.valuationdetails a,
    kaveri.feesrequired b,
    kaveri.measurementmaster c,
    kaveri.propertytypemaster d,
    kaveri.feesrulemaster e,
    kaveri.sromaster f,
    kaveri.villagemaster g,
    kaveri.roadmaster h,
    kaveri.documentmaster i,
    kaveri.stamparticles j
  WHERE (((a.applicationnumber)::text = (b.applicationnumber)::text) AND (a.srocode = b.srocode) AND (a.propertytypeid = d.propertytypeid) AND (a.unitid = c.measurementcode) AND (a.regarticlecode = e.regarticlecode) AND (a.regarticlecode = j.stamparticlecode) AND (b.feerulecode = e.feerulecode) AND (a.srocode = f.srocode) AND (a.villagecode = g.villagecode) AND (a.roadcode = h.roadcode));


ALTER TABLE kaveri.feecalculation_v OWNER TO csgadmin;

