--
-- Name: reg_article_sub_article_mapping; Type: VIEW; Schema: kaveri; Owner: csgadmin
--

CREATE VIEW kaveri.reg_article_sub_article_mapping AS
 SELECT d.regarticlecode,
    d.articlenamee AS nature_of_document,
    a.stamparticlecode,
    a.articlenamee AS article,
    c.stampruleid,
    c.descriptione AS subarticle
   FROM (((kaveri.stamparticles a
     JOIN kaveri.stamprules c ON ((a.stamparticlecode = c.stamparticlecode)))
     JOIN kaveri.stampregrelations b ON ((a.stamparticlecode = b.stamparticlecode)))
     JOIN kaveri.registrationarticles d ON ((b.regarticlecode = d.regarticlecode)));


ALTER TABLE kaveri.reg_article_sub_article_mapping OWNER TO csgadmin;

