--
-- Name: sakalaonlyaccept; Type: MATERIALIZED VIEW; Schema: kaveri; Owner: postgres
--

CREATE MATERIALIZED VIEW kaveri.sakalaonlyaccept AS
 SELECT su.gscno,
    su.applicationnumber,
    su.webmethod
   FROM (((kaveri.sakala_uploadfiledetails su
     JOIN kaveri.applicantapplicationdetails a ON (((su.applicationnumber)::text = (a.applicationnumber)::text)))
     LEFT JOIN kaveri.sakala_uploadfiledetails su2 ON ((((su2.applicationnumber)::text = (su.applicationnumber)::text) AND ((su2.webmethod)::text = 'Update'::text))))
     JOIN kaveri.documentmaster dm ON (((su.applicationnumber)::text = (dm.applicationnumber)::text)))
  WHERE (((a.currentstatus)::text = ANY (ARRAY['CD120'::text, 'CD134'::text, 'CD136'::text])) AND ((su.webmethod)::text = 'Accept'::text) AND (su.processingcode = 1) AND (su2.applicationnumber IS NULL) AND ((dm.registrationdatetime)::date = CURRENT_DATE))
UNION ALL
 SELECT su.gscno,
    su.applicationnumber,
    su.webmethod
   FROM (((kaveri.sakala_uploadfiledetails su
     JOIN kaveri.applicantapplicationdetails a ON (((su.applicationnumber)::text = (a.applicationnumber)::text)))
     LEFT JOIN kaveri.sakala_uploadfiledetails su2 ON ((((su2.applicationnumber)::text = (su.applicationnumber)::text) AND ((su2.webmethod)::text = 'Update'::text))))
     JOIN kaveri.ec_applicationdetails ea ON (((su.applicationnumber)::text = (ea.applicationnumber)::text)))
  WHERE (((a.currentstatus)::text = ANY (ARRAY['CE110'::text, 'CE114'::text])) AND ((su.webmethod)::text = 'Accept'::text) AND (su.processingcode = 1) AND (su2.applicationnumber IS NULL) AND ((ea.signeddatetime)::date = CURRENT_DATE))
UNION ALL
 SELECT su.gscno,
    su.applicationnumber,
    su.webmethod
   FROM (((kaveri.sakala_uploadfiledetails su
     JOIN kaveri.applicantapplicationdetails a ON (((su.applicationnumber)::text = (a.applicationnumber)::text)))
     LEFT JOIN kaveri.sakala_uploadfiledetails su2 ON ((((su2.applicationnumber)::text = (su.applicationnumber)::text) AND ((su2.webmethod)::text = 'Update'::text))))
     JOIN kaveri.cc_applicationdetails ea ON (((su.applicationnumber)::text = (ea.applicationnumber)::text)))
  WHERE (((a.currentstatus)::text = ANY (ARRAY['CC109'::text, 'CC114'::text])) AND ((su.webmethod)::text = 'Accept'::text) AND (su.processingcode = 1) AND (su2.applicationnumber IS NULL) AND ((ea.signeddatetime)::date = CURRENT_DATE))
  WITH NO DATA;


ALTER TABLE kaveri.sakalaonlyaccept OWNER TO postgres;

