--
-- Name: sakalnos; Type: MATERIALIZED VIEW; Schema: kaveri; Owner: postgres
--

CREATE MATERIALIZED VIEW kaveri.sakalnos AS
 SELECT s4.ne,
    s4.gscno
   FROM ( SELECT ( SELECT DISTINCT s1.gscno
                   FROM kaveri.sakala_uploadfiledetails s1
                  WHERE (((ss.gscno)::text = (s1.gscno)::text) AND ((s1.webmethod)::text = 'Update'::text) AND (s1.processingcode = 1))) AS ne,
            ss.gscno
           FROM ( SELECT su.gscno
                   FROM kaveri.sakala_uploadfiledetails su
                  WHERE (((su.uploaddatetime)::date = CURRENT_DATE) AND ((su.webmethod)::text = 'Update'::text) AND (su.processingcode <> 1))) ss) s4
  WHERE (s4.ne IS NULL)
  WITH NO DATA;


ALTER TABLE kaveri.sakalnos OWNER TO postgres;

