-- Name: view_fetch_liveoffices; Type: VIEW; Schema: kaveri; Owner: csgadmin
--

CREATE VIEW kaveri.view_fetch_liveoffices AS
 SELECT d.districtcode,
    d.districtnamee AS registrationdistrict,
    ('SRO '::text || (s.sronamee)::text) AS liveoffices
   FROM kaveri.sromaster s,
    kaveri.districtmaster d
  WHERE ((s.islive = true) AND (s.districtcode = d.districtcode));


ALTER TABLE kaveri.view_fetch_liveoffices OWNER TO csgadmin;

--
-- Name: view_fetch_masterval_road; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.view_fetch_masterval_road AS
 SELECT rm.roadcode,
    rm.roadnamee AS roadname,
    rm.roadnamek,
    vm.srocode,
    vm.villagecode,
    vm.villagenamee AS villagename,
    vm.villagenamek,
    h.hoblicode,
    h.hoblinamee AS hobliname,
    ( SELECT array_to_json(array_agg(row_to_json(agri.*))) AS array_to_json
           FROM ( SELECT ra.agrilandtypeid,
                    agri_ty.description AS agrilandtypedesc,
                    ra.measurementcode AS unitid,
                    ra.rate,
                    val.agrilandtypeid AS agrilandtypeid_val,
                    agri_valty.description AS agrilandtypedesc_val,
                    val.unitid AS unitid_val,
                    val.rate AS rate_val,
                    val.valratedetailid,
                        CASE
                            WHEN (val.valrateheaderid IS NULL) THEN false
                            ELSE true
                        END AS isdisable
                   FROM (((( SELECT rad.roadcode,
                            rad.agrilandtypeid,
                            rad.measurementcode,
                            rad.rate,
                            rad.effectivedate,
                            COALESCE(lead(rad.effectivedate, 1) OVER (PARTITION BY rad.roadcode, rad.agrilandtypeid, rad.measurementcode ORDER BY rad.effectivedate), (CURRENT_DATE)::timestamp without time zone) AS effectivetodate
                           FROM kaveri.rateagriculturaldetail rad
                          WHERE (rad.roadcode = rm.roadcode)
                        UNION
                         SELECT mv.roadcode,
                            mv.agrilandtypeid,
                            mv.unitid AS measurementcode,
                            NULL::numeric AS rate,
                            CURRENT_DATE AS effectivedate,
                            (CURRENT_DATE + 1) AS effectivetodate
                           FROM kaveri.mas_valuationrates mv
                          WHERE ((mv.roadcode = rm.roadcode) AND (mv.propertytypeid = 17) AND (NOT ((mv.roadcode, mv.agrilandtypeid, mv.unitid) IN ( SELECT rd.roadcode,
                                    rd.agrilandtypeid,
                                    rd.measurementcode
                                   FROM kaveri.rateagriculturaldetail rd
                                  WHERE (rd.roadcode = rm.roadcode)))))) ra
                     JOIN kaveri.mas_val_agrilandtypes agri_ty ON ((ra.agrilandtypeid = agri_ty.agrilandtypeid)))
                     LEFT JOIN kaveri.mas_valuationrates val ON (((val.roadcode = ra.roadcode) AND (vm.srocode = val.srocode) AND (ra.agrilandtypeid = val.agrilandtypeid) AND (val.propertytypeid = 17) AND (ra.measurementcode = val.unitid) AND (COALESCE(val.effectivedate, ((CURRENT_DATE + 1))::timestamp without time zone) > CURRENT_DATE))))
                     LEFT JOIN kaveri.mas_val_agrilandtypes agri_valty ON ((val.agrilandtypeid = agri_valty.agrilandtypeid)))
                  WHERE ((ra.roadcode = rm.roadcode) AND (CURRENT_DATE >= ra.effectivedate) AND (CURRENT_DATE <= ra.effectivetodate))) agri) AS agri_val,
    ( SELECT array_to_json(array_agg(row_to_json(nonagri.*))) AS array_to_json
           FROM ( SELECT ra.propertytypeid,
                    ptm.propertytypename,
                    ra.measurementcode AS unitid,
                    ra.rate,
                    val.propertytypeid AS propertytypeid_val,
                    ptm_val.propertytypename AS propertytypename_val,
                    val.unitid AS unitid_val,
                    val.rate AS rate_val,
                    val.valratedetailid,
                        CASE
                            WHEN (val.valrateheaderid IS NULL) THEN false
                            ELSE true
                        END AS isdisable
                   FROM (((( SELECT op.roadcode,
                            op.propertytypeid,
                            op.measurementcode,
                            op.rate,
                            op.effectivedate,
                            COALESCE(lead(op.effectivedate, 1) OVER (PARTITION BY op.roadcode, op.propertytypeid, op.measurementcode ORDER BY op.effectivedate), (CURRENT_DATE)::timestamp without time zone) AS effectivetodate
                           FROM kaveri.openbuiltratedetail op
                          WHERE (op.roadcode = rm.roadcode)
                        UNION
                         SELECT mv.roadcode,
                            mv.propertytypeid,
                            mv.unitid AS measurementcode,
                            NULL::numeric AS rate,
                            CURRENT_DATE AS effectivedate,
                            (CURRENT_DATE + 1) AS effectivetodate
                           FROM kaveri.mas_valuationrates mv
                          WHERE ((mv.roadcode = rm.roadcode) AND (mv.agrilandtypeid IS NULL) AND (mv.amenitiesid IS NULL) AND (NOT ((mv.roadcode, mv.propertytypeid, mv.unitid) IN ( SELECT op.roadcode,
                                    op.propertytypeid,
                                    op.measurementcode
                                   FROM kaveri.openbuiltratedetail op
                                  WHERE (op.roadcode = rm.roadcode)))))) ra
                     JOIN kaveri.propertytypemaster ptm ON ((ptm.propertytypeid = ra.propertytypeid)))
                     LEFT JOIN kaveri.mas_valuationrates val ON (((val.roadcode = ra.roadcode) AND (vm.srocode = val.srocode) AND (ra.propertytypeid = val.propertytypeid) AND (ra.measurementcode = val.unitid) AND (COALESCE(val.effectivedate, ((CURRENT_DATE + 1))::timestamp without time zone) > CURRENT_DATE))))
                     LEFT JOIN kaveri.propertytypemaster ptm_val ON ((val.propertytypeid = ptm_val.propertytypeid)))
                  WHERE ((ra.roadcode = rm.roadcode) AND (CURRENT_DATE >= ra.effectivedate) AND (ptm.propertytypeid <> 12) AND (CURRENT_DATE <= ra.effectivetodate))) nonagri) AS nonagri_val,
    ( SELECT array_to_json(array_agg(row_to_json(nonagri_flat.*))) AS array_to_json
           FROM ( SELECT ra.propertytypeid,
                    ptm.propertytypename,
                    ra.amenitiesid,
                    ra.floorid,
                    ra.measurementcode AS unitid,
                    ra.rate,
                    val.propertytypeid AS propertytypeid_val,
                    val.amenitiesid AS amenitiesid_val,
                    val.floorid AS floorid_val,
                    val.unitid AS unitid_val,
                    val.rate AS rate_val,
                    val.valratedetailid,
                        CASE
                            WHEN (val.valrateheaderid IS NULL) THEN false
                            ELSE true
                        END AS isdisable
                   FROM ((( SELECT op.roadid AS roadcode,
                            op.propertytypeid,
                            op.amenitiesid,
                            op.floorid,
                            op.unitid AS measurementcode,
                            op.rate,
                            op.effectivedate,
                            COALESCE(lead(op.effectivedate, 1) OVER (PARTITION BY op.roadid, op.propertytypeid, op.floorid, op.unitid ORDER BY op.effectivedate), (CURRENT_DATE)::timestamp without time zone) AS effectivetodate
                           FROM kaveri.mas_val_flatrates op
                          WHERE (op.roadid = rm.roadcode)
                        UNION
                         SELECT mv.roadcode,
                            mv.propertytypeid,
                            mv.amenitiesid,
                            mv.floorid,
                            mv.unitid AS measurementcode,
                            NULL::numeric AS rate,
                            CURRENT_DATE AS effectivedate,
                            (CURRENT_DATE + 1) AS effectivetodate
                           FROM kaveri.mas_valuationrates mv
                          WHERE ((mv.roadcode = rm.roadcode) AND (NOT ((mv.roadcode, mv.propertytypeid, mv.floorid, mv.unitid) IN ( SELECT op.roadid,
                                    op.propertytypeid,
                                    op.floorid,
                                    op.unitid
                                   FROM kaveri.mas_val_flatrates op
                                  WHERE (op.roadid = rm.roadcode)))))) ra
                     JOIN kaveri.propertytypemaster ptm ON ((ptm.propertytypeid = ra.propertytypeid)))
                     LEFT JOIN kaveri.mas_valuationrates val ON (((val.roadcode = ra.roadcode) AND (val.propertytypeid = 12) AND (COALESCE(val.effectivedate, ((CURRENT_DATE + 1))::timestamp without time zone) > CURRENT_DATE))))
                  WHERE ((ra.roadcode = rm.roadcode) AND (ptm.propertytypeid = 12))) nonagri_flat) AS nonagri_flat_val
   FROM ((kaveri.roadmaster rm
     JOIN kaveri.villagemaster vm ON ((vm.villagecode = rm.villagecode)))
     JOIN kaveri.hoblimaster h ON ((vm.hoblicode = h.hoblicode)));


ALTER TABLE kaveri.view_fetch_masterval_road OWNER TO postgres;

