    sr.srocode,
    st.cmonth,
    st.cyear,
    st.ctotaldocuments,
    st.ctotalstampduty,
    st.ctotalregfees,
    st.pyear,
    st.ptotaldocuments,
    st.ptotalstampduty,
    st.ptotalregfees
   FROM kaveri.statement st,
    kaveri.sromaster sr
  WHERE ((st.sroname)::text = (sr.sronamee)::text);


