    to_char(a.applicationstartdate, 'HH24:MI:SS'::text) AS "time",
    b.gscno AS sakalanumber,
    a.currentstatus,
    c.wrkflowstatusnamee AS applicationstatus
   FROM ((kaveri.applicantapplicationdetails a
     JOIN kaveri.sakala_partydetails b ON ((a.srocode = b.srocode)))
     JOIN kaveri.wrkflowmaster c ON (((a.currentstatus)::text = (c.wrkflowstatusid)::text)));


ALTER TABLE kaveri.vw_cc_applications OWNER TO postgres;

--
-- Name: vw_citizen_dashbaord; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_citizen_dashbaord AS
 SELECT app.citizenid,
    app.applicationnumber,
    COALESCE(app.regsrocode, app.srocode) AS srocode,
    app.applicationstartdate,
    app.applicationenddate,
    app.applicationdate,
    app.issubmitted,
    app.isduecorrection,
    app.ispayment,
    app.isdueschedule,
    app.assignedto,
    app.applicationtypeid,
    ser.servicename,
    app.currentstatus,
    wrk.wrkflowstatusnamee AS currentstatusname,
    sr.sronamee AS sroname,
    sr.sronamek,
    app.remarks,
    ( SELECT ams_reg_epaymenttransdetails.deptreferencecode
           FROM kaveri.ams_reg_epaymenttransdetails
          WHERE (((ams_reg_epaymenttransdetails.applicationnumber)::text = (app.applicationnumber)::text) AND (ams_reg_epaymenttransdetails.isdelete = false))
          ORDER BY ams_reg_epaymenttransdetails.inserteddatetime DESC
         LIMIT 1) AS deptreferencecode,
        CASE
            WHEN (ff.applicationnumber IS NOT NULL) THEN true
            ELSE false
        END AS wasfrozen,
    ( SELECT max(fp2.crtdt) AS submitteddate
           FROM kaveri.applicationaudit fp2
          WHERE (((fp2.applicationnumber)::text = (app.applicationnumber)::text) AND ((fp2.wrkflowstatusid)::text = 'CE105'::text))) AS submitteddate,
    dm.isdigitallyexecuted,
    dm.issignpageappended,
    dm.uploaddocdeedpath,
    app.ispanverified,
    app.ispanmandatory
   FROM (((((kaveri.applicantapplicationdetails app
     JOIN kaveri.servicesmaster ser ON ((app.applicationtypeid = ser.serviceid)))
     JOIN kaveri.wrkflowmaster wrk ON (((app.currentstatus)::text = (wrk.wrkflowstatusid)::text)))
     LEFT JOIN kaveri.documentmaster dm ON (((app.applicationnumber)::text = (dm.applicationnumber)::text)))
     LEFT JOIN kaveri.sromaster sr ON ((sr.srocode = COALESCE(app.regsrocode, app.srocode))))
     LEFT JOIN ( SELECT DISTINCT fp.applicationnumber
           FROM kaveri.applicationaudit fp
          WHERE ((fp.wrkflowstatusid)::text = 'CD140'::text)
          GROUP BY fp.applicationnumber) ff ON (((ff.applicationnumber)::text = (app.applicationnumber)::text)))
  WHERE (app.isdeleted = false)
  ORDER BY app.applicationstartdate DESC;


ALTER TABLE kaveri.vw_citizen_dashbaord OWNER TO postgres;

