--
-- Name: vw_cnt_totalapplication; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_cnt_totalapplication AS
 SELECT DISTINCT ad.applicationtypeid,
    sm.servicename AS applicationtypename,
    d.bookid,
    bm.booknameenglish AS bookname,
    sum(
        CASE
            WHEN (d.finalregistrationnumber IS NOT NULL) THEN 1
            ELSE 0
        END) OVER (PARTITION BY ad.applicationtypeid, d.bookid) AS cnt_totalapplication
   FROM (((kaveri.applicantapplicationdetails ad
     JOIN kaveri.servicesmaster sm ON ((sm.serviceid = ad.applicationtypeid)))
     JOIN kaveri.documentmaster d ON (((d.applicationnumber)::text = (ad.applicationnumber)::text)))
     JOIN kaveri.booktypemaster bm ON ((d.bookid = bm.bookid)))
  WHERE (((ad.currentstatus)::text = 'CD120'::text) AND (bm.bookid IS NOT NULL) AND (((d.registrationdatetime)::date >= (((((to_char((CURRENT_DATE)::timestamp with time zone, 'YYYY'::text) || '-'::text) || '04'::text) || '-'::text) || '01'::text))::date) OR (((d.registrationdatetime)::date >= ((((((((to_char((CURRENT_DATE)::timestamp with time zone, 'YYYY'::text))::integer - 1))::text || '-'::text) || '04'::text) || '-'::text) || '01'::text))::date) AND ((d.registrationdatetime)::date < (((((to_char((CURRENT_DATE)::timestamp with time zone, 'YYYY'::text) || '-'::text) || '04'::text) || '-'::text) || '01'::text))::date))))
UNION ALL
 SELECT DISTINCT ad.applicationtypeid,
    sm.servicename AS applicationtypename,
    NULL::integer AS bookid,
    NULL::character varying(150) AS bookname,
    sum(
        CASE
            WHEN ((ad.currentstatus)::text = ANY (ARRAY[('CE110'::character varying)::text, ('CC109'::character varying)::text])) THEN 1
            ELSE 0
        END) OVER (PARTITION BY ad.applicationtypeid, ad.bookid) AS cnt_totalapplication
   FROM (kaveri.applicantapplicationdetails ad
     JOIN kaveri.servicesmaster sm ON ((sm.serviceid = ad.applicationtypeid)))
  WHERE (((ad.currentstatus)::text = ANY (ARRAY[('CE110'::character varying)::text, ('CC109'::character varying)::text])) AND (((ad.applicationenddate)::date >= (((((to_char((CURRENT_DATE)::timestamp with time zone, 'YYYY'::text) || '-'::text) || '04'::text) || '-'::text) || '01'::text))::date) OR (((ad.applicationenddate)::date >= ((((((((to_char((CURRENT_DATE)::timestamp with time zone, 'YYYY'::text))::integer - 1))::text || '-'::text) || '04'::text) || '-'::text) || '01'::text))::date) AND ((ad.applicationenddate)::date < (((((to_char((CURRENT_DATE)::timestamp with time zone, 'YYYY'::text) || '-'::text) || '04'::text) || '-'::text) || '01'::text))::date))))
  ORDER BY 1;


ALTER TABLE kaveri.vw_cnt_totalapplication OWNER TO postgres;

--
-- Name: vw_construction_types; Type: VIEW; Schema: kaveri; Owner: csgadmin
--

CREATE VIEW kaveri.vw_construction_types AS
 SELECT ct.constructiontypeid,
    ((max(DISTINCT (ct.description)::text) || '; '::text) || string_agg((((ct.floordesc)::text || ' : '::text) || COALESCE(cr.rate, (ct.rate)::numeric)), ' ; '::text ORDER BY ct.floorid)) AS constructiontypedesc,
    max(
        CASE
            WHEN (ct.floorid = 1) THEN COALESCE(cr.rate, (ct.rate)::numeric)
            ELSE NULL::numeric
        END) AS groundfloorrate,
    max(
        CASE
            WHEN (ct.floorid = 1) THEN NULL::numeric
            ELSE COALESCE(cr.rate, (ct.rate)::numeric)
        END) AS abovefloorrate,
    ct.villagecode
   FROM (( SELECT v.villagecode,
            v.villagenamee AS villagename,
            ct_1.description,
            ct_1.constructiontypeid,
                CASE
                    WHEN (b.floorid = 1) THEN ct_1.groundfloorrate
                    ELSE ct_1.abovefloorrate
                END AS rate,
            b.floorid,
            b.description AS floordesc
           FROM kaveri.mas_val_constructiontypes ct_1,
            kaveri.mas_val_buildingfloors b,
            kaveri.villagemaster v
          WHERE (b.floorid = ANY (ARRAY[1, 2]))) ct
     LEFT JOIN kaveri.mas_val_constructionrates cr ON (((cr.constructiontypeid = ct.constructiontypeid) AND (cr.floorid = ct.floorid) AND (ct.villagecode = cr.villageid))))
  GROUP BY ct.constructiontypeid, ct.villagecode;


ALTER TABLE kaveri.vw_construction_types OWNER TO csgadmin;

--
-- Name: vw_court_order_non_agri; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_court_order_non_agri AS
 SELECT DISTINCT x.propertyid,
    x.sro,
    x.court_order_number,
    x.injuction_or_stay_flag,
    x.survey_no,
    x.currentnumber,
    x.oldnumber,
    x.eastboundary,
    x.westboundary,
    x.northboundary,
    x.southboundary,
    x.area,
    x.description,
    x.applicationnumber,
    x.currentpropertytypeid,
    x.propertynotype,
    x.oldpropertytypeid,
    x.hissa_no
   FROM ( SELECT bpn.id,
            bpn.srocode AS sro,
            bpn.propertyid,
            bpn.injuction_or_stay_flag,
            bpn.orderid,
            bpn.currentpropertytypeid,
            bnt.typenameenglish AS propertynotype,
            bpn.currentnumber,
            bpn.oldpropertytypeid,
            bpn.oldnumber,
            bpn.description AS description1,
            bpn.survey_no,
            bpn.surnoc,
            bpn.hissa_no,
            bp.propertydescription,
            bp.isagriculturalproperty,
            bp.eastboundary,
            bp.northboundary,
            bp.westboundary,
            bp.southboundary,
            bp.area,
            bp.measurementunit,
            mum.descriptionenglish,
            co.ordernumber AS court_order_number,
            co.description,
            co.orderentrydatetime,
            co.iscancelled,
            co.reasonofcancellation,
            pm.applicationnumber
           FROM (((((kaveri.bannedpropertynumbers bpn
             JOIN kaveri.bannedproperties bp ON ((bpn.propertyid = bp.propertyid)))
             JOIN kaveri.propertymaster pm ON (((pm.propertyid = bp.propertyid) AND (bpn.srocode = bp.srocode))))
             JOIN kaveri.courtorders co ON (((bp.srocode = co.srocode) AND (bp.orderid = co.orderid))))
             JOIN kaveri.measunitmaster mum ON ((mum.unitid = bp.measurementunit)))
             JOIN kaveri.propertynotypemaster bnt ON ((bnt.propertytypeid = bpn.currentpropertytypeid)))) x;


ALTER TABLE kaveri.vw_court_order_non_agri OWNER TO postgres;

--
-- Name: vw_cvcdigr_dashboard_count; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_cvcdigr_dashboard_count AS
 SELECT sum(ss.pending) AS pending,
    sum(ss.accepted) AS accepted,
    sum(ss.rejected) AS rejected
   FROM ( SELECT
                CASE
                    WHEN (mas_valrateheader.isapproved IS NULL) THEN count(mas_valrateheader.valrateheaderid)
                    ELSE NULL::bigint
                END AS pending,
                CASE
                    WHEN (mas_valrateheader.isapproved = true) THEN count(mas_valrateheader.valrateheaderid)
                    ELSE NULL::bigint
                END AS accepted,
                CASE
                    WHEN (mas_valrateheader.isapproved = false) THEN count(mas_valrateheader.valrateheaderid)
                    ELSE NULL::bigint
                END AS rejected
           FROM kaveri.mas_valrateheader
          GROUP BY mas_valrateheader.isapproved) ss;


ALTER TABLE kaveri.vw_cvcdigr_dashboard_count OWNER TO postgres;

--
-- Name: vw_dailyregister; Type: VIEW; Schema: kaveri; Owner: csgadmin
