    d.stampduty_others,
    d.infrastructure,
    d.corporation,
    d.muncipal,
    d.prevtotalstampduty,
    d.talukboard,
    d.documentnumber,
    d.bookid,
    d.volumename,
    d.completiondate,
    d.returndate,
    d.prevtotalregistrationfees,
    d.registrationfees,
    d.deficient_registrationfees,
    d.previousdate,
    d.deficient_stampduty,
    d.copyfees,
    d.prevtotalcopyfees,
    d.hindumarriagefee,
    d.otherfees,
    d.otherfeesdesc,
    d.splothermarriagefee,
    d.prevtotalmarriagefee,
    d.splmarriagefee,
    d.prevtotalmutationfee,
    d.mutationfee,
