   FROM kaveri.dailyreceiptfees d,
    kaveri.sromaster s
  WHERE ((d.sroname)::text = (s.sronamee)::text);


ALTER TABLE kaveri.vw_dailyregister OWNER TO csgadmin;

--
-- Name: vw_ddd; Type: MATERIALIZED VIEW; Schema: kaveri; Owner: postgres
--

CREATE MATERIALIZED VIEW kaveri.vw_ddd AS
 SELECT DISTINCT ad.deoid,
    ad.applicationnumber AS applicationnum,
    slot.slotbookdate AS applicationdate,
    slot.slotbooktime AS applicationtime,
    ad.srocode,
    ad.applicationtypeid,
    sm.servicename,
    ad.currentstatus,
    wm.wrkflowstatusnamee,
    COALESCE(dm.ispaymentdetails, false) AS isverified,
    COALESCE(dm.isuploaddocuments, false) AS isuploaddocuments,
    (dm.presentdatetime)::date AS presentdate,
    (dm.executiondatetime)::date AS executedate,
    (regexp_replace((dm.pendingdocumentnumber)::text, '^([^-]*-[^-]*)-.*$'::text, '\1'::text))::character varying AS regexp_replace,
    dm.finalregistrationnumber,
    dm.documentid,
    dm.isprintsummary,
    dm.isprintendorsement,
    dm.isdigitalsigned,
    dm.isregistrationcompleted,
    dm.gscno AS sakalanumber,
    dm.uploadsummarydocpath,
    ad.remarks,
    dm.isundervaluation,
    rg.articlenamee,
    dm.isphotothumbtransmitted,
        CASE
            WHEN ((ad.applicationnumber)::text = (fk.applicationnumber)::text) THEN true
            ELSE false
        END AS ispaymentdone
   FROM ((((((kaveri.applicantapplicationdetails ad
     JOIN kaveri.documentmaster dm ON (((dm.applicationnumber)::text = (ad.applicationnumber)::text)))
     LEFT JOIN ( SELECT DISTINCT sl.applicationnumber,
            sl.appointmentdate AS sltbookedon,
            (sl.appointmentdate)::date AS slotbookdate,
            ((sl.starttime || '-'::text) || (sl.endtime)::text) AS slotbooktime
           FROM kaveri.appointmentmaster sl
          WHERE ((sl.status)::text = ANY (ARRAY[('1'::character varying)::text, ('Pending'::character varying)::text]))) slot ON (((slot.applicationnumber)::text = (ad.applicationnumber)::text)))
     JOIN kaveri.wrkflowmaster wm ON (((wm.wrkflowstatusid)::text = (ad.currentstatus)::text)))
     LEFT JOIN kaveri.registrationarticles rg ON ((ad.regarticlecode = rg.regarticlecode)))
     JOIN kaveri.servicesmaster sm ON ((ad.applicationtypeid = sm.serviceid)))
     LEFT JOIN kaveri.feesrequired_paymentchk fk ON (((ad.applicationnumber)::text = (fk.applicationnumber)::text)))
  WHERE ((ad.deoid IN ( SELECT DISTINCT a.deoid
           FROM kaveri.applicantapplicationdetails a)) AND ((ad.currentstatus)::text = ANY (ARRAY[('CD110'::character varying)::text, ('CD111'::character varying)::text, ('CD112'::character varying)::text, ('CD113'::character varying)::text, ('CD114'::character varying)::text, ('CD115'::character varying)::text, ('CD116'::character varying)::text, ('CD117'::character varying)::text, ('CD120'::character varying)::text, ('CD119'::character varying)::text, ('CD134'::character varying)::text, ('CD136'::character varying)::text])))
  WITH NO DATA;


ALTER TABLE kaveri.vw_ddd OWNER TO postgres;

