   FROM ((kaveri.applicantapplicationdetails ad
     JOIN kaveri.documentmaster dm ON ((((dm.applicationnumber)::text = (ad.applicationnumber)::text) AND (dm.registrationdatetime IS NOT NULL) AND (dm.isuploaddocuments = true))))
     LEFT JOIN kaveri.servicesmaster sm ON ((ad.applicationtypeid = sm.serviceid)));


