--
-- Name: vw_dro_landingboard; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_dro_landingboard AS
 SELECT DISTINCT ad.srocode,
    ad.applicationtypeid,
    sm.servicename AS applicationtypename,
    usr.userid,
    usr.username,
    usr.designame,
    sum(
        CASE
            WHEN ((ad.currentstatus)::text = ANY (ARRAY['FR107'::text, 'FR108'::text, 'FR115'::text, 'FR117'::text, 'FR118'::text, 'FR109'::text])) THEN 1
            ELSE 0
        END) OVER (PARTITION BY ad.srocode, usr.userid, ad.applicationtypeid) AS cnt_dfda_dsda
   FROM ((kaveri.applicantapplicationdetails ad
     JOIN kaveri.servicesmaster sm ON ((sm.serviceid = ad.applicationtypeid)))
     JOIN kaveri.vw_department_users usr ON (((usr.userid = ad.sfdaid) AND (usr.designationid = ANY (ARRAY[10, 11, 5])) AND ((ad.currentstatus)::text = ANY (ARRAY['FR107'::text, 'FR108'::text, 'FR115'::text, 'FR117'::text, 'FR118'::text, 'FR109'::text])))));


