 SELECT empleavedetails.empleavedetailsid,
    empleavedetails.empid,
    empleavedetails.leavestatus,
        CASE
            WHEN ((empleavedetails.leavestatus)::text = 'Approved'::text) THEN (((((((('Leaves approved from'::text || ' '::text) || empleavedetails.fromdate) || ' '::text) || empleavedetails.todate) || ' '::text) || 'By'::text) || ' '::text) || (empleavedetails.reportingperson)::text)
            WHEN ((empleavedetails.leavestatus)::text = 'Rejected'::text) THEN (((((((('Leaves rejected from'::text || ' '::text) || empleavedetails.fromdate) || ' '::text) || empleavedetails.todate) || ' '::text) || 'By'::text) || ' '::text) || (empleavedetails.reportingperson)::text)
            ELSE NULL::text
        END AS leavetatuses
   FROM kaveri.empleavedetails;


