--
-- Name: vw_fee_calculation_amount_details_dept_auditor_v2_tst_v2; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fee_calculation_amount_details_dept_auditor_v2_tst_v2 AS
 SELECT 'citizen'::text AS usertype,
    ff.propertyid,
    (ff.applicationnumber)::text AS applicationnumber,
    sum(ff.cess) AS cess,
    sum(ff.deficit_stamp_duty) AS deficitstampduty,
    sum(ff.mutation_fee) AS mutationfee,
    sum(ff.registration_fee) AS registrationfee,
    sum(ff.service_charge) AS servicecharge,
    sum(ff.stamp_duty) AS stampduty,
    sum(ff.surcharge) AS surcharge,
    sum(ff.duplicate_stamp_duty) AS duplicatestampduty,
    sum(ff.duplicate_registration_fee) AS duplicateregistrationfee,
    sum(ff.private_attendance_fee) AS privateattandancefee,
    sum(ff.consenting_fee) AS consentingfee,
    sum(ff.memo_fees) AS memofee,
    sum(ff.adjudication_fee) AS adjudicationfee,
    sum(ff.e_stamp_fee) AS estampfee,
    sum(ff.denotation_of_stamp_duty) AS denotationofstampduty,
    sum(ff.govt_duty_before_exemption) AS govtdutybeforeexem,
    ( SELECT sum(fss.amountrequired) AS sum
           FROM ( SELECT
                        CASE
                            WHEN (frm.ismanualfee = true) THEN sum(COALESCE(fr.amountrequired, (0)::numeric))
                            ELSE '0'::numeric
                        END AS amountrequired
                   FROM (kaveri.scrutinyfeechange fr
                     JOIN kaveri.feesrulemaster frm ON ((fr.feerulecode = frm.feerulecode)))
                  WHERE ((fr.applicationnumber)::text = (ff.applicationnumber)::text)
                  GROUP BY fr.applicationnumber, frm.ismanualfee) fss) AS otherfee
   FROM ( SELECT ss.propertyid,
            ss.applicationnumber,
                CASE
                    WHEN (ss.feerulecode = 1) THEN sum(COALESCE(ss.amountrequired, (0)::numeric))
                    ELSE '0'::numeric
                END AS registration_fee,
                CASE
                    WHEN (ss.feerulecode = 35) THEN sum(COALESCE(ss.amountrequired, (0)::numeric))
                    ELSE '0'::numeric
                END AS deficit_stamp_duty,
                CASE
                    WHEN (ss.feerulecode = 58) THEN sum(COALESCE(ss.amountrequired, (0)::numeric))
                    ELSE '0'::numeric
                END AS surcharge,
                CASE
                    WHEN (ss.feerulecode = 2) THEN sum(COALESCE(ss.amountrequired, (0)::numeric))
                    ELSE '0'::numeric
                END AS service_charge,
                CASE
                    WHEN (ss.feerulecode = 6) THEN sum(COALESCE(ss.amountrequired, (0)::numeric))
                    ELSE '0'::numeric
                END AS mutation_fee,
                CASE
                    WHEN (ss.feerulecode = 7) THEN sum(COALESCE(ss.amountrequired, (0)::numeric))
                    ELSE '0'::numeric
                END AS private_attendance_fee,
                CASE
                    WHEN (ss.feerulecode = 34) THEN sum(COALESCE(ss.amountrequired, (0)::numeric))
                    ELSE '0'::numeric
                END AS consenting_fee,
                CASE
                    WHEN (ss.feerulecode = 36) THEN sum(COALESCE(ss.amountrequired, (0)::numeric))
                    ELSE '0'::numeric
                END AS stamp_duty,
                CASE
                    WHEN (ss.feerulecode = 59) THEN sum(COALESCE(ss.amountrequired, (0)::numeric))
                    ELSE '0'::numeric
                END AS cess,
                CASE
                    WHEN (ss.feerulecode = 64) THEN sum(COALESCE(ss.amountrequired, (0)::numeric))
                    ELSE '0'::numeric
                END AS duplicate_stamp_duty,
                CASE
                    WHEN (ss.feerulecode = 65) THEN sum(COALESCE(ss.amountrequired, (0)::numeric))
                    ELSE '0'::numeric
                END AS duplicate_registration_fee,
                CASE
                    WHEN (ss.feerulecode = 88) THEN sum(COALESCE(ss.amountrequired, (0)::numeric))
                    ELSE '0'::numeric
                END AS adjudication_fee,
                CASE
                    WHEN (ss.feerulecode = 89) THEN sum(COALESCE(ss.amountrequired, (0)::numeric))
                    ELSE '0'::numeric
                END AS e_stamp_fee,
                CASE
                    WHEN (ss.feerulecode = 90) THEN sum(COALESCE(ss.amountrequired, (0)::numeric))
                    ELSE '0'::numeric
                END AS memo_fees,
                CASE
                    WHEN (ss.feerulecode = 104) THEN sum(COALESCE(ss.amountrequired, (0)::numeric))
                    ELSE '0'::numeric
                END AS denotation_of_stamp_duty,
                CASE
                    WHEN (ss.feerulecode = 105) THEN sum(COALESCE(ss.amountrequired, (0)::numeric))
                    ELSE '0'::numeric
                END AS govt_duty_before_exemption
           FROM ( SELECT b.feerulecode,
                    b.applicationnumber,
                    b.propertyid,
                    b.amountrequired,
                    f.descriptione
                   FROM (kaveri.scrutinyfeechange b
                     LEFT JOIN kaveri.feesrulemaster f ON ((b.feerulecode = f.feerulecode)))
                  WHERE (b.feerulecode = ANY (ARRAY[1, 2, 6, 7, 34, 35, 36, 58, 59, 64, 65, 88, 89, 90, 104, 105]))
                  GROUP BY b.feerulecode, b.applicationnumber, b.propertyid, b.amountrequired, f.descriptione) ss
          GROUP BY ss.propertyid, ss.applicationnumber, ss.feerulecode, ss.amountrequired) ff
  GROUP BY ff.propertyid, ff.applicationnumber
UNION ALL
 SELECT 'sfda'::text AS usertype,
    ff.propertyid,
    (ff.applicationnumber)::text AS applicationnumber,
    sum(ff.cess) AS cess,
    sum(ff.deficit_stamp_duty) AS deficitstampduty,
    sum(ff.mutation_fee) AS mutationfee,
    sum(ff.registration_fee) AS registrationfee,
    sum(ff.service_charge) AS servicecharge,
    sum(ff.stamp_duty) AS stampduty,
    sum(ff.surcharge) AS surcharge,
    sum(ff.duplicate_stamp_duty) AS duplicatestampduty,
    sum(ff.duplicate_registration_fee) AS duplicateregistrationfee,
    sum(ff.private_attendance_fee) AS privateattandancefee,
    sum(ff.consenting_fee) AS consentingfee,
    sum(ff.memo_fees) AS memofee,
    sum(ff.adjudication_fee) AS adjudicationfee,
    sum(ff.e_stamp_fee) AS estampfee,
    sum(ff.denotation_of_stamp_duty) AS denotationofstampduty,
    sum(ff.govt_duty_before_exemption) AS govtdutybeforeexem,
    ( SELECT sum(fss.sfda_amountrequired) AS sum
           FROM ( SELECT
                        CASE
                            WHEN (frm.ismanualfee = true) THEN sum(COALESCE(fr.sfdaamountrequired, (0)::numeric))
                            ELSE '0'::numeric
                        END AS sfda_amountrequired
                   FROM (kaveri.scrutinyfeechange fr
                     JOIN kaveri.feesrulemaster frm ON ((fr.feerulecode = frm.feerulecode)))
                  WHERE ((fr.applicationnumber)::text = (ff.applicationnumber)::text)
                  GROUP BY fr.applicationnumber, frm.ismanualfee) fss) AS otherfee
   FROM ( SELECT ss.propertyid,
            ss.applicationnumber,
                CASE
                    WHEN (ss.feerulecode = 1) THEN sum(ss.sfdaamountrequired)
                    ELSE '0'::numeric
                END AS registration_fee,
                CASE
                    WHEN (ss.feerulecode = 35) THEN sum(ss.sfdaamountrequired)
                    ELSE '0'::numeric
                END AS deficit_stamp_duty,
                CASE
                    WHEN (ss.feerulecode = 58) THEN sum(ss.sfdaamountrequired)
                    ELSE '0'::numeric
                END AS surcharge,
                CASE
                    WHEN (ss.feerulecode = 2) THEN sum(ss.sfdaamountrequired)
                    ELSE '0'::numeric
                END AS service_charge,
                CASE
                    WHEN (ss.feerulecode = 6) THEN sum(ss.sfdaamountrequired)
                    ELSE '0'::numeric
                END AS mutation_fee,
                CASE
                    WHEN (ss.feerulecode = 7) THEN sum(ss.sfdaamountrequired)
                    ELSE '0'::numeric
                END AS private_attendance_fee,
                CASE
                    WHEN (ss.feerulecode = 34) THEN sum(ss.sfdaamountrequired)
                    ELSE '0'::numeric
                END AS consenting_fee,
                CASE
                    WHEN (ss.feerulecode = 36) THEN sum(ss.sfdaamountrequired)
                    ELSE '0'::numeric
                END AS stamp_duty,
                CASE
                    WHEN (ss.feerulecode = 59) THEN sum(ss.sfdaamountrequired)
                    ELSE '0'::numeric
                END AS cess,
                CASE
                    WHEN (ss.feerulecode = 64) THEN sum(ss.sfdaamountrequired)
                    ELSE '0'::numeric
                END AS duplicate_stamp_duty,
                CASE
                    WHEN (ss.feerulecode = 65) THEN sum(ss.sfdaamountrequired)
                    ELSE '0'::numeric
                END AS duplicate_registration_fee,
                CASE
                    WHEN (ss.feerulecode = 88) THEN sum(ss.sfdaamountrequired)
                    ELSE '0'::numeric
                END AS adjudication_fee,
                CASE
                    WHEN (ss.feerulecode = 89) THEN sum(ss.sfdaamountrequired)
                    ELSE '0'::numeric
                END AS e_stamp_fee,
                CASE
                    WHEN (ss.feerulecode = 90) THEN sum(ss.sfdaamountrequired)
                    ELSE '0'::numeric
                END AS memo_fees,
                CASE
                    WHEN (ss.feerulecode = 104) THEN sum(ss.sfdaamountrequired)
                    ELSE '0'::numeric
                END AS denotation_of_stamp_duty,
                CASE
                    WHEN (ss.feerulecode = 105) THEN sum(ss.sfdaamountrequired)
                    ELSE '0'::numeric
                END AS govt_duty_before_exemption
           FROM ( SELECT b.feerulecode,
                    b.applicationnumber,
                    b.propertyid,
                    b.sfdaamountrequired,
                    f.descriptione
                   FROM (kaveri.scrutinyfeechange b
                     LEFT JOIN kaveri.feesrulemaster f ON ((b.feerulecode = f.feerulecode)))
                  WHERE (b.feerulecode = ANY (ARRAY[1, 2, 6, 7, 34, 35, 36, 58, 59, 64, 65, 88, 89, 90, 104, 105]))
                  GROUP BY b.feerulecode, b.applicationnumber, b.propertyid, b.sfdaamountrequired, f.descriptione) ss
          GROUP BY ss.propertyid, ss.applicationnumber, ss.feerulecode, ss.sfdaamountrequired) ff
  GROUP BY ff.propertyid, ff.applicationnumber
UNION ALL
 SELECT 'sro'::text AS usertype,
    ff.propertyid,
    (ff.applicationnumber)::text AS applicationnumber,
    sum(ff.cess) AS cess,
    sum(ff.deficit_stamp_duty) AS deficitstampduty,
    sum(ff.mutation_fee) AS mutationfee,
    sum(ff.registration_fee) AS registrationfee,
    sum(ff.service_charge) AS servicecharge,
    sum(ff.stamp_duty) AS stampduty,
    sum(ff.surcharge) AS surcharge,
    sum(ff.duplicate_stamp_duty) AS duplicatestampduty,
    sum(ff.duplicate_registration_fee) AS duplicateregistrationfee,
    sum(ff.private_attendance_fee) AS privateattandancefee,
    sum(ff.consenting_fee) AS consentingfee,
    sum(ff.memo_fees) AS memofee,
    sum(ff.adjudication_fee) AS adjudicationfee,
    sum(ff.e_stamp_fee) AS estampfee,
    sum(ff.denotation_of_stamp_duty) AS denotationofstampduty,
    sum(ff.govt_duty_before_exemption) AS govtdutybeforeexem,
    ( SELECT sum(fss.sro_amountrequired) AS sum
           FROM ( SELECT
                        CASE
                            WHEN (frm.ismanualfee = true) THEN sum(COALESCE(fr.sroamountrequired, (0)::numeric))
                            ELSE '0'::numeric
                        END AS sro_amountrequired
                   FROM (kaveri.scrutinyfeechange fr
                     JOIN kaveri.feesrulemaster frm ON ((fr.feerulecode = frm.feerulecode)))
                  WHERE ((fr.applicationnumber)::text = (ff.applicationnumber)::text)
                  GROUP BY fr.applicationnumber, frm.ismanualfee) fss) AS otherfee
   FROM ( SELECT ss.propertyid,
            ss.applicationnumber,
                CASE
                    WHEN (ss.feerulecode = 1) THEN sum(ss.sroamountrequired)
                    ELSE '0'::numeric
                END AS registration_fee,
                CASE
                    WHEN (ss.feerulecode = 35) THEN sum(ss.sroamountrequired)
                    ELSE '0'::numeric
                END AS deficit_stamp_duty,
                CASE
                    WHEN (ss.feerulecode = 58) THEN sum(ss.sroamountrequired)
                    ELSE '0'::numeric
                END AS surcharge,
