                    ELSE '0'::numeric
                END AS cess,
                CASE
                    WHEN (ss.feerulecode = 64) THEN sum(ss.sroamountrequired)
                    ELSE '0'::numeric
                END AS duplicate_stamp_duty,
                CASE
                    WHEN (ss.feerulecode = 65) THEN sum(ss.sroamountrequired)
                    ELSE '0'::numeric
                END AS duplicate_registration_fee,
                CASE
                    WHEN (ss.feerulecode = 88) THEN sum(ss.sroamountrequired)
                    ELSE '0'::numeric
                END AS adjudication_fee,
                CASE
                    WHEN (ss.feerulecode = 89) THEN sum(ss.sroamountrequired)
                    ELSE '0'::numeric
                END AS e_stamp_fee,
                CASE
                    WHEN (ss.feerulecode = 90) THEN sum(ss.sroamountrequired)
                    ELSE '0'::numeric
                END AS memo_fees,
                CASE
                    WHEN (ss.feerulecode = 104) THEN sum(ss.sroamountrequired)
                    ELSE '0'::numeric
                END AS denotation_of_stamp_duty,
                CASE
                    WHEN (ss.feerulecode = 105) THEN sum(ss.sroamountrequired)
                    ELSE '0'::numeric
                END AS govt_duty_before_exemption
           FROM ( SELECT b.feerulecode,
                    b.applicationnumber,
                    b.propertyid,
                    b.sroamountrequired,
                    f.descriptione
                   FROM (kaveri.scrutinyfeechange b
                     LEFT JOIN kaveri.feesrulemaster f ON ((b.feerulecode = f.feerulecode)))
                  WHERE (b.feerulecode = ANY (ARRAY[1, 2, 6, 7, 34, 35, 36, 58, 59, 64, 65, 88, 89, 90, 104, 105]))
