--
-- Name: vw_fee_calculation_and_amount_details_citizen; Type: VIEW; Schema: kaveri; Owner: csgadmin
--

CREATE VIEW kaveri.vw_fee_calculation_and_amount_details_citizen AS
 SELECT v.applicationnumber,
    v.isexempted,
    v.exemptdescription,
    v.exemtype,
    v.exemamount,
    v.exemdocpath,
    v.denodocpath,
    v.regexemtype,
    v.regexemamount,
    v.registrationfee,
    v.servicecharge,
    v.mutationfee,
    v.deficitstampduty,
    v.stampduty,
    v.surcharge,
    v.cess,
    v.duplicatestampduty,
    v.duplicateregistrationfee,
    v.privateattandancefee,
    v.consentingfee,
    v.adjudicationfee,
    v.estampfee,
    v.memofees,
    v.safecustodyfee,
    v.preamptionstampduty,
    v.affidavitstampduty,
    v.appealfee,
    v.documentwithdrawalfee,
    v.holidayfee,
    v.willdepositfee,
    v.filingoftrasnlationfee,
    sub.citizen_amountrequired AS othersfee,
    v.denotationofstampduty,
    v.govtdutybeforeexem,
    (v.govtdutybeforeexem - v.stampduty) AS finalexemamt,
    v.prcardfee
   FROM (kaveri.vw_fee_calculation_details_v2 v
     LEFT JOIN ( SELECT fr.applicationnumber,
            sum(fr.amountrequired) AS citizen_amountrequired
           FROM (kaveri.feesrequired fr
             JOIN kaveri.feesrulemaster frm ON (((fr.feerulecode = frm.feerulecode) AND (frm.ismanualfee IS TRUE))))
          GROUP BY fr.applicationnumber) sub ON ((v.applicationnumber = (sub.applicationnumber)::text)));


