                    b.exemdocpath,
                    b.denodocpath,
                    f.descriptione
                   FROM (kaveri.feesrequired b
                     LEFT JOIN kaveri.feesrulemaster f ON ((b.feerulecode = f.feerulecode)))
                  WHERE ((b.feerulecode = ANY (ARRAY[1, 2, 6, 7, 34, 36, 58, 59, 64, 65, 88, 89, 90, 91, 92, 93, 94, 95, 96, 97, 98, 104, 105])) AND (b.exemamount IS NOT NULL))
                  GROUP BY b.feerulecode, b.regexemtype, b.regexemamount, b.undervaluationamount, b.applicationnumber, b.propertyid, b.isexempted, b.exemptdescription, b.exemtype, b.exemamount, b.amountrequired, b.exemdocpath, b.denodocpath, f.descriptione) ss
          GROUP BY ss.regexemtype, ss.regexemamount, ss.applicationnumber, ss.isexempted, ss.exemptdescription, ss.exemtype, ss.exemamount, ss.exemdocpath, ss.denodocpath, ss.feerulecode, ss.amountrequired) ff
  GROUP BY ff.applicationnumber, ff.regexemtype, ff.regexemamount, ff.isexempted, ff.exemptdescription, ff.exemtype, ff.exemamount, ff.exemdocpath, ff.denodocpath;


ALTER TABLE kaveri.vw_fee_calculation_details_underval_v2 OWNER TO csgadmin;

--
-- Name: vw_fee_calculation_and_amount_details_citizen_underval; Type: VIEW; Schema: kaveri; Owner: csgadmin
--

CREATE VIEW kaveri.vw_fee_calculation_and_amount_details_citizen_underval AS
 SELECT v.applicationnumber,
    v.isexempted,
    v.exemptdescription,
    v.exemtype,
    v.exemamount,
    v.exemdocpath,
    v.denodocpath,
    v.regexemtype,
    v.regexemamount,
    v.registrationfee,
    v.servicecharge,
    v.mutationfee,
    v.deficitstampduty,
    v.stampduty,
    v.surcharge,
    v.cess,
    v.duplicatestampduty,
    v.duplicateregistrationfee,
    v.privateattandancefee,
    v.consentingfee,
    v.adjudicationfee,
    v.estampfee,
    v.memofee,
    v.safecustodyfee,
    v.preamptionstampduty,
    v.affidavitstampduty,
    v.appealfee,
    v.documentwithdrawalfee,
    v.holidayfee,
    v.willdepositfee,
    v.filingoftrasnlationfee,
    sub.citizen_amountrequired AS othersfee,
    v.denotationofstampduty,
    v.govtdutybeforeexem,
    (v.govtdutybeforeexem - v.stampduty) AS finalexemamt
   FROM (kaveri.vw_fee_calculation_details_underval_v2 v
     LEFT JOIN ( SELECT fr.applicationnumber,
            sum(fr.amountrequired) AS citizen_amountrequired
           FROM (kaveri.feesrequired fr
             JOIN kaveri.feesrulemaster frm ON (((fr.feerulecode = frm.feerulecode) AND (frm.ismanualfee IS TRUE))))
          GROUP BY fr.applicationnumber) sub ON ((v.applicationnumber = (sub.applicationnumber)::text)));


ALTER TABLE kaveri.vw_fee_calculation_and_amount_details_citizen_underval OWNER TO csgadmin;

--
-- Name: vw_fee_calculation_and_amount_details_dept; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fee_calculation_and_amount_details_dept AS
 SELECT v.usertype,
    v.propertyid,
    v.applicationnumber,
    v.isexempted,
    v.exemptdescription,
    v.exemtype,
    v.exemamount,
    v.exemdocpath,
    v.denodocpath,
    v.cess,
    v.deficitstampduty,
    v.mutationfee,
    v.registrationfee,
    v.servicecharge,
    v.stampduty,
    v.surcharge,
    v.duplicatestampduty,
    v.duplicateregistrationfee,
    v.privateattandancefee,
    v.consentingfee,
    v.memofee,
    v.adjudicationfee,
    v.estampfee,
        CASE
            WHEN ((v.usertype = 'citizen'::text) AND ((v.servicecharge <> (0)::numeric) OR (v.mutationfee <> (0)::numeric))) THEN COALESCE(sub.citizen_amountrequired, (0)::numeric)
            WHEN ((v.usertype = 'sfda'::text) AND ((v.servicecharge <> (0)::numeric) OR (v.mutationfee <> (0)::numeric))) THEN COALESCE(sub.sfda_amountrequired, (0)::numeric)
            WHEN ((v.usertype = 'sro'::text) AND ((v.servicecharge <> (0)::numeric) OR (v.mutationfee <> (0)::numeric))) THEN COALESCE(sub.sro_amountrequired, (0)::numeric)
            ELSE (0)::numeric
        END AS othersfee,
    v.denotationofstampduty,
    v.govtdutybeforeexem,
    (v.govtdutybeforeexem - v.stampduty) AS finalexemamt,
    v.enquiry_fee AS enquiryfee,
    v.pr_card_fee AS prcardfee
   FROM (kaveri.vw_fee_calculation_amount_details_dept_v2_new v
     LEFT JOIN ( SELECT ss.applicationnumber,
            sum(ss.citizen_amountrequired) AS citizen_amountrequired,
            sum(ss.sfda_amountrequired) AS sfda_amountrequired,
            sum(ss.sro_amountrequired) AS sro_amountrequired
           FROM ( SELECT fr.applicationnumber,
                        CASE
                            WHEN (frm.ismanualfee = true) THEN sum(fr.amountrequired)
                            ELSE (0)::numeric
                        END AS citizen_amountrequired,
                        CASE
                            WHEN (frm.ismanualfee = true) THEN sum(fr.sfdaamountrequired)
                            ELSE (0)::numeric
                        END AS sfda_amountrequired,
                        CASE
                            WHEN (frm.ismanualfee = true) THEN sum(fr.sroamountrequired)
                            ELSE (0)::numeric
                        END AS sro_amountrequired
                   FROM (kaveri.feesrequired fr
                     JOIN kaveri.feesrulemaster frm ON ((fr.feerulecode = frm.feerulecode)))
                  GROUP BY fr.applicationnumber, frm.ismanualfee) ss
          GROUP BY ss.applicationnumber) sub ON ((v.applicationnumber = (sub.applicationnumber)::text)));


ALTER TABLE kaveri.vw_fee_calculation_and_amount_details_dept OWNER TO postgres;

