	where feerulecode in (1,2,4,6,7,35,36,58,59,64,65) order by feerulecode'::text) crosstab(applicationnumber text, isexempted boolean, exemptdescription text, exemtype text, exemamount integer, exemdocpath text, denodocpath text, registrationfee bigint, servicecharge bigint, duplicatefee bigint, mutationfee bigint, privateattendancefee bigint, deficitstampduty bigint, stampduty bigint, surcharge bigint, cess bigint, duplicatestampduty bigint, duplicateregistrationfee bigint);


