--
-- Name: vw_fee_calculation_details_chk_v2; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fee_calculation_details_chk_v2 AS
 SELECT DISTINCT (ff.applicationnumber)::text AS applicationnumber,
    ff.isexempted,
    (ff.exemptdescription)::text AS exemptdescription,
    (ff.exemtype)::text AS exemtype,
    ff.exemamount,
    (ff.exemdocpath)::text AS exemdocpath,
    (ff.denodocpath)::text AS denodocpath,
    sum(ff.cess) AS cess,
    sum(ff.deficit_stamp_duty) AS deficitstampduty,
    sum(ff.mutation_fee) AS mutationfee,
    sum(ff.registration_fee) AS registrationfee,
    sum(ff.service_charge) AS servicecharge,
    sum(ff.stamp_duty) AS stampduty,
    sum(ff.surcharge) AS surcharge,
    sum(ff.duplicate_stamp_duty) AS duplicatestampduty,
    sum(ff.duplicate_registration_fee) AS duplicateregistrationfee,
    sum(ff.private_attendance_fee) AS privateattendancefee,
    sum(ff.duplicate_fee) AS duplicatefee
   FROM ( SELECT ss.applicationnumber,
            ss.isexempted,
            ss.exemptdescription,
            ss.exemtype,
            ss.exemamount,
            ss.exemdocpath,
            ss.denodocpath,
                CASE
                    WHEN (ss.feerulecode = 1) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS registration_fee,
                CASE
                    WHEN (ss.feerulecode = 35) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS deficit_stamp_duty,
                CASE
                    WHEN (ss.feerulecode = 58) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS surcharge,
                CASE
                    WHEN (ss.feerulecode = 2) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS service_charge,
                CASE
                    WHEN (ss.feerulecode = 6) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS mutation_fee,
                CASE
                    WHEN (ss.feerulecode = 7) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS private_attendance_fee,
                CASE
                    WHEN (ss.feerulecode = 36) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS stamp_duty,
                CASE
                    WHEN (ss.feerulecode = 59) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS cess,
                CASE
                    WHEN (ss.feerulecode = 64) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS duplicate_stamp_duty,
                CASE
                    WHEN (ss.feerulecode = 65) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS duplicate_registration_fee,
                CASE
                    WHEN (ss.feerulecode = 4) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS duplicate_fee
           FROM ( SELECT b.feerulecode,
                    b.applicationnumber,
                    b.isexempted,
                    b.exemptdescription,
                    b.exemtype,
                    b.exemamount,
                    b.amountrequired,
                    b.exemdocpath,
                    b.denodocpath,
                    f.descriptione
                   FROM (kaveri.feesrequired b
                     LEFT JOIN kaveri.feesrulemaster f ON ((b.feerulecode = f.feerulecode)))
                  WHERE ((b.feerulecode = ANY (ARRAY[1, 2, 6, 7, 36, 58, 59, 64, 65, 4, 35])) AND (b.exemamount IS NOT NULL))
                  GROUP BY b.feerulecode, b.applicationnumber, b.isexempted, b.exemptdescription, b.exemtype, b.exemamount, b.amountrequired, b.exemdocpath, b.denodocpath, f.descriptione) ss
          GROUP BY ss.applicationnumber, ss.isexempted, ss.exemptdescription, ss.exemtype, ss.exemamount, ss.exemdocpath, ss.denodocpath, ss.feerulecode, ss.amountrequired) ff
  GROUP BY ff.applicationnumber, ff.isexempted, ff.exemptdescription, ff.exemtype, ff.exemamount, ff.exemdocpath, ff.denodocpath;


ALTER TABLE kaveri.vw_fee_calculation_details_chk_v2 OWNER TO postgres;

