    crosstab.consentingfee,
    crosstab.adjudicationfee,
    crosstab.estampfee,
    crosstab.memofees,
    crosstab.safecustodyfee,
    crosstab.preamptionstampduty,
    crosstab.affidavitstampduty,
    crosstab.appealfee,
    crosstab.documentwithdrawalfee,
    crosstab.holidayfee,
    crosstab.willdepositfee,
    crosstab.filingoftrasnlationfee,
    crosstab.govtdutybeforeexem
   FROM kaveri.crosstab('select b.applicationnumber::text,b.isexempted::boolean,b.exemptdescription::text,b.exemtype::text,b.exemamount::integer,
			b.exemdocpath::text,b.denodocpath::text,b.regexemtype::text,regexemamount::integer,
e.descriptione::text descriptione,case when b.feerulecode in (1,36,58,59) then b.undervaluationamount::numeric else b.amountrequired::numeric end as amountrequired 
from
--kaveri.valuationdetails a inner join 
kaveri.feesrequired b 
--on ( a.applicationnumber = b.applicationnumber) 
left join kaveri.feesrulemaster e on
--a.regarticlecode = e.regarticlecode and 
b.feerulecode = e.feerulecode order by b.applicationnumber,e.descriptione,b.feerulecode'::text, 'SELECT  descriptione FROM kaveri.feesrulemaster 
	where feerulecode in (1,2,6,7,34,36,58,59,64,65,88,89,90,91,92,93,94,95,96,97,98,104,105) order by feerulecode'::text) crosstab(applicationnumber text, isexempted boolean, exemptdescription text, exemtype text, exemamount integer, exemdocpath text, denodocpath text, regexemtype text, regexemamount integer, registrationfee numeric, servicecharge numeric, mutationfee numeric, privateattandancefee numeric, consentingfee numeric, stampduty numeric, surcharge numeric, cess numeric, duplicatestampduty numeric, duplicateregistrationfee numeric, adjudicationfee numeric, estampfee numeric, memofees numeric, safecustodyfee numeric, preamptionstampduty numeric, affidavitstampduty numeric, appealfee numeric, documentwithdrawalfee numeric, holidayfee numeric, willdepositfee numeric, filingoftrasnlationfee numeric, deficitstampduty numeric, govtdutybeforeexem numeric);


ALTER TABLE kaveri.vw_fee_calculation_details_underval OWNER TO csgadmin;

--
-- Name: vw_feecalculation_movable; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_feecalculation_movable AS
 SELECT a.documentid,
    a.feerulecode,
    b.descriptione,
    a.isexempted,
    a.exemptdescription,
    a.feecalculationstring,
    a.amountrequired,
    c.govtduty AS governmentduty,
    c.noofscanpages AS numberofpages,
    f.isinpercentage,
    c.consideration AS considerationamount,
    a.applicationnumber
   FROM (((kaveri.feesrequired a
     JOIN kaveri.feesrulemaster b ON ((a.feerulecode = b.feerulecode)))
     JOIN kaveri.propertymaster c ON (((c.propertyid = a.propertyid) AND ((a.applicationnumber)::text = (c.applicationnumber)::text))))
     JOIN kaveri.stamprules f ON (((f.stampruleid = c.stampruleid) AND (c.ismovableproperty = true))))
  ORDER BY a.feerulecode;


ALTER TABLE kaveri.vw_feecalculation_movable OWNER TO postgres;

