--
-- Name: vw_fees_landingpage; Type: VIEW; Schema: kaveri; Owner: csgadmin
--

CREATE VIEW kaveri.vw_fees_landingpage AS
 SELECT DISTINCT sum(rd.amountpaid) OVER (PARTITION BY rd.feerulecode) AS feesamount,
    sum(rd.amountpaid) OVER () AS totalamount,
    rd.feerulecode,
    fm.descriptione AS feesname
   FROM (kaveri.receiptdetails rd
     JOIN kaveri.feesrulemaster fm ON ((rd.feerulecode = fm.feerulecode)))
  WHERE ((rd.feerulecode = ANY (ARRAY[1, 36])) AND ((rd.inserteddatetime)::date >= (((((EXTRACT(year FROM CURRENT_DATE) || '-'::text) || '04'::text) || '-'::text) || '01'::text))::date) AND ((rd.inserteddatetime)::date <= ((((((EXTRACT(year FROM CURRENT_DATE) + (1)::numeric) || '-'::text) || '04'::text) || '-'::text) || '01'::text))::date));


ALTER TABLE kaveri.vw_fees_landingpage OWNER TO csgadmin;

--
-- Name: vw_fees_landingpage_1; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fees_landingpage_1 AS
 SELECT DISTINCT sum(rd.amountpaid) OVER (PARTITION BY rd.feerulecode) AS feesamount,
    sum(rd.amountpaid) OVER () AS totalamount,
    rd.feerulecode,
    fm.descriptione AS feesname
   FROM (kaveri.receiptdetails rd
     JOIN kaveri.feesrulemaster fm ON ((rd.feerulecode = fm.feerulecode)))
  WHERE ((rd.feerulecode = ANY (ARRAY[1, 36])) AND (((rd.inserteddatetime)::date >= (((((to_char((CURRENT_DATE)::timestamp with time zone, 'YYYY'::text) || '-'::text) || '04'::text) || '-'::text) || '01'::text))::date) OR (((rd.inserteddatetime)::date >= ((((((((to_char((CURRENT_DATE)::timestamp with time zone, 'YYYY'::text))::integer - 1))::text || '-'::text) || '04'::text) || '-'::text) || '01'::text))::date) AND ((rd.inserteddatetime)::date < (((((to_char((CURRENT_DATE)::timestamp with time zone, 'YYYY'::text) || '-'::text) || '04'::text) || '-'::text) || '01'::text))::date))));


ALTER TABLE kaveri.vw_fees_landingpage_1 OWNER TO postgres;

--
-- Name: vw_fees_landingpage_new; Type: VIEW; Schema: kaveri; Owner: csgadmin
--

CREATE VIEW kaveri.vw_fees_landingpage_new AS
 SELECT DISTINCT sum(rd.amountpaid) OVER (PARTITION BY rd.feerulecode, rd.srocode) AS feesamount,
    sum(rd.amountpaid) OVER (PARTITION BY rd.srocode, rd.feerulecode) AS totalamount,
    rd.srocode,
    rd.feerulecode,
    fm.descriptione AS feesname
   FROM (kaveri.receiptdetails rd
     JOIN kaveri.feesrulemaster fm ON ((rd.feerulecode = fm.feerulecode)))
  WHERE ((rd.feerulecode = ANY (ARRAY[1, 36])) AND (rd.amountpaid <> (0)::numeric));


ALTER TABLE kaveri.vw_fees_landingpage_new OWNER TO csgadmin;

