    frm.descriptione AS feerulename,
    ah.deptpurposeid,
    ah.name AS accntheadname,
    ah.headofaccount AS prpsname,
    ah.treasurynumber AS trsrycode,
    substr((ah.headofaccount)::text, 1, 4) AS prpsnamehead,
    ah.isactive,
    ah.issubpurposeexist,
    sm.servicename,
    sm.nomenclature,
    frm.subrefcode
   FROM (((kaveri.feesrulemaster frm
     LEFT JOIN kaveri.mas_ams_accountheadsfeetypesmapping ahmap ON (((frm.feerulecode = ahmap.feeruleid) AND (ahmap.isactive = true))))
     LEFT JOIN kaveri.mas_ams_accountheads ah ON (((ah.deptpurposeid = ahmap.deptpurposeid) AND (ah.serviceid = ahmap.serviceid))))
     LEFT JOIN kaveri.servicesmaster sm ON ((sm.serviceid = ah.serviceid)));


