--
-- Name: vw_fetch_aadharhash_excel; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_aadharhash_excel AS
 SELECT p.partyid AS linkpartyid,
    p.partytypeid AS linked_partytypeid,
    p.firstname AS linked_firstname,
        CASE
            WHEN ((p1.partytypeid = 4) AND (p2.firstname IS NOT NULL)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is rep. by minor guardian ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ', whose POA is ', s2.descriptione, p2.firstname, ' ', p2.middlename, ' ', p2.lastname)
            WHEN ((p1.partytypeid = 4) AND (p2.firstname IS NULL)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is rep. by minor guardian ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)
            WHEN ((p1.partytypeid = 5) AND (p.isorganization = true)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' POA by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ' is Rep. by ', p1.orgpoaauthsignfname, ' ', p1.orgpoaauthsignlname)
            WHEN ((p1.partytypeid = 5) AND (p.isorganization = false)) THEN concat(s1.descriptione, p1.firstname, ' is POA of ', s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
            WHEN ((p1.partytypeid = 9) AND (p.isorganization = true) AND (p2.firstname IS NOT NULL)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is Rep. by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ', whose POA is ', s2.descriptione, p2.firstname, ' ', p2.middlename, ' ', p2.lastname)
            WHEN ((p1.partytypeid = 9) AND (p.isorganization = true) AND (p2.firstname IS NULL)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is Rep. by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)
            WHEN ((p1.partytypeid IS NULL) AND (p.partytypeid = 1)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
            WHEN ((p1.partytypeid IS NULL) AND (p.partytypeid = 2)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
            ELSE NULL::text
        END AS fullname,
        CASE
            WHEN ((p1.partytypeid = 4) AND (p2.firstname IS NOT NULL)) THEN (p2.aadharhash)::text
            WHEN ((p1.partytypeid = 4) AND (p2.firstname IS NULL)) THEN (p1.aadharhash)::text
            WHEN ((p1.partytypeid = 5) AND (p.isorganization = true)) THEN (p1.aadharhash)::text
            WHEN ((p1.partytypeid = 5) AND (p.isorganization = false)) THEN (p1.aadharhash)::text
            WHEN ((p1.partytypeid = 9) AND (p.isorganization = true) AND (p2.firstname IS NOT NULL)) THEN (p2.aadharhash)::text
            WHEN ((p1.partytypeid = 9) AND (p.isorganization = true) AND (p2.firstname IS NULL)) THEN (p1.aadharhash)::text
            WHEN ((p1.partytypeid IS NULL) AND (p.partytypeid = 1)) THEN (p.aadharhash)::text
            WHEN ((p1.partytypeid IS NULL) AND (p.partytypeid = 2)) THEN (p.aadharhash)::text
            ELSE NULL::text
        END AS aadharhash,
        CASE
            WHEN ((p1.partytypeid = 4) AND (p2.firstname IS NOT NULL)) THEN p2.partyid
            WHEN ((p1.partytypeid = 4) AND (p2.firstname IS NULL)) THEN p1.partyid
            WHEN ((p1.partytypeid = 5) AND (p.isorganization = true)) THEN p1.partyid
            WHEN ((p1.partytypeid = 5) AND (p.isorganization = false)) THEN p1.partyid
            WHEN ((p1.partytypeid = 9) AND (p.isorganization = true) AND (p2.firstname IS NOT NULL)) THEN p2.partyid
            WHEN ((p1.partytypeid = 9) AND (p.isorganization = true) AND (p2.firstname IS NULL)) THEN p1.partyid
            WHEN ((p1.partytypeid IS NULL) AND (p.partytypeid = 1)) THEN p.partyid
            WHEN ((p1.partytypeid IS NULL) AND (p.partytypeid = 2)) THEN p.partyid
            ELSE NULL::bigint
        END AS partyid,
    p.applicationnumber,
        CASE
            WHEN ((p1.partytypeid = 4) AND (p2.firstname IS NOT NULL)) THEN p2.phonenumber
            WHEN ((p1.partytypeid = 4) AND (p2.firstname IS NULL)) THEN p1.phonenumber
            WHEN ((p1.partytypeid = 5) AND (p.isorganization = true)) THEN p1.phonenumber
            WHEN ((p1.partytypeid = 5) AND (p.isorganization = false)) THEN p1.phonenumber
            WHEN ((p1.partytypeid = 9) AND (p.isorganization = true) AND (p2.firstname IS NOT NULL)) THEN p2.phonenumber
            WHEN ((p1.partytypeid = 9) AND (p.isorganization = true) AND (p2.firstname IS NULL)) THEN p1.phonenumber
            WHEN ((p1.partytypeid IS NULL) AND (p.partytypeid = 1)) THEN p.phonenumber
            WHEN ((p1.partytypeid IS NULL) AND (p.partytypeid = 2)) THEN p.phonenumber
            ELSE NULL::character varying
        END AS phonenumber,
        CASE
            WHEN ((p1.partytypeid = 4) AND (p2.firstname IS NOT NULL)) THEN p2.vaultid
            WHEN ((p1.partytypeid = 4) AND (p2.firstname IS NULL)) THEN p1.vaultid
            WHEN ((p1.partytypeid = 5) AND (p.isorganization = true)) THEN p1.vaultid
            WHEN ((p1.partytypeid = 5) AND (p.isorganization = false)) THEN p1.vaultid
            WHEN ((p1.partytypeid = 9) AND (p.isorganization = true) AND (p2.firstname IS NOT NULL)) THEN p2.vaultid
            WHEN ((p1.partytypeid = 9) AND (p.isorganization = true) AND (p2.firstname IS NULL)) THEN p1.vaultid
            WHEN ((p1.partytypeid IS NULL) AND (p.partytypeid = 1)) THEN p.vaultid
            WHEN ((p1.partytypeid IS NULL) AND (p.partytypeid = 2)) THEN p.vaultid
            ELSE NULL::character varying
        END AS vaultid,
    p.ownerno,
    p.mainownerno,
    p.landcode,
        CASE
            WHEN ((p1.partytypeid = 4) AND (p2.firstname IS NOT NULL)) THEN p2.pan
            WHEN ((p1.partytypeid = 4) AND (p2.firstname IS NULL)) THEN p1.pan
            WHEN ((p1.partytypeid = 5) AND (p.isorganization = true)) THEN p1.pan
            WHEN ((p1.partytypeid = 5) AND (p.isorganization = false)) THEN p1.pan
            WHEN ((p1.partytypeid = 9) AND (p.isorganization = true) AND (p2.firstname IS NOT NULL)) THEN p2.pan
            WHEN ((p1.partytypeid = 9) AND (p.isorganization = true) AND (p2.firstname IS NULL)) THEN p1.pan
            WHEN ((p1.partytypeid IS NULL) AND (p.partytypeid = 1)) THEN p.pan
            WHEN ((p1.partytypeid IS NULL) AND (p.partytypeid = 2)) THEN p.pan
            ELSE NULL::character varying
        END AS pan
   FROM ((((((((kaveribck.partyinfo_vrnmissing p
     LEFT JOIN kaveribck.partyinfo_vrnmissing p1 ON (((p.partyid = p1.linkpartyid) AND (p1.partytypeid = ANY (ARRAY[9, 4, 5])))))
     LEFT JOIN kaveribck.partyinfo_vrnmissing p2 ON (((p2.linkpartyid = p1.partyid) AND (p2.partytypeid = ANY (ARRAY[5])))))
     LEFT JOIN kaveri.salutationmaster s ON ((p.salutationid = s.salutationid)))
     LEFT JOIN kaveri.salutationmaster s1 ON ((p1.salutationid = s1.salutationid)))
     LEFT JOIN kaveri.salutationmaster s2 ON ((p2.salutationid = s2.salutationid)))
     LEFT JOIN kaveri.mas_idprooftypes m1 ON ((p.idprooftypeid = m1.idprooftypeid)))
     LEFT JOIN kaveri.mas_idprooftypes m2 ON ((p1.idprooftypeid = m2.idprooftypeid)))
     LEFT JOIN kaveri.mas_idprooftypes m3 ON ((p2.idprooftypeid = m3.idprooftypeid)))
  WHERE ((p.applicationnumber IS NOT NULL) AND (p.partytypeid = ANY (ARRAY[1, 2])) AND ((p.section88exemption IS NULL) OR (p.section88exemption = false)) AND (p.isprivateattendance = false) AND (p.isduplicate IS NOT TRUE) AND (p1.isduplicate IS NOT TRUE) AND (p2.isduplicate IS NOT TRUE));


ALTER TABLE kaveri.vw_fetch_aadharhash_excel OWNER TO postgres;

--
-- Name: vw_fetch_add_order_details; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_add_order_details AS
 SELECT a.orderid,
    to_char(a.orderdate, 'YYYY/MM/DD'::text) AS orderdate,
    a.relativepath,
    a.absolutefilepath,
    d.districtnamee,
    a.documentid,
    a.statuscode,
    a.correctionnote,
    a.documentrescan,
    b.note_enteredpart,
    a.rescandocument,
    b.propertyid,
    b.noteid
   FROM ((kaveri.dec_drordermaster a
     LEFT JOIN kaveri.dec_drpndnote b ON ((a.orderid = b.orderid)))
     LEFT JOIN kaveri.districtmaster d ON ((a.districtcode = d.districtcode)))
  ORDER BY a.orderid DESC;


ALTER TABLE kaveri.vw_fetch_add_order_details OWNER TO postgres;

--
-- Name: vw_fetch_cc; Type: VIEW; Schema: kaveri; Owner: csgadmin
--

CREATE VIEW kaveri.vw_fetch_cc AS
 SELECT DISTINCT dm.documentid,
    s.districtcode,
    d.districtnamee,
    s.srocode,
    s.sronamee,
    dm.documentnumber,
    (
        CASE
            WHEN ((to_char(dm.registrationdatetime, 'MM'::text))::bigint > 3) THEN (((to_char(dm.registrationdatetime, 'YYYY'::text))::bigint || '-'::text) || to_char((dm.registrationdatetime + '1 year'::interval), 'YY'::text))
            ELSE ((((to_char(dm.registrationdatetime, 'YYYY'::text))::bigint - 1) || '-'::text) || to_char(dm.registrationdatetime, 'YY'::text))
        END)::character varying AS yearofregistration,
    dm.bookid,
    dm.pagecount,
    dm.uploaddocdeedpath,
    r.referencetext,
    r.documenttypeid,
    doc.documenttypedesc AS documenttype
   FROM ((((kaveri.documentmaster dm
     JOIN kaveri.sromaster s ON ((s.srocode = dm.srocode)))
     JOIN kaveri.districtmaster d ON ((d.districtcode = s.districtcode)))
     LEFT JOIN kaveri.referencemaster r ON ((r.documentid = dm.documentid)))
     LEFT JOIN kaveri.documenttypemaster doc ON ((r.documenttypeid = doc.documenttypeid)))
  WHERE (dm.isregistrationcompleted = true);


ALTER TABLE kaveri.vw_fetch_cc OWNER TO csgadmin;

--
-- Name: vw_fetch_cc_sfda_dashboard; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_cc_sfda_dashboard AS
 SELECT ad.applicationnumber AS applicationnum,
    COALESCE((ad.applicationdate)::date, (ad.applicationstartdate)::date) AS applicationdate,
    COALESCE(ad.srocode, au.kaverisrocode) AS srocode,
    ad.applicationtypeid,
    sm.servicename,
    ad.currentstatus,
    wm.wrkflowstatusnamee,
    ad.sfdaid,
    usr.username,
    au.gscno
   FROM ((((kaveri.applicantapplicationdetails ad
     JOIN kaveri.cc_applicationdetails au ON (((au.applicationnumber)::text = (ad.applicationnumber)::text)))
     LEFT JOIN kaveri.vw_department_users usr ON ((usr.userid = ad.sfdaid)))
     LEFT JOIN kaveri.wrkflowmaster wm ON (((wm.wrkflowstatusid)::text = (ad.currentstatus)::text)))
     LEFT JOIN kaveri.servicesmaster sm ON ((ad.applicationtypeid = sm.serviceid)))
  WHERE ((ad.applicationtypeid = 12) AND ((ad.currentstatus)::text = ANY (ARRAY['CC105'::text, 'CC106'::text, 'CC108'::text])));


ALTER TABLE kaveri.vw_fetch_cc_sfda_dashboard OWNER TO postgres;

--
-- Name: vw_fetch_cc_sro_dashboard; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_cc_sro_dashboard AS
 SELECT ad.applicationnumber AS applicationnum,
    COALESCE((ad.applicationdate)::date, (ad.applicationstartdate)::date) AS applicationdate,
    COALESCE(ad.srocode, au.kaverisrocode) AS srocode,
    ad.applicationtypeid,
    sm.servicename,
    ad.currentstatus,
    wm.wrkflowstatusnamee,
    ad.sfdaid,
    ad.deoid,
    usr.username,
    au.isprior2003,
    au.gscno
   FROM ((((kaveri.applicantapplicationdetails ad
     JOIN kaveri.cc_applicationdetails au ON (((au.applicationnumber)::text = (ad.applicationnumber)::text)))
     LEFT JOIN kaveri.vw_department_users usr ON ((usr.userid = ad.sfdaid)))
     LEFT JOIN kaveri.wrkflowmaster wm ON (((wm.wrkflowstatusid)::text = (ad.currentstatus)::text)))
     LEFT JOIN kaveri.servicesmaster sm ON ((ad.applicationtypeid = sm.serviceid)))
  WHERE ((ad.applicationtypeid = 12) AND ((ad.currentstatus)::text <> ALL (ARRAY['CC101'::text, 'CC102'::text, 'CC103'::text, 'CC109'::text, 'CC110'::text, 'CC115'::text])));


ALTER TABLE kaveri.vw_fetch_cc_sro_dashboard OWNER TO postgres;

--
-- Name: vw_fetch_cc_sro_dashboard_dept; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_cc_sro_dashboard_dept AS
 SELECT ad.applicationnumber AS applicationnum,
    COALESCE((ad.applicationdate)::date, (ad.applicationstartdate)::date) AS applicationdate,
    au.kaverisrocode AS srocode,
    ad.applicationtypeid,
    'CC Application'::text AS servicename,
    ad.currentstatus,
    wm.wrkflowstatusnamee,
    ad.sfdaid,
    usr.username,
    r.articlenamee,
    au.reason,
    au.isappliedbydept
   FROM ((((kaveri.applicantapplicationdetails ad
     JOIN kaveri.cc_applicationdetails au ON (((au.applicationnumber)::text = (ad.applicationnumber)::text)))
     LEFT JOIN kaveri.registrationarticles r ON ((ad.regarticlecode = r.regarticlecode)))
     LEFT JOIN kaveri.vw_department_users usr ON ((usr.userid = ad.sfdaid)))
     LEFT JOIN kaveri.wrkflowmaster wm ON (((wm.wrkflowstatusid)::text = (ad.currentstatus)::text)))
  WHERE (((ad.currentstatus)::text <> ALL (ARRAY[('CC101'::character varying)::text, ('CC102'::character varying)::text, ('CC103'::character varying)::text])) AND (au.isappliedbydept = true));


ALTER TABLE kaveri.vw_fetch_cc_sro_dashboard_dept OWNER TO postgres;

--
-- Name: vw_fetch_court_order_details; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_court_order_details AS
 SELECT DISTINCT x.applicationnumber,
    x.propertyid,
    x.sro,
    x.court_order_number,
    x.injuction_or_stay_flag,
    x.survey_no,
    x.currentnumber,
    x.oldnumber,
    x.eastboundary,
    x.westboundary,
    x.northboundary,
    x.southboundary,
    x.area,
    x.description AS court_order_details,
    x.propertydescription AS description,
    x.currentpropertytypeid,
    x.oldpropertytypeid,
    x.hissa_no,
    x.propertytypename,
    x.issuingauthority,
    x.issueddate,
    x.villagecode
   FROM ( SELECT bpn.id,
            sm.sronamee AS sro,
            bpn.injuction_or_stay_flag,
            bpn.orderid,
            bpn.currentpropertytypeid,
            bpn.currentnumber,
            bpn.oldpropertytypeid,
            bpn.oldnumber,
            bpn.description AS description1,
            bpn.survey_no,
            bpn.surnoc,
            bpn.hissa_no,
            bp.propertydescription,
            bp.isagriculturalproperty,
            bp.eastboundary,
            bp.northboundary,
            bp.westboundary,
            bp.southboundary,
            bp.area,
            bp.measurementunit,
            co.ordernumber AS court_order_number,
            co.description,
            co.orderentrydatetime,
            co.iscancelled,
            co.reasonofcancellation,
            pm.applicationnumber,
            pm.propertyid,
            pt.typenameenglish AS propertytypename,
            co.issuingauthority,
            co.issueddate,
            bp.villagecode
           FROM ((((((kaveri.courtorders co
             JOIN kaveri.bannedpropertynumbers bpn ON (((co.courtorderid = bpn.orderid) AND (co.srocode = bpn.srocode))))
             JOIN kaveri.bannedproperties bp ON (((bpn.orderid = bp.orderid) AND (bpn.srocode = bp.srocode) AND (bp.courtpropertyid = bpn.propertyid))))
             JOIN kaveri.propertynumberdetails pnd ON (((pnd.currentpropertytypeid = bpn.currentpropertytypeid) AND
                CASE
                    WHEN (pnd.currentpropertytypeid <> 1) THEN ((bpn.currentnumber)::text = (pnd.currentnumber)::text)
                    ELSE ((bpn.survey_no = pnd.survey_no) AND ((bpn.hissa_no)::text = (pnd.hissa_no)::text))
                END)))
             JOIN kaveri.propertymaster pm ON (((pm.propertyid = pnd.propertyid) AND (pm.villagecode = bp.villagecode))))
             JOIN kaveri.propertynotypemaster pt ON ((pnd.currentpropertytypeid = pt.propertytypeid)))
             JOIN kaveri.sromaster sm ON ((sm.srocode = co.srocode)))
          WHERE ((co.isinforce = true) AND (co.iscancelled = false) AND (pnd.currentnumber IS NOT NULL) AND ((pnd.currentnumber)::text <> '0'::text))) x;


ALTER TABLE kaveri.vw_fetch_court_order_details OWNER TO postgres;

--
-- Name: vw_fetch_court_order_fruit; Type: VIEW; Schema: kaveri; Owner: csgadmin
--

CREATE VIEW kaveri.vw_fetch_court_order_fruit AS
 SELECT co.ordernumber,
    bpn.srocode,
    co.issuingauthority,
    co.issueddate,
    co.description AS orderdescription,
    bp.propertydescription,
    bp.villagecode,
    ((bpn.survey_no || '/'::text) || (bpn.hissa_no)::text) AS currentnumber,
    bpn.survey_no,
    bpn.hissa_no
   FROM ((kaveri.bannedpropertynumbers bpn
     JOIN kaveri.bannedproperties bp ON ((bp.courtpropertyid = bpn.propertyid)))
     JOIN kaveri.courtorders co ON (((bpn.srocode = co.srocode) AND (bpn.orderid = co.courtorderid) AND (co.isinforce = true))))
  WHERE (bpn.currentpropertytypeid = 1);


ALTER TABLE kaveri.vw_fetch_court_order_fruit OWNER TO csgadmin;

--
-- Name: vw_fetch_crossref_dashboard; Type: VIEW; Schema: kaveri; Owner: csgadmin
--

CREATE VIEW kaveri.vw_fetch_crossref_dashboard AS
 SELECT dm.documentid,
    dm.srocode,
    dm.regarticlecode,
    ra.articlenamee AS natureofdocument,
    dm.finalregistrationnumber,
    (dm.registrationdatetime)::date AS registrationdatetime,
    dm.bookid,
    bm.booknameenglish AS bookname,
    dm.documentnumber,
    "right"((dm.finalregistrationnumber)::text, 7) AS finyear,
    dm.olddocreference
   FROM ((kaveri.documentmaster dm
     JOIN kaveri.registrationarticles ra ON ((dm.regarticlecode = ra.regarticlecode)))
     JOIN kaveri.booktypemaster bm ON ((bm.bookid = dm.bookid)))
  WHERE ((dm.regarticlecode = ANY (ARRAY[32, 33, 48, 83, 98, 104, 105])) AND (NOT ((COALESCE(dm.documentid, (0)::bigint), COALESCE(dm.srocode, 0), COALESCE(dm.bookid, 0)) IN ( SELECT COALESCE(referencemaster.documentid, (0)::bigint) AS "coalesce",
            COALESCE(referencemaster.srocode, (0)::bigint) AS "coalesce",
            COALESCE(referencemaster.bookid, 0) AS "coalesce"
           FROM kaveri.referencemaster))));


ALTER TABLE kaveri.vw_fetch_crossref_dashboard OWNER TO csgadmin;

--
-- Name: vw_fetch_dept_doc_details; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_dept_doc_details AS
 SELECT DISTINCT dm.applicationnumber,
    ad.srocode,
    ad.applicationtypeid,
    dm.finalregistrationnumber,
    dm.executiondatetime,
    dm.pendingdocumentnumber,
    bm.printablename AS book,
    dm.registrationdatetime,
    pm.sronoofscanpages AS noofscnpages,
    svm.servicename AS applicationtype,
    sm.sronamee AS sroname,
    pm.propertyid,
    dm.presentdatetime,
    dm.documentid,
    sm.sronamek,
    md.isbefore2003
   FROM ((((((kaveri.documentmaster dm
     JOIN kaveri.sromaster sm ON ((sm.srocode = dm.srocode)))
     JOIN kaveri.applicantapplicationdetails ad ON (((ad.applicationnumber)::text = (dm.applicationnumber)::text)))
     LEFT JOIN kaveri.minutebook_data md ON (((md.applicationnumber)::text = (ad.applicationnumber)::text)))
     JOIN kaveri.propertymaster pm ON ((pm.documentid = dm.documentid)))
     JOIN kaveri.servicesmaster svm ON ((svm.serviceid = ad.applicationtypeid)))
     LEFT JOIN kaveri.booktypemaster bm ON ((bm.bookid = dm.bookid)));


ALTER TABLE kaveri.vw_fetch_dept_doc_details OWNER TO postgres;

--
-- Name: vw_fetch_dept_group; Type: VIEW; Schema: kaveri; Owner: csgadmin
--

CREATE VIEW kaveri.vw_fetch_dept_group AS
 SELECT dug.groupid,
    dug.groupname,
    dug.groupdesc,
    dug.isactive,
    ( SELECT array_to_json(array_agg(row_to_json(tmp.*))) AS array_to_json
           FROM ( SELECT grm.rollid,
                    d.designame
                   FROM (kaveri.group_roll_mapping grm
                     JOIN kaveri.desigmaster d ON ((grm.rollid = d.designationid)))
                  WHERE (grm.groupid = dug.groupid)) tmp) AS roleinfo
   FROM kaveri.deptmentusergroup dug;


ALTER TABLE kaveri.vw_fetch_dept_group OWNER TO csgadmin;

--
-- Name: vw_fetch_deptuser_lkp; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_deptuser_lkp AS
 SELECT usr.userid,
    usr.srocode,
    usr.loginname,
    usr.username,
    usr.mobile,
    usr.designationid,
    usr.designame,
    true AS isdefaultrole,
    count(ad.applicationnumber) AS appcount
   FROM (((kaveri.vw_department_users usr
     JOIN kaveri.departmentusers d ON ((d.userid = usr.userid)))
     JOIN kaveri.mas_officemaster mo ON (((mo.officeid = d.officeid) AND (mo.officetypeid = 3))))
     LEFT JOIN kaveri.applicantapplicationdetails ad ON (((usr.userid)::text = ad.assignedto)))
  GROUP BY usr.userid, usr.srocode, usr.loginname, usr.username, usr.mobile, usr.designationid, usr.designame;


ALTER TABLE kaveri.vw_fetch_deptuser_lkp OWNER TO postgres;

--
-- Name: vw_fetch_document_search_parameters; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_document_search_parameters AS
 SELECT b.srocode,
    ( SELECT max(a.noofscanpages) AS max
           FROM kaveri.propertymaster a
          WHERE (a.documentid = b.documentid)) AS noofscanpages,
    c.sronamee,
    b.documentid,
    b.documentnumber,
    b.bookid,
    d.booknameenglish AS booktype,
    "right"((b.finalregistrationnumber)::text, 7) AS financial_year
   FROM ((kaveri.documentmaster b
     JOIN kaveri.sromaster c ON ((b.srocode = c.srocode)))
     JOIN kaveri.booktypemaster d ON ((b.bookid = d.bookid)));


ALTER TABLE kaveri.vw_fetch_document_search_parameters OWNER TO postgres;

--
-- Name: vw_fetch_document_search_parameters_b; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_document_search_parameters_b AS
 SELECT a.propertyid,
    a.srocode,
    a.noofscanpages,
    c.sronamee,
    b.documentid,
    b.documentnumber,
    b.bookid,
    d.booknameenglish AS booktype,
        CASE
            WHEN (date_part('month'::text, CURRENT_DATE) <= (3)::double precision) THEN ((to_char((CURRENT_DATE + '-1 years'::interval), 'YYYY'::text) || '-'::text) || to_char((CURRENT_DATE)::timestamp with time zone, 'YY'::text))
            ELSE ((to_char((CURRENT_DATE)::timestamp with time zone, 'YYYY'::text) || '-'::text) || to_char((CURRENT_DATE + '1 year'::interval), 'YY'::text))
        END AS financial_year
   FROM (((kaveri.documentmaster b
     JOIN kaveri.propertymaster a ON ((b.documentid = a.documentid)))
     JOIN kaveri.sromaster c ON ((b.srocode = c.srocode)))
     JOIN kaveri.booktypemaster d ON ((b.bookid = d.bookid)));


ALTER TABLE kaveri.vw_fetch_document_search_parameters_b OWNER TO postgres;

--
-- Name: vw_fetch_documentdetails; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_documentdetails AS
 SELECT d.applicationnumber,
    s.sronamee,
    p.firstname,
    aa.applicationtype,
    d.bookid,
    d.documentid,
    amee.deptreferencecode,
    d.finalregistrationnumber,
    d.registrationdatetime,
    s.sronamek,
    sl.descriptione
   FROM ((((((kaveri.applicantapplicationdetails a
     JOIN kaveri.partyinfo p ON ((((a.applicationnumber)::text = (p.applicationnumber)::text) AND (p.ispresenter = true))))
     JOIN kaveri.salutationmaster sl ON ((sl.salutationid = p.salutationid)))
     JOIN kaveri.documentmaster d ON (((a.applicationnumber)::text = (d.applicationnumber)::text)))
     JOIN LATERAL ( SELECT ark.deptreferencecode
           FROM (kaveri.ams_reg_epaymenttransdetails ame
             JOIN kaveri.ams_reg_epaymentbankackdetails ark ON ((((ame.deptreferencecode)::text = (ark.deptreferencecode)::text) AND ((ark.paymentstatuscode)::text = ANY (ARRAY[('10700066'::character varying)::text, ('10700072'::character varying)::text])))))
          WHERE (((ame.applicationnumber)::text = (d.applicationnumber)::text) AND (ame.isdelete = false))
         LIMIT 1) amee ON (true))
     JOIN kaveri.sromaster s ON ((a.srocode = s.srocode)))
     JOIN kaveri.applicationtypemaster aa ON ((aa.applicationtypeid = a.applicationtypeid)));


ALTER TABLE kaveri.vw_fetch_documentdetails OWNER TO postgres;

--
-- Name: vw_fetch_dr_order_details; Type: VIEW; Schema: kaveri; Owner: csgadmin
--

CREATE VIEW kaveri.vw_fetch_dr_order_details AS
 SELECT a.orderid,
    a.districtcode,
    b.districtnamee AS droname,
    a.srocode,
    c.sronamee,
    g.loginname AS orderuploadedby,
    a.ordernumber AS drordernumber,
    a.orderdate,
    d.note_preparedpart AS note,
    e.finalregistrationnumber AS registrationno,
        CASE
            WHEN (a.statuscode = 4) THEN 'Finalized'::text
            ELSE 'Pending'::text
        END AS status,
    a.statuscode
   FROM ((((((kaveri.dec_drordermaster a
     JOIN kaveri.districtmaster b ON ((a.districtcode = b.districtcode)))
     JOIN kaveri.sromaster c ON ((a.srocode = c.srocode)))
     JOIN kaveri.dec_drpndnote d ON ((a.orderid = d.orderid)))
     JOIN kaveri.documentmaster e ON ((a.documentid = e.documentid)))
     LEFT JOIN kaveri.ecpropertysearchkeyvalues f ON ((a.orderid = f.orderid)))
     JOIN kaveri.departmentusers g ON ((a.userid = g.userid)))
  ORDER BY a.orderid DESC;


ALTER TABLE kaveri.vw_fetch_dr_order_details OWNER TO csgadmin;

--
-- Name: vw_fetch_droffice; Type: VIEW; Schema: kaveri; Owner: csgadmin
--

CREATE VIEW kaveri.vw_fetch_droffice AS
 SELECT mas_officemaster.officeid,
    mas_officemaster.officename AS igrofficename,
    mas_officemaster.districtid,
    mas_officemaster.kavericode
   FROM kaveri.mas_officemaster
  WHERE (mas_officemaster.officetypeid = 2);


ALTER TABLE kaveri.vw_fetch_droffice OWNER TO csgadmin;

--
-- Name: vw_fetch_ec; Type: VIEW; Schema: kaveri; Owner: raghavendrap
--

CREATE VIEW kaveri.vw_fetch_ec AS
 SELECT DISTINCT pi.partyid,
    pm.propertyid,
    dm.documentid,
    dm.srocode,
    dm.stamp5datetime AS executiondate,
    ra.articlenamee,
    pm.marketvalue,
    pm.consideration,
    string_agg(
        CASE
            WHEN (pi.partytypeid = 1) THEN concat(pi.firstname, pi.middlename, pi.lastname)
            ELSE NULL::text
        END, ', '::text) AS claimant,
    string_agg(
        CASE
            WHEN (pi.partytypeid = 2) THEN concat(pi.firstname, pi.middlename, pi.lastname)
            ELSE NULL::text
        END, ', '::text) AS executant,
    dm.cdnumber,
    dm.pagecount,
    dm.finalregistrationnumber AS documentreference,
    ps.description,
    pn.currentpropertytypeid,
    pn.currentnumber,
    pm.applicationnumber,
    pm.eastboundary AS east,
    pm.westboundary AS west,
    pm.northboundary AS north,
    pm.southboundary AS south,
    ps.easttowest,
    ps.northtosouth,
    pn.currentnumber AS aptno_new,
    pn.oldnumber AS oldno,
    pm.totalarea AS area,
    pm.villagecode,
    v.villagenamee,
    v.hoblicode,
    h.hoblinamee,
    pi.address,
    r.referencetext
   FROM ((((((((kaveri.propertymaster pm
     JOIN kaveri.documentmaster dm ON (((pm.regsrocode = dm.srocode) AND (pm.documentid = dm.documentid))))
     JOIN kaveri.propertyschedules ps ON (((ps.srocode = pm.regsrocode) AND (ps.propertyid = pm.propertyid))))
     JOIN kaveri.registrationarticles ra ON ((ra.regarticlecode = dm.regarticlecode)))
     JOIN kaveri.partyinfo pi ON (((pi.srocode = dm.srocode) AND (pi.documentid = dm.documentid))))
     JOIN kaveri.propertynumberdetails pn ON (((pn.propertyid = pm.propertyid) AND (pn.srocode = pm.regsrocode))))
     JOIN kaveri.villagemaster v ON ((v.villagecode = pm.villagecode)))
     JOIN kaveri.hoblimaster h ON ((h.hoblicode = v.hoblicode)))
     LEFT JOIN kaveri.referencemaster r ON ((r.documentid = dm.documentid)))
  GROUP BY pi.partyid, pm.propertyid, dm.documentid, dm.srocode, dm.stamp5datetime, ra.articlenamee, pm.marketvalue, pm.consideration, dm.cdnumber, dm.pagecount, dm.finalregistrationnumber, ps.description, pm.villagecode, pn.currentpropertytypeid, pn.currentnumber, pm.applicationnumber, pm.eastboundary, pm.westboundary, pm.northboundary, pm.southboundary, ps.easttowest, ps.northtosouth, pn.oldnumber, pm.totalarea, v.villagenamee, v.hoblicode, h.hoblinamee, pi.address, r.referencetext;


ALTER TABLE kaveri.vw_fetch_ec OWNER TO raghavendrap;

--
-- Name: vw_fetch_ec_sfda_dashboard; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_ec_sfda_dashboard AS
 SELECT ad.applicationnumber AS applicationnum,
    COALESCE((ad.applicationdate)::date, (ad.applicationstartdate)::date) AS applicationdate,
    COALESCE(ad.srocode, (au.kaverisrocode)::integer) AS srocode,
    ad.applicationtypeid,
    sm.servicename,
    ad.currentstatus,
    wm.wrkflowstatusnamee,
    ad.sfdaid,
    usr.username,
    au.gscno,
    ff.submitteddate
   FROM (((((kaveri.applicantapplicationdetails ad
     JOIN kaveri.ec_applicationdetails au ON (((au.applicationnumber)::text = (ad.applicationnumber)::text)))
     LEFT JOIN kaveri.vw_department_users usr ON ((usr.userid = ad.sfdaid)))
     LEFT JOIN kaveri.wrkflowmaster wm ON (((wm.wrkflowstatusid)::text = (ad.currentstatus)::text)))
     LEFT JOIN kaveri.servicesmaster sm ON ((ad.applicationtypeid = sm.serviceid)))
     LEFT JOIN ( SELECT aa.applicationnumber,
            max(aa.crtdt) AS submitteddate
           FROM kaveri.applicationaudit aa
          WHERE ((aa.wrkflowstatusid)::text = 'CE105'::text)
          GROUP BY aa.applicationnumber) ff ON (((ad.applicationnumber)::text = (ff.applicationnumber)::text)))
  WHERE ((ad.applicationtypeid = 13) AND ((ad.currentstatus)::text = ANY (ARRAY['CE105'::text, 'CE106'::text, 'CE107'::text, 'CE108'::text, 'CE139'::text])));


ALTER TABLE kaveri.vw_fetch_ec_sfda_dashboard OWNER TO postgres;

--
-- Name: vw_fetch_ec_sro_dashboard; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_ec_sro_dashboard AS
 SELECT ad.applicationnumber AS applicationnum,
    COALESCE((ad.applicationdate)::date, (ad.applicationstartdate)::date) AS applicationdate,
    au.kaverisrocode AS srocode,
    ad.applicationtypeid,
    'EC Application'::text AS servicename,
    ad.currentstatus,
    wm.wrkflowstatusnamee,
    ad.sfdaid,
    usr.username,
    au.isbefore2004,
    ad.deoid,
    au.gscno,
    ( SELECT max(ad_1.crtdt) AS submitteddate
           FROM kaveri.applicationaudit ad_1
          WHERE (((au.applicationnumber)::text = (ad_1.applicationnumber)::text) AND ((ad_1.wrkflowstatusid)::text = 'CE105'::text))) AS submitteddate
   FROM (((kaveri.ec_applicationdetails au
     JOIN kaveri.applicantapplicationdetails ad ON (((au.applicationnumber)::text = (ad.applicationnumber)::text)))
     LEFT JOIN kaveri.vw_department_users usr ON ((usr.userid = ad.sfdaid)))
     LEFT JOIN kaveri.wrkflowmaster wm ON (((wm.wrkflowstatusid)::text = (ad.currentstatus)::text)))
  WHERE ((ad.currentstatus)::text <> ALL (ARRAY[('CE101'::character varying)::text, ('CE102'::character varying)::text, ('CE103'::character varying)::text, ('CE110'::character varying)::text, ('CE115'::character varying)::text]));


ALTER TABLE kaveri.vw_fetch_ec_sro_dashboard OWNER TO postgres;

