          WHERE (((au.applicationnumber)::text = (ad_1.applicationnumber)::text) AND ((ad_1.wrkflowstatusid)::text = 'CE105'::text))) AS submitteddate
   FROM (((kaveri.ec_applicationdetails au
     JOIN kaveri.applicantapplicationdetails ad ON (((au.applicationnumber)::text = (ad.applicationnumber)::text)))
     LEFT JOIN kaveri.vw_department_users usr ON ((usr.userid = ad.sfdaid)))
     LEFT JOIN kaveri.wrkflowmaster wm ON (((wm.wrkflowstatusid)::text = (ad.currentstatus)::text)))
  WHERE ((ad.currentstatus)::text <> ALL (ARRAY[('CE101'::character varying)::text, ('CE102'::character varying)::text, ('CE103'::character varying)::text, ('CE110'::character varying)::text]));


ALTER TABLE kaveri.vw_fetch_ec_sro_dashboard_bck OWNER TO postgres;

