    ff.submitteddate
   FROM (((((kaveri.applicantapplicationdetails ad
     JOIN kaveri.ec_applicationdetails au ON (((au.applicationnumber)::text = (ad.applicationnumber)::text)))
     LEFT JOIN kaveri.registrationarticles r ON ((ad.regarticlecode = r.regarticlecode)))
     LEFT JOIN kaveri.vw_department_users usr ON ((usr.userid = ad.sfdaid)))
     LEFT JOIN kaveri.wrkflowmaster wm ON (((wm.wrkflowstatusid)::text = (ad.currentstatus)::text)))
     LEFT JOIN ( SELECT aa.applicationnumber,
            max(aa.crtdt) AS submitteddate
           FROM kaveri.applicationaudit aa
          WHERE ((aa.wrkflowstatusid)::text = 'CE105'::text)
          GROUP BY aa.applicationnumber) ff ON (((ad.applicationnumber)::text = (ff.applicationnumber)::text)))
  WHERE (((ad.currentstatus)::text <> ALL (ARRAY[('CE101'::character varying)::text, ('CE102'::character varying)::text, ('CE103'::character varying)::text])) AND (au.isappliedbydept = true));


ALTER TABLE kaveri.vw_fetch_ec_sro_dashboard_dept_bck_022026 OWNER TO postgres;

--
-- Name: vw_fetch_ec_sro_dashboard_optimize; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_ec_sro_dashboard_optimize AS
 SELECT ad.applicationnumber AS applicationnum,
    COALESCE((ad.applicationdate)::date, (ad.applicationstartdate)::date) AS applicationdate,
    au.kaverisrocode AS srocode,
    ad.applicationtypeid,
    'EC Application'::text AS servicename,
    ad.currentstatus,
    wm.wrkflowstatusnamee,
    ad.sfdaid,
    usr.username,
    au.isbefore2004,
    ad.deoid
   FROM (((kaveri.ec_applicationdetails au
     JOIN kaveri.applicantapplicationdetails ad ON (((au.applicationnumber)::text = (ad.applicationnumber)::text)))
     LEFT JOIN kaveri.vw_department_users usr ON ((usr.userid = ad.sfdaid)))
     JOIN kaveri.wrkflowmaster wm ON (((wm.wrkflowstatusid)::text = (ad.currentstatus)::text)))
  WHERE ((ad.currentstatus)::text = ANY (ARRAY['CE104'::text, 'CE105'::text, 'CE106'::text, 'CE108'::text, 'CE107'::text, 'CE138'::text, 'CE140'::text, 'CE139'::text, 'CE111'::text, 'CE112'::text, 'CE113'::text, 'CE114'::text]));


ALTER TABLE kaveri.vw_fetch_ec_sro_dashboard_optimize OWNER TO postgres;

