    a.fingerverificationstatusid,
    a.ispartofrtc,
    a.landcode,
    a.mainownerno,
    a.ownerno,
    a.partypoa,
    a.photopath,
    a.poaadmission,
    a.poapresentation,
    a.primaryseller,
    a.profession,
    a.restriction,
    a.restrictiondescription,
    a.restrictiontype,
    a.section88exemption,
    a.thumbmatchfailedreasonid,
    a.thumbminutiae,
