--
-- Name: vw_fetch_list_choose_presenter; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_list_choose_presenter AS
 SELECT p.partyid AS linkpartyid,
    p.partytypeid AS linked_partytypeid,
    p.firstname AS linked_firstname,
    p1.partyid,
    p1.partytypeid,
    p1.firstname,
    p.isorganization,
        CASE
            WHEN ((p1.partytypeid = 4) AND (p2.firstname IS NOT NULL)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is rep. by minor guardian ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ', whose POA is ', s2.descriptione, p2.firstname, ' ', p2.middlename, ' ', p2.lastname)
            WHEN ((p1.partytypeid = 4) AND (p2.firstname IS NULL)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is rep. by minor guardian ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)
            WHEN ((p1.partytypeid = 5) AND (p.isorganization = true)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' POA by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ' is Rep. by ', p1.orgpoaauthsignfname, ' ', p1.orgpoaauthsignlname)
            WHEN ((p1.partytypeid = 5) AND (p.isorganization = false)) THEN concat(s1.descriptione, p1.firstname, ' is POA of ', s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
            WHEN ((p1.partytypeid = 9) AND (p.isorganization = true) AND (p2.firstname IS NOT NULL)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is Rep. by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ', whose POA is ', s2.descriptione, p2.firstname, ' ', p2.middlename, ' ', p2.lastname)
            WHEN ((p1.partytypeid = 9) AND (p.isorganization = true) AND (p2.firstname IS NULL)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is Rep. by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)
            WHEN ((p1.partytypeid IS NULL) AND (p.partytypeid = 1)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
            WHEN ((p1.partytypeid IS NULL) AND (p.partytypeid = 2)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
            ELSE NULL::text
        END AS fullname,
    p.applicationnumber,
        CASE
            WHEN ((p.isorganization = true) AND (p2.firstname IS NULL)) THEN p1.age
            WHEN ((p.isorganization = true) AND (p2.firstname IS NOT NULL)) THEN p2.age
            WHEN ((p.age)::text < '18'::text) THEN p1.age
            ELSE p.age
        END AS age,
        CASE
            WHEN ((p.isorganization = true) AND (p2.firstname IS NULL)) THEN p1.sex
            WHEN ((p.isorganization = true) AND (p2.firstname IS NOT NULL)) THEN p2.sex
            WHEN ((p.age)::text < '18'::text) THEN p1.sex
            ELSE p.sex
        END AS sex,
        CASE
            WHEN ((p.isorganization = true) AND (p2.firstname IS NULL)) THEN concat_ws(' '::text, ((((((
            CASE
                WHEN (p1.housenumber IS NULL) THEN ''::text
                ELSE p1.housenumber
            END || ', '::text) || (p1.address)::text) || ', '::text) || kaveri.fn_fetch_address_village((p1.talukcode)::bigint)) || ' - '::text) || p1.pin))
            WHEN ((p.isorganization = true) AND (p2.firstname IS NOT NULL)) THEN concat_ws(' '::text, ((((((
            CASE
                WHEN (p2.housenumber IS NULL) THEN ''::text
                ELSE p2.housenumber
            END || ', '::text) || (p2.address)::text) || ', '::text) || kaveri.fn_fetch_address_village((p2.talukcode)::bigint)) || ' - '::text) || p2.pin))
            WHEN ((p.age)::text < '18'::text) THEN concat_ws(' '::text, ((((((
            CASE
                WHEN (p.housenumber IS NULL) THEN ''::text
                ELSE p.housenumber
            END || ', '::text) || (p.address)::text) || ', '::text) || kaveri.fn_fetch_address_village((p.talukcode)::bigint)) || ' - '::text) || p.pin))
            ELSE concat_ws(' '::text, ((((((
            CASE
                WHEN (p.housenumber IS NULL) THEN ''::text
                ELSE p.housenumber
            END || ', '::text) || (p.address)::text) || ', '::text) || kaveri.fn_fetch_address_village((p.talukcode)::bigint)) || ' - '::text) || p.pin))
        END AS address,
        CASE
            WHEN (p.idprooftypeid IS NOT NULL) THEN m1.description
            WHEN (p1.idprooftypeid IS NOT NULL) THEN m2.description
            WHEN (p2.idprooftypeid IS NOT NULL) THEN m3.description
            WHEN (p.partyid IS NOT NULL) THEN m1.description
            WHEN (p1.partyid IS NOT NULL) THEN m2.description
            WHEN (p2.partyid IS NOT NULL) THEN m3.description
            ELSE NULL::character varying
        END AS descr,
        CASE
            WHEN ((p.isorganization = true) AND (p.firstname IS NULL)) THEN p.pan
            WHEN ((p.isorganization = true) AND (p.firstname IS NOT NULL)) THEN p.pan
            WHEN (((p.age)::text < '18'::text) AND (p.pan IS NULL)) THEN p1.pan
            WHEN (((p.age)::text < '18'::text) AND (p1.pan IS NULL)) THEN p2.pan
            ELSE p.pan
        END AS pan,
        CASE
            WHEN ((p.isorganization = true) AND (p2.firstname IS NULL)) THEN p1.profession
            WHEN ((p.isorganization = true) AND (p2.firstname IS NOT NULL)) THEN p2.profession
            WHEN ((p.age)::text < '18'::text) THEN p1.profession
            ELSE p.profession
        END AS profession,
    p.isexecutor,
    p.ispresenter,
    p1.isduplicate,
    p1.duplicatepartyid
   FROM ((((((((kaveri.partyinfo p
     LEFT JOIN kaveri.partyinfo p1 ON (((p.partyid = p1.linkpartyid) AND (p1.partytypeid = ANY (ARRAY[9, 4, 5])))))
     LEFT JOIN kaveri.partyinfo p2 ON (((p2.linkpartyid = p1.partyid) AND (p2.partytypeid = ANY (ARRAY[5])))))
     LEFT JOIN kaveri.salutationmaster s ON ((p.salutationid = s.salutationid)))
     LEFT JOIN kaveri.salutationmaster s1 ON ((p1.salutationid = s1.salutationid)))
     LEFT JOIN kaveri.salutationmaster s2 ON ((p2.salutationid = s2.salutationid)))
     LEFT JOIN kaveri.mas_idprooftypes m1 ON ((p.idprooftypeid = m1.idprooftypeid)))
     LEFT JOIN kaveri.mas_idprooftypes m2 ON ((p1.idprooftypeid = m2.idprooftypeid)))
     LEFT JOIN kaveri.mas_idprooftypes m3 ON ((p2.idprooftypeid = m3.idprooftypeid)))
  WHERE ((p.partytypeid = ANY (ARRAY[1, 2])) AND ((p.section88exemption IS NULL) OR (p.section88exemption = false)) AND (p.isprivateattendance = false) AND (p.isduplicate IS NOT TRUE) AND (p.applicationnumber IS NOT NULL));


ALTER TABLE kaveri.vw_fetch_list_choose_presenter OWNER TO postgres;

--
-- Name: vw_fetch_marriage; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_marriage AS
 SELECT ( SELECT d.districtcode
           FROM kaveri.districtmaster d
          WHERE (d.districtcode IN ( SELECT s.districtcode
                   FROM kaveri.sromaster))) AS districtcode,
    ( SELECT d.districtnamee
           FROM kaveri.districtmaster d
          WHERE (d.districtcode IN ( SELECT s.districtcode
                   FROM kaveri.sromaster))) AS districtnamee,
    m.regsrocode,
    s.sronamee,
    m.signedformpath AS uploaddocdeedpath,
    a.applicationtypeid AS documenttypeid,
    se.servicename AS documenttype,
    d2.marriagetypeid,
    d2.marriagetype,
    m.documentnumber,
    (
        CASE
            WHEN ((to_char(m.dateofregistration, 'MM'::text))::bigint > 3) THEN (((to_char(m.dateofregistration, 'YYYY'::text))::bigint || '-'::text) || to_char((m.dateofregistration + '1 year'::interval), 'YY'::text))
            ELSE ((((to_char(m.dateofregistration, 'YYYY'::text))::bigint - 1) || '-'::text) || to_char(m.dateofregistration, 'YY'::text))
        END)::character varying AS yearofregistration
   FROM ((((kaveri.marriageregistration m
     JOIN kaveri.applicantapplicationdetails a ON (((a.applicationnumber)::text = (m.applicationnumber)::text)))
     JOIN kaveri.servicesmaster se ON ((se.serviceid = a.applicationtypeid)))
     JOIN kaveri.sromaster s ON ((m.regsrocode = s.srocode)))
     JOIN kaveri.mas_marriagetype d2 ON ((m.marriagetypeid = d2.marriagetypeid)))
  WHERE (m.isregistraioncomplete = true);


ALTER TABLE kaveri.vw_fetch_marriage OWNER TO postgres;

--
-- Name: vw_fetch_marriage_reg_details; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_marriage_reg_details AS
 SELECT b.registrationid,
    a.applicationnumber,
    a.applicationtypeid,
    c.servicename AS applicationtype,
    b.dateofmarriage,
    b.regsrocode AS srocode,
    sr.sronamee AS sroname,
    b.drcode,
    b.marriagetypeid,
    mt.marriagetype AS marriagetypename,
    b.housebuildingname,
    b.streetaddr,
    b.statecode,
    fun.statenamee AS statename,
    fun.districtcode,
    fun.districtnamee AS districtname,
    fun.talukcode AS talukacode,
    fun.taluknamee AS talukname,
    fun.hoblicode,
    fun.hoblinamee AS hobliname,
    fun.villagecode,
    fun.villagenamee AS villagename,
    b.pincode,
    b.combinephotopath,
    b.bridephoto,
    b.bridegroomphoto,
    b.marriagemodeid
   FROM (((((kaveri.applicantapplicationdetails a
     JOIN kaveri.marriageregistration b ON (((a.applicationnumber)::text = (b.applicationnumber)::text)))
     JOIN kaveri.servicesmaster c ON (((a.applicationtypeid = c.serviceid) AND (c.serviceid = 4))))
     LEFT JOIN kaveri.mas_marriagetype mt ON ((mt.marriagetypeid = b.marriagetypeid)))
     LEFT JOIN kaveri.sromaster sr ON ((sr.srocode = b.regsrocode)))
     JOIN LATERAL kaveri.fn_fetch_marriage_lgdmaster1(b.statecode, b.districtcode, b.talukacode, b.hoblicode, (b.cityvillagecode)::bigint) fun(statecode, statenamee, districtcode, districtnamee, talukcode, taluknamee, hoblicode, hoblinamee, villagecode, villagenamee) ON ((b.statecode = fun.statecode)));


ALTER TABLE kaveri.vw_fetch_marriage_reg_details OWNER TO postgres;

--
-- Name: vw_fetch_marriage_srooffice; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_marriage_srooffice AS
 SELECT DISTINCT a.applicationnumber,
    a.srocode,
    a.sronamee,
    a.drcode,
    a.drname,
    a.sro_option
   FROM ( SELECT pd.applicationnumber,
            sm.srocode,
            sm.sronamee,
            sm.districtcode AS drcode,
            d.districtnamee AS drname,
            'BrideGroom_SRO'::text AS sro_option
           FROM (((kaveri.persondetails pd
             JOIN kaveri.villagemaster v ON ((v.villagecode = pd.percityvillagecode)))
             JOIN kaveri.sromaster sm ON ((v.srocode = sm.srocode)))
             JOIN kaveri.districtmaster d ON ((d.districtcode = sm.districtcode)))
          WHERE ((pd.sex)::text ~~ 'M%'::text)
        UNION ALL
         SELECT pd.applicationnumber,
            sm.srocode,
            sm.sronamee,
            sm.districtcode AS drcode,
            d.districtnamee AS drname,
            'BrideGroom_SRO_pre'::text AS sro_option
           FROM (((kaveri.persondetails pd
             JOIN kaveri.villagemaster v ON ((v.villagecode = pd.precityvillagecode)))
             JOIN kaveri.sromaster sm ON ((v.srocode = sm.srocode)))
             JOIN kaveri.districtmaster d ON ((d.districtcode = sm.districtcode)))
          WHERE ((pd.sex)::text ~~ 'M%'::text)
        UNION ALL
         SELECT pd.applicationnumber,
            sm.srocode,
            sm.sronamee,
            sm.districtcode AS drcode,
            d.districtnamee AS drname,
            'Bride_SRO'::text AS sro_option
           FROM (((kaveri.persondetails pd
             JOIN kaveri.villagemaster v ON ((v.villagecode = pd.percityvillagecode)))
             JOIN kaveri.sromaster sm ON ((v.srocode = sm.srocode)))
             JOIN kaveri.districtmaster d ON ((d.districtcode = sm.districtcode)))
          WHERE ((pd.sex)::text ~~ 'F%'::text)
        UNION ALL
         SELECT pd.applicationnumber,
            sm.srocode,
            sm.sronamee,
            sm.districtcode AS drcode,
            d.districtnamee AS drname,
            'Bride_SRO_pre'::text AS sro_option
           FROM (((kaveri.persondetails pd
             JOIN kaveri.villagemaster v ON ((v.villagecode = pd.precityvillagecode)))
             JOIN kaveri.sromaster sm ON ((v.srocode = sm.srocode)))
             JOIN kaveri.districtmaster d ON ((d.districtcode = sm.districtcode)))
          WHERE ((pd.sex)::text ~~ 'F%'::text)
        UNION ALL
         SELECT pd.applicationnumber,
            sm.srocode,
            sm.sronamee,
            sm.districtcode AS drcode,
            d.districtnamee AS drname,
            'Marriage_Place_SRO'::text AS sro_option
           FROM (((kaveri.marriageregistration pd
             JOIN kaveri.villagemaster v ON ((v.villagecode = pd.cityvillagecode)))
             JOIN kaveri.sromaster sm ON ((v.srocode = sm.srocode)))
             JOIN kaveri.districtmaster d ON ((d.districtcode = sm.districtcode)))) a;


ALTER TABLE kaveri.vw_fetch_marriage_srooffice OWNER TO postgres;

--
-- Name: vw_fetch_marriageapplications; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_marriageapplications AS
 SELECT a.applicationnumber,
    a.applicationstartdate AS applicationdate,
    a.applicationtypeid,
    b.servicename AS applicationtype,
    a.currentstatus,
    c.wrkflowstatusnamee AS status,
    a.assignedto AS sdafda
   FROM ((kaveri.applicantapplicationdetails a
     JOIN kaveri.servicesmaster b ON (((a.applicationtypeid = b.serviceid) AND (b.serviceid = 4))))
     JOIN kaveri.wrkflowmaster c ON (((c.wrkflowstatusid)::text = (a.currentstatus)::text)));


ALTER TABLE kaveri.vw_fetch_marriageapplications OWNER TO postgres;

--
-- Name: vw_fetch_marriagedetails; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_marriagedetails AS
 SELECT p.registrationid,
    p.applicationnumber,
    p.applicationtypeid,
    p.applicationtype,
    p.dateofmarriage,
    p.srocode,
    p.sroname,
    p.drcode,
    p.marriagetypeid,
    p.marriagetypename,
    p.housebuildingname,
    p.streetaddr,
    p.statecode,
    fun.statenamee AS statename,
    p.districtcode,
    fun.districtnamee AS districtname,
    p.talukacode,
    fun.taluknamee AS talukname,
    p.hoblicode,
    fun.hoblinamee AS hobliname,
    p.villagecode AS cityvillagecode,
    fun.villagenamee AS villagename,
    p.pincode,
    p.combinephotopath,
    p.bridephoto,
    p.bridegroomphoto,
    p.marriagemodeid
   FROM (kaveri.vw_fetch_marriage_reg_details p
     JOIN LATERAL kaveri.fn_fetch_marriage_lgdmaster1(p.statecode, p.districtcode, p.talukacode, p.hoblicode, p.villagecode) fun(statecode, statenamee, districtcode, districtnamee, talukcode, taluknamee, hoblicode, hoblinamee, villagecode, villagenamee) ON ((p.statecode = fun.statecode)));


ALTER TABLE kaveri.vw_fetch_marriagedetails OWNER TO postgres;

