--

CREATE VIEW kaveri.vw_fetch_module_submodule_info AS
 SELECT m.moduleid,
    s.submoduleid,
    f.functionid
   FROM ((kaveri.modulemaster m
     LEFT JOIN kaveri.submodulemaster s ON ((m.moduleid = s.moduleid)))
     LEFT JOIN kaveri.functionmaster f ON (((s.moduleid = f.moduleid) AND (s.submoduleid = f.submoduleid) AND (m.moduleid = f.moduleid))))
  ORDER BY m.moduleid, s.submoduleid, f.functionid;


ALTER TABLE kaveri.vw_fetch_module_submodule_info OWNER TO csgadmin;

--
-- Name: vw_fetch_movable_property; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_movable_property AS
 SELECT a.propertyid,
    a.documentid,
    a.stamparticlecode,
    e.articlenamee AS stamparticle,
    a.stampruleid,
    f.descriptione AS stampsubarticalcode,
    d.bookid,
    c.booknameenglish AS booknumber,
    a.regarticlecode,
    d.articlenamee AS registrationfeearticle,
    a.movablepropertydesc AS propertywithdescription,
    a.applicationnumber,
    f.sameasarticleid,
    f.parentrefid,
    f.haschild,
    f.isslabs,
    f.unitisamount,
    f.unitdescriptione,
    f.unit,
    f.value,
    f.minlimit,
    f.maxlimit,
    f.multipliedby,
    f.sdcalcon,
    f.isinpercentage,
    f.isfixduty,
    f.isexempted,
    f.isruleactive,
    f.regvalue,
    f.regispercent,
    f.regmaxlimit,
    f.regminlimit,
    f.regcalconconsideration,
    f.othercalcrule,
    f.othercalcon,
    f.isaddonvalue,
    f.addoncaptione,
    f.activefrom,
    f.activeto,
    f.issurcharge,
    f.urbanvalue,
    f.ruralvalue,
    f.issurchargepercentage,
    f.iscess,
    f.cessvalue,
    f.iscesspercentage
   FROM ((((kaveri.propertymaster a
     JOIN kaveri.registrationarticles d ON ((d.regarticlecode = a.regarticlecode)))
     JOIN kaveri.booktypemaster c ON ((c.bookid = d.bookid)))
     JOIN kaveri.stamparticles e ON ((e.stamparticlecode = a.stamparticlecode)))
     JOIN kaveri.stamprules f ON (((f.stampruleid = a.stampruleid) AND (a.ismovableproperty = true))));


ALTER TABLE kaveri.vw_fetch_movable_property OWNER TO postgres;

--
-- Name: vw_fetch_mr_sfda_dashboard; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_mr_sfda_dashboard AS
 SELECT ad.applicationnumber AS applicationnum,
    COALESCE((ad.applicationdate)::date, (ad.applicationstartdate)::date) AS applicationdate,
    COALESCE(m.regsrocode, m.regsrocode) AS srocode,
    ad.applicationtypeid,
    sm.servicename,
    ad.currentstatus,
    wm.wrkflowstatusnamee,
    ad.sfdaid,
    usr.username,
    mm.marriagemode,
    mt.marriagetype,
    mm.marriagemodeid,
    mt.marriagetypeid
   FROM ((((((kaveri.applicantapplicationdetails ad
     JOIN kaveri.marriageregistration m ON (((m.applicationnumber)::text = (ad.applicationnumber)::text)))
     LEFT JOIN kaveri.vw_department_users usr ON ((usr.userid = ad.sfdaid)))
     LEFT JOIN kaveri.wrkflowmaster wm ON (((wm.wrkflowstatusid)::text = (ad.currentstatus)::text)))
     LEFT JOIN kaveri.servicesmaster sm ON ((ad.applicationtypeid = sm.serviceid)))
     LEFT JOIN kaveri.mas_marriagemode mm ON ((mm.marriagemodeid = m.marriagemodeid)))
     LEFT JOIN kaveri.mas_marriagetype mt ON ((mt.marriagetypeid = m.marriagetypeid)))
  WHERE ((ad.applicationtypeid = 4) AND ((ad.currentstatus)::text <> ALL (ARRAY['MR101'::text, 'MR108'::text, 'MR111'::text, 'MR113'::text, 'MR115'::text, 'MR112'::text, 'MR102'::text, 'MR103'::text, 'MR104'::text, 'MR105'::text, 'MR116'::text, 'MR117'::text, 'MR118'::text, 'MR121'::text])));


ALTER TABLE kaveri.vw_fetch_mr_sfda_dashboard OWNER TO postgres;

--
-- Name: vw_fetch_mr_sro_dashboard; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_mr_sro_dashboard AS
 SELECT ad.applicationnumber AS applicationnum,
    COALESCE((ad.applicationdate)::date, (ad.applicationstartdate)::date) AS applicationdate,
    COALESCE(m.regsrocode, m.regsrocode) AS srocode,
    ad.applicationtypeid,
    sm.servicename,
    ad.currentstatus,
    wm.wrkflowstatusnamee,
    ad.sfdaid,
    usr.username,
    mm.marriagemode,
    mt.marriagetype,
    m.scannedform1path,
    mm.marriagemodeid,
    mt.marriagetypeid
   FROM ((((((kaveri.applicantapplicationdetails ad
     JOIN kaveri.marriageregistration m ON (((m.applicationnumber)::text = (ad.applicationnumber)::text)))
     LEFT JOIN kaveri.vw_department_users usr ON ((usr.userid = ad.sfdaid)))
     LEFT JOIN kaveri.wrkflowmaster wm ON (((wm.wrkflowstatusid)::text = (ad.currentstatus)::text)))
     LEFT JOIN kaveri.servicesmaster sm ON ((ad.applicationtypeid = sm.serviceid)))
     LEFT JOIN kaveri.mas_marriagemode mm ON ((mm.marriagemodeid = m.marriagemodeid)))
     LEFT JOIN kaveri.mas_marriagetype mt ON ((mt.marriagetypeid = m.marriagetypeid)))
  WHERE ((ad.applicationtypeid = 4) AND ((ad.currentstatus)::text <> ALL (ARRAY['MR101'::text, 'MR111'::text, 'MR115'::text, 'MR102'::text, 'MR103'::text, 'MR104'::text, 'MR105'::text, 'MR125'::text, 'MR117'::text, 'MR118'::text, 'MR121'::text])));


ALTER TABLE kaveri.vw_fetch_mr_sro_dashboard OWNER TO postgres;

--
-- Name: vw_fetch_new_property_no_search_parameters; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_new_property_no_search_parameters AS
 SELECT a.srocode,
    a.orderid,
    a.ordernumber AS drordernumber,
    a.orderdate,
    b.documentid,
        CASE
            WHEN (p.propertyid IS NULL) THEN false
            ELSE true
        END AS is_propertynumber_available,
    b.villagecode,
    v.villagenamee,
    b.propertyid,
    p.currentpropertytypeid,
    c.typenameenglish AS currentpropertytype,
    p.currentnumber,
    p.oldpropertytypeid,
    f.typenameenglish AS oldpropertytype,
    p.oldnumber,
    p.survey_no,
    p.surnoc,
    p.hissa_no
   FROM (((((kaveri.dec_drordermaster a
     JOIN kaveri.propertymaster b ON ((a.documentid = b.documentid)))
     LEFT JOIN kaveri.propertynumberdetails p ON ((b.propertyid = p.propertyid)))
     LEFT JOIN kaveri.propertynotypemaster c ON ((p.currentpropertytypeid = c.propertytypeid)))
     LEFT JOIN kaveri.propertynotypemaster f ON ((p.oldpropertytypeid = f.propertytypeid)))
     LEFT JOIN kaveri.villagemaster v ON ((b.villagecode = v.villagecode)));


ALTER TABLE kaveri.vw_fetch_new_property_no_search_parameters OWNER TO postgres;

--
-- Name: vw_fetch_new_property_no_search_parameters_from_ecpropertysearc; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_new_property_no_search_parameters_from_ecpropertysearc AS
 SELECT b.documentid,
    e.villagecode,
    v.villagenamee,
    b.propertyid,
    e.currentpropertytypeid,
    c.typenameenglish AS currentpropertytype,
    e.currentnumber,
    e.oldpropertytypeid,
    f.typenameenglish AS oldpropertytype,
    e.oldnumber,
    e.survey_no,
    e.surnoc,
    e.hissa_no
   FROM ((((kaveri.propertymaster b
     LEFT JOIN kaveri.ecpropertysearchkeyvalues e ON ((b.propertyid = e.propertyid)))
     LEFT JOIN kaveri.propertynotypemaster c ON ((e.currentpropertytypeid = c.propertytypeid)))
     LEFT JOIN kaveri.propertynotypemaster f ON ((e.oldpropertytypeid = f.propertytypeid)))
     LEFT JOIN kaveri.villagemaster v ON ((e.villagecode = v.villagecode)));


ALTER TABLE kaveri.vw_fetch_new_property_no_search_parameters_from_ecpropertysearc OWNER TO postgres;

