    a.transactextacre,
    a.transactextgunta,
    a.transactextfgunta,
    a.districtcode,
    dm.districtnamee,
    a.talukcode,
    ( SELECT t2.taluknamee
           FROM kaveri.talukmaster t2
          WHERE (t2.talukcode = a.talukcode)) AS taluknamee,
    s.statecode,
    s.statenamee,
    a.hoblicode,
    ( SELECT h2.hoblinamee
           FROM kaveri.hoblimaster h2
          WHERE (h2.hoblicode = a.hoblicode)) AS hoblinamee,
    a.villagecode,
    ( SELECT v2.villagenamee
           FROM kaveri.villagemaster v2
          WHERE (v2.villagecode = a.villagecode)) AS villagenamee,
    ( SELECT p2.descriptioninenglish
           FROM kaveri.partytypemaster p2
