--
-- Name: vw_fetch_party_lgd; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_party_lgd AS
 SELECT DISTINCT f.applicationnumber,
    a.partyid,
    a.srocode,
    b.sronamee,
    a.partytypeid,
    d.descriptioninenglish AS partytypename,
    a.isorganization,
    a.firstname,
    a.middlename,
    a.lastname,
    concat_ws(' '::text, e.descriptione, a.firstname, a.middlename, a.lastname) AS name,
    concat_ws(' '::text, COALESCE(a.housenumber, ''::text), a.address, kaveri.fn_fetch_address_taluk_lgd((a.talukcode)::bigint), a.pin) AS address,
    a.aliasname,
    a.tanno,
    a.pan AS idproofnumber,
    a.idprooftypeid,
    id.description AS idprooftypedesc,
    a.age,
    a.sex AS gender,
    r.relatione AS relationship,
    a.relativename,
    a.isexecutor,
    a.ispresenter,
    a.isconsentwitness,
    a.isprivateattendance,
    (a.admissiondate)::date AS admissiondate,
    a.epic,
    a.phonenumber,
    a.fingerid,
    a.fingerverificationstatusid,
    a.ownerno,
    a.photopath,
    a.profession,
    a.section88exemption,
    a.thumbpath,
    a.organizationid,
    a.yearofincorp,
    a.linkpartyid,
    a.housenumber,
    a.pin,
    a.propertyid,
        CASE
            WHEN (au.partytypeid = 9) THEN concat_ws(' '::text, sal_au.descriptione, au.firstname, au.middlename, au.lastname)
            ELSE NULL::text
        END AS auname,
        CASE
            WHEN (au.partytypeid = 9) THEN concat_ws(' '::text, au.housenumber, au.address, kaveri.fn_fetch_address_taluk_lgd((au.talukcode)::bigint), au.pin)
            ELSE NULL::text
        END AS auaddress,
        CASE
            WHEN (au.partytypeid = 9) THEN au.aliasname
            ELSE NULL::character varying
        END AS aualiasname,
        CASE
            WHEN (au.partytypeid = 9) THEN au.age
            ELSE NULL::character varying
        END AS auage,
        CASE
            WHEN (au.partytypeid = 9) THEN au.sex
            ELSE NULL::smallint
        END AS ausex,
        CASE
            WHEN (au.partytypeid = 9) THEN au.idprooftypeid
            ELSE NULL::smallint
        END AS auidprooftypeid,
        CASE
            WHEN (au.partytypeid = 9) THEN id_au.description
            ELSE NULL::character varying
        END AS auidprooftypedesc,
        CASE
            WHEN (au.partytypeid = 9) THEN au.pan
            ELSE NULL::character varying
        END AS auidproofnumber,
        CASE
            WHEN (au.partytypeid = 9) THEN au.profession
            ELSE NULL::character varying
        END AS auprofession,
    poa.isorganization AS poaisorganization,
    concat_ws(' '::text, sal_poa.descriptione, poa.firstname, poa.middlename, poa.lastname) AS poaname,
    concat_ws(' '::text, poa.housenumber, poa.address, kaveri.fn_fetch_address_taluk_lgd((poa.talukcode)::bigint), poa.pin) AS poaaddress,
    poa.age AS poaage,
    poa.sex AS poasex,
    poa.pan AS poaidproofnumber,
    poa.tanno AS poatan,
    poa.profession AS poaprofession,
    rel.relatione AS poarelationship,
    poa.relativename AS poarelativename,
    poa.partytypeid AS poapartytypeid,
    poa.idprooftypeid AS poaidprooftypeid,
    id_poa.description AS poaidprooftypedesc,
    poa_type.descriptioninenglish AS poapartytypename,
    poa.yearofincorp AS poayearofincorp,
    poa.orgpoaauthsignfname,
    poa.orgpoaauthsignmname,
    poa.orgpoaauthsignlname,
        CASE
            WHEN (au.partytypeid = 4) THEN concat_ws(' '::text, sal_au.descriptione, au.firstname, au.middlename, au.lastname)
            ELSE NULL::text
        END AS minorguardianname,
        CASE
            WHEN (au.partytypeid = 4) THEN (au.age)::integer
            ELSE NULL::integer
        END AS minorguardianage,
        CASE
            WHEN (au.partytypeid = 4) THEN r_au.relatione
            ELSE NULL::character varying
        END AS minorguardianrelationship,
        CASE
            WHEN (au.partytypeid = 4) THEN au.relativename
            ELSE NULL::character varying
        END AS minorguardianrelativename,
    a.coveringletterno,
    a.section88file
   FROM (((((((((((((((kaveri.partyinfo a
     JOIN kaveri.applicantapplicationdetails f ON (((a.applicationnumber)::text = (f.applicationnumber)::text)))
     JOIN kaveri.sromaster b ON ((a.srocode = b.srocode)))
     LEFT JOIN kaveri.partyinfo au ON (((a.partyid = au.linkpartyid) AND (au.partytypeid = ANY (ARRAY[9, 4])))))
     LEFT JOIN kaveri.partyinfo poa ON (((a.partyid = poa.linkpartyid) AND (poa.partytypeid = 5))))
     LEFT JOIN kaveri.relationshipmasters rel ON (((rel.id)::text = (poa.relationship)::text)))
     LEFT JOIN kaveri.partytypemaster d ON ((a.partytypeid = d.partytypeid)))
     LEFT JOIN kaveri.partytypemaster poa_type ON ((poa.partytypeid = poa_type.partytypeid)))
     LEFT JOIN kaveri.salutationmaster e ON ((a.salutationid = e.salutationid)))
     LEFT JOIN kaveri.salutationmaster sal_au ON ((au.salutationid = sal_au.salutationid)))
     LEFT JOIN kaveri.salutationmaster sal_poa ON ((sal_poa.salutationid = poa.salutationid)))
     LEFT JOIN kaveri.mas_idprooftypes id ON ((id.idprooftypeid = a.idprooftypeid)))
     LEFT JOIN kaveri.mas_idprooftypes id_au ON ((id_au.idprooftypeid = au.idprooftypeid)))
     LEFT JOIN kaveri.mas_idprooftypes id_poa ON ((id_poa.idprooftypeid = poa.idprooftypeid)))
     LEFT JOIN kaveri.relationshipmasters r ON (((r.id)::text = (a.relationship)::text)))
     LEFT JOIN kaveri.relationshipmasters r_au ON (((r_au.id)::text = (au.relationship)::text)));


ALTER TABLE kaveri.vw_fetch_party_lgd OWNER TO postgres;

--
-- Name: vw_fetch_party_paperless; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_party_paperless AS
 SELECT DISTINCT f.applicationnumber,
    a.partyid,
    a.srocode,
    b.sronamee,
    a.partytypeid,
    d.descriptioninenglish AS partytypename,
    a.isorganization,
        CASE
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NOT NULL)) THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is rep. by minor guardian ', au.firstname, ' ', au.middlename, ' ', au.lastname, ', whose POA is ', sal_poa.descriptione, poa.firstname, ' ', poa.middlename, ' ', poa.lastname)
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NULL)) THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is rep. by minor guardian ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname)
            WHEN ((au.partytypeid = 5) AND (a.isorganization = true)) THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' POA by ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname, ' is Rep. by ', au.orgpoaauthsignfname, ' ', au.orgpoaauthsignlname)
            WHEN ((au.partytypeid = 5) AND (a.isorganization = false)) THEN concat(sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname, ' is POA of ', e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is Rep. by ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname, ', whose POA is ', sal_poa.descriptione, poa.firstname, ' ', poa.middlename, ' ', poa.lastname)
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NULL)) THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is Rep. by ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname)
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 1)) THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 2)) THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 10)) THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
            ELSE NULL::text
        END AS name,
        CASE
            WHEN (md.ispendingdocument = true) THEN (a.address)::text
            ELSE concat_ws(' '::text, ((((((
            CASE
                WHEN (a.housenumber IS NULL) THEN ''::text
                ELSE a.housenumber
            END || ', '::text) || (a.address)::text) || ', '::text) || kaveri.fn_fetch_address_village((a.talukcode)::bigint)) || ' - '::text) || a.pin))
        END AS address,
    a.aliasname,
    a.tanno,
        CASE
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NOT NULL)) THEN (poa.pan)::text
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NULL)) THEN (au.pan)::text
            WHEN ((au.partytypeid = 5) AND (a.isorganization = true)) THEN (a.pan)::text
            WHEN ((au.partytypeid = 5) AND (a.isorganization = false)) THEN (au.pan)::text
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN (poa.pan)::text
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NULL)) THEN (au.pan)::text
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 1)) THEN (a.pan)::text
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 2)) THEN (a.pan)::text
            ELSE NULL::text
        END AS idproofnumber,
        CASE
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NOT NULL)) THEN poa.idprooftypeid
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NULL)) THEN au.idprooftypeid
            WHEN ((au.partytypeid = 5) AND (a.isorganization = true)) THEN a.idprooftypeid
            WHEN ((au.partytypeid = 5) AND (a.isorganization = false)) THEN au.idprooftypeid
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN poa.idprooftypeid
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NULL)) THEN au.idprooftypeid
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 1)) THEN a.idprooftypeid
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 2)) THEN a.idprooftypeid
            ELSE NULL::smallint
        END AS idprooftypeid,
        CASE
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NOT NULL)) THEN (id_poa.description)::text
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NULL)) THEN (id_au.description)::text
            WHEN ((au.partytypeid = 5) AND (a.isorganization = true)) THEN (id.description)::text
            WHEN ((au.partytypeid = 5) AND (a.isorganization = false)) THEN (id_au.description)::text
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN (id_poa.description)::text
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NULL)) THEN (id_au.description)::text
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 1)) THEN (id.description)::text
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 2)) THEN (id.description)::text
            ELSE NULL::text
        END AS idprooftypedesc,
    (
        CASE
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NOT NULL)) THEN poa.age
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NULL)) THEN au.age
            WHEN ((au.partytypeid = 5) AND (a.isorganization = true)) THEN a.age
            WHEN ((au.partytypeid = 5) AND (a.isorganization = false)) THEN au.age
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN poa.age
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NULL)) THEN au.age
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 1)) THEN a.age
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 2)) THEN a.age
            ELSE NULL::character varying
        END)::integer AS age,
        CASE
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NOT NULL)) THEN poa.sex
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NULL)) THEN au.sex
            WHEN ((au.partytypeid = 5) AND (a.isorganization = true)) THEN a.sex
            WHEN ((au.partytypeid = 5) AND (a.isorganization = false)) THEN au.sex
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN poa.sex
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NULL)) THEN au.sex
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 1)) THEN a.sex
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 2)) THEN a.sex
            ELSE NULL::smallint
        END AS gender,
        CASE
            WHEN ((a.isorganization = true) AND (poa.firstname IS NULL)) THEN r_au.relatione
            WHEN ((a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN r_poa.relatione
            WHEN ((a.age)::text < '18'::text) THEN r_au.relatione
            ELSE r.relatione
        END AS relationship,
        CASE
            WHEN ((a.isorganization = true) AND (poa.firstname IS NULL)) THEN au.relativename
            WHEN ((a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN poa.relativename
            WHEN ((a.age)::text < '18'::text) THEN au.relativename
            ELSE a.relativename
        END AS relativename,
    a.isexecutor,
    a.ispresenter,
    a.isconsentwitness,
    a.isprivateattendance,
    (a.admissiondate)::date AS admissiondate,
    a.epic,
        CASE
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NOT NULL)) THEN poa.phonenumber
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NULL)) THEN a.phonenumber
            WHEN ((au.partytypeid = 5) AND (a.isorganization = true)) THEN a.phonenumber
            WHEN ((au.partytypeid = 5) AND (a.isorganization = false)) THEN a.phonenumber
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN poa.phonenumber
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NULL)) THEN au.phonenumber
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 1)) THEN a.phonenumber
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 2)) THEN a.phonenumber
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 10)) THEN a.phonenumber
            ELSE NULL::character varying(15)
        END AS phonenumber,
    a.fingerid,
    a.fingerverificationstatusid,
    a.ownerno,
    a.photopath,
    a.profession,
    a.section88exemption,
    a.thumbpath,
    a.organizationid,
    a.yearofincorp,
    a.linkpartyid,
    a.housenumber,
    a.pin,
    a.propertyid,
    a.isendorseprinted,
        CASE
            WHEN (au.partytypeid = 9) THEN concat_ws(' '::text, sal_au.descriptione, au.firstname, au.middlename, au.lastname)
            ELSE NULL::text
        END AS auname,
        CASE
            WHEN (au.partytypeid = 9) THEN concat_ws(' '::text, au.housenumber, ', '::text, au.address, ', '::text, ((kaveri.fn_fetch_address_village((au.talukcode)::bigint) || ' - '::text) || au.pin))
            ELSE NULL::text
        END AS auaddress,
        CASE
            WHEN (au.partytypeid = 9) THEN au.aliasname
            ELSE NULL::character varying
        END AS aualiasname,
        CASE
            WHEN (au.partytypeid = 9) THEN (
            CASE
                WHEN ((au.age)::text >= '0'::text) THEN au.age
                ELSE NULL::character varying
            END)::integer
            ELSE NULL::integer
        END AS auage,
        CASE
            WHEN (au.partytypeid = 9) THEN au.sex
            ELSE NULL::smallint
        END AS ausex,
        CASE
            WHEN (au.partytypeid = 9) THEN au.idprooftypeid
            ELSE NULL::smallint
        END AS auidprooftypeid,
        CASE
            WHEN (au.partytypeid = 9) THEN id_au.description
            ELSE NULL::character varying
        END AS auidprooftypedesc,
        CASE
            WHEN (au.partytypeid = 9) THEN au.pan
            ELSE NULL::character varying
        END AS auidproofnumber,
        CASE
            WHEN (au.partytypeid = 9) THEN au.profession
            ELSE NULL::character varying
        END AS auprofession,
    poa.isorganization AS poaisorganization,
    concat_ws(' '::text, sal_poa.descriptione, poa.firstname, poa.middlename, poa.lastname) AS poaname,
    concat_ws(' '::text, poa.housenumber, ', '::text, poa.address, ', '::text, ((kaveri.fn_fetch_address_village((poa.talukcode)::bigint) || ' - '::text) || poa.pin)) AS poaaddress,
    (
        CASE
            WHEN ((poa.age)::text >= '0'::text) THEN poa.age
            ELSE NULL::character varying
        END)::integer AS poaage,
    poa.sex AS poasex,
    poa.pan AS poaidproofnumber,
    poa.tanno AS poatan,
    poa.profession AS poaprofession,
    rel.relatione AS poarelationship,
    poa.relativename AS poarelativename,
    poa.partytypeid AS poapartytypeid,
    poa.idprooftypeid AS poaidprooftypeid,
    id_poa.description AS poaidprooftypedesc,
    poa_type.descriptioninenglish AS poapartytypename,
    poa.yearofincorp AS poayearofincorp,
    poa.orgpoaauthsignfname,
    poa.orgpoaauthsignmname,
    poa.orgpoaauthsignlname,
        CASE
            WHEN (au.partytypeid = 4) THEN concat_ws(' '::text, sal_au.descriptione, au.firstname, au.middlename, au.lastname)
            ELSE NULL::text
        END AS minorguardianname,
        CASE
            WHEN (au.partytypeid = 4) THEN (
            CASE
                WHEN ((au.age)::text >= '0'::text) THEN au.age
                ELSE NULL::character varying
            END)::integer
            ELSE NULL::integer
        END AS minorguardianage,
        CASE
            WHEN (au.partytypeid = 4) THEN r_au.relatione
            ELSE NULL::character varying
        END AS minorguardianrelationship,
        CASE
            WHEN (au.partytypeid = 4) THEN au.relativename
            ELSE NULL::character varying
        END AS minorguardianrelativename,
    a.coveringletterno,
    a.section88file,
    (a.thumbremarks)::text AS thumbremarks,
        CASE
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NOT NULL)) THEN poa.ispartyrefused
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NULL)) THEN au.ispartyrefused
            WHEN ((au.partytypeid = 5) AND (a.isorganization = true)) THEN a.ispartyrefused
            WHEN ((au.partytypeid = 5) AND (a.isorganization = false)) THEN au.ispartyrefused
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN poa.ispartyrefused
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NULL)) THEN au.ispartyrefused
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 1)) THEN a.ispartyrefused
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 2)) THEN a.ispartyrefused
            ELSE NULL::boolean
        END AS ispartyrefused,
    a.islateapperance,
    a.presenternamee,
    a.salutationid,
        CASE
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NOT NULL)) THEN poa.isbiometricrefused
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NULL)) THEN au.isbiometricrefused
            WHEN ((au.partytypeid = 5) AND (a.isorganization = true)) THEN a.isbiometricrefused
            WHEN ((au.partytypeid = 5) AND (a.isorganization = false)) THEN au.isbiometricrefused
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN poa.isbiometricrefused
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NULL)) THEN au.isbiometricrefused
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 1)) THEN a.isbiometricrefused
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 2)) THEN a.isbiometricrefused
            ELSE NULL::boolean
        END AS isbiometricrefused,
        CASE
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NOT NULL)) THEN poa.iscitizennotappeared
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NULL)) THEN au.iscitizennotappeared
            WHEN ((au.partytypeid = 5) AND (a.isorganization = true)) THEN a.iscitizennotappeared
            WHEN ((au.partytypeid = 5) AND (a.isorganization = false)) THEN au.iscitizennotappeared
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN poa.iscitizennotappeared
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NULL)) THEN au.iscitizennotappeared
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 1)) THEN a.iscitizennotappeared
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 2)) THEN a.iscitizennotappeared
            ELSE NULL::boolean
        END AS iscitizennotappeared,
        CASE
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NOT NULL)) THEN poa.nameasperaadhar
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NULL)) THEN au.nameasperaadhar
            WHEN ((au.partytypeid = 5) AND (a.isorganization = true)) THEN a.nameasperaadhar
            WHEN ((au.partytypeid = 5) AND (a.isorganization = false)) THEN au.nameasperaadhar
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN poa.nameasperaadhar
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NULL)) THEN au.nameasperaadhar
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 1)) THEN a.nameasperaadhar
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 2)) THEN a.nameasperaadhar
            ELSE NULL::character varying(500)
        END AS nameasperaadhar,
        CASE
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NOT NULL)) THEN poa.iscitizenaadharverified
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NULL)) THEN au.iscitizenaadharverified
            WHEN ((au.partytypeid = 5) AND (a.isorganization = true)) THEN a.iscitizenaadharverified
            WHEN ((au.partytypeid = 5) AND (a.isorganization = false)) THEN au.iscitizenaadharverified
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN poa.iscitizenaadharverified
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NULL)) THEN au.iscitizenaadharverified
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 1)) THEN a.iscitizenaadharverified
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 2)) THEN a.iscitizenaadharverified
            ELSE NULL::boolean
        END AS iscitizenaadharverified,
        CASE
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NOT NULL)) THEN poa.isdeptaadharvalidated
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NULL)) THEN au.isdeptaadharvalidated
            WHEN ((au.partytypeid = 5) AND (a.isorganization = true)) THEN a.isdeptaadharvalidated
