            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN poa.iscitizennotappeared
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NULL)) THEN au.iscitizennotappeared
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 1)) THEN a.iscitizennotappeared
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 2)) THEN a.iscitizennotappeared
            ELSE NULL::boolean
        END AS iscitizennotappeared,
        CASE
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NOT NULL)) THEN poa.nameasperaadhar
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NULL)) THEN au.nameasperaadhar
            WHEN ((au.partytypeid = 5) AND (a.isorganization = true)) THEN a.nameasperaadhar
            WHEN ((au.partytypeid = 5) AND (a.isorganization = false)) THEN au.nameasperaadhar
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN poa.nameasperaadhar
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NULL)) THEN au.nameasperaadhar
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 1)) THEN a.nameasperaadhar
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 2)) THEN a.nameasperaadhar
            ELSE NULL::character varying(500)
        END AS nameasperaadhar,
        CASE
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NOT NULL)) THEN poa.iscitizenaadharverified
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NULL)) THEN au.iscitizenaadharverified
            WHEN ((au.partytypeid = 5) AND (a.isorganization = true)) THEN a.iscitizenaadharverified
            WHEN ((au.partytypeid = 5) AND (a.isorganization = false)) THEN au.iscitizenaadharverified
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN poa.iscitizenaadharverified
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NULL)) THEN au.iscitizenaadharverified
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 1)) THEN a.iscitizenaadharverified
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 2)) THEN a.iscitizenaadharverified
            ELSE NULL::boolean
        END AS iscitizenaadharverified,
        CASE
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NOT NULL)) THEN poa.isdeptaadharvalidated
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NULL)) THEN au.isdeptaadharvalidated
            WHEN ((au.partytypeid = 5) AND (a.isorganization = true)) THEN a.isdeptaadharvalidated
            WHEN ((au.partytypeid = 5) AND (a.isorganization = false)) THEN au.isdeptaadharvalidated
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN poa.isdeptaadharvalidated
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NULL)) THEN au.isdeptaadharvalidated
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 1)) THEN a.isdeptaadharvalidated
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 2)) THEN a.isdeptaadharvalidated
            ELSE NULL::boolean
        END AS isdeptaadharvalidated,
        CASE
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NOT NULL)) THEN poa.aadhaardeclinereason
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NULL)) THEN au.aadhaardeclinereason
            WHEN ((au.partytypeid = 5) AND (a.isorganization = true)) THEN a.aadhaardeclinereason
            WHEN ((au.partytypeid = 5) AND (a.isorganization = false)) THEN au.aadhaardeclinereason
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN poa.aadhaardeclinereason
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NULL)) THEN au.aadhaardeclinereason
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 1)) THEN a.aadhaardeclinereason
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 2)) THEN a.aadhaardeclinereason
            ELSE NULL::character varying(500)
        END AS aadhaardeclinereason,
        CASE
            WHEN (au.partytypeid = 4) THEN (au.nameasperaadhar)::text
            ELSE NULL::text
        END AS minorguardianaadharname,
    poa.nameasperaadhar AS poanameasperaadhar,
    a.transactextfgunta,
    a.transactextgunta,
    a.transactextacre,
    a.isdocumentexecuted,
    a.isendorsementsigned,
    a.isthumbregistersigned,
        CASE
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NOT NULL)) THEN poa.duplicatepartyid
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NULL)) THEN au.duplicatepartyid
            WHEN ((au.partytypeid = 5) AND (a.isorganization = true)) THEN a.duplicatepartyid
            WHEN ((au.partytypeid = 5) AND (a.isorganization = false)) THEN au.duplicatepartyid
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN poa.duplicatepartyid
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NULL)) THEN au.duplicatepartyid
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 1)) THEN a.duplicatepartyid
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 2)) THEN a.duplicatepartyid
            ELSE NULL::bigint
        END AS duplicatepartyid,
        CASE
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NOT NULL)) THEN poa.isduplicate
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NULL)) THEN au.isduplicate
            WHEN ((au.partytypeid = 5) AND (a.isorganization = true)) THEN a.isduplicate
            WHEN ((au.partytypeid = 5) AND (a.isorganization = false)) THEN au.isduplicate
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN poa.isduplicate
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NULL)) THEN au.isduplicate
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 1)) THEN a.isduplicate
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 2)) THEN a.isduplicate
            ELSE NULL::boolean
        END AS isduplicate,
        CASE
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NOT NULL)) THEN (poa.namematchpercentage)::bigint
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NULL)) THEN (au.namematchpercentage)::bigint
            WHEN ((au.partytypeid = 5) AND (a.isorganization = true)) THEN (a.namematchpercentage)::bigint
            WHEN ((au.partytypeid = 5) AND (a.isorganization = false)) THEN (au.namematchpercentage)::bigint
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN (poa.namematchpercentage)::bigint
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NULL)) THEN (au.namematchpercentage)::bigint
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 1)) THEN (a.namematchpercentage)::bigint
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 2)) THEN (a.namematchpercentage)::bigint
            ELSE NULL::bigint
        END AS namematchpercentage,
        CASE
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NOT NULL)) THEN (poa.districtcode)::bigint
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NULL)) THEN (a.districtcode)::bigint
            WHEN ((au.partytypeid = 5) AND (a.isorganization = true)) THEN (a.districtcode)::bigint
            WHEN ((au.partytypeid = 5) AND (a.isorganization = false)) THEN (a.districtcode)::bigint
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN (poa.districtcode)::bigint
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NULL)) THEN (au.districtcode)::bigint
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 1)) THEN (a.districtcode)::bigint
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 2)) THEN (a.districtcode)::bigint
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 10)) THEN (a.districtcode)::bigint
            ELSE NULL::bigint
        END AS districtcode,
        CASE
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NOT NULL)) THEN (poa.talukcode)::bigint
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NULL)) THEN (a.talukcode)::bigint
            WHEN ((au.partytypeid = 5) AND (a.isorganization = true)) THEN (a.talukcode)::bigint
            WHEN ((au.partytypeid = 5) AND (a.isorganization = false)) THEN (a.talukcode)::bigint
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN (poa.talukcode)::bigint
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NULL)) THEN (au.talukcode)::bigint
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 1)) THEN (a.talukcode)::bigint
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 2)) THEN (a.talukcode)::bigint
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 10)) THEN (a.talukcode)::bigint
            ELSE NULL::bigint
        END AS talukcode,
        CASE
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NOT NULL)) THEN poa.villagecode
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NULL)) THEN a.villagecode
            WHEN ((au.partytypeid = 5) AND (a.isorganization = true)) THEN a.villagecode
            WHEN ((au.partytypeid = 5) AND (a.isorganization = false)) THEN a.villagecode
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN poa.villagecode
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NULL)) THEN au.villagecode
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 1)) THEN a.villagecode
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 2)) THEN a.villagecode
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 10)) THEN a.villagecode
            ELSE NULL::bigint
        END AS villagecode,
    ( SELECT aa.vault_id
           FROM kaveri.aadhar_authentication_log aa
          WHERE (aa.partyid = a.partyid)
          ORDER BY aa.id DESC
         LIMIT 1) AS vault_id
   FROM (((((((((((((((((((kaveri.partyinfo a
     JOIN kaveri.applicantapplicationdetails f ON (((a.applicationnumber)::text = (f.applicationnumber)::text)))
     LEFT JOIN kaveri.minutebook_data md ON (((a.applicationnumber)::text = (md.applicationnumber)::text)))
     JOIN kaveri.sromaster b ON ((a.srocode = b.srocode)))
     LEFT JOIN kaveri.partyinfo au ON (((a.partyid = au.linkpartyid) AND (au.partytypeid = ANY (ARRAY[9, 4, 5])))))
     LEFT JOIN kaveri.partyinfo poa ON (((poa.linkpartyid = au.partyid) AND (poa.partytypeid = ANY (ARRAY[5])))))
     LEFT JOIN kaveri.partyinfo dup ON ((au.duplicatepartyid = dup.partyid)))
     LEFT JOIN kaveri.relationshipmasters rel ON (((rel.id)::text = (poa.relationship)::text)))
     LEFT JOIN kaveri.partytypemaster d ON ((a.partytypeid = d.partytypeid)))
     LEFT JOIN kaveri.partytypemaster au_type ON ((au.partytypeid = au_type.partytypeid)))
     LEFT JOIN kaveri.partytypemaster poa_type ON ((poa.partytypeid = poa_type.partytypeid)))
     LEFT JOIN kaveri.salutationmaster e ON ((a.salutationid = e.salutationid)))
     LEFT JOIN kaveri.salutationmaster sal_au ON ((au.salutationid = sal_au.salutationid)))
     LEFT JOIN kaveri.salutationmaster sal_poa ON ((sal_poa.salutationid = poa.salutationid)))
     LEFT JOIN kaveri.mas_idprooftypes id ON ((id.idprooftypeid = a.idprooftypeid)))
     LEFT JOIN kaveri.mas_idprooftypes id_au ON ((id_au.idprooftypeid = au.idprooftypeid)))
     LEFT JOIN kaveri.mas_idprooftypes id_poa ON ((id_poa.idprooftypeid = poa.idprooftypeid)))
     LEFT JOIN kaveri.relationshipmasters r ON (((r.id)::text = (a.relationship)::text)))
     LEFT JOIN kaveri.relationshipmasters r_au ON (((r_au.id)::text = (au.relationship)::text)))
     LEFT JOIN kaveri.relationshipmasters r_poa ON (((r_poa.id)::text = (poa.relationship)::text)))
  WHERE (a.applicationnumber IS NOT NULL);


