--
-- Name: vw_fetch_party_paperless_20260617; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_party_paperless_20260617 AS
 SELECT DISTINCT f.applicationnumber,
    a.partyid,
    a.partytypeid,
        CASE
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NOT NULL)) THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is rep. by minor guardian ', au.firstname, ' ', au.middlename, ' ', au.lastname, ', whose POA is ', sal_poa.descriptione, poa.firstname, ' ', poa.middlename, ' ', poa.lastname)
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NULL)) THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is rep. by minor guardian ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname)
            WHEN ((au.partytypeid = 5) AND (a.isorganization = true)) THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' POA by ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname, ' is Rep. by ', au.orgpoaauthsignfname, ' ', au.orgpoaauthsignlname)
            WHEN ((au.partytypeid = 5) AND (a.isorganization = false)) THEN concat(sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname, ' is POA of ', e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is Rep. by ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname, ', whose POA is ', sal_poa.descriptione, poa.firstname, ' ', poa.middlename, ' ', poa.lastname)
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NULL)) THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname, ' is Rep. by ', sal_au.descriptione, au.firstname, ' ', au.middlename, ' ', au.lastname)
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 1)) THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 2)) THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 10)) THEN concat(e.descriptione, a.firstname, ' ', a.middlename, ' ', a.lastname)
            ELSE NULL::text
        END AS name,
        CASE
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NOT NULL)) THEN al_poa_type.vault_id
            WHEN ((au.partytypeid = 4) AND (poa.firstname IS NULL)) THEN al.vault_id
            WHEN ((au.partytypeid = 5) AND (a.isorganization = true)) THEN al.vault_id
            WHEN ((au.partytypeid = 5) AND (a.isorganization = false)) THEN al.vault_id
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NOT NULL)) THEN al_poa_type.vault_id
            WHEN ((au.partytypeid = 9) AND (a.isorganization = true) AND (poa.firstname IS NULL)) THEN al_type.vault_id
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 1)) THEN al.vault_id
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 2)) THEN al.vault_id
            WHEN ((au.partytypeid IS NULL) AND (a.partytypeid = 10)) THEN al.vault_id
            ELSE NULL::character varying
        END AS vault_id
   FROM (((((((((((((((((((((kaveri.partyinfo a
     JOIN kaveri.applicantapplicationdetails f ON (((a.applicationnumber)::text = (f.applicationnumber)::text)))
     LEFT JOIN kaveri.minutebook_data md ON (((a.applicationnumber)::text = (md.applicationnumber)::text)))
     JOIN kaveri.sromaster b ON ((a.srocode = b.srocode)))
     LEFT JOIN kaveri.partyinfo au ON (((a.partyid = au.linkpartyid) AND (au.partytypeid = ANY (ARRAY[9, 4, 5])))))
     LEFT JOIN kaveri.partyinfo poa ON (((poa.linkpartyid = au.partyid) AND (poa.partytypeid = ANY (ARRAY[5])))))
     LEFT JOIN kaveri.relationshipmasters rel ON (((rel.id)::text = (poa.relationship)::text)))
     LEFT JOIN kaveri.partytypemaster d ON ((a.partytypeid = d.partytypeid)))
     LEFT JOIN kaveri.partytypemaster au_type ON ((au.partytypeid = au_type.partytypeid)))
     LEFT JOIN kaveri.partytypemaster poa_type ON ((poa.partytypeid = poa_type.partytypeid)))
     LEFT JOIN kaveri.aadhar_authentication_log al ON (((a.partyid = al.partyid) AND ((a.applicationnumber)::text = (al.applicationnumber)::text))))
     LEFT JOIN kaveri.aadhar_authentication_log al_type ON (((au.partyid = al_type.partyid) AND ((au.applicationnumber)::text = (al_type.applicationnumber)::text))))
     LEFT JOIN kaveri.aadhar_authentication_log al_poa_type ON (((poa.partyid = al_poa_type.partyid) AND ((poa.applicationnumber)::text = (al_poa_type.applicationnumber)::text))))
     LEFT JOIN kaveri.salutationmaster e ON ((a.salutationid = e.salutationid)))
     LEFT JOIN kaveri.salutationmaster sal_au ON ((au.salutationid = sal_au.salutationid)))
     LEFT JOIN kaveri.salutationmaster sal_poa ON ((sal_poa.salutationid = poa.salutationid)))
     LEFT JOIN kaveri.mas_idprooftypes id ON ((id.idprooftypeid = a.idprooftypeid)))
     LEFT JOIN kaveri.mas_idprooftypes id_au ON ((id_au.idprooftypeid = au.idprooftypeid)))
     LEFT JOIN kaveri.mas_idprooftypes id_poa ON ((id_poa.idprooftypeid = poa.idprooftypeid)))
     LEFT JOIN kaveri.relationshipmasters r ON (((r.id)::text = (a.relationship)::text)))
     LEFT JOIN kaveri.relationshipmasters r_au ON (((r_au.id)::text = (au.relationship)::text)))
     LEFT JOIN kaveri.relationshipmasters r_poa ON (((r_poa.id)::text = (poa.relationship)::text)))
  WHERE (a.applicationnumber IS NOT NULL);


ALTER TABLE kaveri.vw_fetch_party_paperless_20260617 OWNER TO postgres;

--
-- Name: vw_fetch_party_witness; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_party_witness AS
 SELECT 0 AS partyid,
    ''::text AS partyname,
    b.name,
    b.middlename,
    b.lastname,
    b.age,
    b.address,
    b.sex,
    b.profession,
    b.witnessid,
    b.registrationid,
    b.dateofbirth,
    b.status,
    b.phoneno,
    b.relation,
    b.mothername,
    b.fathersname,
    b.srocode,
    b.applicationnumber,
    b.verified,
    b.issroapproved,
    b.statecode,
    b.districtcode,
    b.talukcode,
    b.hoblicode,
    b.villagecode,
    b.relativename,
    b.pincode,
    b.houseno,
    b.iscliment,
    b.isexicutent,
    ( SELECT array_to_json(array_agg(row_to_json(schd.*))) AS array_to_json
           FROM ( SELECT pi.partyid,
                    concat_ws(' '::text, pi.firstname, pi.middlename, pi.lastname) AS partyname,
                        CASE
                            WHEN (COALESCE(pwi.witnessid, (0)::bigint) = 0) THEN 'false'::text
                            ELSE 'true'::text
                        END AS ispartywitness
                   FROM (kaveri.partyinfo pi
                     JOIN kaveri.partywitness pwi ON (((pi.partyid = pwi.partyid) AND (pwi.witnessid = b.witnessid))))
                  WHERE ((pi.applicationnumber)::text = (b.applicationnumber)::text)) schd) AS partyidentifier
   FROM kaveri.witnessinfo b;


ALTER TABLE kaveri.vw_fetch_party_witness OWNER TO postgres;

--
-- Name: vw_fetch_party_witness_lgd; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_party_witness_lgd AS
 SELECT 0 AS partyid,
    ''::text AS partyname,
    b.name,
    b.middlename,
    b.lastname,
    b.age,
    b.address,
    b.sex,
    b.profession,
    b.witnessid,
    b.registrationid,
    b.dateofbirth,
    b.status,
    b.phoneno,
    b.relation,
    b.mothername,
    b.fathersname,
    b.srocode,
    b.applicationnumber,
    b.verified,
    b.issroapproved,
    b.statecode,
    c.statenamee,
    b.districtcode,
    b.talukcode,
    b.hoblicode,
    b.villagecode,
    b.relativename,
    b.pincode,
    b.houseno,
    b.iscliment,
    b.isexicutent,
    ( SELECT array_to_json(array_agg(row_to_json(schd.*))) AS array_to_json
           FROM ( SELECT pi.partyid,
                    ( SELECT vf.fullname
                           FROM kaveri.vw_fetch_list_choose_presenter vf
                          WHERE (((vf.applicationnumber)::text = (b.applicationnumber)::text) AND ((vf.partyid = pi.partyid) OR (vf.linkpartyid = pi.partyid)))) AS partyname,
                        CASE
                            WHEN (COALESCE(pwi.witnessid, (0)::bigint) = 0) THEN 'false'::text
                            ELSE 'true'::text
                        END AS ispartywitness
                   FROM (kaveri.partyinfo pi
                     JOIN kaveri.partywitness pwi ON (((pi.partyid = pwi.partyid) AND (pwi.witnessid = b.witnessid))))
                  WHERE ((pi.applicationnumber)::text = (b.applicationnumber)::text)) schd) AS partyidentifier,
    b.isdocumentexecuted
   FROM (kaveri.witnessinfo b
     LEFT JOIN kaveri.statemaster c ON ((c.statecode = b.statecode)));


ALTER TABLE kaveri.vw_fetch_party_witness_lgd OWNER TO postgres;

--
-- Name: vw_fetch_partypandetails; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_partypandetails AS
 SELECT p.partyid,
    p.applicationnumber,
    p.haspan,
    p.panname,
    p.dob,
    p.pannumber,
    p.form60path,
    p.panstatus,
