--
-- Name: vw_fetch_presenter_for_schedule; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_presenter_for_schedule AS
 SELECT p.partyid AS linkpartyid,
    p.partytypeid AS linked_partytypeid,
    p.firstname AS linked_firstname,
    a.partyid,
    a.partytypeid,
    a.firstname,
    p.isorganization,
        CASE
            WHEN (a.partytypeid = 4) THEN concat(p.firstname, ' is rep. by MG ', a.firstname)
            WHEN ((a.partytypeid = 5) AND (p.isorganization = true)) THEN concat(p.firstname, ' POA by ', a.firstname, ' is Rep. by ', a.orgpoaauthsignfname)
            WHEN ((a.partytypeid = 5) AND (p.isorganization = false)) THEN concat(a.firstname, ' is GPA of ', p.firstname)
            WHEN ((a.partytypeid = 9) AND (p.isorganization = true)) THEN concat(p.firstname, ' is Rep. by ', a.firstname)
            WHEN ((a.partytypeid IS NULL) AND (p.partytypeid = 1)) THEN (p.firstname)::text
            WHEN ((a.partytypeid IS NULL) AND (p.partytypeid = 2)) THEN (p.firstname)::text
            ELSE NULL::text
        END AS fullname,
    p.applicationnumber
   FROM (kaveri.partyinfo p
     LEFT JOIN kaveri.partyinfo a ON ((p.partyid = a.linkpartyid)))
  WHERE ((p.partytypeid = ANY (ARRAY[1, 2])) AND (p.isduplicate IS NOT TRUE));


ALTER TABLE kaveri.vw_fetch_presenter_for_schedule OWNER TO postgres;

--
-- Name: vw_fetch_presenter_info; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_presenter_info AS
 SELECT p.partyid AS linkpartyid,
    p.partytypeid AS linked_partytypeid,
    p.firstname AS linked_firstname,
    p1.partyid,
    p1.partytypeid,
    p1.firstname,
    p.isorganization,
        CASE
            WHEN ((p1.partytypeid = 4) AND (p2.firstname IS NOT NULL)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is rep. by minor guardian ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)
            WHEN ((p1.partytypeid = 4) AND (p2.firstname IS NULL)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is rep. by minor guardian ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)
            WHEN ((p1.partytypeid = 5) AND (p.isorganization = true)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' POA by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ' is Rep. by ', p1.orgpoaauthsignfname, ' ', p1.orgpoaauthsignlname)
            WHEN ((p1.partytypeid = 5) AND (p.isorganization = false)) THEN concat(s1.descriptione, p1.firstname, ' is GPA of ', s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
            WHEN ((p1.partytypeid = 9) AND (p.isorganization = true) AND (p2.firstname IS NOT NULL)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is Rep. by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)
            WHEN ((p1.partytypeid = 9) AND (p.isorganization = true) AND (p2.firstname IS NULL)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is Rep. by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)
            WHEN ((p1.partytypeid IS NULL) AND (p.partytypeid = 1)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
            WHEN ((p1.partytypeid IS NULL) AND (p.partytypeid = 2)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
            ELSE NULL::text
        END AS fullname,
    p.applicationnumber,
        CASE
            WHEN ((p.isorganization = true) AND (p2.firstname IS NULL)) THEN p1.age
            WHEN ((p.isorganization = true) AND (p2.firstname IS NOT NULL)) THEN p2.age
            WHEN ((p.age)::text < '18'::text) THEN p1.age
            ELSE p.age
        END AS age,
        CASE
            WHEN ((p.isorganization = true) AND (p2.firstname IS NULL)) THEN p1.sex
            WHEN ((p.isorganization = true) AND (p2.firstname IS NOT NULL)) THEN p2.sex
            WHEN ((p.age)::text < '18'::text) THEN p1.sex
            ELSE p.sex
        END AS sex,
        CASE
            WHEN ((p.isorganization = true) AND (p2.firstname IS NULL)) THEN concat_ws(' '::text, ((((((
            CASE
                WHEN (p1.housenumber IS NULL) THEN ''::text
                ELSE p1.housenumber
            END || ', '::text) || (p1.address)::text) || ', '::text) || kaveri.fn_fetch_address_village((p1.talukcode)::bigint)) || ' - '::text) || p1.pin))
            WHEN ((p.isorganization = true) AND (p2.firstname IS NOT NULL)) THEN concat_ws(' '::text, ((((((
            CASE
                WHEN (p2.housenumber IS NULL) THEN ''::text
                ELSE p2.housenumber
            END || ', '::text) || (p2.address)::text) || ', '::text) || kaveri.fn_fetch_address_village((p2.talukcode)::bigint)) || ' - '::text) || p2.pin))
            WHEN ((p.age)::text < '18'::text) THEN concat_ws(' '::text, ((((((
            CASE
                WHEN (p.housenumber IS NULL) THEN ''::text
                ELSE p.housenumber
            END || ', '::text) || (p.address)::text) || ', '::text) || kaveri.fn_fetch_address_village((p.talukcode)::bigint)) || ' - '::text) || p.pin))
            ELSE concat_ws(' '::text, ((((((
            CASE
                WHEN (p.housenumber IS NULL) THEN ''::text
                ELSE p.housenumber
            END || ', '::text) || (p.address)::text) || ', '::text) || kaveri.fn_fetch_address_village((p.talukcode)::bigint)) || ' - '::text) || p.pin))
        END AS address,
        CASE
            WHEN (p.idprooftypeid IS NOT NULL) THEN m1.description
            WHEN (p1.idprooftypeid IS NOT NULL) THEN m2.description
            WHEN (p2.idprooftypeid IS NOT NULL) THEN m3.description
            WHEN (p.partyid IS NOT NULL) THEN m1.description
            WHEN (p1.partyid IS NOT NULL) THEN m2.description
            WHEN (p2.partyid IS NOT NULL) THEN m3.description
            ELSE NULL::character varying
        END AS descr,
        CASE
            WHEN ((p.isorganization = true) AND (p.firstname IS NULL)) THEN p.pan
            WHEN ((p.isorganization = true) AND (p.firstname IS NOT NULL)) THEN p.pan
            WHEN (((p.age)::text < '18'::text) AND (p.pan IS NULL)) THEN p1.pan
            WHEN (((p.age)::text < '18'::text) AND (p1.pan IS NULL)) THEN p2.pan
            ELSE p.pan
        END AS pan,
        CASE
            WHEN ((p.isorganization = true) AND (p2.firstname IS NULL)) THEN p1.profession
            WHEN ((p.isorganization = true) AND (p2.firstname IS NOT NULL)) THEN p2.profession
            WHEN ((p.age)::text < '18'::text) THEN p1.profession
            ELSE p.profession
        END AS profession,
    p.isexecutor,
    p.ispresenter
   FROM ((((((((kaveri.partyinfo p
     LEFT JOIN kaveri.partyinfo p1 ON ((p.partyid = p1.linkpartyid)))
     LEFT JOIN kaveri.partyinfo p2 ON ((p1.linkpartyid = p2.partyid)))
     LEFT JOIN kaveri.salutationmaster s ON ((p.salutationid = s.salutationid)))
     LEFT JOIN kaveri.salutationmaster s1 ON ((p1.salutationid = s1.salutationid)))
     LEFT JOIN kaveri.salutationmaster s2 ON ((p2.salutationid = s2.salutationid)))
     LEFT JOIN kaveri.mas_idprooftypes m1 ON ((p.idprooftypeid = m1.idprooftypeid)))
     LEFT JOIN kaveri.mas_idprooftypes m2 ON ((p1.idprooftypeid = m2.idprooftypeid)))
     LEFT JOIN kaveri.mas_idprooftypes m3 ON ((p2.idprooftypeid = m3.idprooftypeid)))
  WHERE ((p.partytypeid = ANY (ARRAY[1, 2])) AND ((p.section88exemption IS NULL) OR (p.section88exemption = false)) AND (p.isprivateattendance = false));


ALTER TABLE kaveri.vw_fetch_presenter_info OWNER TO postgres;

--
-- Name: vw_fetch_property_data; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_property_data AS
 WITH party AS (
         SELECT count(partyinfo.partyid) AS countofparty,
            partyinfo.isprivateattendance,
            partyinfo.partyid,
            partyinfo.applicationnumber
           FROM kaveri.partyinfo
          GROUP BY partyinfo.isprivateattendance, partyinfo.partyid, partyinfo.applicationnumber
        )
 SELECT DISTINCT a.propertyid,
    a.documentid,
    g.districtnamee AS districtname,
    a.villagecode,
    d.villagenamee,
    d.bhoomivillagecode AS village,
    h.hoblinamee,
    h.bhoomihoblicode AS hoblicode,
    i.taluknamee,
    d.bhoomitalukcode AS talukcode,
    d.bhoomidistrictcode AS districtcode,
    a.regsrocode,
    a.srocode,
    c.sronamee,
    a.totalarea,
    a.unitid,
    e.descriptionenglish AS units,
    (pt.typenameenglish)::text AS survey_no,
    l.currentnumber AS hissa_no,
    a.northboundary,
    a.southboundary,
    a.eastboundary,
    a.westboundary,
    a.landmark,
    a.marketvalue,
    a.assessment,
    a.sdcalculationstring,
    a.stampduty,
    a.transferliabilities,
    a.consideration,
    a.additionalduty,
    a.cessduty,
    a.govtduty,
    a.exemptiondescription,
    a.ismovableproperty,
    a.sdrefund,
    a.docmarketvalue,
    a.valid1,
    a.isimdemnified,
    a.restriction,
    a.restrictiontype,
    a.restrictiondescription,
    a.enumber,
    a.claimingblocknumber,
    a.retainingblocknumber,
    a.valuationreport,
    a.loanpurposeid,
    a.applicationnumber,
    a.verified,
    a.issroapproved,
    a.stamparticlecode,
    b.articlenamee AS articlename,
    a.stampruleid,
    f.descriptione AS stamprulename,
    a.regarticlecode,
    f.isslabs,
    f.unitisamount,
    f.unit,
    f.value,
    f.minlimit,
    f.maxlimit,
    f.sdcalcon,
    f.isinpercentage,
    f.isfixduty,
    f.isexempted,
    f.isruleactive,
    f.regvalue,
    f.regispercent,
    f.regmaxlimit,
    f.regminlimit,
    f.regcalconconsideration,
    f.othercalcrule,
    f.othercalcon,
    f.isaddonvalue,
    f.addonvalue,
    f.addoncaptione,
    f.addoncaptionk,
    f.activefrom,
    f.activeto,
    f.issurcharge,
    f.urbanvalue,
    f.ruralvalue,
    f.issurchargepercentage,
    f.iscess,
    f.cessvalue,
    f.iscesspercentage,
    a.propertytypeid,
    a.noofscanpages,
    a.roadcode,
    r.roadnamee,
    f.isparttransactallowed,
    a.ownedarea,
    a.sfdastamparticlecode,
    a.sfdastampruleid,
    a.sfdanoofscanpages,
    a.sfdamarketvalue,
    a.srostamparticlecode,
    a.srostampruleid,
    a.sronoofscanpages,
    a.sromarketvalue,
    a.denodescription,
    a.estampdescription,
    a.adjudescription,
    a.sroconsideration,
    a.sfdaconsideration,
    a.isbefore2004,
    a.sfdastampduty,
    a.srostampduty,
    a.sfdacessduty,
    a.srocessduty,
    a.sfdasurcharge,
    a.srosurcharge,
    a.surcharge,
    a.valuationtypeid,
        CASE
            WHEN (( SELECT sum(1) AS count1
               FROM kaveri.mojanixml m
              WHERE (m.propertyid = a.propertyid)) >= 1) THEN true
            ELSE false
        END AS isesketchused,
    a.sroroadcode,
    ( SELECT r3.roadnamee
           FROM kaveri.roadmaster r3
          WHERE (r3.roadcode = a.sroroadcode)) AS sroroadnamee,
    a.sfdaroadcode,
    ( SELECT r4.roadnamee
           FROM kaveri.roadmaster r4
          WHERE (r4.roadcode = a.sfdaroadcode)) AS sfdaroadnamee,
    i.unit AS unittype,
        CASE
            WHEN ((pnn.currentpropertytypeid = 65) OR (pnn.currentpropertytypeid = 59)) THEN true
            ELSE false
        END AS easthiproperty,
        CASE
            WHEN (pnn.currentpropertytypeid = 60) THEN true
            ELSE false
        END AS eswathuproperty,
        CASE
            WHEN (pnn.currentpropertytypeid = 1) THEN true
            ELSE false
        END AS isbhoomiproperty,
        CASE
            WHEN (pnn.currentpropertytypeid = 67) THEN true
            ELSE false
        END AS isbdaproperty,
        CASE
            WHEN ((party.countofparty = 1) AND ((a.stamparticlecode = 76) OR (a.stamparticlecode = 14)) AND (f.stampruleid <> 514)) THEN party.isprivateattendance
            ELSE false
        END AS iswillpvtattendance,
        CASE
            WHEN ((party.countofparty = 1) AND ((a.stamparticlecode = 76) OR (a.stamparticlecode = 14)) AND (f.stampruleid <> 514)) THEN party.partyid
            ELSE (0)::bigint
        END AS partyidpvtattendance,
    vl.valutiontypename,
    ( SELECT ff.isauditrequired
           FROM kaveri.stamprules ff
          WHERE (ff.stampruleid = a.stampruleid)) AS isauditrequired,
    afspm.auditorstamparticlecode,
    afspm.auditorstampruleid,
    afspm.auditorregarticlecode,
    afspm.auditormarketvalue,
    afspm.auditorconsideration,
    ( SELECT ff.isauditrequired
           FROM kaveri.stamprules ff
          WHERE (ff.stampruleid = a.sfdastampruleid)) AS issdaauditrequired,
    ( SELECT ff.isauditrequired
           FROM kaveri.stamprules ff
          WHERE (ff.stampruleid = a.srostampruleid)) AS issroauditrequired,
        CASE
            WHEN ((mb.docid IS NULL) AND (f.stampruleid = 514)) THEN true
            ELSE false
        END AS firstwillafterdeath,
        CASE
            WHEN (f.stampruleid = 514) THEN true
            ELSE false
        END AS iswillafterdeath,
        CASE
            WHEN (pnn.currentpropertytypeid = 69) THEN true
            ELSE false
        END AS istdrproperty,
        CASE
            WHEN (pnn.currentpropertytypeid = 68) THEN true
            ELSE false
        END AS iskhbproperty,
    a.upormutationfee,
    a.uporprcardfee,
    a.isuporpartextent,
    a.uporpartarea,
    a.uportotalarea,
        CASE
            WHEN (pnn.currentpropertytypeid = 61) THEN true
            ELSE false
        END AS uporproperty
   FROM ((((((((((((((((kaveri.propertymaster a
     LEFT JOIN kaveri.sromaster c ON ((a.srocode = c.srocode)))
     LEFT JOIN kaveri.stamparticles b ON ((a.stamparticlecode = b.stamparticlecode)))
     LEFT JOIN kaveri.application_for_scrutiny_property_master afspm ON ((a.propertyid = afspm.propertyid)))
     LEFT JOIN LATERAL ( SELECT pn.propertyid,
            pn.srocode,
            pn.currentpropertytypeid,
            pn.currentnumber,
            pn.oldpropertytypeid,
            pn.oldnumber,
            pn.description,
            pn.survey_no,
            pn.surnoc,
            pn.hissa_no
           FROM kaveri.propertynumberdetails pn
          WHERE (pn.propertyid = a.propertyid)
         LIMIT 1) l ON ((a.propertyid = l.propertyid)))
     LEFT JOIN ( SELECT pn2.currentpropertytypeid,
            pn2.propertyid
           FROM kaveri.propertynumberdetails pn2
          WHERE (pn2.currentpropertytypeid = ANY (ARRAY[65, 60, 1, 59, 61]))) pnn ON ((a.propertyid = pnn.propertyid)))
     LEFT JOIN kaveri.propertynotypemaster pt ON ((pt.propertytypeid = l.currentpropertytypeid)))
     LEFT JOIN kaveri.villagemaster d ON ((a.villagecode = d.villagecode)))
     LEFT JOIN kaveri.measunitmaster e ON ((a.unitid = e.unitid)))
     LEFT JOIN kaveri.stamprules f ON ((a.stampruleid = f.stampruleid)))
     LEFT JOIN kaveri.talukmaster i ON ((i.talukcode = d.talukcode)))
     LEFT JOIN kaveri.districtmaster g ON ((i.districtcode = g.districtcode)))
     LEFT JOIN kaveri.hoblimaster h ON ((d.hoblicode = h.hoblicode)))
