--
-- Name: vw_fetch_property_data_from_bhoomi; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_property_data_from_bhoomi AS
 SELECT DISTINCT pm.documentid,
    pnd.survey_no,
    pnd.hissa_no,
    b.ownername,
    r.relatione AS relationship,
    b.relativename,
    b.transactextacre,
    b.transactextgunta,
    b.transactextfgunta,
    b.applicationnumber,
    b.srocode,
    s.sronamee AS sroname,
    ptm.propertytypename,
    sa.articlenamee AS stampartcileselected,
    sr.descriptione AS stampsubartcleselected,
    c.villagenamee,
    c.villagecode,
    f.taluknamee,
    f.talukcode,
    d.districtnamee,
    d.districtcode,
    e.hoblinamee,
    e.hoblicode,
    b.ispresenter,
    b.isexecutor
   FROM ((((((((((((kaveri.applicantapplicationdetails ad
     JOIN kaveri.propertymaster pm ON (((ad.applicationnumber)::text = (pm.applicationnumber)::text)))
     JOIN kaveri.propertynumberdetails pnd ON ((pm.propertyid = pnd.propertyid)))
     JOIN ( SELECT string_agg((((((partyinfo.firstname)::text || ' '::text) || (partyinfo.middlename)::text) || ' '::text) || (partyinfo.lastname)::text), ','::text) AS ownername,
            string_agg((partyinfo.relationship)::text, ','::text) AS relationship,
            string_agg((partyinfo.relativename)::text, ','::text) AS relativename,
            partyinfo.transactextacre,
            partyinfo.transactextgunta,
            partyinfo.villagecode,
            partyinfo.districtcode,
            partyinfo.hoblicode,
            partyinfo.talukcode,
            partyinfo.transactextfgunta,
            partyinfo.applicationnumber,
            partyinfo.srocode,
            partyinfo.ispresenter,
            partyinfo.isexecutor
           FROM kaveri.partyinfo
          WHERE ((partyinfo.partytypeid = 1) AND (partyinfo.isexecutor = true))
          GROUP BY partyinfo.isexecutor, partyinfo.ispresenter, partyinfo.transactextacre, partyinfo.transactextgunta, partyinfo.villagecode, partyinfo.districtcode, partyinfo.hoblicode, partyinfo.talukcode, partyinfo.transactextfgunta, partyinfo.applicationnumber, partyinfo.srocode) b ON (((b.applicationnumber)::text = (ad.applicationnumber)::text)))
     LEFT JOIN kaveri.villagemaster c ON ((c.villagecode = b.villagecode)))
     LEFT JOIN kaveri.districtmaster d ON ((b.districtcode = d.districtcode)))
     LEFT JOIN kaveri.hoblimaster e ON ((b.hoblicode = e.hoblicode)))
     LEFT JOIN kaveri.talukmaster f ON ((f.talukcode = b.talukcode)))
     LEFT JOIN kaveri.propertytypemaster ptm ON ((ptm.propertytypeid = pm.propertytypeid)))
     LEFT JOIN kaveri.stamprules sr ON ((sr.stampruleid = pm.stampruleid)))
     LEFT JOIN kaveri.stamparticles sa ON ((sa.stamparticlecode = sr.stamparticlecode)))
     LEFT JOIN kaveri.relationshipmasters r ON ((r.id = (b.relationship)::integer)))
     LEFT JOIN kaveri.sromaster s ON ((s.srocode = b.srocode)));


ALTER TABLE kaveri.vw_fetch_property_data_from_bhoomi OWNER TO postgres;

