            ELSE false
        END AS isbdaproperty,
        CASE
            WHEN ((party.countofparty = 1) AND (a.stamparticlecode = 76)) THEN party.isprivateattendance
            ELSE false
        END AS iswillpvtattendance,
        CASE
            WHEN ((party.countofparty = 1) AND (a.stamparticlecode = 76)) THEN party.partyid
            ELSE (0)::bigint
        END AS partyidpvtattendance
   FROM (((((((((((((kaveri.propertymaster a
     LEFT JOIN kaveri.sromaster c ON ((a.srocode = c.srocode)))
