     LEFT JOIN ( SELECT pn2.currentpropertytypeid,
            pn2.propertyid
           FROM kaveri.propertynumberdetails pn2
          WHERE (pn2.currentpropertytypeid = ANY (ARRAY[65, 60, 1]))) pnn ON ((a.propertyid = pnn.propertyid)))
     LEFT JOIN kaveri.propertynotypemaster pt ON ((pt.propertytypeid = l.currentpropertytypeid)))
     LEFT JOIN kaveri.villagemaster d ON ((a.villagecode = d.villagecode)))
     LEFT JOIN kaveri.measunitmaster e ON ((a.unitid = e.unitid)))
     LEFT JOIN kaveri.stamprules f ON ((a.stampruleid = f.stampruleid)))
