     LEFT JOIN kaveri.hoblimaster h ON ((d.hoblicode = h.hoblicode)))
     LEFT JOIN kaveri.roadmaster r ON ((a.roadcode = r.roadcode)))
     LEFT JOIN party ON (((a.applicationnumber)::text = (party.applicationnumber)::text)))
  WHERE (a.ismovableproperty = true)
