CREATE VIEW kaveri.vw_fetch_property_number_search_key AS
 SELECT a.propertyid,
    a.srocode,
    d.hoblicode,
    a.villagecode,
    d.villagenamee AS village,
    b.currentpropertytypeid,
    c.typenameenglish AS currentpropertytype,
    b.currentnumber,
    b.oldpropertytypeid,
    c.typenameenglish AS oldpropertytype,
    b.oldnumber,
    b.survey_no,
    b.surnoc,
    b.hissa_no
   FROM (((kaveri.propertymaster a
     JOIN kaveri.propertynumberdetails b ON ((a.propertyid = b.propertyid)))
     JOIN kaveri.propertynotypemaster c ON ((b.currentpropertytypeid = c.propertytypeid)))
     JOIN kaveri.villagemaster d ON ((a.villagecode = d.villagecode)));


