--
-- Name: vw_fetch_property_schedules; Type: VIEW; Schema: kaveri; Owner: raghavendrap
--

CREATE VIEW kaveri.vw_fetch_property_schedules AS
 SELECT a.scheduleid,
    a.propertyid,
    b.srocode,
    c.sronamee,
    b.villagecode,
    g.villagenamee,
    a.partyid,
    a.scheduletype,
    a.totalarea,
    a.unitid,
    f.descriptionenglish,
    a.description,
    a.partyids,
    a.aileniatedauthorityid,
    a.alieniatedorder,
    a.bhoomisellerpartyids,
    a.govtrestricorder,
    a.govtrestrictionid,
    a.landcode,
    a.propertygroup,
    a.giftshare,
    a.giftsharedetails,
    a.easttowest,
    a.northtosouth,
    a.northboundary,
    a.southboundary,
    a.eastboundary,
    a.westboundary,
    a.blockchainpropertyid,
    a.assignedblockchainpid,
    a.applicationnumber,
    a.verified,
    b.issroapproved,
    b.propertytypeid,
    b.ismovableproperty,
    ( SELECT p.transactextacre
           FROM kaveri.partyinfo p
          WHERE ((p.propertyid = b.propertyid) AND (p.partytypeid =
                CASE
                    WHEN (sf.isownertobeclaimant = true) THEN 1
                    ELSE 2
                END))
         LIMIT 1) AS transactextacre,
    ( SELECT p.transactextgunta
           FROM kaveri.partyinfo p
          WHERE ((p.propertyid = b.propertyid) AND (p.partytypeid =
                CASE
                    WHEN (sf.isownertobeclaimant = true) THEN 1
                    ELSE 2
                END))
         LIMIT 1) AS transactextgunta,
    ( SELECT p.transactextfgunta
           FROM kaveri.partyinfo p
          WHERE ((p.propertyid = b.propertyid) AND (p.partytypeid =
                CASE
                    WHEN (sf.isownertobeclaimant = true) THEN 1
                    ELSE 2
                END))
         LIMIT 1) AS transactextfgunta
   FROM (((((kaveri.propertyschedules a
     JOIN kaveri.propertymaster b ON ((a.propertyid = b.propertyid)))
     JOIN kaveri.sromaster c ON ((b.regsrocode = c.srocode)))
     JOIN kaveri.measunitmaster f ON ((a.unitid = f.unitid)))
     JOIN kaveri.villagemaster g ON ((b.villagecode = g.villagecode)))
     LEFT JOIN kaveri.stamprulesflag sf ON ((sf.stampruleid = b.stampruleid)))
  WHERE (a.propertyid = b.propertyid)
  ORDER BY a.scheduleid;


ALTER TABLE kaveri.vw_fetch_property_schedules OWNER TO raghavendrap;

