--
-- Name: vw_fetch_reuploadjslip; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_reuploadjslip AS
 SELECT sub.documentid,
    sub.srocode,
    sub.bookid,
    sub.regarticlecode,
    sub.applicationnumber,
    sub.finalregistrationnumber,
    sub.registrationdatetime,
    sub.acknowledgeno,
    sub.remarks,
    sub.jslipsuccess,
    sub.createddate AS uploaddate
   FROM ( SELECT DISTINCT dm.documentid,
            dm.srocode,
            dm.bookid,
            dm.regarticlecode,
            dm.applicationnumber,
            dm.finalregistrationnumber,
            dm.registrationdatetime,
            COALESCE(bf.acknowledgeno, '0'::character varying(8000)) AS acknowledgeno,
            bf.remarks,
            bf.createddate,
                CASE
                    WHEN ((bf.remarks)::text = ANY (ARRAY[('Already Saved'::character varying)::text, ('Saved'::character varying)::text])) THEN true
                    ELSE false
                END AS jslipsuccess,
            dense_rank() OVER (PARTITION BY bf.finalregistrationnumber ORDER BY bf.acknowledgeno DESC NULLS LAST, bf.createddate DESC NULLS LAST) AS rank1
           FROM (((kaveri.documentmaster dm
             LEFT JOIN kaveri.bhoomifileuploaddetails bf ON (((dm.finalregistrationnumber)::text = (bf.finalregistrationnumber)::text)))
             LEFT JOIN kaveri.propertymaster pm ON ((dm.documentid = pm.documentid)))
             LEFT JOIN kaveri.stamprulesflag s ON ((pm.stampruleid = s.stampruleid)))
          WHERE ((dm.isregistrationcompleted = true) AND (pm.propertytypeid = 17) AND (s.isjslipagri IS TRUE))) sub
  WHERE (sub.rank1 = 1);


ALTER TABLE kaveri.vw_fetch_reuploadjslip OWNER TO postgres;

