--
-- Name: vw_fetch_reuploadjslip_eswatuxml; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_reuploadjslip_eswatuxml AS
 SELECT sub.documentid,
    sub.srocode,
    sub.bookid,
    sub.regarticlecode,
    sub.applicationnumber,
    sub.finalregistrationnumber,
    sub.registrationdatetime,
    sub.acknowledgeno,
    sub.remarks,
    sub.createddate AS uploaddate,
    sub.currentpropertytypeid
   FROM ( SELECT DISTINCT dm.documentid,
            dm.srocode,
            dm.bookid,
            dm.regarticlecode,
            dm.applicationnumber,
            dm.finalregistrationnumber,
            dm.registrationdatetime,
            COALESCE(bf.acknowledgeno, '0'::character varying(8000)) AS acknowledgeno,
            bf.remarks,
            bf.createddate,
            dense_rank() OVER (PARTITION BY bf.finalregistrationnumber ORDER BY bf.acknowledgeno DESC NULLS LAST, bf.createddate DESC NULLS LAST) AS rank1,
            p.currentpropertytypeid
           FROM ((((kaveri.documentmaster dm
             LEFT JOIN kaveri.easthi_eswathu_fileuploaddetails bf ON (((dm.finalregistrationnumber)::text = (bf.finalregistrationnumber)::text)))
             LEFT JOIN kaveri.propertymaster pm ON ((dm.documentid = pm.documentid)))
             LEFT JOIN kaveri.stamprulesflag s ON ((pm.stampruleid = s.stampruleid)))
             LEFT JOIN kaveri.propertynumberdetails p ON ((pm.propertyid = p.propertyid)))
          WHERE ((dm.isregistrationcompleted = true) AND (pm.propertytypeid = 28) AND (p.currentpropertytypeid = ANY (ARRAY[59, 60, 65])))) sub
  WHERE (sub.rank1 = 1);


ALTER TABLE kaveri.vw_fetch_reuploadjslip_eswatuxml OWNER TO postgres;

