CREATE VIEW kaveri.vw_fetch_rule_17_deo_dashboard AS
 SELECT DISTINCT ad.applicationnumber AS applicationnum,
    COALESCE((ad.applicationdate)::date, (ad.applicationstartdate)::date) AS applicationdate,
    ad.regsrocode,
    rf.srocode,
    ad.applicationtypeid,
    sm.servicename,
    ad.currentstatus,
    wm.wrkflowstatusnamee,
    ad.sfdaid,
    usr.username,
    ad.deoid,
    ad.applicationstartdate,
    rf.registrationarticle
   FROM ((((kaveri.applicantapplicationdetails ad
     JOIN kaveri.rule17filing rf ON (((rf.applicationnumber)::text = (ad.applicationnumber)::text)))
     LEFT JOIN kaveri.vw_department_users usr ON ((usr.userid = ad.deoid)))
     LEFT JOIN kaveri.wrkflowmaster wm ON (((wm.wrkflowstatusid)::text = (ad.currentstatus)::text)))
     LEFT JOIN kaveri.servicesmaster sm ON ((ad.applicationtypeid = sm.serviceid)))
  WHERE (ad.applicationtypeid = 52)
  GROUP BY ad.applicationnumber, ad.applicationstartdate, ad.applicationdate, ad.regsrocode, rf.srocode, ad.applicationtypeid, sm.servicename, ad.currentstatus, wm.wrkflowstatusnamee, ad.sfdaid, usr.username, ad.deoid, rf.registrationarticle
  ORDER BY ad.applicationstartdate DESC;


