--
-- Name: vw_fetch_section68_property_return_string; Type: VIEW; Schema: kaveri; Owner: raghavendrap
--

CREATE VIEW kaveri.vw_fetch_section68_property_return_string AS
 SELECT tab1.propertyid,
    (tab1.col1 || tab2.col1) AS propertydescription,
    tab3.col1 AS footnotefordesc
   FROM ( SELECT a.propertyid,
            (((((((((((((((((((('(Village)'::text || (COALESCE(b.villagenamee, ''::character varying))::text) || ', '::text) || COALESCE(tab3_1.typenameenglish, ''::text)) || '. '::text) || COALESCE(tab3_1.currentnumber, ''::text)) || ', '::text) || (COALESCE(c.hoblinamee, ''::character varying))::text) || ', '::text) || (COALESCE(d.taluknamee, ''::character varying))::text) || ', '::text) || (COALESCE(e.districtnamee, ''::character varying))::text) || ',(North)'::text) || (COALESCE(a.northboundary, ''::character varying))::text) || ',(South)'::text) || (COALESCE(a.southboundary, ''::character varying))::text) || ',(East)'::text) || (COALESCE(a.eastboundary, ''::character varying))::text) || ',(West)'::text) || (COALESCE(a.westboundary, ''::character varying))::text) || ', '::text) AS col1
           FROM (((((kaveri.propertymaster a
             JOIN kaveri.villagemaster b ON ((a.villagecode = b.villagecode)))
             JOIN kaveri.hoblimaster c ON ((b.hoblicode = c.hoblicode)))
             JOIN kaveri.talukmaster d ON ((c.talukcode = d.talukcode)))
             JOIN kaveri.districtmaster e ON ((d.districtcode = e.districtcode)))
             JOIN ( SELECT g.propertyid,
                    array_to_string(array_agg(h.typenameenglish), ','::text) AS typenameenglish,
                    array_to_string(array_agg(g.currentnumber), ','::text) AS currentnumber
                   FROM (kaveri.propertynotypemaster h
                     JOIN kaveri.propertynumberdetails g ON ((h.propertytypeid = g.currentpropertytypeid)))
                  GROUP BY g.propertyid) tab3_1 ON ((a.propertyid = tab3_1.propertyid)))) tab1,
    ( SELECT f.propertyid,
            ('Private Property Note :'::text || array_to_string(array_agg(((('(Schedule '::text || (COALESCE(f.scheduletype, ''::character varying))::text) || ') '::text) || (COALESCE(f.description, ''::character varying))::text)), ','::text)) AS col1
           FROM kaveri.propertyschedules f
          GROUP BY f.propertyid) tab2,
    ( SELECT pm.propertyid,
            ((((('as per the order number '::text || (o.ordernumber)::text) || ' dated '::text) || to_char(o.orderdate, 'dd-mm-yyyy'::text)) || ' by District Registrar '::text) || (d.districtnamee)::text) AS col1
           FROM (((kaveri.propertymaster pm
             LEFT JOIN kaveri.documentmaster dm ON ((pm.documentid = dm.documentid)))
             LEFT JOIN kaveri.dec_drordermaster o ON ((dm.documentid = o.documentid)))
             LEFT JOIN kaveri.districtmaster d ON ((o.districtcode = d.districtcode)))) tab3
  WHERE ((tab1.propertyid = tab2.propertyid) AND (tab3.propertyid = tab1.propertyid));


ALTER TABLE kaveri.vw_fetch_section68_property_return_string OWNER TO raghavendrap;

--
-- Name: vw_fetch_section68_property_details; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_section68_property_details AS
 SELECT DISTINCT a.propertyid,
    c.srocode,
    c.documentid,
    c.documentnumber,
    c.bookid,
    ((((to_char(c.executiondatetime, 'YYYY'::text))::bigint - 1) || '-'::text) || (to_char(c.executiondatetime, 'YYYY'::text))::bigint) AS financialyear,
        CASE
            WHEN (vs.footnotefordesc IS NOT NULL) THEN ((vs.propertydescription || '##'::text) || vs.footnotefordesc)
            ELSE vs.propertydescription
        END AS propertydescription,
    c.executiondatetime AS executiondate,
    a.stampruleid,
    d.descriptione AS natureofdocument,
    ( SELECT array_to_string(array_agg((((COALESCE(p1.firstname, ''::character varying))::text || (COALESCE(p1.middlename, ''::character varying))::text) || (COALESCE(p1.lastname, ''::character varying))::text)), ', '::text) AS claimantname
           FROM kaveri.partyinfo p1
          WHERE (((p1.applicationnumber)::text = (c.applicationnumber)::text) AND (p1.partytypeid = 1))) AS claimant,
    ( SELECT array_to_string(array_agg((((COALESCE(p1.firstname, ''::character varying))::text || (COALESCE(p1.middlename, ''::character varying))::text) || (COALESCE(p1.lastname, ''::character varying))::text)), ', '::text) AS executantname
           FROM kaveri.partyinfo p1
          WHERE (((p1.applicationnumber)::text = (c.applicationnumber)::text) AND (p1.partytypeid = 2))) AS executant,
    a.sronoofscanpages AS pagecount,
    ap.deedattachpath,
    c.finalregistrationnumber
   FROM ((((((kaveri.propertymaster a
     JOIN kaveri.propertynumberdetails b ON ((a.propertyid = b.propertyid)))
     JOIN kaveri.documentmaster c ON (((a.documentid = c.documentid) AND ((a.applicationnumber)::text = (c.applicationnumber)::text))))
     JOIN kaveri.applicantapplicationdetails ap ON (((ap.applicationnumber)::text = (c.applicationnumber)::text)))
     JOIN kaveri.stamprules d ON (((a.stamparticlecode = d.stamparticlecode) AND (a.stampruleid = d.stampruleid))))
     JOIN kaveri.propertyschedules f ON ((b.propertyid = f.propertyid)))
     LEFT JOIN kaveri.vw_fetch_section68_property_return_string vs ON ((a.propertyid = vs.propertyid)));


ALTER TABLE kaveri.vw_fetch_section68_property_details OWNER TO postgres;

--
-- Name: vw_fetch_selected_party_details; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_selected_party_details AS
 SELECT a.ordernumber,
    a.orderid,
    a.orderdate,
    c.partytypeid,
    c.descriptioninenglish AS partytype,
    d.partyid,
    d.firstname,
    d.middlename,
    d.lastname,
    e.note_preparedpart AS ordernote
   FROM ((((kaveri.dec_drordermaster a
     JOIN kaveri.documentmaster b ON ((a.documentid = b.documentid)))
     JOIN kaveri.partyinfo d ON ((((b.applicationnumber)::text = (d.applicationnumber)::text) AND (d.partytypeid = ANY (ARRAY[1, 2])))))
     JOIN kaveri.partytypemaster c ON ((d.partytypeid = c.partytypeid)))
     JOIN kaveri.dec_drpndnote e ON ((a.orderid = e.orderid)));


ALTER TABLE kaveri.vw_fetch_selected_party_details OWNER TO postgres;

--
-- Name: vw_fetch_sr_correction_requests; Type: VIEW; Schema: kaveri; Owner: csgadmin
--

CREATE VIEW kaveri.vw_fetch_sr_correction_requests AS
 SELECT a.orderid,
    a.districtcode,
    a.srocode,
    b.sronamee,
    b.sronamee AS orderrequestedbysr,
    a.documentid,
    c.finalregistrationnumber AS registrationno,
    a.orderdate AS requestdate,
    d1.note AS "Note",
    a.relativepath AS deedattachpath,
        CASE
            WHEN (a.statuscode = 0) THEN 'Pending'::text
            WHEN (a.statuscode = 1) THEN 'Drorder'::text
            WHEN (a.statuscode = 2) THEN 'Deorescan'::text
            WHEN (a.statuscode = 3) THEN 'Rescandone'::text
            WHEN (a.statuscode = 4) THEN 'Finalized'::text
            ELSE 'Finalized'::text
        END AS status
   FROM ((((kaveri.dec_drordermaster a
     JOIN kaveri.sromaster b ON ((a.srocode = b.srocode)))
     LEFT JOIN kaveri.documentmaster c ON ((a.documentid = c.documentid)))
     JOIN ( SELECT d.orderid,
            array_to_string(array_agg(d.note_enteredpart), ', '::text) AS note
           FROM kaveri.dec_drpndnote d
          GROUP BY d.orderid) d1 ON ((a.orderid = d1.orderid)))
     LEFT JOIN kaveri.ecpropertysearchkeyvalues e ON ((a.orderid = e.orderid)))
  ORDER BY a.orderid DESC;


ALTER TABLE kaveri.vw_fetch_sr_correction_requests OWNER TO csgadmin;

