    a.isaffidavitsd,
    a.ispreamptionsd,
    a.iscertifiedcopysd,
    a.isregistrationfee,
    a.isduplicaterf,
    a.isconsentingfee,
    a.ismapfilingfee,
    a.ismemofee,
    a.isservicecharge,
    a.ispvtattendancefee,
    a.isrfus30,
    a.isdelaycondonationfee,
    a.isdelaycondonationfine,
    a.isappealfee,
    a.isdocumentwithdrawalfee,
    a.isholidayrf,
    a.iswilldepositfee,
    a.isfilingoftranslationfee,
    a.issafecustodyfee,
    a.isauthenticationorattestationpoa,
    a.iswillcancellation,
    a.isprevregddocnoreqd,
    a.ownertypechange,
    a.bookid
   FROM ((kaveri.vw_fetch_stamprules_flags a
     LEFT JOIN kaveri.stamparticles b ON ((b.stamparticlecode = a.stamparticlecode)))
     LEFT JOIN kaveri.bucketmaster c ON ((a.bucketid = c.bucketid)))
  WHERE ((b.stamparticlecode IS NOT NULL) AND (a.isruleactive IS TRUE) AND ((a.value > (0)::numeric) OR (a.regvalue > (0)::numeric)) AND (a.parentrefid >= '-1'::integer))
  ORDER BY b.articlenamee, (split_part((a.descriptione)::text, ')'::text, 1));


ALTER TABLE kaveri.vw_fetch_sub_articles_alp_order_bck OWNER TO postgres;

