--
-- Name: vw_fetch_ulb_districtmapping; Type: VIEW; Schema: kaveri; Owner: csgadmin
--

CREATE VIEW kaveri.vw_fetch_ulb_districtmapping AS
 SELECT DISTINCT b.districtcode AS mappeddistrictcode,
    b.districtcode,
    b.districtnamee,
    s.srocode,
    s.sronamee,
    u2.ulbcode,
    u2.ulbname
   FROM ((((kaveri.districtmaster d
     JOIN kaveri.bhoomidistrictmaster b ON ((d.bhoomidistrictcode = b.districtcode)))
     JOIN kaveri.sromaster s ON ((s.districtcode = d.districtcode)))
     JOIN kaveri.ulbmapping u ON ((u.srocode = s.srocode)))
     JOIN kaveri.ulbmaster u2 ON ((u2.ulbcode = u.ulbcode)))
  WHERE (u2.ulbcode <> 555)
UNION
 SELECT 555 AS mappeddistrictcode,
    b.districtcode,
    b.districtnamee,
    s.srocode,
    s.sronamee,
    u2.ulbcode,
    u2.ulbname
   FROM ((((kaveri.districtmaster d
     JOIN kaveri.bhoomidistrictmaster b ON ((d.bhoomidistrictcode = b.districtcode)))
     JOIN kaveri.sromaster s ON ((s.districtcode = d.districtcode)))
     JOIN kaveri.ulbmapping u ON ((u.srocode = s.srocode)))
     JOIN kaveri.ulbmaster u2 ON ((u2.ulbcode = u.ulbcode)))
  WHERE (u2.ulbcode = 555);


ALTER TABLE kaveri.vw_fetch_ulb_districtmapping OWNER TO csgadmin;

--
-- Name: vw_fetch_under_68_order_from_dr; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_under_68_order_from_dr AS
 SELECT a.srocode,
    a.orderid,
    a.finalregistrationnumber,
    c.documentnumber,
    c.documentid,
    a.ordernumber AS drordernumber,
    to_char(a.orderdate, 'YYYY/MM/DD'::text) AS orderdate,
    a.insertdatetime AS orderuploaddate,
    a.absolutefilepath AS deedattachpath,
    a.statuscode,
    a.correctionnote,
    a.documentrescan,
    a.rescannoofpages,
        CASE
            WHEN ((a.correctionnote = true) AND (a.documentrescan = false)) THEN 'Document noting'::text
            WHEN ((a.correctionnote = false) AND (a.documentrescan = true)) THEN 'Document Rescan'::text
            WHEN ((a.correctionnote = true) AND (a.documentrescan = true)) THEN 'Both'::text
            ELSE NULL::text
        END AS scope,
        CASE
            WHEN (a.statuscode = 0) THEN 'F'::text
            WHEN (a.statuscode = 1) THEN 'DRO Added an Order'::text
            WHEN (a.statuscode = 2) THEN 'Assigned to DEO for Rescan'::text
            WHEN (a.statuscode = 3) THEN 'Rescan Completed'::text
            WHEN (a.statuscode = 4) THEN 'F'::text
            ELSE NULL::text
        END AS actiontype,
    a.sroid,
    a.deoid,
        CASE
            WHEN (a.deoid IS NOT NULL) THEN ( SELECT concat(u.firstname, ' ', u.middlename, u.lastname) AS concat)
            ELSE 'NA'::text
        END AS name,
        CASE
            WHEN (( SELECT s.keyid
               FROM kaveri.ecpropertysearchkeyvalues s
              WHERE (s.orderid = a.orderid)
             LIMIT 1) IS NOT NULL) THEN true
            ELSE false
        END AS propertysearchdone,
        CASE
            WHEN (( SELECT s.keyid
               FROM kaveri.ecnamesearchkeyvalues s
              WHERE (s.orderid = a.orderid)
             LIMIT 1) IS NOT NULL) THEN true
            ELSE false
        END AS partysearchdone,
        CASE
            WHEN (( SELECT s.noteid
               FROM kaveri.dec_drpndnote s
              WHERE (s.orderid = a.orderid)
             LIMIT 1) IS NOT NULL) THEN true
            ELSE false
        END AS notingdone,
        CASE
            WHEN (( SELECT s.note_enteredpart
               FROM kaveri.dec_drpndnote s
              WHERE (s.orderid = a.orderid)
             LIMIT 1) IS NOT NULL) THEN (( SELECT s.note_enteredpart
               FROM kaveri.dec_drpndnote s
              WHERE (s.orderid = a.orderid)
             LIMIT 1))::text
            ELSE ''::text
        END AS noting,
        CASE
            WHEN (( SELECT s.noteid
               FROM kaveri.dec_drpndnote s
              WHERE (s.orderid = a.orderid)
             LIMIT 1) IS NOT NULL) THEN (( SELECT s.noteid
               FROM kaveri.dec_drpndnote s
              WHERE (s.orderid = a.orderid)
             LIMIT 1))::text
            ELSE NULL::text
        END AS noteid,
        CASE
            WHEN (( SELECT s.note_enteredpart
               FROM kaveri.dec_drpndnote s
              WHERE (s.orderid = a.orderid)
             LIMIT 1) IS NOT NULL) THEN (( SELECT s.note_enteredpart
               FROM kaveri.dec_drpndnote s
              WHERE (s.orderid = a.orderid)
             LIMIT 1))::text
            ELSE NULL::text
        END AS note
   FROM ((kaveri.dec_drordermaster a
     LEFT JOIN kaveri.documentmaster c ON ((a.documentid = c.documentid)))
     LEFT JOIN kaveri.departmentusers u ON ((a.deoid = u.userid)))
  ORDER BY a.orderdate DESC;


ALTER TABLE kaveri.vw_fetch_under_68_order_from_dr OWNER TO postgres;

