--
-- Name: vw_fetch_withdrawn_application; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_withdrawn_application AS
 SELECT DISTINCT ad.applicationnumber AS applicationnum,
    dm.documentid,
    slot.slotbookdate AS applicationdate,
    slot.slotbooktime AS applicationtime,
    ad.srocode,
    ad.applicationtypeid,
    sm.servicename,
    ad.currentstatus,
    wm.wrkflowstatusnamee,
    (dm.presentdatetime)::date AS presentdate,
    (dm.executiondatetime)::date AS executedate,
    dm.pendingdocumentnumber,
    dm.finalregistrationnumber,
    dm.isprintsummary,
    dm.isprintendorsement,
    dm.isuploaddocuments,
    dm.isdigitalsigned,
    dm.isregistrationcompleted,
    ad.sfdaid,
    sfda.username AS sfdaname,
    ad.deoid,
    deo.username AS deoname,
    dm.gscno AS sakalanumber,
    dm.uploadsummarydocpath,
    dm.uploaddocdeedpath,
    rg.articlenamee,
        CASE
            WHEN ((ad.applicationnumber)::text = (fk.applicationnumber)::text) THEN true
            ELSE false
        END AS ispaymentdone,
    ( SELECT am.deptreferencecode
           FROM (kaveri.ams_reg_epaymenttransdetails am
             JOIN kaveri.ams_reg_epaymentbankackdetails an ON (((am.deptreferencecode)::text = (an.deptreferencecode)::text)))
          WHERE (((am.applicationnumber)::text = (ad.applicationnumber)::text) AND ((an.paymentstatuscode)::text = ANY (ARRAY['10700066'::text, '10700072'::text])))
          ORDER BY am.inserteddatetime DESC
         LIMIT 1) AS deptreferencecode
   FROM ((((((((kaveri.applicantapplicationdetails ad
     LEFT JOIN kaveri.documentmaster dm ON (((ad.applicationnumber)::text = (dm.applicationnumber)::text)))
     LEFT JOIN ( SELECT sl.applicationnumber,
            sl.appointmentdate AS sltbookedon,
            (sl.appointmentdate)::date AS slotbookdate,
            ((sl.starttime || '-'::text) || (sl.endtime)::text) AS slotbooktime
           FROM kaveri.appointmentmaster sl
          WHERE ((sl.status)::text = ANY (ARRAY[('1'::character varying)::text, ('Pending'::character varying)::text]))) slot ON (((slot.applicationnumber)::text = (ad.applicationnumber)::text)))
     LEFT JOIN kaveri.vw_department_users deo ON ((deo.userid = ad.deoid)))
     LEFT JOIN kaveri.registrationarticles rg ON ((rg.regarticlecode = dm.regarticlecode)))
     LEFT JOIN kaveri.vw_department_users sfda ON ((sfda.userid = ad.sfdaid)))
     LEFT JOIN kaveri.wrkflowmaster wm ON (((wm.wrkflowstatusid)::text = (ad.currentstatus)::text)))
     LEFT JOIN kaveri.servicesmaster sm ON ((ad.applicationtypeid = sm.serviceid)))
     LEFT JOIN kaveri.feesrequired_paymentchk fk ON (((ad.applicationnumber)::text = (fk.applicationnumber)::text)))
  WHERE ((ad.currentstatus)::text = ANY (ARRAY[('CD135'::character varying)::text, 'CD136'::text]));


ALTER TABLE kaveri.vw_fetch_withdrawn_application OWNER TO postgres;

--
-- Name: vw_fetch_witness; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_witness AS
 SELECT (0)::bigint AS partyid,
    pw.partyname,
    a.witnessid,
    concat(a.name, a.middlename, a.lastname) AS witnessname,
    3 AS partytypeid,
    'Consenting Witness'::text AS partytypename,
    a.applicationnumber,
    a.name,
    a.sex,
    a.age,
    a.relation,
    rel.relatione AS relationtype,
    a.relativename,
    a.profession,
    a.districtcode,
    a.talukcode,
    0 AS hoblicode,
    0 AS villagecode,
    ((((((a.address)::text || ', '::text) || ((g.taluknamee)::text || ', '::text)) || ((d.districtnamee)::text || ', '::text)) || ((s.statenamee)::text || ' '::text)) || ' '::text) AS address,
    a.pincode,
    a.houseno,
    a.isendorsementsigned,
    a.isthumbregistersigned
   FROM (((((kaveri.witnessinfo a
     LEFT JOIN ( SELECT b.witnessid,
            pi.applicationnumber,
            string_agg(concat_ws(' '::text, pi.firstname, pi.middlename, pi.lastname), ','::text ORDER BY pi.partyid) AS partyname
           FROM (kaveri.partywitness b
             LEFT JOIN kaveri.partyinfo pi ON ((pi.partyid = b.partyid)))
          GROUP BY b.witnessid, pi.applicationnumber) pw ON (((a.witnessid = pw.witnessid) AND ((pw.applicationnumber)::text = (a.applicationnumber)::text))))
     LEFT JOIN kaveri.relationshipmasters rel ON (((rel.id)::text = (a.relation)::text)))
     LEFT JOIN kaveri.lgd_districtmaster d ON ((d.districtcode = a.districtcode)))
     LEFT JOIN kaveri.lgd_statemaster s ON ((d.lgdstatecode = s.statecode)))
     LEFT JOIN kaveri.lgd_talukmaster g ON ((g.talukcode = a.talukcode)));


ALTER TABLE kaveri.vw_fetch_witness OWNER TO postgres;

