-- Name: vw_fetch_witnessdetails; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_fetch_witnessdetails AS
 SELECT p.witnessid,
    p.salutation,
    p.firstname,
    p.middlename,
    p.lastname,
    p.dob,
    p.age,
    p.email,
    p.phoneno,
    p.perhouseno,
    p.perstreetaddress,
    p.perstatecode,
    p.perdistrictcode,
    p.pertalukacode,
    p.perhoblicode,
    p.pervillagecode,
    p.perpincode,
    p.iscurrentaddresssameaspermanent,
    p.currenthouseno,
    p.currentstreetaddress,
    p.currrentstatecode,
    p.currentdistrictcode,
    p.currenttalukacode,
    p.currenthoblicode,
    p.currentvillagecode,
    p.currentpincode,
    p.relationid,
    p.status,
    p.verified,
    p.isapproved,
    p.inserteddate,
    p.applicationnumber,
    p.genderid,
    p.registrationid,
    p.k1k2_flag,
    p.digisignpath,
    p.witnessrelatedto,
    fun.statenamee AS perstatenamee,
    fun.districtnamee AS perdistrictnamee,
    fun.taluknamee AS pertaluknamee,
    fun.hoblinamee AS perhoblinamee,
    fun.villagenamee AS pervillagenamee,
    fun1.statenamee AS currstatename,
    fun1.districtnamee AS currdistrictname,
    fun1.taluknamee AS currtalukname,
    fun1.hoblinamee AS currhobliname,
    fun1.villagenamee AS currvillagename
   FROM ((kaveri.marriagewitnessinfo p
     JOIN LATERAL kaveri.fn_fetch_marriage_lgdmaster1(p.perstatecode, p.perdistrictcode, p.pertalukacode, p.perhoblicode, (p.pervillagecode)::bigint) fun(statecode, statenamee, districtcode, districtnamee, talukcode, taluknamee, hoblicode, hoblinamee, villagecode, villagenamee) ON ((p.perstatecode = fun.statecode)))
     JOIN LATERAL kaveri.fn_fetch_marriage_lgdmaster1(p.currrentstatecode, p.currentdistrictcode, p.currenttalukacode, p.currenthoblicode, (p.currentvillagecode)::bigint) fun1(statecode, statenamee, districtcode, districtnamee, talukcode, taluknamee, hoblicode, hoblinamee, villagecode, villagenamee) ON ((p.currrentstatecode = fun1.statecode)));


ALTER TABLE kaveri.vw_fetch_witnessdetails OWNER TO postgres;

