-- Name: vw_get_vaultid_excel; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_get_vaultid_excel AS
 WITH latest_auth AS (
         SELECT DISTINCT ON (aal.aadharhash) aal.aadharhash,
            aal.vault_id
           FROM kaveri.aadhar_authentication_log_citizen aal
          ORDER BY aal.aadharhash, aal.inserteddatetime DESC
        )
 SELECT pi.partyid,
    COALESCE(pi.vaultid, d.vaultrefnumber, la.vault_id) AS vaultid
   FROM ((kaveri.partyinfo pi
     LEFT JOIN kaveri.aadhaar_log_citizen_decrypt d ON ((((d.aadhaarhash)::text = (pi.aadharhash)::text) AND ((d.status)::text = 'Y'::text))))
     LEFT JOIN latest_auth la ON (((la.aadharhash)::text = (pi.aadharhash)::text)));


