--
-- Name: vw_jslip_applicationdata; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_jslip_applicationdata AS
 SELECT DISTINCT dm.documentid,
    dm.applicationnumber,
    dm.finalregistrationnumber,
    (dm.documentid || to_char(dm.registrationdatetime, 'ddMMYYYY'::text)) AS regid,
    dm.srocode,
    (dm.registrationdatetime)::date AS registrationdate,
    dm.regarticlecode,
    dmref.regarticlecode AS previousarticlecode,
    dmref.finalregistrationnumber AS previousfinalregistrationnumber,
    (dmref.registrationdatetime)::date AS previousregistrationdate,
    pm.jslipnumber,
    pm.villagecode,
    NULL::text AS correctedcolumncodes,
        CASE
            WHEN (frts.applicationnumber IS NOT NULL) THEN dm.considerationamount
            ELSE ( SELECT sum(pmm.consideration) AS sum
               FROM kaveri.propertymaster pmm
              WHERE ((pmm.applicationnumber)::text = (dm.applicationnumber)::text))
        END AS cost,
    ( SELECT string_agg(DISTINCT (feesrequired.receiptid)::text, ' ,'::text) AS receiptid
           FROM kaveri.feesrequired
          WHERE ((feesrequired.documentid = dm.documentid) AND (feesrequired.receiptid IS NOT NULL))) AS receiptnumber,
    pm.stampruleid
   FROM (((kaveri.documentmaster dm
     JOIN ( SELECT propertymaster.applicationnumber,
            propertymaster.documentid,
            propertymaster.villagecode,
            propertymaster.stampruleid,
            dense_rank() OVER (PARTITION BY propertymaster.documentid ORDER BY propertymaster.villagecode) AS jslipnumber
           FROM kaveri.propertymaster
          WHERE (propertymaster.propertytypeid = 17)) pm ON (((pm.documentid = dm.documentid) AND ((dm.applicationnumber)::text = (pm.applicationnumber)::text))))
     LEFT JOIN kaveri.documentmaster dmref ON ((dmref.documentid = dm.correctionreference)))
     LEFT JOIN kaveri.fruits_data_recv_details frts ON (((frts.applicationnumber)::text = (dm.applicationnumber)::text)));


ALTER TABLE kaveri.vw_jslip_applicationdata OWNER TO postgres;

--
-- Name: vw_jslip_applicationdetails; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_jslip_applicationdetails AS
 SELECT DISTINCT dm.documentid,
    dm.applicationnumber,
    dm.finalregistrationnumber,
    (dm.documentid || to_char(dm.registrationdatetime, 'ddMMYYYY'::text)) AS regid,
    dm.srocode,
    (dm.registrationdatetime)::date AS registrationdate,
    dm.regarticlecode,
    dmref.regarticlecode AS previousarticlecode,
    dmref.finalregistrationnumber AS previousfinalregistrationnumber,
    (dmref.registrationdatetime)::date AS previousregistrationdate,
    pm.jslipnumber,
    pm.villagecode,
    NULL::text AS correctedcolumncodes,
        CASE
            WHEN (frts.applicationnumber IS NOT NULL) THEN dm.considerationamount
            ELSE ( SELECT sum(pmm.consideration) AS sum
               FROM kaveri.propertymaster pmm
              WHERE ((pmm.applicationnumber)::text = (dm.applicationnumber)::text))
        END AS cost,
    ( SELECT string_agg(DISTINCT (feesrequired.receiptid)::text, ' ,'::text) AS receiptid
           FROM kaveri.feesrequired
          WHERE ((feesrequired.documentid = dm.documentid) AND (feesrequired.receiptid IS NOT NULL))) AS receiptnumber,
    pm.stampruleid
   FROM (((kaveri.documentmaster dm
     JOIN LATERAL ( SELECT propertymaster.applicationnumber,
            propertymaster.documentid,
            propertymaster.villagecode,
            propertymaster.stampruleid,
            dense_rank() OVER (PARTITION BY propertymaster.documentid ORDER BY propertymaster.villagecode) AS jslipnumber
           FROM kaveri.propertymaster
          WHERE (((propertymaster.applicationnumber)::text = (dm.applicationnumber)::text) AND (propertymaster.propertytypeid = 17))) pm ON (((pm.documentid = dm.documentid) AND ((dm.applicationnumber)::text = (pm.applicationnumber)::text))))
     LEFT JOIN kaveri.documentmaster dmref ON ((dmref.documentid = dm.correctionreference)))
     LEFT JOIN kaveri.fruits_data_recv_details frts ON (((frts.applicationnumber)::text = (dm.applicationnumber)::text)));


ALTER TABLE kaveri.vw_jslip_applicationdetails OWNER TO postgres;

--
-- Name: vw_jslip_applicationdetails_for_old_method; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_jslip_applicationdetails_for_old_method AS
 SELECT DISTINCT dm.documentid,
    dm.applicationnumber,
    dm.finalregistrationnumber,
    (dm.documentid || to_char(dm.registrationdatetime, 'ddMMYYYY'::text)) AS regid,
    dm.srocode,
    sro.sronamee,
    (dm.registrationdatetime)::date AS registrationdate,
    dm.regarticlecode,
    dmref.regarticlecode AS previousarticlecode,
    dmref.finalregistrationnumber AS previousfinalregistrationnumber,
    (dmref.registrationdatetime)::date AS previousregistrationdate,
    pm.jslipnumber,
    pm.villagecode,
    NULL::text AS correctedcolumncodes,
        CASE
            WHEN (frts.applicationnumber IS NOT NULL) THEN dm.considerationamount
            ELSE ( SELECT sum(pmm.consideration) AS sum
               FROM kaveri.propertymaster pmm
              WHERE ((pmm.applicationnumber)::text = (dm.applicationnumber)::text))
        END AS cost,
    fr1.receiptid AS receiptnumber
   FROM (((((kaveri.documentmaster dm
     JOIN ( SELECT propertymaster.applicationnumber,
            propertymaster.documentid,
            propertymaster.villagecode,
            dense_rank() OVER (PARTITION BY propertymaster.documentid ORDER BY propertymaster.villagecode) AS jslipnumber
           FROM kaveri.propertymaster
          WHERE (propertymaster.propertytypeid = 17)) pm ON (((pm.documentid = dm.documentid) AND ((dm.applicationnumber)::text = (pm.applicationnumber)::text))))
     LEFT JOIN ( SELECT fr.documentid,
            fr.srocode,
            array_to_string(array_agg(DISTINCT fr.receiptid), ', '::text) AS receiptid
           FROM kaveri.feesrequired fr
          WHERE (fr.receiptid IS NOT NULL)
          GROUP BY fr.documentid, fr.srocode) fr1 ON (((fr1.documentid = dm.documentid) AND (fr1.srocode = dm.srocode) AND (fr1.receiptid IS NOT NULL))))
     LEFT JOIN kaveri.documentmaster dmref ON ((dmref.documentid = dm.correctionreference)))
     LEFT JOIN kaveri.fruits_data_recv_details frts ON (((frts.applicationnumber)::text = (dm.applicationnumber)::text)))
     LEFT JOIN kaveri.sromaster sro ON (((sro.srocode)::text = (dm.srocode)::text)))
  WHERE ((dm.finalregistrationnumber IS NOT NULL) AND (dm.registrationdatetime IS NOT NULL));


ALTER TABLE kaveri.vw_jslip_applicationdetails_for_old_method OWNER TO postgres;

--
-- Name: vw_jslip_applicationdetails_for_old_method_org; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_jslip_applicationdetails_for_old_method_org AS
 SELECT DISTINCT dm.documentid,
    dm.applicationnumber,
    dm.finalregistrationnumber,
    (dm.documentid || to_char(dm.registrationdatetime, 'ddMMYYYY'::text)) AS regid,
    dm.srocode,
    sro.sronamee,
    (dm.registrationdatetime)::date AS registrationdate,
    dm.regarticlecode,
    dmref.regarticlecode AS previousarticlecode,
    dmref.finalregistrationnumber AS previousfinalregistrationnumber,
    (dmref.registrationdatetime)::date AS previousregistrationdate,
    pm.jslipnumber,
    pm.villagecode,
    NULL::text AS correctedcolumncodes,
        CASE
            WHEN (frts.applicationnumber IS NOT NULL) THEN dm.considerationamount
            ELSE ( SELECT sum(pmm.consideration) AS sum
               FROM kaveri.propertymaster pmm
              WHERE ((pmm.applicationnumber)::text = (dm.applicationnumber)::text))
        END AS cost,
    fr1.receiptid AS receiptnumber
   FROM (((((kaveri.documentmaster dm
     JOIN ( SELECT propertymaster.applicationnumber,
            propertymaster.documentid,
            propertymaster.villagecode,
            dense_rank() OVER (PARTITION BY propertymaster.documentid ORDER BY propertymaster.villagecode) AS jslipnumber
           FROM kaveri.propertymaster
          WHERE (propertymaster.propertytypeid = 17)) pm ON (((pm.documentid = dm.documentid) AND ((dm.applicationnumber)::text = (pm.applicationnumber)::text))))
     LEFT JOIN ( SELECT fr.documentid,
            fr.srocode,
            array_to_string(array_agg(DISTINCT fr.receiptid), ', '::text) AS receiptid
           FROM kaveri.feesrequired fr
          WHERE (fr.receiptid IS NOT NULL)
          GROUP BY fr.documentid, fr.srocode) fr1 ON (((fr1.documentid = dm.documentid) AND (fr1.srocode = dm.srocode) AND (fr1.receiptid IS NOT NULL))))
     LEFT JOIN kaveri.documentmaster dmref ON ((dmref.documentid = dm.correctionreference)))
     LEFT JOIN kaveri.fruits_data_recv_details frts ON (((frts.applicationnumber)::text = (dm.applicationnumber)::text)))
     LEFT JOIN kaveri.sromaster sro ON (((sro.srocode)::text = (dm.srocode)::text)))
  WHERE ((dm.finalregistrationnumber IS NOT NULL) AND (dm.registrationdatetime IS NOT NULL));


ALTER TABLE kaveri.vw_jslip_applicationdetails_for_old_method_org OWNER TO postgres;

--
-- Name: vw_jslip_applicationdetails_for_old_methods; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_jslip_applicationdetails_for_old_methods AS
 SELECT DISTINCT dm.documentid,
    dm.applicationnumber,
    dm.finalregistrationnumber,
    (dm.documentid || to_char(dm.registrationdatetime, 'ddMMYYYY'::text)) AS regid,
    pm.srocode,
    sro.sronamee,
    (dm.registrationdatetime)::date AS registrationdate,
    dm.regarticlecode,
    dmref.regarticlecode AS previousarticlecode,
    dmref.finalregistrationnumber AS previousfinalregistrationnumber,
    (dmref.registrationdatetime)::date AS previousregistrationdate,
    NULL::text AS jslipnumber,
    pm.villagecode,
    NULL::text AS correctedcolumncodes,
        CASE
            WHEN (frts.applicationnumber IS NOT NULL) THEN dm.considerationamount
            ELSE ( SELECT sum(pmm.consideration) AS sum
               FROM kaveri.propertymaster pmm
              WHERE ((pmm.applicationnumber)::text = (dm.applicationnumber)::text))
        END AS cost,
    ( SELECT (f.receiptid)::text AS receiptid
           FROM kaveri.feesrequired f
          WHERE ((f.applicationnumber)::text = (dm.applicationnumber)::text)
         LIMIT 1) AS receiptnumber
   FROM ((((kaveri.documentmaster dm
     JOIN kaveri.propertymaster pm ON ((((dm.applicationnumber)::text = (pm.applicationnumber)::text) AND (pm.propertytypeid = 17))))
     LEFT JOIN kaveri.documentmaster dmref ON ((dmref.documentid = dm.correctionreference)))
     LEFT JOIN kaveri.fruits_data_recv_details frts ON (((frts.applicationnumber)::text = (dm.applicationnumber)::text)))
     JOIN kaveri.sromaster sro ON (((sro.srocode)::text = (dm.srocode)::text)))
  WHERE ((dm.finalregistrationnumber IS NOT NULL) AND (dm.registrationdatetime IS NOT NULL));


ALTER TABLE kaveri.vw_jslip_applicationdetails_for_old_methods OWNER TO postgres;

