--
-- Name: vw_jslip_easthi_details; Type: VIEW; Schema: kaveri; Owner: csgadmin
--

CREATE VIEW kaveri.vw_jslip_easthi_details AS
 SELECT DISTINCT dm.documentid,
    dm.applicationnumber,
    dm.finalregistrationnumber,
    (dm.documentid || to_char(dm.registrationdatetime, 'ddMMYYYY'::text)) AS regid,
    dm.srocode,
    (dm.registrationdatetime)::date AS registrationdate,
    dm.regarticlecode,
    pm.jslipnumber,
    pm.propertyid,
    pm.villagecode,
    pm.stampduty,
    pm.sdrefund AS prevpropertyid,
    '3042'::text AS receiptnumber,
    'EAASTHI'::text AS jsliptype,
    '0'::text AS xmltypeforeswathu,
    '(0)'::text AS prevregid,
    0 AS prevarticlecode
   FROM ((kaveri.documentmaster dm
     JOIN ( SELECT p.applicationnumber,
            p.propertyid,
            p.documentid,
            p.villagecode,
            p.stampruleid,
            p.sdrefund,
            dense_rank() OVER (PARTITION BY p.documentid ORDER BY p.propertyid) AS jslipnumber,
            sum(p.stampduty) OVER (PARTITION BY p.documentid ORDER BY p.propertyid) AS stampduty
           FROM kaveri.propertymaster p
          WHERE ((p.propertytypeid <> 17) AND (p.propertyid IN ( SELECT pnd.propertyid
                   FROM kaveri.propertynumberdetails pnd
                  WHERE ((pnd.propertyid = p.propertyid) AND (pnd.currentpropertytypeid = ANY (ARRAY[65, 59])))
                 LIMIT 1)))) pm ON (((pm.documentid = dm.documentid) AND ((dm.applicationnumber)::text = (pm.applicationnumber)::text))))
     LEFT JOIN kaveri.vw_fetch_stamprules_flags sr ON ((pm.stampruleid = sr.stampruleid)))
  WHERE ((dm.finalregistrationnumber IS NOT NULL) AND (dm.registrationdatetime IS NOT NULL))
UNION ALL
 SELECT DISTINCT dm.documentid,
    dm.applicationnumber,
    dm.finalregistrationnumber,
    (dm.documentid || to_char(dm.registrationdatetime, 'ddMMYYYY'::text)) AS regid,
    dm.srocode,
    (dm.registrationdatetime)::date AS registrationdate,
    dm.regarticlecode,
    pm.jslipnumber,
    pm.propertyid,
    pm.villagecode,
    pm.stampduty,
    pm.sdrefund AS prevpropertyid,
    'REC02'::text AS receiptnumber,
    'ESWATHU'::text AS jsliptype,
    sr.xmltypeforeswathu,
    kd1.prevregid,
    kd1.prevarticlecode
   FROM (((kaveri.documentmaster dm
     JOIN ( SELECT p.applicationnumber,
            p.propertyid,
            p.documentid,
            p.villagecode,
            p.stampruleid,
            p.sdrefund,
            dense_rank() OVER (PARTITION BY p.documentid ORDER BY p.propertyid) AS jslipnumber,
            sum(p.stampduty) OVER (PARTITION BY p.documentid ORDER BY p.propertyid) AS stampduty
           FROM kaveri.propertymaster p
          WHERE ((p.propertytypeid <> 17) AND (p.propertyid IN ( SELECT pnd.propertyid
                   FROM kaveri.propertynumberdetails pnd
                  WHERE ((pnd.propertyid = p.propertyid) AND (pnd.currentpropertytypeid = 60)))))) pm ON (((pm.documentid = dm.documentid) AND ((dm.applicationnumber)::text = (pm.applicationnumber)::text))))
     LEFT JOIN kaveri.vw_fetch_stamprules_flags sr ON ((sr.stampruleid = pm.stampruleid)))
     LEFT JOIN kaveri.k1documentdetails kd1 ON (((kd1.applicationnumber)::text = (dm.applicationnumber)::text)))
  WHERE ((dm.finalregistrationnumber IS NOT NULL) AND (dm.registrationdatetime IS NOT NULL));


ALTER TABLE kaveri.vw_jslip_easthi_details OWNER TO csgadmin;

