--
-- Name: vw_jslip_easthi_finalproperty; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_jslip_easthi_finalproperty AS
 SELECT d.districtcode,
    d.districtnamee,
    pm.applicationnumber,
    pm.documentid,
    pm.propertyid,
    p.currentnumber,
    pm.villagecode,
    v2.villagenamee,
    pm.sdcalculationstring,
    dm.finalregistrationnumber,
    pm.totalarea,
    pm.northboundary,
    pm.southboundary,
    pm.eastboundary,
    pm.westboundary,
    flt.floorid,
    lg.xml
   FROM ((((((((kaveri.propertymaster pm
     JOIN kaveri.documentmaster dm ON (((dm.documentid = pm.documentid) AND ((dm.applicationnumber)::text = (pm.applicationnumber)::text))))
     LEFT JOIN kaveri.valuationdetails v ON ((v.propertyid = pm.propertyid)))
     LEFT JOIN kaveri.val_flatratedetails flt ON ((flt.valuationid = v.valid)))
     LEFT JOIN kaveri.eaasti_eswatuxmllog lg ON ((pm.propertyid = lg.propertyid)))
     JOIN kaveri.sromaster sm ON ((dm.srocode = sm.srocode)))
     JOIN kaveri.districtmaster d ON ((d.districtcode = sm.districtcode)))
     LEFT JOIN kaveri.villagemaster v2 ON (((dm.srocode = v2.srocode) AND (pm.villagecode = v2.villagecode))))
     JOIN kaveri.propertynumberdetails p ON ((pm.propertyid = p.propertyid)))
  WHERE ((dm.finalregistrationnumber IS NOT NULL) AND (p.currentpropertytypeid = ANY (ARRAY[60, 59, 65])));


ALTER TABLE kaveri.vw_jslip_easthi_finalproperty OWNER TO postgres;

--
-- Name: vw_jslip_surveynumberdata; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_jslip_surveynumberdata AS
 SELECT dm.documentid,
    dm.applicationnumber,
    pm.propertyid,
    dm.finalregistrationnumber,
    (dm.documentid || to_char(dm.registrationdatetime, 'ddMMYYYY'::text)) AS regid,
    v.kaverivillagecode,
    v.bhoomivillagecode AS villagecode,
    pnd.survey_no,
    pnd.hissa_no,
    pnd.surnoc,
    bhv.villagenamee AS village,
    v.bhoomihobicode AS hoblicode,
    bhm.hoblinamee AS hobli,
    btm.talukcode,
    btm.taluknamee AS taluk,
    v.bhoomidistrictcode AS districtcode,
    bdm.districtnamee AS district,
    NULL::text AS govtrestrictioncleared,
    NULL::text AS govtrestrictionid,
    NULL::text AS govtrestrictionorder,
    ps.landcode,
    sf.isownertobeclaimant,
    pnd.currentnumber
   FROM ((((((((((kaveri.documentmaster dm
     JOIN kaveri.propertymaster pm ON (((pm.propertytypeid = 17) AND (pm.documentid = dm.documentid) AND ((dm.applicationnumber)::text = (pm.applicationnumber)::text))))
     JOIN kaveri.propertynumberdetails pnd ON ((pm.propertyid = pnd.propertyid)))
     LEFT JOIN kaveri.stamprules stm ON ((pm.stampruleid = stm.stampruleid)))
     JOIN kaveri.stamprulesflag sf ON ((stm.stampruleid = sf.stampruleid)))
     JOIN kaveri.partyinfo ps ON ((ps.propertyid = pm.propertyid)))
     JOIN kaveri.bhoomimappingdetails v ON ((v.kaverivillagecode = pm.villagecode)))
     JOIN kaveri.bhoomidistrictmaster bdm ON ((v.bhoomidistrictcode = bdm.districtcode)))
     JOIN kaveri.bhoomitalukmaster btm ON (((v.bhoomitalukcode = btm.talukcode) AND (v.bhoomidistrictcode = btm.districtcode))))
     JOIN kaveri.bhoomihoblimaster bhm ON (((v.bhoomihobicode = bhm.hoblicode) AND (v.bhoomitalukcode = bhm.talukcode) AND (v.bhoomidistrictcode = bhm.districtcode))))
     JOIN kaveri.bhoomivillagemaster bhv ON (((v.bhoomivillagecode = bhv.villagecode) AND (v.bhoomihobicode = bhv.hoblicode) AND (v.bhoomitalukcode = bhv.talukcode) AND (v.bhoomidistrictcode = bhv.districtcode))))
  WHERE (ps.landcode <> 0);


ALTER TABLE kaveri.vw_jslip_surveynumberdata OWNER TO postgres;

