ALTER TABLE kaveri.vw_jslip_surveynumberdetails OWNER TO postgres;

--
-- Name: vw_jslip_surveynumberdetails_for_old_method; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_jslip_surveynumberdetails_for_old_method AS
 SELECT dm.documentid,
    dm.applicationnumber,
    pm.propertyid,
    dm.finalregistrationnumber,
    rga.articlenamee,
        CASE
            WHEN (((btm.unit)::text = 'G'::text) AND (pm.unitid = 1)) THEN (pm.totalarea * (40)::numeric)
            WHEN (((btm.unit)::text = 'C'::text) AND (pm.unitid = 1)) THEN (pm.totalarea * (100)::numeric)
            WHEN (((btm.unit)::text = 'G'::text) AND (pm.unitid = 2)) THEN (pm.totalarea * (40)::numeric)
            WHEN (((btm.unit)::text = 'C'::text) AND (pm.unitid = 6)) THEN (pm.totalarea * (100)::numeric)
            ELSE pm.totalarea
        END AS totalarea,
    btm.unit,
    mm.measurementnamee,
    (dm.documentid || to_char(dm.registrationdatetime, 'ddMMYYYY'::text)) AS regid,
    v.kaverivillagecode,
    v.bhoomivillagecode AS villagecode,
    pnd.survey_no,
    pnd.hissa_no,
    pnd.currentnumber,
    bhv.villagenamee AS village,
    v.bhoomihobicode AS hoblicode,
    bhm.hoblinamee AS hobli,
    btm.talukcode,
    btm.taluknamee AS taluk,
    v.bhoomidistrictcode AS districtcode,
    bdm.districtnamee AS district,
    NULL::text AS govtrestrictioncleared,
    NULL::text AS govtrestrictionid,
    NULL::text AS govtrestrictionorder,
    sf.isownertobeclaimant
   FROM (((((((((((kaveri.documentmaster dm
     JOIN kaveri.propertymaster pm ON (((pm.propertytypeid = 17) AND (pm.documentid = dm.documentid) AND ((dm.applicationnumber)::text = (pm.applicationnumber)::text))))
     JOIN kaveri.propertynumberdetails pnd ON ((pm.propertyid = pnd.propertyid)))
     LEFT JOIN kaveri.stamprules stm ON ((pm.stampruleid = stm.stampruleid)))
     JOIN kaveri.stamprulesflag sf ON ((stm.stampruleid = sf.stampruleid)))
     JOIN kaveri.registrationarticles rga ON ((rga.regarticlecode = pm.regarticlecode)))
     JOIN kaveri.measurementmaster mm ON ((mm.measurementcode = pm.unitid)))
     JOIN kaveri.bhoomimappingdetails v ON ((v.kaverivillagecode = pm.villagecode)))
     JOIN kaveri.bhoomidistrictmaster bdm ON ((v.bhoomidistrictcode = bdm.districtcode)))
     JOIN kaveri.bhoomitalukmaster btm ON (((v.bhoomitalukcode = btm.talukcode) AND (v.bhoomidistrictcode = btm.districtcode))))
     JOIN kaveri.bhoomihoblimaster bhm ON (((v.bhoomihobicode = bhm.hoblicode) AND (v.bhoomitalukcode = bhm.talukcode) AND (v.bhoomidistrictcode = bhm.districtcode))))
     JOIN kaveri.bhoomivillagemaster bhv ON (((v.bhoomivillagecode = bhv.villagecode) AND (v.bhoomihobicode = bhv.hoblicode) AND (v.bhoomitalukcode = bhv.talukcode) AND (v.bhoomidistrictcode = bhv.districtcode))))
  WHERE ((dm.finalregistrationnumber IS NOT NULL) AND (dm.registrationdatetime IS NOT NULL));


ALTER TABLE kaveri.vw_jslip_surveynumberdetails_for_old_method OWNER TO postgres;

--
-- Name: vw_k1pendingdashboard; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_k1pendingdashboard AS
 SELECT k1pendingdashboard.applicationid,
    k1pendingdashboard.applicationnumber,
    k1pendingdashboard.pendingnumber,
    k1pendingdashboard.pendingsrocode,
    k1pendingdashboard.statuscode,
        CASE
            WHEN (k1pendingdashboard.statuscode = 1) THEN 'Application recieved from citizen'::text
            WHEN (k1pendingdashboard.statuscode = 2) THEN 'Application sent to DR'::text
            WHEN (k1pendingdashboard.statuscode = 3) THEN 'Application recieved from DR'::text
            WHEN (k1pendingdashboard.statuscode = 4) THEN 'Application finilized'::text
            WHEN (k1pendingdashboard.statuscode = 5) THEN 'Application rejected'::text
            ELSE 'Unknown Status'::text
        END AS statusdescription,
    k1pendingdashboard.citizenid,
    k1pendingdashboard.inserteddatetime,
    k1pendingdashboard.k1k2_flag,
    k1pendingdashboard.presentationdate,
    k1pendingdashboard.ordernumber,
