    k1pendingdashboard.sroid,
    k1pendingdashboard.droid,
    k1pendingdashboard.drremarks,
    k1pendingdashboard.documentdetails,
    k1pendingdashboard.previousstampdetails,
    k1pendingdashboard.previousreceiptdetailspaymentdetails,
    k1pendingdashboard.indexvillagedetails,
    k1pendingdashboard.boundarydetails,
    k1pendingdashboard.valuationdetails,
