--
-- Name: vw_kaveri_registration_document; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_kaveri_registration_document AS
 SELECT a.refid,
    a.documentid,
    (((('This Document has been '::text || (b.type)::text) || ' by documentno.'::text) || ' '::text) || substr((a.referencetext)::text, 37, 20)) AS documentreference,
    d.currentpropertytypeid,
    e.typenameenglish AS propertytype,
    d.currentnumber
   FROM ((((kaveri.referencemaster a
     JOIN kaveri.referencetransactionmaster b ON ((a.trid = b.trid)))
     JOIN kaveri.propertymaster c ON ((a.documentid = c.documentid)))
     JOIN kaveri.propertynumberdetails d ON ((c.propertyid = d.propertyid)))
     JOIN kaveri.propertynotypemaster e ON ((d.currentpropertytypeid = e.propertytypeid)));


ALTER TABLE kaveri.vw_kaveri_registration_document OWNER TO postgres;

