--
-- Name: vw_masval_pendingapproval; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_masval_pendingapproval AS
 SELECT mval.roadcode,
    rm.roadnamee AS roadname,
    rm.roadnamek,
    mval.srocode,
    vm.villagecode,
    vm.villagenamee AS villagename,
    vm.villagenamek,
    h.hoblicode,
    h.hoblinamee AS hobliname,
    mval.sfdaid,
    ( SELECT array_to_json(array_agg(row_to_json(val.*))) AS array_to_json
           FROM ( SELECT 'Agriculture'::text AS propertytype,
                    ra.rate,
                    ra.agrilandtypedesc AS typedesc,
                    ra.rate_val
                   FROM ( SELECT m.roadcode,
                            r.agrilandtypeid,
                            r.measurementcode,
                            r.rate,
                            r.effectivedate,
                            agri_ty.description AS agrilandtypedesc,
                            m.rate AS rate_val
                           FROM ((kaveri.mas_valuationrates m
                             JOIN kaveri.mas_val_agrilandtypes agri_ty ON ((m.agrilandtypeid = agri_ty.agrilandtypeid)))
                             LEFT JOIN ( SELECT ad.roadcode,
                                    ad.agrilandtypeid,
                                    ad.villagecode,
                                    ad.measurementcode,
                                    ad.rate,
                                    ad.effectivedate,
                                    COALESCE(lead(ad.effectivedate, 1) OVER (PARTITION BY ad.roadcode, ad.agrilandtypeid ORDER BY ad.effectivedate), (CURRENT_DATE)::timestamp without time zone) AS effectivetodate
                                   FROM kaveri.rateagriculturaldetail ad) r ON (((r.roadcode = m.roadcode) AND (m.agrilandtypeid = r.agrilandtypeid) AND (m.agrilandtypeid IS NOT NULL) AND (m.propertytypeid = 17) AND (CURRENT_DATE <= r.effectivetodate))))
                          WHERE ((mval.roadcode = m.roadcode) AND (mval.sfdaid = m.sfdaid) AND (m.agrilandtypeid IS NOT NULL) AND (m.propertytypeid = 17) AND (m.valrateheaderid IS NULL))) ra
                  WHERE (ra.roadcode = mval.roadcode)
                UNION ALL
                 SELECT 'Vacant Land/Building'::text AS propertytype,
                    ra.rate,
                    ra.propertytypename AS typedesc,
                    ra.rate_val
                   FROM ( SELECT m.roadcode,
                            r.propertytypeid,
                            r.measurementcode,
                            r.rate,
                            r.effectivedate,
                            ptm.propertytypename,
                            m.rate AS rate_val
                           FROM ((kaveri.mas_valuationrates m
                             JOIN kaveri.propertytypemaster ptm ON ((ptm.propertytypeid = m.propertytypeid)))
                             LEFT JOIN ( SELECT br.roadcode,
                                    br.propertytypeid,
                                    br.rate,
                                    br.measurementcode,
                                    br.effectivedate,
                                    COALESCE(lead(br.effectivedate, 1) OVER (PARTITION BY br.roadcode, br.propertytypeid ORDER BY br.effectivedate), (CURRENT_DATE)::timestamp without time zone) AS effectivetodate
                                   FROM kaveri.openbuiltratedetail br) r ON (((r.roadcode = m.roadcode) AND (m.propertytypeid <> 17) AND (m.agrilandtypeid IS NULL) AND (m.propertytypeid = r.propertytypeid) AND (CURRENT_DATE <= r.effectivetodate))))
                          WHERE ((mval.roadcode = m.roadcode) AND (mval.sfdaid = m.sfdaid) AND (m.agrilandtypeid IS NULL) AND (m.amenitiesid IS NULL) AND (m.valrateheaderid IS NULL))) ra
                  WHERE (ra.roadcode = mval.roadcode)
                UNION ALL
                 SELECT 'Apartment/Flat'::text AS propertytype,
                    ra.rate,
                    ra.propertytypename AS typedesc,
                    ra.rate_val
                   FROM ( SELECT m.roadcode,
                            r.propertytypeid,
                            r.measurementcode,
                            r.rate,
                            r.effectivedate,
                            ptm.propertytypename,
                            m.amenitiesid,
                            m.floorid,
                            m.rate AS rate_val
                           FROM ((kaveri.mas_valuationrates m
                             JOIN kaveri.propertytypemaster ptm ON ((ptm.propertytypeid = m.propertytypeid)))
                             JOIN ( SELECT op.roadid AS roadcode,
                                    op.propertytypeid,
                                    op.amenitiesid,
                                    op.floorid,
                                    op.unitid AS measurementcode,
                                    op.rate,
                                    op.effectivedate,
                                    COALESCE(lead(op.effectivedate, 1) OVER (PARTITION BY op.roadid, op.propertytypeid, op.amenitiesid, op.floorid ORDER BY op.effectivedate), (CURRENT_DATE)::timestamp without time zone) AS effectivetodate
                                   FROM kaveri.mas_val_flatrates op) r ON (((r.roadcode = m.roadcode) AND (m.propertytypeid <> 17) AND (m.agrilandtypeid IS NULL) AND (m.propertytypeid = r.propertytypeid) AND (m.floorid = r.floorid) AND (CURRENT_DATE >= r.effectivedate) AND (CURRENT_DATE <= r.effectivetodate))))
                          WHERE ((mval.roadcode = m.roadcode) AND (mval.sfdaid = m.sfdaid) AND (m.agrilandtypeid IS NULL) AND (m.valrateheaderid IS NULL))) ra
                  WHERE (ra.roadcode = mval.roadcode)) val) AS masval
   FROM (((( SELECT DISTINCT mas_valuationrates.sfdaid,
            mas_valuationrates.srocode,
            mas_valuationrates.roadcode
           FROM kaveri.mas_valuationrates
          WHERE (mas_valuationrates.valrateheaderid IS NULL)) mval
     JOIN kaveri.roadmaster rm ON ((rm.roadcode = mval.roadcode)))
     JOIN kaveri.villagemaster vm ON ((vm.villagecode = rm.villagecode)))
     JOIN kaveri.hoblimaster h ON ((vm.hoblicode = h.hoblicode)));


ALTER TABLE kaveri.vw_masval_pendingapproval OWNER TO postgres;

--
-- Name: vw_masval_pendingapproval_sro; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_masval_pendingapproval_sro AS
 SELECT mh.valrateheaderid,
    mh.circularinfo,
    mh.circularpath,
    mh.effectivedate,
    mval.roadcode,
    rm.roadnamee AS roadname,
    rm.roadnamek,
    mval.srocode,
    vm.villagecode,
    vm.villagenamee AS villagename,
    vm.villagenamek,
    h.hoblicode,
    h.hoblinamee AS hobliname,
    mh.sfdaid,
    ( SELECT array_to_json(array_agg(row_to_json(val.*))) AS array_to_json
           FROM ( SELECT 'Agriculture'::text AS propertytype,
                    ra.rate,
                    ra.agrilandtypedesc AS typedesc,
                    ra.rate_val
                   FROM ( SELECT m.roadcode,
                            r.agrilandtypeid,
                            r.measurementcode,
                            r.rate,
                            r.effectivedate,
                            agri_ty.description AS agrilandtypedesc,
                            m.rate AS rate_val
                           FROM ((kaveri.mas_valratedetail m
                             JOIN kaveri.mas_val_agrilandtypes agri_ty ON ((m.agrilandtypeid = agri_ty.agrilandtypeid)))
                             LEFT JOIN ( SELECT ad.roadcode,
                                    ad.agrilandtypeid,
                                    ad.villagecode,
                                    ad.measurementcode,
                                    ad.rate,
                                    ad.effectivedate,
                                    COALESCE(lead(ad.effectivedate, 1) OVER (PARTITION BY ad.roadcode, ad.agrilandtypeid ORDER BY ad.effectivedate), (CURRENT_DATE)::timestamp without time zone) AS effectivetodate
                                   FROM kaveri.rateagriculturaldetail ad) r ON (((r.roadcode = m.roadcode) AND (m.agrilandtypeid = r.agrilandtypeid) AND (m.propertytypeid = 17) AND (CURRENT_DATE >= r.effectivedate) AND (CURRENT_DATE <= r.effectivetodate))))
                          WHERE ((mh.valrateheaderid = m.valrateheaderid) AND (mval.roadcode = m.roadcode) AND (mval.sfdaid = m.sfdaid) AND (m.propertytypeid = 17))) ra
                  WHERE (mval.roadcode = ra.roadcode)
                UNION ALL
                 SELECT 'Vacant Land/Building'::text AS propertytype,
                    ra.rate,
                    ra.propertytypename AS typedesc,
                    ra.rate_val
                   FROM ( SELECT m.roadcode,
                            r.propertytypeid,
                            r.measurementcode,
                            r.rate,
                            r.effectivedate,
                            ptm.propertytypename,
                            m.rate AS rate_val
                           FROM ((kaveri.mas_valratedetail m
                             JOIN kaveri.propertytypemaster ptm ON ((ptm.propertytypeid = m.propertytypeid)))
                             LEFT JOIN ( SELECT br.roadcode,
                                    br.propertytypeid,
                                    br.rate,
                                    br.measurementcode,
                                    br.effectivedate,
                                    COALESCE(lead(br.effectivedate, 1) OVER (PARTITION BY br.roadcode, br.propertytypeid ORDER BY br.effectivedate), (CURRENT_DATE)::timestamp without time zone) AS effectivetodate
                                   FROM kaveri.openbuiltratedetail br) r ON (((r.roadcode = m.roadcode) AND (m.propertytypeid <> 17) AND (m.agrilandtypeid IS NULL) AND (m.propertytypeid = r.propertytypeid) AND (CURRENT_DATE >= r.effectivedate) AND (CURRENT_DATE <= r.effectivetodate))))
                          WHERE ((mh.valrateheaderid = m.valrateheaderid) AND (mval.roadcode = m.roadcode) AND (mval.sfdaid = m.sfdaid) AND (m.agrilandtypeid IS NULL) AND (m.amenitiesid IS NULL))) ra
                  WHERE (mval.roadcode = ra.roadcode)
                UNION ALL
                 SELECT 'Apartment/Flat'::text AS propertytype,
                    ra.rate,
                    ra.namewithamenities AS typedesc,
                    ra.rate_val
                   FROM ( SELECT m.roadcode,
                            r.propertytypeid,
                            r.measurementcode,
                            r.rate,
                            r.effectivedate,
                            ptm.propertytypename,
                            m.amenitiesid,
                            m.floorid,
                            amn.namewithamenities,
                            m.rate AS rate_val
                           FROM (((kaveri.mas_valratedetail m
                             JOIN kaveri.mas_val_apartmentsamenities amn ON ((amn.amenitiesid = m.amenitiesid)))
                             JOIN kaveri.propertytypemaster ptm ON ((ptm.propertytypeid = m.propertytypeid)))
                             LEFT JOIN ( SELECT op.roadid AS roadcode,
                                    op.propertytypeid,
                                    op.amenitiesid,
                                    op.floorid,
                                    op.unitid AS measurementcode,
                                    op.rate,
                                    op.effectivedate,
                                    COALESCE(lead(op.effectivedate, 1) OVER (PARTITION BY op.roadid, op.propertytypeid, op.amenitiesid, op.floorid ORDER BY op.effectivedate), (CURRENT_DATE)::timestamp without time zone) AS effectivetodate
                                   FROM kaveri.mas_val_flatrates op
                                  WHERE (op.amenitiesid IS NOT NULL)) r ON (((r.roadcode = m.roadcode) AND (m.propertytypeid <> 17) AND (m.agrilandtypeid IS NULL) AND (m.propertytypeid = r.propertytypeid) AND (m.amenitiesid = r.amenitiesid) AND (m.floorid = r.floorid) AND (CURRENT_DATE >= r.effectivedate) AND (CURRENT_DATE <= r.effectivetodate))))
                          WHERE ((mh.valrateheaderid = m.valrateheaderid) AND (mval.roadcode = m.roadcode) AND (mval.sfdaid = m.sfdaid) AND (m.amenitiesid IS NOT NULL) AND (m.agrilandtypeid IS NULL))) ra
                  WHERE (ra.roadcode = mval.roadcode)) val) AS masval
   FROM ((((kaveri.mas_valrateheader mh
     JOIN ( SELECT DISTINCT mas_valratedetail.sfdaid,
            mas_valratedetail.srocode,
            mas_valratedetail.roadcode,
            mas_valratedetail.valrateheaderid
           FROM kaveri.mas_valratedetail
          WHERE (mas_valratedetail.valrateheaderid IS NOT NULL)) mval ON ((mh.valrateheaderid = mval.valrateheaderid)))
     JOIN kaveri.roadmaster rm ON ((rm.roadcode = mval.roadcode)))
     JOIN kaveri.villagemaster vm ON ((vm.villagecode = rm.villagecode)))
     JOIN kaveri.hoblimaster h ON ((vm.hoblicode = h.hoblicode)));


ALTER TABLE kaveri.vw_masval_pendingapproval_sro OWNER TO postgres;

