ALTER TABLE kaveri.vw_measunitmaster OWNER TO csgadmin;

--
-- Name: vw_party_esigned_details; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_party_esigned_details AS
 SELECT per.linkid,
    per.applicationnumber,
    per.partyid,
    per.docpath,
    per.iswitness,
        CASE
            WHEN (per.iswitness = false) THEN ( SELECT partyinfo.iscitizenaadharverified
               FROM kaveri.partyinfo
              WHERE (partyinfo.partyid = per.partyid))
            ELSE false
        END AS iscitizenaadharverified,
        CASE
            WHEN (per.iswitness = false) THEN ( SELECT partyinfo.phonenumber
               FROM kaveri.partyinfo
              WHERE (partyinfo.partyid = per.partyid))
            ELSE ( SELECT witnessinfo.phoneno
               FROM kaveri.witnessinfo
              WHERE (witnessinfo.witnessid = per.partyid))
        END AS phonenumber,
        CASE
            WHEN (per.iswitness = false) THEN ( SELECT
                    CASE
                        WHEN (partyinfo.iscitizenaadharverified = true) THEN partyinfo.nameasperaadhar
                        ELSE partyinfo.firstname
                    END AS nameasperaadhara
               FROM kaveri.partyinfo
              WHERE (partyinfo.partyid = per.partyid))
            ELSE ''::character varying
        END AS nameasperaadhar,
        CASE
            WHEN (per.iswitness = false) THEN ( SELECT partyinfo.isdocumentexecuted
               FROM kaveri.partyinfo
              WHERE (partyinfo.partyid = per.partyid))
            ELSE ( SELECT witnessinfo.isdocumentexecuted
               FROM kaveri.witnessinfo
              WHERE (witnessinfo.witnessid = per.partyid))
        END AS isdocumentexecuted,
    per.documentid
   FROM kaveri.partyesignregister per;


ALTER TABLE kaveri.vw_party_esigned_details OWNER TO postgres;

