ALTER TABLE kaveri.vw_partytypemaster OWNER TO csgadmin;

--
-- Name: vw_payment_scheduler; Type: MATERIALIZED VIEW; Schema: kaveri; Owner: postgres
--

CREATE MATERIALIZED VIEW kaveri.vw_payment_scheduler AS
 SELECT DISTINCT are3.deptreferencecode,
    NULL::text AS paymentstatuscode
   FROM ((kaveri.applicantapplicationdetails a
     JOIN kaveri.ams_reg_epaymenttransdetails are3 ON ((((a.applicationnumber)::text = (are3.applicationnumber)::text) AND (a.applicationtypeid = 1))))
     LEFT JOIN kaveri.ams_reg_epaymentbankackdetails are2 ON (((are2.deptreferencecode)::text = (are3.deptreferencecode)::text)))
  WHERE (((a.currentstatus)::text = 'CD106'::text) AND (are3.inserteddatetime >= (now() - '24:00:00'::interval)) AND (are3.inserteddatetime <= (now() - '01:00:00'::interval)) AND (are2.deptreferencecode IS NULL))
UNION ALL
 SELECT are.deptreferencecode,
    are.paymentstatuscode
   FROM (kaveri.ams_reg_epaymentbankackdetails are
     JOIN ( SELECT arep.deptreferencecode,
            max(arep.inserteddatetime) AS latest_time
           FROM ((kaveri.ams_reg_epaymentbankackdetails arep
             JOIN kaveri.ams_reg_epaymenttransdetails are2 USING (deptreferencecode))
             JOIN kaveri.applicantapplicationdetails a USING (applicationnumber))
          WHERE (((a.currentstatus)::text = 'CD106'::text) AND (arep.transactiontimestamp >= (now() - '24:00:00'::interval)) AND (arep.transactiontimestamp <= (now() - '01:00:00'::interval)) AND (a.applicationtypeid = 1))
          GROUP BY arep.deptreferencecode) latest ON ((((are.deptreferencecode)::text = (latest.deptreferencecode)::text) AND (are.inserteddatetime = latest.latest_time))))
  WHERE ((are.paymentstatuscode)::text <> ALL (ARRAY[('10700066'::character varying)::text, ('10700068'::character varying)::text, ('10700072'::character varying)::text, ('10700103'::character varying)::text, ('10700098'::character varying)::text]))
  WITH NO DATA;


ALTER TABLE kaveri.vw_payment_scheduler OWNER TO postgres;

