--
-- Name: vw_scrutinyfeechange_applicationforscruity_revenue; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_scrutinyfeechange_applicationforscruity_revenue AS
 SELECT DISTINCT a.applicationnumber,
    a.auditcompleteddatetime,
    a.audtr_rmrksfilepath,
    ( SELECT concat_ws(' '::text, du.firstname, du.middlename, du.lastname, '-', dm.designame) AS auditorname
           FROM (kaveri.departmentusers du
             JOIN kaveri.desigmaster dm ON ((du.designationid = dm.designationid)))
          WHERE ((du.serviceflag = true) AND (du.userid = a.auditor))) AS auditorname_designation,
    a.auditor,
    sum(s.auditoramountrequired) AS totalauditorcalculation,
    sum(s.sroamountrequired) AS totalsrocalculation,
    sum(DISTINCT
        CASE
            WHEN (s.feerulecode = ANY (ARRAY[36, 58, 59])) THEN s.auditoramountrequired
            ELSE (0)::numeric
        END) AS auditoramountrequiredstampduty,
    sum(DISTINCT
        CASE
            WHEN (s.feerulecode = ANY (ARRAY[36, 58, 59])) THEN s.sroamountrequired
            ELSE (0)::numeric
        END) AS sroamountrequiredstampduty,
    sum(DISTINCT
        CASE
            WHEN (s.feerulecode = 1) THEN s.auditoramountrequired
            ELSE (0)::numeric
        END) AS auditoramountrequiredregistrationfees,
    sum(DISTINCT
        CASE
            WHEN (s.feerulecode = 1) THEN s.sroamountrequired
            ELSE (0)::numeric
        END) AS sroamountrequiredregistrationfees,
    a.regarticlecode,
    a.isaccepted,
    a.isauditcompleted,
    a.sr_remarks,
    usr.username,
        CASE
            WHEN (vd.uploaddocdeedpath IS NULL) THEN 'Not Registered'::text
            WHEN (vd.uploaddocdeedpath IS NOT NULL) THEN vd.uploaddocdeedpath
            ELSE NULL::text
        END AS uploaddocdeedpath
   FROM ((((kaveri.applicantapplicationdetails ad
     JOIN kaveri.scrutinyfeechange s ON (((s.applicationnumber)::text = (ad.applicationnumber)::text)))
     JOIN kaveri.applicationforscrutiny a ON (((a.applicationnumber)::text = (s.applicationnumber)::text)))
     LEFT JOIN kaveri.vw_department_users usr ON ((usr.userid = ad.sfdaid)))
     LEFT JOIN kaveri.vw_documentmaster vd ON (((vd.applicationnumber)::text = (a.applicationnumber)::text)))
  GROUP BY a.applicationnumber, a.auditcompleteddatetime, a.audtr_rmrksfilepath, a.auditor, a.regarticlecode, a.isaccepted, a.isauditcompleted, a.sr_remarks, usr.username, vd.uploaddocdeedpath;


ALTER TABLE kaveri.vw_scrutinyfeechange_applicationforscruity_revenue OWNER TO postgres;

