--
-- Name: vw_srch_courtorders; Type: VIEW; Schema: kaveri; Owner: csgadmin
--

CREATE VIEW kaveri.vw_srch_courtorders AS
 SELECT app_json.orderid,
    app_json.srocode,
    app_json.ordernumber,
    app_json.issuingauthority,
    app_json.issuedate,
    app_json.description AS courtdescription,
    app_json.casetype,
    app_json.iscancelled,
    app_json.isinforce,
    row_to_json(app_json.*) AS court_json
   FROM ( SELECT co.courtorderid AS orderid,
            co.ordernumber,
            co.srocode,
            co.issuingauthority,
            (co.issueddate)::date AS issuedate,
            co.description,
            co.isinforce,
            co.iscancelled,
            co.casetype,
            co.cancellationdate,
            co.cancellationremarks,
            co.username,
            co.dateofcancellation,
            ( SELECT array_to_json(array_agg(row_to_json(prpty.*))) AS array_to_json
                   FROM ( SELECT bp.courtpropertyid AS propertyid,
                            bp.isagriculturalproperty,
                            tm.districtcode,
                            bp.srocode,
                            bp.villagecode,
                            bp.jurisdictionsrcode,
                            vm.hoblicode,
                            bp.northboundary,
                            bp.southboundary,
                            bp.eastboundary,
                            bp.westboundary,
                            vm.talukcode AS talukacode,
                            bp.propertydescription,
                            bp.area,
                            bp.measurementunit,
                            bp.extentinformation AS extentdescription,
                            bp.isdelete,
                            ( SELECT array_to_json(array_agg(row_to_json(prptyno.*))) AS array_to_json
                                   FROM ( SELECT bpn.propertyid,
    bpn.srocode,
    bpn.currentpropertytypeid,
    bpn.currentnumber,
    bpn.oldnumber,
    bpn.hissa_no AS hissanumber,
    bpn.survey_no AS surveynumber,
    bpn.isdelete,
    bpn.courtpropertynumberid AS propertynumberid
   FROM (kaveri.bannedpropertynumbers bpn
     LEFT JOIN kaveri.propertynotypemaster pntm ON ((pntm.propertytypeid = bpn.currentpropertytypeid)))
  WHERE ((bpn.propertyid = bp.courtpropertyid) AND (bpn.srocode = bp.srocode) AND (COALESCE(bpn.isdelete, false) = false) AND (co.courtorderid = bpn.orderid) AND (co.srocode = bpn.srocode))) prptyno) AS propertynumbers
                           FROM ((kaveri.bannedproperties bp
                             LEFT JOIN kaveri.villagemaster vm ON ((bp.villagecode = vm.villagecode)))
                             LEFT JOIN kaveri.talukmaster tm ON ((vm.talukcode = tm.talukcode)))
                          WHERE ((COALESCE(bp.isdelete, false) = false) AND (co.courtorderid = bp.orderid) AND (co.srocode = bp.srocode))) prpty) AS orderproperties,
            ( SELECT array_to_json(array_agg(row_to_json(prty.*))) AS array_to_json
                   FROM ( SELECT party.courtpartyid AS partyid,
                            party.srocode,
                            party.salutation,
                            party.firstname,
                            party.middlename,
                            party.lastname,
                            party.age,
                            party.house_building_name AS housebuildingname,
                            vm.talukcode AS talukacode,
                            vm.hoblicode,
                            party.villagecode,
                            party.districtcode,
                            party.statecode,
                            party.address,
                            party.pincode,
                            party.isdelete
                           FROM ((kaveri.bannedparties party
                             LEFT JOIN kaveri.villagemaster vm ON ((party.villagecode = vm.villagecode)))
                             LEFT JOIN kaveri.talukmaster tm ON ((vm.talukcode = tm.talukcode)))
                          WHERE ((COALESCE(party.isdelete, false) = false) AND (co.courtorderid = party.orderid) AND (co.srocode = party.srocode))) prty) AS parties
           FROM kaveri.courtorders co
          WHERE (COALESCE(co.iscancelled, false) = false)) app_json;


ALTER TABLE kaveri.vw_srch_courtorders OWNER TO csgadmin;

--
-- Name: vw_sro_graphcnt; Type: VIEW; Schema: kaveri; Owner: postgres
