--
-- Name: vw_sro_graphcnt_opt; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_sro_graphcnt_opt AS
 WITH cte AS (
         SELECT ad.applicationtypeid,
            sm.servicename AS applicationtypename,
            ad.applicationnumber,
                CASE
                    WHEN (ad.applicationtypeid = 13) THEN (ea.kaverisrocode)::integer
                    WHEN (ad.applicationtypeid = 12) THEN ca.kaverisrocode
                    ELSE ad.srocode
                END AS srocode,
                CASE
                    WHEN ((ad.applicationtypeid = 1) AND (ad.bookid IS NOT NULL)) THEN ad.bookid
                    WHEN (ad.applicationtypeid = 12) THEN (ca.booktype)::integer
                    WHEN (ad.applicationtypeid = 13) THEN NULL::integer
                    ELSE NULL::integer
                END AS bookid,
            bm.booknameenglish AS bookname,
            ad.applicationenddate
           FROM ((((kaveri.applicantapplicationdetails ad
             LEFT JOIN kaveri.cc_applicationdetails ca ON (((ad.applicationnumber)::text = (ca.applicationnumber)::text)))
             LEFT JOIN kaveri.ec_applicationdetails ea ON (((ad.applicationnumber)::text = (ea.applicationnumber)::text)))
             JOIN kaveri.servicesmaster sm ON ((sm.serviceid = ad.applicationtypeid)))
             LEFT JOIN kaveri.booktypemaster bm ON ((ad.bookid = bm.bookid)))
          WHERE (((ad.srocode = 173) OR (ca.kaverisrocode = 173) OR (ea.kaverisrocode = 173)) AND ((ad.currentstatus)::text = ANY (ARRAY['CD120'::text, 'CC109'::text, 'CE110'::text])))
        )
 SELECT ss.applicationtypeid,
    ss.applicationtypename,
    ss.applicationnumber,
    ss.srocode,
    ss.bookid,
    ss.bookname,
    ss.applicationenddate
   FROM cte ss
  WHERE (ss.bookid =
        CASE
            WHEN ((ss.applicationtypeid = 1) OR (ss.bookid IS NOT NULL) OR ((ss.applicationtypeid = 12) AND (ss.bookname IS NULL))) THEN ss.bookid
            ELSE NULL::integer
        END)
UNION
 SELECT ss.applicationtypeid,
    ss.applicationtypename,
    ss.applicationnumber,
    ss.srocode,
    ss.bookid,
    ss.bookname,
    ss.applicationenddate
   FROM cte ss
  WHERE (ss.applicationtypeid = 13);


ALTER TABLE kaveri.vw_sro_graphcnt_opt OWNER TO postgres;

--
-- Name: vw_sro_landingboard; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_sro_landingboard AS
 SELECT DISTINCT ad.srocode,
    ad.applicationtypeid,
    sm.servicename AS applicationtypename,
    usr.userid,
    usr.username,
    usr.designame,
    sum(
        CASE
            WHEN ((ad.currentstatus)::text = ANY (ARRAY['CD103'::text, 'CE105'::text, 'CE138'::text, 'CC105'::text, 'CC106'::text, 'CD117'::text])) THEN 1
            ELSE 0
        END) OVER (PARTITION BY ad.srocode, usr.userid, ad.applicationtypeid) AS cnt_sfda,
    sum(
        CASE
            WHEN ((ad.currentstatus)::text = ANY (ARRAY['CD110'::text, 'CD112'::text, 'CD113'::text, 'CD114'::text, 'CD136'::text])) THEN 1
            ELSE 0
        END) OVER (PARTITION BY ad.srocode, usr.userid, ad.applicationtypeid) AS cnt_deo
   FROM ((kaveri.applicantapplicationdetails ad
     JOIN kaveri.servicesmaster sm ON ((sm.serviceid = ad.applicationtypeid)))
     JOIN kaveri.vw_department_users usr ON ((((usr.userid = ad.sfdaid) AND ((ad.currentstatus)::text = ANY (ARRAY['CD103'::text, 'CE105'::text, 'CE138'::text, 'CE139'::text, 'CC105'::text, 'CC106'::text, 'CD117'::text]))) OR ((usr.userid = ad.deoid) AND ((ad.currentstatus)::text = ANY (ARRAY['CD110'::text, 'CD112'::text, 'CD113'::text, 'CD114'::text, 'CD136'::text]))))));


ALTER TABLE kaveri.vw_sro_landingboard OWNER TO postgres;

--
-- Name: vw_sro_landingboard_prev; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_sro_landingboard_prev AS
 SELECT DISTINCT ad.srocode,
    ad.applicationtypeid,
    sm.servicename AS applicationtypename,
    usr.userid,
    usr.username,
    usr.designame,
    sum(
        CASE
            WHEN ((ad.sfdaid IS NOT NULL) AND ((ad.currentstatus)::text = ANY (ARRAY[('CD103'::character varying)::text, ('CE105'::character varying)::text, ('CE138'::character varying)::text, (','::character varying)::text, ('CC105'::character varying)::text, ('CC106'::character varying)::text, ('CD117'::character varying)::text]))) THEN 1
            ELSE 0
        END) OVER (PARTITION BY ad.srocode, usr.userid, ad.applicationtypeid) AS cnt_sfda,
    sum(
        CASE
            WHEN ((ad.deoid IS NOT NULL) AND ((ad.currentstatus)::text = ANY (ARRAY[('CD110'::character varying)::text, ('CD112'::character varying)::text, ('CD114'::character varying)::text]))) THEN 1
            ELSE 0
        END) OVER (PARTITION BY ad.srocode, usr.userid, ad.applicationtypeid) AS cnt_deo
   FROM ((kaveri.applicantapplicationdetails ad
     JOIN kaveri.servicesmaster sm ON ((sm.serviceid = ad.applicationtypeid)))
     LEFT JOIN kaveri.vw_department_users usr ON ((((usr.userid = ad.sfdaid) AND (usr.designationid = ANY (ARRAY[2, 3])) AND ((ad.currentstatus)::text = ANY (ARRAY[('CD103'::character varying)::text, ('CE105'::character varying)::text, ('CE138'::character varying)::text, ('CE139'::character varying)::text, ('CC105'::character varying)::text, ('CC106'::character varying)::text, ('CD117'::character varying)::text]))) OR ((usr.userid = ad.deoid) AND ((ad.currentstatus)::text = ANY (ARRAY[('CD110'::character varying)::text, ('CD112'::character varying)::text, ('CD114'::character varying)::text]))))))
  WHERE ((ad.sfdaid IS NOT NULL) AND (ad.srocode IS NOT NULL) AND (ad.srocode = 147));


ALTER TABLE kaveri.vw_sro_landingboard_prev OWNER TO postgres;

