--
-- Name: vw_total_revenue_collection; Type: VIEW; Schema: kaveri; Owner: csgadmin
--

CREATE VIEW kaveri.vw_total_revenue_collection AS
 SELECT a.userid,
    b.sronamee AS srooffice,
    c.districtnamee AS droffice,
    a.firstname,
    a.middlename,
    a.lastname,
    e.registrationdatetime,
    sum(feecalculation.stampduty) AS stampduty,
    sum(feecalculation.registrationfee) AS registrationfee,
    sum(feecalculation.otherfee) AS otherfee,
    ((sum(feecalculation.stampduty) + sum(feecalculation.registrationfee)) + sum(feecalculation.otherfee)) AS totalfee
   FROM ((((kaveri.departmentusers a
     JOIN kaveri.sromaster b ON ((a.srocode = b.srocode)))
     JOIN kaveri.districtmaster c ON ((b.districtcode = c.districtcode)))
     JOIN ( SELECT feesrequired.srocode,
            feesrequired.documentid,
            sum(
                CASE
                    WHEN (feesrequired.feerulecode = 36) THEN feesrequired.amountpaid
                    ELSE (0)::numeric
                END) AS stampduty,
            sum(
                CASE
                    WHEN (feesrequired.feerulecode = 1) THEN feesrequired.amountpaid
                    ELSE (0)::numeric
                END) AS registrationfee,
            sum(
                CASE
                    WHEN (feesrequired.feerulecode = 2) THEN feesrequired.amountpaid
                    ELSE (0)::numeric
                END) AS scanningfee,
            sum(
                CASE
                    WHEN (feesrequired.feerulecode <> ALL (ARRAY[36, 1, 2])) THEN feesrequired.amountpaid
                    ELSE (0)::numeric
                END) AS otherfee
           FROM kaveri.feesrequired
          GROUP BY feesrequired.srocode, feesrequired.documentid) feecalculation ON ((feecalculation.srocode = b.srocode)))
     JOIN kaveri.documentmaster e ON ((feecalculation.documentid = e.documentid)))
  GROUP BY b.sronamee, c.districtnamee, a.firstname, a.middlename, a.lastname, a.userid, e.registrationdatetime;


ALTER TABLE kaveri.vw_total_revenue_collection OWNER TO csgadmin;

--
-- Name: vw_verify_correction_note_propety_description; Type: VIEW; Schema: kaveri; Owner: postgres
--

CREATE VIEW kaveri.vw_verify_correction_note_propety_description AS
 SELECT DISTINCT b.orderid,
    a.srocode,
    a.documentnumber,
    a.financialyear,
    a.bookid,
    a.propertyid,
    (a.propertydescription || (b.note_enteredpart)::text) AS propertydescription,
    a.executiondate,
    a.natureofdocument,
    a.claimant,
    a.executant,
    a.pagecount,
    a.finalregistrationnumber
   FROM (kaveri.vw_fetch_section68_property_details a
     JOIN kaveri.dec_drpndnote b ON ((a.propertyid = b.propertyid)));


ALTER TABLE kaveri.vw_verify_correction_note_propety_description OWNER TO postgres;

--
-- Name: vw_verifychallan; Type: VIEW; Schema: kaveri; Owner: csgadmin
--

CREATE VIEW kaveri.vw_verifychallan AS
 SELECT epay.officeid,
    epay.remittername AS nameoftheperson,
    ddo.ddocode,
    epay.deptreferencecode AS challannumber,
    mo.officename AS ddoofficename,
    epay.totalamount,
    epay.transactionid,
    CURRENT_TIMESTAMP AS transactiondate,
    '33029493274'::bigint AS ktc25reconcilationno
   FROM (((kaveri.ams_reg_khajaneresponselog khj
     JOIN ( SELECT ams_reg_epaymenttransdetails.transactionid,
            ams_reg_epaymenttransdetails.transactiondatetime,
            ams_reg_epaymenttransdetails.officeid,
            ams_reg_epaymenttransdetails.deptreferencecode,
            ams_reg_epaymenttransdetails.remittername,
            ams_reg_epaymenttransdetails.treasurycode,
            sum(ams_reg_epaymenttransdetails.totalamount) AS totalamount
           FROM kaveri.ams_reg_epaymenttransdetails
          GROUP BY ams_reg_epaymenttransdetails.transactionid, ams_reg_epaymenttransdetails.transactiondatetime, ams_reg_epaymenttransdetails.officeid, ams_reg_epaymenttransdetails.deptreferencecode, ams_reg_epaymenttransdetails.remittername, ams_reg_epaymenttransdetails.treasurycode) epay ON (((epay.deptreferencecode)::text = (khj.deptreferencecode)::text)))
     LEFT JOIN kaveri.mas_officemaster mo ON ((mo.officeid = epay.officeid)))
     LEFT JOIN kaveri.mas_ams_khajaneddocodemapping ddo ON ((ddo.srocode = epay.officeid)));


ALTER TABLE kaveri.vw_verifychallan OWNER TO csgadmin;

